import java.io.Serializable;
import java.util.Iterator;
import org.jeeventstore.ChangeSet;

/**
 * An iterator that iterates over all events for multiple {@link ChangeSet}s
 * in a proper sequence.
 */
public class EventsIterator<T extends ChangeSet> implements Iterator<Serializable> {

    private Iterator<T> cit;
    private Iterator<Serializable> it = null;

    public EventsIterator(Iterator<T> cit) {
        this.cit = cit;
        advance();
    }

    private void advance() {
        if (it != null && it.hasNext())
            return;
        // now either it == null or it has no next
        do {
            // already reached the last change set?
            if (!cit.hasNext()) {
                it = null;
                return;
            }
            // no, another changeset is available.  Grab it.
            ChangeSet nextcs = cit.next();
            it = nextcs.events();
        } while (!it.hasNext()); // protect against ChangeSets w/o events
    }

    @Override
    public boolean hasNext() {
        return it != null;
    }

    @Override
    public Serializable next() {
        Serializable n = it.next();
        advance();
        return n;
    }

    /**
     * {@link #remove()} is not supported.
     */
    @Override
    public void remove() {
        throw new UnsupportedOperationException("Not supported.");
    }

}

import java.io.*;
import java.net.*;

public class SocketServer {
    private ServerSocket serverSocket;
    private Socket clientSocket;
    private PrintWriter out;
    private BufferedReader in;

    public void start(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        clientSocket = serverSocket.accept();
        out = new PrintWriter(clientSocket.getOutputStream(), true);
        in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
        String inputLine;
        while ((inputLine = in.readLine()) != null) {
            if (".".equals(inputLine)) {
                out.println("bye");
                break;
            }
            out.println(inputLine);
        }
    }

    public void stop() throws IOException {
        in.close();
        out.close();
        clientSocket.close();
        serverSocket.close();
    }

    public static void main(String[] args) throws IOException {
        SocketServer server = new SocketServer();
        server.start(6666);
        server.stop();
    }
}

public class RTBench {

    private static Benchmark[] benchmarks = {
        new TaskCreationBenchmark(),
        new IndependentTaskGraph(),
        new LinearTaskGraph(),
        new FixedParallelMaxDependencies(),
        new ChildTaskBenchmark(),
        new FibonacciBenchmark()
    };

    public static void usage() {
        System.out.println();
        System.out.println("java aeminium.runtime.tools.benchmark.RTBench COMMAND");
        System.out.println("");
        System.out.println("COMMANDS:");
        System.out.println(" list             - List available benchmarks.");
        System.out.println(" run BENCHMARK    - Run specified benchmark.");
        System.out.println();
    }

    public static void main(String[] args) {

        if ( args.length == 0 ) {
            usage();
            return;
        }

        if ( args[0].equals("list") ) {
            for( Benchmark benchmark : benchmarks ) {
                System.out.println(benchmark.getName());
            }
        } else if ( args[0].equals("run") && args.length == 2 ) {
            Benchmark benchmark = null;
            for ( Benchmark b : benchmarks ) {
                if ( b.getName().equals(args[1])) {
                    benchmark = b;
                }
            }

            if ( benchmark != null ) {
                Reporter reporter = new StringBuilderReporter();
                reporter.startBenchmark(benchmark.getName());
                benchmark.run(reporter);
                reporter.stopBenchmark(benchmark.getName());
                reporter.flush();
            } else {
                usage();
            }

        } else {
            usage();
        }
    }

    protected static void reportVMStats(Reporter reporter) {
        reporter.reportLn(String.format("Memory (TOTAL/MAX/FREE) (%d,%d,%d)", Runtime.getRuntime().totalMemory(),
                                                                              Runtime.getRuntime().maxMemory(),
                                                                              Runtime.getRuntime().freeMemory()));
    }
}

public class MyArrayList<E> extends MyAbstractList<E> {

  public static final int INITIAL_CAPACITY = 16;

  private E[] data = (E[]) new Object[INITIAL_CAPACITY];

  /** Create a default list */
  public MyArrayList() {
  }

  /** Create a list from an array of objects */
  public MyArrayList(E[] objects) {
    for (int i = 0; i < objects.length; i++)
      add(objects[i]);
  }

  /** Create a new larger array, double the current size + 1 */
  private void ensureCapacity() {
    if (size >= data.length) {
      E[] newData = (E[]) (new Object[size * 2 + 1]);
      System.arraycopy(data, 0, newData, 0, size);
      data = newData;
    }
  }

  /** Trims the capacity to current size */
  public void trimToSize() {
    if (size != data.length) {
      E[] newData = (E[]) (new Object[size]);
      System.arraycopy(data, 0, newData, 0, size);
      data = newData;
    }
  }

  @Override
  public void clear() {
    data = (E[]) new Object[INITIAL_CAPACITY];
    size = 0;
  }

  @Override
  public boolean contains(E e) {
    for (int i = 0; i < size; i++)
      if (e.equals(data[i]))
        return true;

    return false;
  }

  @Override
  public E get(int index) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    return data[index];
  }

  @Override
  public int indexOf(E e) {
    for (int i = 0; i < size; i++)
      if (e.equals(data[i]))
        return i;

    return -1;
  }

  @Override
  public int lastIndexOf(E e) {
    for (int i = size - 1; i >= 0; i--)
      if (e.equals(data[i]))
        return i;

    return -1;
  }

  @Override
  public E set(int index, E e) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E old = data[index];
    data[index] = e;
    return old;
  }

  @Override
  public void add(int index, E e) {
    ensureCapacity();

    for (int i = size - 1; i >= index; i--)
      data[i + 1] = data[i];

    data[index] = e;

    size++;
  }

  @Override
  public E remove(int index) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E e = data[index];

    for (int j = index; j < size - 1; j++)
      data[j] = data[j + 1];

    data[size - 1] = null;

    size--;

    return e;
  }
}

public static void sort(int[] nums){
    for(int currentPlace = 0;currentPlace<nums.length-1;currentPlace++){
        int smallest = Integer.MAX_VALUE;
        int smallestAt = currentPlace+1;
        for(int check = currentPlace; check<nums.length;check++){
            if(nums[check]<smallest){
                smallestAt = check;
                smallest = nums[check];
            }
        }
        int temp = nums[currentPlace];
        nums[currentPlace] = nums[smallestAt];
        nums[smallestAt] = temp;
    }
}

