import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;

import org.eclipse.smarthome.core.types.Command;
import org.eclipse.smarthome.core.types.PrimitiveType;
import org.eclipse.smarthome.core.types.State;

public class DateTimeType implements PrimitiveType, State, Command {

    public final static SimpleDateFormat DATE_FORMATTER = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss");

    protected Calendar calendar;

    public DateTimeType() {
        this(Calendar.getInstance());
    }

    public DateTimeType(Calendar calendar) {
        this.calendar = calendar;
    }

    public DateTimeType(String calendarValue) {
        Date date = null;

        try {
            date = DATE_FORMATTER.parse(calendarValue);
        }
        catch (ParseException fpe) {
            throw new IllegalArgumentException(calendarValue + " is not in a valid format.", fpe);
        }

        if (date != null) {
            calendar = Calendar.getInstance();
            calendar.setTime(date);
        }
    }

    public Calendar getCalendar() {
        return calendar;
    }

    public static DateTimeType valueOf(String value) {
        return new DateTimeType(value);
    }

    public String format(String pattern) {
        try {
            return String.format(pattern, calendar);
        } catch (NullPointerException npe) {
            return DATE_FORMATTER.format(calendar.getTime());
        }
    }

    public String format(Locale locale, String pattern) {
        return String.format(locale, pattern, calendar);
    }

    @Override
    public String toString() {
        return DATE_FORMATTER.format(calendar.getTime());
    }

    @Override
    public int hashCode() {
        final int prime = 31;
        int result = 1;
        result = prime * result + ((calendar == null) ? 0 : calendar.hashCode());
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj)
            return true;
        if (obj == null)
            return false;
        if (getClass() != obj.getClass())
            return false;
        DateTimeType other = (DateTimeType) obj;
        if (calendar == null) {
            if (other.calendar != null)
                return false;
        } else if (!calendar.equals(other.calendar))
            return false;
        return true;
    }

}

import java.util.Arrays;

public class Finder {
    public static void quickSort(int[] list) {
        /* Exercise 23.4 */
        int medianIdx = indexOfMedian(list);
        quickSort(list, medianIdx, list.length - 1);
    }

    public static void quickSort(int[] list, int first, int last) {
        if (last > first) {
            int pivotIndex = partition(list, first, last);
            quickSort(list, first, pivotIndex - 1);
            quickSort(list, pivotIndex + 1, last);
        }
    }

    public static int partition(int[] list, int first, int last) {
        int pivot = list[first]; // Choose the first element as the pivot
        int low = first + 1; // Index for forward search
        int high = last; // Index for backward search

        while (high > low) {
            // Search forward from left
            while (low <= high && list[low] <= pivot)
                low++;

            // Search backward from right
            while (low <= high && list[high] > pivot)
                high--;

            // Swap two elements in the list
            if (high > low) {
                int temp = list[high];
                list[high] = list[low];
                list[low] = temp;
            }
        }

        while (high > first && list[high] >= pivot)
            high--;

        // Swap pivot with list[high]
        if (pivot > list[high]) {
            list[first] = list[high];
            list[high] = pivot;
            return high;
        } else {
            return first;
        }
    }

    static int indexOfMedian(int[] list) {
        int[] temp = {list[0], list[list.length / 2], list[list.length - 1]};
        Arrays.sort(temp);
        if (list[0] == temp[1]) {
            return 0;
        }
        else if (list[list.length / 2] == temp[1]) {
            return list.length / 2;
        }

        return list.length - 1;
    }

    public static void main(String[] args) {
        int[] list = {2, 3, 2, 5, 6, 1, -2, 3, 14, 12};
        quickSort(list);
        for (int i = 0; i < list.length; i++)
            System.out.print(list[i] + " ");
    }
}

import javax.cache.Cache;
import javax.cache.Caching;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.wso2.carbon.context.PrivilegedCarbonContext;
import org.wso2.carbon.registry.core.exceptions.RegistryException;

public class LCManagerFactory {

    private static final Log log = LogFactory.getLog(LCManagerFactory.class);
    private static final String CACHE_NAME = "LC_MANAGER_CACHE";
    private static LCManagerFactory instance = new LCManagerFactory();

    private LCManagerFactory() {
        // Private constructor to enforce singleton pattern
    }

    public static LCManagerFactory getInstance() {
        return instance;
    }

    public RegistryLCManager getLCManager() throws RegistryException {
        PrivilegedCarbonContext carbonContext = PrivilegedCarbonContext.getThreadLocalCarbonContext();
        String tenantDomain = carbonContext.getTenantDomain();
        int tenantId = carbonContext.getTenantId();

        Cache<String, RegistryLCManager> lcCache = Caching.getCacheManager().getCache(CACHE_NAME);
        String cacheKey = tenantDomain + "_" + tenantId;

        RegistryLCManager lcManager = lcCache.get(cacheKey);
        if (lcManager != null) {
            log.debug("Lifecycle manager found in cache for tenant: " + tenantDomain);
            return lcManager;
        }

        try {
            lcManager = new RegistryLCManager();
            lcCache.put(cacheKey, lcManager);
            log.debug("Created and cached new lifecycle manager for tenant: " + tenantDomain);
        } catch (Exception e) {
            log.error("Failed to create lifecycle manager for tenant: " + tenantDomain, e);
            throw new RegistryException("Failed to create lifecycle manager", e);
        }

        return lcManager;
    }
}

