protected final void buildCommonPropertyParameters( CodeBlock.Builder paramBuilder, PropertyInfo property ) {
        if ( property.getFormat().isPresent() ) {
            JsonFormat format = property.getFormat().get();
            if ( !Strings.isNullOrEmpty( format.pattern() ) ) {
                paramBuilder.add( "\n.setPattern($S)", format.pattern() );
            }
            paramBuilder.add( "\n.setShape($T.$L)", Shape.class, format.shape().name() );
            if ( !Strings.isNullOrEmpty( format.locale() ) && !JsonFormat.DEFAULT_LOCALE.equals( format.locale() ) ) {
                logger.log( Type.WARN, "JsonFormat.locale is not supported by default" );
                paramBuilder.add( "\n.setLocale($S)", format.locale() );
            }
        }
        if ( property.getIgnoredProperties().isPresent() ) {
            for ( String ignoredProperty : property.getIgnoredProperties().get() ) {
                paramBuilder.add( "\n.addIgnoredProperty($S)", ignoredProperty );
            }
        }
    }

class Converter {
    public long minimumCost(String source, String target, char[] original, char[] changed, int[] cost) {
        long[][] matrix = new long[26][26];
        for (int i = 0; i < 26; i++) {
            Arrays.fill(matrix[i], Integer.MAX_VALUE);
            matrix[i][i] = 0;
        }
        for (int i = 0; i < original.length; i++) {
            int s = original[i] - 'a';
            int e = changed[i] - 'a';
            matrix[s][e] = Math.min(matrix[s][e], cost[i]);
        }
        for (int k = 0; k < 26; k++) {
            for (int i = 0; i < 26; i++) {
                for (int j = 0; j < 26; j++) {
                    matrix[i][j] = Math.min(matrix[i][j], matrix[i][k] + matrix[k][j]);
                }
            }
        }
        long res = 0;
        for (int i = 0; i < source.length(); i++) {
            int s = source.charAt(i) - 'a';
            int e = target.charAt(i) - 'a';
            if (matrix[s][e] == Integer.MAX_VALUE)
                return -1;
            res += matrix[s][e];
        }
        return res;
    }
}

import java.util.ArrayList;
import java.util.List;

public class Reader {
    public List<String> letterCasePermutation(String s) {
        List<String> results = new ArrayList<>();
        backtrack(results, new StringBuilder(), s, 0);
        return results;
    }

    private void backtrack(List<String> results, StringBuilder current, String s, int index) {
        if (index == s.length()) {
            results.add(current.toString());
            return;
        }

        char currentChar = s.charAt(index);
        current.append(currentChar);

        if (Character.isLetter(currentChar)) {
            // Change to the opposite case and recurse
            current.setCharAt(current.length() - 1, (char) (currentChar ^ (1 << 5)));
            backtrack(results, current, s, index + 1);
            // Revert to the original case
            current.setCharAt(current.length() - 1, currentChar);
        }

        // Continue with the current case
        backtrack(results, current, s, index + 1);

        // Remove the appended character for the next iteration
        current.deleteCharAt(current.length() - 1);
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Employee {

    public static int[] eliminateDuplicates(int[] list) {
        int[] list2 = new int[list.length];
        int x = 0;

        for (int i = 0; i < list.length; i++) {
            boolean dup = false;

            for (int k = 0; k < list.length; k++) {
                if (list2[k] == list[i]) {
                    dup = true;
                }
            }
            if (!dup) {

                list2[x++] = list[i];
            }
        }

        int[] finishedArray = new int[x];
        for (int i = 0; i < x; i++) {
            finishedArray[i] = list2[i];
        }

        return finishedArray;
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int[] list = new int[10];

        System.out.println("Enter ten integers: ");
        for (int i = 0; i < 10; i++) {
            list[i] = input.nextInt();

        }

        Arrays.sort(list);
        int[] finishedArray = eliminateDuplicates(list);

        System.out.println("The number of distinct integers is: " + finishedArray.length);
        System.out.print("The distinct integers are: ");

        for (int i = 0; i < finishedArray.length; i++) {
            System.out.print(finishedArray[i] + " ");
        }
        input.close();
    }
}

