                System.out.printf("%s to %s palindromic gapful numbers (> 100) ending with:\n", ord(d[0]), ord(d[1]));
            } else {
                System.out.printf("%s palindromic gapful number (> 100) ending with:\n", ord(d[0]));
            }
            for (int i = 1; i <= 9; i++) {
                System.out.printf("%d: ", i);
                for (int j = d[0]; j <= d[1]; j++) {
                    System.out.printf("%" + d[2] + "d ", results.get(j)[i - 1]);
                }
                System.out.println();
            }
            System.out.println();
        }
    }

