@Component
public class PdfView extends AbstractITextPdfView {

    @Override
    protected void buildPdfDocument(Map<String, Object> model, Document document, PdfWriter writer,
                                    HttpServletRequest request, HttpServletResponse response) throws Exception {
        // Retrieve face attributes from the model
        String leftEye = (String) model.get("leftEye");
        String rightEye = (String) model.get("rightEye");
        String nose = (String) model.get("nose");
        String mouth = (String) model.get("mouth");

        // Set document size
        document.setPageSize(PageSize.A4);
        document.open();

        // Fetch and position images
        Image leftEyeImage = getImage(leftEye);
        Image rightEyeImage = getImage(rightEye);
        Image noseImage = getImage(nose);
        Image mouthImage = getImage(mouth);

        // Calculate positions
        float pageWidth = PageSize.A4.getWidth();
        float pageHeight = PageSize.A4.getHeight();

        float eyeSpacing = 50f;
        float eyeYPosition = pageHeight - 150f;
        float noseYPosition = eyeYPosition - 100f;
        float mouthYPosition = noseYPosition - 100f;

        float leftEyeXPosition = (pageWidth / 2) - (leftEyeImage.getWidth() / 2) - eyeSpacing;
        float rightEyeXPosition = (pageWidth / 2) - (rightEyeImage.getWidth() / 2) + eyeSpacing;
        float noseXPosition = (pageWidth / 2) - (noseImage.getWidth() / 2);
        float mouthXPosition = (pageWidth / 2) - (mouthImage.getWidth() / 2);

        // Add images to the document
        leftEyeImage.setAbsolutePosition(leftEyeXPosition, eyeYPosition);
        rightEyeImage.setAbsolutePosition(rightEyeXPosition, eyeYPosition);
        noseImage.setAbsolutePosition(noseXPosition, noseYPosition);
        mouthImage.setAbsolutePosition(mouthXPosition, mouthYPosition);

        document.add(leftEyeImage);
        document.add(rightEyeImage);
        document.add(noseImage);
        document.add(mouthImage);

        document.close();
    }

