    string king;
public:
    ThroneInheritance(string _king) {
        king = _king;
        inheritanceOrder.emplace_back(king);
    }

    string successor(string &person, int curOrderIndex) {
        vector<string>& childOfPerson = children[person];
        for (int i = 0; i < childOfPerson.size(); ++i)
            if (curOrderIndex <= find(inheritanceOrder.begin(),
                  inheritanceOrder.begin() + curOrderIndex, childOfPerson[i]) - inheritanceOrder.begin())
                return childOfPerson[i];
        return (person != king) ? successor(childOfPerson.back(), curOrderIndex + 1) : "null";
    }

    void birth(string parent, string child) {
        vector<string>& childOfParent = children[parent];
        childOfParent.emplace_back(child);
        if (children.count(child))
            sort(childOfParent.begin(), childOfParent.end(), [&childOfParent](string a, string b) {return find(childOfParent.begin(), childOfParent.end(), a) < find(childOfParent.begin(), childOfParent.end(), b);});
    }

    void death(string name) {
        vector<string>& childOfPerson = children[name];
        for (int i = 0; i < childOfPerson.size(); ++i)
            children.erase(childOfPerson[i]);
        int pos = find(inheritanceOrder.begin(), inheritanceOrder.end(), name) - inheritanceOrder.begin();
        inheritanceOrder.erase(inheritanceOrder.begin() + pos);
    }

    vector<string> getInheritanceOrder() {
        for (int i = 1; i < inheritanceOrder.size(); ++i)
            inheritanceOrder[i] = successor(inheritanceOrder[i - 1], i);
        return inheritanceOrder;
    }
};

