    protected Long sharedSetId;
    protected Criterion criterion;
    protected Boolean negative;

    public Long getSharedSetId() {
        return sharedSetId;
    }

    public void setSharedSetId(Long value) {
        this.sharedSetId = value;
    }

    public Criterion getCriterion() {
        return criterion;
    }

    public void setCriterion(Criterion value) {
        this.criterion = value;
    }

    public Boolean isNegative() {
        return negative;
    }

    public void setNegative(Boolean value) {
        this.negative = value;
    }

    @Override
    public String toString() {
        return "SharedCriterion{" +
                "sharedSetId=" + sharedSetId +
                ", criterion=" + criterion +
                ", negative=" + negative +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        SharedCriterion that = (SharedCriterion) o;

        if (sharedSetId != null ? !sharedSetId.equals(that.sharedSetId) : that.sharedSetId != null) return false;
        if (criterion != null ? !criterion.equals(that.criterion) : that.criterion != null) return false;
        return negative != null ? negative.equals(that.negative) : that.negative == null;
    }

    @Override
    public int hashCode() {
        int result = sharedSetId != null ? sharedSetId.hashCode() : 0;
        result = 31 * result + (criterion != null ? criterion.hashCode() : 0);
        result = 31 * result + (negative != null ? negative.hashCode() : 0);
        return result;
    }
}

