import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class LogEntryLambdaListener {
    private static final Logger logger = LoggerFactory.getLogger(LogEntryLambdaListener.class);
    private final AmazonS3 s3Client = AmazonS3ClientBuilder.standard().build();
    private final ObjectMapper mapper = new ObjectMapper();
    private final LogSender kafkaSender = new LogSender();

    public void handleRequest(S3Event event, Context context) {
        for (S3EventNotificationRecord record : event.getRecords()) {
            String bucket = record.getS3().getBucket().getName();
            String key = record.getS3().getObject().getKey();
            logger.info("Processing s3://{}/{}", bucket, key);

            try (S3Object s3Object = s3Client.getObject(bucket, key);
                 BufferedReader reader = new BufferedReader(new InputStreamReader(s3Object.getObjectContent()))) {

                String line;
                while ((line = reader.readLine()) != null) {
                    try {
                        LogEntry entry = LogEntry.parse(line);
                        String json = mapper.writeValueAsString(entry);
                        kafkaSender.sendMessage(json);
                    } catch (Exception e) {
                        logger.error("Failed to process line: {}", line, e);
                    }
                }
            } catch (IOException e) {
                logger.error("Error processing s3://{}/{}: {}", bucket, key, e.getMessage());
            }
        }
    }
}

