@Deprecated
@Description("Opens a bzip2-compressed file and provides a reader for the decompressed content.")
@In(String.class)
@Out(Reader.class)
public class Bzip2Opener extends DefaultObjectPipe<String, ObjectReceiver<Reader>> implements Opener {

    private int bufferSize = 1024 * 1024; // Default buffer size: 1MB
    private Charset encoding = StandardCharsets.UTF_8;

    @Override
    public void process(String filePath) {
        try (FileInputStream fileInputStream = new FileInputStream(filePath);
             BZip2CompressorInputStream bzip2InputStream = new BZip2CompressorInputStream(fileInputStream);
             InputStreamReader inputStreamReader = new InputStreamReader(bzip2InputStream, encoding);
             BufferedReader bufferedReader = new BufferedReader(inputStreamReader, bufferSize)) {

            getReceiver().process(bufferedReader);

        } catch (IOException e) {
            throw new RuntimeException("Failed to open or decompress the bzip2 file: " + filePath, e);
        }
    }

    public String getEncoding() {
        return encoding.name();
    }

    public void setEncoding(String encoding) {
        this.encoding = Charset.forName(encoding);
    }

    public int getBufferSize() {
        return bufferSize;
    }

    public void setBufferSize(int bufferSize) {
        this.bufferSize = bufferSize;
    }
}

