import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
 
public class WPrimes {
 
    public static boolean isWPrime(int n) {
        return n == 2 || (
            n > 1
            && n % 2!= 0
            && (factorial(n - 1) + 1) % n == 0
        );
    }
 
    public static long factorial(int n) {
        long result = 1;
        for (int i = 2; i <= n; i++) {
            result *= i;
        }
        return result;
    }
 
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter upper limit: ");
        int c = scanner.nextInt();
        scanner.close();
        System.out.println("Primes under " + c + ":");
        List<Integer> primes = new ArrayList<>();
        for (int n = 0; n < c; n++) {
            if (isWPrime(n)) {
                primes.add(n);
            }
        }
        System.out.println(primes);
    }
}

def ModuloPathCount(grid, rows, cols, memo):
    for row in range(rows):
        for col in range(cols):
            if row == 0 and col == 0:
                memo[row][col] = 1
            elif row == 0:
                memo[row][col] = memo[row][col - 1]
            elif col == 0:
                memo[row][col] = memo[row - 1][col]
            else:
                memo[row][col] = memo[row - 1][col] + memo[row][col - 1]

    dp = list()
    for row in range(rows):
        tmp = list()
        for col in range(cols):
            tmp.append(0)
        dp.append(tmp)

    for row in range(rows):
        for col in range(cols):
            if row == 0 and col == 0:
                dp[row][col] = 1
            elif row == 0:
                dp[row][col] = memo[row][col - 1]
            elif col == 0:
                dp[row][col] = memo[row - 1][col]
            else:
                dp[row][col] = memo[row - 1][col] + memo[row][col - 1]

    count = 0
    for row in range(rows):
        for col in range(cols):
            if grid[row][col] == 1:
                count += dp[row][col]

    return count % 1000000007

