import java.util.*;

public class Runner {

    public List<Integer> minCostPath(int[] coins, int maxJump) {
        int n = coins.length;
        Integer[] path = new Integer[(int) n];

        int[] dp = new int[n];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = coins[0];

        for (int i = 1; i < n; i++) {
            if (coins[i] != -1) {
                for (int j = 1; j <= maxJump && i + j < n; j++) {
                    dp[i] = Math.min(dp[i], dp[i - j] + coins[i]);
                }
            }
        }

        if (dp[n-1] == Integer.MAX_VALUE) {
            return new ArrayList<>();
        }

        path[(int) n-1] = n-1;
        int current = path[(int) n-1];

        for (int i = n - 2; i >= 0; i--) {
            if (dp[i] != dp[current] - coins[current]) {
                return null;
            }
            if (Math.abs(current - i) <= maxJump) {
                path[i] = current;
                current = i;
            }
        }

        List<Integer> result = new ArrayList<>();
        for (Integer i : path) {
            result.add(i);
        }
        Collections.reverse(result);

        return result;
    }
}

