import java.util.*;
import java.io.*;

public class SpecialExchangeSolver {

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int testCases = fs.nextInt();

        while (testCases-- > 0) {
            int n = fs.nextInt();
            int[] scores = fs.nextIntArray(n);
            int exchanges = 0;

            for (int i = 1; i < n; i++) {
                if (scores[i] <= scores[i - 1]) {
                    exchanges += Integer.bitCount(scores[i] ^ scores[i - 1]);
                }
            }

            out.println(exchanges);
        }

        out.flush();
        out.close();
    }

    static class FastScanner {
        private BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        String next() throws IOException {
            while (!st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) throws IOException {
            int[] arr = new int[n];
            for (int i = 0; i < n; i++)
                arr[i] = nextInt();
            return arr;
        }
    }
}

public Response deleteTemplate(String id) throws RequestException, LocalOperationException {
    // Create a Transloadit API request to delete the specified template
    Request request = new Request(Method.DELETE, "/templates/" + id);

    // Send the request to the Transloadit API
    Response response = request.send();

    // Handle any errors that may have occurred during the request
    if (response.isSuccess()) {
        return response;
    } else if (response.isClientError()) {
        throw new RequestException("Client error: " + response.getStatusCode());
    } else if (response.isServerError()) {
        throw new RequestException("Server error: " + response.getStatusCode());
    } else {
        throw new LocalOperationException("Unknown error occurred while deleting template");
    }
}

import java.util.Arrays;
import java.util.stream.IntStream;

public class TwinPrimes {
    static int[] res = new int[10];
    static int ri = 1, p = 10, count = 0;

    static void tabulateTwinPrimes(int bound) {
        if (bound < 5) return; count++;
        int cl = (bound - 1) >> 1, i = 1, j,
                limit = (int) (Math.sqrt(bound) - 1) >> 1;
        boolean[] comp = new boolean[cl]; boolean lp;
        for (j = 3; j < cl; j += 3) comp[j] = true;
        while (i < limit) {
            if (lp =!comp[i]) {
                int pr = (i << 1) + 3;
                for (j = (pr * pr - 2) >> 1; j < cl; j += pr)
                    comp[j] = true;
            }
            if (!comp[++i]) {
                int pr = (i << 1) + 3;
                if (lp) {
                    if (pr > p) {
                        res[ri++] = count;
                        p *= 10;
                    }
                    count++;
                    i++;
                }
                for (j = (pr * pr - 2) >> 1; j < cl; j += pr)
                    comp[j] = true;
            }
        }
        cl--;
        while (i < cl) {
            lp =!comp[i++];
            if (!comp[i] && lp) {
                if ((i++ << 1) + 3 > p) {
                    res[ri++] = count;
                    p *= 10;
                }
                count++;
            }
        }
        res[ri] = count;
    }

    public static void main(String[] args) {
        long start = System.currentTimeMillis();
        String fmt = "%9d twin primes below %13d";
        tabulateTwinPrimes(1_000_000_000);
        long end = System.currentTimeMillis();
        p = 1;
        for (int j = 1; j <= ri; j++)
            System.out.println(String.format(fmt, res[j], p *= 10));
        System.out.println((end - start) / 1000.0 + " sec");
    }
}

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
 
public class Sieve {
  public static void main(String[] args) {
    BlockingQueue<Integer> ch = new LinkedBlockingQueue<Integer>();
    new Thread(new Primes(ch)).start();
    System.out.print("First twenty:");
    for (int i = 0; i < 20; i++) {
      try {
        System.out.print(" " + ch.take());
      } catch (InterruptedException e) {
        e.printStackTrace();
      }
    }
    System.out.println();
  }
}
 
class Primes implements Runnable {
  private BlockingQueue<Integer> ch;
  public Primes(BlockingQueue<Integer> ch) {
    this.ch = ch;
  }
  public void run() {
    ch.add(2);
    new Thread(new Sieve(ch)).start();
  }
}
 
class Sieve implements Runnable {
  private BlockingQueue<Integer> ch;
  public Sieve(BlockingQueue<Integer> ch) {
    this.ch = ch;
  }
  public void run() {
    ch.add(3);
    int q = 9;
    BlockingQueue<Integer> ps = new LinkedBlockingQueue<Integer>();
    new Thread(new Sieve(ps)).start();
    int p = ps.poll();
    BlockingQueue<Integer> nums = new LinkedBlockingQueue<Integer>();
    new Thread(new NumsFromBy(5,2,nums)).start();
    for (int i = 0; ; i++) {
      int n = nums.poll();
      if (n < q) {
        ch.add(n);
      } else {
        BlockingQueue<Integer> ch1 = new LinkedBlockingQueue<Integer>();
        new Thread(new Filter(nums, ch1, p)).start();
        nums = ch1;
        p = ps.poll();
        q = p*p;
      }
    }
  }
}
 
class NumsFromBy implements Runnable {
  private int from;
  private int by;
  private BlockingQueue<Integer> ch;
  public NumsFromBy(int from, int by, BlockingQueue<Integer> ch) {
    this.from = from;
    this.by = by;
    this.ch = ch;
  }
  public void run() {
    for (int i = from; ; i+=by) {
      ch.add(i);
    }
  }
}
 
class Filter implements Runnable {
  private BlockingQueue<Integer> in;
  private BlockingQueue<Integer> out;
  private int prime;
  public Filter(BlockingQueue<Integer> in, BlockingQueue<Integer> out, int prime) {
    this.in = in;
    this.out = out;
    this.prime = prime;
  }
  public void run() {
    for (int i = in.poll(); ; i = in.poll()) {
      if (i%prime!= 0) {
        out.add(i);
      }
    }
  }
}

