public class PidIterator implements Iterator<String> {
    private List<String> pids;
    private int currentIndex = 0;

    public PidIterator(List<String> pids) {
        this.pids = new ArrayList<>(pids);
    }

    @Override
    public boolean hasNext() {
        return currentIndex < pids.size() && pids.get(currentIndex) != null;
    }

    @Override
    public String next() {
        return pids.get(currentIndex++);
    }
}

