    public ParentRowReference(InsertRow parentRow, KeyPropagation keyPropagation) {
        this.parentRow = parentRow;
        this.keyPropagation = keyPropagation;
        this.hrefingRows = new HashMap<>();
    }

    public InsertRow getTarget() {
        return parentRow;
    }

    public KeyPropagation getKeyPropagation() {
        return keyPropagation;
    }

    public void addHrefingRow(InsertRow childRow, SQLIdentifier fkIdentifier) {
        hrefingRows.put(childRow, fkIdentifier);
    }

    public boolean isHrefed(InsertRow childRow) {
        return hrefingRows.containsKey(childRow);
    }

    public SQLIdentifier getHrefColumn(InsertRow childRow) {
        return hrefingRows.get(childRow);
    }

    public void printRelationships() {
        System.out.println("Parent Row: " + parentRow.getRowData());
        System.out.println("Key Propagation: " + keyPropagation);
        System.out.println("Child Rows:");
        for (Map.Entry<InsertRow, SQLIdentifier> entry : hrefingRows.entrySet()) {
            System.out.println("Child Row: " + entry.getKey().getRowData() + ", FK Column: " + entry.getValue());
        }
    }
}

