    private static final String MD5 = "MD5";
    private static final SecureRandom random = new SecureRandom();

    private Digests() {
        // Private constructor to prevent instantiation
    }

    public static byte[] md5(byte[] input) {
        return digest(input, MD5, null, 1);
    }

    public static byte[] md5(byte[] input, byte[] salt) {
        return digest(input, MD5, salt, 1);
    }

    public static byte[] md5(byte[] input, byte[] salt, int iterations) {
        return digest(input, MD5, salt, iterations);
    }

    public static byte[] sha1(byte[] input) {
        return digest(input, SHA1, null, 1);
    }

    public static byte[] sha1(byte[] input, byte[] salt) {
        return digest(input, SHA1, salt, 1);
    }

    public static byte[] sha1(byte[] input, byte[] salt, int iterations) {
        return digest(input, SHA1, salt, iterations);
    }

    public static byte[] md5(InputStream input) throws IOException {
        return digest(input, MD5, null, 1);
    }

    public static byte[] sha1(InputStream input) throws IOException {
        return digest(input, SHA1, null, 1);
    }

    public static byte[] digest(byte[] input, String algorithm, byte[] salt, int iterations) {
        Validate.notNull(input, "Input cannot be null");
        Validate.notBlank(algorithm, "Algorithm cannot be blank");
        Validate.isTrue(iterations >= 1, "Iterations must be positive");

        try {
            MessageDigest digest = MessageDigest.getInstance(algorithm);

            if (salt != null) {
                digest.update(salt);
            }

            byte[] result = digest.digest(input);

            for (int i = 1; i < iterations; i++) {
                digest.reset();
                result = digest.digest(result);
            }

            return result;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Error computing digest: " + algorithm, e);
        }
    }

    public static byte[] digest(InputStream input, String algorithm, byte[] salt, int iterations) throws IOException {
        Validate.notNull(input, "Input stream cannot be null");
        Validate.notBlank(algorithm, "Algorithm cannot be blank");

