private static double IndianToJD(int year, int month, int date) {
       int leapMonth, gyear, m;
       double start, jd;
       gyear = year + INDIAN_ERA_START;
       if(isGregorianLeap(gyear)) {
          leapMonth = 31;
          start = gregorianToJD(gyear, 3, 21);
       } else {
          leapMonth = 30;
          start = gregorianToJD(gyear, 3, 22);
       }
       if (month == 1) {
          jd = start + (date - 1);
       } else {
          jd = start + leapMonth;
          m = month - 2;
          m = Math.min(m, 5);
          jd += m * 31;
          if (month >= 8) {
             m = month - 7;
             jd += m * 30;
          }
          jd += date - 1;
       }
       return jd;
    }

public class Queue {
    private int[] elements;
    private int size;

    public Queue() {
        elements = new int[8];
    }

    public void enqueue(int v) {
        if (size >= elements.length) {
            int[] temp = new int[elements.length * 2];
            System.arraycopy(elements, 0, temp, 0, elements.length);
            elements = temp;
        }
        elements[size++] = v;
    }

    public int dequeue() {
        int v = elements[0];
        size--;
        for (int i = 0; i < size; i++) {
            elements[i] = elements[i+1];
        }
        return v;
    }

    public boolean empty() {
        return size == 0;
    }

    public int getSize() {
        return size;
    }
}

import java.io.BufferedReader;

import java.io.IOException;

import java.io.InputStreamReader;

import java.io.PrintWriter;

import java.util.ArrayList;

import java.util.Arrays;

import java.util.Collections;

import java.util.StringTokenizer;

public class Solve {

    static FastScanner fs = new FastScanner();

    static PrintWriter out = new PrintWriter(System.out);

    public static void main(String[] args) {

        int a = fs.nextInt();

        while (a-- != 0) {

            solve();

        }

        out.close();

    }

    public static void solve() {

        int n = fs.nextInt();

        int[] type = fs.readArray(n);

        int[] damage = new int[n];

        ArrayList<Integer> type0 = new ArrayList<>();

        ArrayList<Integer> type1 = new ArrayList<>();

        long sum = 0;

        for (int i = 0; i < n; i++) {

            damage[i] = fs.nextInt();

            sum += damage[i];

            if ((type[i] == 0 ? type0 : type1).add(damage[i])) ;

        }

        Collections.sort(type0);

        Collections.sort(type1);

        if (type0.size() == type1.size()) {

            int min = Math.min(type1.get(0), type0.get(0));

            sum *= 2;

            sum -= min;

        } else {

            int min = Math.min(type1.size(), type0.size());

            for (int i = 1; i <=min; i++) {

                sum+=type0.get(type0.size()-i);

                sum+=type1.get(type1.size()-i);

            }

        }

        System.out.println(sum);

    }

    static class FastScanner {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer("");

        String next() {

            while (!st.hasMoreTokens())

                try {

                    st = new StringTokenizer(br.readLine());

                } catch (IOException e) {

                    e.printStackTrace();

                }

            return st.nextToken();

        }

        int nextInt() {

            return Integer.parseInt(next());

        }

        int[] readArray(int n) {

            int[] a = new int[n];

            for (int i = 0; i < n; i++) a[i] = nextInt();

            return a;

        }

        long nextLong() {

            return Long.parseLong(next());

        }

    }

}

import java.util.*;

public class SimplePolygonEmbedding2 {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int testCases = sc.nextInt();

        StringBuilder sb = new StringBuilder();

        for (int t = 0; t < testCases; t++) {

            int n = sc.nextInt();

            double theta = Math.toRadians(180 / 4);

            double delta = Math.toRadians((double) 180 / n);

            double x = 0, min = Double.MAX_VALUE, max = Double.MIN_VALUE;

            for (int i = 0; i < 2 * n; i++) {

                x = x + Math.cos(theta);

                theta = theta - delta;

                min = Math.min(x, min);

                max = Math.max(x, max);

            }

            double ans = max - min;

            sb.append(ans).append("\n");

        }

        System.out.print(sb);

    }

}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Checker {
    public TreeNode[] splitBST(TreeNode root, int V) {
        TreeNode sP = new TreeNode(0), bP = new TreeNode(0);
        split(root, V, sP, bP);
        TreeNode[] ans = new TreeNode[2];
        ans[0] = sP.right;
        ans[1] = bP.left;
        return ans;
    }

    private void split(TreeNode node, int v, TreeNode sP, TreeNode bP) {
        if (node == null) return;
        if (node.val <= v) {
            sP.right = node;
            TreeNode right = node.right;
            node.right = null;
            split(right, v, node, bP);
        } else {
            bP.left = node;
            TreeNode left = node.left;
            node.left = null;
            split(left, v, sP, node);
        }
    }
}

