import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class Shell implements Plugin {
    private static final Logger LOGGER = Logger.getLogger(Shell.class.getName());
    private static final String DEFAULT_SHELL_COMMAND = "/bin/bash";

    private String shellCommand;
    private Process shellProcess;
    private HandlerPTY pty;
    private BufferedReader processReader;
    private BufferedWriter processWriter;
    private ExecutorService executor;
    private volatile boolean isConnected;

    public Shell() {
        this.shellCommand = System.getProperty("shell.command", DEFAULT_SHELL_COMMAND);
        this.executor = Executors.newFixedThreadPool(2);
        this.isConnected = false;
    }

    @Override
    public void start() {
        try {
            initializeShellProcess();
            startIOStreams();
            broadcastConnectionEvent(true);
        } catch (IOException e) {
            LOGGER.severe("Failed to start shell process: " + e.getMessage());
            disconnect();
        }
    }

    private void initializeShellProcess() throws IOException {
        ProcessBuilder processBuilder = new ProcessBuilder(shellCommand);
        processBuilder.redirectErrorStream(true);
        shellProcess = processBuilder.start();
    }

    private void startIOStreams() {
        processReader = new BufferedReader(new InputStreamReader(shellProcess.getInputStream()));
        processWriter = new BufferedWriter(new OutputStreamWriter(shellProcess.getOutputStream()));

        executor.submit(this::readProcessOutput);
    }

    private void readProcessOutput() {
        try {
            String line;
            while ((line = processReader.readLine()) != null && isConnected) {
                broadcastOutputEvent(line);
            }
        } catch (IOException e) {
            LOGGER.warning("Error reading process output: " + e.getMessage());
        } finally {
            disconnect();
        }
    }

    public void write(String input) {
        if (!isConnected) return;

        try {
            processWriter.write(input + "\n");
            processWriter.flush();
        } catch (IOException e) {
            LOGGER.warning("Failed to write to shell: " + e.getMessage());
            disconnect();
        }
    }

    @Override
    public void connect() {
        if (!isConnected) {
            start();
            isConnected = true;
        }
    }

    @Override
    public void disconnect() {
        if (isConnected) {
            isConnected = false;

