            notifyPropertyChanged(androidx.databinding.library.baseAdapters.BR.value);
            notifyPropertyChanged(androidx.databinding.library.baseAdapters.BR.formattedValue);
        }
    }

    public void setSilent(Double newValue) {
        suppressUpdate = true;
        setValue(newValue);
        suppressUpdate = false;
    }

    private boolean shouldUpdateValue(Double newValue) {
        return newValue == null && value != null ||
               newValue != null && !newValue.equals(value);
    }

