import java.util.*;

interface GfmlScopeItm {
    String key();
    int docPos();
}

class GfmlScopeList {
    private final String key;
    private final List<GfmlScopeItm> list;

    public GfmlScopeList(String key) {
        this.key = key;
        this.list = new ArrayList<>();
    }

    public void add(GfmlScopeItm item) {
        list.add(item);
    }

    public boolean del(GfmlScopeItm item) {
        return list.remove(item);
    }

    public GfmlScopeItm fetch(int docPos) {
        for (int i = list.size() - 1; i >= 0; i--) {
            GfmlScopeItm item = list.get(i);
            if (item.docPos() <= docPos) {
                return item;
            }
        }
        return null;
    }

    public boolean isEmpty() {
        return list.isEmpty();
    }
}

class GfmlScopeRegy {
    private final Map<String, GfmlScopeList> hash;

    public GfmlScopeRegy() {
        this.hash = new HashMap<>();
    }

    public boolean has(String key) {
        return hash.containsKey(key) && !hash.get(key).isEmpty();
    }

    public void add(GfmlScopeItm item) {
        GfmlScopeList list = itmOrNew(item.key());
        list.add(item);
    }

    public void del(GfmlScopeItm item) {
        GfmlScopeList list = hash.get(item.key());
        if (list != null) {
            list.del(item);
            if (list.isEmpty()) {
                hash.remove(item.key());
            }
        }
    }

    public GfmlScopeItm fetch(String key, int docPos) {
        GfmlScopeList list = hash.get(key);
        if (list != null) {
            return list.fetch(docPos);
        }
        return null;
    }

    private GfmlScopeList itmOrNew(String key) {
        return hash.computeIfAbsent(key, k -> new GfmlScopeList(k));
    }
}

int getHalfEdgeConnector(int clusterFrom, int clusterTo) {
        int first_edge = getClusterHalfEdge(clusterFrom);
        if (first_edge == -1)
            return -1;
        int edge = first_edge;
        int firstEdgeTo = -1;
        int eTo = -1;

        do {
            if (getHalfEdgeTo(edge) == clusterTo)
                return edge;
            if (firstEdgeTo == -1) {
                firstEdgeTo = getClusterHalfEdge(clusterTo);
                if (firstEdgeTo == -1)
                    return -1;
                eTo = firstEdgeTo;
            }
            if (getHalfEdgeTo(eTo) == clusterFrom) {
                edge = getHalfEdgeTwin(eTo);
                assert (getHalfEdgeTo(edge) == clusterTo && getHalfEdgeOrigin(edge) == clusterFrom);
                return edge;
            }
            edge = getHalfEdgeNext(getHalfEdgeTwin(edge));
            eTo = getHalfEdgeNext(getHalfEdgeTwin(eTo));
        } while (edge != first_edge && eTo != firstEdgeTo);
        return -1;
    }

