class Product {
    public List<Integer> topStudents(String[] positive_feedback, String[] negative_feedback, String[] report, int[] student_id, int k) {
        Set<String> pos = new HashSet<>();

        for (String s : positive_feedback){
            pos.add(s);
        }

        Set<String> neg = new HashSet<>();

        for (String s : negative_feedback){
            neg.add(s);
        }

        List<int []> list = new ArrayList<>();
        String [] arr;

        for (int i = 0; i < report.length; ++i){
            arr = report[i].split(" ");
            int score = 0;

            for (String s : arr){
                //System.out.println(s + " " + score);
                if (pos.contains(s))
                    score += 3;

                if (neg.contains(s))
                    score -= 1;
            }

            list.add(new int [] { score, student_id[i]});
        }

        Collections.sort(list, (a, b) -> a[0] == b[0] ? a[1] - b[1] : b[0] - a[0]);

        List<Integer> res = new ArrayList<>();

        for (int i = 0; i < k; ++i){
            res.add(list.get(i)[1]);
        }

        return res;
    }
}

import java.util.Random;
import java.lang.Math;
 
public class Pi {
    public static double pi(double tolerance) {
        double x, y, val, error;
        long sampled = 0, hit = 0, i;
        Random rand = new Random();
        do {
            /* don't check error every turn, make loop tight */
            for (i = 1000000; i > 0; i--, sampled++) {
                x = rand.nextDouble();
                y = rand.nextDouble();
                if (x * x + y * y < 1) hit++;
            }
            val = (double) hit / sampled;
            error = Math.sqrt(val * (1 - val) / sampled) * 4;
            val *= 4;
            /* some feedback, or user gets bored */
            System.err.printf("Pi = %f +/- %5.3e at %dM samples.\r",
                    val, error, sampled/1000000);
        } while (!hit || error > tolerance);
        /* !hit is for completeness's sake; if no hit after 1M samples,
         * your rand() is BROKEN */
        return val;
    }
    public static void main(String[] args) {
        System.out.printf("Pi is %f\n", pi(3e-4)); /* set to 1e-4 for some fun */
    }
}

private void write0(int b) throws IOException {
        if (this.currentChar != -1) {
            b &= 0xff;
            if (this.currentChar == b) {
                if (++this.runLength > 254) {
                    writeRun();
                    this.currentChar = -1;
                    this.runLength = 0;
                }

            } else {
                writeRun();
                this.runLength = 1;
                this.currentChar = b;
            }
        } else {
            this.currentChar = b & 0xff;
            this.runLength++;
        }
    }

public class SayiFormatiHatasi {

    public static void main(String[] args) {

        // Giris argumanlarini simule eden bir dizi tanimlandi
        String[] girisDizisi = {"10.1", "0"}; // Burada farkli degerlerle denenebilir

        try {
            // Diziden degerleri al ve tamsayi olarak ayristir
            int x = Integer.parseInt(girisDizisi[0]);
            int y = Integer.parseInt(girisDizisi[1]);

            // Iki sayiyi bol ve sonucu yazdir
            int z = x / y;
            System.out.println("Sonuc: " + z);

        } catch (NumberFormatException e) {
            // Eger girilen veri tamsayi degilse bu istisna firlatilir
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArithmeticException e) {
            // Eger bolme islemi sifira bolme icermisse bu istisna firlatilir
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } catch (ArrayIndexOutOfBoundsException e) {
            // Eger dizi eksikse bu istisna firlatilir
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisna izini yazdir

        } finally {
            // Bu blok her zaman calisir
            System.out.println("Finally bloguna girildi!");
        }

        // Ek bir ornek: Istisna firlatmayan normal bir akisi test et
        try {
            basariliAkisTesti();
        } catch (Exception e) {
            System.out.println("Beklenmeyen bir hata: " + e.getMessage());
        }
    }

    /**
     * Basarili bir akis senaryosunu test eder.
     */
    public static void basariliAkisTesti() {
        System.out.println("Basarili akis testi calisiyor.");
        int a = 10;
        int b = 5;
        int sonuc = a / b;
        System.out.println("10 / 5 = " + sonuc);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

