import java.io.BufferedReader;

import java.io.InputStreamReader;

public class D {

    public static void main(String[] args) throws Exception{

        BufferedReader bu = new BufferedReader(new InputStreamReader(System.in));

        StringBuilder sb = new StringBuilder();

        //String[] s = bu.readLine().split(" ");

        //int tt = Integer.parseInt(s[0]);

        for(int t=0; t<1; ++t){

            String[] s = bu.readLine().split(" ");

            int n = Integer.parseInt(s[0]);

            int N = n*300, M = 998244353;

            s = bu.readLine().split(" ");

            int[] a = new int[n];

            for(int i=0; i<n; ++i) a[i] = Integer.parseInt(s[i]);

            int[][] dp = new int[n][2*N];

            dp[1][a[1]+N] = 1;

            for(int i=1; i+1<n; ++i) for(int j=0; j<2*N; ++j) if(dp[i][j]!=0){

                int val = j-N;

                dp[i+1][a[i+1]+val+N] += dp[i][j];

                dp[i+1][a[i+1]+val+N] %= M;

                if(val!=0){

                    dp[i+1][a[i+1]-val+N] += dp[i][j];

                    dp[i+1][a[i+1]-val+N] %= M;

                }

            }

            int ans = 0;

            for(int x: dp[n-1]){

                ans += x;

                ans %= M;

            }

            sb.append(ans+"\n");

        }

        System.out.print(sb);

    }

}

import java.util.Scanner;

public class StringPermutation {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String str = input.nextLine();
        displayPermutation(" ", str);
    }

    public static void displayPermutation(String s) {
        displayPermutation("", s);
    }

    public static void displayPermutation(String s1, String s2) {
        if (s2.length() == 0) {
            System.out.println(s1);
        } else {
            for (int i = 0; i < s2.length(); i++) {
                char ch = s2.charAt(i);
                String newS1 = s1 + ch;
                String newS2 = s2.substring(0, i) + s2.substring(i + 1);
                displayPermutation(newS1, newS2);
            }
        }
    }
}

