    }

protected SoyMsgBundle createSoyMsgBundle(final Locale locale) throws IOException {
        Preconditions.checkNotNull(messagesPath, "messagesPath cannot be null!");
        final String path = messagesPath  + "_" + locale.toString() + ".xlf";
        final Enumeration<URL> e = Thread.currentThread().getContextClassLoader().getResources(path);
        final List<SoyMsgBundle> msgBundles = Lists.newArrayList();
        final SoyMsgBundleHandler msgBundleHandler = new SoyMsgBundleHandler(new XliffMsgPlugin());
        while (e.hasMoreElements()) {
            final URL msgFile = e.nextElement();
            final SoyMsgBundle soyMsgBundle = msgBundleHandler.createFromResource(msgFile);
            msgBundles.add(soyMsgBundle);
        }
        return mergeMsgBundles(locale, msgBundles).orNull();
    }

import java.util.Scanner;
 
public class SudokuSolver {
 
    private int[] grid;
 
    public SudokuSolver(String s) {
        grid = new int[81];
        for (int i = 0; i < s.length(); i++) {
            grid[i] = Integer.parseInt(s.substring(i, i + 1));
        }
    }
 
    public void solve() {
        try {
            placeNumber(0);
            System.out.println("Unsolvable!");
        } catch (Exception ex) {
            System.out.println(ex.getMessage());
            System.out.println(this);
        }
    }
 
    public void placeNumber(int pos) {
        if (pos == 81) {
            throw new RuntimeException("Finished!");
        }
        if (grid[pos] > 0) {
            placeNumber(pos + 1);
            return;
        }
        for (int n = 1; n <= 9; n++) {
            if (checkValidity(n, pos % 9, pos / 9)) {
                grid[pos] = n;
                placeNumber(pos + 1);
                grid[pos] = 0;
            }
        }
    }
 
    public boolean checkValidity(int val, int x, int y) {
        for (int i = 0; i < 9; i++) {
            if (grid[y * 9 + i] == val || grid[i * 9 + x] == val)
                return false;
        }
        int startX = (x / 3) * 3;
        int startY = (y / 3) * 3;
        for (int i = startY; i < startY + 3; i++) {
            for (int j = startX; j < startX + 3; j++) {
                if (grid[i * 9 + j] == val)
                    return false;
            }
        }
        return true;
    }
 
    public String toString() {
        String sb = "";
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                sb += (grid[i * 9 + j] + " ");
                if (j == 2 || j == 5)
                    sb += ("| ");
            }
            sb += ('\n');
            if (i == 2 || i == 5)
                sb += ("------+-------+------\n");
        }
        return sb;
    }
 
    public static void main(String[] args) {
        new SudokuSolver("850002400" +
                         "720000009" +
                         "004000000" +
                         "000107002" +
                         "305000900" +
                         "040000000" +
                         "000080070" +
                         "017000000" +
                         "000036040").solve();
    }
}

import java.util.Arrays;
 
public class EightQueens {
    private static int i;
    private static boolean q;
    private static boolean[] a = new boolean[9];
    private static boolean[] b = new boolean[17];
    private static boolean[] c = new boolean[15]; // offset by 7 relative to the Pascal version
    private static int[] x = new int[9];
 
    private static void try(int i) {
        for (int j = 1; ; j++) {
            q = false;
            if (a[j] && b[i+j] && c[i-j+7]) {
                x[i] = j;
                a[j] = false;
                b[i+j] = false;
                c[i-j+7] = false;
                if (i < 8) {
                    try(i + 1);
                    if (!q) {
                        a[j] = true;
                        b[i+j] = true;
                        c[i-j+7] = true;
                    }
                } else {
                    q = true;
                }
            }
            if (q || j == 8) {
                break;
            }
        }
    }
 
    public static void main(String[] args) {
        for (i = 1; i <= 8; i++) {
            a[i] = true;
        }
        for (i = 2; i <= 16; i++) {
            b[i] = true;
        }
        for (i = 0; i <= 14; i++) {
            c[i] = true;
        }
        try(1);
        if (q) {
            for (i = 1; i <= 8; i++) {
                System.out.println(i + " " + x[i]);
            }
        }
    }
}

import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
 
public class StemAndLeaf {
    private static int[] data = { 12, 127, 28, 42, 39, 113, 42, 18, 44, 118,
            44, 37, 113, 124, 37, 48, 127, 36, 29, 31, 125, 139, 131, 115, 105,
            132, 104, 123, 35, 113, 122, 42, 117, 119, 58, 109, 23, 105, 63,
            27, 44, 105, 99, 41, 128, 121, 116, 125, 32, 61, 37, 127, 29, 113,
            121, 58, 114, 126, 53, 114, 96, 25, 109, 7, 31, 141, 46, 13, 27,
            43, 117, 116, 27, 7, 68, 40, 31, 115, 124, 42, 128, 52, 71, 118,
            117, 38, 27, 106, 33, 117, 116, 111, 40, 119, 47, 105, 57, 122,
            109, 124, 115, 43, 120, 43, 27, 27, 18, 28, 48, 125, 107, 114, 34,
            133, 45, 120, 30, 127, 31, 116, 146 };
 
    public static Map<Integer, List<Integer>> createPlot(int... data){
        Map<Integer, List<Integer>> plot = new TreeMap<Integer, List<Integer>>();
        int highestStem = -1; //for filling in stems with no leaves
        for(int datum:data){
            int leaf = datum % 10;
            int stem = datum / 10; //integer division
            if(stem > highestStem){
                highestStem = stem;
            }
            if(plot.containsKey(stem)){
                plot.get(stem).add(leaf);
            }else{
                LinkedList<Integer> list = new LinkedList<Integer>();
                list.add(leaf);
                plot.put(stem, list);
            }
        }
        if(plot.keySet().size() < highestStem + 1 /*highest stem value and 0*/ ){
            for(int i = 0; i <= highestStem; i++){
                if(!plot.containsKey(i)){
                    LinkedList<Integer> list = new LinkedList<Integer>();
                    plot.put(i, list);
                }
            }
        }
        return plot;
    }
 
    public static void printPlot(Map<Integer, List<Integer>> plot){
        for(Map.Entry<Integer, List<Integer>> line : plot.entrySet()){
            Collections.sort(line.getValue());
            System.out.println(line.getKey() + " | " + line.getValue());
        }
    }
 
    public static void main(String[] args){
        Map<Integer, List<Integer>> plot = createPlot(data);
        printPlot(plot);
    }
}

