    // throw new UnsupportedOperationException("Waiting to be implemented.");
    // FC c = FC.withLinkPointer();
    List<Integer> ret = new ArrayList<>(grid[0].length);
    for (int j = 0; j < grid[0].length; j++) {
        ret.add(find(grid, 0, j));
    }
    return ret;
}

private int find(int[][] grid, int r, int j) {
    if (r >= grid.length) { return j; }
    int rtn = -1;
    if (grid[r][j] == -1 && (j - 1 < 0 || grid[r][j - 1] == 1)) { return rtn; }
    if (grid[r][j] == 1 && (j + 1 >= grid[0].length || grid[r][j + 1] == -1)) { return rtn; }
    if (grid[r][j] == 1) { rtn = find(grid, r + 1, j + 1); }
    if (grid[r][j] == -1) { rtn = find(grid, r + 1, j - 1); }
    return rtn;
}

