public class Adapters {

    static final TypeAdapter<Double> DOUBLE_ADAPTER = new TypeAdapter<Double>() {
        @Override
        public void write(JsonWriter out, Double value) throws IOException {
            if (value == null) {
                throw new JsonIOException("Null value found for Double type");
            }
            out.value(value);
        }

        @Override
        public Double read(JsonReader in) throws IOException {
            return in.nextDouble();
        }
    };

    static final TypeAdapter<Long> LONG_ADAPTER = new TypeAdapter<Long>() {
        @Override
        public void write(JsonWriter out, Long value) throws IOException {
            if (value == null) {
                throw new JsonIOException("Null value found for Long type");
            }
            out.value(value);
        }

        @Override
        public Long read(JsonReader in) throws IOException {
            return in.nextLong();
        }
    };

    static final TypeAdapter<Integer> INTEGER_ADAPTER = new TypeAdapter<Integer>() {
        @Override
        public void write(JsonWriter out, Integer value) throws IOException {
            if (value == null) {
                throw new JsonIOException("Null value found for Integer type");
            }
            out.value(value);
        }

        @Override
        public Integer read(JsonReader in) throws IOException {
            return in.nextInt();
        }
    };

    static final TypeAdapter<Boolean> BOOLEAN_ADAPTER = new TypeAdapter<Boolean>() {
        @Override
        public void write(JsonWriter out, Boolean value) throws IOException {
            if (value == null) {
                throw new JsonIOException("Null value found for Boolean type");
            }
            out.value(value);
        }

        @Override
        public Boolean read(JsonReader in) throws IOException {
            return in.nextBoolean();
        }
    };

    static final TypeAdapter<String> STRING_ADAPTER = new TypeAdapter<String>() {
