private void maybeUpdatePicker() {
    // Check if any subchannel states have changed since the last picker was created
    boolean statesChanged = false;
    for (Subchannel subchannel : subchannels) {
        if (subchannel.getState() != subchannel.getLastReportedState()) {
            statesChanged = true;
            break;
        }
    }

    // If states have changed, update the picker
    if (statesChanged) {
        updatePicker();
    }
}

private void updatePicker() {
    // Logic to create a new picker based on the current subchannel states
    // This could involve sorting, filtering, or any other logic based on the requirements
    List<Subchannel> activeSubchannels = new ArrayList<>();
    for (Subchannel subchannel : subchannels) {
        if (subchannel.getState() == SubchannelState.READY) {
            activeSubchannels.add(subchannel);
        }
    }

    // Create a new picker with the active subchannels
    Picker newPicker = new Picker(activeSubchannels);
    currentPicker = newPicker;

    // Update the last reported state of each subchannel
    for (Subchannel subchannel : subchannels) {
        subchannel.setLastReportedState(subchannel.getState());
    }
}

