public class AsyncServer extends IOReactorExecutor<DefaultListeningIOReactor> {

    public AsyncServer(final IOReactorConfig ioReactorConfig) {
        super(ioReactorConfig, null);
    }

    @Override
    DefaultListeningIOReactor createIOReactor(
            final IOEventHandlerFactory ioEventHandlerFactory,
            final IOReactorConfig ioReactorConfig,
            final ThreadFactory threadFactory,
            final Callback<IOSession> sessionShutdownCallback) throws IOException {
        return new DefaultListeningIOReactor(ioEventHandlerFactory, ioReactorConfig, threadFactory, threadFactory,
                LoggingIOSessionDecorator.INSTANCE, LoggingIOSessionListener.INSTANCE, sessionShutdownCallback);
    }

    public Future<ListenerEndpoint> listen(final InetSocketAddress address) {
        return reactor().listen(address, null);
    }

    public Set<ListenerEndpoint> getEndpoints() {
        return reactor().getEndpoints();
    }

}

import org.junit.Assert;
import com.alibaba.druid.sql.dialect.oracle.parser.OracleStatementParser;
import com.alibaba.druid.sql.dialect.oracle.visitor.OracleSchemaStatVisitor;
import com.alibaba.druid.sql.ast.statement.SQLStatement;
import com.alibaba.druid.sql.ast.statement.SQLInsertStatement;
import com.alibaba.druid.stat.TableStat;

import java.util.List;
import java.util.Map;

public class OracleInsertTest1 extends OracleTest {

    public void test_0() throws Exception {
        String sql = "INSERT INTO bonuses (employee_id, bonus_amount) " +
                     "SELECT employee_id, salary * 0.1 " +
                     "FROM employees " +
                     "WHERE department_id = 10 " +
                     "UNION ALL " +
                     "SELECT sales_rep_id, commission_pct * 5000 " +
                     "FROM orders";

        OracleStatementParser parser = new OracleStatementParser(sql);
        List<SQLStatement> statementList = parser.parseStatementList();
        SQLStatement stmt = statementList.get(0);

        OracleSchemaStatVisitor visitor = new OracleSchemaStatVisitor();
        stmt.accept(visitor);

        Map<TableStat.Name, TableStat> tableStats = visitor.getTables();

        Assert.assertEquals(2, tableStats.size());

        Assert.assertTrue(tableStats.containsKey(new TableStat.Name("employees")));
        Assert.assertTrue(tableStats.containsKey(new TableStat.Name("orders")));

        TableStat employeesStat = tableStats.get(new TableStat.Name("employees"));
        Assert.assertEquals(1, employeesStat.getColumns().size());
        Assert.assertTrue(employeesStat.getColumns().contains(new TableStat.Column("employees", "employee_id")));

        TableStat ordersStat = tableStats.get(new TableStat.Name("orders"));
        Assert.assertEquals(1, ordersStat.getColumns().size());
        Assert.assertTrue(ordersStat.getColumns().contains(new TableStat.Column("orders", "sales_rep_id")));

        Assert.assertTrue(stmt instanceof SQLInsertStatement);
        SQLInsertStatement insertStmt = (SQLInsertStatement) stmt;
        Assert.assertEquals(1, insertStmt.getColumns().size());
        Assert.assertEquals("employee_id", insertStmt.getColumns().get(0).getName());
    }
}

