import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class Foodbox {
  private List<Eatable> box;
 
  public Foodbox(Eatable... food) {
    if (Arrays.stream(food).anyMatch(f ->!f.canEat())) {
      throw new IllegalArgumentException("food must be eadible");
    }
    this.box = Arrays.stream(food).collect(Collectors.toList());
  }
}
 
interface Eatable {
  boolean canEat();
}
 
class Fruit implements Eatable {
  @Override
  public boolean canEat() {
    return true;
  }
}
 
class Apple extends Fruit {
}
 
class Product {
  public static void main(String[] args) {
    Foodbox foodbox = new Foodbox(new Fruit(), new Apple());
    System.out.println(foodbox);
 
    try {
      new Foodbox(new Apple(), "string can't eat");
    } catch (IllegalArgumentException e) {
      System.out.println(e.getMessage());
    }
  }
}

