import java.io.*;

public class JavaObjectOutput implements Closeable {
    private final ObjectOutputStream out;
    private boolean compactMode;

    public JavaObjectOutput(OutputStream outputStream) throws IOException {
        this.out = new ObjectOutputStream(outputStream);
        this.compactMode = false;
    }

    public JavaObjectOutput(OutputStream outputStream, boolean compactMode) throws IOException {
        this.out = new ObjectOutputStream(outputStream);
        this.compactMode = compactMode;
    }

    public void setCompactMode(boolean compactMode) {
        this.compactMode = compactMode;
    }

    public void writeBool(boolean value) throws IOException {
        out.writeBoolean(value);
    }

    public void writeByte(byte value) throws IOException {
        out.writeByte(value);
    }

    public void writeShort(short value) throws IOException {
        out.writeShort(value);
    }

    public void writeInt(int value) throws IOException {
        out.writeInt(value);
    }

    public void writeLong(long value) throws IOException {
        out.writeLong(value);
    }

    public void writeFloat(float value) throws IOException {
        out.writeFloat(value);
    }

    public void writeDouble(double value) throws IOException {
        out.writeDouble(value);
    }

    public void writeBytes(byte[] bytes) throws IOException {
        if (bytes == null) {
            out.writeInt(-1);
            return;
        }
        writeBytes(bytes, 0, bytes.length);
    }

    public void writeBytes(byte[] bytes, int offset, int length) throws IOException {
        if (bytes == null) {
            out.writeInt(-1);
            return;
        }
        out.writeInt(length);
        out.write(bytes, offset, length);
    }

    public void writeUTF8(String value) throws IOException {
        if (value == null) {
            out.writeInt(-1);
            return;
        }
        byte[] utf8Bytes = value.getBytes("UTF-8");
        out.writeInt(utf8Bytes.length);
        out.write(utf8Bytes);
    }

    public void writeObject(Serializable obj) throws IOException {
        if (obj == null) {
            out.writeBoolean(false);
            return;
        }

        out.writeBoolean(true);
        if (compactMode) {
            // Compact serialization strategy
            if (obj instanceof Number || obj instanceof Boolean || obj instanceof Character) {
                out.writeObject(obj.toString());
            } else {
                out.writeObject(obj);
            }
        } else {
            out.writeObject(obj);
        }
    }

private void stereotype(Options opt, Doc c, Align align) {
    for (Tag tag : c.tags("stereotype")) {
        String t[] = tokenize(tag.text());
        if (t.length != 1) {
        System.err.println("@stereotype expects one field: " + tag.text());
        continue;
        }
        tableLine(align, guilWrap(opt, t[0]));
    }
    }

