class ProductOfNumbers {

    private List<Integer> prod;

    public ProductOfNumbers() {
        prod = new ArrayList<>();
    }

    public void add(int num) {
        if (num == 0) {
            prod = new ArrayList<>();
        }
        else if (prod.size() == 0) {
            prod.add(num);
        }
        else {
            prod.add(prod.get(prod.size() - 1) * num);
        }
    }

    public int getProduct(int k) {
        if (prod.size() < k) return 0;
        int size = prod.size();
        return prod.get(size - 1) / (k == size ? 1 : prod.get(size - k - 1));
    }
}

