import javax.mail.internet.InternetAddress;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cache.CacheManager;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class SmtpConfig {

    @Value("${smtp.host}")
    private String smtpHost;
    @Value("${smtp.port}")
    private Integer smtpPort;
    @Value("${smtp.user}")
    private String smtpUser;
    @Value("${smtp.password}")
    private String smtpPwd;
    @Value("${mail.from.email}")
    private String fromEmail;
    @Value("${mail.from.name}")
    private String fromName;
    @Value("${mail.interceptor.activate}")
    private Boolean interceptAll;
    @Value("${mail.interceptor.email}")
    private String interceptEmail;
    @Value("${mail.interceptor.name}")
    private String interceptName;
    @Value("${mail.charset}")
    private String charset;
    @Value("${mail.exception.email}")
    private String emailException;

    @Value("${mail.cache.name}")
    private String mailCache;

    @Bean
    public SmtpServerData smtpServer() {
        return new SmtpServerData(smtpHost, smtpPort, smtpUser, smtpPwd);
    }

    @Bean
    public EmailService smtpService(CacheManager cacheManager) throws Exception {
        EmailService service = builder();
        return create(cacheManager,mailCache, service);

    }

    public EmailService create(CacheManager cacheManager,String cacheName, EmailService emailService)
    {
        if(cacheManager == null)
        {
            return  emailService;
        }

        return new CachingEmailSmtpService(cacheManager,cacheName,emailService);
    }

    public EmailService builder() throws Exception {
        SimpleSmtpService service = new SimpleSmtpService();
        service.setSmtpServerData(smtpServer());
        service.setFromAddress(new InternetAddress(fromEmail, fromName));
        service.setCharset(charset);

        if (interceptAll) {
            service.setTestAddress(new InternetAddress(interceptEmail, interceptName));
        }
        return service;
    }

    @Bean
    public InternetAddress exceptionAddress() throws Exception {
        return new InternetAddress(emailException);
    }
}

import org.junit.Assert;
import org.junit.Test;
import tachyon.util.io.PathUtils;

/**
 * Unit tests for the {@link UnderFileSystem} class.
 */
public class UnderFileSystemTest {

    private void parseTest(String path, String expectedUfs, String expectedPath) {
        Pair<String, String> result = UnderFileSystem.parse(path);

        if (expectedUfs == null) {
            Assert.assertNull(result);
        } else {
            Assert.assertNotNull(result);
            Assert.assertEquals(expectedUfs, result.getFirst());
            Assert.assertEquals(PathUtils.normalizePath(expectedPath, "/"),
                PathUtils.normalizePath(result.getSecond(), "/"));
        }
    }

    @Test
    public void parseTest() {
      parseTest("file:///path", "file:///", "/path");
      parseTest("file://localhost:19998/path", "file://localhost:19998/", "/path");
      parseTest("tachyon://localhost:19998/path", "tachyon://localhost:19998", "/path");
      parseTest("tachyon-ft://localhost:19998/path", "tachyon-ft://localhost:19998", "/path");
      parseTest("hdfs://localhost:19998/path", "hdfs://localhost:19998", "/path");
      parseTest("s3://localhost:19998/path", "s3://localhost:19998", "/path");
      parseTest("s3n://localhost:19998/path", "s3n://localhost:19998", "/path");
      parseTest("glusterfs://localhost:19998/path", "glusterfs://localhost:19998", "/path");
      parseTest("/path", null, "/path");
      parseTest("path", null, "/path");
      parseTest(":", null, "/:");
      parseTest(null,null,null);
    }
}

