import java.io.BufferedReader;

import java.io.BufferedWriter;

import java.io.IOException;

import java.io.InputStreamReader;

import java.io.OutputStreamWriter;

public class Finder {

    static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));

    static final int max = 3000;

    static final int inf = max;

    public static void main(String[] args) throws IOException {

        int t = Integer.parseInt(br.readLine());

        while (t-- > 0)

            bw.write(solve() + "\n");

        bw.flush();

        bw.close();

        br.close();

    }

    public static int solve() throws IOException {

        int i, j, n;

        n = Integer.parseInt(br.readLine());

        int[] a = new int[n + 1];

        int[][] dp = new int[n + 1][n + 1];

        String[] s = br.readLine().split(" ");

        for (i = 1; i <= n; i++)

            a[i] = Integer.parseInt(s[i - 1]);

        for (i = 2; i <= n; i++)

        {

            int cnt = 0;

            for (j = i; j <= n; j++)

                dp[i][j] = inf;

            for (j = i - 1; j >= 1; j--)

                if (j + a[j] >= i)

                    dp[i][j + a[j]] = Math.min(dp[i][j + a[j]], dp[j][i - 1] + cnt++);

            for (j = i + 1; j <= n; j++)

                dp[i][j] = Math.min(dp[i][j], dp[i][j - 1]);

        }

        return dp[n][n];

    }

}

class Finder {
    class Node{
        int start;
        int end;
        Node(int start, int end) {
            this.start = start;
            this.end = end;
        }

        public String toString() {
            return start + "-" + end;
        }
    }
    List<Node> list;
    public int maxPalindromes(String s, int k) {
        list = new ArrayList<>();

        for (int i = 0; i < s.length(); i++) {
            extendPalindrome(s, i, i, k);
            extendPalindrome(s, i, i + 1, k);
        }

        Collections.sort(list, (a, b) -> (a.end - b.end));
        int ans = 0;
        int end = -1;
        //System.out.println(list);
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i).start > end) {
                end = list.get(i).end;
                ans++;
            }
        }

        return ans;
    }

    private void extendPalindrome(String s, int left, int right, int k) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            if (right - left + 1 >= k) {
                list.add(new Node(left, right));
                break;
            }
            left--; right++;
        }
    }
}

