import com.intellij.lang.BracePair;
import com.intellij.lang.DefaultCustomizableBraceMatcher;
import com.intellij.psi.TokenType;
import com.intellij.psi.tree.IElementType;
import com.intellij.psi.tree.TokenSet;

public class BuildBraceMatcher extends DefaultCustomizableBraceMatcher {
    private static final BracePair[] PAIRS = {
            new BracePair(TokenType.LPAR, TokenType.RPAR, true),
            new BracePair(TokenType.LBRACKET, TokenType.RBRACKET, true),
            new BracePair(TokenType.LBRACE, TokenType.RBRACE, true)
    };

    private static final TokenSet BRACES_ALLOWED_BEFORE = TokenSet.create(
            TokenType.LITERAL_STRING,
            TokenType.IDENTIFIER,
            TokenType.KEYWORD
    );

    public BuildBraceMatcher() {
        super(PAIRS);
    }

    @Override
    public BracePair[] getPairs() {
        return PAIRS;
    }

    @Override
    public boolean isPairedBracesAllowedBeforeType(IElementType type) {
        return BRACES_ALLOWED_BEFORE.contains(type) || type == TokenType.WHITE_SPACE || type == TokenType.COMMENT;
    }

    @Override
    public int getCodeConstructStart(PsiFile file, int offset) {
        // Logic to determine the start of a code construct
        // For the sake of this example, assume we just return offset
        return offset;
    }

    public static void main(String[] args) {
        BuildBraceMatcher matcher = new BuildBraceMatcher();

        // Example usage of the matcher
        IElementType sampleType = TokenType.LITERAL_STRING;
        System.out.println("Is paired braces allowed: " + matcher.isPairedBracesAllowedBeforeType(sampleType));

        int codeConstructStart = matcher.getCodeConstructStart(null, 10);
        System.out.println("Code construct start: " + codeConstructStart);
    }
}

