        int res = 0;
        for (int i=0; i<n; i++) {
            HashSet<Integer> set = new HashSet<>();
            int uniqueSegmentCount = 0;
            for (int j=i; j<n; j++) {
                if (set.contains(nums[j])) {
                    // do nothing;
                } else if (set.contains(nums[j]-1) && set.contains(nums[j]+1)) {
                    uniqueSegmentCount -= 1;
                } else if (set.contains(nums[j]-1) && !set.contains(nums[j]+1)) {
                    // do nothing;
                } else if (!set.contains(nums[j]-1) && set.contains(nums[j]+1)) {
                    // do nothing;
                } else if (!set.contains(nums[j])) {
                    uniqueSegmentCount += 1;
                }

                set.add(nums[j]);

                res += uniqueSegmentCount - 1;
            }
        }

        return res;
    }
}

