class Validator {
    public int maxCoins(int[] piles) {
        Arrays.sort(piles);
        int n = piles.length / 3;
        int coins = 0;
        for (int i = piles.length - 2, j = 0; i > -1 && j < n; i -= 2, ++j) {
            coins += piles[i];
        }
        return coins;
    }
}

import java.sql.CallableStatement;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Time;
import java.time.LocalTime;
import java.time.ZoneId;

import org.apache.ibatis.type.BaseTypeHandler;
import org.apache.ibatis.type.JdbcType;
import org.apache.ibatis.type.MappedTypes;

@MappedTypes(LocalTime.class)
public class LocalTimeTypeHandler extends BaseTypeHandler<LocalTime> {

    @Override
    public void setNonNullParameter(
            PreparedStatement ps,
            int i,
            LocalTime parameter,
            JdbcType jdbcType
    ) throws SQLException {
        if (parameter == null) {
            ps.setTime(i, null);
        } else {
            Time time = Time.valueOf(parameter);
            ps.setTime(i, time);
        }
    }

    @Override
    public LocalTime getNullableResult(
            ResultSet rs,
            String columnName
    ) throws SQLException {
        Time sqlTime = rs.getTime(columnName);
        return convertToLocalTime(sqlTime);
    }

    @Override
    public LocalTime getNullableResult(
            ResultSet rs,
            int columnIndex
    ) throws SQLException {
        Time sqlTime = rs.getTime(columnIndex);
        return convertToLocalTime(sqlTime);
    }

    @Override
    public LocalTime getNullableResult(
            CallableStatement cs,
            int columnIndex
    ) throws SQLException {
        Time sqlTime = cs.getTime(columnIndex);
        return convertToLocalTime(sqlTime);
    }

    private LocalTime convertToLocalTime(Time sqlTime) {
        if (sqlTime == null) {
            return null;
        }

        return sqlTime.toLocalTime();
    }
}

public static String ST_ITOC(int[] values) {
