    public enum ReservationStatus {
        PENDING, ALLOCATED, REJECTED, COMPLETED
    }

    public Reservation(long userId, int numResources) {
        this(userId, numResources, 0, System.currentTimeMillis(), 0);
    }

    public Reservation(long userId, int numResources, int priority) {
        this(userId, numResources, priority, System.currentTimeMillis(), 0);
    }

    public Reservation(long userId, int numResources, int priority, long reqStartTime, long duration) {
        super(userId, numResources, duration);
        this.reservationId = UUID.randomUUID();
        this.reqStartTime = reqStartTime;
        this.rangeList = new RangeList();
        this.priority = priority;
        this.status = ReservationStatus.PENDING;
