        this.reqStartTime = reqStartTime;
    }

    public RangeList getResourceRanges() {
        return rangeList;
    }

    public void setResourceRanges(RangeList rangeList) {
        if (this.rangeList.isEmpty()) {
            this.rangeList = rangeList;
        }
    }

    public int getPriority() {
        return priority;
    }

