        Reservation that = (Reservation) o;
        return reqStartTime == that.reqStartTime &&
                priority == that.priority &&
                Objects.equals(reservationId, that.reservationId) &&
                Objects.equals(rangeList, that.rangeList) &&
                status == that.status;
    }

    @Override
    public int hashCode() {
        return Objects.hash(reservationId, reqStartTime, rangeList, priority, status);
    }

