public:
    int minCoins(vector<int> &coins, int target) {
        /*
        This algorithm works with integers 1 to 0,
        we simply need to minus the target and obtain the first occurence
        */
        sort(coins.begin(), coins.end()); // to make sure the highest number is first,
                                        // otherwise we will reach a timeout when use stack
        int result = 0;

        auto it = find(coins.begin(), coins.end(), 0);

        // Here find only works with binary search
        // Instead, I decided to use the divide & conquer method to find the first occurrence
        // of the target.
        if (target < coins[0]) return result;
        if (target > coins[it - coins.begin()]) return result + 1;

        if (target >= coins[it - coins.begin()]) {
            result = ++it;
        }
        else {
            // target must be between the chance numbers.

            auto f = lower(coins.begin(), coins.begin() + it - coins.begin(), target);
            auto b = upper(coins.begin() + it, coins.end(), target);

            result = 0;
            if (it < f) {
                result = ++it;
            } else {
                result = min(result, 1 + minCoins(coins, target - coins[b - coins.begin()] - 1));
            }

        }
        return result;
    }

    // split the array into two and find min value.
    int lower(vector<int> &v, vector<int> &v1, int target) {
        sort(v.begin(), v.end());
        vector<int>::iterator cur = upper(v.begin() + 1, v.end() - 1);
        if (target <= v[cur - v.begin() - 1]) {
            return 1 + find(v1.begin(), v1.end(), target - v[cur - v.begin() - 1]) + 1;
        }
        else {
            return 0;
        }
    }

    int upper(vector<int> &v, vector<int> &v1, int target) {
        sort(v.begin(), v.end());
        vector<int>::iterator i = lower(v1.begin(), v1.end(), target - v[v.begin() - 1]);
        i++;
        if (v[i - v.begin() - 1] = target)
            return i - 1; // use i - 1 to get the last number
        else
            return 0;
    }
};

