protected void addEquiJoinColumn( QueryContext context,
                                      PlanNode node,
                                      Column joinColumn ) {
        if (node.getSelectors().contains(joinColumn.selectorName())) {

            List<Column> columns = node.getPropertyAsList(Property.PROJECT_COLUMNS, Column.class);
            List<String> types = node.getPropertyAsList(Property.PROJECT_COLUMN_TYPES, String.class);
            if (columns != null && addIfMissing(context, joinColumn, columns, types)) {
                node.setProperty(Property.PROJECT_COLUMNS, columns);
                node.setProperty(Property.PROJECT_COLUMN_TYPES, types);
            }
        }

        for (PlanNode child : node) {
            addEquiJoinColumn(context, child, joinColumn);
        }
    }

public class MC {
    public static void main(String[] args) {
        System.out.println(getPi(10000));
        System.out.println(getPi(100000));
        System.out.println(getPi(1000000));
        System.out.println(getPi(10000000));
        System.out.println(getPi(100000000));
 
    }
    public static double getPi(int numThrows){
        int inCircle= 0;
        for(int i= 0;i < numThrows;i++){
            //a square with a side of length 2 centered at 0 has
            //x and y range of -1 to 1
            double randX= (Math.random() * 2) - 1;//range -1 to 1
            double randY= (Math.random() * 2) - 1;//range -1 to 1
            //distance from (0,0) = sqrt((x-0)^2+(y-0)^2)
            double dist= Math.sqrt(randX * randX + randY * randY);
            //^ or in Java 1.5+: double dist= Math.hypot(randX, randY);
            if(dist < 1){//circle with diameter of 2 has radius of 1
                inCircle++;
            }
        }
        return 4.0 * inCircle / numThrows;
    }
}

