public static ArrayList<String> getpowerset(int a[],int n,ArrayList<String> ps)
    {
        if(n<0)
        {
            return null;
        }
        if(n==0)
        {
            if(ps==null)
                ps=new ArrayList<String>();
            ps.add(" ");
            return ps;
        }
        ps=getpowerset(a, n-1, ps);
        ArrayList<String> tmp=new ArrayList<String>();
        for(String s:ps)
        {
            if(s.equals(" "))
                tmp.add(""+a[n-1]);
            else
                tmp.add(s+a[n-1]);
        }
        ps.addAll(tmp);
        return ps;
    }

private boolean getTableDefinition(Connection tbcon) throws SQLException {
    String query = "SELECT * FROM session_table";
    try (Statement stmt = tbcon.createStatement();
         ResultSet rs = stmt.executeQuery(query)) {
        ResultSetMetaData metaData = rs.getMetaData();
        int columnCount = metaData.getColumnCount();
        if (columnCount == 5) {
            for (int i = 1; i <= columnCount; i++) {
                String columnName = metaData.getColumnName(i);
                String columnType = metaData.getColumnTypeName(i);
                if (!checkColumn(columnName, columnType)) {
                    return false;
                }
            }
            return true;
        }
    }
    return false;
}

private boolean checkColumn(String columnName, String columnType) {
    // Define the expected column names and types
    Map<String, String> expectedColumns = new HashMap<>();
    expectedColumns.put("session_id", "VARCHAR");
    expectedColumns.put("user_id", "VARCHAR");
    expectedColumns.put("start_time", "TIMESTAMP");
    expectedColumns.put("end_time", "TIMESTAMP");
    expectedColumns.put("status", "VARCHAR");

    // Check if the column name and type match the expected ones
    String expectedType = expectedColumns.get(columnName);
    return expectedType != null && expectedType.equalsIgnoreCase(columnType);
}

import java.util.Random;
 
public static final Random gen = new Random();
 
// version for array of ints
public static void shuffle (int[] array) {
    int n = array.length;
    while (n > 1) {
        int k = gen.nextInt(n--); //decrements after using the value
        int temp = array[n];
        array[n] = array[k];
        array[k] = temp;
    }
}
// version for array of references
public static void shuffle (Object[] array) {
    int n = array.length;
    while (n > 1) {
        int k = gen.nextInt(n--); //decrements after using the value
        Object temp = array[n];
        array[n] = array[k];
        array[k] = temp;
    }
}

