import org.apache.jena.query.Query;
import org.apache.jena.query.QueryFactory;
import org.apache.jena.sparql.algebra.Algebra;
import org.apache.jena.sparql.algebra.Op;
import org.apache.jena.atlas.io.IndentedWriter;

public class SparqlQueryTestRunner implements Runnable {

    // Static counter to track number of tests executed.
    private static int testCount = 0;

    // Manifest entry containing test details.
    private ManifestEntry manifestEntry;

    // Constructor accepting a manifest entry.
    public SparqlQueryTestRunner(ManifestEntry entry) {
        this.manifestEntry = entry;
    }

    // The runnable interface implementation.
    @Override
    public void run() {
        try {
            // Step 1: Retrieve the query string from the manifest entry.
            String queryStr = manifestEntry.getQueryString();
            String baseURI = manifestEntry.getBaseURI();

            // Step 2: Parse the query using Jena ARQ.
            Query query = QueryFactory.create(queryStr, baseURI);

            // Step 3: Serialize the query to a formatted string.
            StringBuilder buffer = new StringBuilder();
            // Using IndentedWriter for a pretty formatting demonstration.
            IndentedWriter iw = new IndentedWriter(buffer);
            iw.println("# Serialized SPARQL Query:");
            iw.println(query.toString());
            iw.flush();

            // Step 4: Re-validate the query by parsing the serialized string.
            String serializedQuery = buffer.toString();
            Query parsedQuery = QueryFactory.create(serializedQuery, baseURI);

            // Step 5: Validate the query's algebra structure.
            Op op = Algebra.compile(parsedQuery);
            if (op == null) {
                throw new Exception("Algebra compilation returned null for test: " + manifestEntry.getTestName());
            }

            // Additional check: Ensure that the original query and the parsed query are equivalent.
            if (!query.toString().equals(parsedQuery.toString())) {
                throw new Exception("Mismatch between original and re-parsed query for test: " + manifestEntry.getTestName());
            }

            // Report successful test execution.
            System.out.println("Test '" + manifestEntry.getTestName() + "' passed.");
        } catch (Exception e) {
            // Detailed error reporting when test fails.
            System.err.println("Test '" + manifestEntry.getTestName() + "' failed: " + e.getMessage());
            e.printStackTrace();
        } finally {

import java.util.Scanner;

public class Service {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a list of characters in one line: ");
        String line = in.nextLine();
        char[] chars = line.toCharArray();

        System.out.println("Enter a single character: ");
        char ch = in.next().charAt(0);
        System.out.println("The character " + ch + " occurs " + count(chars, ch) + " times.");
        in.close();
    }

    public static int count(char[] chars, char ch) {
        return count(chars, ch, chars.length - 1);
    }

    public static int count(char[] chars, char ch, int high) {
        if (high > 0) {
            return chars[high] == ch ? (1 + count(chars, ch, high - 1)) : (count(chars, ch, high - 1));
        } else {
            return 0;
        }
    }
}

