/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode(int x) { val = x; }
 * }
 */
class Order {
    public int getDecimalValue(ListNode head) {
        int cur = 0;
        while (head != null) {
            cur = cur * 2 + head.val;
            head = head.next;
        }
        return cur;
    }
}

@SuppressWarnings("unchecked")
    private void displaySlide(final Slide slide, final boolean isReverse) {
        synchronized (this) {
            try {
                LOGGER.trace("Display slide N°" + slide.getPage() + " reverse=" + isReverse);
                SlideModel<SlideStep> previousSlideModel = null;
                if (this.selectedSlide != null) {
                    final Class<Model> previousClass = (Class<Model>) (this.selectedSlide.getModelClass() == null
                            ? Class.forName(getPresentationService().getPresentation().getSlides().getDefaultModelClass())
                            : Class.forName(this.selectedSlide.getModelClass()));
                    previousSlideModel = (SlideModel<SlideStep>) getModel(previousClass, this.selectedSlide);
                }

                final Class<Model> nextClass = (Class<Model>) (slide.getModelClass() == null
                        ? Class.forName(getPresentationService().getPresentation().getSlides().getDefaultModelClass())
                        : Class.forName(slide.getModelClass()));
                this.selectedSlideModel = (SlideModel<SlideStep>) getModel(nextClass, slide);

                if (!view().node().getChildren().contains(this.selectedSlideModel.node())) {
                    view().node().getChildren().add(this.selectedSlideModel.node());
                }

                this.slideAnimation = buildSlideTransition(isReverse, previousSlideModel, this.selectedSlideModel);
                this.selectedSlideModel.setCurrentFlow(isReverse ? SlideFlow.backward : SlideFlow.forward);
                if (isReverse) {
                    this.slideAnimation.setRate(-1);
                    this.slideAnimation.playFrom(this.slideAnimation.getCycleDuration());
                } else {
                    this.slideAnimation.setRate(1);
                    this.slideAnimation.playFromStart();
                }

                this.selectedSlide = slide;

            } catch (final ClassNotFoundException e) {
                LOGGER.error("Error while loading a slide", e);
            }
        }
    }

import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.scene.text.Text;
import javafx.stage.Stage;

import java.util.Random;

public class TwoCircles extends Application {

    private static final int CIRCLE_RADIUS = 15;

    @Override
    public void start(Stage primaryStage) {

        // Create two random points
        Random rand = new Random();
        int x1 = rand.nextInt(400);
        int y1 = rand.nextInt(400);
        int x2 = rand.nextInt(400);
        int y2 = rand.nextInt(400);

        // Calculate the distance between the points
        double distance = Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));

        // Create the circles
        Circle circle1 = new Circle(x1, y1, CIRCLE_RADIUS);
        circle1.setFill(javafx.scene.paint.Color.BLUE);
        Circle circle2 = new Circle(x2, y2, CIRCLE_RADIUS);
        circle2.setFill(javafx.scene.paint.Color.GREEN);

        // Create the line
        Line line = new Line(x1, y1, x2, y2);
        line.setStroke(javafx.scene.paint.Color.RED);

        // Create the distance text
        Text text = new Text((x1 + x2) / 2, (y1 + y2) / 2, String.format("%.2f", distance));
        text.setStroke(javafx.scene.paint.Color.BLACK);
        text.setStyle("-fx-font-size: 14px;");

        // Create a group to hold the shapes
        Group group = new Group(circle1, circle2, line, text);

        // Create a scene and add the group to it
        Scene scene = new Scene(group, 400, 400);

        // Set the stage title and scene, and show the stage
        primaryStage.setTitle("Two Circles and Their Distance");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.io.File;

public class FileRenamer {
    public static void main(String[] args) {
        String directoryPath = "/path/to/directory/"; // Replace with the path to your directory
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();
        for (File file : files) {
            if (file.isFile() && file.getName().matches("Exercise\\d_\\d")) {
                String oldName = file.getName();
                String[] parts = oldName.split("_");
                String newName = String.format("Exercise%02d_%02d", Integer.parseInt(parts[0].substring(8)), Integer.parseInt(parts[1]));
                File newFile = new File(directoryPath + newName);
                if (file.renameTo(newFile)) {
                    System.out.println("Renamed " + oldName + " to " + newName);
                } else {
                    System.err.println("Error renaming " + oldName);
                }
            }
        }
    }
}

