private void handleConnectionProperties(URLConnection conn) {
    // Set the request method to GET
    conn.setRequestMethod("GET");
    // Set the content type to application/json
    conn.setRequestProperty("Content-Type", "application/json");
    // Set the accept header to application/json
    conn.setRequestProperty("Accept", "application/json");
    // Set the user agent to a custom value
    conn.setRequestProperty("User-Agent", "MyCustomUserAgent");
    // Set the connection timeout to 10 seconds
    conn.setConnectTimeout(10000);
    // Set the read timeout to 10 seconds
    conn.setReadTimeout(10000);
}

