public class FontPropertyEditor extends AbstractPropertyEditor implements ActionListener {

    private JLabel label;
    private JButton button;
    private Font font;
    private static final ResourceManager RESOURCE = ResourceManager.get(FontPropertyEditor.class);

    public FontPropertyEditor() {
        editor = new JPanel(new PercentLayout(PercentLayout.HORIZONTAL, 0));
        ((JPanel) editor).add("*", label = new DefaultCellRenderer());
        label.setOpaque(false);
        ((JPanel) editor).add(button = ComponentFactory.Helper.getFactory().createMiniButton());
        button.addActionListener(this);
        selectNull();
    }

    public Object getValue() {
        return font;
    }

    public void setValue(Object value) {
        Font oldFont = font;
        font = (Font) value;
        firePropertyChange(oldFont, font);
        updateLabel();
    }

    public void actionPerformed(ActionEvent e) {
        if (e.getSource() == button) {
            if (RESOURCE.getString("FontPropertyEditor.clearFont.text").equals(button.getText())) {
                selectNull();
            } else {
                selectFont();
            }
        }
    }

    protected void selectFont() {
        Font selectedFont = JFontChooser.showDialog(editor, RESOURCE.getString("FontPropertyEditor.title"), font);

        if (selectedFont != null) {
            setValue(selectedFont);
        }
    }

    protected void selectNull() {
        setValue(null);
        button.setText(RESOURCE.getString("FontPropertyEditor.selectFont.text"));
        button.setToolTipText(RESOURCE.getString("FontPropertyEditor.selectFont.tooltip"));
    }

    private void updateLabel() {
        if (font == null) {
            label.setText(RESOURCE.getString("FontPropertyEditor.nullFontLabel.text"));
        } else {
            label.setText(font.getFontName() + " " + font.getSize());
            label.setFont(font.deriveFont(font.getStyle() | Font.BOLD));
        }
        button.setText(RESOURCE.getString("FontPropertyEditor.clearFont.text"));

