public class Deranged {
 
    public static boolean deranged(String a, String b) {
        if (a.length()!= b.length()) {
            return false;
        }
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) == b.charAt(i)) {
                return false;
            }
        }
        return true;
    }
 
    public static void main(String[] args) throws IOException {
        /* read the whole thing in. how big can it be? */
        BufferedReader br = new BufferedReader(new FileReader("unixdict.txt"));
        List<String> words = new ArrayList<String>();
        String line;
        while ((line = br.readLine())!= null) {
            words.add(line);
        }
        br.close();
 
        Map<String, List<String>> m = new HashMap<String, List<String>>();
        int best_len = 0;
        String w1 = "", w2 = "";
 
        for (String w : words) {
            // don't bother: too short to beat current record
            if (w.length() <= best_len) {
                continue;
            }
 
            // save strings in map, with sorted string as key
            char[] letters = w.toCharArray();
            Arrays.sort(letters);
            String k = new String(letters);
 
            if (!m.containsKey(k)) {
                m.put(k, new ArrayList<String>());
            }
            m.get(k).add(w);
 
            for (String c : m.get(k)) {
                if (deranged(w, c)) {
                    best_len = w.length();
                    w1 = c;
                    w2 = w;
                    break;
                }
            }
        }
 
        System.out.println(w1 + " " + w2 + " : Length " + best_len);
    }
}

