/**
 * AbstractDatabaseConverter is assumed to be part of the local project framework.
 * It provides the general structure for database schema conversions.
 */
public abstract class AbstractDatabaseConverter {
    protected VersionControl versionControl;

    public AbstractDatabaseConverter(VersionControl versionControl) {
        this.versionControl = versionControl;
    }

    public abstract JsonObject convertEntry(JsonObject entry) throws DatabaseConversionException;
}

/**
 * VersionControl is a placeholder for a version management utility.
 */
class VersionControl {
    // Implementation details are omitted.
}

/**
 * DatabaseConversionException is thrown when there is an error during
 * the conversion of a database entry.
 */
class DatabaseConversionException extends Exception {
    public DatabaseConversionException(String message) {
        super(message);
    }
}

/**
 * DatabaseEntryConverter upgrades outdated JSON database entries.
 * It relocates specific fields to align with the new database schema.
 */
public class DatabaseEntryConverter extends AbstractDatabaseConverter {

    private static final String SERVICE_CONFIG = "serviceConfig";
    private static final String TEMPLATE_FIELD = "template";
    private static final String SERVICE_DESCRIPTION_FIELD = "serviceDescription";

    public DatabaseEntryConverter(VersionControl versionControl) {
        super(versionControl);
    }

    /**
     * Converts the obsolete JSON representation of a database entry into the new format.
     * It identifies the service configuration data and, for each element, relocates the
     * template field to a new field called serviceDescription.
     *
     * @param entry the original JSON object representing a database entry
     * @return the updated JsonObject with the new schema applied
     * @throws DatabaseConversionException if the conversion fails due to schema issues
     */
    @Override
    public JsonObject convertEntry(JsonObject entry) throws DatabaseConversionException {
        if (entry == null) {
            throw new DatabaseConversionException("Input JSON entry is null.");
        }

        if (entry.has(SERVICE_CONFIG)) {
            JsonElement serviceConfigElement = entry.get(SERVICE_CONFIG);
            if (!serviceConfigElement.isJsonArray()) {
                throw new DatabaseConversionException("Service configuration is not an array.");
            }

