import java.util.ArrayList;
import java.util.Scanner;

public class Sorter {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a sequence of numbers ending with a 0: ");

        ArrayList<Integer> list = new ArrayList<>();
        Integer integer;
        while ((integer = in.nextInt()) != 0) {
            list.add(integer);
        }

        System.out.println("The largest number is " + max(list));
        in.close();
    }

    public static Integer max(ArrayList<Integer> list) {
        if (list == null || list.isEmpty()) {
            return null;
        }
        Integer max = list.get(0);
        for (Integer integer : list) {
            max = Math.max(max, integer);
        }
        return max;
    }

}

public int minCostToSupplyWater(int n, int[] wells, int[][] pipes) {
        // Create a Union-Find data structure to handle connected components
        UnionFind uf = new UnionFind(n + 1);

        // Initialize an empty list to store all edges (both wells and pipes) with their costs
        List<int[]> edges = new ArrayList<>();

        // Create an edge for each well, connecting the well to a dummy node at index 0
        // The cost is the well's cost
        for (int i = 0; i < wells.length; i++) {
            edges.add(new int[]{0, i + 1, wells[i]});
        }

        // Create an edge for each pipe, with the same format (from, to, cost)
        for (int[] pipe : pipes) {
            edges.add(pipe);
        }

        // Sort the edges by their cost in ascending order
        edges.sort((a, b) -> a[2] - b[2]);

        // Initialize the total cost to 0
        int totalCost = 0;

        // Process each edge in order
        for (int[] edge : edges) {
            int from = edge[0];
            int to = edge[1];
            int cost = edge[2];

            // If the two nodes in the edge are not connected, connect them and add the cost to the total
            if (uf.union(from, to)) {
                totalCost += cost;
            }
        }

        // Return the total cost of connecting all nodes
        return totalCost;
    }

    private static class UnionFind {
        private int[] parent;
        private int[] rank;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
            rank = new int[n];
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

