/**
 * Interface for managing a .newsrc configuration file.
 * This file is used by newsreading applications to keep track of
 * subscribed newsgroups and read articles.
 */
public interface Newsrc {

    /**
     * Lists all subscribed newsgroups.
     *
     * @return An iterator over the names of all subscribed newsgroups.
     */
    Iterator<String> list();

    /**
     * Checks if a newsgroup is currently subscribed.
     *
     * @param newsgroup The name of the newsgroup to check.
     * @return true if the newsgroup is subscribed, false otherwise.
     */
    boolean isSubscribed(String newsgroup);

    /**
     * Sets the subscription status of a newsgroup.
     *
     * @param newsgroup The name of the newsgroup to update.
     * @param subs      true to subscribe, false to unsubscribe.
     */
    void setSubscribed(String newsgroup, boolean subs);

    /**
     * Checks if an article in a newsgroup has been seen.
     *
     * @param newsgroup The name of the newsgroup.
     * @param article   The article number to check.
     * @return true if the article has been seen, false otherwise.
     */
    boolean isSeen(String newsgroup, int article);

    /**
     * Sets the seen status of an article in a newsgroup.
     *
     * @param newsgroup The name of the newsgroup.
     * @param article   The article number to update.
     * @param seen      true if the article has been seen, false otherwise.
     */
    void setSeen(String newsgroup, int article, boolean seen);

    /**
     * Closes the .newsrc configuration, potentially saving any changes.
     */
    void close();
}

class Tuple2Serializer<T1, T2> implements Serializer<Tuple2<T1, T2>> {
    private final Serializer<T1> firstSerializer;
    private final Serializer<T2> secondSerializer;

    public Tuple2Serializer(Serializer<T1> firstSerializer, Serializer<T2> secondSerializer) {
        this.firstSerializer = firstSerializer;
        this.secondSerializer = secondSerializer;
    }

    @Override
    public byte[] serialize(Tuple2<T1, T2> tuple) {
        byte[] firstBytes = firstSerializer.serialize(tuple.getFirst());
        byte[] secondBytes = secondSerializer.serialize(tuple.getSecond());
        byte[] result = new byte[firstBytes.length + secondBytes.length];
        System.arraycopy(firstBytes, 0, result, 0, firstBytes.length);
        System.arraycopy(secondBytes, 0, result, firstBytes.length, secondBytes.length);
        return result;
    }

    @Override
    public Tuple2<T1, T2> deserialize(byte[] bytes) {
        int firstLength = firstSerializer.deserializeLength(bytes);
        byte[] firstBytes = Arrays.copyOfRange(bytes, 0, firstLength);
        byte[] secondBytes = Arrays.copyOfRange(bytes, firstLength, bytes.length);
        T1 first = firstSerializer.deserialize(firstBytes);
        T2 second = secondSerializer.deserialize(secondBytes);
        return new Tuple2<>(first, second);
    }

    @Override
    public int deserializeLength(byte[] bytes) {
        return firstSerializer.deserializeLength(bytes) + secondSerializer.deserializeLength(bytes);
    }
}

class Tuple2<T1, T2> {
    private final T1 first;
    private final T2 second;

    public Tuple2(T1 first, T2 second) {
        this.first = first;
        this.second = second;
    }

    public T1 getFirst() {
        return first;
    }

    public T2 getSecond() {
        return second;
    }
}

