import java.util.ArrayList;
import java.util.List;

class State {
    private List<VendorInfo> vendorInfoList;

    public State() {
        this.vendorInfoList = new ArrayList<>();
    }

    public List<VendorInfo> getVendorInfoList() {
        return vendorInfoList;
    }

    public void addVendorInfo(VendorInfo vendorInfo) {
        vendorInfoList.add(vendorInfo);
    }
}

class VendorInfo {
    private String name;
    private String address;
    private String contact;

    public VendorInfo(String name, String address, String contact) {
        this.name = name;
        this.address = address;
        this.contact = contact;
    }

    @Override
    public String toString() {
        return "VendorInfo{" +
                "name='" + name + '\'' +
                ", address='" + address + '\'' +
                ", contact='" + contact + '\'' +
                '}';
    }
}

class VendorInfoBuilder {

    public String getSectionName() {
        return "Vendor Section";
    }

    public void build(State state, String[] lines) {
        if (lines.length < 3) {
            throw new IllegalArgumentException("Insufficient input lines. At least 3 lines are required.");
        }

        String name = lines[0].trim();
        String address = lines[1].trim();
        String contact = lines[2].trim();

        VendorInfo vendorInfo = new VendorInfo(name, address, contact);
        state.addVendorInfo(vendorInfo);
    }

    public static void main(String[] args) {
        State state = new State();
        VendorInfoBuilder builder = new VendorInfoBuilder();

        String[] inputLines = {
            "Vendor Name",
            "123 Vendor St, Vendor City",
            "555-1234"
        };

        System.out.println("Section Name: " + builder.getSectionName());

        try {
            builder.build(state, inputLines);
            System.out.println("Vendor Info added successfully.");
        } catch (IllegalArgumentException e) {
            System.err.println("Error: " + e.getMessage());
        }

        for (VendorInfo info : state.getVendorInfoList()) {
            System.out.println(info);
        }
    }
}

