import java.util.Scanner;
 
public class Calculator {
 
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String values[][] = new String[3][100];
    String tempStr = new String();
    int i,j,isString=0;
    double val[] = new double[3];
    double temp;
 
    for(i=0;i<3;i++){
      System.out.print("Enter "+(i+1)+(i==0?"st":((i==1)?"nd":"rd"))+" value : ");
      values[i] = sc.nextLine();
 
      for(j=0;values[i].charAt(j)!=00;j++){
        if(((values[i].charAt(j)<'0' || values[i].charAt(j)>'9') && (values[i].charAt(j)!='.' ||values[i].charAt(j)!='-'||values[i].charAt(j)!='+'))
        ||((values[i].charAt(j)=='.' ||values[i].charAt(j)=='-'||values[i].charAt(j)=='+')&&(values[i].charAt(j+1)<'0' || values[i].charAt(j+1)>'9')))
          isString = 1;
      }
    }
 
    if(isString==0){
      for(i=0;i<3;i++)
        val[i] = Double.parseDouble(values[i]);
    }
 
    for(i=0;i<3-1;i++){
      for(j=i+1;j<3;j++){
        if(isString==0 && val[i]>val[j]){
          temp = val[j];
          val[j] = val[i];
          val[i] = temp;
        }
 
        else if(values[i].charAt(0)>values[j].charAt(0)){
          tempStr = values[j];
          values[j] = values[i];
          values[i] = tempStr;
        }
      }
    }
 
    for(i=0;i<3;i++)
      isString==1?System.out.println('X'+i+" = "+values[i]):System.out.println('X'+i+" = "+val[i]);
  }
}

