import java.beans.*;
import java.net.*;
import java.util.*;

public class IpWatch implements Runnable {
    private String currentIp = "";
    private final long wait;
    private volatile boolean running = false;
    private final PropertyChangeSupport support = new PropertyChangeSupport(this);
    private Thread thread;

    public IpWatch(int intervalSeconds) {
        this.wait = intervalSeconds * 1000L;
    }

    public void addPropertyChangeListener(PropertyChangeListener listener) {
        support.addPropertyChangeListener(listener);
    }

    public void start() {
        if (!running) {
            running = true;
            thread = new Thread(this);
            thread.start();
        }
    }

    public void stop() {
        running = false;
        if (thread != null) {
            thread.interrupt();
        }
    }

    private String findIp() {
        List<String> ips = new ArrayList<>();
        try {
            Enumeration<NetworkInterface> interfaces = NetworkInterface.getNetworkInterfaces();
            while (interfaces.hasMoreElements()) {
                NetworkInterface iface = interfaces.nextElement();
                Enumeration<InetAddress> addresses = iface.getInetAddresses();
                while (addresses.hasMoreElements()) {
                    InetAddress addr = addresses.nextElement();
                    if (!addr.isLoopbackAddress()) {
                        ips.add(addr.getHostAddress());
                    }
                }
            }
        } catch (SocketException ignored) {
            return "";
        }
        Collections.sort(ips);
        return String.join(", ", ips);
    }

    @Override
    public void run() {
        currentIp = findIp();
        while (running) {
            String newIp = findIp();
            if (!newIp.equals(currentIp)) {
                support.firePropertyChange("ip", currentIp, newIp);
                currentIp = newIp;
            }
            try {
                Thread.sleep(wait);
            } catch (InterruptedException e) {
                running = false;
                Thread.currentThread().interrupt();
            }
        }
    }

    public static void main(String[] args) throws InterruptedException {
        IpWatch watcher = new IpWatch(2);
        watcher.addPropertyChangeListener(evt -> {
            System.out.println("IP changed from " + evt.getOldValue() + " to " + evt.getNewValue());
        });
        watcher.start();
        Thread.sleep(60000);
        watcher.stop();
    }
}

import java.util.*;

public class Manager

{

    public static void main(String[] args) {

        Scanner sc=new Scanner(System.in);

        int t=sc.nextInt();

        while(t>0){

            t--;

           int n=sc.nextInt();

           int[] arr=new int[n];

           for(int i=0;i<n;i++){

               arr[i]=sc.nextInt();

           }

           Arrays.sort(arr);

           int count=1;

           int temp=-1;

           int vari=0;

           for(int i=0;i<n;i++){

               vari+=1;

               temp=Math.max(temp,arr[i]);

               if(temp<=count+vari-1){

                   count+=vari;

                   vari=0;

               }

           }

           System.out.println(count);

        }

    }

}

public boolean isProcessed(Trace trace, Node node, Direction direction) {
        boolean ret = false;
        if (trace.getTransaction() != null) {
            List<ProcessorWrapper> procs = null;
            synchronized (processors) {
                procs = processors.get(trace.getTransaction());
            }
            if (procs != null) {
                for (int i = 0; !ret && i < procs.size(); i++) {
                    ret = procs.get(i).isProcessed(trace, node, direction);
                }
            }
        }
        if (log.isLoggable(Level.FINEST)) {
            log.finest("ProcessManager: isProcessed trace=" + trace + " node=" + node
                    + " direction=" + direction + "? " + ret);
        }
        return ret;
    }

