import java.util.*;

public class CsvMarshalTest extends CamelTestSupport {

    @Test
    public void testCsvMarshal() throws Exception {
        MockEndpoint mock = getMockEndpoint("mock:result");
        mock.expectedMessageCount(1);

        List<Map<String, Object>> data = new ArrayList<>();
        Map<String, Object> row1 = new LinkedHashMap<>();
        row1.put("name", "John");
        row1.put("age", 30);
        row1.put("city", "New York");
        data.add(row1);

        Map<String, Object> row2 = new LinkedHashMap<>();
        row2.put("name", "Jane");
        row2.put("age", 25);
        row2.put("city", "Los Angeles");
        data.add(row2);

        template.sendBody("direct:start", data);

        assertMockEndpointsSatisfied();

        String body = mock.getReceivedExchanges().get(0).getIn().getBody(String.class);
        String[] lines = body.split("\\r?\\n");

        assertEquals("John,30,New York", lines[0]);
        assertEquals("Jane,25,Los Angeles", lines[1]);
    }

    @Override
    protected RouteBuilder createRouteBuilder() throws Exception {
        return new RouteBuilder() {
            @Override
            public void configure() throws Exception {
                from("direct:start")
                        .marshal().csv()
                        .convertBodyTo(String.class)
                        .to("mock:result");
            }
        };
    }
}

