public void sendDecryptedData(Event event) throws InterruptedException, SSLException, ExecutionException {
    // Do decryption on event data.
    byte[] decryptedData = decrypt(event.getData());

    // Send decrypted data through the engine.
    byte[] encryptedData = engine.encrypt(decryptedData);

    // Send encrypted data upstream.
    upstream.send(encryptedData);
}

