public class AuthorityConsumer {

    private static final Logger log = Logger.getLogger(AuthorityConsumer.class);

    private final Set<String> itemsToUpdateAuthority = new HashSet<>();
    private final Set<String> itemsToReindex = new HashSet<>();

    public void initialize() {
        log.info("AuthorityConsumer initialized.");
    }

    public void consume(Context ctx, Event event) {
        try {
            if (event.getEventType() == Event.EventType.ITEM_ARCHIVED) {
                Item item = (Item) event.getObject();
                String itemId = item.getID().toString();

                itemsToReindex.add(itemId);
                log.info("Item archived, added to reindex: " + itemId);

                if (requiresAuthorityUpdate(item)) {
                    itemsToUpdateAuthority.add(itemId);
                    log.info("Authority update required, added to authority update list: " + itemId);
                }
            }
        } catch (Exception e) {
            log.error("Error while processing event: " + event, e);
        }
    }

    public void end(Context ctx) {
        log.info("Ending AuthorityConsumer processing.");
        turnOffAuthorizationChecks();

        if (!itemsToUpdateAuthority.isEmpty()) {
            processAuthorityUpdates();
        }

        if (!itemsToReindex.isEmpty()) {
            performReindexing();
        }

        clearAllCollections();
        log.info("Processing completed.");
    }

    private void turnOffAuthorizationChecks() {
        log.info("Authorization checks turned off.");
        // Logic to turn off authorization checks
    }

    private void processAuthorityUpdates() {
        try {
            for (String itemId : itemsToUpdateAuthority) {
                // Perform authority update logic
                log.info("Updating authority for item ID: " + itemId);
            }
        } catch (Exception e) {
            log.error("Error while updating authority for items.", e);
        }
    }

    private void performReindexing() {
        try {
            for (String itemId : itemsToReindex) {
                // Perform reindexing logic
                log.info("Reindexing item ID: " + itemId);
            }
        } catch (Exception e) {
            log.error("Error while reindexing items.", e);
        }
    }

    private void clearAllCollections() {
        itemsToUpdateAuthority.clear();

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
 
public class FermatNumbers {
 
    public static void main(String[] args) {
        System.out.println("First 10 Fermat numbers:");
        for ( int i = 0 ; i < 10 ; i++ ) {
            System.out.printf("F[%d] = %s\n", i, fermat(i));
        }
        System.out.printf("%nFirst 12 Fermat numbers factored:%n");
        for ( int i = 0 ; i < 13 ; i++ ) {
            System.out.printf("F[%d] = %s\n", i, getString(getFactors(i, fermat(i))));
        }
    }
 
    private static String getString(List<BigInteger> factors) {
        if ( factors.size() == 1 ) {
            return factors.get(0) + " (PRIME)";
        }
        return factors.stream().map(v -> v.toString()).map(v -> v.startsWith("-") ? "(C" + v.replace("-", "") + ")" : v).collect(Collectors.joining(" * "));
    }
 
    private static Map<Integer, String> COMPOSITE = new HashMap<>();
    static {
        COMPOSITE.put(9, "5529");
        COMPOSITE.put(10, "6078");
        COMPOSITE.put(11, "1037");
        COMPOSITE.put(12, "5488");
        COMPOSITE.put(13, "2884");
    }
 
    private static List<BigInteger> getFactors(int fermatIndex, BigInteger n) {
        List<BigInteger> factors = new ArrayList<>();
        BigInteger factor = BigInteger.ONE;
        while ( true ) {
            if ( n.isProbablePrime(100) ) {
                factors.add(n);
                break;
            }
            else {
                if ( COMPOSITE.containsKey(fermatIndex) ) {
                    String stop = COMPOSITE.get(fermatIndex);
                    if ( n.toString().startsWith(stop) ) {
                        factors.add(new BigInteger("-" + n.toString().length()));
                        break;
                    }
                }
                factor = pollardRhoFast(n);
                if ( factor.compareTo(BigInteger.ZERO) == 0 ) {
                    factors.add(n);
                    break;
                }
                else {
                    factors.add(factor);
                    n = n.divide(factor);
                }
            }
        }
        return factors;
    }
 
    private static final BigInteger TWO = BigInteger.valueOf(2);
 
    private static BigInteger fermat(int n) {
        return TWO.pow((int)Math.pow(2, n)).add(BigInteger.ONE);
    }
 
    //  See:  https://en.wikipedia.org/wiki/Pollard%27s_rho_algorithm
    @SuppressWarnings("unused")
    private static BigInteger pollardRho(BigInteger n) {

protected static final <T, K extends Serializable>
    K _key2Id(
                    final Key<T> key
                    )
    {
        K  id = null;
        try {
            @SuppressWarnings( "unchecked" )
            K  obj = (K)key.getId();
