public static Properties extractSubset(final Properties properties, final String prefix) {
        final Properties subset = new Properties();
        if (prefix == null || prefix.length() == 0) {
            return subset;
        }
        final String prefixToMatch = prefix.charAt(prefix.length() - 1) != '.' ? prefix + '.' : prefix;
        final List<String> keys = new ArrayList<>();
        for (final String key : properties.stringPropertyNames()) {
            if (key.startsWith(prefixToMatch)) {
                subset.setProperty(key.substring(prefixToMatch.length()), properties.getProperty(key));
                keys.add(key);
            }
        }
        for (final String key : keys) {
            properties.remove(key);
        }
        return subset;
    }

 
public class Animal {
    private final String name;
    private int age;
 
    public Animal(String name, int age) {
        this.name = name;
        this.age = age;
    }
 
    public Animal copy() {
        return new Animal(name, age);
    }
 
    public String toString() {
        return "Name: " + name + ", Age: " + age;
    }
 
    public final String getName() {
        return name;
    }
 
    public final int getAge() {
        return age;
    }
 
    public final void setAge(int age) {
        this.age = age;
    }
}
 
public class Dog extends Animal {
    private final String breed;
 
    public Dog(String name, int age, String breed) {
        super(name, age);
        this.breed = breed;
    }
 
    @Override
    public Dog copy() {
        return new Dog(getName(), getAge(), breed);
    }
 
    @Override
    public String toString() {
        return super.toString() + ", Breed: " + breed;
    }
 
    public final String getBreed() {
        return breed;
    }
}
 
public class Generator {
    public static void main(String[] args) {
        Animal a = new Dog("Rover", 3, "Terrier");
        Animal b = a.copy();  // calls Dog.copy() because runtime type of 'a' is Dog
        System.out.println("Dog 'a' = " + a);   // implicitly calls Dog.toString()
        System.out.println("Dog 'b' = " + b);   // ditto
        System.out.println("Dog 'a' is " + (a == b? "" : "not") + " the same object as Dog 'b'");
    }
}

