import org.glassfish.jersey.test.JerseyTest;
import org.junit.Test;
import static org.assertj.core.api.Assertions.assertThat;

public class ErrorEntityWriterTest extends JerseyTest {

    @Override
    protected Application configure() {
        return new ErrorEntityWriterTestResourceConfig();
    }

    @Test
    public void formatsErrorsAsHtml() {
        Response response = target("/trigger-error").request().get();

        assertThat(response.getStatus()).isEqualTo(Status.INTERNAL_SERVER_ERROR.getStatusCode());
        assertThat(response.getMediaType()).isEqualTo(MediaType.TEXT_HTML_TYPE);

        String output = response.readEntity(String.class);
        assertThat(output).contains("<html>");
        assertThat(output).contains("<body>");
        assertThat(output).contains("<h1>Error</h1>");
    }

    public static class ErrorEntityWriterTestResourceConfig extends ResourceConfig {
        public ErrorEntityWriterTestResourceConfig() {
            register(ErrorEntityWriter.class);
            register(WebApplicationExceptionMapper.class);
            register(TestResource.class);
        }
    }

    @Provider
    public static class WebApplicationExceptionMapper implements ExceptionMapper<WebApplicationException> {
        @Override
        public Response toResponse(WebApplicationException exception) {
            ErrorResponse errorResponse = new ErrorResponse("An error occurred");
            return Response.status(Status.INTERNAL_SERVER_ERROR)
                    .entity(errorResponse)
                    .type(MediaType.TEXT_HTML)
                    .build();
        }
    }

    @Provider
    public static class ErrorEntityWriter extends AbstractEntityWriter<ErrorResponse> {
        @Override
        public void writeTo(ErrorResponse errorResponse,
                            Class<?> aClass,
                            Type type,
                            Annotation[] annotations,
                            MediaType mediaType,
                            MultivaluedMap<String, Object> httpHeaders,
                            OutputStream entityStream) throws IOException {
            String html = "<html><body><h1>Error</h1><p>" + errorResponse.getMessage() + "</p></body></html>";
            entityStream.write(html.getBytes());
        }
    }

    @Path("/")
    public static class TestResource {
        @GET
        @Path("/trigger-error")
        public Response triggerError() {
            throw new WebApplicationException("This is a test error");
        }
    }

import java.util.Arrays;
 
public class Mean {
    public static double mean(double[] v, int len) {
        double sum = 0;
        int i;
        for (i = 0; i < len; i++)
            sum += v[i];
        return sum / len;
    }
 
    public static void main(String[] args) {
        double[] v = {1, 2, 2.718, 3, 3.142};
        int i, len;
        for (len = 5; len >= 0; len--) {
            System.out.print("mean[");
            for (i = 0; i < len; i++)
                System.out.print(i == 0? "" : ", " + v[i]);
            System.out.println("] = " + mean(v, len));
        }
    }
}

public class Point implements Comparable<Point> {
    private double x;
    private double y;

    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public int compareTo(Point other) {
        if (x < other.x) {
            return -1;
        } else if (x > other.x) {
            return 1;
        } else {
            if (y < other.y) {
                return -1;
            } else if (y > other.y) {
                return 1;
            } else {
                return 0;
            }
        }
    }
}

