import java.util.Random;

public class Parser {
    private static Point[] points = new Point[100];
    private static CompareY comparator = new CompareY();

    public static void main(String[] args) {
        Random randomPoint = new Random();
        for (int i = 0; i < points.length; i++) {
            points[i] = new Point(randomPoint.nextDouble() * randomPoint.nextInt(999), randomPoint.nextDouble() * randomPoint.nextInt(999));
        }
        System.out.println("Created 100 Random Points: ");
        for (Point point : points) {
            System.out.print(point.toString());
        }

        System.out.println("Increasing order by the x-coordinates: ");
        Arrays.sort(points);
        for (Point point : points) {
            System.out.print(point.toString());
        }

        System.out.println("Increasing order by the y-coordinates: ");
        Arrays.sort(points, comparator);
        for (Point point : points) {
            System.out.print(point.toString());
        }
    }
}

import java.util.Locale;
import java.util.ResourceBundle;

public String getString(String key) {
    // Get the current locale
    Locale currentLocale = Locale.getDefault();

    // Get the resource bundle for the current locale
    ResourceBundle bundle = ResourceBundle.getBundle("ResourceBundle", currentLocale);

    // Lookup the key in the resource bundle
    String localizedString = bundle.getString(key);

    // If the key is not found, return the key itself
    if (localizedString == null) {
        return key;
    }

    return localizedString;
}

import java.math.BigInteger;
 
public class CombinationsAndPermutations {
 
    public static void main(String[] args) {
        System.out.println(Double.MAX_VALUE);
        System.out.println("A sample of permutations from 1 to 12 with exact Integer arithmetic:");
        for ( int n = 1 ; n <= 12 ; n++ ) {
            int k = n / 2;
            System.out.printf("%d P %d = %s%n", n, k, permutation(n, k));
        }
 
        System.out.println();
        System.out.println("A sample of combinations from 10 to 60 with exact Integer arithmetic:");
        for ( int n = 10 ; n <= 60 ; n += 5 ) {
            int k = n / 2;
            System.out.printf("%d C %d = %s%n", n, k, combination(n, k));
        }
 
        System.out.println();
        System.out.println("A sample of permutations from 5 to 15000 displayed in floating point arithmetic:");
        System.out.printf("%d P %d = %s%n", 5, 2, display(permutation(5, 2), 50));
        for ( int n = 1000 ; n <= 15000 ; n += 1000 ) {
            int k = n / 2;
            System.out.printf("%d P %d = %s%n", n, k, display(permutation(n, k), 50));
        }
 
        System.out.println();
        System.out.println("A sample of combinations from 100 to 1000 displayed in floating point arithmetic:");
        for ( int n = 100 ; n <= 1000 ; n += 100 ) {
            int k = n / 2;
            System.out.printf("%d C %d = %s%n", n, k, display(combination(n, k), 50));
        }
 
    }
 
    private static String display(BigInteger val, int precision) {
        String s = val.toString();
        precision = Math.min(precision, s.length());
        StringBuilder sb = new StringBuilder();
        sb.append(s.substring(0, 1));
        sb.append(".");
        sb.append(s.substring(1, precision));
        sb.append(" * 10^");
        sb.append(s.length()-1);
        return sb.toString();
    }
 
    public static BigInteger combination(int n, int k) {
        //  Select value with smallest intermediate results
        //    combination(n, k) = combination(n, n-k)
        if ( n-k < k ) {
            k = n-k;
        }
        BigInteger result = permutation(n, k);
        while ( k > 0 ) {
            result = result.divide(BigInteger.valueOf(k));
            k--;
        }
        return result;
    }
 
    public static BigInteger permutation(int n, int k) {
        BigInteger result = BigInteger.ONE;
        for ( int i = n ; i >= n-k+1 ; i-- ) {
            result = result.multiply(BigInteger.valueOf(i));
        }
        return result;
    }
 
}

public static boolean isMarkovMatrix(double[][] m) {
    int n = m.length;
    for (int j = 0; j < n; j++) {
        double columnSum = 0;
        for (int i = 0; i < n; i++) {
            if (m[i][j] < 0) // check if the element is negative
                return false;
            columnSum += m[i][j];
        }
        if (Math.abs(columnSum - 1.0) > 0.0001) // check if the column sum is 1
            return false;
    }
    return true;
}

public class Series {

    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.printf("m(%d) = %.2f%n", i, computeSeries(i));
        }
    }

    public static double computeSeries(int i) {
        if (i == 1) {
            return 1.0;
        } else {
            return computeSeries(i - 1) + 1.0 / i;
        }
    }
}

private Stream<Triple> memberRelations(final FedoraResource container) throws RepositoryException {
        final org.apache.jena.graph.Node memberRelation;
        if (container.hasProperty(LDP_HAS_MEMBER_RELATION)) {
            final Property property = getJcrNode(container).getProperty(LDP_HAS_MEMBER_RELATION);
            memberRelation = createURI(property.getString());
        } else if (container.hasType(LDP_BASIC_CONTAINER)) {
            memberRelation = LDP_MEMBER.asNode();
        } else {
            return empty();
        }
        final String insertedContainerProperty;
        if (container.hasType(LDP_INDIRECT_CONTAINER)) {
            if (container.hasProperty(LDP_INSERTED_CONTENT_RELATION)) {
                insertedContainerProperty = getJcrNode(container).getProperty(LDP_INSERTED_CONTENT_RELATION)
                    .getString();
            } else {
                return empty();
            }
        } else {
            insertedContainerProperty = MEMBER_SUBJECT.getURI();
        }
        return container.getChildren().flatMap(
            UncheckedFunction.uncheck(child -> {
                final org.apache.jena.graph.Node childSubject = uriFor(child.getDescribedResource());
                if (insertedContainerProperty.equals(MEMBER_SUBJECT.getURI())) {
                    return of(create(subject(), memberRelation, childSubject));
                }
                String insertedContentProperty = getPropertyNameFromPredicate(getJcrNode(resource()),
                        createResource(insertedContainerProperty), null);
                if (child.hasProperty(insertedContentProperty)) {

                } else if (child.hasProperty(getReferencePropertyName(insertedContentProperty))) {

                    insertedContentProperty = getReferencePropertyName(insertedContentProperty);
                } else {

                    return empty();
                }
                return iteratorToStream(new PropertyValueIterator(
                        getJcrNode(child).getProperty(insertedContentProperty)))
                    .map(uncheck(v -> create(subject(), memberRelation,
                        new ValueConverter(getJcrNode(container).getSession(), translator()).convert(v).asNode())));
            }));
    }

