public class MySubsystemExtension implements Extension {

    private static final Logger log = Logger.getLogger("MySubsystemExtension");
    public static final String SUBSYSTEM_NAME = "my-subsystem";
    public static final String XML_NAMESPACE = "urn:jboss:domain:my-subsystem:1.0";
    static final PathElement SUBSYSTEM_PATH = PathElement.pathElement("subsystem", SUBSYSTEM_NAME);

    @Override
    public void initialize(ExtensionContext context) {
        log.info("Initializing MySubsystemExtension for " + SUBSYSTEM_NAME);
        SubsystemRegistration subsystemReg = context.registerSubsystem(SUBSYSTEM_NAME);
        ManagementResourceRegistration root = subsystemReg.registerSubsystemModel(new MySubsystemRootDefinition());
        root.registerOperationHandler(GenericSubsystemDescribeHandler.DEFINITION, GenericSubsystemDescribeHandler.INSTANCE);
        subsystemReg.registerXMLElementWriter(new MySubsystemXMLWriter());
    }

    @Override
    public void initializeParsers(ExtensionParsingContext context) {
        context.setSubsystemXmlMapping(SUBSYSTEM_NAME, XML_NAMESPACE, new MySubsystemParser());
    }

    public static ResourceDescriptionResolver getResourceDescriptionResolver(final String keySuffix) {
        StringBuilder keyBuilder = new StringBuilder("my-subsystem");
        if (keySuffix != null && !keySuffix.isEmpty()) {
            keyBuilder.append('.').append(keySuffix);
        }
        return new MyResourceDescriptionResolver(keyBuilder.toString());
    }
}

