public class Product {
 
    private static final int MAX_NUM_TRIES = 72;
    private static final int LINE_BEGIN = 7;
    private static final int LAST_LINE = 18;
 
    private static int yp = LINE_BEGIN;
    private static int xp = 0;
 
    private static char[] number = new char[5];
    private static char[] guess = new char[5];
 
    private static final int MAX_STR = 256;
 
    private static void mvaddstrf(int y, int x, String fmt, Object... args) {
        String buf = String.format(fmt, args);
        System.out.printf("\033[%d;%dH%s", y, x, buf);
    }
 
    private static void ask_for_a_number() {
        int i = 0;
        char[] symbols = "123456789".toCharArray();
 
        mvaddstrf(5, 0, "Enter four digits: ");
        while (i < 4) {
            int c = System.in.read();
            if ((c >= '1') && (c <= '9') && (symbols[c - '1']!= 0)) {
                System.out.print((char) c);
                symbols[c - '1'] = 0;
                guess[i++] = (char) c;
            }
        }
    }
 
    private static void choose_the_number() {
        int i = 0, j;
        char[] symbols = "123456789".toCharArray();
 
        while (i < 4) {
            j = new Random().nextInt(9);
            if (symbols[j]!= 0) {
                number[i++] = symbols[j];
                symbols[j] = 0;
            }
        }
    }
 
    public static void main(String[] args) {
        choose_the_number();
 
        for (int i = 0; i < MAX_NUM_TRIES; i++) {
            ask_for_a_number();
            int bulls = 0, cows = 0;
            for (int j = 0; j < 4; j++) {
                if (guess[j] == number[j]) {
                    bulls++;
                } else {
                    for (int k = 0; k < 4; k++) {
                        if (guess[j] == number[k]) {
                            cows++;
                        }
                    }
                }
            }
            mvaddstrf(yp, xp, "Bulls: %d, Cows: %d", bulls, cows);
            yp++;
            if (bulls == 4) {
                mvaddstrf(yp, xp, "You win!");
                break;
            }
        }
    }
}

public class Finder {
