    protected T instance;

    public final T getInstance() {
        if (instance == null) {
            instance = createInstance();
        }
        return instance;
    }

    protected abstract T createInstance();

    public final boolean isInitialized() {
        return instance != null;
    }

    public void reset() {
        instance = null;
    }

}

