import java.io.File;
import java.io.FileNotFoundException;
import java.util.HashSet;
import java.util.Scanner;
 
public class AutomaticAbbreviations {
 
    public static int shortestAbbreviationLength(String line, int listSize) {
        String[] words = line.split(" ");
        int wordCount = words.length;
        // Can't give true answer with unexpected number of entries
        if (wordCount!= listSize) {
            throw new IllegalArgumentException("Not enough entries, expected " + listSize + " found " + wordCount);
        }
 
        // Find the small slice length that gives list_size unique values
        int abbreviationLength = 1;
        HashSet<String> abbreviations = new HashSet<>();
        while (true) {
            for (String word : words) {
                abbreviations.add(word.substring(0, abbreviationLength));
            }
            if (abbreviations.size() == listSize) {
                return abbreviationLength;
            }
            abbreviationLength++;
            abbreviations.clear();
        }
    }
 
    public static void automaticAbbreviations(String filename, int wordsPerLine) {
        try {
            Scanner file = new Scanner(new File(filename));
            while (file.hasNextLine()) {
                String line = file.nextLine();
                if (line.length() > 0) {
                    int length = shortestAbbreviationLength(line, wordsPerLine);
                    System.out.println(String.format("%2d %s", length, line));
                } else {
                    System.out.println();
                }
            }
        } catch (FileNotFoundException e) {
            System.out.println("File not found");
        }
    }
 
    public static void main(String[] args) {
        automaticAbbreviations("daysOfWeek.txt", 7);
    }
}

