import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.StringTokenizer;
 
public class CSV {
 
    private Map<String, String> m_oData;
    private int m_nCols;
    private int m_nRows;
 
    public CSV() {
        m_oData = new HashMap<String, String>();
        m_nCols = 0;
        m_nRows = 0;
    }
 
    public boolean open(String filename, char delim) {
        File file = new File(filename);
        if (file.exists()) {
            try {
                open(new BufferedReader(new FileReader(file)), delim);
                return true;
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return false;
    }
 
    public void open(BufferedReader reader, char delim) {
        clear();
        String line;
        try {
            while ((line = reader.readLine())!= null) {
                int nCol = 0;
                StringTokenizer lineStream = new StringTokenizer(line, String.valueOf(delim));
                String cell;
                while (lineStream.hasMoreTokens()) {
                    cell = lineStream.nextToken();
                    m_oData.put(nCol + "," + m_nRows, trim(cell));
                    nCol++;
                }
                m_nCols = Math.max(m_nCols, nCol);
                m_nRows++;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public boolean save(String pFile, char delim) {
        File file = new File(pFile);
        if (file.exists()) {
            try {
                save(new BufferedWriter(new FileWriter(file)), delim);
                return true;
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        return false;
    }
 
    public void save(BufferedWriter writer, char delim) {
        try {
            for (int nRow = 0; nRow < m_nRows; nRow++) {
                for (int nCol = 0; nCol < m_nCols; nCol++) {
                    writer.write(trim(m_oData.get(nCol + "," + nRow)));
                    if ((nCol + 1) < m_nCols) {
                        writer.write(delim);
                    } else {
                        writer.write("\n");
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public void clear() {
        m_oData.clear();
        m_nRows = m_nCols = 0;
    }

