public static boolean isPositiveZ(Point2D_I32 a, Point2D_I32 b, Point2D_I32 c ) {
    // Calculate vectors v0 and v1
    Point2D_I32 v0 = new Point2D_I32(a.x - b.x, a.y - b.y);
    Point2D_I32 v1 = new Point2D_I32(c.x - b.x, c.y - b.y);

    // Calculate cross product
    int crossProduct = v0.x * v1.y - v0.y * v1.x;

    // Return true if cross product is positive
    return crossProduct > 0;
}

