    public enum SimulationComponent {
        CREATE, START, PAUSE, EXIT, CLEANUP, TIME
    }

    private final EnumMap<SimulationComponent, JComponent> components;
    private final JFrame window;
    private final JLabel displayedTime;

    public PCSimulationGui(AgentGuiConfig config) {
        super(config);
        components = new EnumMap<>(SimulationComponent.class);
        window = new JFrame("Simulation Controller");
        window.setLayout(new GridBagLayout());

        JPanel controlPanel = new JPanel();
        controlPanel.setLayout(new BoxLayout(controlPanel, BoxLayout.X_AXIS));
        controlPanel.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        JButton createBtn = createButton("Create Agents", "Initialize agents");
        JButton startBtn = createButton("Start", "Begin simulation");
        JButton pauseBtn = createButton("Pause", "Pause simulation");
        JButton cleanupBtn = createButton("Cleanup", "Remove agents");
        JButton exitBtn = createButton("Exit", "Terminate application");

        displayedTime = new JLabel("Time: 0.00s");
        displayedTime.setFont(new Font("Dialog", Font.BOLD, 14));
        displayedTime.setBorder(BorderFactory.createEmptyBorder(0, 20, 0, 5));

        addComponentsWithSpacing(controlPanel,
            createBtn, startBtn, pauseBtn, cleanupBtn, exitBtn);

        controlPanel.add(Box.createHorizontalGlue());
        controlPanel.add(displayedTime);

        registerComponents(createBtn, startBtn, pauseBtn, cleanupBtn, exitBtn);

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.gridx = gbc.gridy = 0;
        gbc.weightx = 1.0;
        gbc.fill = GridBagConstraints.HORIZONTAL;
        window.add(controlPanel, gbc);

        configureMainWindow();
    }

    private JButton createButton(String text, String tooltip) {
        JButton btn = new JButton(text);
        btn.setToolTipText(tooltip);
        btn.setMargin(new Insets(4, 8, 4, 8));
        return btn;
    }

    private void addComponentsWithSpacing(Container panel, Component... components) {
        for (Component comp : components) {
            panel.add(comp);
            panel.add(Box.createHorizontalStrut(8));
        }
    }

    private void registerComponents(JButton... buttons) {
        components.put(SimulationComponent.CREATE, buttons[0]);
        components.put(SimulationComponent.START, buttons[1]);

import org.biopax.paxtools.model.BioPAXElement;
import org.biopax.paxtools.model.BioPAXFactory;
import org.biopax.paxtools.model.Xref;

public Xref findPreferredXref(BioPAXElement bpe) {
    Xref preferredXref = null;
    String[] preferredDbValues = {"ncbi gene", "uniprot", "refseq", "chebi"};

    for(Xref xref : bpe.getXref()) {
        String currentDb = xref.getDb();

        for(String preferredDb : preferredDbValues) {
            if(currentDb.equals(preferredDb)) {
                preferredXref = xref;
                return preferredXref;
            }
        }
    }

    return preferredXref;
}

public class Roots {
    public interface Function {
    public double f(double x);
    }
 
    private static int sign(double x) {
    return (x < 0.0) ? -1 : (x > 0.0) ? 1 : 0;
    }
 
    public static void printRoots(Function f, double lowerBound,
                  double upperBound, double step) {
    double x = lowerBound, ox = x;
    double y = f.f(x), oy = y;
    int s = sign(y), os = s;
 
    for (; x <= upperBound ; x += step) {
        s = sign(y = f.f(x));
        if (s == 0) {
        System.out.println(x);
        } else if (s != os) {
        double dx = x - ox;
        double dy = y - oy;
        double cx = x - dx * (y / dy);
        System.out.println("~" + cx);
        }
        ox = x; oy = y; os = s;
    }
    }
 
    public static void main(String[] args) {
    Function poly = new Function () {
        public double f(double x) {
        return x*x*x - 3*x*x + 2*x;
        }
    };
    printRoots(poly, -1.0, 4, 0.002);
    }
}

