private void queueEmptyMaybeFlush() {
        if (PERIODIC_FORCE_FLUSH) {
            long currentTime = time.get();

            if ((currentTime - lastFlushTime) > FORCE_FLUSH_AFTER_THIS_MANY_MILI_SECONDS) {

                if (writer.syncToDisk()) {
                    this.numberOfFlushesTotal.incrementAndGet();
                }

                lastFlushTime = time.get();
            }
        }
    }

import org.apache.ignite.IgniteCheckedException;
import org.apache.ignite.internal.pagemem.PageMemory;
import org.apache.ignite.internal.processors.cache.persistence.tree.io.DataPageIO;

/**
 * Insert fragment to data page record.
 */
public class DataPageInsertFragmentRecord extends PageDeltaRecord {
    /** Link to the last entry fragment. */
    private final long lastLink;

    /** Actual fragment data. */
    private final byte[] payload;

    /**
     * @param grpId Cache group ID.
     * @param pageId Page ID.
     * @param payload Fragment payload.
     * @param lastLink Link to the last entry fragment.
     */
    public DataPageInsertFragmentRecord(
        final int grpId,
        final long pageId,
        final byte[] payload,
        final long lastLink
    ) {
        super(grpId, pageId);

        this.lastLink = lastLink;
        this.payload = payload;
    }

    /** {@inheritDoc} */
    @Override public void applyDelta(PageMemory pageMem, long pageAddr) throws IgniteCheckedException {
        DataPageIO io = DataPageIO.VERSIONS.forPage(pageAddr);

        io.addRowFragment(pageAddr, payload, lastLink, pageMem.pageSize());
    }

    /** {@inheritDoc} */
    @Override public RecordType type() {
        return RecordType.DATA_PAGE_INSERT_FRAGMENT_RECORD;
    }

    /**
     * @return Fragment payload size.
     */
    public int payloadSize() {
        return payload.length;
    }

    /**
     * @return Fragment payload.
     */
    public byte[] payload() {
        return payload;
    }

    /**
     * @return Link to the last entry fragment.
     */
    public long lastLink() {
        return lastLink;
    }
}

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
 
public class Sierpinski {
 
    public static void main(String[] args) throws IOException {
        final int order = 8;
        final int width = 1 << order;
        final int margin = 10;
        final int height = width + 2 * margin;
        final int widthHeight = width + height;
        final BufferedImage im = new BufferedImage(widthHeight, widthHeight, BufferedImage.TYPE_BYTE_GRAY);
        final Color gBlack = Color.BLACK;
        final Color gWhite = Color.WHITE;
        final int gBlackInt = gBlack.getRGB();
        final int gWhiteInt = gWhite.getRGB();
        for (int y = 0; y < widthHeight; y++) {
            for (int x = 0; x < widthHeight; x++) {
                im.setRGB(x, y, gWhiteInt);
            }
        }
 
        for (int y = 0; y < width; y++) {
            for (int x = 0; x < width; x++) {
                if ((x & y) == 0) {
                    im.setRGB(x, y, gBlackInt);
                }
            }
        }
        File outputfile = new File("sierpinski.png");
        ImageIO.write(im, "png", outputfile);
    }
}

