import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
 
public class Ranges {
    // A range is represented as a pair of doubles
    static class Range {
        double first;
        double second;
        Range(double first, double second) {
            this.first = first;
            this.second = second;
        }
    }
 
    static void normalizeRanges(List<Range> ranges) {
        for (Range range : ranges) {
            if (range.second < range.first) {
                double temp = range.first;
                range.first = range.second;
                range.second = temp;
            }
        }
        Collections.sort(ranges, (a, b) -> Double.compare(a.first, b.first));
    }
 
    // Merges a range of ranges in-place. Returns an iterator to the
    // end of the resulting range, similarly to std::remove.
    static int mergeRanges(List<Range> ranges) {
        int out = 0;
        for (int i = 0; i < ranges.size(); ) {
            int j = i;
            while (++j < ranges.size() && ranges.get(j).first <= ranges.get(i).second)
                ranges.get(i).second = Math.max(ranges.get(i).second, ranges.get(j).second);
            ranges.set(out++, ranges.get(i));
            i = j;
        }
        return out;
    }
 
    static int consolidateRanges(List<Range> ranges) {
        normalizeRanges(ranges);
        return mergeRanges(ranges);
    }
 
    static void printRange(Range range) {
        System.out.printf("[%f, %f]", range.first, range.second);
    }
 
    static void printRanges(List<Range> ranges) {
        if (!ranges.isEmpty()) {
            printRange(ranges.get(0));
            for (int i = 1; i < ranges.size(); ++i) {
                System.out.print(", ");
                printRange(ranges.get(i));
            }
        }
    }
 
    public static void main(String[] args) {
        List<Range> testCases[] = {
            new ArrayList<Range>() {{ add(new Range(1.1, 2.2)); }},
            new ArrayList<Range>() {{ add(new Range(6.1, 7.2)); add(new Range(7.2, 8.3)); }},
            new ArrayList<Range>() {{ add(new Range(4, 3)); add(new Range(2, 1)); }},
            new ArrayList<Range>() {{ add(new Range(4, 3)); add(new Range(2, 1)); add(new Range(-1, -2)); add(new Range(3.9, 10)); }},
            new ArrayList<Range>() {{ add(new Range(1, 3)); add(new Range(-6, -1)); add(new Range(-4, -5)); add(new Range(8, 2)); add(new Range(-6, -6)); }}
        };
        for (List<Range> ranges : testCases) {
            printRanges(ranges);
            System.out.print(" -> ");

