import java.io.IOException;
import uk.ac.susx.mlcl.byblo.io.Weighted;

public class WeightStatsObjectSource<T extends Weighted<T>> implements ObjectSource<T> {

    private final ObjectSource<T> source;
    private double weightMin = Double.POSITIVE_INFINITY;
    private double weightMax = Double.NEGATIVE_INFINITY;
    private double weightSum = 0.0;
    private long weightCount = 0;

    public WeightStatsObjectSource(ObjectSource<T> source) {
        if (source == null) {
            throw new IllegalArgumentException("Source cannot be null");
        }
        this.source = source;
    }

    @Override
    public boolean hasNext() throws IOException {
        return source.hasNext();
    }

    @Override
    public T read() throws IOException {
        T obj = source.read();
        if (obj != null) {
            updateWeightStatistics(obj.getWeight());
        }
        return obj;
    }

    private void updateWeightStatistics(double weight) {
        weightMin = Math.min(weightMin, weight);
        weightMax = Math.max(weightMax, weight);
        weightSum += weight;
        weightCount++;
    }

    public double getWeightSum() {
        return weightSum;
    }

    public double getWeightMin() {
        return weightCount > 0 ? weightMin : 0.0;
    }

    public double getWeightMax() {
        return weightCount > 0 ? weightMax : 0.0;
    }

    public double getWeightRange() {
        return weightCount > 0 ? weightMax - weightMin : 0.0;
    }

    public double getWeightMean() {
        return weightCount > 0 ? weightSum / weightCount : 0.0;
    }

    @Override
    public void close() throws IOException {
        source.close();
    }

    @Override
    public void reset() throws IOException {
        source.reset();
        resetWeightStatistics();
    }

    private void resetWeightStatistics() {
        weightMin = Double.POSITIVE_INFINITY;
        weightMax = Double.NEGATIVE_INFINITY;
        weightSum = 0.0;
        weightCount = 0;
    }

    @Override
    public String toString() {
        return String.format(
            "WeightStatsObjectSource[count=%d, min=%.4f, max=%.4f, sum=%.4f, mean=%.4f]",
            weightCount, getWeightMin(), getWeightMax(), getWeightSum(), getWeightMean()
        );
    }
}

@Override
    public final void close() throws JMSException
    {
        externalAccessLock.writeLock().lock();
        try
        {
            if (closed)
                return;
            closed = true;
            onConsumerClose();
        }
        finally
        {
            externalAccessLock.writeLock().unlock();
        }
        onConsumerClosed();
    }

import java.util.List;
import java.util.Set;
import java.util.function.Function;

import anatlyzer.atl.analyser.generators.CSPModel2;
import anatlyzer.atl.analyser.generators.ErrorSlice;
import anatlyzer.atl.analyser.generators.GraphvizBuffer;
import anatlyzer.atl.util.Pair;
import anatlyzer.atlext.ATL.InPatternElement;
import anatlyzer.atlext.ATL.OutPatternElement;
import anatlyzer.atlext.OCL.CollectionOperationCallExp;
import anatlyzer.atlext.OCL.Iterator;
import anatlyzer.atlext.OCL.IteratorExp;
import anatlyzer.atlext.OCL.LetExp;
import anatlyzer.atlext.OCL.OCLFactory;
import anatlyzer.atlext.OCL.OclExpression;
import anatlyzer.atlext.OCL.SequenceExp;

public class SplitIteratorBodyNode extends AbstractInvariantReplacerNode {

    private List<IInvariantNode> paths;
    private IteratorExp expr;

    public SplitIteratorBodyNode(List<IInvariantNode> paths, IteratorExp expr) {
        super(null);
        this.paths = paths;
        this.expr = expr;
        this.paths.forEach(p -> p.setParent(this));
    }

    @Override
    public void genErrorSlice(ErrorSlice slice) {
        paths.forEach(p -> p.genErrorSlice(slice));
    }

    @Override
    public OclExpression genExpr(CSPModel2 builder) {
        return genAux(builder, (node) -> node.genExpr(builder));
    }

    @Override
    public OclExpression genExprNormalized(CSPModel2 builder) {
        return genAux(builder, (node) -> node.genExprNormalized(builder));
    }

    public OclExpression genAux(CSPModel2 builder, Function<IInvariantNode, OclExpression> gen) {
        // assume the paths are from collections...
        SequenceExp seq = OCLFactory.eINSTANCE.createSequenceExp();
        for (IInvariantNode iInvariantNode : paths) {
            seq.getElements().add(gen.apply(iInvariantNode));
        }

        CollectionOperationCallExp flatten = OCLFactory.eINSTANCE.createCollectionOperationCallExp();
        flatten.setOperationName("flatten");
        flatten.setSource(seq);

        return flatten;
    }

    @Override
    public void genGraphviz(GraphvizBuffer<IInvariantNode> gv) {
        gv.addNode(this, gvText("Split node. ", expr), true);
        paths.forEach(p -> {
            p.genGraphviz(gv);
            gv.addEdge(p, this);
        });
    }

    @Override
    public void getTargetObjectsInBinding(Set<OutPatternElement> elems) {
        paths.forEach(n -> n.getTargetObjectsInBinding(elems));
    }

    @Override
    public Pair<LetExp, LetExp> genIteratorBindings(CSPModel2 builder, Iterator it, Iterator targetIt) {
        // do nothing
        return null;
    }

import com.google.api.services.dfareporting.Dfareporting;
import com.google.api.services.dfareporting.model.FloodlightActivity;
import com.google.api.services.samples.dfareporting.DfaReportingFactory;

/**
 * This example creates a floodlight activity in a given activity group. To create an activity
 * group, run CreateFloodlightActivityGroup.java.
 *
 * Tags: floodlightActivities.insert
 *
 */
public class CreateFloodlightActivity {
  private static final String USER_PROFILE_ID = "INSERT_USER_PROFILE_ID_HERE";

  private static final String ACTIVITY_GROUP_ID = "INSERT_ACTIVITY_GROUP_ID_HERE";
  private static final String ACTIVITY_NAME = "INSERT_ACTIVITY_NAME_HERE";
  private static final String URL = "INSERT_EXPECTED_URL_HERE";

  public static void runExample(Dfareporting reporting, long profileId, String activityName,
      String url, long activityGroupId) throws Exception {
    // Set floodlight activity structure.
    FloodlightActivity activity = new FloodlightActivity();
    activity.setCountingMethod("STANDARD_COUNTING");
    activity.setName(activityName);
    activity.setFloodlightActivityGroupId(activityGroupId);
    activity.setExpectedUrl(url);

    // Create the floodlight tag activity.
    FloodlightActivity result =
        reporting.floodlightActivities().insert(profileId, activity).execute();

    // Display new floodlight activity ID.
    if (result != null) {
      System.out.printf("Floodlight activity with ID %d was created.%n", result.getId());
    }
  }

  public static void main(String[] args) throws Exception {
    Dfareporting reporting = DfaReportingFactory.getInstance();

    long activityGroupId = Long.parseLong(ACTIVITY_GROUP_ID);
    long profileId = Long.parseLong(USER_PROFILE_ID);

    runExample(reporting, profileId, ACTIVITY_NAME, URL, activityGroupId);
  }
}

class Cashier {

    int k;
    int discount;

    int count = 0;

    Map<Integer, Integer> map = new HashMap<>();

    public Cashier(int n, int discount, int[] products, int[] prices) {
        k = n;
        this.discount = discount;
        for (int i = 0; i < products.length; i++) {
            map.put(products[i], prices[i]);
        }
    }

    public double getBill(int[] product, int[] amount) {
        count++;

        double res = 0;

        for (int i = 0; i < product.length; i++) {
            res += map.get(product[i]) * amount[i];
        }

        if (count % k == 0) {
            res = res - (discount * res) / 100;
        }

        return res;
    }
}

