class Handler {
    int n,m;
    int[][] dirs = new int[][]{{1,0},{0,-1},{-1,0},{0,1}};
    boolean[][] vis;

    public boolean containsCycle(char[][] grid) {
        n = grid.length;
        m = grid[0].length;
        vis = new boolean[n][m];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                if(vis[i][j]) continue;
                if(dfs(grid,i,j,grid[i][j],-1,-1,new HashSet<Integer>())) return true;
            }
        }
        return false;
    }

    public boolean dfs(char[][] grid, int x, int y, char tar, int lx, int ly, Set<Integer> set){
        if(x<0 || x>=n || y<0 || y>=m) return false;
        if(grid[x][y]!=tar) return false;
        if(set.contains(x*1000+y)) return true;
        set.add(x*1000+y);
        vis[x][y] = true;
        for(int[] dir: dirs){
            int nx = x+dir[0], ny = y+dir[1];
            if(nx==lx && ny==ly) continue;
            if(dfs(grid,nx,ny,tar,x,y,set)) return true;
        }
        return false;
    }
}

class Logger {
    public int waysToReachTarget(int target, int[][] types) {
        long M = (long) 1e9 + 7;
        long[] a = new long[target + 1];
        a[0] = 1;
        for (int[] t : types) {
            for (int i = a.length - 1; i >= 0; --i) {
                if (a[i] == 0) continue;
                int fen = 0;
                for (int j = 1; j <= t[0]; ++j) {
                    fen += t[1];
                    if (i + fen >= a.length) break;
                    a[i + fen] = (a[i + fen] + a[i]) % M;
                }
            }
        }
        return (int) a[target];

    }
}

import java.util.function.Consumer;
