public static <T extends Comparable<T>> Set<Set<T>> consolidateSets(Set<T>[] sets) {
    int size = sets.length;
    boolean[] consolidated = new boolean[size]; // all false by default
    int i = 0;
    while (i < size - 1) {
        if (!consolidated[i]) {
            while (true) {
                int intersects = 0;
                for (int j = i + 1; j < size; j++) {
                    if (consolidated[j]) continue;
                    if (sets[i].stream().anyMatch(sets[j]::contains)) {
                        sets[i].addAll(sets[j]);
                        consolidated[j] = true;
                        intersects++;
                    }
                }
                if (intersects == 0) break;
            }
        }
        i++;
    }
    return IntStream.range(0, size).filter(i ->!consolidated[i]).mapToObj(i -> new TreeSet<>(sets[i])).collect(Collectors.toSet());
}
 
public static void main(String[] args) {
    Set<Character>[] unconsolidatedSets = new Set[] {
        new HashSet<>(Arrays.asList('A', 'B', 'C', 'D')),
        new HashSet<>(Arrays.asList('A', 'B', 'B', 'D')),
        new HashSet<>(Arrays.asList('A', 'B', 'C', 'D', 'D', 'B')),
        new HashSet<>(Arrays.asList('H', 'I', 'K', 'A', 'B', 'C', 'D', 'D', 'B', 'F', 'G', 'H'))
    };
    for (Set<Character>[] sets : unconsolidatedSets) System.out.println(consolidateSets(sets));
}

public class NumberOfDaysInYear {
    public static void main(String[] args) {
        for (int year = 2000; year <= 2020; year++) {
            System.out.println(year + " has " + numberOfDaysInAYear(year) + " days");
        }
    }

    public static int numberOfDaysInAYear(int year) {
        if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
            return 366; // leap year
        } else {
            return 365; // non-leap year
        }
    }
}

