public final class ConstructorArrObjSNS {

    private ConstructorArrObjSNS() {
        // Private constructor to prevent instantiation
    }

    public static ArrayList<ObjectSNSDeportivo> producirArrayObjetoSNS(JSONArray jsonArray, FactoryObjectSNSDeportivo factory) {
        ArrayList<ObjectSNSDeportivo> objetoSNSList = new ArrayList<>();
        for (int i = 0; i < jsonArray.length(); i++) {
            try {
                String jsonString = jsonArray.getString(i);
                ObjectSNSDeportivo objetoSNS = factory.createObject(jsonString);
                objetoSNSList.add(objetoSNS);
            } catch (JSONException | ExcepcionJsonDeserializacion e) {
                e.printStackTrace();
            }
        }
        return objetoSNSList;
    }

    public static ArrayList<KeyValueItem> producirArrayAdapterObjSNS(ArrayList<ObjectSNSDeportivo> objetoSNSList, String[] atributos) {
        return producirArrayAdapterObjSNS(objetoSNSList, atributos, " - ");
    }

    public static ArrayList<KeyValueItem> producirArrayAdapterObjSNS(ArrayList<ObjectSNSDeportivo> objetoSNSList, String[] atributos, String separador) {
        ArrayList<KeyValueItem> keyValueItemList = new ArrayList<>();
        for (ObjectSNSDeportivo objetoSNS : objetoSNSList) {
            StringBuilder sb = new StringBuilder();
            for (String atributo : atributos) {
                if (sb.length() > 0) {
                    sb.append(separador);
                }
                sb.append(JsonUtils.getAttributeValue(objetoSNS, atributo));
            }
            KeyValueItem keyValueItem = new KeyValueItem(sb.toString(), objetoSNS);
            keyValueItemList.add(keyValueItem);
        }
        return keyValueItemList;
    }

    public static class KeyValueItem {
        private final String key;
        private final ObjectSNSDeportivo value;

        public KeyValueItem(String key, ObjectSNSDeportivo value) {
            this.key = key;
            this.value = value;
        }

        public String getKey() {
            return key;
        }

        public ObjectSNSDeportivo getValue() {
            return value;
        }
    }
}

