        System.out.print("Enter the initial temperature of the water in degrees Celsius: ");
        double initialTemp = input.nextDouble();
        System.out.print("Enter the final temperature of the water in degrees Celsius: ");
        double finalTemp = input.nextDouble();

        // Calculate the energy needed
        double energy = weight * (finalTemp - initialTemp) * 4184;

        // Display the result
        System.out.printf("The energy needed to heat %.2f kilograms of water from %.2f°C to %.2f°C is %.2f joules.%n", weight, initialTemp, finalTemp, energy);
    }
}

public class Course {
    private String courseName;
    private String[] students = new String[1];
    private int numberOfStudents;

    public Course(String courseName) {
        this.courseName = courseName;
    }

    public String getCourseName() {
        return courseName;
    }

    public void addStudent(String student) {
        if (numberOfStudents == students.length) {
            String[] newStudents = new String[students.length * 2];
            System.arraycopy(students, 0, newStudents, 0, students.length);
            students = newStudents;
        }
        students[numberOfStudents++] = student;
    }

    public void dropStudent(String student) {
        for (int i = 0; i < numberOfStudents; i++) {
            if (students[i].equals(student)) {
                students[i] = null;
                System.arraycopy(students, i + 1, students, i, numberOfStudents - i - 1);
                numberOfStudents--;
                break;
            }
        }
    }

    public void clear() {
        students = new String[1];
        numberOfStudents = 0;
    }

    public String[] getStudents() {
        return students;
    }

    public int getNumberOfStudents() {
        return numberOfStudents;
    }
}

import java.util.Scanner;
import java.util.HashSet;

public class IntegralArray {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int c = scanner.nextInt();
            HashSet<Integer> set = new HashSet<>();
            for (int i = 0; i < n; i++) {
                set.add(scanner.nextInt());
            }
            boolean isIntegral = true;
            for (int x : set) {
                for (int y = 1; y <= x && isIntegral; y++) {
                    if (set.contains(x / y)) {
                        continue;
                    } else {
                        isIntegral = false;
                    }
                }
            }
            System.out.println(isIntegral ? "Yes" : "No");
        }
        scanner.close();
    }
}

import org.geotools.coverage.grid.GridCoverage2D;
import org.jgrasstools.hortonmachine.modules.geomorphology.aspect.OmsAspect;
import org.jgrasstools.hortonmachine.utils.HMTestCase;
import org.jgrasstools.hortonmachine.utils.HMTestMaps;
import org.jgrasstools.hortonmachine.utils.CoverageUtilities;
import org.junit.Before;
import org.junit.Test;

public class AspectCalculationTest extends HMTestCase {

    private GridCoverage2D elevationGrid;
    private final double TOLERANCE_DEG = 0.01;
    private final double TOLERANCE_RAD = 0.001;

    @Before
    public void setUp() throws Exception {
        super.setUp();
        elevationGrid = HMTestMaps.createPitTestMap();
    }

    @Test
    public void testAspectDegrees() throws Exception {
        OmsAspect aspectCalculator = new OmsAspect();
        aspectCalculator.inElev = elevationGrid;
        aspectCalculator.doRadiants = false;
        aspectCalculator.doRound = false;
        aspectCalculator.process();

        GridCoverage2D computedAspectGrid = aspectCalculator.outAspect;
        double[][] computedMatrix = CoverageUtilities.getMatrix(computedAspectGrid);
        double[][] expectedMatrix = HMTestMaps.aspectDataDegrees();

        checkMatrixEqual(computedMatrix, expectedMatrix, TOLERANCE_DEG);
    }

    @Test
    public void testAspectRadians() throws Exception {
        OmsAspect aspectCalculator = new OmsAspect();
        aspectCalculator.inElev = elevationGrid;
        aspectCalculator.doRadiants = true;
        aspectCalculator.doRound = false;
        aspectCalculator.process();

        GridCoverage2D computedAspectGrid = aspectCalculator.outAspect;
        double[][] computedMatrix = CoverageUtilities.getMatrix(computedAspectGrid);
        double[][] expectedMatrix = HMTestMaps.aspectDataRadiants();

        checkMatrixEqual(computedMatrix, expectedMatrix, TOLERANCE_RAD);
    }

    private void checkMatrixEqual(double[][] actual, double[][] expected, double tolerance) {
        for (int row = 0; row < expected.length; row++) {
            for (int col = 0; col < expected[0].length; col++) {
                assertEquals("Mismatch at ["+row+"]["+col+"]",
                    expected[row][col], actual[row][col], tolerance);
            }
        }
    }
}

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
 
public class FuscSequence {
    public static void main(String[] args) {
        System.out.println("First 61 fusc numbers:");
        for (int n : fuscSequence().take(61)) {
            System.out.print(n + " ");
        }
        System.out.println();
        System.out.println();
        System.out.println("Fusc numbers up to 1000000000 that are longer than any previous one:");
        int max = 0;
        for (int n : fuscSequence().take(1000000000)) {
            if (n >= max) {
                max = Math.max(10, max * 10);
                System.out.println("index = " + n + ", fusc number = " + n);
            }
        }
    }
 
    public static Iterator<Integer> fuscSequence() {
        List<Integer> sequence = new ArrayList<>();
        sequence.add(0);
        sequence.add(1);
        int n = 0;
        return new Iterator<Integer>() {
            @Override
            public boolean hasNext() {
                return true;
            }
 
            @Override
            public Integer next() {
                if (n > 1) {
                    if (n % 2 == 0) {
                        sequence.add(sequence.get(n / 2));
                    } else {
                        sequence.add(sequence.get((n - 1) / 2) + sequence.get((n + 1) / 2));
                    }
                }
                int result = sequence.get(n);
                n++;
                return result;
            }
        };
    }
}

