    }
}

import com.palantir.logsafe.Arg;
import com.palantir.logsafe.SafeArg;
import com.palantir.logsafe.UnsafeArg;
import com.palantir.logsafe.logger.SafeLogger;
import com.palantir.logsafe.logger.SafeLoggerFactory;

import javax.annotation.Nullable;
import java.util.concurrent.atomic.AtomicReference;

public final class TimestampDebugLogger {
    private static final SafeLogger logger = SafeLoggerFactory.get(TimestampDebugLogger.class);

    private static final AtomicReference<TimestampRange> lastSuccessfulRange = new AtomicReference<>();

    private TimestampDebugLogger() {
        // Prevent instantiation
    }

    public static void handedOutTimestamps(long start, long end, @Nullable String context) {
        if (logger.isTraceEnabled()) {
            logger.trace("Handed out timestamps",
                    SafeArg.of("startTimestamp", start),
                    SafeArg.of("endTimestamp", end),
                    UnsafeArg.of("context", context));
        }
        updateLastSuccessfulRange(start, end);
    }

    public static void createdPersistentTimestamp(long timestamp, String source) {
        if (logger.isDebugEnabled()) {
            logger.debug("Created persistent timestamp",
                    SafeArg.of("timestamp", timestamp),
                    SafeArg.of("source", source));
        }
    }

    public static void willStoreNewUpperLimit(long proposedUpperLimit) {
        if (logger.isTraceEnabled()) {
            logger.trace("Attempting to store new upper timestamp limit",
                    SafeArg.of("proposedUpperLimit", proposedUpperLimit));
        }
    }

    public static void didStoreNewUpperLimit(long newUpperLimit, boolean success) {
        if (logger.isDebugEnabled()) {
            logger.debug("Stored new upper timestamp limit",
                    SafeArg.of("newUpperLimit", newUpperLimit),
                    SafeArg.of("success", success));
        }
    }

    private static void updateLastSuccessfulRange(long start, long end) {
        TimestampRange newRange = new TimestampRange(start, end);
        lastSuccessfulRange.updateAndGet(currentRange ->
            currentRange == null || newRange.compareTo(currentRange) > 0 ? newRange : currentRange
        );
    }

    public static TimestampRange getLastSuccessfulRange() {
        return lastSuccessfulRange.get();
    }

    public static void logTimestampServiceFailure(String operation, Throwable error) {
        logger.error("Timestamp service operation failed",
                SafeArg.of("operation", operation),
                UnsafeArg.of("error", error));

public ComponentInstance createInstance(Object instance) {
        BasicComponentInstance obj = constructComponentInstance(new ImmediateManagedReference(instance), true);
        obj.constructionFinished();
        return obj;
    }

public static Snapshot getSnapshot(ExecutorService service) {
        Preconditions.checkNotNull(service, "service");
        if (service instanceof ThreadPoolExecutor) {
            val tpe = (ThreadPoolExecutor) service;
            return new Snapshot(tpe.getQueue().size(), tpe.getActiveCount(), tpe.getPoolSize());
        } else if (service instanceof ForkJoinPool) {
            val fjp = (ForkJoinPool) service;
            return new Snapshot(fjp.getQueuedSubmissionCount(), fjp.getActiveThreadCount(), fjp.getPoolSize());
        } else {
            return null;
        }
    }

