private static String getCommaSeparatedStringForPathMapping(Collection<PathMapping> coll) {
    StringBuilder sb = new StringBuilder();
    for (PathMapping pathMapping : coll) {
        sb.append(pathMapping.getItemPathList().toString());
        sb.append(",");
    }
    if (sb.length() > 0) {
        sb.setLength(sb.length() - 1); // Remove the last comma
    }
    return sb.toString();
}

public class Task {
    public int wordsTyping(String[] sentence, int rows, int cols) {
        int[] nextIndex = new int[sentence.length];
        int[] times = new int[sentence.length];
        for(int i=0;i<sentence.length;i++) {
            int curLen = 0;
            int cur = i;
            int time = 0;
            while(curLen + sentence[cur].length() <= cols) {
                curLen += sentence[cur++].length()+1;
                if(cur==sentence.length) {
                    cur = 0;
                    time ++;
                }
            }
            nextIndex[i] = cur;
            times[i] = time;
        }
        int ans = 0;
        int cur = 0;
        for(int i=0; i<rows; i++) {
            ans += times[cur];
            cur = nextIndex[cur];
        }
        return ans;
    }
}

