public int findWays(int steps, int arrLen) {
    int[][] dp = new int[steps + 1][arrLen + 1];
    dp[0][0] = 1;
    final int MOD = 1000000007;
    for (int i = 1; i <= steps; i++) {
        for (int j = 1; j <= arrLen; j++) {
            dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j + 1] + dp[i - 1][j]) % MOD;
        }
    }
    return dp[steps][0];
}

public class Processor {
    public int numberOfBeams(String[] bank) {
        int m = bank.length;
        int n = bank[0].length();
        int[] rowDevices = new int[m];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (bank[i].charAt(j) == '1') {
                    rowDevices[i]++;
                }
            }
        }

        int totalBeams = 0;

        for (int i = 0; i < m; i++) {
            if (rowDevices[i] > 0) {
                for (int j = i + 1; j < m; j++) {
                    boolean hasDevice = false;
                    for (int k = i + 1; k < j; k++) {
                        if (rowDevices[k] > 0) {
                            hasDevice = true;
                            break;
                        }
                    }
                    if (rowDevices[j] > 0 &&!hasDevice) {
                        totalBeams += rowDevices[i] * rowDevices[j];
                    }
                }
            }
        }

        return totalBeams;
    }

    public static void main(String[] args) {
        Processor solution = new Processor();
        String[] bank = {"011001", "000000", "010100", "001000"};
        System.out.println(solution.numberOfBeams(bank)); // Output: 8
    }
}

