public class AsyncServer {

    private final DefaultListeningIOReactor ioReactor;
    private final IOEventHandlerFactory eventHandlerFactory;
    private final Set<ListenerEndpoint> endpoints;

    public AsyncServer(IOReactorConfig config, ThreadFactory threadFactory) throws IOReactorException {
        this.ioReactor = new DefaultListeningIOReactor(config, threadFactory);
        this.eventHandlerFactory = new MyIOEventHandlerFactory();
        this.endpoints = new HashSet<>();
    }

    public void listen(String host, int port) throws IOException {
        InetSocketAddress address = new InetSocketAddress(InetAddressUtils.resolve(host), port);
        Future<ListenerEndpoint> future = ioReactor.listen(address, eventHandlerFactory, new LoggingIOSessionListener());
        future.completed().addListener(new FutureCallback<ListenerEndpoint>() {
            @Override
            public void completed(ListenerEndpoint result) {
                endpoints.add(result);
                System.out.println("Listening on " + result.getAddress());
            }

            @Override
            public void failed(Exception ex) {
                System.err.println("Failed to listen on " + address + ": " + ex.getMessage());
            }

            @Override
            public void cancelled() {
                System.out.println("Listen operation cancelled on " + address);
            }
        });
    }

    public Set<ListenerEndpoint> getEndpoints() {
        return new HashSet<>(endpoints);
    }

    public void shutdown() throws IOException {
        ioReactor.gracefulShutdown(TimeValue.ofSeconds(5));
        ioReactor.awaitShutdown(TimeValue.ofSeconds(10));
    }

    private static class MyIOEventHandlerFactory implements IOEventHandlerFactory {
        @Override
        public BaseIOEventHandler createHandler(final IOSession session) {
            return new LoggingIOSessionDecorator(session, new MyIOEventHandler());
        }
    }

    private static class MyIOEventHandler extends AbstractIOEventHandler {
        @Override
        public void connected(final IOSession session) {

