        String taskFormat = "MMMM d yyyy h:mma zzz";
        System.out.println("Input:             " + taskDate);
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern(taskFormat, Locale.ENGLISH);
        LocalDateTime ldt = LocalDateTime.parse(taskDate, formatter);
        ldt = ldt.plusHours(12);
