class Task {
    public String[] findWords(String[] words) {
        String[] rows = new String[] {"qwertyuiopQWERTYUIOP", "asdfghjklASDFGHJKL",
            "zxcvbnmZXCVBNM"};

        List<String> list = new ArrayList();

        for(String word : words){
            for(String row : rows){
                boolean isOnThisRow = true;
                for(char c : word.toCharArray()){
                    if(row.indexOf(c) < 0){
                        isOnThisRow = false;
                        break;
                    }
                }

                if(isOnThisRow){
                    list.add(word);
                    break;
                }
            }
        }

        return list.toArray(new String[list.size()]);

    }
}

