import java.util.Currency;

public class CurrencyTransform implements Transform<Currency> {

    /**
     * Converts a string representation of a currency into a Currency object.
     *
     * @param symbol the string representation of the currency (e.g., "USD").
     * @return the corresponding Currency object.
     * @throws IllegalArgumentException if the symbol is not a valid currency code.
     */
    @Override
    public Currency read(String symbol) {
        if (symbol == null || symbol.trim().isEmpty()) {
            throw new IllegalArgumentException("Currency symbol cannot be null or empty.");
        }
        return Currency.getInstance(symbol.trim());
    }

    /**
     * Converts a Currency object into its string representation.
     *
     * @param currency the Currency object to be converted.
     * @return the string representation of the currency (e.g., "USD").
     * @throws IllegalArgumentException if the currency object is null.
     */
    @Override
    public String write(Currency currency) {
        if (currency == null) {
            throw new IllegalArgumentException("Currency object cannot be null.");
        }
        return currency.toString();
    }

    /**
     * Interface defining the transformation methods.
     *
     * @param <T> the type of object to be transformed.
     */
    public interface Transform<T> {
        T read(String value);
        String write(T value);
    }

    // Example usage
    public static void main(String[] args) {
        CurrencyTransform transformer = new CurrencyTransform();

        // Deserialization example
        String currencyCode = "EUR";
        Currency currency = transformer.read(currencyCode);
        System.out.println("Deserialized Currency: " + currency.getCurrencyCode());

        // Serialization example
        String serializedCurrency = transformer.write(currency);
        System.out.println("Serialized Currency: " + serializedCurrency);
    }
}

import java.io.*;
import java.util.*;

public class Helper {

    static final int MOD = (int)1e9 + 7;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        int t = Integer.parseInt(br.readLine());

        while(t-- > 0) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());

            long ans = 1;
            for(int i = 0; i < k; i++) {
                ans = (ans * n) % MOD;
            }

            pw.println(ans);
        }

        pw.close();
    }
}

