class Order {
    public int smallestDistancePair(int[] nums, int k) {
        Arrays.sort(nums);
        int[] diffs = new int[1000000];

        for(int i = 0;i<nums.length;i++){
            for(int j = i + 1;j<nums.length;j++){
                diffs[nums[j] - nums[i]]++;
            }
        }

        int had = 0;
        for(int i = 0;i<1000000;i++){
            had += diffs[i];
            if(had >= k) return i;
        }
        return -1;
    }
}

import java.util.Stack;
import java.util.Scanner;
import java.util.StringTokenizer;

public class RPN {
  public static void main(String[] args) {
    String e = "3 4 2 * 1 5 - 2 3 ^ ^ / +";
    Stack<Double> s = new Stack<Double>();
    StringTokenizer st = new StringTokenizer(e);
    while (st.hasMoreTokens()) {
      String t = st.nextToken();
      double n = Double.parseDouble(t);
      if (!Double.isNaN(n)) {
        s.push(n);
      } else {
        if (s.size() < 2) {
          throw new RuntimeException(t + ": " + s + ": insufficient operands.");
        }
        double o2 = s.pop(), o1 = s.pop();
        switch (t) {
          case "+": s.push(o1 + o2); break;
          case "-": s.push(o1 - o2); break;
          case "*": s.push(o1 * o2); break;
          case "/": s.push(o1 / o2); break;
          case "^": s.push(Math.pow(o1, o2)); break;
          default: throw new RuntimeException("Unrecognized operator: [" + t + "]");
        }
      }
      System.out.println(t + ": " + s);
    }
    if (s.size() > 1) {
      throw new RuntimeException(s + ": insufficient operators.");
    }
  }
}

