class Account {
    public int[][] restoreMatrix(int[] rowSum, int[] colSum) {
        int n=rowSum.length;
        int m=colSum.length;
        int[][] a=new int[n][m];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                int tmp=rowSum[i];
                int tmp1=colSum[j];
                a[i][j]=Math.min(tmp,tmp1);
                rowSum[i]-=a[i][j];
                colSum[j]-=a[i][j];
            }
        }
        return a;
    }
}

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;

public class FileEncrypter {
    public static void main(String[] args) {
        // Prompt the user for input and output file names
        String inputFileName = System.console().readLine("Enter input file name: ");
        String outputFileName = System.console().readLine("Enter output file name: ");

        try (FileInputStream input = new FileInputStream(inputFileName);
             FileOutputStream output = new FileOutputStream(outputFileName)) {

            // Read the input file byte by byte and write the encrypted version to the output file
            int b;
            while ((b = input.read()) != -1) {
                output.write(b + 5);
            }
        } catch (IOException e) {
            System.err.println("Error: " + e.getMessage());
        }
    }
}

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;

public class SimpleImage {

    // Default constants
    private static final int DEFAULT_WIDTH = 100;
    private static final int DEFAULT_HEIGHT = 100;
    private static final Color DEFAULT_COLOR = Color.GRAY;
    private static final String DEFAULT_NAME = "DefaultImage";

    // Variables for image management
    private String fileName;
    private BufferedImage image;
    private Dimension size;

    // Constructor for creating an image with specified dimensions and fill color
    public SimpleImage(int width, int height, Color fillColor) {
        this.fileName = DEFAULT_NAME;
        this.size = new Dimension(width, height);
        createNewImage(width, height, fillColor);
    }

    // Constructor for loading an image from a file
    public SimpleImage(String filePath) {
        this.fileName = extractFileName(filePath);
        readImageFromFile(filePath);
    }

    // Method to extract the file's name from the file path
    public String getName() {
        return fileName;
    }

    // Method to retrieve the dimensions of the image
    public Dimension getSize() {
        return new Dimension(size);
    }

    // Method to return the color at a specific pixel coordinate
    public Color getColor(int x, int y) {
        if (!isWithinBounds(x, y)) {
            throw new IllegalArgumentException("Coordinates (" + x + ", " + y + ") are out of image bounds.");
        }
        int rgb = image.getRGB(x, y);
        return new Color(rgb, true);
    }

    // Method to draw the image onto a provided Graphics context
    public void paint(Graphics g, int x, int y) {
        if (g != null && image != null) {
            g.drawImage(image, x, y, size.width, size.height, null);
        }
    }

    // Private helper method to check if coordinates are within image boundaries
    private boolean isWithinBounds(int x, int y) {
        return x >= 0 && y >= 0 && x < size.width && y < size.height;
    }

    // Private helper method to create a new image with a specific fill color
    private void createNewImage(int width, int height, Color fillColor) {
        image = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        size = new Dimension(width, height);
        for (int i = 0; i < width; i++) {
            for (int j = 0; j < height; j++) {
                image.setRGB(i, j, fillColor.getRGB());
            }
        }
    }

