import java.io.IOException;

public class CopyStreamException extends IOException {

    private static final long serialVersionUID = -329458362737828274L;

    private final long totalBytesTransferred;
    private final IOException ioException;

    /**
     * Creates a new CopyStreamException instance.
     *
     * @param message The exception message.
     * @param totalBytesTransferred The number of bytes transferred before the exception occurred.
     * @param ioException The IOException that caused the stream copy to fail.
     */
    public CopyStreamException(String message, long totalBytesTransferred, IOException ioException) {
        super(message);
        this.totalBytesTransferred = totalBytesTransferred;
        this.ioException = ioException;
        initCause(ioException);
    }

    /**
     * Returns the total number of bytes transferred before the stream copy failed.
     *
     * @return The total number of bytes transferred.
     */
    public long getTotalBytesTransferred() {
        return totalBytesTransferred;
    }

    /**
     * Returns the IOException that caused the stream copy to fail.
     *
     * @return The IOException that caused the stream copy to fail.
     */
    public IOException getIOException() {
        return ioException;
    }

    /**
     * Gets the cause of this throwable.
     *
     * @return the cause of this throwable or {@code null} if the
     *         cause is nonexistent or unknown.
     */
    @Override
    public Throwable getCause() {
        return ioException;
    }
}

