import java.util.Random;

/*
 * Bu kod, minimum 8 karakter ve maksimum 12 karakter iceren bir rastgele sifre olusturur.
 * Sifre en az bir buyuk harf, bir rakam ve bir ozel karakter icermektedir:
 */

public class SifreUreteci {

    public static String sifreUret() {

        String buyukHarfler = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"; // Buyuk harfler
        String rakamlar = "0123456789"; // Rakamlar
        String ozelKarakterler = "!@#$%^&*()_+-=[]{}|;':\"<>,.?/\\"; // Ozel karakterler

        Random rastgele = new Random();

        int uzunluk = 8 + rastgele.nextInt(5); // 8 ile 12 arasinda rastgele bir uzunluk belirlenir
        String sifre = "";

        // Her bir karakter grubundan rastgele bir karakter secilir ve sifreye eklenir
        sifre += buyukHarfler.charAt(rastgele.nextInt(buyukHarfler.length()));
        sifre += rakamlar.charAt(rastgele.nextInt(rakamlar.length()));
        sifre += ozelKarakterler.charAt(rastgele.nextInt(ozelKarakterler.length()));

        // Geriye kalan karakterler rastgele secilir
        for (int i = 0; i < uzunluk - 3; i++) {
            String karakterler = buyukHarfler + rakamlar + ozelKarakterler + buyukHarfler.toLowerCase();
            sifre += karakterler.charAt(rastgele.nextInt(karakterler.length()));
        }

        return stringKaristir(sifre); // Sifreyi karistir ve dondur
    }

    public static String stringKaristir(String sifre) {

        char[] dizi = sifre.toCharArray();
        Random rastgele = new Random();
        for (int i = dizi.length - 1; i > 0; i--) {
            int index = rastgele.nextInt(i); // Rastgele bir index sec
            char temp = dizi[index];
            dizi[index] = dizi[i];
            dizi[i] = temp;
        }
        return new String(dizi);
    }

    public static void main(String[] args) {
        System.out.println(sifreUret()); // Rastgele sifreyi yazdir
    }
}

import com.intellij.ide.util.treeView.smartTree.ActionPresentation;
import com.intellij.ide.util.treeView.smartTree.ActionPresentationData;
import com.intellij.ide.util.treeView.smartTree.Sorter;
import com.intellij.navigation.ItemPresentation;
import com.intellij.psi.*;
import org.jetbrains.annotations.NonNls;
import org.jetbrains.annotations.NotNull;

import java.util.Comparator;

public class KindSorter implements Sorter {
  @NonNls public static final String ID = "KIND";
  private final boolean isPopup;

  public static final KindSorter INSTANCE = new KindSorter(false);
  public static final KindSorter POPUP_INSTANCE = new KindSorter(true);

  private KindSorter(boolean isPopup) {
    this.isPopup = isPopup;
  }

  private static final Comparator<Object> COMPARATOR = (o1, o2) -> {
    int weight1 = getWeight(o1);
    int weight2 = getWeight(o2);
    return weight1 - weight2;
  };

  private static int getWeight(Object element) {
    if (element instanceof PsiAnonymousClass) return 1;
    if (element instanceof PsiClass) {
      if (((PsiClass) element).getName() == null) return 2;  //anonymous
      return 2 + (INSTANCE.isPopup ? 1 : 0);
    }
    if (element instanceof PsiClassInitializer) return 3;
    if (element instanceof SuperTypesGrouper.SuperTypesGroup) return 4;
    if (element instanceof PsiMethod) {
      PsiMethod method = (PsiMethod) element;
      if (method.isConstructor()) return 5;
      return 6;
    }
    if (element instanceof PropertyGrouper.PropertyGroup) return 7;
    return 8; //PsiField
  }

  @Override
  @NotNull
  public Comparator getComparator() {
    return COMPARATOR;
  }

  @Override
  public boolean isVisible() {
    return true;
  }

  @Override
  @NotNull
  public ActionPresentation getPresentation() {
    return new ActionPresentationData("Sort by Kind", "Sort elements by their type", com.intellij.icons.AllIcons.ObjectBrowser.Sort);
  }

  @Override
  @NotNull
  public String getName() {
    return ID;
  }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
 
public class DateFinder {
    public static void main(String[] args) {
        List<List<String>> dates = Arrays.asList(
                Arrays.asList("May", "15"),
                Arrays.asList("May", "16"),
                Arrays.asList("May", "19"),
                Arrays.asList("June", "17"),
                Arrays.asList("June", "18"),
                Arrays.asList("July", "14"),
                Arrays.asList("July", "16"),
                Arrays.asList("August", "14"),
                Arrays.asList("August", "15"),
                Arrays.asList("August", "17"));
        System.out.println(dates.size() + " remaining\n");
        List<List<String>> uniqueMonths = dates.stream()
               .collect(Collectors.groupingBy(l -> l.get(1)))
               .entrySet().stream()
               .filter(e -> e.getValue().size() == 1)
               .map(e -> e.getValue().get(0))
               .collect(Collectors.toList());
        dates = dates.stream()
               .filter(l ->!uniqueMonths.contains(l.get(0)))
               .collect(Collectors.toList());
        System.out.println(dates.size() + " remaining\n");
        dates = dates.stream()
               .collect(Collectors.groupingBy(l -> l.get(1)))
               .entrySet().stream()
               .filter(e -> e.getValue().size() == 1)
               .map(e -> e.getValue().get(0))
               .collect(Collectors.toList());
        System.out.println(dates.size() + " remaining\n");
        dates = dates.stream()
               .collect(Collectors.groupingBy(l -> l.get(0)))
               .entrySet().stream()
               .filter(e -> e.getValue().size() == 1)
               .map(e -> e.getValue().get(0))
               .collect(Collectors.toList());
        System.out.println(dates);
    }
}

public int nextGreaterElement(int n) {
        char [] chars = (n + "").toCharArray();
        int i, j;

        for (i = chars.length - 2; i >= 0; i--) {
            if (chars[i] < chars[i + 1]) {
                break;
            }
        }

        if (i == -1) return -1;

        else {
            for (j = chars.length - 1; j > i; j--) {
                if (chars[j] > chars[i]) {
                    break;
                }
            }
            swap(chars, i, j);
        }
        reverse(chars, i + 1);
        try {
            return Integer.parseInt(new String(chars));
        } catch (Exception e) {
            return -1;
        }
    }

    private void reverse(char [] arr, int start) {
        int i = start, j = arr.length - 1;
        while (i < j) {
            swap(arr, i, j);
            i++;
            j--;
        }
    }

    private void swap(char [] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

