import org.lisoft.lsml.math.FastFactorial;

import java.math.BigDecimal;
import java.math.BigInteger;

import static org.lisoft.lsml.math.FastFactorial.*;

/**
 * This class models a binomial distribution
 *
 */
public class BinomialDistribution implements Distribution {
    private final double p;
    private final int n;

    public static long nChooseK(int n, long aK) {
        if(n-aK < aK){
            return nChooseK(n, n-aK);
        }
        long ans = 1;
        for (int kk = 0; kk < aK; ++kk) {
            ans = ans * (n - kk) / (kk + 1);
        }
        return ans;
    }

    public static BigInteger nChooseKLargeNumbers(int n, int aK) {
        if(n-aK < aK){
            return nChooseKLargeNumbers(n, n-aK);
        }
        return factorial(n).divide(factorial(aK).multiply(factorial(n-aK)));

        /*
        BigInteger ans = BigInteger.valueOf(1);
        for (int kk = 0; kk < aK; ++kk) {
            ans = ans.multiply(BigInteger.valueOf(n - kk)).divide(BigInteger.valueOf(kk + 1));
        }
        return ans;*/
    }

    public BinomialDistribution(double aP, int aN) {
        p = aP;
        n = aN;
    }

    @Override
    public double pdf(double aX) {
        long k = Math.round(aX);
        return nChooseK(n, k) * Math.pow(p, k) * Math.pow(1.0 - p, n - k);
    }

    public static double pdf(int aK, int aN, double aP){
        BigDecimal Pk = BigDecimal.valueOf(aP).pow(aK);
        BigDecimal PnotK = BigDecimal.valueOf(1.0-aP).pow(aN-aK);
        BigDecimal permutations = new BigDecimal(nChooseKLargeNumbers(aN, aK));
        return permutations.multiply(Pk).multiply(PnotK).doubleValue();
    }

    @Override
    public double cdf(double aX) {
        double ans = 0;
        final long k = (long) (aX + Math.ulp(aX)); // Accept anything within truncation error of k as k.
        for (int i = 0; i <= k; ++i) {
            ans += pdf(i);
        }
        return ans;
    }

}

import java.util.Scanner;

public class NextMonthInterest {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Get input from user
        System.out.print("Enter the balance: ");
        double balance = scanner.nextDouble();
        System.out.print("Enter the annual interest rate: ");
        double annualInterestRate = scanner.nextDouble();

        // Calculate interest for next month
        double monthlyInterestRate = annualInterestRate / 1200.0;
        double interest = balance * monthlyInterestRate;

        // Output result
        System.out.printf("The interest for the next month is $%.2f", interest);
    }
}

public class Circle2DTest {
    public static void main(String[] args) {
        // Create a Circle2D object with center at (2, 2) and radius 5.5
        Circle2D c1 = new Circle2D(2, 2, 5.5);

        // Display area and perimeter of c1
        System.out.println("Area of c1: " + c1.getArea());
        System.out.println("Perimeter of c1: " + c1.getPerimeter());

        // Check if c1 contains the point (3, 3)
        System.out.println("c1 contains point (3, 3): " + c1.contains(3, 3));

        // Create a new Circle2D object with center at (4, 5) and radius 10.5
        Circle2D c2 = new Circle2D(4, 5, 10.5);

        // Check if c1 contains c2
        System.out.println("c1 contains c2: " + c1.contains(c2));

        // Create a new Circle2D object with center at (3, 5) and radius 2.3
        Circle2D c3 = new Circle2D(3, 5, 2.3);

        // Check if c1 overlaps c3
        System.out.println("c1 overlaps c3: " + c1.overlaps(c3));
    }
}

class Cache {
    public boolean buddyStrings(String A, String B) {
        if(A.length() != B.length()){
            return false;
        }
        ArrayList<Integer> diff = new ArrayList<>();
        for(int i = 0; i < A.length(); ++i){
            if(A.charAt(i) != B.charAt(i)){
                diff.add(i);
            }
        }
        if(diff.size() == 2){
            return A.charAt(diff.get(0)) == B.charAt(diff.get(1)) && A.charAt(diff.get(1)) == B.charAt(diff.get(0));
        }
        if(diff.size() == 0){
            HashSet<Character> s = new HashSet<>();
            for(Character c : A.toCharArray()){
                if(s.contains(c)){
                    return true;
                }
                s.add(c);
            }
        }
        return false;
    }
}

import java.awt.Color;
import java.awt.Graphics;
 
import javax.swing.JFrame;
import javax.swing.JPanel;
 
public class Langton extends JFrame{
    private JPanel planePanel;
    private static final int ZOOM = 4;
 
    public Langton(final boolean[][] plane){
        planePanel = new JPanel(){
            @Override
            public void paint(Graphics g) {
                for(int y = 0; y < plane.length;y++){
                    for(int x = 0; x < plane[0].length;x++){
                        g.setColor(plane[y][x] ? Color.BLACK : Color.WHITE);
                        g.fillRect(x * ZOOM, y * ZOOM, ZOOM, ZOOM);
                    }
                }
                //mark the starting point
                g.setColor(Color.GREEN);
                g.fillRect(plane[0].length / 2 * ZOOM,
                           plane.length / 2 * ZOOM, ZOOM/2, ZOOM/2);
            }
        };
        planePanel.setSize(plane[0].length - 1, plane.length - 1);
        add(planePanel);
        setSize(ZOOM * plane[0].length, ZOOM * plane.length + 30);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setVisible(true);
    }
 
    public static void main(String[] args){
        new Langton(runAnt(100, 100));
    }
 
    private static boolean[][] runAnt(int height, int width){
        boolean[][] plane = new boolean[height][width];
        int antX = width/2, antY = height/2;//start in the middle-ish
        int xChange = 0, yChange = -1; //start moving up
        while(antX < width && antY < height && antX >= 0 && antY >= 0){
            if(plane[antY][antX]){
                //turn left
                if(xChange == 0){ //if moving up or down
                    xChange = yChange;
                    yChange = 0;
                }else{ //if moving left or right
                    yChange = -xChange;
                    xChange = 0;
                }
            }else{
                //turn right
                if(xChange == 0){ //if moving up or down
                    xChange = -yChange;
                    yChange = 0;
                }else{ //if moving left or right
                    yChange = xChange;
                    xChange = 0;
                }
            }
            plane[antY][antX] = !plane[antY][antX];
            antX += xChange;
            antY += yChange;
        }
        return plane;
    }
}

private double determineAlphaMin(int n, double[] alpha_min, HyperBoundingBox interval) {
    // Sort the alpha values
    Arrays.sort(alpha_min);

    // Check if n is within the bounds of the array
    if (n >= 0 && n < alpha_min.length) {
        return alpha_min[n];
    } else {
        // Handle the case where n is out of bounds
        throw new IllegalArgumentException("n is out of bounds");
    }
}

@SuppressWarnings("unchecked")
    public static <T> T[] cloneArray(T[] original) {
        if (original == null) {
            return null;
        }
        try {
            Class<?> clazz = original.getClass().getComponentType();
            T[] copy = (T[]) Array.newInstance(clazz, original.length);
            if (copy.length != 0) {
                Constructor<T> copyConstructor = (Constructor<T>) clazz.getConstructor(clazz);
                int i = 0;
                for (T t : original) {
                    copy[i++] = copyConstructor.newInstance(t);
                }
            }
            return copy;
        } catch (Exception e) {
            throw new RuntimeException("Cannot copy array. Does its type have a copy-constructor? " + original, e);
        }
    }

