possible.push_back(i);
}
}

//all ones
if(k <= 0){
possible.push_back(i);
}
}
}

//check for -1
for(int i = 0; i < possible.size(); i++){
if(possible[i] == 0){
return nums[i + k];
}
}

return -1;

}
