class Student:
    def addOneRow(self, root: TreeNode, val: int, depth: int) -> TreeNode:
        if depth == 1:
            new_tree = TreeNode(val, root,None)
            return new_tree
        stack = []
        current_depth = 1
        stack.append(root)
        while (stack):
            top = stack.pop()
            current_depth+=1
            if current_depth>2 and current_depth<depth:
                obj = TreeNode(val, None,None)
                obj.val = val
                obj.left = top.left
                obj.right = top.right
                top.left = obj
                top.right = obj
            else:
                if top.left:
                    stack.insert(0,top.left)
                if top.right:
                    stack.insert(0,top.right)
        return root
