public class NegativeBaseNumbers {
    private static final String DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
 
    private static String encodeNegativeBase(long n, int b) {
        if (b < -62 || b > -1) {
            throw new IllegalArgumentException("b");
        }
        if (n == 0) {
            return "0";
        }
        StringBuilder output = new StringBuilder();
        long nn = n;
        while (nn!= 0) {
            int rem = (int)(nn % b);
            nn /= b;
            if (rem < 0) {
                nn++;
                rem -= b;
            }
            output.append(DIGITS.charAt(rem));
        }
        return new StringBuilder(output.toString()).reverse().toString();
    }
 
    private static long decodeNegativeBase(String ns, int b) {
        if (b < -62 || b > -1) {
            throw new IllegalArgumentException("b");
        }
        if (ns.equals("0")) {
            return 0;
        }
        long total = 0;
        long bb = 1;
        for (int i = ns.length() - 1; i >= 0; i--) {
            char c = ns.charAt(i);
            total += DIGITS.indexOf(c) * bb;
            bb *= b;
        }
        return total;
    }
 
    public static void main(String[] args) {
        List<Tuple<Long, Integer>> nbl = new ArrayList<>();
        nbl.add(new Tuple<>(10L, -2));
        nbl.add(new Tuple<>(146L, -3));
        nbl.add(new Tuple<>(15L, -10));
        nbl.add(new Tuple<>(-34025238427L, -62));
        for (Tuple<Long, Integer> p : nbl) {
            String ns = encodeNegativeBase(p.getItem1(), p.getItem2());
            System.out.printf("%12d encoded in base %3d = %s%n", p.getItem1(), p.getItem2(), ns);
            long n = decodeNegativeBase(ns, p.getItem2());
            System.out.printf("%12d decoded in base %3d = %d%n", p.getItem1(), p.getItem2(), n);
            System.out.println();
        }
    }
}
 
