import jetbrains.jetpad.base.Registration;
import jetbrains.jetpad.mapper.Mapper;
import jetbrains.jetpad.mapper.MapperFactory;
import jetbrains.jetpad.mapper.Synchronizer;
import jetbrains.jetpad.model.collections.list.ObservableList;

import java.util.ArrayList;
import java.util.List;

public class ObservableCollectionRoleSynchronizer<SourceT, TargetT, MapperT extends Mapper<? super SourceT, ? extends TargetT>> implements Synchronizer {
    private final ObservableList<SourceT> mySource;
    private final List<TargetT> myTarget;
    private final MapperFactory<SourceT, MapperT> myMapperFactory;
    private Registration myCollectionRegistration;
    private final List<MapperT> myMappers = new ArrayList<>();

    public ObservableCollectionRoleSynchronizer(ObservableList<SourceT> source, List<TargetT> target, MapperFactory<SourceT, MapperT> mapperFactory) {
        mySource = source;
        myTarget = target;
        myMapperFactory = mapperFactory;
    }

    @Override
    public void onAttach() {
        myTarget.clear();
        for (SourceT sourceItem : mySource) {
            MapperT mapper = createMapper(sourceItem);
            myMappers.add(mapper);
            myTarget.add(mapper.getTarget());
        }

        myCollectionRegistration = mySource.addListener(new jetbrains.jetpad.model.collections.list.ObservableListListener<SourceT>() {
            @Override
            public void onItemAdded(int index, SourceT item) {
                MapperT mapper = createMapper(item);
                myMappers.add(index, mapper);
                myTarget.add(index, mapper.getTarget());
            }

            @Override
            public void onItemRemoved(int index, SourceT item) {
                MapperT mapper = myMappers.remove(index);
                myTarget.remove(index);
            }
        });
    }

    @Override
    public void onDetach() {
        if (myCollectionRegistration != null) {
            myCollectionRegistration.remove();
            myCollectionRegistration = null;
        }
        myTarget.clear();
        myMappers.clear();
    }

    protected MapperT createMapper(SourceT sourceItem) {
        return myMapperFactory.createMapper(sourceItem);
    }
}

