public class Student {
    private class Complex {
        int real;
        int image;

        public Complex(String comStr) {
            String[] tokens = comStr.split("\\+");
            real = Integer.parseInt(tokens[0]);
            image = Integer.parseInt(tokens[1].substring(0, tokens[1].length() - 1));
        }

        public Complex(int real, int image) {
            this.real = real;
            this.image = image;
        }

        public Complex multiply(Complex b) {
            // real
            int r = this.real * b.real - this.image * b.image;

            // image
            int i = this.real * b.image + b.real * this.image;
            return new Complex(r, i);
        }

        public String toString() {
            return real + "+" + image + "i";
        }
    }

    public String complexNumberMultiply(String a, String b) {
        Complex ac = new Complex(a);
        Complex bc = new Complex(b);
        System.out.println(ac);
        System.out.println(bc);

        return ac.multiply(bc).toString();
    }
}

import net.minecraft.client.renderer.Tessellator;
import net.minecraft.client.renderer.tileentity.TileEntitySpecialRenderer;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.util.ResourceLocation;
import net.minecraft.world.World;
import org.lwjgl.opengl.GL11;

public class TileEntitySailRenderer extends TileEntitySpecialRenderer {
    private final SailModel model = new SailModel();
    private final ResourceLocation texture = new ResourceLocation("Ported_Blocks:textures/texturemaps/Sail_HD.png");

    @Override
    public void renderTileEntityAt(TileEntity tileEntity, double x, double y, double z, float partialTick) {
        if (tileEntity == null || tileEntity.isInvalid()) return;

        GL11.glPushMatrix();
        GL11.glEnable(GL11.GL_TEXTURE_2D);
        GL11.glEnable(GL11.GL_LIGHTING);
        GL11.glTranslated(x + 0.5, y + 1.5, z + 0.5);
        GL11.glRotatef(180.0F, 1.0F, 0.0F, 0.0F);

        int meta = tileEntity.getBlockMetadata() & 3;
        float rotation = meta * 90.0F;
        GL11.glRotatef(rotation, 0.0F, 1.0F, 0.0F);

        adjustLightFixture(tileEntity.getWorldObj(), tileEntity.xCoord, tileEntity.yCoord, tileEntity.zCoord);
        bindTexture(texture);

        GL11.glPushMatrix();
        GL11.glScalef(1.0F, 1.0F, 1.0F);
        model.render();
        GL11.glPopMatrix();

        GL11.glDisable(GL11.GL_LIGHTING);
        GL11.glDisable(GL11.GL_TEXTURE_2D);
        GL11.glPopMatrix();
        GL11.glColor4f(1.0F, 1.0F, 1.0F, 1.0F);
    }

    private void adjustLightFixture(World world, int x, int y, int z) {
        if (world == null) return;

        int lightValue = world.getLightBrightnessForSkyBlocks(x, y, z, 0);
        Tessellator.instance.setBrightness(lightValue);

        float skyLight = (lightValue >> 16) / 32768.0F;
        float blockLight = (lightValue & 0xFFFF) / 32768.0F;
        float brightness = Math.max(skyLight, blockLight);

        GL11.glLightModel(GL11.GL_LIGHT_MODEL_AMBIENT,
            getBuffer(brightness * 0.2F, brightness * 0.2F, brightness * 0.2F, 1.0F));
        GL11.glLight(GL11.GL_LIGHT0, GL11.GL_POSITION,
            getBuffer(0.0F, 1.0F, 0.0F, 0.0F));
    }

    private FloatBuffer getBuffer(float a, float b, float c, float d) {
        ByteBuffer bb = ByteBuffer.allocateDirect(16);
        bb.order(ByteOrder.nativeOrder());
        FloatBuffer fb = bb.asFloatBuffer();
        fb.put(a).put(b).put(c).put(d);
        fb.flip();
        return fb;
    }
}

import java.util.Arrays;
 
public class BellTriangle {
 
    private static int bellIndex(int row, int col) {
        return row * (row - 1) / 2 + col;
    }
 
    private static int getBell(int[] bellTri, int row, int col) {
        int index = bellIndex(row, col);
        return bellTri[index];
    }
 
    private static void setBell(int[] bellTri, int row, int col, int value) {
        int index = bellIndex(row, col);
        bellTri[index] = value;
    }
 
    private static int[] bellTriangle(int n) {
        int length = n * (n + 1) / 2;
        int[] tri = new int[length];
        int i, j;
 
        setBell(tri, 1, 0, 1);
        for (i = 2; i <= n; ++i) {
            setBell(tri, i, 0, getBell(tri, i - 1, i - 2));
            for (j = 1; j < i; ++j) {
                int value = getBell(tri, i, j - 1) + getBell(tri, i - 1, j - 1);
                setBell(tri, i, j, value);
            }
        }
 
        return tri;
    }
 
    public static void main(String[] args) {
        final int rows = 15;
        int[] bt = bellTriangle(rows);
        int i, j;
 
        System.out.println("First fifteen Bell numbers:");
        for (i = 1; i <= rows; ++i) {
            System.out.printf("%2d: %d\n", i, getBell(bt, i, 0));
        }
 
        System.out.println("\nThe first ten rows of Bell's triangle:");
        for (i = 1; i <= 10; ++i) {
            System.out.print(getBell(bt, i, 0));
            for (j = 1; j < i; ++j) {
                System.out.printf(", %d", getBell(bt, i, j));
            }
            System.out.println();
        }
    }
}

