public class JarWriter {

    public static void packToJar(Path rootDir, OutputStream output) throws IOException {
        Manifest manifest = createManifest();
        try (JarOutputStream jos = new JarOutputStream(output, manifest)) {
            processDirectory(rootDir, jos, rootDir);
        }
    }

    private static Manifest createManifest() {
        Manifest manifest = new Manifest();
        manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
        return manifest;
    }

    private static void processDirectory(Path currentPath, JarOutputStream jos, Path rootDir) throws IOException {
        if (Files.isRegularFile(currentPath)) {
            addFileEntry(currentPath, jos, rootDir);
        } else {
            addDirectoryEntry(currentPath, jos, rootDir);
            try (DirectoryStream<Path> dirStream = Files.newDirectoryStream(currentPath)) {
                for (Path child : dirStream) {
                    processDirectory(child, jos, rootDir);
                }
            }
        }
    }

    private static void addDirectoryEntry(Path dirPath, JarOutputStream jos, Path rootDir) throws IOException {
        String entryName = getRelativePath(dirPath, rootDir);
        if (!entryName.isEmpty()) {
            if (!entryName.endsWith("/")) entryName += "/";
            JarEntry entry = new JarEntry(entryName);
            entry.setTime(Files.getLastModifiedTime(dirPath).toMillis());
            jos.putNextEntry(entry);
            jos.closeEntry();
        }
    }

    private static void addFileEntry(Path filePath, JarOutputStream jos, Path rootDir) throws IOException {
        String entryName = getRelativePath(filePath, rootDir);
        JarEntry entry = new JarEntry(entryName);
        entry.setTime(Files.getLastModifiedTime(filePath).toMillis());

        jos.putNextEntry(entry);
        try (BufferedInputStream bis = new BufferedInputStream(Files.newInputStream(filePath))) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = bis.read(buffer)) != -1) {
                jos.write(buffer, 0, bytesRead);
            }
        }
        jos.closeEntry();
    }

