import org.springframework.beans.factory.annotation.Autowired;
import org.summerb.easycrud.api.EasyCrudService;
import org.summerb.easycrud.api.EasyCrudServiceResolver;
import org.summerb.easycrud.api.dto.EntityChangedEvent;
import org.summerb.easycrud.api.dto.HasId;
import org.summerb.easycrud.api.relations.DataSet;
import org.summerb.easycrud.api.relations.DataTable;
import org.summerb.easycrud.impl.dao.mysql.integration.DataSetUpdaterOnEntityChangedEvent;
import org.summerb.methodCapturers.PropertyNameObtainer;

public class DataSetUpdaterOnEntityChangedEventImpl
    implements DataSetUpdaterOnEntityChangedEvent, PropertyNameObtainer {
  @Autowired protected EasyCrudServiceResolver easyCrudServiceResolver;

  @SuppressWarnings({"unchecked", "rawtypes"})
  @Override
  public void updateDataSet(DataSet dataSet, EntityChangedEvent<?> event) {
    if (!(event.getPayload() instanceof HasId)) {
      return;
    }

    HasId changedObj = (HasId) event.getPayload();
    EasyCrudService service =
        easyCrudServiceResolver.resolveByDtoClass((Class) changedObj.getClass());
    String entityTypeMessageCode = service.getEntityTypeMessageCode();

    if (!dataSet.containsKey(entityTypeMessageCode)) {
      return;
    }

    DataTable dataTable = dataSet.get(entityTypeMessageCode);
    if (event.getChangeType() == EntityChangedEvent.ChangeType.REMOVED) {
      dataTable.remove(changedObj.getId());
    } else {
      dataTable.put(changedObj.getId(), changedObj);
    }
  }

  public EasyCrudServiceResolver getEasyCrudServiceResolver() {
    return easyCrudServiceResolver;
  }

  public void setEasyCrudServiceResolver(EasyCrudServiceResolver easyCrudServiceResolver) {
    this.easyCrudServiceResolver = easyCrudServiceResolver;
  }

  @Override
  public String getPropertyName(int arg0) {
    return null;
  }
}

