        return bottomRight.getY();
    }

@Override
    public Set<DatabaseObject> getAffectedDatabaseObjects(Database database) {
        if (this.generateStatementsVolatile(database)) {
            return new HashSet<>();
        }
        Set<DatabaseObject> affectedObjects = new HashSet<>();
        SqlStatement[] statements = generateStatements(database);
        if (statements != null) {
            for (SqlStatement statement : statements) {
                affectedObjects.addAll(SqlGeneratorFactory.getInstance()
                    .getAffectedDatabaseObjects(statement, database));
            }
        }
        return affectedObjects;
    }

java
public int similarPairs(String[] words) {
    Map<String, Integer> counter = new HashMap<>();
    for (String word : words) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        counter.put(String.valueOf(chars), counter.getOrDefault(String.valueOf(chars), 0) + 1);
    }
    int res = 0;
    for (Map.Entry<String, Integer> item : counter.entrySet()) {
        int num = item.getValue();
        res += num * (num - 1) / 2;
    }
    return res;
}

