import java.util.List;
import javax.ws.rs.core.Response;

import org.ovirt.engine.api.model.StorageConnection;
import org.ovirt.engine.api.model.StorageConnections;
import org.ovirt.engine.api.resource.StorageDomainServerConnectionResource;
import org.ovirt.engine.api.resource.StorageDomainServerConnectionsResource;
import org.ovirt.engine.core.common.action.AttachDetachStorageConnectionParameters;
import org.ovirt.engine.core.common.action.VdcActionType;
import org.ovirt.engine.core.common.businessentities.StorageServerConnections;
import org.ovirt.engine.core.common.queries.IdQueryParameters;
import org.ovirt.engine.core.common.queries.VdcQueryType;
import org.ovirt.engine.core.compat.Guid;

public class BackendStorageDomainServerConnectionsResource
        extends AbstractBackendCollectionResource<StorageConnection, StorageServerConnections>
        implements StorageDomainServerConnectionsResource {

    Guid storageDomainId = null;

    public BackendStorageDomainServerConnectionsResource(Guid storageDomainId) {
        super(StorageConnection.class, StorageServerConnections.class);
        this.storageDomainId = storageDomainId;
    }

    @Override
    public StorageConnections list() {
        List<StorageServerConnections> connections = getConnections();
        return mapCollection(connections);
    }

    protected List<StorageServerConnections> getConnections() {
        return getEntity(List.class,
                VdcQueryType.GetStorageServerConnectionsForDomain,
                new IdQueryParameters(storageDomainId),
                "storage domain: id=" + storageDomainId);
    }

    private StorageConnections mapCollection(List<StorageServerConnections> entities) {
        StorageConnections collection = new StorageConnections();
        for (StorageServerConnections entity : entities) {
            StorageConnection connection = map(entity);
            if (connection != null) {
                collection.getStorageConnections().add(addLinks(populate(connection, entity)));
            }
        }
        return collection;
    }

    @Override
    public Response add(StorageConnection storageConnection) {
        validateParameters(storageConnection, "id");

        return performAction(VdcActionType.AttachStorageConnectionToStorageDomain,
                new AttachDetachStorageConnectionParameters(storageDomainId, storageConnection.getId()));
    }

    @Override
    public StorageDomainServerConnectionResource getConnectionResource(String id) {
        return inject(new BackendStorageDomainServerConnectionResource(id, this));
    }
}

@CheckReturnValue
  protected Statement genParamTypeChecks(TemplateNode node, String alias) {
    ImmutableList.Builder<Statement> declarations = ImmutableList.builder();
    for (TemplateParam param : node.getAllParams()) {
      String paramName = param.name();
      SoyType paramType = param.type();
      CodeChunk.Generator generator = templateTranslationContext.codeGenerator();
      Expression paramChunk = genCodeForParamAccess(paramName, param);
      JsType jsType = getJsTypeForParamTypeCheck(paramType);

      String paramAlias = genParamAlias(paramName);
      Expression coerced = jsType.getValueCoercion(paramChunk, generator);
      if (coerced != null) {

        paramChunk = generator.declarationBuilder().setRhs(coerced).build().ref();
      }
      if (param.hasDefault()) {
        if (coerced == null) {
          paramChunk = generator.declarationBuilder().setRhs(paramChunk).build().ref();
        }
        declarations.add(
            genParamDefault(param, paramChunk, alias, jsType,   true));
      }

      Expression value;
      Optional<Expression> soyTypeAssertion =
          jsType.getSoyTypeAssertion(paramChunk, paramName, generator);

      if (soyTypeAssertion.isPresent()) {
        value = soyTypeAssertion.get();
      } else {
        value = paramChunk;
      }
      VariableDeclaration.Builder declarationBuilder =
          VariableDeclaration.builder(paramAlias)
              .setRhs(value)
              .setGoogRequires(jsType.getGoogRequires());
      declarationBuilder.setJsDoc(
          JsDoc.builder()
              .addParameterizedAnnotation(
                  "type", getJsTypeForParamForDeclaration(paramType).typeExpr())
              .build());
      VariableDeclaration declaration = declarationBuilder.build();
      declarations.add(declaration);
      templateTranslationContext
          .soyToJsVariableMappings()

          .put(paramName, id(paramAlias));
    }
    return Statement.of(declarations.build());
  }

import java.io.Serializable;
import java.util.Set;

import javax.enterprise.context.RequestScoped;
import javax.enterprise.context.spi.CreationalContext;
import javax.enterprise.inject.spi.Bean;
import javax.enterprise.inject.spi.BeanManager;
import javax.enterprise.util.AnnotationLiteral;
import javax.inject.Inject;

public class BeanLocator implements Serializable {

    private static final long serialVersionUID = 1L;

    @Inject
    private BeanManager beanManager;

    @Inject
    private NGSessionScopeContext ngSessionScopeContext;

    public Object lookup(String beanName, String sessionId) {
        ngSessionScopeContext.setCurrentSessionId(sessionId);

        Bean<?> bean = null;

        Set<Bean<?>> beans = beanManager.getBeans(beanName);
        if (beans != null && !beans.isEmpty()) {
            bean = beanManager.resolve(beans);
        } else {
             beans = beanManager.getBeans(AngularBeansUtils.getClassForBean(beanName));
             if(beans != null && !beans.isEmpty()) {
                bean = beanManager.resolve(beans);
             }
        }

        if (bean == null) {
            return null;
        }

        CreationalContext<?> creationalContext = beanManager.createCreationalContext(bean);

        if (bean.getScope().equals(RequestScoped.class)) {
            return beanManager.getReference(bean, AngularBeansUtils.getClassForBean(beanName), creationalContext);
        } else if (bean.getScope().equals(NGSessionScopeContext.class)) {
            return beanManager.getReference(bean, AngularBeansUtils.getClassForBean(beanName), creationalContext);
        } else {
            return beanManager.getReference(bean, AngularBeansUtils.getClassForBean(beanName), creationalContext);
        }
    }
}

class AngularBeansUtils {
    public static Class<?> getClassForBean(String beanName) {
        try {
            return Class.forName(beanName);
        } catch (ClassNotFoundException e) {
            return null;
        }
    }
}

