(empty UT function, nothing else). Help:https://leetcode.com/problems/complete-binary-tree/discuss/287378/JavaJava-DFSOnTheTreeWeCheckIfTreeIsComplete

public class Queue {

    public boolean isCompleteTree(TreeNode root) {
        Deque<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);

        while(!queue.isEmpty() && (root != null)) {
            int size = queue.size();
            for(int i=0; i<size; i++){
                 TreeNode node = queue.poll(); // dequeuing multiple times
                 if(i*2+1 >= size) return false; // reaching last level but extra node found there

                 queue.offer(node.left);
                 if(node.right != null) queue.offer(node.right);
            }
        }

        return queue.isEmpty();
    }
}

