public class Ludic {
 
    public static void main(String[] args) {
        int len, i;
        int[] x = ludic(2005, 1000, len);
 
        System.out.println("First 25:");
        for (i = 0; i < 25; i++) System.out.print(" " + x[i]);
        System.out.println();
 
        for (i = 0; x[i] <= 1000; i++);
        System.out.println("Ludics below 1000: " + i);
 
        System.out.println("Ludic 2000 to 2005:");
        for (i = 2000; i <= 2005; i++) System.out.print(" " + x[i - 1]);
        System.out.println();
 
        System.out.println("Triples below 250:");
        for (i = 0; x[i] + 6 <= 250; i++)
            if (find(x, x[i] + 2) && find(x, x[i] + 6))
                System.out.print(" (" + x[i] + " " + (x[i] + 2) + " " + (x[i] + 6) + ")");
 
        System.out.println();
    }
 
    public static int[] ludic(int min_len, int min_val, int len) {
        int cap, i, v, active = 1, nf = 0;
        List<Filt> f = new ArrayList<Filt>();
        f.add(new Filt(4, 4));
 
        for (v = 1; ; ++v) {
            for (i = 1; i < active && --f.get(i).i > 0; i++);
 
            if (i < active)
                f.get(i).i = f.get(i).v;
            else if (nf == f.get(i).i)
                f.get(i).i = f.get(i).v, ++active;  // enable one more filter
            else {
                if (nf >= cap)
                    cap *= 2;
                f.add(new Filt(v + nf, v));
                if (++nf >= min_len && v >= min_val) break;
            }
        }
 
        // pack the sequence into a uint[]
        // filt_t struct was used earlier for cache locality in loops
        int[] x = new int[nf];
        for (i = 0; i < nf; i++) x[i] = f.get(i).v;
 
        return x;
    }
 
    public static boolean find(int[] a, int v) {
        int i;
        for (i = 0; a[i] <= v; i++)
            if (v == a[i]) return true;
        return false;
    }
 
}
 
