    public int[] finalPrices(int[] prices) {
        int len = prices.length;
        int[] ret = new int[len];
        for (int i = 0; i < len; i ++) {
            int p = prices[i];
            for (int j = i + 1; j < len; j ++) {
                if (p >= prices[j]) {
                    p -= prices[j];
                    break;
                }
            }
            ret[i] = p;
        }
        return ret;
    }
