        this.vertexSet = new HashSet<>();
    }

    // Abstract method to add a vertex to the graph
    public abstract boolean addVertex(V vertex);

    // Abstract method to get a set of vertices in the graph
    public abstract Set<V> getVertexSet();

    // Abstract method to add an edge between two vertices
    public abstract boolean addEdge(V source, V target, E edge);

    // Abstract method to get all edges in the graph
    public abstract Set<E> getAllEdges();

    // Abstract method to get an edge between two vertices
    public abstract E getEdge(V source, V target);

    // Abstract method to remove an edge between two vertices
