    // Abstract method to get the degree of a vertex
    public abstract int degreeOf(V vertex);

    // Abstract method to get incoming edges of a vertex
    public abstract Set<E> incomingEdgesOf(V vertex);

    // Abstract method to get outgoing edges of a vertex
    public abstract Set<E> outgoingEdgesOf(V vertex);

    // Method to check if a vertex exists in the graph
    public boolean vertexExists(V vertex) {
        return vertexSet.contains(vertex);
    }

    // Method to remove a vertex from the graph
    public boolean removeVertex(V vertex) {
        if (!vertexExists(vertex)) {
            return false;
        }
        // Remove edges associated with this vertex
        for (E edge : outgoingEdgesOf(vertex)) {
            removeEdge(vertex, getTargetVertex(edge));
        }
        for (E edge : incomingEdgesOf(vertex)) {
            removeEdge(getSourceVertex(edge), vertex);
        }
        return vertexSet.remove(vertex);
    }

    // Helper method to get target vertex from an edge
    protected abstract V getTargetVertex(E edge);

    // Helper method to get source vertex from an edge
    protected abstract V getSourceVertex(E edge);

    // Method to return the total number of vertices
    public int numberOfVertices() {
        return vertexSet.size();
    }

    // Method to return the total number of edges
    public int numberOfEdges() {
        return getAllEdges().size();
    }

