    static FastReader sc=null;

    public static void main(String[] args) {

        sc=new FastReader();

        int t=sc.nextInt();

        while(t-->0) {

            long a=sc.nextLong(),m=sc.nextLong();

            m/=gcd(a,m);

            System.out.println(phi(m));

        }

    }

    static long phi(long n) {

        long result = n;

        for (long i = 2; i * i <= n; i++) {

            if (n % i == 0) {

                while (n % i == 0)

                    n /= i;

                result -= result / i;

            }

        }

        if (n > 1)

            result -= result / n;

        return result;

    }

