 * Abstract representation of a parameter proxy.
 * Provides mechanisms to create views, build tree structures,
 * and register listeners for parameter changes.
 */
public abstract class ProxyParameter extends ProxyObject implements Parameter {
    protected final Logger log;
    protected final String path;
    protected final String name;
    protected final ManagedCollectionFactory mcf;
    protected final Receiver.Factory receiverFactory;

    /**
     * @param log             SLF4j Logger for logging activities.
     * @param path            The path configuration for the parameter.
     * @param name            The name of the parameter.
     * @param mcf             Managed collection factory for dependency injection.
     * @param receiverFactory Factory for creating event/message receivers.
     */
    @Inject
    public ProxyParameter(Logger log, @Assisted String path, @Assisted String name,
                          ManagedCollectionFactory mcf, Receiver.Factory receiverFactory) {
        this.log = log;
        this.path = path;
        this.name = name;
        this.mcf = mcf;
        this.receiverFactory = receiverFactory;
        log.info("ProxyParameter created with path: {} and name: {}", path, name);
    }

    /**
     * Creates a view representation of the parameter based on the given mode.
     *
     * @param mode The view mode.
     * @return A ParameterView instance.
     */
    public abstract ParameterView createView(String mode);

    /**
     * Builds and returns a tree structure snapshot of the parameter data.
     *
     * @return A Tree representing the parameter structure.
     */
    public Tree getTree() {
        Tree tree = createTree();
        registerListener();
        log.debug("Tree created for parameter: {}", name);
        return tree;
    }

