/**
 * An interface for identifying and handling instances of classes that can be considered "empty."
 * Implementing classes define their own criteria for determining emptiness.
 */
public interface Emptiable {

    /**
     * Checks whether this instance is considered empty.
     * The definition of "empty" is determined by the implementing class.
     *
     * @return {@code true} if this instance is empty, {@code false} otherwise.
     */
    boolean isEmpty();

    /**
     * A default implementation of the {@code Emptiable} interface for convenience.
     * This class can be extended by other classes to provide a basic implementation.
     */
    abstract class AbstractEmptiable implements Emptiable {

        /**
         * Default constructor.
         */
        protected AbstractEmptiable() {
        }

        /**
         * Returns a string representation of this instance, including its emptiness status.
         *
         * @return a string representation of this instance.
         */
        @Override
        public String toString() {
            return getClass().getSimpleName() + "[isEmpty=" + isEmpty() + "]";
        }
    }

    /**
     * A simple example implementation of the {@code Emptiable} interface.
     * This class represents a container that is empty if it holds no data.
     */
    class DataContainer extends AbstractEmptiable {

        private final Object data;

        /**
         * Constructs a new {@code DataContainer} with the specified data.
         *
         * @param data the data to be stored in this container.
         */
        public DataContainer(Object data) {
            this.data = data;
        }

        /**
         * Checks whether this container is empty.
         * The container is considered empty if it holds no data.
         *
         * @return {@code true} if this container is empty, {@code false} otherwise.
         */
        @Override
        public boolean isEmpty() {
            return data == null;
        }
    }
}

