 * The type of the character in a specific anime.
 * (http://anidb.net/perl-bin/animedb.pl?show=userpage&uid=63935)
 * @see AnimeCharacter#getType()
 * @see AnimeCharacter#setType(Integer)
 */
public class AnimeCharacterType {
    /** Appears in. */
    public final static AnimeCharacterType APPEARS_IN
        = new AnimeCharacterType(0);
    /** Cameo appearance in. */
    public final static AnimeCharacterType CAMEO_APPEARANCE_IN
        = new AnimeCharacterType(1);
    /** Main character in. */
    public final static AnimeCharacterType MAIN_CHARACTER_IN
        = new AnimeCharacterType(2);

    /** The value. */
    private int value;

    private AnimeCharacterType(final int value) {
        super();
        this.value = value;
    }

    /**
     * Returns an instance of the class for the given value.
     * @param value The value.
     * @return The instance of <code>null</code>, if there is no instance for
     * the given value.
     */
    public static AnimeCharacterType getInstance(final int value) {
        if (APPEARS_IN.value == value) {
            return APPEARS_IN;
        } else if (CAMEO_APPEARANCE_IN.value == value) {
            return CAMEO_APPEARANCE_IN;
        } else if (MAIN_CHARACTER_IN.value == value) {
            return MAIN_CHARACTER_IN;
        }
        return null;
    }

    /**
     * Returns the value.
     * @return The value.
     */
    public long getValue() {
        return this.value;
    }

    public int hashCode() {
        int result = 17;

        result = 37 * result + this.value;
        return result;
    }

    public boolean equals(final Object obj) {
        AnimeCharacterType type;

        if (obj instanceof AnimeCharacterType) {
            type = (AnimeCharacterType) obj;
            if (this.value == type.value) {
                return true;
            }
        }
        return false;
    }
}

import java.util.Arrays;
 
public class EgyptianDivision {
 
    public static long egyptianDivision(long dividend, long divisor, long[] remainder) {
        // remainder is an out parameter, pass null if you do not need the remainder
        long[] powers = new long[64];
        long[] doublings = new long[64];
        int i;
        for (i = 0; i < 64; i++) {
            powers[i] = 1 << i;
            doublings[i] = divisor << i;
            if (doublings[i] > dividend)
                break;
        }
        long answer = 0;
        long accumulator = 0;
        for (i = i - 1; i >= 0; i--) {
            // If the current value of the accumulator added to the
            // doublings cell would be less than or equal to the
            // dividend then add it to the accumulator
            if (accumulator + doublings[i] <= dividend) {
                accumulator += doublings[i];
                answer += powers[i];
            }
        }
        if (remainder!= null)
            remainder[0] = dividend - accumulator;
        return answer;
    }
 
    public static void go(long a, long b) {
        long[] y = new long[1];
        long x = egyptianDivision(a, b, y);
        System.out.println(a + " / " + b + " = " + x + " remainder " + y[0]);
        assert (a == b * x + y[0]);
    }
 
    public static void main(String[] args) {
        go(580, 32);
    }
}

