public final SimpleFeatureCollection treatStringAsURL(final Template template, final String geoJsonUrl) throws IOException {
    // Create a URL object from the geoJsonUrl string
    URL url = new URL(geoJsonUrl);
    // Open a connection to the URL
    URLConnection connection = url.openConnection();
    // Get the input stream from the connection
    InputStream inputStream = connection.getInputStream();
    // Create a DataStore from the input stream
    DataStore dataStore = DataStoreFinder.getDataStore(Collections.singletonMap("url", inputStream));
    // Get the feature source from the data store
    FeatureSource<SimpleFeatureType, SimpleFeature> featureSource = dataStore.getFeatureSource(dataStore.getTypeNames()[0]);
    // Get the feature collection from the feature source
    SimpleFeatureCollection featureCollection = featureSource.getFeatures();
    // Return the feature collection
    return featureCollection;
}

