class FieldValueWritable implements Writable {
    private Writable value;

    public FieldValueWritable() {}

    public FieldValueWritable(Writable value) {
        this.value = value;
    }

    public Writable getValue() {
        return value;
    }

    public void setValue(Writable value) {
        this.value = value;
    }

    @Override
    public void write(DataOutput out) throws IOException {
        if (value == null) {
            out.writeBoolean(false);
            return;
        }
        out.writeBoolean(true);
        Text.writeString(out, value.getClass().getName());
        value.write(out);
    }

    @Override
    public void readFields(DataInput in) throws IOException {
        boolean hasValue = in.readBoolean();
        if (!hasValue) {
            value = null;
            return;
        }
        try {
            String className = Text.readString(in);
            Class<?> cls = Class.forName(className);
            value = (Writable) cls.getDeclaredConstructor().newInstance();
            value.readFields(in);
        } catch (Exception e) {
            throw new IOException("Field deserialization failed", e);
        }
    }

    @Override
    public String toString() {
        return value != null ? value.toString() : "null";
    }
}

