import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * InputStream that returns content in small portions.
 *
 */
public final class SlowInputStream extends InputStream {

    /**
     * Original stream.
     */
    private final InputStream origin;

    /**
     * Ctor.
     * @param size The size of the array to encapsulate
     */
    public SlowInputStream(final int size) {
        this(new ByteArrayInputStream(new byte[size]));
    }

    /**
     * Ctor.
     * @param stream Original stream to encapsulate and make slower
     */
    SlowInputStream(final InputStream stream) {
        super();
        this.origin = stream;
    }

    @Override
    public int read() throws IOException {
        final byte[] buf = new byte[1];
        final int result;
        if (this.read(buf) < 0) {
            result = -1;
        } else {
            result = Byte.toUnsignedInt(buf[0]);
        }
        return result;
    }

    @Override
    public int read(final byte[] buf, final int offset, final int len)
        throws IOException {
        final int result;
        if (len > 1) {
            result = this.origin.read(buf, offset, len - 1);
        } else {
            result = this.origin.read(buf, offset, len);
        }
        return result;
    }

    @Override
    public int read(final byte[] buf) throws IOException {
        return this.read(buf, 0, buf.length);
    }

}

public TwoDimensionalCounter scale(double d) {
    TwoDimensionalCounter scaledCounter = new TwoDimensionalCounter();

    for (Map.Entry<TwoDimensionalKey, Double> entry : this.entrySet()) {
        scaledCounter.setCount(entry.getKey(), entry.getValue() * d);
    }

    return scaledCounter;
}

/*
 * Collection of small helper routines that each walk the same
 * sample array a different way: even positions, doubling steps,
 * odd values, stopping at a multiple of three, and printing
 * everything.
 */
public class DiziElemanErisim {

    static void ciftIndisleriYazdir(int[] veri) {
        System.out.print("Cift indisli elemanlar: ");
        for (int idx = 0; idx < veri.length; idx++) {
            if (idx % 2 == 0) {
                System.out.print(veri[idx] + " ");
            }
        }
        System.out.println();
    }

    static void katlananIndisleriYazdir(int[] veri) {
        System.out.print("i artan indislerdeki elemanlar: ");
        for (int idx = 1; idx < veri.length; idx += idx) {
            System.out.print(veri[idx] + " ");
        }
        System.out.println();
    }

    static void tekSayilariYazdir(int[] veri) {
        System.out.print("Tek sayi elemanlar: ");
        for (int idx = 1; idx < veri.length; idx++) {
            if (veri[idx] % 2 == 0) {
                continue;
            }
            System.out.print(veri[idx] + " ");
        }
        System.out.println();
    }

    static void uculeBolunenKadarYazdir(int[] veri) {
        System.out.print("Ucun kati bir elemana kadar: ");
        for (int idx = 1; idx < veri.length; idx++) {
            if (veri[idx] % 3 == 0) {
                break;
            }
            System.out.print(veri[idx] + " ");
        }
        System.out.println();
    }

    static void hepsiniYazdir(int[] veri) {
        System.out.print("Tum elemanlar: ");
        for (int idx = 0; idx < veri.length; idx++) {
            System.out.print(veri[idx] + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {
        int[] ornekVeri = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        hepsiniYazdir(ornekVeri);
        ciftIndisleriYazdir(ornekVeri);
        katlananIndisleriYazdir(ornekVeri);
        tekSayilariYazdir(ornekVeri);
        uculeBolunenKadarYazdir(ornekVeri);
    }
}

