import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();

        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] a = new int[n];

            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }

            int min = a[0];

            for (int i = 1; i < n; i++) {
                if (a[i] < min) {
                    min = a[i];
                }
            }

            int sum = 0;

            for (int i = 0; i < n; i++) {
                sum += a[i] - min;
            }

            System.out.println(sum);
        }
    }
}

