public class Program {
    final int MOD = 1_000_000_007;
    long dp[][], fact[], invfact[];

    public int rearrangeSticks(int n, int k) {
        dp = new long[k+2][n+2];
        fact = new long[n+2];
        invfact = new long[n+2];
        fact[0] = invfact[0] = 1;
        for(int i = 1; i <= n; i++) {
            fact[i] = (fact[i-1]*i)%MOD;
            invfact[i] = pow(fact[i], MOD-2);
        }
        return (int)solve(k+1, n);
    }

    private long solve(int k, int n) {
        if(k > n || k == 0) return k == n ? 1 : 0;
        if(dp[k][n] != 0) return dp[k][n];

        dp[k][n] = (invfact[k]*((solve(k-1, n-1) + (n-1)*solve(k, n-1))%MOD))%MOD;
        return dp[k][n];
    }

    private long pow(long a, int b) {
        if(b == 0) return 1;
        long tmp = pow(a, b/2);
        if(b % 2 == 0) return (tmp*tmp)%MOD;
        else return (((tmp*tmp)%MOD)*a)%MOD;
    }
}

