public class FtpClient {

    public static void main(String[] args) {
        // Hard-coded demonstration values
        final String hostport = "localhost:21";
        final String username = "anonymous";
        final String password = "";
        final String dir = "pub";
        final String file = "somefile.bin";

        FTPClient conn = new FTPClient();
        try {
            conn.connect(hostport);
            System.out.println(conn);

            int reply = conn.getReplyCode();
            if (!FTPReply.isPositiveCompletion(reply)) {
                conn.disconnect();
                System.err.println("FTP server refused connection.");
                System.exit(1);
            }

            if (!conn.login(username, password)) {
                conn.logout();
                System.err.println("FTP server refused login.");
                System.exit(1);
            }

            if (!conn.changeWorkingDirectory(dir)) {
                conn.logout();
                System.err.println("FTP server refused directory.");
                System.exit(1);
            }
            System.out.println(conn.printWorkingDirectory());

            FTPFile[] files = conn.listFiles();
            for (FTPFile f : files) {
                System.out.printf("%v %12d %v %v\n", f.getTimestamp(), f.getSize(), f.getType(), f.getName());
            }

            InputStream r = conn.retrieveFileStream(file);
            if (r == null) {
                conn.logout();
                System.err.println("FTP server refused file.");
                System.exit(1);
            }

            OutputStream f = new FileOutputStream(file);
            int n = 0;
            byte[] buffer = new byte[1024];
            while ((n = r.read(buffer))!= -1) {
                f.write(buffer, 0, n);
            }
            f.close();
            r.close();

            System.out.println("Wrote", n, "bytes to", file);
        } catch (IOException ex) {
            Logger.getLogger(FtpClient.class.getName()).log(Level.SEVERE, null, ex);
        } finally {
            try {
                conn.disconnect();
            } catch (IOException ex) {

