class Validator {
    public int minimumMountainRemovals(int[] nums) {
        int[] fnL = new int[nums.length+1];
        int[] fnR = new int[nums.length+1];
        for (int idx=0;idx<nums.length;idx++) {
            fnL[idx] = idx;
            int ans = 0;
            for (int k=idx-1;k>=0;k--) {
                if (nums[k] <nums[idx]) {
                    fnL[idx] = Math.min(fnL[idx], fnL[k] + ans);
                }
                ans += 1;
                if (fnL[idx] <= ans) {
                    break;
                }
            }
        }
        for (int idx=nums.length-1;idx>=0;idx--) {
            fnR[idx] = nums.length - 1 - idx;
            int ans = 0;
            for (int k=idx+1;k<nums.length;k++) {
                if (nums[k] < nums[idx]) {
                    fnR[idx] = Math.min(fnR[idx], fnR[k] + ans);
                }
                ans += 1;
                if (fnR[idx] <= ans) {
                    break;
                }
            }
        }
        int ans = nums.length;
        for (int i=1;i<nums.length-1;i++) {
            ans = Math.min(ans, fnL[i] + fnR[i]);
        }
        return ans;
    }
}

