import java.util.Arrays;
 
public class AdditivePrimes
{
    public static void main( String[] args )
    {
        final int N = 500;
        System.out.printf( "Rosetta Code: additive primes less than %d:\n", N );
        boolean[] isPrime = new boolean[N];
        memoizeIsPrime( isPrime, N );
        System.out.printf( "   2" );
        int count = 1;
        for (int i = 3; i < N; i += 2)
        {
            if (isPrime[i] && isPrime[sumOfDecimalDigits( i )])
            {
                System.out.printf( "%4d", i );
                ++count;
                if ((count % 10) == 0)
                {
                    System.out.printf( "\n" );
                }
            }
        }
        System.out.printf( "\nThose were %d additive primes.\n", count );
    }/* main */
 
    private static void memoizeIsPrime( boolean[] result, final int N )
    {
        result[2] = true;
        result[3] = true;
        int[] prime = new int[N];
        prime[0] = 3;
        int end = 1;
        for (int n = 5; n < N; n += 2)
        {
            boolean nIsPrime = true;
            for (int i = 0; i < end; ++i)
            {
                final int PRIME = prime[i];
                if (n % PRIME == 0)
                {
                    nIsPrime = false;
                    break;
                }
                if (PRIME * PRIME > n)
                {
                    break;
                }
            }
            if (nIsPrime)
            {
                prime[end++] = n;
                result[n] = true;
            }
        }
    }/* memoizeIsPrime */
 
    private static int sumOfDecimalDigits( int n )
    {
        int sum = 0;
        while (n > 0)
        {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }/* sumOfDecimalDigits */
}/* AdditivePrimes */

