import java.math.BigInteger;
import java.util.Arrays;
 
class Validator {
    final static int nMax = 250;
    final static int nBranches = 4;
 
    static BigInteger[] rooted = new BigInteger[nMax + 1];
    static BigInteger[] unrooted = new BigInteger[nMax + 1];
    static BigInteger[] c = new BigInteger[nBranches];
 
    static void tree(int br, int n, int l, int inSum, BigInteger cnt) {
        int sum = inSum;
        for (int b = br + 1; b <= nBranches; b++) {
            sum += n;
 
            if (sum > nMax || (l * 2 >= sum && b >= nBranches))
                return;
 
            BigInteger tmp = rooted[n];
            if (b == br + 1) {
                c[br] = tmp.multiply(cnt);
            } else {
                c[br] = c[br].multiply(tmp.add(BigInteger.valueOf(b - br - 1)));
                c[br] = c[br].divide(BigInteger.valueOf(b - br));
            }
 
            if (l * 2 < sum)
                unrooted[sum] = unrooted[sum].add(c[br]);
 
            if (b < nBranches)
                rooted[sum] = rooted[sum].add(c[br]);
 
            for (int m = n - 1; m > 0; m--)
                tree(b, m, l, sum, c[br]);
        }
    }
 
    static void bicenter(int s) {
        if ((s & 1) == 0) {
            BigInteger tmp = rooted[s / 2];
            tmp = tmp.add(BigInteger.ONE).multiply(rooted[s / 2]);
            unrooted[s] = unrooted[s].add(tmp.shiftRight(1));
        }
    }
 
    public static void main(String[] args) {
        Arrays.fill(rooted, BigInteger.ZERO);
        Arrays.fill(unrooted, BigInteger.ZERO);
        rooted[0] = rooted[1] = BigInteger.ONE;
        unrooted[0] = unrooted[1] = BigInteger.ONE;
 
        for (int n = 1; n <= nMax; n++) {
            tree(0, n, n, 1, BigInteger.ONE);
            bicenter(n);
            System.out.printf("%d: %s%n", n, unrooted[n]);
        }
    }
}

import java.io.IOException;
import java.io.PrintWriter;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Set;
import java.util.HashSet;
import java.util.Scanner;
import java.util.concurrent.Executors;

public class ChatServer {

    // Tum client isimlerini saklar, boylece tekrar eden isimler engellenebilir.
    private static Set<String> names = new HashSet<>();

    // Tum client'lar icin PrintWriter'lari saklar, yayini yapmak icin kullanilir.
    private static Set<PrintWriter> writers = new HashSet<>();

    // Main metod, server'i baslatir
    public static void main(String[] args) throws Exception {
        System.out.println("Chat server calisiyor...");
        var pool = Executors.newFixedThreadPool(500); // 500 thread'lik bir havuz olusturur

        try (var listener = new ServerSocket(59001)) { // Sunucuyu dinlemeye baslar
            System.out.println(listener.getInetAddress().toString());
            while (true) {
                // Her client baglantisi icin yeni bir thread baslatir
                pool.execute(new Handler(listener.accept()));
            }
        }
    }

    // Handler sinifi, her client icin yeni bir thread olarak calisir
    private static class Handler implements Runnable {
        private String name; // Client'in adi
        private Socket socket; // Client ile baglanti icin socket
        private PrintWriter out; // Client'a mesaj gondermek icin PrintWriter

        public Handler(Socket socket) {
            this.socket = socket;
        }

        // Her bir client icin run metodu calistirilir
        public void run() {
            try (var in = new Scanner(socket.getInputStream())) { // Client'tan gelen veriyi okur
                out = new PrintWriter(socket.getOutputStream(), true); // Client'a veri gondermek icin cikti stream'i

                // Kullanicidan benzersiz bir isim alana kadar istek yapmaya devam et.
                while (true) {
                    out.println("SUBMITNAME"); // isim iste
                    name = in.nextLine(); // Kullanicinin ismini al
                    if (name == null) {
                        return; // isim bossa cik
                    }
                    synchronized (names) { // Erisim kontrolu icin synchronized
                        // Eger isim bos degilse ve daha once alinmamissa, ismi kabul et
                        if (!name.isBlank() && !names.contains(name)) {
                            names.add(name); // isimleri ekle
                            break; // Donguden cik
                        }
                    }

public class AntiPrimesPlus {
 
    static int count_divisors(int n) {
        int count = 0;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                if (i == n / i)
                    count++;
                else
                    count += 2;
            }
        }
        return count;
    }
 
    public static void main(String[] args) {
        final int max = 15;
        System.out.printf("The first %d terms of the sequence are:\n", max);
        for (int i = 1, next = 1; next <= max; ++i) {
            if (next == count_divisors(i)) {
                System.out.printf("%d ", i);
                next++;
            }
        }
        System.out.println();
    }
}

public class StopWatch {
    private long startTime;
    private long endTime;

    public StopWatch() {
        startTime = System.currentTimeMillis();
    }

    public void start() {
        startTime = System.currentTimeMillis();
    }

    public void stop() {
        endTime = System.currentTimeMillis();
    }

    public long getElapsedTime() {
        return endTime - startTime;
    }
}

