}

import java.io.*;
import java.util.*;
import java.text.*;
import java.math.*;
import java.util.regex.*;

class Graph {

    static class fraction{
        int num,den;
    }

    static fraction[] examples = {{1,2}, {3,1}, {23,8}, {13,11}, {22,7}, {-151,77}};
    static fraction[] sqrt2 = {{14142,10000}, {141421,100000}, {1414214,1000000}, {14142136,10000000}};
    static fraction[] pi = {{31,10}, {314,100}, {3142,1000}, {31428,10000}, {314285,100000}, {3142857,1000000}, {31428571,10000000}, {314285714,100000000}};

    static int r2cf(int numerator,int denominator)
    {
        int quotient=0,temp;

        if(denominator!= 0)
        {
            quotient = numerator / denominator;

            temp = numerator;

            numerator = denominator;

            denominator = temp % denominator;
        }

        return quotient;
    }

    public static void main(String[] args) {
        int i;

        System.out.println("Running the examples :");

        for(i=0;i<examples.length;i++)
        {
            System.out.print("\nFor N = " + examples[i].num + ", D = " + examples[i].den + " :");

            while(examples[i].den!= 0){
                System.out.print(" " + r2cf(examples[i].num,examples[i].den));
            }
        }

        System.out.println("\n\nRunning for " + (char)251 + "2 :"); /* 251 is the ASCII code for the square root symbol */

        for(i=0;i<sqrt2.length;i++)
        {
            System.out.print("\nFor N = " + sqrt2[i].num + ", D = " + sqrt2[i].den + " :");

            while(sqrt2[i].den!= 0){
                System.out.print(" " + r2cf(sqrt2[i].num,sqrt2[i].den));
            }
        }

        System.out.println("\n\nRunning for " + (char)227 + " :"); /* 227 is the ASCII code for Pi's symbol */

        for(i=0;i<pi.length;i++)
        {
            System.out.print("\nFor N = " + pi[i].num + ", D = " + pi[i].den + " :");

            while(pi[i].den!= 0){
                System.out.print(" " + r2cf(pi[i].num,pi[i].den));
            }
        }
    }
}

