public class Tray extends Group {

    private final TaskList taskList;
    private final TrayCard questCard;
    private final ConversationDialog conversationDialog;
    private boolean isHidden = true;
    private float trayWidth;

    public Tray(TaskList taskList, Skin skin) {
        this.taskList = taskList;
        this.questCard = new TrayCard(skin);
        this.conversationDialog = new ConversationDialog("Conversation", skin);

        Table layout = new Table();
        layout.add(questCard).growX().row();
        layout.add(conversationDialog).growX();

        addActor(layout);
        setWidth(layout.getWidth());
        setHeight(layout.getHeight());
        trayWidth = getWidth();
        setPosition(-trayWidth, 0); // Initially hidden

        updateQuestDetails();
    }

    @Override
    public void act(float delta) {
        super.act(delta);
        updateQuestDetails();
    }

    private void updateQuestDetails() {
        Quest currentQuest = taskList.getCurrentQuest();
        if (currentQuest != null) {
            questCard.setQuestDetails(currentQuest.getTitle(), currentQuest.getDescription());
            conversationDialog.setText(currentQuest.getDialog());
        } else {
            questCard.setQuestDetails("No Active Quest", "No quest is currently active.");
            conversationDialog.setText("");
        }
    }

    public void showTray() {
        if (isHidden) {
            addAction(Actions.moveTo(0, 0, 0.5f));
            isHidden = false;
        }
    }

    public void hideTray() {
        if (!isHidden) {
            addAction(Actions.moveTo(-trayWidth, 0, 0.5f));
            isHidden = true;
        }
    }

    public void toggle() {
        if (isHidden) {
            showTray();
        } else {
            hideTray();
        }
    }
}

import com.google.common.base.Function;
import com.google.common.base.Joiner;
import com.google.common.collect.Collections2;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import javax.annotation.Nonnull;
import javax.annotation.Nullable;
import org.sonar.api.utils.log.Logger;
import org.sonar.api.utils.log.Loggers;

public class ScmAccountToUserLoader {

  private static final Logger log = Loggers.get(ScmAccountToUserLoader.class);

  private final UserIndex userIndex;

  public ScmAccountToUserLoader(UserIndex userIndex) {
    this.userIndex = userIndex;
  }

  @Nullable
  public String load(String scmAccount) {
    List<UserDoc> users = userIndex.searchByScmAccount(scmAccount);
    if (users.size() == 1) {
      return users.get(0).login();
    }
    if (users.size() > 1) {
      log.warn(
          "Multiple users found for SCM account '{}': {}. Returning null.",
          scmAccount,
          Joiner.on(", ").join(Collections2.transform(users, UserDocToLogin.INSTANCE)));
      return null;
    }
    return null;
  }

  public Collection<String> loadAll(Collection<? extends String> scmAccounts) {
    throw new UnsupportedOperationException("Bulk loading not supported");
  }

  private enum UserDocToLogin implements Function<UserDoc, String> {
    INSTANCE;

    @Override
    public String apply(@Nonnull UserDoc user) {
      Objects.requireNonNull(user, "UserDoc must not be null");
      return user.login();
    }
  }

  // Mock classes for compilation
  private interface UserIndex {
    List<UserDoc> searchByScmAccount(String scmAccount);
  }

  private interface UserDoc {
    String login();
  }
}

import java.util.Date;
