/**
 */
public class Project implements Entity<Project> {

    private final UUID mUuid;
    private final String mName;
    private String mDescription;
    private Date mCreationDate;

    public Project(UUID uuid, String name) {
        Validate.notNull(uuid, "uuid must not be null");
        Validate.notEmpty(name, "name must not be empty");

        mUuid = uuid;
        mName = name;
    }

    public static Project newProject(String name) {
        return new Project(UUID.randomUUID(), name);
    }

    public UUID getUuid() {
        return mUuid;
    }

    public String getName() {
        return mName;
    }

    public String getDescription() {
        return mDescription;
    }

    public void setDescription(String description) {
        mDescription = description;
    }

    public Date getCreationDate() {
        return mCreationDate;
    }

    public void setCreationDate(Date creationDate) {
        mCreationDate = creationDate;
    }

    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof Project)) {
            return false;
        }
        Project rhs = (Project) obj;
        return new EqualsBuilder().append(mUuid, rhs.mUuid).isEquals();
    }

    @Override
    public int hashCode() {
        return new HashCodeBuilder().append(mUuid).toHashCode();
    }

    @Override
    public boolean sameIdentityAs(Project other) {
        return this.equals(other);
    }
}

