import com.amazonaws.AmazonClientException;
import com.amazonaws.protocol.MarshallingInfo;
import com.amazonaws.protocol.MarshallingType;
import com.amazonaws.protocol.MarshallLocation;
import com.amazonaws.protocol.ProtocolRequestMarshaller;
import com.amazonaws.util.ValidationUtils;

public class UpdateMedicalVocabularyRequestMarshaller implements ProtocolRequestMarshaller<UpdateMedicalVocabularyRequest> {

    private static final MarshallingInfo<String> VOCABULARYNAME_BINDING = MarshallingInfo.builder(MarshallingType.STRING)
            .marshallLocation(MarshallLocation.PAYLOAD)
            .marshallLocationName("VocabularyName")
            .build();
    private static final MarshallingInfo<String> LANGUAGECODE_BINDING = MarshallingInfo.builder(MarshallingType.STRING)
            .marshallLocation(MarshallLocation.PAYLOAD)
            .marshallLocationName("LanguageCode")
            .build();
    private static final MarshallingInfo<String> VOCABULARYFILEURI_BINDING = MarshallingInfo.builder(MarshallingType.STRING)
            .marshallLocation(MarshallLocation.PAYLOAD)
            .marshallLocationName("VocabularyFileUri")
            .build();

    private static final UpdateMedicalVocabularyRequestMarshaller INSTANCE = new UpdateMedicalVocabularyRequestMarshaller();

    public static UpdateMedicalVocabularyRequestMarshaller getInstance() {
        return INSTANCE;
    }

    private UpdateMedicalVocabularyRequestMarshaller() {}

    @Override
    public void marshall(UpdateMedicalVocabularyRequest request, ProtocolRequestMarshaller<UpdateMedicalVocabularyRequest> protocolMarshaller) {
        try {
            ValidationUtils.assertNotNull(request, "Request object cannot be null");

            protocolMarshaller.marshall(request.getVocabularyName(), VOCABULARYNAME_BINDING);
            protocolMarshaller.marshall(request.getLanguageCode(), LANGUAGECODE_BINDING);
            protocolMarshaller.marshall(request.getVocabularyFileUri(), VOCABULARYFILEURI_BINDING);
        } catch (Exception e) {
            throw new AmazonClientException("Failed to serialize request payload: " + e.getMessage(), e);
        }
    }
}

class Counter {
    public int countPalindromicSubsequence(String s) {
        int total = 0;
        for (char ch = 'a'; ch <= 'z'; ++ch) {
            int selfCount = 0;
            boolean[] counts = new boolean[26];
            int last = -1;
            for (int i = 0; i < s.length(); ++i) {
                if (s.charAt(i) == ch) {
                    ++selfCount;
                    if (last == -1) {
                        last = i;
                    } else {
                        for (int j = last + 1; j < i; ++j) {
                            counts[s.charAt(j) - 'a'] = true;
                        }
                        last = i;
                    }
                }
            }
            for (int i = 0; i < 26; ++i) {
                total += counts[i] ? 1 : 0;
            }
            total += selfCount >= 3 ? 1 : 0;
        }
        return total;
    }
}

public enum IntToWords {
    ;
 
    private static final String[] small = {
            "", "one", "two", "three", "four",
            "five", "six", "seven", "eight", "nine",
            "ten", "eleven", "twelve", "thirteen", "fourteen",
            "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"};
    private static final String[] tens = {
            "", "", "twenty", "thirty", "forty",
            "fifty", "sixty", "seventy", "eighty", "ninety"};
    private static final String[] big = {
            "", "thousand", "million", "billion", "trillion",
            "quadrillion", "quintillion"};
 
    public static void main(String[] args) {
        System.out.println(int2Text(0));
        System.out.println(int2Text(10));
        System.out.println(int2Text(30));
        System.out.println(int2Text(47));
        System.out.println(int2Text(100));
        System.out.println(int2Text(999));
        System.out.println(int2Text(1000));
        System.out.println(int2Text(9999));
        System.out.println(int2Text(123_456));
        System.out.println(int2Text(900_000_001));
        System.out.println(int2Text(1_234_567_890));
        System.out.println(int2Text(-987_654_321));
        System.out.println(int2Text(Long.MAX_VALUE));
        System.out.println(int2Text(Long.MIN_VALUE));
    }
 
    public static String int2Text(long number) {
        StringBuilder sb = new StringBuilder();
 
        if (number == 0) {
            return "zero";
        }
 
        long num = -Math.abs(number);
 
        int unit = 1;
        while (true) {
            int rem100 = (int) -(num % 100);
            if (rem100 >= 20) {
                if (rem100 % 10 == 0) {
                    sb.insert(0, tens[rem100 / 10] + " ");
                } else {
                    sb.insert(0, tens[rem100 / 10] + "-" + small[rem100 % 10] + " ");
                }
            } else if (rem100 != 0) {
                sb.insert(0, small[rem100] + " ");
            }
 
            int hundreds = (int) -(num % 1000) / 100;
            if (hundreds != 0) {
                sb.insert(0, small[hundreds] + " hundred ");
            }
 
            num /= 1000;
            if (num == 0) {
                break;
            }
 
            int rem1000 = (int) -(num % 1000);
            if (rem1000 != 0) {
                sb.insert(0, big[unit] + " ");
            }
            unit++;
        }
 
        if (number < 0) {
            sb.insert(0, "negative ");
        }
 
        return sb.toString().trim();
    }
}

class Main {
    int cnt;
    public int maxKDivisibleComponents(int n, int[][] edges, int[] values, int k) {
        ArrayList<Integer> graph[]= new ArrayList[n];
        for(int i=0;i<n;i++) graph[i]=new ArrayList<>();
        for(int edge[] : edges){
            int u=edge[0],v=edge[1];
            graph[u].add(v);
            graph[v].add(u);
        }
        cnt=0;
        dfs(graph,0,-1,k,values);
        return cnt;
    }
    public int dfs(ArrayList<Integer> graph[],int u,int pt,int k,int values[]){
        int sum=values[u]%k;
        for(int v : graph[u]){
            if(v==pt) continue;
            sum = (sum+dfs(graph,v,u,k,values))%k;
        }
        if(sum==0) cnt++;
        return sum;
    }
}

public ByteBufSlice slice(int offset, int length) {
    if (offset < 0 || length < 0 || offset + length > this.capacity()) {
        throw new IndexOutOfBoundsException(String.format("Invalid offset/length arguments, offset: %d, length: %d", offset, length));
    }
    return new ByteBufSlice(this, this.readerIndex() + offset, length);
}

import java.util.Scanner;

public class Checker {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter number of students now: ");
        final int numOfStudents = in.nextInt();
        int[] grades = new int[numOfStudents];

        System.out.println("Now enter " + numOfStudents + " space separated scores: ");

        for (int i = 0; i < numOfStudents; i++) {
            grades[i] = in.nextInt();
        }
        printLetterGrades(grades, findBestGrade(grades));

    }

    static void printLetterGrades(int[] grades, int bestGrade) {

        for (int j = 0; j < grades.length; j++) {
            char letterGrade;
            if (grades[j] >= (bestGrade - 10)) {
                letterGrade = 'A';
            } else if (grades[j] >= (bestGrade - 20)) {
                letterGrade = 'B';
            } else if (grades[j] >= (bestGrade - 30)) {
                letterGrade = 'C';
            } else if (grades[j] >= (bestGrade - 40)) {
                letterGrade = 'D';
            } else {
                letterGrade = 'F';
            }
            System.out.println("Student " + j + " score is " + grades[j] + " and grade is " + letterGrade);
        }

    }

    static int findBestGrade(int[] grades) {
        int best = grades[0];
        for (int i = 0; i < grades.length; i++) {
            if (grades[i] > best) {
                best = grades[i];
            }
        }
        return best;
    }

}

