public final class TestingFunctions {
    private TestingFunctions() {
        // Utility class, prevent instantiation
    }

    /**
     * Perform garbage collection in the current runtime environment
     * @return true if garbage collection was successful
     */
    public static boolean gc() {
        try {
            System.gc();
            return true;
        } catch (Exception e) {
            return false;
        }
    }

    /**
     * Retrieve the default system locale
     * @return current system locale
     */
    public static String getDefaultLocale() {
        return Locale.getDefault().toLanguageTag();
    }

    /**
     * Retrieve the default system timezone
     * @return current system timezone identifier
     */
    public static String getDefaultTimeZone() {
        return ZoneId.systemDefault().getId();
    }

    /**
     * Get the current JavaScript realm
     * @param context current execution context
     * @return current realm object
     */
    public static RealmObject getCurrentRealm(ExecutionContext context) {
        Objects.requireNonNull(context, "Execution context cannot be null");
        return context.getRealm();
    }

    /**
     * Evaluate a script within a specific realm
     * @param realm target realm for script execution
     * @param source script source code
     * @param filename optional filename for source tracing
     * @return result of script evaluation
     */
    public static Object evalInRealm(RealmObject realm, String source, String filename) {
        Objects.requireNonNull(realm, "Realm cannot be null");
        Objects.requireNonNull(source, "Source script cannot be null");

        Source scriptSource = new Source(filename != null ? filename : "<anonymous>", source);
        ExecutionContext context = realm.createScriptContext();

        try {
            return Reflect.eval(context, scriptSource);
        } catch (Exception e) {
            // Handle potential script evaluation errors
            return null;
        }
    }

    /**
     * Load and evaluate script from file path
     * @param realm target realm for script execution

