public static boolean tableContainsString(VoltTable t, String s, boolean caseSenstive) {
        if (t.getRowCount() == 0) {
            return false;
        }
        if (!caseSenstive) {
            s = s.toLowerCase();
        }
        VoltTableRow row = t.fetchRow(0);
        do {
            for (int i = 0; i < t.getColumnCount(); i++) {
                if (t.getColumnType(i) == VoltType.STRING) {
                    String value = row.getString(i);
                    if (value == null) {
                        continue;
                    }
                    if (!caseSenstive) {
                        value = value.toLowerCase();
                    }
                    if (value.contains(s)) {
                        return true;
                    }
                }
            }
        } while (row.advanceRow());
        return false;
    }

class Counter {
  // sub-array
  public int[] smallestSubarrays(int[] nums) {
    int n = nums.length, nxt[][] = new int[n][], pre[] = new int[31];
    Arrays.fill(pre, -1);

    for (int i = nums.length - 1; i >= 0; i--) {
      for (int j = 0; j < 31; j++) if ((nums[i] & (1 << j)) != 0) pre[j] = i;
      nxt[i] = pre.clone();
    }

    int res[] = new int[n];
    for (int i = 0; i < n; i++) {
      int r = i;
      for (int j = 0; j < 31; j++) r = Math.max(r, nxt[i][j]);
      res[i] = r - i + 1;
    }
    return res;
  }
}

