import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Scanner;
 
public class PerlinNoise {
    private static int[] p = new int[512];
    private static double fade(double t) { return t * t * t * (t * (t * 6 - 15) + 10); }
    private static double lerp(double t, double a, double b) { return a + t * (b - a); }
    private static double grad(int hash, double x, double y, double z) {
          int h = hash & 15;
          double u = h<8? x : y,
                 v = h<4? y : h==12||h==14? x : z;
          return ((h&1) == 0? u : -u) + ((h&2) == 0? v : -v);
       }
    private static double noise(double x, double y, double z) {
          int X = (int)Math.floor(x) & 255,
              Y = (int)Math.floor(y) & 255,
              Z = (int)Math.floor(z) & 255;
          x -= Math.floor(x);
          y -= Math.floor(y);
          z -= Math.floor(z);
          double u = fade(x),
                 v = fade(y),
                 w = fade(z);
          int A = p[X  ]+Y, AA = p[A]+Z, AB = p[A+1]+Z,
              B = p[X+1]+Y, BA = p[B]+Z, BB = p[B+1]+Z;
 
          return lerp(w, lerp(v, lerp(u, grad(p[AA  ], x , y , z   ),
                                         grad(p[BA  ], x-1, y , z   )),
                                 lerp(u, grad(p[AB  ], x , y-1, z   ),
                                         grad(p[BB  ], x-1, y-1, z   ))),
                         lerp(v, lerp(u, grad(p[AA+1], x , y , z-1 ),
                                         grad(p[BA+1], x-1, y , z-1 )),
                                 lerp(u, grad(p[AB+1], x , y-1, z-1 ),
                                         grad(p[BB+1], x-1, y-1, z-1 ))));
       }
    private static void loadPermutation(String fileName) throws IOException{
        BufferedReader br = new BufferedReader(new FileReader(fileName));
        String line;
        int i=0;
        while((line=br.readLine())!=null){
            p[i]=Integer.parseInt(line);
            p[i+256]=p[i];
            i++;
        }
        br.close();
    }
    public static void main(String[] args) throws IOException {
        if(args.length!=4)
            System.out.println("Usage : java PerlinNoise <permutation data file> <x,y,z co-ordinates separated by space>");
        else{
            loadPermutation(args[0]);
            System.out.printf("Perlin Noise for (%s,%s,%s) is %.17lf",args[1],args[2],args[3],noise(Double.parseDouble(args[1]),Double.parseDouble(args[2]),Double.parseDouble(args[3])));
        }
    }
}

