private void solve() throws IOException {
int n = reader.nextInt();
int s = reader.nextInt();
long[] a = new long[n];
for (int i = 0; i < n; i++) {
a[i] = reader.nextInt();
}
int start = 0;
long sum = s;
int[] l = new int[n];
int[] r = new int[n];
l[0] = start;
for (int i = 0; i < n; i++) {
sum -= a[i];
if(sum < 0){
r[start] = i-1;
sum += a[start];
start = i;
}
}
r[start] = n;
long maxsum = a[0];
int appl = -1;
int applr = -1;
final int REGAL = 0;
final int MONK = 1;
for (int i = 0; i < n; i++) {
final long cur = maxsum;
maxsum = Math.max(maxsum, cur + a[i]);
if(cur == maxsum){
continue;
}
final int[] ret = new int[2];
ret[REGAL] = l[i];
ret[MONK] = r[i];
if(i-l[i]>(n-r[ret[MONK]])*(r[ret[MONK]]-l[ret[MONK]])
/(r[ret[MONK]]-l[ret[MONK]])+n*REGAL){
ret[MONK] = -1;
}
if(appl == -1 || ret[MONK] >= applr || ret[REGAL] < l[appl]){
appl = ret[MONK];
applr = ret[MONK];
}
}
if(appl<0){
out.print(-"1");
return;
}
final int max = appl;
out.println();
print(out, max);
print(out, maxsum + a[appl] + a[appl-1]);
}

void solve(int testNumber) throws IOException {
