import java.time.LocalDate;
import java.util.List;

public abstract class BaseHospitalReportImpl extends DomainImpl {

    // Abstract method to validate a list of hospital reports
    protected abstract void validateReportList(List<HospitalReport> reports) throws ValidationException;

    // Abstract method to validate a location for the report
    protected abstract void validateLocation(Location location) throws ValidationException;

    // Abstract method to validate the date range of the report
    protected abstract void validateDateRange(LocalDate startDate, LocalDate endDate) throws ValidationException;

    // Abstract method to validate report ID
    protected abstract void validateReportId(String reportId) throws ValidationException;

    // Abstract method to validate patient context
    protected abstract void validatePatientContext(PatientContext patientContext) throws ValidationException;

    // Validates the combination of report and template
    protected void validateReportAndTemplate(String reportId, String templateId) throws ValidationException {
        if (reportId == null || reportId.isEmpty()) {
            throw new ValidationException("Report ID cannot be null or empty");
        }
        if (templateId == null || templateId.isEmpty()) {
            throw new ValidationException("Template ID cannot be null or empty");
        }
        // Further validation logic can be added by subclasses
    }

    // Validates a provided patient ID
    protected void validatePatientId(String patientId) throws ValidationException {
        if (patientId == null || patientId.isEmpty()) {
            throw new ValidationException("Patient ID cannot be null or empty");
        }
    }

    // Check if the report exists
    protected abstract boolean reportExists(String reportId);

    // Method to ensure only valid reports processed
    protected void processValidReports(List<HospitalReport> reports) throws ValidationException {
        validateReportList(reports);
        for (HospitalReport report : reports) {
            if (!reportExists(report.getId())) {
                throw new ValidationException("Report does not exist: " + report.getId());
            }
        }
    }

    // Validates whether a date is in the past
    protected void validatePastDate(LocalDate date) throws ValidationException {
        if (date.isAfter(LocalDate.now())) {
            throw new ValidationException("Date cannot be in the future: " + date);
        }
    }
}

import java.util.*;
public class Counter
{
    public static void solve(Scanner scanner) {
        int N = scanner.nextInt();
        int[] A = new int[N];
        for (int i=0; i<N; ++i) A[i] = scanner.nextInt();
        int[] B = new int[N];
        for (int i=0; i<N; ++i) B[i] = scanner.nextInt();
        boolean[] kills_all = new boolean[N+1];
        for (int k=1; k<=N; ++k) {
            boolean ok = true;
            long pmonocarp = 0, ppolicarp = 0;
            for (int i=0; i<N; ++i) {
                if (A[i] % k != 0) ok = false;
                if (B[i] % k != 0) ok = false;
                pmonocarp += (long)(A[i]+)/k;
                ppolicarp += (long)(B[i])/k;
                if (pmonocarp < (long)i+1 || ppolicarp < (long)i+1) ok = false;
                if (!ok) break;
            }
            if (ok) kills_all[k] = true;
        }
        List<Integer> ans = new ArrayList();
        for (int k=1; k<=N; ++k)
            if (kills_all[k]) ans.add(k);
        System.out.println(ans.size());
        System.out.println(ans.toString().replaceAll("[\\[\\],]", ""));
    }
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        for (int test=0; test<T; ++test) {
            solve(scanner);
        }
        scanner.close();
    }
}

import org.esupportail.commons.mail.CachingEmailSmtpService;
import org.esupportail.commons.mail.SimpleSmtpService;
import org.esupportail.commons.mail.SmtpService;
import org.esupportail.commons.mail.model.SmtpServerData;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.cache.Cache;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Import;

import javax.inject.Inject;
import javax.inject.Named;
import javax.mail.internet.AddressException;
import javax.mail.internet.InternetAddress;
import java.io.UnsupportedEncodingException;

@Configuration
@Import({ CacheConfig.class })
public class SmtpConfig {

    @Value("${smtp.host}")
    private String smtpHost;

    @Value("${smtp.port}")
    private Integer smtpPort;

    @Value("${smtp.user}")
    private String smtpUser;

    @Value("${smtp.password}")
    private String smtpPwd;

    @Value("${smtp.fromEmail}")
    private String fromEmail;

    @Value("${smtp.fromName}")
    private String fromName;

    @Value("${smtp.interceptAll}")
    private boolean interceptAll;

    @Value("${smtp.interceptEmail}")
    private String interceptEmail;

    @Value("${smtp.interceptName}")
    private String interceptName;

    @Value("${smtp.charset}")
    private String charset;

    @Value("${exceptionHandling.email}")
    private String emailException;

    @Inject
    @Named("mailCache")
    private Cache mailCache;

    @Bean
    public SmtpServerData smtpServer() {
        return SmtpServerData.builder()
                .host(smtpHost)
                .port(smtpPort)
                .user(smtpUser)
                .password(smtpPwd)
                .build();
    }

    @Bean
    public SmtpService smtpService() throws UnsupportedEncodingException {
        final InternetAddress from =
                new InternetAddress(fromEmail, fromName);
        final InternetAddress intercept =
                new InternetAddress(interceptEmail, interceptName);
        return CachingEmailSmtpService.create(
                SimpleSmtpService
                        .builder(from, null, intercept)
                        .interceptAll(interceptAll)
                        .charset(charset)
                        .server(smtpServer())
                        .build(),
                mailCache);
    }

    @Bean
    public InternetAddress exceptionAddress() throws AddressException {
        return new InternetAddress(emailException);
    }

}

