public class DivisibleBy5And6 {
    public static void main(String[] args) {
        final int LOWER_LIMIT = 100;
        final int UPPER_LIMIT = 1000;
        final int NUMBERS_PER_LINE = 10;

        int count = 0;
        for (int i = LOWER_LIMIT; i <= UPPER_LIMIT; i++) {
            if (i % 5 == 0 && i % 6 == 0) {
                System.out.print(i + " ");
                count++;
                if (count % NUMBERS_PER_LINE == 0) {
                    System.out.println();
                }
            }
        }
    }
}

public class VendorInfoBuilder implements SectionBuilder {
    private String vendorId;
    private final List<String> payloadLines = new ArrayList<>();

    @Override
    public String getSectionName() {
        return Constants.VendorSectionName;
    }

    @Override
    public void reset() {
        vendorId = null;
        payloadLines.clear();
    }

    @Override
    public void processLine(String line) {
        if (vendorId == null) {
            vendorId = line.trim();
        } else {
            payloadLines.add(line);
        }
    }

    @Override
    public void build(State state) throws ParseException {
        if (vendorId == null || vendorId.isEmpty()) {
            throw new ParseException("Invalid vendor section: missing identifier");
        }

        VendorInfo vendorInfo = new VendorInfo(vendorId, new ArrayList<>(payloadLines));
        Stratum currentStratum = state.getCurrentStratum();

        if (currentStratum == null) {
            throw new ParseException("Cannot attach vendor info - no active stratum");
        }

        currentStratum.addVendorInfo(vendorInfo);
    }
}

class VendorInfo {
    private final String identifier;
    private final List<String> payload;

    public VendorInfo(String identifier, List<String> payload) {
        if (identifier == null || identifier.isEmpty()) {
            throw new IllegalArgumentException("Vendor identifier required");
        }
        this.identifier = identifier;
        this.payload = Collections.unmodifiableList(new ArrayList<>(payload));
    }

    public String getIdentifier() {
        return identifier;
    }

    public List<String> getPayload() {
        return payload;
    }
}

class Logger {

    int MAXN = 4000005;

    int[] lp = new int[MAXN];
    boolean[] prime = new boolean[MAXN];

    public void sieve() {
        for(int i=0;i<MAXN;i++){
            prime[i] = true;
        }
        prime[0] = prime[1] = false;
        for(int i=2;i*i<MAXN;i++){
            if(prime[i]){
                for(int j=2*i;j<MAXN;j+=i){
                    prime[j] = false;
                }
            }
        }
    }

    public int diagonalPrime(int[][] nums) {
        sieve();
        int ans = 0;
        int m = nums.length;
        int n = nums[0].length;
        for(int i = 0; i < m; i++) {
            if(prime[nums[i][i]]) {
                ans = Math.max(ans, nums[i][i]);
            }
            if(prime[nums[i][m - 1 - i]]) {
                ans = Math.max(ans, nums[i][m - 1 - i]);
            }
        }

        return ans;
    }
}

public static double[][] mult(double a[][], double b[][]){//a[m][n], b[n][p]
   if(a.length == 0) return new double[0][0];
   if(a[0].length != b.length) return null; //invalid dims
 
   int n = a[0].length;
   int m = a.length;
   int p = b[0].length;
 
   double ans[][] = new double[m][p];
 
   for(int i = 0;i < m;i++){
      for(int j = 0;j < p;j++){
         for(int k = 0;k < n;k++){
            ans[i][j] += a[i][k] * b[k][j];
         }
      }
   }
   return ans;
}

