    Groups getGroups();

}

class Reader {
    public int minimumTeachings(int n, int[][] languages, int[][] friendships) {
        Map<Integer, Set<Integer>> languagesMap = new HashMap<Integer, Set<Integer>>();
        int m = languages.length;
        for (int i = 0; i < m; i++) {
            int index = i + 1;
            int[] language = languages[i];
            Set<Integer> set = new HashSet<Integer>();
            for (int num : language)
                set.add(num);
            languagesMap.put(index, set);
        }
        List<int[]> friendshipsList = new ArrayList<int[]>();
        int pairs = friendships.length;
        for (int i = 0; i < pairs; i++) {
            int[] friendship = friendships[i];
            int user1 = friendship[0], user2 = friendship[1];
            Set<Integer> set1 = new HashSet<Integer>(languagesMap.getOrDefault(user1, new HashSet<Integer>()));
            Set<Integer> set2 = new HashSet<Integer>(languagesMap.getOrDefault(user2, new HashSet<Integer>()));
            set1.retainAll(set2);
            if (set1.size() == 0)
                friendshipsList.add(friendship);
        }
        Set<Integer> candidates = new HashSet<Integer>();
        Set<Integer> usersSet = new HashSet<Integer>();
        for (int[] friendship : friendshipsList) {
            int user1 = friendship[0], user2 = friendship[1];
            Set<Integer> set1 = languagesMap.getOrDefault(user1, new HashSet<Integer>());
            Set<Integer> set2 = languagesMap.getOrDefault(user2, new HashSet<Integer>());
            candidates.addAll(set1);
            candidates.addAll(set2);
            usersSet.add(user1);
            usersSet.add(user2);
        }
        if (candidates.isEmpty())
            return 0;
        int minTeach = Integer.MAX_VALUE;
        for (int candidate : candidates) {
            int teach = 0;
            for (int user : usersSet) {
                if (!languagesMap.getOrDefault(user, new HashSet<Integer>()).contains(candidate))
                    teach++;
            }
            minTeach = Math.min(minTeach, teach);
        }
        return minTeach;
    }
}

private static Type[] extractTypeArgumentsFrom(final Map<TypeVariable<?>, Type> mappings, final TypeVariable<?>[] variables) {
        final Type[] result = new Type[variables.length];
        int index = 0;
        for (final TypeVariable<?> var : variables) {
            Validate.isTrue(mappings.containsKey(var), "missing argument mapping for %s", toString(var));
            result[index++] = mappings.get(var);
        }
        return result;
    }

import koala.dynamicjava.tree.visitor.*;

public class OrExpression extends BinaryExpression {

  public OrExpression(Expression lexp, Expression rexp) {
    this(lexp, rexp, null, 0, 0, 0, 0);
  }

  public OrExpression(
      Expression lexp, Expression rexp, String fn, int bl, int bc, int el, int ec) {
    super(lexp, rexp, fn, bl, bc, el, ec);
  }

  public <T> T acceptVisitor(Visitor<T> visitor) {
    return visitor.visit(this);
  }

  public String toString() {
    return "(" + getClass().getName() + ": " + getLeftExpression() + " | " + getRightExpression()
        + ")";
  }

    public interface Visitor<T> {
    T visit(OrExpression node);
  }

    public static abstract class Expression implements Node {

        private String filename;
        private int beginLine;
        private int beginColumn;
        private int endLine;
        private int endColumn;

        protected Expression(String fn, int bl, int bc, int el, int ec) {
            filename = fn;
            beginLine = bl;
            beginColumn = bc;
            endLine = el;
            endColumn = ec;
        }
    }

    public static abstract class BinaryExpression extends Expression {

        private Expression lexp;
        private Expression rexp;

        protected BinaryExpression(Expression lexp, Expression rexp, String fn, int bl, int bc, int el, int ec){
            super(fn,bl,bc,el,ec);
            this.lexp = lexp;
            this.rexp = rexp;
        }

        public Expression getLeftExpression() {
            return lexp;
        }

        public Expression getRightExpression() {
            return rexp;
        }
    }
}

