import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
 
public class Sparkline {
 
    private static final String bar = "▁▂▃▄▅▆▇█";
    private static final int barcount = bar.length();
 
    public static void main(String[] args) {
        String[] lines = ("0 0 1 1; 0 1 19 20; 0 999 4000 4999 7000 7999;"
                + "1 2 3 4 5 6 7 8 7 6 5 4 3 2 1;"
                + "1.5, 0.5 3.5, 2.5 5.5, 4.5 7.5, 6.5 ").split(";");
 
        for (String line : lines) {
            System.out.println("\nNumbers: " + line);
            List<Double> numbers = new ArrayList<>();
            Pattern p = Pattern.compile("[\\s,]+");
            Matcher m = p.matcher(line.trim());
            while (m.find()) {
                numbers.add(Double.parseDouble(m.group()));
            }
            double mn = Double.MAX_VALUE;
            double mx = Double.MIN_VALUE;
            for (double n : numbers) {
                mn = Math.min(mn, n);
                mx = Math.max(mx, n);
            }
            double extent = mx - mn;
            StringBuilder sb = new StringBuilder();
            for (double n : numbers) {
                sb.append(bar.charAt(Math.min(barcount - 1,
                        (int) ((n - mn) / extent * barcount))));
            }
            System.out.println("  min: " + mn + "; max: " + mx);
            System.out.println("  " + sb.toString());
        }
    }
}

import java.util.Random;

/**
 * A 3D ball that a Player can be near or kick.
 */
class Ball {
    private float posX;
    private float posY;
    private float posZ;

    public Ball(float posX, float posY, float posZ) {
        this.posX = posX;
        this.posY = posY;
        this.posZ = posZ;
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public float getZ() {
        return posZ;
    }

    public void setZ(float posZ) {
        this.posZ = posZ;
    }

    public void setXYZ(float posX, float posY, float posZ) {
        this.posX = posX;
        this.posY = posY;
        this.posZ = posZ;
    }

    @Override
    public String toString() {
        return "(" + posX + "," + posY + "," + posZ + ")";
    }
}

public class Player {
    private int jerseyNumber;
    private float posX;
    private float posY;
    private float posZ;

    public Player(int jerseyNumber, float posX, float posY, float posZ) {
        this.jerseyNumber = jerseyNumber;
        this.posX = posX;
        this.posY = posY;
        this.posZ = posZ;
    }

    public void move(float xDisp, float yDisp) {
        posX += xDisp;
        posY += yDisp;
    }

    public void jump(float zDisp) {
        posZ += zDisp;
    }

    public boolean near(Ball ball) {
        double distance = Math.sqrt(
                Math.pow(ball.getX() - posX, 2)
                + Math.pow(ball.getY() - posY, 2)
                + Math.pow(ball.getZ() - posZ, 2));
        return distance < 8;
    }

    public void kick(Ball ball) {
        Random rand = new Random();
        ball.setX(ball.getX() + rand.nextInt(20));
        ball.setY(ball.getY() + rand.nextInt(20));
        ball.setZ(ball.getZ() + rand.nextInt(5));
    }
}

