public class Calculator {
    public int maximumProduct(int[] nums) {
        if (nums == null || nums.length < 3){
            return 0;
        }

        Arrays.sort(nums);
        int m = nums.length - 1;
        return Math.max(nums[0]*nums[1]*nums[m], nums[m] * nums[m-1] * nums[m-2]);
    }
}

 
import java.awt.*;
import java.awt.geom.Path2D;
import javax.swing.*;
import java.lang.Math;
 
/* assumes a == b */
public class SuperEllipse extends JPanel {
    private final double n;
    private final int a;
 
    public SuperEllipse(double n, int a) {
        if (n <= 0.0 || a <= 0) {
            throw new IllegalArgumentException();
        }
        this.n = n;
        this.a = a;
        setPreferredSize(new Dimension(650, 650));
        setBackground(Color.black);
    }
 
    private void drawEllipse(Graphics2D g) {
        double[] points = new double[a + 1];
        Path2D p = new Path2D.Double();
        p.moveTo(a, 0.0);
 
        // calculate first quadrant
        for (int x = a; x >= 0; x--) {
            points[x] = Math.pow(Math.pow(a, n) - Math.pow(x, n), 1.0 / n);
            p.lineTo(x, -points[x]);
        }
 
        // mirror to others
        for (int x = 0; x <= a; x++) p.lineTo(x, points[x]);
        for (int x = a; x >= 0; x--) p.lineTo(-x, points[x]);
        for (int x = 0; x <= a; x++) p.lineTo(-x, -points[x]);
 
        g.translate(getWidth() / 2, getHeight() / 2);
        g.setColor(Color.yellow);
        g.fill(p);
    }
 
    @Override
    public void paintComponent(Graphics gg) {
        super.paintComponent(gg);
        Graphics2D g = (Graphics2D) gg;
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                           RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                           RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        drawEllipse(g);
    }
}
 
public class SuperEllipseDemo {
    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                JFrame f = new JFrame();
                f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
                f.setTitle("Super Ellipse");
                f.setResizable(false);
                f.add(new SuperEllipse(2.5, 200), BorderLayout.CENTER);
                f.pack();
                f.setLocationRelativeTo(null);
                f.setVisible(true);
            }
        });
    }
}

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.Random;
import javax.imageio.ImageIO;
 
public class BarnsleyFern {
 
    private int imgWidth, imgHeight;
    private Color paintColor, bgColor;
    private double x, y;
    private int age;
 
    private BufferedImage fern;
    private int[][] pix;
 
    public BarnsleyFern(int imgWidth, int imgHeight, Color paintColor, Color bgColor) {
        this.imgWidth = imgWidth;
        this.imgHeight = imgHeight;
        this.paintColor = paintColor;
        this.bgColor = bgColor;
        this.x = 0;
        this.y = 0;
        this.age = 0;
 
        this.fern = new BufferedImage(imgWidth, imgHeight, BufferedImage.TYPE_INT_RGB);
        this.pix = new int[imgWidth][imgHeight];
        this.pix[(int) scale(0, 0)[0]][(int) scale(0, 0)[1]] = paintColor.getRGB();
    }
 
    private double[] scale(double x, double y) {
        double[] scaled = new double[2];
        scaled[0] = (x + 2.182) * (imgWidth - 1) / 4.8378;
        scaled[1] = (9.9983 - y) * (imgHeight - 1) / 9.9983;
        return scaled;
    }
 
    private double[] transform(double x, double y) {
        double[] transformed = new double[2];
        Random rand = new Random();
        double randNum = rand.nextDouble() * 100;
        if (randNum < 1) {
            transformed[0] = 0;
            transformed[1] = 0.16 * y;
        } else if (1 <= randNum && randNum < 86) {
            transformed[0] = 0.85 * x + 0.04 * y;
            transformed[1] = -0.04 * x + 0.85 * y + 1.6;
        } else if (86 <= randNum && randNum < 93) {
            transformed[0] = 0.2 * x - 0.26 * y;
            transformed[1] = 0.23 * x + 0.22 * y + 1.6;
        } else {
            transformed[0] = -0.15 * x + 0.28 * y;
            transformed[1] = 0.26 * x + 0.24 * y + 0.44;
        }
        return transformed;
    }
 
    public void iterate(int iterations) {
        for (int i = 0; i < iterations; i++) {
            double[] transformed = transform(x, y);
            x = transformed[0];
            y = transformed[1];
            pix[(int) scale(x, y)[0]][(int) scale(x, y)[1]] = paintColor.getRGB();
        }
        age += iterations;
    }
 
    public void saveImage(String filename) {
        try {
            File outputfile = new File(filename);
            ImageIO.write(fern, "png", outputfile);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
