import com.google.common.collect.ImmutableSet;
import com.intellij.codeInspection.ex.InspectionElementsMergerBase;
import com.intellij.openapi.util.ArrayUtilRt;
import org.jdom.Attribute;
import org.jdom.Element;
import org.jetbrains.annotations.NotNull;

import java.util.Map;
import java.util.Set;
import java.util.ArrayList;
import java.util.List;

/**
 * This merger consolidates multiple redundant string operation inspections
 * into a single unified inspection configuration. It handles current and legacy
 * configurations, merging them seamlessly into the new inspection tool settings.
 */
public class MergedStringOperationsMerger extends InspectionElementsMergerBase {

    // Constant representing a legacy merger name used for identification
    private static final String LEGACY_MERGER_NAME = "LegacyStringOperationsMerger";

    // An immutable set of legacy inspection tool names that are subject to merger.
    private static final Set<String> LEGACY_SOURCE_NAMES = ImmutableSet.of(
            "StringConcatCheck",
            "RedundantStringCheck",
            "LegacyStringInspection"
    );

    /**
     * Returns the name of the merged inspection tool.
     *
     * @return the merged tool name.
     */
    @NotNull
    @Override
    public String getMergedToolName() {
        return "MergedStringOperations";
    }

    /**
     * Retrieves an individual inspection configuration element from the provided mapping.
     * It first checks for the current tool name, and if not found, it attempts to locate and
     * transform a legacy configuration element.
     *
     * @param provider a map containing tool names as keys and their configuration elements as values.
     * @param toolName the name of the tool to find.
     * @return an XML Element representing the merged inspection configuration, or null if not found.
     */
    @Override
