import java.util.Scanner;
import java.util.Vector;
import java.util.Iterator;
import java.util.StringTokenizer;
import java.lang.Math;
 
public class RPN {
  public static double rpn(String expr) {
    Scanner iss = new Scanner(expr);
    Vector<Double> stack = new Vector<Double>();
    System.out.println("Input\tOperation\tStack after");
    String token;
    while (iss.hasNext()) {
      token = iss.next();
      System.out.print(token + "\t");
      double tokenNum;
      try {
    tokenNum = Double.parseDouble(token);
    System.out.print("Push\t\t");
    stack.add(tokenNum);
      } catch (NumberFormatException e) {
    System.out.print("Operate\t\t");
    double secondOperand = stack.lastElement();
    stack.remove(stack.size() - 1);
    double firstOperand = stack.lastElement();
    stack.remove(stack.size() - 1);
    if (token.equals("*"))
      stack.add(firstOperand * secondOperand);
    else if (token.equals("/"))
      stack.add(firstOperand / secondOperand);
    else if (token.equals("-"))
      stack.add(firstOperand - secondOperand);
    else if (token.equals("+"))
      stack.add(firstOperand + secondOperand);
    else if (token.equals("^"))
      stack.add(Math.pow(firstOperand, secondOperand));
    else { //just in case
      System.out.println("Error");
      System.exit(1);
    }
      }
      Iterator<Double> it = stack.iterator();
      while (it.hasNext()) {
    System.out.print(it.next() + " ");
      }
      System.out.println();
    }
    return stack.lastElement();
  }
 
  public static void main(String[] args) {
    String s = " 3 4 2 * 1 5 - 2 3 ^ ^ / + ";
    System.out.println("Final answer: " + rpn(s));
  }
}

import java.util.ArrayList;

