import java.io.*;

public class UpTheStrip {

    private static class MyScanner {

        BufferedReader br;

        StringTokenizer st;

        public MyScanner() {

           br = new BufferedReader(new InputStreamReader(System.in));

        }

        String next() {

            while (st == null || !st.hasMoreElements()) {

                try {

                    st = new StringTokenizer(br.readLine());

                } catch (IOException e) {

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }

        int nextInt() {

            return Integer.parseInt(next());

        }

        long nextLong() {

            return Long.parseLong(next());

        }

        double nextDouble() {

            return Double.parseDouble(next());

        }

        String nextLine(){

            String str = "";

          try {

             str = br.readLine();

          } catch (IOException e) {

             e.printStackTrace();

          }

          return str;

        }

     }

    public static long solution(long n, long m) {

        long[] dp  = new long[(int)n];

        long[] sum  = new long[(int)n];

        dp[0] = 1;

        sum[0] = 0;

        long prev = 1;

        for(int i = 2; i<=n; i++) {

            dp[i-1] = prev;

            sum[i-1] = (sum[i-1] + sum[i-2])%m;

            sum[i-1] = (sum[i-1] + dp[0])%m;

            dp[i-1] = (dp[i-1] + sum[i-1])%m;

            prev = (prev + dp[i-1])%m;

            int j = i+i;

            while(j<=n)

            {

                sum[j-1] = (sum[j-1] + dp[i-1])%m;

                sum[j-1] = (sum[j-1] - dp[i-2] + m)%m;

                j+=i;

            }

        }

        return dp[(int)n-1];

    }

private static PrintWriter out = new PrintWriter(System.out);

public static void main (String[] args)

{

    MyScanner s =  new MyScanner();

    long n = s.nextLong();

    long m = s.nextLong();

    out.println(solution(n,m));

    out.flush();

    out.close();

}

}

import java.util.*;

public class Processor {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter the sides of a triangle separated by spaces: ");
        double s1 = in.nextDouble();
        double s2 = in.nextDouble();
        double s3 = in.nextDouble();

        if (s3 > (s1 + s2) || s2 > (s1 + s3) || s1 > (s3 + s2)) {
