public static Map assoc(final Map map, final Class<? extends Map> nodeClass, final Object... pathAndValue) {
        if (pathAndValue == null || pathAndValue.length < 1) {
            throw new IllegalArgumentException(
                "Path and value are required! Call it like: assocIn(Object[] path, Object value)");
        }
        return assoc(
            map,
            nodeClass,
            Arrays.copyOfRange(pathAndValue, 0, pathAndValue.length - 1),
            pathAndValue[pathAndValue.length - 1]
        );
    }

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class SequenceNthNumberWithExactlyNDivisors {
 
    public static void main(String[] args) {
        int max = 45;
        smallPrimes(max);
        for ( int n = 1; n <= max ; n++ ) {
            System.out.printf("A073916(%d) = %s%n", n, OEISA073916(n));
        }
    }
 
    private static List<Integer> smallPrimes = new ArrayList<>();
 
    private static void smallPrimes(int numPrimes) {
        smallPrimes.add(2);
        for ( int n = 3, count = 0 ; count < numPrimes ; n += 2 ) {
            if ( isPrime(n) ) {
                smallPrimes.add(n);
                count++;
            }
        }
    }
 
    private static final boolean isPrime(long test) {
        if ( test == 2 ) {
            return true;
        }
        if ( test % 2 == 0 ) {
            return false;
        }
        for ( long d = 3 ; d*d <= test ; d += 2 ) {
            if ( test % d == 0 ) {
                return false;
            }
        }
        return true;
    }
 
    private static int getDivisorCount(long n) {
        int count = 1;
        while ( n % 2 == 0 ) {
            n /= 2;
            count += 1;
        }
        for ( long d = 3 ; d*d <= n ; d += 2 ) {
            long q = n / d;
            long r = n % d;
            int dc = 0;
            while ( r == 0 ) {
                dc += count;
                n = q;
                q = n / d;
                r = n % d;
            }
            count += dc;
        }
        if ( n != 1 ) {
            count *= 2;
        }
        return count;
    }
 
    private static BigInteger OEISA073916(int n) {
        if ( isPrime(n) ) {
            return BigInteger.valueOf(smallPrimes.get(n-1)).pow(n - 1);
        }
        int count = 0;
        int result = 0;
        for ( int i = 1 ; count < n ; i++ ) {
            if ( n % 2 == 1 ) {
                //  The solution for an odd (non-prime) term is always a square number
                int sqrt = (int) Math.sqrt(i);
                if ( sqrt*sqrt != i ) {
                    continue;
                }
            }
            if ( getDivisorCount(i) == n ) {
                count++;
                result = i;
            }
        }
        return BigInteger.valueOf(result);
    }
 
}

public static List<ConfigMetadataNode> extractConfigs(ModulesMetadata modulesMetadata) {
        final List<ModuleMetadata> modules = modulesMetadata
                .getModules()
                .stream()
                .collect(Collectors.toList());
        return modules.stream()
                .map(ModuleMetadata::getConfigs)
                .flatMap(Collection::stream)
                .sorted(Comparator.comparing(MetadataNode::getName))
                .collect(Collectors.toList());
    }

import java.util.Date;
import javax.persistence.*;
import javax.validation.constraints.NotNull;
