@Entity
@Table(
    name = "client_logs",
    uniqueConstraints = {@UniqueConstraint(columnNames = {"user_id", "created_on"})}
)
public class ClientLog extends OwnedEntity {

  @Lob
  @Length(max = 16777215)
  @Column(name = "data", length = 16777215)
  private String data;

  @NotNull
  @Temporal(TemporalType.TIMESTAMP)
  @Column(name = "created_on", nullable = false)
  private Date createdOn;

  public ClientLog() {}

  public ClientLog(String userId, String data) {
    super(userId);
    this.data = data;
    this.createdOn = new Date();
  }

  public ClientLog(ClientLog clone) {
    super(clone.getUserId());
    this.data = clone.getData();
    this.createdOn = clone.getCreatedOn();
  }

  public String getData() {
    return data;
  }

  public void setData(String data) {
    this.data = data;
  }

  public Date getCreatedOn() {
    return createdOn;
  }

  public void setCreatedOn(Date createdOn) {
    this.createdOn = createdOn;
  }

  @Override
  public String toString() {
    return new ToStringBuilder(this)
        .append("data", data)
        .append("createdOn", createdOn)
        .toString();
  }
}

