public static void quote(StringBuilder buf, String arg)
   {
      if (!mightNeedQuotes(arg)) {
         buf.append(arg);
         return;
      }
      buf.append('"');

      int nPending = 0;
      for (int i = 0; i < arg.length(); i++) {
         char c = arg.charAt(i);
         if (c == '\\') {
            nPending++;
         }
         else {
            if (c == '"') {

               for (int j = 0; j < nPending; j++) {
                  buf.append('\\');
               }

               buf.append('\\');
            }
            nPending = 0;
         }
         buf.append(c);
      }

      for (int j = 0; j < nPending; j++) {
         buf.append('\\');
      }
      buf.append('"');
   }

import java.util.ArrayList;
import java.util.Arrays;
