import com.intellij.openapi.fileEditor.FileDocumentManager;
import com.intellij.openapi.fileEditor.FileEditorManager;
import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiDocumentManager;
import com.intellij.psi.PsiFile;
import javax.swing.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class ReformatCodeAction extends AnAction {

    @Override
    public void update(AnActionEvent e) {
        Project project = e.getProject();
        Editor editor = e.getData(CommonDataKeys.EDITOR);
        boolean enabled = project != null && editor != null && canFormatFile(project, editor);
        e.getPresentation().setEnabled(enabled);
    }

    @Override
    public void actionPerformed(AnActionEvent e) {
        Project project = e.getProject();
        Editor editor = e.getData(CommonDataKeys.EDITOR);
        if (project == null || editor == null || !canFormatFile(project, editor)) {
            return;
        }

        LayoutCodeDialog dialog = new LayoutCodeDialog(project, editor);
        if (dialog.showAndGet()) {
            FileInEditorProcessor processor = new FileInEditorProcessor(project, editor, dialog.getFormattingOptions());
            processor.reformatFile();
        }
    }

    private boolean canFormatFile(Project project, Editor editor) {
        PsiFile file = PsiDocumentManager.getInstance(project).getPsiFile(editor.getDocument());
        return file != null && LanguageFormatting.INSTANCE.forLanguage(file.getLanguage()) != null;
    }

    private static class LayoutCodeDialog extends DialogWrapper {
        private final Project myProject;
        private final Editor myEditor;
        private JCheckBox myOptimizeImports;
        private JCheckBox myReformatAll;

        protected LayoutCodeDialog(Project project, Editor editor) {
            super(project);
            myProject = project;
            myEditor = editor;
            setTitle("Reformat Code");
            init();
        }

        @Override
        protected JComponent createCenterPanel() {
            JPanel panel = new JPanel();
            myOptimizeImports = new JCheckBox("Optimize Imports");
            myReformatAll = new JCheckBox("Reformat All");
            panel.add(myOptimizeImports);
            panel.add(myReformatAll);
            return panel;
        }

public List<String> escapePiecesForUri(final List<String> pieces) {
    final List<String> escapedPieces = new ArrayList<>();
    for (String piece : pieces) {
        String escapedPiece = piece.replace(" ", "%20");
        escapedPiece = escapedPiece.replace("&", "%26");
        escapedPiece = escapedPiece.replace("=", "%3D");
        escapedPiece = escapedPiece.replace("?", "%3F");
        escapedPiece = escapedPiece.replace("#", "%23");
        escapedPiece = escapedPiece.replace("/", "%2F");
        escapedPiece = escapedPiece.replace(":", "%3A");
        escapedPiece = escapedPiece.replace("@", "%40");
        escapedPiece = escapedPiece = escapedPiece.replace("$", "%24");
        escapedPiece = escapedPiece.replace(",", "%2C");
        escapedPiece = escapedPiece.replace(";", "%3B");
        escapedPiece = escapedPiece.replace("+", "%2B");
        escapedPiece = escapedPiece.replace("'", "%27");
        escapedPiece = escapedPiece.replace("(", "%28");
        escapedPiece = escapedPiece.replace(")", "%29");
        escapedPiece = escapedPiece.replace("[", "%5B");
        escapedPiece = escapedPiece.replace("]", "%5D");
        escapedPieces.add(escapedPiece);
    }
    return escapedPieces;
}

