#include <stdio.h>
#include <math.h>
#include <string.h>
#include <algorithm>
using namespace std;
int main() {
    int t;
    scanf("%d", &t);
    while(t--) {
        int n;
        scanf("%d", &n);
        int k[n];
        memset(k, 0, sizeof(k));
        for(n; n--;)
            scanf("%d", &k[n]);
        if(k[2] % 16 == 0) {
            printf("%c\n", 8);
            for(int i = 0; i <= ceil(k[2]/16) - 1; ++i)
                if(i % 2 == 0)
                    printf("%d", i + 1);
                else
                    printf("%c", 8);
            for(int i = 0; i < ceil(k[2]/16) - 1; ++i)
                printf("\n");
            for(int i = 0; i < ceil(k[2]/16); ++i)
                printf("%d", i + 1);
            for(int i = 0; i < ceil(k[2]/16); ++i)
                printf("%c", 8);
            if(i < ceil(k[2]/16))
                printf("\n");
        } else {
            int a[2][n];
            memset(a, 0, sizeof(a));
            for(int i = 0; i < 2; ++i) {
                for(int j = 1; j < n && j < ceil(k[2]/16); ++j) {
                    if(i) {
                        ++a[i][j];
                        --k[j];
                    } else {
                        a[i][j] = 1;
                    }
                }
            }
            for(int i = 0; i <= 1; ++i) {
                for(int j = 0; j < n; ++j)
                    for(int k = j, l = 0; k < n && l < a[1-i][k] - 1; ++k, ++l) {
                        a[i][j] += a[1-i][k];
                        if(i)
                        --k[j];
                    }
            }
            bool flag = true;
            for(int i = 0; i < n; ++i) {
                if(a[0][i] != a[1][i])
                    flag = false;
            }
            printf("%d\n", flag);
            for(int i = 0; i < 2; ++i)
                for(int j = 0; j < n; ++j)
                    for(int k = 0; k < a[i][j]; ++k)
                        printf("%c", 8);
                for(int j = 0; j < ceil(k[2]/16) - 1; ++j)
                    printf("\n");
        }
    }
    return 0;
}

public class Program {
    /*
    u-> four(4)
    x-> six(6)
    v-> seven(7)
    z-> zero(0)
    */
    public String originalDigits(String s) {
        //assume that s is always valid
        String[] dict = {"zero","ufor","five","xis","vense","wto","one","rthee","heigt","nine"};
        int[] table = {0,4,5,6,7,2,1,3,8,9};
        int[] remains = new int[26];
        StringBuilder sb = new StringBuilder();
        char[] arr = s.toCharArray();
        for(int i=0;i<arr.length;i++) {
            remains[arr[i]-'a'] += 1;
        }
        for(int i=0;i<dict.length;i++) {
            char[] num = dict[i].toCharArray();
            while(remains[num[0]-'a'] > 0) {
                remains[num[0]-'a'] -= 1;
                for(int j=1;j<num.length;j++) {
                    remains[num[j]-'a'] -= 1;
                }
                sb.append(table[i]);
            }
        }
        char[] res = sb.toString().toCharArray();
        Arrays.sort(res);
        return String.valueOf(res);
    }
}

