/** "Girisi Yasak" trafik levhasini geometrik sekillerle ciziyor. */
public class GirisYasaktirIsareti extends JPanel {

    private static final long serialVersionUID = 1L;

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);

        Point ortaNokta = new Point(getWidth() / 2, getHeight() / 2);

        int disCemberYaricapi = Math.min(getWidth() / 2, getHeight() / 2) - 5;
        int icCemberYaricapi = (int) (disCemberYaricapi * 0.9);
        int cubukUzunlugu = (int) (icCemberYaricapi * 1.4);
        int cubukKalinligi = (int) (icCemberYaricapi * 0.35);

        // Levhanin beyaz kenarligi
        tuval.setColor(Color.WHITE);
        tuval.fillOval(ortaNokta.x - disCemberYaricapi, ortaNokta.y - disCemberYaricapi,
                2 * disCemberYaricapi, 2 * disCemberYaricapi);

        // Kirmizi govde
        tuval.setColor(Color.RED);
        tuval.fillOval(ortaNokta.x - icCemberYaricapi, ortaNokta.y - icCemberYaricapi,
                icCemberYaricapi * 2, icCemberYaricapi * 2);

        // Ortadaki yatay beyaz cubuk
        tuval.setColor(Color.WHITE);
        tuval.fillRect(ortaNokta.x - cubukUzunlugu / 2, ortaNokta.y - cubukKalinligi / 2,
                cubukUzunlugu, cubukKalinligi);
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            GirisYasaktirIsareti levha = new GirisYasaktirIsareti();
            levha.setBackground(Color.GREEN.darker());

            JFrame pencere = new JFrame("Giris Yasaktir!");
            pencere.setSize(400, 300);
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            pencere.getContentPane().add(levha, BorderLayout.CENTER);
            pencere.setVisible(true);
        });
    }
}

public class AtamaIslemleri {

    public static void main(String[] args) {
        // Starting values for the walkthrough of compound assignment operators.
        int a = 5;
        int b = 10;
        int c = 15;

        a = a + b;
        System.out.println("Toplama ve Atama: x = " + a + " y = " + b); // a = 15

        a -= b;
        System.out.println("Cikarma ve Atama: x = " + a + " y = " + b); // a = 5

        a *= 2;
        System.out.println("Carpma ve Atama: x = " + a + " y = " + b); // a = 10

        a /= 4;
        System.out.println("Bolme ve Atama: x = " + a + " y = " + b); // a = 2

        a %= 3;
        System.out.println("Mod ve Atama: x = " + a + " y = " + b); // a = 2

        a += c;
        System.out.println("Toplama ve Atama (x + z): x = " + a + " z = " + c); // a = 17

        a *= c;
        System.out.println("Carpma ve Atama (x * z): x = " + a + " z = " + c); // a = 255

        a = c / a;
        System.out.println("Bolme ve Atama (z / x): x = " + a + " z = " + c); // a = 0

        a = b % (a + 1);
        System.out.println("Mod ve Atama (y % (x + 1)): x = " + a + " y = " + b); // a = 0

        a = 10;
        b += a;
        System.out.println("Toplama ve Atama (y + x): x = " + a + " y = " + b); // b = 20

        b /= a;
        System.out.println("Bolme ve Atama (y / x): x = " + a + " y = " + b); // b = 2

        a = -a;
        System.out.println("Negatif deger: x = " + a); // a = -10
    }
}

import java.util.ArrayList;
