/**
 * Prints a numbered menu and reads the chosen index.
 */
public class Menu {
    public static int getChoice(ArrayList<String> options) {
        int i = 1;
        for (String option : options) {
            System.out.println(i + "-" + option);
            i++;
        }
        System.out.print("Choose 1.." + options.size() + ": ");
        Scanner scanner = new Scanner(System.in);
        return Integer.parseInt(scanner.nextLine());
    }

    public static int getChoice(Object[] options) {
        int i = 1;
        for (Object option : options) {
            System.out.println(i + "-" + option.toString());
            i++;
        }
        System.out.print("Choose 1.." + options.length + ": ");
        Scanner scanner = new Scanner(System.in);
        return Integer.parseInt(scanner.nextLine());
    }
}

class Rational {
    private int numerator;
    private int denominator;

    public Rational(int numerator, int denominator) {
        if (denominator == 0) {
            throw new IllegalArgumentException("Denominator cannot be zero.");
        }

        // Make sure the negative sign is in the numerator only
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }

        this.numerator = numerator;
        this.denominator = denominator;
    }

    public Rational add(Rational other) {
        int commonDenominator = this.denominator * other.denominator;
        int sumNumerator = this.numerator * other.denominator + other.numerator * this.denominator;

        return new Rational(sumNumerator, commonDenominator);
    }

    public double toDouble() {
        return (double) this.numerator / this.denominator;
    }

    public String toString() {
        return this.numerator + "/" + this.denominator;
    }
}

public class SummationSeries {
    public static void main(String[] args) {
        Rational sum = new Rational(0, 1);

        for (int i = 1; i <= 99; i++) {
            Rational term = new Rational(i, i + 1);
            sum = sum.add(term);
        }

        System.out.println("Summation series result: " + sum.toDouble());
    }
}

import java.util.Arrays;
import java.util.stream.DoubleStream;
import java.util.stream.IntStream;

public class Fib1000 {
    public static void main(String[] args) {
        show(Fib1000(), "First 1000 Fibonacci numbers");
    }

    public static double[] Fib1000() {
        double a = 0, b = 1;
        double[] r = new double[1000];
        for (int i = 0; i < r.length; i++) {
            r[i] = b;
            b = b + a;
            a = b;
        }
        return r;
    }

    public static void show(double[] c, String title) {
        int[] f = new int[9];
        for (double v : c) {
            f[((int) v) - 1]++;
        }
        System.out.println(title);
        System.out.println("Digit  Observed  Predicted");
        for (int i = 0; i < f.length; i++) {
            System.out.printf("  %d  %9.3f  %8.3f\n", i + 1, (double) f[i] / c.length,
                    Math.log10(1 + 1 / (double) (i + 1)));
        }
    }
}

private Map<String, Object> parseTSUIDsList(HttpQuery query) {
