import net.sourceforge.plantuml.command.CommandExecutionResult;
import net.sourceforge.plantuml.command.SingleLineCommand2;
import net.sourceforge.plantuml.core.Diagram;
import net.sourceforge.plantuml.core.UmlSource;
import net.sourceforge.plantuml.regex.IRegex;
import net.sourceforge.plantuml.regex.MyPattern;
import net.sourceforge.plantuml.regex.RegexConcat;
import net.sourceforge.plantuml.regex.RegexResult;
import net.sourceforge.plantuml.regex.RegexSplitter;
import net.sourceforge.plantuml.skin.SkinParamUtils;

public class CommandAddData extends SingleLineCommand2 {

  public CommandAddData() {
    super(getRegexConcat());
  }

  static IRegex getRegexConcat() {
    return RegexConcat.build(
        CommandAddData.class.getName(),
        false,
        SkinParamUtils.COLOR_OR_FONT_OR_BACKGROUND_COLOR,
        "(?:[%s]+",
        "([a-zA-Z0-9_]+)",
        "[%s]+)?",
        ":",
        "[%. ]*(.+)",
        "[%. ]*");
  }

  @Override
  protected CommandExecutionResult executeArg(Diagram system, RegexResult result) {
    final AbstractClassOrObjectDiagram diagram = (AbstractClassOrObjectDiagram) system;
    final String entityName = result.get("1", 0);
    final String dataField = result.get("2", 0);

    IEntity entity = diagram.getEntity(entityName);
    if (entity == null) {
      entity = diagram.createEntity(entityName);
      if (entity == null) {
        return CommandExecutionResult.error("Cannot create entity " + entityName);
      }
    }

    diagram.addMember(entity, dataField);
    return CommandExecutionResult.ok();
  }
}

import com.intellij.codeInsight.AnnotationUtil;
import com.intellij.codeInspection.ProblemHighlightType;
