import java.util.Scanner;

public class Account {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m1 = sc.nextInt();
        int m2 = sc.nextInt();
        int[][] a = new int[n][n];
        int[][] b = new int[n][n];
        for (int i = 0; i < m1; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            a[x - 1][y - 1] = 1;
            a[y - 1][x - 1] = 1;
        }
        for (int i = 0; i < m2; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            b[x - 1][y - 1] = 1;
            b[y - 1][x - 1] = 1;
        }
        int count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 0 && b[i][j] == 0) {
                    count++;
                }
            }
        }
        System.out.println(count / 2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] == 0 && b[i][j] == 0) {
                    System.out.println((i + 1) + " " + (j + 1));
                }
            }
        }
    }
}

