import javax.xml.bind.annotation.adapters.XmlAdapter;
import javax.xml.bind.annotation.XmlElement;
import javax.xml.bind.annotation.XmlType;
import javax.xml.bind.annotation.XmlAccessorType;
import javax.xml.bind.annotation.XmlAccessType;

@XmlAccessorType(XmlAccessType.FIELD)
@XmlType(name = "tgspan", propOrder = {"value", "style"})
public class Tgspan {

    @XmlElement(name = "value", required = true)
    protected String value;

    @XmlElement(name = "style")
    protected String style;

    public Tgspan() {
    }

    public Tgspan(String value, String style) {
        this.value = value;
        this.style = style;
    }

    public String getValue() {
        return value;
    }

    public void setValue(String value) {
        this.value = value;
    }

    public String getStyle() {
        return style;
    }

    public void setStyle(String style) {
        this.style = style;
    }

    @Override
    public String toString() {
        return "Tgspan{" +
                "value='" + value + '\'' +
                ", style='" + style + '\'' +
                '}';
    }

    public static class StringAdapter extends XmlAdapter<String, String> {

        @Override
        public String unmarshal(String v) throws Exception {
            return normalizeString(v);
        }

        @Override
        public String marshal(String v) throws Exception {
            return v;
        }

        private String normalizeString(String value) {
            return value == null ? null : value.trim().replaceAll("\\s+", " ");
        }
    }

    public static void main(String[] args) {
        // Example usage
        Tgspan tgspan = new Tgspan("  Example text   ", "Bold");
        System.out.println(tgspan);
        System.out.println("Normalized Value: " + tgspan.getValue());

        // Setting a new value
        tgspan.setValue("   New styled text   ");
        System.out.println("Updated Tgspan: " + tgspan);
    }
}

@Override
public synchronized void prepareAnalyzer(Engine engine) throws InitializationException {
    try {
        // Load the suppression XML file
        File suppressionFile = new File("suppression.xml");
        if (!suppressionFile.exists()) {
            throw new InitializationException("Suppression file not found: " + suppressionFile.getAbsolutePath());
        }
        // Parse the suppression XML file
        DocumentBuilderFactory dbFactory = DocumentBuilderFactory.newInstance();
        DocumentBuilder dBuilder = dbFactory.newDocumentBuilder();
        Document doc = dBuilder.parse(suppressionFile);
        doc.getDocumentElement().normalize();
        // Process the parsed XML document
        NodeList nodeList = doc.getElementsByTagName("suppress");
        for (int i = 0; i < nodeList.getLength(); i++) {
            Node node = nodeList.item(i);
            if (node.getNodeType() == Node.ELEMENT_NODE) {
                Element element = (Element) node;
                String cve = element.getAttribute("cve");
                String justification = element.getAttribute("justification");
                // Add the suppression to the engine
                engine.addSuppression(cve, justification);
            }
        }
    } catch (Exception e) {
        throw new InitializationException("Error loading suppression file: " + e.getMessage(), e);
    }
}

