import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.HashCodeBuilder;

import javax.xml.bind.annotation.XmlElement;
import javax.xml.bind.annotation.XmlRootElement;

@XmlRootElement(name = "endpoints")
public class Endpoints {
    @XmlElement(name = "endpoint")
    private Set<Endpoint> endpoints;

    @XmlElement(name = "applicationName")
    private String application;

    @XmlElement(name = "links")
    private Map<String, URI> links;

    public Endpoints() {
        this.endpoints = new HashSet<>();
        this.links = new HashMap<>();
    }

    public Set<Endpoint> getEndpoints() {
        return endpoints;
    }

    public void setEndpoints(Set<Endpoint> endpoints) {
        this.endpoints = endpoints;
    }

    public String getApplication() {
        return application;
    }

    public void setApplication(String application) {
        this.application = application;
    }

    public Map<String, URI> getLinks() {
        return links;
    }

    public void setLinks(Map<String, URI> links) {
        this.links = links;
    }

    public void addEndpoint(Endpoint endpoint) {
        this.endpoints.add(endpoint);
    }

    public void addLink(String name, URI uri) {
        this.links.put(name, uri);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        Endpoints that = (Endpoints) obj;
        return new EqualsBuilder()
                .append(endpoints, that.endpoints)
                .append(application, that.application)
                .append(links, that.links)
                .isEquals();
    }

    @Override
    public int hashCode() {
        return new HashCodeBuilder(17, 37)
                .append(endpoints)
                .append(application)
                .append(links)
                .toHashCode();
    }

    @Override
    public String toString() {
        return "Endpoints{" +
                "endpoints=" + endpoints +
                ", application='" + application + '\'' +
                ", links=" + links +
                '}';
    }
}

