import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class Taus {
 
    public static void main(String[] args) {
        List<Integer> taus = new ArrayList<>();
        IntStream.iterate(1, n -> n + 1)
               .forEach(n -> {
                    int numDivisors = n
                           .primeFactors()
                           .values()
                           .stream()
                           .mapToInt(i -> i + 1)
                           .reduce(1, (a, b) -> a * b);
                    if (n % numDivisors == 0) {
                        taus.add(n);
                    }
                });
        System.out.println(taus.subList(0, 100));
    }
 
    public static Stream<Integer> primeFactors(int n) {
        return IntStream.iterate(2, i -> i + 1)
               .filter(i -> n % i == 0)
               .map(i -> {
                    int count = 0;
                    while (n % i == 0) {
                        n /= i;
                        count++;
                    }
                    return count;
                })
               .takeWhile(i -> i > 0);
    }
}

