import java.util.Random;
import java.util.Scanner;

public class SansOyunu {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);
        Random rng = new Random();

        System.out.println("0 ile 100 arasinda bir sayi giriniz:");
        int guess = input.nextInt();
        input.close();

        // Reject the guess early if it falls outside the valid range.
        boolean inRange = guess >= 0 && guess <= 100;
        if (!inRange) {
            System.out.println("Lutfen 0 ile 100 arasinda bir sayi giriniz.");
            return;
        }

        // Draw the outcome roll and apply a 35% win chance threshold.
        int roll = rng.nextInt(100);
        boolean isWin = roll < 35;

        System.out.println(isWin ? "Kazandiniz!" : "Kaybettiniz!");
    }
}

import java.util.Scanner;

public class QuadraticEquation {
    private double a;
    private double b;
    private double c;

    public QuadraticEquation(double a, double b, double c) {
        this.a = a;
        this.b = b;
        this.c = c;
    }

    public double getA() {
        return a;
    }

    public double getB() {
        return b;
    }

    public double getC() {
        return c;
    }

    public double getDiscriminant() {
        return b * b - 4 * a * c;
    }

    public double getRoot1() {
        double discriminant = getDiscriminant();
        if (discriminant < 0) {
            return 0;
        } else {
            return (-b + Math.sqrt(discriminant)) / (2 * a);
        }
    }

    public double getRoot2() {
        double discriminant = getDiscriminant();
        if (discriminant < 0) {
            return 0;
        } else {
            return (-b - Math.sqrt(discriminant)) / (2 * a);
        }
    }
}

public class TestQuadraticEquation {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the values of a, b, and c: ");
        double a = input.nextDouble();
        double b = input.nextDouble();
        double c = input.nextDouble();

        QuadraticEquation equation = new QuadraticEquation(a, b, c);

        double discriminant = equation.getDiscriminant();
        if (discriminant > 0) {
            double root1 = equation.getRoot1();
            double root2 = equation.getRoot2();
            System.out.println("The equation has two roots " + root1 + " and " + root2);
        } else if (discriminant == 0) {
            double root = equation.getRoot1();
            System.out.println("The equation has one root " + root);
        } else {
            System.out.println("The equation has no roots");
        }
    }
}

