public class AngloDuration {

    public static void main(String[] args) {
        System.out.println(angloDuration(7259));
        System.out.println(angloDuration(86400));
        System.out.println(angloDuration(6000000));
    }

    public static String angloDuration(int intSeconds) {
        return zip(weekParts(intSeconds), Arrays.asList("wk", "d", "hr", "min", "sec"))
               .filter(x -> x.get(0)!= null)
               .map(x -> x.get(0).toString() + " " + x.get(1))
               .collect(Collectors.joining(", "));
    }

    public static List<Integer> weekParts(int intSeconds) {
        return Stream.of(null, 7, 24, 60, 60)
               .reduceRight((a, x) -> {
                    int intRest = a.remaining;
                    int intMod = x == null? intRest : intRest % x;
                    return new Parts(intRest - intMod, intMod);
                }, new Parts(intSeconds, 0))
               .parts;
    }

    public static <A, B> List<List<Object>> zip(List<A> xs, List<B> ys) {
        return IntStream.range(0, xs.size())
               .mapToObj(i -> Arrays.asList(xs.get(i), ys.get(i)))
               .collect(Collectors.toList());
    }

    private static class Parts {
        public final int remaining;
        public final List<Integer> parts;

        public Parts(int remaining, int... parts) {
            this.remaining = remaining;
            this.parts = Arrays.stream(parts).boxed().collect(Collectors.toList());
        }
    }
}

public static void bitwise(int a, int b){
  System.out.println("a AND b: " + (a & b));
  System.out.println("a OR b: "+ (a | b));
  System.out.println("a XOR b: "+ (a ^ b));
  System.out.println("NOT a: " + ~a);
  System.out.println("a << b: " + (a << b)); // left shift
  System.out.println("a >> b: " + (a >> b)); // arithmetic right shift
  System.out.println("a >>> b: " + (a >>> b)); // logical right shift
  System.out.println("a rol b: " + Integer.rotateLeft(a, b)); //rotate left, Java 1.5+
  System.out.println("a ror b: " + Integer.rotateRight(a, b)); //rotate right, Java 1.5+
}

import java.io.IOException;
import java.io.ObjectInput;
import java.io.ObjectOutput;
import java.io.ObjectOutputStream;
import java.io.StringWriter;
import java.util.ArrayList;
import java.util.List;

import org.drools.core.WorkingMemory;
import org.drools.core.audit.event.LogEvent;
import org.kie.internal.event.KnowledgeRuntimeEventManager;

import com.thoughtworks.xstream.XStream;

/**
 * A logger of events generated by a working memory.
 * It stores its information in memory, so it can be retrieved later.
 */
public class WorkingMemoryInMemoryLogger extends WorkingMemoryLogger {

    private List<LogEvent> events            = new ArrayList<LogEvent>();

    public WorkingMemoryInMemoryLogger() {
    }

    public WorkingMemoryInMemoryLogger(final WorkingMemory workingMemory) {
        super( workingMemory );
    }

    public WorkingMemoryInMemoryLogger(final KnowledgeRuntimeEventManager session) {
        super( session );
    }

    @SuppressWarnings("unchecked")
    public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
        super.readExternal(in);
        events  = (List<LogEvent>) in.readObject();
    }

    public void writeExternal(ObjectOutput out) throws IOException {
        super.writeExternal(out);
        out.writeObject(events);
    }

    public String getEvents() {
        final XStream xstream = new XStream();
        StringWriter writer = new StringWriter();
        try {
            final ObjectOutputStream out = xstream.createObjectOutputStream(writer);
            out.writeObject( this.events );
            out.close();
        } catch (Throwable t) {
            throw new RuntimeException("Unable to create event output: " + t.getMessage());
        }
        return writer.toString();
    }

    /**
     * Clears all the events in the log.
     */
    public void clear() {
        this.events.clear();
    }

    /**
     * @see org.kie.audit.WorkingMemoryLogger
     */
    public void logEventCreated(final LogEvent logEvent) {
        this.events.add( logEvent );
    }

    public List<LogEvent> getLogEvents() {
        return this.events;
    }

}

public String getJniType(TypeMirror type) {
    if (TypeUtil.isPrimitiveOrVoid(type)) {
      return getPrimitiveObjCType(type);
    } else if (TypeUtil.isArray(type)) {
      return "jarray";
    } else if (typeUtil.isString(type)) {
      return "jstring";
    } else if (typeUtil.isClassType(type)) {
      return "jclass";
    }
    return "jobject";
  }

