public class ShortestSubarrayWithTargetSum {
    public static int shortestSubarrayWithTargetSum(int[] nums, int target) {
        int sum, start=0, minLength = Integer.MAX_VALUE;
        int n = nums.length;
        for (int end=0; end < n; end++) {
            // calculate the sum over subarray[start:end+1]
            sum = 0;  // sum of the subarray[start:end+1]
            for (int i = start; i <= end; i++)
                sum += nums[i];

            while (sum >= target) {
                if (sum == target)
                    minLength = Math.min(minLength, end-start+1);

                // remove the starting element of subarray[], so we can
                // seek for new subarray starting from position start+1
                sum -= nums[start++];
            }
        }

        // It is possible that minLength was never updated and still holds Integer.MAX_VALUE
        // in this case, we return -1 to indicate there is no subarray with target sum
        return minLength == Integer.MAX_VALUE ? -1 : minLength;
    }

    public static void main (String[] args) {
        int[] nums = {1,2,3};
        int target = 5;
        System.out.println(shortestSubarrayWithTargetSum(nums, target));  // Returns 2

        nums = new int[]{1,1,1,2,3};
        target = 4;
        System.out.println(shortestSubarrayWithTargetSum(nums, target));  // Returns 2

        nums = new int[]{2,4,6,8};
        target = 3;
        System.out.println(shortestSubarrayWithTargetSum(nums, target));  // Returns -1
    }
}
