import java.util.function.Function;

public class Builder<T> {
    private T instance;

    private Builder(T instance) {
        this.instance = instance;
    }

    public static <T> Builder<T> build(T instance) {
        return new Builder<>(instance);
    }

    public Builder<T> with(Function<T, T> function) {
        instance = function.apply(instance);
        return this;
    }

    public T build() {
        return instance;
    }
}

