public int[] solve(int[] nums, int pivot) {
    // First, initialize start and end pointers and curr pointer
    int start = 0, end = nums.length - 1;
    int curr = 0;

    // Then, we run a while loop till start is less than or equal to end
    while (start <= end) {
        // Base case: if the current element is less than pivot, swap it with the element at start index and increment both start and curr
        if (nums[curr] < pivot) {
            swap(nums, start, curr);
            start++;
            curr++;

        // Base case: if the current element is greater than or equal to pivot, swap it with the element at end index and decrement end
        } else if (nums[curr] >= pivot) {
            swap(nums, end, curr);
            end--;
        }
        // If current element is equal to pivot, increment curr
        else {
            curr++;
        }
    }
    // Return the modified array
    return nums;
}

// This function is to swap the elements at positions i and j in the array
private void swap(int[] nums, int i, int j) {
    int temp = nums[i];
    nums[i] = nums[j];
    nums[j] = temp;
}

class Calculator {
    public long minCost(int[] a, int[] b) {
        int min = Integer.MAX_VALUE;
        Map<Integer, Integer> map1 = new HashMap<>();
        for(int x : a){
            min = Math.min(min, x);
            map1.put(x, map1.getOrDefault(x, 0) + 1);
        }
        Map<Integer, Integer> map2 = new HashMap<>();
        for(int y : b){
            min = Math.min(min, y);
            if(map1.containsKey(y)){
                if(map1.get(y) == 1)
                    map1.remove(y);
                else
                    map1.put(y, map1.get(y) - 1);
            }else{
                map2.put(y, map2.getOrDefault(y, 0) + 1);
            }
        }
        Queue<int[]> left1 = new PriorityQueue<>((x,y) -> x[0] - y[0]);
        Queue<int[]> left2 = new PriorityQueue<>((x,y) -> y[0] - x[0]);
        for(int key : map1.keySet()){
            if(map1.get(key) % 2 == 1)
                return -1;
            left1.offer(new int[]{key, map1.get(key)});
        }
        for(int key : map2.keySet()){
            if(map2.get(key) % 2 == 1)
                return -1;
            left2.offer(new int[]{key, map2.get(key)});
        }
        long res = 0;
        while(!left1.isEmpty() && !left2.isEmpty()){
            int[] a1 = left1.poll();
            int[] b1 = left2.poll();
            if(a1[1] == b1[1]){
                res += Math.min((long)Math.min(a1[0], b1[0]) * a1[1] / 2, (long)min * a1[1]);
            }else if(a1[1] > b1[1]){
                res += Math.min((long)Math.min(a1[0], b1[0]) * b1[1] / 2, (long)min * b1[1]);
                left1.offer(new int[]{a1[0], a1[1] - b1[1]});
            }else{
                res += Math.min((long)Math.min(a1[0], b1[0]) * a1[1] / 2, (long)min * a1[1]);
                left2.offer(new int[]{b1[0], b1[1] - a1[1]});
            }
        }
        if(left1.isEmpty() && left2.isEmpty())
            return res;
        return -1;
    }
}

public static double computeCommission(double salesAmount) {
    double commission = 0;
    if (salesAmount <= 5000) {
        commission = salesAmount * 0.08;
    } else if (salesAmount <= 10000) {
        commission = 5000 * 0.08 + (salesAmount - 5000) * 0.1;
    } else {
        commission = 5000 * 0.08 + 5000 * 0.1 + (salesAmount - 10000) * 0.12;
    }
    return commission;
}

public static void main(String[] args) {
    System.out.println("Sales Amount Commission");
    for (int i = 10000; i <= 100000; i += 5000) {
        System.out.printf("%-10d%-10.1f\n", i, computeCommission(i));
    }
}

