public class Chi2Test {
 
    private static final int A = 12;
    private static final double k1_factrl = 1.0;
    private static final List<Double> COEF = IntStream.range(0, A)
           .mapToObj(k -> Math.exp(A - k) * Math.pow(A - k, k - 0.5) / k1_factrl)
           .collect(Collectors.toList());
 
    private static double gamma_spounge(double z) {
        return COEF.stream().reduce(0.0, (res, c) -> res + c / (z + COEF.indexOf(c)))
                * Math.exp(-(z + A)) * Math.pow(z + A, z + 0.5) / z;
    }
 
    private static double gammaInc_Q(double a, double x) {
        double a1 = a - 1, a2 = a - 2;
        Function<Double, Double> f0 = t -> Math.pow(t, a1) * Math.exp(-t);
        Function<Double, Double> df0 = t -> (a1 - t) * Math.pow(t, a2) * Math.exp(-t);
 
        double y = a1;
        while (f0.apply(y) * (x - y) > 2.0e-8 && y < x) {
            y += 0.3;
        }
        if (y > x) {
            y = x;
        }
 
        double h = 3.0e-4;
        int n = (int) (y / h);
        h = y / n;
        double hh = 0.5 * h;
        double sum = 0;
        for (int j = n - 1; j >= 0; j--) {
            double t = h * j;
            sum += f0.apply(t) + hh * df0.apply(t);
        }
        return h * sum / gamma_spounge(a);
    }
 
    private static double chi2UniformDistance(List<Integer> dataSet) {
        double expected = dataSet.stream().mapToInt(Integer::intValue).sum() / (double) dataSet.size();
        return dataSet.stream().mapToDouble(d -> Math.pow(d - expected, 2)).sum() / expected;
    }
 
    private static double chi2Probability(int dof, double distance) {
        return 1.0 - gammaInc_Q(0.5 * dof, 0.5 * distance);
    }
 
    private static boolean chi2IsUniform(List<Integer> dataSet, double significance) {
        int dof = dataSet.size() - 1;
        double dist = chi2UniformDistance(dataSet);
        return chi2Probability(dof, dist) > significance;
    }
 
