                Arrays.asList(199809, 200665, 199607, 200270, 199649),
                Arrays.asList(522573, 244456, 139979, 71531, 21461));
 
        for (List<Integer> ds : dsets) {
            System.out.println("Data set:" + ds);
            int dof = ds.size() - 1;
            System.out.println("  degrees of freedom: " + dof);
            double distance = chi2UniformDistance(ds);

