// See https://en.wikipedia.org/wiki/Divisor_function
class Divisor_count {
    public static void main(String[] args) {
        final int limit = 100;
        System.out.println("The first " + limit + " tau numbers are:");
        int count = 0;
        for (int n = 1; count < limit; ++n) {
            if (n % divisor_count(n) == 0) {
                System.out.printf("%6d", n);
                ++count;
                if (count % 10 == 0)
                    System.out.println();
            }
        }
    }
 
    private static int divisor_count(int n) {
        int total = 1;
        // Deal with powers of 2 first
        for (; (n & 1) == 0; n >>= 1)
            ++total;
        // Odd prime factors up to the square root
        for (int p = 3; p * p <= n; p += 2) {
            int count = 1;
            for (; n % p == 0; n /= p)
                ++count;
            total *= count;
        }
        // If n > 1 then it's prime
        if (n > 1)
            total *= 2;
        return total;
    }
}

import com.google.common.net.MediaType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.ws.rs.client.Client;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.Response;

/**
 * XOS API web client.
 */
public class XosApi {

    private final Logger log = LoggerFactory.getLogger(getClass());

    private static final String EMPTY_STRING = "";
    private static final String EMPTY_JSON_STRING = "{}";

    private final String baseUrl;
    private final XosAccess access;
    private final Client client;

    /**
     * Creates an XOS API instance with given access info.
     *
     * @param access XOS access info
     */
    public XosApi(XosAccess access) {
        this.access = access;
        this.baseUrl = access.endpoint();
        this.client = ClientBuilder.newClient();
    }

    /**
     * Returns XOS access info.
     *
     * @return XOS access info
     */
    public XosAccess access() {
        return access;
    }

    /**
     * Returns base URL.
     *
     * @return base URL
     */
    public String baseUrl() {
        return baseUrl;
    }

    /**
     * Performs a REST GET method with a given path.
     *
     * @param path path
     * @return JSON string; empty JSON string if it fails
     */
    public String restGet(String path) {
        try {
            WebTarget wt = client.target(baseUrl + path);
            Response response = wt.request(MediaType.JSON_UTF_8.toString()).get();

            if (response.getStatus() == Response.Status.OK.getStatusCode()) {
                return response.readEntity(String.class);
            } else {
                log.warn("Failed to read {} from XOS: HTTP status {}", path, response.getStatus());
                return EMPTY_JSON_STRING;
            }
        } catch (Exception e) {
            log.error("Failed REST call to {}", baseUrl + path, e);
            return EMPTY_JSON_STRING;
        }
    }
}

class Queue {
    public long maximumOr(int[] nums, int k) {
        // 预处理所有位置
        int[] cnt = new int[32];
        for (int i = 0; i < nums.length; i++) {
            for (int j = 0; j < 31; j++) {
                if ((nums[i] & (1 << j)) > 0) {
                    cnt[j]++;
                }
            }
        }
        // 最高位的并列暴力k次
        int max = Integer.MIN_VALUE;
        for (int n : nums) {
            max = Math.max(n, max);
        }
        int high = 0;
        int t = max;
        while (t != 0) {
            t /= 2;
            high++;
        }
        // high表示1有多高，1对应1
        Map<Integer, Integer> num2Idx = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] >= (1 << (high - 1))) {
                num2Idx.put(nums[i], i);
            }
        }
        long res = Integer.MIN_VALUE;
        for (Map.Entry<Integer, Integer> entry : num2Idx.entrySet()) {
            // 移动k次
            int num = entry.getKey();
            int index = entry.getValue();
            long g = num;
            for (int i = 0; i < k; i++) {
                g *= 2;
            }
            long ans = g;
            ans |= get(cnt, nums[index]);
            res = Math.max(ans, res);
        }
        return res;

    }

    private int get(int[] cnt, int t) {
        int[] res = new int[32];
        for (int i = 0; i < cnt.length; i++) {
            res[i] = cnt[i];
        }
        for (int i = 0; i < 31; i++) {
            if ((t & (1 << i)) > 0) {
                res[i]--;
            }
        }
        int ans = 0;
        for (int i = 0; i < 31; i++) {
            if (res[i] > 0) {
                ans += (1 << i);
            }
        }
        return ans;
    }
}

