private Map<MethodSymbol, Attribute> getAllValues() {
    Map<MethodSymbol, Attribute> values = new HashMap<>();
    for (MethodSymbol m : elements) {
        if (values.containsKey(m)) {
            continue;
        }
        Attribute value = getDefaultValue(m);
        if (value == null) {
            value = getElementValue(m);
        }
        values.put(m, value);
    }
    return values;
}

