import java.util.Scanner;

public class Solution {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);
        int n = input.nextInt();
        int m = input.nextInt();
        int p = input.nextInt();
        int[][] like = new int[n][m];
         for(int i=0; i<n; i++)
            for(int j=0; j<m; j++)
                like[i][j] = input.nextInt();

        int[] maxSatisfy = new int[1<<m];
        for(int i=0; i<(1<<m); i++)
           for(int j=0; j<m; j++)
               if((i&(1<<j)) != 0)
                   maxSatisfy[i] = Math.max(maxSatisfy[i], Integer.bitCount(i&like[0][j]));

        for(int i=1; i<n; i++)
            for(int sub=0; sub<(1<<m); sub++)
                for(int j=0; j<m; j++)
                    if((sub&(1<<j)) != 0)
                        maxSatisfy[sub] = Math.max(maxSatisfy[sub], Integer.bitCount((sub&like[i][j])) + maxSatisfy[sub^(1<<j)]);

        StringBuilder ans = new StringBuilder();
        for(int sub=(1<<m)-1; sub>=0; sub--)
            if(Integer.bitCount(sub) <= n/2 && maxSatisfy[sub] == Integer.bitCount(sub)){
                for(int j=0; j<m; j++)
                    if((sub&(1<<j)) != 0)
                        ans.append(1);
                    else
                        ans.append(0);
                System.out.println(ans.toString());
                return;
            }

    }
}

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.S3Event;
import com.amazonaws.services.s3.AmazonS3;
import com.amazonaws.services.s3.AmazonS3Client;
import com.amazonaws.services.s3.event.S3EventNotification;
import com.amazonaws.services.s3.model.GetObjectRequest;
import com.amazonaws.services.s3.model.S3Object;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.tikal.logregator.LogEntry;
import com.tikal.logregator.LogSender;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.*;
import java.util.List;

/**
 */
public class LogEntryLambdaListener implements RequestHandler<S3Event, String> {

    Logger logger = LoggerFactory.getLogger(LogEntryLambdaListener.class);

    @Override
    public String handleRequest(S3Event input, Context context) {
        AmazonS3 s3Client = new AmazonS3Client();
        List<S3EventNotification.S3EventNotificationRecord> records = input.getRecords();
        ObjectMapper mapper = new ObjectMapper();
        LogSender kafkaSender = new LogSender();
        records.forEach(record -> {
            String srcBucket = record.getS3().getBucket().getName();
            // Object key may have spaces or unicode non-ASCII characters.
            String srcKey = record.getS3().getObject().getKey();

            try {
                logger.info("Param from env:" + System.getenv("TEST_KEY"));
                S3Object s3Object = s3Client.getObject(new GetObjectRequest(
                        srcBucket, srcKey));

                InputStream is = s3Object.getObjectContent();
                InputStreamReader r = new InputStreamReader(is);
                BufferedReader reader = new BufferedReader(r);
                String line = null;
                while((line = reader.readLine()) != null) {
                    LogEntry entry = LogEntry.parse(line);
                    String json = mapper.writeValueAsString(entry);
                    //TODO Send file to kafka
                    logger.info("sending to kafka the following json: " + json);
                    kafkaSender.sendMessage(json);
                }
                logger.info("Handling bucket " + srcBucket + " and key " + srcKey);
            } catch (IOException e) {
                logger.error("Unable handling s3 object " + srcBucket+"/"+srcKey+": " + e.getMessage(), e);
            }

        });

        return null;
    }
}

import java.util.Arrays;
 
public class TruncatablePrimes {
    private static final int MAX_PRIME = 1000000;
    private static boolean[] primes;
    private static int n_primes;
 
    /*  Sieve. If we were to handle 10^9 range, use bit field. Regardless,
     *  if a large amount of prime numbers need to be tested, sieve is fast.
     */
    private static void init_primes() {
        int j;
        primes = new boolean[MAX_PRIME];
        Arrays.fill(primes, true);
        primes[0] = primes[1] = false;
        int i = 2;
        while (i * i < MAX_PRIME) {
            for (j = i * 2; j < MAX_PRIME; j += i)
                primes[j] = false;
            while (++i < MAX_PRIME &&!primes[i]);
        }
    }
 
    private static boolean left_trunc(int n) {
        int tens = 1;
        while (tens < n) tens *= 10;
 
        while (n > 0) {
            if (!primes[n]) return false;
            tens /= 10;
            if (n < tens) return false;
            n %= tens;
        }
        return true;
    }
 
    private static boolean right_trunc(int n) {
        while (n > 0) {
            if (!primes[n]) return false;
            n /= 10;
        }
        return true;
    }
 
    public static void main(String[] args) {
        int n;
        int max_left = 0, max_right = 0;
        init_primes();
 
        for (n = MAX_PRIME - 1; max_left == 0;  n -= 2)
            if (left_trunc(n)) max_left = n;
 
        for (n = MAX_PRIME - 1; max_right == 0; n -= 2)
            if (right_trunc(n)) max_right = n;
 
        System.out.println("Left: " + max_left + "; right: " + max_right);
    }
}

