    for(int i = 1; i < n; i++){
        String[] ed = br.readLine().split(" ");
        int a = Integer.parseInt(ed[0]), b = Integer.parseInt(ed[1]);
        adj[a].add(b);
        adj[b].add(a);
    }
    color[1] = 1;
    Queue<Integer> q = new LinkedList<>();
    q.add(1);
    while(!q.isEmpty()){
        int v = q.poll();
        for(int i: adj[v]){
            if(color[i] == 0){
                color[i] = -color[v];
                dist[i] = dist[v] + 1;
                q.add(i);
            }
            else if(color[i] == color[v]) dist[i] = Math.min(dist[i], dist[v] + 1);
        }
    }
    for(int i = 0; i < str.length; i++){
        if(str[i].equals("1")){
