import java.util.*;

public class Dreamoon{

    public static void main(String[] args) {

        Scanner scan = new Scanner(System.in);

        int testCases=scan.nextInt();

        while(testCases>0){

            int arrayLength=scan.nextInt();

            int x=scan.nextInt();

            int[] array = new int[arrayLength];

            for(int i=0; i<arrayLength; i++){

                array[i]=scan.nextInt();

            }

            System.out.println(getMaxV(array, x));

            testCases--;

        }

    }

    public static int getMaxV(int[] array, int x){

        int prevSmallest=0;

        for(int i=0; i<array.length; i++){

            for(int j=array.length-1;j>i; j--){

                if(array[j]<=array[j-1]){

                    int temp=array[j];

                    array[j]=array[j-1];

                    array[j-1]=temp;

                }

            }

            int missingNumbers=array[i]-prevSmallest-1;

            if(x>=missingNumbers ){

                if(missingNumbers>=0){

                    x-=missingNumbers;

                }

                prevSmallest=array[i];

            }else{

                return prevSmallest+x;

            }

        }

        return array[array.length-1]+x;

    }

}

import java.io.IOException;
import java.sql.SQLException;
import java.util.UUID;

import org.ndexbio.common.models.dao.postgresql.TaskDAO;
import org.ndexbio.model.exceptions.NdexException;
import org.ndexbio.model.object.Status;

import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.databind.JsonMappingException;

public abstract class NdexTaskProcessor implements Runnable {

    private volatile boolean shutdown = false;
    protected UUID taskId;

    public NdexTaskProcessor(UUID taskId) {
        this.taskId = taskId;
    }

    public void shutdown() {
        shutdown = true;
    }

    protected boolean isShutdown() {
        return shutdown;
    }

    protected void saveTaskStatus(Status status, String message, String stackTrace) throws NdexException {
        try (TaskDAO taskDAO = new TaskDAO()) {
            taskDAO.updateTaskStatus(this.taskId, status, message, stackTrace);
            taskDAO.commit();
        } catch (SQLException | JsonParseException | JsonMappingException | IOException e) {
            throw new NdexException("Failed to update task status: " + e.getMessage(), e);
        }
    }

    protected void saveTaskStatus(Status status, String message) throws NdexException {
        saveTaskStatus(status, message, null);
    }

    protected UUID getTaskId() {
        return this.taskId;
    }

}

