    private static final String USER = "username";
    private static final String PASS = "password";

    public void delete(String tableName, String geometryColumnName) {
        try (Connection conn = DriverManager.getConnection(DB_URL, USER, PASS);
             Statement stmt = conn.createStatement()) {

            // Drop the triggers
            String dropTriggersQuery = "DROP TRIGGER IF EXISTS trigger_name ON " + tableName;
            stmt.executeUpdate(dropTriggersQuery);

            // Drop the RTree table
            String dropRTreeTableQuery = "DROP TABLE IF EXISTS rtree_table";
            stmt.executeUpdate(dropRTreeTableQuery);

            // Delete the extension
            String deleteExtensionQuery = "DROP EXTENSION IF EXISTS postgis";
            stmt.executeUpdate(deleteExtensionQuery);

            System.out.println("RTree Index deleted successfully");

        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}

