import java.awt.Color;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.Deque;
import java.util.LinkedList;
 
public class FloodFill {
  public void floodFill(BufferedImage image, Point node, Color targetColor, Color replacementColor) {
    int width = image.getWidth();
    int height = image.getHeight();
    int target = targetColor.getRGB();
    int replacement = replacementColor.getRGB();
    if (target != replacement) {
      Deque<Point> queue = new LinkedList<Point>();
      do {
        int x = node.x;
        int y = node.y;
        while (x > 0 && image.getRGB(x - 1, y) == target) {
          x--;
        }
        boolean spanUp = false;
        boolean spanDown = false;
        while (x < width && image.getRGB(x, y) == target) {
          image.setRGB(x, y, replacement);
          if (!spanUp && y > 0 && image.getRGB(x, y - 1) == target) {
            queue.add(new Point(x, y - 1));
            spanUp = true;
          } else if (spanUp && y > 0 && image.getRGB(x, y - 1) != target) {
            spanUp = false;
          }
          if (!spanDown && y < height - 1 && image.getRGB(x, y + 1) == target) {
            queue.add(new Point(x, y + 1));
            spanDown = true;
          } else if (spanDown && y < height - 1 && image.getRGB(x, y + 1) != target) {
            spanDown = false;
          }
          x++;
        }
      } while ((node = queue.pollFirst()) != null);
    }
  }
}

import android.content.ContentValues;
import android.provider.BaseColumns;
import android.text.TextUtils;
import java.util.Date;

public class MovieContentValues extends DbContentValues {
    public static final String COLUMN_JSON = "json_data";
    public static final String COLUMN_TIMESTAMP = "timestamp";

    public static Builder builder() {
        return new Builder();
    }

    public static class Builder {
        private ContentValues cv = new ContentValues();

        public Builder setId(long id) {
            cv.put(BaseColumns._ID, id);
            return this;
        }

        public Builder setJson(String json) {
            if (!TextUtils.isEmpty(json)) {
                cv.put(COLUMN_JSON, json);
            }
            return this;
        }

        public Builder setJsonIfNotEmpty(String json) {
            return setJson(json);
        }

        public Builder setTimestamp(Date date) {
            cv.put(COLUMN_TIMESTAMP, date.getTime());
            return this;
        }

        public Builder setTimestamp(long timestamp) {
            cv.put(COLUMN_TIMESTAMP, timestamp);
            return this;
        }

        public ContentValues build() {
            ContentValues result = new ContentValues(cv);
            if (!result.containsKey(COLUMN_TIMESTAMP)) {
                result.put(COLUMN_TIMESTAMP, new Date().getTime());
            }
            validateConstraints();
            return result;
        }

        public void clear() {
            cv.clear();
        }

        private void validateConstraints() {
            if (cv.containsKey(COLUMN_JSON) {
                String json = cv.getAsString(COLUMN_JSON);
                if (TextUtils.isEmpty(json)) {
                    throw new IllegalArgumentException("JSON cannot be empty");
                }
            }
        }

        public Builder mergeWith(ContentValues other) {
            cv.putAll(other);
            return this;
        }

        public Builder withoutJson() {
            cv.remove(COLUMN_JSON);
            return this;
        }

        public Builder withCurrentTimestamp() {
            cv.remove(COLUMN_TIMESTAMP);
            return this;
        }
    }
}

/**
 * Round figure defined purely by its radius.
 */
public class Cember extends Sekil {

    private double r;

    public Cember(double r) {
        super("Cember");
        this.r = r;
    }

    public double getYaricap() {
        return r;
    }

    public void setYaricap(double r) {
        this.r = r;
    }

    @Override
    public double alanHesapla() {
        return Math.PI * r * r;
    }

    @Override
    public double cevreHesapla() {
        return 2.0 * Math.PI * r;
    }

    @Override
    public void ciz() {
        System.out.println("Cember ciziliyor: Yaricap " + r);
    }
}

import com.example.dto.DepartmentDTO;
import com.example.entity.LocationMasEntity;
import com.example.entity.Organisation;
import org.modelmapper.ModelMapper;
import org.modelmapper.convention.MatchingStrategies;
import org.springframework.stereotype.Component;

@Component
public class DepartmentServiceMapper extends AbstractServiceMapper {

    private ModelMapper modelMapper;

    public DepartmentServiceMapper() {
        this.modelMapper = new ModelMapper();
        this.modelMapper.getConfiguration().setMatchingStrategy(MatchingStrategies.STRICT);
    }

    public DepartmentDTO mapDepartmentEntityToDepartment(LocationMasEntity departmentEntity) {
        if (departmentEntity == null) {
            return null;
        }
        DepartmentDTO departmentDTO = modelMapper.map(departmentEntity, DepartmentDTO.class);
        if (departmentEntity.getOrganisation() != null) {
            departmentDTO.setOrgId(departmentEntity.getOrganisation().getOrgId());
        }
        return departmentDTO;
    }

    public void mapDepartmentToDepartmentEntity(DepartmentDTO departmentDTO, LocationMasEntity departmentEntity) {
        if (departmentDTO == null || departmentEntity == null) {
            return;
        }

        modelMapper.map(departmentDTO, departmentEntity);

        if (hasLinkToTbOrganisation(departmentDTO)) {
            Organisation organisation = new Organisation();
            organisation.setOrgId(departmentDTO.getOrgId());
            departmentEntity.setOrganisation(organisation);
        } else {
          departmentEntity.setOrganisation(null);
        }
    }

    public boolean hasLinkToTbOrganisation(DepartmentDTO departmentDTO) {
        return departmentDTO.getOrgId() != null;
    }

    public ModelMapper getModelMapper() {
        return modelMapper;
    }

    public void setModelMapper(ModelMapper modelMapper) {
        this.modelMapper = modelMapper;
    }
}

abstract class AbstractServiceMapper {
    //Potentially some common methods between service mappers.
}

import java.math.BigDecimal;

public class Counter {
    public static void main(String[] args) {
        BigDecimal value = new BigDecimal("123.45");
        System.out.println(toInt(value));  // Output: null

        value = new BigDecimal("123");
        System.out.println(toInt(value));  // Output: 123
    }

    private static Integer toInt(BigDecimal value) {
        if (value.scale() <= 0 && value.compareTo(new BigDecimal(Integer.MAX_VALUE)) <= 0
                && value.compareTo(new BigDecimal(Integer.MIN_VALUE)) >= 0) {
            return value.intValue();
        }
        return null;
    }
}

import android.app.Activity;
import android.net.ConnectivityManager;
import android.net.DhcpInfo;
