import java.awt.image.BufferedImage;
import java.awt.image.DataBufferByte;
import java.awt.image.WritableRaster;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;
 
public class Image {
 
    public static void main(String[] args) throws IOException {
        // A rectangle from 0,0 to 300,240.
        int x = 0;
        int y = 0;
        int width = 300;
        int height = 240;
 
        // Create an image
        BufferedImage im = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
 
        // set some color variables for convience
        int red = 0xff0000ff;
        int blue = 0x0000ffff;
 
        // Fill with a uniform color
        im.getGraphics().setColor(red);
        im.getGraphics().fillRect(x, y, width, height);
 
        // Set individual pixels
        im.setRGB(10, 20, blue);
        im.setRGB(20, 30, 0x000000ff);
        im.setRGB(30, 40, 0x102030ff);
 
        // Get the values of specific pixels as color.Color types.
        // The color will be in the color.Model of the image (in this
        // case color.NRGBA) but color models can convert their values
        // to other models.
        int c1 = im.getRGB(0, 0);
        int c2 = im.getRGB(10, 20);
 
        // or directly as RGB components (scaled values)
        int redc = (c1 >> 16) & 0xff;
        int greenc = (c1 >> 8) & 0xff;
        int bluec = c1 & 0xff;
        redc = (c2 >> 16) & 0xff;
        greenc = (c2 >> 8) & 0xff;
        bluec = c2 & 0xff;
 
        // Images can be read and writen in various formats
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        ImageIO.write(im, "png", buf);
 
        System.out.println("Image size: " + im.getWidth() + " × " + im.getHeight());
        System.out.println(buf.size() + " bytes when encoded as PNG.");
        System.out.printf("Pixel at %7v is %v\n", new java.awt.Point(0, 0), c1);
        System.out.printf("Pixel at %7v is %#v\n", new java.awt.Point(10, 20), c2); // %#v shows type details
        System.out.printf("Pixel at %7v has R=%d, G=%d, B=%d\n",
                new java.awt.Point(30, 40), redc, greenc, bluec);
    }
}

