public byte[] getHeaderWithBlankCrc(byte[] header) {
    byte[] blankCrcHeader = Arrays.copyOf(header, header.length);
    // Set CRC field to all zeros
    for (int i = 0; i < 4; i++) {
        blankCrcHeader[header.length - 4 + i] = 0;
    }
    return blankCrcHeader;
}

