import java.util.Map;
import java.util.Set;

public class RedundantStringOperationMerger extends InspectionElementsMergerBase {

  private static final String OLD_MERGER_NAME = "RedundantStringOperation";
  private static final Set<String> OLD_SOURCE_NAMES =
      ImmutableSet.of(
          "RedundantStringToString", "RedundantStringSubstring", "UnnecessaryCallToStringValueOf");

  private static final String MERGED_NAME = "StringOperationCanBeSimplified";

  private static final Map<String, String> SOURCE_TO_MERGED =
          Map.of(
              "RedundantStringToString", MERGED_NAME,
              "RedundantStringSubstring", MERGED_NAME,
              "UnnecessaryCallToStringValueOf", MERGED_NAME
          );
  @Override
  public @NotNull String getMergedToolName() {
    return MERGED_NAME;
  }

    @Override
    public Element getSourceElement(@NotNull String sourceToolName, @NotNull Element root) {
        if (OLD_MERGER_NAME.equals(sourceToolName)) {
            Element mergedElement = new Element(MERGED_NAME);
            for (String oldSourceName : OLD_SOURCE_NAMES) {
                Element oldSourceElement = super.getSourceElement(oldSourceName, root);
              if(oldSourceElement != null) {
                  merge(mergedElement, new Element[]{oldSourceElement});
              }
            }
            return mergedElement;
        }
        return super.getSourceElement(sourceToolName, root);
    }

  @Override
  public String @NotNull [] getSourceToolNames() {
    return ArrayUtilRt.toStringArray(SOURCE_TO_MERGED.keySet());
  }

  @Override
  public String @NotNull [] getSuppressIds() {
    return new String[] {"StringOperationCanBeSimplified", "RedundantStringOperation"};
  }
  @Override
    protected boolean writeMergedContent(@NotNull Element toolElement) {
        return !"UnnecessaryCallToStringValueOf".equals(toolElement.getName());
    }
  @Override
  protected void merge(@NotNull Element mergedElement, Element @NotNull [] elements) {
    for (Element element : elements) {
      if("RedundantStringToString".equals(element.getName())){
          setAttribute(mergedElement, "REDUNDANT_STRING_TO_STRING", "true");
      } else if ("RedundantStringSubstring".equals(element.getName())) {
          setAttribute(mergedElement, "REDUNDANT_SUBSTRING", "true");

import java.util.ArrayList;
import java.util.List;
import java.util.TreeMap;
import java.util.Map;

public class IndexXYMap<K, V> extends TreeMap<K, V> {

    private final List<K> indexList = new ArrayList<>();
    private double maxXDifference = 0;

    public IndexXYMap() {
        super();
    }

    @Override
    public V put(K key, V value) {
        V returnValue = super.put(key, value);
        indexList.add(key);
        updateMaxXDifference();
        return returnValue;
    }

    public void updateMaxXDifference() {
        maxXDifference = 0;
        if (indexList.size() < 2) {
            return;
        }
        for (int i = 1; i < indexList.size(); i++) {
            double diff = Math.abs(((Double) indexList.get(i)) - ((Double) indexList.get(i - 1)));
            maxXDifference = Math.max(maxXDifference, diff);
        }
    }

    public double getMaxXDifference() {
        return maxXDifference;
    }

    @Override
    public void clear() {
        super.clear();
        indexList.clear();
        maxXDifference = 0;
    }

    public K getXByIndex(int index) {
        return indexList.get(index);
    }

    public V getYByIndex(int index) {
        K key = indexList.get(index);
        return super.get(key);
    }

    public XYEntry<K, V> getByIndex(int index) {
        K key = indexList.get(index);
        V value = super.get(key);
        return new XYEntry<>(key, value);
    }

    public V removeByIndex(int index) {
        K key = indexList.remove(index);
        V value = super.remove(key);
        updateMaxXDifference();
        return value;
    }

    public int getIndexForKey(K key) {
        return indexList.indexOf(key);
    }

    public List<K> getIndexList(){
        return new ArrayList<>(indexList);
    }

    public static class XYEntry<K, V> {
        private final K key;
        private final V value;

        public XYEntry(K key, V value) {
            this.key = key;
            this.value = value;
        }

        public K getKey() {
            return key;
        }

        public V getValue() {
            return value;
        }
    }
}

import java.io.IOException;
import org.apache.pig.data.Tuple;
import org.apache.pig.data.TupleFactory;
import org.codehaus.jackson.JsonParseException;

public class MergedTupleCreator {

  private int[] keyFieldIndex;
  private int[] valueFieldIndex;
  private Tuple outputTuple;
  private boolean valueIsNull;

  public MergedTupleCreator() {}

  public void setup(BlockSchema schema, String pivotKeys)
      throws JsonParseException, IOException {
    String[] keyColumns = pivotKeys.split(",");
    keyFieldIndex = new int[keyColumns.length];
    valueFieldIndex = new int[schema.getFieldCount() - keyColumns.length];

    int j = 0;
    int k = 0;
    for (int i = 0; i < schema.getFieldCount(); i++) {
      String fieldName = schema.getFieldName(i);
      boolean isKeyField = false;
      for (String keyColumn : keyColumns) {
        if (fieldName.equals(keyColumn)) {
          keyFieldIndex[j++] = i;
          isKeyField = true;
          break;
        }
      }
      if (!isKeyField) {
        valueFieldIndex[k++] = i;
      }
    }

    outputTuple = TupleFactory.getInstance().newTuple(schema.getFieldCount());
    valueIsNull = valueFieldIndex.length == 0;
  }

  public Tuple create(Tuple key, Tuple value) throws IOException {
    try {
      for (int i = 0; i < keyFieldIndex.length; i++) {
        outputTuple.set(keyFieldIndex[i], key.get(i));
      }

      if (!valueIsNull) {
        int offset = keyFieldIndex.length;
        for (int i = 0; i < valueFieldIndex.length; i++) {
          outputTuple.set(valueFieldIndex[i], value.get(i));
        }
      }
      return outputTuple;

    } catch (Exception e) {
      throw new IOException(e);
    }
  }
}

