import java.io.*;
import java.lang.reflect.*;
import java.util.*;

public class HPObjectOutputStream extends DataOutputStream {
    private ObjectOutputStreamSupport support;

    public HPObjectOutputStream(OutputStream out) throws IOException {
        super(out);
        support = new ObjectOutputStreamSupport(this);
    }

    public void writeObject(Object obj) throws IOException {
        support.writeObject(obj);
    }
}

class ObjectOutputStreamSupport {
    private DataOutputStream out;
    private Map<Object, Integer> writtenObjects = new IdentityHashMap<>();
    private int objectCounter = 0;

    public ObjectOutputStreamSupport(DataOutputStream out) {
        this.out = out;
    }

    public void writeObject(Object obj) throws IOException {
        if (obj == null) {
            out.writeByte(0); // Null object
            return;
        }

        Integer existingId = writtenObjects.get(obj);
        if (existingId != null) {
            out.writeByte(1); // Already written object
            out.writeInt(existingId);
            return;
        }

        out.writeByte(2); // New object
        int id = objectCounter++;
        writtenObjects.put(obj, id);
        out.writeInt(id);

        Class<?> clazz = obj.getClass();
        out.writeUTF(clazz.getName());

        if (clazz.isArray()) {
            writeArray(obj);
        } else if (Enum.class.isAssignableFrom(clazz)) {
            writeEnum(obj);
        }
    }

        private void writeArray(Object array) throws IOException {
        int length = Array.getLength(array);
        out.writeInt(length);
        for (int i = 0; i < length; i++) {
            writeObject(Array.get(array, i));
        }
    }

    private void writeEnum(Object enumObj) throws IOException {
        Enum<?> e = (Enum<?>) enumObj;
        out.writeUTF(e.name());
    }
}

