        diffuseColor = BLUE; // Start color is blue
        setFields(); // Set up field listeners
    }

    // Method to set up input fields
    private void setFields() {
        // Assuming 'isOver' is declared in the X3D scene
        isOver = false; // Initialize the isOver state
        browser.addEventListener("isOver", this::readableFieldChanged);
    }

    // This method is called when the field value changes
    private void readableFieldChanged(String fieldName) {
        if ("isOver".equals(fieldName)) {
            updateColor(); // Update the color based on mouse interaction
        }
    }

    // Method to update color based on cursor state
    private void updateColor() {
        if (isOver) {
            diffuseColor = RED; // Change color to red
        } else {
            diffuseColor = BLUE; // Change color to blue
        }
        browser.setFieldValue("diffuseColor_changed", diffuseColor); // Update the field
    }

    // Method to handle event processing
    public void eventsProcessed() {
        // Add logic for processing events if necessary
    }

    // Cleanup method on shutdown
    public void shutdown() {
        // Clean up resources, if needed
        browser.removeEventListener("isOver", this::readableFieldChanged);
    }

    // Additional methods can be added here for extended functionality
}

import java.util.Arrays;

public class Tree {
    public static void main(String[] args) {
        Double searchKey = 111.11;
        Double[] values = new Double[]{4400.1, 1203.3, 3100.0, 18700.8, 4100.6, 111.11, 2222.21, 4529.21};

        System.out.println("Generic Binary Search method found the search key value: " + searchKey + " at index: " + binarySearch(values,
                searchKey) + " in the above array.");

    }

    public static <E extends Comparable<E>> int binarySearch(E[] list, E key) {
        System.out.println("Sorting the array to ensure binarySearch is supported: ");
        Arrays.sort(list);
        System.out.println(Arrays.toString(list));
        int lowIdx = 0; // First element in the array
        int highIdx = list.length - 1; // Last element in the array
        while (highIdx >= lowIdx) {
            int midIdx = (lowIdx + highIdx) / 2;
            int compare = key.compareTo(list[midIdx]); // Compare key to value at midIdx
            if (compare < 0) { // Key is less than list[midIdx]
                highIdx = midIdx - 1; // Value can only be to the left of list[midIdx]
            } else if (compare == 0) { // Key equals list[midIdx]
                return midIdx; // Return the index of matched value
            } else { // Key is greater than list[midIdx]
                lowIdx = midIdx + 1; // Value can only be to the right of list[midIdx]
            }
        }
        return -1; // No matching value found in list
    }
}

