public class Peano extends PApplet {

// Peano class
class Peano
  {
    float draw_length;
    Vec2D vec;
    float theta;
    String axiom;
    Grammar grammar;
    final int DELTA = 60; // degrees
    Peano(Vec2D vec)
    {
      axiom = "XF"; // Axiom
      HashMap<String, String> rules = new HashMap<String, String>();
      rules.put("X", "X+YF++YF-FX--FXFX-YF+"); // LSystem Rules
      rules.put("Y", "-FX+YFYF++YF+FX--FX-Y");
      grammar = new Grammar(axiom, rules);
      theta   = 0;
      draw_length = 100;
      this.vec = vec;
    }

    String generate(int gen)
    {
      draw_length = draw_length * (float)pow(0.6, gen);
      return grammar.generate(gen);
    }

    ArrayList<Vec2D> translate_rules(String prod)
    {
      // An array to store line vertices as Vec2D
      ArrayList<Vec2D> pts = new ArrayList<Vec2D>();
      for (int i = 0; i < prod.length(); i++)
      {
        char ch = prod.charAt(i);
        switch(ch)
        {
          case 'F':
            pts.add(vec.copy());
            vec = new Vec2D(
              cos(radians(theta)) * draw_length + vec.x,
              -sin(radians(theta)) * draw_length + vec.y
            );
            pts.add(vec);
            break;
          case '+':
            theta += DELTA;
            break;
          case '-':
            theta -= DELTA;
            break;
          case 'X':
          case 'Y':
            break;
          default:
            System.out.println("character " + ch + " not in grammar");
        }
      }
      return pts;
    }
  }

