import java.util.Scanner;

public class Nim {
    public static void main(String[] args) {
        int tokens = 12;
        System.out.println("Nim game");
        System.out.println("Starting with " + tokens + " tokens.");
        System.out.println("");

        while (true) {
            tokens = p_turn(tokens);
            print_remaining(tokens);
            tokens = c_turn(tokens);
            print_remaining(tokens);

            if (tokens == 0) {
                System.out.println("Computer wins!");
                break;
            }
        }
    }

    public static int p_turn(int tokens) {
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println("How many tokens would you like to take?");
            int take = scanner.nextInt();

            if (take > 3 || take < 1) {
                System.out.println("Take must be between 1 and 3.");
                System.out.println("");
                continue;
            }

            return tokens - take;
        }
    }

    public static int c_turn(int tokens) {
        int take = tokens % 4;
        System.out.println("Computer takes " + take + " tokens.");
        return tokens - take;
    }

    public static void print_remaining(int tokens) {
        System.out.println(tokens + " tokens remaining.");
        System.out.println("");
    }
}

