import java.util.BitSet;

public class MinFlipsToZeroMatrix {
    public int minFlips(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        BitSet currentState = new BitSet(m * n);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (mat[i][j] == 1) {
                    int index = i * n + j;
                    currentState.set(index);
                }
            }
        }
        if (currentState.isEmpty())
            return 0;
        int[][] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        Queue<int[]> queue = new LinkedList<>();
        queue.offer(new int[]{currentState.nextSetBit(0), 0});
        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int index = current[0];
            int step = current[1];
            if (index == -1) {
                return step;
            }
            for (int[] dir : directions) {
                int newX = index / n + dir[0];
                int newY = index % n + dir[1];
                if (newX >= 0 && newX < m && newY >= 0 && newY < n) {
                    int nextIndex = newX * n + newY;
                    int nextState = currentState.get(index) ^ 1;
                    if (!currentState.get(nextIndex)) {
                        currentState.set(nextIndex, nextState);
                        queue.offer(new int[]{nextState == 1 ? nextIndex : nextIndex + 1, step + 1});
                        currentState.set(nextIndex, nextState ^ 1);
                    }
                }
            }
        }
        return -1;
    }
}

class Finder {
    public List<List<Integer>> allPathsSourceTarget(int[][] graph) {
        List<List<Integer>> resultList = new ArrayList<>();
        if(graph == null || graph.length == 0) return resultList;
        List<Integer> list = new ArrayList<>();
        dfs(0, graph, list, resultList);
        return resultList;
    }
    private void dfs(int u, int[][] graph, List<Integer> list, List<List<Integer>> resultList) {
        list.add(u);
        if(u == graph.length-1)
            resultList.add(new ArrayList<>(list));
        for(int i = 0; i < graph[u].length; i++) {
            int v = graph[u][i];
            dfs(v, graph, list, resultList);
        }
        list.remove(list.size()-1);
    }
}

