import java.io.*;

import java.util.*;

public class Pairs2

{

    public static void main(String args[])throws Exception

    {

        BufferedReader bu=new BufferedReader(new InputStreamReader(System.in));

        StringBuilder sb=new StringBuilder();

        int t=Integer.parseInt(bu.readLine());

        while(t-->0)

        {

            String s[]=bu.readLine().split(" ");

            int n=Integer.parseInt(s[0]),l=Integer.parseInt(s[1]),r=Integer.parseInt(s[2]);

            int i; Integer a[]=new Integer[n];

            s=bu.readLine().split(" ");

            for(i=0;i<n;i++) a[i]=Integer.parseInt(s[i]);

            Arrays.sort(a);

            long ans=0;

            for(i=0;i<n;i++) {

                int min=lowest(a,a[i],l),max=highest(a,a[i],r);

                if(min==-1||max==-1)

                    continue;

                if(max>=min) ans+=max-min+1;

                if(a[i]*2>=l && a[i]*2<=r) ans--;

            }

            ans/=2;

            sb.append(ans+"\n");

        }

        System.out.print(sb);

    }

    static int lowest(Integer a[],int k,int x)

    {

        int l=0,r=a.length-1,mid,ans=-1;

        while(l<=r)

        {

            mid=(l+r)>>1;

            if(a[mid]+k>=x)

            {

                ans=mid;

                r=mid-1;

            }

            else l=mid+1;

        }

        return ans;

    }

    static int highest(Integer a[],int k,int x)

    {

        int l=0,r=a.length-1,mid,ans=-1;

        while(l<=r)

        {

            mid=(l+r)>>1;

            if(a[mid]+k<=x)

            {

                ans=mid;

                l=mid+1;

            }

            else r=mid-1;

        }

        return ans;

    }

}

