import org.omg.CORBA.portable.OutputStream;
import org.omg.CORBA.portable.InputStream;
import org.omg.CORBA.Any;
import org.omg.CORBA.TypeCode;
import org.omg.CORBA.StructMember;
import org.omg.CORBA.ORB;

public class ReceivedObjectHelper {
    private static TypeCode _tc = null;

    public static void write(OutputStream out, ReceivedObject obj) {
        out.write_string(obj.getBy());
        out.write_string(obj.getFrom());
        DateTimeHelper.write(out, obj.getDate());
        out.write_long(obj.getId());
        out.write_string(obj.getVia());
    }

    public static ReceivedObject read(InputStream in) {
        ReceivedObject obj = new ReceivedObject();
        obj.setBy(in.read_string());
        obj.setFrom(in.read_string());
        obj.setDate(DateTimeHelper.read(in));
        obj.setId(in.read_long());
        obj.setVia(in.read_string());
        return obj;
    }

    public static void insert(Any any, ReceivedObject obj) {
        OutputStream out = any.create_output_stream();
        write(out, obj);
        any.read_value(out.create_input_stream(), type());
    }

    public static ReceivedObject extract(Any any) {
        return read(any.create_input_stream());
    }

    public synchronized static TypeCode type() {
        if (_tc == null) {
            ORB orb = ORB.init();
            StructMember[] members = new StructMember[5];
            members[0] = new StructMember("by", orb.get_primitive_tc(org.omg.CORBA.TCKind.tk_string), null);
            members[1] = new StructMember("from", orb.get_primitive_tc(org.omg.CORBA.TCKind.tk_string), null);
            members[2] = new StructMember("date", DateTimeHelper.type(), null);
            members[3] = new StructMember("id", orb.get_primitive_tc(org.omg.CORBA.TCKind.tk_long), null);
            members[4] = new StructMember("via", orb.get_primitive_tc(org.omg.CORBA.TCKind.tk_string), null);
            _tc = orb.create_struct_tc(id(), "ReceivedObject", members);
        }
        return _tc;
    }

    public static String id() {
        return "IDL:ReceivedObject:1.0";
    }
}

class Vector {
    int n;
    long sum;

    public long kMirror(int k, int n) {
        this.sum = 0;
        this.n = n;
        for (int len = 1; this.n > 0; len++) {
            // 长度为 len 的 k 进制的镜像数字
            char[] chars = new char[len];
            dfs(chars, 0, chars.length - 1, k);
        }
        return sum;
    }

    private void dfs(char[] chars, int i, int j, int k) {
        if (this.n == 0) {
            return;
        }
        if (i == j) {
            for (int p = 0; p < k; p++) {
                if (p == 0 && i == 0) {
                    continue;
                }
                chars[i] = (char) ('0' + p);
                dfs(chars, i + 1, j - 1, k);
            }
            return;
        }
        if (i > j) {
            long ten = Long.parseLong(String.valueOf(chars), k);
            String str = String.valueOf(ten);
            for (int l = 0, r = str.length() - 1; l < r; l++, r--) {
                if (str.charAt(l) != str.charAt(r)) {
                    return;
                }
            }
            this.n--;
            sum += ten;
            return;
        }
        for (int p = 0; p < k && this.n > 0; p++) {
            if (i == 0 && p == 0) {
                continue;
            }
            chars[i] = chars[j] = (char) ('0' + p);
            dfs(chars, i + 1, j - 1, k);
        }
    }
}

