class Product {
    public int countPartition(int[] nums, int k) {
        int n = nums.length;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 0; i < n + 1; ++i) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j < k + 1; ++j) {
                dp[i][j] = dp[i - 1][j];
                if (j >= nums[i - 1]) {
                    dp[i][j] += dp[i - 1][j - nums[i - 1]];
                }
                dp[i][j] %= 1000000007;
            }
        }
        return dp[n][k];
    }
}

class Queue {
    public int minOperations(int[] nums, int k) {
        int xor = 0;
        for (int num : nums) {
            xor ^= num;
        }
        return minOperationsHelper(nums, k, xor);
    }

    private int minOperationsHelper(int[] nums, int k, int xor) {
        if (xor == k) {
            return 0;
        }
        int minOperations = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int diff = Math.abs(Integer.bitCount(xor ^ num) - Integer.bitCount(k ^ num));
            minOperations = Math.min(minOperations, diff);
        }
        return minOperations;
    }
}

import java.util.Comparator;
import java.util.function.Function;

interface ComparatorBy<T> extends Comparator<T> {
    static <T, U extends Comparable<? super U>> ComparatorBy<T> comparing(Function<T, U> prop) {
        return (o1, o2) -> {
            U p1 = prop.apply(o1);
            U p2 = prop.apply(o2);
            return p1.compareTo(p2);
        };
    }

    default ComparatorBy<T> invert() {
        return (o1, o2) -> this.compare(o2, o1);
    }

    default ComparatorBy<T> thenBy(ComparatorBy<T> then) {
        return (o1, o2) -> {
            int res = this.compare(o1, o2);
            return (res != 0) ? res : then.compare(o1, o2);
        };
    }

  default <U extends Comparable<? super U>> ComparatorBy<T> thenBy(Function<T, U> prop) {
        return thenBy(comparing(prop));
  }
}

class Comparators {
    public static <T, U extends Comparable<? super U>> ComparatorBy<T> comparing(Function<T, U> prop) {
        return ComparatorBy.comparing(prop);
    }
}

