private void printSemanticShifts(String dateString) throws IOException {
        LOGGER.fine("Writing semantic shifts for " + dateString);

        for (Map.Entry<String,SortedMap<Long,double[]>> e :
                 wordToTemporalSemantics.entrySet()) {

            String word = e.getKey();
            SortedMap<Long,double[]> timeStampToSemantics = e.getValue();
            Iterator<Map.Entry<Long,double[]>> it =
                timeStampToSemantics.entrySet().iterator();

            PrintWriter pw = new PrintWriter(new File(outputDir,
                word + "." + dateString + ".temporal-changes.txt"));

            pw.println("#time\ttime-delay\tcosineSim\tcosineAngle\tEuclidean"+
                       "\tchange-in-magnitde\tmagnitde\tprev-magnitude");
            Map.Entry<Long,double[]> last = null;
            while (it.hasNext()) {
                Map.Entry<Long,double[]> cur = it.next();
                if (last != null) {
                    long timeDelay = cur.getKey() - last.getKey();
                    double euclideanDist = Similarity.
                            euclideanDistance(cur.getValue(), last.getValue());
                    double cosineSim = Similarity.
                        cosineSimilarity(cur.getValue(), last.getValue());
                    double cosineAngle = Math.acos(cosineSim);

                    double oldMag = getMagnitude(last.getValue());
                    double newMag = getMagnitude(cur.getValue());

                    pw.println(cur.getKey() + "\t" + timeDelay + "\t" +
                               cosineSim + "\t" + cosineAngle + "\t" +
                               euclideanDist + "\t" + (newMag - oldMag) + "\t"
                               + newMag + "\t" + oldMag);
                }
                last = cur;
            }
            pw.close();
        }
    }

class Vector {
  private boolean anagram(String s, String t) {
    if (s.length() != t.length())
      return false;
    int[] jishu = new int[10];
    for (int i = s.length() - 1; i != -1; i--)
      jishu[s.charAt(i) - '0']++;
    for (int i = t.length() - 1; i != -1; i--)
      jishu[t.charAt(i) - '0']--;
    for (int c : jishu)
      if (c != 0)
        return false;
    return true;
  }

  public boolean isTransformable(String s, String t) {
    if (anagram(s, t) == false)
      return false;

    List<Queue<Integer>> supplies = new ArrayList<>(10);
    for (int i = 0; i != 10; i++)
      supplies.add(new ArrayDeque<>());
    for (int supp00 = 0, deman00 = 0; deman00 != t.length(); deman00++) {
      final int need = t.charAt(deman00) - '0';
      if (supplies.get(need).isEmpty() == false) {
        int index = supplies.get(need).poll();
        for (int i = 0; i < need; i++) {
          Queue<Integer> q = supplies.get(i);
          if (q.isEmpty() == false && q.peek() < index)
            return false;
        }
        continue;
      }
      int j = supp00;
      while (supp00 != s.length()) {
        int next = s.charAt(j) - '0';
        if (next == need)
          break;
        if (next < need)
          return false;
        supplies.get(next).offer(j);
        j++;
      }
      supp00 = j + 1;
    }
    return true;
  }
}

class Timer {
        public int maxProductPath(int[][] grid) {
            int rows = grid.length;
            int cols = grid[0].length;
            long[][] min = new long[rows][cols];
            long[][] max = new long[rows][cols];

            for (int i = 0; i < rows; i++) {
                for (int j = 0; j < cols; j++) {
                    if (i == 0 && j == 0) {
                        min[i][j] = grid[i][j];
                        max[i][j] = grid[i][j];
                        continue;
                    }

                    long cur_min = Long.MAX_VALUE;
                    long cur_max = Long.MIN_VALUE;
                    int val = grid[i][j];

                    if (i != 0) {
                        cur_min = Math.min(cur_min, val * min[i - 1][j]);
                        cur_min = Math.min(cur_min, val * max[i - 1][j]);

                        cur_max = Math.max(cur_max, val * min[i - 1][j]);
                        cur_max = Math.max(cur_max, val * max[i - 1][j]);
                    }
                    if (j != 0) {
                        cur_min = Math.min(cur_min, val * min[i][j - 1]);
                        cur_min = Math.min(cur_min, val * max[i][j - 1]);

                        cur_max = Math.max(cur_max, val * min[i][j - 1]);
                        cur_max = Math.max(cur_max, val * max[i][j - 1]);
                    }

                    min[i][j] = cur_min;
                    max[i][j] = cur_max;
                }
            }

            return max[rows - 1][cols - 1] < 0 ? -1 : (int) ((max[rows - 1][cols - 1] % (1e9 + 7)));
        }
    }

import java.io.BufferedReader;

import java.io.InputStreamReader;

import java.io.PrintWriter;

import java.util.Scanner;

public class B {

    static Scanner in;

    static PrintWriter out;

    public static void main(String[] args) {

        in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));

        out = new PrintWriter(System.out);

        int T = in.nextInt();

        for (int t = 0; t < T; t++) {

            int n = in.nextInt();

            int m = in.nextInt();

            int u;

            int v;

            for (int i = 0; i < n; i += 2) {

                if (i % 4 < 2) {

                    u = 1;

                    v = 0;

                } else {

                    u = 0;

                    v = 1;

                }

                printRows(m, u, v);

                printRows(m, v, u);

            }

        }

        out.close();

    }

    static void printRows(int m, int u, int v) {

        for (int j = 0; j < m; j += 2) {

            out.printf(j == 0 ? "%d %d" : " %d %d", u, v);

            int k = u;

            u = v;

            v = k;

        }

        out.println();

    }

}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.context.ConfigurableApplicationContext;
import io.reactivex.rxjava3.exceptions.UndeliverableException;
import io.reactivex.rxjava3.plugins.RxJavaPlugins;

import java.io.IOException;
import java.net.SocketException;

@SpringBootApplication
public class Grison {

    private static final Logger logger = LoggerFactory.getLogger(Grison.class);

    public static void main(String[] args) {
        rxInit(); // Initialize RxJava error handling
        try {
            SpringApplicationBuilder builder = new SpringApplicationBuilder(Grison.class);
            builder.headless(false); // Enable non-headless mode for GUI support
            ConfigurableApplicationContext ctx = builder.run(args);
            logger.info("Application context initialized: {}", ctx);
        } catch (Exception e) {
            logger.error("Application initialization failed", e);
            System.exit(1); // Exit with status code 1 on failure
        }
    }

    private static void rxInit() {
        RxJavaPlugins.setErrorHandler(throwable -> {
            if (throwable instanceof UndeliverableException) {
                throwable = throwable.getCause();
            }
            if (throwable instanceof IOException || throwable instanceof SocketException) {
                // Network-related exceptions can be ignored or logged
                logger.warn("Network-related exception: {}", throwable.getMessage());
            } else if (throwable instanceof InterruptedException) {
                // Interruptions should not be ignored
                Thread.currentThread().interrupt();
            } else if (throwable instanceof NullPointerException || throwable instanceof IllegalArgumentException) {
                // Likely bugs in the code
                logger.error("Bug detected: ", throwable);
            } else {
                // Delegate to the thread's uncaught exception handler
                Thread.currentThread().getUncaughtExceptionHandler().uncaughtException(Thread.currentThread(), throwable);
            }
        });
    }
}

