@Override
public Map<String, Object> getShapePropertiesFromCTSer(Object ctSer) {
    Map<String, Object> shapeProperties = new HashMap<>();

    CTShapeProperties spPr = getShapePropertiesFromCTGroup((CTGroup)ctSer);
    for (CTShapeProperties ctShapeProperties : spPr.getSpOrExtLst()) {
        if (ctShapeProperties.isSetSolidFill()) {
            CTSolidColorFillProperties scfp = ctShapeProperties.getSolidFill();
            if (scfp.isSetSrgbClr()) {
                shapeProperties.put("fillColor", scfp.getSrgbClr().getVal());
            }
        }
        if (ctShapeProperties.isSetLine()) {
            CTLineProperties ln = ctShapeProperties.getLine();
            if (ln.isSetSolidFill()) {
                CTSolidColorFillProperties ln_scfp = ln.getSolidFill();
                if (ln_scfp.isSetSrgbClr()) {
                    shapeProperties.put("borderColor", ln_scfp.getSrgbClr().getVal());
                }
            }
        }
    }

    return shapeProperties;
}

class Service {
    public int minElements(int[] nums, int limit, int goal) {
        long sum = 0;
        for (int value : nums) {
            sum += value;
        }
        long target = goal;
        if (sum < target) {
            long diff = target - sum;
            long need = diff / limit;
            if (diff % limit != 0) {
                need ++;
            }
            return (int) need;
        } else if (sum > target) {
            long diff = sum - target;
            long need = diff / limit;
            if (diff % limit != 0) {
                need ++;
            }
            return (int) need;
        } else {
            return 0;
        }
    }
}

