public static String getSingular(String noun) {
   int length = noun.length();
   String singular = "";
   if (noun.endsWith("s")) {
       singular = noun.substring(0, length - 1);
   } else {
       singular = noun;
   }
   return singular;
}

public String getNameSpaceName(String pageTitle) {
    if (pageTitle == null || pageTitle.trim().length() == 0) {
        return "";
    }
    int index = pageTitle.indexOf(":");
    if (index == -1) {
        return "";
    }
    return pageTitle.substring(0, index);
}

