import java.util.Arrays;
 
public class GroupStage{
    //team left digit vs team right digit
    static String[] games = {"12", "13", "14", "23", "24", "34"};
    static String results = "000000";//start with left teams all losing
 
    private static boolean nextResult(){
        if(results.equals("222222")) return false;
        int res = Integer.parseInt(results, 3) + 1;
        results = Integer.toString(res, 3);
        while(results.length() < 6) results = "0" + results;    //left pad with 0s
        return true;
    }
 
    public static void main(String[] args){
        int[][] points = new int[4][10];        //playing 3 games, points range from 0 to 9
        do{
            int[] records = {0,0,0,0};
            for(int i = 0; i < 6; i++){
                switch(results.charAt(i)){
                    case '2': records[games[i].charAt(0) - '1'] += 3; break;    //win for left team
                    case '1':                                                   //draw
                        records[games[i].charAt(0) - '1']++;
                        records[games[i].charAt(1) - '1']++;
                        break;
                    case '0': records[games[i].charAt(1) - '1'] += 3; break;    //win for right team
                }
            }
            Arrays.sort(records);   //sort ascending, first place team on the right
            points[0][records[0]]++;
            points[1][records[1]]++;
            points[2][records[2]]++;
            points[3][records[3]]++;
        }while(nextResult());
        System.out.println("First place: " + Arrays.toString(points[3]));
        System.out.println("Second place: " + Arrays.toString(points[2]));
        System.out.println("Third place: " + Arrays.toString(points[1]));
        System.out.println("Fourth place: " + Arrays.toString(points[0]));
    }
}

import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.UnsupportedEncodingException;
import java.util.Hashtable;

import net.comcraft.client.Comcraft;

/**
 *
 */
public class LangBundle {

    private Hashtable wordMap;
    private Hashtable defaultMap;
    private Comcraft cc;

    public LangBundle(Comcraft cc) {
        wordMap = new Hashtable(150);
        defaultMap = new Hashtable(150);
        this.cc = cc;
    }

    private void loadMap(String fileName, Hashtable map) {
        map.clear();

        BufferedReader bufferedReader;

        InputStream resource = cc.getResourceAsStream(fileName);
        if (resource == null) {
            // A user set a language from a mod and the mod is now missing, resource is null.
            return;
        }
        try {
            bufferedReader = new BufferedReader(new InputStreamReader(resource, "UTF-8"));
        } catch (UnsupportedEncodingException ex) {
            //#debug
//#             ex.printStackTrace();
            bufferedReader = new BufferedReader(new InputStreamReader(resource));
        }

        while (!bufferedReader.getReachedTheEnd()) {
            String word = bufferedReader.readLine();

            if (word != null) {
                String key;
                String text;

                int firstIndex = word.indexOf("=");

                if (firstIndex != -1) {
                    key = word.substring(0, firstIndex);
                    text = word.substring(firstIndex + 1);

                    map.put(key, text);
                }
            }
        }
    }

    public void setDefaultMap(String fileName) {
        loadMap(fileName, defaultMap);
    }

    public void loadBundle(String fileName) {
        loadMap(fileName, wordMap);
    }

    public String getText(String key) {
        String word = (String) wordMap.get(key);

        if (word == null) {
            word = (String) defaultMap.get(key);

            if (word == null) {
                return "???";
            }
        }

        return word;
    }
}

'''

I created a class which stores locations as objects, then builds a ranked list through each add() method call. During the get() method call I return the current best item in the ranked list.

This works as it is guaranteed that the number of get() calls will never exceed the number of add() calls.

class SORTracker:

    def __init__(self):
        self.locations = []

    def add(self, name: str, score: int) -> None:
        new_location = Location(name, score)
        self.locations.append(new_location)
        sorted(self.locations, key=lambda x: (-x.score, x.name))

    def get(self) -> str:
        return self.locations[0].name

class Location:
    def __init__(self, name, score):
        self.name = name
        self.score = score

if __name__ == "__main__":
