public static Class<?> getCommonType(Class<?> type1, Class<?> type2) {
    // Get all the superclasses of the first type
    Set<Class<?>> superclasses1 = new HashSet<>();
    for (Class<?> c = type1; c != null; c = c.getSuperclass()) {
        superclasses1.add(c);
    }

    // Check if the second type is a superclass of the first type
    for (Class<?> c = type2; c != null; c = c.getSuperclass()) {
        if (superclasses1.contains(c)) {
            return c;
        }
    }

    // Check if any interfaces are in common between the two types
    Set<Class<?>> interfaces1 = new HashSet<>(Arrays.asList(type1.getInterfaces()));
    for (Class<?> i : type2.getInterfaces()) {
        if (interfaces1.contains(i)) {
            return i;
        }
    }

    // No common type found, return Object class
    return Object.class;
}

public List<List<Classification.RuntimeClassification>> generate() {
