    List<List<Classification.RuntimeClassification>> treeData = new ArrayList<>();
    for (Classification.RuntimeClassification cls : classes) {
      treeData.add(cls.getClassifications());
    }
    combinations = new ArrayList<>();
    getCombinations(treeData, 0, new ArrayList<>());
    return combinations;
  }

public static ExtractionFn toExtractionFn(QueryGranularity queryGranularity) {
    if (queryGranularity == null) {
        return null;
    }
    switch (queryGranularity) {
        case ALL:
            return IdentityExtractionFn.getInstance();
        case NONE:
            return new TimeFormatExtractionFn("1970-01-01T00:00:00.000Z", "yyyy-MM-dd'T'HH:mm:ss.SSS'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case SECOND:
            return new TimeFormatExtractionFn(null, "yyyy-MM-dd'T'HH:mm:ss'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case MINUTE:
            return new TimeFormatExtractionFn(null, "yyyy-MM-dd'T'HH:mm'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case HOUR:
            return new TimeFormatExtractionFn(null, "yyyy-MM-dd'T'HH'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case DAY:
            return new TimeFormatExtractionFn(null, "yyyy-MM-dd'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case WEEK:
            return new TimeFormatExtractionFn(null, "'W'ww-yyyy'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case MONTH:
            return new TimeFormatExtractionFn(null, "yyyy-MM'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        case YEAR:
            return new TimeFormatExtractionFn(null, "yyyy'Z'", DateTimeZone.UTC, Locale.ENGLISH);
        default:
            throw new IAE("Unknown queryGranularity[%s]", queryGranularity);
    }
}

