    public static void main(final String[] args) {
        try (Writer writer = new BufferedWriter(new FileWriter("sierpinski_square.svg"))) {
            SierpinskiSquareCurve s = new SierpinskiSquareCurve(writer);
            int size = 635, length = 5;
            s.currentAngle = 0;
            s.currentX = (size - length)/2;
            s.currentY = length;
            s.lineLength = length;
            s.begin(size);
            s.execute(rewrite(5));
            s.end();
        } catch (final Exception ex) {
            ex.printStackTrace();
        }
    }
 
    private SierpinskiSquareCurve(final Writer writer) {
        this.writer = writer;
    }
 
    private void begin(final int size) throws IOException {
        write("<svg xmlns='http://www.w3.org/2000/svg' width='%d' height='%d'>\n", size, size);
        write("<rect width='100%%' height='100%%' fill='white'/>\n");
        write("<path stroke-width='1' stroke='black' fill='none' d='");
    }
 
    private void end() throws IOException {
        write("'/>\n</svg>\n");
    }
 
    private void execute(final String s) throws IOException {
        write("M%g,%g\n", currentX, currentY);
        for (int i = 0, n = s.length(); i < n; ++i) {
            switch (s.charAt(i)) {
                case 'F':
                    line(lineLength);
                    break;
                case '+':
                    turn(ANGLE);
                    break;
                case '-':
                    turn(-ANGLE);
                    break;
            }
        }
    }
 
    private void line(final double length) throws IOException {
        final double theta = (Math.PI * currentAngle) / 180.0;
        currentX += length * Math.cos(theta);
        currentY += length * Math.sin(theta);
        write("L%g,%g\n", currentX, currentY);
    }
 
    private void turn(final int angle) {
        currentAngle = (currentAngle + angle) % 360;
    }
 
    private void write(final String format, final Object... args) throws IOException {
        writer.write(String.format(format, args));
    }
 
    private static String rewrite(final int order) {
        String s = AXIOM;
        for (int i = 0; i < order; ++i) {
            final StringBuilder sb = new StringBuilder();
            for (int j = 0, n = s.length(); j < n; ++j) {
                final char ch = s.charAt(j);
                if (ch == 'X')
                    sb.append(PRODUCTION);
                else
                    sb.append(ch);
            }
            s = sb.toString();
        }

import javax.jdo.annotations.Column;
import javax.jdo.annotations.IdentityType;
import javax.jdo.annotations.Inheritance;
import javax.jdo.annotations.InheritanceStrategy;
import javax.jdo.annotations.PersistenceCapable;
import javax.jdo.annotations.PrimaryKey;

import org.apache.isis.applib.util.ObjectContracts;

import au.com.scds.chats.dom.activity.Activity;

//import au.com.scds.chats.dom.AbstractNamedChatsDomainEntity;

/**
 * Base class for the 'name' types.
 *
 * We want to have referential integrity in the database but use strings as
 * primary and foreign keys for these simple code types, so have to use
 * Application as the Identity Type and identify name as the primary key.
 *
 * This means we cannot extend the AbstractNamedChatsDomain entity as DN seems
 * to want the Identity Type of child to be the same as parent class.
 *
 *
 */
// TODO maybe this could be a map to prevent unnecessary database queries
@PersistenceCapable(identityType = IdentityType.APPLICATION)
@Inheritance(strategy = InheritanceStrategy.SUBCLASS_TABLE)
public abstract class ClassificationValue {

    private String name;

    public ClassificationValue() {
    }

    public ClassificationValue(String name) {
        this.name = name;
    }

    public String title(){
        return getName();
    }

    @PrimaryKey
    @Column(allowsNull = "false", length = 50)
    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    @Override
    public boolean equals(final Object obj) {
        if (obj == null) {
            return false;
        }
        if (obj == this) {
            return true;
        }
        if (!this.getClass().isInstance(obj)) {
            return false;
        }
        return ((ClassificationValue) obj).getName().equals(this.getName());
    }

    @Override
    public String toString() {
        return this.getClass().getSimpleName() + ":" + this.getName();
    }
}

