            double distance;
            for (int i = route.posInPoints; i < route.points.size(); ++i){
                Location routeLocation = new Location(route.points.get(i));
                distance = Calculator.distance(location,routeLocation);
                if (minDistance > distance){
                    minDistance = distance;
                }
            }
        }
        return minDistance;
    }

