import java.util.regex.Pattern;
import java.util.regex.Matcher;
import java.util.regex.PatternSyntaxException;
import java.util.ArrayList;
import java.util.List;
import java.util.Stack;
 
public class Sexp {
 
    private static final boolean dbg = false;
 
    private static final String term_regex = "(?mx)\\s*(?:\\s*(?P<brackl>\\()|\\s*(?P<brackr>\\))|\\s*(?P<num>\\-?\\d+\\.\\d+|\\-?\\d+)|\\s*(?P<sq>\"[^\"]*\")|\\s*(?P<s>[^(^)\\s]+))";
 
    public static Object parse_sexp(String sexp) {
        Stack<List<Object>> stack = new Stack<List<Object>>();
        List<Object> out = new ArrayList<Object>();
        if (dbg) System.out.printf("%-6s %-14s %-44s %-s\n", "term", "value", "out", "stack");
        Pattern p = Pattern.compile(term_regex);
        Matcher m = p.matcher(sexp);
        while (m.find()) {
            String term = null;
            String value = null;
            for (String g : m.groupNames()) {
                if (m.group(g)!= null) {
                    term = g;
                    value = m.group(g);
                    break;
                }
            }
            if (dbg) System.out.printf("%-7s %-14s %-44r %-r\n", term, value, out, stack);
            if (term.equals("brackl")) {
                stack.push(out);
                out = new ArrayList<Object>();
            } else if (term.equals("brackr")) {
                assert!stack.isEmpty() : "Trouble with nesting of brackets";
                List<Object> tmpout = out;
                out = stack.pop();
                out.add(tmpout);
            } else if (term.equals("num")) {
                double v = Double.parseDouble(value);
                if (v == (int) v) v = (int) v;
                out.add(v);
            } else if (term.equals("sq")) {
                out.add(value.substring(1, value.length() - 1));
            } else if (term.equals("s")) {
                out.add(value);
            } else {
                throw new RuntimeException("Error: " + term + " " + value);
            }
        }
        assert stack.isEmpty() : "Trouble with nesting of brackets";
        return out.get(0);
    }
 
    public static String print_sexp(Object exp) {
        String out = "";
        if (exp instanceof List) {
            out += "(";
            for (Object x : (List) exp) {
                out += print_sexp(x) + " ";
            }
            out += ")";
        } else if (exp instanceof String && ((String) exp).matches(".*[\\s()].*")) {
            out += "\"" + ((String) exp).replace("\"", "\\\"") + "\"";
        } else {
            out += exp.toString();

