public class MatrixStack {
    private Stack<double[][]> stack = new Stack<>();

    public MatrixStack pushMatrix(double[][] matrix) {
        if (stack.isEmpty()) {
            stack.push(matrix);
        } else {
            double[][] lastMatrix = stack.peek();
            stack.push(lastMatrix);
        }
        return this;
    }
}

