import java.lang.Math.*;
 
class Legendre {
    private final int N;
    private final double[] roots;
    private final double[] weights;
    private final double[][] c;
 
    public Legendre(int N) {
        this.N = N;
        roots = new double[N];
        weights = new double[N];
        c = new double[N + 1][N + 1];
 
        // coefficients:
        c[0][0] = 1.0;
        c[1][1] = 1.0;
        for (int n = 2; n <= N; n++) {
            c[n][0] = (1 - n) * c[n - 2][0] / n;
            for (int i = 1; i <= n; i++)
                c[n][i] = ((2 * n - 1) * c[n - 1][i - 1] - (n - 1) * c[n - 2][i]) / n;
        }
 
        // roots:
        double x;
        double x1;
        for (int i = 1; i <= N; i++) {
            x = cos(PI * (i - 0.25) / (N + 0.5));
            do {
                x1 = x;
                x -= evaluate(N, x) / diff(N, x);
            } while (x!= x1);
 
            x1 = diff(N, x);
            roots[i - 1] = x;
            weights[i - 1] = 2 / ((1 - x * x) * x1 * x1);
        }
 
        System.out.print("Roots:");
        for (double root : roots)
            System.out.printf(" %f", root);
        System.out.println();
        System.out.print("Weights:");
        for (double weight : weights)
            System.out.printf(" %f", weight);
        System.out.println();
    }
 
    public double evaluate(int n, double x) {
        double s = c[n][n];
        for (int i = n; i > 0; i--)
            s = s * x + c[n][i - 1];
        return s;
    }
 
    public double diff(int n, double x) {
        return n * (x * evaluate(n, x) - evaluate(n - 1, x)) / (x * x - 1);
    }
 
    public double integrate(DoubleFunction<Double> f, double a, double b) {
        double c1 = (b - a) / 2;
        double c2 = (b + a) / 2;
        double s = 0.0;
        for (int i = 0; i < N; i++)
            s += weights[i] * f.apply(c1 * roots[i] + c2);
        return c1 * s;
    }
}
 
public class Service {
    public static void main(String[] args) {
        Legendre legendre = new Legendre(5);
        System.out.println("integrating Exp(x) over [-3, 3]:");
        System.out.printf("\t%10.8f\n", legendre.integrate(Math::exp, -3.0, 3.0));
        System.out.println("compared to actual:");
        System.out.printf("\t%10.8f\n", exp(3.0) - exp(-3.0));
    }
}

import java.util.Scanner;

public class AverageAcceleration {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the starting velocity in m/s: ");
        double v0 = input.nextDouble();
        System.out.print("Enter the ending velocity in m/s: ");
        double v1 = input.nextDouble();
        System.out.print("Enter the time span in seconds: ");
        double t = input.nextDouble();

        // Calculate the average acceleration
        double acceleration = (v1 - v0) / t;

        // Display the result
        System.out.printf("The average acceleration is %.2f m/s^2.%n", acceleration);
    }
}

