@WebService
@Stateless
public class KutzCarRentalWS {

    private DataBase db = new DataBase();
    private Utils utils = new Utils();

    @WebMethod
    public List<Car> getCars() {
        return db.getAllCars();
    }

    @WebMethod
    public List<Reservation> getReservations() {
        return db.getAllReservations();
    }

    @WebMethod
    public Reservation createReservation(
            @WebParam(name = "rentalDate") String rentalDate,
            @WebParam(name = "returnDate") String returnDate,
            @WebParam(name = "idCar") int idCar) throws Exception {

        Car car = db.findCarById(idCar);
        if (car == null) {
            throw new Exception("Car not found with ID: " + idCar);
        }

        int totalDays = utils.calculateDays(rentalDate, returnDate);
        double priceTotal = totalDays * car.getPricePerDay();

        Reservation reservation = new Reservation();
        reservation.setRentalDate(rentalDate);
        reservation.setReturnDate(returnDate);
        reservation.setIdCar(idCar);
        reservation.setPriceTotal(priceTotal);

        db.addReservation(reservation);
        return reservation;
    }

    @WebMethod
    public Reservation getReservation(@WebParam(name = "reservationId") int reservationId) throws Exception {
        Reservation reservation = db.findReservationById(reservationId);
        if (reservation == null) {
            throw new Exception("Reservation not found with ID: " + reservationId);
        }
        return reservation;
    }

    @WebMethod
    public Car findCarById(@WebParam(name = "idCar") int idCar) throws Exception {
        Car car = db.findCarById(idCar);
        if (car == null) {
            throw new Exception("Car not found with ID: " + idCar);
        }
        return car;
    }
}

