/**
 * Represents a criterion that belongs to a shared set.
 * <span class="constraint AdxEnabled">This is enabled for AdX.</span>
 */
@XmlAccessorType(XmlAccessType.FIELD)
@XmlType(name = "SharedCriterion", propOrder = {
    "sharedSetId",
    "criterion",
    "negative"
})
public class SharedCriterion {

  @XmlElement(required = true)
  private Long sharedSetId;

  @XmlElement(required = true)
  private Criterion criterion;

  private Boolean negative;

  public SharedCriterion() {}

  /**
   * Gets the shared set id.
   * @return the shared set id
   */
  public Long getSharedSetId() {
    return sharedSetId;
  }

  /**
   * Sets the shared set id.
   * @param sharedSetId the shared set id
   */
  public void setSharedSetId(Long sharedSetId) {
    this.sharedSetId = sharedSetId;
  }

  /**
   * Gets the criterion.
   * @return the criterion
   */
  public Criterion getCriterion() {
    return criterion;
  }

  /**
   * Sets the criterion.
   * @param criterion the criterion
   */
  public void setCriterion(Criterion criterion) {
    this.criterion = criterion;
  }

  /**
   * Gets the negative flag.
   * @return the negative flag
   */
  public Boolean isNegative() {
    return negative;
  }

  /**
   * Sets the negative flag.
   * @param negative the negative flag
   */
  public void setNegative(Boolean negative) {
    this.negative = negative;
  }

  @Override
  public String toString() {
    return "SharedCriterion{" +
        "sharedSetId=" + sharedSetId +
        ", criterion=" + criterion +
        ", negative=" + negative +
        '}';
  }
}

public static DocumentBuilder getXmlParser() {
    try {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setValidating(false);
        factory.setNamespaceAware(true);
        factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
        factory.setFeature("http://xml.org/sax/features/validation", false);
        factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
        factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
        factory.setXIncludeAware(false);
        factory.setExpandEntityReferences(false);
        return factory.newDocumentBuilder();
    } catch (ParserConfigurationException e) {
        throw new RuntimeException("Failed to create XML parser", e);
    }
}

