import java.io.DataOutputStream;
import java.io.IOException;

// Application specific imports
import org.web3d.vrml.lang.*;
import org.web3d.vrml.nodes.VRMLNodeType;

/**
 * A FieldCompressor that works by compressing the range of data.  Floats are
 * converted to ints before range compression.
 *
 */
public class RangeCompressor extends BinaryFieldEncoder {
    /**
     * Compress this field and deposit the output to the bitstream
     *
     * @param dos The stream to output the result
     * @param fieldType The type of field to compress from FieldConstants.
     * @param data The field data
     */
    public void compress(DataOutputStream dos, int fieldType, int[] data)
        throws IOException {

        CompressionTools.rangeCompressIntArray(dos,false,1,data);
    }

    /**
     * Compress this field and deposit the output to the bitstream
     *
     * @param dos The stream to output the result
     * @param fieldType The type of field to compress from FieldConstants.
     * @param data The field data
     */
    public void compress(DataOutputStream dos, int fieldType, float[] data)
        throws IOException {
        switch(fieldType) {
            case FieldConstants.SFCOLOR:
            case FieldConstants.SFVEC3F:
            case FieldConstants.SFROTATION:
            case FieldConstants.SFCOLORRGBA:
            case FieldConstants.SFVEC2F:
                for(int i=0; i < data.length; i++) {
                   dos.writeFloat(data[i]);
                }
                break;
            case FieldConstants.MFCOLOR:
            case FieldConstants.MFVEC3F:
            case FieldConstants.MFFLOAT:
            case FieldConstants.MFROTATION:
            case FieldConstants.MFCOLORRGBA:
            case FieldConstants.MFVEC2F:
                CompressionTools.compressFloatArray(dos, false,1,data);
                break;
            default:
                System.out.println("Unhandled datatype in compress float[]: " + fieldType);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Objects;
 
public class RandomLatinSquares {
    private static void printSquare(List<List<Integer>> latin) {
        for (List<Integer> row : latin) {
            Iterator<Integer> it = row.iterator();
 
            System.out.print("[");
            if (it.hasNext()) {
                Integer col = it.next();
                System.out.print(col);
            }
            while (it.hasNext()) {
                Integer col = it.next();
                System.out.print(", ");
                System.out.print(col);
            }
            System.out.println("]");
        }
        System.out.println();
    }
 
    private static void latinSquare(int n) {
        if (n <= 0) {
            System.out.println("[]");
            return;
        }
 
        List<List<Integer>> latin = new ArrayList<>(n);
        for (int i = 0; i < n; ++i) {
            List<Integer> inner = new ArrayList<>(n);
            for (int j = 0; j < n; ++j) {
                inner.add(j);
            }
            latin.add(inner);
        }
        // first row
        Collections.shuffle(latin.get(0));
 
        // middle row(s)
        for (int i = 1; i < n - 1; ++i) {
            boolean shuffled = false;
            shuffling:
            while (!shuffled) {
                Collections.shuffle(latin.get(i));
                for (int k = 0; k < i; ++k) {
                    for (int j = 0; j < n; ++j) {
                        if (Objects.equals(latin.get(k).get(j), latin.get(i).get(j))) {
                            continue shuffling;
                        }
                    }
                }
                shuffled = true;
            }
        }
 
        // last row
        for (int j = 0; j < n; ++j) {
            List<Boolean> used = new ArrayList<>(n);
            for (int i = 0; i < n; ++i) {
                used.add(false);
            }
            for (int i = 0; i < n - 1; ++i) {
                used.set(latin.get(i).get(j), true);
            }
            for (int k = 0; k < n; ++k) {
                if (!used.get(k)) {
                    latin.get(n - 1).set(j, k);
                    break;
                }
            }
        }
 
        printSquare(latin);
    }
 
    public static void main(String[] args) {
        latinSquare(5);
        latinSquare(5);
        latinSquare(10);
    }
}

import com.squareup.javapoet.*;
import javax.lang.model.element.Modifier;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

public class AbstractTypeInitialiser {

    private static final String DEFAULT_PACKAGE = "com.generated.types";
    private static final String DEFAULT_DESCRIPTION = "Auto-generated interface type";

    public static class TypeDesc {
        private String typeName;
        private String packageName;
        private String description;
        private List<MethodSpec> methods;

        private TypeDesc(Builder builder) {
            this.typeName = builder.typeName;
            this.packageName = builder.packageName;
            this.description = builder.description;
            this.methods = builder.methods;
        }

        public static class Builder {
            private String typeName;
            private String packageName = DEFAULT_PACKAGE;
            private String description = DEFAULT_DESCRIPTION;
            private List<MethodSpec> methods = Collections.emptyList();

            public Builder typeName(String typeName) {
                this.typeName = typeName;
                return this;
            }

            public Builder packageName(String packageName) {
                this.packageName = packageName;
                return this;
            }

            public Builder description(String description) {
                this.description = description;
                return this;
            }

            public Builder methods(List<MethodSpec> methods) {
                this.methods = methods;
                return this;
            }

            public TypeDesc build() {
                return new TypeDesc(this);
            }
        }
    }

    public Optional<TypeSpec> create(TypeDesc typeDesc) {
        return Optional.ofNullable(interfaceBuilder(typeDesc));
    }

    private TypeSpec interfaceBuilder(TypeDesc typeDesc) {
        if (typeDesc == null || typeDesc.typeName == null) {
            return null;
        }

        TypeSpec.Builder interfaceBuilder = TypeSpec.interfaceBuilder(typeDesc.typeName)
                .addModifiers(Modifier.PUBLIC)
                .addJavadoc(docType(typeDesc));

        typeDesc.methods.forEach(interfaceBuilder::addMethod);

        return interfaceBuilder.build();
    }

    private String docType(TypeDesc typeDesc) {
        return String.format("%s\n\n@generated",
            Optional.ofNullable(typeDesc.description)
                .orElse(DEFAULT_DESCRIPTION)
        );
    }
}

