public int findTileSYMPART(double x1, double x2) {
    // Assuming the tiles are arranged in a 3x3 grid
    // and each tile is of equal size
    // Calculate the width and height of each tile
    double tileWidth = 1.0 / 3.0;
    double tileHeight = 1.0 / 3.0;

    // Determine the row and column of the point (x1, x2)
    int row = (int) Math.floor(x2 / tileHeight);
    int col = (int) Math.floor(x1 / tileWidth);

    // Check if the point is within the bounds of the grid
    if (row < 0 || row >= 3 || col < 0 || col >= 3) {
        return -1;
    }

    // Calculate the tile number based on the row and column
    return row * 3 + col;
}

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public static LocalDateTime convertToDateTime(Object o, ZoneId timeZone, LocalDateTime defaultValue) {
    if (o == null) {
        return defaultValue;
    }
    try {
        String str = o.toString().trim();
        if (str.isEmpty()) {
            return defaultValue;
        }
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");
        formatter = formatter.withLocale(Locale.getDefault()).withZone(timeZone);
        return LocalDateTime.parse(str, formatter);
    } catch (DateTimeParseException ex) {
        return defaultValue;
    }
}

