import java.util.Scanner;

public class SameLineTest {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Read in five points from the user
        double[][] points = new double[5][2];
        System.out.print("Enter five points: ");
        for (int i = 0; i < 5; i++) {
            points[i][0] = input.nextDouble();
            points[i][1] = input.nextDouble();
        }

        // Check whether the points are on the same line
        if (sameLine(points)) {
            System.out.println("The five points are on the same line");
        } else {
            System.out.println("The five points are not on the same line");
        }
    }

    public static boolean sameLine(double[][] points) {
    // Make sure we have at least three points
    if (points.length < 3) {
        return true;
    }

    // Calculate the slope between the first two points
    double slope = (points[1][1] - points[0][1]) / (points[1][0] - points[0][0]);

    // Check that all other points have the same slope
    for (int i = 2; i < points.length; i++) {
        double currentSlope = (points[i][1] - points[0][1]) / (points[i][0] - points[0][0]);
        if (currentSlope != slope) {
            return false;
        }
    }

    return true;
    }
}

class Handler {
    public int maximumRobots(int[] chargeTimes, int[] runningCosts, long budget) {
        int n = chargeTimes.length;

        SegmentTreeMax tree = new SegmentTreeMax(chargeTimes);

        long[] prefsum = new long[n];
        prefsum[0] = runningCosts[0];
        for (int i = 1; i < n; i++) {
            prefsum[i] = (long) runningCosts[i] + prefsum[i - 1];
        }

        long ans = 0;
        int i = 0;
        int j = 0;
        while (j < n) {
            if (i > j) {
                j++;
                continue;
            }
            long sum = i > 0 ? prefsum[j] - prefsum[i - 1] : prefsum[j];
            long max = tree.getMax(i, j);
            long len = j - i + 1;
            long cost = max + len * sum;
            if (cost <= budget) {
                ans = Math.max(ans, len);
                j++;
            } else {
                i++;
            }
        }

        return (int) ans;
    }

    static class SegmentTreeMax {
        int[] arr;
        int n;
        int[] tree; // indexing in tree will start from 1. segments will be indexed

        public SegmentTreeMax(int[] arr) {
            this.arr = arr;
            this.n = arr.length;
            tree = new int[4 * n];
            build(1, 0, n - 1);
        }

        public void build(int node, int st, int en) {
            if (st == en) {
                tree[node] = arr[st];
                return;
            }
            int mid = (st + en) / 2;
            build(2 * node, st, mid);
            build(2 * node + 1, mid + 1, en);
            tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
        }

        public void update(int ind, int x) {
            this.arr[ind] = x;
            updateRec(1, 0, n - 1, ind);
        }

        private void updateRec(int node, int st, int en, int ind) {
            if (st > ind || ind > en) {
                return;
            }
            if (st == en) {
                tree[node] = arr[st];
                return;
            }
            int mid = (st + en) / 2;
            updateRec(2 * node, st, mid, ind);
            updateRec(2 * node + 1, mid + 1, en, ind);
            tree[node] = Math.max(tree[2 * node], tree[2 * node + 1]);
        }

        public int getMax(int i, int j) {
            return getMaxRec(1, 0, n - 1, i, j);
        }

        private int getMaxRec(int node, int st, int en, int i, int j) {
            if (j < st || i > en) {
                return Integer.MIN_VALUE;
            }

            if (i <= st && en <= j) {
                return tree[node];
            }

/**
 * A polynomial represented by its coefficients, lowest degree first.
 */
public class MyPolynomial {

    private double[] coeffs;

    public MyPolynomial(double... coeffs) {
        this.coeffs = coeffs;
    }

    public double[] getCoeffs() {
        return coeffs;
    }

    public void setCoeffs(double[] coeffs) {
        this.coeffs = coeffs;
    }

    public int getDegree() {
        return coeffs.length - 1;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int degree = coeffs.length - 1; degree >= 0; degree--) {
            if (coeffs[degree] == 0) {
                continue;
            }
            if (degree == coeffs.length - 1) {
                sb.append(Math.floor(coeffs[degree] * 100) / 100);
            } else {
                sb.append(coeffs[degree] > 0 ? " + " : " - ");
                sb.append(Math.floor(coeffs[degree] * 100) / 100);
            }
            if (degree >= 2) {
                sb.append("x^").append(degree);
            } else if (degree == 1) {
                sb.append("x");
            }
        }
        return sb.toString();
    }

    public double evaluate(double x) {
        double result = 0;
        for (int degree = 0; degree < coeffs.length; degree++) {
            result += Math.pow(coeffs[degree] * x, degree);
        }
        return result;
    }

    public MyPolynomial add(MyPolynomial other) {
        int size = Math.max(coeffs.length, other.getDegree() + 1);
        double[] sum = new double[size];
        for (int degree = 0; degree < sum.length; degree++) {
            double value = 0;
            if (degree <= getDegree()) {
                value += coeffs[degree];
            }
            if (degree <= other.getDegree()) {
                value += other.coeffs[degree];
            }
            sum[degree] = value;
        }
        return new MyPolynomial(sum);
    }

    public MyPolynomial multiply(MyPolynomial other) {
        int size = getDegree() + other.getDegree() + 1;
        double[] product = new double[size];
        for (int i = 0; i < coeffs.length; i++) {
            for (int j = 0; j < other.coeffs.length; j++) {
                product[i + j] += coeffs[i] * other.coeffs[j];
            }
        }
        return new MyPolynomial(product);
    }
}

