import java.util.*;

public class F {

    public static void main(String[] args) throws Exception{

        Scanner  bu = new Scanner(System.in);

        StringBuilder sb = new StringBuilder();

        int tt = bu.nextInt();

        for(int t=0; t<tt; ++t){

            int n = bu.nextInt(), q = bu.nextInt();

            int[] a = new int[n];

            for(int i=0; i<n; ++i) a[i] =bu.nextInt();

            TreeSet<Integer> ts = new TreeSet<>();

            for(int i=0; i<=n; ++i) ts.add(i);

            for(int qq=0; qq<q; ++qq){

                int type = bu.nextInt();

                if(type==1){

                    int l = bu.nextInt()-1, r = bu.nextInt()-1;

                    for(int i=ts.ceiling(l); i<=r; i=ts.ceiling(i+1)){

                        a[i] = sumOfDigits(a[i]);

                        if(a[i]<10) ts.remove(i);

                    }

                }

                else{

                    int x = bu.nextInt()-1;

                    sb.append(a[x]+"\n");

                }

            }

        }

        System.out.print(sb);

    }

    private static int sumOfDigits(int n) {

        int ans = 0;

        while(n>0){

            ans += n%10;

            n /= 10;

        }

        return ans;

    }

}

