import java.util.function.Function;
 
public class Shape {
    public static void main(String[] args) {
        System.out.println(makeList(". "));
    }
 
    public static String makeList(String sep) {
        int counter = 0;
        Function<String, String> makeItem = label -> {
            counter += 1;
            return counter + sep + label;
        };
        return makeItem.apply("First") + "\n" + makeItem.apply("Second") + "\n" + makeItem.apply("Third");
    }
}

