public class DivansChocolateShop {

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        int testCases = Integer.parseInt(scanner.nextLine());

        while (testCases-- > 0) {
            String[] inputs = scanner.nextLine().split(" ");
            int n = Integer.parseInt(inputs[0]);
            int l = Integer.parseInt(inputs[1]);
            int r = Integer.parseInt(inputs[2]);
            int k = Integer.parseInt(inputs[3]);

            String pricesString = scanner.nextLine();
            String[] prices = pricesString.split(" ");
            int[] pricesArray = new int[n];

            for (int i = 0; i < n; i++) {
                pricesArray[i] = Integer.parseInt(prices[i]);
            }

            Arrays.sort(pricesArray);

            int count = 0;
            int totalCost = 0;
            for (int i = 0; i < n; i++) {
                if (pricesArray[i] >= l && pricesArray[i] <= r && totalCost + pricesArray[i] <= k) {
                    count++;
                    totalCost += pricesArray[i];
                }
            }

            System.out.println(count);
        }

        scanner.close();
    }
}

private static int getSortPriority(JTable table, int column)
    {
        List<? extends SortKey> sortKeys = table.getRowSorter().getSortKeys();
        for (int i=0; i<sortKeys.size(); i++)
        {
            SortKey sortKey = sortKeys.get(i);
            if (sortKey.getColumn() == table.convertColumnIndexToModel(column))
            {
                return i;
            }
        }
        return -1;
    }

