import java.io.File;
import java.util.StringTokenizer;

import org.core.Fichero;

public class Processor {

    public static void main(String[] args) {
        if (args.length != 1) {
            System.err.println("Usage: java Processor <configFile>");
            System.exit(-1);
        }

        String configFile = args[0];

        try {
            execute(configFile);
        } catch (Exception e) {
            System.err.println("Error during execution: " + e.getMessage());
            e.printStackTrace();
            System.exit(-1);
        }
    }

    public static void execute(String configFile) throws Exception {
        Fichero file = new Fichero(configFile);
        String linea = file.readLine();

        String trainingInput = "";
        String testingInput = "";
        String trainingOutput = "";
        String testingOutput = "";

        String parameters = "";

        while (linea != null) {
            if (linea.startsWith("%input_data_training")) {
                trainingInput = file.readLine().trim();
            } else if (linea.startsWith("%input_data_testing")) {
                testingInput = file.readLine().trim();
            } else if (linea.startsWith("%output_data_training")) {
                trainingOutput = file.readLine().trim();
            } else if (linea.startsWith("%output_data_testing")) {
                testingOutput = file.readLine().trim();
            } else if (linea.startsWith("%algorithm")) {
                parameters = file.readLine().trim();
            }

            linea = file.readLine();
        }

        file.close();

        RMini rMini = new RMini();

        // Parse parameters and set them to RMini
        StringTokenizer st = new StringTokenizer(parameters, ",");
        while (st.hasMoreTokens()) {
            String parameter = st.nextToken().trim();
            String[] parts = parameter.split("=");
            if (parts.length == 2) {
                String paramName = parts[0].trim();
                String paramValue = parts[1].trim();
                rMini.setParameter(paramName, paramValue);
            }
        }

        // Set data files to RMini
        rMini.setTrainingInput(trainingInput);
        rMini.setTestingInput(testingInput);
        rMini.setTrainingOutput(trainingOutput);
        rMini.setTestingOutput(testingOutput);

        // Execute RMini algorithm
        rMini.execute();

        System.out.println("RMini execution completed successfully.");
    }
}

import java.util.Collection;
import java.util.concurrent.CountDownLatch;

public class TextGetOneCommand {

    private final int mergeCount;
    private final Collection<TextGetOneCommand> mergeCommands;
    private final Collection<TextGetOneCommand> assocCommands;
    private final CountDownLatch countDownLatch;
    private CachedData result;
    private boolean completed;

    public TextGetOneCommand(int mergeCount, Collection<TextGetOneCommand> mergeCommands,
                             Collection<TextGetOneCommand> assocCommands) {
        this.mergeCount = mergeCount;
        this.mergeCommands = mergeCommands;
        this.assocCommands = assocCommands;
        this.countDownLatch = new CountDownLatch(mergeCount);
        this.completed = false;
    }

    public void dispatch(String key, CachedData data) {
        if (mergeCount == 1) {
            handleSingleGet(key, data);
        } else {
            handleMergedGet(key, data);
        }
    }

    private void handleSingleGet(String key, CachedData data) {
        if (data != null) {
            setResult(data);
        } else {
            decodeError();
        }
        countDownLatch();
    }

    private void handleMergedGet(String key, CachedData data) {
        for (TextGetOneCommand cmd : mergeCommands) {
            if (cmd != this) {
                cmd.dispatch(key, data);
            }
        }
        setResult(data);
        countDownLatch();
    }

    private void setResult(CachedData data) {
        this.result = data;
        this.completed = true;
    }

    private void decodeError() {
        this.result = null;
        this.completed = true;
    }

    private void countDownLatch() {
        countDownLatch.countDown();
        if (countDownLatch.getCount() == 0) {
            for (TextGetOneCommand cmd : assocCommands) {
                cmd.countDownLatch();
            }
        }
    }

    public CachedData getResult() {
        return result;
    }

    public boolean isCompleted() {
        return completed;
    }
}

