    static class PROBLEM {

        public void solve(FastReader in, PrintWriter out) {

            int n = in.ni(), k = in.ni(), a[] = in.ra(n);

            int max = 1, l = 1;

            for (int i = 1; i < k-1; i++) {

                if(a[i] > a[i-1] && a[i] > a[i+1]) max++;

            }

            int cur = max;

            for (int i = 1; i < n-k+1; i++) {

                if(a[i+k-2] > a[i+k-3] && a[i+k-2] > a[i+k-1]) cur++;

                if(a[i] > a[i-1] && a[i] > a[i+1]) cur--;

                if(cur > max){

                    max = cur;

                    l = i+1;

                    //out.println("i = " + i + " cur = " + cur + " [l,r] = " + (i+1) + "," + (i+k));

                }

            }

            out.println(max + " " + l);

        }

    }

    static int find(int u){

        if(u == parent[u]) return u;

        return parent[u] = find(parent[u]);

    }

    static void union(int u, int v){

        int a = find(u), b = find(v);

        if(a == b) return;

        if(rank[a] > rank[b]){

            parent[b] = a;

            rank[a] += rank[b];

        }else{

            parent[a] = b;

            rank[b] += rank[a];

        }

    }

    static void dsu(){

        for (int i = 0; i < 101; i++) {

            parent[i] = i;

            rank[i] = 1;

        }

    }

