import java.util.*;

class Tree {
    public int[] resultArray(int[] a) {
        Map<Integer, Integer> m = compress(a);
        FenwickTree f1 = new FenwickTree(100005), f2 = new FenwickTree(100005);
        List<Integer> l1 = new ArrayList<>(), l2 = new ArrayList<>();
        l1.add(a[0]);
        f1.adjust(m.get(a[0]), 1);
        l2.add(a[1]);
        f2.adjust(m.get(a[1]), 1);
        for(int i = 2; i < a.length; i++) {
            int x = m.get(a[i]);
            int c1 = f1.rangeSumQuery(x + 1, 100004);
            int c2 = f2.rangeSumQuery(x + 1, 100004);
            if(c1 > c2) {
                l1.add(a[i]);
                f1.adjust(x, 1);
            }
            else if(c1 < c2) {
                l2.add(a[i]);
                f2.adjust(x, 1);
            }
            else {
                if(l1.size() <= l2.size()) {
                    l1.add(a[i]);
                    f1.adjust(x, 1);
                }
                else {
                    l2.add(a[i]);
                    f2.adjust(x, 1);
                }
            }
        }
        int[] ans = new int[a.length];
        int k = 0, i1 = 0, i2 = 0;
        for(; i1 < l1.size(); i1++, k++) {
            ans[k] = l1.get(i1);
        }
        for(; i2 < l2.size(); i2++, k++) {
            ans[k] = l2.get(i2);
        }
        return ans;
    }
    private Map<Integer, Integer> compress(int[] a) {
        Map<Integer, Integer> m = new HashMap<>();
        int[] b = Arrays.copyOf(a, a.length);
        Arrays.sort(b);
        int v = 1;
        for(int i = 0; i < b.length; i++) {
            if(i == 0 || b[i] != b[i - 1]) {
                m.put(b[i], v);
                v++;
            }
        }
        return m;
    }
}
class FenwickTree {
    private int[] ft;

    /*
        n is the largest integer value among all the input integers
     */
    public FenwickTree(int n) {
        ft = new int[n];
    }

    /*
        query the sum in range [l, r]
     */
    public int rangeSumQuery(int l, int r) {
        if(l > r) return 0;
        return rangeSumQuery(r) - (l == 1 ? 0 : rangeSumQuery(l - 1));
    }

    /*
        query the sum in range[1, r]
     */
    private int rangeSumQuery(int r) {
        int sum = 0;
        for(; r > 0; r -= leastSignificantOne(r)) {
            sum += ft[r];
        }
        return sum;
    }

    /*
        adjust the value of index k by diff
     */
    public void adjust(int k, int diff) {
        for(; k < ft.length; k += leastSignificantOne(k)) {
            ft[k] += diff;
        }
    }

    private int leastSignificantOne(int i) {

