import java.util.Random;
 
public class BestShuffle {
    private final static Random rand = new Random();
 
    public static void main(String[] args) {
        String[] words = {"abracadabra", "seesaw", "grrrrrr", "pop", "up", "a"};
        for (String w : words)
            System.out.println(bestShuffle(w));
    }
 
    public static String bestShuffle(final String s1) {
        char[] s2 = s1.toCharArray();
        shuffle(s2);
        for (int i = 0; i < s2.length; i++) {
            if (s2[i] != s1.charAt(i))
                continue;
            for (int j = 0; j < s2.length; j++) {
                if (s2[i] != s2[j] && s2[i] != s1.charAt(j) && s2[j] != s1.charAt(i)) {
                    char tmp = s2[i];
                    s2[i] = s2[j];
                    s2[j] = tmp;
                    break;
                }
            }
        }
        return s1 + " " + new String(s2) + " (" + count(s1, s2) + ")";
    }
 
    public static void shuffle(char[] text) {
        for (int i = text.length - 1; i > 0; i--) {
            int r = rand.nextInt(i + 1);
            char tmp = text[i];
            text[i] = text[r];
            text[r] = tmp;
        }
    }
 
    private static int count(final String s1, final char[] s2) {
        int count = 0;
        for (int i = 0; i < s2.length; i++)
            if (s1.charAt(i) == s2[i])
                count++;
        return count;
    }
}

public class Processor {
    public List<List<Integer>> updateMatrix(List<List<Integer>> matrix) {
        if (matrix == null || matrix.size() == 0 || matrix.get(0).size() == 0) {
            return matrix;
        }

        Queue<int[]> queue = new LinkedList<int[]>();
        List<List<Integer>> res = new ArrayList<List<Integer>>();
        for (int i = 0; i < matrix.size(); i++) {
            List<Integer> tmp = new ArrayList<Integer>();
            for (int j = 0; j < matrix.get(i).size(); j++) {
                int value = matrix.get(i).get(j);
                if (value == 0) {
                    queue.offer(new int[]{i, j});
                    tmp.add(0);
                } else {
                    tmp.add(Integer.MAX_VALUE);
                }
            }
            res.add(tmp);
        }

        while (!queue.isEmpty()) {
            int[] point = queue.poll();
            int row = point[0], col = point[1];
            int value = res.get(row).get(col);
            int newVal = value + 1;
            if (row > 0) {
                int check1 = res.get(row - 1).get(col);
                if (check1 > newVal) {
                    res.get(row - 1).set(col, newVal);
                    queue.offer(new int[]{row - 1, col});
                }
            }
            if (row < res.size() - 1) {
                int check2 = res.get(row + 1).get(col);
                if (check2 > newVal) {
                    res.get(row + 1).set(col, newVal);
                    queue.offer(new int[]{row + 1, col});
                }
            }
            if (col > 0) {
                int check2 = res.get(row).get(col - 1);
                if (check2 > newVal) {
                    res.get(row).set(col - 1, newVal);
                    queue.offer(new int[]{row, col - 1});
                }
            }
            if (col < res.get(0).size() - 1) {
                int check2 = res.get(row).get(col + 1);
                if (check2 > newVal) {
                    res.get(row).set(col + 1, newVal);
                    queue.offer(new int[]{row, col + 1});
                }
            }
        }
        return res;
    }
}

