class Builder {
    int max(int a,int b){
        return a>b?a:b;
    }
    int min(int a,int b){
        return a<b?a:b;
    }

    public int distributeCookies(int[] cookies, int k) {
        int n=cookies.length;
        int[] gs=new int[n+1];
        int m=1;
        int ret=2147483647;
        while (gs[0]==0){
            int[] cou=new int[k];
            for (int i=0;i<n;i++){
                cou[gs[i+1]]+=cookies[i];
            }
            int ref=0;
            for (int i=0;i<k;i++){
                ref=max(ref,cou[i]);
            }
            ret=min(ret,ref);
            int j=n;
            while (gs[j]==k-1){
                j--;
            }
            gs[j]++;
            for (int i=j+1;i<=n;i++){
                gs[i]=0;
            }
        }
        return ret;
    }
}

