private <T> T invoke(Context context, Map<String, String[]> parameters, Class<T> classOfT, String paramPrefix) {
    try {
        Constructor<T> constructor = classOfT.getConstructor();
        T instance = constructor.newInstance();

        for (Map.Entry<String, String[]> entry : parameters.entrySet()) {
            String key = entry.getKey();
            if (key.startsWith(paramPrefix)) {
                String fieldName = key.substring(paramPrefix.length());
                Field field = classOfT.getDeclaredField(fieldName);
                field.setAccessible(true);
                field.set(instance, entry.getValue());
            }
        }

        return instance;
    } catch (NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException | NoSuchFieldException e) {
        e.printStackTrace();
    }

    return null;
}

