public class Tree {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int a = sc.nextInt();
            int b = sc.nextInt();
            int c = sc.nextInt();
            int[] p = new int[m];
            for (int i = 0; i < m; i++) {
                p[i] = sc.nextInt();
            }
            int[][] g = new int[n][n];
            for (int i = 0; i < m; i++) {
                int u = sc.nextInt() - 1;
                int v = sc.nextInt() - 1;
                g[u][v] = g[v][u] = p[i];
            }
            int[] d = new int[n];
            Arrays.fill(d, Integer.MAX_VALUE);
            d[a - 1] = 0;
            boolean[] used = new boolean[n];
            for (int i = 0; i < n; i++) {
                int v = -1;
                for (int j = 0; j < n; j++) {
                    if (!used[j] && (v == -1 || d[j] < d[v])) {
                        v = j;
                    }
                }
                used[v] = true;
                for (int j = 0; j < n; j++) {
                    if (g[v][j] != 0) {
                        d[j] = Math.min(d[j], d[v] + g[v][j]);
                    }
                }
            }
            int ans = d[b - 1] + d[c - 1];
            System.out.println(ans);
        }
    }
}

