    }
}

import java.util.Stack;

public class Checker {
    public int[] nextGreaterElements(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        Stack<Integer> stack = new Stack<>();

        for (int i = 2 * n - 1; i >= 0; i--) {
            while (!stack.isEmpty() && stack.peek() <= nums[i % n]) {
                stack.pop();
            }
            res[i % n] = stack.isEmpty()? -1 : stack.peek();
            stack.push(nums[i % n]);
        }

        return res;
    }
}

// The compiler can automatically implement Clone on structs (assuming all members have implemented Clone).
class Tree<T> implements Cloneable {
    Leaf<T> left;
    T data;
    Leaf<T> right;
 
    Tree(T data) {
        this.left = null;
        this.data = data;
        this.right = null;
    }
 
    static <T> Leaf<T> leaf(T d) {
        return new Leaf<>(new Tree<>(d));
    }
 
    @Override
    public Tree<T> clone() {
        try {
            Tree<T> clone = (Tree<T>) super.clone();
            clone.left = left == null? null : left.clone();
            clone.right = right == null? null : right.clone();
            return clone;
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }
}
 
class Leaf<T> implements Cloneable {
    Tree<T> tree;
 
    Leaf(Tree<T> tree) {
        this.tree = tree;
    }
 
    @Override
    public Leaf<T> clone() {
        try {
            return (Leaf<T>) super.clone();
        } catch (CloneNotSupportedException e) {
            throw new RuntimeException(e);
        }
    }
}
 
