public class Ackermann {
    public static int ack(int m, int n) {
        if (m == 0) {
            return n + 1;
        } else if (n == 0) {
            return ack(m - 1, 1);
        } else {
            return ack(m - 1, ack(m, n - 1));
        }
    }
 
    public static void main(String[] args) {
        int a = ack(3, 4);
        System.out.println(a); // 125
    }
}

class Runner {
    public int preimageSizeFZF(int K) {
        int i = 0;
        int nz = 0;
        int start = -1;
        if (K == 0) {
            return 5;
        }
        int mul = 0;
        while ((K-nz) >= 31) {
            int v = mul+1;
            if ((mul+1) % 5 == 0 && K-nz <= 50) {
                break;
            }
            mul += 1;
            i += 125;
            nz += 31;
            while (v % 5 == 0) {
                nz += 1;
                v /= 5;
            }
        }
        if (K == nz) {
            start = i;
        }
        i += 1;
        while (true) {
            int v = i;
            while (v % 5 == 0) {
                v /= 5;
                nz += 1;
            }
            if (nz > K) {
                if (start == -1) {
                    return 0;
                }
                return i-start;
            }
            if (nz == K && start == -1) {
                start = i;
            }
            i += 1;
        }
    }
}

import java.util.Arrays;
 
public class PartialApplication {
    interface IntegerFunction {
        int call(int arg);
    }
 
    // Original method fs(f, s).
    static int[] fs(IntegerFunction f, int[] s) {
        int[] r = new int[s.length];
        for (int i = 0; i < s.length; i++)
            r[i] = f.call(s[i]);
        return r;
    }
 
    interface SequenceFunction {
        int[] call(int[] arg);
    }
 
    // Curried method fs(f).call(s),
    // necessary for partial application.
    static SequenceFunction fs(final IntegerFunction f) {
        return new SequenceFunction() {
            public int[] call(int[] s) {
                // Call original method.
                return fs(f, s);
            }
        };
    }
 
    static IntegerFunction f1 = new IntegerFunction() {
        public int call(int i) {
            return i * 2;
        }
    };
 
    static IntegerFunction f2 = new IntegerFunction() {
        public int call(int i) {
            return i * i;
        }
    };
 
    static SequenceFunction fsf1 = fs(f1); // Partial application.
 
    static SequenceFunction fsf2 = fs(f2);
 
    public static void main(String[] args) {
        int[][] sequences = {
            { 0, 1, 2, 3 },
            { 2, 4, 6, 8 },
        };
 
        for (int[] array : sequences) {
            System.out.printf(
                "array: %s\n" +
                "  fsf1(array): %s\n" +
                "  fsf2(array): %s\n",
                Arrays.toString(array),
                Arrays.toString(fsf1.call(array)),
                Arrays.toString(fsf2.call(array)));
        }
    }
}

class Logger {
    public List<Integer> filterRestaurants(int[][] rest, int veg, int mp, int md) {
        List<int[]> list = new ArrayList<>();
        List<Integer> re = new ArrayList<>();
        for(int[] r : rest)
        {
            // [idi, ratingi, veganFriendlyi, pricei, distancei]
            if(veg == 1 && r[2] == 0) continue;
            if(r[3] > mp) continue;
            if(r[4] > md) continue;
            list.add(r);
        }
        Collections.sort(list, (a, b)->(a[1] == b[1] ? b[0] - a[0] : b[1] - a[1]));
        for(int[] r : list)
        {
            re.add(r[0]);
        }
        return re;
    }
}

import java.util.ArrayList;
import java.util.Scanner;

public class Product {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter five integers: ");
        ArrayList<Integer> list = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            list.add(in.nextInt());
        }

        sort(list);
        System.out.print("The numbers in increasing order: ");
        System.out.print("\n" + list.toString());
        in.close();
    }

    public static void sort(ArrayList<Integer> list) {
        boolean loop = true;
        while (loop) {
            loop = false; //Reset to check if can remain false
            for (int n = 0; n < list.size(); n++) {
                for (int i = n; i < list.size(); i++) {
                    if (!(i == n)) {
                        if (list.get(n) > list.get(i)) {
                            loop = true; // Not finished sorting..
                            swapElements(list, n, i);
                        }

                    }
                }
            }

        }

    }

    static void swapElements(ArrayList<Integer> list, int idx1, int idx2) {
        Integer temp = list.get(idx1);
        list.set(idx1, list.get(idx2));
        list.set(idx2, temp);
    }
}

