import static org.easymock.EasyMock.expect;
import static org.junit.Assert.assertSame;

public class FeatureToggleInterceptorTest extends EasyMockTest {

  private AnnotatedAuroraAdmin realThrift;
  private AnnotatedAuroraAdmin decoratedThrift;
  private Predicate<Method> predicate;

  @Before
  public void setUp() {
    realThrift = createMock(AnnotatedAuroraAdmin.class);
    predicate = createMock(new Clazz<Predicate<Method>>() { });
    Injector injector = Guice.createInjector(new AbstractModule() {
      @Override
      protected void configure() {
        MockDecoratedThrift.bindForwardedMock(binder(), realThrift);
        bind(new TypeLiteral<Predicate<Method>>() { }).toInstance(predicate);
        AopModule.bindThriftDecorator(
            binder(),
            Matchers.annotatedWith(DecoratedThrift.class),
            new FeatureToggleInterceptor());
      }
    });
    decoratedThrift = injector.getInstance(AnnotatedAuroraAdmin.class);
  }

  @Test
  public void testPredicatePass() throws Exception {
    TaskQuery query = new TaskQuery();
    Response response = new Response()
        .setResponseCode(ResponseCode.OK);

    expect(predicate.apply(EasyMock.anyObject())).andReturn(true);
    expect(realThrift.getTasksStatus(query)).andReturn(response);

    control.replay();

    assertSame(response, decoratedThrift.getTasksStatus(query));
  }

  @Test
  public void testPredicateDeny() throws Exception {
    TaskQuery query = new TaskQuery();
    expect(predicate.apply(EasyMock.anyObject())).andReturn(false);

    control.replay();

    assertSame(ResponseCode.ERROR, decoratedThrift.getTasksStatus(query).getResponseCode());
  }
}

public class Squares {
    public static void main(String[] args) {
        for (int n = 1; n <= 22; n++) {
            System.out.println(n + " " + f(n));
        }
        int[] nonSquares = new int[1_000_000];
        for (int n = 0; n < nonSquares.length; n++) {
            nonSquares[n] = f(n + 1);
        }
        int[] squares = new int[1001];
        for (int n = 0; n < squares.length; n++) {
            squares[n] = n * n;
        }
        for (int n : squares) {
            if (n > nonSquares[nonSquares.length - 1]) {
                break;
            }
            int index = Arrays.binarySearch(nonSquares, n);
            if (index >= 0) {
                System.out.println("Oops, found a square f(" + index + ") = " + n);
            }
        }
    }
    public static int f(int n) {
        return n + (int) Math.floor(0.5 + Math.sqrt(n));
    }
}

