import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.apache.log4j.Logger;
import com.cloud.utils.exception.CloudRuntimeException;

public class DriverLoader {

    private static final Logger LOGGER = Logger.getLogger(DriverLoader.class);
    private static final List<String> LOADED_DRIVERS = new ArrayList<>();
    private static final Map<String, String> DRIVERS = new HashMap<>();

    static {
        DRIVERS.put("mysql", "com.mysql.cj.jdbc.Driver");
        DRIVERS.put("postgresql", "org.postgresql.Driver");
        DRIVERS.put("h2", "org.h2.Driver");
    }

    public static void loadDriver(String dbDriver) {
        if (LOADED_DRIVERS.contains(dbDriver)) {
            LOGGER.info("Driver for " + dbDriver + " is already loaded.");
            return;
        }

        String driverClass = DRIVERS.get(dbDriver);
        if (driverClass == null) {
            String errorMsg = "Unsupported database driver: " + dbDriver;
            LOGGER.error(errorMsg);
            throw new CloudRuntimeException(errorMsg);
        }

        try {
            Class.forName(driverClass).newInstance();
            LOADED_DRIVERS.add(dbDriver);
            LOGGER.info("Successfully loaded driver for " + dbDriver);
        } catch (ClassNotFoundException e) {
            String errorMsg = "Driver class not found: " + driverClass;
            LOGGER.error(errorMsg, e);
            throw new CloudRuntimeException(errorMsg, e);
        } catch (InstantiationException | IllegalAccessException e) {
            String errorMsg = "Failed to instantiate driver: " + driverClass;
            LOGGER.error(errorMsg, e);
            throw new CloudRuntimeException(errorMsg, e);
        }
    }

    public static void main(String[] args) {
        try {
            loadDriver("mysql");
            loadDriver("postgresql");
            loadDriver("h2");
            loadDriver("mysql"); // Should log that it's already loaded
        } catch (Exception e) {
            LOGGER.error("Error loading drivers: " + e.getMessage(), e);
        }
    }
}

