import java.io.File;
import java.util.Scanner;
 
public class LongestStringChallenge {
 
    public static void main(String[] args) throws Exception {
        String lines = "", longest = "";
        try (Scanner sc = new Scanner(new File("lines.txt"))) {
            while(sc.hasNext()) {
                String line = sc.nextLine();
                if (longer(longest, line))
                    lines = longest = line;
                else if (!longer(line, longest))
                    lines = lines.concat("\n").concat(line);
            }
        }
        System.out.println(lines);
    }
 
    static boolean longer(String a, String b) {
        try {
            String dummy = a.substring(b.length());
        } catch (StringIndexOutOfBoundsException e) {
            return true;
        }
        return false;
    }
}

import jdk.vm.ci.code.InstalledCode;
import jdk.vm.ci.meta.MetaAccessProvider;
import jdk.vm.ci.meta.ResolvedJavaMethod;
import org.junit.Test;
import com.oracle.graal.api.directives.GraalDirectives;
import com.oracle.graal.compiler.test.GraalCompilerTest;
import java.lang.reflect.Method;

public class InstalledCodeInvalidationTest extends GraalCompilerTest {

    private static final int RECURSION_DEPTH = 5;

    public static void recurse(int depth) {
        if (depth == 0) {
            GraalDirectives.deoptimizeAndInvalidate();
        } else {
            recurse(depth - 1);
        }
    }

    @Test
    public void testInstalledCodeInvalidation() throws Exception {
        MetaAccessProvider metaAccess = getMetaAccess();
        Method method = getMethod("recurse");
        ResolvedJavaMethod resolvedMethod = metaAccess.lookupJavaMethod(method);
        InstalledCode code = getCode(resolvedMethod);

        try {
            code.executeVarargs(RECURSION_DEPTH);
        } catch (Throwable t) {
            //Check if the exception is graal directive exception.
            if (!t.toString().contains("DeoptimizeException")) {
                  throw t;
            }
        }

        if (code.isAlive()) {
            assertTrue(code.isValid());
        }
        code.invalidate();

        if (GraalDirectives.inCompiledCode()) {
              throw new AssertionError("Code should not be running in compiled code after invalidation.");
        }

        assertFalse(code.isAlive());
    }
}

