import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import tools.devnull.kodo.Specification;

import static org.mockito.Mockito.when;
import static tools.devnull.kodo.Expectation.it;
import static tools.devnull.kodo.Expectation.to;

public class TargetPredicateTest {

    @Mock
    private IncomeMessage messageFromTarget;

    @Mock
    private IncomeMessage messageFromOtherTarget;

    @Mock
    private IncomeMessage messageFromUnknownTarget;

    private Predicates.TargetPredicate<String> predicate;

    @Before
    public void initialize() {
        MockitoAnnotations.openMocks(this);
        when(messageFromTarget.getTargetIdentifier()).thenReturn("validTarget");
        when(messageFromOtherTarget.getTargetIdentifier()).thenReturn("otherTarget");
        when(messageFromUnknownTarget.getTargetIdentifier()).thenReturn(null);

        predicate = Predicates.target("validTarget");
    }

    @Test
    public void test() {
        Specification.given(predicate)
            .expect(it.toAccept(messageFromTarget))
            .expect(it.toReject(messageFromOtherTarget))
            .expect(it.toReject(messageFromUnknownTarget))
            .verify();
    }

    static class IncomeMessage {
        private String targetIdentifier;

        public String getTargetIdentifier() {
            return targetIdentifier;
        }

        public void setTargetIdentifier(String targetIdentifier) {
            this.targetIdentifier = targetIdentifier;
        }
    }

    static class Predicates {
        static class TargetPredicate<T> {
            private final T target;

            public TargetPredicate(T target) {
                this.target = target;
            }

            public boolean test(IncomeMessage message) {
                return target.equals(message.getTargetIdentifier());
            }
        }

        static <T> TargetPredicate<T> target(T target) {
            return new TargetPredicate<>(target);
        }
    }
}

import java.util.HashMap;
import java.util.Map;

public class DefaultCacheLoaderWriterProviderConfiguration {
    private Map<String, CacheLoaderWriter<?, ?>> cacheLoaderWriters = new HashMap<>();

    public DefaultCacheLoaderWriterProviderConfiguration addLoaderFor(String alias, Class<? extends CacheLoaderWriter<?, ?>> clazz, Object... arguments) {
        try {
            CacheLoaderWriter<?, ?> cacheLoaderWriter = clazz.getConstructor(arguments.getClass()).newInstance(arguments);
            cacheLoaderWriters.put(alias, cacheLoaderWriter);
        } catch (Exception e) {
            e.printStackTrace();
        }
        return this;
    }
}

public class AnagramChecker {
    /**
     * Determines if two strings are anagrams of each other.
     */
    public static boolean areAnagrams(String first, String second) {
        String a = first.toLowerCase().replaceAll("\\s", "");
        String b = second.toLowerCase().replaceAll("\\s", "");

        if (a.length() != b.length()) {
            return false;
        }

        int[] counts = new int[26];
        for (int i = 0; i < a.length(); i++) {
            counts[a.charAt(i) - 'a']++;
            counts[b.charAt(i) - 'a']--;
        }

        for (int count : counts) {
            if (count != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        System.out.println(areAnagrams("listen", "silent"));
        System.out.println(areAnagrams("hello", "world"));
    }
}

import java.lang.reflect.Constructor;

import com.amazonaws.AmazonServiceException;

public abstract class AbstractErrorUnmarshaller<T> implements Unmarshaller<AmazonServiceException, T> {

    /**
     * The type of AmazonServiceException that will be instantiated. Subclasses
     * specialized for a specific type of exception can control this through the
     * protected constructor.
     */
    protected final Class<? extends AmazonServiceException> exceptionClass;

    /**
     * Constructs a new error unmarshaller that will unmarshall error responses
     * into AmazonServiceException objects.
     */
    public AbstractErrorUnmarshaller() {
        this(AmazonServiceException.class);
    }

    /**
     * Constructs a new error unmarshaller that will unmarshall error responses
     * into objects of the specified class, extending AmazonServiceException.
     *
     * @param exceptionClass
     *            The subclass of AmazonServiceException which will be
     *            instantiated and populated by this class.
     */
    public AbstractErrorUnmarshaller(Class<? extends AmazonServiceException> exceptionClass) {
        this.exceptionClass = exceptionClass;
    }

    /**
     * Constructs a new exception object of the type specified in this class's
     * constructor and sets the specified error message.
     *
     * @param message
     *            The error message to set in the new exception object.
     *
     * @return A new exception object of the type specified in this class's
     *         constructor and sets the specified error message.
     *
     * @throws Exception
     *             If there are any problems using reflection to invoke the
     *             exception class's constructor.
     */
    protected AmazonServiceException newException(String message) throws Exception {
        Constructor<? extends AmazonServiceException> constructor = exceptionClass.getConstructor(String.class);
        return constructor.newInstance(message);
    }

}

class Program {
    private class Node implements Comparable<Node> {
        int diff, A, B;

        public Node (int d, int a, int b) {
            diff = d;
            A = a;
            B = b;
        }

        @Override
        public int compareTo(Node other) {
            return this.diff - other.diff;
        }
    }

    public int twoCitySchedCost(int[][] costs) {
        List<Node> l = new ArrayList<>();
        int n = costs.length, x = 0, total = 0;

        for (int i = 0; i < n; ++i) {
            l.add(new Node(costs[i][1] - costs[i][0], costs[i][0], costs[i][1]));
        }

        Collections.sort(l);

        for (Node diff: l) {
            if (x < n / 2) {
                total += diff.B;
            } else {
                total += diff.A;
            }
            ++x;
        }

        return total;
    }
}

