import java.util.concurrent.atomic.AtomicLong;

public class UniqueIDGenerator {
   private static final int LENGTH = 15;
   private static final char[] ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789".toCharArray();
   private static final AtomicLong LAST_TIME_MS = new AtomicLong();
   private static final int[] DIGITS = new int[LENGTH];

   static {
      for (int i = 0; i < LENGTH; i++) {
         DIGITS[i] = ALPHABET.length - i - 1;
      }
   }

   public static byte[] getNextID() {
      long currentTimeMS = System.currentTimeMillis();
      long lastTimeMS;
      int[] digits = new int[LENGTH];
      synchronized (UniqueIDGenerator.class) {
         lastTimeMS = LAST_TIME_MS.get();
         if (currentTimeMS == lastTimeMS) {
            try {
               UniqueIDGenerator.class.wait(1);
            } catch (InterruptedException e) {
            }
            currentTimeMS = System.currentTimeMillis();
         }
         if (currentTimeMS < lastTimeMS) {
            throw new RuntimeException("Time is running backwards! Please fix your system clock.");
         }
         LAST_TIME_MS.set(currentTimeMS);
         for (int i = LENGTH - 1; i >= 0; i--) {
            digits[i] = DIGITS[i] + (int) (currentTimeMS % ALPHABET.length);
            if (digits[i] >= ALPHABET.length) {
               digits[i] -= ALPHABET.length;
            }
            currentTimeMS /= ALPHABET.length;
         }
      }
      byte[] id = new byte[LENGTH];
      for (int i = 0; i < LENGTH; i++) {
         id[i] = (byte) ALPHABET[digits[i]];
      }
      return id;
   }
}

import java.util.ArrayList;
 
public class FirstClass{
 
    public interface Function<A,B>{
        B apply(A x);
    }
 
    public static <A,B,C> Function<A, C> compose(
            final Function<B, C> f, final Function<A, B> g) {
        return new Function<A, C>() {
            @Override public C apply(A x) {
                return f.apply(g.apply(x));
            }
        };
    }
 
    public static void main(String[] args){
        ArrayList<Function<Double, Double>> functions =
            new ArrayList<Function<Double,Double>>();
 
        functions.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return Math.cos(x);
                    }
                });
        functions.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return Math.tan(x);
                    }
                });
        functions.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return x * x;
                    }
                });
 
        ArrayList<Function<Double, Double>> inverse = new ArrayList<Function<Double,Double>>();
 
        inverse.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return Math.acos(x);
                    }
                });
        inverse.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return Math.atan(x);
                    }
                });
        inverse.add(
                new Function<Double, Double>(){
                    @Override public Double apply(Double x){
                        return Math.sqrt(x);
                    }
                });
        System.out.println("Compositions:");
        for(int i = 0; i < functions.size(); i++){
            System.out.println(compose(functions.get(i), inverse.get(i)).apply(0.5));
        }
        System.out.println("Hard-coded compositions:");
        System.out.println(Math.cos(Math.acos(0.5)));
        System.out.println(Math.tan(Math.atan(0.5)));
        System.out.println(Math.pow(Math.sqrt(0.5), 2));
    }
}

