public final class BaseAnnotationHandlersTest extends RobolectricTestCase {

    @Override
    public void beforeTest() throws Exception {
        super.beforeTest();
        FragmentAnnotations.setEnabled(true);
    }

    @Test(expected = IllegalAccessException.class)
    public void testInstantiation() throws Exception {
        new BaseAnnotationHandlers();
    }

    @Test(expected = InvocationTargetException.class)
    public void testInstantiationByReflection() throws Exception {
        final Constructor<?> constructor = BaseAnnotationHandlers.class.getDeclaredConstructor();
        constructor.setAccessible(true);
        constructor.newInstance();
    }

    @Test
    public void testObtainFragmentHandler() {
        final FragmentAnnotationHandler handler = BaseAnnotationHandlers.obtainFragmentHandler(
            TestFragment.class
        );
        assertThat(handler, is(not(nullValue())));
        assertThat(
            handler.getClass().getName(),
            CoreMatchers.<CharSequence>is(BaseAnnotationHandlers.FragmentHandler.class.getName())
        );
    }

    @Test
    public void testObtainFragmentHandlerWhenAnnotationsAreDisabled() {
        FragmentAnnotations.setEnabled(false);
        final FragmentAnnotationHandler handler = BaseAnnotationHandlers.obtainFragmentHandler(
            TestFragment.class
        );
        assertThat(handler, is(not(nullValue())));
        assertThat(
            handler.getClass().getName(),
            CoreMatchers.<CharSequence>is(BaseAnnotationHandlers.FragmentHandler.class.getName())
        );
    }

    public static class TestFragment extends Fragment {}
}

