        // Call super to maintain basic functionality
        super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);

        // Set foreground color
        setForeground(unselectedForeground);

        // Set background color based on selection state and custom selection color if provided
        if (isSelected) {
            if (selectionBackground != null) {
                setBackground(selectionBackground);
            } else {
                setBackground(table.getSelectionBackground());
            }
        } else {
            setBackground(unselectedBackground);
        }

        // Delegate cell value setting to custom setValue
