public class LoopIncrementWithinBody {
 
    static final int LIMIT = 42;
 
    static boolean isPrime(long n) {
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        long d = 5;
        while (d * d <= n) {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }
 
    public static void main(String[] args) {
        long i;
        int n;
        for (i = LIMIT, n = 0; n < LIMIT; i++)
            if (isPrime(i)) {
                n++;
                System.out.printf("n = %-2d  %,19d\n", n, i);
                i += i - 1;
            }
    }
}

import java.util.Scanner;

public class Library {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int i = 0; i < t; i++) {
            int w = scanner.nextInt();
            int d = scanner.nextInt();
            int h = scanner.nextInt();
            int a = scanner.nextInt();
            int b = scanner.nextInt();
            int f = scanner.nextInt();
            int g = scanner.nextInt();
            System.out.println(Math.min(
                    findPath1(a, b, f, g, d, w, h),
                    findPath2(a, b, f, g, d, w, h)
            ));
        }
    }

    private static int findPath1(int a, int b, int f, int g, int d, int w, int h) {
        return h + a + b + Math.abs(f - w) + Math.abs(g - d);
    }

    private static int findPath2(int a, int b, int f, int g, int d, int w, int h) {
        return h + Math.abs(f - a) + Math.abs(g - b);
    }
}

class Validator {

    private static final int MAX_LEN = 1 << 8;

    private int sequenceToNum(int[] cells) {
        int res = 0;
        for (int i = 0;i < cells.length;i++) {
            res += cells[i] * (1 << (7 - i));
        }
        return res;
    }

    private int[] generateNewCells(int[] cells) {
        int[] newCells = new int[cells.length];
        newCells[0] = newCells[newCells.length - 1] = 0;
        for (int i = 1;i < cells.length - 1;i++) {
            if ((cells[i - 1] ^ cells [i + 1]) == 0) {
                newCells[i] = 1;
            } else {
                newCells[i] = 0;
            }
        }
        return newCells;
    }

    public int[] prisonAfterNDays(int[] cells, int N) {
        Map<Integer, Integer> numToIndex = new HashMap<>();
        List<int[]> sequence = new ArrayList<>(MAX_LEN);
        int loopStart = -1;
        int[] nowCells = cells;
        for (int i = 0;i < MAX_LEN;i++) {
            int num = sequenceToNum(nowCells);
            if (!numToIndex.containsKey(num)) {
                numToIndex.put(num, i);
                sequence.add(nowCells);
                nowCells = generateNewCells(nowCells);
            } else {
                loopStart = numToIndex.get(num);
                break;
            }
        }
        if (loopStart == -1) {
            throw new IllegalStateException("???");
        }

        int loopSize = sequence.size() - loopStart;
        if (N < loopStart) {
            return sequence.get(N);
        } else {
            return sequence.get(loopStart + ((N - loopStart) % loopSize));
        }
    }
}

