public class Unicode {

  private static final String LC_ASCII = "abcdefghijklmnopqrstuvwxyz";
  private static final String UC_ASCII = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";

  public static void main(String[] args) {
    System.out.println("ASCII lower case:");
    System.out.println(LC_ASCII);
    for (char l = 'a'; l <= 'z'; l++) {
      System.out.print(String.valueOf(l));
    }
    System.out.println();

    System.out.println("\nASCII upper case:");
    System.out.println(UC_ASCII);
    for (char l = 'A'; l <= 'Z'; l++) {
      System.out.print(String.valueOf(l));
    }
    System.out.println();

    System.out.println("\nUnicode version " + Unicode.Version);
    showRange16("Lower case 16-bit code points:", Unicode.Lower.R16);
    showRange32("Lower case 32-bit code points:", Unicode.Lower.R32);
    showRange16("Upper case 16-bit code points:", Unicode.Upper.R16);
    showRange32("Upper case 32-bit code points:", Unicode.Upper.R32);
  }

