    System.out.print("\n" + hdr + "\n");
    System.out.printf("%d ranges:\n", rList.size());
    for (Range16 rng : rList) {
      System.out.printf("%U: ", rng.getLo());
      for (char r = rng.getLo(); r <= rng.getHi(); r += rng.getStride()) {
        System.out.printf("%c", r);
      }
      System.out.println();
    }
  }

  private static void showRange32(String hdr, List<Range32> rList) {
    System.out.print("\n" + hdr + "\n");
    System.out.printf("%d ranges:\n", rList.size());
    for (Range32 rng : rList) {
      System.out.printf("%U: ", rng.getLo());
      for (char r = rng.getLo(); r <= rng.getHi(); r += rng.getStride()) {
        System.out.printf("%c", r);
      }
      System.out.println();
    }
  }

