class TopVotedCandidate {
    int[] winners;
    int[] times;

    public TopVotedCandidate(int[] persons, int[] times) {
        this.times = times;

        int n = persons.length;

        this.winners = new int[n];

        // counter each person's vote
        int[] count = new int[n + 1];

        // initialize
        int max = 1;
        int winner = persons[0];
        winners[0] = winner;
        count[winner]++;

        for (int i = 1; i < n; i++) {
            // find who to vote
            int person = persons[i];

            // count vote for person
            count[person]++;
            if (count[person] >= max) {
                max = count[person];
                // update winner
                winners[i] = person;
                winner = person;
            } else {
                winners[i] = winner;
            }
        }
    }

    public int q(int t) {
        int ind = findMostRecentIndex(t);
        // System.out.println("time t " + t + " ind " + ind + " winner[ind] " + winners[ind]);
        return winners[ind];
    }

    private int findMostRecentIndex(int t) {
        int i = 0;
        while (i < times.length - 1 && times[i + 1] <= t) {
            i++;
        }
        return i;
    }
}

