import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class FFR {
    private static List<Integer> r = Arrays.asList(null, 1);
    private static List<Integer> s = Arrays.asList(null, 2);

    public static int ffr(int n) {
        if (n < 1 ||!(n instanceof Integer)) {
            throw new IllegalArgumentException("n must be an int >= 1");
        }
        try {
            return r.get(n);
        } catch (IndexOutOfBoundsException e) {
            int ffr_n_1 = ffr(n - 1);
            int lastr = r.get(r.size() - 1);
            // extend s up to, and one past, last r
            s.addAll(IntStream.range(s.get(s.size() - 1) + 1, lastr).boxed().collect(Collectors.toList()));
            if (s.get(s.size() - 1) < lastr) {
                s.add(lastr + 1);
            }
            // access s[n-1] temporarily extending s if necessary
            int len_s = s.size();
            int ffs_n_1 = s.get(n - 1);
            if (len_s > n) {
                ffs_n_1 = (n - len_s) + s.get(s.size() - 1);
            }
            int ans = ffr_n_1 + ffs_n_1;
            r.add(ans);
            return ans;
        }
    }

    public static int ffs(int n) {
        if (n < 1 ||!(n instanceof Integer)) {
            throw new IllegalArgumentException("n must be an int >= 1");
        }
        try {
            return s.get(n);
        } catch (IndexOutOfBoundsException e) {
            for (int i = r.size(); i < n + 2; i++) {
                ffr(i);
                if (s.size() > n) {
                    return s.get(n);
                }
            }
            throw new RuntimeException("Whoops!");
        }
    }

    public static void main(String[] args) {
        List<Integer> first10 = IntStream.range(1, 11).map(FFR::ffr).boxed().collect(Collectors.toList());
        assert first10.equals(Arrays.asList(1, 3, 7, 12, 18, 26, 35, 45, 56, 69));
        System.out.println("ffr(n) for n = [1..10] is " + first10);
        //
        int[] bin = new int[1001];
        for (int i = 40; i > 0; i--) {
            bin[ffr(i)]++;
        }
        for (int i = 960; i > 0; i--) {
            bin[ffs(i)]++;
        }
        if (Arrays.stream(bin).allMatch(b -> b == 1)) {
            System.out.println("All Integers 1..1000 found OK");
        } else {
            System.out.println("All Integers 1..1000 NOT found only once: ERROR");
        }
    }
}

import org.apache.commons.lang.StringUtils;

public class GroupMapper {

    public Group map(DbGroup entity, Group template) {
        Group model = template != null ? template : new Group();
        if (entity != null) {
            if (entity.getId() != null) {
                model.setId(GuidUtils.encode(entity.getId()));
            }
            if (StringUtils.isNotBlank(entity.getName())) {
                model.setName(entity.getName());
            }
            if (entity.getDomain() != null) {
                model.setDomain(mapDomain(entity.getDomain()));
            }
        }
        return model;
    }

    public Group map(DirectoryGroup directoryGroup, Group template) {
        Group model = template != null ? template : new Group();
        if (directoryGroup != null) {
            if (directoryGroup.getEntryId() != null) {
                model.setId(DirectoryEntryIdUtils.encode(directoryGroup.getEntryId()));
            }
            if (StringUtils.isNotBlank(directoryGroup.getName())) {
                model.setName(directoryGroup.getName());
            }
            if (directoryGroup.getDomain() != null) {
                model.setDomain(mapDomain(directoryGroup.getDomain()));
            }
        }
        return model;
    }

    public DbGroup map(Group model, DbGroup template) {
        DbGroup entity = template != null ? template : new DbGroup();
        if (model != null) {
            if (StringUtils.isNotBlank(model.getId())) {
                entity.setId(GuidUtils.decode(model.getId()));
            }
            if (StringUtils.isNotBlank(model.getName())) {
                entity.setName(model.getName());
            }
            if (model.getDomain() != null) {
                entity.setDomain(mapDomain(model.getDomain()));
            }
        }
        return entity;
    }

    private Domain mapDomain(Domain domain) {
        if (domain == null) {
            return null;
        }
        Domain dom = new Domain();
        if (StringUtils.isNotBlank(domain.getId())) {
            dom.setId(domain.getId());
        }
        if (StringUtils.isNotBlank(domain.getName())) {
            dom.setName(domain.getName());
        }
        return dom;
    }
}

import com.example.app.service.ICycleService;
import com.example.app.entity.Cycle;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.ejb.EJB;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;

@Path("/cycles")
public class CycleResource {

    @EJB
    private ICycleService cycleService;

    private static final Logger LOGGER = Logger.getLogger(CycleResource.class.getName());

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Cycle createCycle(Cycle cycle) {
        try {
            return cycleService.saveOrUpdateCycle(cycle);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error creating cycle", e);
            return null;
        }
    }

    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public List<Cycle> getAllCycle() {
        try {
            return cycleService.getAllCycles();
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error getting all cycles", e);
            return null;
        }
    }

    @GET
    @Path("/{id}")
    @Produces(MediaType.APPLICATION_JSON)
    public Cycle getCycle(@PathParam("id") Long id) {
        try {
            return cycleService.findCycleById(id);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error getting cycle with id: " + id, e);
            return null;
        }
    }

    @PUT
    @Path("/{id}")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Cycle updateCycle(@PathParam("id") Long id, Cycle cycle) {
        try {
            cycle.setId(id);
            return cycleService.saveOrUpdateCycle(cycle);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error updating cycle with id: " + id, e);
            return null;
        }
    }

    @DELETE
    @Path("/{id}")
    public void deleteCycle(@PathParam("id") Long id) {
        try {
            cycleService.deleteCycle(id);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error deleting cycle with id: " + id, e);
        }
    }
}

