import jdk.vm.ci.code.InstalledCode;
import jdk.vm.ci.hotspot.CompilerToVMHelper;
import jdk.vm.ci.meta.ResolvedJavaMethod;
import org.graalvm.compiler.api.directives.GraalDirectives;
import org.graalvm.compiler.core.test.GraalCompilerTest;
import org.junit.Assert;
import org.junit.Test;

public class InstalledCodeInvalidationTest extends GraalCompilerTest {

    private static final int RECURSION_DEPTH = 10;

    @Test
    public void testInstalledCodeInvalidation() throws Exception {
        ResolvedJavaMethod method = getResolvedJavaMethod("recurse");
        InstalledCode code = getCode(method);
        Assert.assertNotNull(code);

        // Initial invocation to compile the method
        recurse(0);

        // Invoke again to ensure we are in compiled state
        recurse(0);

        // Check if the code is still valid
        Assert.assertTrue(code.isValid());

        // Invoke with a specific depth to trigger deoptimization and invalidation
        recurse(RECURSION_DEPTH);

        // Check if the code is invalidated
        Assert.assertFalse(code.isValid());
    }

    private void recurse(int depth) {
        if (depth == RECURSION_DEPTH) {
            // Trigger deoptimization and invalidation
            GraalDirectives.deoptimizeAndInvalidate();
        } else {
            // Recursive call to create multiple stack frames
            recurse(depth + 1);
        }
    }

    private InstalledCode getCode(ResolvedJavaMethod method) {
        try {
            return CompilerToVMHelper.getSpeculatedCode(method);
        } catch (Exception e) {
            throw new RuntimeException("Failed to get installed code", e);
        }
    }
}

