public class PancakeSort {
    public static void pancakeSort(int[] a) {
        // Returns the index of the highest number in the range 0 until n.
        int indexOfMax(int n) {
            int maxIndex = 0;
            for (int i = 1; i < n; i++) {
                if (a[i] > a[maxIndex]) {
                    maxIndex = i;
                }
            }
            return maxIndex;
        }

        // Flips the elements in the range 0.. n.
        void flip(int index) {
            for (int i = 0; i < (index + 1) / 2; i++) {
                int temp = a[i];
                a[i] = a[index - i];
                a[index - i] = temp;
            }
        }

        for (int n = a.length; n > 1; n--) {  // successively reduce size of array by 1
            int index = indexOfMax(n); // find index of largest
            if (index!= n - 1) {     // if it's not already at the end
                if (index > 0) {      // if it's not already at the beginning
                    flip(index);       // move largest to beginning
                    System.out.println(Arrays.toString(a) + " after flipping first " + (index + 1));
                }
                flip(n - 1);           // move largest to end
                System.out.println(Arrays.toString(a) + " after flipping first " + n);
            }
        }
    }

    public static void main(String[] args) {
        int[] a = {7, 6, 9, 2, 4, 8, 1, 3, 5};
        System.out.println(Arrays.toString(a) + " initially");
        pancakeSort(a);
    }
}

