import java.util.Scanner;

public class MatchingNo {

    public static void main(String[] args) {

        Scanner scan=new Scanner(System.in);

        int t=scan.nextInt();

        while(t-->0){

            int n=scan.nextInt();

            if((n&1)==0){

                System.out.println("No");

                continue;

            }

            else{

                System.out.println("Yes");

            }

            int j=2*n;

            for(int i=1;i<=(n+1)/2;i++){

                System.out.println(j+" "+i);

                j-=2;

            }

            j=2*n-1;

            for(int i=(n+3)/2;i<=n;i++){

                System.out.println(i+" "+j);

                j-=2;

            }

        }

    }

}

import javax.sound.midi.Instrument;
import javax.sound.midi.MidiSystem;
import javax.sound.midi.Soundbank;
import javax.sound.midi.Synthesizer;

public class SynthInstrumentTest {

    public static void main(String[] args) {
        Synthesizer synth = null;
        try {
            // Initialize synthesizer and open it
            synth = MidiSystem.getSynthesizer();
            synth.open();

            // Retrieve the default soundbank
            Soundbank defaultSoundbank = synth.getDefaultSoundbank();
            assertTrue("Default soundbank should not be null", defaultSoundbank != null);

            Instrument[] soundbankInstruments = defaultSoundbank.getInstruments();
            int instrumentCount = soundbankInstruments.length;
            System.out.println("Initial instrument count in soundbank: " + instrumentCount);

            // Unload all instruments from the synthesizer using the soundbank
            for (Instrument instr : soundbankInstruments) {
                // Assume unloadInstrument is supported by the synthesizer
                synth.unloadInstrument(instr);
            }

            // Verify that no instruments remain loaded in the synthesizer
            Instrument[] loadedAfterUnload = synth.getLoadedInstruments();
            assertEquals("No instruments should be loaded after unload", 0, loadedAfterUnload.length);
            System.out.println("All instruments successfully unloaded.");

            // Load all instruments back into the synthesizer
            for (Instrument instr : soundbankInstruments) {
                synth.loadInstrument(instr);
            }

            // Verify that instruments are loaded (should match the original soundbank count)
            Instrument[] loadedAfterLoad = synth.getLoadedInstruments();
            assertEquals("Instruments loaded should match the soundbank count", instrumentCount, loadedAfterLoad.length);
            System.out.println("All instruments successfully reloaded.");

            // Unload the instruments once again
            for (Instrument instr : soundbankInstruments) {
                synth.unloadInstrument(instr);
            }

            // Confirm that the synthesizer is cleared of loaded instruments
            Instrument[] loadedAfterFinalUnload = synth.getLoadedInstruments();
            assertEquals("Synthesizer should have no instruments after final unload", 0, loadedAfterFinalUnload.length);
            System.out.println("Final unload successful, no instruments loaded.");

        } catch (Exception e) {
            e.printStackTrace();

