        setPreferenceStore(SadlPreferences.getPreferenceStore());
    }

    @Override
    protected void createFieldEditors() {
        // Add a header label to the preference page
        addField(new LabelFieldEditor("header",
            "Configure your specialized language settings below:", getFieldEditorParent()));

        // Base URI text input field
        addField(new StringFieldEditor(SadlPreferences.BASE_URI, "Base URI:", getFieldEditorParent()));

        // Radio group for selecting the model format
        String[][] formatOptions = new String[][] {
            { "XML", "xml" },
            { "JSON", "json" },
            { "YAML", "yaml" }
        };
        addField(new RadioGroupFieldEditor(SadlPreferences.MODEL_FORMAT,
            "Select model format:", formatOptions.length, formatOptions, getFieldEditorParent(), true));

