    public static SparseBlock createSparseBlock(int rlen) {
        return createSparseBlock(MatrixBlock.DEFAULT_SPARSEBLOCK, rlen);
    }

    public static SparseBlock createSparseBlock(SparseBlock.Type type, int rlen) {
        switch (type) {
            case MCSR:
                return new SparseBlockMCSR(rlen);
            case CSR:
                return new SparseBlockCSR(rlen);
            case COO:
                return new SparseBlockCOO(rlen);
            default:
                throw new RuntimeException("Unknown sparse block type: " + type);
        }
    }

    public static SparseBlock copySparseBlock(SparseBlock.Type type, SparseBlock sblock, boolean forceCopy) {
        if (!forceCopy && isSparseBlockType(sblock, type))
            return sblock;

        switch (type) {
            case MCSR:
                return new SparseBlockMCSR(sblock);
            case CSR:
                return new SparseBlockCSR(sblock);
            case COO:
                return new SparseBlockCOO(sblock);
            default:
                throw new RuntimeException("Unknown sparse block type: " + type);
        }
    }

    public static boolean isSparseBlockType(SparseBlock sblock, SparseBlock.Type type) {
        return (sblock instanceof SparseBlockMCSR && type == SparseBlock.Type.MCSR)
                || (sblock instanceof SparseBlockCSR && type == SparseBlock.Type.CSR)
                || (sblock instanceof SparseBlockCOO && type == SparseBlock.Type.COO);
    }

    public static SparseBlock.Type getSparseBlockType(SparseBlock sblock) {
        if (sblock instanceof SparseBlockMCSR)
            return SparseBlock.Type.MCSR;
        else if (sblock instanceof SparseBlockCSR)
            return SparseBlock.Type.CSR;
        else if (sblock instanceof SparseBlockCOO)
            return SparseBlock.Type.COO;
        else
            return null;
    }

