public int[][] addIntegersInSubmatrix(int n, int[][] queries) {
    int[][] mat = new int[n][n];

    // Initialize matrix with all zeros
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            mat[i][j] = 0;
        }
    }

    // Process each query
    for (int[] query : queries) {
        int row1 = query[0];
        int col1 = query[1];
        int row2 = query[2];
        int col2 = query[3];

        for (int i = row1; i <= row2; i++) {
            for (int j = col1; j <= col2; j++) {
                mat[i][j]++;
            }
        }
    }

    return mat;
}

