import java.util.List;

import org.apache.isis.applib.annotation.Action;
import org.apache.isis.applib.annotation.DomainService;
import org.apache.isis.applib.annotation.MemberOrder;
import org.apache.isis.applib.annotation.Named;
import org.apache.isis.applib.annotation.Prototype;
import org.apache.isis.applib.fixturescripts.FixtureResult;
import org.apache.isis.applib.fixturescripts.FixtureScript;
import org.apache.isis.applib.fixturescripts.FixtureScripts;

@DomainService
@Named("Prototyping")
public class SimpleObjectsFixturesService {

    private final FixtureScripts fixtureScripts;

    public SimpleObjectsFixturesService(FixtureScripts fixtureScripts) {
        this.fixtureScripts = fixtureScripts;
    }

    @Prototype
    @MemberOrder(sequence = "1")
    public List<FixtureResult> runFixtureScript(
            @Named("Fixture Script") FixtureScript fixtureScript,
            @Named("Parameters") String parameters) {
        return fixtureScripts.runFixtureScript(fixtureScript, parameters);
    }

    public FixtureScript default0RunFixtureScript() {
        return findFixtureScriptFor(SimpleObjectsFixture.class);
    }

    public List<FixtureScript> choices0RunFixtureScript() {
        return fixtureScripts.getFixtureScriptList("fixture.simple");
    }

    @Prototype
    @MemberOrder(sequence = "2")
    public <T> T installFixturesAndReturnFirst(final FixtureScript fixtureScript) {
        final List<FixtureResult> fixtureResults = fixtureScripts.run(fixtureScript);
        if (fixtureResults.isEmpty()) {
            return null;
        }
        return (T) fixtureResults.get(0).getObject();
    }

    @Prototype
    @MemberOrder(sequence = "3")
    public <T> T instalarFixturesAlumnos() {
        return installFixturesAndReturnFirst(findFixtureScriptFor(AlumnosFixture.class));
    }

    @Prototype
    @MemberOrder(sequence = "4")
    public <T> T instalarFixturesCursos() {
        return installFixturesAndReturnFirst(findFixtureScriptFor(CursosFixture.class));
    }

    protected FixtureScript findFixtureScriptFor(final Class<? extends FixtureScript> fixtureScriptClass) {
        final List<FixtureScript> fixtureScriptList = fixtureScripts.getFixtureScriptList("fixture.simple");
        for (FixtureScript fixtureScript : fixtureScriptList) {
            if (fixtureScriptClass.isAssignableFrom(fixtureScript.getClass())) {
                return fixtureScript;
            }
        }
        return null;
    }
}

