import java.util.Deque;
import java.util.LinkedList;

/**
 * @title: 魔术迭代
 * @date 2022-04-10 10:34
 * @description: TODO
 */
public class 魔术迭代 {
    public static void main(String[] args) {
        int []numbs ={0,1,2};
        String[] ops = {"C", "D", "+"};
        new 魔术迭代().calPoints(ops);
    }

    public int calPoints(String[] ops) {
        Deque<Integer> stack = new LinkedList<>();
        for (String i : ops) {
            switch (i) {
                case "C": {
                    stack.pollLast();
                    break;
                }
                case "D": {
                    stack.addLast(stack.peekLast() * 2);
                    break;
                }
                case "+": {
                    Integer s1 = stack.pollLast();
                    Integer s2 = stack.pollLast();
                    stack.addLast(s2);
                    stack.addLast(s1);
                    stack.addLast(s1 + s2);
                    break;
                }
                default: {
                    stack.addLast(Integer.parseInt(i));
                    break;
                }
            }
        }
        return stack.stream().mapToInt(x -> x).sum();
    }
