import com.google.common.base.Charsets;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;
import javax.annotation.Nonnull;

public class HttpStoreRevisions implements Revisions {
    private final HttpStore store;

    public HttpStoreRevisions(@Nonnull HttpStore store) {
        if (store == null) {
            throw new IllegalArgumentException("HttpStore cannot be null");
        }
        this.store = store;
    }

    @Nonnull
    @Override
    public String getHead() {
        try {
            URL url = new URL(store.getBaseUrl() + "/head");
            URLConnection connection = url.openConnection();
            connection.setRequestProperty("Accept-Charset", Charsets.UTF_8.name());

            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(connection.getInputStream(), Charsets.UTF_8))) {
                String revisionId = reader.readLine();
                if (revisionId == null || revisionId.isEmpty()) {
                    throw new IllegalStateException("Empty revision ID received from store");
                }
                return revisionId;
            }
        } catch (IOException e) {
            throw new RuntimeException("Failed to retrieve head revision", e);
        }
    }

    @Override
    public void setHead(@Nonnull String revisionId) {
        throw new UnsupportedOperationException("setHead is not implemented");
    }

    @Override
    public void setHead(@Nonnull String revisionId, boolean force) {
        throw new UnsupportedOperationException("setHead is not implemented");
    }

    @Override
    public boolean isHead(@Nonnull String revisionId) {
        return getHead().equals(revisionId);
    }

    @Override
    public void close() {
        // No resources to close
    }
}

