public class Helper {
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        System.out.println("Loan amount: ");
        double loanAmount = in.nextDouble();

        System.out.println("Number of years: ");
        int numYears = in.nextInt();
        System.out.println("\nInterest rate - Monthly Payment - Total Payment");
        for (double i = 5.0; i <= 8.0; i += 0.125) {

            // Obtain monthly interest rate
            double monthlyInterestRate = i / 1200; //As decimal number
            // Calculate payment
            double monthlyPayment = loanAmount * monthlyInterestRate / (1
                    - 1 / Math.pow(1 + monthlyInterestRate, numYears * 12));
            double totalPayment = monthlyPayment * numYears * 12;

            System.out.printf("\t%.3f", i);
            System.out.print("%");
            System.out.printf("\t\t\t%.2f", monthlyPayment);
            System.out.printf("\t\t\t%.2f", totalPayment);
            System.out.println();

        }

        in.close();

    }
}

public V action(Callable<V> callable) throws Exception {
    int attempts = 0;
    while (attempts < maxAttempts) {
        try {
            return callable.call();
        } catch (Exception e) {
            if (attempts >= maxAttempts - 1) {
                throw e;
            }
            Thread.sleep(retryDelay);
        }
        attempts++;
    }
    throw new IllegalStateException("Unexpected state: should have returned or thrown by now");
}

public static BufferedImage ByteBufferImage( byte[] data, int width, int height ) {
        int[] bandoffsets = {0, 1, 2, 3};
        DataBufferByte dbb = new DataBufferByte(data, data.length);
        WritableRaster wr = Raster.createInterleavedRaster(dbb, width, height, width * 4, 4, bandoffsets, null);
        int[] bitfield = {8, 8, 8, 8};
        ColorSpace cs = ColorSpace.getInstance(ColorSpace.CS_sRGB);
        ColorModel cm = new ComponentColorModel(cs, bitfield, true, false, Transparency.TRANSLUCENT, DataBuffer.TYPE_BYTE);
        return new BufferedImage(cm, wr, false, null);
    }

protected String toHexString(int i) {
    // Convert the integer to a hex string
    String hexString = Integer.toHexString(i);
    // Ensure the hex string is 16 digits long
    while (hexString.length() < 16) {
        hexString = "0" + hexString;
    }
    return hexString;
}

