import java.util.Random;
import java.util.Scanner;
import java.util.Date;
import java.awt.Color;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Line2D;
import java.awt.geom.Point2D;
import javax.swing.JFrame;
import javax.swing.JPanel;
 
public class PolygonChaos extends JPanel {
 
    private static final long serialVersionUID = 1L;
    private static final int WINDOW_SIDE = 500;
    private static final double PI = Math.PI;
    private static final int NUM_SIDES = 3;
    private static final double SIDE_LENGTH = 100;
    private static final int NUM_ITERATIONS = 10000;
    private static final int SEED_X = WINDOW_SIDE/2;
    private static final int SEED_Y = WINDOW_SIDE/2;
 
    private static double[][] vertices;
    private static double sumX = 0;
    private static double sumY = 0;
    private static double seedX;
    private static double seedY;
    private static Random random;
 
    public PolygonChaos() {
        random = new Random();
        vertices = new double[NUM_SIDES][2];
 
        for(int i=0;i<NUM_SIDES;i++){
            vertices[i][0] = SEED_X + SIDE_LENGTH*Math.cos(i*2*PI/NUM_SIDES);
            vertices[i][1] = SEED_Y + SIDE_LENGTH*Math.sin(i*2*PI/NUM_SIDES);
            sumX+= vertices[i][0];
            sumY+= vertices[i][1];
        }
 
        seedX = sumX/NUM_SIDES;
        seedY = sumY/NUM_SIDES;
    }
 
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        Graphics2D g2 = (Graphics2D) g;
 
        for(int i=0;i<NUM_SIDES;i++){
            g2.draw(new Line2D.Double(vertices[i][0],vertices[i][1],vertices[(i+1)%NUM_SIDES][0],vertices[(i+1)%NUM_SIDES][1]));
        }
 
        g2.draw(new Line2D.Double(seedX,seedY,seedX,seedY));
 
        for(int i=0;i<NUM_ITERATIONS;i++){
            int choice = random.nextInt(NUM_SIDES);
 
            seedX = (seedX + (NUM_SIDES-2)*vertices[choice][0])/(NUM_SIDES-1);
            seedY = (seedY + (NUM_SIDES-2)*vertices[choice][1])/(NUM_SIDES-1);
 
            g2.draw(new Line2D.Double(seedX,seedY,seedX,seedY));
        }
    }
 
    public static void main(String[] args) {
        JFrame frame = new JFrame("Polygon Chaos");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(WINDOW_SIDE,WINDOW_SIDE);
        frame.add(new PolygonChaos());
        frame.setVisible(true);
    }
}

