import fm.ua.ikysil.smap.VendorInfo;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public class VendorInfoBuilder implements Builder {
    private static final String SECTION_NAME = "VENDOR";
    private final List<String> vendorLines = new ArrayList<>();

    @Override
    public String getSectionName() {
        return SECTION_NAME;
    }

    @Override
    public boolean canParse(String line) {
        return line != null && line.trim().startsWith(SECTION_NAME);
    }

    @Override
    public void processLine(String line) {
        if (line != null && !line.trim().equals(SECTION_NAME)) {
            vendorLines.add(line.trim());
        }
    }

    @Override
    public VendorInfo build(State state) {
        if (vendorLines.isEmpty()) {
            return null;
        }

        VendorInfo vendorInfo = new VendorInfo();
        for (String vendorLine : vendorLines) {
            processVendorLine(vendorInfo, vendorLine);
        }

        if (state.getCurrentStratum() != null) {
            state.getCurrentStratum().getVendorInfoList().add(vendorInfo);
        }

        return vendorInfo;
    }

    private void processVendorLine(VendorInfo vendorInfo, String line) {
        if (line == null || line.isEmpty()) {
            return;
        }

        String[] parts = line.split("\\s+", 2);
        if (parts.length < 2) {
            return;
        }

        String key = parts[0].trim();
        String value = parts[1].trim();

        switch (key.toUpperCase()) {
            case "NAME":
                vendorInfo.setName(value);
                break;
            case "URL":
                vendorInfo.setUrl(value);
                break;
            case "EMAIL":
                vendorInfo.setEmail(value);
                break;
            default:
                vendorInfo.getAdditionalInfo().put(key, value);
                break;
        }
    }

    @Override
    public void reset() {
        vendorLines.clear();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        VendorInfoBuilder that = (VendorInfoBuilder) o;
        return Objects.equals(vendorLines, that.vendorLines);
    }

    @Override
    public int hashCode() {
        return Objects.hash(vendorLines);
    }

    @Override
    public String toString() {
        return "VendorInfoBuilder{" +
                "vendorLines=" + vendorLines +
                '}';
    }
}

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.zip.ZipEntry;
import java.util.zip.ZipFile;

import org.junit.Rule;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.junit.rules.TemporaryFolder;

import org.apache.geode.test.junit.rules.GfshShellConnectionRule;

public class ExportLogsStatsOverHttpDUnitTest {

  @Rule
  public TemporaryFolder tempFolder = new TemporaryFolder();

  @Rule
  public GfshShellConnectionRule connector = new GfshShellConnectionRule();

  private int httpPort = 8080;

  @Test
  public void testExportWithDir() throws Exception {
    connector.connectIfNeeded(httpPort);
    File dir = tempFolder.newFolder("dir");
    String command = "export logs --dir=" + dir.getAbsolutePath();
    connector.executeCommand(command);
    String commandResult = connector.getGfshOutput();

    String zipPath = getZipPathFromCommandResult(commandResult);

    assertThat(new File(zipPath).exists()).isTrue();

    Set<String> actualZipEntries = getZipEntries(zipPath);
    Set<String> expectedZipEntries = getExpectedZipEntries();
        assertThat(actualZipEntries).containsAll(expectedZipEntries);

    // Check that the zip file is also removed on the server-side
    String locatorZipPath = zipPath.replace(dir.getAbsolutePath(), ".");
    command = "sh ls " + locatorZipPath;
    connector.executeCommand(command);
    assertThat(connector.getGfshOutput()).contains("No such file or directory");
  }

    private Set<String> getExpectedZipEntries() {
        return Set.of("locator.log", "stats.gfs");
    }

    private Set<String> getZipEntries(String zipPath) throws IOException {
        try (ZipFile zipFile = new ZipFile(zipPath)) {
            return zipFile.stream()
              .map(ZipEntry::getName)
              .collect(Collectors.toSet());
    }
  }

  String getZipPathFromCommandResult(String commandResult) {
    String[] lines = commandResult.split(System.lineSeparator());
    String filePath = null;
    for (String line : lines) {
      if (line.contains("Logs exported to")) {
        filePath = line.substring(line.indexOf("[") + 1, line.indexOf("]"));
        break;
      }
    }
    return filePath;
  }
}

public static String stripBlankLines(String text) {
        if (text == null) {
            return null;
        }
        try {
            StringBuffer output = new StringBuffer();
            BufferedReader in = new BufferedReader(new StringReader(text));
            boolean doneOneLine = false;
            while (true) {
                String line = in.readLine();
                if (line == null) {
                    break;
                }
                if (line.trim().length() > 0) {
                    output.append(line);
                    output.append('\n');
                    doneOneLine = true;
                }
            }
            if (!doneOneLine) {
                output.append('\n');
            }
            return output.toString();
        } catch (IOException e) {
            throw new IllegalArgumentException(e);
        }
    }

import java.util.Vector;
import java.util.Iterator;
 
class Hofstadter
{
  public static int F(int n) {
    if ( n == 0 ) return 1;
    return n - M(F(n-1));
  }
  public static int M(int n) {
    if ( n == 0 ) return 0;
    return n - F(M(n-1));
  }
}
 
