      ra.add(new Integer(Hofstadter.F(i)));
      rb.add(new Integer(Hofstadter.M(i)));
    }
    for(Iterator it = ra.iterator(); it.hasNext(); ) {
      System.out.print(it.next() + " ");
    }
    System.out.println();
    for(Iterator it = rb.iterator(); it.hasNext(); ) {
      System.out.print(it.next() + " ");
    }
    System.out.println();
  }
}

public class Queue {
    public static void main(String[] args) {
        for (int i = 10000; i <= 100000; i += 10000) {
            double pi = 0;
            for (int j = 0; j < i; j++) {
                int sign = j % 2 == 0 ? 1 : -1;
                double term = sign * (1.0 / (2 * j + 1));
                pi += term;
            }
            pi *= 4;
            System.out.println("pi for i = " + i + ": " + pi);
        }
    }
}

import java.util.Scanner;

public class Order {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        while (T-- > 0) {
            solve(scanner);
        }
    }

    public static void solve(Scanner scanner) {
        int n = scanner.nextInt();
        String s = scanner.next();
        int i = 0, j = n - 1;
        while (i < j) {
            if (s.charAt(i)!= s.charAt(j)) {
                i++;
                j--;
                n -= 2;
            } else {
                break;
            }
        }
        System.out.println(n);
    }
}

