public static double shoelace(String inputFile) {
    int i, numPoints;
    double leftSum = 0, rightSum = 0;
    List<Point> pointSet = new ArrayList<Point>();
    try {
        BufferedReader br = new BufferedReader(new FileReader(inputFile));
        numPoints = Integer.parseInt(br.readLine());
        for (i = 0; i < numPoints; i++) {
            String[] line = br.readLine().split(" ");
            pointSet.add(new Point(Double.parseDouble(line[0]), Double.parseDouble(line[1])));
        }
        br.close();
    } catch (IOException e) {
        e.printStackTrace();
    }
    pointSet.add(pointSet.get(0));
    for (i = 0; i < numPoints; i++) {
        leftSum += pointSet.get(i).x * pointSet.get(i + 1).y;
        rightSum += pointSet.get(i + 1).x * pointSet.get(i).y;
    }
    return 0.5 * Math.abs(leftSum - rightSum);
}
 
static class Point {
    double x, y;
    public Point(double x, double y) {
        this.x = x;
        this.y = y;
    }
}
}

