public class HbaseSampledCpuLoadDaoV2 implements SampledCpuLoadDao {

    private final HbaseAgentStatDaoOperationsV2 operations;

    private final CpuLoadDecoder cpuLoadDecoder;

    private final CpuLoadSampler cpuLoadSampler;

    public HbaseSampledCpuLoadDaoV2(HbaseAgentStatDaoOperationsV2 operations, CpuLoadDecoder cpuLoadDecoder, CpuLoadSampler cpuLoadSampler) {
        this.operations = Objects.requireNonNull(operations, "operations");
        this.cpuLoadDecoder = Objects.requireNonNull(cpuLoadDecoder, "cpuLoadDecoder");
        this.cpuLoadSampler = Objects.requireNonNull(cpuLoadSampler, "cpuLoadSampler");
    }

    @Override
    public List<SampledCpuLoad> getSampledAgentStatList(String agentId, TimeWindow timeWindow) {
        long scanFrom = timeWindow.getWindowRange().getFrom();
        long scanTo = timeWindow.getWindowRange().getTo() + timeWindow.getWindowSlotSize();
        Range range = Range.newRange(scanFrom, scanTo);
        AgentStatMapperV2<CpuLoadBo> mapper = createRowMapper(agentId, range);
        SampledAgentStatResultExtractor<CpuLoadBo, SampledCpuLoad> resultExtractor = new SampledAgentStatResultExtractor<>(timeWindow, mapper, cpuLoadSampler);
        return operations.getSampledAgentStatList(cpuLoadDecoder, agentId, range, resultExtractor);
    }

    private AgentStatMapperV2<CpuLoadBo> createRowMapper(String agentId, Range range) {
        return new AgentStatMapperV2<>(cpuLoadDecoder, agentId, range);
    }
}

import java.io.IOException;
import java.io.InputStreamReader;
import static java.lang.Math.min;

public class Builder {
    public static void main(String[]args) throws IOException {
        InputStreamReader ir = new InputStreamReader(System.in);
        BufferedReader br = new BufferedReader(ir);

        int test = Integer.parseInt(br.readLine());

        for (int i = 0; i < test ; i++) {
            String[] firstInputs = br.readLine().split(" ");
            int x = Integer.parseInt(firstInputs[0]);
            int y = Integer.parseInt(firstInputs[1]);

            String[] seconInputs = br.readLine().split(" ");
            int a = Integer.parseInt(seconInputs[0]);
            int b = Integer.parseInt(seconInputs[1]);

            int result = min(x,y)*b + Math.abs(x-y)*a;
            System.out.println(result);
        }
    }
}

import org.jboss.aesh.edit.actions.Action;
import org.jboss.aesh.edit.actions.Operation;
import org.jboss.aesh.terminal.Key;

/**
 */
public class KeyOperation {

    private final Key key;
    private final Operation operation;
    private Action workingMode = Action.NO_ACTION;

    public KeyOperation(Key key, Operation operation) {
        this.key = key;
        this.operation = operation;
    }

    public KeyOperation(Key key, Operation operation, Action workingMode) {
        this.key = key;
        this.operation = operation;
        this.workingMode = workingMode;
    }

    public Key getKey() {
        return key;
    }

    public int[] getKeyValues() {
        return key.getKeyValues();
    }

    public int getFirstValue() {
        return key.getFirstValue();
    }

    public Operation getOperation() {
        return operation;
    }

    public Action getWorkingMode() {
        return workingMode;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof KeyOperation)) return false;

        KeyOperation that = (KeyOperation) o;

        return key == that.key &&
                operation == that.operation &&
                workingMode == that.workingMode;
    }

    @Override
    public int hashCode() {
        int result = key.hashCode();
        result = 31 * result + operation.hashCode();
        result = 31 * result + workingMode.hashCode();
        return result;
    }

    @Override
    public String toString() {
        return "KeyOperation{" +
                "key=" + key +
                ", operation=" + operation +
                ", workingMode=" + workingMode +
                '}';
    }
}

import javafx.application.Application;
import javafx.geometry.Point2D;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.stage.Stage;

import java.util.Random;

public class TwoCircles extends Application {

    private final int RADIUS = 15;
    private final int WINDOW_WIDTH = 500;
    private final int WINDOW_HEIGHT = 500;

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create a Group to hold the circles and line
        Group root = new Group();

        // Create the two circles with random centers
        Random random = new Random();
        Circle circle1 = new Circle(random.nextInt(WINDOW_WIDTH), random.nextInt(WINDOW_HEIGHT), RADIUS, Color.RED);
        Circle circle2 = new Circle(random.nextInt(WINDOW_WIDTH), random.nextInt(WINDOW_HEIGHT), RADIUS, Color.BLUE);

        // Calculate the line endpoints to avoid crossing inside the circles
        Point2D point1 = new Point2D(circle1.getCenterX(), circle1.getCenterY());
        Point2D point2 = new Point2D(circle2.getCenterX(), circle2.getCenterY());
        Point2D direction = point2.subtract(point1).normalize();
        Point2D offset1 = direction.multiply(RADIUS);
        Point2D offset2 = direction.multiply(-RADIUS);
        Point2D lineStart = point1.add(offset1);
        Point2D lineEnd = point2.add(offset2);

        // Create the line with the calculated endpoints
        Line line = new Line(lineStart.getX(), lineStart.getY(), lineEnd.getX(), lineEnd.getY());
        line.setStrokeWidth(2);
        line.setStroke(Color.GREEN);

        // Add the circles and line to the root Group
        root.getChildren().addAll(circle1, circle2, line);

        // Create the Scene and set it on the Stage
        Scene scene = new Scene(root, WINDOW_WIDTH, WINDOW_HEIGHT);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Two Circles");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.math.BigInteger;
import java.util.PriorityQueue;
 
final class Hamming {
    private static BigInteger THREE = BigInteger.valueOf(3);
    private static BigInteger FIVE = BigInteger.valueOf(5);
 
    private static void updateFrontier(BigInteger x,
                                       PriorityQueue<BigInteger> pq) {
        pq.offer(x.shiftLeft(1));
        pq.offer(x.multiply(THREE));
        pq.offer(x.multiply(FIVE));
    }
 
    public static BigInteger hamming(int n) {
        if (n <= 0)
            throw new IllegalArgumentException("Invalid parameter");
        PriorityQueue<BigInteger> frontier = new PriorityQueue<BigInteger>();
        updateFrontier(BigInteger.ONE, frontier);
        BigInteger lowest = BigInteger.ONE;
        for (int i = 1; i < n; i++) {
            lowest = frontier.poll();
            while (frontier.peek().equals(lowest))
                frontier.poll();
            updateFrontier(lowest, frontier);
        }
        return lowest;
    }
 
    public static void main(String[] args) {
        System.out.print("Hamming(1 .. 20) =");
        for (int i = 1; i < 21; i++)
             System.out.print(" " + hamming(i));
        System.out.println("\nHamming(1691) = " + hamming(1691));
        System.out.println("Hamming(1000000) = " + hamming(1000000));
    }
}

public class Antiprime {
 
    static int countDivisors(int n) {
        if (n < 2) return 1;
        int count = 2; // 1 and n
        for (int i = 2; i <= n/2; ++i) {
            if (n%i == 0) ++count;
        }
        return count;
    }
 
    public static void main(String[] args) {
        int maxDiv = 0, count = 0;
        System.out.println("The first 20 anti-primes are:");
        for (int n = 1; count < 20; ++n) {
            int d = countDivisors(n);
            if (d > maxDiv) {
                System.out.printf("%d ", n);
                maxDiv = d;
                count++;
            }
        }
        System.out.println();
    }
}

import java.util.Comparator;
import java.util.Objects;
import java.util.function.Function;

public final class Comparators {

    private Comparators() {
        // Prevent instantiation
    }

    public interface ComparatorBy<T> extends Comparator<T> {
        default <U extends Comparable<? super U>> ComparatorBy<T> thenBy(
            Function<? super T, ? extends U> prop) {
            return thenBy(prop, false);
        }

        default <U extends Comparable<? super U>> ComparatorBy<T> thenBy(
            Function<? super T, ? extends U> prop, boolean reversed) {
            Objects.requireNonNull(prop, "Property extractor cannot be null");
            return thenComparing(comparing(prop, reversed));
        }

        default ComparatorBy<T> invert() {
            return (a, b) -> reversed().compare(a, b);
        }
    }

    public static <T, U extends Comparable<? super U>> ComparatorBy<T> comparing(
        Function<? super T, ? extends U> prop) {
        return comparing(prop, false);
    }

    public static <T, U extends Comparable<? super U>> ComparatorBy<T> comparing(
        Function<? super T, ? extends U> prop, boolean reversed) {
        Objects.requireNonNull(prop, "Property extractor cannot be null");

        Comparator<T> baseComparator = (a, b) -> {
            if (a == b) return 0;
            if (a == null) return reversed ? 1 : -1;
            if (b == null) return reversed ? -1 : 1;

            U valueA = prop.apply(a);
            U valueB = prop.apply(b);

            if (valueA == valueB) return 0;
            if (valueA == null) return reversed ? 1 : -1;
            if (valueB == null) return reversed ? -1 : 1;

            int result = valueA.compareTo(valueB);
            return reversed ? -result : result;
        };

        return new ComparatorBy<T>() {
            @Override
            public int compare(T a, T b) {
                return baseComparator.compare(a, b);
            }

            @Override
            public ComparatorBy<T> reversed() {
                return comparing(prop, !reversed);
            }
        };
    }

    public static <T, U extends Comparable<? super U>> ComparatorBy<T> comparingNullable(
        Function<? super T, ? extends U> prop) {
        return comparingNullable(prop, false);
    }

    public static <T, U extends Comparable<? super U>> ComparatorBy<T> comparingNullable(
        Function<? super T, ? extends U> prop, boolean reversed) {
        Objects.requireNonNull(prop, "Property extractor cannot be null");

