import org.junit.Test;
import static org.junit.Assert.*;

public class HashThreeTest {

    private static class ObjectTest {
        private final int hashCode;
        private final String name;

        public ObjectTest(int hashCode, String name) {
            this.hashCode = hashCode;
            this.name = name;
        }

        @Override
        public int hashCode() {
            return hashCode;
        }

        @Override
        public boolean equals(Object obj) {
            if (this == obj) return true;
            if (obj == null || getClass() != obj.getClass()) return false;
            ObjectTest that = (ObjectTest) obj;
            return hashCode == that.hashCode && name.equals(that.name);
        }

        @Override
        public String toString() {
            return "ObjectTest{" + "hashCode=" + hashCode + ", name='" + name + '\'' + '}';
        }
    }

    @Test
    public void test1() {
        HashThree<ObjectTest> three = new HashThree<>();
        ObjectTest test1 = new ObjectTest(0x1A, "Test1");
        ObjectTest test2 = new ObjectTest(0x2B, "Test2");
        ObjectTest test3 = new ObjectTest(0x1A, "Test3"); // Same hash as test1

        // Test adding objects
        assertTrue(three.add(test1));
        assertEquals(1, three.size());
        assertTrue(three.add(test2));
        assertEquals(2, three.size());

        // Test adding duplicate object
        assertFalse(three.add(test1));
        assertEquals(2, three.size());

        // Test adding object with same hash but different value
        assertTrue(three.add(test3));
        assertEquals(3, three.size());

        // Test existence checks
        assertTrue(three.contains(test1));
        assertTrue(three.contains(test2));
        assertTrue(three.contains(test3));

        // Test replacing an object
        ObjectTest test4 = new ObjectTest(0x1A, "Test4"); // Same hash as test1 and test3
        assertTrue(three.replace(test1, test4));
        assertFalse(three.contains(test1));
        assertTrue(three.contains(test4));

        // Test removing an object
        assertTrue(three.remove(test2));
        assertEquals(2, three.size());
        assertFalse(three.contains(test2));
    }
}

