import org.bson.BsonReader;
import org.bson.BsonValue;
import org.bson.BsonWriter;
import org.bson.Document;
import org.bson.codecs.CollectibleCodec;
import org.bson.codecs.DecoderContext;
import org.bson.codecs.EncoderContext;
import org.bson.codecs.configuration.CodecRegistry;
import org.bson.types.ObjectId;

import java.util.LinkedHashMap;

import static java.lang.String.format;

public final class ImmutableDocumentCodec implements CollectibleCodec<ImmutableDocument> {
    private final CodecRegistry codecRegistry;
    private static final String ID_FIELD_NAME = "_id";

    public ImmutableDocumentCodec(final CodecRegistry codecRegistry) {
        this.codecRegistry = codecRegistry;
    }

    @Override
    public ImmutableDocument generateIdIfAbsentFromDocument(final ImmutableDocument document) {
        LinkedHashMap<String, Object> mutable = new LinkedHashMap<String, Object>(document);
        mutable.put(ID_FIELD_NAME, new ObjectId());
        return new ImmutableDocument(mutable);
    }

    @Override
    public boolean documentHasId(final ImmutableDocument document) {
        return document.containsKey(ID_FIELD_NAME);
    }

    @Override
    public BsonValue getDocumentId(final ImmutableDocument document) {
        if (!documentHasId(document)) {
            throw new IllegalStateException(format("The document does not contain an %s", ID_FIELD_NAME));
        }
        return document.toBsonDocument(ImmutableDocument.class, codecRegistry).get(ID_FIELD_NAME);
    }

    @Override
    public void encode(final BsonWriter writer, final ImmutableDocument value, final EncoderContext encoderContext) {
        codecRegistry.get(Document.class).encode(writer, new Document(value), encoderContext);
    }

    @Override
    public Class<ImmutableDocument> getEncoderClass() {
        return ImmutableDocument.class;
    }

    @Override
    public ImmutableDocument decode(final BsonReader reader, final DecoderContext decoderContext) {
        Document document = codecRegistry.get(Document.class).decode(reader, decoderContext);
        return new ImmutableDocument(document);
    }
}

import java.util.Scanner;

public class GradeConverter {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a letter grade (A, B, C, D, or F): ");
        String letterGrade = input.next();

        double numericGrade;

        switch (letterGrade) {
            case "A":
                numericGrade = 4.0;
                break;
            case "B":
                numericGrade = 3.0;
                break;
            case "C":
                numericGrade = 2.0;
                break;
            case "D":
                numericGrade = 1.0;
                break;
            case "F":
                numericGrade = 0.0;
                break;
            default:
                System.out.println("Invalid grade");
                return;
        }

        System.out.println("The numeric value of " + letterGrade + " is " + numericGrade);
    }
}

import java.io.InputStream;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.util.zip.Inflater;
import java.util.zip.InflaterInputStream;

public class NativeZip {

    private long mObj;
    private InputStream mInput;

    static {
        System.loadLibrary("nativezip"); // Or the appropriate name
    }

    public NativeZip(String zipPath) {
        mObj = getZip(zipPath);
    }

    public NativeZip(ByteBuffer buffer) {
        mObj = getZipFromByteBuffer(buffer);
    }

    @Override
    protected void finalize() throws Throwable {
        try {
            release();
        } finally {
            super.finalize();
        }
    }

    public void close() {
        release();
    }

    public void release() {
        if (mObj != 0) {
            _release(mObj);
            mObj = 0;
            if (mInput != null) {
                try {
                    mInput.close();
                } catch (IOException e) {
                    // Ignore
                }
                mInput = null;
            }
        }
    }

    public boolean isReleased() {
        return mObj == 0;
    }

    public InputStream getInputStream(String filePath) {
        return createInputStream(_getInputStream(mObj, filePath), 8); // 8 means DEFLATED
    }

    // Called from native
    private InputStream createInputStream(long nativePtr, int compressionMethod) {
        ByteBuffer bb = ByteBuffer.allocateDirect(1024 * 1024); // 1MB
        ByteBufferInputStream bbis = new ByteBufferInputStream(bb);

        if (compressionMethod == 8) { // DEFLATED
            return new InflaterInputStream(bbis, new Inflater(true), 512);
        } else {
            return bbis;
        }
    }

    private static native long getZip(String zipPath);
    private static native long getZipFromByteBuffer(ByteBuffer buffer);
    private static native void _release(long obj);
    private static native long _getInputStream(long obj, String filePath);

}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.PriorityQueue;

class Validator {
    public long kSum(int[] arr, int k) {

        Arrays.sort(arr);
        int p = 0;
        while (p < arr.length && arr[p] < 0) {
            p++;
        }

        int[] pos = Arrays.copyOfRange(arr, p, arr.length);
        int[] neg = Arrays.copyOfRange(arr, 0, p);

        for (int i = 0; i < neg.length; i++) {
            neg[i] = -neg[i];
        }
        Arrays.sort(neg);

        long max = 0;
        for (int v : pos) {
            max += v;
        }

        var alist = kMinSum(pos, k);
        var blist = kMinSum(neg, k);

       // System.out.println(alist);
       // System.out.println(blist);

        int[] ptr = new int[alist.size()];
        Arrays.fill(ptr, 1);

        PriorityQueue<long[]> sums = new PriorityQueue<>((a, b) -> Long.compare(a[1], b[1]));
        for (int i = 0; i < alist.size(); i++) {
            sums.add(new long[]{i, alist.get(i) + blist.get(0)});
        }

        PriorityQueue<Long> pq = new PriorityQueue<>();
        while (pq.size() < k) {
            long[] pair = sums.poll();
//            System.out.println(Arrays.toString(pair));
            pq.add(pair[1]);
            int idx = (int) pair[0];
            if (ptr[idx] < blist.size()) {
                sums.add(new long[]{idx, alist.get(idx) + blist.get(ptr[idx])});
                ptr[idx]++;
            }
        }

//        System.out.println("max=" + max);

        for (int i = 0; i < k - 1; i++) {
//            System.out.println(pq.peek());

            pq.poll();
        }
        return max - pq.poll();

    }

    private List<Long> kMinSum(int[] arr, int k) {
        List<Long> ans = new ArrayList<>();
        ans.add(0L);
        if (arr.length == 0) {
            return ans;
        }
        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> Long.compare(a[1], b[1]));
        pq.add(new long[]{0, arr[0]});

        while (!pq.isEmpty() && ans.size() < k) {
            long[] p = pq.poll();
            long sum = p[1];
            int hi = (int) p[0];
            ans.add(sum);
            if (hi + 1 < arr.length) {
                pq.add(new long[]{hi + 1, sum - arr[hi] + arr[hi + 1]});
                pq.add(new long[]{hi + 1, sum + arr[hi + 1]});
            }
        }
        return ans;
    }

    private void swap(int[] arr, int i, int j) {
        arr[i] ^= arr[j];
        arr[j] ^= arr[i];
        arr[i] ^= arr[j];
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Benford {
    public static void main(String[] args) {
        List<Integer> fibseries = fibseries(1000);
        benford(fibseries).forEach(System.out::println);
    }

    private static List<Integer> fibseries(int n) {
        return IntStream.range(0, n)
               .mapToObj(i -> i < 2? i : fibseries.get(i - 1) + fibseries.get(i - 2))
               .collect(Collectors.toList());
    }

    private static List<List<Double>> benford(List<Integer> array) {
        return IntStream.range(1, 10)
               .mapToObj(val -> Arrays.asList(
                        (double) val,
                        array.stream()
                               .filter(item -> item.toString().charAt(0) == val)
                               .count() / array.size(),
                        Math.log10(1 + 1 / val)
                ))
               .collect(Collectors.toList());
    }
}

