        if (getClass() != obj.getClass())
            return false;
        Version other = (Version) obj;
        if (cctrl == null) {
            if (other.cctrl != null)
                return false;
        } else if (!cctrl.equals(other.cctrl))
            return false;
        if (pycclib == null) {
            if (other.pycclib != null)
                return false;
        } else if (!pycclib.equals(other.pycclib))
            return false;
        return true;
    }
}

public class MeanAngle {
    public static void main(String[] args) {
        double[] a = {350, 10};
        double[] b = {90, 180, 270, 360};
        double[] c = {10, 20, 30};
        System.out.println(meanAngleDeg(a));
        System.out.println(meanAngleDeg(b));
        System.out.println(meanAngleDeg(c));
    }

    public static double sum(double[] a) {
        double s = 0;
        for (int i = 0; i < a.length; i++) s += a[i];
        return s;
    }

    public static double degToRad(double a) {
        return Math.PI / 180 * a;
    }

    public static double meanAngleDeg(double[] a) {
        return 180 / Math.PI * Math.atan2(
                sum(a.map(degToRad).map(Math.sin)) / a.length,
                sum(a.map(degToRad).map(Math.cos)) / a.length
        );
    }
}

