private void setHeaderList(Map<String, List<String>> headers, String name, String value) {
    // Check if the header name already exists in the map
    if (headers.containsKey(name)) {
        // If it exists, add the value to the existing list
        headers.get(name).add(value);
    } else {
        // If it does not exist, create a new list, add the value, and put it in the map
        List<String> values = new ArrayList<>();
        values.add(value);
        headers.put(name, values);
    }
}

