import java.util.HashMap;
import java.util.Map;
 
public class HofstadterQSequence {
    // Initialize the dictionary with the first two indices filled.
    private static final Map<Integer, Integer> QList = new HashMap<Integer, Integer>() {{
        put(1, 1);
        put(2, 1);
    }};
 
    public static void main(String[] args) {
        int lessThanLast = 0;
        /* Initialize our variable that holds the number of times
         * a member of the sequence was less than its preceding term. */
 
        for (int n = 1; n <= 100000; n++) {
            int q = Q(n); // Get Q(n).
 
            if (n > 1 && QList.get(n - 1) > q) // If Q(n) is less than Q(n - 1),
                lessThanLast++;            // then add to the counter.
 
            if (n > 10 && n!= 1000) continue; /* If n is greater than 10 and not 1000,
                                                * the rest of the code in the loop does not apply,
                                                * and it will be skipped. */
 
            if (!Confirm(n, q)) // Confirm Q(n) is correct.
                throw new RuntimeException(String.format("Invalid result: Q(%d) != %d", n, q));
 
            System.out.println(String.format("Q(%d) = %d", n, q)); // Write Q(n) to the console.
        }
 
        System.out.println(String.format("Number of times a member of the sequence was less than its preceding term: %d.",
                lessThanLast));
    }
 
    private static boolean Confirm(int n, int value) {
        if (n <= 10)
            return new int[]{1, 1, 2, 3, 3, 4, 5, 5, 6, 6}[n - 1] == value;
        if (n == 1000)
            return 502 == value;
        throw new IllegalArgumentException("Invalid index.");
    }
 
    private static int Q(int n) {
        Integer q = QList.get(n);
 
        if (q == null) { // Try to get Q(n) from the dictionary.
            q = Q(n - Q(n - 1)) + Q(n - Q(n - 2)); // If it's not available, then calculate it.
            QList.put(n, q); // Add it to the dictionary.
        }
 
        return q;
    }
}

import java.text.DateFormat;
import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 *
 */
public class Time {
    private int hour;
    private int minute;
    private int second;

    public Time(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public void setHour(int hour) {
        this.hour = hour;
    }

    public int getMinute() {
        return minute;
    }

    public void setMinute(int minute) {
        this.minute = minute;
    }

    public int getSecond() {
        return second;
    }

    public void setSecond(int second) {
        this.second = second;
    }

    public void setTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public Time nextSecond(){
        this.second+=1;
        return this;
    }

    public Time previousSecond(){
        this.second-=1;
        return this;
    }

    @Override
    public String toString() {
        String timeString = String.format("%d:%d:%d", hour, minute, second);
        Date time = null;
        try {
            time = new SimpleDateFormat("HH:mm:ss").parse(timeString);
        } catch (ParseException ex) {
            Logger.getLogger(Time.class.getName()).log(Level.SEVERE, null, ex);
        }
        timeString = new SimpleDateFormat("HH:mm:ss").format(time);
        return timeString;
    }

}

