public void encodeTo(QualityFormat format, byte[] buffer, int offset) {
        byte vo = format.getOffset();
        for (int i = 0; i < data.length; ++i)
            buffer[offset++] = (byte) (data[i] + vo);
    }

    public byte[] encode(int offset) {
        if (offset < 0 || offset > 70)
            throw new IllegalArgumentException();
        byte[] copy = new byte[data.length];
        for (int i = copy.length - 1; i >= 0; --i)
            copy[i] += data[i] + offset;
        return copy;
    }

import org.apache.hyracks.api.dataflow.value.ITypeTraits;
import org.apache.hyracks.api.dataflow.value.IValueExtractor;
import org.apache.hyracks.api.dataflow.value.IValueWriter;
import org.apache.hyracks.api.dataflow.value.IValueReader;
import org.apache.hyracks.api.dataflow.value.IValueCollector;
import org.apache.hyracks.api.dataflow.value.IValueContext;
import org.apache.hyracks.api.dataflow.value.ObjectInspector;
import org.apache.hyracks.api.exceptions.HyracksDataException;

public class IntermediateStddevPopAggregateDescriptor extends AggregateFunctionDescriptor {

    private static final long serialVersionUID = 1L;

    @Override
    public String getIdentifier() {
        return "INTERMEDIATE_STDDEV_POP";
    }

    @Override
    public AggregateEvaluatorFactory createAggregateEvaluatorFactory() {
        return new AggregateEvaluatorFactory() {
            @Override
            public AggregateEvaluator createEvaluator() {
                return new IntermediateStddevEvaluator();
            }
        };
    }

    private class IntermediateStddevEvaluator extends AggregateEvaluator {
        private double sum = 0;
        private double sumOfSquares = 0;
        private int count = 0;

        @Override
        public void init() {
            sum = 0;
            sumOfSquares = 0;
            count = 0;
        }

        @Override
        public void accumulate(Object value) throws HyracksDataException {
            if (value != null) {
                double val = ((Number) value).doubleValue();
                count++;
                sum += val;
                sumOfSquares += val * val;
            }
        }

        @Override
        public void combine(AggregateEvaluator other) throws HyracksDataException {
            IntermediateStddevEvaluator otherEvaluator = (IntermediateStddevEvaluator) other;
            count += otherEvaluator.count;
            sum += otherEvaluator.sum;
            sumOfSquares += otherEvaluator.sumOfSquares;
        }

        @Override
        public Object getResult() throws HyracksDataException {
            if (count == 0) return null;
            double mean = sum / count;
            double variance = (sumOfSquares - (2 * mean * sum) / count + (count * mean * mean)) / count;
            return Math.sqrt(variance);
        }

        @Override
        public void reset() {
            init();
        }
    }
}

