public class OpenProjectAction implements ActionListener {

    private KrokiMockupToolApp krokiApp;

    public OpenProjectAction(KrokiMockupToolApp krokiApp) {
        this.krokiApp = krokiApp;
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        JFileChooser fileChooser = new JFileChooser();
        FileNameExtensionFilter filter = new FileNameExtensionFilter(
                "Kroki Project Files (*.kroki)", "kroki");
        fileChooser.setFileFilter(filter);

        int returnVal = fileChooser.showOpenDialog(krokiApp.getFrame());

        if (returnVal == JFileChooser.APPROVE_OPTION) {
            File file = fileChooser.getSelectedFile();
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                BussinesSubsystem bussinesSubsystem = (BussinesSubsystem) ois.readObject();
                krokiApp.getWorkspace().addProject(bussinesSubsystem);
            } catch (Exception ex) {
                JOptionPane.showMessageDialog(
                        krokiApp.getFrame(),
                        "Error loading project from file:\n" + ex.getMessage(),
                        "Error",
                        JOptionPane.ERROR_MESSAGE);
            }
        }
    }
}

public synchronized IMolecularFormula getNextFormula() {

        mainCycle: while (searchRunning) {
            double currentMass = calculateCurrentMass();

            if (currentMass > maxMass) {

                synchronized (currentCounts) {
                    currentCounts[lastIncreasedPosition] = maxCounts[lastIncreasedPosition];
                    increaseCounter(lastIncreasedPosition);
                }
                continue mainCycle;
            }

            if ((currentMass >= minMass) && (currentMass <= maxMass)) {
                IMolecularFormula cdkFormula = generateFormulaObject();
                increaseCounter(0);
                return cdkFormula;
            }

            increaseCounter(0);
        }

        return null;
    }

import java.util.List;

public class Timer {

    class Trie {
        boolean end = false;
        Trie[] next = new Trie[26];
    }

    public String replaceWords(List<String> dict, String sentence) {
        Trie root = new Trie();
        for(String s : dict) {
            buildTrie(root, s);
        }

        String[] ss = sentence.split(" ");
        StringBuilder sb = new StringBuilder();
        for(String s : ss) {
            StringBuilder t = new StringBuilder();
            findPrefix(root, s, t);
            sb.append(t).append(" ");
        }

        return sb.toString().trim();
    }

    private void findPrefix(Trie root, String s, StringBuilder sb) {
        if(root.end)    return ;
        if("".equals(s))    return;
        char c = s.charAt(0);
        if(root.next[c-'a'] != null) {
            sb.append(c);
            findPrefix(root.next[c-'a'], s.substring(1), sb);
        } else {
            sb.append(s);
            return;
        }
    }

    private void buildTrie(Trie root, String s) {
        if("".equals(s)) {
            root.end = true;
            return;
        }
        char c = s.charAt(0);
        if(root.next[c-'a'] == null)
            root.next[c-'a'] = new Trie();
        buildTrie(root.next[c-'a'], s.substring(1));
    }
}

