import java.util.*;
public class Stripe{
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while(t-- > 0){
            sc.nextLine();
            char[][] mat = new char[8][8];
            for(int i = 0; i < 8; i++){
                String str = sc.nextLine();
                for(int j = 0; j < 8; j++){
                    mat[i][j] = str.charAt(j);
                }
            }
            boolean red = false;
            boolean blue = false;
            for(int i = 0; i < 8; i++){
                for(int j = 0; j < 8; j++){
                    if(mat[i][j] == 'R'){
                        red = true;
                        if(blue) break;
                    }
                    if(mat[i][j] == 'B'){
                        blue = true;
                        if(red) break;
                    }
                }
            }
            if(red && !blue) System.out.println("R");
            else System.out.println("B");
        }
    }
}

