import javax.xml.bind.annotation.XmlAttribute;
import javax.xml.bind.annotation.XmlRootElement;
import java.util.Objects;

@XmlRootElement(name = "proxyModule")
public class MutableProxyModule extends MutableModule implements BareProxyModule {

    @XmlAttribute(name = "declaration")
    private MutableQualifiedNamable declaration;

    public MutableProxyModule() {
        // Default constructor
    }

    public MutableProxyModule(MutableQualifiedNamable declaration) {
        this.declaration = declaration;
    }

    public static MutableProxyModule copyOfProxyModule(BareProxyModule original, CopyOption... options) {
        MutableProxyModule copy = new MutableProxyModule();
        copy.setDeclaration(original.getDeclaration());
        return copy;
    }

    @Override
    public MutableQualifiedNamable getDeclaration() {
        return declaration;
    }

    @Override
    public MutableProxyModule setDeclaration(MutableQualifiedNamable declaration) {
        this.declaration = declaration;
        return this;
    }

    public MutableProxyModule setDeclaration(String qualifiedName) {
        this.declaration = new MutableQualifiedNamable(qualifiedName);
        return this;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof MutableProxyModule)) return false;
        if (!super.equals(o)) return false;
        MutableProxyModule that = (MutableProxyModule) o;
        return Objects.equals(declaration, that.declaration);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), declaration);
    }

    @Override
    public String toString() {
        return "MutableProxyModule{" +
                "declaration=" + declaration +
                '}';
    }

    @Override
    public void accept(BareModuleVisitor visitor) {
        visitor.visitProxyModule(this);
    }
}

