import java.util.Scanner;

public class UpdateFiles {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        for (int i = 0; i < t; i++) {
            long n = sc.nextLong();
            long k = sc.nextLong();
            System.out.println(minHours(n, k));
        }
        sc.close();
    }

    public static long minHours(long n, long k) {
        if (n == 1) return 0;
        long low = 1, high = 60; // Assuming 2^60 is greater than 10^18
        while (low < high) {
            long mid = (low + high) / 2;
            if (k * (1L << mid) < n) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

