public class Validator {
    public static void main(String[] args) {
        double x1 = -1.356;
        double y1 = 1.743;
        double x2 = -1.377;
        double y2 = 1.929;
        double x3 = -1.432;
        double y3 = 1.711;

        double s1 = findSide(x1, y1, x2, y2);
        double s2 = findSide(x2, y2, x3, y3);
        double s3 = findSide(x1, y1, x3, y3);

        if (isValid(s1, s2, s3)) {
            System.out.println("The area of the triangle is: " + area(s1, s2, s3));
        } else {
            System.out.println("The input for sides, is invalid");
        }

    }

    public static double area(double side1, double side2, double side3) {
        double s = (side1 + side2 + side3) / 2;

        return Math.sqrt((s * (s - side1) * (s - side2) * (s - side3)));
    }

    public static boolean isValid(
            double side1, double side2, double side3) {
        if ((side1 + side2) > side3) {
            return false;
        } else if ((side1 + side3) > side2) {
            return false;
        } else if ((side2 + side3) > side1) {
            return false;
        } else {
            return true;
        }
    }

    public static double findSide(double x, double y, double w, double z) {

        return Math.pow(Math.pow(x - w, 2) + Math.pow(y - z, 2), 0.5);
    }
}

import org.springframework.stereotype.Component;
import java.util.ArrayList;
import java.util.List;

@Component
public class TaskCompletionProvider {

    private List<RecoveryStrategy<?>> recoveryStrategies = new ArrayList<>();
    private List<TaskExpansionStrategy> expansionStrategies = new ArrayList<>();

    public List<String> complete(String dslStart, int detailLevel) {
        TaskDefinition taskDefinition = parseTaskDefinition(dslStart);
        if (taskDefinition != null) {
            return generateExpansions(taskDefinition, detailLevel);
        } else {
            return generateRecoveryProposals(dslStart);
        }
    }

    private TaskDefinition parseTaskDefinition(String dsl) {
        // Simple mock parser logic for demonstration
        if (dsl != null && !dsl.trim().isEmpty()) {
            return new TaskDefinition(dsl.trim()); // Simulating parsing success
        }
        return null; // Simulating parsing failure
    }

    private List<String> generateExpansions(TaskDefinition taskDefinition, int detailLevel) {
        List<String> proposals = new ArrayList<>();
        for (TaskExpansionStrategy strategy : expansionStrategies) {
            proposals.addAll(strategy.expand(taskDefinition, detailLevel));
        }
        return proposals;
    }

    private List<String> generateRecoveryProposals(String invalidInput) {
        List<String> proposals = new ArrayList<>();
        for (RecoveryStrategy<?> strategy : recoveryStrategies) {
            proposals.addAll(strategy.recover(invalidInput));
        }
        return proposals;
    }

    public void addCompletionRecoveryStrategy(RecoveryStrategy<?> recoveryStrategy) {
        recoveryStrategies.add(recoveryStrategy);
    }

    public void addTaskExpansionStrategy(TaskExpansionStrategy expansionStrategy) {
        expansionStrategies.add(expansionStrategy);
    }
}

interface RecoveryStrategy<T> {
    List<String> recover(String invalidInput);
}

interface TaskExpansionStrategy {
    List<String> expand(TaskDefinition taskDefinition, int detailLevel);
}

class TaskDefinition {
    private String definition;

    public TaskDefinition(String definition) {
        this.definition = definition;
    }

    public String getDefinition() {
        return definition;
    }
}

class SampleRecoveryStrategy implements RecoveryStrategy<SampleRecoveryStrategy> {
    @Override
    public List<String> recover(String invalidInput) {
        List<String> corrections = new ArrayList<>();
        corrections.add("Did you mean: " + invalidInput + "?");
        return corrections;
    }
}

import org.geoserver.catalog.DataStoreInfo;
import org.geoserver.catalog.LayerInfo;
import org.geotools.data.Query;
import org.geotools.feature.visitor.UniqueVisitor;
import org.geotools.jdbc.JDBCDataStore;
import org.geotools.jdbc.VirtualTable;

import org.opengis.feature.type.FeatureType;

import org.geoserver.catalog.*;

import java.io.IOException;
import java.lang.reflect.Method;
import java.lang.IllegalAccessException;
import java.lang.reflect.InvocationTargetException;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.Set;
import java.util.TreeSet;

public class PossibleValuesReader {

    public Set read(DataStoreInfo dataStoreInfo, LayerInfo layerInfo, String propertyName)
        throws IOException, NoSuchMethodException, SQLException, IllegalAccessException, InvocationTargetException
    {
        JDBCDataStore store = (JDBCDataStore)dataStoreInfo.getDataStore(null);
        FeatureTypeInfo info = (FeatureTypeInfo)layerInfo.getResource();

        FeatureType schema = null;

        if(info.getMetadata() != null && info.getMetadata().containsKey(FeatureTypeInfo.JDBC_VIRTUAL_TABLE)) {
            VirtualTable vt = (VirtualTable) info.getMetadata().get(FeatureTypeInfo.JDBC_VIRTUAL_TABLE);
            if(!store.getVirtualTables().containsValue(vt)) {
                store.addVirtualTable(vt);
            }
            schema = store.getSchema(vt.getName());
        }
        else {
            schema = store.getSchema(info.getNativeName());
        }

        Query query = new Query(null, null, new String[] { });
        UniqueVisitor visitor = new UniqueVisitor(propertyName);

        Method storeGetAggregateValueMethod = store.getClass().getDeclaredMethod(
            "getAggregateValue",
            org.opengis.feature.FeatureVisitor.class,
            org.opengis.feature.simple.SimpleFeatureType.class,
            org.geotools.data.Query.class,
            java.sql.Connection.class
        );
        storeGetAggregateValueMethod.setAccessible(true);

        Connection conn = store.getDataSource().getConnection();
        try {
            storeGetAggregateValueMethod.invoke(store, visitor, schema, query, conn);
        }
        finally {
            conn.close();
        }

        Set values = visitor.getUnique();
        values.remove(null);
        // ordered by comparator for type
        return new TreeSet(values);
    }
}

