public class CopyStreamException extends IOException {
    private static final long serialVersionUID = 6740093478674800213L;
    private final long totalBytesTransferred;

    /**
     * Constructs a CopyStreamException with detailed failure context.
     *
     * @param message               Description of the error context
     * @param totalBytesTransferred Bytes successfully copied before failure
     * @param cause                 Original I/O exception triggering the failure
     * @throws IllegalArgumentException if cause is null
     */
    public CopyStreamException(String message, long totalBytesTransferred, IOException cause) {
        super(message);
        if (cause == null) {
            throw new IllegalArgumentException("Root cause exception must be provided");
        }
        this.totalBytesTransferred = totalBytesTransferred;
        initCause(cause);
    }

    /**
     * Retrieves the count of bytes successfully transferred before failure.
     *
     * @return Long value representing successfully copied bytes
     */
    public long getTotalBytesTransferred() {
        return totalBytesTransferred;
    }

    /**
     * Returns the root cause IOException that terminated the copy operation.
     * Guaranteed to be non-null and of type IOException.
     *
     * @return Original I/O exception causing the failure
     */
    public IOException getIOException() {
        return (IOException) getCause();
    }

    /**
     * Generates a composite string representation including base exception
     * details, bytes transferred, and root cause information.
     *
     * @return Enriched string representation of exception state
     */
    @Override
    public String toString() {
        return super.toString() + " [Bytes Transferred: " + totalBytesTransferred
               + ", Root Cause: " + getCause().toString() + "]";
    }

