import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Scanner;
 
public class PalindromeDates {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the number of palindrome dates to find: ");
        int count = in.nextInt();
        in.close();
        System.out.println("Next " + count + " palindrome dates:");
        Calendar calendar = new GregorianCalendar();
        calendar.setTime(new Date());
        calendar.add(Calendar.DATE, 1);
        while (count > 0) {
            String str = String.format("%tF", calendar);
            if (isPalindrome(str)) {
                System.out.println(str);
                --count;
            }
            calendar.add(Calendar.DATE, 1);
        }
    }
    private static boolean isPalindrome(String str) {
        int n = str.length();
        for (int i = 0; i + 1 < n; ++i, --n) {
            if (str.charAt(i)!= str.charAt(n - 1))
                return false;
        }
        return true;
    }
}

