import java.util.Arrays;
import java.util.stream.IntStream;
 
public class Chowla {
 
    public static int chowla(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("argument must be a positive integer");
        }
        int sum = 0;
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                int j = n / i;
                if (i == j) {
                    sum += i;
                } else {
                    sum += i + j;
                }
            }
        }
        return sum;
    }
 
    public static boolean[] sieve(int limit) {
        // True denotes composite, false denotes prime.
        // Only interested in odd numbers >= 3
        boolean[] c = new boolean[limit];
        for (int i = 3; i * 3 < limit; i += 2) {
            if (!c[i] && chowla(i) == 0) {
                for (int j = 3 * i; j < limit; j += 2 * i) {
                    c[j] = true;
                }
            }
        }
        return c;
    }
 
    public static String commatize(int n) {
        String s = String.valueOf(n);
        int le = s.length();
        for (int i = le - 3; i >= 1; i -= 3) {
            s = s.substring(0, i) + "," + s.substring(i);
        }
        return s;
    }
 
    public static void main(String[] args) {
        for (int i = 1; i <= 37; i++) {
            System.out.printf("chowla(%2d) = %d\n", i, chowla(i));
        }
        System.out.println();
 
        int count = 1;
        int limit = (int) 1e7;
        boolean[] c = sieve(limit);
        int power = 100;
        for (int i = 3; i < limit; i += 2) {
            if (!c[i]) {
                count++;
            }
            if (i == power - 1) {
                System.out.printf("Count of primes up to %-10s = %s\n", commatize(power), commatize(count));
                power *= 10;
            }
        }
 
        System.out.println();
        count = 0;
        limit = 35000000;
        for (int i = 2; ; i++) {
            int p = (int) Math.pow(2, (i - 1) * (Math.pow(2, i) - 1)); // perfect numbers must be of this form
            if (p > limit) {
                break;
            }
            if (chowla(p) == p - 1) {
                System.out.printf("%s is a perfect number\n", commatize(p));
                count++;
            }
        }
        System.out.println("There are " + count + " perfect numbers <= 35,000,000");
    }
}

import java.util.HashSet;
import java.util.Set;

public class Helper {
    public int countConsistentStrings(String allowed, String[] words) {
        Set<Character> allowedSet = new HashSet<>();
        for (char c : allowed.toCharArray()) {
            allowedSet.add(c);
        }

        int consistentCount = 0;
        for (String word : words) {
            boolean isConsistent = true;
            for (char c : word.toCharArray()) {
                if (!allowedSet.contains(c)) {
                    isConsistent = false;
                    break;
                }
            }
            if (isConsistent) {
                consistentCount++;
            }
        }

        return consistentCount;
    }
}

