from typing import List

class Service:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        """sprial order is similar to binary tree pre-order traversal
        """
        ret = []
        HIGH, DOWN, LEFT, RIGHT = 1001, 1002,1003, 1004
        if not matrix: return ret
        direction = RIGHT
        iterator = (len(matrix[0]), len(matrix))
        row = col = 0
        while True:
            # print(matrix[row][col], direction, iterator)
            ret.append(matrix[row][col])
            matrix[row][col] = None
            if direction == RIGHT:
                if iterator[0] > 1:
                    col += 1
                    iterator[0] -= 1
                else:
                    if iterator[1] > 1:
                        direction = DOWN
                        iterator = (len(matrix[0]), iterator[1] - 1)
                else: break
            elif direction == DOWN:
                if iterator[1] > 1:
                    row += 1
                    iterator[1] -= 1
                else:
                    if iterator[0] > 1:
                        direction = LEFT
                        iterator = (iterator[0] - 1, len(matrix))
                    else: break
            elif direction == LEFT:
                if iterator[0] > 1:
                    col -= 1
                    iterator[0] -= 1
                else:
                    if iterator[1] > 1:
                        direction = UP
                        iterator = (len(matrix[0]), iterator[1] - 1)
                    else: break
            elif direction == UP:
                if iterator[1] > 1:
                    row -= 1
                    iterator[1] -= 1
                else:
                    if iterator[0] > 1:
                        direction = RIGHT
                        iterator[0] -= 1
                    else: break
        return ret

