import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class SmileyFace extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {
        // Create a canvas to draw on
        Canvas canvas = new Canvas(400, 400);
        GraphicsContext gc = canvas.getGraphicsContext2D();

        // Draw the smiley face
        gc.setFill(Color.YELLOW);
        gc.fillOval(100, 100, 200, 200);
        gc.setFill(Color.BLACK);
        gc.fillOval(150, 150, 25, 25);
        gc.fillOval(225, 150, 25, 25);
        gc.setFill(Color.RED);
        gc.fillOval(165, 200, 70, 70);

        // Create a scene and add the canvas to it
        Scene scene = new Scene(canvas);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

class Converter {
    public int countVowelPermutation(int n) {
        int M = 1000000007;
        long[] count = new long[5];
        Arrays.fill(count, 1);

        for (int j = 0; j < n-1; j++) {
            long a = (count[1] + count[2] + count[4]) % M;
            long e = (count[0] + count[2]) % M;
            long i = (count[1] + count[3]) % M;
            long o = count[2];
            long u = (count[2] + count[3]) % M;
            count[0] = a;
            count[1] = e;
            count[2] = i;
            count[3] = o;
            count[4] = u;
        }

        long total = 0;
        for (long c : count) {
            total = (total + c)%M;
        }
        return (int)total;
    }
}

import java.util.Random;

public class Barbero2 {
    private int n; // Barber identifier
    private int countClientes = 0; // Current number of clients
    private final int cantMax = 10; // Maximum allowed clients
    private final int cantMin = 0; // Minimum allowed clients
    private Random rand = new Random();

    public Barbero2(int n) {
        this.n = n;
    }

    public void sentarCliente() throws InterruptedException {
        if (countClientes >= cantMax) {
            System.err.println("Error: Maximum client limit reached. Cannot seat more clients.");
            return;
        }
        countClientes++;
        System.out.println("Client seated. Total clients: " + countClientes);
        Thread.sleep(rand.nextInt(1000)); // Simulate seating time
    }

    public void afeitar() throws InterruptedException {
        if (countClientes <= cantMin) {
            System.err.println("Error: No clients available to shave.");
            return;
        }
        countClientes--;
        System.out.println("Client shaved. Total clients: " + countClientes);
        Thread.sleep(rand.nextInt(2000)); // Simulate shaving time
    }

    public void cobrar() throws InterruptedException {
        if (countClientes <= cantMin) {
            System.err.println("Error: No clients available to charge.");
            return;
        }
        countClientes--;
        System.out.println("Client charged. Total clients: " + countClientes);
        Thread.sleep(rand.nextInt(500)); // Simulate charging time
    }

    public static void main(String[] args) {
        Barbero2 barbero = new Barbero2(1);
        try {
            for (int i = 0; i < 15; i++) {
                barbero.sentarCliente();
                barbero.afeitar();
                barbero.cobrar();
            }
        } catch (InterruptedException e) {
            System.err.println("Thread interrupted: " + e.getMessage());
        }
    }
}

import com.intellij.lang.BracePair;
import com.intellij.lang.PairedBraceMatcher;
import com.intellij.psi.PsiFile;
import com.intellij.psi.tree.IElementType;
import com.intellij.psi.tree.TokenSet;
import com.intellij.psi.PsiElement;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

public class BuildBraceMatcher implements PairedBraceMatcher {

    private static final BracePair[] PAIRS = new BracePair[]{
            new BracePair(BuildTokenTypes.LBRACE, BuildTokenTypes.RBRACE, true),
            new BracePair(BuildTokenTypes.LBRACKET, BuildTokenTypes.RBRACKET, true),
            new BracePair(BuildTokenTypes.LPAREN, BuildTokenTypes.RPAREN, false)
    };

    private static final TokenSet BRACES_ALLOWED_BEFORE = TokenSet.create(
            BuildTokenTypes.WHITE_SPACE,
            BuildTokenTypes.NEW_LINE,
            BuildTokenTypes.BLOCK_COMMENT,
            BuildTokenTypes.LINE_COMMENT,
            BuildTokenTypes.COLON,
            BuildTokenTypes.COMMA,
            BuildTokenTypes.RBRACE,
            BuildTokenTypes.RBRACKET,
            BuildTokenTypes.RPAREN
    );

    @Override
    public BracePair @NotNull [] getPairs() {
        return PAIRS;
    }

    @Override
    public boolean isPairedBracesAllowedBeforeType(@NotNull IElementType lbraceType, @Nullable IElementType contextType) {
        return BRACES_ALLOWED_BEFORE.contains(contextType);
    }

    @Override
    public int getCodeConstructStart(PsiFile file, int openingBraceOffset) {
        return openingBraceOffset;
    }

    public static TokenSet tokenSet(){
        return BRACES_ALLOWED_BEFORE;
    }
}

interface BuildTokenTypes {
    IElementType LBRACE = null;
    IElementType RBRACE = null;
    IElementType LBRACKET = null;
    IElementType RBRACKET = null;
    IElementType LPAREN = null;
    IElementType RPAREN = null;
    IElementType WHITE_SPACE = null;
    IElementType NEW_LINE = null;
    IElementType BLOCK_COMMENT = null;
    IElementType LINE_COMMENT = null;
    IElementType COLON = null;
    IElementType COMMA = null;
}

import java.util.Random; // Rastgele sayilar uretmek icin Random sinifini ice aktarir.
import java.util.Scanner; // Kullanicidan giris almak icin Scanner sinifini ice aktarir.

public class RastgeleSayiTahmin { // Ana sinif

    public static void main(String[] args) { // Programin calismaya basladigi ana fonksiyon

        // Random sinifindan bir nesne olusturur, bu nesne ile rastgele sayilar uretilir.
        Random rastgele = new Random();

        // 1 ile 100 arasinda rastgele bir sayi uretir. 'nextInt(100)' ifadesi 0-99 arasinda bir sayi uretir,
        // bu yuzden sonuca 1 eklenir ve 1-100 araliginda bir sayi elde edilir.
        int sayi = rastgele.nextInt(100) + 1;

        // Kullanicidan giris almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicinin dogru tahmini yapana kadar donecek sonsuz bir dongu baslatilir.
        while(true) {

            // Kullanicinin girdigi sayiyi okur ve 'girilen' degiskenine atar.
            int girilen = scanner.nextInt();

            // Rastgele uretilen sayi ve kullanicinin girdigi sayiyi ekrana yazdirir.
            System.out.println("Rastgele = " + sayi + " Girilen = " + girilen);

            // Eger kullanicinin girdigi sayi, rastgele uretilen sayiya esitse, donguden cikilir.
            if(sayi == girilen) {
                // Tahmin dogru, dongu sonlanir.
                break;
            }
            // Eger girilen sayi, rastgele sayidan kucukse, kullaniciya daha buyuk bir sayi girmesi gerektigini soyler.
            else if(girilen < sayi) {
                System.out.println("Daha buyuk bir sayi giriniz (yukari).");
            }
            // Eger girilen sayi, rastgele sayidan buyukse, kullaniciya daha kucuk bir sayi girmesi gerektigini soyler.
            else {
                System.out.println("Daha kucuk bir sayi giriniz (asagi).");
            }
        }
        // Program burada sonlanir, scanner nesnesini kapatmayi unutmamak gerekir.
        scanner.close();
    }
}

