import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.PropertyNamingStrategy;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.datatype.guava.GuavaModule;
import com.fasterxml.jackson.datatype.jdk8.Jdk8Module;
import com.github.lake54.groupsio.api.domain.Page;

import java.util.function.Function;

/**
 * Utility class for interacting with Jackson types.
 */
public class JacksonUtils {

    /**
     * A reference to the default {@link TypeFactory} instance.
     */
    private static final TypeFactory TYPE_FACTORY = TypeFactory.defaultInstance();

    /**
     * A static mapper instance to use for all JSON interaction.
     */
    private static final ObjectMapper MAPPER = createMapper();

    /**
     * Converts an object to the type defined by the provided generator.
     *
     * @param object
     *      the object to convert to the new type.
     * @param generator
     *      the generator to create a new type reference.
     * @return
     *      an instance of the defined type.
     */
    public static <T> T convert(Object object, Function<TypeFactory, JavaType> generator) {
        return MAPPER.convertValue(object, generateType(generator));
    }

    /**
     * Creates an {@link ObjectMapper} instance with configuration.
     *
     * @return
     *      an {@link ObjectMapper} instance.
     */
    public static ObjectMapper createMapper() {
        ObjectMapper mapper = new ObjectMapper();

        mapper.registerModule(new GuavaModule());
        mapper.registerModule(new Jdk8Module());
        mapper.setSerializationInclusion(JsonInclude.Include.NON_NULL);

        return mapper;
    }

    /**
     * Creates a type reference to use for pagination.
     *
     * @param tClass
     *      the class to use for pagination.
     * @return
     *      a type representing a page of the provided class.
     */
    public static JavaType createPaginationType(Class<?> tClass) {
        return generateType(factory -> factory.constructParametricType(Page.class, tClass));
    }

    /**
     * Creates a type reference using the provided generator.
     *
     * @param generator
     *      the generator used to create a new type reference.
     * @return
     *      a type defined by the generating function.
     */
    public static JavaType generateType(Function<TypeFactory, JavaType> generator) {
        return generator.apply(TYPE_FACTORY);
    }
}

import java.util.*;
import java.io.*;

public class Order {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int t = in.nextInt();
        while (t-- > 0) {
            int n = in.nextInt();
            int[] a = new int[n];
            int totalTwos = 0;
            List<Integer> twoCounts = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                a[i] = in.nextInt();
                int count = 0;
                while (a[i] % 2 == 0) {
                    a[i] /= 2;
                    count++;
                }
                totalTwos += count;
                twoCounts.add(count);
            }
            int needTwos = n - totalTwos;
            if (needTwos <= 0) {
                System.out.println(0);
                continue;
            }
            Collections.sort(twoCounts);
            int operations = -1;
            for (int i = n - 1; i >= 0 && needTwos > 0; i--) {
                int index = n - i;
                needTwos -= index;
                operations++;
            }
            System.out.println(needTwos <= 0 ? operations : -1);
        }
        in.close();
    }
}

import java.util.*;

public class Utils {
    public static void main(String[] args) {
        int[] primes = new int[1000];
        for (int i = 2; i < 1000; i++) {
            if (isPrime(i)) {
                primes[i] = 1;
            }
        }

        int[][] twinPrimes = new int[1000][2];
        for (int i = 2, j = 0; i < primes.length; i++) {
            if (primes[i] > 0) {
                twinPrimes[j] = twinPrime(primes, i);
                if (twinPrimes[j][0] > 1) {
                    j++;
                }
            }
        }
        for (int i = 0; i < twinPrimes.length; i++) {
            if (twinPrimes[i][0] == 0) break;
            System.out.println(Arrays.toString(twinPrimes[i]));

        }

    }

    static boolean isPrime(int num) {
        boolean prime = true;
        for (int i = 2; i <= (num / 2); i++) {
            if (num % i == 0) {
                prime = false;
                break;
            }
        }
        return prime;
    }

    static int[] twinPrime(int[] primes, int prime) {
        if (primes[prime + 2] > 0) {
            return new int[]{prime, prime + 2};
        }
        return new int[]{0, 0};
    }
}

import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.api.complex.IComplexNumber;
import org.nd4j.linalg.factory.Nd4j;

public class Mean extends Sum {

    private INDArray inputArray;
    private IComplexNumber inputComplexArray;
    private double finalResult;
    private IComplexNumber finalResultComplex;

    public Mean(INDArray array) {
        this.inputArray = array;
        this.finalResult = calculateMean(array);
    }

    public Mean(IComplexNumber complexArray) {
        this.inputComplexArray = complexArray;
        this.finalResultComplex = calculateMean(complexArray);
    }

    public Mean(INDArray array1, INDArray array2) {
        this.inputArray = Nd4j.add(array1, array2);
        this.finalResult = calculateMean(this.inputArray);
    }

    public Mean(IComplexNumber complex1, IComplexNumber complex2) {
        this.inputComplexArray = complex1.add(complex2);
        this.finalResultComplex = calculateMean(inputComplexArray);
    }

    private double calculateMean(INDArray array) {
        double sum = sumArray(array);
        long count = array.length();
        return sum / count;
    }

    private IComplexNumber calculateMean(IComplexNumber complex) {
        IComplexNumber sum = sumComplex(complex);
        long count = 1; // To be updated based on actual array size if needed
        return sum.dividedBy(count);
    }

    private double sumArray(INDArray array) {
        return array.sumNumber().doubleValue();
    }

    private IComplexNumber sumComplex(IComplexNumber complex) {
        return complex; // Customize aggregation of complex numbers if needed
    }

    public double getFinalResult() {
        return finalResult;
    }

    public IComplexNumber getFinalResultComplex() {
        return finalResultComplex;
    }

    @Override
    public String toString() {
        return "Mean of the array is: " + finalResult;
    }

    public void printComplexMean() {
        System.out.println("Mean of complex numbers is: " + finalResultComplex);
    }

    public static void main(String[] args) {
        INDArray sampleArray = Nd4j.create(new double[]{1, 2, 3, 4, 5});
        Mean meanCalculator = new Mean(sampleArray);
        System.out.println(meanCalculator);

