        IComplexNumber complex2 = Nd4j.createComplex(4, 5);
        Mean complexMeanCalculator = new Mean(complex1, complex2);
        complexMeanCalculator.printComplexMean();
    }
}

 
public final class Pt {
    private final double x;
    private final double y;
    private static final double C = 7.0;
    private static final Pt ZERO = new Pt(Double.POSITIVE_INFINITY, Double.POSITIVE_INFINITY);
    private final boolean isZero;
    public final double getX() {
        return this.x;
    }
    public final double getY() {
        return this.y;
    }
    public final boolean getIsZero() {
        return this.isZero;
    }
    public Pt(double x, double y) {
        this.x = x;
        this.y = y;
        this.isZero = x > 1.0E20 || x < -1.0E20;
    }
    public final Pt dbl() {
        if (this.isZero) {
            return this;
        }
        double l = 3.0 * this.x * this.x / (2.0 * this.y);
        double t = l * l - 2.0 * this.x;
        return new Pt(t, l * (this.x - t) - this.y);
    }
    public final Pt unaryMinus() {
        return new Pt(this.x, -this.y);
    }
    public final Pt plus(Pt other) {
        if (this.x == other.x && this.y == other.y) {
            return this.dbl();
        }
        if (this.isZero) {
            return other;
        }
        if (other.isZero) {
            return this;
        }
        double l = (other.y - this.y) / (other.x - this.x);
        double t = l * l - this.x - other.x;
        return new Pt(t, l * (this.x - t) - this.y);
    }
    public final Pt times(int n) {
        Pt r = ZERO;
        Pt p = this;
        int i = 1;
        while (i <= n) {
            if ((i & n)!= 0) {
                r = r.plus(p);
            }
            p = p.dbl();
            i = i << 1;
        }
        return r;
    }
    public final String toString() {
        if (this.isZero) {
            return "Zero";
        }
        return "(" + String.format("%.3f", this.x) + ", " + String.format("%.3f", this.y) + ")";
    }
}
 
public final class MainKt {
    public static final double C = 7.0;
    public static final void main(String[] args) {
        Pt a = new Pt(1.0, Math.cbrt(1.0 * 1.0 - C));
        Pt b = new Pt(2.0, Math.cbrt(2.0 * 2.0 - C));
        Pt c = a.plus(b);
        Pt d = c.unaryMinus();
        System.out.println("a         = " + a);
        System.out.println("b         = " + b);
        System.out.println("c = a + b = " + c);
        System.out.println("d = -c    = " + d);
        System.out.println("c + d     = " + c.plus(d));
        System.out.println("a + b + d = " + a.plus(b.plus(d)));
        System.out.println("a * 12345 = " + a.times(12345));
    }
}

private void cacheNameInternal(INode inode) {

    if (inode.isDirectory()) {
      return;
    }
    ByteArray name = new ByteArray(inode.getLocalNameBytes());
    name = nameCache.put(name);
    if (name != null) {
      inode.setLocalName(name.getBytes());
    }
  }

import hudson.Extension;
import hudson.FilePath;
import hudson.Functions;
import hudson.model.Computer;
import hudson.remoting.Callable;
import jenkins.model.Jenkins;
import hudson.node_monitors.DiskSpaceMonitorDescriptor.DiskSpace;
import org.kohsuke.stapler.DataBoundConstructor;

import java.io.IOException;
import java.text.ParseException;

/**
 * Checks available disk space of the remote FS root.
 * Requires Mustang.
 *
 */
public class DiskSpaceMonitor extends AbstractDiskSpaceMonitor {
    @DataBoundConstructor
    public DiskSpaceMonitor(String freeSpaceThreshold) throws ParseException {
        super(freeSpaceThreshold);
    }

    public DiskSpaceMonitor() {}

    public DiskSpace getFreeSpace(Computer c) {
        return DESCRIPTOR.get(c);
    }

    @Override
    public String getColumnCaption() {
        // Hide this column from non-admins
        return Jenkins.getInstance().hasPermission(Jenkins.ADMINISTER) ? super.getColumnCaption() : null;
    }

    public static final DiskSpaceMonitorDescriptor DESCRIPTOR = new DiskSpaceMonitorDescriptor() {
        public String getDisplayName() {
            return Messages.DiskSpaceMonitor_DisplayName();
        }

        @Override
        protected Callable<DiskSpace, IOException> createCallable(Computer c) {
            FilePath p = c.getNode().getRootPath();
            if(p==null) return null;

            return p.asCallableWith(new GetUsableSpace());
        }
    };

    @Extension
    public static DiskSpaceMonitorDescriptor install() {
        if(Functions.isMustangOrAbove())    return DESCRIPTOR;
        return null;
    }
}

import akka.actor.ActorRef;
import akka.actor.ActorSystem;
import akka.actor.Props;
import akka.routing.RoundRobinPool;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.scheduling.annotation.Async;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.util.List;

@Service
@RequiredArgsConstructor(onConstructor_ = @Autowired)
public class BlogPostsFetcher {

    private final BlogRepository blogRepository;
    private final MetadataRepository metadataRepository;
    private final ActorSystem actorSystem;
    private final PreventConcurrentExecutionSafeguard safeguard;
    private final NowProvider nowProvider;

    @Async
    public void refreshPostsAsynchronously() {
        refreshPosts();
    }

    public void refreshPosts() {
        if (safeguard.isFetchingProcessInProgress()) {
            return;
        }
        safeguard.setFetchingProcessInProgress(true);
        startFetchingProcess();
        safeguard.setFetchingProcessInProgress(false);
    }

    private void startFetchingProcess() {
        List<String> rssLinks = blogRepository.getActiveBlogsRssLinks();
        ActorRef rssCheckingActor = actorSystem.actorOf(new RoundRobinPool(10).props(Props.create(RssCheckingActor.class)));
        ActorRef newBlogPostStoringActor = actorSystem.actorOf(Props.create(NewBlogPostStoringActor.class));

        rssLinks.forEach(rssLink -> rssCheckingActor.tell(new RssCheckingActor.CheckRssCommand(rssLink, newBlogPostStoringActor)));

        LocalDateTime now = nowProvider.now();
        metadataRepository.updateLastFetchTime(now);
    }
}

class RssCheckingActor extends AbstractLoggingActor {

    private final SyndFeedProducer syndFeedProducer;

    public RssCheckingActor(SyndFeedProducer syndFeedProducer) {
        this.syndFeedProducer = syndFeedProducer;
    }

    @Override
    public Receive createReceive() {
        return receiveBuilder()
                .match(CheckRssCommand.class, command -> {
                    var feed = syndFeedProducer.getFeed(command.rssLink);
                    command.storingActor.tell(new NewBlogPostStoringActor.StorePostsCommand(feed));
                })
                .build();
    }

    static class CheckRssCommand {
        final String rssLink;
        final ActorRef storingActor;

        public CheckRssCommand(String rssLink, ActorRef storingActor) {
            this.rssLink = rssLink;
            this.storingActor = storingActor;
        }
    }
}

