public class XmlReader {
 
    public static void main(String[] args) {
        try {
            // Either read the xml from a string...
            StringReader XReader = new StringReader("<inventory title=... </inventory>");
 
            //... or read it from the file system.
            //XReader = XmlReader.Create("xmlfile.xml");
 
            // Create a XPathDocument object (which implements the IXPathNavigable interface)
            // which is optimized for XPath operation. (very fast).
            DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
            DocumentBuilder db = dbf.newDocumentBuilder();
            Document doc = db.parse(new InputSource(XReader));
 
            // Create a Navigator to navigate through the document.
            XPath xpath = XPathFactory.newInstance().newXPath();
            NodeList nodes = (NodeList) xpath.evaluate("//item", doc, XPathConstants.NODESET);
 
            // Move to the first element of the selection. (if available).
            if (nodes.getLength() > 0) {
                System.out.println(nodes.item(0).getTextContent()); // The outer xml of the first item element.
            }
 
            // Get an iterator to loop over multiple selected nodes.
            NodeList nodes2 = (NodeList) xpath.evaluate("//price", doc, XPathConstants.NODESET);
 
            for (int i = 0; i < nodes2.getLength(); i++) {
                System.out.println(nodes2.item(i).getTextContent());
            }
 
            NodeList nodes3 = (NodeList) xpath.evaluate("//name", doc, XPathConstants.NODESET);
 
            // Use a generic list.
            List<String> NodesValues = new ArrayList<String>();
 
            for (int i = 0; i < nodes3.getLength(); i++) {
                NodesValues.add(nodes3.item(i).getTextContent());
            }
 
            // Convert the generic list to an array and output the count of items.
            System.out.println(NodesValues.toArray().length);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

