public class Tree {
    public int minimumXOR(int num1, int num2) {
        int xor = num1 ^ num2;
        int setBits = Integer.bitCount(xor);
        int x = 0;
        for (int i = 30; i >= 0 && setBits > 0; i--) {
            if (((xor >> i) & 1) == 1) {
                x |= (1 << i);
                setBits--;
            }
        }
        return x;
    }
}

public static boolean isSubtype(Type s, Type t, VisitorState state) {
    if (s == null || t == null) {
      return false;
    }
    if (SUBTYPE_UNDEFINED.contains(s.getTag()) || SUBTYPE_UNDEFINED.contains(t.getTag())) {
      return false;
    }
    Types types = state.getTypes();
    return types.isSubtype(types.erasure(s), types.erasure(t));
  }

public static double[] getRightmostLowestPoint(double[][] points) {
    double[] result = points[0]; // initialize result to the first point
    for (int i = 1; i < points.length; i++) {
        double[] currentPoint = points[i];
        if (currentPoint[1] < result[1] || (currentPoint[1] == result[1] && currentPoint[0] > result[0])) {
            result = currentPoint;
        }
    }
    return result;
}
