public class Logger {
    public static void main(String[] args) {
        //Test

        String binaryString1 = "1010";
        String binaryString2 = "1014";
        try {

            System.out.println("Binary number: " + binaryString1 + " converted to decimal is " + bin2Dec(binaryString1));
            System.out.println("Binary number: " + binaryString2 + " converted to decimal is " + bin2Dec(binaryString2));

        } catch (NumberFormatException numberFormatException) {
            System.out.println(numberFormatException);
        }
    }

    public static int bin2Dec(String binaryString) {
        int decimalValue = 0;
        if (!checkBinaryChars(binaryString)) {
            throw new BinaryFormatException(binaryString);
        }
        char[] binChars = binaryString.toCharArray();

        for (int i = binChars.length - 1, binaryIndex = 0; i >= 0; i--, binaryIndex++) {
            decimalValue += getBinaryValue(binChars[i], binaryIndex);
        }

        return decimalValue;
    }

    static boolean checkBinaryChars(String binaryString) {
        char[] binStrValues = binaryString.toCharArray();
        for (char c : binStrValues) {
            if (c != '0' && c != '1') {
                return false;
            }
        }
        return true;
    }

    static int getBinaryValue(char binaryChar, int index) {
        int weight = (int) Math.pow(2, index);
        if (binaryChar == '1') {
            return weight;
        }
        return 0;
    }

}

import java.util.ArrayList;
import java.util.List;
 
public class AbundantOddNumbers {
    private static List<Integer> list = new ArrayList<>();
    private static List<Integer> result = new ArrayList<>();
 
    public static void main(String[] args) {
        System.out.println("First 25: ");
        abundantOdd(1,100000, 25, false);
 
        System.out.println("\n\nThousandth: ");
        abundantOdd(1,2500000, 1000, true);
 
        System.out.println("\n\nFirst over 1bn:");
        abundantOdd(1000000001, 2147483647, 1, false);
    }
    private static void abundantOdd(int start, int finish, int listSize, boolean printOne) {
        for (int oddNum = start; oddNum < finish; oddNum += 2) {
            list.clear();
            for (int toDivide = 1; toDivide < oddNum; toDivide+=2) {
                if (oddNum % toDivide == 0)
                    list.add(toDivide);
            }
            if (sumList(list) > oddNum) {
                if(!printOne)
                    System.out.printf("%5d <= %5d \n",oddNum, sumList(list) );
                result.add(oddNum);
            }
            if(printOne && result.size() >= listSize)
                System.out.printf("%5d <= %5d \n",oddNum, sumList(list) );
 
            if(result.size() >= listSize) break;
        }
    }
    private static int sumList(List list) {
        int sum = 0;
        for (int i = 0; i < list.size(); i++) {
            String temp = list.get(i).toString();
            sum += Integer.parseInt(temp);
        }
        return sum;
    }
}

import java.net.HttpURLConnection;

public class GetOpParam {

  private static final String NAME = "op";

  public enum Op {
    OPEN(true, HttpURLConnection.HTTP_OK, true),
    GETFILESTATUS(false, HttpURLConnection.HTTP_OK, false),
    LISTSTATUS(false, HttpURLConnection.HTTP_OK, true),
    GETCONTENTSUMMARY(false, HttpURLConnection.HTTP_OK, false),
    GETFILECHECKSUM(true, HttpURLConnection.HTTP_OK, false),
    GETHOMEDIRECTORY(false, HttpURLConnection.HTTP_OK, false),
    GETDELEGATIONTOKEN(false, HttpURLConnection.HTTP_OK, false),
    GETTRASHROOT(false, HttpURLConnection.HTTP_OK, false);

    private final boolean redirect;
    private final int expectedHttpResponseCode;
    private final boolean doOutput;

    Op(final boolean redirect, final int expectedHttpResponseCode, final boolean doOutput) {
      this.redirect = redirect;
      this.expectedHttpResponseCode = expectedHttpResponseCode;
      this.doOutput = doOutput;
    }

    public boolean getRedirect() {
      return redirect;
    }

    public int getExpectedHttpResponseCode() {
      return expectedHttpResponseCode;
    }

    public boolean getDoOutput() {
      return doOutput;
    }
  }

  private static final Domain<Op> DOMAIN = new Domain<>(NAME, Op.class);

  private final Op value;

  public GetOpParam(final String str) {
    this.value = DOMAIN.parse(str);
  }

  public String getName() {
    return NAME;
  }

  public Op getType() {
    return value;
  }

  @Override
  public String toString() {
    return DOMAIN.toString(value);
  }

  public String toQueryString() {
    return NAME + "=" + value;
  }

  private static class Domain<T extends Enum<T>> {
    private final String name;
    private final Class<T> enumClass;

    Domain(String name, Class<T> enumClass) {
      this.name = name;
      this.enumClass = enumClass;
    }

    public T parse(String str) {
      try {
        return Enum.valueOf(enumClass, str.toUpperCase());
      } catch (IllegalArgumentException e) {
        throw new IllegalArgumentException(
            "Invalid value for " + name + ": " + str +
                ". Valid values are: " + java.util.Arrays.asList(enumClass.getEnumConstants()));
      }
    }

    public String toString(T value) {
      return value.name().toLowerCase();
    }
  }
}

public class Order {
    int counter=0;
    public int findTargetSumWays(int[] a, int s) {
        findSum(a, a.length-1, s);
        return counter;
    }
    void findSum(int[] a, int i, int s) {
        if(i==0) {
            if(s+a[i]==0)counter++;
            if(s-a[i]==0)counter++;
            return;
        }
        findSum(a, i-1, s+a[i]);
        findSum(a, i-1, s-a[i]);
    }

}

