    public MovablePoint(int x, int y, int xSpeed, int ySpeed) {
        this.x = x;
        this.y = y;
        this.xSpeed = xSpeed;
        this.ySpeed = ySpeed;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int getxSpeed() {
        return xSpeed;
    }

    public void setxSpeed(int xSpeed) {
        this.xSpeed = xSpeed;
    }

    public int getySpeed() {
        return ySpeed;
    }

    public void setySpeed(int ySpeed) {
        this.ySpeed = ySpeed;
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ") speed=" + xSpeed + "," + ySpeed + ')';
    }

    @Override
    public void moveUp() {
       this.y-=this.ySpeed;
    }

    @Override
    public void moveDown() {
        this.y+=this.ySpeed;
    }

    @Override
    public void moveLeft() {
        this.x-=this.xSpeed;
    }

    @Override
    public void moveRight() {
        this.x+=this.xSpeed;
    }
}

import com.google.common.collect.ImmutableList;
import com.streamsets.pipeline.api.Record;
import com.streamsets.pipeline.api.StageException;
import com.streamsets.pipeline.config.DataFormat;
import com.streamsets.pipeline.lib.mqtt.Errors;
import com.streamsets.pipeline.lib.mqtt.MqttClientConfigBean;
import com.streamsets.pipeline.sdk.PushSourceRunner;
import com.streamsets.pipeline.sdk.StageRunner;
import com.streamsets.pipeline.stage.origin.lib.DataParserFormatConfig;
import org.junit.Assert;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.UUID;

public class TestMqttClientSource {

  @Test
  public void testSource() throws Exception {
    MqttClientConfigBean commonConf = new MqttClientConfigBean();
    commonConf.brokerUrl = "tcp://localhost:1833";
    commonConf.clientId = UUID.randomUUID().toString();

    MqttClientSourceConfigBean subscriberConf = new MqttClientSourceConfigBean();
    subscriberConf.topicFilters = ImmutableList.of("sample/topic");
    subscriberConf.dataFormat = DataFormat.JSON;
    subscriberConf.dataFormatConfig = new DataParserFormatConfig();

    MqttClientSource source = new MqttClientSource(commonConf, subscriberConf);
    PushSourceRunner runner = new PushSourceRunner
        .Builder(MqttClientDSource.class, source)
        .addOutputLane("a").build();

    runner.runInit();
    try {
      List<Record> records = new ArrayList<>();
      runner.runProduce(Collections.<String, String>emptyMap(), 1, new PushSourceRunner.Callback() {
        @Override
        public void processBatch(StageRunner.Output output) {
          records.clear();
          records.addAll(output.getRecords().get("a"));
          runner.setStop();
        }
      });
      runner.waitOnProduce();
    } catch (Exception ex) {
      Assert.assertNotNull(ex.getCause());
      Assert.assertNotNull(ex.getCause().getCause());
      StageException stageException = (StageException) ex.getCause().getCause();
      Assert.assertNotNull(stageException.getErrorCode());
      Assert.assertEquals(stageException.getErrorCode(), Errors.MQTT_04);
    } finally {
      runner.runDestroy();
    }
  }

}

import java.io.FileOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import org.apache.commons.net.ftp.FTP;
import org.apache.commons.net.ftp.FTPClient;
import org.apache.commons.net.ftp.FTPFile;
import org.apache.commons.net.ftp.FTPReply;
 
public class FTPconn {
 
    public static void main(String[] args) throws IOException {
        String server = "ftp.hq.nasa.gov";
        int port = 21;
        String user = "anonymous";
        String pass = "ftptest@example.com";
 
        OutputStream output = null;
 
        FTPClient ftpClient = new FTPClient();
        try {
            ftpClient.connect(server, port);
 
            serverReply(ftpClient);
 
            int replyCode = ftpClient.getReplyCode();
            if (!FTPReply.isPositiveCompletion(replyCode)) {
                System.out.println("Failure. Server reply code: " + replyCode);
                return;
            }
 
            serverReply(ftpClient);
 
            if (!ftpClient.login(user, pass)) {
                System.out.println("Could not login to the server.");
                return;
            }
 
            String dir = "pub/issoutreach/Living in Space Stories (MP3 Files)/";
            if (!ftpClient.changeWorkingDirectory(dir)) {
                System.out.println("Change directory failed.");
                return;
            }
 
            ftpClient.enterLocalPassiveMode();
 
            for (FTPFile file : ftpClient.listFiles())
                System.out.println(file);
 
            String filename = "Can People go to Mars.mp3";
            output = new FileOutputStream(filename);
 
            ftpClient.setFileType(FTP.BINARY_FILE_TYPE);
            if (!ftpClient.retrieveFile(filename, output)) {
                System.out.println("Retrieving file failed");
                return;
            }
 
            serverReply(ftpClient);
 
            ftpClient.logout();
 
        } finally {
            if (output != null)
                output.close();
        }
    }
 
    private static void serverReply(FTPClient ftpClient) {
        for (String reply : ftpClient.getReplyStrings()) {
            System.out.println(reply);
        }
    }
}

public Object eval(ScriptContext scriptContext) throws ScriptException {
        if (this.compiledScript == null) {
            if (LOGGER.isDebugEnabled()) {
                LOGGER.debug("No compiled script available, invoking ScriptEngine.eval(String, ScriptContext) for script:\n" + this.script);
            }
            return this.scriptEngine.eval(this.script, scriptContext);
        }
        try {
            if (LOGGER.isDebugEnabled()) {
                LOGGER.debug("Compiled script available, invoking CompiledScript.eval(ScriptContext) for script:\n" + this.script);
            }
            return evalCompiledScriptWithContextMethod.invoke(this.compiledScript, scriptContext);
        }
        catch (Exception e) {
            if (e instanceof ScriptException) {
                throw (ScriptException)e;
            }

            throw new ScriptException(e);
        }
    }

import org.apache.jena.arq.junit.manifest.ManifestEntry;
import org.apache.jena.atlas.io.IndentedLineBuffer ;
import org.apache.jena.query.Query ;
import org.apache.jena.query.Syntax ;
import org.apache.jena.sparql.sse.SSE_ParseException ;
import org.apache.jena.sparql.util.QueryUtils ;

public class SerializationTest implements Runnable
{
    static int count = 0 ;
    String queryString ;
    ManifestEntry testEntry;

    public SerializationTest(ManifestEntry entry) {
        testEntry = entry ;
    }
    // A serialization test is:
    //   Read query in.
    //   Serialize to string.
    //   Parse again.
    //   Are they equal?

    @Override
    public void run()
    {
        Query query = SparqlTestLib.queryFromEntry(testEntry);
        // Whatever was read in.
        runTestWorker(query, query.getSyntax()) ;
    }

    protected void runTestWorker(Query query, Syntax syntax)
    {
        IndentedLineBuffer buff = new IndentedLineBuffer() ;
        query.serialize(buff, syntax) ;
        String baseURI = null ;

        if ( ! query.explicitlySetBaseURI() )
            // Not in query - use the same one (e.g. file read from) .
            baseURI = query.getBaseURI() ;

        // Query syntax and algebra tests.

        try {
            QueryUtils.checkParse(query) ;
        }
        catch (RuntimeException ex)
        {
            System.err.println("**** Test: "+testEntry.getName()) ;
            System.err.println("** "+ex.getMessage()) ;
            System.err.println(query) ;
            throw ex ;
        }

        try {
            QueryUtils.checkOp(query, true) ;
        } catch (SSE_ParseException ex)
        {
            System.err.println("**** Test: "+testEntry.getName()) ;
            System.err.println("** Algebra error: "+ex.getMessage()) ;
        }
    }
}

import net.imagej.ops.Ops;
import net.imagej.ops.create.CreateImg;
import net.imagej.ops.special.function.AbstractUnaryFunctionOp;
import net.imagej.ops.special.function.Functions;
import net.imagej.ops.special.function.UnaryFunctionOp;
import net.imglib2.Dimensions;
import net.imglib2.Interval;
import net.imglib2.img.Img;
import net.imglib2.type.numeric.real.DoubleType;
import org.scijava.plugin.Plugin;

@Plugin(type = Ops.Create.Img.class)
public class CreateImgFromInterval<I extends Interval>
        extends AbstractUnaryFunctionOp<I, Img<DoubleType>> {

    private UnaryFunctionOp<Dimensions, Img<DoubleType>> createImgOp;

    @Override
    public void initialize() {
        createImgOp = Functions.unary(ops(), CreateImg.class,
                Img.class, Dimensions.class, new DoubleType());
    }

    @Override
    public Img<DoubleType> calculate(final I input) {
        return createImgOp.calculate(input);
    }

    public static <I extends Interval> Img<DoubleType> create(
            final I input, final CreateImgFromInterval<I> op) {
        return op.calculate(input);
    }

    public static <I extends Interval> Img<DoubleType> create(
            final I input, final UFViaUFSameIO<I, Img<DoubleType>> op)
    {
        return op.inOut(input);
    }
}

class UFViaUFSameIO<I, O> extends AbstractUnaryFunctionOp<I, O> {

    private final UnaryFunctionOp<I, O> worker;

    public UFViaUFSameIO(final UnaryFunctionOp<I, O> worker) {
        this.worker = worker;
    }

    @Override
    public O calculate(final I input) {
        return worker.calculate(input);
    }
    public O inOut(I input){
        return calculate(input);
    }
    UnaryFunctionOp<I, O> createWorker(){
        return worker;
    }
}

