import java.util.Arrays;
 
public class Finder {
    public static void main(String[] args) {
        String[] strings = new String[]{"Here", "are", "some", "sample", "strings", "to", "be", "sorted"};
 
        printArray("Unsorted:", strings);
 
        Arrays.sort(strings, (first, second) -> {
            int lengthDifference = second.length() - first.length();
            if (lengthDifference == 0) {
                return first.toLowerCase().compareTo(second.toLowerCase());
            } else {
                return lengthDifference;
            }
        });
 
        printArray("Sorted:", strings);
    }
 
    private static void printArray(String message, String[] array) {
        System.out.print(message + " [");
        for (int i = 0; i < array.length; i++) {
            String string = array[i];
            if (i == array.length - 1) {
                System.out.print(string);
            } else {
                System.out.print(string + ", ");
            }
        }
        System.out.println("]");
    }
}

public int waitForProcess(Process process, Thread outputThread, Thread errorThread) throws InterruptedException {
