public class Validator {
    public int maxProduct(int[] nums) {
        int n = nums.length;
        int first = Math.max(nums[0], nums[1]);
        int second = Math.min(nums[0], nums[1]);
        int max = first;

        for(int i=2; i<n; i++){
            if(nums[i] > first){
                second = first;
                first = nums[i];
            }else if(nums[i] > second){
                second = nums[i];
            }
            max = Math.max(max, first*second);
        }
        return max;
    }
}

