public class RSA {
 
    public static void main(String[] args) {
        BigInteger n = new BigInteger("9516311845790656153499716760847001433441357");
        BigInteger e = new BigInteger("65537");
        BigInteger d = new BigInteger("5617843187844953170308463622230283376298685");
 
        String message = "Rosetta Code!";
        System.out.println("message                 " + message);
 
        String hex_data = new BigInteger(message.getBytes()).toString(16);
        System.out.println("hex data                " + hex_data);
 
        BigInteger plain_text = new BigInteger(hex_data, 16);
        System.out.println("plain text integer      " + plain_text);
 
        if (plain_text.compareTo(n) > 0) {
            throw new RuntimeException("plain text too large for key");
        }
 
        BigInteger encrypted_text = plain_text.modPow(e, n);
        System.out.println("encrypted text integer  " + encrypted_text);
 
        BigInteger decrypted_text = encrypted_text.modPow(d, n);
        System.out.println("decrypted text integer  " + decrypted_text);
 
        System.out.println("message                 " + new String(decrypted_text.toByteArray()));
    }
}

import java.io.File;
