import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
 
public class OrderDisjointListItems {
 
    public static void orderDisjointListItems(List<String> data, List<String> items) {
        //Modifies data list in-place
        List<Integer> itemindices = new ArrayList<Integer>();
        Set<String> itemSet = new TreeSet<String>(items);
        for (String item : itemSet) {
            int itemcount = 0;
            for (String s : items) {
                if (s.equals(item)) {
                    itemcount++;
                }
            }
            //assert data.count(item) >= itemcount, 'More of %r than in data' % item
            int lastindex = -1;
            for (int i = 0; i < itemcount; i++) {
                lastindex = data.indexOf(item, lastindex + 1);
                itemindices.add(lastindex);
            }
        }
        java.util.Collections.sort(itemindices);
        for (int i = 0; i < itemindices.size(); i++) {
            data.set(itemindices.get(i), items.get(i));
        }
    }
 
    public static void main(String[] args) {
        String tostring = " ";
        List<String> data = new ArrayList<String>();
        List<String> items = new ArrayList<String>();
        data.add("the");
        data.add("cat");
        data.add("sat");
        data.add("on");
        data.add("the");
        data.add("mat");
        items.add("mat");
        items.add("cat");
        System.out.print("Data M: " + tostring + " Order N: " + tostring + " ");
        orderDisjointListItems(data, items);
        System.out.println("-> M' " + tostring);
    }
}

import java.text.ParseException;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Clock time holder formatted as HH:mm:ss.
 */
public class Time {
    private int hour;
    private int minute;
    private int second;

    public Time(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public void setHour(int hour) {
        this.hour = hour;
    }

    public int getMinute() {
        return minute;
    }

    public void setMinute(int minute) {
        this.minute = minute;
    }

    public int getSecond() {
        return second;
    }

    public void setSecond(int second) {
        this.second = second;
    }

    public void setTime(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public Time nextSecond() {
        second = second + 1;
        return this;
    }

    public Time previousSecond() {
        second = second - 1;
        return this;
    }

    @Override
    public String toString() {
        String raw = hour + ":" + minute + ":" + second;
        Date parsed = null;
        try {
            parsed = new SimpleDateFormat("HH:mm:ss").parse(raw);
        } catch (ParseException ex) {
            Logger.getLogger(Time.class.getName()).log(Level.SEVERE, null, ex);
        }
        return new SimpleDateFormat("HH:mm:ss").format(parsed);
    }
}

class TestTime {
    public static void main(String[] args) {
        Time t1 = new Time(1, 2, 3);
        System.out.println(t1);

        t1.setHour(4);
        t1.setMinute(5);
        t1.setSecond(6);
        System.out.println(t1);
        System.out.println("Hour: " + t1.getHour());
        System.out.println("Minute: " + t1.getMinute());
        System.out.println("Second: " + t1.getSecond());

        t1.setTime(23, 59, 58);
        System.out.println(t1);

        System.out.println(t1.nextSecond());
        System.out.println(t1.nextSecond().nextSecond());

        System.out.println(t1.previousSecond());
        System.out.println(t1.previousSecond().previousSecond());
    }
}

import java.util.Random;

public class Barbero2 {
    private int n; // Number of barbers
    private int countClientes; // Current number of clients being served
    private final int cantMax = 5; // Maximum number of clients
    private final int cantMin = 0; // Minimum number of clients
    private Random rand; // Random number generator for delays

    public Barbero2(int n) {
        this.n = n;
        this.countClientes = 0;
        this.rand = new Random();
    }

    public synchronized void sentarCliente() {
        while (countClientes >= cantMax) {
            System.out.println("Barberia llena, cliente esperando...");
            try {
                wait();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        countClientes++;
        System.out.println("Cliente sentado. Clientes siendo atendidos: " + countClientes);
        notifyAll();
    }

    public synchronized void afeitar() {
        if (countClientes <= cantMin) {
            System.out.println("No hay clientes para afeitar.");
            return;
        }
        System.out.println("Afeitando cliente...");
        try {
            Thread.sleep(rand.nextInt(2000) + 1000); // Simulate shaving time (1-3 seconds)
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        System.out.println("Cliente afeitado.");
    }

    public synchronized void cobrar() {
        if (countClientes <= cantMin) {
            System.out.println("No hay clientes para cobrar.");
            return;
        }
        System.out.println("Cobrando al cliente...");
        try {
            Thread.sleep(rand.nextInt(1000) + 500); // Simulate billing time (0.5-1.5 seconds)
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        countClientes--;
        System.out.println("Cliente cobrado. Clientes siendo atendidos: " + countClientes);
        notifyAll();
    }

