public class Student {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    for (int i = 0; i < n; i++) {
        int[] scores = new int[4];
        boolean[] seen = new boolean[4];
        for (int j = 0; j < scores.length; j++) {
            scores[j] = sc.nextInt();
        }
        for (int j = 0; j < scores.length; j++) {
            seen[j] = false;
        }
        int max = -1;
        int maxIndex = -1;
        for (int j = 0; j < scores.length; j++) {
            if (scores[j] > max) {
                max = scores[j];
                maxIndex = j;
            }
        }
        for (int j = 0; j < scores.length; j++) {
            if (scores[j] != max && !seen[j]) {
                System.out.println("NO");
                break;
            }
        }
        if(j == scores.length) {
            System.out.println("YES");
        }
    }
  }
}

private ITableMetaData mergeTableMetaData(List<Column> columnsToMerge, ITableMetaData originalMetaData) throws DataSetException {
        Column[] columns = new Column[originalMetaData.getColumns().length + columnsToMerge.size()];
        System.arraycopy(originalMetaData.getColumns(), 0, columns, 0, originalMetaData.getColumns().length);
        for (int i = 0; i < columnsToMerge.size(); i++) {
            Column column = columnsToMerge.get(i);
            columns[columns.length - columnsToMerge.size() + i] = column;
        }
        return new DefaultTableMetaData(originalMetaData.getTableName(), columns);
    }

public class AttractiveNumbers {
    private static final int MAX = 120;

    private static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }

    private static int countPrimeFactors(int n) {
        if (n == 1) return 0;
        if (isPrime(n)) return 1;
        int nn = n;
        int count = 0;
        int f = 2;
        while (true) {
            if (nn % f == 0) {
                count++;
                nn /= f;
                if (nn == 1) break;
                if (isPrime(nn)) f = nn;
            } else if (f >= 3) {
                f += 2;
            } else {
                f = 3;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        System.out.println("The attractive numbers up to and including " + MAX + " are:");
        int count = 0;
        for (int i = 1; i <= MAX; i++) {
            int n = countPrimeFactors(i);
            if (isPrime(n)) {
                System.out.printf("%4d", i);
                if (++count % 20 == 0) System.out.println();
            }
        }
        System.out.println();
    }
}

