        return sharedSetId;
    }

    public void setSharedSetId(Long sharedSetId) {
        this.sharedSetId = sharedSetId;
    }

    @XmlElement(name = "criterion")
    public Criterion getCriterion() {
        return criterion;
    }

    public void setCriterion(Criterion criterion) {
        this.criterion = criterion;
    }

    @XmlElement(name = "isNegative")
    public boolean isNegative() {
        return negative;
    }

    public void setNegative(boolean negative) {
        this.negative = negative;
    }

    // Additional boilerplate methods (equals/hashCode/toString) would typically follow
    // but are omitted per line count constraint
}

