    }
}

import java.util.Scanner;

public class pb5 {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        while (t--> 0){

            int n = sc.nextInt();

            if (n <= 3){

                System.out.println(-1);

                continue;

            }

            int temp = (n % 2 == 0  ? n-1 : n);

            while (temp > 0){

                System.out.print(temp + " ");

                temp -= 2;

            }

            System.out.print(4 + " ");

            System.out.print(2 + " ");

            temp = 6;

            while (temp <= n){

                System.out.print(temp + " ");

                temp += 2;

            }

            System.out.println();

        }

    }

}

