import java.util.*;

import java.lang.*;

import java.io.*;

public class Solution

{

    PrintWriter out = new PrintWriter(System.out);

    BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

    StringTokenizer tok = new StringTokenizer("");

    String next() throws IOException {

        if (!tok.hasMoreTokens()) { tok = new StringTokenizer(in.readLine()); }

        return tok.nextToken();

    }

    int ni() throws IOException { return Integer.parseInt(next()); }

    long nl() throws IOException { return Long.parseLong(next()); }

    int[] na(int n) throws IOException { int[]A=new int[n]; for (int i=0;i<n;i++) A[i]=ni(); return A; }

    long mod=1000000007;

    void solve() throws IOException {

        //for (int tc=ni();tc>0;tc--) {

            int n=ni();

            int lt=query(1);

            int rt=query(n);

            int mid=n;

            int mv=rt;

            if (lt<rt) { mid=1; mv=lt; }

            //int lv=lt;

            //int rv=rt;

            lt=1;

            rt=n;

            while (lt+1<mid || rt-1>mid) {

                if (mid-lt<rt-mid) {

                    int nr=(mid+rt)/2;

                    int nv=query(nr);

                    if (nv<mv) { mv=nv; lt=mid; mid=nr; }

                    else rt=nr;

                }

                else {

                    int nr=(mid+lt)/2;

                    int nv=query(nr);

                    if (nv<mv) { mv=nv; rt=mid; mid=nr; }

                    else lt=nr;

                }

            }

            out.println("! "+mid);

        //}

        out.flush();

    }

    int query(int a) throws IOException {

        out.println("? "+a);

        out.flush();

        return ni();

    }

    int gcd(int a,int b) { return(b==0?a:gcd(b,a%b)); }

    long gcd(long a,long b) { return(b==0?a:gcd(b,a%b)); }

    long mp(long a,long p) { long r=1; while(p>0) { if ((p&1)==1) r=(r*a)%mod; p>>=1; a=(a*a)%mod; } return r; }

    public static void main(String[] args) throws IOException {

        new Solution().solve();

    }

}

import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.Arrays;

public class Timer {
    public static void main(String[] args) {
        BigInteger maxLongVal = BigInteger.valueOf(Long.MAX_VALUE);
        int count = 0;
        long rootNum = (long) Math.sqrt(maxLongVal.doubleValue());
        BigInteger root = BigInteger.valueOf(rootNum);
        BigInteger[] result = new BigInteger[10];
        while (count < 10) {
            root = root.add(BigInteger.ONE);
            BigInteger n2 = root.pow(2);
            if (n2.compareTo(maxLongVal) > 0) {
                result[count] = n2;
                count++;
            }

        }
        System.out.println("Long.MAX_VALUE = " + Long.MAX_VALUE);
        System.out.println("The square numbers greater than Long.MAX_VALUE are: ");
        System.out.println(Arrays.toString(result));

    }
}

import java.net.URI;
import java.net.URISyntaxException;
public class WebAddressParser{
    public static void main(String[] args){
        parseAddress("foo://example.com:8042/over/there?name=ferret#nose");
        parseAddress("urn:example:animal:ferret:nose");
    }
 
    static void parseAddress(String a){
        System.out.println("Parsing " + a);
        try{
 
            // this line does the work
            URI u = new URI(a);
 
            System.out.println("\tscheme = " + u.getScheme());
            System.out.println("\tdomain = " + u.getHost());
            System.out.println("\tport = " + (-1==u.getPort()?"default":u.getPort()));
            System.out.println("\tpath = " + (null==u.getPath()?u.getSchemeSpecificPart():u.getPath()));
            System.out.println("\tquery = " + u.getQuery());
            System.out.println("\tfragment = " + u.getFragment());
        }
        catch (URISyntaxException x){
            System.err.println("Oops: " + x);
        }
    }
}

import org.junit.Before;
import org.junit.Ignore;
import org.junit.Test;
import org.sakaiproject.importer.api.ImportFileParser;
import org.sakaiproject.importer.api.ImportDataSource;
import org.sakaiproject.importer.impl.importables.Assessment;
import org.sakaiproject.importer.impl.importables.HtmlDocument;
import lombok.extern.slf4j.Slf4j;

import java.io.InputStream;
import java.util.List;
import java.util.stream.Collectors;

import static org.junit.Assert.assertTrue;

@Slf4j
@Ignore
public class CommonCartridgeTest {

    private ImportFileParser parser;
    private InputStream archiveStream;

    @Before
    public void setUp() {
        parser = new CommonCartridgeFileParser();
        archiveStream = getClass().getClassLoader().getResourceAsStream("psychology.zip");
    }

    @Test
    public void testIsValidArchive() {
        boolean isValid = parser.isValidArchive(archiveStream);
        assertTrue("The archive should be valid", isValid);
        log.info("Archive validation test passed.");
    }

    @Test
    public void testCanGetQti() {
        ImportDataSource dataSource = parser.parse(archiveStream, "psychology.zip");
        List<Assessment> assessments = dataSource.getItems().stream()
                .filter(item -> item instanceof Assessment)
                .map(item -> (Assessment) item)
                .collect(Collectors.toList());

        List<HtmlDocument> htmlDocuments = dataSource.getItems().stream()
                .filter(item -> item instanceof HtmlDocument)
                .map(item -> (HtmlDocument) item)
                .collect(Collectors.toList());

        log.info("Parsed {} assessments and {} HTML documents.", assessments.size(), htmlDocuments.size());
        assertTrue("At least one assessment should be present", assessments.size() > 0);
    }
}

