@WebServlet("/BenchmarkTest11696")
public class BenchmarkTest11696 extends HttpServlet {
    private static final long serialVersionUID = 1L;

    @Override
    public void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        doPost(request, response);
    }

    @Override
    public void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String param = request.getParameter("foo");
        String bar = new Program().doSomething(param);

        String startURIslashes = "";
        try {
            startURIslashes = System.getProperty("os.name").indexOf("Windows") > -1 ? "\\\\" : "//";
        } catch (Exception localException) {
            response.getWriter().println("Error: " + localException.toString());
        }

        String target = startURIslashes + "localhost:8080/Benchmark/resources/images/" + bar;
        try {
            URI fileURI = new URI(target);
            File fileTarget = new File(fileURI);
            response.getWriter().println("Access to file: " + fileTarget.getAbsolutePath());
        } catch (URISyntaxException e) {
            response.getWriter().println("Invalid URI: " + target);
        } catch (Exception e) {
            response.getWriter().println("Unexpected exception: " + e.toString());
        }
    }

    private class Program {
        public String doSomething(String param) {
            StringBuilder sb = new StringBuilder(param);
            sb.append("_SafeStuff");
            return sb.toString();
        }
    }
}

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.function.Supplier;
import java.util.stream.Stream;
 
public class IntersectingNumberWheels {
 
    private final Map<String, Supplier<Integer>> isect;
 
    public IntersectingNumberWheels(Map<String, Integer[]> wheels) {
        this.isect = new HashMap<>();
        for (Map.Entry<String, Integer[]> entry : wheels.entrySet()) {
            String name = entry.getKey();
            Integer[] wheel = entry.getValue();
            this.isect.put(name, this.wstate(name, wheel));
        }
    }
 
    private Supplier<Integer> wstate(String name, Integer[] wheel) {
        int pos = 0;
        int ln = wheel.length;
        return () -> {
            Integer nxt = wheel[pos % ln];
            pos++;
            if (nxt instanceof String) {
                return this.isect.get(nxt).get();
            } else {
                return nxt;
            }
        };
    }
 
    public Iterator<Integer> iterator() {
        return new Iterator<Integer>() {
            @Override
            public boolean hasNext() {
                return true;
            }
 
            @Override
            public Integer next() {
                return isect.get(isect.keySet().iterator().next()).get();
            }
        };
    }
 
    public static void main(String[] args) {
        Map<String, Integer[]> group = new HashMap<>();
        group.put("A", new Integer[]{1, 2, 3});
        System.out.println(new IntersectingNumberWheels(group));
        System.out.println("  Generates:");
        System.out.println("    " + Stream.generate(() -> group.get("A")[0]).limit(20).reduce("", (a, b) -> a + " " + b));
 
        group.put("A", new Integer[]{1, "B".hashCode(), 2});
        group.put("B", new Integer[]{3, 4});
        System.out.println(new IntersectingNumberWheels(group));
        System.out.println("  Generates:");
        System.out.println("    " + Stream.generate(() -> group.get("A")[0]).limit(20).reduce("", (a, b) -> a + " " + b));
 
        group.put("A", new Integer[]{1, "D".hashCode(), "D".hashCode()});
        group.put("D", new Integer[]{6, 7, 8});
        System.out.println(new IntersectingNumberWheels(group));
        System.out.println("  Generates:");
        System.out.println("    " + Stream.generate(() -> group.get("A")[0]).limit(20).reduce("", (a, b) -> a + " " + b));
 
        group.put("A", new Integer[]{1, "B".hashCode(), "C".hashCode()});
        group.put("B", new Integer[]{3, 4});
        group.put("C", new Integer[]{5, "B".hashCode()});

/**
 * Implementation of DataRow that is backed by primitive arrays. Should always
 * be used if more than 50% of the data is sparse. As fast (or even faster than
 * map implementation) but needs considerably less memory. This implementation uses
 * float arrays instead of double arrays which might reduce the used memory even more.
 *
 */
public class FloatSparseArrayDataRow extends AbstractSparseArrayDataRow {

    private static final long serialVersionUID = -2445500346242180129L;

    /** Stores the used attribute values. */
    private float[] values;

    /** Creates an empty sparse array data row with size 0. */
    public FloatSparseArrayDataRow() {
        this(0);
    }

    /** Creates a sparse array data row of the given size. */
    public FloatSparseArrayDataRow(int size) {
        super(size);
        values = new float[size];
    }

    @Override
    protected void swapValues(int a, int b) {
        float tt = values[a];
        values[a] = values[b];
        values[b] = tt;
    }

    @Override
    public void resizeValues(int length) {
        float[] d = new float[length];
        System.arraycopy(values, 0, d, 0, Math.min(values.length, length));
        values = d;
    }

    @Override
    public void removeValue(int index) {
        System.arraycopy(values, index + 1, values, index, (values.length - (index + 1)));
    }

    /** Returns the desired data for the given attribute. */
    @Override
    public double getValue(int index) {
        return values[index];
    }

    /** Sets the given data for the given attribute. */
    @Override
    public void setValue(int index, double v) {
        values[index] = (float)v;
    }

    @Override
    protected double[] getAllValues() {
        double[] result = new double[this.values.length];
        for (int i = 0; i < result.length; i++)
            result[i] = this.values[i];
        return result;
    }

    @Override
    public int getType() {
        return DataRowFactory.TYPE_FLOAT_SPARSE_ARRAY;
    }
}

import java.util.List;
import java.util.LinkedList;

public class ConfigurationSetting {

    // Internal reference to the configuration buffer
    private final String configBuffer;

    // The complete name of the configuration option
    private final String configVar;

    // List of configuration arguments for the option (immutable copy)
    private final List<String> args;

    // Source identifier where the configuration option is defined
    private final String source;

    // Line number in the source for traceability
    private final int line;

    // Contextual location related to the configuration setting
    private final String context;

    /**
     * Constructor for ConfigurationSetting.
     * Initializes the configuration setting with all related metadata.
     *
     * @param configBuffer Reference to the configuration buffer.
     * @param configVar The configuration variable name.
     * @param argsList List of configuration arguments.
     * @param source Source identifier where the configuration is defined.
     * @param line Line number in the source file.
     * @param context Contextual location for the configuration setting.
     */
    public ConfigurationSetting(String configBuffer, String configVar, List<String> argsList, String source, int line, String context) {
        // Assign configuration buffer reference
        this.configBuffer = configBuffer;

        // Set the configuration variable name
        this.configVar = configVar;

        // Create an immutable copy of the configuration arguments list
        this.args = new LinkedList<String>(argsList);

        // Set the source identifier from where the configuration was read
        this.source = source;

        // Set the originating line number from the source file
        this.line = line;

        // Set the context associated with the configuration setting
        this.context = context;
    }

    // Accessor method to retrieve the configuration buffer reference
    public String getBuffer() {
        return configBuffer;
    }

    // Accessor method to retrieve the configuration variable name
    public String getVar() {
        return configVar;
    }

    // Accessor method to retrieve a copy of the configuration arguments list
    public List<String> getArgs() {
        // Return a new list to protect internal state from external modifications
        return new LinkedList<String>(args);
    }

    // Accessor method to retrieve the source identifier
    public String getSource() {
        return source;
    }

import org.eclipse.swt.SWT;
import org.eclipse.swt.events.ModifyEvent;
import org.eclipse.swt.events.ModifyListener;
import org.eclipse.swt.widgets.Composite;
import org.eclipse.swt.widgets.Spinner;

import melnorme.util.swt.SWTLayoutUtil;
import melnorme.util.swt.SWTUtil;
import melnorme.util.swt.components.FieldComponent;
import melnorme.util.swt.components.LabelledFieldComponent;

public class SpinnerNumberField extends LabelledFieldComponent<Integer> {

    protected Spinner spinner;

    public SpinnerNumberField(String labelText) {
        super(labelText, Option_AllowNull.NO, 0);
    }

    @Override
    public int getPreferredLayoutColumns() {
        return 2;
    }

    @Override
    protected void createContents_all(Composite topControl) {
        createContents_Label(topControl);
        createContents_Spinner(topControl);
    }

    @Override
    protected void createContents_layout() {
        SWTLayoutUtil.layout2Controls_spanLast(label, spinner);
    }

    protected void createContents_Spinner(Composite parent) {
        spinner = createFieldSpinner(this, parent, SWT.BORDER);
    }

    public Spinner getSpinner() {
        return spinner;
    }

    @Override
    public Spinner getFieldControl() {
        return spinner;
    }

    @Override
    protected void doUpdateComponentFromValue() {
        spinner.setSelection(getFieldValue());
    }

    public SpinnerNumberField setValueMinimum(int minimum) {
        spinner.setMinimum(minimum);
        return this;
    }

    public SpinnerNumberField setValueMaximum(int maximum) {
        spinner.setMaximum(maximum);
        return this;
    }

    public SpinnerNumberField setValueIncrement(int increment) {
        spinner.setIncrement(increment);
        return this;
    }

    @Override
    public void setEnabled(boolean enabled) {
        SWTUtil.setEnabledIfOk(label, enabled);
        SWTUtil.setEnabledIfOk(spinner, enabled);
    }

    /* -----------------  ----------------- */

    public static Spinner createFieldSpinner(FieldComponent<Integer> field, Composite parent, int style) {
        final Spinner spinner = new Spinner(parent, style);
        spinner.addModifyListener(new ModifyListener() {
            @Override
            public void modifyText(ModifyEvent e) {
                field.setFieldValueFromControl(spinner.getSelection());
            }
        });
        return spinner;
    }

}

import java.text.*;
import java.util.*;
 
public class CalendarTask {
 
    public static void main(String[] args) {
        printCalendar(1969, 3);
    }
 
    static void printCalendar(int year, int nCols) {
        if (nCols < 1 || nCols > 12)
            throw new IllegalArgumentException("Illegal column width.");
 
        Calendar date = new GregorianCalendar(year, 0, 1);
 
        int nRows = (int) Math.ceil(12.0 / nCols);
        int offs = date.get(Calendar.DAY_OF_WEEK) - 1;
        int w = nCols * 24;
 
        String[] monthNames = new DateFormatSymbols(Locale.US).getMonths();
 
        String[][] mons = new String[12][8];
        for (int m = 0; m < 12; m++) {
 
            String name = monthNames[m];
            int len = 11 + name.length() / 2;
            String format = MessageFormat.format("%{0}s%{1}s", len, 21 - len);
 
            mons[m][0] = String.format(format, name, "");
            mons[m][1] = " Su Mo Tu We Th Fr Sa";
            int dim = date.getActualMaximum(Calendar.DAY_OF_MONTH);
 
            for (int d = 1; d < 43; d++) {
                boolean isDay = d > offs && d <= offs + dim;
                String entry = isDay ? String.format(" %2s", d - offs) : "   ";
                if (d % 7 == 1)
                    mons[m][2 + (d - 1) / 7] = entry;
                else
                    mons[m][2 + (d - 1) / 7] += entry;
            }
            offs = (offs + dim) % 7;
            date.add(Calendar.MONTH, 1);
        }
 
        System.out.printf("%" + (w / 2 + 10) + "s%n", "[Snoopy Picture]");
        System.out.printf("%" + (w / 2 + 4) + "s%n%n", year);
 
        for (int r = 0; r < nRows; r++) {
            for (int i = 0; i < 8; i++) {
                for (int c = r * nCols; c < (r + 1) * nCols && c < 12; c++)
                    System.out.printf("   %s", mons[c][i]);
                System.out.println();
            }
            System.out.println();
        }
    }
}

public class TwinPrimes {
    public static boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }

        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        for (int i = 3; i <= 997; i++) {
            if (isPrime(i) && isPrime(i + 2)) {
                System.out.println("(" + i + ", " + (i + 2) + ")");
            }
        }
    }
}

public class Student {
    public String nearestPalindromic(String input) {
        if (input == null || input.length() == 0) {
            return input;
        }

        int n = input.length();
        long val = Long.valueOf(input);
        if (val == 0) {
            return "1";
        }

        long mask = 1;
        for (int i = 0; i < n / 2; i++) {
            mask = mask * 10;
        }

        long[] ans = new long[3];
        ans[1] = getNumber(val / mask, n, mask);
        if (isTen(val/mask)) {
            ans[0] = 0;
            for (int i = 0; i < n - 1; i++)
                ans[0] = ans[0] * 10 + 9;
        }
        else {
            ans[0] = getNumber(val / mask - 1, n, mask);
        }
        ans[2] = getNumber(val / mask + 1, n, mask);

        long ret = ans[2];
        if (Math.abs(ans[0] - val) <= Math.abs(ans[2] - val)) {
            ret = ans[0];
        }
        if (
                ans[1] != val &&
                        ((Math.abs(ans[1] - val) < Math.abs(ret - val)) ||
                (Math.abs(ans[1] - val) == Math.abs(ret - val) && ans[1] < ret))) {
            ret = ans[1];
        }
        return String.valueOf(ret);
    }
    boolean isTen(long val) {
        while (val > 1) {
            if (val % 10 == 0) {
                val /= 10;
            }
            else return false;
        }
        return val == 1;
    }

    private long reverseInt(long num) {
        long ans = 0;
        while (num != 0) {
            ans = ans * 10 + num % 10;
            num /= 10;
        }
        return ans;
    }
    private long getNumber(long prev, int n, long mask) {
        if (n % 2 == 1) {
            long last = reverseInt(prev / 10);
            return prev * mask + last;
        }
        else {
            return prev * mask + reverseInt(prev);
        }
    }
}

