@RunWith(Arquillian.class)
public class DefaultManagedExecutorServiceTestCase {
    private static final Logger LOGGER = Logger.getLogger(DefaultManagedExecutorServiceTestCase.class.getName());

    @Resource
    private ManagedExecutorService managedExecutorService;

    @EJB
    private DefaultManagedExecutorServiceTestEJB testEJB;

    @Deployment
    public static WebArchive getDeployment() {
        return ShrinkWrap.create(WebArchive.class)
            .addClass(DefaultManagedExecutorServiceTestCase.class)
            .addClass(DefaultManagedExecutorServiceTestEJB.class)
            .addClass(TestEJBRunnable.class);
    }

    @Test
    public void testTaskSubmission() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);
        final Subject testSubject = new Subject();

        TestEJBRunnable task = new TestEJBRunnable(latch);
        Future<?> future = managedExecutorService.submit(task);

        boolean completed = latch.await(5, TimeUnit.SECONDS);
        Assert.assertTrue("Task did not complete within expected time", completed);

        future.get(); // Validate task completion
    }

    @Test
    public void testSecureTaskExecution() throws Exception {
        final CountDownLatch latch = new CountDownLatch(1);

        Callable<Boolean> secureTask = () -> {
            String currentUser = PolicyContext.getContextID();
            LOGGER.info("Current Security Context: " + currentUser);
            latch.countDown();
            return true;
        };

        Future<Boolean> future = managedExecutorService.submit(secureTask);
        boolean completed = latch.await(3, TimeUnit.SECONDS);

        Assert.assertTrue("Secure task execution failed", completed);

