def min_operations_to_alternate(nums):
    n = len(nums)
    if n < 3:
        return n - 1

    # Initialize two scenarios, one starting with nums[0] and another with a new number
    # that differs from nums[0]
    even = 0  # nums[i] == nums[i-2]
    odd = 1   # nums[i] != nums[i-2]

    for i in range(1, n):
        if i % 2 == 1:
            # i is odd, nums[i] should be different from nums[i-1]
            if nums[i] == nums[i-1]:
                even += 1
                odd += 1
            else:
                # nums[i] != nums[i-1], so odd scenario can keep nums[i] unchanged
                # but even scenario might need a change
                even, odd = odd, even
        else:
            # i is even, nums[i] should be equal to nums[i-2]
            if nums[i] == nums[i-2]:
                odd += 1
            else:
                # nums[i] != nums[i-2], so even scenario can keep nums[i] unchanged
                # but odd scenario might need a change
                even, odd = odd, even + 1

    # Return the minimum changes needed
    return min(even, odd)

# Test cases
print(min_operations_to_alternate([3, 1, 3, 2, 4, 3]))  # Output: 3
print(min_operations_to_alternate([1, 2, 2, 2, 2]))    # Output: 2

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Program {
    public String smallestFromLeaf(TreeNode root) {
        String[] smallest = new String[1];

        dfs(root, "", smallest);
        return smallest[0];
    }
    void dfs(TreeNode nd, String trace, String[] smallest) {
        if (nd == null) {
            return;
        }
        trace += (char)(nd.val + 'a');
        if (nd.left == null && nd.right == null) {
            StringBuilder sb = new StringBuilder();
            for (int i = trace.length() - 1; i >= 0; i--) {
                sb.append(trace.charAt(i));
            }
            String str = sb.toString();
            if (smallest[0] == null || str.compareTo(smallest[0]) < 0) {
                smallest[0] = str;
            }
        }
        dfs(nd.left, trace, smallest);
        dfs(nd.right, trace, smallest);
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;
 
public class Shape {
 
    private static final String FILENAME = "mlijobs.txt";
    private static final int INOUTFIELD = 1;
    private static final int TIMEFIELD = 3;
    private static final int NUMFIELDS = 7;
 
    public static void main(String[] args) {
        try {
            BufferedReader file = new BufferedReader(new FileReader(FILENAME));
            int ml = 0;
            int out = 0;
            List<String> mlTimes = new ArrayList<>();
            byte[] in = "IN".getBytes();
            String line;
            while ((line = file.readLine())!= null) {
                String[] f = line.split(" ");
                if (f.length!= NUMFIELDS) {
                    throw new RuntimeException("unexpected format, " + f.length + " fields.");
                }
                if (f[INOUTFIELD].equals(new String(in))) {
                    out--;
                    if (out < 0) {
                        throw new RuntimeException("negative license use at " + f[TIMEFIELD]);
                    }
                    continue;
                }
                out++;
                if (out < ml) {
                    continue;
                }
 
                if (out > ml) {
                    ml = out;
                    mlTimes.clear();
                }
                mlTimes.add(f[TIMEFIELD]);
            }
            file.close();
 
            System.out.println("max licenses: " + ml);
            System.out.println("at:");
            for (String t : mlTimes) {
                System.out.println(" " + t);
            }
        } catch (IOException ex) {
            Logger.getLogger(Shape.class.getName()).log(Level.SEVERE, null, ex);
        }
    }
}

import java.io.*;

import java.util.*;

public class TimePass {

    public static String solve(int n,int k,int arr[]) {

        Set<Integer>set=new HashSet<>();

        for(int i:arr) set.add(i);

        for(int i:arr) {

            if(set.contains(i+k)) return "YES";

        }

        return "NO";

    }

    public static void main (String[] args) throws java.lang.Exception

    {

        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));

        PrintWriter out=new PrintWriter(System.out);

        int testCases=Integer.parseInt(br.readLine());

        while(testCases-->0){

         String input[]=br.readLine().split(" ");

         int n=Integer.parseInt(input[0]);

         int k=Integer.parseInt(input[1]);

         input=br.readLine().split(" ");

         int arr[]=new int[n];

         for(int i=0;i<n;i++) {

             arr[i]=Integer.parseInt(input[i]);

         }

         String ans=solve(n,k,arr);

         out.print(ans);

         out.print('\n');

        }

        out.close();

    }

}

import java.util.Arrays;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class Mean {
 
    public static void main(String[] args) {
        System.out.println(arithmeticMean(1, 10));
        System.out.println(geometricMean(1, 10));
        System.out.println(harmonicMean(1, 10));
    }
 
    public static double arithmeticMean(int from, int to) {
        return IntStream.rangeClosed(from, to).average().getAsDouble();
    }
 
    public static double geometricMean(int from, int to) {
        return Math.pow(IntStream.rangeClosed(from, to).reduce(1, (a, b) -> a * b), 1.0 / (to - from + 1));
    }
 
    public static double harmonicMean(int from, int to) {
        return (to - from + 1) / IntStream.rangeClosed(from, to).mapToDouble(i -> 1.0 / i).sum();
    }
}

