import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class OddEvenSubsequence {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(st.nextToken());
        }
        int[] odd = new int[n];
        int[] even = new int[n];
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                even[i] = arr[i];
            } else {
                odd[i] = arr[i];
            }
        }
        Arrays.sort(even);
        Arrays.sort(odd);
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < k; i++) {
            int maxOdd = odd[n - k + i];
            int maxEven = even[i];
            min = Math.min(min, Math.min(maxOdd, maxEven));
        }
        System.out.println(min);
    }
}

import com.fasterxml.jackson.annotation.JsonProperty;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.beam.sdk.coders.Coder;
import org.apache.beam.sdk.coders.CustomCoder;
import org.apache.beam.sdk.coders.VarLongCoder;
import org.apache.beam.sdk.nexmark.NexmarkUtils;

import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;

public class SellerPrice {
    private final long seller;
    private final long price;

    public SellerPrice(@JsonProperty("seller") long seller, @JsonProperty("price") long price) {
        this.seller = seller;
        this.price = price;
    }

    public long getSeller() {
        return seller;
    }

    public long getPrice() {
        return price;
    }

    public long sizeInBytes() {
        return 16; // 8 bytes for seller + 8 bytes for price
    }

    @Override
    public String toString() {
        try {
            return new ObjectMapper().writeValueAsString(this);
        } catch (JsonProcessingException e) {
            throw new RuntimeException("Failed to serialize SellerPrice to JSON", e);
        }
    }

    public static final Coder<SellerPrice> CODER = new CustomCoder<SellerPrice>() {
        private static final VarLongCoder LONG_CODER = VarLongCoder.of();

        @Override
        public void encode(SellerPrice value, OutputStream outStream) throws IOException {
            LONG_CODER.encode(value.getSeller(), outStream);
            LONG_CODER.encode(value.getPrice(), outStream);
        }

        @Override
        public SellerPrice decode(InputStream inStream) throws IOException {
            long seller = LONG_CODER.decode(inStream);
            long price = LONG_CODER.decode(inStream);
            return new SellerPrice(seller, price);
        }

        @Override
        public void verifyDeterministic() throws NonDeterministicException {
            LONG_CODER.verifyDeterministic();
        }
    };
}

class Node {
    int data;
    Node next;

    Node(int data) {
        this.data = data;
    }
}

public class LinkedListReversal {
    /**
     * Reverses a singly linked list iteratively.
     */
    public static Node reverse(Node head) {
        Node previous = null;
        Node current = head;
        while (current != null) {
            Node nextNode = current.next;
            current.next = previous;
            previous = current;
            current = nextNode;
        }
        return previous;
    }

    public static void printList(Node head) {
        Node current = head;
        while (current != null) {
            System.out.print(current.data + " -> ");
            current = current.next;
        }
        System.out.println("null");
    }

    public static void main(String[] args) {
        Node head = new Node(1);
        head.next = new Node(2);
        head.next.next = new Node(3);
        head.next.next.next = new Node(4);

        System.out.print("Original: ");
        printList(head);

        head = reverse(head);
        System.out.print("Reversed: ");
        printList(head);
    }
}

