public class Search {
 
    public static void main(String[] args) {
        List<CityData> citydata = Arrays.asList(
                new CityData("Lagos", 21),
                new CityData("Cairo", 15.2),
                new CityData("Kinshasa-Brazzaville", 11.3),
                new CityData("Greater Johannesburg", 7.55),
                new CityData("Mogadishu", 5.85),
                new CityData("Khartoum-Omdurman", 4.98),
                new CityData("Dar Es Salaam", 4.7),
                new CityData("Alexandria", 4.58),
                new CityData("Abidjan", 4.4),
                new CityData("Casablanca", 3.98)
        );
 
        System.out.println(searchGetIndexByName("Dar Es Salaam", citydata, CityData::getName));
        System.out.println(searchGetPopThreshold(5, citydata, CityData::getPopulation));
        System.out.println(searchGetPopByName("A", citydata, CityData::getName));
    }
 
    public static int searchGetIndexByName(String name, List<CityData> data, Function<CityData, String> nameFunc) {
        return data.indexOf(new CityData(name, 0));
    }
 
    public static double searchGetPopByName(String name, List<CityData> data, Function<CityData, String> nameFunc) {
        return data.stream()
               .filter(cityData -> nameFunc.apply(cityData).startsWith(name))
               .map(CityData::getPopulation)
               .findFirst()
               .orElse(-1);
    }
 
    public static String searchGetPopThreshold(double popThreshold, List<CityData> data, Function<CityData, Double> popFunc) {
        return data.stream()
               .filter(cityData -> popFunc.apply(cityData) >= popThreshold)
               .map(CityData::getName)
               .findFirst()
               .orElse(null);
    }
 
    public static class CityData {
        private String name;
        private double population;
 
        public CityData(String name, double population) {
            this.name = name;
            this.population = population;
        }
 
        public String getName() {
            return name;
        }
 
        public double getPopulation() {
            return population;
        }
 
        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass()!= o.getClass()) return false;
 
            CityData cityData = (CityData) o;
 
            return name.equals(cityData.name);
        }

import java.util.ArrayList;
import java.util.List;
 
public class ResistorMesh {
    static class Node {
        public Node(double v, int fixed_) {
            V = v;
            Fixed = fixed_;
        }
 
        public double V;
        public int Fixed;
    }
 
    static void SetBoundary(List<List<Node>> m) {
        m.get(1).get(1).V = 1.0;
        m.get(1).get(1).Fixed = 1;
 
        m.get(6).get(7).V = -1.0;
        m.get(6).get(7).Fixed = -1;
    }
 
    static double CalcuateDifference(List<List<Node>> m, List<List<Node>> d, int w, int h) {
        double total = 0.0;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                double v = 0.0;
                int n = 0;
                if (i > 0) {
                    v += m.get(i - 1).get(j).V;
                    n++;
                }
                if (j > 0) {
                    v += m.get(i).get(j - 1).V;
                    n++;
                }
                if (i + 1 < h) {
                    v += m.get(i + 1).get(j).V;
                    n++;
                }
                if (j + 1 < w) {
                    v += m.get(i).get(j + 1).V;
                    n++;
                }
                v = m.get(i).get(j).V - v / n;
                d.get(i).get(j).V = v;
                if (m.get(i).get(j).Fixed == 0) {
                    total += v * v;
                }
            }
        }
        return total;
    }
 
    static double Iter(List<List<Node>> m, int w, int h) {
        List<List<Node>> d = new ArrayList<List<Node>>(h);
        for (int i = 0; i < h; i++) {
            List<Node> t = new ArrayList<Node>(w);
            for (int j = 0; j < w; j++) {
                t.add(new Node(0.0, 0));
            }
            d.add(t);
        }
 
        double[] curr = new double[3];
        double diff = 1e10;
 
        while (diff > 1e-24) {
            SetBoundary(m);
            diff = CalcuateDifference(m, d, w, h);
            for (int i = 0; i < h; i++) {
                for (int j = 0; j < w; j++) {
                    m.get(i).get(j).V -= d.get(i).get(j).V;
                }
            }
        }
 
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                int k = 0;
                if (i!= 0) k++;
                if (j!= 0) k++;
                if (i < h - 1) k++;
                if (j < w - 1) k++;
                curr[m.get(i).get(j).Fixed + 1] += d.get(i).get(j).V * k;
            }
        }
 
        return (curr[2] - curr[0]) / 2.0;
    }
 
