import java.util.concurrent.ThreadLocalRandom;

/**
 */
public class BulkIndexingStressTest {

    public static void main(String[] args) {
        final int NUMBER_OF_NODES = 4;
        final int NUMBER_OF_INDICES = 600;
        final int BATCH = 300;

        final Settings nodeSettings = ImmutableSettings.settingsBuilder().put("index.number_of_shards", 2).build();

//            ESLogger logger = Loggers.getLogger("org.elasticsearch");
//            logger.setLevel("DEBUG");
        Node[] nodes = new Node[NUMBER_OF_NODES];
        for (int i = 0; i < nodes.length; i++) {
            nodes[i] = NodeBuilder.nodeBuilder().settings(nodeSettings).node();
        }

        Client client = nodes.length == 1 ? nodes[0].client() : nodes[1].client();

        while (true) {
            BulkRequestBuilder bulkRequest = client.prepareBulk();
            for (int i = 0; i < BATCH; i++) {
                bulkRequest.add(Requests.indexRequest("test" + ThreadLocalRandom.current().nextInt(NUMBER_OF_INDICES)).type("type").source("field", "value"));
            }
            BulkResponse bulkResponse = bulkRequest.execute().actionGet();
            if (bulkResponse.hasFailures()) {
                for (BulkItemResponse item : bulkResponse) {
                    if (item.isFailed()) {
                        System.out.println("failed response:" + item.getFailureMessage());
                    }
                }

                throw new RuntimeException("Failed responses");
            }
            ;
        }
    }
}

public class Triple<F, S, T> {
    private final F prim;
    private final S sec;
    private final T third;

    public Triple(F prim, S sec, T third) {
        this.prim = prim;
        this.sec = sec;
        this.third = third;
    }

    public F getFirst() {
        return prim;
    }

    public S getSecond() {
        return sec;
    }

    public T getThird() {
        return third;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) {
            return true;
        }
        if (!(obj instanceof Triple)) {
            return false;
        }
        Triple<?, ?, ?> other = (Triple<?, ?, ?>) obj;

        return (prim == null ? other.prim == null : prim.equals(other.prim)) &&
               (sec == null ? other.sec == null : sec.equals(other.sec)) &&
               (third == null ? other.third == null : third.equals(other.third));
    }

    @Override
    public int hashCode() {
        int result = 1;
        result = 31 * result + (prim == null ? 0 : prim.hashCode());
        result = 31 * result + (sec == null ? 0 : sec.hashCode());
        result = 31 * result + (third == null ? 0 : third.hashCode());
        return result;
    }

    @Override
    public String toString() {
        return String.format("Triple [first=%s, second=%s, third=%s]", prim, sec, third);
    }

    public static void main(String[] args) {
        Triple<String, Integer, Double> triple1 = new Triple<>("Hello", 123, 45.67);
        Triple<String, Integer, Double> triple2 = new Triple<>("Hello", 123, 45.67);
        Triple<String, Integer, Double> triple3 = new Triple<>(null, null, null);

        System.out.println("Triple 1: " + triple1);
        System.out.println("Triple 2: " + triple2);
        System.out.println("Triple 3: " + triple3);

        System.out.println("Triple 1 equals Triple 2: " + triple1.equals(triple2));
        System.out.println("Triple 1 equals Triple 3: " + triple1.equals(triple3));

        System.out.println("Hash Code of Triple 1: " + triple1.hashCode());
        System.out.println("Hash Code of Triple 2: " + triple2.hashCode());
        System.out.println("Hash Code of Triple 3: " + triple3.hashCode());

        Triple<Integer, String, Boolean> triple4 = new Triple<>(1, "Test", true);
        System.out.println("Triple 4: " + triple4);
    }
}

