import java.io.InputStreamReader;

import java.io.PrintWriter;

import java.util.Arrays;

import java.util.Scanner;

public class A {

    public static void main(String[] args) {

        Scanner in = new Scanner(new InputStreamReader(System.in));

        PrintWriter out = new PrintWriter(System.out);

        int K = 200003;

        boolean[] isPrime = new boolean[K];

        Arrays.fill(isPrime, true);

        for (int i = 2; i * i < K; i++) {

            if (isPrime[i]) {

                for (int j = i * i; j < K; j += i) {

                    isPrime[j] = false;

                }

            }

        }

        int T = in.nextInt();

        for (int t = 0; t < T; t++) {

            int n = in.nextInt();

            int[] a = new int[n];

            int lastOdd = -1;

            int sum = 0;

            for (int i = 0; i < n; i++) {

                a[i] = in.nextInt();

                sum += a[i];

                if (a[i] % 2 == 1) {

                    lastOdd = i;

                }

            }

            int r = isPrime[sum] ? n - 1 : n;

            out.println(r);

            boolean start = true;

            for (int i = 0; i < n; i++) {

                if (isPrime[sum] && i == lastOdd) {

                    continue;

                }

                out.print((start ? "" : " ") + (i + 1));

                start = false;

            }

            out.println();

        }

        out.close();

    }

}

private static byte[] lmv2Response(final byte[] hash, final byte[] challenge, final byte[] clientData)
            throws AuthenticationException {
        final HMACMD5 hmacMD5 = new HMACMD5(hash);
        hmacMD5.update(challenge);
        hmacMD5.update(clientData);
        final byte[] mac = hmacMD5.getOutput();
        final byte[] lmv2Response = new byte[mac.length + clientData.length];
        System.arraycopy(mac, 0, lmv2Response, 0, mac.length);
        System.arraycopy(clientData, 0, lmv2Response, mac.length, clientData.length);
        return lmv2Response;
    }

