public int minimumBitFlips(int start, int goal) {
    int flips = 0;
    while (start != goal) {
        int diff = start ^ goal;
        int count = countTrailingZeros(diff);
        flips += count;
        goal &= ~diff;
        start &= ~diff;
    }
    return flips;
}

private int countTrailingZeros(int n) {
    int count = 0;
    while (n != 0) {
        n >>= 1;
        count++;
    }
    return count;
}

