import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class CidrCanonicalizer {
 
    public static void main(String[] args) {
        List<String> tests = new ArrayList<>();
        tests.add("87.70.141.1/22");
        tests.add("36.18.154.103/12");
        tests.add("62.62.197.11/29");
        tests.add("67.137.119.181/4");
        tests.add("161.214.74.21/24");
        tests.add("184.232.176.184/18");
 
        for (String test : tests) {
            System.out.println(String.format("%-18s -> %s", test, canonicalize(test)));
        }
    }
 
    public static String canonicalize(String cidr) {
        String[] split = cidr.split("/");
        String dotted = split[0];
        int size = Integer.parseInt(split[1]);
 
        // get IP as binary string
        List<String> bin = new ArrayList<>();
        for (String n : dotted.split("\\.")) {
            int i = Integer.parseInt(n);
            bin.add(String.format("%08b", i));
        }
        String binary = String.join("", bin);
 
        // replace the host part with all zeros
        binary = binary.substring(0, size) + "0".repeat(32 - size);
 
        // convert back to dotted-decimal
        List<String> canon = IntStream.range(0, binary.length())
               .filter(i -> i % 8 == 0)
               .mapToObj(i -> Integer.parseInt(binary.substring(i, i + 8), 2))
               .map(i -> String.format("%d", i))
               .collect(Collectors.toList());
 
        // and return
        return String.join(".", canon) + "/" + split[1];
    }
}

