public abstract class ProxyParameter<T> {
    protected final Logger logger = LoggerFactory.getLogger(this.getClass());
    protected String path;
    protected String name;
    protected List<ParameterListener<T>> listeners;

    public ProxyParameter(String path, String name) {
        this.path = path;
        this.name = name;
        this.listeners = new ArrayList<>();
    }

    public void addListener(ParameterListener<T> listener) {
        listeners.add(listener);
    }

    public void removeListener(ParameterListener<T> listener) {
        listeners.remove(listener);
    }

    protected void notifyListeners(T oldValue, T newValue) {
        for (ParameterListener<T> listener : listeners) {
            listener.valueChanged(oldValue, newValue);
        }
    }

    public abstract ParameterView<T> createView();

    public abstract Tree<T> getTree();

    public abstract ProxyParameter<T> getChild(String childName);

    // Additional helper methods
}

interface ParameterListener<T> {
    void valueChanged(T oldValue, T newValue);
}

class Parameter<T> {
    private T value;

    public Parameter(T value) {
        this.value = value;
    }

    public T getValue() {
        return value;
    }

    public void setValue(T value) {
        T oldValue = this.value;
        this.value = value;
        // Notify listeners here if this class had them.
    }
}

class ParameterView<T> {
    private final ProxyParameter<T> parameter;

    public ParameterView(ProxyParameter<T> parameter) {
        this.parameter = parameter;
    }

    public T getValue() {
        return parameter.getValue();
    }

    public void setValue(T value) {
        parameter.setValue(value);
        // Notify listeners if implemented in ProxyParameter.
    }
}

