         }

       }

       for(int i = last;i>=first;i--){

        if(palindrome(s, i , last) && ((first  + (n - i))) > ans.length()){

            ans = new StringBuilder(s.substring(0,first));

            ans.append(s.substring(i, n));

        }

       }

       println(ans.toString());

    }

