public static <T, K, V, C extends Collection<Map<K, V>>> C objectToMapCollection(ObjectMapper mapper, T source, Class<C> targetCollectionType, Class<K> targetKeyType, Class<V> targetValueType) throws Exception {
    JavaType mapType = mapper.getTypeFactory().constructMapType(Map.class, targetKeyType, targetValueType);
    JavaType collectionType = mapper.getTypeFactory().constructCollectionType(targetCollectionType, mapType);
    return mapper.convertValue(source, collectionType);
}

import java.util.Arrays;
 
public class Fractions {
 
    public static int indexOf(int[] haystack, int needle) {
        int idx = 0;
        for (int straw : haystack) {
            if (straw == needle) {
                return idx;
            } else {
                idx += 1;
            }
        }
        return -1;
    }
 
    public static boolean getDigits(int n, int le, int[] digits) {
        while (n > 0) {
            int r = n % 10;
            if (r == 0 || indexOf(digits, r) >= 0) {
                return false;
            }
            le -= 1;
            digits[le] = r;
            n = n / 10;
        }
        return true;
    }
 
    public static int removeDigit(int[] digits, int le, int idx) {
        int[] pows = {1, 10, 100, 1000, 10000};
        int sum = 0;
        int pow = pows[le - 2];
        int i = 0;
        while (i < le) {
            if (i == idx) {
                i += 1;
                continue;
            }
            sum = sum + digits[i] * pow;
            pow = pow / 10;
            i += 1;
        }
        return sum;
    }
 
    public static void main(String[] args) {
        int[][] lims = { { 12, 97 }, { 123, 986 }, { 1234, 9875 }, { 12345, 98764 } };
        int[] count = new int[5];
