        int i = 0;
        while (i < lims.length) {
            int n = lims[i][0];
            while (n < lims[i][1]) {
                int[] nDigits = new int[i + 2];
                boolean nOk = getDigits(n, i + 2, nDigits);
                if (!nOk) {
                    n += 1;
                    continue;
                }
                int d = n + 1;
                while (d <= lims[i][1] + 1) {
                    int[] dDigits = new int[i + 2];
                    boolean dOk = getDigits(d, i + 2, dDigits);
                    if (!dOk) {
                        d += 1;
                        continue;
                    }
                    int nix = 0;
                    while (nix < nDigits.length) {
                        int digit = nDigits[nix];
                        int dix = indexOf(dDigits, digit);
                        if (dix >= 0) {
                            int rn = removeDigit(nDigits, i + 2, nix);
                            int rd = removeDigit(dDigits, i + 2, dix);
                            if ((1.0 * n / d) == (1.0 * rn / rd)) {
                                count[i] += 1;
                                omitted[i][digit] += 1;
                                if (count[i] <= 12) {

