class Vector {
    public int findNumberOfLIS(int[] nums) {
        int n = nums.length;
        int[][] f = new int[n][2];
        int max = 0;
        for (int i = 0; i < n; i++) {
            f[i][0] = 1; // num
            f[i][1] = 1; // count
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (nums[i] > nums[j]) { // increasing
                    if (f[i][0] < f[j][0] + 1) { // update
                        f[i][0] = f[j][0] + 1;
                        f[i][1] = f[j][1];
                    } else if (f[i][0] == f[j][0] + 1) {
                        f[i][1] += f[j][1];
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            max = Math.max(max, f[i][0]);
        }
        // System.out.println(max);
        int count = 0;
        for (int i = 0; i < n; i++) {
            // System.out.println(f[i][0] + ":" + f[i][1]);
            if (f[i][0] == max) { count += f[i][1]; }
        }
        return count;
    }
}

