class Game {
    public int countConsistentStrings(String allowed, String[] words) {
        int count = 0;
        for (String word : words) {
            if (isConsistent(allowed, word)) {
                count++;
            }
        }
        return count;
    }

    private boolean isConsistent(String allowed, String word) {
        for (char c : word.toCharArray()) {
            if (!allowed.contains(String.valueOf(c))) {
                return false;
            }
        }
        return true;
    }
}

import com.rapidminer.example.Attribute;
import com.rapidminer.example.Example;
import com.rapidminer.example.ExampleSet;
import com.rapidminer.operator.AbstractExampleSetProcessing;
import com.rapidminer.operator.OperatorDescription;
import com.rapidminer.operator.OperatorException;
import com.rapidminer.operator.ports.metadata.AttributeMetaData;
import com.rapidminer.operator.ports.metadata.RangeMetaData;
import com.rapidminer.parameter.ParameterType;
import com.rapidminer.tools.Ontology;

import java.util.ArrayList;
import java.util.List;

public class AbsoluteValueFilter extends AbstractExampleSetProcessing {

    public AbsoluteValueFilter(OperatorDescription description) {
        super(description);
    }

    @Override
    public ExampleSet process(ExampleSet exampleSet) throws OperatorException {
        ExampleSet processedSet = super.process(exampleSet);
        updateMetadataRanges(processedSet);
        return processedSet;
    }

    @Override
    protected void processExample(Example example) {
        for (Attribute attribute : getFilteredAttributes()) {
            double originalValue = example.getValue(attribute);
            example.setValue(attribute, Math.abs(originalValue));
        }
    }

    private void updateMetadataRanges(ExampleSet exampleSet) {
        int[] allowedTypes = getFilterValueTypes();
        for (Attribute attribute : exampleSet.getAttributes().createAttributeArray(allowedTypes)) {
            AttributeMetaData metaData = attribute.getMetaData();
            RangeMetaData originalRange = metaData.getRange();
            if (originalRange != null) {
                double lowerBound = originalRange.getLower();
                double upperBound = originalRange.getUpper();
                double transformedMax = Math.max(Math.abs(lowerBound), Math.abs(upperBound));
                metaData.setRange(new RangeMetaData(0.0, transformedMax));
            }
        }
    }

    @Override
    protected int[] getFilterValueTypes() {
        return new int[]{Ontology.NUMERICAL};
    }

    @Override
    public List<ParameterType> getParameterTypes() {
        List<ParameterType> types = new ArrayList<>();
        types.addAll(super.getParameterTypes());
        return types;
    }
}

import java.util.Scanner;  // Kullanicidan giris almak icin Scanner sinifini ice aktar

public class RakamlarToplami {

    // 'rakamlarToplaminiBul' metodu, verilen sayinin rakamlarinin toplamini hesaplar
    int rakamlarToplaminiBul(int sayi) {
        int rakamlarToplami = 0;  // Rakamlarin toplamini tutacak degisken

        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sayinin son rakamini almak icin 10'a gore mod islemi yapilir
            int rakam = sayi % 10;
            // Rakamlar toplamina bu rakami ekle
            rakamlarToplami += rakam;
            // Sayiyi her seferinde 10'a bolerek bir basamagini eksilt
            sayi = sayi / 10;
        }

        // Tum rakamlar toplandiktan sonra sonucu dondurur
        return rakamlarToplami;
    }

    public static void main(String[] args) {

        // Kullanicidan giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicinin bir sayi girmesini iste
        System.out.println("Lutfen bir sayi giriniz:");
        int sayi = okuyucu.nextInt();  // Kullanicinin girdigi sayi alinir

        // RakamlarToplami sinifindan bir nesne olustur
        RakamlarToplami bulucu = new RakamlarToplami();

        // 'rakamlarToplaminiBul' metodunu cagirarak girilen sayinin rakamlarinin toplamini hesapla
        int sonuc = bulucu.rakamlarToplaminiBul(sayi);

        // Hesaplanan rakamlar toplamini ekrana yazdir
        System.out.println("Rakamlar Toplami = " + sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

