public class Series {
    public static void main(String[] args) {
        for (int i = 1; i <= 10; i++) {
            System.out.println("m(" + i + ") = " + computeM(i));
        }
    }

    public static double computeM(int i) {
        if (i == 1) {
            return 1.0/3;
        } else {
            return i/(2.0*i + 1) + computeM(i - 1);
        }
    }
}

public int getAsByteArrayOffset() {
    if (position >= length)
      return -1;

    final int begin = position;

    final int size = OBinaryProtocol.bytes2int(buffer, position);
    position += OBinaryProtocol.SIZE_INT + size;

    return begin;
  }

