        System.out.print("i artan indislerdeki elemanlar: ");
        for (int i = 1; i < dizi.length; i += i) { // i += i hatali bir ifade
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Dizinin tek sayi olan elemanlarini yazdirir
    static void yaz3(int[] dizi) {
        System.out.print("Tek sayi elemanlar: ");
        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] % 2 == 0)
                continue;
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // 3'e tam bolunen bir elemana rastlayana kadar elemanlari yazdirir
    static void yaz4(int[] dizi) {
        System.out.print("Ucun kati bir elemana kadar: ");
        for (int i = 1; i < dizi.length; i++) {
            if (dizi[i] % 3 == 0)
                break;
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    // Tum elemanlari yazdirir
    static void yazTum(int[] dizi) {
        System.out.print("Tum elemanlar: ");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
        System.out.println();
    }

    public static void main(String[] args) {

        // Ornek bir dizi
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        yazTum(dizi);
        yaz1(dizi);
        yaz2(dizi);
        yaz3(dizi);
        yaz4(dizi);

    }
}

import java.util.Scanner;

/*7.14 (Computing gcd) Write a method that returns the gcd of an
 * unspecified number of integers. The method header is specified as follows:
 * public static int gcd(int... numbers)
 * Write a test program that prompts the user to enter five numbers,
 * invokes the method to find the gcd of these numbers, and displays the gcd.
 */
public class Library {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int[] numsToFind = new int[5];
        System.out.println("Please enter 5 numbers now to find their GCD:");

        for (int i = 0; i < numsToFind.length; i++) {
            numsToFind[i] = input.nextInt();
        }

        System.out.println("The GCD of these 5 integers is " + gcd(numsToFind));
    }

    public static int gcd(int... numbers) {
        int minNum = numbers[0];
        for (int i = 1; i < numbers.length; i++) {
            if (numbers[i] < minNum) {
                minNum = numbers[i];
            }
        }

        int gcd = 1;
        boolean checkNum;

        for (int i = 2; i < minNum; i++) {
            checkNum = true;
            for (int j = 0; j < numbers.length; j++) {
                if (numbers[j] % i != 0)
                    checkNum = false;
            }
            if (checkNum) {
                gcd = i;
            }
        }
        return gcd;
    }
}

import java.lang.reflect.Type;
import javax.inject.Inject;
import org.seedstack.business.internal.utils.BusinessUtils;
import org.seedstack.business.specification.dsl.SpecificationBuilder;

/**
 * An helper base class that can be extended to create an <strong>implementation</strong> of a
 * repository interface which, in turn, must extend {@link Repository}.
 *
 * <p> This class is mainly used as a common base for specialized technology-specific
 * implementations. Client code will often extend these more specialized classes instead of this
 * one. </p>
 *
 * @param <A> Type of the aggregate root.
 * @param <I> Type of the aggregate root identifier.
 * @see Repository
 * @see org.seedstack.business.util.inmemory.BaseInMemoryRepository
 */
public abstract class BaseRepository<A extends AggregateRoot<I>, I> implements Repository<A, I> {

    private static final int AGGREGATE_INDEX = 0;
    private static final int KEY_INDEX = 1;
    private final Class<A> aggregateRootClass;
    private final Class<I> idClass;
    @Inject
    private SpecificationBuilder specificationBuilder;

    /**
     * Creates a base domain repository. Actual classes managed by the repository are determined by
     * reflection.
     */
    @SuppressWarnings("unchecked")
    protected BaseRepository() {
        Type[] generics = BusinessUtils.resolveGenerics(BaseRepository.class, getClass());
        this.aggregateRootClass = (Class<A>) generics[AGGREGATE_INDEX];
        this.idClass = (Class<I>) generics[KEY_INDEX];
    }

    /**
     * Creates a base domain repository. Actual classes managed by the repository are specified
     * explicitly. This can be used to create a dynamic implementation of a repository.
     *
     * @param aggregateRootClass the aggregate root class.
     * @param idClass            the aggregate root identifier class.
     */
    protected BaseRepository(Class<A> aggregateRootClass, Class<I> idClass) {
        this.aggregateRootClass = aggregateRootClass;
        this.idClass = idClass;
    }

    @Override
    public Class<A> getAggregateRootClass() {
        return aggregateRootClass;
    }

    @Override
    public Class<I> getIdentifierClass() {
        return idClass;
    }

    @Override
    public SpecificationBuilder getSpecificationBuilder() {
        return specificationBuilder;
    }
}

import com.google.appengine.api.datastore.Query;
import org.vosao.dao.BaseDaoImpl;
import org.vosao.dao.FileChunkDao;
import org.vosao.dao.FileDao;
import org.vosao.entity.FileEntity;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;

public class FileDaoImpl extends BaseDaoImpl<FileEntity> implements FileDao {

    private FileChunkDao fileChunkDao;

    public FileDaoImpl() {
        super(FileEntity.class);
    }

    public void setFileChunkDao(FileChunkDao fileChunkDao) {
        this.fileChunkDao = fileChunkDao;
    }

    @Override
    public void remove(Long fileId) {
        FileEntity file = getById(fileId);
        if (file != null) {
            fileChunkDao.removeByFile(fileId);
            super.remove(fileId);
        }
    }

    @Override
    public void remove(List<Long> ids) {
        for (Long id : ids) {
            remove(id);
        }
    }

    @Override
    public List<FileEntity> getByFolder(Long folderId) {
        Query query = newQuery();
        query.addFilter("folderId", Query.FilterOperator.EQUAL, folderId);
        return select(query, "getByFolder", params(folderId));
    }

    @Override
    public FileEntity getByName(Long folderId, String name) {
        Query query = newQuery();
        query.addFilter("folderId", Query.FilterOperator.EQUAL, folderId);
        query.addFilter("filename", Query.FilterOperator.EQUAL, name);
        return selectOne(query, "getByName", params(folderId, name));
    }

    @Override
    public void save(FileEntity file, byte[] content) {
        file.setLastModifiedTime(new Date());
        file.setSize(content.length);
        super.save(file);
        fileChunkDao.save(file.getId(), content);
    }

    @Override
    public void removeByFolder(Long folderId) {
        List<FileEntity> files = getByFolder(folderId);
        for (FileEntity file : files) {
            remove(file.getId());
        }
    }

    @Override
    public void removeAll() {
        List<FileEntity> files = selectAll();
        for (FileEntity file : files) {
            remove(file.getId());
        }
    }

    @Override
    public byte[] getFileContent(FileEntity file) {
        return fileChunkDao.getByFile(file.getId());
    }

    private List<Object> params(Object... values) {
        List<Object> result = new ArrayList<>();
        for (Object value : values) {
            result.add(value);
        }
        return result;
    }
}

import java.io.Serializable;

public class MusicMedia implements Serializable {
    private static final long serialVersionUID = 1L;

    private String id;
    private String title;
    private String artist;
    private String url;
    private long time; // in milliseconds
    private long size; // in bytes
    private String albumId;
    private String album;
    private long duration; // in milliseconds

    public MusicMedia(String id, String title, String artist, String url, long time, long size, String albumId, String album, long duration) {
        this.id = id;
        this.title = title;
        this.artist = artist;
        this.url = url;
        this.time = time;
        this.size = size;
        this.albumId = albumId;
        this.album = album;
        this.duration = duration;
    }

    // Getters and Setters
    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getArtist() {
        return artist;
    }

    public void setArtist(String artist) {
        this.artist = artist;
    }

    public String getUrl() {
        return url;
    }

    public void setUrl(String url) {
        this.url = url;
    }

    public long getTime() {
        return time;
    }

    public void setTime(long time) {
        this.time = time;
    }

    public long getSize() {
        return size;
    }

    public void setSize(long size) {
        this.size = size;
    }

    public String getAlbumId() {
        return albumId;
    }

    public void setAlbumId(String albumId) {
        this.albumId = albumId;
    }

    public String getAlbum() {
        return album;
    }

    public void setAlbum(String album) {
        this.album = album;
    }

    public long getDuration() {
        return duration;
    }

    public void setDuration(long duration) {
        this.duration = duration;
    }

    // Formatting methods
    public String formatPlaybackTime() {
        long minutes = (time / 1000) / 60;
        long seconds = (time / 1000) % 60;
        return String.format("%02d:%02d", minutes, seconds);
    }

    public String formatFileSize() {
        if (size <= 0) return "0 bytes";
        String[] sizes = {"bytes", "KB", "MB", "GB"};
        int index = (int) (Math.log(size) / Math.log(1024));
        double formattedSize = size / Math.pow(1024, index);
        return String.format("%.2f %s", formattedSize, sizes[index]);
    }

