public class B {

    InputStream is;

    FastWriter out;

    String INPUT = "";

    void solve()

    {

        for(int T = ni();T > 0;T--)go();

    }

    void go() {

        int n = ni(), m = ni(), K = ni();

        int[] from = new int[m];

        int[] to = new int[m];

        for (int i = 0; i < m; i++) {

            from[i] = ni() - 1;

            to[i] = ni() - 1;

        }

        int[][] g = packU(n, from, to);

        Random gen = new Random();

        for(int[] row : g){

            shuffle(row, gen);

            Arrays.sort(row);

        }

        boolean[] alive = go(K, g);

        int ga = 0;

        for(boolean v : alive){

            if(v)ga++;

        }

        if(ga > 0){

            out.println(1 + " " + ga);

            for(int i = 0;i < n;i++){

                if(alive[i]){

                    out.print(i+1).print(" ");

                }

            }

            out.println();

            return;

        }

        alive = go(K-1, g);

        Queue<Integer> q = new ArrayDeque<>();

        for(int i = 0;i < n;i++){

            if(gdeg[i] == K-1){

                q.add(i);

            }

        }

        while(!q.isEmpty()){

            int cur = q.poll();

            if(!alive[cur])continue;

            int[] can = new int[K];

            int p = 0;

            can[p++] = cur;

            for(int e : g[cur]){

                if(alive[e]){

                    can[p++] = e;

                }

            }

            if(p == K) {

                boolean ok = true;

                inner:

                for (int j = 0; j < K; j++) {

                    for (int t = j + 1; t < K; t++) {

                        if (Arrays.binarySearch(g[can[j]], can[t]) < 0) {

                            ok = false;

                            break inner;

                        }

                    }

                }

                if (ok) {

                    out.println(2);

                    for(int j = 0;j < K;j++){

                        out.print((can[j]+1)).print(" ");

                    }

                    out.println();

                    return;

                }

            }

            alive[cur] = false;

            for(int e : g[cur]){

                if(alive[e] && --gdeg[e] == K-1){

                    q.add(e);

                }

            }

        }

        out.println(-1);

    }

