import org.bukkit.Location;
import org.bukkit.plugin.java.JavaPlugin;
import javax.annotation.Nullable;
import java.util.Collection;
import java.util.HashMap;
import java.util.Map;

public class SAPI_Locations implements IDisposable {

    private final JavaPlugin plugin;
    private final Map<String, NamedLocation> namedLocations;
    private boolean _isDisposed;

    public SAPI_Locations(JavaPlugin plugin) {
        this.plugin = plugin;
        this.namedLocations = new HashMap<>();
        this._isDisposed = false;
        loadNamedLocations();
    }

    private void loadNamedLocations() {
        // Simulate loading named locations from a data source
        namedLocations.put("spawn", new NamedLocation("spawn", new Location(plugin.getServer().getWorld("world"), 0, 64, 0)));
        namedLocations.put("arena", new NamedLocation("arena", new Location(plugin.getServer().getWorld("world"), 100, 64, 100)));
    }

    @Nullable
    public Location get(String name) {
        if (_isDisposed) {
            throw new IllegalStateException("API instance has been disposed.");
        }
        if (name == null || name.isEmpty()) {
            throw new IllegalArgumentException("Name cannot be null or empty.");
        }
        NamedLocation namedLocation = namedLocations.get(name);
        return namedLocation != null ? namedLocation.getLocation() : null;
    }

    public Collection<NamedLocation> getScriptLocations() {
        if (_isDisposed) {
            throw new IllegalStateException("API instance has been disposed.");
        }
        return namedLocations.values();
    }

    public <T extends Collection<NamedLocation>> T getScriptLocations(T output) {
        if (_isDisposed) {
            throw new IllegalStateException("API instance has been disposed.");
        }
        if (output == null) {
            throw new IllegalArgumentException("Output collection cannot be null.");
        }
        output.addAll(namedLocations.values());
        return output;
    }

    @Override
    public void dispose() {
        if (!_isDisposed) {
            namedLocations.clear();
            _isDisposed = true;
        }
    }

    public boolean isDisposed() {
        return _isDisposed;
    }

    private static class NamedLocation {
        private final String name;
        private final Location location;

        public NamedLocation(String name, Location location) {
            this.name = name;
            this.location = location;
        }

        public String getName() {
            return name;
        }

import com.azure.core.annotation.Fluent;
import com.fasterxml.jackson.annotation.JsonProperty;
import java.util.List;

@Fluent
public class HealthcareEntity extends HealthcareEntityProperties {

    @JsonProperty("assertion")
    private String assertion;

    @JsonProperty("name")
    private String name;

    @JsonProperty("links")
    private List<String> links;

    public HealthcareEntity() {
        // Default constructor
    }

    public String getAssertion() {
        return assertion;
    }

    public HealthcareEntity setAssertion(String assertion) {
        this.assertion = assertion;
        return this;
    }

    public String getName() {
        return name;
    }

    public HealthcareEntity setName(String name) {
        this.name = name;
        return this;
    }

    public List<String> getLinks() {
        return links;
    }

    public HealthcareEntity setLinks(List<String> links) {
        this.links = links;
        return this;
    }

    @Override
    public String toString() {
        return "HealthcareEntity{" +
                "assertion='" + assertion + '\'' +
                ", name='" + name + '\'' +
                ", links=" + links +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        HealthcareEntity that = (HealthcareEntity) o;

        if (assertion != null ? !assertion.equals(that.assertion) : that.assertion != null) return false;
        if (name != null ? !name.equals(that.name) : that.name != null) return false;
        return links != null ? links.equals(that.links) : that.links == null;
    }

    @Override
    public int hashCode() {
        int result = assertion != null ? assertion.hashCode() : 0;
        result = 31 * result + (name != null ? name.hashCode() : 0);
        result = 31 * result + (links != null ? links.hashCode() : 0);
        return result;
    }
}

