public class UserSnapshotRequest {
    private Map<String, Boolean> userSnapshotRequests = new HashMap<>();

    public void userSnapshotRequestExistenceCheck(String user, boolean deleteExistingRequest) throws Exception {
        if (userSnapshotRequests.containsKey(user)) {
            if (deleteExistingRequest) {
                userSnapshotRequests.remove(user);
            } else {
                throw new Exception("User snapshot request already exists");
            }
        }
    }
}

import jdk.vm.ci.code.InstalledCode;
import jdk.vm.ci.code.InvalidInstalledCodeException;

import org.junit.Test;

import com.oracle.graal.api.directives.GraalDirectives;

public class InstalledCodeInvalidationTest extends GraalCompilerTest {

    public void recurse(InstalledCode code, int depth) throws InvalidInstalledCodeException {
        if (depth > 1) {
            /*
             * Recurse a few times to ensure there are multiple activations.
             */
            code.executeVarargs(this, code, depth - 1);
        } else {
            /*
             * Deoptimize this activation and make the compiled code no longer usable.
             */

            GraalDirectives.deoptimizeAndInvalidate();
            assert code.isAlive() && !code.isValid();
            code.invalidate();
            assert !code.isAlive();
        }
        if (GraalDirectives.inCompiledCode()) {
            /*
             * If this still in compiled code then the deoptimizeAndInvalidate call above didn't
             * remove all existing activations.
             */
            throw new InternalError();
        }
    }

    /**
     * Test that after uncommon trapping in an installed code it's still possible to invalidate all
     * existing activations of that installed code.
     *
     * @throws InvalidInstalledCodeException
     */
    @Test
    public void testInstalledCodeInvalidation() throws InvalidInstalledCodeException {
        InstalledCode code = getCode(getMetaAccess().lookupJavaMethod(getMethod("recurse")));
        code.executeVarargs(this, code, 3);
    }
}

import java.util.ArrayList;
import java.util.List;
import java.lang.Math;

public class QuadraticRoots {

    public static void main(String[] args) {
        for (double[] c : new double[][] {
                {1, -2, 1},
                {1, 0, 1},
                {1, -10, 1},
                {1, -1000, 1},
                {1, -1e9, 1},
        }) {
            test(c[0], c[1], c[2]);
        }
    }

    public static void test(double a, double b, double c) {
        System.out.print("coefficients: " + a + " " + b + " " + c + " -> ");
        List<Double> r = qr(a, b, c)[0];
        List<Complex> i = qr(a, b, c)[1];
        switch (r.size()) {
            case 1:
                System.out.println("one real root: " + r.get(0));
                break;
            case 2:
                System.out.println("two real roots: " + r.get(0) + " " + r.get(1));
                break;
            default:
                System.out.println("two complex roots: " + i.get(0) + " " + i.get(1));
        }
    }

    public static List<Double>[] qr(double a, double b, double c) {
        double d = b*b-4*a*c;
        List<Double> r = new ArrayList<Double>();
        List<Complex> i = new ArrayList<Complex>();
        switch (true) {
            case d == 0:
                // single root
                r.add(-b/(2*a));
                break;
            case d > 0:
                // two real roots
                if (b < 0) {
                    d = Math.sqrt(d)-b;
                } else {
                    d = -Math.sqrt(d)-b;
                }
                r.add(d/(2*a));
                r.add((2*c)/d);
                break;
            case d < 0:
                // two complex roots
                double den = 1/(2*a);
                Complex t1 = new Complex(-b*den, 0);
                Complex t2 = new Complex(0, Math.sqrt(-d)*den);
                i.add(t1.add(t2));
                i.add(t1.sub(t2));
                break;
            default:
                // otherwise d overflowed or a coefficient was NAN
                r.add(d);
        }
        return new List[] {r, i};
    }
}

class Complex {
    double real;
    double imag;

    public Complex(double real, double imag) {
        this.real = real;
        this.imag = imag;
    }

    public Complex add(Complex c) {
        return new Complex(real + c.real, imag + c.imag);
    }

    public Complex sub(Complex c) {
        return new Complex(real - c.real, imag - c.imag);
    }

    public String toString() {
        return "(" + real + " + " + imag + "i)";
    }
}

