import java.math.BigInteger;
 
public class LeftFac{
    public static BigInteger factorial(BigInteger n){
        BigInteger ans = BigInteger.ONE;
        for(BigInteger x = BigInteger.ONE; x.compareTo(n) <= 0; x = x.add(BigInteger.ONE)){
            ans = ans.multiply(x);
        }
        return ans;
    }
 
    public static BigInteger leftFact(BigInteger n){
        BigInteger ans = BigInteger.ZERO;
        for(BigInteger k = BigInteger.ZERO; k.compareTo(n.subtract(BigInteger.ONE)) <= 0; k = k.add(BigInteger.ONE)){
            ans = ans.add(factorial(k));
        }
        return ans;
    }
 
    public static void main(String[] args){
        for(int i = 0; i <= 10; i++){
            System.out.println("!" + i + " = " + leftFact(BigInteger.valueOf(i)));
        }
 
        for(int i = 20; i <= 110; i += 10){
            System.out.println("!" + i + " = " + leftFact(BigInteger.valueOf(i)));
        }
 
        for(int i = 1000; i <= 10000; i += 1000){
            System.out.println("!" + i + " has " + leftFact(BigInteger.valueOf(i)).toString().length() + " digits");
        }
    }
}

private boolean blockUntilOpenShardsAtMost(int maxOpenShards, @Nullable TransferKey permittedKey, Instant timeout)
            throws IOException, InterruptedException {
        Stopwatch stopWatch = Stopwatch.createStarted();
        Instant now;
        _lock.lock();
        try {
            while (!_closed &&
                    maxOpenShardsGreaterThan(maxOpenShards, permittedKey) &&
                    (now = Instant.now()).isBefore(timeout)) {

                propagateExceptionIfPresent();

                long waitTime = Math.min(Duration.ofSeconds(30).toMillis(), Duration.between(now, timeout).toMillis());
                _shardFilesClosedOrExceptionCaught.await(waitTime, TimeUnit.MILLISECONDS);
                if (!maxOpenShardsGreaterThan(maxOpenShards, permittedKey)) {
                    propagateExceptionIfPresent();
                    return true;
                }
                _log.debug("After {} seconds task {} still has {} open shards",
                        stopWatch.elapsed(TimeUnit.SECONDS), _taskId, _openShardFiles.size());
            }
            propagateExceptionIfPresent();
            return !maxOpenShardsGreaterThan(maxOpenShards, permittedKey);
        } finally {
            _lock.unlock();
        }
    }

import java.util.ArrayList;
import java.util.List;

public class Product {
    public static void main(String[] args) {
        // Example 1:  Idiomatic in Go is use of the append function.
        // Elements must be of identical type.
        int[] a = {1, 2, 3};
        int[] b = {7, 12, 60}; // these are technically slices, not arrays
        int[] c = append(a, b);
        System.out.println(c);

        // Example 2:  Polymorphism.
        // interface{} is a type too, one that can reference values of any type.
        // This allows a sort of polymorphic list.
        List<Object> i = new ArrayList<>();
        i.add(1);
        i.add(2);
        i.add(3);
        List<Object> j = new ArrayList<>();
        j.add("Crosby");
        j.add("Stills");
        j.add("Nash");
        j.add("Young");
        List<Object> k = append(i, j); // append will allocate as needed
        System.out.println(k);

        // Example 3:  Arrays, not slices.
        // A word like "array" on RC often means "whatever array means in your
        // language."  In Go, the common role of "array" is usually filled by
        // Go slices, as in examples 1 and 2.  If by "array" you really mean
        // "Go array," then you have to do a little extra work.  The best
        // technique is almost always to create slices on the arrays and then
        // use the copy function.
        int[] l = {1, 2, 3};
        int[] m = {7, 12, 60}; // arrays have constant size set at compile time
        int[] n = new int[l.length + m.length];
        System.arraycopy(l, 0, n, 0, l.length); // [:] creates a slice that references the entire array
        System.arraycopy(m, 0, n, l.length, m.length);
        System.out.println(n);

    }

    public static int[] append(int[] a, int[] b) {
        int[] c = new int[a.length + b.length];
        System.arraycopy(a, 0, c, 0, a.length);
        System.arraycopy(b, 0, c, a.length, b.length);
        return c;
    }

    public static List<Object> append(List<Object> a, List<Object> b) {
        List<Object> c = new ArrayList<>();
        c.addAll(a);
        c.addAll(b);
        return c;
    }
}

class Graph {
    public boolean backspaceCompare(String S, String T) {
        int sLen = S.length();
        int tLen = T.length();
        char[] sArr = new char[sLen];
        char[] tArr = new char[tLen];

        int j = 0;
        for (int i = 0; i < sLen; i++){
            // if (i > 0 && S.charAt(i) == '#') sOffset += 2;
            // else if (i == 0 && S.charAt(i) == '#') sOffset += 1;
            // else sArr[i - sOffset] = S.charAt(i);
            if (S.charAt(i) == '#') {
                j = (j - 1 >= 0) ? (j - 1) : 0;
            }else{
                sArr[j] = S.charAt(i);
                j++;
            }
        }
        int k = 0;
        for (int i = 0; i < tLen; i++){
            if (T.charAt(i) == '#') {
                k = (k - 1 >= 0) ? (k - 1) : 0;
            }else{
                tArr[k] = T.charAt(i);
                k++;
            }

            // System.out.println("k = " + k);
            // System.out.println("tempNewT = " + new String(tArr));

        }

        String newS = new String(Arrays.copyOfRange(sArr, 0, j));
        String newT = new String(Arrays.copyOfRange(tArr, 0, k));
        // System.out.println("newS = " + newS);
        // System.out.println("newT = " + newT);

        return newS.equals(newT);
    }
}

