import java.io.IOException;
import java.util.HashMap;
import java.util.Map;

import javax.cache.Cache;
import javax.cache.Caching;
import javax.xml.parsers.ParserConfigurationException;
import javax.xml.stream.XMLStreamException;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.wso2.carbon.apimgt.persistence.exceptions.PersistenceException;
import org.wso2.carbon.apimgt.persistence.utils.RegistryLCManager;
import org.wso2.carbon.context.PrivilegedCarbonContext;
import org.wso2.carbon.registry.core.exceptions.RegistryException;
import org.xml.sax.SAXException;

public class LCManagerFactory {

    private static final Log log = LogFactory.getLog(LCManagerFactory.class);
    private static LCManagerFactory instance;

    private LCManagerFactory() {

    }

    public static LCManagerFactory getInstance() {
        if (instance == null) {
            instance = new LCManagerFactory();
        }
        return instance;
    }

    public RegistryLCManager getLCManager() throws PersistenceException {
        String tenantDomain = PrivilegedCarbonContext.getThreadLocalCarbonContext().getTenantDomain();
        String cacheName = tenantDomain + "_" + APIConstants.LC_CACHE_NAME;
        int tenantId = PrivilegedCarbonContext.getThreadLocalCarbonContext().getTenantId();
        Cache lcCache = Caching.getCacheManager(APIConstants.API_MANAGER_CACHE_MANAGER)
                .getCache(APIConstants.LC_CACHE_NAME);
        RegistryLCManager lcManager = (RegistryLCManager) lcCache.get(cacheName);
        if (lcManager != null) {
            log.debug("Lifecycle info servered from Cache.");
            return lcManager;
        } else {
            try {
                log.debug("Lifecycle info not found in Cache.");
                lcManager = new RegistryLCManager(tenantId);
                lcCache.put(cacheName, lcManager);
                return lcManager;
            } catch (RegistryException | XMLStreamException | ParserConfigurationException | SAXException
                    | IOException e) {
                throw new PersistenceException("Error while accessing the lifecycle resource ", e);
            }
        }
    }
}

public class Reader {

   public int nextGreaterElement(int n) {
        if(n<12)return -1;
        char[] c=String.valueOf(n).toCharArray();
        reverse(c, 0, c.length-1);
        for (int k = 1; k < c.length; k++) {
            if(c[k-1]>c[k]){
                int min=Integer.MAX_VALUE;
                int mini=k;
                for (int i = k-1; i >=0 ; i--) {
                    if(c[i] < min  &&  c[i]>c[k]){
                        min=c[i];
                        mini=i;
                    }
                }
                char temp=c[mini];
                c[mini]=c[k];
                c[k]=temp;
                Arrays.sort(c, 0, k);
                reverse(c, 0, k-1);
                break;
            }
        }
        reverse(c, 0, c.length-1);
        int res;
        try {
             res=Integer.parseInt(new String(c));
        }catch (Exception e){
            return -1;
        }
        return res>n ? res : -1;

    }

    private  void reverse(char[] c, int i, int j) {
        while (i<j){
            char temp=c[i];
            c[i]=c[j];
            c[j]=temp;
            i++;
            j--;
        }
    }
}

private void init_jdbcTypes(ResultSet rs) throws SQLException {
    ResultSetMetaData metaData = rs.getMetaData();
    int columnCount = metaData.getColumnCount();

    for (int i = 1; i <= columnCount; i++) {
        int jdbcType = metaData.getColumnType(i);
        String columnName = metaData.getColumnName(i);
        System.out.println("Column " + columnName + " has JDBC type " + jdbcType);
    }
}

public class DiziSinirAsimiHatasi {

    public static void main(String[] args) {

        // Stand-in for command-line style input
        String[] inputs = {"10", "0"};

        try {
            int first = Integer.parseInt(inputs[0]);
            int second = Integer.parseInt(inputs[2]); // deliberately out of bounds

            int quotient = first / second;
            System.out.println("Sonuc: " + quotient);

        } catch (NumberFormatException nfe) {
            System.out.println("Gecersiz giris: Lutfen sadece tamsayi giriniz.");
            System.out.println("Istisna mesaji: " + nfe.getMessage());
            nfe.printStackTrace();

        } catch (ArithmeticException ae) {
            System.out.println("Sifira bolme hatasi olustu!");
            System.out.println("Istisna mesaji: " + ae.getMessage());
            ae.printStackTrace();

        } catch (ArrayIndexOutOfBoundsException aioobe) {
            System.out.println("Eksik giris: Lutfen iki sayi giriniz.");
            System.out.println("Istisna mesaji: " + aioobe.getMessage());
            aioobe.printStackTrace();

        } finally {
            System.out.println("Finally bloguna girildi!");
        }

        try {
            runHappyPath();
        } catch (Exception unexpected) {
            System.out.println("Beklenmeyen bir hata: " + unexpected.getMessage());
        }
    }

    /**
     * Demonstrates a division that completes without throwing anything.
     */
    public static void runHappyPath() {
        System.out.println("Basarili akis testi calisiyor.");
        int numerator = 10;
        int denominator = 5;
        int result = numerator / denominator;
        System.out.println("10 / 5 = " + result);
        System.out.println("Her sey yolunda, istisna firlatilmadi!");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class PrimePartition {
 
    public static void main(String[] args) {
        List<Integer> primes = IntStream.rangeClosed(2, 22699)
               .filter(PrimePartition::isPrime)
               .boxed()
               .collect(Collectors.toList());
 
        List<List<Integer>> testCases = Arrays.asList(
                Arrays.asList(99809, 1),
                Arrays.asList(18, 2),
                Arrays.asList(19, 3),
                Arrays.asList(20, 4),
                Arrays.asList(2017, 24),
                Arrays.asList(22699, 1),
                Arrays.asList(22699, 2),
                Arrays.asList(22699, 3),
                Arrays.asList(22699, 4),
                Arrays.asList(40355, 3)
        );
 
        for (List<Integer> testCase : testCases) {
            List<Integer> result = partition(primes, testCase.get(0), testCase.get(1));
            String str = result.isEmpty()? "no solution" : result.stream().map(Object::toString).collect(Collectors.joining(" + "));
            System.out.println("Partitioned " + testCase.get(0) + " with " + testCase.get(1) + " primes: " + str);
        }
    }
 
    private static List<Integer> partition(List<Integer> primes, int x, int n) {
        return Stream.iterate(new ArrayList<Integer>(), list -> {
            if (list.size() == n) {
                return null;
            }
            List<Integer> result = new ArrayList<>();
            for (int i = 0; i < primes.size(); i++) {
                List<Integer> newList = new ArrayList<>(list);
                newList.add(primes.get(i));
                if (newList.size() == n && newList.stream().mapToInt(Integer::intValue).sum() == x) {
                    result.add(primes.get(i));
                } else {
                    List<Integer> subResult = partition(primes.subList(i + 1, primes.size()), x, n);
                    if (!subResult.isEmpty()) {
                        result.addAll(subResult);
                    }
                }
            }
            return result;
        }).filter(list ->!list.isEmpty()).findFirst().orElse(new ArrayList<>());
    }
 
    private static boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(n); i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}

java
public class Shape {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        String a = scanner.next();
        String b = scanner.next();
        System.out.println(maxSimilarityScore(a, b, n, m));
    }

    private static long maxSimilarityScore(String a, String b, int n, int m) {
        long maxScore = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                for (int len = 1; i + len <= n && j + len <= m; len++) {
                    String subA = a.substring(i, i + len);
                    String subB = b.substring(j, j + len);
                    long score = 4 * lcs(subA, subB) - subA.length() - subB.length();
                    maxScore = Math.max(maxScore, score);
                }
            }
        }
        return maxScore;
    }

    private static long lcs(String x, String y) {
        int n = x.length(), m = y.length();
        long[][] dp = new long[n + 1][m + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if (x.charAt(i - 1) == y.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1];
                } else {
                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[n][m];
    }
}

import java.util.List;

import org.springframework.dao.ConcurrencyFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.validation.BindingResult;
import org.springframework.validation.FieldError;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.*;

/**
 * Controller advice to translate the server side exceptions to client-friendly json structures.
 */
@ControllerAdvice
public class ExceptionTranslator {

    @ExceptionHandler(ConcurrencyFailureException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    @ResponseBody
    public ErrorDTO processConcurencyError(ConcurrencyFailureException ex) {
        return new ErrorDTO(ErrorConstants.ERR_CONCURRENCY_FAILURE);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    @ResponseBody
    public ErrorDTO processValidationError(MethodArgumentNotValidException ex) {
        BindingResult result = ex.getBindingResult();
        List<FieldError> fieldErrors = result.getFieldErrors();

        return processFieldErrors(fieldErrors);
    }

    @ExceptionHandler(CustomParameterizedException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    @ResponseBody
    public ParameterizedErrorDTO processParameterizedValidationError(CustomParameterizedException ex) {
        return ex.getErrorDTO();
    }

    @ExceptionHandler(AccessDeniedException.class)
    @ResponseStatus(HttpStatus.FORBIDDEN)
    @ResponseBody
    public ErrorDTO processAccessDeniedExcpetion(AccessDeniedException e) {
        return new ErrorDTO(ErrorConstants.ERR_ACCESS_DENIED, e.getMessage());
    }

    private ErrorDTO processFieldErrors(List<FieldError> fieldErrors) {
        ErrorDTO dto = new ErrorDTO(ErrorConstants.ERR_VALIDATION);

        for (FieldError fieldError : fieldErrors) {
            dto.add(fieldError.getObjectName(), fieldError.getField(), fieldError.getCode());
        }

        return dto;
    }

    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
    @ResponseBody
    @ResponseStatus(HttpStatus.METHOD_NOT_ALLOWED)
    public ErrorDTO processMethodNotSupportedException(HttpRequestMethodNotSupportedException exception) {
        return new ErrorDTO(ErrorConstants.ERR_METHOD_NOT_SUPPORTED, exception.getMessage());
    }
}

import org.springframework.cglib.proxy.Enhancer;
import org.springframework.cglib.proxy.MethodInterceptor;
import org.springframework.cglib.proxy.MethodProxy;

import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import java.lang.reflect.Method;

public class Beans implements MethodInterceptor {
    private PropertyChangeSupport propertySupport;

    public Beans() {
        this.propertySupport = new PropertyChangeSupport(this);
    }

    public static <T> T newInstance(Class<T> clazz) {
        Enhancer enhancer = new Enhancer();
        enhancer.setSuperclass(clazz);
        enhancer.setCallback(new Beans());
        return (T) enhancer.create();
    }

    @Override
    public Object intercept(Object obj, Method method, Object[] args, MethodProxy proxy) throws Throwable {
        String methodName = method.getName();

        if (isSetter(methodName)) {
            String propertyName = getPropertyNameFromSetter(methodName);
            Object oldValue = proxy.invokeSuper(obj, args);
            Object newValue = args[0];
            propertySupport.firePropertyChange(propertyName, oldValue, newValue);
            return newValue;
        }

        if (method.getDeclaringClass() == Object.class) {
            return proxy.invokeSuper(obj, args);
        }

        return proxy.invokeSuper(obj, args);
    }

    public void addPropertyChangeListener(PropertyChangeListener listener) {
        propertySupport.addPropertyChangeListener(listener);
    }

    public void removePropertyChangeListener(PropertyChangeListener listener) {
        propertySupport.removePropertyChangeListener(listener);
    }

    private boolean isSetter(String methodName) {
        return methodName.startsWith("set") && method.getParameterCount() == 1;
    }

    private String getPropertyNameFromSetter(String methodName) {
        return Character.toLowerCase(methodName.charAt(3)) + methodName.substring(4);
    }
}

