import java.util.Scanner;

public class Handler {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter an index in the Fibonacci sequence: ");
        int idx = in.nextInt();

        System.out.println("Fibonacci num at " + idx + " is " + fib(idx));
        in.close();
    }

    static long fib(int idx) {
        long f0 = 0;
        long f1 = 1;
        long result = 0;
        for (int i = 1; i < idx; i++) {
            result = f0 + f1;
            f0 = f1;
            f1 = result;
        }
        return result;
    }

}

import org.jboss.aesh.console.InputOperation;
import org.jboss.aesh.console.action.Action;
import org.jboss.aesh.console.Key;

public class KeyOperation {

    private final Key key;
    private final Action operation;
    private final String workingMode;

    public KeyOperation(Key key, Action operation, String workingMode) {
        this.key = key;
        this.operation = operation;
        this.workingMode = workingMode;
    }

    public Key getKey() {
        return key;
    }

    public Action getOperation() {
        return operation;
    }

    public String getWorkingMode() {
        return workingMode;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (!(obj instanceof KeyOperation)) return false;
        KeyOperation that = (KeyOperation) obj;
        return key.equals(that.key) &&
               operation.equals(that.operation) &&
               workingMode.equals(that.workingMode);
    }

    @Override
    public int hashCode() {
        int result = key.hashCode();
        result = 31 * result + operation.hashCode();
        result = 31 * result + workingMode.hashCode();
        return result;
    }

    @Override
    public String toString() {
        return "KeyOperation{" +
               "key=" + key +
               ", operation=" + operation +
               ", workingMode='" + workingMode + '\'' +
               '}';
    }
}

import java.util.Arrays;
public class FD {
    public static void main(String args[]) {
        double[] a = {90, 47, 58, 29, 22, 32, 55, 5, 55, 73};
        System.out.println(Arrays.toString(dif(a, 1)));
        System.out.println(Arrays.toString(dif(a, 2)));
        System.out.println(Arrays.toString(dif(a, 9)));
        System.out.println(Arrays.toString(dif(a, 10)));      //let's test
        System.out.println(Arrays.toString(dif(a, 11)));
        System.out.println(Arrays.toString(dif(a, -1)));
        System.out.println(Arrays.toString(dif(a, 0)));
    }
 
    public static double[] dif(double[] a, int n) {
        if (n < 0)
            return null; // if the programmer was dumb
 
        for (int i = 0; i < n && a.length > 0; i++) {
            double[] b = new double[a.length - 1];
            for (int j = 0; j < b.length; j++){
                b[j] = a[j+1] - a[j];
            }
            a = b; //"recurse"
        }
        return a;
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Hofq {
 
    public static void main(String[] args) {
        List<Integer> qMemo = new ArrayList<>();
        qMemo.add(0);
        qMemo.add(1);
        qMemo.add(1);
        Hofq hofq = new Hofq();
        for (int i = 1; i < 11; i++) {
            System.out.println("Q(" + i + ")=" + hofq.q(qMemo, i));
        }
        System.out.println("Q(1000)=" + hofq.q(qMemo, 1000));
        int q100001 = hofq.q(qMemo, 100_000); // precompute all
        System.out.println("Q(100000)=" + q100000);
        int nless = (int) (1..100_000).filter(i -> hofq.q(qMemo, i + 1) < hofq.q(qMemo, i)).count();
        System.out.println("Term is less than preceding term " + nless + " times");
    }
 
    private int q(List<Integer> qMemo, int x) {
        int curLen = qMemo.size() - 1;
        int i = x;
        if (i > curLen) {
            // extend storage
            for (int j = curLen + 1; j <= i; j++) {
                int qj = qMemo.get(j - qMemo.get(j - 1)) + qMemo.get(j - qMemo.get(j - 2));
                qMemo.add(qj);
            }
        }
        return qMemo.get(i);
    }
}

import com.google.common.base.Preconditions;
import com.google.common.collect.Iterators;
import org.apache.druid.java.util.common.io.Closer;
import org.apache.druid.java.util.common.parsers.CloseableIterator;

import javax.annotation.Nullable;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;

public class CloseableIterators {

    public static <T> CloseableIterator<T> concat(List<? extends CloseableIterator<? extends T>> iterators) {
        Preconditions.checkNotNull(iterators, "iterators cannot be null");
        Closer closer = Closer.create();
        for (CloseableIterator<? extends T> iterator : iterators) {
            closer.register(iterator);
        }
        Iterator<T> concatenated = Iterators.concat(iterators.iterator());
        return wrap(concatenated, closer);
    }

    public static <T> CloseableIterator<T> mergeSorted(
            List<? extends CloseableIterator<? extends T>> iterators,
            Comparator<T> comparator
    ) {
        Preconditions.checkNotNull(iterators, "iterators cannot be null");
        Preconditions.checkNotNull(comparator, "comparator cannot be null");
        Closer closer = Closer.create();
        for (CloseableIterator<? extends T> iterator : iterators) {
            closer.register(iterator);
        }
        Iterator<T> merged = Iterators.mergeSorted(iterators, comparator);
        return wrap(merged, closer);
    }

    public static <T> CloseableIterator<T> wrap(Iterator<T> innerIterator, @Nullable Closeable closeable) {
        Preconditions.checkNotNull(innerIterator, "innerIterator cannot be null");
        return new CloseableIterator<T>() {
            @Override
            public boolean hasNext() {
                return innerIterator.hasNext();
            }

            @Override
            public T next() {
                return innerIterator.next();
            }

            @Override
            public void close() {
                if (closeable != null) {
                    try {
                        closeable.close();
                    } catch (Exception e) {
                        throw new RuntimeException("Failed to close resource", e);
                    }
                }
            }
        };
    }

    public static <T> CloseableIterator<T> withEmptyBaggage(Iterator<T> innerIterator) {
        return wrap(innerIterator, null);
    }
}

