if(! flag) return -1;
int addTimes = 0;
for(int i = maxTimes * alen - blen; i < maxTimes * alen; i++){
if(a.charAt(i) == b.charAt(i)) ++addTimes;
}
return addTimes;

}

}

Complexity Analysis

• Time Complexity: Let l be the length of a, m be the length of b, $$O(m^2)$$.
• Space Complexity: $$O(1)$$.

