import java.io.*;
import java.util.jar.*;

public class JarWriter {

    public void packToJar(File jarRootDir, OutputStream os) throws FileNotFoundException, IOException {
        Manifest manifest = new Manifest();
        Attributes mainAttributes = manifest.getMainAttributes();
        mainAttributes.put(Attributes.Name.MANIFEST_VERSION, "1.0");

        try (JarOutputStream target = new JarOutputStream(os, manifest)) {
            add("", jarRootDir, target);
        }
    }

    private void add(String prefix, File source, JarOutputStream target) throws IOException {
        String name = prefix + source.getName();
        if (source.isDirectory()) {
            if (!name.isEmpty()) {
                String entryName = name.endsWith("/") ? name : name + "/";
                JarEntry entry = new JarEntry(entryName);
                entry.setTime(source.lastModified());
                target.putNextEntry(entry);
                target.closeEntry();
            }
            File[] nestedFiles = source.listFiles();
            if (nestedFiles != null) {
                for (File nestedFile : nestedFiles) {
                    add(name + "/", nestedFile, target);
                }
            }
        } else {
            try (FileInputStream in = new FileInputStream(source)) {
                String jarentryName = name.replace("\\", "/");
                JarEntry entry = new JarEntry(jarentryName);
                entry.setTime(source.lastModified());
                target.putNextEntry(entry);
                byte[] buffer = new byte[1024];
                int count;
                while ((count = in.read(buffer)) > 0) {
                    target.write(buffer, 0, count);
                }
                target.closeEntry();
            }
        }
    }

    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java JarWriter <root-directory> <output-jar>");
            return;
        }
        File rootDir = new File(args[0]);
        File outputFile = new File(args[1]);

        try (FileOutputStream fos = new FileOutputStream(outputFile)) {
            JarWriter jarWriter = new JarWriter();
            jarWriter.packToJar(rootDir, fos);
            System.out.println("JAR file created successfully.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

