public class Library {
    public static void main(String[] args) throws InterruptedException {
        // The reader sends lines to the writer via an async channel, so the reader is never blocked.
        BlockingQueue<String> readerSend = new LinkedBlockingQueue<>();
        BlockingQueue<String> writerRecv = new LinkedBlockingQueue<>();
 
        // The writer sends the final count via a blocking channel with bound 0,
        // meaning the buffer is exactly the size of the result.
        BlockingQueue<Integer> writerSend = new ArrayBlockingQueue<>(0);
        BlockingQueue<Integer> readerRecv = new ArrayBlockingQueue<>(0);
 
        // Define the work the reader will do.
        Runnable readerWork = () -> {
            try (BufferedReader reader = new BufferedReader(new FileReader(new File("input.txt")))) {
                String line;
                while ((line = reader.readLine())!= null) {
                    readerSend.put(line);
                }
 
                // Dropping the sender disconnects it and tells the receiver the connection is closed.
                readerSend.close();
 
                // Now that we've sent all the lines,
                // block until the writer gives us the final count.
                int count = readerRecv.take();
 
                System.out.println(count);
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
            }
        };
 
        // Define the work the writer will do.
        Runnable writerWork = () -> {
            int lineCount = 0;
 
            try {
                while (true) {
                    String msg = writerRecv.take();
                    System.out.println(msg);
                    lineCount++;
                }
            } catch (InterruptedException e) {
                // indicates the connection has been closed by the sender.
            }
 
            // Send the final count back to the reader.
            try {
                writerSend.put(lineCount);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
 
            try {
                writerSend.close();
            } catch (IOException e) {

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Timer {
    private int findVal(TreeNode root, HashMap<TreeNode, Integer> map) {
        if (root != null) {
            int val = root.val;
            val += findVal(root.left, map);
            val += findVal(root.right, map);
            //System.out.println("Adding " + val + " to " + root.val);
            map.put(root, val);
            return val;
        }
        return 0;
    }
    private boolean canBreak(TreeNode root, HashMap<TreeNode, Integer> map, int total) {
        if (root != null) {
            if (root.left != null) {
                int v1 = map.get(root.left);
                int v2 = total - v1;
                if (v1 == v2) {
                    return true;
                }
            }
            if (root.right != null) {
                int v1 = map.get(root.right);
                int v2 = total-v1;
                if (v1 == v2) {
                    return true;
                }
            }
            if (!canBreak(root.left, map, total)) {
                return canBreak(root.right, map, total);
            } else {
                return true;
            }
        }
        return false;
    }
    public boolean checkEqualTree(TreeNode root) {
        HashMap<TreeNode, Integer> map = new HashMap<>();
        int total = findVal(root, map);
        return canBreak(root, map, total);
    }
}

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.BaseAdapter;
import android.widget.TextView;
import android.widget.Toast;

import java.util.List;

public class SimpleDataAdapter extends BaseAdapter {

    private List<SimpleData> mItems;
    private LayoutInflater mInflater;
    private int selectedPosition = -1;

    public interface OnItemClickListener {
        void onItemClick(SimpleData item);
    }

    private OnItemClickListener mListener;

    public SimpleDataAdapter(Context context, List<SimpleData> items, OnItemClickListener listener) {
        mItems = items;
        mInflater = LayoutInflater.from(context);
        mListener = listener;
    }

    @Override
    public int getCount() {
        return mItems.size();
    }

    @Override
    public Object getItem(int position) {
        return mItems.get(position);
    }

    @Override
    public long getItemId(int position) {
        return position;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        SimpleItemViewHolder holder;

        if (convertView == null) {
            convertView = mInflater.inflate(android.R.layout.simple_list_item_1, parent, false);
            holder = new SimpleItemViewHolder();
            holder.textView = convertView.findViewById(android.R.id.text1);
            convertView.setTag(holder);
        } else {
            holder = (SimpleItemViewHolder) convertView.getTag();
        }

        SimpleData item = mItems.get(position);
        holder.textView.setText(item.getText());

        if (position == selectedPosition) {
            holder.textView.setBackgroundColor(0xFF00FF00); // Example: Green highlight
        } else {
            holder.textView.setBackgroundColor(0x00000000); // Transparent
        }

        convertView.setOnClickListener(v -> {
            selectedPosition = position;
            notifyDataSetChanged();
            mListener.onItemClick(item);

        });

        return convertView;
    }

    static class SimpleItemViewHolder {
        TextView textView;
    }
}

class Validator {
    public boolean checkValidGrid(int[][] grid) {
        int n = grid.length;
        int[][] b = grid;
        if (b[0][0]!=0) return false;
        for (int i = 0;i<n;i++) {
            for (int j = 0;j<n;++j) {
                if (b[i][j]==0) continue;
                boolean seen= false;
                for (int x = 0;x<n&&!seen;x++) {
                    for (int y = 0; y < n&&!seen; ++y) {
                        if (b[x][y] == b[i][j] - 1) {
                            int d1 = Math.abs(x-i);
                            int d2=Math.abs(y-j);
                            if ((d1==1&&d2==2) || (d2==1&&d1==2)) {
                                // ok
                            } else return false;
                            seen=true;
                        }
                    }
                }
            }
        }
        return true;
    }
}

