**Response:** public int longestArithSeqLength(int[] nums) {
    int[] dp = new int[nums.length];
    int longestStreak = 0;

    for (int i = 0; i < nums.length; i++) {
        for (int j = 0; j < i; j++) {
            int diff = nums[i] - nums[j];
            int seqLength = dp[j];
            int index = binarySearch(nums, j + 1, nums.length - 1, nums[j] + diff);

            if (index > j) {
                seqLength = Math.max(seqLength, dp[index]);
            }

            dp[i] = Math.max(dp[i], seqLength + 1);
            longestStreak = Math.max(longestStreak, dp[i]);
        }
    }

    return longestStreak >= 3 ? longestStreak : 0;
}

private int binarySearch(int[] nums, int left, int right, int target) {
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        } else if (nums[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return left;
}

import java.util.Scanner;

public class PointPosition {

    public static boolean leftOfTheLine(double x0, double y0, double x1, double y1, double x2, double y2) {
        return ((x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)) > 0;
    }

    public static boolean rightOfTheLine(double x0, double y0, double x1, double y1, double x2, double y2) {
        return ((x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)) < 0;
    }

    public static boolean onTheSameLine(double x0, double y0, double x1, double y1, double x2, double y2) {
        return ((x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0)) == 0;
    }

    public static boolean onTheLineSegment(double x0, double y0, double x1, double y1, double x2, double y2) {
        return onTheSameLine(x0, y0, x1, y1, x2, y2)
                && ((x2 >= x0 && x2 <= x1) || (x2 <= x0 && x2 >= x1))
                && ((y2 >= y0 && y2 <= y1) || (y2 <= y0 && y2 >= y1));
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter three points for p0, p1, and p2: ");
        double x0 = input.nextDouble();
        double y0 = input.nextDouble();
        double x1 = input.nextDouble();
        double y1 = input.nextDouble();
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();

        if (onTheLineSegment(x0, y0, x1, y1, x2, y2)) {
            System.out.println("(" + x2 + ", " + y2 + ") is on the line segment from (" + x0 + ", " + y0 + ") to (" + x1 + ", " + y1 + ")");
        } else if (onTheSameLine(x0, y0, x1, y1, x2, y2)) {
            System.out.println("(" + x2 + ", " + y2 + ") is on the same line from (" + x0 + ", " + y0 + ") to (" + x1 + ", " + y1 + ")");
        } else if (leftOfTheLine(x0, y0, x1, y1, x2, y2)) {
            System.out.println("(" + x2 + ", " + y2 + ") is on the left side of the line from (" + x0 + ", " + y0 + ") to (" + x1 + ", " + y1 + ")");
        } else {
            System.out.println("(" + x2 + ", " + y2 + ") is on the right side of the line from (" + x0 + ", " + y0 + ") to (" + x1 + ", " + y1 + ")");
        }
    }
}

class Finder {
    public int uniqueMorseRepresentations(String[] words) {
        Set<String> set = new HashSet<String>();
        String[] morse = {".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."};
        for(String word: words){
            String s="";
            for(char c: word.toCharArray()){
                s+=morse[c-'a'];
            }
            set.add(s);
        }
        return set.size();
    }
}

import java.util.Comparator;
import java.util.function.Function;

/**
 *         created on 26-04-2017
 */
public class Comparators {
    public static <T, R extends Comparable<R>> ComparatorBy<T> comparing(Function<T, R> prop) {
        return (o1, o2) -> prop.apply(o1).compareTo(prop.apply(o2));
    }

    public interface ComparatorBy<T> extends Comparator<T> {

        public default ComparatorBy<T> invert() {
            return (o1, o2) -> compare(o2, o1);
        }

        public default <R extends Comparable<R>> ComparatorBy<T> thenBy(Function<T, R> prop) {
            Comparator<T> then = Comparators.comparing(prop); // Comparador criado 1 x
            return (o1, o2) -> {
                int res = compare(o1, o2);
                if(res != 0) return res;
                return then.compare(o1, o2); // Captura da variável then
            };
        }
    }
}

