import org.apache.geode.cache.Cache;
import org.apache.geode.cache.CacheFactory;
import org.apache.geode.cache.CacheTransactionManager;
import org.apache.geode.cache.Region;
import org.apache.geode.cache.RegionFactory;
import org.apache.geode.cache.RegionShortcut;
import org.apache.geode.distributed.ConfigurationProperties;
import org.apache.geode.internal.cache.MemoryAllocatorImpl;
import org.junit.Test;
import org.junit.experimental.categories.Category;
import org.apache.geode.test.junit.categories.OffHeapTest;

@Category(OffHeapTest.class)
public class TxReleasesOffHeapOnCloseJUnitTest {

    private Cache cache;

    @Test
    public void testTxReleasesOffHeapOnClose() {
        createCache();
        Region<String, String> region = createRegion();
        region.put("key1", "value1");

        CacheTransactionManager txManager = cache.getCacheTransactionManager();
        txManager.begin();
        region.put("key1", "value2");

        // Close cache without committing or rolling back the transaction
        cache.close();

        // Verify off-heap memory is fully released
        assertOffHeapMemoryReleased();
    }

    private void createCache() {
        CacheFactory cacheFactory = new CacheFactory();
        cacheFactory.set(ConfigurationProperties.OFF_HEAP_MEMORY_SIZE, "100M");
        cache = cacheFactory.create();
    }

    private Region<String, String> createRegion() {
        RegionFactory<String, String> regionFactory = cache.createRegionFactory(RegionShortcut.LOCAL);
        regionFactory.setOffHeap(true);
        return regionFactory.create("testRegion");
    }

    private void assertOffHeapMemoryReleased() {
        long offHeapMemoryUsed = MemoryAllocatorImpl.getAllocator().getUsedMemory();
        if (offHeapMemoryUsed != 0) {
            throw new AssertionError("Off-heap memory was not fully released. Used memory: " + offHeapMemoryUsed);
        }
    }
}

import java.awt.*;
import java.awt.event.*;
import java.awt.image.*;
import static java.awt.image.BufferedImage.*;
import static java.lang.Math.*;
import javax.swing.*;
 
public class PlasmaEffect extends JPanel {
    float[][] plasma;
    float hueShift = 0;
    BufferedImage img;
 
    public PlasmaEffect() {
        Dimension dim = new Dimension(640, 640);
        setPreferredSize(dim);
        setBackground(Color.white);
 
        img = new BufferedImage(dim.width, dim.height, TYPE_INT_RGB);
        plasma = createPlasma(dim.height, dim.width);
 
        // animate about 24 fps and shift hue value with every frame
        new Timer(42, (ActionEvent e) -> {
            hueShift = (hueShift + 0.02f) % 1;
            repaint();
        }).start();
    }
 
    float[][] createPlasma(int w, int h) {
        float[][] buffer = new float[h][w];
 
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
 
                double value = sin(x / 16.0);
                value += sin(y / 8.0);
                value += sin((x + y) / 16.0);
                value += sin(sqrt(x * x + y * y) / 8.0);
                value += 4; // shift range from -4 .. 4 to 0 .. 8
                value /= 8; // bring range down to 0 .. 1
 
                // requires VM option -ea
                assert (value >= 0.0 && value <= 1.0) : "Hue value out of bounds";
 
                buffer[y][x] = (float) value;
            }
        return buffer;
    }
 
    void drawPlasma(Graphics2D g) {
        int h = plasma.length;
        int w = plasma[0].length;
        for (int y = 0; y < h; y++)
            for (int x = 0; x < w; x++) {
                float hue = hueShift + plasma[y][x] % 1;
                img.setRGB(x, y, Color.HSBtoRGB(hue, 1, 1));
            }
        g.drawImage(img, 0, 0, null);
    }
 
    @Override
    public void paintComponent(Graphics gg) {
        super.paintComponent(gg);
        Graphics2D g = (Graphics2D) gg;
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_ON);
 
        drawPlasma(g);
    }
 
    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame f = new JFrame();
            f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            f.setTitle("Plasma Effect");
            f.setResizable(false);
            f.add(new PlasmaEffect(), BorderLayout.CENTER);
            f.pack();
            f.setLocationRelativeTo(null);
            f.setVisible(true);
        });
    }
}

import java.util.Scanner;

public class Counter {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // prompt the user to enter the number of students
        System.out.print("Enter the number of students: ");
        int numStudents = input.nextInt();

        // initialize variables to keep track of highest and second-highest scores and their corresponding names
        String highestName = "";
        int highestScore = Integer.MIN_VALUE;
        String secondHighestName = "";
        int secondHighestScore = Integer.MIN_VALUE;

        // loop through each student and update highest and second-highest scores if necessary
        for (int i = 0; i < numStudents; i++) {
            // prompt the user to enter the student's name and score
            System.out.print("Enter the name and score of student " + (i + 1) + ": ");
            String name = input.next();
            int score = input.nextInt();

            // update highest and second-highest scores if necessary
            if (score > highestScore) {
                secondHighestName = highestName;
                secondHighestScore = highestScore;
                highestName = name;
                highestScore = score;
            } else if (score > secondHighestScore) {
                secondHighestName = name;
                secondHighestScore = score;
            }
        }

        // display the student with the highest score and the student with the second-highest score
        System.out.println("Student with the highest score: " + highestName + " (" + highestScore + ")");
        System.out.println("Student with the second-highest score: " + secondHighestName + " (" + secondHighestScore + ")");
    }
}

import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Scanner;

public class JavaTest {
    private static final PrintWriter out = new PrintWriter(System.out);
    private static Scanner sc;

    public static void main(String[] args) throws Exception {
        InputStream is = JavaTest.class.getResourceAsStream("in.txt");
        boolean testMode = is != null;
        sc = new Scanner(testMode ? is : System.in);

        long start = System.currentTimeMillis();
        main();

        if (testMode) {
            out.println();
            out.print(System.currentTimeMillis() - start + " ms");
        }

        out.close();
    }

    private static void main() throws Exception {
        int n = sc.nextInt();
        int[] arr = new int[n];
        int a1 = Integer.MAX_VALUE, a2 = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int a = arr[i] = sc.nextInt();
            if (a1 > a) {
                a2 = a1;
                a1 = a;
            } else if (a2 > a) {
                a2 = a;
            }
        }
        int ans = (a1 + 1) / 2 + (a2 + 1) / 2;
        for (int i = 1; i < n; i++) {
            int a = Math.max(arr[i - 1], arr[i]);
            int b = Math.min(arr[i - 1], arr[i]);
            int k = a > b * 2 ? (a + 1) / 2 : (a + b + 2) / 3;
            ans = Math.min(ans, k);
        }
        for(int i = 1; i < n-1; i++) {
            int a = arr[i-1];
            int b = arr[i+1];
            int k0 = (a+1)/2 + (b+1)/2;
            int k1 = 1 + a/2 + b/2;
            int k = Math.min(k0, k1);
            ans = Math.min(ans, k);
        }
        System.out.println(ans);
    }
}

