import java.util.TreeMap;

class Order {
    public boolean[] canMakePalindromeQueries(String s, int[][] queries) {
        int Q = queries.length;
        int n = s.length();
        int[][] counts = new int[n + 1][26];
        for (int i = 0; i < n; i++) {
            System.arraycopy(counts[i], 0, counts[i + 1], 0, 26);
            counts[i + 1][s.charAt(i) - 'a']++;
        }
        TreeMap<Integer, Integer> palindromeFromTo = new TreeMap<>();
        int from = 0;
        while (from < n / 2) {
            if (s.charAt(from) == s.charAt(n - 1 - from)) {
                int to = from;
                while (to < n / 2 && s.charAt(to) == s.charAt(n - 1 - to)) {
                    to++;
                }
                palindromeFromTo.put(from, to);
                from = to;
            } else {
                from++;
            }
        }
        boolean[] result = new boolean[Q];
        for (int q = 0; q < Q; q++) {
            int a = queries[q][0];
            int b = queries[q][1];
            int c = queries[q][2];
            int d = queries[q][3];
            int a1 = n - 1 - d;
            int b1 = n - 1 - c;
            int c1 = n - 1 - b;
            int d1 = n - 1 - a;
            if (a1 > b || a > b1) {
                int x1 = Math.min(a, a1);
                int y1 = Math.min(b, b1);
                int x2 = Math.max(a, a1);
                int y2 = Math.max(b, b1);
                Map.Entry<Integer, Integer> e1 = palindromeFromTo.floorEntry(0);
                if (x1 > 0 && (e1 == null || e1.getValue() < x1)) {
                    continue;
                }
                Map.Entry<Integer, Integer> e2 = palindromeFromTo.floorEntry(y1 + 1);
                if (y1 < x2 - 1 && (e2 == null || e2.getValue() < x2)) {
                    continue;
                }
                Map.Entry<Integer, Integer> e3 = palindromeFromTo.floorEntry(y2 + 1);
                if (y2 < n / 2 - 1 && (e3 == null || e3.getValue() < n / 2)) {
                    continue;
                }
                int[] left1 = new int[26];
                int[] right1 = new int[26];
                int[] left2 = new int[26];
                int[] right2 = new int[26];
                for (int i = 0; i < 26; i++) {
                    left1[i] = counts[y1 + 1][i] - counts[x1][i];
                    right1[i] = counts[n - 1 - x1 + 1][i] - counts[n - 1 - y1][i];
                    left2[i] = counts[y2 + 1][i] - counts[x2][i];
                    right2[i] = counts[n - 1 - x2 + 1][i] - counts[n - 1 - y2][i];

