public class Partial {
    public static void main(String[] args) throws Exception {
        int[] x = { 1, 2, 3, 4 };
        int[] y = { 1, 2, 3, 4 };
        int i;
        pfunc f = partial(Partial.class.getMethod("square", int.class));
        pfunc g = partial(Partial.class.getMethod("dbl", int.class));
        System.out.println("partial square:");
        f.apply(x, 4);
        for (i = 0; i < 4; i++)
            System.out.println(x[i]);
        System.out.println("partial double:");
        g.apply(y, 4);
        for (i = 0; i < 4; i++)
            System.out.println(y[i]);
    }
 
    public static int square(int a) {
        return a * a;
    }
 
    public static int dbl(int a) {
        return a + a;
    }
 
    public static pfunc partial(Method fin) throws Exception {
        pfunc f;
        static int idx = 0;
        String lib = "/tmp/stuff" + (++idx) + ".so";
        String cc = "cc -pipe -x c -shared -o " + lib + " -";
        Process p = Runtime.getRuntime().exec(cc);
        PrintStream ps = new PrintStream(p.getOutputStream());
        ps.println("#define t typedef\xat int _i,*i;t _i(*__)(_i);__ p =(__)%p;"
                + "void _(i _1, _i l){while(--l>-1)l[_1]=p(l[_1]);}", fin);
        ps.close();
        p.waitFor();
        f = (pfunc) load(lib).getMethod("_").invoke(null);
        new File(lib).delete();
        return f;
    }
 
    public static Class<?> load(String lib) throws Exception {
        URLClassLoader cl = (URLClassLoader) ClassLoader.getSystemClassLoader();
        URL[] urls = cl.getURLs();
        List<URL> urlList = new ArrayList<URL>();
        for (URL url : urls)
            urlList.add(url);
        urlList.add(new File(lib).toURI().toURL());
        URL[] newUrls = urlList.toArray(new URL[urlList.size()]);
        cl = new URLClassLoader(newUrls, cl.getParent());
        return cl.loadClass("Partial");
    }
 
    public static interface pfunc {
        public void apply(int[] _1, int l);
    }
}

