        return "Pair{" +
                "p1=" + p1 +
                ", p2=" + p2 +
                '}';
    }
}

class Game {
    public int largestUniqueNumber(int[] A) {
        Set<Integer> all = new HashSet();
        Set<Integer> duplicate = new HashSet();
        for (int a: A) {
            if (all.contains(a))
                duplicate.add(a);
            else
                all.add(a);
        }

        int result = -1;
        for (int a: all) {
            if (!duplicate.contains(a))
                result = Math.max(a, result);
        }
        return result;
    }
}

