public static <E> ClassicCounter<E> loadCounter(String filename, Class<E> c) throws RuntimeException {
    ClassicCounter<E> counter = new ClassicCounter<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split("\\s+");
            if (parts.length != 2) {
                throw new RuntimeException("Invalid line format: " + line);
            }
            String keyString = parts[0];
            int count = Integer.parseInt(parts[1]);
            E key = c.getDeclaredConstructor(String.class).newInstance(keyString);
            counter.setCount(key, count);
        }
    } catch (IOException | NoSuchMethodException | InstantiationException | IllegalAccessException | InvocationTargetException e) {
        throw new RuntimeException("Error reading file: " + filename, e);
    }
    return counter;
}

import java.util.Scanner;

public class Processor {
    private void findSubsequence(String[] tokens) {
        int longest = 0;
        int longestStartIndex = 0;
        int count = 1;
        int value = 0;
        int startIndex = 0;

        for (int i = 0; i < tokens.length - 1; i++) {
            int curr = Integer.parseInt(tokens[i]);
            int next = Integer.parseInt(tokens[i + 1]);
            if (next == 0) break;
            if (curr == next) {
                count++;
                longest = Math.max(longest, count);
                if (count == longest) {
                    value = curr;
                    longestStartIndex = startIndex;
                }
            } else {
                startIndex = i + 1;
                count = 1;
            }

        }
        System.out.println("The longest same number sequence starts at index " + longestStartIndex +
                " with " + longest + " values " + "of " + value);

    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.println("Enter a series of numbers ending with 0:");
        String[] tokens = input.nextLine().split("\\s+");
        new Processor().findSubsequence(tokens);

        input.close();

    }
}

