public String mergeRealPath(String mapping, String parentRealPath, String newRealPath, boolean isOutSide) {
    String mergedPath = "";

    if (isOutSide) {
        mergedPath = parentRealPath + mapping + newRealPath;
    } else {
        mergedPath = parentRealPath + newRealPath;
    }

    return mergedPath;
}

