import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
 
public class Reader {
    private static final String FILE_NAME = "output.txt";
    private static final String DIR_NAME = "docs";
    private static final String ROOT = ".";
    private static final String ROOT_SLASH = "/";
    
    public static void main(String[] args) {
        try {
            create(ROOT);
            create(ROOT_SLASH);
        } catch (IOException e) {
            error_handler(e, 1);
        }
    }
    
    private static void create(String root) throws IOException {
        Path fPath = Paths.get(root, FILE_NAME);
        Path dPath = Paths.get(root, DIR_NAME);
        Files.createDirectories(dPath);
        Files.createFile(fPath);
    }
    
    private static void error_handler(Exception e, int code) {
        System.err.println("Error: " + e.getMessage());
        System.exit(code);
    }
}

import com.dd.plist.NSDictionary;
import com.dd.plist.NSObject;
import com.dd.plist.PropertyListParser;
import com.dd.plist.XMLPropertyListWriter;
import com.google.common.collect.ImmutableMap;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.util.Map;

public class PlistProcessStep {

    private final File input;
    private final File output;
    private final ImmutableMap<String, NSObject> additionalKeys;
    private final ImmutableMap<String, NSObject> overrideKeys;

    public PlistProcessStep(File input, File output, ImmutableMap<String, NSObject> additionalKeys, ImmutableMap<String, NSObject> overrideKeys) {
        this.input = input;
        this.output = output;
        this.additionalKeys = additionalKeys;
        this.overrideKeys = overrideKeys;
    }

    public void execute() {
        try {
            // Parse the input plist file
            NSDictionary rootDict = (NSDictionary) PropertyListParser.parse(input);

            // Add additional keys if they do not already exist
            for (Map.Entry<String, NSObject> entry : additionalKeys.entrySet()) {
                if (!rootDict.containsKey(entry.getKey())) {
                    rootDict.put(entry.getKey(), entry.getValue());
                }
            }

            // Override existing keys with the override keys map
            for (Map.Entry<String, NSObject> entry : overrideKeys.entrySet()) {
                rootDict.put(entry.getKey(), entry.getValue());
            }

            // Serialize the modified plist and write it to the output path
            try (FileOutputStream fos = new FileOutputStream(output)) {
                XMLPropertyListWriter.write(rootDict, fos);
            }

        } catch (Exception e) {
            System.err.println("Error processing plist file: " + e.getMessage());
            e.printStackTrace();
        }
    }

    public String getShortName() {
        return "PlistProcessor";
    }

    public String getDescription() {
        return "Processes a Property List (plist) file by adding new keys and overriding existing ones, then saves the modified plist to a specified output path.";
    }

    public static void main(String[] args) {
        // Example usage
        File inputFile = new File("path/to/input.plist");
        File outputFile = new File("path/to/output.plist");

        ImmutableMap<String, NSObject> additionalKeys = ImmutableMap.of(
                "newKey1", new NSObject(),
                "newKey2", new NSObject()
        );

import java.util.ArrayList;
import java.util.List;
 
public class ListRootedTrees {
    private static final List<Long> TREE_LIST = new ArrayList<>();
 
    private static final List<Integer> OFFSET = new ArrayList<>();
 
    static {
        for (int i = 0; i < 32; i++) {
            if (i == 1) {
                OFFSET.add(1);
            } else {
                OFFSET.add(0);
            }
        }
    }
 
    private static void append(long t) {
        TREE_LIST.add(1 | (t << 1));
    }
 
    private static void show(long t, int l) {
        while (l-- > 0) {
            if (t % 2 == 1) {
                System.out.print('(');
            } else {
                System.out.print(')');
            }
            t = t >> 1;
        }
    }
 
    private static void listTrees(int n) {
        for (int i = OFFSET.get(n); i < OFFSET.get(n + 1); i++) {
            show(TREE_LIST.get(i), n * 2);
            System.out.println();
        }
    }
 
    private static void assemble(int n, long t, int sl, int pos, int rem) {
        if (rem == 0) {
            append(t);
            return;
        }
 
        var pp = pos;
        var ss = sl;
 
        if (sl > rem) {
            ss = rem;
            pp = OFFSET.get(ss);
        } else if (pp >= OFFSET.get(ss + 1)) {
            ss--;
            if (ss == 0) {
                return;
            }
            pp = OFFSET.get(ss);
        }
 
        assemble(n, t << (2 * ss) | TREE_LIST.get(pp), ss, pp, rem - ss);
        assemble(n, t, ss, pp + 1, rem);
    }
 
    private static void makeTrees(int n) {
        if (OFFSET.get(n + 1) != 0) {
            return;
        }
        if (n > 0) {
            makeTrees(n - 1);
        }
        assemble(n, 0, n - 1, OFFSET.get(n - 1), n - 1);
        OFFSET.set(n + 1, TREE_LIST.size());
    }
 
    private static void test(int n) {
        if (n < 1 || n > 12) {
            throw new IllegalArgumentException("Argument must be between 1 and 12");
        }
 
        append(0);
 
        makeTrees(n);
        System.out.printf("Number of %d-trees: %d\n", n, OFFSET.get(n + 1) - OFFSET.get(n));
        listTrees(n);
    }
 
    public static void main(String[] args) {
        test(5);
    }
}

import java.util.Arrays;
 
public class SpecialVariables {
 
    public static void main(String[] args) {
 
        //String-Array args contains the command line parameters passed to the program
        //Note that the "Arrays.toString()"-call is just used for pretty-printing
        System.out.println(Arrays.toString(args));
 
        //<Classname>.class might qualify as a special variable, since it always contains a Class<T>-object that
        //is used in Reflection
        System.out.println(SpecialVariables.class);
 
 
        //The following are not really "variables", since they are properly encapsulated:
 
        //System.getenv() returns a String-String-Map of environment-variables
        System.out.println(System.getenv());
 
        //System.getProperties() returns a Map of "things somebody might want to know", including OS and architecture
        // the Java VM runs on, various paths like home direcoty of the user that runs the program, class (library) paths,
        System.out.println(System.getProperties());
 
        //Runtime.getRuntime() returns a Runtime-Object that contains "changing" data about the running Java VM's
        // environment, like available processor cores or available RAM
        System.out.println(Runtime.getRuntime().availableProcessors());
 
    }
}

public class AngleDifference {
 
    public static double getDifference(double b1, double b2) {
        double r = (b2 - b1) % 360.0;
        if (r < -180.0)
            r += 360.0;
        if (r >= 180.0)
            r -= 360.0;
        return r;
    }
 
    public static void main(String[] args) {
        System.out.println("Input in -180 to +180 range");
        System.out.println(getDifference(20.0, 45.0));
        System.out.println(getDifference(-45.0, 45.0));
        System.out.println(getDifference(-85.0, 90.0));
        System.out.println(getDifference(-95.0, 90.0));
        System.out.println(getDifference(-45.0, 125.0));
        System.out.println(getDifference(-45.0, 145.0));
        System.out.println(getDifference(-45.0, 125.0));
        System.out.println(getDifference(-45.0, 145.0));
        System.out.println(getDifference(29.4803, -88.6381));
        System.out.println(getDifference(-78.3251, -159.036));
 
        System.out.println("Input in wider range");
        System.out.println(getDifference(-70099.74233810938, 29840.67437876723));
        System.out.println(getDifference(-165313.6666297357, 33693.9894517456));
        System.out.println(getDifference(1174.8380510598456, -154146.66490124757));
        System.out.println(getDifference(60175.77306795546, 42213.07192354373));
    }
}

public static void selection_sort(Comparable[] array) {
    for (int i = 0; i < array.length - 1; i++) {
        int k = i;
        for (int j = i + 1; j < array.length; j++)
            if (array[j].compareTo(array[k]) < 0)
                k = j;
 
        if (k!= i) {
            Comparable tmp = array[i];
            array[i] = array[k];
            array[k] = tmp;
        }
    }
}
 
public static void main(String[] args) {
    Integer[] i = new Integer[] { 4, 9, 3, -2, 0, 7, -5, 1, 6, 8 };
    selection_sort(i);
    System.out.println(Arrays.toString(i));
 
    Short[] s = new Short[i.length];
    for (int j = 0; j < i.length; j++)
        s[j] = (short) -i[j];
    selection_sort(s);
    System.out.println(Arrays.toString(s));
 
    Character[] c = new Character[] { 'z', 'h', 'd', 'c', 'a' };
    selection_sort(c);
    System.out.println(Arrays.toString(c));
}

import java.util.Optional;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.OptionalLong;

public class OptionalShouldBeEmpty extends BasicErrorMessageFactory {

  private OptionalShouldBeEmpty(String message, Object... args) {
    super(message, args);
  }

  public static ErrorMessageFactory shouldBeEmpty(Optional<?> optional) {
    return new OptionalShouldBeEmpty("%nExpecting Optional to be empty, but it contained: <%s>", optional.get());
  }

  public static ErrorMessageFactory shouldBeEmpty(OptionalDouble optional) {
    return new OptionalShouldBeEmpty("%nExpecting OptionalDouble to be empty, but it contained: <%s>", optional.getAsDouble());
  }

  public static ErrorMessageFactory shouldBeEmpty(OptionalInt optional) {
    return new OptionalShouldBeEmpty("%nExpecting OptionalInt to be empty, but it contained: <%s>", optional.getAsInt());
  }

  public static ErrorMessageFactory shouldBeEmpty(OptionalLong optional) {
    return new OptionalShouldBeEmpty("%nExpecting OptionalLong to be empty, but it contained: <%s>", optional.getAsLong());
  }

  public static class BasicErrorMessageFactory implements ErrorMessageFactory {

    private final String message;
    private final Object[] arguments;

    public BasicErrorMessageFactory(String message, Object... arguments) {
      this.message = message;
      this.arguments = arguments;
    }

    @Override
    public String create(String description) {
      return String.format(message, arguments);
    }

    @Override
    public String toString() {
      return String.format(message, arguments);
    }
  }

  public interface ErrorMessageFactory {
    String create(String description);

    String toString();
  }
}

