    public SubMiniTab() {
        // Default constructor
    }

    public SubMiniTab(int count, String id, String key, String name, String param, boolean selected) {
        this.count = count;
        this.id = id;
        this.key = key;
        this.name = name;
        this.param = param;
        this.selected = selected;
