        sb.append("SubMiniTab [");
        sb.append("count=").append(count);
        sb.append(", id='").append(id).append('\'');
        sb.append(", key='").append(key).append('\'');
        sb.append(", name='").append(name).append('\'');
        sb.append(", param='").append(param).append('\'');
        sb.append(", selected=").append(selected);
        sb.append(']');
        return sb.toString();
    }

    public static void main(String[] args) {
        SubMiniTab subMiniTab = new SubMiniTab();
        subMiniTab.setCount(5);
        subMiniTab.setId("tab1");
        subMiniTab.setKey("key1");
        subMiniTab.setName("Tab One");
        subMiniTab.setParam("param1");
        subMiniTab.setSelected(true);

        System.out.println(subMiniTab);

        SubMiniTab anotherSubMiniTab = new SubMiniTab(10, "tab2", "key2", "Tab Two", "param2", false);
        System.out.println(anotherSubMiniTab);
    }
}

import java.io.*;

public class Converter {
    public static void main(String[] args) {
        try {
            // Open the file for reading
            FileInputStream countStream = new FileInputStream("Converter.dat");

            // Read the count from the file
            int count = countStream.read();

            // Close the file input stream
            countStream.close();

            // Increment the count
            count++;

            // Open the file for writing
            FileOutputStream updateStream = new FileOutputStream("Converter.dat");

            // Write the updated count to the file
            updateStream.write(count);

            // Close the file output stream
            updateStream.close();

            System.out.println("This program has been executed " + count + " times.");
        } catch (FileNotFoundException e) {
            // File doesn't exist yet, so start count at 1 and create file
            try {
                FileOutputStream createStream = new FileOutputStream("Converter.dat");
                createStream.write(1);
                createStream.close();
                System.out.println("This program has been executed 1 time.");
            } catch (IOException ex) {
                System.out.println("Error creating count file: " + ex.getMessage());
            }
        } catch (IOException e) {
            System.out.println("Error updating count file: " + e.getMessage());
        }
    }
}

