import java.io.*;
import java.util.*;

public class Validator {
    public static void main(String[] args) {
        FastScanner sc = new FastScanner();
        PrintWriter pw = new PrintWriter(System.out);

        int t = sc.ni();
        while (t-- > 0) {
            int n = sc.ni();
            long[] a = new long[n];
            for (int i = 0; i < n; i++) {
                a[i] = sc.nl();
            }

            int cnt = 0;
            pw.println(n);
            for (int i = 0; i < n; i++) {
                int max = (int) Math.max(a[i], 1);
                int min = (int) Math.min(a[i], 1);
                while (max % min != 0) {
                    max++;
                    a[i] = Math.min(a[i] + max - a[i], (long) 1e18);
                    pw.println((i + 1) + " " + (max - a[i]));
                    cnt++;
                }
            }
        }
        pw.close();
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int ni() {
            return Integer.parseInt(next());
        }

        long nl() {
            return Long.parseLong(next());
        }

        double nd() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

