import java.util.Scanner;

public class RakamlarToplami {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Bir sayi giriniz:");
        int remaining = input.nextInt();

        // Accumulate digit sum with a do-while loop instead of a plain while-loop.
        int total = 0;
        if (remaining > 0) {
            do {
                int lastDigit = remaining % 10;
                total = total + lastDigit;
                remaining /= 10;
            } while (remaining > 0);
        }

        System.out.println("Rakamlar toplami: " + total);

        input.close();
    }
}

public class Logger {
    public static void main(String[] args) {
        int number = 2;
        int count = 0;
        while (number < 10000) {
            if (isPrime(number)) {
                count++;
            }
            number++;
        }
        System.out.println("The number of prime numbers less than 10,000 is: " + count);
    }

    public static boolean isPrime(int number) {
        for (int divisor = 2; divisor <= number / 2; divisor++) {
            if (number % divisor == 0) {
                return false;
            }
        }
        return true;
    }
}

