// Based on https://www.cairographics.org/samples/gradient/
 
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.LinearGradientPaint;
import java.awt.RadialGradientPaint;
import java.awt.geom.Point2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
 
public class Sphere {
 
    public static void main(String[] args) throws IOException {
        final Color black = new Color(0, 0, 0);
        final Color white = new Color(255, 255, 255);
 
        final int size = 300;
        final double diameter = 0.6 * size;
 
        final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_RGB);
        final Graphics2D g2d = image.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
 
        final LinearGradientPaint linearGradient = new LinearGradientPaint(0, 0, 0, size, new float[]{0, 1}, new Color[]{white, black});
        g2d.setPaint(linearGradient);
        g2d.fillRect(0, 0, size, size);
 
        final Point2D point1 = new Point2D.Double(0.4 * size, 0.4 * size);
        final Point2D point2 = new Point2D.Double(0.45 * size, 0.4 * size);
        final RadialGradientPaint radialGradient = new RadialGradientPaint(point1, (float) (size * 0.5), point2, (float) (size * 0.1), new float[]{0, 1}, new Color[]{white, black});
 
        g2d.setPaint(radialGradient);
        g2d.drawOval((int) ((size - diameter) / 2), (int) ((size - diameter) / 2), (int) diameter, (int) diameter);
 
        ImageIO.write(image, "png", new File("sphere.png"));
    }
}

