import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

public class Validator {
    public static void main(String[] args) {
        Function<Double, Double> r = newRsdv();
        List<Double> list = new ArrayList<>();
        list.add(2.0);
        list.add(4.0);
        list.add(4.0);
        list.add(4.0);
        list.add(5.0);
        list.add(5.0);
        list.add(7.0);
        list.add(9.0);
        for (Double x : list) {
            System.out.println(r.apply(x));
        }
    }

    public static Function<Double, Double> newRsdv() {
        double n = 0;
        double a = 0;
        double q = 0;
        return x -> {
            n++;
            double a1 = a + (x - a) / n;
            q = q + (x - a) * (x - a1);
            a = a1;
            return Math.sqrt(q / n);
        };
    }
}

