            androidHttpTransport = new HttpTransportSE(SERVICE_URL);
            androidHttpTransport.call(SERVICE_NS + METHOD_NAME, envelope);

            SoapObject result = (SoapObject) envelope.bodyIn;
            String versionResponse = result.getProperty(0).toString();

            Log.d(TAG, "Version Check Response: " + versionResponse);
            return processVersionResponse(versionResponse);

