            String[] versionParts = response.split("\\|");
            if (versionParts.length >= 2) {
                versionCode = versionParts[0];
                String downloadUrl = versionParts[1];

import java.io.*;
import java.util.Iterator;
import java.util.Map;
import com.google.common.collect.Maps;

public class RegionFileCache {

    private static final Map<File, RegionFile> regionsByFilename = Maps.newHashMap();
    private static final int MAX_CACHE_SIZE = 256;

    public static synchronized RegionFile createOrLoadRegionFile(File worldDir, int chunkX, int chunkZ) {
        File regionDir = new File(worldDir, "region");
        File regionFile = new File(regionDir, "r." + (chunkX >> 5) + "." + (chunkZ >> 5) + ".mca");

        RegionFile region = regionsByFilename.get(regionFile);

        if (region != null) {
            return region;
        }

        if (!regionDir.exists()) {
            regionDir.mkdirs();
        }

        if (regionsByFilename.size() >= MAX_CACHE_SIZE) {
            clearRegionFileReferences();
        }

        region = new RegionFile(regionFile);
        regionsByFilename.put(regionFile, region);
        return region;
    }

    public static synchronized void clearRegionFileReferences() {
        Iterator<Map.Entry<File, RegionFile>> iterator = regionsByFilename.entrySet().iterator();

        while (iterator.hasNext()) {
            Map.Entry<File, RegionFile> entry = iterator.next();
            RegionFile region = entry.getValue();
            try {
                if (region != null) {
                    region.close();
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
            iterator.remove();
        }
    }

    public static DataInputStream getChunkInputStream(File worldDir, int chunkX, int chunkZ) {
        RegionFile regionFile = createOrLoadRegionFile(worldDir, chunkX, chunkZ);
        try {
            return regionFile.getChunkDataInputStream(chunkX & 31, chunkZ & 31);
        } catch (IOException e) {
            e.printStackTrace();
            return null;
        }

    }

    public static DataOutputStream getChunkOutputStream(File worldDir, int chunkX, int chunkZ) {
        RegionFile regionFile = createOrLoadRegionFile(worldDir, chunkX, chunkZ);
         try {
             return regionFile.getChunkDataOutputStream(chunkX & 31, chunkZ & 31);
         } catch (IOException e) {
             e.printStackTrace();
             return null;
        }
    }

