import java.util.Scanner;

public class BasamakSayisi {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Bir sayi giriniz:");
        int value = input.nextInt();

        // Count digits with a for-loop that keeps chopping off the last digit
        // instead of the original while-loop version.
        int digitCount;
        for (digitCount = 0; value > 0; digitCount++) {
            value /= 10;
        }

        System.out.println("Basamak sayisi: " + digitCount);

        input.close();
    }
}

