        String activityId = getStringFromJson(historicalData, HistoryJsonConstants.ACTIVITY_ID);

        HistoricActivityInstanceEntityManager historicActivityInstanceEntityManager = getHistoricActivityInstanceEntityManager(commandContext);
        HistoricActivityInstanceEntity historicActivityInstance = historicActivityInstanceEntityManager
            .findUnfinishedHistoricActivityInstance(executionId, activityId);

        if (historicActivityInstance != null) {
            historicActivityInstance.setEndTime(getDateFromJson(historicalData, HistoryJsonConstants.END_TIME));
            historicActivityInstance.setDeleteReason(getStringFromJson(historicalData, HistoryJsonConstants.DELETE_REASON));
            historicActivityInstance.setDurationInMillis(getDateFromJson(historicalData, HistoryJsonConstants.START_TIME).getTime(),
                historicActivityInstance.getEndTime().getTime());

            dispatchEvent(FlowableEngineEventType.HISTORIC_ACTIVITY_INSTANCE_ENDED, historicActivityInstance);
        }
    }
}

import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
