import java.util.logging.Level;
import java.util.logging.Logger;

public class VCardParameterCaseClasses<T extends VCardParameter> {
    private static final Logger LOGGER = Logger.getLogger(VCardParameterCaseClasses.class.getName());

    private final Class<T> parameterClass;
    private final List<Constructor<T>> constructors;

    public VCardParameterCaseClasses(Class<T> parameterClass) {
        this.parameterClass = Objects.requireNonNull(parameterClass, "Parameter class cannot be null");
        this.constructors = findSupportedConstructors();
    }

    private List<Constructor<T>> findSupportedConstructors() {
        List<Constructor<T>> validConstructors = new ArrayList<>();
        Constructor<?>[] declaredConstructors = parameterClass.getDeclaredConstructors();

        for (Constructor<?> constructor : declaredConstructors) {
            Class<?>[] parameterTypes = constructor.getParameterTypes();
            if (isValidConstructor(parameterTypes)) {
                @SuppressWarnings("unchecked")
                Constructor<T> typedConstructor = (Constructor<T>) constructor;
                validConstructors.add(typedConstructor);
            }
        }

        return validConstructors;
    }

    private boolean isValidConstructor(Class<?>[] parameterTypes) {
        return parameterTypes.length <= 2 &&
               Arrays.stream(parameterTypes).allMatch(this::isSupportedParameterType);
    }

    private boolean isSupportedParameterType(Class<?> type) {
        return type == String.class || type == Object.class;
    }

    public T create(String value) {
        for (Constructor<T> constructor : constructors) {
            try {
                Class<?>[] parameterTypes = constructor.getParameterTypes();
                if (parameterTypes.length == 0) {
                    T instance = constructor.newInstance();
                    return instance;
                } else if (parameterTypes.length == 1 && parameterTypes[0] == String.class) {
                    return constructor.newInstance(value);
                }
            } catch (Exception e) {
                LOGGER.log(Level.FINE, "Constructor instantiation failed", e);
            }
        }
        throw new IllegalArgumentException("Unable to create parameter instance: " + value);
    }

    public boolean matches(T object, String value) {
        if (object == null || value == null) {
            return false;
        }

import java.util.Scanner;

public class NumberCounter {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int[] counts = new int[101]; // array to hold counts of each number

        // read integers from user until 0 is entered
        int number;
        do {
            System.out.print("Enter an integer between 1 and 100 (0 to stop): ");
            number = input.nextInt();
            if (number >= 1 && number <= 100) {
                counts[number]++; // increment count for the entered number
            }
        } while (number != 0);

        // display the counts for each number
        for (int i = 1; i <= 100; i++) {
            if (counts[i] > 0) {
                System.out.println(i + " occurs " + counts[i] + " times");
            }
        }
    }
}

