public class FairShare {
    public static int turn(int base, int n) {
        int sum = 0;
        while (n!= 0) {
            int rem = n % base;
            n = n / base;
            sum = sum + rem;
        }
        return sum % base;
    }

    public static void fairshare(int base, int count) {
        System.out.print("Base %2d: " % [base]);
        for (int i = 0; i < count; i++) {
            int t = turn(base, i);
            System.out.print(" %2d" % [t]);
        }
        System.out.println();
    }

    public static void turnCount(int base, int count) {
        int[] cnt = new int[base];

        for (int i = 0; i < count; i++) {
            int t = turn(base, i);
            cnt[t] = cnt[t] + 1;
        }

        int minTurn = base * count;
        int maxTurn = -1;
        int portion = 0;
        for (int i = 0; i < base; i++) {
            if (cnt[i] > 0) {
                portion = portion + 1;
            }
            if (cnt[i] < minTurn) {
                minTurn = cnt[i];
            }
            if (cnt[i] > maxTurn) {
                maxTurn = cnt[i];
            }
        }

        System.out.print("  With %d people: " % [base]);
        if (0 == minTurn) {
            System.out.println("Only %d have a turn" % portion);
        } else if (minTurn == maxTurn) {
            System.out.println("%d" % [minTurn]);
        } else {
            System.out.println("%d or %d" % [minTurn, maxTurn]);
        }
    }

    public static void main(String[] args) {
        fairshare(2, 25);
        fairshare(3, 25);
        fairshare(5, 25);
        fairshare(11, 25);

        System.out.println("How many times does each get a turn in 50000 iterations?");
        turnCount(191, 50000);
        turnCount(1377, 50000);
        turnCount(49999, 50000);
        turnCount(50000, 50000);
        turnCount(50001, 50000);
    }
}

