import java.math.BigInteger;
 
public class SuperDNumbers {
 
    public static void main(String[] args) {
        for ( int i = 2 ; i <= 9 ; i++ ) {
            superD(i, 10);
        }
    }
 
    private static final void superD(int d, int max) {
        long start = System.currentTimeMillis();
        String test = "";
        for ( int i = 0 ; i < d ; i++ ) {
            test += (""+d);
        }
 
        int n = 0;
        int i = 0;
        System.out.printf("First %d super-%d numbers: %n", max, d);
        while ( n < max ) {
            i++;
            BigInteger val = BigInteger.valueOf(d).multiply(BigInteger.valueOf(i).pow(d));
            if ( val.toString().contains(test) ) {
                n++;
                System.out.printf("%d ", i);
            }
        }
        long end = System.currentTimeMillis();
        System.out.printf("%nRun time %d ms%n%n", end-start);
 
    }
 
}

public class Game {
    public List<int[]> ans = new ArrayList<int[]> ();
    public int[]dx = {0, 0, -1, 1};
    public int[]dy = {1, -1, 0, 0};
    public boolean check(int i, int j, int rows, int cols) {
        if (i < 0 || i >= rows || j < 0 || j >= cols) return false;
        return true;
    }
    public List<int[]> pacificAtlantic(int[][] matrix) {
        if (matrix == null || matrix.length == 0) return ans;
        int rows = matrix.length;
        int cols = matrix[0].length;
        boolean [][]pacific = new boolean[rows][cols];
        boolean [][]atlantic = new boolean[rows][cols];
        Queue<Integer> queue = new LinkedList<Integer> ();
        for (int i = 0; i < rows; i ++) {
                pacific[i][0] = true;
                queue.add(i * cols);
        }
        for (int i = 1; i < cols; i ++) {
                pacific[0][i] = true;
                queue.add(i);
        }
        while (!queue.isEmpty()) {
                int point = queue.poll();
                int x = point / cols;
                int y = point % cols;
                for (int i = 0; i < 4; i ++) {
                    int px = x + dx[i];
                    int py = y + dy[i];
                    if(check(px, py, rows, cols) && !pacific[px][py] && matrix[x][y] <= matrix[px][py]) {
                        pacific[px][py] = true;
                        queue.add(px * cols + py);
                    }
                }
        }
        for (int i = 0; i < rows; i ++) {
                atlantic[i][cols - 1] = true;
                queue.add(i * cols + cols - 1);
        }
        for (int i = 0; i < cols - 1; i ++) {
                atlantic[rows - 1][i] = true;
                queue.add((rows - 1) * cols + i);
        }
        while (!queue.isEmpty()) {
                int point = queue.poll();
                int x = point / cols;
                int y = point % cols;
                if (pacific[x][y] && atlantic[x][y]) ans.add(new int[]{x, y});
                for (int i = 0; i < 4; i ++) {
                    int px = x + dx[i];
                    int py = y + dy[i];
                    if(check(px, py, rows, cols) && !atlantic[px][py] && matrix[x][y] <= matrix[px][py]) {
                        atlantic[px][py] = true;
                        queue.add(px * cols + py);
                    }
                }
        }
        return ans;
    }
}

