import org.apache.commons.lang3.StringUtils;
import org.apache.commons.pool2.KeyedPooledObjectFactory;
import org.apache.commons.pool2.impl.GenericKeyedObjectPool;
import org.apache.commons.pool2.impl.GenericKeyedObjectPoolConfig;

import java.io.OutputStream;
import java.net.Socket;

public abstract class AbstractGraphiteMetricsSender {

    private static final String REPLACEMENT = "_";

    protected GenericKeyedObjectPool<SocketConnectionInfos, OutputStream> createSocketOutputStreamPool(
            KeyedPooledObjectFactory<SocketConnectionInfos, OutputStream> factory,
            GenericKeyedObjectPoolConfig<OutputStream> poolConfig) {

        poolConfig.setTestOnBorrow(true);
        poolConfig.setTestOnReturn(true);
        poolConfig.setTestWhileIdle(true);
        poolConfig.setTimeBetweenEvictionRunsMillis(30000);
        poolConfig.setNumTestsPerEvictionRun(-1);
        poolConfig.setMinEvictableIdleTimeMillis(60000);

        return new GenericKeyedObjectPool<>(factory, poolConfig);
    }

    /**
     * Sanitize a string to be Graphite compliant:
     * - replaces none alphanumeric characters by {@value #REPLACEMENT}
     * - deletes leading and trailing {@value #REPLACEMENT}
     *
     * @param string the String to sanitize
     * @return the Graphite compliant String
     */
    protected String sanitizeString(String string) {
        if (StringUtils.isBlank(string)) {
            return "";
        }

        String result = string.replaceAll("[^a-zA-Z0-9\\-]", REPLACEMENT);
        result = StringUtils.strip(result, REPLACEMENT);
        return result;
    }

    protected static class SocketConnectionInfos {
        private final String host;
        private final int port;

        public SocketConnectionInfos(String host, int port) {
            this.host = host;
            this.port = port;
        }

        public String getHost() {
            return host;
        }

        public int getPort() {
            return port;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;

            SocketConnectionInfos that = (SocketConnectionInfos) o;

            if (port != that.port) return false;
            return host.equals(that.host);
        }

        @Override
        public int hashCode() {
            int result = host.hashCode();
            result = 31 * result + port;
            return result;
        }
    }
}

