import net.sourceforge.plantuml.command.regex.RegexConcat;
import net.sourceforge.plantuml.command.regex.RegexLeaf;
import net.sourceforge.plantuml.command.regex.RegexResult;
import net.sourceforge.plantuml.cucadiagram.IEntity;
import net.sourceforge.plantuml.cucadiagram.AbstractClassOrObjectDiagram;
import net.sourceforge.plantuml.skin.VisibilityModifier;

public class CommandAddData extends SingleLineCommand2<AbstractClassOrObjectDiagram> {

    public CommandAddData() {
        super(getRegexConcat());
    }

    private static RegexConcat getRegexConcat() {
        return RegexConcat.build(CommandAddData.class.getName(),
            RegexLeaf.start(),
            new RegexLeaf("ENTITY", "([\\p{L}0-9_.]+)"),
            RegexLeaf.spaceOneOrMore(),
            new RegexLeaf("DATA", "([+\\-#]?[\\p{L}0-9_()]+)"),
            RegexLeaf.end());
    }

    @Override
    protected CommandExecutionResult executeArg(AbstractClassOrObjectDiagram diagram, LineLocation location, RegexResult arg) {
        final String entityName = arg.get("ENTITY", 0);
        final String data = arg.get("DATA", 0);

        IEntity entity = diagram.getOrCreateEntity(entityName);
        if (entity == null) {
            return CommandExecutionResult.error("Entity not found: " + entityName);
        }

        VisibilityModifier visibility = extractVisibilityModifier(data);
        String cleanData = data.replaceAll("[+\\-#]", "");

        if (cleanData.contains("(")) {
            entity.addMethod(cleanData, visibility);
        } else {
            entity.addField(cleanData, visibility);
        }

        diagram.setVisibilityModifierPresent(visibility != null);
        return CommandExecutionResult.ok();
    }

    private VisibilityModifier extractVisibilityModifier(String data) {
        if (data.startsWith("+")) {
            return VisibilityModifier.PUBLIC;
        } else if (data.startsWith("-")) {
            return VisibilityModifier.PRIVATE;
        } else if (data.startsWith("#")) {
            return VisibilityModifier.PROTECTED;
        }
        return null;
    }
}

