            if (f <= 9) {
                System.out.print(" "); //Leading space
            }
            System.out.printf("%-2.1f                 %.3f", feet, footToMeter(feet));
            System.out.print("              |            ");
            System.out.printf("%2.1f                   %.3f\n", meters, meterToFoot(meters));

        }
    }

    public static double footToMeter(double foot) {
        return 0.305 * foot;
