import java.util.HashMap;
import java.util.Map;

/**
 * Type-safe enumeration for representing the state of a deployment.
 */
public class StateType {

    /**
     * Deployment state indicating the application is running.
     */
    public static final StateType RUNNING = new StateType(1);

    /**
     * Deployment state indicating the application has completed deployment.
     */
    public static final StateType COMPLETED = new StateType(2);

    /**
     * Deployment state indicating the deployment has failed.
     */
    public static final StateType FAILED = new StateType(3);

    /**
     * Deployment state indicating the application has been released.
     */
    public static final StateType RELEASED = new StateType(4);

    private static final Map<Integer, StateType> stateTypes = new HashMap<>();
    private static final Map<StateType, String> stateDescs = new HashMap<>();

    static {
        stateTypes.put(RUNNING.getValue(), RUNNING);
