import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.*;

public class Codeforces {

    static class Pair {
        int left;
        int right;
        int length;

        Pair(int left, int right) {
            this.left = left;
            this.right = right;
            length = right - left + 1;
        }
    }

    static Scanner f = new Scanner(System.in);
    static PrintWriter out = new PrintWriter(System.out);
    static int mod = 1000_000_007;
    static final int MAX = Integer.MAX_VALUE;
    static final int MIN = Integer.MIN_VALUE;
    static boolean[] isPrime = new boolean[100005];

    public static void main(String[] args) {

        int t;
        t = 1;
        t = f.nextInt();
        while (t-- > 0) {
            solve();
        }

    }

    public static void solve() {

        int n = f.nextInt();
        if (n == 1) {
            System.out.println(1);
            return;
        }
        PriorityQueue<Pair> pq = new PriorityQueue<>(new Comparator<Pair>() {
            public int compare(Pair p1, Pair p2) {
                if (p1.length != p2.length)
                    return Integer.compare(p2.length, p1.length);
                else {
                    return Integer.compare(p1.left, p2.left);
                }
            }
        });

        pq.add(new Pair(1, n));
        int arr[] = new int[n];
        for (int i = 1; i <= n; i++) {
            Pair p = pq.poll();
            int l = p.left, r = p.right;
            int mid = 0;
            if(p.length%2 == 0){
                mid = (l + r - 1)/2;
            }
            else {
                mid = (l + r)/2;
            }

            arr[mid - 1] = i;
            if(l <= mid - 1)
                pq.add(new Pair(l, mid - 1));
            if(mid + 1 <= r)
                pq.add(new Pair(mid + 1, r));
        }

        for (int it : arr) {
            System.out.print(it + " ");
        }

        System.out.println();

        out.flush();
    }

    static int gcd(int a, int b) {
        if (a < b) {
            return gcd(b, a);
        }

        if (b == 0)
            return a;
        return gcd(b, a % b);
    }

    static boolean isPrime(long n) {
        if (n <= 1)
            return false;

        else if (n == 2)
            return true;

        else if (n % 2 == 0)
            return false;

        for (long i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i == 0)
                return false;
        }
        return true;
    }

import java.util.LinkedList;
import java.util.Queue;

class Counter {
    public int minKnightMoves(int x, int y) {
        // Since the board is symmetric, we can consider only the first quadrant
        x = Math.abs(x);
        y = Math.abs(y);

        // Possible moves of a knight
        int[][] directions = {
            {2, 1}, {1, 2}, {-1, 2}, {-2, 1},
            {-2, -1}, {-1, -2}, {1, -2}, {2, -1}
        };

        // BFS initialization
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[301][301];

        queue.offer(new int[]{0, 0});
        visited[0][0] = true;

        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();

                if (current[0] == x && current[1] == y) {
                    return steps;
                }

                for (int[] dir : directions) {
                    int newX = current[0] + dir[0];
                    int newY = current[1] + dir[1];

                    if (newX >= 0 && newY >= 0 && !visited[newX][newY]) {
                        visited[newX][newY] = true;
                        queue.offer(new int[]{newX, newY});
                    }
                }
            }

            steps++;
        }

        return -1; // This line should never be reached
    }
}

import java.util.*;
import java.util.regex.*;
import java.io.*;
 
public class DataMunging2 {
 
    public static final Pattern e = Pattern.compile("\\s+");
 
    public static void main(String[] args) {
        try {
            BufferedReader infile = new BufferedReader(new FileReader(args[0]));
            List<String> duplicates = new ArrayList<String>();
            Set<String> datestamps = new HashSet<String>(); //for the datestamps
 
            String eingabe;
            int all_ok = 0;//all_ok for lines in the given pattern e
            while ((eingabe = infile.readLine()) != null) {
                String[] fields = e.split(eingabe); //we tokenize on empty fields
                if (fields.length != 49) //we expect 49 fields in a record
                    System.out.println("Format not ok!");
                if (datestamps.add(fields[0])) { //not duplicated
                    int howoften = (fields.length - 1) / 2 ; //number of measurement
                                                             //devices and values
                    for (int n = 1; Integer.parseInt(fields[2*n]) >= 1; n++) {
                        if (n == howoften) {
                            all_ok++ ;
                            break ;
                        }
                    }
                } else {
                    duplicates.add(fields[0]); //first field holds datestamp
                }
            }
            infile.close();
            System.out.println("The following " + duplicates.size() + " datestamps were duplicated:");
            for (String x : duplicates)
                System.out.println(x);
            System.out.println(all_ok + " records were complete and ok!");
        } catch (IOException e) {
            System.err.println("Can't open file " + args[0]);
            System.exit(1);
        }
    }
}

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStreamReader;
import java.util.Hashtable;

public class LangBundle {
    private Hashtable<String, String> defaultMap;
    private Hashtable<String, String> userMap;
    private String defaultLanguage;

    public LangBundle(String defaultLanguage) {
        this.defaultLanguage = defaultLanguage;
        this.defaultMap = new Hashtable<>();
        this.userMap = new Hashtable<>();
    }

    public void setDefaultMap(String fileName) {
        loadMap(fileName, defaultMap);
    }

    public void loadBundle(String fileName) {
        loadMap(fileName, userMap);
    }

    private void loadMap(String fileName, Hashtable<String, String> map) {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(new FileInputStream(fileName), "UTF-8"))) {
            String line;
            while ((line = reader.readLine()) != null) {
                String[] parts = line.split("=", 2);
                if (parts.length == 2) {
                    String key = parts[0].trim();
                    String value = parts[1].trim();
                    map.put(key, value);
                }
            }
        } catch (Exception e) {
            System.err.println("Error loading language file: " + fileName);
            e.printStackTrace();
        }
    }

    public String getText(String key) {
        String value = userMap.get(key);
        if (value == null) {
            value = defaultMap.get(key);
        }
        return value != null ? value : "Translation not found";
    }

    public static void main(String[] args) {
        LangBundle langBundle = new LangBundle("en");

        // Load default language file
        langBundle.setDefaultMap("default_lang.txt");

        // Load user-defined language bundle if it exists
        langBundle.loadBundle("user_lang.txt");

        // Fetch some translations
        String greeting = langBundle.getText("greeting");
        String farewell = langBundle.getText("farewell");

        System.out.println("Greeting: " + greeting);
        System.out.println("Farewell: " + farewell);
    }
}

