public void writeToSessions(Object message, Set<IoSession> sessions) {
    for (IoSession session : sessions) {
        if (message instanceof IoBuffer) {
            session.write(((IoBuffer) message).duplicate());
        } else {
            session.write(message);
        }
    }
}

public void initialise(ParseException e, String str, int errorOffset) {
    String[][] context = new String[][]{{str.substring(Math.max(0, errorOffset - 50), errorOffset)},
                                          {str.substring(errorOffset, Math.min(str.length(), errorOffset + 50))}};

    MessageFormat format = new MessageFormat(e.getMessage());
    e.setMessage(format.format(context));
}

public static void setHotspotBounds(Drawable drawable, int left, int top, int right, int bottom) {
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {

            int size = (right - left) / 8;
            drawable.setHotspotBounds(left + size, top + size, right - size, bottom - size);
        } else {
            drawable.setBounds(left, top, right, bottom);
        }
    }

import org.bson.*;
import org.bson.codecs.CollectibleCodec;
import org.bson.codecs.DecoderContext;
import org.bson.codecs.EncoderContext;
import org.bson.codecs.configuration.CodecRegistry;
import org.bson.types.ObjectId;

import java.util.LinkedHashMap;
import java.util.Map;

public class ImmutableDocumentCodec implements CollectibleCodec<ImmutableDocument> {

    private static final String ID_FIELD_NAME = "_id";
    private final CodecRegistry codecRegistry;

    public ImmutableDocumentCodec(CodecRegistry codecRegistry) {
        this.codecRegistry = codecRegistry;
    }

    @Override
    public ImmutableDocument generateIdIfAbsentFromDocument(ImmutableDocument document) {
        if (!documentHasId(document)) {
            return new ImmutableDocument(new LinkedHashMap<>(document.getDocument())).withId(new ObjectId());
        }
        return document;
    }

    @Override
    public boolean documentHasId(ImmutableDocument document) {
        return document.getDocument().containsKey(ID_FIELD_NAME);
    }

    @Override
    public BsonValue getDocumentId(ImmutableDocument document) {
        if (!documentHasId(document)) {
            throw new IllegalStateException("Document does not contain an ID");
        }
        return new BsonObjectId((ObjectId) document.getDocument().get(ID_FIELD_NAME));
    }

    @Override
    public void encode(BsonWriter writer, ImmutableDocument value, EncoderContext encoderContext) {
        Document mutableDocument = new Document(new LinkedHashMap<>(value.getDocument()));
        codecRegistry.get(Document.class).encode(writer, mutableDocument, encoderContext);
    }

    @Override
    public ImmutableDocument decode(BsonReader reader, DecoderContext decoderContext) {
        Document mutableDocument = codecRegistry.get(Document.class).decode(reader, decoderContext);
        return new ImmutableDocument(mutableDocument);
    }

    @Override
    public Class<ImmutableDocument> getEncoderClass() {
        return ImmutableDocument.class;
    }
}

