     */
    public TemplateInformationControlCreator(int orientation)  {
        Assert.isLegal(orientation == SWT.RIGHT_TO_LEFT || orientation == SWT.LEFT_TO_RIGHT);
        fOrientation= orientation;
    }

    /*
     * @see org.eclipse.jface.text.IInformationControlCreator#createInformationControl(org.eclipse.swt.widgets.Shell)
     */
    public IInformationControl createInformationControl(Shell parent) {
        fControl= new SourceViewerInformationControl(parent, SWT.TOOL | fOrientation, SWT.NONE);
        fControl.addDisposeListener(new DisposeListener() {
            public void widgetDisposed(DisposeEvent e) {
                fControl= null;
            }
        });
        return fControl;
    }

    /*
     * @see org.eclipse.jface.text.IInformationControlCreatorExtension#canReuse(org.eclipse.jface.text.IInformationControl)
     */
    public boolean canReuse(IInformationControl control) {
        return fControl == control && fControl != null;
    }

    /*
     * @see org.eclipse.jface.text.IInformationControlCreatorExtension#canReplace(org.eclipse.jface.text.IInformationControlCreator)
     */
    public boolean canReplace(IInformationControlCreator creator) {
        return (creator != null && getClass() == creator.getClass());
    }
}

class Logger {
    public String longestDiverseString(int a, int b, int c) {
        int[] arr = new int[]{a, b, c};
        StringBuilder res = new StringBuilder();
        int prevIndex = -1;
        while (true) {
            int maxIndex = -1, maxCount = 0;
            for (int i = 0; i < arr.length; i++) {
                if (i != prevIndex && arr[i] > maxCount) {
                    maxIndex = i;
                    maxCount = arr[i];
                }
            }
            if (maxIndex < 0 || arr[maxIndex] <= 0) {
                break;
            }
            int count = arr[maxIndex];
            if (count == 1 || (prevIndex >= 0 && arr[maxIndex] < arr[prevIndex])) {
                res.append((char)('a' + maxIndex));
                arr[maxIndex]--;
            } else {
                res.append((char)('a' + maxIndex)).append((char)('a' + maxIndex));
                arr[maxIndex] -= 2;
            }
            prevIndex = maxIndex;
        }
        return res.toString();
    }
}

class Library {
    public int findFinalValue(int[] nums, int original) {
        HashMap<Integer, Integer> map = new HashMap<>();
        for(int x: nums) {
            map.put(x, 1);
        }
        while(map.get(original) != null) {
            original *= 2;
        }
        return original;
    }
}

int guessFluffedDataSize() {
    if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled()) SibTr.entry(this, tc, "guessFluffedDataSize");
    int total = 0;

    if (bodyMap != null) {

       total += FLUFFED_MAP_OVERHEAD;

       total += bodyMap.size() * FLUFFED_MAP_ENTRY_SIZE;
    }

    else {

      JsMsgPart part = getPayloadIfFluffed();
      if (part != null) {

        total += part.estimateFieldValueSize(JmsMapBodyAccess.BODY_DATA_ENTRY_NAME) * 2;
      }

      else {

        int payloadSize = jmo.getPayloadPart().getAssembledLengthIfKnown();
        if (payloadSize != -1) {
          int flatMapSize = payloadSize-FLATTENED_PAYLOAD_PART;

          int numEnts = flatMapSize / 30;
          if (numEnts > 0) {

            total += FLUFFED_MAP_OVERHEAD;
            total += numEnts * FLUFFED_MAP_ENTRY_SIZE;
          }
        }

        else {

          total += FLUFFED_MAP_OVERHEAD;

          total += getPayload().estimateFieldValueSize(JmsMapBodyAccess.BODY_DATA_ENTRY_NAME) * 2;
        }
      }
    }
    if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled()) SibTr.exit(this, tc, "guessFluffedDataSize",  total);
    return total;
  }

* Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Converter {
    public int sumEvenGrandparent(TreeNode root) {
        if(root==null) return 0;
        int sum=0;
        if(root.left!=null && root.left.left!=null && root.left.left.val%2==0) sum+=root.left.left.val;
        if(root.left!=null && root.left.right!=null && root.left.right.val%2==0) sum+=root.left.right.val;
        if(root.right!=null && root.right.left!=null && root.right.left.val%2==0) sum+=root.right.left.val;
        if(root.right!=null && root.right.right!=null && root.right.right.val%2==0) sum+=root.right.right.val;
        sum+=sumEvenGrandparent(root.left);
        sum+=sumEvenGrandparent(root.right);
        return sum;
    }
}

public class ArrayStatistics {
    public static void main(String[] args) {
        int[] numbers = {12, 45, 7, 23, 56, 89, 34};

        int min = numbers[0];
        int max = numbers[0];
        int sum = 0;

        for (int number : numbers) {
            if (number < min) min = number;
            if (number > max) max = number;
            sum += number;
        }

        double average = (double) sum / numbers.length;

        System.out.println("Min: " + min);
        System.out.println("Max: " + max);
        System.out.println("Sum: " + sum);
        System.out.printf("Average: %.2f%n", average);
    }
}

import java.math.BigDecimal;
import java.math.MathContext;
import java.util.Date;
 
public class AGM {
    public static void main(String[] args) {
        Date start = new Date();
        BigDecimal x0 = new BigDecimal("1");
        BigDecimal y0 = new BigDecimal("0.5");
        BigDecimal Z = new BigDecimal("0.25");
        y0 = y0.sqrt(MathContext.DECIMAL128);
        int n = 1;
        for (int i = 0; i < 8; i++) {
            BigDecimal resA = (x0.add(y0)).divide(new BigDecimal("2"), MathContext.DECIMAL128);
            BigDecimal resB = x0.multiply(y0);
            Z = Z.subtract(n.multiply(resA.subtract(x0).multiply(resA.subtract(x0))));
            n *= 2;
            x0 = resA;
            y0 = resB.sqrt(MathContext.DECIMAL128);
            Z = Z.subtract(n.multiply(x0.subtract(resA).multiply(x0.subtract(resA))));
            n *= 2;
        }
        x0 = x0.multiply(x0).divide(Z, MathContext.DECIMAL128);
        System.out.println("Took " + (new Date().getTime() - start.getTime()) + " ms for computation.");
        start = new Date();
        System.out.println(x0);
        System.out.println("Took " + (new Date().getTime() - start.getTime()) + " ms for output.");
    }
}

import java.util.Scanner;
import java.util.Stack;

public class ZookeeperGame {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        StringBuilder result = new StringBuilder();

        while (t-- > 0) {
            String s = scanner.next();
            Stack<Character> stack = new Stack<>();

            for (char c : s.toCharArray()) {
                if (!stack.isEmpty() && (stack.peek() == 'A' && c == 'B' || stack.peek() == 'B' && c == 'B')) {
                    stack.pop();
                } else {
                    stack.push(c);
                }
            }

            result.append(stack.size()).append('\n');
        }

        System.out.print(result);
        scanner.close();
    }
}

