private static Collection<Class<?>> filterInterfaces(Class<?> object, Class<?> base) {
    List<Class<?>> result = new ArrayList<>();
    for (Class<?> iface : object.getInterfaces()) {
        if (!base.isAssignableFrom(iface)) {
            result.add(iface);
        }
    }
    return result;
}

class Reader {
    public int longestStrChain(String[] words) {

        Comparator<String> cmp = new Comparator<String>() {
            public int compare(String s1, String s2) {
                return s1.length() - s2.length();
            }
        };

        Arrays.sort(words, cmp);

        Map<String, Integer> map = new HashMap<String, Integer>();

        int res = 1;
        for (String s: words) {
            int n = s.length();
            int cur = 1;
            for (int i = 0; i < n; ++i) {
                String pred = s.substring(0, i) + s.substring(i+1);
                if (map.containsKey(pred) && map.get(pred) + 1 > cur) cur = map.get(pred) + 1;
            }
            map.put(s, cur);
            if (cur > res) res = cur;
        }
        return res;

    }
}

public static boolean prime(long a){
   if(a == 2){
      return true;
   }else if(a <= 1 || a % 2 == 0){
      return false;
   }
   long max = (long)Math.sqrt(a);
   for(long n= 3; n <= max; n+= 2){
      if(a % n == 0){ return false; }
   }
   return true;
}

using System;
