    @Test
    public void testPropertiesOverride() {
        ConfigProperties configProperties = new ConfigProperties();
        Properties defaultProps = new Properties();
        defaultProps.setProperty(GIT_DAEMON_ENABLED, "false");
        defaultProps.setProperty(GIT_SSH_ENABLED, "false");
        defaultProps.setProperty(GIT_NIO_DIR_NAME, "git-repos");

        configProperties.setDefaults(defaultProps);

        Properties customProps = new Properties();
        customProps.setProperty(GIT_DAEMON_ENABLED, "true");
        customProps.setProperty(GIT_SSH_ENABLED, "true");
        customProps.setProperty(GIT_NIO_DIR_NAME, "custom-git-repos");

        configProperties.load(customProps);

        assertFalse(configProperties.getBoolean(GIT_DAEMON_ENABLED));
        assertFalse(configProperties.getBoolean(GIT_SSH_ENABLED));
        assertEquals("git-repos", configProperties.get(GIT_NIO_DIR_NAME));
    }

    @Test
    public void testCustomPropertiesWithNoDefaults() {
        ConfigProperties configProperties = new ConfigProperties();
        Properties customProps = new Properties();
        customProps.setProperty(GIT_DAEMON_ENABLED, "true");
        customProps.setProperty(GIT_SSH_ENABLED, "true");
        customProps.setProperty(GIT_NIO_DIR_NAME, "custom-git-repos");

        configProperties.load(customProps);

        assertTrue(configProperties.getBoolean(GIT_DAEMON_ENABLED));
        assertTrue(configProperties.getBoolean(GIT_SSH_ENABLED));

import com.sun.net.httpserver.*;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;

public class MyServer {
    public static void main(String[] args) throws IOException {
        HttpServer server = HttpServer.create(new InetSocketAddress(8000), 0);
        server.createContext("/test", new MyHandler());
        server.setExecutor(null); // creates a default executor
        server.start();
    }

    static class MyHandler implements HttpHandler {
        @Override
        public void handle(HttpExchange t) throws IOException {
            String response = "This is the response";
            t.sendResponseHeaders(200, response.length());
            OutputStream os = t.getResponseBody();
            os.write(response.getBytes());
            os.close();
        }
    }
}

import java.net.MalformedURLException;
import java.net.URL;
import org.wso2.carbon.messaging.CarbonMessage;
import org.wso2.carbon.messaging.CarbonCallback;
import org.wso2.carbon.messaging.Constants;
import org.wso2.carbon.gateway.core.ServiceContextHolder;
import org.wso2.carbon.gateway.core.config.ParameterHolder;
import org.wso2.carbon.gateway.core.outbound.AbstractOutboundEndpoint;

public class HTTPOutboundEndpoint extends AbstractOutboundEndpoint {

    private String uri;

    public HTTPOutboundEndpoint(String name, ParameterHolder parameters) {
        super(name, parameters);
        setUri(parameters.getParameter("uri").getValue());
    }

    @Override
    public void receive(CarbonMessage carbonMessage, CarbonCallback carbonCallback) throws Exception {
        processRequest(carbonMessage);
        ServiceContextHolder.getInstance().getSender().send(carbonMessage, carbonCallback);
    }

    private void processRequest(CarbonMessage carbonMessage) throws MalformedURLException {
        URL url = new URL(getUri());
        String host = url.getHost();
        int port = url.getPort() == -1 ? url.getDefaultPort() : url.getPort();
        String path = url.getPath();

        carbonMessage.setProperty(Constants.TO, getUri());
        carbonMessage.setProperty(Constants.PROTOCOL, url.getProtocol());
        carbonMessage.setProperty(Constants.HOST, host);
        carbonMessage.setProperty(Constants.PORT, port);

        if (port != 80 && port != 443) {
            carbonMessage.setHeader("Host", host + ":" + port);
        } else {
            carbonMessage.setHeader("Host", host);
        }

        carbonMessage.setHeader("Content-Length", String.valueOf(carbonMessage.getByteBuffer().remaining()));
    }

    private void setUri(String uri) {
        this.uri = uri;
    }

    private String getUri() {
        return uri;
    }

    @Override
    public void setParameters(ParameterHolder parameters) {
        super.setParameters(parameters);
        if (parameters.getParameter("uri") != null) {
            setUri(parameters.getParameter("uri").getValue());
        }
    }

    @Override
    public String toString() {
        return "HTTPOutboundEndpoint{" +
                "uri='" + uri + '\'' +
                '}';
    }
}

import java.util.Arrays;
 
public class CircleSort {
 
    public static void main(String[] args) {
        circleSort(new int[]{2, 14, 4, 6, 8, 1, 3, 5, 7, 11, 0, 13, 12, -1});
    }
 
    public static void circleSort(int[] arr) {
        if (arr.length > 0)
            do {
                System.out.println(Arrays.toString(arr));
            } while (circleSortR(arr, 0, arr.length - 1, 0) != 0);
    }
 
    private static int circleSortR(int[] arr, int lo, int hi, int numSwaps) {
        if (lo == hi)
            return numSwaps;
 
        int high = hi;
        int low = lo;
        int mid = (hi - lo) / 2;
 
        while (lo < hi) {
            if (arr[lo] > arr[hi]) {
                swap(arr, lo, hi);
                numSwaps++;
            }
            lo++;
            hi--;
        }
 
        if (lo == hi && arr[lo] > arr[hi + 1]) {
            swap(arr, lo, hi + 1);
            numSwaps++;
        }
 
        numSwaps = circleSortR(arr, low, low + mid, numSwaps);
        numSwaps = circleSortR(arr, low + mid + 1, high, numSwaps);
 
        return numSwaps;
    }
 
    private static void swap(int[] arr, int idx1, int idx2) {
        int tmp = arr[idx1];
        arr[idx1] = arr[idx2];
        arr[idx2] = tmp;
    }
}

