import java.io.IOException;

public class CopyStreamException extends IOException {
    private final long totalBytesTransferred;
    private final IOException ioException;

    public CopyStreamException(String message, long totalBytesTransferred, IOException ioException) {
        super(message);
        this.totalBytesTransferred = totalBytesTransferred;
        this.ioException = ioException;
        initCause(ioException);
    }

    public long getTotalBytesTransferred() {
        return totalBytesTransferred;
    }

    public IOException getIOException() {
        return ioException;
    }

    @Override
    public String toString() {
        return super.toString() + " [Total Bytes Transferred: " + totalBytesTransferred + ", Cause: " + ioException + "]";
    }
}

public int minOperations(int n) {
        //near logn solution: time 0(n) space o(1)

        int res = 0;
        //find the number of 1
        int count = 0;
        for(int i = 0;i<=n;i<<=1){
            if((n&i)!=0){
                count++;
            }
        }
        //calculate
        if(count%2==0){
            res = count/2+count/4;
        }else{
            res = (count+1)/2 + (count-1)/4;
        }
        return res;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class Anagram {

    public static void main(String[] args) throws IOException {
        URL url = new URL("http://www.puzzlers.org/pub/wordlists/unixdict.txt");
        BufferedReader reader = new BufferedReader(new InputStreamReader(url.openStream()));
        List<String> words = new ArrayList<>();
        String line;
        while ((line = reader.readLine())!= null) {
            words.add(line);
        }
        reader.close();
        Map<Integer, List<String>> grouped = words.stream()
                .filter(word -> {
                    char[] chars = word.toCharArray();
                    Arrays.sort(chars);
                    return new String(chars).equals(word);
                }).collect(Collectors.groupingBy(String::length));
        List<Integer> keys = new ArrayList<>(grouped.keySet());
        keys.sort(Comparator.reverseOrder());
        System.out.println(grouped.get(keys.get(0)));
    }
}

