private static String getCode(char c){
  switch(c){
    case 'B': case 'F': case 'P': case 'V':
      return "1";
    case 'C': case 'G': case 'J': case 'K':
    case 'Q': case 'S': case 'X': case 'Z':
      return "2";
    case 'D': case 'T':
      return "3";
    case 'L':
      return "4";
    case 'M': case 'N':
      return "5";
    case 'R':
      return "6";
    default:
      return "";
  }
}
 
public static String soundex(String s){
  String code, previous, soundex;
  code = s.toUpperCase().charAt(0) + "";
 
  // EDITED : previous = "7";
  previous = getCode(s.toUpperCase().charAt(0));
 
  for(int i = 1;i < s.length();i++){
    String current = getCode(s.toUpperCase().charAt(i));
    if(current.length() > 0 && !current.equals(previous)){
      code = code + current;
    }
    previous = current;
  }
  soundex = (code + "0000").substring(0, 4);
  return soundex;
}

import java.io.IOException;
import java.io.ObjectOutputStream;
import java.io.OutputStream;

public class JavaObjectOutput implements ObjectOutput {
    private ObjectOutputStream out;
    private boolean compact;

    public JavaObjectOutput(OutputStream outputStream, boolean compact) throws IOException {
        this.compact = compact;
        if (compact) {
            this.out = new CompactedObjectOutputStream(outputStream);
        } else {
            this.out = new ObjectOutputStream(outputStream);
        }
    }

    @Override
    public void writeBool(boolean v) throws IOException {
        out.writeBoolean(v);
    }

    @Override
    public void writeByte(byte v) throws IOException {
        out.writeByte(v);
    }

    @Override
    public void writeShort(short v) throws IOException {
        out.writeShort(v);
    }

    @Override
    public void writeInt(int v) throws IOException {
        out.writeInt(v);
    }

    @Override
    public void writeLong(long v) throws IOException {
        out.writeLong(v);
    }

    @Override
    public void writeFloat(float v) throws IOException {
        out.writeFloat(v);
    }

    @Override
    public void writeDouble(double v) throws IOException {
        out.writeDouble(v);
    }

    @Override
    public void writeBytes(byte[] v) throws IOException {
        if (v == null) {
            out.writeInt(-1);
        } else {
            out.writeInt(v.length);
            out.write(v);
        }
    }

    @Override
    public void writeBytes(byte[] v, int off, int len) throws IOException {
        if (v == null) {
            out.writeInt(-1);
        } else {
            out.writeInt(len);
            out.write(v, off, len);
        }
    }

    @Override
    public void writeUTF8(String v) throws IOException {
        if (v == null) {
            out.writeInt(-1);
        } else {
            out.writeUTF(v);
        }
    }

    @Override
    public void writeObject(Object o) throws IOException {
        if (o == null) {
            out.writeInt(-1);
        } else {
            out.writeObject(o);
        }
    }

    @Override
    public void flushBuffer() throws IOException {
        out.flush();
    }

    @Override
    public void close() throws IOException {
        out.close();
    }

    private static class CompactedObjectOutputStream extends ObjectOutputStream {
        public CompactedObjectOutputStream(OutputStream out) throws IOException {
            super(out);
        }

        @Override
        protected void writeStreamHeader() throws IOException {

