        LogEntry entry = new LogEntry();
        String[] parts = logLine.split(" ", 2);
        entry.timestamp = parts[0];
        entry.message = parts[1];

public void checkClassNameConflict(String className, DataSchema schema) {
  if (className == null || schema == null) {
    throw new IllegalArgumentException("className or schema cannot be null");
  }

  String qualifiedName = schema.getFullName();
  String[] splitName = qualifiedName.split("\\.");

  // getting the last part of the qualified name
  String schemaName = splitName[splitName.length - 1];

  if (!className.equals(schemaName)) {
    String errorMessage = "Class name conflict found. Expected class name is " + schemaName + ", but provided class name is " + className;
    throw new IllegalArgumentException(errorMessage);
  }
}

