        if( findGCD( a, b ) == a ){
            isBmulA = true;
        }

        if( findGCD( a, c ) == a ){
            isCmulA = true;
        }
        if( findGCD( c, b ) == b ){
            isCmulB = true;
        }

        long lcmAB = (A*B)/findGCD(a,b);
        long lcmAC = (A*C)/findGCD(a,c);
        long lcmBC = (C*B)/findGCD(c,b);
        long lcmABC = (lcmAB*C)/findGCD( lcmAB,C );

        while(low<high){

            ans = (low+high)/2;

            long countTillAns = 0;
            countTillAns += ans/A;

            countTillAns += ans/B;

            countTillAns += ans/C;
            // System.out.println( "Checking for " + ans + " and count = " + countTillAns);

                countTillAns -= ans/(lcmAB);

                countTillAns -= ans/(lcmAC);

                countTillAns -= ans/(lcmBC);
            countTillAns += ans/(lcmABC);

            // System.out.println( "Checking for " + ans + " and count = " + countTillAns);

            if( countTillAns == n ){

                long ansPoss = ans;

                while( ansPoss%a != 0 && ansPoss%b != 0 && ansPoss%c != 0 ){
                    ansPoss--;
                }

                return (int)ansPoss;

            }

            if( countTillAns < n ){
                low = ans+1;
            }
            else high = ans-1;

        }
        return (int)low;

    }
}

