public class GatewayDAO {

    private static GatewayDAO instance = new GatewayDAO();

    private GatewayDAO(){
        super();
    }

    public static GatewayDAO getInstance(){
        return instance;
    }

    /**
     *
     * @param manager
     * @param incId the incremental auto id in the db
     * @return
     */
    public DBRegisteredGateway getGatewayByIncId(EntityManager manager, int incId){

        DBRegisteredGateway dbRegisteredGateway = manager.find(DBRegisteredGateway.class, incId);
        return dbRegisteredGateway;
    }

    /**
     *
     * @param manager
     * @param name the gateway (registered) name
     * @return
     */
    public DBRegisteredGateway getGateway(EntityManager manager, String name){

        StringBuffer sb = new StringBuffer();
        sb.append("SELECT g ");
        sb.append("FROM DBRegisteredGateway g ");
        sb.append("WHERE g.registeredName = :gname ");

        DBRegisteredGateway result = manager.createQuery(sb.toString(), DBRegisteredGateway.class).
        setParameter("gname", name).
        getSingleResult();

        return result;
    }

    public List<DBRegisteredGateway> getInstanceList(EntityManager manager){
        List<DBRegisteredGateway> result =  manager.createQuery("SELECT instance FROM DBRegisteredGateway instance", DBRegisteredGateway.class).getResultList();

        return result;

    }

}

import java.util.*;

public class Calculator {
    public static void main(String[] args) {

        int lottery;
        int lotteryDigit1;
        int lotteryDigit2;
        do {
            lottery = 10 + (int) (Math.random() * 90);

            // Get digits from lottery
            lotteryDigit1 = lottery / 10;
            lotteryDigit2 = lottery % 10;
        } while (lotteryDigit1 == lotteryDigit2);

        System.out.println(lotteryDigit1 + " " + lotteryDigit2 + " " + lottery);

        // Prompt the user to enter a guess
        Scanner input = new Scanner(System.in);
        System.out.print("Enter your lottery pick (two digits): ");
        int guess = input.nextInt();

        // Get digits from guess
        int guessDigit1 = guess / 10;
        int guessDigit2 = guess % 10;

        System.out.println("The lottery number is " + lottery);

        // Check the guess
        if (guess == lottery)
            System.out.println("Exact match: you win $10,000");
        else if (guessDigit2 == lotteryDigit1
                && guessDigit1 == lotteryDigit2)
            System.out.println("Match all digits: you win $3,000");
        else if (guessDigit1 == lotteryDigit1
                || guessDigit1 == lotteryDigit2
                || guessDigit2 == lotteryDigit1
                || guessDigit2 == lotteryDigit2)
            System.out.println("Match one digit: you win $1,000");
        else
            System.out.println("Sorry, no match");

    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.stage.Stage;

public class Employee extends Application {
    private final double RADIUS = 80;
    private final double WIDTH = 200;
    private final double HEIGHT = 200;

    @Override
    public void start(Stage primaryStage) throws Exception {
        double[][] pointsInCircle = new double[5][2];
        Circle circle = new Circle(100,100, RADIUS);
        circle.setFill(Color.TRANSPARENT);
        circle.setStroke(Color.BLACK);

        for (int i = 0; i < 5; i++) {
            pointsInCircle[i] = randomPointOnCircle(circle.getCenterX(), circle.getCenterY(), RADIUS);
        }
        drawCircleWithPolygonPoints(pointsInCircle, primaryStage, circle);

    }

    private void drawCircleWithPolygonPoints(double[][] points, Stage stage, Circle circle) {
        Pane pane = new Pane();
        pane.getChildren().add(circle);

        for (int i = 0; i < points.length - 1; i++) {
            Line line = new Line(points[i][0], points[i][1], points[i + 1][0], points[i + 1][1]);
            pane.getChildren().add(line);
        }

        Scene scene = new Scene(pane, WIDTH, HEIGHT);
        stage.setScene(scene);
        stage.setTitle(getClass().getName());
        stage.show();

    }

    private double[] randomPointOnCircle(double centerX, double centerY, double radius) {
        double angle = Math.random() * 2 * Math.PI,
                A = Math.sqrt(Math.random()) * radius,
                B = Math.cos(angle) * A,
                C = Math.sin(angle) * A;
        return new double[]{centerX + B, centerY + C};
    }

    public static void main(String[] args) {
        launch(args);
    }

}

/**
 * Demonstrates implementing Runnable instead of extending Thread.
 * Each worker prints a label repeatedly on its own delay until told to stop.
 */
public class RunnableOrnegi implements Runnable {

    private final String label;          // text printed on every tick
    private final int intervalMillis;     // pause between ticks
    private volatile boolean active = true; // flips to false to request shutdown

    public RunnableOrnegi(String label, int intervalMillis) {
        this.label = label;
        this.intervalMillis = intervalMillis;
    }

    // Loop body executed on whichever Thread wraps this Runnable
    @Override
    public void run() {
        while (active) {
            System.out.println(Thread.currentThread().getName() + ": " + label);
            try {
                Thread.sleep(intervalMillis);
            } catch (InterruptedException interrupted) {
                System.out.println(Thread.currentThread().getName() + " kesildi.");
                return;
            }
        }
        System.out.println(Thread.currentThread().getName() + " durduruldu.");
    }

    // Signals the loop to end after the current sleep finishes
    public void requestStop() {
        active = false;
    }

    public static void main(String[] args) {
        RunnableOrnegi first = new RunnableOrnegi("ali", 1000);
        Thread workerOne = new Thread(first, "Thread-1");

        RunnableOrnegi second = new RunnableOrnegi("veli", 2000);
        Thread workerTwo = new Thread(second, "Thread-2");

        RunnableOrnegi third = new RunnableOrnegi("ayse", 3000);
        Thread workerThree = new Thread(third, "Thread-3");

        workerOne.start();
        workerTwo.start();
        workerThree.start();

        // Let the workers run for a while before shutting them down
        sleepQuietly(10000);

        System.out.println("Thread'ler durduruluyor...");
        first.requestStop();
        second.requestStop();
        third.requestStop();

        joinQuietly(workerOne);
        joinQuietly(workerTwo);
        joinQuietly(workerThree);

        System.out.println("Program sonlandi.");
    }

    private static void sleepQuietly(long millis) {
        try {
            Thread.sleep(millis);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }

    private static void joinQuietly(Thread thread) {
        try {
            thread.join();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}

import com.microsoft.azure.iothub.IotHubServiceboundMessage;
import com.microsoft.azure.iothub.IotHubEventCallback;

import java.io.IOException;
import java.net.URISyntaxException;

/** An interface for an IoT Hub transport. */
public interface IotHubTransport
{
    /**
     * Establishes a communication channel with an IoT Hub. If a channel is
     * already open, the function shall do nothing.
     *
     * @throws IOException if a communication channel cannot be
     * established.
     */
    void open() throws IOException;

    /**
     * Closes all resources used to communicate with an IoT Hub. Once {@code close()} is
     * called, the transport is no longer usable. If the transport is already
     * closed, the function shall do nothing.
     *
     * @throws IOException if an error occurs in closing the transport.
     */
    void close() throws IOException;

    /**
     * Adds a message to the transport queue.
     *
     * @param msg the message to be sent.
     * @param callback the callback to be invoked when a response for the
     * message is received.
     * @param callbackContext the context to be passed in when the callback is
     * invoked.
     */
    void addMessage(IotHubServiceboundMessage msg,
            IotHubEventCallback callback,
            Object callbackContext);

    /**
     * Sends all messages on the transport queue. If a previous send attempt had
     * failed, the function will attempt to resend the messages in the previous
     * attempt.
     *
     * @throws IOException if the server could not be reached.
     */
    void sendMessages() throws IOException;

    /** Invokes the callbacks for all completed requests. */
    void invokeCallbacks();

    /**
     * <p>
     * Invokes the message callback if a message is found and
     * responds to the IoT Hub on how the processed message should be
     * handled by the IoT Hub.
     * </p>
     * If no message callback is set, the function will do nothing.
     *
     * @throws IOException if the server could not be reached.
     */
    void handleMessage() throws IOException;

    /**
     * Returns {@code true} if the transport has no more messages to handle,
     * and {@code false} otherwise.
     *
     * @return {@code true} if the transport has no more messages to handle,
     * and {@code false} otherwise.
     */
    boolean isEmpty();
}

