public static Object deepCopy(Object original) throws IOException, ClassNotFoundException {
    // Create a byte array output stream to serialize original object
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    ObjectOutputStream output = new ObjectOutputStream(outputStream);
    output.writeObject(original);

    // Create a byte array input stream to deserialize the serialized object
    ByteArrayInputStream inputStream = new ByteArrayInputStream(outputStream.toByteArray());
    ObjectInputStream input = new ObjectInputStream(inputStream);
    return input.readObject(); // return the deep copy of the original object
}

