import java.util.*;

import java.lang.*;

import java.io.*;

/* Name of the class has to be "Main" only if the class is public. */

public class Codechef {

    public static void main(String[] args) throws java.lang.Exception {

        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        while (t-- > 0) {

            int n = sc.nextInt();

            int arr[] = new int[n];

            for(int i = 0;i<n;i++){

                arr[i] = sc.nextInt();

            }

            int count = n;

            if(n == 1){

                System.out.println(arr[0] % 2 == 0 ? 0 : -1);

            }

            else{

                for(int i = 0;i<n && count > 0;i++){

                while(arr[i] % 2 == 0 && arr[i] > 1 && count > 0){

                    arr[i] = arr[i]/2;

                    count--;

                    }

                }

                int ans = 0;

                ArrayList<Integer> ll = new ArrayList<Integer>();

                for(int i = 2;i<=n;i++){

                    int j=i;

                    int k = 0;

                    while(j % 2 == 0){

                        k++;

                        j/=2;

                    }

                    if(k > 0){

                        ll.add(k);

                    }

                }

                Collections.sort(ll);

                for(int i = ll.size()-1;i>=0 && count > 0;i--){

                    ans++;

                    count -= ll.get(i);

                }

                if(count <= 0){

                    System.out.println(ans);

                }

                else{

                    System.out.println(-1);

                }

            }

        }

    }

}

