public class LogEntryLambdaListener implements RequestHandler<S3Event, String> {
    private final AmazonS3 s3Client = AmazonS3ClientBuilder.defaultClient();
    private final ObjectMapper mapper = new ObjectMapper();
    private final LogSender kafkaSender = new LogSender();
    private static final Logger logger = LoggerFactory.getLogger(LogEntryLambdaListener.class);

    @Override
    public String handleRequest(S3Event s3event, Context context) {
        try {
            logger.info("Event: " + mapper.writeValueAsString(s3event));
            var records = s3event.getRecords();
            String srcBucket = records.get(0).getS3().getBucket().getName();
            String srcKey = records.get(0).getS3().getObject().getKey();

            S3Object s3Object = s3Client.getObject(srcBucket, srcKey);
            S3ObjectInputStream inputStream = s3Object.getObjectContent();
            BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream));

            String line;
            while ((line = reader.readLine()) != null) {
                LogEntry entry = LogEntry.parse(line);
                String json = mapper.writeValueAsString(entry);
                kafkaSender.sendMessage(json);
            }
            String testValue = System.getenv("TEST_KEY");
            logger.info("ENVIRONMENT VARIABLE TEST_KEY: " + testValue);
            return "Ok";

        } catch (Exception e) {
            logger.error("Error processing S3 event", e);
            throw new RuntimeException(e);
        }
    }
}

public abstract class MyAbstractList<E> implements MyList<E> {
    protected int size = 0; // The size of the list

    protected MyAbstractList() {
    }

    protected MyAbstractList(E[] objects) {
        for (int i = 0; i < objects.length; i++)
            add(objects[i]);
    }

    @Override
    public void add(E e) {
        add(size, e);
    }

    @Override
    public boolean isEmpty() {
        return size == 0;
    }

    @Override
    public int size() {
        return size;
    }

    @Override
    public boolean remove(E e) {
        if (indexOf(e) >= 0) {
            remove(indexOf(e));
            return true;
        } else
            return false;
    }

    /*---------------------------------------------  Exercise24_01 ---------------------------------------------------*/

    @Override
    public boolean addAll(MyList<E> otherList) {
        int startSize = size;
        for (E e : otherList) {
            if (!contains(e)) {
                add(e);
            }
        }
        return size == startSize;
    }

    @Override
    public boolean removeAll(MyList<E> otherList) {
        boolean changed = false;
        for (E e : otherList) {
            boolean removed = remove(e);
            if (removed) {
                changed = true;
            }
        }
        return changed;
    }

    @Override
    public boolean retainAll(MyList<E> otherList) {
        boolean changed = false;
        for (E e : this) {
            if (!otherList.contains(e)) {
                remove(indexOf(e));
                changed = true;
            }
        }
        return changed;
    }
}

class Helper {
    public int waysToSplitArray(int[] nums) {
        long[] sum = new long[nums.length];
        sum[0] = nums[0];
        for (int i=1; i<nums.length; i++) {
            sum[i] = nums[i] + sum[i-1];
        }

        int count = 0;
        for (int i=0; i<nums.length-1; i++) {
            if (sum[nums.length-1] - sum[i] <= sum[i]) count++;
        }
        return count;
    }
}

public static boolean perf(int n){
    int sum= 0;
    for(int i= 1;i < n;i++){
        if(n % i == 0){
            sum+= i;
        }
    }
    return sum == n;
}

import java.awt.Graphics;
import java.awt.image.BufferedImage;
import javax.swing.JFrame;
 
public class Mandelbrot extends JFrame {
 
    private final int MAX_ITER = 570;
    private final double ZOOM = 150;
    private BufferedImage I;
    private double zx, zy, cX, cY, tmp;
 
    public Mandelbrot() {
        super("Mandelbrot Set");
        setBounds(100, 100, 800, 600);
        setResizable(false);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        I = new BufferedImage(getWidth(), getHeight(), BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < getHeight(); y++) {
            for (int x = 0; x < getWidth(); x++) {
                zx = zy = 0;
                cX = (x - 400) / ZOOM;
                cY = (y - 300) / ZOOM;
                int iter = MAX_ITER;
                while (zx * zx + zy * zy < 4 && iter > 0) {
                    tmp = zx * zx - zy * zy + cX;
                    zy = 2.0 * zx * zy + cY;
                    zx = tmp;
                    iter--;
                }
                I.setRGB(x, y, iter | (iter << 8));
            }
        }
    }
 
    @Override
    public void paint(Graphics g) {
        g.drawImage(I, 0, 0, this);
    }
 
    public static void main(String[] args) {
        new Mandelbrot().setVisible(true);
    }
}

public static Class<?> box(Class<?> primitive) {
    if (!primitive.isPrimitive()) {
        return primitive;
    } else if (primitive == boolean.class) {
        return Boolean.class;
    } else if (primitive == byte.class) {
        return Byte.class;
    } else if (primitive == char.class) {
        return Character.class;
    } else if (primitive == double.class) {
        return Double.class;
    } else if (primitive == float.class) {
        return Float.class;
    } else if (primitive == int.class) {
        return Integer.class;
    } else if (primitive == long.class) {
        return Long.class;
    } else if (primitive == short.class) {
        return Short.class;
    } else {
        throw new IllegalArgumentException("Unexpected primitive type: " + primitive.getName());
    }
}

import java.util.Scanner;

public class Processor {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        while (t-- > 0) {

            int n = sc.nextInt();

            char[] str1 = new char[n + 5];

            char[] str2 = new char[n + 5];

            String ss = sc.next();

            String tt = sc.next();

            str1 = ss.toCharArray();

            str2 = tt.toCharArray();

            int x = 0, y = 0, v01 = 0, ans1 = 100000, ans2 = 100000;

            for (int i = 0; i < n; i++) {

                if (str1[i] == '1')

                    x++;

                if (str2[i] == '1')

                    y++;

                if (str1[i] != str2[i])

                    v01++;

            }

            if (x == y)

                ans1 = v01;

            if (y == n - x + 1)

                ans2 = n - v01;

            if (ans1 == 100000 && ans2 == 100000)

                System.out.println(-1);

            else

                System.out.println(Math.min(ans1, ans2));

        }

    }

}

import org.apache.felix.scr.annotations.Component;
