/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Validator {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new DeltaCodeInputReader(inputStream);
        DoubleIOProblem solver = new DoubleIOProblem();
        solver.solve(1, in, outputStream);
    }

    static class DoubleIOProblem {
        private int objective = 0;

        public DoubleIOProblem() {
            this.objective = 100009;
        }

        public void solve(int testNumber, DeltaCodeInputReader input, DoubleIOOutputWriter output) {
            int n = input.nextInt();
            int p = input.nextInt() * 10000;
            int answer = 0;
            if (p != 0) {
                for (int i = 0; i < n; i++) {
                    int divisor = gcd(p, objective);
                    p -= divisor;
                    objective -= divisor;
                    answer++;
                    if (p <= 0) {
                        break;
                    }
                    answersize++;
                }
            }
            if (p > 0) {
                answer = -1;
            }
            output.println(answer);
        }

    }

    static class DoubleIOOutputWriter {
        private final PrintWriter writer;

        public DoubleIOOutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(outputStream);
        }

        public DoubleIOOutputWriter(String fileName) {
            writer = new PrintWriter(fileName);
        }

        public void println(int i) {
            writer.println(i);
        }

        public void close() {
            writer.close();
        }

    }

    static class DeltaCodeInputReader {
        private final BufferedReader reader;
        private StringTokenizer tokenizer;

        public DeltaCodeInputReader(InputStream inputStream) {
            reader = new BufferedReader(new InputStreamReader(inputStream));
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }

public class Converter {
