class Game {

    public int visiblePoints(List<List<Integer>> points, int angle, List<Integer> location) {
        int lx = location.get(0);
        int ly = location.get(1);
        double[] degrees = new double[points.size() * 2];
        //init
        for (int i = 0; i < degrees.length; i++) {
            degrees[i] = Double.MAX_VALUE;
        }

        int cnt = 0, idx = 0;
        for (int i = 0; i < points.size(); i++) {
            List<Integer> p = points.get(i);
            int px = p.get(0);
            int py = p.get(1);
            if (px == lx) {
                if (py == ly) {
                    cnt++;
                } else if (py < ly) {
                    degrees[idx++] = 270;
                    degrees[idx++] = 270 + 360;
                } else {
                    degrees[idx++] = 90;
                    degrees[idx++] = 90 + 360;
                }
                continue;
            }
            if (py == ly) {
                if (px > lx) {
                    degrees[idx++] = 0;
                    degrees[idx++] = 0 + 360;
                } else {
                    degrees[idx++] = 180;
                    degrees[idx++] = 180 + 360;
                }
                continue;
            }

            double tan = ((double) (py - ly)) / (px - lx);
            double degree = Math.toDegrees(Math.atan(tan));
            if (py > ly && px > lx) {
                degrees[idx++] = degree;
                degrees[idx++] = degree + 360;
            } else if (py > ly && px < lx) {
                degrees[idx++] = 180 + degree;
                degrees[idx++] = 180 + degree + 360;
            } else if (py < ly && px < lx) {
                degrees[idx++] = 180 + degree;
                degrees[idx++] = 180 + degree + 360;
            } else {
                degrees[idx++] = degree;
                degrees[idx++] = degree + 360;
            }
        }

        Arrays.sort(degrees);
        int max=1,cur=1;
        int left=0;
        for (int i = 1; i < idx; i++) {
            while(degrees[i]-degrees[left]>angle){
                left++;
                cur--;
            }
            cur++;
            max=Math.max(max,cur);
        }
        return cnt+max;
    }

}

