class Game {
    public long minimumDifference(int[] nums) {
        int n = nums.length / 3;
        PriorityQueue<Integer> pq1 = new PriorityQueue<>((a, b) -> b - a);
        PriorityQueue<Integer> pq2 = new PriorityQueue<>();
        long sum1 = 0;
        long sum2 = 0;

        for (int i = 0; i < n; i++) {
            sum1 += nums[i];
            pq1.offer(nums[i]);
        }
        for (int i = 2 * n ; i < 3 * n; i++) {
            sum2 += nums[i];
            pq2.offer(nums[i]);
        }
        long a = sum1, b = sum2;
        long ans = sum1 - sum2;
        long[] left = new long[n];
        long[] right = new long[n];
        for (int i = n; i < 2 * n; i++) {
            pq1.offer(nums[i]);
            int p = pq1.poll();
            sum1 += nums[i] - p;
            left[i - n] = sum1;
        }
        for (int i = 2 * n - 1; i >= n; i--) {
            pq2.offer(nums[i]);
            sum2 += nums[i] - pq2.poll();
            right[i - n] = sum2;
        }
        ans = Math.min(a - sum2, sum1 - b);
        for (int i = n; i < 2 * n - 1; i++) {
            ans = Math.min(ans, left[i - n] - right[i - n + 1]);
        }
        // System.out.println(Arrays.toString(left));
        // System.out.println(Arrays.toString(right));
        return ans;
    }
}

public static TreeSet<Long> factors(long n)
{
 TreeSet<Long> factors = new TreeSet<Long>();
 factors.add(n);
 factors.add(1L);
 for(long test = n - 1; test >= Math.sqrt(n); test--)
  if(n % test == 0)
  {
   factors.add(test);
   factors.add(n / test);
  }
 return factors;
}

