/**
 * A class for parsing and building the vendor section of a source map.
 */
class VendorInfoBuilder implements SectionBuilder {

    @Override
    public String getSectionName() {
        return Constants.VendorSectionName;
    }

    @Override
    public void build(State state, String[] lines) throws SourceMapException {
        if (lines.length < 2) {
            throw new SourceMapException("Expected an identifier for vendor info");
        }

        String vendorId = lines[1];
        String[] viLines = Arrays.copyOfRange(lines, 2, lines.length);
        VendorInfo vendorInfo = new VendorInfo(vendorId, viLines);

        state.getStratum(state.currentStratum).addVendorInfo(vendorInfo);
    }
}

