import java.util.Random;
import java.util.Scanner;

public class Vector {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Random rand = new Random();
        for (int i = 0; i < 9; ++i) {
            String s = generate(i);
            System.out.println((balanced(s)? " ok: " : "bad: ") + s);
        }
    }

    public static String generate(int n, char left, char right) {
        String str = new String(new char[n]).replace("\0", String.valueOf(left)) + new String(new char[n]).replace("\0", String.valueOf(right));
        for (int i = 0; i < str.length(); i++) {
            int j = rand.nextInt(str.length());
            char temp = str.charAt(i);
            str = str.substring(0, i) + str.charAt(j) + str.substring(i + 1);
            str = str.substring(0, j) + temp + str.substring(j + 1);
        }
        return str;
    }

    public static boolean balanced(String str, char left, char right) {
        int count = 0;
        for (int i = 0; i < str.length(); i++) {
            if (str.charAt(i) == left) {
                count++;
            } else if (str.charAt(i) == right) {
                if (--count < 0) {
                    return false;
                }
            }
        }
        return count == 0;
    }
}

