                    for (int[] a : g[i]) {
                        ans[a[1]] = val++;
                    }
                    break;
                }
            }
            for (int i = 0; i < n; i++) {
                for (int[] a : g[i]) {

                    if (ans[a[1]] == -1) {
                        ans[a[1]] = val++;
                    }
                }
            }
            for (int a : ans) out.println(a);
