import java.util.Arrays;

public class Parser {
    public int[] numMovesStonesII(int[] stones) {
        Arrays.sort(stones);
        int n = stones.length;
        int minMoves = Integer.MAX_VALUE;
        int maxMoves = 0;

        // Calculate the maximum number of moves
        int maxGap = stones[n - 1] - stones[1] - n + 2;
        int maxGap2 = stones[n - 2] - stones[0] - n + 2;
        maxMoves = Math.max(maxGap, maxGap2);

        // Calculate the minimum number of moves
        int i = 0;
        for (int j = 0; j < n; ++j) {
            while (stones[j] - stones[i] + 1 > n) {
                ++i;
            }
            if (j - i + 1 == n - 1 && stones[j] - stones[i] == n - 2) {
                minMoves = Math.min(minMoves, 2);
            } else {
                minMoves = Math.min(minMoves, n - (j - i + 1));
            }
        }

        return new int[]{minMoves, maxMoves > 0 ? maxMoves - 1 : 0};
    }

    public static void main(String[] args) {
        Parser sol = new Parser();
        int[] stones1 = {7, 4, 9};
        int[] stones2 = {6, 5, 4, 3, 10};
        System.out.println(Arrays.toString(sol.numMovesStonesII(stones1))); // Output: [1, 2]
        System.out.println(Arrays.toString(sol.numMovesStonesII(stones2))); // Output: [2, 3]
    }
}

