public class Generator {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        CDivision solver = new CDivision();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class CDivision {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            long p = in.nextLong();
            long q = in.nextLong();
            if (p < q) {
                out.println(p);
            } else if (p % q != 0) {
                out.println(p);
            } else {
                ArrayList<Integer> list = distinctPrimeFactors((int) q);
                long ans = 1;
                for (int i = 0; i < list.size(); i++) {
                    long x = p;
                    while (x % q == 0) {
                        x /= (long) list.get(i);
                    }
                    ans = Math.max(ans, x);
                }
                out.println(ans);
            }
        }

        public ArrayList<Integer> distinctPrimeFactors(int n) {
            ArrayList<Integer> factorials = new ArrayList<>();
            int limit = (int) Math.sqrt(n);
            if (n % 2 == 0) {
                factorials.add(2);
                while (n % 2 == 0) n /= 2;
            }
            for (int i = 3; i <= limit; i += 2) {
                if (n % i == 0) {
                    factorials.add(i);
                    while (n % i == 0) n /= i;
                }
            }
            if (n > 2) factorials.add(n);
            return factorials;
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {

import java.util.concurrent.locks.Condition;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

import org.I0Itec.zkclient.exception.ZkNoNodeException;
import org.apache.log4j.Logger;

/**
 * @param <T>
 *            The data type that is being watched.
 */
public final class ContentWatcher<T extends Object> implements IZkDataListener {

    private static final Logger LOG = Logger.getLogger(ContentWatcher.class);

    private Lock _contentLock = new ReentrantLock(true);
    private Condition _contentAvailable = _contentLock.newCondition();

    private Holder<T> _content;
    private String _fileName;
    private ZkClient _zkClient;

    public ContentWatcher(ZkClient zkClient, String fileName) {
        _fileName = fileName;
        _zkClient = zkClient;
    }

    public void start() {
        _zkClient.subscribeDataChanges(_fileName, this);
        readData();
        LOG.debug("Started ContentWatcher");
    }

    @SuppressWarnings("unchecked")
    private void readData() {
        try {
            setContent((T) _zkClient.readData(_fileName));
        } catch (ZkNoNodeException e) {
            // ignore if the node has not yet been created
        }
    }

    public void stop() {
        _zkClient.unsubscribeDataChanges(_fileName, this);
    }

    public void setContent(T data) {
        LOG.debug("Received new data: " + data);
        _contentLock.lock();
        try {
            _content = new Holder<T>(data);
            _contentAvailable.signalAll();
        } finally {
            _contentLock.unlock();
        }
    }

    @SuppressWarnings("unchecked")
    @Override
    public void handleDataChange(String dataPath, Object data) {
        setContent((T) data);
    }

    @Override
    public void handleDataDeleted(String dataPath) {
        // ignore
    }

    public T getContent() throws InterruptedException {
        _contentLock.lock();
        try {
            while (_content == null) {
                _contentAvailable.await();
            }
            return _content.get();
        } finally {
            _contentLock.unlock();
        }
    }
}

