import java.util.Map;
import java.util.HashMap;
import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
 
public class entropy_narc {
 
    public static double log2(double d) {
        return Math.log(d) / Math.log(2.0);
    }
 
    public static double shannon(String s) {
        Map<Character, Integer> counters = new HashMap<Character, Integer>();
        for (char c : s.toCharArray()) {
            if (counters.containsKey(c)) {
                counters.put(c, counters.get(c) + 1);
            } else {
                counters.put(c, 1);
            }
        }
        double nn = s.length();
        double sum = 0.0;
        for (char key : counters.keySet()) {
            double term = counters.get(key) / nn;
            sum += term * log2(term);
        }
        return -sum;
    }
 
    public static void main(String[] args) {
        String prog = null;
        try {
            prog = new String(Files.readAllBytes(Paths.get("entropy_narc.java")));
        } catch (IOException e) {
            e.printStackTrace();
        }
        System.out.println("This program's entropy is " + String.format("%18.16f", shannon(prog)));
    }
}

