#include <iostream>
#include <vector>

bool checksum(std::vector<int>& arr, int start, int end, int sum) {
    for (int i = start; i < end-1; ++i) {
        for (int j = i+1; j < end; ++j) {
            for (int k = j+1; k <= end; ++k) {
                if (arr[i] + arr[j] + arr[k] == sum)
                    return true;
            }
        }
    }
    return false;
}

void solve() {
    int t, n, sum, val;
    std::cin >> t;
    for(int i = 0; i < t; ++i) {
        std::cin >> n;
        std::vector<int> arr(n);
        sum = 0;
        for(int j = 0; j < n; ++j) {
            std::cin >> val;
            arr[j] = val;
            sum += val;
        }
        if (sum % 2 == 0) {
            std::cout << "YES" << std::endl;
            if(checksum(arr, 0, n, sum)){
                // Print 3 values here
            }
            else
                std::cout << "NO" << std::endl;
        }
        else {
            std::cout << "NO" << std::endl;
        }
    }
}

