    private final List<Thread> lookupThreads = new ArrayList<>();

    public LoopHandler(int startLoop, int endLoop, int numThreads) {
        this.startLoop = startLoop;
        this.endLoop = endLoop;
        this.curLoop = startLoop;
        this.numThreads = numThreads;
    }

    @Override
    public void run() {
        LoopRange range;
        while ((range = loopGetRange()) != null) {
            loopDoRange(range.start, range.end);
        }
    }

    private synchronized LoopRange loopGetRange() {
        if (curLoop >= endLoop) {
            return null;
        }

        int start = curLoop;
        int rangeSize = (endLoop - curLoop) / numThreads;

        if (rangeSize == 0) {
            rangeSize = endLoop - curLoop;
        }

        int end = Math.min(curLoop + rangeSize, endLoop);
        curLoop = end;

        return new LoopRange(start, end);
    }

    public void loopProcess() throws InterruptedException {
        for (int i = 0; i < numThreads; i++) {
            Thread thread = new Thread(this);
            lookupThreads.add(thread);
            thread.start();
        }

        for (Thread thread : lookupThreads) {
            thread.join();
        }
    }

    protected void loopDoRange(int start, int end) {
        // This function is empty and should be implemented by subclasses
    }

    private static class LoopRange {
        public int start;
        public int end;

        public LoopRange(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }
}

