import java.util.Arrays;

class Helper {
    public int maxDistance(int[] position, int m) {

        Arrays.sort(position);

        return findLastPlacable(position, m, 1, position[position.length - 1] - position[0]);

    }

    private int findLastPlacable(int[] arr, int m, int lo, int hi) {
        if (lo == hi) {
            return lo;
        }

        int mid = lo + (hi - lo + 1) / 2;
        if (canPlace(arr, m, mid)) {
            return findLastPlacable(arr, m, mid, hi);
        } else {
            return findLastPlacable(arr, m, lo, mid - 1);
        }

    }

    private boolean canPlace(int[] arr, int m, int dist) {

        int cnt = 0;
        int prev = -1;
        for (int p : arr) {
            if (prev < 0) {
                cnt++;
                prev = p;
            } else if (p - prev >= dist) {
                cnt++;
                prev = p;
            }
            if (cnt == m) {
                return true;
            }
        }
        return false;

    }
}

