class Builder {
    public long[] kthPalindrome(int[] queries, int intLength) {
        int len = queries.length;
        long[] result = new long[len];
        int posNum = (intLength + 1) / 2;
        long istart = 1;
        for(int i = 0; i < posNum - 1; i++){
            istart *= 10;
        }
        long iend = istart * 10 - 1;
        for(int i = 0; i < len; i++){
            if(queries[i] > iend - istart + 1){
                result[i] = -1;
            } else {
                long r = istart + queries[i] - 1;
                long res = r;
                long tmp = r;
                if(intLength % 2 == 1){
                    tmp = tmp / 10;
                }
                while(tmp > 0){
                    res = res * 10 + tmp % 10;
                    tmp = tmp / 10;
                }
                result[i] = res;
            }
        }
        return result;
    }
}

class Timer {

    public List<Integer> eventualSafeNodes(int[][] graph) {
        int n = graph.length;
        List<Integer> ans = new ArrayList();
        if (n == 0) {
            return ans;
        }

        boolean[] isGood = new boolean[n];
        int[] outDegrees = new int[n];
        List<List<Integer>> inDegreeNodes = new ArrayList<>(n);
        for (int i=0; i<n; i++) {
            inDegreeNodes.add(new ArrayList<Integer>());
        }
        for (int i=0; i<n; i++) {
            outDegrees[i] = graph[i].length;
            for (int j=0; j<graph[i].length; j++) {
                inDegreeNodes.get(graph[i][j]).add(i);
            }
        }

        while (true) {
            List<Integer> candidates = new ArrayList<Integer>();

            for (int i=0; i<n; i++) {
                if (outDegrees[i] == 0 && !isGood[i]) {
                    candidates.add(i);
                }
            }

            if (candidates.size() > 0) {
                for (int c:candidates) {
                    for (int node:inDegreeNodes.get(c)) {
                        outDegrees[node]--;
                    }

                    isGood[c] = true;
                }
            } else {
                break;
            }
        }

        for (int i=0; i<n; i++) {
            if (isGood[i]) {
                ans.add(i);
            }
        }

        return ans;
    }
}

class Logger {
    public int minDays(int n) {
        Set<Integer> seen = new HashSet<>();
        Queue<Integer> q = new LinkedList<>();
        q.add(n);
        int steps = 0;
        while (!q.isEmpty()) {
            int size = q.size();
            while (size-- > 0) {
                int cur = q.remove();
                if (cur == 0) return steps;
                if (seen.add(cur - 1))
                    q.add(cur - 1);
                if (cur % 2 == 0 && seen.add(cur / 2))
                    q.add(cur / 2);
                if (cur % 3 == 0 && seen.add(cur - 2 * (cur / 3)))
                    q.add(cur - 2 * (cur / 3));
            }
            ++steps;
        }
        return steps;
    }
}

