public class Cache {
    public int distributeCandies(int[] candies) {
        if(candies == null || candies.length == 0) return 0;
        Map<Integer, Integer> map = new HashMap<>();
        for(int i=0; i<candies.length; i++) {
            int count = map.getOrDefault(candies[i], 0);
            map.put(candies[i], count+1);
        }

        int size = candies.length;
        return Math.min(map.size(), size /2);

    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class AttractiveNumbers {
 
    private static final int MAX = 120;
 
    private static boolean isPrime(int num) {
        return IntStream.range(2, num).noneMatch(i -> num % i == 0);
    }
 
    private static List<Integer> extractPrimeFactor(int num) {
        List<Integer> factors = new ArrayList<>();
        int i = 2;
        while (i <= num) {
            if (num % i == 0) {
                factors.add(i);
                num /= i;
            } else {
                i++;
            }
        }
        return factors;
    }
 
    private static List<Integer> factorize(int num) {
        return extractPrimeFactor(num).stream().map(i -> i).collect(Collectors.toList());
    }
 
    public static void main(String[] args) {
        List<Integer> output = IntStream.range(4, MAX + 1)
               .filter(i -> isPrime(factorize(i).size()))
               .boxed()
               .collect(Collectors.toList());
        System.out.println("The attractive numbers up to and including 120 are\n" + output);
    }
}

public final class StateType {

    // Integer constants for each state
    public static final int RUNNING_INT = 0;
    public static final int COMPLETED_INT = 1;
    public static final int FAILED_INT = 2;
    public static final int RELEASED_INT = 3;

    // StateType instances for each state
    public static final StateType RUNNING = new StateType(RUNNING_INT, "Running");
    public static final StateType COMPLETED = new StateType(COMPLETED_INT, "Completed");
    public static final StateType FAILED = new StateType(FAILED_INT, "Failed");
    public static final StateType RELEASED = new StateType(RELEASED_INT, "Released");

    // Arrays to hold all state types and descriptions
    private static final StateType[] stateTypes = {RUNNING, COMPLETED, FAILED, RELEASED};
    private static final String[] stateDescs = {"Running", "Completed", "Failed", "Released"};

    // Instance variables
    private final int value;
    private final String description;

    // Private constructor to enforce immutability
    private StateType(int value, String description) {
        this.value = value;
        this.description = description;
    }

    // Get the integer value of the state
    public int getValue() {
        return value;
    }

    // Get the description of the state
    public String getDescription() {
        return description;
    }

    // Get the array of state descriptions
    public static String[] getStringTable() {
        return stateDescs.clone();
    }

    // Get the array of state types
    public static StateType[] getEnumValueTable() {
        return stateTypes.clone();
    }

    // Retrieve a state type based on an integer value
    public static StateType getStateType(int type) {
        for (StateType state : stateTypes) {
            if (state.getValue() == type) {
                return state;
            }
        }
        throw new IllegalArgumentException("Invalid state type: " + type);
    }

    // Override toString to return the description
    @Override
    public String toString() {
        return description;
    }

    // Get the offset for the first state value
    public static int getOffset() {
        return RUNNING_INT;
    }

    // Example usage
    public static void main(String[] args) {
        StateType state = StateType.getStateType(StateType.RUNNING_INT);
        System.out.println("State: " + state.toString());
        System.out.println("Value: " + state.getValue());
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class SquareFree {
 
    public static void main(String[] args) {
        System.out.println(IntStream.rangeClosed(1, 145)
               .filter(SquareFree::isSquareFree)
               .boxed()
               .collect(Collectors.groupingBy(i -> i / 20))
               .values()
               .stream()
               .map(l -> l.stream().map(Object::toString).collect(Collectors.joining(" ")))
               .collect(Collectors.joining("\n")));
        System.out.println();
 
        long m = 1000000000000L;
        System.out.println(IntStream.rangeClosed(0, 145)
               .mapToLong(i -> m + i)
               .filter(SquareFree::isSquareFree)
               .boxed()
               .collect(Collectors.groupingBy(i -> i / 6))
               .values()
               .stream()
               .map(l -> l.stream().map(Object::toString).collect(Collectors.joining(" ")))
               .collect(Collectors.joining("\n")));
        System.out.println();
 
        int[] markers = {100, 1000, 10000, 100000, 1000000};
        int count = 0;
        for (int n = 1; n <= 1000000; n++) {
            if (isSquareFree(n)) {
                count++;
            }
            if (IntStream.of(markers).anyMatch(i -> i == n)) {
                System.out.println(count + " square-frees upto " + n);
            }
        }
    }
 
    private static boolean isSquareFree(int n) {
        List<Integer> primeFactors = primeFactors(n);
        return primeFactors.stream().distinct().noneMatch(i -> Collections.frequency(primeFactors, i) > 1);
    }
 
    private static List<Integer> primeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        for (int i = 2; i <= n / i; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
        }
        if (n > 1) {
            factors.add(n);
        }
        return factors;
    }
}

