import java.util.*;
public class Helper {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            String s = scanner.next();
            int[] count = new int[3];
            for (int i = 0; i < n; i++) {
                count[s.charAt(i) - 'a']++;
            }
            for (int i = 0; i < n; i++) {
                if (count[0] > count[1] && count[0] > count[2]) {
                    System.out.println(1);
                    break;
                } else {
                    int[] tempCount = new int[3];
                    for (int j = i; j < n; j++) {
                        tempCount[s.charAt(j) - 'a']++;
                        if (tempCount[0] > tempCount[1] && tempCount[0] > tempCount[2]) {
                            System.out.println(tempCount[0] - tempCount[1] < 2 ? tempCount[0] - tempCount[1] + 1 : 3);
                            break;
                        }
                    }
                    if (i == n - 1) {
                        System.out.println(-1);
                        break;
                    }
                }
            }
        }
    }
}

import java.util.*;

interface Generator<T> {
    T next();
}

class FilmGenerator implements Generator<String> {
    private static final String[] FILMNAME = {
            "Snow White", "Star Wars", "Casablanca", "The Lion King", "Titanic"
    };
    private static final int LENGTH = FILMNAME.length;
    private int id = 0;
    private int cursor = 0;

    @Override
    public String next() {
        String film = FILMNAME[cursor];
        cursor = (cursor + 1) % LENGTH;
        return film;
    }
}

public class Converter {
    static Generator<String> getFilmGenerator() {
        return new FilmGenerator();
    }

    static String[] getFilms(String[] array) {
        Generator<String> gen = getFilmGenerator();
        for (int i = 0; i < array.length; i++) {
            array[i] = gen.next();
        }
        return array;
    }

    static Collection<String> getFilms(Collection<String> c, int filmNum) {
        Generator<String> gen = getFilmGenerator();
        for (int i = 0; i < filmNum; i++) {
            c.add(gen.next());
        }
        return c;
    }

    @SuppressWarnings({"unchecked","rawtypes"})
    public static void main(String[] args) {
        int size = 7;
        System.out.println(Arrays.toString(getFilms(new String[size])));

        List arrayList = new ArrayList();
        System.out.println(getFilms(arrayList, size));
        List linkedList = new LinkedList();
        System.out.println(getFilms(linkedList, size));

        Set hashSet = new HashSet();
        System.out.println(getFilms(hashSet, size));
        Set linkedHashSet = new LinkedHashSet();
        System.out.println(getFilms(linkedHashSet, size));
        Set treeSet = new TreeSet();
        System.out.println(getFilms(treeSet, size));
    }
}

import java.awt.geom.Point2D;

public class Calculator {
    public static void main(String[] args) {
        Point2D pt = new Point2D.Double(1, 0);
        double theta = Math.PI / 2; // rotate 90 degrees
        Point2D solution = new Point2D.Double();
        rotate(theta, pt, solution);
        System.out.println("Rotated point: (" + solution.getX() + ", " + solution.getY() + ")");
    }

    public static void rotate(double theta, Point2D pt, Point2D solution) {
        double cosTheta = Math.cos(theta);
        double sinTheta = Math.sin(theta);

        double x = cosTheta * pt.getX() - sinTheta * pt.getY();
        double y = sinTheta * pt.getX() + cosTheta * pt.getY();

        solution.setLocation(x, y);
    }
}

