public interface BrowserParts {

    /** Called before the activity's content view is inflated. */
    void preInflationStartup();

    /**
     * Called after the activity's content view is inflated.  Responsible for setting the content
     * view on the activity and loading the native library.
     */
    void setContentViewAndLoadLibrary();

    /** Called after the activity's content view is inflated and native library is loaded. */
    void postInflationStartup();

    /**
     * Starts preconnecting to the URL associated with this activity.
     *
     * This should only be called after native has loaded and all view inflation and
     * fragment initialization has finished, as the preconnect is lower priority than
     * those tasks.
     */
    void maybePreconnect();

    /** Initialize the compositor, this must be called after the native library is loaded. */
    void initializeCompositor();

    /**
     * Initialize the state that depends on native library, such as creating the singleton
     * controllers and starting the native processes.
     */
    void initializeState();

    /** Called when the native library has been fully initialized. */
    void finishNativeInitialization();

    /**
     * Called when the startup failed at some point.  If this is called, the activity is
     * responsible for calling either {@link #destroy()} or {@link #stop()}.
     */
    void onStartupFailure();

     /**
      * @return True if the activity has been destroyed.
