class Manager {
    public int[] minOperations(int[] nums, int[] queries) {
        Arrays.sort(nums);
        int n = nums.length;
        long[] prefixSum = new long[n + 1];
        for (int i = 0; i < n; i++) {
            prefixSum[i + 1] = prefixSum[i] + nums[i];
        }
        int m = queries.length;
        int[] answer = new int[m];
        for (int i = 0; i < m; i++) {
            int query = queries[i];
            int idx = binarySearch(nums, query);
            long leftSum = prefixSum[idx];
            long rightSum = prefixSum[n] - prefixSum[idx];
            long leftCount = idx;
            long rightCount = n - idx;
            answer[i] = (int) (Math.abs(leftSum - leftCount * (long) query) + Math.abs(rightSum - rightCount * (long) query));
        }
        return answer;
    }

    private int binarySearch(int[] nums, int target) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return left;
    }
}

