public class Builder {
    public int findBestValue(int[] arr, int target) {
        int max = 0;
        int sum = 0;
        for (int num : arr) {
            max = Math.max(max, num);
            sum += num;
        }
        if (sum <= target) return max;
        int left = 0, right = max;
        while (left < right) {
            int mid = (left + right) / 2;
            int curSum = getSum(arr, mid);
            if (curSum < target) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        int sum1 = getSum(arr, left - 1);
        int sum2 = getSum(arr, left);
        if (Math.abs(target - sum1) <= Math.abs(target - sum2)) return left - 1;
        return left;
    }

    private int getSum(int[] arr, int mid) {
        int sum = 0;
        for (int num : arr) {
            sum += Math.min(num, mid);
        }
        return sum;
    }
}

import java.util.Scanner;

/*
 * Bu program bir topun zeminde ziplama hareketini adim adim simule eder.
 *
 * Her saniyede topun yuksekligi mevcut hiza gore guncellenir, hiz ise
 * yer cekiminden dolayi azalir. Yukseklik negatife dustugunde top zemine
 * carpmis kabul edilir; hiz yonu ters cevrilip yarisina indirilerek
 * bir sonraki ziplama baslatilir.
 */

public class Ziplama {

  public static void main(String[] args) {

    Scanner girdiOkuyucu = new Scanner(System.in);

    System.out.print("Ilk hizi giriniz: ");
    double mevcutHiz = girdiOkuyucu.nextDouble();
    girdiOkuyucu.close();

    double mevcutYukseklik = 0;
    double gecenSure = 0;
    int ziplamaSayaci = 0;
    final int hedefZiplama = 5;
    final double yerCekimi = 32;

    for (;;) {
      if (ziplamaSayaci >= hedefZiplama) {
        break;
      }

      System.out.println("Zaman: " + gecenSure + " saniye " + " Yukseklik: " + mevcutYukseklik + " feet " + " Hiz: " + mevcutHiz);

      mevcutYukseklik += mevcutHiz;
      mevcutHiz -= yerCekimi;

      if (mevcutYukseklik < 0) {
        mevcutHiz *= -0.5;
        mevcutYukseklik = 0;
        ziplamaSayaci++;
      }

      gecenSure++;
    }
  }
}

