import java.nio.charset.Charset;
import java.nio.charset.CharsetDecoder;
import java.nio.charset.CharsetEncoder;

class IconvCharset extends Charset {
    private final IconvMetaData info;

    IconvCharset(IconvMetaData info) {
        super(info.name, info.aliases);
        this.info = info;

        if (info.hasDecoder) {
            try {
                newDecoder();
            } catch (Exception e) {
                throw new IllegalArgumentException(
                        "Decoder not supported for " + info.name);
            }
        }

        if (info.hasEncoder) {
            try {
                newEncoder();
            } catch (Exception e) {
                throw new IllegalArgumentException(
                        "Encoder not supported for " + info.name);
            }
        }
    }

    public boolean contains(Charset cs) {
        return false;
    }

    public CharsetDecoder newDecoder() {
        if (!info.hasDecoder)
            throw new UnsupportedOperationException();
        try {
            return new IconvDecoder(this, info.name);
        } catch (Exception e) { // Example of exception handling
            throw new UnsupportedOperationException(e.getMessage());
        }
    }

    public CharsetEncoder newEncoder() {
        if (!info.hasEncoder)
            throw new UnsupportedOperationException();
        try {
            return new IconvEncoder(this, info.name);
        } catch (Exception e) { // Example of exception handling
            throw new UnsupportedOperationException(e.getMessage());
        }
    }
}

