import java.awt.Color;
import java.awt.Graphics;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;
import java.awt.image.BufferedImage;
import javax.swing.JFrame;
import javax.swing.JPanel;
 
public class GrayStripes extends JPanel implements KeyListener {
    private static final long serialVersionUID = 1L;
    private static final int horiz = 640;
    private static final int vert = 480;
    private static final int pruh = vert / 4;
    private static final double dpp = 255.0;
    private BufferedImage image;
    private Graphics g;
    private int[] source = { 4, 8, 1, 3, 16, 0, 2, 32, 1, 1, 64, 0 };
 
public GrayStripes() {
    image = new BufferedImage(horiz, vert, BufferedImage.TYPE_INT_RGB);
    g = image.getGraphics();
    g.setColor(Color.black);
    g.fillRect(0, 0, horiz, vert);
    for (int i = 0; i < source.length; i += 3) {
        int hiy = source[i] * pruh;
        int loy = hiy - pruh;
        int krok = horiz / source[i + 1];
        double piecol = 255.0 / (source[i + 1] - 1);
        for (int x = 0; x < source[i + 1]; x++) {
            Color barva = new Color((int) (piecol * x / dpp), (int) (piecol * x / dpp), (int) (piecol * x / dpp));
            g.setColor(barva);
            if (source[i + 2] == 1) {
                g.fillRect(x * krok, hiy, x * krok + krok, loy);
            } else {
                g.fillRect(horiz - x * krok, hiy, horiz - ((x + 1) * krok), loy);
            }
        }
    }
}
 
public void paintComponent(Graphics g) {
    super.paintComponent(g);
    g.drawImage(image, 0, 0, null);
}
 
public static void main(String[] args) {
    JFrame frame = new JFrame("Gray stripes");
    frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
    frame.addWindowListener(new WindowAdapter() {
        public void windowClosing(WindowEvent e) {
            System.exit(0);
        }
    });
    frame.add(new GrayStripes());
    frame.pack();
    frame.setVisible(true);
    frame.addKeyListener(new GrayStripes());
}
 
