}

public int kthSmallest(int[] nums, int k) {
int n = nums.length;
int lo = 0, hi = n - 1;
while (lo < hi) {
int mid = lo + (hi - lo) / 2;
int count = countSmaller(nums, mid, n);
if (count < k) {
lo = mid + 1;
} else {
hi = mid;
}
}
return nums[lo];
}
private int countSmaller(int[] nums, int target, int n) {
int count = 0;
for (int i = 0; i < n; ++i) {
if (nums[i] > target) {
count += i;
}
}
return count;
}
}

