import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.GeneratedValue;
import javax.persistence.GenerationType;
import javax.persistence.Id;
import javax.persistence.Table;

@Entity
@Table(name = "level_course_lms")
public class LevelCourseLMS {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id")
    private long id;

    @Column(name = "course_id", nullable = false)
    private long course;

    @Column(name = "level_id", nullable = false)
    private long level;

    @Column(name = "platform_id", nullable = false)
    private Long platform;

    public LevelCourseLMS() {
    }

    public LevelCourseLMS(long course, long level, Long platform) {
        this.course = course;
        this.level = level;
        this.platform = platform;
    }

    public long getId() {
        return id;
    }

    public void setId(long id) {
        this.id = id;
    }

    public long getCourse() {
        return course;
    }

    public void setCourse(long course) {
        this.course = course;
    }

    public long getLevel() {
        return level;
    }

    public void setLevel(long level) {
        this.level = level;
    }

    public Long getPlatform() {
        return platform;
    }

    public void setPlatform(Long platform) {
        this.platform = platform;
    }

    @Override
    public String toString() {
        return "LevelCourseLMS{" +
                "id=" + id +
                ", course=" + course +
                ", level=" + level +
                ", platform=" + platform +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        LevelCourseLMS that = (LevelCourseLMS) o;

        if (id != that.id) return false;
        if (course != that.course) return false;
        if (level != that.level) return false;
        return platform != null ? platform.equals(that.platform) : that.platform == null;
    }

    @Override
    public int hashCode() {
        int result = (int) (id ^ (id >>> 32));
        result = 31 * result + (int) (course ^ (course >>> 32));
        result = 31 * result + (int) (level ^ (level >>> 32));
        result = 31 * result + (platform != null ? platform.hashCode() : 0);
        return result;
    }
}

