public class Utils {
    public int surfaceArea(int[][] grid) {
        int N = grid.length;
        int ans = 0;

        for (int i = 0; i < N; ++i)
            for (int j = 0; j < N; ++j)
                if (grid[i][j] > 0) {
                    ans += 2;  // because top and bottom face are always added
                    for (int k = 0; k < 4; ++k) {
                        int nx = i + dx[k];
                        int ny = j + dy[k];
                        int adjacent = 0;
                        if (0 <= nx && nx < N && 0 <= ny && ny < N)
                            adjacent = grid[nx][ny];

                        ans += Math.max(grid[i][j] - adjacent, 0);
                    }
                }

        return ans;
    }

    private int[] dx = {0, 0, 1, -1};
    private int[] dy = {1, -1, 0, 0};
}

