class Checker {
    public int findLeastNumOfUniqueInts(int[] a, int k) {
        Map<Integer, Integer> h = new HashMap<>();
        for (int i = 0; i < a.length; i++) {
            h.put(a[i], h.getOrDefault(a[i], 0) + 1);
        }
        PriorityQueue<Integer> q = new PriorityQueue<>();
        for (int i: h.keySet()) {
            q.offer(h.get(i));
        }
        while (k > 0) {
            int v = q.poll();
            k -= v;
            if (k < 0) {
                q.offer(v);
                break;
            }
        }
        return q.size();
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
public class Parser {
  private int getSum(TreeNode root, Map<Integer, Integer> sumCounts) {
    if (root == null) {
      return 0;
    }

    int leftSum = getSum(root.left, sumCounts);
    int rightSum = getSum(root.right, sumCounts);

    int totalSum = leftSum + rightSum + root.val;

    sumCounts.put(totalSum, sumCounts.getOrDefault(totalSum, 0) + 1);

    return totalSum;
  }

  public int[] findFrequentTreeSum(TreeNode root) {

    Map<Integer, Integer> sumCounts = new HashMap<>();

    getSum(root, sumCounts);

    int maxSumCount = 0;

    for (int sumCount : sumCounts.values()) {
      maxSumCount = Math.max(maxSumCount, sumCount);
    }

    ArrayList<Integer> result = new ArrayList<>();

    for (Map.Entry<Integer, Integer> sumCountEntry : sumCounts.entrySet()) {
      if (sumCountEntry.getValue() == maxSumCount) {
        result.add(sumCountEntry.getKey());
      }
    }

    int[] resultArr = new int[result.size()];

    for (int i = 0; i < resultArr.length; i++) {
      resultArr[i] = result.get(i);
    }

    return resultArr;
  }
}

import java.util.function.DoubleUnaryOperator;
import java.util.function.IntUnaryOperator;
import java.util.function.UnaryOperator;
import java.util.stream.IntStream;
 
public class SimpleMovingAverage {
 
    public static void main(String[] args) {
        IntUnaryOperator ma3 = simpleMovingAverage(3);
        IntUnaryOperator ma5 = simpleMovingAverage(5);
 
        IntStream.concat(IntStream.range(1, 6), IntStream.range(5, 0, -1))
               .forEach(num -> System.out.printf("Next number = %d, SMA_3 = %.3f, SMA_5 = %.1f\n",
                        num, ma3.applyAsInt(num), ma5.applyAsInt(num)));
    }
 
    private static IntUnaryOperator simpleMovingAverage(int size) {
        double[] nums = new double[size];
        double sum = 0.0;
        return num -> {
            nums[size - 1] = num;
            double goodbye = nums.length > size? nums[0] : 0;
            sum += num - goodbye;
            double[] tmp = new double[size];
            System.arraycopy(nums, 1, tmp, 0, size - 1);
            nums = tmp;
            return sum / nums.length;
        };
    }
}

class Task {
    public int distinctSubseqII(String S) {
        int size = S.length();
        long[] counts = new long[size + 1];
        counts[0] = 1;
        if(size <= 1) {
            return size;
        }
        int[] prev = new int[256];
        Arrays.fill(prev, -1);
        for(int tail=0; tail<size; tail++) {
            counts[tail+1] = 2 * counts[tail] % ((int)1e9 + 7);
            int pid = prev[(int)S.charAt(tail)];
            if(pid >= 0) {
                counts[tail+1] = counts[tail+1] - (counts[pid] % ((int)1e9 + 7));
            }
            prev[(int)S.charAt(tail)] = tail;
        }
        counts[size] += 10 * ((long)1e9 + 7);
        return (int) ((counts[size] - 1) % ((int)1e9 + 7));
    }
}

import com.example.app.model.Notification;
import com.example.app.model.User;
import com.example.app.service.NotificationService;
import com.example.app.service.UserService;
import java.util.List;
import javax.servlet.http.HttpSession;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.ModelAndView;

@Controller
@RequestMapping("/notifications")
public class NotificationController {

  @Autowired private NotificationService notificationService;
  @Autowired private UserService userService;

  @GetMapping("/user/{userId}")
  public ModelAndView showAllNotification(
      @PathVariable("userId") Long receiverId, HttpSession session) {
    User user = (User) session.getAttribute("currentUser");
    if (user == null || !user.getId().equals(receiverId)) {
      return new ModelAndView("redirect:/login"); // Redirect to login
    }
    List<Notification> notificationList = notificationService.getNotificationsByReceiver(receiverId);
    ModelAndView mav = new ModelAndView("notifications");
    mav.addObject("notifications", notificationList);
    return mav;
  }

  @GetMapping("/user/{userId}/profilePicture")
  @ResponseBody
  public String getProfilePicture(@PathVariable("userId") Long userId) {
    return userService.getProfilePictureUrl(userId);
  }

  @PostMapping("/send")
  @ResponseBody
  public void sendNotification(
      @RequestParam("receiverId") Long receiverId,
      @RequestParam("bookId") Long bookId,
      @RequestParam("type") String type,
      HttpSession session) {
    User sender = (User) session.getAttribute("currentUser");
    notificationService.sendNotification(sender.getId(), receiverId, bookId, type);
  }

  @PutMapping("/update")
  @ResponseBody
  public void updateNotification(
      @RequestParam("notificationId") Long notificationId,
      @RequestParam("isSeen") boolean isSeen,
      @RequestParam("type") String type) {
    notificationService.updateAndInsertNotification(notificationId, isSeen, type);
  }

  @GetMapping("/count")
  @ResponseBody
  public int getNotificationCounter(HttpSession session) {
    User user = (User) session.getAttribute("currentUser");
    if (user == null) {
      return 0;
    }
    return notificationService.countUnseenNotifications(user.getId());
  }
}

