import com.watabou.utils.Randomness;

public class VaultPainter {

    private Room room;
    private Level level;

    public VaultPainter(Level level, Room room) {
        this.level = level;
        this.room = room;
    }

    public void paint() {
        fillTerrain();
        createEmptyArea();
        placeFeatures();
    }

    private void fillTerrain() {
        for (int x = room.left; x <= room.right; x++) {
            for (int y = room.top; y <= room.bottom; y++) {
                if (x == room.left || x == room.right || y == room.top || y == room.bottom) {
                    room.setTile(x, y, Tile.WALL);
                } else {
                    room.setTile(x, y, Tile.EMPTY);
                }
            }
        }
    }

    private void createEmptyArea() {
        // Assuming the area of the room is already defined by walls
        int centerX = room.left + (room.right - room.left) / 2;
        int centerY = room.top + (room.bottom - room.top) / 2;
        for (int x = centerX - 1; x <= centerX + 1; x++) {
            for (int y = centerY - 1; y <= centerY + 1; y++) {
                room.setTile(x, y, Tile.EMPTY);
            }
        }
    }

    private void placeFeatures() {
        int featureType = Randomness.get(0, 4);
        switch (featureType) {
            case 0:
                placeLockedChest();
                break;
            case 1:
                placeCrystalChests();
                break;
            case 2:
                placeTreasureOnPedestal();
                break;
            default:
                break;
        }
        placeLockedEntrance();
        placeKeys();
    }

    private void placeLockedChest() {
        int chestX = Randomness.get(room.left + 1, room.right - 1);
        int chestY = Randomness.get(room.top + 1, room.bottom - 1);
        room.addItem(new LockedChest(), chestX, chestY);
    }

    private void placeCrystalChests() {
        for (int i = 0; i < 2; i++) {
            int chestX = Randomness.get(room.left + 1, room.right - 1);
            int chestY = Randomness.get(room.top + 1, room.bottom - 1);
            room.addItem(new CrystalChest(), chestX, chestY);
        }
    }

    private void placeTreasureOnPedestal() {
        int pedestalX = Randomness.get(room.left + 1, room.right - 1);
        int pedestalY = Randomness.get(room.top + 1, room.bottom - 1);
        room.addItem(new TreasureOnPedestal(), pedestalX, pedestalY);
    }

    private void placeLockedEntrance() {
        int entranceX = Randomness.get(room.left, room.right);

import java.util.HashMap;
import java.util.Map;

class Shape {
    public int kSimilarity(String A, String B) {
        return kSimilarity0(A, B);
    }

    Map<String, Integer> m = new HashMap<String, Integer>();

    private int kSimilarity0(String a, String b) {
//      Helper.tr(a, b);
        if (a.length() < 2)
            return 0;
        if (a.charAt(0) == b.charAt(0))
            return kSimilarity0(a.substring(1), b.substring(1));
        String key = a + b;
        if (!m.containsKey(key)) {
            int ans = Integer.MAX_VALUE;
            for (int i = 1; i < b.length(); i++) {
                if (b.charAt(i) == a.charAt(0))
                    ans = Math.min(ans,
                            1 + kSimilarity0(a.substring(1), b.substring(1, i) + b.charAt(0) + b.substring(i + 1)));
            }
            m.put(key, ans);
//          Helper.tr(a, b, ans);
        }
        return m.get(key);
    }
}

