        }
        HttpCommandExecutor executor = null;
        try {
            executor = new HttpCommandExecutor(url);
        } catch (Exception e) {

            LOGGER.error(
                    "Received unknown exception while creating the "
                            + "HttpCommandExecutor, can not continue!",
                    e);
            return null;
        }
        return new RemoteWebDriver(executor, capabilities);
    }

