import java.nio.ByteBuffer;
import java.util.Arrays;
import org.apache.accumulo.core.data.Key;

public class AccumuloRowId {
    private byte[] indexId;
    private byte[] dataId;
    private byte[] adapterId;
    private int numberOfDuplicates;

    // Constructor for deserialization from Accumulo Key
    public AccumuloRowId(Key key) {
        this(key.getRow().copyBytes());
    }

    // Constructor for deserialization from byte array
    public AccumuloRowId(byte[] accumuloRowId) {
        ByteBuffer buffer = ByteBuffer.wrap(accumuloRowId);
        int totalLength = accumuloRowId.length;

        // Extract metadata from the end of the row ID
        buffer.position(totalLength - 12); // 4 bytes each for adapterId length, dataId length, and duplicates
        int adapterIdLength = buffer.getInt();
        int dataIdLength = buffer.getInt();
        numberOfDuplicates = buffer.getInt();

        // Extract indexId, adapterId, and dataId
        buffer.position(0);
        indexId = new byte[totalLength - 12 - adapterIdLength - dataIdLength];
        buffer.get(indexId);

        adapterId = new byte[adapterIdLength];
        buffer.get(adapterId);

        dataId = new byte[dataIdLength];
        buffer.get(dataId);
    }

    // Constructor for direct construction from components
    public AccumuloRowId(byte[] indexId, byte[] dataId, byte[] adapterId, int numberOfDuplicates) {
        this.indexId = Arrays.copyOf(indexId, indexId.length);
        this.dataId = Arrays.copyOf(dataId, dataId.length);
        this.adapterId = Arrays.copyOf(adapterId, adapterId.length);
        this.numberOfDuplicates = numberOfDuplicates;
    }

    // Serialize the row ID into a byte array
    public byte[] getRowId() {
        int totalLength = indexId.length + dataId.length + adapterId.length + 12; // 12 bytes for metadata
        ByteBuffer buffer = ByteBuffer.allocate(totalLength);

        buffer.put(indexId);
        buffer.put(adapterId);
        buffer.put(dataId);

        // Append metadata
        buffer.putInt(adapterId.length);
        buffer.putInt(dataId.length);
        buffer.putInt(numberOfDuplicates);

        return buffer.array();
    }

    // Getters for components
    public byte[] getIndexId() {
        return Arrays.copyOf(indexId, indexId.length);
    }

    public byte[] getDataId() {
        return Arrays.copyOf(dataId, dataId.length);
    }

    public byte[] getAdapterId() {
        return Arrays.copyOf(adapterId, adapterId.length);
    }

    public int getNumberOfDuplicates() {
        return numberOfDuplicates;
    }

