import java.util.Arrays;

public class Timer {

    public static void main(String[] args) {
        int[] nums = {2,-1,0,4,-2,-9}; // try with different inputs
        System.out.println(minimumAbosuluteDifferenceSum(nums));
    }

    public static int minimumAbosuluteDifferenceSum(int[] nums) {
        if(nums.length == 0) return 0;
        Arrays.sort(nums);
        int sum1 = 0, sum2 = 0;
        for (int i = 0; i < nums.length / 2; i++) {
            sum1 += nums[i];
        }
        for (int i = nums.length / 2; i < nums.length; i++) {
            sum2 += nums[i];
        }
        return Math.abs(sum1 - sum2);
    }
}

