public class BoxingTheCompass{
    private static String[] points = new String[32];
 
    public static void main(String[] args){
        buildPoints();
 
        double heading = 0;
 
        for(int i = 0; i<= 32;i++){
            heading = i * 11.25;
            switch(i % 3){
                case 1:
                    heading += 5.62;
                    break;
                case 2:
                    heading -= 5.62;
                    break;
                default:
            }
 
            System.out.printf("%s\t%18s\t%s°\n",(i % 32) + 1, initialUpper(getPoint(heading)), heading);
        }
    }
 
    private static void buildPoints(){
        String[] cardinal = {"north", "east", "south", "west"};
        String[] pointDesc = {"1", "1 by 2", "1-C", "C by 1", "C", "C by 2", "2-C", "2 by 1"};
 
        String str1, str2, strC;
 
        for(int i = 0;i <= 3;i++){
            str1 = cardinal[i];
            str2 = cardinal[(i + 1) % 4];
            strC = (str1.equals("north") || str1.equals("south")) ? (str1 + str2): (str2 + str1);
            for(int j = 0;j <= 7;j++){
                points[i * 8 + j] = pointDesc[j].replace("1", str1).replace("2", str2).replace("C", strC);
            }
        }
    }
 
    private static String initialUpper(String s){
        return s.substring(0, 1).toUpperCase() + s.substring(1);
    }
 
    private static String getPoint(double degrees){
        double testD = (degrees / 11.25) + 0.5;
        return points[(int)Math.floor(testD % 32)];
    }
}

public byte[] createEncodingBuffer(Batch batch) {
    // assume Batch is a custom class representing a batch of data
    // and has a method called 'getEncoding' that returns a byte array

    // create a new byte buffer with the size of the encoding
    ByteBuffer buffer = ByteBuffer.allocate(batch.getEncoding().length);

    // put the encoding into the buffer
    buffer.put(batch.getEncoding());

    // return the byte array from the buffer
    return buffer.array();
}

import java.util.Scanner;

public class Order {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }
            int maxDiff = a[n - 1] - a[0];
            for (int i = 0; i < n; i++) {
                for (int j = i; j < n; j++) {
                    for (int k = 1; k <= j - i + 1; k++) {
                        int[] b = new int[n];
                        System.arraycopy(a, 0, b, 0, n);
                        int temp = b[i];
                        for (int l = i; l < j; l++) {
                            b[l] = b[l + 1];
                        }
                        b[j] = temp;
                        for (int l = 0; l < k - 1; l++) {
                            temp = b[i];
                            for (int m = i; m < j; m++) {
                                b[m] = b[m + 1];
                            }
                            b[j] = temp;
                        }
                        maxDiff = Math.max(maxDiff, b[n - 1] - b[0]);
                    }
                }
            }
            System.out.println(maxDiff);
        }
    }
}

public class Logger {
    public boolean validUtf8(int[] data) {
        for (int i = 0; i < data.length; i++) {
            if (getDigit(data[i], 0) == 1) {
                int j = 1;
                while (j < 8 && getDigit(data[i], j) == 1)
                    j++;
                if (j == 8 || j - 1 == 0)
                    return false;
                j--;
                for (int k = 0; k < j; k++) {
                    i++;
                    if (i == data.length)
                        return false;
                    if (getDigit(data[i], 0) != 1 || getDigit(data[i], 1) != 0)
                        return false;
                }
            }
        }
        return true;
    }

    private int getDigit(int number, int position) {
        return (number & (1 << (7 - position))) > 0 ? 1 : 0;
    }
}

