}

public class Circle2D {
    private double x;
    private double y;
    private double radius;

    public Circle2D() {
        this(0, 0, 1);
    }

    public Circle2D(double x, double y, double radius) {
        this.x = x;
        this.y = y;
        this.radius = radius;
    }

    public double getX() {
        return x;
    }

    public double getY() {
        return y;
    }

    public double getRadius() {
        return radius;
    }

    public double getArea() {
        return Math.PI * radius * radius;
    }

    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }

    public boolean contains(double x, double y) {
        double distance = Math.sqrt((this.x - x) * (this.x - x) + (this.y - y) * (this.y - y));
        return distance < radius;
    }

    public boolean contains(Circle2D circle) {
        double distance = Math.sqrt((this.x - circle.x) * (this.x - circle.x) + (this.y - circle.y) * (this.y - circle.y));
        return distance + circle.radius <= radius;
    }

    public boolean overlaps(Circle2D circle) {
        double distance = Math.sqrt((this.x - circle.x) * (this.x - circle.x) + (this.y - circle.y) * (this.y - circle.y));
        return distance < this.radius + circle.radius;
    }
}

import org.eclipse.persistence.testing.models.employee.domain.*;
import org.eclipse.persistence.testing.framework.*;
import org.eclipse.persistence.queries.*;
import org.eclipse.persistence.expressions.*;

import java.util.Vector;

public class ConformResultsPerformanceTest extends TestCase {

    ReadAllQuery conformedQuery;
    Vector result;
    long startTime;

    public ConformResultsPerformanceTest() {
        setDescription("Tests the performance of conforming query results within a Unit of Work.");
    }

    public void buildConformQuery() {
        ExpressionBuilder builder = new ExpressionBuilder();
        Expression whereClause = builder.get("lastName").notEqual("test");

        conformedQuery = new ReadAllQuery(Employee.class);
        conformedQuery.setSelectionCriteria(whereClause);
        conformedQuery.conformResultsInUnitOfWork();
    }

    public void prepareTest() {
        buildConformQuery();
        EmployeeWrapperPolicy.unwrapCount = 0;
    }

    public void test() {
        startTime = System.currentTimeMillis();
        result = (Vector) getSession().executeQuery(conformedQuery);
    }

    public void verify() {
        long duration = System.currentTimeMillis() - startTime;
        int expectedUnwrapCount = result.size();
        int actualUnwrapCount = EmployeeWrapperPolicy.unwrapCount;

        if (actualUnwrapCount != expectedUnwrapCount) {
            fail("Unwrap count does not match the result size. Expected: " + expectedUnwrapCount + ", Actual: " + actualUnwrapCount);
        }

        if (duration > 1000) { // Set a reasonable threshold
            warning("Query execution time exceeded threshold: " + duration + "ms");
        }
    }

    public void reset() {
        EmployeeWrapperPolicy.unwrapCount = 0;
    }
}

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.turbo.TurboFilter;
import ch.qos.logback.core.spi.FilterReply;
import org.slf4j.LoggerFactory;
import org.slf4j.Marker;
import org.springframework.metrics.instrument.Counter;
import org.springframework.metrics.instrument.MeterRegistry;

public class LogbackMetrics implements MeterBinder {
    @Override
    public void bindTo(MeterRegistry registry) {
        LoggerContext context = (LoggerContext) LoggerFactory.getILoggerFactory();
        context.addTurboFilter(new MetricsTurboFilter(registry));
    }
}

class MetricsTurboFilter extends TurboFilter {
    private final Counter errorCounter;
    private final Counter warnCounter;
    private final Counter infoCounter;
    private final Counter debugCounter;
    private final Counter traceCounter;

    MetricsTurboFilter(MeterRegistry registry) {
        errorCounter = registry.counter("logback_events", "level", "error");
        warnCounter = registry.counter("logback_events", "level", "warn");
        infoCounter = registry.counter("logback_events", "level", "info");
        debugCounter = registry.counter("logback_events", "level", "debug");
        traceCounter = registry.counter("logback_events", "level", "trace");
    }

    @Override
    public FilterReply decide(Marker marker, Logger logger, Level level, String format, Object[] params, Throwable t) {
        switch(level.toInt()) {
            case Level.ERROR_INT:
                errorCounter.increment();
                break;
            case Level.WARN_INT:
                warnCounter.increment();
                break;
            case Level.INFO_INT:
                infoCounter.increment();
                break;
            case Level.DEBUG_INT:
                debugCounter.increment();
                break;
            case Level.TRACE_INT:
                traceCounter.increment();
                break;
        }

        return FilterReply.NEUTRAL;
    }
}

class Account {
    int[] fa;
    int fa(int root) {
        return fa[root] == root ? root : (fa[root] = fa(fa[root]));
    }
    int[] fa1;
    int fa1(int root) {
        return fa1[root] == root ? root : (fa1[root] = fa1(fa1[root]));
    }
    List<Integer>[] edges;
    public int maximumInvitations(int[] favorite) {

        fa = new int[favorite.length+1];
        Arrays.setAll(fa,i->i);

        edges = new ArrayList[favorite.length];
        Arrays.setAll(edges,i->new ArrayList<>());

        for (int i = 0; i < favorite.length; i++) {
            edges[favorite[i]].add(i);
            int l = fa(i);
            int r = fa(favorite[i]);
            if (l != r) {
                fa[l] = r;
            }
        }

        boolean[] flag = new boolean[favorite.length+1];
        int ans = 0;
        List<Integer> allow = new ArrayList<>();
        for (int i = 0; i < favorite.length; i++) {
            int f = fa(i);
            if (flag[f]) continue;

            flag[f] = true;
            ans = Math.max(ans,cal(i,favorite,allow));
        }
        int sum = 0;
        for (int i = 0; i < allow.size(); i++) {
            sum += allow.get(i);
        }
        ans = Math.max(ans,sum);

        return ans;

    }

    int cal(int root, int[] favorite, List<Integer> allow) {
        Set<Integer> set = new HashSet<>();
        while (!set.contains(root)) {
            set.add(root);
            root = favorite[root];
        }
        set.clear();
        while (!set.contains(root)) {
            set.add(root);
            root = favorite[root];
        }

        int ans = set.size();
        if (ans == 2) {
            Integer[] arr = set.toArray(new Integer[2]);
            ans += dfs(arr[0],edges,arr[1],0) + dfs(arr[1],edges,arr[0],0);
            allow.add(ans);

        }

        return ans;
    }

    private int dfs(int root, List<Integer>[] edges, int pre, int num) {

        int ans = num;
        for (Integer next : edges[root]) {
            if (next == pre) continue;
            ans = Math.max(ans,dfs(next,edges,root,num+1));
        }
        return ans;
    }
}

