public int countGoodNumbers(long n) {
        int MOD = 1000000007;

        long result = 1;

        for (long i = 0; i < n; i += 2) {
            long oddPlace = (i % 2 == 1) ? 5 : 4;
            long evenPlace = (i % 2 == 0) ? 4 : 5;

            oddPlace = (oddPlace + MOD) % MOD;
            evenPlace = (evenPlace + MOD) % MOD;

            oddPlace = (oddPlace * evenPlace) % MOD;
            evenPlace = (evenPlace * oddPlace) % MOD;

            result = (result * oddPlace) % MOD;
            result = (result * evenPlace) % MOD;
        }

        return (int)result;
    }
}

import java.io.DataInput;
import java.io.DataOutput;
