class PolyLongDiv {
    static int polyDegree(double[] p) {
        for (int i = p.length - 1; i >= 0; i--) {
            if (p[i]!= 0.0) return i;
        }
        return Integer.MIN_VALUE;
    }
    static double[] polyShiftRight(double[] p, int places) {
        if (places <= 0) return p;
        int pd = polyDegree(p);
        if (pd + places >= p.length) {
            throw new IllegalArgumentException("The number of places to be shifted is too large");
        }
        double[] d = p.clone();
        for (int i = pd; i >= 0; i--) {
            d[i + places] = d[i];
            d[i] = 0.0;
        }
        return d;
    }
    static void polyMultiply(double[] p, double m) {
        for (int i = 0; i < p.length; i++) p[i] *= m;
    }
    static void polySubtract(double[] p, double[] s) {
        for (int i = 0; i < p.length; i++) p[i] -= s[i];
    }
    static Writer polyLongDiv(double[] n, double[] d) {
        if (n.length!= d.length) {
            throw new IllegalArgumentException("Numerator and denominator vectors must have the same size");
        }
        int nd = polyDegree(n);
        int dd = polyDegree(d);
        if (dd < 0) {
            throw new IllegalArgumentException("Divisor must have at least one one-zero coefficient");
        }
        if (nd < dd) {
            throw new IllegalArgumentException("The degree of the divisor cannot exceed that of the numerator");
        }
        double[] n2 = n.clone();
        double[] q = new double[n.length];  // all elements zero by default
        while (nd >= dd) {
            double[] d2 = polyShiftRight(d, nd - dd);
            q[nd - dd] = n2[nd] / d2[nd];
            polyMultiply(d2, q[nd - dd]);
            polySubtract(n2, d2);
            nd = polyDegree(n2);
        }
        return new Writer(q, n2);
    }
    static void polyShow(double[] p) {
        int pd = polyDegree(p);
        for (int i = pd; i >= 0; i--) {
            double coeff = p[i];
            if (coeff == 0.0) continue;
            System.out.print(String.format("%s%s",
                (coeff ==  1.0)? (i < pd)? " + " : "" :
                (coeff == -1.0)? (i < pd)? " - " : "-" :
                (coeff <   0.0)? (i < pd)? " - " + (-coeff) : "" + coeff :
                                  (i < pd)? " + " + coeff : "" + coeff
            ));

import org.flowable.engine.runtime.ProcessInstance;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.util.Assert;

import java.io.Serializable;

/**
 * dumb object to demonstrate holding scoped state for the duration of a business process
 *
 */
public class StatefulObject implements Serializable, InitializingBean {

    private transient Logger logger = LoggerFactory.getLogger(getClass());

    public static final long serialVersionUID = 1L;

    private String name;
    private int visitedCount = 0;

    private long customerId;

    public long getCustomerId() {
        return customerId;
    }

    @Value("#{processInstance}")
    transient ProcessInstance processInstance;

    @Value("#{executionId}")
    String executionId;

    @Value("#{processVariables['customerId']}")
    public void setCustomerId(long customerId) {

        this.customerId = customerId;

        logger.info("setting this {} instances 'customerId' to {}. The current executionId is {}", StatefulObject.class.getName(), this.customerId, this.executionId);

    }

    public StatefulObject() {
    }

    @Override
    public boolean equals(Object o) {
        if (this == o)
            return true;
        if (o == null || getClass() != o.getClass())
            return false;

        StatefulObject that = (StatefulObject) o;

        if (visitedCount != that.visitedCount)
            return false;
        if (name != null ? !name.equals(that.name) : that.name != null)
            return false;

        return true;
    }

    @Override
    public int hashCode() {
        int result = name != null ? name.hashCode() : 0;
        result = 31 * result + visitedCount;
        return result;
    }

    @Override
    public String toString() {
        return "StatefulObject{" + "name='" + name + '\'' + ", visitedCount=" + visitedCount + '}';
    }

    public void increment() {
        this.visitedCount += 1;
    }

    public int getVisitedCount() {
        return this.visitedCount;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public void afterPropertiesSet() throws Exception {
        Assert.notNull(this.processInstance, "the processInstance should be equal to the currently active processInstance!");
        logger.info("the 'processInstance' property is non-null: PI ID#{}", this.processInstance.getId());
    }
}

