class Graph {
    public int maximumWealth(int[][] accounts) {
        int ans = 0;
        for(int[] acc:accounts) {
            int mon=0;
            for(int i:acc) mon+=i;
            if(mon>ans) ans=mon;
        }
        return ans;
    }
