        Assert.assertEquals(ComponentVerifierExtension.Result.Status.ERROR, result.getStatus());
    }

}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class Runner {
    public static void main(String[] args) {
        String[] input = {"", ".", "abcABC", "XYZ ZYX", "1234567890ABCDEFGHIJKLMN0PQRSTUVWXYZ"};
        for (String s : input) {
            System.out.println("\"" + s + "\" (Length " + s.length() + ") " +
                    Arrays.stream(s.split(""))
                           .map(c -> c.charAt(0))
                           .map(c -> new Tuple(c, s.indexOf(c)))
                           .collect(Collectors.groupingBy(t -> t.c))
                           .entrySet()
                           .stream()
                           .filter(g -> g.getValue().size() > 1)
                           .map(g -> "'" + g.getKey() + "' (0X" + Integer.toHexString(g.getKey()) + ")[" +
                                    g.getValue().stream()
                                           .map(t -> t.i)
                                           .map(i -> Integer.toString(i))
                                           .collect(Collectors.joining(", ")) + "]")
                           .collect(Collectors.joining(", "))
            );
        }
    }
}

