public class Runner {

public boolean validateStackSequences(int[] pushed, int[] popped) {
    int stackIndex = 0;
    int poppedIndex = 0;
    int stackSize = pushed.length;

    while (stackIndex < stackSize && poppedIndex < stackSize) {
        // Push all elements that are not present in popped
        while (stackIndex < stackSize && pushed[stackIndex] != popped[poppedIndex]) {
            stackIndex++;
        }
        // If stack is empty or top element doesn't match current element in pushed
        if (stackIndex == 0 || pushed[stackIndex] != popped[poppedIndex]) {
            return false; // Sequence is invalid
        }
        stackIndex++; poppedIndex++;
    }

    // Check if there are remaining elements in popped that weren't matched with pushed
    while (poppedIndex < stackSize) {
        if (popped[poppedIndex] != pushed[stackIndex - 1]) {
            return false; // Sequence is invalid
        }
        poppedIndex++; stackIndex--;
    }

    return true;
}

// Example usage:
// int[] pushed = {1,2,3,4,5};
// int[] popped = {4,5,3,2,1};
// System.out.println(new Runner().validateStackSequences(pushed, popped)); // Output: true
}

public class LoopHandler implements Runnable {
    protected class LoopRange {
        public int start, end;
    }
    protected Thread lookupThreads[];
    protected int startLoop, endLoop, curLoop, numThreads;

    public LoopHandler(int start, int end, int threads) {
        startLoop = curLoop = start;
        endLoop = end;
        numThreads = threads;
        lookupThreads = new Thread[numThreads];
    }

    protected synchronized LoopRange loopGetRange() {
        if (curLoop >= endLoop)
            return null;
        LoopRange ret = new LoopRange();
        ret.start = curLoop;
        curLoop += (endLoop-startLoop)/numThreads+1;
        ret.end = (curLoop<endLoop) ? curLoop : endLoop;
        return ret;
    }

    public void loopDoRange(int start, int end) {
    }

    public void loopProcess() {
        for (int i = 0; i < numThreads; i++) {
            lookupThreads[i] = new Thread(this);
            lookupThreads[i].start();
        }
        for (int i = 0; i < numThreads; i++) {
            try {
                lookupThreads[i].join();
        lookupThreads[i] = null;
            } catch (InterruptedException iex) {}
        }
    }

    public void run() {
        LoopRange str;
        while ((str = loopGetRange()) != null) {
            loopDoRange(str.start, str.end);
        }
    }
}

