public class SpaceString {
    public String insertSpaces(String s, int[] spaces) {
        StringBuilder sb = new StringBuilder();

        int start = 0;
        for (int space : spaces) {
            sb.append(s, start, space - start);
            sb.append(" ");
            start = space + 1;
        }
        sb.append(s.substring(start));
        return sb.toString();
    }
}

