Approach:
The idea is, Starting from the bigger side, if our number is in monotone then you can traverse left if its is in increasing order, right if tails.
We just need to follow this approach to get the answer.

time complexity - O(n)

space complexity - O(1)
"""

class Service:
    def largestNumber(self, n: int) -> int:
        n = str(n)
        if "-1" == n:
            return "1"
        new_n = list(n)
        n1, n2 = new_n.copy(), new_n.copy()
        n1.reverse()
        res, new_res = n, ""

        for i in range(len(new_n)):
            if int(new_n[i]) > int(n1[i]):
                n1.insert(i, new_n[i])
            if int(new_n[i]) <= int(n2[i]):
                n2.insert(i, new_n[i])

        if i == -len(n):
            if len(n1) > 0:
                res = int("".join(n1))
            else:
                res = int("".join(n2))
        else:
            if len(n1) == 0:
                res = int("".join(n2[i:]))
            else:
                res = int("".join(n1[:i+1]) + "".join(s for s in n2[i:]))
        return res

