// Problem Link: https://codeforces.com/problemset/problem/1617/D1
public class guess_imposters {
    public static void main (String[] args) throws IOException {
        // set up
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int T = Integer.parseInt(in.readLine());
        for (int t=0;t<T;t++) {
            int n = Integer.parseInt(in.readLine());
            int last = -1;
            int r;
            int curr_index = 0;
            int[] identity = new int[n]; // -1 for imposter, 1 for crewmate
            int[] known = new int[2];
            while (curr_index < n-2) {
                out.println("? " + (curr_index+1) + " " + (curr_index+2) + " " + (curr_index+3));
                out.flush();
                r = Integer.parseInt(in.readLine());
                if (r==-1) {
                    out.close();
                    break;
                }
                if (last != -1 && r != last) {
                    if (r==0 && last==1) {
                        identity[curr_index-1] = 1;
                        identity[curr_index+2] = -1;
                    }
                    else {
                        identity[curr_index-1] = -1;
                        identity[curr_index+2] = 1;
                    }
                    known[0] = curr_index-1;
                    known[1] = curr_index+2;
                    break;
                }
                last = r;
                curr_index += 1;
            }
            int total = 0;
            for (int i=0;i<n;i++) {
                if (identity[i]==0) {
                    out.println("? " + (known[0]+1) + " " + (known[1]+1) + " " + (i+1));
                    out.flush();
                    r = Integer.parseInt(in.readLine());
                    if (r==-1) {
                        out.close();
                        break; }
                    if (r==0) identity[i] = -1;
                    else identity[i] = 1;
                }
                if (identity[i]==-1) total += 1;
            }
            StringBuilder ans = new StringBuilder();
            ans.append("! ");
            ans.append(total);
            for (int i=0;i<n;i++) if (identity[i]==-1) ans.append(" ").append(i+1);
            out.println(ans);
            out.flush();
        }
        out.close();
    }
}

