import org.apache.log4j.Logger;
import org.dspace.content.DSpaceObject;
import org.dspace.content.Item;
import org.dspace.core.Context;
import org.dspace.event.Consumer;
import org.dspace.event.Event;
import java.util.HashSet;
import java.util.Set;

public class AuthorityConsumer implements Consumer {

    private static Logger log = Logger.getLogger(AuthorityConsumer.class);
    private Set<Integer> itemsToUpdateAuthority = new HashSet<>();
    private Set<Integer> itemsToReindex = new HashSet<>();

    public void initialize() throws Exception { }

    public void consume(Context ctx, Event event) throws Exception {

        DSpaceObject dso = event.getSubject(ctx);
        if (dso instanceof Item) {
            Item item = (Item) dso;

            if (item.isArchived())
            {
                Integer id = item.getID();

                if (!itemsToReindex.contains(id)) {
                   itemsToReindex.add(id);
                }

                if (event.getDetail() != null && event.getDetail().equals("INSTALL")) {
                    itemsToUpdateAuthority.add(id);
                }
            }
        }
    }

    public void end(Context ctx) throws Exception {

        try {
            ctx.turnOffAuthorisationSystem();

            for (Integer id : itemsToUpdateAuthority) {
                Item item = Item.find(ctx, id);
                if (item != null) {
                    //Assuming an external function to index
                    AuthorityIndexClient.indexItem(item);
                }
            }
            itemsToUpdateAuthority.clear();

            for (Integer id : itemsToReindex) {
                Item item = Item.find(ctx, id);
                if (item != null) {
                    AuthorityIndexClient.indexItem(item);
                }
            }
            itemsToReindex.clear();

        } catch (Exception e) {
            log.error("Error updating authority index", e);
            ctx.abort();
        } finally {
            ctx.restoreAuthSystemState();
        }
    }

    public void finish(Context ctx) throws Exception {
        // nothing
    }
}

import java.util.*;

class Graph {
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        int n = values.length;
        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        long totalSum = 0;
        for (int value : values) {
            totalSum += value;
        }

        long minSumToKeep = dfs(0, -1, adjList, values);

        return totalSum - minSumToKeep;
    }

    private long dfs(int node, int parent, List<List<Integer>> adjList, int[] values) {
        if (adjList.get(node).size() == 1 && node != 0) {
            return values[node];
        }

        long sum = 0;
        for (int neighbor : adjList.get(node)) {
            if (neighbor != parent) {
                sum += dfs(neighbor, node, adjList, values);
            }
        }

        return Math.min(sum, values[node]);
    }
}

