import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.SortedMap;
import java.util.TreeMap;
 
public class Library {
    public static <TItem> SortedMap<TItem, Integer> getFrequencies(Iterable<TItem> items) {
        SortedMap<TItem, Integer> dictionary = new TreeMap<TItem, Integer>();
        for (TItem item : items) {
            if (dictionary.containsKey(item)) {
                dictionary.put(item, dictionary.get(item) + 1);
            } else {
                dictionary.put(item, 1);
            }
        }
        return dictionary;
    }
 
    public static void main(String[] arguments) {
        String file = arguments.length > 0? arguments[0] : null;
        if (file!= null) {
            try {
                String text = new String(Files.readAllBytes(Paths.get(file)));
                for (Map.Entry<Character, Integer> entry : getFrequencies(text.toCharArray()).entrySet()) {
                    System.out.println(entry.getKey() + ": " + entry.getValue());
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}

@Override
public void write (final int b) {
    // Ensure there is enough space in the buffer
    if (count == buf.length) {
        grow(count + 1);
    }
    // Write the byte to the buffer
    buf[count++] = (byte) b;
}

private void grow(int minCapacity) {
    // Calculate new capacity
    int oldCapacity = buf.length;
    int newCapacity = oldCapacity << 1; // Double the old capacity
    if (newCapacity - minCapacity < 0) {
        newCapacity = minCapacity;
    }
    // Allocate a new array and copy the old data
    buf = Arrays.copyOf(buf, newCapacity);
}

