import javax.swing.JFileChooser;
import model.thermocouple.graduate.Graduate;
import model.thermocouple.graduate.GraduateFactory;

public class GraduateConverter {

  private Component parent;

  public GraduateConverter(Component parent) {
    this.parent = parent;
  }

  public void run() {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Select Graduation File");

    if (fileChooser.showOpenDialog(parent) == JFileChooser.APPROVE_OPTION) {
      Path graduationFilePath = fileChooser.getSelectedFile().toPath();

      Graduate graduate = null;
      try {
        graduate = GraduateFactory.fromFile(graduationFilePath);
      } catch (IOException e) {
        System.err.println("Error loading graduation file: " + e.getMessage());
        return;
      }

      fileChooser.setDialogTitle("Select Voltage Data File");
      if (fileChooser.showOpenDialog(parent) == JFileChooser.APPROVE_OPTION) {
        Path voltageFilePath = fileChooser.getSelectedFile().toPath();

        List<Double> temperatures = new ArrayList<>();

        try {
          List<String> lines = Files.readAllLines(voltageFilePath);
          NumberFormat numberFormat = NumberFormat.getInstance(Locale.US);

          for (String line : lines) {
            try {
              double voltage = numberFormat.parse(line.trim()).doubleValue();
              double temperature = graduate.convert(voltage, 22 + 273);
              temperatures.add(temperature);
            } catch (ParseException e) {
              System.err.println("Error parsing voltage: " + line + " - " + e.getMessage());
            }
          }

          try (PrintStream out = new PrintStream(Files.newOutputStream(voltageFilePath))) {
            NumberFormat temperatureFormat = NumberFormat.getNumberInstance(Locale.US);
            temperatureFormat.setMaximumFractionDigits(3);
            temperatureFormat.setMinimumFractionDigits(3);

            for (Double temperature : temperatures) {
              out.println(temperatureFormat.format(temperature));
            }
          } catch (IOException e) {
            System.err.println("Error writing to file: " + e.getMessage());
          }

        } catch (IOException e) {
          System.err.println("Error reading voltage file: " + e.getMessage());
        }

import java.util.Scanner;

public class StudentMajorAndStatus {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter two characters: ");
        String s = input.nextLine();

        char major = s.charAt(0);
        char status = s.charAt(1);

        String majorString, statusString;

        switch (major) {
            case 'M':
                majorString = "Mathematics";
                break;
            case 'C':
                majorString = "Computer Science";
                break;
            case 'I':
                majorString = "Information Technology";
                break;
            default:
                System.out.println("Invalid input");
                return;
        }

        switch (status) {
            case '1':
                statusString = "Freshman";
                break;
            case '2':
                statusString = "Sophomore";
                break;
            case '3':
                statusString = "Junior";
                break;
            case '4':
                statusString = "Senior";
                break;
            default:
                System.out.println("Invalid input");
                return;
        }

        System.out.println(majorString + " " + statusString);
    }
}

private void updateChunksInProjectVersions(final DatabaseTransOperator transOperator,
      final int projectId, final int version, final int chunk)
      throws ProjectManagerException {
    final String UPDATE_PROJECT_NUM_CHUNKS =
        "UPDATE project_versions SET num_chunks=? WHERE project_id=? AND version=?";
    try {
      transOperator.update(UPDATE_PROJECT_NUM_CHUNKS, chunk, projectId, version);
      transOperator.getConnection().commit();
    } catch (final SQLException e) {
      logger.error("Error updating project " + projectId + " : chunk_num " + chunk, e);
      throw new ProjectManagerException(
          "Error updating project " + projectId + " : chunk_num " + chunk, e);
    }
  }

