import java.util.Scanner;

public class AssignGrades {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the total number of students
        System.out.print("Enter the number of students: ");
        int numStudents = input.nextInt();

        // Prompt the user to enter all of the scores
        System.out.print("Enter " + numStudents + " scores: ");

        // Read the scores into an array
        int[] scores = new int[numStudents];
        for (int i = 0; i < numStudents; i++) {
            scores[i] = input.nextInt();
        }

        // Find the best score
        int best = scores[0];
        for (int i = 1; i < numStudents; i++) {
            if (scores[i] > best) {
                best = scores[i];
            }
        }

        // Assign grades based on the scheme
        for (int i = 0; i < numStudents; i++) {
            char grade;
            if (scores[i] >= best - 10) {
                grade = 'A';
            } else if (scores[i] >= best - 20) {
                grade = 'B';
            } else if (scores[i] >= best - 30) {
                grade = 'C';
            } else if (scores[i] >= best - 40) {
                grade = 'D';
            } else {
                grade = 'F';
            }
            System.out.println("Student " + i + " score is " + scores[i] + " and grade is " + grade);
        }
    }
}

import java.util.Arrays;
import java.util.Comparator;
 
class Item {
    double w, v;
    String name;
    public Item(double w, double v, String name) {
        this.w = w;
        this.v = v;
        this.name = name;
    }
}
 
class ItemComparator implements Comparator<Item> {
    public int compare(Item a, Item b) {
        double ua = a.v / a.w, ub = b.v / b.w;
        return ua < ub? -1 : ua > ub;
    }
}
 
public class Knapsack {
    public static void main(String[] args) {
        Item[] items = {
            new Item(3.8, 36, "beef"),
            new Item(5.4, 43, "pork"),
            new Item(3.6, 90, "ham"),
            new Item(2.4, 45, "greaves"),
            new Item(4.0, 30, "flitch"),
            new Item(2.5, 56, "brawn"),
            new Item(3.7, 67, "welt"),
            new Item(3.0, 95, "salami"),
            new Item(5.9, 98, "sausage"),
        };
        double space = 15;
        Arrays.sort(items, new ItemComparator());
        for (Item it : items) {
            if (space < it.w)
                break;
            space -= it.w;
            System.out.printf("take all %s\n", it.name);
        }
        if (space > 0)
            System.out.printf("take %gkg of %g kg of %s\n",
                space, it.w, it.name);
    }
}

