import static org.junit.Assert.assertArrayEquals;

import com.google.common.collect.ImmutableMap;
import com.google.common.collect.Iterables;
import com.google.protobuf.ByteString;
import java.io.IOException;
import org.apache.beam.model.fnexecution.v1.BeamFnApi.StateKey;
import org.apache.beam.sdk.coders.StringUtf8Coder;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.JUnit4;

/** Tests for {@link MultimapSideInput}. */
@RunWith(JUnit4.class)
public class MultimapSideInputTest {
  @Test
  public void testGet() throws Exception {
    FakeBeamFnStateClient fakeBeamFnStateClient = new FakeBeamFnStateClient(ImmutableMap.of(
        key("A"), encode("A1", "A2", "A3"),
        key("B"), encode("B1", "B2")));

    MultimapSideInput<String, String> multimapSideInput = new MultimapSideInput<>(
        fakeBeamFnStateClient,
        "instructionId",
        "ptransformId",
        "sideInputId",
        ByteString.copyFromUtf8("encodedWindow"),
        StringUtf8Coder.of(),
        StringUtf8Coder.of());
    assertArrayEquals(new String[]{ "A1", "A2", "A3" },
        Iterables.toArray(multimapSideInput.get("A"), String.class));
    assertArrayEquals(new String[]{ "B1", "B2" },
        Iterables.toArray(multimapSideInput.get("B"), String.class));
    assertArrayEquals(new String[]{ },
        Iterables.toArray(multimapSideInput.get("unknown"), String.class));
  }

  private StateKey key(String id) throws IOException {
    return StateKey.newBuilder().setMultimapSideInput(
        StateKey.MultimapSideInput.newBuilder()
            .setPtransformId("ptransformId")
            .setSideInputId("sideInputId")
            .setWindow(ByteString.copyFromUtf8("encodedWindow"))
            .setKey(encode(id))).build();
  }

  private ByteString encode(String ... values) throws IOException {
    ByteString.Output out = ByteString.newOutput();
    for (String value : values) {
      StringUtf8Coder.of().encode(value, out);
    }
    return out.toByteString();
  }
}

import java.io.IOException;
import java.net.URISyntaxException;

/**
 * Contract for a transport used to interact with an IoT Hub.
 */
public interface IotHubTransport {
    /**
     * Establishes a connection to an IoT Hub.
     *
     * @throws IOException if the connection could not be established.
     */
    void open() throws IOException, URISyntaxException;

    /**
     * Terminates the connection to an IoT Hub.
     *
     * @throws IOException if the connection could not be closed.
     */
    void close() throws IOException;

    /**
     * Adds a message to the queue for sending.
     *
     * @param msg             the message to be sent.
     * @param callback        the callback to be invoked upon completion.
     * @param callbackContext the context for the callback.
     */
    void addMessage(IotHubServiceboundMessage msg, IotHubEventCallback callback, Object callbackContext);

    /**
     * Sends the queued messages to the IoT Hub.
     *
     * @throws IOException if sending failed.
     */
    void sendMessages() throws IOException;

    /**
     * Invokes registered callbacks for completed send operations.
     */
    void invokeCallbacks();

    /**
     * Handles an incoming message from the IoT Hub.
     *
     * @param msg the received message.
     * @return the feedback to the IoT Hub.
     */
    IotHubMessageResult handleMessage(IotHubServiceboundMessage msg);

    /**
     * Sends any pending messages and retries any previous failed send attempts
     * @throws IOException the exception
     */
    void sendAndHandleMessages() throws IOException;

    /**
     * Check whether the transport is empty
     * @return the boolean value of the current state.
     */
    boolean isEmpty();
}

import java.util.Scanner;  // kullanici girisini okumak icin gerekli sinif

public class Fibonacci {

    // Belirtilen adete kadar Fibonacci dizisini yazdirir ve altin orani hesaplar
    void fibonacciYazdir(int adet) {

        int guncel = 0;   // her adimda hesaplanan yeni terim
        int onceki = 1;   // dizideki ilk terim
        int oncekiIkinci = 1; // dizideki ikinci terim

        // ilk iki terim sabit oldugundan direkt yazdirilir
        System.out.print("1 1 ");

        int index = 2;
        while (index < adet) {
            guncel = onceki + oncekiIkinci; // yeni terim onceki ikisinin toplami
            onceki = oncekiIkinci;          // kaydirma islemi
            oncekiIkinci = guncel;
            System.out.print(guncel + " ");
            index++;
        }

        System.out.println();

        // son iki terimin orani altin oranina yaklasir
        System.out.println("Altin oran = " + (double) ((double) oncekiIkinci / onceki));
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen bir sayi giriniz");
        int girilenDeger = tarayici.nextInt();

        Fibonacci hesaplayici = new Fibonacci();
        hesaplayici.fibonacciYazdir(girilenDeger);

        tarayici.close();
    }
}

public class Luhn {
    public static void main(String[] args) {
        System.out.println(luhnTest("49927398716"));
        System.out.println(luhnTest("49927398717"));
        System.out.println(luhnTest("1234567812345678"));
        System.out.println(luhnTest("1234567812345670"));
    }
 
    public static boolean luhnTest(String number){
        int s1 = 0, s2 = 0;
        String reverse = new StringBuffer(number).reverse().toString();
        for(int i = 0 ;i < reverse.length();i++){
            int digit = Character.digit(reverse.charAt(i), 10);
            if(i % 2 == 0){//this is for odd digits, they are 1-indexed in the algorithm
                s1 += digit;
            }else{//add 2 * digit for 0-4, add 2 * digit - 9 for 5-9
                s2 += 2 * digit;
                if(digit >= 5){
                    s2 -= 9;
                }
            }
        }
        return (s1 + s2) % 10 == 0;
    }
}

import java.io.*;
import java.util.*;

public class Writer {
    static final int N = (int) 1e4 + 10;
    static int n;
    static int[] a = new int[N];
    static int[][] f = new int[N][N * 2];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int T = sc.nextInt();
        while (T-- > 0) {
            solve(sc, pw);
        }
        pw.close();
    }

    public static void solve(Scanner sc, PrintWriter pw) {
        n = sc.nextInt();
        for (int i = 1; i <= n; i++) {
            a[i] = sc.nextInt();
        }
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j < N * 2; j++) {
                f[i][j] = Integer.MAX_VALUE / 2;
            }
        }
        f[1][a[1] + N] = 0;
        f[1][N - a[1]] = a[1] * 2;
        for (int i = 2; i <= n; i++) {
            for (int j = -N; j <= N; j++) {
                if (j + a[i] <= N) {
                    f[i][j + a[i] + N] = Math.min(f[i][j + a[i] + N], f[i - 1][j + N] + Math.abs(j + a[i]));
                }
                if (j - a[i] >= -N) {
                    f[i][j - a[i] + N] = Math.min(f[i][j - a[i] + N], f[i - 1][j + N] + Math.abs(j - a[i]));
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int i = -N; i <= N; i++) {
            ans = Math.min(ans, f[n][i + N]);
        }
        pw.println(ans);
    }
}

import java.util.Random;
import java.util.Scanner;

public class RastgeleKarakterYazdirma {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        Random random = new Random();

        // Kullanicidan bir kelime girmesini iste
        System.out.println("Bir kelime giriniz:");
        String kelime = scanner.nextLine();

        // Eger kelime bossa hata mesaji yazdir ve programi sonlandir
        if (kelime.isEmpty()) {
            System.out.println("Kelime bos olamaz.");
            scanner.close();
            return;
        }

        // Kullanicidan kac karakter secilecegini sor
        System.out.println("Kac rastgele karakter secmek istersiniz?");
        int karakterSayisi = scanner.nextInt();

        scanner.close();

        // Eger kullanicidan girilen sayi gecersizse hata mesaji yazdir
        if (karakterSayisi <= 0 || karakterSayisi > kelime.length()) {
            System.out.println("Gecersiz karakter sayisi. 1 ile " + kelime.length() + " arasinda bir sayi giriniz.");
            return;
        }

        // Rastgele karakterleri sec ve ekrana yazdir
        System.out.println("Secilen rastgele karakterler:");
        boolean[] secilenindeksler = new boolean[kelime.length()];
        for (int i = 0; i < karakterSayisi; i++) {
            int indeks;
            // Ayni karakterin tekrar secilmemesi icin dongu
            do {
                indeks = random.nextInt(kelime.length());
            } while (secilenindeksler[indeks]);

            secilenindeksler[indeks] = true;
            System.out.println("indeks " + indeks + ": " + kelime.charAt(indeks));
        }

        // Kullaniciya istatistik goster
        System.out.println("\nKelimenin uzunlugu: " + kelime.length());
        System.out.println("Secilen karakter sayisi: " + karakterSayisi);
    }
}

import java.awt.Image;
import java.awt.image.BufferedImage;
import java.awt.image.RenderedImage;
import java.io.IOException;
import java.io.OutputStream;
import java.util.Iterator;

import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.inject.Named;
import javax.inject.Singleton;

import org.xwiki.component.annotation.Component;

import net.coobird.thumbnailator.Thumbnails;

/**
 * Image processor implementation based on the Thumbnailator library.
 *
 */
@Component
@Singleton
@Named("thumbnailator")
public class ThumbnailatorImageProcessor extends DefaultImageProcessor
{
    @Override
    public void writeImage(RenderedImage image, String mimeType, float quality, OutputStream out) throws IOException
    {
        if (image instanceof BufferedImage) {
            Thumbnails.of((BufferedImage) image).scale(1).outputFormat(getFormatNameForMimeType(mimeType))
                .outputQuality(quality).toOutputStream(out);
        } else {
            super.writeImage(image, mimeType, quality, out);
        }
    }

    @Override
    public RenderedImage scaleImage(Image image, int width, int height)
    {
        if (image instanceof BufferedImage) {
            try {
                return Thumbnails.of((BufferedImage) image).size(width, height).asBufferedImage();
            } catch (IOException e) {
            }
        }
        return super.scaleImage(image, width, height);
    }

    private String getFormatNameForMimeType(String mimeType)
    {
        Iterator<ImageReader> imageReaders = ImageIO.getImageReadersByMIMEType(mimeType);
        if (imageReaders.hasNext()) {
            try {
                return imageReaders.next().getFormatName();
            } catch (IOException e) {
            }
        }
        return mimeType;
    }
}

