import java.util.ArrayList;
import java.util.List;
import java.util.Random;

public List<BinarySolution> doCrossover(double probability, BinarySolution parent1, BinarySolution parent2) throws JMetalException {
    Random rand = new Random();
    List<BinarySolution> offspring = new ArrayList<>();

    // Check if crossover should happen
    if (rand.nextDouble() > probability) {
        offspring.add(parent1);
        offspring.add(parent2);
        return offspring;
    }

    // Perform crossover
    int n = parent1.getNumberOfVariables();
    int point = rand.nextInt(n);

    BinarySolution offspring1 = parent1.copy();
    BinarySolution offspring2 = parent2.copy();

    for (int i = point; i < n; i++) {
        offspring1.setVariableValue(i, parent2.getVariableValue(i));
        offspring2.setVariableValue(i, parent1.getVariableValue(i));
    }

    offspring.add(offspring1);
    offspring.add(offspring2);

    return offspring;
}

import java.math.BigInteger;
public class SumDigits {
    public static int sumDigits(long num) {
    return sumDigits(num, 10);
    }
    public static int sumDigits(long num, int base) {
    String s = Long.toString(num, base);
    int result = 0;
    for (int i = 0; i < s.length(); i++)
        result += Character.digit(s.charAt(i), base);
    return result;
    }
    public static int sumDigits(BigInteger num) {
    return sumDigits(num, 10);
    }
    public static int sumDigits(BigInteger num, int base) {
    String s = num.toString(base);
    int result = 0;
    for (int i = 0; i < s.length(); i++)
        result += Character.digit(s.charAt(i), base);
    return result;
    }
 
    public static void main(String[] args) {
    System.out.println(sumDigits(1));
    System.out.println(sumDigits(12345));
    System.out.println(sumDigits(123045));
    System.out.println(sumDigits(0xfe, 16));
    System.out.println(sumDigits(0xf0e, 16));
    System.out.println(sumDigits(new BigInteger("12345678901234567890")));
    }
}

