import java.util.ArrayList;
import java.util.List;

public class LinkArgument {
    private static final String LINK_FORMAT = "<a href=\"%s\" class=\"%s\" title=\"%s\">%s</a>";
    private static final String LINK_FORMAT_WITHOUT_CSS_CLASS = "<a href=\"%s\" title=\"%s\">%s</a>";

    private final MessageResolver messageResolver;
    private String url;
    private Resolvable title;
    private String cssClass;
    private String text;

    public LinkArgument(MessageResolver messageResolver) {
        this.messageResolver = messageResolver;
    }

    public LinkArgument url(String url) {
        this.url = url;
        return this;
    }

    public LinkArgument title(Resolvable title) {
        this.title = title;
        return this;
    }

    public LinkArgument text(String text) {
        this.text = text;
        return this;
    }

    public LinkArgument cssClass(String cssClass) {
        this.cssClass = cssClass;
        return this;
    }

    public String resolve() {
        validateUrl();
        String resolvedTitle = resolveTitle();
        String resolvedText = resolveText();

        return buildHtmlLink(
            sanitize(url),
            resolvedTitle,
            sanitize(cssClass),
            resolvedText
        );
    }

    private void validateUrl() {
        if (url == null || url.trim().isEmpty()) {
            throw new IllegalArgumentException("URL must not be empty");
        }
    }

    private String resolveTitle() {
        return title != null
            ? messageResolver.resolve(title)
            : null;
    }

    private String resolveText() {
        return text != null
            ? text
            : (title != null ? messageResolver.resolve(title) : "");
    }

    private String buildHtmlLink(String url, String title, String cssClass, String text) {
        List<String> attributes = new ArrayList<>();
        attributes.add("href=\"" + url + "\"");

        if (cssClass != null) {
            attributes.add("class=\"" + cssClass + "\"");
        }
        if (title != null && !title.isEmpty()) {
            attributes.add("title=\"" + sanitize(title) + "\"");
        }

        return String.format(
            cssClass != null ? LINK_FORMAT : LINK_FORMAT_WITHOUT_CSS_CLASS,
            url,
            cssClass != null ? cssClass : "",
            title != null ? sanitize(title) : "",
            text
        );
    }

    private String sanitize(String input) {
        return input != null ? input.trim().replaceAll("\"", "&quot;") : "";
    }

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
 
public class Abbreviations {
    public static void main(String[] args) throws IOException {
        Path path = Paths.get("days_of_week.txt");
        List<String> readAllLines = Files.readAllLines(path);
        for (int i = 0; i < readAllLines.size(); i++) {
            String line = readAllLines.get(i);
            if (line.length() == 0) continue;
 
            String[] days = line.split(" ");
            if (days.length != 7) throw new RuntimeException("There aren't 7 days on line " + (i + 1));
 
            Map<String, Integer> temp = new HashMap<>();
            for (String day : days) {
                Integer count = temp.getOrDefault(day, 0);
                temp.put(day, count + 1);
            }
            if (temp.size() < 7) {
                System.out.print(" ∞  ");
                System.out.println(line);
                continue;
            }
 
            int len = 1;
            while (true) {
                temp.clear();
                for (String day : days) {
                    String sd;
                    if (len >= day.length()) {
                        sd = day;
                    } else {
                        sd = day.substring(0, len);
                    }
                    Integer count = temp.getOrDefault(sd, 0);
                    temp.put(sd, count + 1);
                }
                if (temp.size() == 7) {
                    System.out.printf("%2d  %s\n", len, line);
                    break;
                }
                len++;
            }
        }
    }
}

import io.trino.spi.TrinoException;
import org.testng.annotations.Test;

import static io.trino.spi.StandardErrorCode.INVALID_FUNCTION_ARGUMENT;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.testng.Assert.assertEquals;

public class TestApproximateCountDistinctAggregations
{
    @Test
    public void testStandardErrorToBuckets()
    {
        // Boundary and typical standard error scenarios
        assertEquals(standardErrorToBuckets(0.5), 2048);
        assertEquals(standardErrorToBuckets(1.0), 1024);
        assertEquals(standardErrorToBuckets(2.0), 512);
        assertEquals(standardErrorToBuckets(3.0), 256);
        assertEquals(standardErrorToBuckets(4.0), 128);
        assertEquals(standardErrorToBuckets(5.0), 64);
        assertEquals(standardErrorToBuckets(6.0), 32);
        assertEquals(standardErrorToBuckets(7.0), 16);
        assertEquals(standardErrorToBuckets(8.0), 8);
        assertEquals(standardErrorToBuckets(9.0), 4);
        assertEquals(standardErrorToBuckets(10.0), 2);
    }

    @Test
    public void testInvalidStandardErrorValues()
    {
        // Test invalid (out-of-bounds) standard error inputs
        assertThatThrownBy(() -> standardErrorToBuckets(0.0))
                .isInstanceOf(TrinoException.class)
                .hasFieldOrPropertyWithValue("errorCode", INVALID_FUNCTION_ARGUMENT);

        assertThatThrownBy(() -> standardErrorToBuckets(11.0))
                .isInstanceOf(TrinoException.class)
                .hasFieldOrPropertyWithValue("errorCode", INVALID_FUNCTION_ARGUMENT);

        assertThatThrownBy(() -> standardErrorToBuckets(-1.0))
                .isInstanceOf(TrinoException.class)
                .hasFieldOrPropertyWithValue("errorCode", INVALID_FUNCTION_ARGUMENT);
    }

    private int standardErrorToBuckets(double standardError)
    {
        if (standardError <= 0.0 || standardError > 10.0) {
            throw new TrinoException(INVALID_FUNCTION_ARGUMENT,
                "Standard error must be between 0.0 and 10.0 exclusive");
        }

        return (int) Math.pow(2, Math.floor(11.0 - standardError));
    }
}

import java.util.Arrays;
import java.util.stream.IntStream;

public class Parser {
    public static void main(String[] args) {
        long[] r = items1();
        System.out.println(r[0] + " v  " + r[1] + " a  " + r[2] + " b");  // 0 15 11
        long start = System.nanoTime();
        for (int i = 1000; i > 0; i--) items1();
        System.out.println((System.nanoTime() - start) / 1000000);
    }

    static long[] items0()  // 1.2 µs
    {
        long v, v0 = 0, a, b, c, a0 = 0, b0 = 0, c0 = 0;
        for (a = 0; a <= 10; a++)
            for (b = 0; a * 5 + b * 3 <= 50; b++)
                for (c = 0; a * 25 + b * 15 + c * 2 <= 250 && a * 3 + b * 2 + c * 20 <= 250; c++)
                    if (v0 < (v = a * 30 + b * 18 + c * 25))
                    {
                        v0 = v; a0 = a; b0 = b; c0 = c;
                        //System.out.println(String.format("%5d %5d %5d %5d", v, a, b, c));
                    }
        return new long[] { a0, b0, c0 };
    }

    static long[] items1()  // 0,22 µs
    {
        long v, v0 = 0, a, b, c, a0 = 0, b0 = 0, c0 = 0, c1 = 0;
        for (a = 0; a <= 10; a++)
            for (b = 0; a * 5 + b * 3 <= 50; b++)
            {
                c = (250 - a * 25 - b * 15) / 2;
                if ((c1 = (250 - a * 3 - b * 2) / 20) < c) c = c1;
                if (v0 < (v = a * 30 + b * 18 + c * 25))
                { v0 = v; a0 = a; b0 = b; c0 = c; }
            }
        return new long[] { a0, b0, c0 };
    }
}

class Timer {
    public boolean checkStraightLine(int[][] coordinates) {
        return sln1(coordinates);
    }

    private boolean sln1(int[][] coo){
        //vertical line
        if(coo[0][0] == coo[1][0]){
            for(int i = 2 ;i < coo.length;i++){
                if(coo[i][0] != coo[0][0]) return false;
            }
        }else{
            int a = (coo[0][1]-coo[1][1])/(coo[0][0]-coo[1][0]);
            int b = coo[0][1]-a*coo[0][0];
            for(int i = 2 ;i < coo.length;i++){
                if(coo[i][0]*a+b != coo[i][1]) return false;
            }
        }
        return true;
    }
}

// Custom checked exception used to demonstrate user-defined error types.
public class OzellesmisIstisna extends Exception {

    // Version marker required for Serializable compatibility
    private static final long serialVersionUID = 1L;

    // The descriptive text carried by this exception
    private final String detail;

    // Constructor forwards the message to the base Exception and keeps a copy
    public OzellesmisIstisna(String detail) {
        super(detail);
        this.detail = detail;
    }

    @Override
    public String getMessage() {
        return detail;
    }

    /**
     * Demonstrates several scenarios involving this custom exception.
     */
    public static void main(String[] args) {

        System.out.println("1. Ornek: Basit bir istisna firlatma ve yakalama");
        try {
            throw new OzellesmisIstisna("Bu bir ozel istisnadir");
        } catch (OzellesmisIstisna ex) {
            System.out.println("Hata Mesaji: " + ex.getMessage());
        }

        System.out.println("2. Ornek: Istisna baska bir metot icinde firlatiliyor");
        try {
            triggerFailure();
        } catch (OzellesmisIstisna ex) {
            System.out.println("Metottan Gelen Hata: " + ex.getMessage());
        }

        System.out.println("3. Ornek: Birden fazla istisna durumunu kontrol etme");
        try {
            validateNonNegative(-5);
        } catch (OzellesmisIstisna ex) {
            System.out.println("Kontrol Hatasi: " + ex.getMessage());
        }

        System.out.println("4. Ornek: Normal akis");
        try {
            validateNonNegative(10);
            System.out.println("Hata yok, islem basariyla tamamlandi!");
        } catch (OzellesmisIstisna ex) {
            System.out.println("Hata: " + ex.getMessage());
        }
    }

    /**
     * Always raises the custom exception; used to show propagation.
     * @throws OzellesmisIstisna unconditionally
     */
    public static void triggerFailure() throws OzellesmisIstisna {
        throw new OzellesmisIstisna("Bu metot her zaman bir istisna firlatir!");
    }

    /**
     * Rejects negative numbers by throwing the custom exception.
     * @param value number to validate
     * @throws OzellesmisIstisna if value is negative
     */
    public static void validateNonNegative(int value) throws OzellesmisIstisna {
        if (value < 0) {
            throw new OzellesmisIstisna("Gecersiz sayi: " + value + ". Sifirdan kucuk olamaz.");
        }
    }
}

