import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import land.face.strife.StrifePlugin;
import land.face.strife.data.champion.Champion;
import land.face.strife.data.champion.LifeSkillType;
import org.bukkit.entity.Player;

public class CombatStatusManager {

  private final StrifePlugin plugin;
  private final Map<Player, Integer> tickMap = new ConcurrentHashMap<>();

  private static final int SECONDS_TILL_EXPIRY = 8;

  public CombatStatusManager(StrifePlugin plugin) {
    this.plugin = plugin;
  }

  public boolean isInCombat(Player player) {
    return tickMap.containsKey(player);
  }

  public void addPlayer(Player player) {
    tickMap.put(player, SECONDS_TILL_EXPIRY);
  }

  public void tickCombat() {
    for (Player player : tickMap.keySet()) {
      if (!player.isOnline() || !player.isValid()) {
        tickMap.remove(player);
        continue;
      }
      int ticksLeft = tickMap.get(player);
      if (ticksLeft < 1) {
        doExitCombat(player);
        tickMap.remove(player);
        continue;
      }
      tickMap.put(player, ticksLeft - 1);
    }
  }

  public void doExitCombat(Player player) {
    if (!tickMap.containsKey(player)) {
      return;
    }
    Champion champion = plugin.getChampionManager().getChampion(player);
    if (champion.getDetailsContainer().getExpValues() == null) {
      return;
    }
    for (LifeSkillType type : champion.getDetailsContainer().getExpValues().keySet()) {
      plugin.getSkillExperienceManager().addExperience(player, type,
          champion.getDetailsContainer().getExpValues().get(type), false, false);
    }
    champion.getDetailsContainer().clearAll();
  }
}

import java.util.Scanner;

public class Calculator {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a string: ");
        String input = in.next();
        in.close();

        displayPermutation(input);
    }

    public static void displayPermutation(String s) {
        displayPermutation(" ", s);
    }

    public static void displayPermutation(String s1, String s2) {
        if (s2.length() > 0) {
            for (int i = 0; i < s2.length(); i++) {
                String shuffle1 = s1 + s2.charAt(i);
                String shuffle2 = s2.substring(0, i) + s2.substring(i + 1);
                displayPermutation(shuffle1, shuffle2);
            }
        } else {
            System.out.println(s1);
        }
    }
}

import java.math.BigInteger;
import java.util.stream.IntStream;
 
public class IntegerSquareRoot {
 
    public static BigInteger isqrt(BigInteger number) {
        BigInteger q = BigInteger.ONE;
        while (q.compareTo(number) <= 0) {
            q = q.shiftLeft(2);
        }
 
        BigInteger z = number;
        BigInteger result = BigInteger.ZERO;
 
        while (q.compareTo(BigInteger.ONE) > 0) {
            q = q.shiftRight(2);
            BigInteger t = z.subtract(result).subtract(q);
            result = result.shiftRight(1);
 
            if (t.compareTo(BigInteger.ZERO) >= 0) {
                z = t;
                result = result.add(q);
            }
        }
 
        return result;
    }
 
    public static String withThousandSeparator(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) {
            sb.append(s.charAt(i));
            if (i % 3 == 0 && i!= 0) {
                sb.append(",");
            }
        }
        return sb.reverse().toString();
    }
 
    public static void main(String[] args) {
        System.out.println("The integer square roots of integers from 0 to 65 are:");
        IntStream.rangeClosed(0, 65).forEach(n -> System.out.print(isqrt(BigInteger.valueOf(n)) + " "));
 
        System.out.println("\nThe integer square roots of odd powers of 7 from 7^1 up to 7^74 are:");
        IntStream.range(1, 75).filter(n -> n % 2!= 0).forEach(exp -> {
            BigInteger pow = BigInteger.valueOf(7).pow(exp);
            System.out.printf("7^%2d=%83s ISQRT: %42s %n", exp, withThousandSeparator(pow.toString()), withThousandSeparator(isqrt(pow).toString()));
        });
    }
}

public class Converter {
    public static void main(String[] args) {
        int count = 1;
        int i = 2;
        while (count <= 100) {
            if (isEmips(i)) {
                System.out.print(i + " ");
                if (count % 10 == 0) {
                    System.out.println();
                }
                count++;
            }

            ++i;
        }
    }

    private static boolean isEmips(int n) {
        if (isPrime(n)) {
            String s = String.valueOf(n);
            if (checkPalindrome(s)) {
                return false;
            } else {
                String result = "";
                for (int i = s.length() - 1; i >= 0; i--) {
                    result += s.charAt(i);
                }
                int revNum = Integer.parseInt(result);
                return isPrime(revNum);
            }
        }
        return false;
    }

    static boolean isPrime(int n) {
        for (int i = 2; i <= n / 2; i++) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    static boolean checkPalindrome(String num) {
        for (int i = 0, j = num.length() - 1; i < num.length() / 2; i++, j--) {
            if (num.charAt(i) != num.charAt(j)) {
                return false;
            }
        }
        return true;
    }

}

import java.util.*;

public class ElementalDecompress {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();

        for (int testCase = 0; testCase < t; testCase++) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }

            if (!solve(a)) {
                System.out.println("NO");
            }
        }
    }

    private static boolean solve(int[] a) {
        int n = a.length;
        boolean[] used = new boolean[n + 1];
        int[] p = new int[n];
        int[] q = new int[n];
        int maxUnavailable = 1;

        for (int i = 0; i < n; i++) {
            if (a[i] == maxUnavailable) {
                while (used[maxUnavailable]) {
                    maxUnavailable++;
                }
                p[i] = maxUnavailable++;
                q[i] = a[i];
            } else {
                p[i] = a[i];
                q[i] = maxUnavailable;
                used[maxUnavailable] = true;
                maxUnavailable++;
            }

            if (p[i] > n || q[i] > n) {
                System.out.println("NO");
                return false;
            }
        }

        for (int i = 1; i <= n; i++) {
            if (!used[i]) {
                System.out.println("NO");
                return false;
            }
        }

        System.out.println("YES");
        printArray(p);
        printArray(q);
        return true;
    }

    private static void printArray(int[] arr) {
        for (int i = 0; i < arr.length; i++) {
            System.out.print(arr[i] + " ");
        }
        System.out.println();
    }
}

import java.util.Scanner;

public class KesirliSayiToplama {

    public static void main(String[] args) {

        // Kullanicidan ondalikli iki deger okuyoruz
        Scanner girisOkuyucu = new Scanner(System.in);

        System.out.println("Birinci sayiyi giriniz: ");
        double ilkDeger = girisOkuyucu.nextDouble();

        System.out.println("ikinci sayiyi giriniz: ");
        double ikinciDeger = girisOkuyucu.nextDouble();

        girisOkuyucu.close();

        // Toplami ayri bir metotta hesaplatiyoruz
        double sonuc = topla(ilkDeger, ikinciDeger);

        System.out.println(ilkDeger + " ile " + ikinciDeger + " toplami: " + sonuc);
    }

    private static double topla(double a, double b) {
        return a + b;
    }
}

import java.util.Random;
import java.util.SortedSet;
import java.util.TreeSet;
 
public class CaesarCipher {
    private static final String printable = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ!" +
            "\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~ \t\n\r\f\u000b\u000c";
    private static final Random random = new Random();
    private static final SortedSet<Character> sortedPrintable = new TreeSet<>();
    static {
        for (char c : printable.toCharArray()) {
            sortedPrintable.add(c);
        }
    }
    private static final String exampleKey = sortedPrintable.stream().map(String::valueOf).reduce("", String::concat);
    public static String encode(String plaintext, String key) {
        return plaintext.chars().mapToObj(c -> key.charAt(printable.indexOf(c))).map(String::valueOf).reduce("", String::concat);
    }
    public static String decode(String plaintext, String key) {
        return plaintext.chars().mapToObj(c -> printable.charAt(key.indexOf(c))).map(String::valueOf).reduce("", String::concat);
    }
    public static void main(String[] args) {
        String original = "A simple example.";
        String encoded = encode(original, exampleKey);
        String decoded = decode(encoded, exampleKey);
        System.out.println("The original is: " + original + "\n" +
                "Encoding it with the key: " + exampleKey + "\n" +
                "Gives: " + encoded + "\n" +
                "Decoding it by the same key gives: " + decoded);
    }
}

