import java.util.*;

public class Builder {
    static String markovMatrix = "It is a Markov matrix";
    static String notMarkovMatrix = "It is not a Markov matrix";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[][] test = new double[3][3];

        System.out.println("Enter a 3-by-3 matrix row by row: ");

        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                test[i][j] = in.nextDouble();
            }
        }
        if (isMarkovMatrix(test)) {
            System.out.println(markovMatrix);
        } else {
            System.out.println(notMarkovMatrix);
        }
        in.close();

    }

    public static boolean isMarkovMatrix(double[][] m) {
        for (int i = 0; i < 3; i++) {
            double sum = 0;
            for (int j = 0; j < 3; j++) {
                if (m[j][i] < 0) {
                    return false;
                }
                sum += m[j][i];
            }
            if (sum != 1) {
                return false;
            }
        }
        return true;

    }
}

public PropertyDescriptor findPropertyDescriptor(String name) throws IntrospectionException {
    BeanInfo beanInfo = Introspector.getBeanInfo(getClass());
    PropertyDescriptor[] propertyDescriptors = beanInfo.getPropertyDescriptors();

    for (PropertyDescriptor pd : propertyDescriptors) {
        if (pd.getName().equals(name)) {
            return pd;
        }
    }

    throw new IntrospectionException("No property descriptor found for name: " + name);
}

class Student {
    public String removeDuplicates(String S) {
        Stack<Character> st =  new Stack<>();
        for(char w:S.toCharArray()){
            if(st.size()==0) st.push(w);
            else{
                if(st.peek()==w) st.pop();
                else st.push(w);
            }
        }
        StringBuilder sb = new StringBuilder();
        while(st.size()>0) sb.append(st.pop());
        return sb.reverse().toString();
    }
}

