import java.io.IOException;

/**
 * The CopyStreamException class is thrown by the org.apache.commons.io.Util
 * copyStream() methods.  It stores the number of bytes confirmed to
 * have been transferred before an I/O error as well as the IOException
 * responsible for the failure of a copy operation.
 *
 * @see Util
 */
public class CopyStreamException extends IOException {
  private static final long serialVersionUID = -2602899129433221532L;

  private final long totalBytesTransferred;

  /**
   * Creates a new CopyStreamException instance.
   *
   * @param message A message describing the error.
   * @param bytesTransferred The total number of bytes transferred before
   * an exception was thrown in a copy operation.
   * @param exception The IOException thrown during a copy operation.
   */
  public CopyStreamException(String message, long bytesTransferred, IOException exception) {
    super(message);
    initCause(exception); // merge this into super() call once we need 1.6+
    totalBytesTransferred = bytesTransferred;
  }

  /**
   * Returns the total number of bytes confirmed to have
   * been transferred by a failed copy operation.
   *
   * @return The total number of bytes confirmed to have
   * been transferred by a failed copy operation.
   */
  public long getTotalBytesTransferred() {
    return totalBytesTransferred;
  }

  /**
   * Returns the IOException responsible for the failure of a copy operation.
   *
   * @return The IOException responsible for the failure of a copy operation.
   */
  public IOException getIOException() {
    return (IOException) getCause(); // cast is OK because it was initialised with an IOException
  }
}

import org.bson.BsonReader;
import org.bson.BsonWriter;
import org.bson.codecs.Codec;
import org.bson.codecs.CollectibleCodec;
import org.bson.codecs.DecoderContext;
import org.bson.codecs.EncoderContext;
import org.bson.codecs.configuration.CodecRegistry;
import org.bson.types.ObjectId;
import org.bson.Document;
import org.bson.BsonValue;

import java.util.LinkedHashMap;
import java.util.Map;

public class ImmutableDocumentCodec implements CollectibleCodec<ImmutableDocument> {

    private static final String ID_FIELD_NAME = "_id";
    private final Codec<Document> documentCodec;

    public ImmutableDocumentCodec(CodecRegistry registry) {
        this.documentCodec = registry.get(Document.class);
    }

    @Override
    public ImmutableDocument generateIdIfAbsentFromDocument(ImmutableDocument document) {
        if (!documentHasId(document)) {
            return new ImmutableDocument(document.with("_id", new ObjectId()));
        }
        return document;
    }

    @Override
    public boolean documentHasId(ImmutableDocument document) {
        return document.containsKey(ID_FIELD_NAME);
    }

    @Override
    public BsonValue getDocumentId(ImmutableDocument document) {
        if (!documentHasId(document)) {
            throw new IllegalStateException("Document does not contain an _id");
        }
        Object id = document.get(ID_FIELD_NAME);
        if (id instanceof ObjectId) {
            return org.bson.BsonObjectId.create((ObjectId) id);
        }
        throw new IllegalStateException("Invalid _id. Value must be an ObjectId.");
    }

    @Override
    public void encode(BsonWriter writer, ImmutableDocument document, EncoderContext encoderContext) {
        documentCodec.encode(writer, new Document(document), encoderContext);
    }

    @Override
    public ImmutableDocument decode(BsonReader reader, DecoderContext decoderContext) {
        Document document = documentCodec.decode(reader, decoderContext);
        return new ImmutableDocument(document);
    }

    @Override
    public Class<ImmutableDocument> getEncoderClass() {
        return ImmutableDocument.class;
    }
}

public class Manager {
    public String gcdOfStrings(String str1, String str2) {
        if (!(str1 + str2).equals(str2 + str1)) return "";

        int gcdLength = gcd(str1.length(), str2.length());
        return str1.substring(0, gcdLength);
    }

    public int gcd(int a, int b) {
        if (b == 0) return a;
        return gcd(b, a % b);
    }
}

