            testCases[i] = Math.min(balance(values, a) + balance(values, a), balance(values, b) + balance(values, b));
        }

        for (int tc : testCases) {
            System.out.println(tc);
        }

    }

    private static long balance(int[] values, long cost) throws IllegalStateException {
        long sum = 0;
        for (;;) {
            if (sum > cost)
                throw new IllegalStateException("not enough money");
            if (values[0] == values[1])
                return sum;
            long min = Math.min(Math.abs(values[0]), Math.abs(values[1]));
            sum += cost;
            if (values[0] > 0)
                values[0]--;
            else if (values[0] < 0)
                values[0]++;
            else // values[0] == 0
                values[1] -= Math.min(Math.abs(values[1]), min);
        }
    }

