public class Subleq {
 
    public static void main(String[] args) {
        int[] mem = {15, 17, -1, 17, -1, -1, 16, 1, -1, 16, 3, -1, 15, 15, 0, 0,
            -1, 72, 101, 108, 108, 111, 44, 32, 119, 111, 114, 108, 100, 33, 10, 0};
 
        Scanner input = new Scanner(System.in);
        int instructionPointer = 0;
 
        do {
            int a = mem[instructionPointer];
            int b = mem[instructionPointer + 1];
 
            if (a == -1) {
                mem[b] = input.nextInt();
 
            } else if (b == -1) {
                System.out.printf("%c", (char) mem[a]);
 
            } else {
 
                mem[b] -= mem[a];
                if (mem[b] < 1) {
                    instructionPointer = mem[instructionPointer + 2];
                    continue;
                }
            }
 
            instructionPointer += 3;
 
        } while (instructionPointer >= 0);
    }
}

public static double jaro(String s, String t) {
    if (s.equals(t)) {
        return 1.0;
    }
 
    int sLen = s.length();
    int tLen = t.length();
    int matchDistance = Math.max(sLen, tLen) / 2 - 1;
 
    boolean[] sMatches = new boolean[sLen];
    boolean[] tMatches = new boolean[tLen];
    double matches = 0.0;
 
    for (int i = 0; i < sLen; i++) {
        int jStart = Math.max(0, i - matchDistance);
        int jEnd = Math.min(i + matchDistance, tLen - 1);
 
        for (int j = jStart; j <= jEnd; j++) {
            if (tMatches[j]) {
                continue;
            }
            if (s.charAt(i)!= t.charAt(j)) {
                continue;
            }
            sMatches[i] = true;
            tMatches[j] = true;
            matches += 1.0;
            break;
        }
    }
 
    if (matches == 0.0) {
        return 0.0;
    }
 
    int k = 0;
    double transpositions = 0.0;
    for (int i = 0; i < sLen; i++) {
        if (!sMatches[i]) {
            continue;
        }
        while (!tMatches[k]) {
            k++;
        }
        if (s.charAt(i)!= t.charAt(k)) {
            transpositions += 1.0;
        }
        k++;
    }
 
    return (matches / sLen +
            matches / tLen +
            (matches - transpositions / 2.0) / matches) / 3.0;
}
 
