/**
 * SentimentAnalysisRequest is a data container used to encapsulate all input parameters
 * required for performing a sentiment analysis operation.
 * <p>
 * This class collects various optional parameters that describe the input source to be analyzed,
 * how the text should be extracted, and additional query parameters for refining text selection.
 * It accepts text, HTML, or URL data and provides flags and query strings that adjust how the
 * sentiment analysis engine processes the input.
 * </p>
 * <p>
 * The design follows a simple object-oriented approach with standard retrieval (getter) and assignment
 * (setter) methods for each property, allowing flexible configuration by clients.
 * </p>
 * <p>
 * Example usage:
 * <pre>
 *     SentimentAnalysisRequest request = new SentimentAnalysisRequest("http://example.com");
 *     request.setShowSourceText(true);
 *     request.setCquery(".article-content");
 *     request.setXpath("//div[@class='text']");
 *     request.setSourceText("<html>...</html>");
 * </pre>
 * </p>
 *
 * Note: This code is designed for integration with systems interfacing with sentiment analysis services,
 * possibly within frameworks like MuleSoft.
 *
 */
public class SentimentAnalysisRequest {

    // Private member variables for input parameters
    private String source;
    private boolean showSourceText;
    private String cquery;
    private String xpath;
    private String sourceText;

    // ------------------------------------------------------------------------
    // Constructors
    // ------------------------------------------------------------------------

    /**
     * Default constructor.
     * Initializes the request without setting the default source.
     */
    public SentimentAnalysisRequest() {
        // Setting default values
        this.source = null;
        this.showSourceText = false;
        this.cquery = null;
        this.xpath = null;
        this.sourceText = null;
    }

    /**
     * Parameterized constructor.
     * Initializes the request with a default source.
     *
     * @param source the input source (text, HTML or URL) for sentiment analysis.
     */
    public SentimentAnalysisRequest(@Optional String source) {
        this.source = source;
        this.showSourceText = false;
        this.cquery = null;
        this.xpath = null;
        this.sourceText = null;
    }

    // ------------------------------------------------------------------------
    // Getter and Setter Methods

public JCExpression coerce(Env<AttrContext> env, JCExpression tree, Type target) {
        Env<AttrContext> prevEnv = this.env;
        try {
            this.env = env;
            return coerce(tree, target);
        }
        finally {
            this.env = prevEnv;
        }
    }

