class Converter {

    private String expandRepeatUpToLength100(String input) {
        StringBuffer ret = new StringBuffer(), repeat = new StringBuffer();
        char[] c = input.toCharArray();
        boolean isInsideRepeatBlock = false;

        for(char ch : c) {
            if (ch == '(') {
                isInsideRepeatBlock = true;
            } else if (ch == ')') {
                break;
            } else {
                if (isInsideRepeatBlock) {
                    repeat.append(ch);
                } else {
                    ret.append(ch);
                }
            }
        }

        if (isAllNine(repeat.toString())) {
            return addOneToLastDigit(ret.toString());
        }

        for(int i=0;i<100;i++) {
            ret.append(repeat);
        }

        String res = Double.toString(Double.parseDouble(ret.toString()));
        if (res.length() > 100) {
            return res.substring(0, 100);
        } else {
            return res;
        }
    }

    private boolean isAllNine(String s) {
        boolean ret = false;
        for (char c : s.toCharArray()) {
            if (c != '9') {
                ret = false;
                break;
            } else {
                ret = true;
            }
        }
        return ret;
    }

    private String addOneToLastDigit(String s) {
        Double v = Double.parseDouble(s);
        String[] splitted = s.split("\\.");
        int decimalLength = 0;
        if (splitted.length == 2) {
            decimalLength = splitted[1].length();
        }
        Double inc = (double) 1;
        for(int i=0;i<decimalLength;i++) {
            inc = inc / 10;
        }
        return Double.toString(v + inc);
    }

    public boolean isRationalEqual(String S, String T) {
        S = expandRepeatUpToLength100(S);
        T = expandRepeatUpToLength100(T);
        Double v = Double.parseDouble(S) - Double.parseDouble(T);
        Double bar = 1e-10;
        return (v < bar && v > -bar);
    }
}

