@Configuration
@EnableWebMvc
@ComponentScan(basePackages = {
    "org.flowable.app.rest.api",
    "org.flowable.app.rest.exception"
})
public class ApiDispatcherServletConfiguration implements WebMvcConfigurer {

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private Environment environment;

    @Bean
    public LocaleResolver localeResolver() {
        SessionLocaleResolver resolver = new SessionLocaleResolver();
        resolver.setDefaultLocale(Locale.ENGLISH);
        return resolver;
    }

    @Bean
    public RequestMappingHandlerMapping requestMappingHandlerMapping() {
        RequestMappingHandlerMapping handlerMapping = new RequestMappingHandlerMapping();
        handlerMapping.setUseSuffixPatternMatch(false);
        handlerMapping.setRemoveSemicolonContent(false);
        handlerMapping.setOrder(0);
        return handlerMapping;
    }

    @Override
    public void configureMessageConverters(List<HttpMessageConverter<?>> converters) {
        converters.add(new MappingJackson2HttpMessageConverter(objectMapper));
    }

    @Override
    public void configureAsyncSupport(AsyncSupportConfigurer configurer) {
        Long timeout = environment.getProperty("async.request.timeout", Long.class, 5000L);
        configurer.setDefaultTimeout(timeout);
    }

    @Override
    public void configurePathMatch(PathMatchConfigurer configurer) {
        configurer.setUseSuffixPatternMatch(false);
    }

    @Override
    public void addFormatters(FormatterRegistry registry) {
        registry.removeConvertible(String.class, Date.class);
        registry.addConverter(new StringToDateConverter());
    }

    private static class StringToDateConverter implements Converter<String, Date> {
        @Override
        public Date convert(String source) {
            try {
                return new SimpleDateFormat("yyyy-MM-dd").parse(source);
            } catch (ParseException e) {
                throw new IllegalArgumentException("Invalid date format");
            }
        }
    }
}

import static com.google.appengine.api.datastore.Query.FilterOperator.EQUAL;

import java.util.Date;
import java.util.List;

import org.vosao.dao.BaseDaoImpl;
import org.vosao.dao.FileChunkDao;
import org.vosao.dao.FileDao;
import org.vosao.entity.FileEntity;

import com.google.appengine.api.datastore.Query;

public class FileDaoImpl extends BaseDaoImpl<FileEntity>
        implements FileDao {

    public FileDaoImpl() {
        super(FileEntity.class);
    }

    @Override
    public void remove(final Long fileId) {
        if (fileId == null) {
            return;
        }
        getFileChunkDao().removeByFile(fileId);
        super.remove(fileId);
    }

    @Override
    public void remove(final List<Long> ids) {
        for (Long fileId : ids) {
            remove(fileId);
        }
    }

    @Override
    public List<FileEntity> getByFolder(Long folderId) {
        Query q = newQuery();
        q.addFilter("folderId", EQUAL, folderId);
        return select(q, "getByFolder", params(folderId));
    }

    @Override
    public FileEntity getByName(Long folderId, String name) {
        Query q = newQuery();
        q.addFilter("folderId", EQUAL, folderId);
        q.addFilter("filename", EQUAL, name);
        return selectOne(q, "getByName", params(folderId, name));
    }

    @Override
    public void save(FileEntity file, byte[] content) {
        file.setLastModifiedTime(new Date());
        file.setSize(content.length);
        save(file);
        getFileChunkDao().save(file, content);
    }

    @Override
    public void removeByFolder(Long folderId) {
        List<FileEntity> files = getByFolder(folderId);
        for (FileEntity file : files) {
            remove(file.getId());
        }
    }

    @Override
    public void removeAll() {
        super.removeAll();
        getFileChunkDao().removeAll();
    }

    public FileChunkDao getFileChunkDao() {
        return getDao().getFileChunkDao();
    }

    @Override
    public byte[] getFileContent(FileEntity file) {
        return getFileChunkDao().getFileContent(file);
    }

}

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.Scanner;
import java.util.Set;
import java.util.HashSet;
 
public class MadLibs_RosettaCode
{
    public static void main(String[] args)
    {
        String madLibs =
"Write a program to create a Mad Libs like story.\n" +
"The program should read an arbitrary multiline story from input.\n" +
"The story will be terminated with a blank line.\n" +
"Then, find each replacement to be made within the story, \n" +
"ask the user for a word to replace it with, and make all the replacements.\n" +
"Stop when there are none left and print the final story.\n" +
"The input should be an arbitrary story in the form:\n" +
"<name> went for a walk in the park. <he or she>\n" +
"found a <noun>. <name> decided to take it home.\n" +
"Given this example, it should then ask for a name, \n" +
"a he or she and a noun (<name> gets replaced both times with the same value).";
 
        StringBuilder sb = new StringBuilder();
        Pattern pattern = Pattern.compile("\\<(.*?)\\>");
        String storyLine;
        String replacement;
 
        System.out.println(madLibs + "\n\n");
        System.out.println("Enter a story: ");
 
        // Continue to get input while empty line hasn't been entered.
        do
        {
            storyLine = new Scanner(System.in).nextLine();
            sb.append(storyLine + "\n");
        } while (!storyLine.isEmpty());
 
        // Retrieve only the unique regex matches from the user entered story.
        Matcher nameMatch = pattern.matcher(sb.toString());
        if(nameMatch.find() && nameMatch.group(1).equals("name"))
        {
            do
            {
                System.out.println("Enter value for: " + nameMatch.group(1));
                replacement = new Scanner(System.in).nextLine();
            } while (replacement.isEmpty());
            sb.replace(nameMatch.start(), nameMatch.end(), replacement);
        }
 
        Set<String> matches = new HashSet<String>();
        while(nameMatch.find())
        {
            matches.add(nameMatch.group(1));
        }
 
        for(String match : matches)
        {
            replacement = "";
            // Guarantee we get a non-whitespace value for the replacement
            do
            {
                System.out.println("Enter value for: " + match);
                replacement = new Scanner(System.in).nextLine();
            } while (replacement.isEmpty());
 
            int location = sb.indexOf("<" + match + ">");
            sb.replace(location, location + match.length() + 2, replacement);

