import net.sourceforge.jnlp.ProcessResult;
import net.sourceforge.jnlp.ServerAccess;
import org.junit.Assert;
import org.junit.Test;

public class AllStackTracesTest {

    @Test
    public void AllStackTracesTest1() {
        ServerAccess server = new ServerAccess();
        String c = "-J-Djava.security.policy==security.policy";
        String cc = "security/AllStackTraces.jnlp";
        ProcessResult pr = server.executeJavawsHeadless(c, cc);
        Assert.assertTrue("access denied", pr.stderr.matches(
                "(?s).*java.security.AccessControlException: access denied "
                + "(\"java.lang.RuntimePermission\" \"getStackTrace\").*"));
        Assert.assertFalse("ClassNotFoundException should not be there", pr.stderr.contains("ClassNotFoundException"));
        Assert.assertFalse("Executed app should not have terminated", pr.wasTerminated);
        Assert.assertEquals("Javaws should have returned error", 1, pr.retValue);
    }
}

