public class Sorter {
    public int countTriplets(int[] nums1, int[] nums2) {
        HashMap<Long, Integer> nums1Squared, nums2Squared;
        nums1Squared = new HashMap<>();
        nums2Squared = new HashMap<>();

        // Populate the frequency maps for nums1 and nums2 squares
        for(int num : nums1) {
            long square = (long) num * num;
            nums1Squared.put(square, nums1Squared.getOrDefault(square, 0) + 1);
        }
        for(int num : nums2) {
            long square = (long) num * num;
            nums2Squared.put(square, nums2Squared.getOrDefault(square, 0) + 1);
        }

        int countType1 = 0, countType2 = 0;

        // Count Type 1 Triplets
        for (Map.Entry<Long, Integer> entry : nums1Squared.entrySet()) {
            long square = entry.getKey();
            long remainder = square / nums2Squared.size();
            for (int j = 0; j < nums2Squared.size(); j++) {
                if (square - remainder * jL == 0) {
                    long coef = (long) Math.ceil(Math.sqrt(square / (long) j));
                    countType1 += entry.getValue() * coef * (coef - 1);
                }
            }
        }

        // Count Type 2 Triplets
        for (int i = 0; i < nums2Squared.size(); i++) {
            long square = (long) iL * iL;
            if (nums1Squared.containsKey(square)) {
                countType2 += nums1Squared.get(square) * nums2Squared.size();
            }
        }

        return countType1 + countType2;
    }

    // Utility function to calculate ceiling square root (optimization)
    private int ceiling(long num) {
        int sqrt = (int) Math.sqrt(num);
        return sqrt > 0 ? sqrt : 1;
    }

    // Utility function to calculate error margin (optimization)
    private long jL = 1;
}

