        long val3 = ifact[r];

        return (((val1 * val2) % Mod) * val3) % Mod;
    }

    long expo(long a, long b, long mod) {
        long res = 1;
        while (b != 0) {
            if ((b & 1) == 1)
                res = (res * a) % mod;

            a = (a * a) % mod;
            b >>= 1;
        }

        return res;
