import javax.xml.XMLConstants;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;

import org.xml.sax.SAXException;

public void createOrUpdateXsdFile(File xmlInputFile, File xsdOutFile)
        throws XmlException, IOException {
    try {
        SchemaFactory factory = SchemaFactory.newInstance(XMLConstants.W3C_XML_SCHEMA_NS_URI);
        Schema schema = factory.newSchema(xmlInputFile);
        schema.write(xsdOutFile);
    } catch (SAXException e) {
        throw new XmlException("Error while creating schema from XML file.", e);
    } catch (IOException e) {
        throw new IOException("Error while writing output XSD file.", e);
    }
}

