class Order {
    public boolean checkXMatrix(int[][] grid) {
        int n = grid.length;
        for(int i =0; i < n; i++)
            for(int j =0; j <n; j++)
            {
                if(i == j || i+j == n-1)
                {
                    if(grid[i][j] == 0)
                    return false;
                }
                else{
                    if(grid[i][j] != 0)
                        return false;
                }
            }
        return true;
    }
}

import jakarta.enterprise.context.spi.Context;
import jakarta.enterprise.context.spi.Contextual;
import jakarta.enterprise.context.spi.CreationalContext;
import org.jboss.cdi.tck.spi.Contexts;
import org.jboss.weld.context.ManagedContext;
import org.jboss.weld.context.RequestContext;
import org.jboss.weld.context.DependentContext;
import org.jboss.weld.context.ApplicationContext;
import org.jboss.weld.manager.BeanManagerImpl;

public class ContextsImpl implements Contexts<BeanManagerImpl> {

    private final BeanManagerImpl beanManager;

    public ContextsImpl(BeanManagerImpl beanManager) {
        this.beanManager = beanManager;
    }

    @Override
    public RequestContext getRequestContext() {
        return beanManager.instance(RequestContext.class);
    }

    @Override
    public DependentContext getDependentContext() {
        return beanManager.instance(DependentContext.class);
    }

    @Override
    public void setActive(Class<? extends Context> contextType) {
        Context context = beanManager.getContext(contextType);
        if (context instanceof ManagedContext) {
            ((ManagedContext) context).activate();
        }
    }

    @Override
    public void setInactive(Class<? extends Context> contextType) {
        Context context = beanManager.getContext(contextType);
        if (context instanceof ManagedContext) {
            ((ManagedContext) context).deactivate();
        }
    }

    @Override
    public void destroyContext(Class<? extends Context> contextType) {
        Context context = beanManager.getContext(contextType);
        if (context instanceof ApplicationContext) {
            ((ApplicationContext) context).invalidate();
        } else if (context instanceof ManagedContext) {
            ManagedContext managedContext = (ManagedContext) context;
            managedContext.deactivate();
            managedContext.activate();
        } else {
            throw new UnsupportedOperationException("Cannot destroy context of type: " + contextType.getName());
        }
    }
}

