            System.out.println(infixToPostfix(expression));
        } catch (Exception ex) {
            System.out.println("Wrong expression");
        }
    }

    public static String infixToPostfix(String expression) {
        String result = "";

        Stack<Character> operatorStack = new Stack<>();
        java.util.StringTokenizer tokens =
                new java.util.StringTokenizer(expression, "()+-/*%", true);

        while (tokens.hasMoreTokens()) {
            String token = tokens.nextToken().trim(); // Extract a token
            if (token.length() == 0) {
                continue;
            } else if (token.charAt(0) == '+' || token.charAt(0) == '-') {
                while (!operatorStack.isEmpty() &&
                        (operatorStack.peek().equals('+') ||
                                operatorStack.peek().equals('-') ||
                                operatorStack.peek().equals('*') ||
                                operatorStack.peek().equals('/')
                        )) {
                    result += operatorStack.pop() + " ";
                }

                operatorStack.push(new Character(token.charAt(0)));
            } else if (token.charAt(0) == '*' || token.charAt(0) == '/') {

                while (!operatorStack.isEmpty() &&
                        (operatorStack.peek().equals('*') ||
                                operatorStack.peek().equals('/')
                        )) {
                    result += operatorStack.pop() + " ";
                }

                operatorStack.push(new Character(token.charAt(0)));
            } else if (token.trim().charAt(0) == '(') {
                operatorStack.push(new Character('('));
            } else if (token.trim().charAt(0) == ')') {
                while (!operatorStack.peek().equals('(')) {
                    result += operatorStack.pop() + " ";
                }

                operatorStack.pop();
            } else {
                result += token + " ";
            }
        }
        while (!operatorStack.isEmpty()) {
            result += operatorStack.pop() + " ";
        }
        return result;
    }
}

private BufferedImage convertImage(BufferedImage image) {
    if (image.getType() != BufferedImage.TYPE_INT_RGB) {
        BufferedImage convertedImage = new BufferedImage(image.getWidth(), image.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D g2d = convertedImage.createGraphics();
        g2d.drawImage(image, 0, 0, null);
        g2d.dispose();
        return convertedImage;
    }
    return image;
}

import java.sql.ParameterMetaData;
import java.sql.SQLException;
import java.util.Collections;
import java.util.List;

import org.apache.phoenix.jdbc.PhoenixConnection;
import org.apache.phoenix.jdbc.PhoenixStatement;
import org.apache.phoenix.parse.DropSequenceStatement;
import org.apache.phoenix.schema.MetaDataClient;
import org.apache.phoenix.execute.MutationState;
import org.apache.phoenix.execute.MutationPlan;
import org.apache.phoenix.compile.StatementContext;

public class DropSequenceCompiler {

    private final PhoenixStatement statement;

    public DropSequenceCompiler(PhoenixStatement statement) {
        this.statement = statement;
    }

    public MutationPlan compile(final DropSequenceStatement dropSequenceStatement) throws SQLException {
        final PhoenixConnection connection = statement.getConnection();
        final MetaDataClient metaDataClient = new MetaDataClient(connection);
        final StatementContext context = new StatementContext(statement);

        return new MutationPlan() {
            @Override
            public MutationState execute() throws SQLException {
                return metaDataClient.dropSequence(dropSequenceStatement.getSequenceName());
            }

            @Override
            public List<KeyPart> getStatementKey() {
                return Collections.emptyList();
            }

            @Override
            public StatementContext getContext() {
                return context;
            }

            @Override
            public PhoenixConnection getConnection() {
                return connection;
            }

            @Override
            public ParameterMetaData getParameterMetaData() throws SQLException {
                 return null;
            }

            @Override
            public String getExplainPlan() {
                return "DROP SEQUENCE " + dropSequenceStatement.getSequenceName();
            }
        };
    }
}

private ItemDetail getItemDetail(Gson gson, JsonElement itemType, JsonElement detail) {
        if (itemType == null || detail == null) return null;
        Item.Type type = gson.fromJson(itemType, Item.Type.class);
        Class<? extends ItemDetail> detailType;
        switch (type) {
            case Armor:
                detailType = Armor.class;
                break;
            case Back:
                detailType = Back.class;
                break;
            case Bag:
                detailType = Bag.class;
                break;
            case Consumable:
                detailType = Consumable.class;
                break;
            case MiniPet:
                detailType = Mini.class;
                break;
            case Trinket:
                detailType = Trinket.class;
                break;
            case UpgradeComponent:
                detailType = UpgradeComponent.class;
                break;
            case Weapon:
                detailType = Weapon.class;
                break;
            default:
                detailType = Utility.class;
        }
        return gson.fromJson(detail, detailType);
    }

