public void setIdIfMutatorExists(Document document, String id) {
  Method mutator;
  try {
    mutator = document.getClass().getMethod("setId", String.class);
  } catch (NoSuchMethodException e) {
    // Mutator doesn't exist.
    return;
  }

  try {
    mutator.invoke(document, id);
  } catch (Exception e) {
    // Error invoking mutator.
    throw new RuntimeException(e);
  }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Iterator;
 
public class PolynomialLongDivision {
 
    public static int degree(List<Integer> poly) {
        while (poly.size() > 0 && poly.get(poly.size() - 1) == 0) {
            poly.remove(poly.size() - 1);
        }
        return poly.size() - 1;
    }
 
    public static List<Integer> poly_div(List<Integer> N, List<Integer> D) {
        int dD = degree(D);
        int dN = degree(N);
        if (dD < 0) {
            throw new ArithmeticException("Division by zero");
        }
        List<Integer> q = new ArrayList<Integer>();
        List<Integer> r = new ArrayList<Integer>();
        if (dN >= dD) {
            q = new ArrayList<Integer>(dN);
            for (int i = 0; i < dN; i++) {
                q.add(0);
            }
            while (dN >= dD) {
                List<Integer> d = new ArrayList<Integer>(dN - dD + D.size());
                for (int i = 0; i < dN - dD; i++) {
                    d.add(0);
                }
                d.addAll(D);
                double mult = q.get(dN - dD) = N.get(N.size() - 1) / (double) d.get(d.size() - 1);
                for (int i = 0; i < d.size(); i++) {
                    d.set(i, (int) (d.get(i) * mult));
                }
                for (int i = 0; i < N.size(); i++) {
                    N.set(i, N.get(i) - d.get(i));
                }
                dN = degree(N);
            }
            r = N;
        } else {
            q = new ArrayList<Integer>(1);
            q.add(0);
            r = N;
        }
        List<Integer> result = new ArrayList<Integer>(q.size() + r.size());
        result.addAll(q);
        result.addAll(r);
        return result;
    }
 
    public static void main(String[] args) {
        System.out.println("POLYNOMIAL LONG DIVISION");
        List<Integer> N = new ArrayList<Integer>();
        N.add(-42);
        N.add(0);
        N.add(-12);
        N.add(1);
        List<Integer> D = new ArrayList<Integer>();
        D.add(-3);
        D.add(1);
        D.add(0);
        D.add(0);
        System.out.print("  " + N + " / " + D + " = ");
        List<Integer> result = poly_div(N, D);
        System.out.print(" " + result.subList(0, result.size() - 4) + " remainder " + result.subList(result.size() - 4, result.size()));
    }
}

public ArrayList<Integer> sortByBits(ArrayList<Integer> nums) {
  // Sort nums first.
  // Then, for each number n, get the count of the number of ones in its
  // binary representation, c.
  // Then, put it with the others whose binary count is c.
  Collections.sort(nums);
  TreeMap<Integer, List<Integer>> map = new TreeMap<>();
  for (int i : nums) {
    int c = 0;
    int j = i;
    while (j != 0) {
      if ((j & 1) == 1) c++;
      j >>= 1;
    }
    if (!map.containsKey(c)) map.put(c, new ArrayList<>());
    List<Integer> list = new ArrayList<Integer>(map.get(c));
    list.add(i);
    map.put(c, list);
  }
  nums.clear();
  for (int c : map.keySet()) {
    List<Integer> list = map.get(c);
    for (int i : list) {
      nums.add(i);
    }
  }
  return nums;
}

