  for (int i : nums) {
    int c = 0;
    int j = i;
    while (j != 0) {
      if ((j & 1) == 1) c++;
      j >>= 1;
    }
    if (!map.containsKey(c)) map.put(c, new ArrayList<>());
    List<Integer> list = new ArrayList<>(map.get(c));
    list.add(i);
    map.put(c, list);
  }
  List<Integer> result = new ArrayList<>();
  for (int c : map.keySet()) {
    List<Integer> list = map.get(c);
    for (int i : list) {
      result.add(i);
    }
  }
  // result contains the result.
  // Copy it to nums.
  int index = 0;
  for (int i : result) {
    nums[index++] = i;
  }
  return nums;
}

public List<Integer> sortByBits(List<Integer> nums) {
  Map<Integer, List<Integer>> map = new HashMap<>();
  for (Integer n : nums) {
    int c = 0;
    int temp = n;
    while (temp != 0) {
      if (temp % 2 == 1) {
        c++;
      }
      temp >>= 1;
    }
    List<Integer> list = map.getOrDefault(c, new ArrayList<>());
    list.add(n);
    map.put(c, list);
  }
  List<Integer> result = new ArrayList<>();
  for (int k : map.keySet()) {
    List<Integer> list = map.get(k);
    Collections.sort(list);
    result.addAll(list);
  }
  return result;
}

