        printTaxicabNumbers(taxicabNumbers);
    }
 
    private static Map<Long, List<Tuple<Integer, Integer>>> getTaxicabNumbers(int length) {
        SortedMap<Long, List<Tuple<Integer, Integer>>> sumsOfTwoCubes = new TreeMap<Long, List<Tuple<Integer, Integer>>>();
 
        for (int i = 1; i < Integer.MAX_VALUE; i++) {
            for (int j = 1; j < Integer.MAX_VALUE; j++) {
                long sum = (long) Math.pow((double) i, 3) + Math.pow((double) j, 3);
 
                if (!sumsOfTwoCubes.containsKey(sum)) {
                    sumsOfTwoCubes.put(sum, new ArrayList<Tuple<Integer, Integer>>());
                }
 
                sumsOfTwoCubes.get(sum).add(new Tuple<Integer, Integer>(i, j));
 
                if (j >= i) {
                    break;
                }
            }
 
            // Found that you need to keep going for a while after the length, because higher i values fill in gaps
            if (sumsOfTwoCubes.size() >= length * 1.1) {
                break;
            }
        }
 
        Map<Long, List<Tuple<Integer, Integer>>> values = new HashMap<Long, List<Tuple<Integer, Integer>>>();
 
        for (Entry<Long, List<Tuple<Integer, Integer>>> entry : sumsOfTwoCubes.entrySet()) {
            if (entry.getValue().size() >= 2) {
                values.put(entry.getKey(), entry.getValue());
            }
 
            if (values.size() >= length) {
                break;
            }
        }
 
        return values;
    }
 
    private static void printTaxicabNumbers(Map<Long, List<Tuple<Integer, Integer>>> values) {
        int i = 1;
 
        for (Entry<Long, List<Tuple<Integer, Integer>>> entry : values.entrySet()) {
            StringBuilder output = new StringBuilder().append(String.format("%10d\t%4d", i, entry.getKey()));
 
            for (Tuple<Integer, Integer> numbers : entry.getValue()) {
                output.append(String.format("\t= %d^3 + %d^3", numbers.item1, numbers.item2));
            }
 
            if (i <= 25 || (i >= 2000 && i <= 2006)) {
                System.out.println(output.toString());
            }
 
            i++;
        }
    }
 
