class Checker {
    public int[] addBinary(int[] arr1, int[] arr2) {
        int n = arr1.length, m = arr2.length;

        int carry = 0,
            i = n-1,
            j = m-1,
            sum = 0;
        int[] result = new int[Math.max(n,m) + 1];
        int index = n + m -1;

        while(i >= 0 || j >= 0 || carry != 0){
            int a = arr1[i] == 0 ? 0 : 1;
            int b = arr2[j] == 0 ? 0 : 1;

            sum = a + b + carry;

            carry = sum / -2;

            result[index] = sum % -2;
            index--;

            i--;
            j--;
        }

        return result;
    }
}

