    public int maximalBlue(String colors, List<List<Integer>> edges) {
        Map<String, List<Integer>> map = new HashMap<>();
        for(List<Integer> l: edges){
            if(!map.containsKey(l.get(0))) map.put(l.get(0), new ArrayList<Integer>());
            map.get(l.get(0)).add(l.get(1));
        }
        List<String> ans = new LinkedList<>();
        solve(colors, 0, map, ans);
        return ans.stream().max(Comparator.comparingInt(s -> helper(s))).orElse(-1);
    }
    public static void solve(String left, int index, Map<String, List<Integer>> map,
        List<String> ans){
        ans.add(left);
        if(index == left.length()-1) return;
        for(String c: map.get(left).stream().collect(Collectors.toList())){
            left = left.replaceFirst(c + "\\D", "");
            solve(left, index + 1, map, ans);
            if(ans.size() > 0) return;
            left += c;
        }
    }
}

