class Counter {
    public int maximumProduct(int[] nums, int k) {
        int mod = (int) 1e9 + 7;
        Arrays.sort(nums);
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        for (int num : nums) {
            pq.offer(num);
        }
        while (k-- > 0) {
            int cur = pq.poll();
            cur += 1;
            pq.offer(cur);
        }
        long res = 1;
        while (!pq.isEmpty()) {
            res = res * pq.poll() % mod;
        }
        return (int) res;
    }
}

