@Controller
public class UserJService {

    @Autowired
    private UserLocalService userLocalService;

    @Autowired
    private MessageSource messageSource;

    @Autowired
    private SessionLocaleResolver localeResolver;

    @GetMapping("/users")
    @ResponseBody
    public String findAllPageable(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "10") int size,
            HttpServletRequest request) {

        // Resolve the user's locale
        Locale locale = localeResolver.resolveLocale(request);

        // Retrieve paginated user data
        Page<User> userPage = userLocalService.findAll(PageRequest.of(page, size));

        // Calculate pagination metadata
        long totalEntries = userPage.getTotalElements();
        int totalPages = userPage.getTotalPages();
        int currentPage = userPage.getNumber();
        int pageSize = userPage.getSize();

        // Localized text for the current page range
