import java.math.BigInteger;

public class BellNumbers {
    public static void init(BigInteger[] array, BigInteger value) {
        if (null == array) return;
        for (int i = 0; i < array.length; ++i) {
            array[i] = value;
        }
    }

    public static BigInteger[][] bellTriangle(int n) {
        BigInteger[][] tri = new BigInteger[n][];
        for (int i = 0; i < n; ++i) {
            tri[i] = new BigInteger[i];
            init(tri[i], BigInteger.ZERO);
        }
        tri[1][0] = BigInteger.ONE;
        for (int i = 2; i < n; ++i) {
            tri[i][0] = tri[i - 1][i - 2];
            for (int j = 1; j < i; ++j) {
                tri[i][j] = tri[i][j - 1].add(tri[i - 1][j - 1]);
            }
        }
        return tri;
    }

    public static void main(String[] args) {
        var bt = bellTriangle(51);
        System.out.println("First fifteen and fiftieth Bell numbers:");
        for (int i = 1; i < 16; ++i) {
            System.out.printf("%2d: %s%n", i, bt[i][0]);
        }
        System.out.printf("50: %s%n", bt[50][0]);
        System.out.println();
        System.out.println("The first ten rows of Bell's triangle:");
        for (int i = 1; i < 11; ++i) {
            //System.out.println(bt[i]);
            var it = bt[i].iterator();
            System.out.print("[");
            if (it.hasNext()) {
                System.out.print(it.next());
            }
            while (it.hasNext()) {
                System.out.print(", ");
                System.out.print(it.next());
            }
            System.out.println("]");
        }
    }
}

