class Shape {
    public int maxUncrossedLines(int[] A, int[] B) {
        int res = 0;
        int[][] dp = new int[A.length+1][B.length+1];
        for(int i = 1;i<=A.length;i++){
            for(int k = 1;k<=B.length;k++){
                if(A[i-1] == B[k-1]){
                    dp[i][k] = max(dp[i-1][k],dp[i][k-1],dp[i-1][k-1]+1);
                }
                else{
                    dp[i][k] = max(dp[i-1][k],dp[i][k-1],dp[i-1][k-1]);
                }
                if(dp[i][k]>res)
                    res = dp[i][k];
            }
        }
        return res;
    }

    int max(int a, int b, int c){
        if(b>a) a = b;
        if(c>a) a = c;
        return a;
    }
}

