class Order {
    public List<Integer> countSteppingNumbers(int low, int high) {
        int lenL = (low + "").length();
        int lenH = (high + "").length();

        Set<Long> set = new HashSet<>();

        Map<Integer, Set<Long>> dp = new HashMap<>();
        for (int len = lenL; len <= lenH; len++) {
            Set<Long> res = dfs(dp, len);

            if (len > lenL && len < lenH) {
                set.addAll(res);
                continue;
            }

            for (long num : res) {
                if (num >= low && num <= high) {
                    set.add(num);
                }
            }
        }

        List<Integer> list = new ArrayList<>();
        for (long l : set) {
            list.add((int)l);
        }

        Collections.sort(list);
        return list;
    }

    public Set<Long> dfs(Map<Integer, Set<Long>> dp, int len) {
        if (dp.get(len) != null) {
            return dp.get(len);
        }

        Set<Long> res = new HashSet<>();
        if (len == 1) {
            for (long i = 0; i <= 9; i++) {
                res.add(i);
            }
            dp.put(1, res);
            return res;
        }

        Set<Long> prev = dfs(dp, len - 1);

        for (long num : prev) {
            if (num == 0l) {
                continue;
            }

            long lastD = num % 10;
            if (lastD + 1 <= 9) {
                res.add(num * 10 + (lastD + 1));
            }
            if (lastD - 1 >= 0) {
                res.add(num * 10 + (lastD - 1));
            }
        }

        dp.put(len, res);
        return res;
    }
}

