import java.lang.Math;
 
public class Narcissistic
{
    public boolean isNarcissistic(int z)
    {
        if (z < 0) return false;
        String n = Integer.toString(z);
        int t = 0, l = n.length();
        for (int i = 0; i < l; i++)
            t += Math.pow(n.charAt(i) - 48, l);
 
        return t == z;
    }
}
 
public class Solution
{
    public static void main(String[] args)
    {
        Narcissistic n = new Narcissistic();
        int c = 0, x = 0;
        while (c < 25)
        {
            if (n.isNarcissistic(x))
            {
                if (c % 5 == 0) System.out.println();
                System.out.printf("%7d ", x);
                c++;
            }
            x++;
        }
        System.out.println("\n\nPress any key to continue...");
        System.in.read();
    }
}

class Parser {
    public int distMoney(int money, int children) {
        if (money == 8 * children) {
            return children;
        } else if (money > 8 * children) {
            return children - 1;
        } else if (money < children) {
            return -1;
        } else {
            int res = 0;
            for (int i = 0; i < children; ++i) {
                int r = children - i, m = money - i * 8;
                if (m < r) break;
                else if (r == 1 && m == 4) {
                    continue;
                } else {
                    res = i;
                }
            }
            return res;
        }
    }
}

class Order {
    private HashMap<String, Integer>  kk = new HashMap<>();
    private int maxVal = 0;
    public int maxFreq(String s, int maxLetters, int minSize, int maxSize) {

        for (int sz = minSize; sz <= maxSize; sz++) {
            helper(s, sz, maxLetters);
        }
        return maxVal;
    }
    private void helper(String s, int sz, int  maxLetters) {
         int[] map = new int[26];
         int diff = 0, n = s.length();
        int lo = 0;

        for (int hi = 0; hi < n; hi++) {
            char ch = s.charAt(hi);
            if (++map[ch-'a'] == 1) diff++;
            if (hi-lo+1 == sz) {
                if (diff <= maxLetters) {
                    String tmp = s.substring(lo, hi+1);
                    kk.put(tmp, kk.getOrDefault(tmp,0)+1);
                    maxVal = Math.max(maxVal, kk.get(tmp));
                }
                char d = s.charAt(lo++);
                if (--map[d-'a']==0) diff--;
            }
        }

    }
}

class Processor {
    long mod = 1000000007;

    public int countPartitions(int[] nums, int k) {
        // mem[i][j] 表示前 i 个元素和为 j 的方案数
        long[][] mem = new long[nums.length + 1][k + 1];
        long sum = 0;
        mem[0][0] = 1;
        for (int i = 0; i < nums.length; i++) {
            for (int j = 0; j <= k; j++) {
                mem[i + 1][j] = mem[i][j];
                if (nums[i] <= j) {
                    mem[i + 1][j] += mem[i][j - nums[i]];
                }
                mem[i + 1][j] %= mod;
            }
            sum += nums[i];
        }
        if (k * 2L > sum) {
            return 0;
        }
        long tot = 0;
        for (int i = 0; i < k; i++) {
            tot += mem[nums.length][i] * 2;
            tot %= mod;
        }
        long pow2 = 1;
        for (int i = 0; i < nums.length; i++) {
            pow2 = pow2 * 2 % mod;
        }
        return (int) ((((pow2 - tot) % mod) + mod) % mod);
    }
}

