import java.util.*;

class Task {
    public int countPairs(List<List<Integer>> coordinates, int k) {
        int ans = 0;
        for(int k1 = 0; k1 <= k; k1++) {
            int k2 = k - k1;
            ans += compute(coordinates, k1, k2);
        }
        return ans;
    }
    private int compute(List<List<Integer>> coordinates, int k1, int k2) {
        int cnt = 0;
        Map<Integer, Map<Integer, Integer>> map = new HashMap<>();
        for(int i = 0; i < coordinates.size(); i++) {
            int x2 = coordinates.get(i).get(0), y2 = coordinates.get(i).get(1);
            int x1 = k1 ^ x2, y1 = k2 ^ y2;
            Map<Integer, Integer> m = map.getOrDefault(x1, null);
            if(m != null) {
                cnt += m.getOrDefault(y1, 0);
            }
            if(!map.containsKey(x2)) {
                Map<Integer, Integer> m1 = new HashMap<>();
                map.put(x2, m1);
            }
            Map<Integer, Integer> m2 = map.get(x2);
            m2.put(y2, m2.getOrDefault(y2, 0) + 1);
        }
        return cnt;
    }
}

