public class MatrixMultiplication {
    public static int[][] multiply(int[][] a, int[][] b) {
        int rows = a.length;
        int cols = b[0].length;
        int common = b.length;

        int[][] result = new int[rows][cols];
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                for (int k = 0; k < common; k++) {
                    result[i][j] += a[i][k] * b[k][j];
                }
            }
        }
        return result;
    }

    public static void main(String[] args) {
        int[][] first = {{1, 2}, {3, 4}};
        int[][] second = {{5, 6}, {7, 8}};

        int[][] product = multiply(first, second);
        for (int[] row : product) {
            for (int value : row) {
                System.out.print(value + " ");
            }
            System.out.println();
        }
    }
}

public class Stack {
    public static void main(String[] args) {
        int count = 0;
        for (int year = 101; year <= 2100; year++) {
            if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
                System.out.printf("%-5d", year);
                count++;
                if (count % 10 == 0) {
                    System.out.println();
                }
            }
        }
        System.out.println("\n\nThe number of leap years is " + count);
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public class Finder {
    public List<List<Integer>> closestNodes(TreeNode root, int[] queries) {
        List<Integer> sortedValues = new ArrayList<>();
        inorderTraversal(root, sortedValues);

        List<List<Integer>> result = new ArrayList<>();
        for (int query : queries) {
            List<Integer> answer = new ArrayList<>();
            int mini = findFloor(sortedValues, query);
            int maxi = findCeil(sortedValues, query);
            answer.add(mini);
            answer.add(maxi);
            result.add(answer);
        }

        return result;
    }

    private void inorderTraversal(TreeNode node, List<Integer> sortedValues) {
        if (node == null) return;
        inorderTraversal(node.left, sortedValues);
        sortedValues.add(node.val);
        inorderTraversal(node.right, sortedValues);
    }

    private int findFloor(List<Integer> sortedValues, int query) {
        int left = 0, right = sortedValues.size() - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (sortedValues.get(mid) == query) {
                return query;
            } else if (sortedValues.get(mid) < query) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return right >= 0 ? sortedValues.get(right) : -1;
    }

    private int findCeil(List<Integer> sortedValues, int query) {
        int left = 0, right = sortedValues.size() - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (sortedValues.get(mid) == query) {
                return query;
            } else if (sortedValues.get(mid) < query) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return left < sortedValues.size() ? sortedValues.get(left) : -1;
    }
}

import java.util.Map;

import org.apache.accumulo.core.metadata.StoredTabletFile;
import org.apache.accumulo.core.metadata.TabletFile;
import org.apache.accumulo.tserver.compaction.CompactionPlan;
import org.apache.accumulo.tserver.compaction.CompactionStrategy;
import org.apache.accumulo.tserver.compaction.MajorCompactionRequest;

@SuppressWarnings("removal")
public class TestCompactionStrategy extends CompactionStrategy {

  private String inputPrefix = "Z";
  private String dropPrefix = "Z";
  private boolean shouldCompact = false;

  @Override
  public void init(Map<String,String> options) {
    if (options.containsKey("inputPrefix"))
      inputPrefix = options.get("inputPrefix");
    if (options.containsKey("dropPrefix"))
      dropPrefix = options.get("dropPrefix");
    if (options.containsKey("shouldCompact"))
      shouldCompact = Boolean.parseBoolean(options.get("shouldCompact"));
  }

  @Override
  public boolean shouldCompact(MajorCompactionRequest request) {
    if (shouldCompact)
      return true;

    for (TabletFile file : request.getFiles().keySet()) {
      if (file.getFileName().startsWith(inputPrefix))
        return true;
      if (file.getFileName().startsWith(dropPrefix))
        return true;
    }

    return false;
  }

  @Override
  public CompactionPlan getCompactionPlan(MajorCompactionRequest request) {
    CompactionPlan plan = new CompactionPlan();

    for (StoredTabletFile file : request.getFiles().keySet()) {
      if (file.getFileName().startsWith(dropPrefix)) {
        plan.deleteFiles.add(file);
      } else if (file.getFileName().startsWith(inputPrefix)) {
        plan.inputFiles.add(file);
      }
    }

    return plan;
  }
}

