import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
 
public class Factorization {
    public static List<Integer> generateFactors(int n) {
        List<Integer> factors = new ArrayList<Integer>();
        factors.add(1);
        factors.add(n);
        for (int i = 2; i * i <= n; ++i) {
            if (n % i == 0) {
                factors.add(i);
                if (i * i!= n)
                    factors.add(n / i);
            }
        }
 
        Collections.sort(factors);
        return factors;
    }
 
    public static void main(String[] args) {
        int[] sampleNumbers = { 3135, 45, 60, 81 };
 
        for (int i = 0; i < sampleNumbers.length; ++i) {
            List<Integer> factors = generateFactors(sampleNumbers[i]);
            System.out.print("Factors of ");
            System.out.printf("%4d", sampleNumbers[i]);
            System.out.print(" are: ");
            for (int factor : factors) {
                System.out.print(factor + " ");
            }
            System.out.println();
        }
    }
}

public class Pi {
 
    public static void main(String[] args) {
        int[] throws = {1000, 10_000, 100_000, 1_000_000, 10_000_000};
        for (int n : throws) {
            System.out.printf("%8d samples: PI = %s%n", n, approx_pi(n));
        }
    }
 
    public static double approx_pi(int throws) {
        int times_inside = 0;
        for (int i = 0; i < throws; i++) {
            double x = Math.random();
            double y = Math.random();
            if (Math.hypot(x, y) <= 1.0) {
                times_inside++;
            }
        }
        return 4.0 * times_inside / throws;
    }
}

