        final int lengthOne = str1.length();
        System.out.println("Enter string two: ");

        String str2 = input.nextLine();
        final int lengthTwo = str2.length();

        if (str1.charAt(0) != str2.charAt(0)) {

            System.out.println(str1 + " and " + str2 + " have :(. ---> no common prefix <---");

        } else {
            int indexOfLCP = 0;
            for (int i = 0; i < (Math.max(lengthOne, lengthTwo)); i++) {

                if (str1.charAt(i) == str2.charAt(i)) {
                    indexOfLCP = i;
                } else {
                    break;
                }
            }
            System.out.print("The common prefix is: " + str1.substring(0, indexOfLCP + 1));

        }

        input.close();
    }

}

import com.rapidminer.example.Attribute;
import com.rapidminer.example.Example;
import com.rapidminer.example.ExampleSet;
import com.rapidminer.operator.OperatorDescription;
import com.rapidminer.operator.OperatorException;
import com.rapidminer.operator.ports.metadata.AttributeMetaData;
import com.rapidminer.operator.ports.metadata.ExampleSetMetaData;
import com.rapidminer.operator.preprocessing.AbstractValueProcessing;
import com.rapidminer.tools.Ontology;
import com.rapidminer.tools.math.container.Range;

/**
 * This operator simply replaces all values by their absolute respective value.
 *
 */
public class AbsoluteValueFilter extends AbstractValueProcessing {

    public AbsoluteValueFilter(OperatorDescription description) {
        super(description);
    }

    @Override
    public ExampleSetMetaData applyOnFilteredMetaData(ExampleSetMetaData metaData) {
        for (AttributeMetaData amd : metaData.getAllAttributes()) {
            if (amd.isNumerical() && !amd.isSpecial()) {
                Range range = amd.getValueRange();
                amd.setValueRange(new Range(0, Math.max(Math.abs(range.getLower()), Math.abs(range.getUpper()))),
                        amd.getValueSetRelation());
                amd.getMean().setUnkown();
            }
        }

        return metaData;
    }

    @Override
    public ExampleSet applyOnFiltered(ExampleSet exampleSet) throws OperatorException {
        for (Example example : exampleSet) {
            for (Attribute attribute : exampleSet.getAttributes()) {
                if (attribute.isNumerical()) {
                    double value = example.getValue(attribute);
                    value = Math.abs(value);
                    example.setValue(attribute, value);
                }
            }
        }
        return exampleSet;
    }

    @Override
    protected int[] getFilterValueTypes() {
        return new int[] { Ontology.NUMERICAL };
    }

    @Override
    public boolean writesIntoExistingData() {
        return true;
    }
}

import org.apache.calcite.sql.SqlIdentifier;
import org.apache.calcite.sql.parser.SqlParserPos;
import org.apache.calcite.util.Util;

import com.google.common.collect.ImmutableList;

import java.util.List;
import java.util.Objects;

/**
 * A generic implementation of {@link SqlMoniker}.
 */
public class SqlMonikerImpl implements SqlMoniker {
  //~ Instance fields --------------------------------------------------------

  private final ImmutableList<String> names;
  private final SqlMonikerType type;

  //~ Constructors -----------------------------------------------------------

  /**
   * Creates a moniker with an array of names.
   */
  public SqlMonikerImpl(List<String> names, SqlMonikerType type) {
    this.names = ImmutableList.copyOf(names);
    this.type = Objects.requireNonNull(type);
  }

  /**
   * Creates a moniker with a single name.
   */
  public SqlMonikerImpl(String name, SqlMonikerType type) {
    this(ImmutableList.of(name), type);
  }

  //~ Methods ----------------------------------------------------------------

  @Override public boolean equals(Object obj) {
    return this == obj
        || obj instanceof SqlMonikerImpl
        && type == ((SqlMonikerImpl) obj).type
        && names.equals(((SqlMonikerImpl) obj).names);
  }

  @Override public int hashCode() {
    return Objects.hash(type, names);
  }

  public SqlMonikerType getType() {
    return type;
  }

  public List<String> getFullyQualifiedNames() {
    return names;
  }

  public SqlIdentifier toIdentifier() {
    return new SqlIdentifier(names, SqlParserPos.ZERO);
  }

  public String toString() {
    return Util.sepList(names, ".");
  }

  public String id() {
    return type + "(" + this + ")";
  }
}

// End SqlMonikerImpl.java

