public String formatResults(double[] results, String shape) {
    StringBuilder sb = new StringBuilder();
    if (shape.equals("table")) {
        sb.append("|  Result   |\n");
        sb.append("|-----------|\n");
        for (double result : results) {
            sb.append(String.format("| %9.2f |\n", result));
        }
    } else if (shape.equals("list")) {
        sb.append("Results:\n");
        for (double result : results) {
            sb.append(String.format("- %.2f\n", result));
        }
    } else {
        sb.append("Invalid shape type.");
    }
    return sb.toString();
}

