    static class FastReader

    {

        BufferedReader br;

        StringTokenizer st;

        public FastReader()

        {

            br = new BufferedReader(new

                     InputStreamReader(System.in));

        }

        String next()

        {

            while (st == null || !st.hasMoreElements())

            {

                try

                {

                    st = new StringTokenizer(br.readLine());

                }

                catch (IOException  e)

                {

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }

        int nextInt()

        {

            return Integer.parseInt(next());

        }

        long nextLong()

        {

            return Long.parseLong(next());

        }

        double nextDouble()

        {

            return Double.parseDouble(next());

        }

        String nextLine()

        {

            String str = "";

            try

            {

                str = br.readLine();

            }

            catch (IOException e)

            {

                e.printStackTrace();

            }

            return str;

        }

    }

    public static void main(String[] args)

    {

        FastReader sc=new FastReader();

        int i,j=0;

        int t = sc.nextInt();

        while(t-->0)

        {

            int n = sc.nextInt();

            Integer a[]=new Integer[n];

            int c = 0;

            int ans = 0;

            for(i=0;i<n;i++)

            {

                a[i]=sc.nextInt();

                if(a[i]%2!=0)

                c++;

                }

            if(c>0)

            ans = n-c;

            else

            {

                boolean f =true;

                int k =0;

                while(f==true)

                {

                    k++;

                    for(i=0;i<n;i++)

                    {

                        if(a[i]%2!=0)

                        {

                            f=false;

                            break;

                        }

                        else

                        a[i]=a[i]/2;

                    }

                }

                ans=n-1+k-1;

            }

            System.out.println(ans);

        }

        }

}

public static SASLFailure parseSASLFailure(XmlPullParser parser) throws XmlPullParserException, IOException {
        final int initialDepth = parser.getDepth();
        String condition = null;
        Map<String, String> descriptiveTexts = null;
        outerloop: while (true) {
            int eventType = parser.next();
            switch (eventType) {
            case XmlPullParser.START_TAG:
                String name = parser.getName();
                if (name.equals("text")) {
                    descriptiveTexts = parseDescriptiveTexts(parser, descriptiveTexts);
                }
                else {
                    assert (condition == null);
                    condition = parser.getName();
                }
                break;
            case XmlPullParser.END_TAG:
                if (parser.getDepth() == initialDepth) {
                    break outerloop;
                }
                break;
            }
        }
        return new SASLFailure(condition, descriptiveTexts);
    }

import java.util.Scanner;

public class Processor {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.print("Enter the number of values: ");
        int len = in.nextInt();
        int[] nums = new int[len];

        System.out.print("Enter the values: ");
        for (int i = 0; i < len; i++) {
            nums[i] = in.nextInt();
        }
        if (isConsecutiveFour(nums)) {
            System.out.println("The list has consecutive fours.");
        } else {
            System.out.println("The list does not have consecutive fours.");
        }
    }

    public static boolean isConsecutiveFour(int[] values) {
        int lastNum = values[0];
        int count = 1;
        for (int j = 1; j < values.length; j++) {
            if (lastNum == values[j]) {
                count++;
            } else {
                lastNum = values[j];
                count = 1;
            }
            if (count == 4) {
                return true;
            }
        }
        return false;

    }

}

