public void removeBucket(String name) throws FileNotFoundException {
        Bucket bucket;
        synchronized (buckets) {
            if (!buckets.containsKey(name)) {
                throw new FileNotFoundException("No such bucket: "+ name);
            }
            bucket = buckets.remove(name);
        }
        CAPIServer capi = bucket.getCAPIServer();
        if (capi != null) {
            capi.shutdown();
        }
        BucketAdminServer adminServer = bucket.getAdminServer();
        if (adminServer != null) {
            adminServer.shutdown();
        }
        bucket.stop();
    }

private Operation range( CssFormatter formatter ) {
        type = LIST;
        double start = get( 0 ).doubleValue( formatter );
        double end;
        if( parameters.size() >= 2 ) {
            end = get( 1 ).doubleValue( formatter );
        } else {
            end = start;
            start = 1;
        }
        double step;
        if( parameters.size() >= 3 ) {
            step = get( 2 ).doubleValue( formatter );
        } else {
            step = 1;
        }
        String unit = get( 0 ).unit( formatter );
        Operation op = new Operation( this, ' ' );
        while( start <= end ) {
            op.addOperand( new ValueExpression( this, start + unit ) );
            start += step;
        }
        return op;
    }

