            System.out.printf("\nTotal salary for " + ASSOCIATE + " professors is $%.2f", totalSalaryAssociate);
            System.out.printf("\nTotal salary for " + FULL + " professors is $%.2f", totalSalaryFull);
            System.out.printf("\nTotal salary for ALL faculty is $%.2f", totalSalaryAll);

            // Averages
            System.out.printf("\nTotal average salary for " + ASSISTANT + " professors is $%.2f", average(countAssistant
                    , totalSalaryAssistant));
            System.out.printf("\nTotal average salary for " + ASSOCIATE + " professors is $%.2f", average(countAssociate
                    , totalSalaryAssociate));

import java.util.Arrays;
import java.util.function.Function;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class PartialApplication {
    public static void main(String[] args) {
        int[] xs = {0, 1, 2, 3};
        int[] ys = {2, 4, 6, 8};

        Function<int[], int[]> fsf1 = fs(f1);
        Function<int[], int[]> fsf2 = fs(f2);

        System.out.println("xs:");
        System.out.println("\tfsf1: " + Arrays.stream(fsf1.apply(xs)).boxed().collect(Collectors.toList()));
        System.out.println("\tfsf2: " + Arrays.stream(fsf2.apply(xs)).boxed().collect(Collectors.toList()));
        System.out.println("\nys:");
        System.out.println("\tfsf1: " + Arrays.stream(fsf1.apply(ys)).boxed().collect(Collectors.toList()));
        System.out.println("\tfsf2: " + Arrays.stream(fsf2.apply(ys)).boxed().collect(Collectors.toList()));
    }

    public static Function<int[], int[]> fs(Function<Integer, Integer> f) {
        return (int[] cont) -> {
            for (int i = 0; i < cont.length; i++) {
                cont[i] = f.apply(cont[i]);
            }
            return cont;
        };
    }

    public static Function<Integer, Integer> f1(Integer x) {
        return x * 2;
    }

    public static Function<Integer, Integer> f2(Integer x) {
        return x * x;
    }
}

