import java.util.Scanner;

public class JavaApplication3 {

    static Scanner scan;

    public static void main(String[] args) {

        scan = new Scanner(System.in);

        int n = scan.nextInt();

        int[] q = new int[n - 1];

        int upper = 0, qSum = 0;

        for (int i = 0; i < n - 1; i++) {

            q[i] = scan.nextInt();

            qSum += q[i];

            if (qSum > 0)

                upper++;

        }

        int[] p = new int[n];

        int[] sorted = new int[n];

        p[0] = n - upper;

        try {

            sorted[p[0] - 1] = p[0];

            for (int i = 1; i < n; i++) {

                p[i] = p[i - 1] + q[i - 1];

                if (sorted[p[i] - 1] != 0) {

                    throw new Exception();

                }

                sorted[p[i] - 1] = p[i];

            }

        } catch (Exception e) {

            System.out.println(-1);

            return;

        }

        for (int i = 0; i < n; i++) {

            System.out.print(p[i] + " ");

        }

    }

}

import com.google.gson.JsonDeserializationContext;
import com.google.gson.JsonDeserializer;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;

import java.lang.reflect.Type;

public class WayPointDeserializer implements JsonDeserializer<WayPoint> {

    private SoldierDeserializer soldierDeserializer;

    public WayPointDeserializer(SoldierDeserializer soldierDeserializer) {
        this.soldierDeserializer = soldierDeserializer;
    }

    @Override
    public WayPoint deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
        if (!json.isJsonObject()) {
            return null;
        }

        JsonObject jsonObject = json.getAsJsonObject();

        if (!jsonObject.has("tile") || jsonObject.get("tile").isJsonNull()) {
            return null;
        }

        if (soldierDeserializer.currentSoldier == null) {
            return null;
        }

        Tile tile = context.deserialize(jsonObject.get("tile"), Tile.class);

        WeightedPath path = null;
        if (jsonObject.has("path") && !jsonObject.get("path").isJsonNull()) {
            path = context.deserialize(jsonObject.get("path"), WeightedPath.class);
        }

        WayPoint wayPoint = new WayPoint(tile);
        wayPoint.setSoldier(soldierDeserializer.currentSoldier);
        wayPoint.setPath(path);

        if (jsonObject.has("aim") && !jsonObject.get("aim").isJsonNull()) {
            Tile aim = context.deserialize(jsonObject.get("aim"), Tile.class);
            wayPoint.setAim(aim);
        }

        if (jsonObject.has("wait") && !jsonObject.get("wait").isJsonNull()) {
            int wait = jsonObject.get("wait").getAsInt();
            wayPoint.setWait(wait);
        }

        return wayPoint;
    }
}

