@WebServlet("/BenchmarkTest08873")
public class BenchmarkTest08873 extends HttpServlet {

  protected void doGet(HttpServletRequest request, HttpServletResponse response)
      throws IOException {
    doPost(request, response);
  }

  protected void doPost(HttpServletRequest request, HttpServletResponse response)
      throws IOException {
    response.setContentType("text/html;charset=UTF-8");
    PrintWriter out = response.getWriter();

    Enumeration<String> headerNames = request.getHeaderNames();
    if (headerNames != null && headerNames.hasMoreElements()) {
      String param = headerNames.nextElement();
      String bar = (new Library()).doSomething(param);

      SecureRandom numGen = null;
      boolean randNumber = false;
      try {
        numGen = SecureRandom.getInstanceStrong();
        randNumber = numGen.nextBoolean();
      } catch (NoSuchAlgorithmException e) {
        out.println("Failed to generate secure random number: " + e.getMessage());
      }

      out.println("Randomness test executed.  Escaped header: " + bar);
    } else {
      out.println("No headers found in the request.");
    }
  }

  private static class Library {
    public String doSomething(String param) {
      return htmlEscape(param);
    }

    private String htmlEscape(String input) {
      return HtmlUtils.htmlEscape(input);
    }
  }
}

