import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Provider;
import org.springframework.beans.factory.annotation.Autowired;

public class SystemsBeanLoader {

  @Autowired private Provider<SystemsSystemBeanLoader> systemLoaderProvider;
  @Autowired private Provider<SystemsApplyerBeanLoader> applyerLoaderProvider;

  public SystemsBean load(GameBeanDAO dao) {
    SystemsBean systemsBean = new SystemsBean();
    systemsBean.setApplyers(loadApplyers(dao));
    systemsBean.setSystems(loadSystems(dao));
    return systemsBean;
  }

  private List<SystemsApplyerBean> loadApplyers(GameBeanDAO dao) {
    List<SystemsApplyerBean> applyers = new ArrayList<>();
    List<String> paths = dao.getList("applyers");
    if (paths != null) {
      for (String path : paths) {
        Path file = dao.getFile(path);
        Path parent = dao.getParent(file);
        applyers.add(loadApplyer(parent.resolve(file.getFileName())));
      }
    }
    return applyers;
  }

  private SystemsApplyerBean loadApplyer(Path path) {
    return applyerLoaderProvider.get().load(path);
  }

  private List<SystemsSystemBean> loadSystems(GameBeanDAO dao) {
    List<SystemsSystemBean> systems = new ArrayList<>();
    List<String> paths = dao.getList("systems");
    if (paths != null) {
      for (String path : paths) {
        Path file = dao.getFile(path);
        Path parent = dao.getParent(file);
        systems.add(loadSystem(parent.resolve(file.getFileName())));
      }
    }
    return systems;
  }

  private SystemsSystemBean loadSystem(Path path) {
    return systemLoaderProvider.get().load(path);
  }
}

class SystemsBean {
  private List<SystemsApplyerBean> applyers;
  private List<SystemsSystemBean> systems;

  public void setApplyers(List<SystemsApplyerBean> applyers) {
    this.applyers = applyers;
  }

  public void setSystems(List<SystemsSystemBean> systems) {
    this.systems = systems;
  }
}

