import java.util.Scanner;

public class ConvexPolygonArea {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter the number of points: ");
        int numberOfPoints = input.nextInt();

        double[][] points = new double[numberOfPoints][2];
        System.out.println("Enter the coordinates of the points:");
        for (int i = 0; i < numberOfPoints; i++) {
            points[i][0] = input.nextDouble();
            points[i][1] = input.nextDouble();
        }

        double area = getConvexPolygonArea(points);
        System.out.printf("The total area is %.3f\n", area);
    }

    public static double getConvexPolygonArea(double[][] points) {
        double area = 0;
        for (int i = 0; i < points.length; i++) {
            int j = (i + 1) % points.length;
            area += points[i][0] * points[j][1];
            area -= points[i][1] * points[j][0];
        }
        area /= 2.0;
        return Math.abs(area);
    }
}

import java.util.Random;
 
public class PrisonersAndDrawers {
 
    private static final Random RANDOM = new Random();
 
    // Uses 0-based numbering rather than 1-based numbering throughout.
    private static void doTrials(int trials, int np, String strategy) {
        int pardoned = 0;
        trial:
        for (int t = 0; t < trials; t++) {
            int[] drawers = new int[100];
            for (int i = 0; i < 100; i++) {
                drawers[i] = i;
            }
            shuffle(drawers);
            prisoner:
            for (int p = 0; p < np; p++) {
                if (strategy.equals("optimal")) {
                    int prev = p;
                    for (int d = 0; d < 50; d++) {
                        int this = drawers[prev];
                        if (this == p) {
                            continue prisoner;
                        }
                        prev = this;
                    }
                } else {
                    // Assumes a prisoner remembers previous drawers (s)he opened
                    // and chooses at random from the others.
                    boolean[] opened = new boolean[100];
                    for (int d = 0; d < 50; d++) {
                        int n;
                        do {
                            n = RANDOM.nextInt(100);
                        } while (opened[n]);
                        opened[n] = true;
                        if (drawers[n] == p) {
                            continue prisoner;
                        }
                    }
                }
                continue trial;
            }
            pardoned++;
        }
        double rf = (double) pardoned / trials * 100;
        System.out.printf("  strategy = %-7s  pardoned = %-6d relative frequency = %5.2f%%\n\n", strategy, pardoned, rf);
    }
 
    private static void shuffle(int[] drawers) {
        for (int i = 0; i < 100; i++) {
            int j = RANDOM.nextInt(100);
            int tmp = drawers[i];
            drawers[i] = drawers[j];
            drawers[j] = tmp;
        }
    }
 
    public static void main(String[] args) {
        int trials = 100000;
        for (int np : new int[]{10, 100}) {
            System.out.printf("Results from %d trials with %d prisoners:\n\n", trials, np);
            for (String strategy : new String[]{"random", "optimal"}) {
                doTrials(trials, np, strategy);
            }
        }
    }
}

