            if(c[i]<c[j]){

                lastInd = i;

                j = 0;

            }

            else if(c[i]==c[j]){

                j = (j+1)%(lastInd+1);

            }

            else break;

        }

        String s1 = s.substring(0, lastInd+1);

        StringBuilder sb = new StringBuilder(s1);

        sb.append(s1.repeat(k/s1.length()));

        pw.println(sb.substring(0, k));

        pw.flush();

        pw.close();

    }

    static class FS{

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer("");

        String next(){

            while(!st.hasMoreElements()){

                try{

                    st = new StringTokenizer(br.readLine());

                } catch(Exception ignored){

                }

            }

            return st.nextToken();

        }

        int[] nextArray(int n){

            int[] a = new int[n];

            for(int i = 0; i < n; i++){

                a[i] = nextInt();

            }

            return a;

        }

        long[] nextLongArray(int n){

            long[] a = new long[n];

            for(int i = 0; i < n; i++){

                a[i] = nextLong();

            }

            return a;

        }

        int nextInt(){

            return Integer.parseInt(next());

        }

        long nextLong(){

            return Long.parseLong(next());

        }

        double nextDouble(){

            return Double.parseDouble(next());

        }

    }

}

import javax.inject.Inject;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public abstract class BaseRepository<ID, T extends AggregateRoot<ID>> implements Repository<ID, T> {

    private static final int AGGREGATE_INDEX = 1;
    private static final int KEY_INDEX = 0;

    private Class<T> aggregateRootClass;
    private Class<ID> idClass;
    private SpecificationBuilder<T> specificationBuilder;

    @Inject
    public void setSpecificationBuilder(SpecificationBuilder<T> specificationBuilder) {
        this.specificationBuilder = specificationBuilder;
    }

    protected BaseRepository() {
        Type genericSuperclass = getClass().getGenericSuperclass();
        while (!(genericSuperclass instanceof ParameterizedType)) {
            genericSuperclass = ((Class<?>) genericSuperclass).getGenericSuperclass();
        }
        ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        if (actualTypeArguments[KEY_INDEX] instanceof Class) {
            this.idClass = (Class<ID>) actualTypeArguments[KEY_INDEX];
        } else {
            throw new IllegalArgumentException("Could not determine ID class");
        }

        if (actualTypeArguments[AGGREGATE_INDEX] instanceof Class) {
            this.aggregateRootClass = (Class<T>) actualTypeArguments[AGGREGATE_INDEX];
        } else {
            throw new IllegalArgumentException("Could not determine Aggregate Root class");
        }
    }

    protected BaseRepository(Class<T> aggregateRootClass, Class<ID> idClass) {
        this.aggregateRootClass = aggregateRootClass;
        this.idClass = idClass;
    }

    public Class<T> getAggregateRootClass() {
        return aggregateRootClass;
    }

    public Class<ID> getIdentifierClass() {
        return idClass;
    }

    public SpecificationBuilder<T> getSpecificationBuilder() {
        return specificationBuilder;
    }

    // Additional methods can be added here for common repository operations
    // such as save, delete, findById, etc., which can be overridden by subclasses.

    // Example method:
    public void save(T aggregateRoot) {
        // Implementation would depend on the storage technology
        throw new UnsupportedOperationException("Save operation not implemented");
    }

    // Example method:
    public void delete(ID id) {
        // Implementation would depend on the storage technology
        throw new UnsupportedOperationException("Delete operation not implemented");
    }

public class FuscSequence {
 
    public static void main(String[] args) {
        System.out.println("Show the first 61 fusc numbers (starting at zero) in a horizontal format");
        for ( int n = 0 ; n < 61 ; n++ ) {
            System.out.printf("%,d ", fusc[n]);
        }
 
        System.out.printf("%n%nShow the fusc number (and its index) whose length is greater than any previous fusc number length.%n");
        int start = 0;
        for (int i = 0 ; i <= 5 ; i++ ) {
            int val = i != 0 ? (int) Math.pow(10, i) : -1;
            for ( int j = start ; j < FUSC_MAX ; j++ ) {
                if ( fusc[j] > val ) {
                    System.out.printf("fusc[%,d] = %,d%n", j, fusc[j] );
                    start = j;
                    break;
                }
            }
        }
    }
 
    private static final int FUSC_MAX = 30000000;
    private static int[] fusc = new int[FUSC_MAX];
 
    static {
        fusc[0] = 0;
        fusc[1] = 1;
        for ( int n = 2 ; n < FUSC_MAX ; n++ ) {
            fusc[n] = (n % 2 == 0 ? fusc[n/2] : fusc[(n-1)/2] + fusc[(n+1)/2]);
        }
    }
}

import java.util.Arrays;
 
public class PrintTriangle {
    public static void printTriangle(int n) {
        // degenerate cases
        if (n <= 0) {
            return;
        }
        System.out.println(1);
        if (n == 1) {
            return;
        }
        // iterate over rows, zero based
        int[] a = new int[(n+1)/2];
        a[0] = 1;
        for (int row = 1, middle = 0; row < n; row++) {
            // generate new row
            boolean even = (row&1) == 0;
            if (even) {
                a[middle+1] = a[middle] * 2;
            }
            for (int i = middle; i > 0; i--) {
                a[i] += a[i-1];
            }
            // print row
            for (int i = 0; i <= middle; i++) {
                System.out.print(a[i] + " ");
            }
            if (even) {
                middle++;
            }
            for (int i = middle; i >= 0; i--) {
                System.out.print(a[i] + " ");
            }
            System.out.println("");
        }
    }
 
    public static void main(String[] args) {
        printTriangle(4);
    }
}

