public void resetCursor(BTree btree, boolean forwards) {
    if (forwards) {
        Node node = btree.getRoot();
        while (node != null && !node.isLeaf()) {
            node = node.getChild(0);
        }
        if (node != null) {
            currentPosition = 0;
            currentLeaf = node;
        } else {
            currentPosition = -1;
            currentLeaf = null;
        }
    } else {
        Node node = btree.getRoot();
        while (node != null && !node.isLeaf()) {
            node = node.getChild(node.getDegree() - 1);
        }
        if (node != null) {
            currentPosition = node.size() - 1;
            currentLeaf = node;
        } else {
            currentPosition = -1;
            currentLeaf = null;
        }
    }
}

/**
 * Evaluates whether one integer feature is greater than another within a given context.
 *
 * @param <T> The type of the context.
 */
public class GreaterThanIntegerOperator<T> extends AbstractCachableFeature<T, Boolean> implements BooleanFeature<T> {

    private IntegerFeature<T> operand1;
    private IntegerFeature<T> operand2;

    public GreaterThanIntegerOperator(IntegerFeature<T> operand1, IntegerFeature<T> operand2) {
        this.operand1 = operand1;
        this.operand2 = operand2;
    }

    @Override
    protected FeatureResult<Boolean> checkInternal(T context, RuntimeEnvironment runtime) {
        Integer value1 = operand1.evaluate(context, runtime).getValue();
        Integer value2 = operand2.evaluate(context, runtime).getValue();

        if (value1 == null || value2 == null) {
            return FeatureResult.nullResult();
        }

        return FeatureResult.from(value1 > value2);
    }

    @Override
    public void addDynamicSourceCode(DynamicSourceCodeBuilder builder) {
        builder.startMethod("boolean", "evaluateGreaterThan", operand1.getValueType().getSimpleName() + " value1, " + operand2.getValueType().getSimpleName() + " value2");
        builder.addLine("return value1 > value2;");
        builder.endMethod();

        operand1.addDynamicSourceCode(builder);
        operand2.addDynamicSourceCode(builder);
    }

    public IntegerFeature<T> getOperand1() {
        return operand1;
    }

    public void setOperand1(IntegerFeature<T> operand1) {
        this.operand1 = operand1;
    }

    public IntegerFeature<T> getOperand2() {
        return operand2;
    }

    public void setOperand2(IntegerFeature<T> operand2) {
        this.operand2 = operand2;
    }

    @Override
    public Class<Boolean> getValueType() {
        return Boolean.class;
    }
}

import java.util.*;

interface Generator<T> {
    T next();
}

class FilmGenerator implements Generator<String> {
    private static final String[] FILMNAMES = {"Inception", "Interstellar", "The Matrix", "Blade Runner", "The Dark Knight"};
    private static int cursor = 0;
    private static int count = 0;

    public FilmGenerator() {
        count++;
    }

    @Override
    public String next() {
        if (cursor >= FILMNAMES.length) {
            cursor = 0;
        }
        return FILMNAMES[cursor++];
    }

    public static int getCount() {
        return count;
    }
}

public class FilmCollectionDemo {
    public static void main(String[] args) {
        FilmGenerator generator = new FilmGenerator();

        // Populate an array
        String[] filmArray = new String[5];
        for (int i = 0; i < filmArray.length; i++) {
            filmArray[i] = generator.next();
        }
        System.out.println("Array: " + Arrays.toString(filmArray));

        // Populate an ArrayList
        List<String> filmList = new ArrayList<>();
        for (int i = 0; i < 5; i++) {
            filmList.add(generator.next());
        }
        System.out.println("ArrayList: " + filmList);

        // Populate a LinkedList
        List<String> filmLinkedList = new LinkedList<>();
        for (int i = 0; i < 5; i++) {
            filmLinkedList.add(generator.next());
        }
        System.out.println("LinkedList: " + filmLinkedList);

        // Populate a HashSet
        Set<String> filmSet = new HashSet<>();
        for (int i = 0; i < 5; i++) {
            filmSet.add(generator.next());
        }
        System.out.println("HashSet: " + filmSet);

        System.out.println("Total generator instances: " + FilmGenerator.getCount());
    }
}

