import java.util.List;
 
public class Manager {
    private static class Range {
        int start;
        int end;
        boolean print;
 
        public Range(int s, int e, boolean p) {
            start = s;
            end = e;
            print = p;
        }
    }
 
    public static void main(String[] args) {
        List<Range> rgs = List.of(
            new Range(2, 1000, true),
            new Range(1000, 4000, true),
            new Range(2, 10_000, false),
            new Range(2, 100_000, false),
            new Range(2, 1_000_000, false),
            new Range(2, 10_000_000, false),
            new Range(2, 100_000_000, false),
            new Range(2, 1_000_000_000, false)
        );
        for (Range rg : rgs) {
            if (rg.start == 2) {
                System.out.printf("eban numbers up to and including %d\n", rg.end);
            } else {
                System.out.printf("eban numbers between %d and %d\n", rg.start, rg.end);
            }
            int count = 0;
            for (int i = rg.start; i <= rg.end; ++i) {
                int b = i / 1_000_000_000;
                int r = i % 1_000_000_000;
                int m = r / 1_000_000;
                r = i % 1_000_000;
                int t = r / 1_000;
                r %= 1_000;
                if (m >= 30 && m <= 66) m %= 10;
                if (t >= 30 && t <= 66) t %= 10;
                if (r >= 30 && r <= 66) r %= 10;
                if (b == 0 || b == 2 || b == 4 || b == 6) {
                    if (m == 0 || m == 2 || m == 4 || m == 6) {
                        if (t == 0 || t == 2 || t == 4 || t == 6) {
                            if (r == 0 || r == 2 || r == 4 || r == 6) {
                                if (rg.print) System.out.printf("%d ", i);
                                count++;
                            }
                        }
                    }
                }
            }
            if (rg.print) {
                System.out.println();
            }
            System.out.printf("count = %d\n\n", count);
        }
    }
}

import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
 
public class DiningPhilosophers {
 
    public static void main(String[] args) {
        new DiningPhilosophers().dine();
    }
 
    private static final String[] PHILOSOPHER_NAMES = { "Aristotle", "Kant", "Spinoza", "Marx", "Russel" };
 
    private static final Random RANDOM = new Random(507129);
 
    private final Philosopher[] philosophers = new Philosopher[PHILOSOPHER_NAMES.length];
 
    private final Lock[] forks = new Lock[PHILOSOPHER_NAMES.length];
 
    public DiningPhilosophers() {
        for (int i = 0; i < forks.length; i++) {
            forks[i] = new ReentrantLock();
        }
 
        for (int i = 0; i < philosophers.length; i++) {
            philosophers[i] = new Philosopher(PHILOSOPHER_NAMES[i], forks[i], forks[(i + 1) % forks.length]);
        }
    }
 
    public void dine() {
        for (Philosopher philosopher : philosophers) {
            philosopher.start();
        }
 
        try {
            Thread.sleep(100000);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
 
        for (Philosopher philosopher : philosophers) {
            philosopher.setRunning(false);
        }
 
        System.out.println("Now we're finishing.");
    }
 
    private static class Philosopher extends Thread {
 
        private final String name;
 
        private final Lock forkOnLeft;
 
        private final Lock forkOnRight;
 
        private boolean running = true;
 
        public Philosopher(String name, Lock forkOnLeft, Lock forkOnRight) {
            this.name = name;
            this.forkOnLeft = forkOnLeft;
            this.forkOnRight = forkOnRight;
        }
 
        public void run() {
            while (running) {
                // Philosopher is thinking (but really is sleeping).
                try {
