import org.apache.phoenix.compile.MutationPlan;
import org.apache.phoenix.compile.StatementContext;
import org.apache.phoenix.execute.MetaDataClient;
import org.apache.phoenix.jdbc.PhoenixConnection;
import org.apache.phoenix.jdbc.PhoenixStatement;
import org.apache.phoenix.parse.DropSequenceStatement;
import org.apache.phoenix.schema.ParameterMetaData;

public class DropSequenceCompiler {

    private final DropSequenceStatement statement;
    private final PhoenixConnection connection;
    private final StatementContext context;

    public DropSequenceCompiler(DropSequenceStatement statement, PhoenixStatement phoenixStatement) {
        this.statement = statement;
        this.connection = phoenixStatement.getConnection();
        this.context = new StatementContext(phoenixStatement);
    }

    public MutationPlan compile() {
        return new MutationPlan() {
            private final MetaDataClient client = new MetaDataClient(connection);

            @Override
            public void execute() throws Exception {
                client.dropSequence(statement.getSequenceName());
            }

            @Override
            public String getExplainPlan() {
                return "DROP SEQUENCE " + statement.getSequenceName();
            }

            @Override
            public StatementContext getContext() {
                return context;
            }

            @Override
            public PhoenixConnection getConnection() {
                return connection;
            }

            @Override
            public ParameterMetaData getParameterMetaData() {
                return ParameterMetaData.EMPTY_PARAMETER_META_DATA;
            }
        };
    }
}

public class Shape {
    public int hammingDistance(int x, int y) {
        int t = x ^ y, ans = 0;
        while(t>0){
            if((t & 0x1) == 1){
                ans++;
            }
            t = t>>1;
        }
        return ans;
    }
}

public String rankTeams(String[] votes) {
        Map<Character, Integer> map = new HashMap<>();
        for (String vote : votes) {
            for (char c : vote.toCharArray()) {
                map.put(c, map.getOrDefault(c, 0) + 1);
            }
        }
        PriorityQueue<Character> pq = new PriorityQueue<>(new Comparator<Character>() {
            @Override
            public int compare(Character o1, Character o2) {
                int cmp = map.get(o2) - map.get(o1);
                if (cmp != 0) return cmp;
                return o1 - o2;
            }
        });
        pq.addAll(map.keySet());
        StringBuilder sb = new StringBuilder();
        while (!pq.isEmpty()) {
            sb.append(pq.poll());
        }
        return sb.toString();
    }
}

