public class Soundex {
    public static void main(String[] args) {
        String soundex = soundex("Euler");
        System.out.println(soundex);
    }

    public static String soundex(String s) {
        String a = s.toLowerCase();
        char f = a.charAt(0);
        String r = "";
        Map<Character, Integer> codes = new HashMap<Character, Integer>();
        codes.put('a', 0);
        codes.put('e', 0);
        codes.put('i', 0);
        codes.put('o', 0);
        codes.put('u', 0);
        codes.put('b', 1);
        codes.put('f', 1);
        codes.put('p', 1);
        codes.put('v', 1);
        codes.put('c', 2);
        codes.put('g', 2);
        codes.put('j', 2);
        codes.put('k', 2);
        codes.put('q', 2);
        codes.put('s', 2);
        codes.put('x', 2);
        codes.put('z', 2);
        codes.put('d', 3);
        codes.put('t', 3);
        codes.put('l', 4);
        codes.put('m', 5);
        codes.put('n', 5);
        codes.put('r', 6);

        r = f + "";
        for (int i = 1; i < a.length(); i++) {
            char v = a.charAt(i);
            if (i == 1) {
                if (codes.get(v)!= codes.get(f)) {
                    r += codes.get(v);
                }
            } else {
                if (codes.get(v)!= codes.get(a.charAt(i - 1))) {
                    r += codes.get(v);
                }
            }
        }

        return (r + "000").substring(0, 4).toUpperCase();
    }
}

