public class RSSAdapter extends RecyclerView.Adapter<RSSAdapter.ArticleViewHolder> {

    private List<FeedItems> rssFI;
    private Document _document;
    private Context context;

    public RSSAdapter(Context context) {
        this.context = context;
        this.rssFI = new ArrayList<>();
    }

    public void setXMLDocument(Document document) {
        this._document = document;
        parseXMLData();
        notifyDataSetChanged();
    }

    private void parseXMLData() {
        if (_document != null) {
            NodeList items = _document.getElementsByTagName("item");
            for (int i = 0; i < items.getLength(); i++) {
                String title = items.item(i).getChildNodes().item(1).getTextContent(); // Assuming title is the second child
                String description = items.item(i).getChildNodes().item(2).getTextContent(); // Assuming description is the third child
                String link = items.item(i).getChildNodes().item(3).getTextContent(); // Assuming link is the fourth child
                String pubDate = items.item(i).getChildNodes().item(4).getTextContent(); // Assuming pubDate is the fifth child
                rssFI.add(new FeedItems(title, description, link, pubDate));
            }
            logRecordCount();
        }
    }

    private void logRecordCount() {
        System.out.println("Number of records: " + rssFI.size());
    }

    @Override
    public int getItemCount() {
        return rssFI.size();
    }

    @Override
    public ArticleViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(parent.getContext()).inflate(R.layout.item_feed, parent, false);
        return new ArticleViewHolder(view);
    }

    @Override
    public void onBindViewHolder(ArticleViewHolder holder, int position) {
        FeedItems item = rssFI.get(position);
        holder.titleTextView.setText(item.getTitle());
        holder.descriptionTextView.setText(item.getDescription());
        holder.linkTextView.setText(item.getLink());
        holder.pubDateTextView.setText(item.getPubDate());
    }

    public static class ArticleViewHolder extends RecyclerView.ViewHolder {
        public TextView titleTextView;
        public TextView descriptionTextView;

