public static Experiment readExperiment(final File file) throws IOException {
    // Check if the file is null
    if (file == null) {
        throw new IllegalArgumentException("File must not be null");
    }

    // Check if the file exists and is readable
    if (!file.exists() || !file.canRead()) {
        throw new FileNotFoundException("File does not exist or is not readable: " + file.getAbsolutePath());
    }

    // Initialize the experiment object
    Experiment experiment = new Experiment();

    // Use a BufferedReader to read the file line by line
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            // Process each line to populate the experiment object
            // This is a placeholder for the actual parsing logic
            // For example, you might split the line by commas and set fields on the experiment object
            String[] parts = line.split(",");
            if (parts.length >= 3) {
                experiment.setName(parts[0]);
                experiment.setDate(parts[1]);
                experiment.setResults(parts[2]);
            }
        }
    }

    // Return the populated experiment object
    return experiment;
}

