public class LoopHandler implements Runnable {
    private static int startLoop = 0;
    private static int endLoop = 100;
    private static int curLoop = startLoop;
    private static final int numThreads = 4;
    private static Thread[] lookupThreads = new Thread[numThreads];

    private static synchronized LoopRange loopGetRange() {
        if (curLoop >= endLoop) {
            return null;
        }
        int start = curLoop;
        int chunkSize = (endLoop - startLoop) / numThreads;
        int end = Math.min(start + chunkSize, endLoop);
        curLoop = end;
        return new LoopRange(start, end);
    }

    private void loopDoRange(int start, int end) {
        // Placeholder for custom loop processing logic
        for (int i = start; i < end; i++) {
            System.out.println("Processing iteration: " + i + " by " + Thread.currentThread().getName());
        }
    }

    @Override
    public void run() {
        LoopRange range;
        while ((range = loopGetRange()) != null) {
            loopDoRange(range.start, range.end);
        }
    }

    public void loopProcess() {
        for (int i = 0; i < numThreads; i++) {
            lookupThreads[i] = new Thread(new LoopHandler());
            lookupThreads[i].start();
        }

        for (Thread thread : lookupThreads) {
            try {
                thread.join();
            } catch (InterruptedException e) {
                System.err.println("Thread interrupted: " + e.getMessage());
            }
        }
    }

    private static class LoopRange {
        int start;
        int end;

        LoopRange(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    public static void main(String[] args) {
        LoopHandler handler = new LoopHandler();
        handler.loopProcess();
        System.out.println("All threads completed processing.");
    }
}

import java.nio.Buffer;

import java.util.*;

import java.io.*;

public class Sorter {

    static int N = 200010;

    static int[] tr = new int[N];

    static int idx = 1;

    public static void main(String[] args) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int n = Integer.parseInt(br.readLine());

        String[] ss;

        int[][] arr = new int[n][3];

//        TreeSet<Integer> set = new TreeSet<>();

        List<Integer> list = new ArrayList<>();

        Map<Integer, Integer> map = new HashMap<>();

        for (int i = 0; i < n; i ++) {

            ss = br.readLine().split(" ");

            arr[i][0] = Integer.parseInt(ss[0]);

            arr[i][1] = Integer.parseInt(ss[1]);

            arr[i][2] = i;

            list.add(arr[i][0]);

        }

        Collections.sort(list);

        for (int key : list) {

            map.put(key, idx ++);

        }

        Arrays.sort(arr, (a, b) -> (a[1] - b[1]));

        int[] ans = new int[n];

        for (int i = 0; i < n; i ++) {

            int left = map.get(arr[i][0]);

            ans[arr[i][2]] = i - query(left - 1);

            add(left, 1);

        }

        for (int i : ans) System.out.println(i);

    }

    private static void add(int x, int t) {

        for (int i = x; i < idx; i += i & (-i)) tr[i] += t;

    }

    private static int query(int x) {

        int res = 0;

        for (int i = x; i > 0; i -= i & (-i)) res += tr[i];

        return res;

    }

}

