import org.apache.accumulo.core.data.Key;

import java.nio.ByteBuffer;
import java.util.Arrays;

public class AccumuloRowId {

    private byte[] indexId;
    private byte[] dataId;
    private byte[] adapterId;
    private int numberOfDuplicates;
    private byte[] rowId;

    public AccumuloRowId(Key key) {
        this(key.getRow().getBytes());
    }

    public AccumuloRowId(byte[] accumuloRowId) {
        ByteBuffer buffer = ByteBuffer.wrap(accumuloRowId);
        int adapterIdLength = buffer.getInt(accumuloRowId.length - 12);
        int dataIdLength = buffer.getInt(accumuloRowId.length - 8);
        numberOfDuplicates = buffer.getInt(accumuloRowId.length - 4);

        int indexIdLength = accumuloRowId.length - 12 - adapterIdLength - dataIdLength;

        indexId = new byte[indexIdLength];
        adapterId = new byte[adapterIdLength];
        dataId = new byte[dataIdLength];

        buffer.position(0);
        buffer.get(indexId, 0, indexIdLength);
        buffer.get(adapterId, indexIdLength, adapterIdLength);
        buffer.get(dataId, indexIdLength + adapterIdLength, dataIdLength);

        this.rowId = accumuloRowId;
    }

    public AccumuloRowId(byte[] indexId, byte[] dataId, byte[] adapterId, int numberOfDuplicates) {
        this.indexId = indexId;
        this.dataId = dataId;
        this.adapterId = adapterId;
        this.numberOfDuplicates = numberOfDuplicates;

        ByteBuffer buffer = ByteBuffer.allocate(indexId.length + adapterId.length + dataId.length + 12);
        buffer.put(indexId);
        buffer.put(adapterId);
        buffer.put(dataId);
        buffer.putInt(adapterId.length);
        buffer.putInt(dataId.length);
        buffer.putInt(numberOfDuplicates);

        this.rowId = buffer.array();
    }

    public byte[] getRowId() {
        return rowId;
    }

    public byte[] getIndexId() {
        return indexId;
    }

    public byte[] getDataId() {
        return dataId;
    }

    public byte[] getAdapterId() {
        return adapterId;
    }

    public int getNumberOfDuplicates() {
        return numberOfDuplicates;
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Stack {
    public List<Integer> getAllElements(TreeNode root1, TreeNode root2) {
        List<Integer> res = new ArrayList<>();
        dfs(root1, res);
        dfs(root2, res);

        Collections.sort(res);

        return res;
    }

    private void dfs(TreeNode t, List<Integer> res){
        if(t == null){
            return;
        }

        res.add(t.val);
        dfs(t.left, res);
        dfs(t.right, res);
    }
}

public class HataFirlatma {

    public static void main(String[] args) {

        try {
            // bol fonksiyonunu cagir ve sonucunu yazdir
            bol(10, 0);
        } catch (ArithmeticException e) {
            // Sifira bolme istisnasini yakala ve mesaj yazdir
            System.out.println("Hata: Sifira bolme islemi yapilamaz!");
            System.out.println("Hata mesaji: " + e.getMessage());
        }

        // Ek testler
        try {
            bol(20, 5); // Gecerli bir bolme islemi
            bol(15, -3); // Negatif sayi ile bolme islemi
        } catch (ArithmeticException e) {
            System.out.println("Hata olustu: " + e.getMessage());
        }

        // Alternatif bir islem ornegi
        System.out.println("Toplama islemi: " + topla(10, 5));
    }

    /**
     * Iki sayiyi bolen bir metot
     * @param x Bolunen
     * @param y Bolen
     * @throws ArithmeticException Eger y sifirsa
     */
    public static void bol(int x, int y) throws ArithmeticException {
        if (y == 0) {
            // Eger bolen sifir ise ArithmeticException firlat
            throw new ArithmeticException("Sifira bolme hatasi!");
        }
        int z = x / y; // Bolme islemini yap
        System.out.println("Bolme Islemi: " + z); // Sonucu yazdir
    }

    /**
     * Iki sayinin toplamini bulan bir metot
     * @param a Birinci sayi
     * @param b Ikinci sayi
     * @return a ve b toplami
     */
    public static int topla(int a, int b) {
        return a + b; // Iki sayiyi topla ve sonucu dondur
    }
}

