public class Fractions {
    public static int indexOf(int n, int[] s) {
        for (int i = 0; i < s.length; i++) {
            if (n == s[i]) {
                return i;
            }
        }
        return -1;
    }
 
    public static boolean getDigits(int n, int le, int[] digits) {
        int mn = n;
        int mle = le;
        while (mn > 0) {
            int r = mn % 10;
            if (r == 0 || indexOf(r, digits) >= 0) {
                return false;
            }
            mle--;
            digits[mle] = r;
            mn /= 10;
        }
        return true;
    }
 
