    public static int removeDigit(int[] digits, int le, int idx) {
        int sum = 0;
        int pow = pows[le - 2];
        for (int i = 0; i < le; i++) {
            if (i == idx) {
                continue;
            }
            sum += digits[i] * pow;
            pow /= 10;
        }
        return sum;
    }
 
