import java.util.Arrays;
import java.util.Comparator;
import java.util.Set;
import java.util.TreeSet;
 
public class DisjointSort {
    public static void disjointSort(int[] array, int[] indices) {
        int[] sorted = indices.clone();
        Arrays.sort(sorted);
        Set<int[]> swaps = new TreeSet<>(Comparator.comparingInt(a -> a[0]));
        for (int i = 0; i < indices.length; i++) {
            int a = indices[i];
            int b = sorted[i];
            if (a > b) {
                swaps.add(new int[]{b, a});
            } else {
                swaps.add(new int[]{a, b});
            }
        }
        for (int[] swap : swaps) {
            int a = swap[0];
            int b = swap[1];
            int temp = array[a];
            array[a] = array[b];
            array[b] = temp;
        }
    }
 
    public static void main(String[] args) {
        int[] array = {7, 6, 5, 4, 3, 2, 1, 0};
        int[] indices = {6, 1, 7};
        disjointSort(array, indices);
        System.out.println(Arrays.toString(array));
    }
}

