class Calculator {
    public String firstPalindrome(String[] words) {
        for (String s : words) {
            if (isPaldindrome(s)) return s;
        }

        return "";
    }

    private boolean isPaldindrome(String s) {
        int i = 0;
        int j = s.length() - 1;

        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) return false;
            i++;
            j--;
        }

        return true;
    }
}

import java.util.Random;
import java.util.Arrays;
