import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public class Weasel {
    private static final String target = "METHINKS IT IS LIKE A WEASEL";
    private static final String charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
    private static final double minmutaterate = 0.09;
    private static final int C = 100;
    private static final int perfectfitness = target.length();
    private static final Random random = new Random();

    private static int fitness(String trial) {
        return (int) IntStream.range(0, target.length())
               .filter(i -> trial.charAt(i) == target.charAt(i))
               .count();
    }

    private static double mutaterate() {
        return 1 - ((perfectfitness - fitness(parent)) / (double) perfectfitness * (1 - minmutaterate));
    }

    private static String mutate(String parent, double rate) {
        return IntStream.range(0, parent.length())
               .mapToObj(i -> random.nextDouble() <= rate? parent.charAt(i) : charset.charAt(random.nextInt(charset.length())))
               .map(c -> Character.toString(c))
               .collect(Collectors.joining());
    }

    private static void que() {
        System.out.printf("#%-4d, fitness: %4.1f%%, '%s'\n", iterations, fitness(parent) * 100.0 / perfectfitness, parent);
    }

    private static List<String> mate(String a, String b) {
        int place = 0;
        if (random.nextInt(10) < 7) {
            place = random.nextInt(target.length());
        }
        return Arrays.asList(a, b, a.substring(0, place) + b.substring(place), b.substring(0, place) + a.substring(place));
    }

    private static String parent;
    private static int iterations = 0;
    private static int center = C / 2;

    public static void main(String[] args) {
        parent = IntStream.range(0, target.length())
               .mapToObj(i -> charset.charAt(random.nextInt(charset.length())))
               .map(c -> Character.toString(c))
               .collect(Collectors.joining());
        while (!parent.equals(target)) {
            double rate = mutaterate();
            iterations++;
            if (iterations % 100 == 0) {
                que();
            }
            List<String> copies = Stream.concat(
                    IntStream.range(0, C).mapToObj(i -> mutate(parent, rate)),
                    Stream.of(parent))
                   .collect(Collectors.toList());

