public class Helper {
    public static int minimumDeleteSum(String word1, String word2) {
        int[][] arrSum = new int[word1.length() + 1][word2.length() + 1];
        for (int[] ar : arrSum) {
            Arrays.fill(ar, -1);
        }
        return fun(word1, word2, 0, 0, arrSum);
    }

    private static int fun(String word1, String word2, int i, int j, int[][] arrSum) {
        if (arrSum[i][j] != -1) return arrSum[i][j];

        if(i==word1.length() && j==word2.length()){
            arrSum[i][j]=0;
            return 0;
        }
        int ans=0;
        if(i!=word1.length()){
            if(j!=word2.length())
            ans = Math.min(   arrSum[i+1][j] + word2.charAt(j), fun(word1, word2, i+1, j, arrSum)  +
                  arrSum[i][j+1] + word1.charAt(i)
