    public class MaximalSumOfALenglish {
        public int MaximalSum(List<Integer> list){
            int length = list.size();
            int maxSum = Integer.MIN_VALUE;
            int total = 0;
            for(int i = 0; i < length; ++i) {
                if(total+list.get(i) < list.get(i))
                    total = list.get(i);
                else total += list.get(i);
                if(maxSum < total)
                    maxSum = total;
            }
            return maxSum;
        }
    }

    public int MaximalSum(List<Integer> list){
        Integer maxSum = Integer.MIN_VALUE;
        Integer val = list.get(0);
        maxSum = Math.max(maxSum, val);
        Integer tmp;
        for(Integer i : list.subList(1, list.size())) {
            tmp = val+i;
            maxSum = val >= 0 ? Math.max(maxSum, tmp) : Math.max(maxSum, Math.max(val, tmp));
            val = tmp;
        }
        return maxSum;
    }

