import java.util.Arrays;
import java.util.List;

public class MedianTwoSortedArray {
    public void rearrangeString(String s) {
        char[] output = s.toCharArray();

        int i, j;
        while (true) {
            boolean enterLoop = true;
            for (i = 0, j = 1; i < output.length; i++, j++) {
                if (output[i] == output[j]) {
                    if (!removeBites(output, i))
                        enterLoop = false;
                } else if (j < output.length)
                    continue;
                else if (!removeBites(output, i))
                    enterLoop = false;

                if (!enterLoop)
                    break;
            }
            if (!enterLoop)
                break;

        }
    }

    private boolean removeBites(char[] output, int i) {
        if (output[i] != output[i + 1]) {
            output[i] = 'x';
            output[i + 1] = 'x';
            return true;
        } else
            return false;
    }
}
