public class NumberOfGoodPairs {
    public static int numberOfUniqueGoodPairs(int[] nums) {
        int n = nums.length;

        int uniques = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (nums[i] == nums[j]) {
                    uniques++;
                    break;
                }
            }
        }

        return uniques;
    }

