public interface Emptiable {
    boolean isEmpty();
}

class Range implements Emptiable {
    private final double lower;
    private final double upper;

    public Range(double lower, double upper) {
        this.lower = lower;
        this.upper = upper;
    }

    @Override
    public boolean isEmpty() {
        // A Range is considered empty if the lower and upper bounds are equal.
        return lower == upper;
    }
}

class Metadata implements Emptiable {
    private final String title;
    private final String description;

    public Metadata(String title, String description) {
        this.title = title;
        this.description = description;
    }

    @Override
    public boolean isEmpty() {
        // Metadata is empty when both title and description are null or blank.
        return (title == null || title.trim().isEmpty())
                && (description == null || description.trim().isEmpty());
    }
}

class Envelope implements Emptiable {
    private final double area;

    public Envelope(double area) {
        this.area = area;
    }

    @Override
    public boolean isEmpty() {
        // An Envelope is considered empty if its area is zero.
        return area == 0.0;
    }
}

public class EmptiableDemo {
    public static void main(String[] args) {
        Emptiable range = new Range(5.0, 5.0);
        Emptiable metadata = new Metadata("  ", "");
        Emptiable envelope = new Envelope(0.0);

        printEmptiableStatus("Range", range);
        printEmptiableStatus("Metadata", metadata);
        printEmptiableStatus("Envelope", envelope);
    }

    private static void printEmptiableStatus(String name, Emptiable obj) {
        System.out.println(name + " is " + (obj.isEmpty() ? "empty" : "not empty"));
    }
}

class Product {
    public int countConsistentStrings(String allowed, String[] words) {
        int[] f = distinct(allowed);
        int re = 0;
        for(String w : words)
        {
            int[] g = distinct(w);
            if(same(f, g)) re++;
        }
        return re;
    }

    boolean same(int[] f, int[] g)
    {
        for(int i = 0; i < 26; i++)
        {
            if(g[i] > f[i]) return false;
        }
        return true;
    }

    int[] distinct(String str)
    {
        int[] f = new int[26];
        for(char c : str.toCharArray())
        {
            int idx = c - 'a';
            if(f[idx] == 0) f[idx]++;
        }
        return f;
    }
}

