public String addSpaces(String s, int[] spaces) {
    StringBuilder result = new StringBuilder();
    int spaceIndex = 0;

    for (int i = 0; i < s.length(); i++) {
        if (spaceIndex < spaces.length && i == spaces[spaceIndex]) {
            result.append(' ');
            spaceIndex++;
        }
        result.append(s.charAt(i));
    }

    return result.toString();
}

import java.math.BigInteger;
import java.util.Scanner;

public class Chernick {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        BigInteger z = new BigInteger("0");
        for (int n = 3; n <= 10; n++) {
            long multiplier = (n > 4)? (1 << (n - 4)) : 1;
            if (n > 5)
                multiplier *= 5;
            for (long k = 1; ; k++) {
                long m = k * multiplier;
                if (is_chernick(n, m, z)) {
                    System.out.println("a(" + n + ") has m = " + m);
                    break;
                }
            }
        }
    }

    public static boolean primality_pretest(long k) {
        if (k % 3 == 0 || k % 5 == 0 || k % 7 == 0 || k % 11 == 0 || k % 13 == 0 || k % 17 == 0 || k % 19 == 0 || k % 23 == 0)
            return (k <= 23);
        return true;
    }

    public static boolean probprime(long k, BigInteger n) {
        n = BigInteger.valueOf(k);
        return n.isProbablePrime(0);
    }

    public static boolean is_chernick(int n, long m, BigInteger z) {
        long t = 9 * m;
        if (primality_pretest(6 * m + 1) == false)
            return false;
        if (primality_pretest(12 * m + 1) == false)
            return false;
        for (int i = 1; i <= n - 2; i++)
            if (primality_pretest((t << i) + 1) == false)
                return false;
        if (probprime(6 * m + 1, z) == false)
            return false;
        if (probprime(12 * m + 1, z) == false)
            return false;
        for (int i = 1; i <= n - 2; i++)
            if (probprime((t << i) + 1, z) == false)
                return false;
        return true;
    }
}

