import java.util.HashMap;
import java.util.Map;
import java.util.stream.IntStream;

public class YinYang {
    public static void main(String[] args) {
        System.out.println(yinyang(3));
    }

    public static String yinyang(int n) {
        int[] radii = new int[]{1, 3, 6};
        int[][] ranges = IntStream.of(radii).map(i -> i * n).toArray();
        int[][][] squares = IntStream.of(ranges).map(r -> {
            int[] rnge = IntStream.rangeClosed(-r, r).toArray();
            return IntStream.of(rnge).map(x -> IntStream.of(rnge).map(y -> new int[]{x, y}).toArray()).toArray();
        }).toArray(int[][][]::new);
        int[][][] circles = IntStream.of(squares).map(sqrpoints -> {
            int radius = sqrpoints.length;
            return IntStream.of(sqrpoints).map(sqrpoints1 -> {
                return IntStream.of(sqrpoints1).filter(point -> Math.hypot(point[0], point[1]) <= radius).toArray();
            }).toArray(int[][]::new);
        }).toArray(int[][][]::new);
        Map<int[], String> m = new HashMap<>();
        IntStream.of(squares[squares.length - 1]).forEach(sqrpoints -> {
            IntStream.of(sqrpoints).forEach(point -> {
                m.put(point, " ");
            });
        });
        IntStream.of(circles[circles.length - 1]).forEach(sqrpoints -> {
            IntStream.of(sqrpoints).forEach(point -> {
                m.put(point, "*");
            });
        });
        IntStream.of(circles[circles.length - 1]).forEach(sqrpoints -> {
            IntStream.of(sqrpoints).filter(point -> point[0] > 0).forEach(point -> {
                m.put(point, "·");
            });
        });
        IntStream.of(circles[circles.length - 2]).forEach(sqrpoints -> {
            IntStream.of(sqrpoints).forEach(point -> {
                m.put(new int[]{point[0], point[1] + 3 * n}, "*");
                m.put(new int[]{point[0], point[1] - 3 * n}, "·");
            });
        });
        IntStream.of(circles[circles.length - 3]).forEach(sqrpoints -> {
            IntStream.of(sqrpoints).forEach(point -> {
                m.put(new int[]{point[0], point[1] + 3 * n}, "·");
                m.put(new int[]{point[0], point[1] - 3 * n}, "*");
            });
        });
        return IntStream.of(ranges[ranges.length - 1]).mapToObj(y -> {
            return IntStream.of(ranges[ranges.length - 1]).mapToObj(x -> {
                return m.get(new int[]{-x, y});
            }).reduce("", (s, s2) -> s + s2);
        }).reduce("", (s, s2) -> s + "\n" + s2);
    }
}

import java.util.HashMap;
import java.util.Map;
 
public class MutualRecursion {
 
    public static void main(final String args[]) {
        int max = 20;
        System.out.printf("First %d values of the Female sequence:  %n", max);
        for (int i = 0; i < max; i++) {
            System.out.printf("  f(%d) = %d%n", i, f(i));
        }
        System.out.printf("First %d values of the Male sequence:  %n", max);
        for (int i = 0; i < 20; i++) {
            System.out.printf("  m(%d) = %d%n", i, m(i));
        }
    }
 
    private static Map<Integer,Integer> F_MAP = new HashMap<>();
 
    private static int f(final int n) {
        if ( F_MAP.containsKey(n) ) {
            return F_MAP.get(n);
        }
        int fn = n == 0 ? 1 : n - m(f(n - 1));
        F_MAP.put(n, fn);
        return fn;
    }
 
    private static Map<Integer,Integer> M_MAP = new HashMap<>();
 
    private static int m(final int n) {
        if ( M_MAP.containsKey(n) ) {
            return M_MAP.get(n);
        }
        int mn = n == 0 ? 0 : n - f(m(n - 1));
        M_MAP.put(n, mn);
        return mn;
    }
 
 
}

class Product {
    public int longestMountain(int[] A) {
        int max = 0;
        for (int i = 1; i < A.length - 1; i++) {
            if (A[i] > A[i - 1] && A[i] > A[i + 1]) {
                int left = i;
                while (left > 0 && A[left] > A[left - 1]) left--;
                int right = i;
                while (right < A.length - 1 && A[right] > A[right + 1]) right++;
                max = Math.max(max, right - left + 1);
            }
        }
        return max;
    }
}

