@Path("v3/protection-groups")
public class V3_getProtectionGrpList extends getData {

    @GET
    @Produces({MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML,
               MediaType.TEXT_HTML, "text/csv"})
    public Object constructResponse(@QueryParam("format") String format) {
        UserProvisioningManager upm = getUpm();
        List<ProtectionGroup> protectionGrpLst = upm.getAllProtectionGroups();

        if(protectionGrpLst.isEmpty()) {
            return formatResponse(format, "No protection groups configured");
        }

        List<List<Object>> data = new ArrayList<>();
        String[] columns = {"Group Name", "Description", "Dataset ID"};

        for(ProtectionGroup group : protectionGrpLst) {
            List<ProtectionElement> elements =
                upm.getProtectionElementsByGrpId(group.getGroupId());

            for(ProtectionElement element : elements) {
                List<Object> row = new ArrayList<>();
                row.add(group.getGroupName());
                row.add(group.getDescription());
                row.add(element.getProtectedResourceId());
                data.add(row);
            }
        }

        if(data.isEmpty()) {
            return formatResponse(format, "Protection groups contain no accessible elements");
        }

        return formatResponse(format, columns, data);
    }

    public static class ProtectionGroup {
        private String groupId;
        private String groupName;
        private String description;

        public String getGroupId() { return groupId; }
        public String getGroupName() { return groupName; }
        public String getDescription() { return description; }
    }

