import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class Zumkeller {
 
    public static void main(String[] args) {
        System.out.println("220 Zumkeller numbers:");
        printZumkellers(220);
        System.out.println("\n\n40 odd Zumkeller numbers:");
        printZumkellers(40, true);
    }
 
    public static boolean isZumkeller(int n) {
        List<Integer> d = divisors(n);
        int s = d.stream().mapToInt(Integer::intValue).sum();
        if (s % 2 == 0 && d.stream().mapToInt(Integer::intValue).max().getAsInt() <= s/2) {
            for (int x = 1; x < 1 << d.size(); x++) {
                if (subset(d, x).stream().mapToInt(Integer::intValue).sum() == s/2) {
                    return true;
                }
            }
        }
        return false;
    }
 
    public static void printZumkellers(int N, boolean oddonly) {
        int nprinted = 0;
        for (int n = 1; n < 100000; n++) {
            if ((oddonly == false || n % 2 == 1) && isZumkeller(n)) {
                System.out.printf("%8d", n);
                nprinted++;
                if (nprinted % 10 == 0) {
                    System.out.println();
                }
                if (nprinted >= N) {
                    return;
                }
            }
        }
    }
 
    public static List<Integer> divisors(int n) {
        return IntStream.range(1, n + 1).filter(i -> n % i == 0).boxed().collect(Collectors.toList());
    }
 
    public static List<Integer> subset(List<Integer> d, int x) {
        List<Integer> s = new ArrayList<>();
        for (int i = 0; i < d.size(); i++) {
            if ((x & (1 << i))!= 0) {
                s.add(d.get(i));
            }
        }
        return s;
    }
}

