import java.net.Inet4Address;
import java.net.UnknownHostException;
 
public class Service {
 
    public static String canonical_cidr(String cidr) {
        String[] split = cidr.split("/");
        if (split.length == 2) {
            try {
                Inet4Address addr = (Inet4Address) Inet4Address.getByName(split[0]);
                int mask = Integer.parseInt(split[1]);
                int bitmask = 0xff_ff_ff_ff << (32 - mask);
                addr = (Inet4Address) Inet4Address.getByName(addr.getAddress() & bitmask);
                return String.format("%s/%d", addr, mask);
            } catch (UnknownHostException e) {
                return cidr;
            }
        } else {
            return cidr;
        }
    }
 
    public static void main(String[] args) {
        System.out.println(canonical_cidr("127.1.2.3/24"));
    }
}

