/// @brief using cpp binary_search() optimized way
vector<int> get_max_vector1(vector<int> number){
  sort(number.begin(), number.end(), greater<int>());
  int currNum;
  for(int i = 0; i < number.size(); i++){
    currNum = number[i];
    for(int j = i + 1; j < number.size(); j++){
      int nextNum = number[j];
      if(currNum > 0){
        int prod = currNum * nextNum;
        if(!binary_search(number.begin(), number.begin() + j, prod)){
          break;
        }
      }
    }
  }
  return number;
}

