/// @brief get the answer as a string
string remove_leading_zeros(string str)
{
    int len = 0;
    int i = 0;
    while (str[i] == '0' && i < str.length())
    {
        i++;
    }
    if (i == str.length())
    {
        return "0";
    }
    string ans;
    bool sb = false;
    // check for minus which is different than subtract
    if (i != 0 && str[i] == '-')
    {
        sb = false;
        len = (int)str.length() - i;
    }
    else if (str[i] == '-')
    {
        len = (int)str.length() - i;
        sb = true;
    }
    else
    {
        len = (int)str.length() - i;
        sb = 0;
    }

    for (int j = 0; j < len; j++)
    {
        if (str[i + j] != '0')
        {
            ans = ans + str[i + j];
        }
    }

    if (sb)
        ans = '-' + ans;

    return ans;
}

