public class PrimeNumberCount {
    public static void main(String[] args) {
        int count = 0;
        for (int i = 2; i < 10000; i++) {
            if (isPrime(i)) {
                count++;
            }
        }
        System.out.println("The number of prime numbers less than 10000 is " + count);
    }

    public static boolean isPrime(int number) {
        for (int divisor = 2; divisor <= number / 2; divisor++) {
            if (number % divisor == 0) {
                return false; // number is not a prime
            }
        }
        return true; // number is prime
    }
}

import org.apache.camel.CamelContext;
import org.apache.camel.builder.RouteBuilder;
import org.apache.camel.impl.DefaultCamelContext;
import org.apache.camel.test.junit4.CamelTestSupport;
import org.junit.Test;
import org.eclipse.jetty.server.Server;
import org.eclipse.jetty.servlet.ServletContextHandler;

public class HttpFilterCamelHeadersTest extends CamelTestSupport {

    private static final int PORT = 8080;
    private Server server;

    @Override
    protected RouteBuilder createRouteBuilder() {
        return new RouteBuilder() {
            @Override
            public void configure() {
                from("jetty:http://localhost:" + PORT + "/hello")
                    .bean(MyFooBean.class, "hello")
                    .removeHeaders("Camel*");
            }
        };
    }

    @Override
    protected void doPostSetup() throws Exception {
        server = new Server(PORT);
        ServletContextHandler context = new ServletContextHandler(ServletContextHandler.SESSIONS);
        context.setContextPath("/");
        server.setHandler(context);
        server.start();
    }

    @Override
    protected void doPostTearDown() throws Exception {
        server.stop();
    }

    @Test
    public void testFilterHeaders() throws Exception {
        String response = template.requestBody("http://localhost:" + PORT + "/hello?name=John", null, String.class);

        assertEquals("Hello, John", response);
        assertNull(getMockEndpoint("mock:result").getExchanges().get(0).getIn().getHeader("CamelHttpResponseCode"));
    }

    public static class MyFooBean {
        public String hello(String name) {
            return "Hello, " + name;
        }
    }

    public static void main(String[] args) throws Exception {
        CamelContext context = new DefaultCamelContext();
        context.addRoutes(new HttpFilterCamelHeadersTest().createRouteBuilder());
        context.start();

        // Keep the server running
        Thread.sleep(Long.MAX_VALUE);
    }
}

private void insertionSort(int left, int right) {
        for (int p = left + 1; p <= right; p++) {
            byte[] tmpRange = ranges[p];
            String tmpFilename = filenames[p];
            int j;
            for (j = p; j > left && KeyUtils.compareKey(tmpRange, ranges[j - 1]) < 0; j--) {
                ranges[j] = ranges[j - 1];
                filenames[j] = filenames[j - 1];
            }
            ranges[j] = tmpRange;
            filenames[j] = tmpFilename;
        }
    }

import java.util.Arrays;

public class Stack {

    public static void main(String[] args) {
        int[] deck = makeDeck();
        int picks = 0;
        int sum = 0;
        while (sum != 24) {
            picks++;
            sum = randomDraw4(deck);
            System.out.println("Pick #" + picks);
            System.out.println("Drew 4 cards and their sum was " + sum);
        }
        System.out.println("Drew cards " + picks + " times to yield " + sum);
    }

    private static int randomDraw4(int[] deck) {
        int card1 = deck[(int) (Math.random() * 51)]; //array of 52 cards has indexes 0 to 51
        int card2 = deck[(int) (Math.random() * 51)];
        int card3 = deck[(int) (Math.random() * 51)];
        int card4 = deck[(int) (Math.random() * 51)];

        return (card1 + card2 + card3 + card4);
    }

    private static int[] makeDeck() {
        int[] deck = new int[52];
        int cardNum = 1;
        for (int i = 0; i < deck.length; i++) {
            deck[i] = cardNum;
            if (cardNum == 13) {
                cardNum = 1;
                continue;
            }
            cardNum++;

        }
        return deck;
    }

}

import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.parser.DefaultJSONParser;
import com.alibaba.fastjson.serializer.SerializeWriter;
import java.util.concurrent.atomic.AtomicLongArray;

public class AtomicLongArrayCodec {

    private static final AtomicLongArrayCodec instance = new AtomicLongArrayCodec();

    private AtomicLongArrayCodec() {}

    public static AtomicLongArrayCodec getInstance() {
        return instance;
    }

    public void write(AtomicLongArray array, SerializeWriter out) {
        if (array == null) {
            out.write("null");
            return;
        }

        out.write('[');
        for (int i = 0; i < array.length(); i++) {
            if (i != 0) {
                out.write(',');
            }
            out.writeLong(array.get(i));
        }
        out.write(']');
    }

    public AtomicLongArray deserialize(DefaultJSONParser parser) {
        Object token = parser.getToken();
        if (token == null || "null".equals(token)) {
            return null;
        }

        if (!(token instanceof JSONArray)) {
            throw new IllegalArgumentException("Expected a JSONArray, but got " + token);
        }

        JSONArray jsonArray = (JSONArray) token;
        AtomicLongArray atomicLongArray = new AtomicLongArray(jsonArray.size());

        for (int i = 0; i < jsonArray.size(); i++) {
            atomicLongArray.set(i, jsonArray.getLongValue(i));
        }
        return atomicLongArray;
    }

    public Object getFastMatchToken() {
        return JSONArray.class;
    }

    public static void main(String[] args) {
        AtomicLongArray atomicArray = new AtomicLongArray(new long[]{1L, 2L, 3L});

        SerializeWriter writer = new SerializeWriter();
        AtomicLongArrayCodec codec = AtomicLongArrayCodec.getInstance();

        // Serialize
        codec.write(atomicArray, writer);
        System.out.println("Serialized output: " + writer.toString());

        // Deserialize
        DefaultJSONParser parser = new DefaultJSONParser(writer.toString());
        AtomicLongArray deserializedArray = codec.deserialize(parser);

        System.out.print("Deserialized output: ");
        for (int i = 0; i < deserializedArray.length(); i++) {
            System.out.print(deserializedArray.get(i) + " ");
        }
    }
}

class Vector {
    public long[] unmarkedSumArray(int[] nums, int[][] queries) {
        int n = nums.length;
        PriorityQueue<Pair> q = new PriorityQueue<>();
        long ans = 0;

        for(int i = 0; i<n; i++) {
            q.add(new Pair(nums[i], i));
            ans+=nums[i];
        }
        int mark[] = new int[n];
        long res[] = new long[queries.length];
        for(int i = 0; i<queries.length; i++) {
            int index = queries[i][0];
            int k = queries[i][1];
            if(mark[index] == 0) {
                ans-=nums[index];
                mark[index] = 1;
            }
            int val = nums[index];
            while(k > 0 && !q.isEmpty()) {
                Pair e = q.poll();
                if(mark[e.y] != 0)continue;
                k--;
                ans-=e.x;
                mark[e.y] = 1;
            }
            res[i] = ans;
        }
        return res;
    }

    static class Pair implements Comparable<Pair> {
        int x, y;

        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Pair o) {
            if(x == o.x)return Integer.compare(this.y, o.y);
            return Integer.compare(this.x, o.x);
        }

