import org.wandora.application.Wandora;
import org.wandora.application.WandoraTool;
import org.wandora.application.contexts.Context;
import org.wandora.application.gui.UIBox;
import org.wandora.utils.Logger;

import java.util.ArrayList;
import java.util.List;

public class EuropeanaExtractor extends WandoraTool {

    private static final long serialVersionUID = 1L;
    private EuropeanaExtractorUI ui;

    @Override
    public void execute(Wandora wandora, Context context) {
        try {
            if (ui == null) {
                initGUI();
            }
            if (wasAccepted()) {
                List<EuropeanaSubExtractor> extractors = getExtractors();
                for (EuropeanaSubExtractor extractor : extractors) {
                    try {
                        log("Starting extraction with " + extractor.getName());
                        extractor.execute(wandora, context);
                        log("Completed extraction with " + extractor.getName());
                    } catch (Exception e) {
                        singleLog("Error during extraction with " + extractor.getName(), e);
                    }
                }
                setState(WAIT);
            } else {
                setState(CANCEL);
            }
        } catch (Exception e) {
            singleLog("Error in EuropeanaExtractor", e);
            setState(CANCEL);
        }
    }

    private void initGUI() {
        ui = new EuropeanaExtractorUI();
        ui.init();
    }

    private boolean wasAccepted() {
        return UIBox.showDialog(ui, "Configure Europeana Extraction") == UIBox.ACCEPT;
    }

    private List<EuropeanaSubExtractor> getExtractors() {
        List<EuropeanaSubExtractor> extractors = new ArrayList<>();
        // Assuming UI provides a method to get selected extractors
        extractors.addAll(ui.getSelectedExtractors());
        return extractors;
    }

    private void log(String message) {
        Logger.log(message);
    }

    private void singleLog(String message, Exception e) {
        Logger.log(message + ": " + e.getMessage());
    }

    @Override
    public String getName() {
        return "Europeana Extractor";
    }

    @Override
    public String getDescription() {
        return "A tool for extracting data from the Europeana API based on user-configured settings.";
    }
}

