def partitionLabels(s: str) -> List[int]:
    last_occurrence = defaultdict(int)
    for i, c in enumerate(s):
        last_occurrence[c] = i

    j = 0
    result = []
    for i, c in enumerate(s):
        j = max(j, last_occurrence[c])
        if i == j:
            result.append(1)
        else:
            result[-1] += 1

    return result

private static Type mapTypeParameters(Type toMapType, Type typeAndParams)
    {
        if (isMissingTypeParameters(typeAndParams))
        {
            return erase(toMapType);
        }
        else
        {
            VarMap varMap = new VarMap();
            Type handlingTypeAndParams = typeAndParams;
            while (handlingTypeAndParams instanceof ParameterizedType)
            {
                ParameterizedType pType = (ParameterizedType) handlingTypeAndParams;
                Class<?> clazz = (Class<?>) pType.getRawType();

                varMap.addAll(clazz.getTypeParameters(), pType.getActualTypeArguments());
                handlingTypeAndParams = pType.getOwnerType();
            }
            return varMap.map(toMapType);
        }
    }

class Account {
    Map<Integer,List<Integer>> tree;
    int[] s;
    int[] nums;
    int[] tmp;
    public int componentValue(int[] nums, int[][] edges) {
        int sum=0;
        this.nums=nums;
        int n=nums.length;
        int ma=0;
        for(int i=0;i<n;i++){
            sum+=nums[i];
            ma=Math.max(ma,nums[i]);
        }
        int m=edges.length;
        tree=new HashMap<>();
        for(int[] edge:edges){
            tree.computeIfAbsent(edge[0],k->new ArrayList<>()).add(edge[1]);
            tree.computeIfAbsent(edge[1],k->new ArrayList<>()).add(edge[0]);
        }
        s=new int[n];
        tmp=new int[n];
        dfs(0,-1);
        int ans=1;
        for(int i=ma;i<=sum;i++){
            if(sum%i==0){
                if(ok(i,sum/i)){
                    ans=sum/i-1;

                    break;
                }
            }
        }
        return ans;
    }

    private void dfs(int i,int fa){
        s[i]+=nums[i];
        List<Integer> childs=tree.get(i);
        if(childs==null)return;
        for(Integer child:childs){
            if(child!=fa){
                dfs(child,i);
                  s[i]+=s[child];
            }
        }
    }

      private int dfs1(int i,int fa,int sum){

        List<Integer> childs=tree.get(i);
        if(childs==null){
            if(s[i]==sum){
                return 1;
            }else{
                return 0;
            }
        }
        int ret=0;
        for(Integer child:childs){
            if(child!=fa){
                int t=dfs1(child,i,sum);
                ret+=t;
            }
        }
        if(ret*sum+sum==s[i]){
            ret++;
        }
        return ret;
    }

    private boolean ok(int sum,int cnt){
        int t=dfs1(0,-1,sum);
        return t==cnt;
    }

}

