                if ( arr1[0]==0)

                    ans++;

                else {

                    if (arr1[1]==1){

                        ans++;

                        arr1[1]=0;

                    }

                }

            }

            for ( int i=1; i<n-1; i++){

                if ( arr2[i]==1){

                    if ( arr1[i]==0)

                        ans++;

                    else{

                        if ( arr1[i-1]==1 || arr1[i+1]==1)

                            ans++;

                        if ( arr1[i-1]==1)

                            arr1[i-1]=0;

                        else if ( arr1[i+1]==1)

                            arr1[i+1]=0;

                    }

                }

            }

            if ( arr2[n-1]==1){

                if ( arr1[n-1]==0)

                    ans++;

                else {

                    if ( arr1[n-2]==1)

                        ans++;

                }

            }

            System.out.println(ans);

        }

    }

}

import java.io.InputStreamReader;
import java.util.Arrays;

public class Builder {
    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int numOfTestcases = Integer.parseInt(reader.readLine());
        for (int i = 0; i < numOfTestcases; i++) {
            System.out.println(maxMoves(reader.readLine()));
        }
    }

    /**
     * Returns the maximum number of moves you can perform on a given string $s$
     *
     * @param s String to analyse
     *
     * @return The maximum number of moves you can perform on a given string $s$
     */
    public static int maxMoves(String s) {
        int openParens = 0;
        int openAngleBrackets = 0;
        char[] stringArray = s.toCharArray();
        int[] openParenHistory = new int[stringArray.length + 1];
        int[] openBracketsHistory = new int[stringArray.length + 1];

        Arrays.fill(openParenHistory, 0);
        Arrays.fill(openBracketsHistory, 0);

        for (int numMoved = 0; numMoved < stringArray.length; numMoved++) {
            if (stringArray[numMoved] == '(') {
                openParens++;
            } else if (stringArray[numMoved] == ')') {
                openParens--;
            } else if (stringArray[numMoved] == '[') {
                openAngleBrackets++;
            } else if (stringArray[numMoved] == ']') {
                openAngleBrackets--;
            }

            openParenHistory[numMoved + 1] = openParens;
            openBracketsHistory[numMoved + 1] = openAngleBrackets;
        }

        int maxNumMoved = 0;

        for (int numMoved = 0; numMoved < stringArray.length; numMoved++) {
            for (int rearrangeNum = numMoved; rearrangeNum < stringArray.length; rearrangeNum++) {
                int diffParen = openParenHistory[rearrangeNum + 1] - openParenHistory[numMoved];
                int diffBracket = openBracketsHistory[rearrangeNum + 1] - openBracketsHistory[numMoved];

                if (diffParen == 0 && diffBracket == 0) {
                    maxNumMoved = Math.max(maxNumMoved, rearrangeNum - numMoved + 1);
                }
            }
        }

        return max

