import java.io.*;
import java.util.*;

public class Shape {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int testCases = Integer.parseInt(reader.readLine());
        StringBuilder output = new StringBuilder();

        for (int t = 0; t < testCases; t++) {
            int heroCount = Integer.parseInt(reader.readLine());
            int[] levels = Arrays.stream(reader.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
            Arrays.sort(levels);
            int possibleWinners = 1;
            int minLevel = levels[0];

            for (int i = 1; i < heroCount; i++) {
                if (levels[i] == minLevel) {
                    possibleWinners++;
                } else {
                    possibleWinners = 1;
                    minLevel = levels[i];
                }
            }
            output.append(possibleWinners).append("\n");
        }
        System.out.println(output);
    }
}

