import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.input.MouseButton;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.stage.Stage;

public class AddRemovePoints extends Application {

    private Pane pane;

    @Override
    public void start(Stage primaryStage) {
        pane = new Pane();
        Scene scene = new Scene(pane, 400, 400);

        // Add event listeners to pane
        pane.setOnMouseClicked(event -> {
            if (event.getButton() == MouseButton.PRIMARY) {
                // Create point on left-click
                double x = event.getX();
                double y = event.getY();
                Circle point = new Circle(x, y, 5.0, Color.RED);
                pane.getChildren().add(point);
            } else if (event.getButton() == MouseButton.SECONDARY) {
                // Remove point on right-click
                for (int i = 0; i < pane.getChildren().size(); i++) {
                    Circle point = (Circle) pane.getChildren().get(i);
                    if (point.contains(event.getX(), event.getY())) {
                        pane.getChildren().remove(point);
                        break;
                    }
                }
            }
        });

        primaryStage.setScene(scene);
        primaryStage.setTitle("Add/Remove Points");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.scene.text.Text;
import javafx.stage.Stage;

public class Checker extends Application {
    static final double WIDTH = 400;
    static final double HEIGHT = 400;
    static final double RADIUS = 15;

    @Override
    public void start(Stage primaryStage) {
        Pane pane = new Pane();
        double x1 = Math.random() * (WIDTH - 15);
        double y1 = Math.random() * (HEIGHT - 15);
        double x2 = Math.random() * (WIDTH - 15);
        double y2 = Math.random() * (HEIGHT - 15);

        Circle c1 = new Circle(x1, y1, RADIUS);
        Circle c2 = new Circle(x2, y2, RADIUS);
        c1.setFill(Color.WHITE);
        c1.setStroke(Color.BLACK);
        c2.setFill(Color.WHITE);
        c2.setStroke(Color.BLACK);

        Text text1 = new Text(x1, y1, "1");
        Text text2 = new Text(x2, y2, "2");

        Line line = drawConnectionLine(x1, y1, x2, y2, RADIUS);

        pane.getChildren().addAll(c1, c2, line, text1, text2);

        Scene scene = new Scene(pane, WIDTH, HEIGHT);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private Line drawConnectionLine(
            double x1, double y1, double x2, double y2, double radius) {
        double d = Math.sqrt((y2 - y1) * (y2 - y1) + (x2 - x1) * (x2 - x1));
        int x11 = (int) (x1 - radius * (x1 - x2) / d);
        int y11 = (int) (y1 - radius * (y1 - y2) / d);
        int x21 = (int) (x2 + radius * (x1 - x2) / d);
        int y21 = (int) (y2 + radius * (y1 - y2) / d);
        return new Line(x11, y11, x21, y21);
    }

    public static void main(String[] args) {
        Application.launch(args);
    }
}

private String buildRequestParams(Map<String, String> requestParameters) throws FMSException {
    StringBuilder queryParams = new StringBuilder();
    try {
        for (Map.Entry<String, String> entry : requestParameters.entrySet()) {
            if (queryParams.length() > 0) {
                queryParams.append("&");
            }
            queryParams.append(URLEncoder.encode(entry.getKey(), "UTF-8"));
            queryParams.append("=");
            queryParams.append(URLEncoder.encode(entry.getValue(), "UTF-8"));
        }
    } catch (UnsupportedEncodingException e) {
        throw new FMSException("Error encoding request parameters", e);
    }
    return queryParams.toString();
}

