import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class PoliceFireSanitation {
 
    public static void main(String[] args) {
        List<String> list = new ArrayList<>();
        list.add("Police");
        list.add("Fire");
        list.add("Sanitation");
        List<List<String>> permutations = permutations(list);
        System.out.println(String.format("%3s %6s %4s %10s", " ", "Police", "Fire", "Sanitation"));
        int c = 1;
        for (List<String> permutation : permutations) {
            int p = Integer.parseInt(permutation.get(0));
            int f = Integer.parseInt(permutation.get(1));
            int s = Integer.parseInt(permutation.get(2));
            if (p + s + f == 12 && p % 2 == 0) {
                System.out.println(String.format("%3d %6d %4d %10d", c, p, f, s));
                c++;
            }
        }
    }
 
    public static <T> List<List<T>> permutations(List<T> list) {
        if (list.size() == 1) {
            List<List<T>> result = new ArrayList<>();
            result.add(list);
            return result;
        }
        List<List<T>> result = new ArrayList<>();
        for (int i = 0; i < list.size(); i++) {
            T head = list.get(i);
            List<T> tail = new ArrayList<>(list);
            tail.remove(i);
            List<List<T>> permutations = permutations(tail);
            for (List<T> permutation : permutations) {
                List<T> newList = new ArrayList<>();
                newList.add(head);
                newList.addAll(permutation);
                result.add(newList);
            }
        }
        return result;
    }
}

import java.util.Queue;
import java.util.LinkedList;
 
public class QueueDemo {
    public static void main(String[] args) {
        // Create a queue and "push" items into it
        Queue<Integer> queue = new LinkedList<Integer>();
        queue.add(1);
        queue.add(3);
        queue.add(5);
 
        // "Pop" items from the queue in FIFO order
        System.out.println(queue.remove()); // 1
        System.out.println(queue.remove()); // 3
        System.out.println(queue.remove()); // 5
 
        // To tell if the queue is empty, we check the count
        boolean empty = queue.isEmpty();
        System.out.println(empty); // "True"
 
        // If we try to pop from an empty queue, an exception
        // is thrown.
        try {
            queue.remove();
        } catch (Exception exception) {
            System.out.println(exception.getMessage()); // "Queue empty."
        }
    }
}

