class Graph {
    public int minimizedMaximum(int n, int[] quantities) {
        int lo = 1;
        int hi = 100_000;
        while (lo < hi) {
            int m = lo + (hi - lo) / 2;
            if (check(m, n, quantities)) {
                hi = m;
            } else {
                lo = m + 1;
            }
        }
        return check(lo, n, quantities) ? lo : lo - 1;
    }

    private boolean check(int m, long n, int[] quantities) {
        for (int i = 0; i < quantities.length; i++) {
            int t = quantities[i] % m == 0 ? quantities[i] / m : quantities[i] / m + 1;
            n -= t;
        }
        return n >= 0;
    }
}

