        CamelContext context = context();
        Component component = context.getComponent("elasticsearch-rest");
        ComponentVerifierExtension verifier = component.getExtension(ComponentVerifierExtension.class).orElseThrow(() -> new IllegalArgumentException("ComponentVerifierExtension not available"));

