import java.util.*;
import java.io.*;

class Calculator {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int[] f = new int[n];
        for (int i = 0; i < n; i++) {
            f[i] = in.nextInt();
        }

        Map<Integer, Integer> hMap = new HashMap<>();
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (!hMap.containsKey(f[i])) {
                hMap.put(f[i], ++m);
            }
        }

        int[] g = new int[n];
        for (int i = 0; i < n; i++) {
            g[i] = f[i];
        }

        int[] h = new int[m + 1];
        for (int i = 1; i <= m; i++) {
            h[i] = i;
        }

        boolean valid = true;
        for (int i = 0; i < n; i++) {
            if (h[g[i]] != f[i]) {
                valid = false;
                break;
            }
        }

        if (!valid) {
            out.println(-1);
        } else {
            out.println(m);
            out.println(Arrays.toString(g));
            out.println(Arrays.toString(h));
        }

        out.flush();
    }
}

