public static double[] evaluatePerformance(Tagger tagger, EvaluationData evaluationData) {
    double[] performance = new double[2];
    int totalErrors = 0;
    int totalItems = 0;
    int totalSequences = 0;
    int sequenceErrors = 0;
    for (Sequence sequence : evaluationData.getSequences()) {
        totalSequences++;
        List<Item> items = sequence.getItems();
        totalItems += items.size();
        for (Item item : items) {
            String goldLabel = item.getLabel();
            String predictedLabel = tagger.tag(item.getFeatures());
            if (!goldLabel.equals(predictedLabel)) {
                totalErrors++;
                sequenceErrors++;
            }
        }
    }
    performance[0] = (double) totalErrors / totalItems;
    performance[1] = (double) sequenceErrors / totalSequences;
    return performance;
}

