import java.util.Arrays;

class Counter {
    private int[][] workers;
    private int[][] bikes;
    private int memo[][];

    private int backtrack(int workerIndex, int bikeUsed) {
        if (workerIndex == workers.length) {
            return 0;
        }

        if (memo[workerIndex][bikeUsed] != -1) {
            return memo[workerIndex][bikeUsed];
        }

        int minDistance = Integer.MAX_VALUE;
        for (int i = 0; i < bikes.length; i++) {
            if ((bikeUsed & (1 << i)) == 0) { // Bike i is not used
                int distance = Math.abs(workers[workerIndex][0] - bikes[i][0]) +
                               Math.abs(workers[workerIndex][1] - bikes[i][1]);
                int newBikeUsed = bikeUsed | (1 << i);
                minDistance = Math.min(minDistance, distance + backtrack(workerIndex + 1, newBikeUsed));
            }
        }

        return memo[workerIndex][bikeUsed] = minDistance;
    }

    public int assignBikes(int[][] workers, int[][] bikes) {
        this.workers = workers;
        this.bikes = bikes;
        this.memo = new int[workers.length][1 << bikes.length];
        for (int[] row : memo) {
            Arrays.fill(row, -1);
        }
        return backtrack(0, 0);
    }
}

import java.io.InputStream;
import java.nio.ByteBuffer;
import java.util.zip.Inflater;
import java.util.zip.InflaterInputStream;

public class NativeZip {
    private long mObj; // Native ZIP object reference
    private InputStream mInput; // Input stream for ZIP data

    // Compression method constants
    public static final int STORE = 0;
    public static final int DEFLATE = 8;

    // Initialize ZIP from a file path
    public NativeZip(String path) {
        mObj = getZip(path);
        if (mObj == 0) {
            throw new IllegalArgumentException("Failed to open ZIP file: " + path);
        }
    }

    // Initialize ZIP from a ByteBuffer
    public NativeZip(ByteBuffer buffer) {
        mObj = getZipFromByteBuffer(buffer);
        if (mObj == 0) {
            throw new IllegalArgumentException("Failed to open ZIP from ByteBuffer");
        }
    }

    // Release native resources
    public void release() {
        if (mObj != 0) {
            _release(mObj);
            mObj = 0;
        }
    }

    // Get an input stream for a specific file in the ZIP
    public InputStream getInputStream(String path) {
        if (mObj == 0) {
            throw new IllegalStateException("ZIP object is not initialized");
        }
        long streamObj = _getInputStream(mObj, path);
        if (streamObj == 0) {
            throw new IllegalArgumentException("File not found in ZIP: " + path);
        }
        return createInputStream(streamObj);
    }

    // Native method to open ZIP from file path
    private native long getZip(String path);

    // Native method to open ZIP from ByteBuffer
    private native long getZipFromByteBuffer(ByteBuffer buffer);

    // Native method to release resources
    private native void _release(long obj);

    // Native method to get an input stream for a file in the ZIP
    private native long _getInputStream(long obj, String path);

    // Create an input stream from a native stream object
    private InputStream createInputStream(long streamObj) {
        ByteBuffer buffer = getStreamBuffer(streamObj);
        int compression = getStreamCompression(streamObj);

        if (compression == STORE) {
            return new ByteBufferInputStream(buffer);
        } else if (compression == DEFLATE) {
            return new InflaterInputStream(new ByteBufferInputStream(buffer), new Inflater(true));
        } else {
            throw new UnsupportedOperationException("Unsupported compression method: " + compression);
        }
    }

    // Native method to get the buffer for a stream

public IAtomContainer assignDoubleBonds(IAtomContainer atomContainer) throws CDKException {

    for (IBond bond : atomContainer.bonds()) {
        if (bond.getOrder() == IBond.Order.UNSET && bond.getAtom(0).getAtomicNumber() == 6
            && bond.getAtom(1).getAtomicNumber() == 6) {
            bond.setOrder(IBond.Order.DOUBLE);
        }
    }
    return atomContainer;
}

// Calculate hypotenuse n of OTT assuming only nothingness, unity, and hyp[n-1] if n>1
//, May 6th., 2013
import java.math.BigInteger;
public class Galloway {
static int N = 123456;
static BigInteger[] hyp = new BigInteger[N-3];
static BigInteger G(int n, int g) {
return g>n?BigInteger.ZERO:(g==1 || n-g<2)?BigInteger.ONE:hyp[n-g-2];
}
static void G_hyp(int n) {
for(int i=0;i<N-2*n-1;i++)
n==1?hyp[n-1+i]=BigInteger.ONE.add(G(i+n+1,n+1)):hyp[n-1+i]=hyp[n-1+i].add(G(i+n+1,n+1));
}
}

import java.math.BigInteger;
public class Mersenne
{
 
    public static boolean isPrime(int p) {
        if (p == 2)
            return true;
        else if (p <= 1 || p % 2 == 0)
            return false;
        else {
            int to = (int)Math.sqrt(p);
            for (int i = 3; i <= to; i += 2)
                if (p % i == 0)
                    return false;
            return true;
        }
    }
 
    public static boolean isMersennePrime(int p) {
        if (p == 2)
            return true;
        else {
            BigInteger m_p = BigInteger.ONE.shiftLeft(p).subtract(BigInteger.ONE);
            BigInteger s = BigInteger.valueOf(4);
            for (int i = 3; i <= p; i++)
                s = s.multiply(s).subtract(BigInteger.valueOf(2)).mod(m_p);
            return s.equals(BigInteger.ZERO);
        }
    }
 
    // an arbitrary upper bound can be given as an argument
    public static void main(String[] args) {
        int upb;
        if (args.length == 0)
            upb = 500;
        else
            upb = Integer.parseInt(args[0]);
 
        System.out.print(" Finding Mersenne primes in M[2.." + upb + "]:\nM2 ");
        for (int p = 3; p <= upb; p += 2)
            if (isPrime(p) && isMersennePrime(p))
                System.out.print(" M" + p);
        System.out.println();
    }
}

