class Tree {
    public int reachableNodes(int n, int[][] edges, int[] restricted) {
        List<Integer>[] adjList = new List[n];
        for (int i = 0; i < n; i++) {
            adjList[i] = new ArrayList();
        }
        for (int[] e : edges){
            adjList[e[0]].add(e[1]);
            adjList[e[1]].add(e[0]);
        }
        Set<Integer> nonreachable = new HashSet();
        for (int r : restricted) {
            nonreachable.add(r);
        }
        Set<Integer> reached = new HashSet();
        Queue<Integer> queue = new LinkedList();
        reached.add(0);
        queue.offer(0);
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            for (int neigh : adjList[cur]) {
                if (!reached.contains(neigh) && !nonreachable.contains(neigh)) {
                    reached.add(neigh);
                    queue.offer(neigh);
                }
            }
        }
        return reached.size();
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Processor {
    int sum = 0;

    public int rangeSumBST(TreeNode root, int L, int R) {
        dfs(root, L, R);
        return sum;
    }

    private void dfs(TreeNode node, int L, int R) {
        if (node == null) {
            return;
        }
        if (node.val >= L && node.val <= R) {
            sum += node.val;
            dfs(node.left, L, R);
            dfs(node.right, L, R);
        } else if (node.val < L) {
            dfs(node.right, L, R);
        } else if (node.val > R) {
            dfs(node.left, L, R);
        }
    }
}

