class Library {
   public boolean canBeEqual(int[] target, int[] arr) {
        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : arr) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        Map<Integer, Integer> targetCountMap = new HashMap<>();
        for (int num : target) {
            targetCountMap.put(num, targetCountMap.getOrDefault(num, 0) + 1);
        }

        for (Integer key : countMap.keySet()) {
            if (!countMap.get(key).equals(targetCountMap.getOrDefault(key, 0))) {
                return false;
            }
        }
        return true;
    }
}

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
 
public class Digester {
 
    public static void main(String[] args) {
        System.out.println(hexDigest("Rosetta code", "MD5"));
    }
 
    static String hexDigest(String str, String digestName) {
        try {
            MessageDigest md = MessageDigest.getInstance(digestName);
            byte[] digest = md.digest(str.getBytes(StandardCharsets.UTF_8));
            char[] hex = new char[digest.length * 2];
            for (int i = 0; i < digest.length; i++) {
                hex[2 * i] = "0123456789abcdef".charAt((digest[i] & 0xf0) >> 4);
                hex[2 * i + 1] = "0123456789abcdef".charAt(digest[i] & 0x0f);
            }
            return new String(hex);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

