import org.flowable.engine.common.api.FlowableException;
import org.flowable.engine.common.api.FlowableIllegalArgumentException;
import org.flowable.engine.common.api.FlowableObjectNotFoundException;
import org.flowable.engine.common.impl.interceptor.Command;
import org.flowable.engine.common.impl.interceptor.CommandContext;
import org.flowable.engine.form.TaskFormData;
import org.flowable.engine.impl.form.FormEngine;
import org.flowable.engine.impl.form.TaskFormHandler;
import org.flowable.engine.impl.persistence.entity.TaskEntity;
import org.flowable.engine.impl.util.CommandContextUtil;
import org.flowable.engine.impl.util.FormHandlerUtil;
import org.flowable.engine.task.Task;

/**
 */
public class GetRenderedTaskFormCmd implements Command<Object>, Serializable {

    private static final long serialVersionUID = 1L;
    protected String taskId;
    protected String formEngineName;

    public GetRenderedTaskFormCmd(String taskId, String formEngineName) {
        this.taskId = taskId;
        this.formEngineName = formEngineName;
    }

    public Object execute(CommandContext commandContext) {

        if (taskId == null) {
            throw new FlowableIllegalArgumentException("Task id should not be null");
        }

        TaskEntity task = CommandContextUtil.getTaskEntityManager(commandContext).findById(taskId);
        if (task == null) {
            throw new FlowableObjectNotFoundException("Task '" + taskId + "' not found", Task.class);
        }

        TaskFormHandler taskFormHandler = FormHandlerUtil.getTaskFormHandlder(task);
        if (taskFormHandler != null) {

            FormEngine formEngine = CommandContextUtil.getProcessEngineConfiguration(commandContext).getFormEngines().get(formEngineName);

            if (formEngine == null) {
                throw new FlowableException("No formEngine '" + formEngineName + "' defined process engine configuration");
            }

            TaskFormData taskForm = taskFormHandler.createTaskForm(task);

            return formEngine.renderTaskForm(taskForm);
        }

        return null;
    }
}

import java.util.function.Function;
 
public class Church {
    private final Function<Function<Integer, Integer>, Function<Integer, Integer>> runner;
 
    public Church(Function<Function<Integer, Integer>, Function<Integer, Integer>> runner) {
        this.runner = runner;
    }
 
    public static Church zero() {
        return new Church(f -> x -> x);
    }
 
    public Church succ() {
        return new Church(f -> {
            Function<Integer, Integer> g = runner.apply(f);
            return x -> f.apply(g.apply(f).apply(x));
        });
    }
 
    public Function<Integer, Integer> run(Function<Integer, Integer> f) {
        return runner.apply(f);
    }
 
    public Church exp(Church rhs) {
        return new Church(rhs.runner.apply(runner));
    }
 
    public Church add(Church rhs) {
        return new Church(f -> {
            Function<Integer, Integer> selfRunner = runner.apply(f);
            Function<Integer, Integer> rhsRunner = rhs.runner.apply(f);
            return x -> selfRunner.apply(rhsRunner.apply(x));
        });
    }
 
    public Church mul(Church rhs) {
        return new Church(f -> runner.apply(rhs.runner.apply(f)));
    }
 
    public static Church from(int n) {
        Church ret = zero();
        for (int i = 0; i < n; i++) {
            ret = ret.succ();
        }
        return ret;
    }
 
    public int toInt() {
        return run(x -> x + 1).apply(0);
    }
 
    public static void main(String[] args) {
        System.out.println("three =\t" + from(3).toInt());
        System.out.println("four =\t" + from(4).toInt());
 
        System.out.println("three + four =\t" + from(3).add(from(4)).toInt());
        System.out.println("three * four =\t" + from(3).mul(from(4)).toInt());
 
        System.out.println("three ^ four =\t" + from(3).exp(from(4)).toInt());
        System.out.println("four ^ three =\t" + from(4).exp(from(3)).toInt());
    }
}

import java.util.Scanner;

public class Faktoriyel {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Bir sayi giriniz:");
        int n = input.nextInt();

        System.out.print(n);

        // Compute n! by counting down from n to 1 using a for-loop
        // (original used a while-loop that mutated the input variable).
        int product = 1;
        for (int k = n; k > 0; k--) {
            product *= k;
        }

        System.out.println("! = " + product);

        input.close();
    }
}

