import java.util.*;

class Graph {
    private int n;
    private List<List<int[]>> edges;

    public Graph(int n, int[][] edges) {
        this.n = n;
        this.edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            this.edges.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            this.edges.get(edge[0]).add(new int[]{edge[1], edge[2]});
        }
    }

    public void addEdge(int[] edge) {
        this.edges.get(edge[0]).add(new int[]{edge[1], edge[2]});
    }

    public int shortestPath(int node1, int node2) {
        int[][] distance = new int[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(distance[i], Integer.MAX_VALUE);
        }
        distance[node1][node1] = 0;

        PriorityQueue<int[]> queue = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        queue.offer(new int[]{0, node1});

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentDistance = current[0];
            int currentNode = current[1];

            if (currentDistance > distance[node1][currentNode]) {
                continue;
            }

            for (int[] neighbor : edges.get(currentNode)) {
                int neighborNode = neighbor[0];
                int neighborDistance = currentDistance + neighbor[1];

                if (neighborDistance < distance[node1][neighborNode]) {
                    distance[node1][neighborNode] = neighborDistance;
                    queue.offer(new int[]{neighborDistance, neighborNode});
                }
            }
        }

        return distance[node1][node2] == Integer.MAX_VALUE ? -1 : distance[node1][node2];
    }
}

import java.util.Scanner;

public class Tree {
    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            System.out.print("Enter a, b, c (as integers): ");
            /* a,b,c as integers in Standard Form */
            int a = in.nextInt();
            int b = in.nextInt();
            int c = in.nextInt();
            Rational aRational = new Rational(a); // Constructs Rational with denominator of 1 as default
            Rational bRational = new Rational(b); // Constructs Rational with denominator of 1 as default
            Rational cRational = new Rational(c); // Constructs Rational with denominator of 1 as default
            Rational h = new Rational(bRational.multiply(new Rational(-1)).longValue(),
                    aRational.multiply(new Rational(2)).longValue());
            Rational k = aRational.multiply(h.multiply(h)).add(bRational.multiply(h)).add(cRational);
            System.out.println("h is " + h + ", k is " + k);

        } catch (Exception e) {
            System.out.println(e.getMessage());
            e.printStackTrace();
        }
    }
}

public static <T> void copy(final ActionContext<T> source, final SchedulableActionContext<T> target) {
    target.setActor(source.getActor());
    target.putAll(source.toMap());
    target.setInitialDelay(target.getInitialDelay(TimeUnit.NANOSECONDS), TimeUnit.NANOSECONDS);
    target.setPeriod(source.getPeriod(TimeUnit.NANOSECONDS), TimeUnit.NANOSECONDS);
    }

