public class PossibleValuesReader {
    private static final Logger LOGGER = Logger.getLogger(PossibleValuesReader.class.getName());

    private final DataStoreInfo dataStoreInfo;
    private final LayerInfo layerInfo;
    private final String propertyName;

    public PossibleValuesReader(DataStoreInfo dataStoreInfo, LayerInfo layerInfo, String propertyName) {
        this.dataStoreInfo = dataStoreInfo;
        this.layerInfo = layerInfo;
        this.propertyName = propertyName;
    }

    public Set<Serializable> getUnique() {
        Set<Serializable> uniqueValues = new LinkedHashSet<>();

        try {
            DataStore dataStore = dataStoreInfo.getDataStore(null);

            if (!(dataStore instanceof JDBCDataStore)) {
                throw new UnsupportedOperationException("Unsupported data store type");
            }

            JDBCDataStore jdbcDataStore = (JDBCDataStore) dataStore;
            SimpleFeatureSource featureSource = jdbcDataStore.getFeatureSource(layerInfo.getName());

            String tableName = extractTableName(featureSource);
            String schemaName = extractSchemaName(featureSource);

            uniqueValues = retrieveUniqueValues(jdbcDataStore, tableName, schemaName);

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error retrieving unique values", e);
        }

        return Collections.unmodifiableSet(uniqueValues);
    }

    private String extractTableName(SimpleFeatureSource featureSource) {
        if (featureSource.getSchema().getName().getLocalPart() instanceof String) {
            return featureSource.getSchema().getName().getLocalPart();
        }
        throw new IllegalStateException("Unable to extract table name");
    }

    private String extractSchemaName(SimpleFeatureSource featureSource) {
        try {
            VirtualTable virtualTable = featureSource.getClass()
                .getDeclaredMethod("getVirtualTable")
                .invoke(featureSource);

            return virtualTable != null ? virtualTable.getSchemaName() : null;

@SuppressWarnings("deprecation") private static short shortBE(ByteBuf buffer, int offset) {
    return (short) (buffer.getByte(offset) << 8 | buffer.getByte(offset + 1) & 0xFF);
}

@SuppressWarnings("deprecation") private static int intBE(ByteBuf buffer, int offset) {
    return buffer.getByte(offset) << 24 |
           (buffer.getByte(offset + 1) & 0xFF) << 16 |
           (buffer.getByte(offset + 2) & 0xFF) << 8 |
           buffer.getByte(offset + 3) & 0xFF;
}

@SuppressWarnings("deprecation") private static long longBE(ByteBuf buffer, int offset) {
    return (long) buffer.getByte(offset) << 56 |
           ((long) buffer.getByte(offset + 1) & 0xFF) << 48 |
           ((long) buffer.getByte(offset + 2) & 0xFF) << 40 |
           ((long) buffer.getByte(offset + 3) & 0xFF) << 32 |
           ((long) buffer.getByte(offset + 4) & 0xFF) << 24 |
           ((long) buffer.getByte(offset + 5) & 0xFF) << 16 |
           ((long) buffer.getByte(offset + 6) & 0xFF) << 8 |
           (long) buffer.getByte(offset + 7) & 0xFF;
}

