class Finder {
    public int minimumOperations(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);
        int ans = 0;
        if (nums[0] != 0) ans++;
        for (int i = 1; i < n; ++i) {
            if (nums[i] != nums[i - 1]) ans++;
        }
        return ans;
    }
}

