class Logger {
    public int largestInteger(int num) {
        int[] counts = new int[10];
        int tmp = num, result = 0, flag = 1;
        while (tmp > 0) {
            counts[tmp % 10]++;
            tmp /= 10;
        }
        int evenPos = 0, oddPos = 1;
        while (num > 0) {
            if (((num % 10) & 1) == 0) {
                while (counts[evenPos] == 0) {
                    evenPos += 2;
                }
                result += evenPos * flag;
                counts[evenPos]--;
            } else {
                while (counts[oddPos] == 0) {
                    oddPos += 2;
                }
                counts[oddPos]--;
                result += oddPos * flag;
            }
            flag *= 10;
            num /= 10;
        }
        return result;
    }
}

