class Parser {
    public int minInsertions(String s) {
        int res = 0;
        int balance = 0;
        char[] arr = s.toCharArray();
        for(int i = 0; i < arr.length; i++){
            if(arr[i] == '('){
                ++balance;
            }else{
                if(balance > 0){
                    --balance;
                }else{
                    ++res;
                }

                if(i < arr.length - 1 && arr[i+1] == ')'){
                    ++i;
                }else{
                    ++res;
                }

            }
        }
        if(balance > 0)res += balance * 2;
        return res;
    }
}

