public int[] arrow(int numArrows, int[] aliceArrows) {
        ArrayList<Integer> bob = new ArrayList<Integer>();
        ArrayList<Integer> alice = new ArrayList<Integer>();
        int n = 0;
        int[] bobArrows = new int[12];
        for(int i = 0; i < 12; i++){
            alice.add(aliceArrows[i]);
            n += aliceArrows[i];
        }
        while(n != numArrows){
            int max = Collections.max(alice);
            int index = alice.indexOf(max);
            alice.set(index,max-1);
            bob.set(index,max-1);
            n++;
        }
        for(int i = 0; i < 12; i++){
            bobArrows[i] = bob.get(i);
        }
        return bobArrows;
    }
}

