    public int minCostToSupplyWater(int n, int[] wells, int[][] pipes) {
        HashMap<Pair, Integer> bestPipe = new HashMap<>();
        for (int[] pipe : pipes) {
            Pair p = new Pair(pipe[0] - 1, pipe[1] - 1);
            int prev = bestPipe.getOrDefault(p, Integer.MAX_VALUE);
            if (pipe[2] < prev) {
                bestPipe.put(p, pipe[2]);
            }
        }

        Edge[] edges = new Edge[bestPipe.size()];
        int idx = 0;
        for (Map.Entry<Pair, Integer> kvp : bestPipe.entrySet()) {
            Edge e = new Edge();
            e.p = kvp.getKey();
            e.cost = kvp.getValue();
            edges[idx++] = e;
        }
        Arrays.sort(edges, Edge.BY_COST);

        int totalCost = 0;
        int cost[] = new int[n];
        for (int i = 0; i < n; ++i) {
            cost[i] = wells[i];
            totalCost += wells[i];
        }

        DisjointSet djs = new DisjointSet(n);
        // int pipeCost = 0;
        for (Edge e : edges) {
            if (djs.find(e.p.u) == djs.find(e.p.v)) {
                continue;
            }
            int uCost = cost[djs.find(e.p.u)];
            int vCost = cost[djs.find(e.p.v)];
            int expensive = Math.max(uCost, vCost);
            if (e.cost < expensive) {
                int savings = expensive - e.cost;
                totalCost -= savings;
                djs.union(e.p.u, e.p.v);
                cost[djs.find(e.p.u)] = Math.min(uCost, vCost);
            }
        }
        return totalCost;

