public static String[] levenshteinAlign(String a, String b) {
    String aa = a.toLowerCase();
    String bb = b.toLowerCase();
    int[][] costs = new int[a.length() + 1][b.length() + 1];
    for (int j = 0; j <= b.length(); j++) {
        costs[0][j] = j;
    }
    for (int i = 1; i <= a.length(); i++) {
        costs[i][0] = i;
        for (int j = 1; j <= b.length(); j++) {
            int temp = costs[i - 1][j - 1] + (aa.charAt(i - 1) == bb.charAt(j - 1)? 0 : 1);
            costs[i][j] = Math.min(1 + Math.min(costs[i - 1][j], costs[i][j - 1]), temp);
        }
    }
 
    // walk back through matrix to figure out path
    StringBuilder aPathRev = new StringBuilder();
    StringBuilder bPathRev = new StringBuilder();
    int i = a.length();
    int j = b.length();
    while (i!= 0 && j!= 0) {
        int temp = costs[i - 1][j - 1] + (aa.charAt(i - 1) == bb.charAt(j - 1)? 0 : 1);
        switch (costs[i][j]) {
            case temp:
                aPathRev.append(aa.charAt(--i));
                bPathRev.append(bb.charAt(--j));
                break;
            case 1 + costs[i - 1][j]:
                aPathRev.append(aa.charAt(--i));
                bPathRev.append('-');
                break;
            case 1 + costs[i][j - 1]:
                aPathRev.append('-');
                bPathRev.append(bb.charAt(--j));
                break;
        }
    }
    return new String[]{aPathRev.reverse().toString(), bPathRev.reverse().toString()};
}
 
public static void main(String[] args) {
    String[] result = levenshteinAlign("place", "palace");
    System.out.println(result[0]);
    System.out.println(result[1]);
    System.out.println();
    result = levenshteinAlign("rosettacode", "raisethysword");
    System.out.println(result[0]);
    System.out.println(result[1]);
}

