public class EgyptianDivision {

    // EGYPTIAN DIVISION --------------------------------

    // eqyptianQuotRem :: Int -> Int -> (Int, Int)
    public static Pair<Integer, Integer> eqyptianQuotRem(int m, int n) {
        Function<Pair<Integer, Integer>, List<Pair<Integer, Integer>>> expansion = (Pair<Integer, Integer> x) -> {
            int i = x.fst;
            int x1 = x.snd;
            if (x1 > m) {
                return null;
            } else {
                return List.of(
                        new Pair<>(i, x1),
                        new Pair<>(i + i, x1 + x1)
                );
            }
        };
        BiFunction<Pair<Integer, Integer>, Pair<Integer, Integer>, Pair<Integer, Integer>> collapse = (Pair<Integer, Integer> x, Pair<Integer, Integer> y) -> {
            int i = x.fst;
            int x1 = x.snd;
            int q = y.fst;
            int r = y.snd;
            if (x1 < r) {
                return new Pair<>(q + i, r - x1);
            } else {
                return new Pair<>(q, r);
            }
        };
        return foldr(
                collapse,
                new Pair<>(0, m),
                unfoldr(expansion, new Pair<>(1, n))
        );
    }

    // TEST ---------------------------------------------

    // main :: IO ()
    public static void main(String[] args) {
        showLog(
                eqyptianQuotRem(580, 34)
        );
        // -> [17, 2]
    }

