    // Just :: a -> Maybe a
    public static <A> Maybe<A> Just(A x) {
        return new Maybe<>(x);
    }

    // Nothing :: Maybe a
    public static <A> Maybe<A> Nothing() {
        return new Maybe<>();
    }

    // flip :: (a -> b -> c) -> b -> a -> c
    public static <A, B, C> Function<B, Function<A, C>> flip(BiFunction<A, B, C> f) {
        return a -> b -> f.apply(b, a);
    }

    // foldr :: (a -> b -> b) -> b -> [a] -> b
    public static <A, B> B foldr(BiFunction<A, B, B> f, B a, List<A> xs) {
        return xs.stream().reduce(a, flip(f));
    }

