public class Conversion {

    public static double footToMeter(double foot) {
        return 0.305 * foot;
    }

    public static double meterToFoot(double meter) {
        return 3.279 * meter;
    }

    public static void main(String[] args) {
        System.out.println("Feet   Meters | Meters Feet");
        System.out.println("___________________________");
        for (double i = 1.0, j = 20.0; i <= 10.0; i++, j += 5) {
            System.out.printf("%-7.1f%-7.3f | %-7.1f%-7.3f\n", i, footToMeter(i), j, meterToFoot(j));
        }
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.stage.Stage;

public class CircleColor extends Application {

    @Override
    public void start(Stage primaryStage) {

        // Create a circle with radius 50 at the center of the pane
        Circle circle = new Circle(150, 150, 50);

        // Set the initial color of the circle to black
        circle.setFill(Color.BLACK);

        // Add event handlers to change the color of the circle when the mouse button is pressed or released
        circle.setOnMousePressed(event -> circle.setFill(Color.WHITE));
        circle.setOnMouseReleased(event -> circle.setFill(Color.BLACK));

        // Create the pane and add the circle
        Pane pane = new Pane();
        pane.getChildren().add(circle);

        // Create the scene and show the stage
        Scene scene = new Scene(pane, 300, 300);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Circle Color");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.util.Scanner;

public class SortCities {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt user to enter three cities
        System.out.print("Enter the name of the first city: ");
        String city1 = scanner.nextLine();

        System.out.print("Enter the name of the second city: ");
        String city2 = scanner.nextLine();

        System.out.print("Enter the name of the third city: ");
        String city3 = scanner.nextLine();

        // Sort the cities in ascending order
        String temp;

        if (city1.compareTo(city2) > 0) {
            temp = city1;
            city1 = city2;
            city2 = temp;
        }

        if (city2.compareTo(city3) > 0) {
            temp = city2;
            city2 = city3;
            city3 = temp;
        }

        if (city1.compareTo(city2) > 0) {
            temp = city1;
            city1 = city2;
            city2 = temp;
        }

        // Display the cities in ascending order
        System.out.printf("The cities in alphabetical order are %s, %s, and %s\n", city1, city2, city3);

        scanner.close();
    }
}

public boolean lemonadeChange(int[] bills) {
    int five = 0, ten = 0;
    for (int bill : bills) {
        if (bill == 5) {
            five++;
        } else if (bill == 10) {
            if (five == 0) return false;
            five--;
            ten++;
        } else {
            if (ten > 0 && five > 0) {
                ten--;
                five--;
            } else if (five >= 3) {
                five -= 3;
            } else {
                return false;
            }
        }
    }
    return true;
}

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.hateoas.EntityModel;
import org.springframework.hateoas.Link;
import org.springframework.hateoas.Links;
import javassist.util.proxy.ProxyFactory;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

public class ResourceDeserializer extends JsonDeserializer<EntityModel<?>> {

    private final TypeResolver typeResolver;
    private final Configuration configuration;

    public ResourceDeserializer(TypeResolver typeResolver, Configuration configuration) {
        this.typeResolver = typeResolver;
        this.configuration = configuration;
    }

    @Override
    public EntityModel<?> deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
        ObjectMapper mapper = (ObjectMapper) p.getCodec();
        ObjectNode rootNode = mapper.readTree(p);
        JsonNode contentNode = rootNode.get("content");
        JsonNode linksNode = rootNode.get("_links");

        Type resourceType = getResourceDeserializationType(rootNode);
        Object content = mapper.convertValue(contentNode, mapper.constructType(resourceType));

        List<Link> linkList = new ArrayList<>();
        if (linksNode != null) {
            Iterator<String> linkNames = linksNode.fieldNames();
            while (linkNames.hasNext()) {
                String linkName = linkNames.next();
                String href = linksNode.get(linkName).get("href").asText();
                linkList.add(Link.of(href, linkName));
            }
        }

        return EntityModel.of(content, Links.of(linkList));
    }

    private Type getResourceDeserializationType(JsonNode rootNode) {
        String typeName = rootNode.get("type").asText();
        Type type = typeResolver.resolveType(typeName);

        if (type instanceof Class<?> && ((Class<?>) type).isInterface()) {
            ProxyFactory factory = new ProxyFactory();
            factory.setSuperclass((Class<?>) type);
            return factory.createClass();
        } else if (type instanceof Class<?> && ((Class<?>) type).isAbstract()) {
            ProxyFactory factory = new ProxyFactory();
            factory.setSuperclass((Class<?>) type);
            return factory.createClass();
        }

import com.google.common.base.Objects;

public class GroupKey {

    private final String upperName;
    private final String leftName;

    public GroupKey(String upperName) {
        this(upperName, null);
    }

    public GroupKey(String upperName, String leftName) {
        this.upperName = upperName;
        this.leftName = leftName;
    }

    public String getUpperName() {
        return upperName;
    }

    public String getLeftName() {
        return leftName;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        GroupKey groupKey = (GroupKey) o;

        if (!Objects.equal(upperName, groupKey.upperName)) return false;
        return Objects.equal(leftName, groupKey.leftName);
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(upperName, leftName);
    }

    @Override
    public String toString() {
        return "GroupKey{" +
                "upperName='" + upperName + '\'' +
                ", leftName='" + leftName + '\'' +
                '}';
    }

    public static void main(String[] args) {
        GroupKey key1 = new GroupKey("A", "B");
        GroupKey key2 = new GroupKey("A", "B");
        GroupKey key3 = new GroupKey("C", "D");

        System.out.println("key1 equals key2: " + key1.equals(key2));
        System.out.println("key1 equals key3: " + key1.equals(key3));
        System.out.println("key1 hashCode: " + key1.hashCode());
        System.out.println("key2 hashCode: " + key2.hashCode());
        System.out.println("key3 hashCode: " + key3.hashCode());
        System.out.println("key1 toString: " + key1.toString());
    }
}

import java.io.BufferedReader;
