import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.util.Log;
import android.widget.Toast;

public class ReceiverPublic extends BroadcastReceiver {
    public static final String ACTION_ENABLE = "com.example.acdisplay.ACTION_ENABLE";
    public static final String ACTION_DISABLE = "com.example.acdisplay.ACTION_DISABLE";
    public static final String ACTION_TOGGLE = "com.example.acdisplay.ACTION_TOGGLE";
    private static final String TAG = "AcDisplayReceiver";

    @Override
    public void onReceive(Context context, Intent intent) {
        String action = intent.getAction();
        if (action == null) {
            Log.d(TAG, "Received null action");
            return;
        }

        Log.d(TAG, "Received action: " + action);
        switch (action) {
            case ACTION_ENABLE:
            case ACTION_DISABLE:
            case ACTION_TOGGLE:
                processIntent(context, action);
                break;
            default:
                Log.w(TAG, "Unsupported action: " + action);
        }
    }

    private void processIntent(Context context, String action) {
        if (!validatePermissions(context)) {
            Log.w(TAG, "Permission check failed for: " + action);
            Toast.makeText(context, R.string.permission_denied, Toast.LENGTH_SHORT).show();
            return;
        }

        Config config = Config.getInstance(context);
        boolean targetState = resolveTargetState(config, action);

        applyStateChange(context, config, targetState);
        provideUserFeedback(context, targetState);
    }

    private boolean validatePermissions(Context context) {
        if (!App.getAccessManager().hasPermission(context)) {
            Log.w(TAG, "Caller lacks required permissions");
            return false;
        }
        return true;
    }

    private boolean resolveTargetState(Config config, String action) {
        boolean currentState = config.isEnabled();
        switch (action) {
            case ACTION_ENABLE:
                return true;
            case ACTION_DISABLE:
                return false;
            case ACTION_TOGGLE:
                return !currentState;
            default:
                throw new IllegalArgumentException("Invalid action: " + action);
        }
    }

    private void applyStateChange(Context context, Config config, boolean enabled) {
        Log.i(TAG, "Updating state to: " + enabled);
        config.setEnabled(enabled);
        config.persistState();
    }

public class Sphere{
    static char[] shades = {'.', ':', '!', '*', 'o', 'e', '&', '#', '%', '@'};
 
    static double[] light = { 30, 30, -50 };
    private static void normalize(double[] v){
        double len = Math.sqrt(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]);
        v[0] /= len; v[1] /= len; v[2] /= len;
    }
 
    private static double dot(double[] x, double[] y){
        double d = x[0]*y[0] + x[1]*y[1] + x[2]*y[2];
        return d < 0 ? -d : 0;
    }
 
    public static void drawSphere(double R, double k, double ambient){
        double[] vec = new double[3];
        for(int i = (int)Math.floor(-R); i <= (int)Math.ceil(R); i++){
            double x = i + .5;
            for(int j = (int)Math.floor(-2 * R); j <= (int)Math.ceil(2 * R); j++){
                double y = j / 2. + .5;
                if(x * x + y * y <= R * R) {
                    vec[0] = x;
                    vec[1] = y;
                    vec[2] = Math.sqrt(R * R - x * x - y * y);
                    normalize(vec);
                    double b = Math.pow(dot(light, vec), k) + ambient;
                    int intensity = (b <= 0) ?
                                shades.length - 2 :
                                (int)Math.max((1 - b) * (shades.length - 1), 0);
                    System.out.print(shades[intensity]);
                } else
                    System.out.print(' ');
            }
            System.out.println();
        }
    }
 
    public static void main(String[] args){
        normalize(light);
        drawSphere(20, 4, .1);
        drawSphere(10, 2, .4);
    }
}

