class FileSystem {
    TreeNode root;
    Set<String> set = new HashSet<>();
    public FileSystem() {
        root = new TreeNode("/");
        root.isFile = true;
    }

    public List<String> ls(String path) {
        String[] objs = path.split("/");
        TreeNode curNode = root;
        String rawPath = "";
        List<String> res = new LinkedList<>();
        for(int i=1; i<objs.length; i++){   // start with '/' so objs' length is > 1
            String one = objs[i];
            rawPath += "/" + one;
            curNode = curNode.list.get(one);
            res.add(curNode.val);
            if(curNode.isFile){
                break;
            }
        }
        if(objs.length == 1){
            return root.list.keySet().stream().sorted().collect(Collectors.toList());
        }
        return res;
    }

    public void mkdir(String path) {
        String[] subnodes = path.split("/");
        TreeNode curNode = root;
        String rawPath = "";
        for(int i=1; i<subnodes.length; i++){
            String one = subnodes[i];
            rawPath += "/" + one;
            if(!curNode.list.containsKey(one)){
                TreeNode child = new TreeNode(one);
                curNode.list.put(one,child);
                set.add(rawPath);
            }
            curNode = curNode.list.get(one);
        }
        curNode.isFile = true;
    }

