public void drawHypercubeHelper(Plot plot, Group group, String cls, double minx, double miny, double[] r_edges, int off, int b) {
    if(off == r_edges.length) {
        Line edge = new Line(minx, miny, minx + r_edges[0], miny + r_edges[1]);
        edge.getStyleClass().add(cls);
        group.getChildren().add(edge);
        return;
    }

    int old_b = b;
    b |= 1 << off;
    drawHypercubeHelper(plot, group, cls, minx, miny, r_edges, off+1, b);
    b = old_b;
    b |= 1 << off;
    double [] r_edges_2 = Arrays.copyOf(r_edges, r_edges.length);
    r_edges_2[off] *= -1;
    drawHypercubeHelper(plot, group, cls, minx + r_edges[0], miny + r_edges[1], r_edges_2, off+1, b);
}

