class Generator {
    public int maxNumberOfBalloons(String text) {
        if (text == null || text.length() == 0) {
            return 0;
        }
        int[] freq = new int[256];
        for (final char c : text.toCharArray()) {
            freq[c]++;
        }
        int min = Integer.MAX_VALUE;
        for (final char c : new char[]{'b', 'a', 'l', 'o', 'n'}) {
            if (c == 'l' || c == 'o') {
                min = Math.min(min, freq[c]/2);
            } else {
                min = Math.min(min, freq[c]);
            }
        }
        return min == Integer.MAX_VALUE ? 0 : min;
    }
}

import java.io.IOException;

interface EdgeListStream {
    boolean hasNextEdge() throws IOException;
    EdgeData getNextEdge() throws IOException;
    void close() throws IOException;
}

class EdgeData {
    private final Object[] properties;

    public EdgeData(Object[] properties) {
        this.properties = properties;
    }

    public Object[] getProperties() {
        return properties;
    }
}

public class EdgeListPropertyFilter implements EdgeListStream {
    private final EdgeListStream inputStream;
    private final int[] propertyIndices;
    private EdgeData nextEdgeCache;

    public EdgeListPropertyFilter(EdgeListStream inputStream, int[] propertyIndices) {
        this.inputStream = inputStream;
        this.propertyIndices = propertyIndices;
    }

    @Override
    public boolean hasNextEdge() throws IOException {
        return inputStream.hasNextEdge();
    }

    @Override
    public EdgeData getNextEdge() throws IOException {
        if (nextEdgeCache == null) {
            if (!inputStream.hasNextEdge()) {
                return null;
            }
            EdgeData edge = inputStream.getNextEdge();
            nextEdgeCache = filterEdgeProperties(edge);
        }
        EdgeData result = nextEdgeCache;
        nextEdgeCache = null;
        return result;
    }

    private EdgeData filterEdgeProperties(EdgeData edge) {
        Object[] originalProperties = edge.getProperties();
        Object[] filteredProperties = new Object[propertyIndices.length];

        for (int i = 0; i < propertyIndices.length; i++) {
            int index = propertyIndices[i];
            filteredProperties[i] = originalProperties[index];
        }
        return new EdgeData(filteredProperties);
    }

    @Override
    public void close() throws IOException {
        inputStream.close();
    }

    public static void main(String[] args) {
        // Example Usage
        EdgeListStream inputStream = new MockEdgeListStream(); // Assume MockEdgeListStream is defined
        int[] propertyIndices = {0, 2}; // Define which properties to keep

        EdgeListPropertyFilter filter = new EdgeListPropertyFilter(inputStream, propertyIndices);
        try {
            while (filter.hasNextEdge()) {
                EdgeData edge = filter.getNextEdge();
                if (edge != null) {
                    for (Object property : edge.getProperties()) {
                        System.out.print(property + " ");
                    }
                    System.out.println();
                }
            }
        } catch (IOException e) {

import java.security.*;
import java.util.*;

public byte[] getClassDigest(Class<?> def, Map<String, String> conf) throws NoSuchAlgorithmException {
    MessageDigest md = MessageDigest.getInstance(conf.get("algorithm"));
    byte[] byteCode = def.getResourceAsStream(
        "/" + def.getName().replace('.', '/') + ".class"
    ).readAllBytes();
    return md.digest(byteCode);
}

