class Builder {
    public int countOrders(int n) {
        int MOD = 1_000_000_007;
        long[] dp = new long[n];
        dp[0] = 1;
        for (int i = 1; i < n; i++) {
            int slots = i * 2 + 1;
            int combs = (1 + slots) * slots / 2;
            dp[i] = dp[i - 1] * (combs % MOD);
            dp[i] %= MOD;
        }
        return (int) dp[n - 1];
    }
}

import java.io.PrintStream;
import java.util.Random;
import java.util.Scanner;
 
public class GameOfLife {
    public static void main(String[] args) {
        int w = 0, h = 0;
        if (args.length > 0) {
            w = Integer.parseInt(args[0]);
        }
        if (args.length > 1) {
            h = Integer.parseInt(args[1]);
        }
        if (w <= 0) {
            w = 30;
        }
        if (h <= 0) {
            h = 30;
        }
        game(w, h);
    }
 
    public static void game(int w, int h) {
        int[][] univ = new int[h][w];
        Random rand = new Random();
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                univ[y][x] = rand.nextInt(10) < 1? 1 : 0;
            }
        }
        while (true) {
            show(univ, w, h);
            evolve(univ, w, h);
            try {
                Thread.sleep(200);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
 
    public static void show(int[][] univ, int w, int h) {
        System.out.print("\033[H");
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                if (univ[y][x] == 1) {
                    System.out.print("\033[07m  \033[m");
                } else {
                    System.out.print("  ");
                }
            }
            System.out.print("\033[E");
        }
        System.out.flush();
    }
 
    public static void evolve(int[][] univ, int w, int h) {
        int[][] newUniv = new int[h][w];
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                int n = 0;
                for (int y1 = y - 1; y1 <= y + 1; y1++) {
                    for (int x1 = x - 1; x1 <= x + 1; x1++) {
                        if (univ[(y1 + h) % h][(x1 + w) % w] == 1) {
                            n++;
                        }
                    }
                }
                if (univ[y][x] == 1) {
                    n--;
                }
                newUniv[y][x] = (n == 3 || (n == 2 && univ[y][x] == 1))? 1 : 0;
            }
        }
        for (int y = 0; y < h; y++) {
            for (int x = 0; x < w; x++) {
                univ[y][x] = newUniv[y][x];
            }
        }
    }
}

