public class Tree {
    public static void main(String[] args) {

        int[][] employeeHours = {
                {2, 4, 3, 4, 5, 8, 8},  //emp0
                {7, 3, 4, 3, 3, 4, 4},  //emp1
                {3, 3, 4, 3, 3, 2, 2},  //emp2
                {9, 3, 4, 7, 3, 4, 1},  //emp3
                {3, 5, 4, 3, 6, 3, 8},  //emp4
                {3, 4, 4, 6, 3, 4, 4},  //emp5
                {3, 7, 4, 8, 3, 8, 4},  //emp6
                {6, 3, 5, 9, 2, 7, 9}}; //emp7

        int[][] sumHours = new int[8][2];

        for (int row = 0; row < employeeHours.length; row++) {
            for (int column = 0; column < employeeHours[row].length; column++) {

                sumHours[row][0] += employeeHours[row][column];
            }
            sumHours[row][1] = row; //Save original index for sort function
        }

//      Arrays.sort(sumHours); //built in sort
        //Selection Sort
        for (int i = 0; i < sumHours.length - 1; i++) {
            for (int j = i + 1; j < sumHours.length; j++) {
                if (sumHours[i][0] < sumHours[j][0]) {
                    int[] tmp = sumHours[i];
                    sumHours[i] = sumHours[j];
                    sumHours[j] = tmp;
                }

            }
        }
        printArray(sumHours);

    }

    public static void printArray(int[][] array) {

//      for(int i = array.length - 1; i >= 0; i--) { //Print in reverse
        for (int i = 0; i < array.length; i++) {
            System.out.print("Employee number: " + array[i][1] + "'s total hours for the week were ");
            System.out.print(array[i][0] + "\n");
//      }
        }

    }

}

import java.util.Scanner;

public class Helper {
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        System.out.println("Enter 10 numbers: ");
        double mean, std = 0, sum = 0;

        double[] nums = new double[10];

        for (int i = 0; i < nums.length; i++) {
            nums[i] = in.nextDouble();
        }
        for (double num : nums) {
            sum += num;
        }

        mean = sum / 10;
        System.out.println("The mean is " + mean);

        double temp = 0;

        for (double num : nums) {
            temp += Math.pow(num - mean, 2);
        }
        std = Math.sqrt(temp / 9); // n-1

        System.out.printf("The standard deviation is %.5f", std);
    }

}

// Swing/AWT tabanli serbest el cizim uygulamasi
import java.awt.BorderLayout;
import java.awt.Point;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.event.MouseMotionAdapter;
import java.awt.Graphics;

import java.util.ArrayList;
import java.util.List;

import javax.swing.SwingUtilities;
import javax.swing.WindowConstants;
import javax.swing.JFrame;
import javax.swing.JPanel;

/** Fare ile serbest cizim yapilabilen minimal bir panel bileseni. */
public class BasitCizimPaneli extends JPanel {
    private static final long serialVersionUID = -3630443364990545965L;

    // Her biri bir surukleme hareketine karsilik gelen nokta dizileri
    private final List<List<Point>> cizimKatmanlari = new ArrayList<>();

    public BasitCizimPaneli() {
        addMouseMotionListener(new MouseMotionAdapter() {
            @Override
            public void mouseDragged(MouseEvent olay) {
                // Aktif cizginin son parcasina yeni nokta ekle
                sonCizgi().add(new Point(olay.getX(), olay.getY()));
                repaint(0, 0, getWidth(), getHeight());
            }
        });

        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent olay) {
                // Fareye basildiginda yeni bir cizgi baslat
                List<Point> yeniCizgi = new ArrayList<>();
                yeniCizgi.add(new Point(olay.getX(), olay.getY()));
                cizimKatmanlari.add(yeniCizgi);
            }
        });
    }

    private List<Point> sonCizgi() {
        return cizimKatmanlari.get(cizimKatmanlari.size() - 1);
    }

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);
        for (List<Point> cizgi : cizimKatmanlari) {
            noktalariBirlestirerekCiz(tuval, cizgi);
        }
    }

    private void noktalariBirlestirerekCiz(Graphics tuval, List<Point> noktalar) {
        Point onceki = noktalar.get(0);
        for (Point simdiki : noktalar) {
            tuval.drawLine(onceki.x, onceki.y, simdiki.x, simdiki.y);
            onceki = simdiki;
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            JFrame pencere = new JFrame("Basit Cizim Programi");
            pencere.getContentPane().add(new BasitCizimPaneli(), BorderLayout.CENTER);
            pencere.setDefaultCloseOperation(WindowConstants.EXIT_ON_CLOSE);
            pencere.setSize(400, 300);
            pencere.setVisible(true);
        });
    }
}

import org.mongodb.morphia.Datastore;
import org.mongodb.morphia.query.Query;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Repository;
import lombok.NonNull;

import java.util.List;

@Repository
public class UserRepository extends AbstractRepository<User> {

    @Autowired
    private Datastore datastore;

    public UserRepository() {
        super(User.class);
    }

    public List<User> findUsers() {
        Query<User> query = datastore.createQuery(User.class);
        return query.asList();
    }

    public User findUserByUsername(@NonNull String username) {
        Query<User> query = datastore.createQuery(User.class)
                .field("username").equal(username);
        return query.get();
    }

    public void saveUser(@NonNull User user) {
        datastore.save(user);
    }

    public void updateUser(@NonNull User user) {
        Query<User> query = datastore.createQuery(User.class)
                .field("username").equal(user.getUsername());

        datastore.update(query, datastore.createUpdateOperations(User.class)
                .set("failedLoginAttempts", user.getFailedLoginAttempts())
                .set("lastLogin", user.getLastLogin()));
    }

    public void incrementFailedLoginAttempts(@NonNull String username) {
        Query<User> query = datastore.createQuery(User.class)
                .field("username").equal(username);

        datastore.update(query, datastore.createUpdateOperations(User.class)
                .inc("failedLoginAttempts", 1));
    }

    public void resetFailedLoginAttempts(@NonNull String username) {
        Query<User> query = datastore.createQuery(User.class)
                .field("username").equal(username);

        datastore.update(query, datastore.createUpdateOperations(User.class)
                .set("failedLoginAttempts", 0));
    }
}

