public Observable<ServiceResponse<String>> getContentWithServiceResponseAsync(String resourceGroupName, String automationAccountName, String configurationName) {
    // Validate the input parameters
    if (resourceGroupName == null || resourceGroupName.isEmpty()) {
        throw new IllegalArgumentException("resourceGroupName cannot be null or empty");
    }
    if (automationAccountName == null || automationAccountName.isEmpty()) {
        throw new IllegalArgumentException("automationAccountName cannot be null or empty");
    }
    if (configurationName == null || configurationName.isEmpty()) {
        throw new IllegalArgumentException("configurationName cannot be null or empty");
    }

    // Construct the URL for the API call
    String url = String.format("https://management.azure.com/subscriptions/%s/resourceGroups/%s/providers/Microsoft.Automation/automationAccounts/%s/configurations/%s/content?api-version=2015-10-31",
            subscriptionId, resourceGroupName, automationAccountName, configurationName);

    // Create the request
    HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("Authorization", "Bearer " + accessToken)
            .header("Content-Type", "application/json")
            .GET()
            .build();

    // Send the request and handle the response
    return Observable.create(emitter -> {
        HttpClient client = HttpClient.newHttpClient();
        client.sendAsync(request, HttpResponse.BodyHandlers.ofString())
                .thenApply(response -> {
                    if (response.statusCode() == 200) {
                        return new ServiceResponse<>(response.body(), response.statusCode());
                    } else {
                        throw new RuntimeException("Failed to retrieve configuration content: " + response.statusCode());
                    }
                })
                .thenAccept(emitter::onNext)
                .exceptionally(ex -> {
                    emitter.onError(ex);
                    return null;
                });
    });
}

class Main {
    public String reversePrefix(String word, char ch) {
        StringBuffer sb = new StringBuffer();
        for(int i = 0;i<word.length();i++) {
            if(word.charAt(i) == ch) {
                sb.append(word.substring(0,i+1)).reverse();
                sb.append(word.substring(i+1));
                break;
            }
        }
        if(sb.length()!=word.length())
            return word;
        else
            return sb.toString();
    }
}

class Counter {
    public int minFlipsMonoIncr(String S) {
        int[] oneCount = new int[S.length() + 1];
        for (int i = 1; i <= S.length(); i++) {
            oneCount[i] = (S.charAt(i - 1) == '1' ? 1 : 0) + oneCount[i - 1];
        }
        int min = Integer.MAX_VALUE;
        for (int i = 0; i <= S.length(); i++) {
            min = Math.min(min, oneCount[i] + S.length() - i - (oneCount[S.length()] - oneCount[i]));
        }
        return min;
    }
}

