class Tree {
    public int twoSumLessThanK(int[] A, int K) {
        Arrays.sort(A);
        if(A.length <= 1)
            return -1;
        if(A[0]+ A[1]>=K)
            return -1;
        int font = 0;
        int last = A.length-1;
        int min = 2000;
        while(font <last ){
            if(A[last]+ A[font]>=K)
            {
                last --;
            }else{
                min =Math.min(min, K - A[last]- A[font]);
                font ++;
            }
        }
        return K-min;
    }
}

