import java.util.InputMismatchException;

public class E1406D {

    public static void main(String[] args) {

        FastIO io = new FastIO();

        int n = io.nextInt();

        long[] changes = new long[n - 1];

        long init = io.nextInt();

        long last = init;

        long sumPosChange = 0;

        for (int i = 0; i < n - 1; i++) {

            int cur = io.nextInt();

            changes[i] = cur - last;

            if (changes[i] > 0) sumPosChange += changes[i];

            last = cur;

        }

        if (sumPosChange + init > 0) {

            io.println((sumPosChange + init + 1) / 2);

        } else {

            io.println((sumPosChange + init) / 2);

        }

        int q = io.nextInt();

        while (q-- > 0) {

            int l = io.nextInt() - 1;

            int r = io.nextInt() - 1;

            int v = io.nextInt();

            if (l == 0) init += v;

            else {

                long newVal = changes[l - 1] + v;

                if (newVal >= 0 && changes[l - 1] >= 0) sumPosChange += v;

                else if (newVal <= 0 && changes[l - 1] >= 0) sumPosChange -= changes[l - 1];

                else if (newVal >= 0 && changes[l - 1] <= 0) sumPosChange += newVal;

                changes[l - 1] = newVal;

            }

            if (r < n - 1) {

                v = -v;

                long newVal = changes[r] + v;

                if (newVal >= 0 && changes[r] >= 0) sumPosChange += v;

                else if (newVal <= 0 && changes[r] >= 0) sumPosChange -= changes[r];

                else if (newVal >= 0 && changes[r] <= 0) sumPosChange += newVal;

                changes[r] = newVal;

            }

            if (sumPosChange + init > 0) {

                io.println((sumPosChange + init + 1) / 2);

            } else {

                io.println((sumPosChange + init) / 2);

            }

        }

        io.flush();

    }

    private static class FastIO extends PrintWriter {

        private InputStream stream;

        private byte[] buf = new byte[1 << 16];

        private int curChar, numChars;

        // standard input

        public FastIO() {

            this(System.in, System.out);

        }

        public FastIO(InputStream i, OutputStream o) {

            super(o);

            stream = i;

        }

        // file input

        public FastIO(String i, String o) throws IOException {

            super(new FileWriter(o));

            stream = new FileInputStream(i);

        }

