public class MianChowla {
    public static void main(String[] args) {
        int n = 100;
        List<Integer> mc = new ArrayList<>(Arrays.asList(1));
        Set<Integer> sums = new HashSet<>(Arrays.asList(2));
        Instant st = Instant.now();
        for (int i = 1; i < n; i++) {
            for (int j = mc.get(i - 1) + 1; ; j++) {
                mc.add(j);
                List<Integer> ts = new ArrayList<>();
                for (int k = 0; k <= i; k++) {
                    int sum = mc.get(k) + j;
                    if (sums.contains(sum)) {
                        ts.clear();
                        break;
                    }
                    ts.add(sum);
                }
                if (ts.size() > 0) {
                    sums.addAll(ts);
                    break;
                }
            }
        }
        Instant et = Instant.now();
        String s = " of the Mian-Chowla sequence are:\n";
        System.out.println("The first 30 terms" + s + mc.subList(0, 29).stream().map(String::valueOf).collect(Collectors.joining(" ")));
        System.out.println("\nTerms 91 to 100" + s + mc.subList(90, 99).stream().map(String::valueOf).collect(Collectors.joining(" ")));
        System.out.println("\nComputation time was " + Duration.between(st, et).toMillis() + "ms.");
    }
}

import java.util.*;
