public class practice {

    public static void main(String[] args) throws IOException {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(new BufferedWriter(new PrintWriter(System.out)));
        StringBuilder sb = new StringBuilder();

        int t = Integer.parseInt(br.readLine());

        while (t --> 0) {

            int n = Integer.parseInt(br.readLine());

            StringTokenizer st = new StringTokenizer(br.readLine());
            Map<Integer, Integer> map = new HashMap<>() {{ put(0, 0); put(1, 0); }};
            int arr[] = new int[n];

            for (int i = 0; i < n; i++) {

                arr[i] = Integer.parseInt(st.nextToken());
                map.put(arr[i] % 2, map.getOrDefault(arr[i] % 2, 0) + 1);
            }

            if (map.get(0) % 2 == 0 && map.get(1) % 2 == 0) sb.append("Yes");
            else {

                Arrays.sort(arr);
                boolean flag = false;

                for (int i = 0; i < n - 1; i++) {

                    if (arr[i] + 1 == arr[i + 1]) {

                        flag = true;
                        break;
                    }
                }

                sb.append(flag ? "Yes" : "No");
            }

            sb.append("\n");
        }

        pw.println(sb.toString().trim());
        pw.close();
        br.close();
    }
}

