   public static void main (String[] args) throws java.lang.Exception

    {

      BufferedReader br=new BufferedReader(new InputStreamReader(System.in));

      StringTokenizer st=new StringTokenizer(br.readLine());

      long H=Long.parseLong(st.nextToken());

      int n=Integer.parseInt(st.nextToken());

      int a[]=new int[n];

      st=new StringTokenizer(br.readLine());

      long prefix[]=new long[n];

      long sum=0;

      long min=Long.MAX_VALUE;

      for(int i=0;i<n;i++){

         a[i]=Integer.parseInt(st.nextToken());

         sum+=a[i];

         prefix[i]=sum;

         min=Math.min(min,prefix[i]);

      }

      if(prefix[n-1]>=0){

         if(H+min>0){

            System.out.print(-1);

         }

         else{

            for(int i=0;i<n;i++){

               if(prefix[i]+H<=0){

                  System.out.print((i+1));

                  break;

               }

            }

         }

      }

      else{

         if(H+min<=0){

            for(int i=0;i<n;i++){

               if(prefix[i]+H<=0){

                  System.out.print((i+1));

                  break;

               }

            }

         }

         else{

            long k=(long)Math.ceil((H+min)/(double)Math.abs(prefix[n-1]));

            H=H+k*prefix[n-1];

            long time=k*n;

            for(int i=0;i<n;i++){

               if(prefix[i]+H<=0){

                  time=time+i+1;

                  break;

               }

            }

            System.out.print(time);

         }

      }

    }

}

import java.util.Scanner;

public class PointPosition {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter three points
        System.out.print("Enter three points for p0, p1, and p2: ");
        double x0 = input.nextDouble();
        double y0 = input.nextDouble();
        double x1 = input.nextDouble();
        double y1 = input.nextDouble();
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();

        // Determine the position of p2 relative to the line from p0 to p1
        double position = (x1 - x0) * (y2 - y0) - (x2 - x0) * (y1 - y0);

        // Display the result
        if (position > 0) {
            System.out.println("p2 is on the left side of the line from p0 to p1");
        } else if (position < 0) {
            System.out.println("p2 is on the right side of the line from p0 to p1");
        } else {
            System.out.println("p2 is on the same line as the line from p0 to p1");
        }
    }
}

