import java.util.LinkedList;
import java.util.List;

/**
 * ConfigurationValue class encapsulates a configuration option representing
 * command-line arguments and related metadata.
 */
public class ConfigurationValue {

    private String buffer; // Holds the raw command-line input
    private String var; // Configuration variable name
    private List<String> args; // List of associated arguments
    private String source; // Source from which the configuration was derived
    private int line; // Line number in the configuration
    private String context; // Additional context regarding the configuration

    /**
     * Constructor to initialize ConfigurationValue with necessary parameters.
     *
     * @param buffer The raw command-line input as a string.
     * @param var The name of the configuration variable.
     * @param source The source of the configuration.
     * @param line The line number of the configuration.
     * @param context The context of the configuration.
     */
    public ConfigurationValue(String buffer, String var, String source, int line, String context) {
        this.buffer = buffer;
        this.var = var;
        this.source = source;
        this.line = line;
        this.context = context;
        this.args = new LinkedList<>();
        parseArguments();
    }

    /**
     * Parses the raw command-line input and populates args list.
     */
    private void parseArguments() {
        String[] tokens = buffer.split("\\s+"); // Split the buffer by whitespace
        for (String token : tokens) {
            if (!token.trim().isEmpty()) {
                args.add(token); // Add non-empty tokens to the args list
            }
        }
    }

    /**
     * Returns the list of associated arguments.
     *
     * @return List of arguments.
     */
    public List<String> getArgs() {
        return args;
    }

    /**
     * Returns the raw command-line input.
     *
     * @return The raw input buffer.
     */
    public String getBuffer() {
        return buffer;
    }

    /**
     * Returns the source of the configuration.
     *
     * @return The configuration source.
     */
    public String getSource() {
        return source;
    }

    /**
     * Returns the line number in the configuration.
     *
     * @return The line number.
     */
    public int getLine() {
        return line;
    }

    /**
     * Returns the name of the configuration variable.
     *
     * @return The variable name.
     */
    public String getVar() {
        return var;
    }

