            return queryString;
        }
        StringBuilder sb = new StringBuilder(queryString);
        sb.append(" ORDER BY ");
        sb.append(getAlias(queryString));
        sb.append(".");
        sb.append(propertyPath);
        sb.append(" ");
        sb.append(asc ? "ASC" : "DESC");
        return sb.toString();
    }

/**
 * An interface for identifying objects that can be considered "empty".
 */
public interface Emptiable {

    /**
     * Checks if the object is considered empty.  The definition of "empty"
     * is specific to the implementing class.
     *
     * @return {@code true} if the object is empty, {@code false} otherwise.
     */
    boolean isEmpty();

    /**
     * Example of a class implementing the Emptiable interface.
     * Note: This is just for demonstration and not part of the core interface definition.
     */
    class ExampleClass implements Emptiable {

        private String data;

        public ExampleClass(String data) {
            this.data = data;
        }

        @Override
        public boolean isEmpty() {
            return data == null || data.isEmpty();
        }

        public static void main(String[] args) {
            ExampleClass emptyExample = new ExampleClass(null);
            ExampleClass nonEmptyExample = new ExampleClass("Some data");

            System.out.println("Empty example is empty: " + emptyExample.isEmpty());
            System.out.println("Non-empty example is empty: " + nonEmptyExample.isEmpty());
        }
    }
}

