class Writer {
    public boolean canTraverseAllPairs(int[] nums) {

        Map<Integer, Set<Integer>> numMap = new HashMap<>();
        Map<Integer, Set<Integer>> primeMap = new HashMap<>();

        for(int i = 0; i < nums.length; i++){
            int n = nums[i];
            int p = 2;
            Set<Integer> numSet = new HashSet<>();
            while(n != 1){
                if(n % p == 0){

                    Set<Integer> set = primeMap.getOrDefault(p, new HashSet<Integer>());
                    set.add(i);
                    primeMap.put(p, set);

                    numSet.add(p);
                    n /= p;
                }
                p++;
                if(p >= 350){
                    Set<Integer> set = primeMap.getOrDefault(n, new HashSet<Integer>());
                    set.add(i);
                    primeMap.put(n, set);

                    numSet.add(n);
                    n = 1;
                }
            }
            numMap.put(i, numSet);
        }

        //System.out.println(numMap);
        //System.out.println(primeMap);

        Set<Integer> visited = new HashSet<>();
        Queue<Integer> Q = new LinkedList<>();
        Q.add(0);
        visited.add(0);

        Set<Integer> visitedPrimes = new HashSet<>();

        while(!Q.isEmpty()){
            int size = Q.size();
            for(int i = 0; i < size; i++){
                int cur = Q.poll();
                //System.out.println("cur = " + cur);
                Set<Integer> primes = numMap.get(cur);
                //System.out.println("get primes = " + primes);
                for(int p : primes){
                    if(visitedPrimes.contains(p)) continue;
                    visitedPrimes.add(p);
                    //System.out.println("get prime = " + p);
                    Set<Integer> nexts = primeMap.get(p);
                    //System.out.println("get nexts = " + nexts);
                    for(int n : nexts){
                        if(!visited.contains(n)){
                            visited.add(n);
                            Q.add(n);
                        }
                    }
                }
            }
        }
        //System.out.println(visited);
        return visited.size() == nums.length;
    }
}

import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class BytesArray {
    private byte[] bytes;
    private int offset;
    private int length;

    public BytesArray(byte[] initialData) {
        if (initialData == null) {
            throw new IllegalArgumentException("Initial data cannot be null");
        }
        this.bytes = Arrays.copyOf(initialData, initialData.length);
        this.length = initialData.length;
        this.offset = 0;
    }

    public BytesArray(int capacity) {
        if (capacity < 0) {
            throw new IllegalArgumentException("Capacity cannot be negative");
        }
        this.bytes = new byte[capacity];
        this.length = 0;
        this.offset = 0;
    }

    public void write(byte[] newBytes) {
        if (newBytes == null || newBytes.length == 0) {
            return;
        }
        ensureCapacity(length + newBytes.length);
        System.arraycopy(newBytes, 0, bytes, length, newBytes.length);
        length += newBytes.length;
    }

    public byte get(int index) {
        checkBounds(index);
        return bytes[offset + index];
    }

    public int indexOf(byte value) {
        for (int i = offset; i < offset + length; i++) {
            if (bytes[i] == value) {
                return i - offset;
            }
        }
        return -1;
    }

    public BytesArray slice(int start, int end) {
        if (start < 0 || end > length || start >= end) {
            throw new IllegalArgumentException("Invalid slice parameters");
        }
        int newSize = end - start;
        BytesArray slicedArray = new BytesArray(newSize);
        System.arraycopy(bytes, offset + start, slicedArray.bytes, 0, newSize);
        slicedArray.length = newSize;
        return slicedArray;
    }

    public byte[] toBytes() {
        return Arrays.copyOfRange(bytes, offset, offset + length);
    }

    public String toUtf8() {
        return new String(toBytes(), StandardCharsets.UTF_8);
    }

    private void checkBounds(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("Index out of bounds: " + index);
        }
    }

    private void ensureCapacity(int minCapacity) {
        if (minCapacity > bytes.length) {
            int newSize = Math.max(bytes.length * 2, minCapacity);
            bytes = Arrays.copyOf(bytes, newSize);
        }
    }

    public int length() {
        return length;
    }

    public void clear() {
        length = 0;
    }

