        try {

import java.util.Arrays;
import java.util.stream.IntStream;
 
public class HofstadterConway {
 
    public static int[] genHofstadterConway(int max) {
        int[] result = new int[max];
        result[0] = result[1] = 1;
        for (int ix = 2; ix < max; ix++)
            result[ix] = result[result[ix - 1] - 1] + result[ix - result[ix - 1]];
        return result;
    }
 
    public static void main(String[] args) {
        double[] adiv = new double[1 << 20];
        {
            int[] a = genHofstadterConway(1 << 20);
            for (int i = 0; i < 1 << 20; i++)
                adiv[i] = a[i] / (double) (i + 1);
        }
        for (int p = 2; p <= 20; p++) {
            int[] max = IntStream.range((1 << (p - 1)) - 1, (1 << p) - (1 << (p - 1)))
                   .mapToObj(ix -> new int[]{ix + 1, adiv[ix]})
                   .max((x, y) -> Double.compare(y[1], x[1]))
                   .get();
            System.out.printf("Maximum from 2^%d to 2^%d is %f at %d%n",
                    p - 1, p, max[1], max[0]);
        }
        System.out.printf("The winning number is %d.%n",
                IntStream.range(0, 1 << 20)
                       .filter(i -> (adiv[i] > 0.55))
                       .max()
                       .getAsInt() + 1
        );
    }
}

import java.util.List;
import java.util.function.Function;

public class DoubleSeries extends TimeSeries<Double> {
    String mName;

    DoubleSeries(List<Entry<Double>> data, String name) {
        super(data);
        mName = name;
    }

    public DoubleSeries(String name) {
        super();
        mName = name;
    }

    public String getName() {
        return mName;
    }

    public void setName(String name) {
        mName = name;
    }

    public DoubleSeries merge(DoubleSeries other, MergeFunction<Double, Double> f) {
        return new DoubleSeries(DoubleSeries.merge(this, other, f).mData, mName);
    }

    public DoubleSeries mapToDouble(Function<Double, Double> f) {
        return new DoubleSeries(map(f).mData, mName);
    }

    public DoubleSeries plus(DoubleSeries other) {
        return merge(other, (x, y) -> x + y);
    }

    public DoubleSeries plus(double other) {
        return mapToDouble(x -> x + other);
    }

    public DoubleSeries mul(DoubleSeries other) {
        return merge(other, (x, y) -> x * y);
    }

    public DoubleSeries mul(double factor) {
        return mapToDouble(x -> x * factor);
    }

    public DoubleSeries div(DoubleSeries other) {
        return merge(other, (x, y) -> x / y);
    }

    public DoubleSeries returns() {
        return this.div(lag(1)).plus(-1);
    }

    public double getLast() {
        return getData().get(size() - 1).getItem();
    }

    public DoubleSeries tail(int n) {
        return new DoubleSeries(getData().subList(size() - n, size()), getName());
    }

    public DoubleSeries returns(int days) {
        return this.div(lag(days)).plus(-1);
    }

    public double[] toArray() {
        return stream().mapToDouble(Entry::getItem).toArray();
    }

    @Override public DoubleSeries toAscending() {
        return new DoubleSeries(super.toAscending().mData, getName());
    }

    @Override public DoubleSeries toDescending() {
        return new DoubleSeries(super.toDescending().mData, getName());
    }

    @Override public DoubleSeries lag(int k) {
        return new DoubleSeries(super.lag(k).mData, getName());
    }

    @Override public String toString() {
        return mData.isEmpty() ? "DoubleSeries{empty}" :
            "DoubleSeries{" +
                "mName=" + mName +
                ", from=" + mData.get(0).getInstant() +
                ", to=" + mData.get(mData.size() - 1).getInstant() +
                ", size=" + mData.size() +
                '}';
    }
}

import java.util.Scanner;

public class Faktoriyel {

    // Rekursif olarak faktoriyel hesaplayan metod
    public static int recursiveFaktoriyel(int sayi) {
        int sonuc = 0; // Baslangic degeri
        // Eger sayi 0 ise, faktoriyel 1 olarak kabul edilir
        if (sayi == sonuc) {
            return sonuc + 1;
        }
        // Aksi takdirde, ozyinelemeli olarak sayi * (sayi-1)'in faktoriyeli hesaplanir
        return sayi * recursiveFaktoriyel(sayi - 1);
    }

    // Dongu ile faktoriyel hesaplayan metod
    public static int iterativeFaktoriyel(int sayi) {
        int sonuc = 1; // Sonuc 1 olarak alinir

        // 1'den sayiya kadar olan sayilari carpip faktoriyel hesaplanir
        for (int i = 1; i <= sayi; i++) {
            sonuc *= i;
        }
        return sonuc;
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        System.out.print("Faktoriyelini hesaplamak icin bir sayi girin: ");
        int sayi = sc.nextInt();
        sc.close();

        // Sonucu ekrana yazdir
        System.out.println(sayi + " sayisinin faktoriyeli (iterative): " + iterativeFaktoriyel(sayi));
        System.out.println(sayi + " sayisinin faktoriyeli (rekursive): " + recursiveFaktoriyel(sayi));
    }
}

private Retryer<Void> buildRetryer(State state) {
    RetryerBuilder<Void> retryerBuilder;

    if (this instanceof Retriable) {
        retryerBuilder = ((Retriable) this).getRetryerBuilder();
    } else {
        retryerBuilder = DEFAULT_RETRYER_BUILDER;
    }

    Retryer<Void> retryer = retryerBuilder.build();

    if (GobblinMetrics.isEnabled()) {
        retryer = new MetricsAwareRetryer<>(retryer, GobblinMetrics.getInstance());
    }

    return retryer;
}

