import biz.ganttproject.core.task.dependency.TaskDependency;
import biz.ganttproject.core.time.GanttCalendar;
import java.util.Date;

public interface TaskDependencyConstraint {
  enum Type {
    FINISH_START,
    START_START
  }

  Type getType();

  void setTaskDependency(TaskDependency dependency);

  Collision getCollision();

  Collision getBackwardCollision(GanttCalendar startDate);

  String getName();

  ActivityBinding getActivityBinding();

  interface Collision {
    Date getAcceptableStart();

    int getVariation();

    boolean isActive();
  }

  String getPersistentValue();

  TaskDependencyConstraint cloneConstraint();

  class DefaultCollision implements Collision {
    private final Date myAcceptableStart;
    private final int myVariation;
    private final boolean isActive;

    public static final int NO_VARIATION = 0;
    public static final int START_EARLIER_VARIATION = 1;
    public static final int START_LATER_VARIATION = 2;

    public DefaultCollision(Date acceptableStart, int variation, boolean isActive) {
      myAcceptableStart = acceptableStart;
      myVariation = variation;
      this.isActive = isActive;
    }

    @Override
    public Date getAcceptableStart() {
      return myAcceptableStart;
    }

    @Override
    public int getVariation() {
      return myVariation;
    }

    @Override
    public boolean isActive() {
      return isActive;
    }
  }

  static Type fromPersistentValue(String persistentValue) {
    if ("finishStart".equals(persistentValue)) {
      return Type.FINISH_START;
    }
    if ("startStart".equals(persistentValue)) {
      return Type.START_START;
    }
    throw new IllegalArgumentException(
        "Unsupported persistent value=" + persistentValue);
  }
}

class FinishStartConstraint implements TaskDependencyConstraint {

  private TaskDependency myDependency;

  @Override
  public Type getType() {
    return Type.FINISH_START;
  }

  @Override
  public void setTaskDependency(TaskDependency dependency) {
    myDependency = dependency;
  }

  @Override
  public Collision getCollision() {
    return null;
  }

  @Override
  public String getName() {
    return "Finish-Start";
  }
  @Override
  public Collision getBackwardCollision(GanttCalendar startDate){
      return null;
  }

  @Override
  public ActivityBinding getActivityBinding() {
    return null;
  }

  @Override
  public String getPersistentValue() {
    return "finishStart";
  }

  @Override
  public TaskDependencyConstraint cloneConstraint() {
    return new FinishStartConstraint();
  }
}

import java.net.*;
import java.io.*;

public class ChatSunucu {

    public static void main(String[] args) throws IOException {
        try (// Bir sunucu soketi olustur
        ServerSocket sunucuSoketi = new ServerSocket(8000)) {
            System.out.println("Sunucu baslatildi");

            // Bir baglanti istegi bekle
            Socket soket = sunucuSoketi.accept();

            System.out.println("Istemci baglandi");

            // Veri alisverisi icin girdi ve cikti akislari olustur
            DataInputStream istemcidenGelenVeri = new DataInputStream(soket.getInputStream());
            DataOutputStream istemciyeGidenVeri = new DataOutputStream(soket.getOutputStream());

            while (true) {
                // Istemciden bir mesaj oku
                String mesaj = istemcidenGelenVeri.readUTF();

                // Mesaji geri gonder
                istemciyeGidenVeri.writeUTF(mesaj);
            }
        }
    }
}

