public class Guitar implements Comparable<Guitar> {

    private String serialNumber;
    private double price;
    private String builder;
    private String model;
    private String backWood;
    private String topWood;

    public Guitar() {
    }

    public Guitar(String serialNumber, double price, String builder, String model, String backWood, String topWood) {
        this.serialNumber = serialNumber;
        this.price = price;
        this.builder = builder;
        this.model = model;
        this.backWood = backWood;
        this.topWood = topWood;
    }

    public String getSerialNumber() {
        return serialNumber;
    }

    public void setSerialNumber(String serialNumber) {
        if (!serialNumber.isEmpty()) {
            this.serialNumber = serialNumber;
        }
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        this.price = price;
    }

    public String getBuilder() {
        return builder;
    }

    public void setBuilder(String builder) {
        this.builder = builder;
    }

    public String getModel() {
        return model;
    }

    public void setModel(String model) {
        this.model = model;
    }

    public String getBackWood() {
        return backWood;
    }

    public void setBackWood(String backWood) {
        this.backWood = backWood;
    }

    public String getTopWood() {
        return topWood;
    }

    public void setTopWood(String topWood) {
        this.topWood = topWood;
    }

    public void createSound() {
        System.out.println("serialNumber: " + getSerialNumber());
        System.out.println("Price: " + getPrice());
        System.out.println("Builder: " + getBuilder());
        System.out.println("Model: " + getModel());
        System.out.println("BackWood: " + getBackWood());
        System.out.println("TopWood: " + getTopWood());
    }

    @Override
    public String toString() {
        return "Guitar{" + "serialNumber=" + serialNumber + ", price=" + price + ", builder=" + builder + ", model=" + model + ", backWood=" + backWood + ", topWood=" + topWood + '}';
    }

    @Override
    public int compareTo(Guitar t) {
        if (this.getPrice() > t.getPrice()) {
            return 1;
        } else if(this.getPrice() < t.getPrice()){
            return -1;
        }else return this.getSerialNumber().compareTo(t.getSerialNumber());
    }
}

import com.example.notification.model.Notification;
import com.example.notification.model.User;
import com.example.notification.service.NotificationService;
import com.example.notification.service.UserService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import javax.servlet.http.HttpSession;
import java.io.IOException;
import java.util.List;

@Controller
@RequestMapping("/notifications")
public class NotificationController {

    @Autowired
    private NotificationService notificationService;

    @Autowired
    private UserService userService;

    @GetMapping("/all")
    public String showAllNotification(HttpSession session, Model model) {
        User user = (User) session.getAttribute("currentUser");
        if (user != null) {
            List<Notification> notificationList = notificationService.getNotificationsByUserId(user.getId());
            model.addAttribute("notifications", notificationList);
            return "notifications";
        }
        return "redirect:/login";
    }

    @GetMapping("/profile-picture/{userId}")
    @ResponseBody
    public byte[] getProfilePicture(@PathVariable Long userId) throws IOException {
        User user = userService.getUserById(userId);
        if (user != null && user.getProfilePicture() != null) {
            return user.getProfilePicture();
        }
        return new byte[0];
    }

    @PostMapping("/send")
