import java.util.Stack;
 
public class ShuntingYard {
 
    public static void main(String[] args) {
        String infix = "3 + 4 * 2 / ( 1 - 5 ) ^ 2 ^ 3";
        System.out.printf("infix:   %s%n", infix);
        System.out.printf("postfix: %s%n", infixToPostfix(infix));
    }
 
    static String infixToPostfix(String infix) {
        /* To find out the precedence, we take the index of the
           token in the ops string and divide by 2 (rounding down).
           This will give us: 0, 0, 1, 1, 2 */
        final String ops = "-+/*^";
 
        StringBuilder sb = new StringBuilder();
        Stack<Integer> s = new Stack<>();
 
        for (String token : infix.split("\\s")) {
            if (token.isEmpty())
                continue;
            char c = token.charAt(0);
            int idx = ops.indexOf(c);
 
            // check for operator
            if (idx != -1) {
                if (s.isEmpty())
                    s.push(idx);
 
                else {
                    while (!s.isEmpty()) {
                        int prec2 = s.peek() / 2;
                        int prec1 = idx / 2;
                        if (prec2 > prec1 || (prec2 == prec1 && c != '^'))
                            sb.append(ops.charAt(s.pop())).append(' ');
                        else break;
                    }
                    s.push(idx);
                }
            }
            else if (c == '(') {
                s.push(-2); // -2 stands for '('
            }
            else if (c == ')') {
                // until '(' on stack, pop operators.
                while (s.peek() != -2)
                    sb.append(ops.charAt(s.pop())).append(' ');
                s.pop();
            }
            else {
                sb.append(token).append(' ');
            }
        }
        while (!s.isEmpty())
            sb.append(ops.charAt(s.pop())).append(' ');
        return sb.toString();
    }
}

import com.sun.org.apache.xerces.internal.xs.XSSimpleType;
import java.util.ArrayList;
import java.util.List;

public class ValidatedInfo {
    private String normalizedValue;
    private Object actualValue;
    private XSSimpleType memberType;
    private XSSimpleType[] memberTypes;
    private List<XSSimpleType> itemValueTypes;

    public void reset() {
        normalizedValue = null;
        actualValue = null;
        memberType = null;
        memberTypes = null;
        itemValueTypes = null;
    }

    public String stringValue() {
        if (normalizedValue != null) {
            return normalizedValue;
        } else if (actualValue != null) {
            return actualValue.toString();
        } else {
            return "";
        }
    }

    public void addMemberType(XSSimpleType type) {
        if (memberTypes == null) {
            memberTypes = new XSSimpleType[]{type};
        } else {
            XSSimpleType[] newTypes = new XSSimpleType[memberTypes.length + 1];
            System.arraycopy(memberTypes, 0, newTypes, 0, memberTypes.length);
            newTypes[memberTypes.length] = type;
            memberTypes = newTypes;
        }
    }

    public void addItemValueType(XSSimpleType type) {
        if (itemValueTypes == null) {
            itemValueTypes = new ArrayList<>();
        }
        itemValueTypes.add(type);
    }

    public String getNormalizedValue() {
        return normalizedValue;
    }

    public void setNormalizedValue(String normalizedValue) {
        this.normalizedValue = normalizedValue;
    }

    public Object getActualValue() {
        return actualValue;
    }

    public void setActualValue(Object actualValue) {
        this.actualValue = actualValue;
    }

    public XSSimpleType getMemberType() {
        return memberType;
    }

    public void setMemberType(XSSimpleType memberType) {
        this.memberType = memberType;
    }

    public XSSimpleType[] getMemberTypes() {
        return memberTypes != null ? memberTypes.clone() : null;
    }

    public void setMemberTypes(XSSimpleType[] memberTypes) {
        this.memberTypes = memberTypes != null ? memberTypes.clone() : null;
    }

    public List<XSSimpleType> getItemValueTypes() {
        return itemValueTypes != null ? new ArrayList<>(itemValueTypes) : null;
    }

    public void setItemValueTypes(List<XSSimpleType> itemValueTypes) {
        this.itemValueTypes = itemValueTypes != null ? new ArrayList<>(itemValueTypes) : null;
    }

    public boolean isUnionValidation() {
        return memberType != null && memberTypes != null;
    }

