import java.util.*;

public class Queue {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();

        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextInt();
        }

        int[] f = new int[(int) Math.pow(2, k)];
        for (int x = 0; x < (int) Math.pow(2, k); x++) {
            int[] dist = new int[n];
            for (int i = 0; i < n; i++) {
                dist[i] = a[i] ^ x;
            }
            Arrays.sort(dist);

            int minDiff = Integer.MAX_VALUE;
            for (int i = 0; i < n - 1; i++) {
                minDiff = Math.min(minDiff, dist[i + 1] - dist[i]);
            }
            f[x] = minDiff;
        }

        for (int ans : f) {
            System.out.print(ans + " ");
        }
    }
}

