public Character findEmojiByVendorCodePoint(String vendor, int point) {
    String emoji = Character.toChars(point).toString();
    String vendorEmoji = vendor + emoji;
    for (int i = 0; i < Character.codePointCount(vendorEmoji, 0, vendorEmoji.length()); i++) {
        int codePoint = Character.codePointAt(vendorEmoji, i);
        String name = Character.getName(codePoint);
        if (name.startsWith(vendor)) {
            return (char) codePoint;
        }
    }
    return null;
}

