# @Subject : https://leetcode-cn.com/problems/3sum/

def threeSum(nums):
    result = []
    if len(nums) < 3:
        return result
    nums.sort()
    for i in range(len(nums) - 2):
        if nums[i] > 0:
            break
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l = i + 1
        r = len(nums) - 1
        while l < r:
            sum = nums[i] + nums[l] + nums[r]
            if sum == 0:
                result.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l = l + 1
                while l < r and nums[r] == nums[r - 1]:
                    r = r - 1
                l = l + 1
                r = r - 1
            elif sum < 0:
                l = l + 1
            else:
                r = r - 1
    return result

if __name__ == '__main__':
    input_nums = [-1, 0, 1, 2, -1, -4]
    print(threeSum(input_nums))<|endoftext|>#!/usr/bin/env python3
