def isPalindrome(s):
    if len(s) == 0:
        return True
    s = s.lower()
    result = ''
    for i in range(len(s)):
        if s[i].isdigit() or s[i].isalpha():
            result = result + s[i]
    if result == result[::-1]:
        return True
    else:
        return False

