import com.datastax.driver.core.Cluster;
import com.datastax.driver.core.Session;
import com.datastax.driver.core.TableMetadata;

import java.util.Map;
import java.util.ArrayList;

public void createTableWithData(String table, Map<String, String> columns, ArrayList<String> pk) {
    Cluster cluster = Cluster.builder().addContactPoints(nodes).build();
    Session session = cluster.connect();

    StringBuilder sb = new StringBuilder("CREATE TABLE IF NOT EXISTS " + table + "(");

    for (Map.Entry<String, String> entry : columns.entrySet()) {
        sb.append(entry.getKey()).append(" ").append(entry.getValue()).append(", ");
    }

    sb.append("PRIMARY KEY (");
    for (String key : pk) {
        sb.append(key).append(", ");
    }
    sb.replace(sb.lastIndexOf(", "), sb.length(), "");
    sb.append("))");

    String query = sb.toString();
    session.execute(query);

    TableMetadata metadata = session.getCluster().getMetadata().getKeyspace(keyspace).getTable(table);
    System.out.printf("Table %s created%n", metadata.exportAsString());

    session.close();
    cluster.close();
}

