// Dummy interface for unmarshalling error responses.
interface Unmarshaller<T, R> {
    T unmarshall(R input);
}

// Dummy service exception representing an error from AWS services.
class AmazonServiceException extends Exception {
    public AmazonServiceException(String message) {
        super(message);
    }

    // Example of additional functionality common in AWS exceptions.
    public void setServiceErrorMessage(String errorMessage) {
        // Implementation for setting additional error details.
    }
}

// Abstract base class for error unmarshallers.
abstract class AbstractErrorUnmarshaller implements Unmarshaller<AmazonServiceException, String> {
    // The specific exception class to be instantiated.
    private Class<? extends AmazonServiceException> exceptionClass;

    // Default constructor using AmazonServiceException as the exception type.
    public AbstractErrorUnmarshaller() {
        this.exceptionClass = AmazonServiceException.class;
    }

    // Constructor accepting a custom exception class.
    public AbstractErrorUnmarshaller(Class<? extends AmazonServiceException> exceptionClass) {
        if (exceptionClass == null) {
            throw new IllegalArgumentException("Exception class cannot be null.");
        }
        this.exceptionClass = exceptionClass;
    }

    // Unmarshall the error response by creating a new exception instance.
    @Override
    public AmazonServiceException unmarshall(String errorMessage) {
        AmazonServiceException ase = newException(errorMessage);
        // Additional error processing can be performed here.
        return ase;
    }

    // Dynamically create an exception instance using reflection.
    protected AmazonServiceException newException(String errorMessage) {
        try {
            Constructor<? extends AmazonServiceException> ctor =
                exceptionClass.getConstructor(String.class);
            return ctor.newInstance(errorMessage);
        } catch (NoSuchMethodException e) {
            throw new RuntimeException("The exception class must have a constructor that accepts a String parameter.", e);
        } catch (InstantiationException e) {
            throw new RuntimeException("Unable to instantiate exception class.", e);
        } catch (IllegalAccessException e) {
            throw new RuntimeException("Access to the constructor is denied.", e);
        } catch (InvocationTargetException e) {
            throw new RuntimeException("Constructor threw an exception.", e);

