// Enum representing different states of the hash join probe process.
enum JoinState {
  MATCH_PROBE,       // Matching probe records against the hash table.
  PROCESS_RESIDUAL,  // Processing build records not matched.
  TERMINATED         // Join processing complete.
}

// Interface defining the behavior for executing the probe side of a hash join.
interface HashJoinProbe {
  // Initialize the probe with build and probe data batches, hash table, and execution context.
  void init(BuildDataBatch buildBatch, ProbeDataBatch probeBatch, HashTable hashTable, ExecutionContext context);

  // Process a batch of probe records. Returns true if more processing remains.
  boolean processProbeBatch();

  // Process build-side records that did not have any matching probe records.
  void processResidualBuild();

  // Check if the join operation is fully terminated.
  boolean isTerminated();
}

// Dummy data batch representing build side input.
class BuildDataBatch {
  List<String> records;

  BuildDataBatch() {
    records = new ArrayList<>();
  }

  // Stub method to add a record.
  void addRecord(String record) {
    records.add(record);
  }

  int size() {
    return records.size();
  }
}

// Dummy data batch representing probe side input.
class ProbeDataBatch {
  List<String> records;

  ProbeDataBatch() {
    records = new ArrayList<>();
  }

  // Stub method to add a record.
  void addRecord(String record) {
    records.add(record);
  }

  int size() {
    return records.size();
  }
}

// Dummy HashTable used during join processing.
class HashTable {
  // Simulating a hash table storing keys as strings.
  List<String> keys;

  HashTable() {
    keys = new ArrayList<>();
  }

  // Add a key to the hash table.
  void addKey(String key) {
    keys.add(key);
  }

  // Check if key exists within the hash table.
  boolean contains(String key) {
    return keys.contains(key);
  }
}

// Dummy ExecutionContext representing necessary configuration and memory management.
class ExecutionContext {
  // Maximum output records per batch.
  int outputLimit;

  ExecutionContext(int limit) {
    this.outputLimit = limit;
  }
}

