public class D {
    static long[] a;
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextLong();
        }
        if (n == 2) {
            System.out.println(-1);
            return;
        }
        long prev = a[0];
        long curr = a[1];
        int count = 0;
        for (int i = 2; i < n; i++) {
            long next = a[i];
            if (curr <= next) {
                count++;
                curr = next;
            } else {
                curr = curr ^ prev;
                prev = curr;
                curr = next;
            }
        }
        if (count == 0) {
            System.out.println(-1);
        } else {
            System.out.println(count);
        }
    }
}

