public class MultimapSideInputTest {

  private static final StringUtf8Coder CODER = StringUtf8Coder.of();

  @Test
  public void testGet() throws Exception {
    FakeBeamFnStateClient state =
        new FakeBeamFnStateClient(
            ImmutableMap.of(
                key("bundle", "view1", "a"),
                ImmutableMap.of("0", encode("a0"), "1", encode("a1")),
                key("bundle", "view1", "b"),
                ImmutableMap.of("0", encode("b0"))));
    MultimapSideInput<String, String> sideInput =
        new MultimapSideInput<>(state, "bundle", "view1", CODER, CODER);

    Assert.assertEquals(
        Iterables.size(sideInput.get("a")), 2);
    Assert.assertTrue(sideInput.get("a").contains("a0"));
    Assert.assertTrue(sideInput.get("a").contains("a1"));

    Assert.assertEquals(
        Iterables.size(sideInput.get("b")), 1);
    Assert.assertTrue(sideInput.get("b").contains("b0"));

    Assert.assertEquals(
        Iterables.size(sideInput.get("c")), 0);
  }

  private static BeamFnApi.StateKey key(String bundle, String view, String key) {
    return BeamFnApi.StateKey.newBuilder()
        .setMultimapSideInput(
            BeamFnApi.StateKey.MultimapSideInput.newBuilder()
                .setTransformId("transform")
                .setViewId(view)
                .setKey(encode(key))
                .build())
        .build();
  }

  private static byte[] encode(String value) {
    return CODER.encode(value);
  }
}

