public class Finder {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a String: ");
        String s = in.nextLine().trim();
        System.out.println("The number of uppercase letters in " + s + " is: " + numUpperCase(s, 0, 0));

    }

    static int numUpperCase(String str, int idx, int count) {
        if (idx == str.length()) {
            return count;
        }
        if (Character.isUpperCase(str.charAt(idx))) {
            count++;
        }
        return numUpperCase(str, ++idx, count);
    }
}

private ODocument getEdgeWithPossibleId(String start, String end, List<String> ids) {
    // Assuming you have a list of edges
    List<ODocument> edges = getEdges(start, end);

    // Iterate over the edges
    for (ODocument edge : edges) {
        // Get the id of the edge
        String edgeId = edge.getId();

        // Check if the id is in the list of ids
        if (ids.contains(edgeId)) {
            // If it is, return the edge
            return edge;
        }
    }

    // If no edge with a valid id is found, return the first edge
    if (!edges.isEmpty()) {
        return edges.get(0);
    }

    // If there are no edges, return null
    return null;
}

