public class Sqrt {
    public static void main(String[] args) {
        System.out.println(" n   f");
        List<Integer> squares = new ArrayList<>();
        for (int n = 1; n < 1000000; n++) {
            int v1 = f(n);
            int v2 = (int) Math.sqrt(v1);
            if (v1 == v2 * v2) squares.add(n);
            if (n < 23) System.out.println(String.format("%2d", n) + " : " + v1);
        }
        System.out.println();
        if (squares.size() == 0) System.out.println("There are no squares for n less than one million");
        else System.out.println("Squares are generated for the following values of n: " + squares);
    }

    public static int f(int n) {
        return n + (int) Math.floor(0.5 + Math.sqrt(n));
    }
}

