import java.util.HashMap;
import java.util.Scanner;

public class LongestStriketime {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt(); // Read the number of test cases

        while (t-- > 0) {
            int n = scanner.nextInt(); // Read the length of the array
            int k = scanner.nextInt(); // Read the integer k
            int[] a = new int[n];

            // Read the array elements
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }

            // Use a HashMap to count occurrences of each element
            HashMap<Integer, Integer> countMap = new HashMap<>();
            for (int num : a) {
                countMap.put(num, countMap.getOrDefault(num, 0) + 1);
            }

            // Find the first element that appears at least k times
            int firstElement = -1;
            for (int num : countMap.keySet()) {
                if (countMap.get(num) >= k) {
                    firstElement = num;
                    break;
                }
            }

            // If no such element is found, output "-1"
            if (firstElement == -1) {
                System.out.println("-1");
                continue;
            }

            // Find the last element that appears at least k times
            int lastElement = -1;
            for (int num : countMap.keySet()) {
                if (countMap.get(num) >= k) {
                    lastElement = num;
                }
            }

            // If the first and last elements are the same, output this pair
            if (firstElement == lastElement) {
                System.out.println(firstElement + " " + lastElement);
            } else {
                System.out.println("-1");
            }
        }

        scanner.close();
    }
}

