import java.util.Scanner;

public class ArtanSiraBesSayi {

    public static void main(String[] args) {
        Scanner giris = new Scanner(System.in);

        // Siralanacak bes deger icin dizi kullaniyoruz
        int[] degerler = new int[5];

        System.out.println("5 adet sayi giriniz:");
        int index = 0;
        while (index < degerler.length) {
            System.out.print((index + 1) + ". sayi: ");
            degerler[index] = giris.nextInt();
            index++;
        }

        giris.close();

        // Kabarcik siralama (bubble sort) mantigiyla kucukten buyuge diziyoruz
        for (int tur = 0; tur < degerler.length - 1; tur++) {
            for (int j = 0; j < degerler.length - 1 - tur; j++) {
                if (degerler[j] > degerler[j + 1]) {
                    int yer = degerler[j];
                    degerler[j] = degerler[j + 1];
                    degerler[j + 1] = yer;
                }
            }
        }

        System.out.println("Sayilar kucukten buyuge sirali:");
        for (int deger : degerler) {
            System.out.println(deger);
        }
    }
}

import com.mongodb.event.CommandListener;
import com.mongodb.event.CommandStartedEvent;
import com.mongodb.event.CommandSucceededEvent;
import com.mongodb.event.CommandFailedEvent;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import io.micrometer.core.instrument.Tag;
import java.util.List;
import java.util.ArrayList;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.TimeUnit;

public class MongoMetricsCommandListener implements CommandListener {
    private final MeterRegistry registry;
    private final MongoCommandTagsProvider tagsProvider;
    private final ConcurrentMap<Integer, CommandContext> activeCommands = new ConcurrentHashMap<>();

    public MongoMetricsCommandListener(MeterRegistry registry, MongoCommandTagsProvider tagsProvider) {
        this.registry = registry;
        this.tagsProvider = tagsProvider;
    }

    public MongoMetricsCommandListener(MeterRegistry registry) {
        this(registry, new DefaultMongoCommandTagsProvider());
    }

    @Override
    public void commandStarted(CommandStartedEvent event) {
        List<Tag> tags = tagsProvider.getTags(event);
        long startTime = System.nanoTime();
        activeCommands.put(event.getRequestId(), new CommandContext(startTime, tags));
    }

    @Override
    public void commandSucceeded(CommandSucceededEvent event) {
        CommandContext context = activeCommands.remove(event.getRequestId());
        if (context != null) {
            List<Tag> tags = new ArrayList<>(context.tags);
            tags.add(Tag.of("status", "SUCCESS"));
            timeCommand(context.startTime, tags);
        }
    }

    @Override
    public void commandFailed(CommandFailedEvent event) {
        CommandContext context = activeCommands.remove(event.getRequestId());
        if (context != null) {
            List<Tag> tags = new ArrayList<>(context.tags);
            tags.add(Tag.of("status", "FAILURE"));
            Throwable error = event.getThrowable();
            if (error != null) {
                tags.add(Tag.of("error", error.getClass().getSimpleName()));
            }
            timeCommand(context.startTime, tags);
        }
    }

    private void timeCommand(long startTime, List<Tag> tags) {
        long durationNanos = System.nanoTime() - startTime;
        Timer.builder("mongodb.command")
                .tags(tags)
                .register(registry)
                .record(durationNanos, TimeUnit.NANOSECONDS);
    }

