class Utils {
    public int[] pathsWithMaxScore(List<String> board) {
        int mod = 1000000007;

        // {value, count}
        int[][][] dp = new int[board.size()][board.get(0).length()][];

        for (int i = 0; i < board.size(); i++) {
            for (int j = 0; j < board.get(i).length(); j++) {
                char c = board.get(i).charAt(j);
                if (c == 'X') {
                    dp[i][j] = new int[] {-1, 0};
                } else if (c == 'E') {
                    dp[i][j] = new int[] {0, 1};
                } else if (c == 'S') {
                    dp[i][j] = new int[] {0, 0};
                } else {
                    dp[i][j] = new int[] {c - '0', 0};
                }

                //System.out.print(Arrays.toString(dp[i][j]) + ", ");
            }
            //System.out.println("");
        }

        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp[0].length; j++) {

                if ((i == 0 && j == 0) || dp[i][j][0] == -1) {
                    continue;
                }

                int[] left = getDp(dp, i, j - 1);
                int[] up = getDp(dp, i - 1, j);
                int[] leftUp = getDp(dp, i - 1, j - 1);

                if (left[0] == -1 && up[0] == -1 && leftUp[0] == -1) {
                    dp[i][j][0] = -1;
                    continue;
                }

                int max = Math.max(leftUp[0], Math.max(left[0], up[0]));
                dp[i][j][0] += max;
                if (left[0] == max) {
                    dp[i][j][1] = (dp[i][j][1] + left[1]) % mod;
                }
                if (up[0] == max) {
                    dp[i][j][1] = (dp[i][j][1] + up[1]) % mod;
                }
                if (leftUp[0] == max) {
                    dp[i][j][1] = (dp[i][j][1] + leftUp[1]) % mod;
                }

                //System.out.print(Arrays.toString(dp[i][j]) + ", ");
            }
            //System.out.println("");
        }

        if (dp[dp.length - 1][dp[0].length - 1][0] == -1) {
            return new int[] {0, 0};
        }
        return dp[dp.length - 1][dp[0].length - 1];
    }

    public int[] getDp(int[][][] dp, int i, int j) {
        if (i < 0 || j < 0) {
            return new int[] {-1, 0};
        }
        return dp[i][j];
    }
}

