            return "Yengec";
        }
        if ((ay == 7 && gun >= 23) || (ay == 8 && gun <= 22)) {
            return "Aslan";
        }
        if ((ay == 8 && gun >= 23) || (ay == 9 && gun <= 22)) {
            return "Basak";
