public class SquareFreeNumbers {
    public static boolean squareFree(int n) {
        if (n % 4 == 0) {
            return false;
        }
        int p = 3;
        while (p * p <= n) {
            int count = 0;
            while (n % p == 0) {
                count++;
                if (count > 1) {
                    return false;
                }
                n /= p;
            }
            p += 2;
        }
        return true;
    }

    public static void printSquareFreeNumbers(int from, int to) {
        System.out.printf("Square-free numbers between %d and %d:%n", from, to);
        StringBuilder line = new StringBuilder();
        for (int i = from; i <= to; i++) {
            if (squareFree(i)) {
                if (line.length() > 0) {
                    line.append(' ');
                }
                line.append(i);
                if (line.length() >= 80) {
                    System.out.println(line);
                    line.setLength(0);
                }
            }
        }
        if (line.length() > 0) {
            System.out.println(line);
        }
    }

    public static void printSquareFreeCount(int from, int to) {
        int count = 0;
        for (int i = from; i <= to; i++) {
            if (squareFree(i)) {
                count++;
            }
        }
        System.out.printf("Number of square-free numbers between %d and %d: %d%n", from, to, count);
    }

    public static void main(String[] args) {
        printSquareFreeNumbers(1, 145);
        printSquareFreeNumbers(1000000000000L, 1000000000145L);
        int n = 100;
        while (n <= 1000000) {
            printSquareFreeCount(1, n);
            n *= 10;
        }
    }
}

