/**
 * @param tasks a list of intervals representing the enqueue time and processing time of each task.
 * @return the order in which the tasks will be processed by the CPU.
 */
public List<Integer> leastInterval(int[][] tasks) {
    PriorityQueue<Task> queue = new PriorityQueue<>(Comparator.comparingInt(Task::getProcessingTime));
    int[] taskIndices = new int[tasks.length];
    Arrays.fill(taskIndices, -1);

    // Insert all the tasks into the queue with their enqueue time as the priority
    for (int i = 0; i < tasks.length; i++) {
        Task task = new Task(tasks[i][0], tasks[i][1]);
        queue.offer(task);
    }

    List<Integer> order = new ArrayList<>();
    int currentTime = 0;

    while (!queue.empty()) {
        Task currentTask = queue.poll();
        order.add(currentTask.getIndex());
        currentTime += currentTask.getProcessingTime();

        // Check if any tasks are available to insert into the queue
        while (!queue.empty() && queue.peek().getEnqueueTime() == currentTime) {
            Task nextTask = queue.poll();
            if (nextTask.getIndex() >= 0) {
                queue.offer(nextTask);
            }
        }

        // Increment the enqueue time of the remaining tasks in the queue
        for (Task task : queue) {
            task.setEnqueueTime(++currentTime);
        }
    }

    return order;
}

class Task implements Comparable<Task> {
    int index;
    int enqueueTime;
    int processingTime;

    public Task(int enqueueTime, int processingTime) {
        this.enqueueTime = enqueueTime;
        this.processingTime = processingTime;
        this.index = -1;
    }

    public int getIndex() {
        return index;
    }

    public int getEnqueueTime() {
        return enqueueTime;
    }

    public int getProcessingTime() {
        return processingTime;
    }

    @Override
    public int compareTo(Task other) {
        return Integer.compare(this.processingTime, other.processingTime);
    }
}

