public class Helper {
    public static void main(String[] args) {

        String[] packageParts = Exercise17_01.class.getPackage().getName().split("\\.");
        String filePath = packageParts[0] + File.separator + packageParts[1] + File.separator + "Helper.dat";
        if (!(new File(filePath).exists())) {
            try (FileOutputStream fis = new FileOutputStream(filePath)) {
                DataOutputStream dos = new DataOutputStream(fis);
                runCreateTestDatFile(dos);
            } catch (Exception e) {
                e.printStackTrace();
                System.out.println(e.getLocalizedMessage());
            }

        }
        try (FileInputStream fis = new FileInputStream(filePath)) {
            DataInputStream dis = new DataInputStream(fis);

            int sum = 0;
            int numIntegers = dis.available() / 4; // An integer is stored as 4 bytes

            System.out.print("The sum of: ");
            for (int i = 0; i < numIntegers; i++) {
                int n = dis.readInt();
                if (i == 0) {
                    System.out.print(n + "");
                } else {
                    System.out.print(" + " + n);
                }
                sum += n;
            }
            System.out.println(" = " + sum);

        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static void runCreateTestDatFile(DataOutputStream dos) throws IOException {
        for (int i = 0; i < 10; i++) {
            int n = (int) (1 + Math.random() * 10);
            dos.writeInt(n);
        }
        dos.flush();
        dos.close();

    }
}

import java.awt.*;
import javax.swing.*;
 
public class PinstripeDisplay extends JPanel {
 
    final int bands = 4;
 
    public PinstripeDisplay() {
        setPreferredSize(new Dimension(900, 600));
    }
 
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        int h = getHeight();
        for (int b = 1; b <= bands; b++) {
            for (int x = 0, colIndex = 0; x < getWidth(); x += b, colIndex++) {
                g.setColor(colIndex % 2 == 0 ? Color.white : Color.black);
                g.fillRect(x, (b - 1) * (h / bands), x + b, b * (h / bands));
            }
        }
    }
 
    public static void main(String[] args) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                JFrame f = new JFrame();
                f.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
                f.setTitle("PinstripeDisplay");
                f.add(new PinstripeDisplay(), BorderLayout.CENTER);
                f.pack();
                f.setLocationRelativeTo(null);
                f.setVisible(true);
            }
        });
    }
}

import java.net.*;
import java.io.*;
import java.util.Scanner;

/*
 * Minimal socket-based chat client. Connects to a local chat server,
 * relays whatever the user types, and prints the echoed response.
 */

public class ChatIstemci {

    public static void main(String[] args) throws IOException {
        try (Socket connection = new Socket("localhost", 8000)) {

            DataInputStream fromServer = new DataInputStream(connection.getInputStream());
            DataOutputStream toServer = new DataOutputStream(connection.getOutputStream());

            try (Scanner keyboard = new Scanner(System.in)) {
                while (true) {
                    String outgoing = keyboard.nextLine();
                    toServer.writeUTF(outgoing);

                    String incoming = fromServer.readUTF();
                    System.out.println(incoming);
                }
            }
        }
    }
}

