import java.util.Scanner;

public class Tree {
  public static void main(String[] args) {
    Scanner scanner = new Scanner(System.in);
    int n = scanner.nextInt();
    int[] a = new int[n];
    for (int i = 0; i < n; i++) {
      a[i] = scanner.nextInt();
    }

    helper(a, 0, n - 1);

  }

  static void helper(int[] a, int l, int r) {
    if (l == r) {
      System.out.println("! " + l);
      return;
    }

    int mid = (l + r) / 2;
    helper(a, l, mid);
    helper(a, mid + 1,r);

    int maxIndex = findMaxInSubarray(a, l, mid);
    int secondMax = findSecondMaxInSubarray(a, l, mid);
    findSecondMaxInMainArray(a, secondMax);

    System.out.println(! secondMax);
  }

  static int findMaxInSubarray(int[] a, int l, int r) {
    int max = a[l++];
    while (l <= r) {
      if (a[l] > max) {
        max = a[l++];
      }

    }
    return max;
  }

  static int findSecondMaxInSubarray(int[] a, int l, int r) {
    int secondMax = a[l++];
    while (l <= r) {
      if (a[l] > secondMax) {
        secondMax = a[l++];
      }

    }
    return secondMax;
  }

  static int findSecondMaxInMainArray(int[] a, int secondMax) {
    for (int i = 0; i < a.length; i++) {
      if (a[i] != secondMax && a[i] > secondMax) {
        System.out.println("! " + i);
        break;
      }
    }
  }

}

