/**
 * Reads a matrix, prints it, and reports its sum and average.
 */
public class Part1 {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter number of rows: ");
        int rows = scanner.nextInt();
        System.out.print("Enter number of cols: ");
        int cols = scanner.nextInt();
        int[][] matrix = new int[rows][cols];
        System.out.println("Enter the matrix");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                System.out.print("matrix[" + i + "][" + j + "]= ");
                matrix[i][j] = scanner.nextInt();
            }
        }
        System.out.println("Matrix inputted: ");
        int sum = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                System.out.print(matrix[i][j] + " ");
                sum += matrix[i][j];
            }
            System.out.println();
        }
        System.out.println("Sum: " + sum);
        System.out.println("Average: " + (float) sum / (rows * cols));
    }
}

import com.google.common.base.Joiner;
import com.google.common.collect.Iterables;
import eu.the5zig.mod.The5zigAPI;
import eu.the5zig.util.minecraft.ChatColor;
import java.util.Iterator;

public class ColorCommandHandler {

  private static final Iterable<ChatColor> RAINBOW_IT =
      Iterables.cycle(
          ChatColor.RED,
          ChatColor.GOLD,
          ChatColor.YELLOW,
          ChatColor.GREEN,
          ChatColor.AQUA,
          ChatColor.BLUE,
          ChatColor.LIGHT_PURPLE);

  public void run(String command, String[] args) {
    if (args.length == 0) {
      StringBuilder sb = new StringBuilder();
      for (ChatColor code : ChatColor.values()) {
        if (code.isFormat() || code.isColor()) {
          sb.append(getCode(code));
        }
      }
      The5zigAPI.getAPI().messagePlayer(sb.toString());
      return;
    }
    String message = Joiner.on(" ").join(args);
    Iterator<ChatColor> it = iterator();
    StringBuilder builder = new StringBuilder();
    for (char c : message.toCharArray()) {
      if (c != ' ') {
        builder.append(next(it));
      }
      builder.append(c);
    }
    sendPlayerMessage(builder.toString());
  }

  private String getCode(ChatColor code) {
    return code.toString() + code.getChar() + " ";
  }

  private Iterator<ChatColor> iterator() {
    return RAINBOW_IT.iterator();
  }

  private ChatColor next(Iterator<ChatColor> it) {
    return it.next();
  }

  private void sendPlayerMessage(String message) {
    The5zigAPI.getAPI().sendPlayerMessage(message);
  }
}

