@Override
    public Long generate() {

        long max = maximum.get();

        long identifier = atomicLong.incrementAndGet();

        if (identifier > max) {

            do {

                if (logger.isDebugEnabled())
                    logger.debug("About to request a pool of identifiers from database, maximum id: {}", max);

                synchronized (monitor) {

                    max = maximum.get();
                    identifier = atomicLong.incrementAndGet();

                    if (identifier >= max) {

                        try (Session session = driver.session()) {

                            try (Transaction transaction = session.beginTransaction()) {

                                Statement statement = new Statement("MERGE (g:`" + sequenceNodeLabel + "`) ON CREATE SET g.nextId = 1 ON MATCH SET g.nextId = g.nextId + {poolSize} RETURN g.nextId", Collections.singletonMap("poolSize", poolSize));

                                StatementResult result = transaction.run(statement);

                                if (result.hasNext()) {

                                    Record record = result.next();

                                    long nextId = record.get(0).asLong();

                                    atomicLong.set(nextId - poolSize);
                                    maximum.set(nextId);
                                }

                                transaction.success();
                            }
                        }

                        max = maximum.get();

                        identifier = atomicLong.incrementAndGet();

                        if (logger.isDebugEnabled())
                            logger.debug("Requested new pool of identifiers from database, current id: {}, maximum id: {}", identifier, max);
                    }
                    else if (logger.isDebugEnabled())
                        logger.debug("No need to request pool of identifiers, current id: {}, maximum id: {}", identifier, max);
                }
            }
            while (identifier > max);
        }
        else if (logger.isDebugEnabled())
            logger.debug("Current identifier: {}", identifier);

        return identifier;
    }

import java.security.MessageDigest;

import javax.enterprise.inject.Typed;

import org.apache.commons.codec.binary.Base64;

@Typed(PasswordEncryptor.class)
public class MD5PasswordEncryptor implements PasswordEncryptor
{
   private static final long serialVersionUID = 1422059557145039442L;

   @Override
   public String encodePassword(final String password, final Object salt)
   {
      try
      {
         MessageDigest digest = MessageDigest.getInstance("MD5");
         digest.reset();
         digest.update(salt.toString().getBytes());
         byte[] passwordHash = digest.digest(password.getBytes());

         Base64 encoder = new Base64();
         byte[] encoded = encoder.encode(passwordHash);
         return new String(encoded);
      }
      catch (Exception e)
      {
         throw new RuntimeException(e);
      }
   }

   @Override
   public boolean isPasswordValid(final String cypherPass, final String password, final Object salt)
   {
      return cypherPass.equals(this.encodePassword(password, salt));
   }

}

