"""

import math

def solution(arr):
    masks = {}
    for i, x in enumerate(arr):
        if x not in masks:
            masks[x] = set()
        masks[x].add(i)

    visited = set()
    to_visit = [0]

    moves = 0
    while to_visit:
        pivot_idx = to_visit.pop()
        if pivot_idx in visited:
            continue
        pos, right = pivot_idx, pivot_idx
        while pos in masks and right in masks[pos]:
            right += 1

        sub_array_len = right - pos
        if sub_array_len > 1:
            moves += 1

        visited |= set(range(pos + 1, right))

        for x in arr[pos:right]:
            if x not in visited:
                to_visit.append(arr.index(x))

    return moves

