        DIV('/', 2);
 
        public final char symbol;
        public final int precedence;
 
        BinaryOperator(char symbol, int precedence) {
            this.symbol = symbol;
            this.precedence = precedence;
        }
 
        public BigRational eval(BigRational leftValue, BigRational rightValue) {
            switch (this) {
                case ADD:
                    return leftValue.add(rightValue);
                case SUB:
                    return leftValue.subtract(rightValue);
                case MUL:
                    return leftValue.multiply(rightValue);
                case DIV:
                    return leftValue.divide(rightValue);
            }
            throw new IllegalStateException();
        }
 
        public static BinaryOperator forSymbol(char symbol) {
            for (BinaryOperator operator : values()) {
                if (operator.symbol == symbol) {
                    return operator;
                }
            }
            throw new IllegalArgumentException(String.valueOf(symbol));
        }
    }
 
    public static class Number implements Expression {
        private final BigRational number;
 
        public Number(BigRational number) {
            this.number = number;
        }
 
        @Override
        public BigRational eval() {
            return number;
        }
 
        @Override
        public String toString() {
            return number.toString();
        }
    }
 
    public static class BinaryExpression implements Expression {
        public final Expression leftOperand;
        public final BinaryOperator operator;
        public final Expression rightOperand;
 
        public BinaryExpression(Expression leftOperand, BinaryOperator operator, Expression rightOperand) {
            this.leftOperand = leftOperand;
            this.operator = operator;
            this.rightOperand = rightOperand;
        }
 
        @Override
        public BigRational eval() {
            BigRational leftValue = leftOperand.eval();
            BigRational rightValue = rightOperand.eval();
            return operator.eval(leftValue, rightValue);
        }
 
        @Override
        public String toString() {
            return "(" + leftOperand + " " + operator.symbol + " " + rightOperand + ")";
        }
    }

import com.github.mpkorstanje.simmetrics.StringDistance;
import com.github.mpkorstanje.simmetrics.StringDistances;
import com.github.mpkorstanje.simmetrics.builders.StringDistanceBuilder;
import com.github.mpkorstanje.simmetrics.tokenizers.Tokenizer;
import com.github.mpkorstanje.simmetrics.tokenizers.Tokenizers;
import java.util.List;

public class StringDistanceDemo {

    public static void main(String[] args) {
        example01();
        example02();
        example03();
    }

    private static void example01() {
        String str1 = "kitten";
        String str2 = "sitting";

        StringDistance metric = StringDistances.levenshtein();
        float distance = metric.distance(str1, str2);

        System.out.println("=== Example 1: Predefined Levenshtein ===");
        System.out.println("String 1: \"" + str1 + "\"");
        System.out.println("String 2: \"" + str2 + "\"");
        System.out.printf("Raw character distance: %.1f%n%n", distance);
    }

    private static void example02() {
        String str1 = "The quick brown fox";
        String str2 = "The lazy brown dog";

        StringDistanceBuilder builder = StringDistances.euclideanDistance();
        Tokenizer tokenizer = Tokenizers.whitespace();
        StringDistance metric = builder.tokenize(tokenizer).build();

        List<String> tokens1 = tokenizer.tokenize(str1);
        List<String> tokens2 = tokenizer.tokenize(str2);
        float distance = metric.distance(str1, str2);

        System.out.println("=== Example 2: Word Tokenization ===");
        System.out.println("Tokenizer: Whitespace");
        System.out.println("Tokens 1: " + tokens1);
        System.out.println("Tokens 2: " + tokens2);
        System.out.printf("Euclidean distance: %.2f%n%n", distance);
    }

    private static void example03() {
        String str1 = "artificial";
        String str2 = "artistic";

        StringDistanceBuilder builder = StringDistances.euclideanDistance();
        Tokenizer tokenizer = Tokenizers.qGram(3);
        StringDistance metric = builder.tokenize(tokenizer).build();

        List<String> tokens1 = tokenizer.tokenize(str1);
        List<String> tokens2 = tokenizer.tokenize(str2);
        float distance = metric.distance(str1, str2);

        System.out.println("=== Example 3: Custom Q-Grams ===");
        System.out.println("Tokenizer: 3-character Q-Grams");
        System.out.println("Tokens 1: " + tokens1);
        System.out.println("Tokens 2: " + tokens2);
        System.out.printf("Euclidean distance: %.2f%n%n", distance);
    }
}

public class Haversine {
    public static final double R = 6372.8; // In kilometers
    public static double haversine(double lat1, double lon1, double lat2, double lon2) {
        double dLat = Math.toRadians(lat2 - lat1);
        double dLon = Math.toRadians(lon2 - lon1);
        lat1 = Math.toRadians(lat1);
        lat2 = Math.toRadians(lat2);
 
        double a = Math.pow(Math.sin(dLat / 2),2) + Math.pow(Math.sin(dLon / 2),2) * Math.cos(lat1) * Math.cos(lat2);
        double c = 2 * Math.asin(Math.sqrt(a));
        return R * c;
    }
    public static void main(String[] args) {
        System.out.println(haversine(36.12, -86.67, 33.94, -118.40));
    }
}

