// Simulated Eclipse progress monitor interface.
interface IProgressMonitor {
    void beginTask(String name, int totalWork);
    void worked(int work);
    void done();
}

// A specialized progress monitor that is not intended for typical progress tracking.
class UnsupportedProgressMonitor implements IProgressMonitor {
    @Override
    public void beginTask(String name, int totalWork) {
        // Unsupported monitor does nothing.
    }
    @Override
    public void worked(int work) {
        // Unsupported monitor does nothing.
    }
    @Override
    public void done() {
        // Unsupported monitor does nothing.
    }
}

// Remote service interface representing progress reporting.
interface ProgressReportingService {
    // Reports progress using the provided monitor.
    void reportProgress(IProgressMonitor monitor) throws IllegalArgumentException;
}

// Concrete service implementation that performs progress reporting.
class ProgressReportingServiceImpl implements ProgressReportingService {

    private static final String TASK_NAME = "Processing";
    private static final int TOTAL_WORK = 100;
    private static final int WORK_INCREMENT = 10;

    @Override
    public void reportProgress(IProgressMonitor monitor) throws IllegalArgumentException {
        // Check for unsupported monitor type.
        if (monitor instanceof UnsupportedProgressMonitor) {
            throw new IllegalArgumentException("Unsupported progress monitor provided.");
        }
        // Begin the task.
        monitor.beginTask(TASK_NAME, TOTAL_WORK);
        // Simulate work in increments.
        for (int workDone = 0; workDone < TOTAL_WORK; workDone += WORK_INCREMENT) {
            monitor.worked(WORK_INCREMENT);
        }
        // Complete the task.
        monitor.done();
    }
}

