class Cache {
    int[][] mem;
    public int mctFromLeafValues(int[] arr) {
        mem = new int[arr.length + 1][arr.length + 1];
        return helper(arr, 0, arr.length);
    }

    public int getMax(int[] arr, int left, int right){
        int m = 0;
        for (int i = left; i < right; i++){
            if (arr[i] > m){
                m = arr[i];
            }
        }
        return m;
    }

    public int helper(int[] arr, int left, int right){
        if (left + 1 >= right){
            return 0;
        }
        if(mem[left][right] != 0){
            return mem[left][right];
        }
        int ans = Integer.MAX_VALUE;
        for (int i = left; i < right - 1; i++){
            int l = helper(arr, left, i + 1);
            int r = helper(arr, i+1, right);
            int ml = getMax(arr, left, i + 1);
            int mr = getMax(arr, i + 1, right);
            ans = Math.min(ans, l + r + ml * mr);
        }
        mem[left][right] = ans;
        return ans;
    }
}

