import java.math.BigInteger;
import static java.math.BigInteger.ONE;
 
public class PythTrip{
 
    public static void main(String[] args){
        long tripCount = 0, primCount = 0;
 
        //change this to whatever perimeter limit you want;the RAM's the limit
        BigInteger periLimit = BigInteger.valueOf(100),
                peri2 = periLimit.divide(BigInteger.valueOf(2)),
                peri3 = periLimit.divide(BigInteger.valueOf(3));
 
        for(BigInteger a = ONE; a.compareTo(peri3) < 0; a = a.add(ONE)){
            BigInteger aa = a.multiply(a);
 
            for(BigInteger b = a.add(ONE);
                    b.compareTo(peri2) < 0; b = b.add(ONE)){
                BigInteger bb = b.multiply(b);
                BigInteger ab = a.add(b);
                BigInteger aabb = aa.add(bb);
 
                for(BigInteger c = b.add(ONE);
                        c.compareTo(peri2) < 0; c = c.add(ONE)){
 
                    int compare = aabb.compareTo(c.multiply(c));
                    //if a+b+c > periLimit
                    if(ab.add(c).compareTo(periLimit) > 0){
                        break;
                    }
                    //if a^2 + b^2 != c^2
                    if(compare < 0){
                        break;
                    }else if (compare == 0){
                        tripCount++;
                        System.out.print(a + ", " + b + ", " + c);
 
                        //does binary GCD under the hood
                        if(a.gcd(b).equals(ONE)){
                            System.out.print(" primitive");
                            primCount++;
                        }
                        System.out.println();
                    }
                }
            }
        }
        System.out.println("Up to a perimeter of " + periLimit + ", there are "
                + tripCount + " triples, of which " + primCount + " are primitive.");
    }
}

import java.util.Scanner;

public class Writer {
    public static void main(String[] arsg) {

        System.out.print("To display the time, enter the time zone offset to GMT now: ");

        Scanner input = new Scanner(System.in);

        int offset = input.nextInt();

        long totalMilliseconds = System.currentTimeMillis();

        long totalSeconds = totalMilliseconds / 1000;

        long currentSecond = totalSeconds % 60;

        long totalMinutes = totalSeconds / 60;

        long currentMinute = totalMinutes % 60;

        long totalHours = totalMinutes / 60;

        long currentHour = totalHours % 24;

        currentHour += offset;

        System.out.println("Your current time is " + currentHour + ":"
                + currentMinute + ":" + currentSecond);
    }

}

public void recomposeStripAndPreserveSpaceDeclarations(WhiteSpaceInfo wsi) {
    List<WhiteSpaceInfo> list = // get the list of WhiteSpaceInfo elements
    boolean hasStripSpace = false;
    boolean hasPreserveSpace = false;

    for (WhiteSpaceInfo info : list) {
        if (info.isStripSpace()) {
            hasStripSpace = true;
        } else if (info.isPreserveSpace()) {
            hasPreserveSpace = true;
        }

        if (hasStripSpace && hasPreserveSpace) {
            // recompose the strip-space and preserve-space declarations
            list.remove(info);
            list.remove(wsi);
            list.add(new WhiteSpaceInfo(true, true));
            break;
        }
    }
}

