public class Library{

    public static void main(String[] args){

        HashMap<Integer,List<Long>> x = new HashMap<>();

        HashMap<Integer,List<Long>> y = new HashMap<>();

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int m = sc.nextInt();

        for(int i=0;i<n;i++){

            for(int j=0;j<m;j++){

                int c = sc.nextInt();

                if(x.containsKey(c)){

                    x.get(c).add((long)i);

                    y.get(c).add((long)j);

                }

                else{

                    x.put(c,new ArrayList<>(Arrays.asList((long)i)));

                    y.put(c,new ArrayList<>(Arrays.asList((long)j)));

                }

            }

        }

        long ans = 0;

        for(int k:x.keySet()){

            List<Long> arr = x.get(k);

            long s = 0;

            for(int i=0;i<arr.size();i++){

                ans+= i*arr.get(i)-s;

                s+=arr.get(i);

            }

            arr=y.get(k);

            s=0;

            Collections.sort(arr);

            for(int i=0;i<arr.size();i++)

            {

                ans+=i*arr.get(i)-s;

                s+=arr.get(i);

            }

        }

        System.out.println(ans);

    }

}

