}

class Queue {
    public int minAbsoluteDifference(List<Integer> nums, int x) {
        TreeSet<Integer> set = new TreeSet<>();
        int i , n = nums.size() , ans = Integer.MAX_VALUE;
        if (x == 0) {
            return 0;
        }
        for (i = 0;i < n;i ++) {
            int value = nums.get(i);
            Integer floor = set.floor(value);
            Integer ceil = set.ceiling(value);
            if (floor != null) {
                int absValue = Math.abs(floor - value);
                ans = Math.min(ans , absValue);
            }
            if (ceil != null) {
                int absValue = Math.abs(ceil - value);
                ans = Math.min(ans , absValue);
            }
            if (i - (x - 1) >= 0) {
                set.add(nums.get(i - (x - 1)));
            }
        }
        return ans;
    }

}

