import java.lang.annotation.Retention;
import java.lang.annotation.Target;
import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.RetentionPolicy;

import javax.servlet.ServletException;

import org.kohsuke.stapler.StaplerRequest;
import org.kohsuke.stapler.AnnotationHandler;
import org.kohsuke.stapler.InjectedParameter;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.PARAMETER)
@Documented
@InjectedParameter
public @interface Header {
    String value();
    boolean required() default true;
}

class HandlerImpl extends AnnotationHandler<Header> {

    @Override
    public Object parse(StaplerRequest req, Header a, Class type, Class genericType) throws ServletException {
        String headerName = a.value();
        String headerValue = req.getHeader(headerName);

        if (a.required() && headerValue == null) {
            throw new ServletException("Required header '" + headerName + "' is missing");
        }

        return convert(headerValue, type);
    }

    private Object convert(String value, Class type) throws ServletException {
        if (value == null) {
            return null;
        }
        if (type == String.class) {
            return value;
        } else if (type == int.class || type == Integer.class) {
            try {
                return Integer.parseInt(value);
            } catch (NumberFormatException e) {
                throw new ServletException("Failed to convert header value to int", e);
            }
        } else if (type == long.class || type == Long.class) {
            try {
                return Long.parseLong(value);
            } catch (NumberFormatException e) {
                throw new ServletException("Failed to convert header value to long", e);
            }
        } else if (type == boolean.class || type == Boolean.class) {
            return Boolean.parseBoolean(value);
        } else {
            throw new ServletException("Unsupported type for header conversion: " + type.getName());
        }
    }
}

/*
 * Birden fazla arka plan gorevini thread kullanarak paralel olarak calistiran ve belirli
 * bir sure sonunda gorevleri sonlandiran genisletilmis Java programi.
 */

public class ArkaPlanGorevi implements Runnable {

    private String gorevAdi; // Gorevin ismi
    private volatile boolean calisiyor = true; // Thread'in calisma durumu

    // Constructor: Gorev ismini belirler
    public ArkaPlanGorevi(String gorevAdi) {
        this.gorevAdi = gorevAdi;
    }

    // Arka plan gorevini calistiracak metod
    public void run() {
        int sayac = 0;
        while (calisiyor && sayac < 10) {
            System.out.println(gorevAdi + " calisiyor: " + sayac); // Gorev mesajini yazdir
            try {
                Thread.sleep(400); // 0.4 saniye uyur
            } catch (InterruptedException e) {
                System.out.println(gorevAdi + " kesildi.");
                return; // Thread sonlandirilir
            }
            sayac++;
        }
        System.out.println(gorevAdi + " tamamlandi.");
    }

    // Thread'i durdurma metodu
    public void durdur() {
        calisiyor = false;
    }

    // Programin ana metodu
    public static void main(String[] args) {
        // Arka plan gorevleri olustur
        ArkaPlanGorevi gorev1 = new ArkaPlanGorevi("Gorev-1");
        ArkaPlanGorevi gorev2 = new ArkaPlanGorevi("Gorev-2");
        ArkaPlanGorevi gorev3 = new ArkaPlanGorevi("Gorev-3");

        // Thread'leri olustur ve adlandir
        Thread thread1 = new Thread(gorev1, "Thread-1");
        Thread thread2 = new Thread(gorev2, "Thread-2");
        Thread thread3 = new Thread(gorev3, "Thread-3");

        // Thread'leri baslat
        thread1.start();
        thread2.start();
        thread3.start();

        // Ana thread'de baska isler yap
        for (int i = 0; i < 5; i++) {
            System.out.println("Ana thread is yapiyor: " + i);
            try {
                Thread.sleep(500); // 0.5 saniye uyur
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }

        // Belirli bir sure sonra tum thread'leri durdur
        try {
            Thread.sleep(5000); // 5 saniye bekle
        } catch (InterruptedException e) {
            e.printStackTrace();
        }

        System.out.println("Tum gorevler durduruluyor...");
        gorev1.durdur();
        gorev2.durdur();
        gorev3.durdur();

        // Tum thread'lerin tamamlanmasini bekle
        try {
            thread1.join();
            thread2.join();
            thread3.join();

public String checkHiveTable(String namespace, String name, String location) {
    if (namespace == null || namespace.isEmpty() || name == null || name.isEmpty()) {
        // invalid input parameters
        return null;
    }

    String nsTable = namespace + "." + name;
    String defaultTable = "default." + name;

    // If location is not null, check nsTable or defaultTable with the given location
    if (location != null && !location.isEmpty()) {
        if (checkTableAtLocation(nsTable, location)) {
            return namespace;
        } else if (checkTableAtLocation(defaultTable, location)) {
            return "default";
        } else {
            return null;
        }
    }

    // Else, check whether nsTable exists or not
    if (checkTableExistence(nsTable)) {
        return namespace;
    }

    // If nsTable does not exist, check whether defaultTable exists
    if (checkTableExistence(defaultTable)) {
        return "default";
    }

    // Neither nsTable nor defaultTable exist
    return null;
}

