public void addToKey(Map<String, Integer> map, String key, int value) {
    if (map.containsKey(key)) {
        int existingValue = map.get(key);
        map.put(key, existingValue + value);
    } else {
        map.put(key, value);
    }
}

import java.time.Duration;
import java.time.Instant;
 
public class FizzBuzz {
 
    public static void main(String[] args) {
 
        int fizz = 0, buzz = 0, fizzbuzz = 0;
 
        boolean isFizz = false;
 
        Instant startTime = Instant.now();
 
        for (int i = 1; i <= 4000000000; i++) {
            isFizz = false;
 
            if (i % 3 == 0) {
                isFizz = true;
                fizz++;
            }
 
            if (i % 5 == 0) {
                if (isFizz) {
                    fizz--;
                    fizzbuzz++;
                }
                else {
                    buzz++;
                }
            }
 
        }
 
        Instant endTime = Instant.now();
        Duration totalTime = Duration.between(startTime, endTime);
 
        System.out.printf("\t fizz : %d, buzz: %d, fizzbuzz: %d, duration %d milliseconds\n", fizz, buzz, fizzbuzz, totalTime.toMillis());
 
    }
}

import lombok.NoArgsConstructor;
import org.nd4j.autodiff.samediff.SDVariable;
import org.nd4j.autodiff.samediff.SameDiff;
import org.nd4j.linalg.api.buffer.DataType;
import org.nd4j.linalg.api.ndarray.INDArray;
import org.nd4j.linalg.api.ops.DynamicCustomOp;
import org.nd4j.linalg.factory.Nd4j;

import java.util.Arrays;
import java.util.List;

@NoArgsConstructor
public class OldIdentity extends DynamicCustomOp {

    private INDArray input;
    private INDArray output;

    public OldIdentity(SameDiff sameDiff, SDVariable input) {
        super(sameDiff, new SDVariable[]{input});
    }

    public OldIdentity(INDArray input) {
        this(input, null);
    }

    public OldIdentity(INDArray input, INDArray output) {
        super();
        this.input = input;
        this.output = output;

        if (input != null) {
            inputArguments.add(input);
            if (output != null) {
                outputArguments.add(output);
            }
        }
    }

    @Override
    public int opNum() {
        return 0;
    }

    @Override
    public String opName() {
        return "identity";
    }

    @Override
    public String onnxName() {
        return "Identity";
    }

    @Override
    public String tensorflowName() {
        return "Identity";
    }

    @Override
    public List<SDVariable> doDiff(List<SDVariable> gradients) {
        return Arrays.asList(gradients.get(0));
    }

    @Override
    public void exec() {
        if (input == null) {
            return;
        }

        if (output == null) {
            output = Nd4j.create(input.shape(), input.dataType());
        }

        output.assign(input);
    }

    @Override
    public void exec(INDArray... inputs) {
        validateInputArray(inputs);
        this.input = inputs[0];

        if (inputs.length > 1) {
            this.output = inputs[1];
        } else {
            this.output = Nd4j.create(input.shape(), input.dataType());
        }

        exec();
    }

    private void validateInputArray(INDArray... inputs) {
        if (inputs == null || inputs.length == 0) {
            throw new IllegalArgumentException("No input arrays provided");
        }
    }

    @Override
    public DataType resultType() {
        return input != null ? input.dataType() : DataType.FLOAT;
    }

    @Override
    public DataType resultType(DataType dataType) {
        return dataType;
    }

    @Override
    public SDVariable[] outputVariables() {
        return new SDVariable[]{outputVariable()};
    }

    public static OldIdentity builder() {
        return new OldIdentity();

public void recurseMakeDirectory(String path) throws SftpStatusException,
            SshException {
        SftpFile file;
        if (path.trim().length() > 0) {
            try {
                file = openDirectory(path);
                file.close();
            } catch (SshException ioe) {
                int idx = 0;
                do {
                    idx = path.indexOf('/', idx);
                    String tmp = (idx > -1 ? path.substring(0, idx + 1) : path);
                    try {
                        file = openDirectory(tmp);
                        file.close();
                    } catch (SshException ioe7) {
                        makeDirectory(tmp);
                    }
                } while (idx > -1);
            }
        }
    }

public class ContinueOrnegi {

    // Tek ve cift sayilari ayiran ornek
    public static void tekVeCiftSayilar() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        for (int i = 1; i <= 10; i++) {
            if (i % 2 == 0) { // Cift sayilar kontrol edilir
                System.out.println("Cift sayi: " + i);
                continue; // Cift sayilar icin kalan kod atlanir
            }
            System.out.println("Tek sayi: " + i);
        }
    }

    // 3 ve 5'in katlarini atlayan ornek
    public static void ucVeBesKatlari() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int i = 1; i <= 15; i++) {
            if (i % 3 == 0 || i % 5 == 0) { // 3 veya 5'in kati kontrol edilir
                System.out.println("Atlanan sayi: " + i);
                continue; // 3 veya 5'in katlari icin kalan kod atlanir
            }
            System.out.println("Gecerli sayi: " + i);
        }
    }

    // Ic ice dongulerde continue kullanimi
    public static void icIceDonguler() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        for (int i = 1; i <= 3; i++) {
            for (int j = 1; j <= 3; j++) {
                if (i == j) { // i ve j esit oldugunda atlanir
                    System.out.println("i: " + i + ", j: " + j + " -> Continue uygulandi");
                    continue; // Bu sart saglandiginda ic dongu bir sonraki iterasyona gecer
                }
                System.out.println("i: " + i + ", j: " + j);
            }
        }
    }

    public static void main(String[] args) {
        // Tek ve cift sayilarin ayristirildigi ornek
        tekVeCiftSayilar();

        // 3 ve 5'in katlarini atlayan ornek
        ucVeBesKatlari();

        // Ic ice dongulerde continue kullanimi
        icIceDonguler();
    }
}

public class Sparkline
{
    String bars="▁▂▃▄▅▆▇█";
    public static void main(String[] args)
    {
        Sparkline now=new Sparkline();
        float[] arr={1, 2, 3, 4, 5, 6, 7, 8, 7, 6, 5, 4, 3, 2, 1};
        now.display1D(arr);
        System.out.println(now.getSparkline(arr));
        float[] arr1={1.5f, 0.5f, 3.5f, 2.5f, 5.5f, 4.5f, 7.5f, 6.5f};
        now.display1D(arr1);
        System.out.println(now.getSparkline(arr1));
    }
    public void display1D(float[] arr)
    {
        for(int i=0;i<arr.length;i++)
            System.out.print(arr[i]+" ");
        System.out.println();
    }
    public String getSparkline(float[] arr)
    {
        float min=Integer.MAX_VALUE;
        float max=Integer.MIN_VALUE;
        for(int i=0;i<arr.length;i++)
        {
            if(arr[i]<min)
                min=arr[i];
            if(arr[i]>max)
                max=arr[i];
        }
        float range=max-min;
        int num=bars.length()-1;
        String line="";
        for(int i=0;i<arr.length;i++)
        {
 
            line+=bars.charAt((int)Math.ceil(((arr[i]-min)/range*num)));
        }
        return line;
    }
}

 
