public class FloodFillAlgorithm {
 
    private Mat image;
 
    public FloodFillAlgorithm(Mat image) {
        this.image = image;
    }
 
    public void flood(Point startPoint, Scalar tgtColor, Scalar loDiff) {
        int width = image.cols();
        int height = image.rows();
 
        int[] data = new int[width * height];
        image.get(0, 0, data);
 
        int[] tgtData = new int[width * height];
        image.get(0, 0, tgtData);
 
        int startX = (int) startPoint.x;
        int startY = (int) startPoint.y;
 
        int startColor = data[startY * width + startX];
 
        Queue<Point> queue = new LinkedList<Point>();
        queue.add(startPoint);
 
        while (!queue.isEmpty()) {
            Point p = queue.remove();
 
            int x = (int) p.x;
            int y = (int) p.y;
 
            int index = y * width + x;
 
            if (data[index] == startColor) {
                tgtData[index] = (int) tgtColor.val[0];
 
                if (x > 0) {
                    queue.add(new Point(x - 1, y));
                }
 
                if (x < width - 1) {
                    queue.add(new Point(x + 1, y));
                }
 
                if (y > 0) {
                    queue.add(new Point(x, y - 1));
                }
 
                if (y < height - 1) {
                    queue.add(new Point(x, y + 1));
                }
            }
        }
 
        image.put(0, 0, tgtData);
    }
 
