public abstract class ProxyParameter<TYPE, PARAMETER extends Parameter<TYPE>> extends ProxyObject<PARAMETER> implements Parameter<TYPE> {

    private static final Logger logger = LoggerFactory.getLogger(ProxyParameter.class);

    private final String path;
    private final String name;

    @Inject
    private ManagedCollectionFactory managedCollectionFactory;

    @Inject
    private ReceiverFactory receiverFactory;

    protected ProxyParameter(String path, String name) {
        this.path = path;
        this.name = name;
    }

    public abstract ParameterView<TYPE> createView();

    public abstract Tree getTree();

    public abstract TYPE getType();

    public abstract List<Parameter> getChild();

    public String getPath() {
        return path;
    }

    public String getName() {
        return name;
    }

    public static class Simple<TYPE> extends ProxyParameter<TYPE, Parameter<TYPE>> {

        private final TYPE type;

        public Simple(String path, String name, TYPE type) {
            super(path, name);
            this.type = type;
        }

        @Override
        public ParameterView<TYPE> createView() {
            // TODO Auto-generated method stub
            return null;
        }

        @Override
        public Tree getTree() {
            // TODO Auto-generated method stub
            return null;
        }

        @Override
        public TYPE getType() {
            return type;
        }

        @Override
        public List<Parameter> getChild() {
            return null;
        }
    }
}

