        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] parent = new int[n + 1];
            int[] a = new int[n + 1];
            List<Integer>[] children = new ArrayList[n + 1];
            for (int i = 0; i <= n; i++) {
                children[i] = new ArrayList<>();
            }
            for (int i = 2; i <= n; i++) {
                parent[i] = scanner.nextInt();
                children[parent[i]].add(i);
            }
