                    break;
                }
                long[] nextDp = new long[n + 1];
                for (int i = 1; i <= n; i++) {
                    nextDp[i] = Long.MIN_VALUE;
                }
                for (int u : layer[d]) {
                    for (int v : children.get(d)) {
                        for (int x : layer[d + 1]) {
                            nextDp[v] = Math.max(nextDp[v], Math.max(dp[v] + Math.abs(u - x), dp[v] + Math.abs(x - u)));
                        }
