class Counter {
    public List<List<String>> printTree(TreeNode root) {
        int height = getHeight(root);
        int rows = height;
        int cols = (1 << height) - 1;
        List<List<String>> res = new ArrayList<>();
        for (int i = 0; i < rows; i++) {
            List<String> row = new ArrayList<>();
            for (int j = 0; j < cols; j++) {
                row.add("");
            }
            res.add(row);
        }
        constructTree(res, root, 0, 0, cols - 1);
        return res;
    }

    private int getHeight(TreeNode node) {
        if (node == null) {
            return 0;
        }
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    private void constructTree(List<List<String>> res, TreeNode node, int row, int left, int right) {
        if (node == null) {
            return;
        }
        int mid = (left + right) / 2;
        res.get(row).set(mid, String.valueOf(node.val));
        constructTree(res, node.left, row + 1, left - (1 << (getHeight(node) - row - 1)), mid - 1);
        constructTree(res, node.right, row + 1, mid + 1, right + (1 << (getHeight(node) - row - 1)));
    }
}

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.MathContext;
import java.math.RoundingMode;
import java.util.logging.Logger;
 
public class Counter {
    private static final Logger LOGGER = Logger.getLogger(Counter.class.getName());
 
    // DC for dollars and cents.  Value is an integer number of cents.
    private static class DC {
        private final BigInteger value;
 
        private DC(BigInteger value) {
            this.value = value;
        }
 
        @Override
        public String toString() {
            BigInteger d = value.divide(BigInteger.valueOf(100));
            if (value.compareTo(BigInteger.ZERO) < 0) {
                value = value.negate();
            }
            return String.format("%d.%02d", d, value.mod(BigInteger.valueOf(100)));
        }
 
        // Extend returns extended price of a unit price.
        public DC extend(int n) {
            return new DC(value.multiply(BigInteger.valueOf(n)));
        }
    }
 
    private static final BigInteger ONE = BigInteger.ONE;
    private static final BigDecimal HUNDRED = BigDecimal.valueOf(100);
 
    // ParseDC parses dollars and cents as a string into a DC.
    public static DC parseDC(String s) {
        BigDecimal r;
        try {
            r = new BigDecimal(s);
        } catch (NumberFormatException e) {
            return null;
        }
        r = r.multiply(HUNDRED);
        if (r.scale()!= 0) {
            return null;
        }
        return new DC(r.toBigInteger());
    }
 
    // TR for tax rate.  Value is an an exact rational.
    private static class TR {
        private final BigDecimal value;
 
        private TR(BigDecimal value) {
            this.value = value;
        }
 
        @Override
        public String toString() {
            return value.toString();
        }
 
        // SetString overrides Rat.SetString to return the TR type.
        public static TR setString(String s) {
            try {
                return new TR(new BigDecimal(s));
            } catch (NumberFormatException e) {
                return null;
            }
        }
 
        private static final BigDecimal HALF = BigDecimal.valueOf(1, 1);
 
        // Tax computes a tax amount, rounding to the nearest cent.
        public DC tax(DC dc) {
            BigDecimal r = new BigDecimal(dc.value);
            r = r.multiply(value, MathContext.DECIMAL128);
            r = r.add(HALF);
            return new DC(r.toBigInteger());
        }
    }
 
    public static void main(String[] args) {
        DC hamburgerPrice = parseDC("5.50");

