 */
@Entity
@Table( name = "user_delegate" )
@Access( AccessType.FIELD )
public class UserDelegateEntity implements UserDelegate
{
    @Id
    @Column( name = "id" )
    private String id;

    @Column( name = "user_id" )
    private long userId;

    @Column( name = "type" )
    private int type = UserType.REGULAR.getId();

    @Column( name = "relation_document", length = 3000 )
    private String relationDocument;

    @Override
    public String getId()
    {
        return id;
    }

    @Override
    public void setId( final String id )
    {
        this.id = id;
    }

    @Override
    public long getUserId()
    {
        return userId;
    }

    @Override
    public void setUserId( final long userId )
    {
        this.userId = userId;
    }

    @Override
    public int getType()
    {
        return type;
    }

    @Override
    public void setType( final int type )
    {
        this.type = type;
    }

    @Override
    public String getRelationDocument()
    {
        return relationDocument;
    }

    @Override
    public void setRelationDocument( final String relationDocument )
    {
        this.relationDocument = relationDocument;
    }

    @Override
    public String getLinkId()
    {
        return String.format( "%s|%s", getClassPath(), getUniqueIdentifier() );
    }

    @Override
    public String getUniqueIdentifier()
    {
        return getId();
    }

    @Override
    public String getClassPath()
    {
        return this.getClass().getSimpleName();
    }

    @Override
    public String getContext()
    {
        return PermissionObject.IDENTITY_MANAGEMENT.getName();
    }

    @Override
    public String getKeyId()
    {
        return getId();
    }

    @Override
    public boolean equals( final Object o )
    {
        if ( this == o )
        {
            return true;
        }
        if ( !( o instanceof UserDelegateEntity ) )
        {
            return false;
        }

        final UserDelegateEntity that = ( UserDelegateEntity ) o;

        return id != null ? id.equals( that.id ) : that.id == null;
    }

    @Override
    public int hashCode()
    {
        return id != null ? id.hashCode() : 0;
    }
}

#include <iostream>
#include <cmath>

using namespace std;

int main() {
    int tcases;
    cin >> tcases;

    while (tcases--) {
        int n, mod0 = 0, mod1 = 0, mod2 = 0;
        cin >> n;

        for(int i=0; i < n; i++) {
            int val;
            cin >> val;

            if (val % 3 == 0) {
                mod0++;
            }
            else if (val % 3 == 1) {
                mod1++;
            }
            else {
                mod2++;
            }
        }

        int adjustCount = std::min(std::abs(mod0-mod1), std::abs(mod1-mod2));
        cout << adjustCount << "\n";
    }
    return 0;
}

