import com.amazonaws.transform.StaxUnmarshallerContext;
import com.amazonaws.transform.SimpleTypeStaxUnmarshallers;
import com.amazonaws.transform.StaxUnmarshaller;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.events.XMLEvent;

public class ModifyReservedInstancesResultStaxUnmarshaller implements StaxUnmarshaller<ModifyReservedInstancesResult> {

    private static ModifyReservedInstancesResultStaxUnmarshaller instance;

    static {
        instance = new ModifyReservedInstancesResultStaxUnmarshaller();
    }

    private ModifyReservedInstancesResultStaxUnmarshaller() {}

    public static ModifyReservedInstancesResultStaxUnmarshaller getInstance() {
        return instance;
    }

    @Override
    public ModifyReservedInstancesResult unmarshall(StaxUnmarshallerContext context) throws XMLStreamException {
        ModifyReservedInstancesResult result = new ModifyReservedInstancesResult();
        int originalDepth = context.getCurrentDepth();
        int targetDepth = originalDepth + 1;

        while (true) {
            XMLEvent event = context.nextEvent();
            if (event.isEndDocument()) {
                break;
            }

            if (event.isStartElement()) {
                String localName = context.getCurrentName();
                int currentDepth = context.getCurrentDepth();

                if (currentDepth == targetDepth) {
                    if ("reservedInstancesModificationId".equals(localName)) {
                        StringStaxUnmarshaller unmarshaller = SimpleTypeStaxUnmarshallers.StringStaxUnmarshaller.getInstance();
                        String id = unmarshaller.unmarshall(context);
                        result.setReservedInstancesModificationId(id);
                    }
                }
            } else if (event.isEndElement()) {
                if (context.getCurrentDepth() < originalDepth) {
                    break;
                }
            }
        }

        return result;
    }
}

class ModifyReservedInstancesResult {
    private String reservedInstancesModificationId;

    public String getReservedInstancesModificationId() {
        return reservedInstancesModificationId;
    }

    public void setReservedInstancesModificationId(String reservedInstancesModificationId) {
        this.reservedInstancesModificationId = reservedInstancesModificationId;
    }
}

import org.jivesoftware.Spark;

import javax.swing.Action;
import javax.swing.Icon;
import javax.swing.JButton;

import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * Button UI for handling of rollover buttons.
 *
 */
public class RolloverButton extends JButton {
    private static final long serialVersionUID = 6351541211385798436L;

    /**
     * Create a new RolloverButton.
     */
    public RolloverButton() {
        decorate();
    }

    public RolloverButton(String text) {
        super(text);
        decorate();
    }

    public RolloverButton(Action action) {
        super(action);
        decorate();
    }

    /**
     * Create a new RolloverButton.
     *
     * @param icon the icon to use on the button.
     */
    public RolloverButton(Icon icon) {
        super(icon);
        decorate();
    }

    /**
     * Create a new RolloverButton.
     *
     * @param text the button text.
     * @param icon the button icon.
     */
    public RolloverButton(String text, Icon icon) {
        super(text, icon);
        decorate();
    }

    /**
     * Decorates the button with the approriate UI configurations.
     */
    protected void decorate() {
        setBorderPainted(false);
        setOpaque(true);

        setContentAreaFilled(false);
        setMargin(new Insets(1, 1, 1, 1));

        addMouseListener(new MouseAdapter() {
            public void mouseEntered(MouseEvent e) {
                if (isEnabled()) {
                    setBorderPainted(true);

                    // Handle background border on mac.
                    if (!Spark.isMac()) {
                        setContentAreaFilled(true);
                    }
                }
            }

            public void mouseExited(MouseEvent e) {
                setBorderPainted(false);
                setContentAreaFilled(false);
            }
        });

    }

}

import java.util.ArrayList;
import java.util.List;

public class Zoo {

    private List<Animal> animals = new ArrayList<>();
    private List<AnimalAddedListener> animalAddedListeners = new ArrayList<>();

    public void addAnimal(Animal animal) {
        this.animals.add(animal);
        notifyAnimalAddedListeners(animal);
    }

    public void registerAnimalAddedListener(AnimalAddedListener listener) {
        this.animalAddedListeners.add(listener);
    }

    public void unregisterAnimalAddedListener(AnimalAddedListener listener) {
        this.animalAddedListeners.remove(listener);
    }

    protected void notifyAnimalAddedListeners(Animal animal) {
        animalAddedListeners.forEach(listener -> listener.onAnimalAdded(animal));
    }

    public static void main(String[] args) {
        Zoo zoo = new Zoo();

        // Example usage assuming Animal and AnimalAddedListener are defined
        Animal animal1 = new Animal("Lion");
        Animal animal2 = new Animal("Elephant");

        zoo.registerAnimalAddedListener(animal -> System.out.println("New animal added: " + animal.getName()));

        zoo.addAnimal(animal1);
        zoo.addAnimal(animal2);
    }
}

class Animal {
    private String name;

    public Animal(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

interface AnimalAddedListener {
    void onAnimalAdded(Animal animal);
}

