public class NumberOfPrefixesThatNeedToBeFlipedToBinaryString {
    public int numberOfPrefixesThatNeedToBeFlipped(int[] flips) {
        int ans = 0;
        for(int i = 0; i < flips.length; ++i){
            int flip = i;
            while (flip < flips.length && flip >= 0) {
                int flipInd = flip + 1;
                flipInd += flips[flip];
                if(flipInd == i + 1){
                    ans ++;
                }
                flip = flipInd;
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        var solver = new NumberOfPrefixesThatNeedToBeFlipedToBinaryString();
        var output = solver.numberOfPrefixesThatNeedToBeFlipped(new int[]{5,1,4,1,1,3,1,1,0,0,0});
        System.out.println(output);
    }

}

