public class PermutationPartitionValue {
    private static final int MOD = 998244353;
    private static int[] suffixMax = new int[200005];
    private static int[] segmentSum = new int[200005];
    private static int[] totalSum = new int[200005];

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int n = Integer.parseInt(tokenizer.nextToken());
        int k = Integer.parseInt(tokenizer.nextToken());
        int[] p = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            p[i] = Integer.parseInt(reader.readLine());
            segmentSum[i] = segmentSum[i - 1] + p[i];
        }

        for (int i = 1; i <= n; i++) {
            suffixMax[i] = Math.max(i, suffixMax[i - 1]);
        }

        for (int i = n; i >= 1; i--) {
            suffixMax[i] = Math.max(suffixMax[i], p[i]);
        }

        calculatePartitions(p, k, 1, Integer.MAX_VALUE, 0);

        System.out.println(suffixMax[n] - totalSum[k - 1] - (k > 1 ? segmentSum[n] : 0) + MOD);
        System.out.println(totalPartitions % MOD);
    }

    private static void calculatePartitions(int[] p, int k, int left, int maxSuffix, int count) {
        if (k == 1 || left > suffixMax[k]) return;

        if (left >= p[left] && left <= p[k - 1]) {
            int right = k < n ? k + 1 : n;
            while (left < right && p[right - 1] >= p[left]) right--;
            partitionValue += suffixMax[right] - p[left] + 1;
            totalPartitions = (totalPartitions + (k > 2 ? 1 : 0)) % MOD;
        }

        calculatePartitions(p, k, left + 1, maxSuffix, count);

        if (left == k) calculatePartitions(p, k, left - 1, Math.max(suffixMax[left], p[left]), count + 1);
    }

    private static int partitionValue = 0;
    private static int totalPartitions = 0;
}

