class BayesNetNode {

    private String variable;
    private List<BayesNetNode> parents;
    private List<BayesNetNode> children;
    private ProbabilityDistribution distribution;

    public BayesNetNode(String variable) {
        this.variable = variable;
        this.parents = new ArrayList<>();
        this.children = new ArrayList<>();
        this.distribution = new ProbabilityDistribution();
    }

    public void addParent(BayesNetNode parent) {
        this.parents.add(parent);
        parent.addChild(this);
        updateDistribution();
    }

    public void addChild(BayesNetNode child) {
        this.children.add(child);
    }

    public boolean influencedBy(BayesNetNode node) {
        return this.parents.contains(node);
    }

    public void setProbability(Hashtable<String, Boolean> conditions, double probability) {
        this.distribution.setProbability(conditions, probability);
    }

    public boolean isRoot() {
        return this.parents.isEmpty();
    }

    public String getVariable() {
        return this.variable;
    }

    public List<BayesNetNode> getChildren() {
        return this.children;
    }

    public List<BayesNetNode> getParents() {
        return this.parents;
    }

    @Override
    public String toString() {
        return "BayesNetNode{" +
                "variable='" + variable + '\'' +
                ", parents=" + parents.stream().map(BayesNetNode::getVariable).toList() +
                ", children=" + children.stream().map(BayesNetNode::getVariable).toList() +
                '}';
    }

    public double probabilityOf(Hashtable<String, Boolean> conditions) {
        return this.distribution.getProbability(conditions);
    }

    public boolean isTrueFor(double probability, Hashtable<String, Boolean> model) {
        Hashtable<String, Boolean> conditions = new Hashtable<>(model);
        double p = probabilityOf(conditions);
        return p >= probability;
    }

    private void updateDistribution() {
        // Assuming ProbabilityDistribution has a method to update based on parents
        // and their possible states.  This is a placeholder, the actual
        // implementation would depend on how ProbabilityDistribution is designed.
        this.distribution.updateBasedOnParents(this.parents);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;
        BayesNetNode that = (BayesNetNode) obj;

public static Timestamp addMonthsToTimestamp(Timestamp timestamp, int amount) {
    Calendar cal = Calendar.getInstance();
    cal.setTimeInMillis(timestamp.getTime());
    cal.add(Calendar.MONTH, amount);
    return new Timestamp(cal.getTime().getTime());
}

class Game {
        public int pathSum(int[] nums) {
            int[][] div = new int[nums.length][];
            int p = 0;
            for(int v : nums){
                int d = v/100;
                int ind = v/10%10;
                int val = v%10;
                div[p++] = new int[]{d, ind-1, val};
            }
            int all = 0;
            outer:
            for(int[] u : div){
                int d = u[0], ind = u[1], val = u[2];
                for(int[] v : div){
                    if(v[0] == d+1 &&
                            (v[1] == ind*2 || v[1] == ind*2+1)){
                        continue outer;
                    }
                }
                while(d > 0){
                    for(int[] v : div){
                        if(v[0] == d && v[1] == ind){
                            all += v[2];
                            break;
                        }
                    }
                    d--; ind>>= 1;
                }
            }
            return all;
        }
    }

public class TuitionCalculator {
    public static void main(String[] args) {
        double tuition = 10000.0; // Initial tuition is $10,000
        double totalCost = 0.0;

        // Compute the tuition for each of the next ten years
        for (int i = 1; i <= 10; i++) {
            tuition *= 1.05; // Increase tuition by 5%
            if (i > 4) {
                totalCost += tuition; // Add tuition to the total cost for years 5-10
            }
        }

        // Display the tuition in ten years and the total cost of four years' worth of tuition
        System.out.printf("The tuition in ten years is $%.2f\n", tuition);
        System.out.printf("The total cost of four years' worth of tuition after the tenth year is $%.2f\n", totalCost);
    }
}

