/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
class Library {
    public boolean checkEqualTree(TreeNode root) {
        if(root == null){
            return false;
        }

        // calc sum
        sumUp(root);

        // check possible
        return check(root.left, root.val) || check(root.right, root.val);
    }

    private int sumUp(TreeNode root){
        if(root == null){
            return 0;
        }

        root.val += (sumUp(root.left) + sumUp(root.right));
        return root.val;
    }

    private boolean check(TreeNode root, int total){
        if(root == null){
            return false;
        }

        if(total - root.val == root.val){
            return true;
        }

        return check(root.left, total) || check(root.right, total);
    }
}

import java.util.Random;
public class SevenSidedDice
{
    private static final Random rnd = new Random();
    public static void main(String[] args)
    {
        SevenSidedDice now=new SevenSidedDice();
        System.out.println("Random number from 1 to 7: "+now.seven());
    }
    int seven()
    {
        int v=21;
        while(v>20)
            v=five()+five()*5-6;
        return 1+v%7;
    }
    int five()
    {
        return 1+rnd.nextInt(5);
    }
}

import java.util.Arrays;
import java.util.Comparator;
 
public class RJSortStability {
 
  public static void main(String[] args) {
    String[] cityList = { "UK  London", "US  New York", "US  Birmingham", "UK  Birmingham", };
 
    String[] cn = cityList.clone();
    System.out.println("\nBefore sort:");
    for (String city : cn) {
      System.out.println(city);
    }
 
    // sort by city
    Arrays.sort(cn, new Comparator<String>() {
      public int compare(String lft, String rgt) {
        return lft.substring(4).compareTo(rgt.substring(4));
      }
    });
 
    System.out.println("\nAfter sort on city:");
    for (String city : cn) {
      System.out.println(city);
    }
 
    cn = cityList.clone();
    System.out.println("\nBefore sort:");
    for (String city : cn) {
      System.out.println(city);
    }
 
    // sort by country
    Arrays.sort(cn, new Comparator<String>() {
      public int compare(String lft, String rgt) {
        return lft.substring(0, 2).compareTo(rgt.substring(0, 2));
      }
    });
 
    System.out.println("\nAfter sort on country:");
    for (String city : cn) {
      System.out.println(city);
    }
 
    System.out.println();
  }
}

