class Finder {
    public int minTimeToColorful(String colors, int[] neededTime) {
        int n = colors.length();
        int[] dp = new int[n];
        dp[0] = neededTime[0];
        for (int i = 1; i < n; i++) {
            int prev = (colors.charAt(i - 1) == colors.charAt(i)) ? dp[i - 1] : 0;
            dp[i] = Math.min(prev, neededTime[i]);
        }
        return dp[n - 1];
    }
}

