public int minDeletionSize(String[] strs) {
    int count = 0;
    for (int i = 0; i < strs[0].length(); i++) {
        for (int j = 0; j < strs.length - 1; j++) {
            //check if strs in current column is in lexicographic order
            if (strs[j].charAt(i) > strs[j + 1].charAt(i)) {       //if not in order increment count and break
                count++;
                break;
            }
        }
    }
    return count;
}

@Override
    public final EventData convert(final CommonEvent commonEvent) {

        final String dataType = commonEvent.getDataType().asBaseType();
        final SerializedDataType serUserDataType = new SerializedDataType(dataType);
        final Serializer userDataSerializer = serRegistry.getSerializer(serUserDataType);
        final byte[] serUserData = userDataSerializer.marshal(commonEvent.getData(), serUserDataType);
        final byte[] serData;
        if (userDataSerializer.getMimeType().matchEncoding(targetContentType)) {
            serData = serUserData;
        } else {
            final Base64Data base64data = new Base64Data(serUserData);
            final Serializer base64Serializer = serRegistry.getSerializer(Base64Data.SER_TYPE);
            serData = base64Serializer.marshal(base64data, Base64Data.SER_TYPE);
        }

        final EscMeta escMeta = EscSpiUtils.createEscMeta(serRegistry, targetContentType, commonEvent);
        final SerializedDataType escMetaType = new SerializedDataType(EscMeta.TYPE.asBaseType());
        final Serializer escMetaSerializer = getSerializer(escMetaType);
        final byte[] escSerMeta = escMetaSerializer.marshal(escMeta, escMetaType);

        final EventData.Builder builder = EventData.newBuilder().eventId(commonEvent.getId().asBaseType())
                .type(dataType);
        if (targetContentType.isJson()) {
            builder.jsonData(serData);
            builder.jsonMetadata(escSerMeta);
        } else {
            builder.data(serData);
            builder.metadata(escSerMeta);
        }
        return builder.build();
    }

static boolean isValidHostNameForSNI(String hostname) {
    // Check if the hostname is null or empty
    if (hostname == null || hostname.isEmpty()) {
        return false;
    }

    // Check if the hostname contains only valid characters
    if (!hostname.matches("[a-zA-Z0-9.-]+")) {
        return false;
    }

    // Check if the hostname starts or ends with a hyphen
    if (hostname.startsWith("-") || hostname.endsWith("-")) {
        return false;
    }

    // Check if the hostname contains consecutive hyphens
    if (hostname.contains("--")) {
        return false;
    }

    // Check if the hostname is a valid domain name
    String[] labels = hostname.split("\\.");
    for (String label : labels) {
        if (label.isEmpty() || label.length() > 63) {
            return false;
        }
    }

    // Check if the total length of the hostname is within the limit
    if (hostname.length() > 255) {
        return false;
    }

    return true;
}

 
public class Gamma {
    public static void main(String[] args) {
        System.out.println(" x\tStirling\t\tLanczos\n");
        for (int i = 1; i <= 20; i++) {
            double d = i / 10.0;
            System.out.printf("%4.2f\t", d);
            System.out.printf("%17.15f\t", gammaStirling(d));
            System.out.printf("%17.15f\n", gammaLanczos(d));
        }
    }
 
    public static double gammaStirling(double x) {
        return Math.sqrt(2.0 * Math.PI / x) * Math.pow(x / Math.E, x);
    }
 
    public static double gammaLanczos(double x) {
        double xx = x;
        double[] p = {
            0.99999999999980993,
            676.5203681218851,
            -1259.1392167224028,
            771.32342877765313,
            -176.61502916214059,
            12.507343278686905,
            -0.13857109526572012,
            9.9843695780195716e-6,
            1.5056327351493116e-7
        };
        int g = 7;
        if (xx < 0.5) return Math.PI / (Math.sin(Math.PI * xx) * gammaLanczos(1.0 - xx));
        xx--;
        double a = p[0];
        double t = xx + g + 0.5;
        for (int i = 1; i < p.length; i++) a += p[i] / (xx + i);
        return Math.sqrt(2.0 * Math.PI) * Math.pow(t, xx + 0.5) * Math.exp(-t) * a;
    }
}

