import java.util.Arrays;

public class Builder {
    public boolean doesValidArrayExist(int[] derived) {
        int n = derived.length;
        int[] original = new int[n];

        // Try with original[0] = 0
        original[0] = 0;
        for (int i = 0; i < n - 1; i++) {
            original[i + 1] = original[i] ^ derived[i];
        }
        if ((original[n - 1] ^ original[0]) == derived[n - 1]) {
            return true;
        }

        // Try with original[0] = 1
        original[0] = 1;
        for (int i = 0; i < n - 1; i++) {
            original[i + 1] = original[i] ^ derived[i];
        }
        if ((original[n - 1] ^ original[0]) == derived[n - 1]) {
            return true;
        }

        return false;
    }
}

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.RoundingMode;

public class BinomialDistribution {
    private final double probabilityOfSuccess;
    private final int numberOfTrials;
    private static final int PRECISION_SCALE = 10;

    public BinomialDistribution(double p, int n) {
        if (p < 0 || p > 1) {
            throw new IllegalArgumentException("Probability must be between 0 and 1");
        }
        if (n < 0) {
            throw new IllegalArgumentException("Number of trials must be non-negative");
        }
        this.probabilityOfSuccess = p;
        this.numberOfTrials = n;
    }

    public double pdf(int k) {
        if (k < 0 || k > numberOfTrials) {
            return 0.0;
        }
        return nChooseK(numberOfTrials, k) *
               Math.pow(probabilityOfSuccess, k) *
               Math.pow(1 - probabilityOfSuccess, numberOfTrials - k);
    }

    public double cdf(int k) {
        if (k < 0) {
            return 0.0;
        }
        if (k >= numberOfTrials) {
            return 1.0;
        }
        double cumulativeProbability = 0.0;
        for (int i = 0; i <= k; i++) {
            cumulativeProbability += pdf(i);
        }
        return cumulativeProbability;
    }

    private long nChooseK(int n, int k) {
        if (k > n) return 0;
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; i++) {
            result *= (n - k + i);
            result /= i;
        }
        return result;
    }

    public BigDecimal nChooseKLargeNumbers(int n, int k) {
        if (k > n) return BigDecimal.ZERO;
        if (k > n / 2) {
            k = n - k;
        }

        BigInteger numerator = BigInteger.ONE;
        BigInteger denominator = BigInteger.ONE;

        for (int i = 1; i <= k; i++) {
            numerator = numerator.multiply(BigInteger.valueOf(n - k + i));
            denominator = denominator.multiply(BigInteger.valueOf(i));
        }

        return new BigDecimal(numerator.divide(denominator))
            .setScale(PRECISION_SCALE, RoundingMode.HALF_UP);
    }

    public double getMean() {
        return numberOfTrials * probabilityOfSuccess;
    }

    public double getVariance() {
        return numberOfTrials * probabilityOfSuccess * (1 - probabilityOfSuccess);
    }

    public double getStandardDeviation() {
        return Math.sqrt(getVariance());
    }

    public double getMode() {
        int mode = (int) Math.floor((numberOfTrials + 1) * probabilityOfSuccess);
        return mode;
    }

public static Map<String, String> deserializeCatalogSignature(String signature) {
        Map<String, String> tableSignatures = Maps.newHashMap();
        for (String oneSig : signature.split(Pattern.quote(SIGNATURE_DELIMITER))) {
            if (!oneSig.isEmpty()) {
                final String[] parts = oneSig.split(Pattern.quote(SIGNATURE_TABLE_NAME_SEPARATOR), 2);
                tableSignatures.put(parts[0], parts[1]);
            }
        }
        return tableSignatures;
    }

