    public static int rot13char(int c) {
        if (c >= 'a' && c <='m' || c >= 'A' && c <= 'M') {
            return c + 13;
        } else if (c >= 'n' && c <= 'z' || c >= 'N' && c <= 'Z') {
            return c - 13;
        }
        return c;
    }
}

