import org.apache.hc.core5.reactor.IOSessionListener;
import org.apache.hc.core5.reactor.ListenerEndpoint;
import org.apache.hc.core5.util.TimeValue;

class AsyncServer extends IOReactorExecutor {

  private final DefaultListeningIOReactor ioReactor;

  public AsyncServer(
      final IOEventHandlerFactory eventHandlerFactory, final IOReactorConfig ioReactorConfig) {
    super();
    this.ioReactor =
        createIOReactor(
            eventHandlerFactory,
            ioReactorConfig,
            new LoggingIOSessionDecorator(),
            new LoggingIOSessionListener());
  }

  private DefaultListeningIOReactor createIOReactor(
      final IOEventHandlerFactory eventHandlerFactory,
      final IOReactorConfig ioReactorConfig,
      final Callback<IOSession> IOSessionDecorator,
      final IOSessionListener ioSessionListener) {

    return new DefaultListeningIOReactor(
        eventHandlerFactory, ioReactorConfig, IOSessionDecorator, ioSessionListener, null, null);
  }

  public Future<ListenerEndpoint> listen(final SocketAddress address) {
    return ioReactor.listen(address, null);
  }

  public Set<ListenerEndpoint> getEndpoints() {
    return ioReactor.getEndpoints();
  }

  DefaultListeningIOReactor reactor() {
    return ioReactor;
  }

  static class LoggingIOSessionDecorator implements Callback<IOSession> {

    @Override
    public void execute(final IOSession ioSession) {
      System.out.println("New session: " + ioSession);
    }
  }

  static class LoggingIOSessionListener implements IOSessionListener {

    @Override
    public void connected(final IOSession session) {
      System.out.println("Session connected: " + session);
    }

    @Override
    public void disconnected(final IOSession session) {
      System.out.println("Session disconnected: " + session);
    }

    @Override
    public void inputReady(IOSession session) {}

    @Override
    public void outputReady(IOSession session) {}

    @Override
    public void timeout(IOSession session) {}
  }
}

