import java.util.HashMap;
import java.util.Map;

public class HofstadterQ {
    public static void main(String[] args) {
        HofstadterQ hofstadterQ = new HofstadterQ();
        for (int i = 1; i <= 10; i++) {
            System.out.println("Q(" + i + ") = " + hofstadterQ.Q(i));
        }
        System.out.println("Q(1000) = " + hofstadterQ.Q(1000));
    }

    private Map<Integer, Integer> memo = new HashMap<>();

    public HofstadterQ() {
        memo.put(1, 1);
        memo.put(2, 1);
        memo.put(3, 1);
    }

    public int Q(int n) {
        Integer result = memo.get(n);
        if (result == null) {
            result = Q(n - Q(n - 1)) + Q(n - Q(n - 2));
            memo.put(n, result);
        }
        return result;
    }
}

class Counter {
    public boolean isReachableAtTime(int sx, int sy, int fx, int fy, int t) {
        int dx = Math.abs(sx - fx);
        int dy = Math.abs(sy - fy);
        if (dx == 0 && dy == 0 && t == 1) return false;
        return Math.max(dx, dy) - Math.min(dx, dy) <= t - Math.min(dx, dy);
    }
}

