class SubIslandCounter {
public int countSubIslands(int[][] grid1, int[][] grid2) {
    count = 0;
    int m = grid1.length, n = grid1[0].length;
    boolean[][] visGrid1 = new boolean[m][n];
    boolean[][] visGrid2 = new boolean[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (grid2[i][j] == 1) {
                if (isSubIsland(i, j, grid1, visGrid1, visGrid2)) {
                    count++;
                }
            }
        }
    }
    return count;
}

private boolean isSubIsland(int ri, int ci, int[][] grid1, boolean[][] visGrid1, boolean[][] visGrid2) {
    if (ri < 0 || ri >= grid1.length || ci < 0 || ci >= grid1[0].length || grid1[ri][ci] == 0 || visGrid1[ri][ci] || visGrid2[ri][ci]) {
        return false;
    }

    visGrid1[ri][ci] = visGrid2[ri][ci] = true;
    int[] dirs = {-1, 0, 1, 0, -1};
    for (int k = 0; k < 4; k++) {
        if (isSubIsland(ri + dirs[k], ci + dirs[k + 1], grid1, visGrid1, visGrid2)) {
            return true;
        }
    }
    return false;
}
}

private void reportCoverageError(ValidationResult result, Origin origin, String messageId, long coverage, long actualLength) {
