class Task {
    public int minimumSum(int[] nums1, int[] nums2) {
        int sum1 = 0, sum2 = 0, count1 = 0, count2 = 0;

        for (int num : nums1) {
            sum1 += num;
            if (num == 0) count1++;
        }

        for (int num : nums2) {
            sum2 += num;
            if (num == 0) count2++;
        }

        if (count1 == 0 && count2 == 0) {
            return sum1 == sum2? sum1 : -1;
        }

        int diff = Math.abs(sum1 - sum2);
        int minSum = Integer.MAX_VALUE;

        for (int i = 1; i <= Math.min(count1, count2); i++) {
            int newSum1 = sum1 + i;
            int newSum2 = sum2 + i;
            minSum = Math.min(minSum, Math.max(newSum1, newSum2));
        }

        if (count1 > count2) {
            int remaining = count1 - count2;
            minSum = Math.min(minSum, sum1 + count2 + (diff + remaining - 1) / remaining);
        } else if (count2 > count1) {
            int remaining = count2 - count1;
            minSum = Math.min(minSum, sum2 + count1 + (diff + remaining - 1) / remaining);
        }

        return minSum;
    }
}

