public class BlinkPlannerFactory implements PlannerFactory {

    private static final String PLANNER_TYPE_BATCH = "batch";
    private static final String PLANNER_TYPE_STREAMING = "streaming";

    @Override
    public Planner create(
        Executor executor,
        EnvironmentSettings environmentSettings,
        TableConfig tableConfig
    ) {
        validateConfiguration(environmentSettings);

        switch (environmentSettings.getExecutionType()) {
            case BATCH:
                return createBatchPlanner(executor, environmentSettings, tableConfig);
            case STREAMING:
                return createStreamingPlanner(executor, environmentSettings, tableConfig);
            default:
                throw new IllegalArgumentException("Unsupported execution type");
        }
    }

    private Planner createBatchPlanner(
        Executor executor,
        EnvironmentSettings settings,
        TableConfig tableConfig
    ) {
        try {
            Class<?> batchPlannerClass = Class.forName(
                "org.apache.flink.table.planner.batch.BatchPlanner"
            );
            return (Planner) batchPlannerClass
                .getConstructor(Executor.class, EnvironmentSettings.class, TableConfig.class)
                .newInstance(executor, settings, tableConfig);
        } catch (Exception e) {
            throw new RuntimeException("Unable to create batch planner", e);
        }
    }

    private Planner createStreamingPlanner(
        Executor executor,
        EnvironmentSettings settings,
        TableConfig tableConfig
    ) {
        try {
            Class<?> streamPlannerClass = Class.forName(
                "org.apache.flink.table.planner.stream.StreamPlanner"
            );
            return (Planner) streamPlannerClass
                .getConstructor(Executor.class, EnvironmentSettings.class, TableConfig.class)

