        setProjection(query.getProjection());
        setSelection(query.getSelection());
        setSelectionArgs(query.getSelectionArgs());
        setSortOrder(query.getSortOrder());
    }

    public void enableCursorCache(boolean enable) {
        this.cacheSize = enable ? 100 : 0;
    }

    public void enableCursorCache(int maxItems) {
        this.cacheSize = maxItems;
    }

    @Override
    public Cursor loadInBackground() {
        Cursor baseCursor = super.loadInBackground();
        CPOrmCursor<Model> ormCursor = new CPOrmCursor<>(baseCursor, tableDetails, cacheSize);

        if (cacheSize > 0) {
            int itemCount = ormCursor.getCount();
            int prefetchLimit = Math.min(cacheSize, itemCount);

            for (int position = 0; position < prefetchLimit; position++) {
                ormCursor.moveToPosition(position);
                ormCursor.getCachedModel();
            }
            ormCursor.moveToPosition(-1);
        }

        return ormCursor;
    }

    public static class CPOrmCursor<Model extends CPOrmModel> extends CursorWrapper {
        private final TableDetails tableDetails;
        private final SparseArray<Model> modelCache;
        private final int maxCacheSize;

        CPOrmCursor(Cursor cursor, TableDetails tableDetails, int maxCacheSize) {
            super(cursor);
            this.tableDetails = tableDetails;
            this.maxCacheSize = maxCacheSize;
            this.modelCache = maxCacheSize > 0 ? new SparseArray<>() : null;
        }

        public Model getModel() {
            if (modelCache == null) {
                return tableDetails.fromCursor(getWrappedCursor());
            }

            int currentPos = getPosition();
            Model cachedModel = modelCache.get(currentPos);

            if (cachedModel == null) {
                cachedModel = tableDetails.fromCursor(getWrappedCursor());

public class Delegator {
   private Object delegate;
   public String operation() {
      if (delegate!= null && delegate.getClass().getMethod("thing", null)!= null) {
         return (String) delegate.getClass().getMethod("thing", null).invoke(delegate, null);
      }
      return "default implementation";
   }
}
 
public class Delegate {
   public String thing() {
      return "delegate implementation";
   }
}
 
public class Finder {
   public static void main(String[] args) throws Exception {
      // No delegate
      Delegator a = new Delegator();
      assert a.operation().equals("default implementation");
 
      // With a delegate that does not implement "thing"
      a.delegate = "A delegate may be any object";
      assert a.operation().equals("default implementation");
 
      // With delegate that implements "thing"
      a.delegate = new Delegate();
      assert a.operation().equals("delegate implementation");
   }
}

