import java.util.function.Function;
import java.util.function.UnaryOperator;
 
public class Compose {
 
    // functor class to be returned by compose function
    public static class compose_functor<Fun1, Fun2> implements UnaryOperator<Fun2> {
        protected Fun1 f;
        protected Fun2 g;
 
        public compose_functor(Fun1 _f, Fun2 _g) {
            f = _f;
            g = _g;
        }
 
        public Fun1 operator()(Fun2 x) {
            return f(g(x));
        }
    }
 
    // we wrap it in a function so the compiler infers the template arguments
    // whereas if we used the class directly we would have to specify them explicitly
    public static <Fun1, Fun2> compose_functor<Fun1, Fun2> compose(Fun1 f, Fun2 g) {
        return new compose_functor<Fun1, Fun2>(f, g);
    }
 
    public static void main(String[] args) {
        System.out.println(compose(Math::sin, Math::asin).apply(0.5));
    }
}

import java.awt.Font;
import java.awt.Graphics2D;

public void drawString(Graphics2D g, String text, double x, double y) {
    // Set font and size
    Font font = new Font("Arial", Font.PLAIN, 12);
    g.setFont(font);

    // Get text dimensions
    int textWidth = g.getFontMetrics().stringWidth(text);
    int textHeight = g.getFontMetrics().getHeight();

    // Calculate pixel coordinates based on logical coordinates
    int pixelX = (int) (x * getWidth() - textWidth / 2);
    int pixelY = (int) (getHeight() - y * getHeight() - textHeight / 2);

    // Draw string
    g.drawString(text, pixelX, pixelY);
}

public Proposal convertToProposal(Transaction txn) {
    Proposal.Builder proposalBuilder = Proposal.newBuilder();
    proposalBuilder.setProposalBytes(ByteString.copyFrom(txn.toByteArray()));
    return proposalBuilder.build();
}

import java.util.HashMap;
import java.util.Map;
import java.util.Stack;
import java.util.regex.Pattern;
 
public class PostfixToInfix {
 
    static class Operator {
 
        public Operator(char t, int p, boolean i) {
            Token = t;
            Precedence = p;
            IsRightAssociative = i;
        }
 
        public char Token;
        public int Precedence;
        public boolean IsRightAssociative;
    }
 
    static Map<Character, Operator> operators = new HashMap<Character, Operator>() {
        {
            '+', new Operator('+', 2, false);
        },
        {
            '-', new Operator('-', 2, false);
        },
        {
            '/', new Operator('/', 3, false);
        },
        {
            '*', new Operator('*', 3, false);
        },
        {
            '^', new Operator('^', 4, true);
        }
    };
 
    static class Expression {
 
        public String ex;
        public Operator op;
 
        public Expression(String e) {
            ex = e;
        }
 
        public Expression(String e1, String e2, Operator o) {
            ex = String.format("%s %s %s", e1, o.Token, e2);
            op = o;
        }
    }
 
    static String PostfixToInfix(String postfix) {
        Stack<Expression> stack = new Stack<Expression>();
 
        for (String token : Pattern.compile("\\s+").split(postfix)) {
            char c = token.charAt(0);
 
            Operator op = operators.get(c);
            if (op!= null && token.length() == 1) {
                Expression rhs = stack.pop();
                Expression lhs = stack.pop();
 
                int opPrec = op.Precedence;
 
                int lhsPrec = lhs.op!= null? lhs.op.Precedence : Integer.MAX_VALUE;
                int rhsPrec = rhs.op!= null? rhs.op.Precedence : Integer.MAX_VALUE;
 
                if (lhsPrec < opPrec || (lhsPrec == opPrec && c == '^'))
                    lhs.ex = '(' + lhs.ex + ')';
 
                if (rhsPrec < opPrec || (rhsPrec == opPrec && c!= '^'))
                    rhs.ex = '(' + rhs.ex + ')';
 
                stack.push(new Expression(lhs.ex, rhs.ex, op));
            } else {
                stack.push(new Expression(token));
            }
 
            // print intermediate result
            System.out.printf("%s -> [%s]\n", token, String.join(", ", stack.stream().map(e -> e.ex).toArray(String[]::new)));
        }
        return stack.peek().ex;
    }
 
