        String[] inputs = { "3 4 2 * 1 5 - 2 3 ^ ^ / +", "1 2 + 3 4 + ^ 5 6 + ^" };
        for (String e : inputs) {

public class PandigitalMultiples {
    public static void main(String[] args) {
        int magic_number = 9 * 8 * 7;
        int div = 9876432 / magic_number * magic_number;
        int[] candidates = new int[div / magic_number + 1];
        for (int i = 0; i < candidates.length; i++) {
            candidates[i] = div - i * magic_number;
        }
        int res = 0;
        for (int c : candidates) {
            int[] digits = new int[10];
            int n = c;
            while (n > 0) {
                digits[n % 10]++;
                n /= 10;
            }
            boolean ok = true;
            for (int i = 0; i < 10; i++) {
                if (digits[i] > 1 || digits[i] == 0) {
                    ok = false;
                    break;
                }
            }
            if (ok) {
                res = c;
                break;
            }
        }
        System.out.println("Largest decimal number is " + res);
    }
}

