import org.w3c.dom.Node;

/**
 * An XPathFunction which will run XStream safe XPath queries.
 *
 * @see XStreamSafeEvaluator
 *
 */
public class XStreamSafeSearchFunction implements XPathFunction {

    private final Node rootNode;
    private XPath xpath;
    private static XStreamSafeEvaluator evaluator = new XStreamSafeEvaluator();

    public XStreamSafeSearchFunction(Node rootNode, XPath xpath) {
        this.rootNode = rootNode;
        this.xpath = xpath;
    }

    public Object evaluate(List parameters) throws XPathFunctionException {
        String xPathExpression = getXPathExpressionParameter(parameters);
        evaluator.setXpath(xpath);
        //Node rootSearchNode = getRootSearchNodeParameter(parameters);
        try {
            return evaluator.evaluate(xPathExpression, rootNode);
        } catch (XPathExpressionException e) {
            throw new XPathFunctionException(e);
        }
    }

    private String getXPathExpressionParameter(List parameters) throws XPathFunctionException {
        if (parameters.size() < 1) {
            throw new XPathFunctionException("First parameter must be an XPath expression.");
        }
        if (!(parameters.get(0) instanceof String)) {
            throw new XPathFunctionException("First parameter must be an XPath expression String");
        }
        return (String)parameters.get(0);
    }

    public XPath getXpath() {
        return xpath;
    }

    public void setXpath(XPath xpath) {
        this.xpath = xpath;
    }

    /*private Node getRootSearchNodeParameter(List parameters) throws XPathFunctionException {
        if (parameters.size() < 2) {
            throw new XPathFunctionException("Second parameter should be root node and is required");
        }
        System.out.println(parameters.get(1));
        if (!(parameters.get(1) instanceof Node)) {
            throw new XPathFunctionException("Second parameter should be an instance of Node (try using the root() XPath function).");
        }
        return (Node)parameters.get(1);
    }*/

}

public class Population {
    public static void main(String[] args) {
        final int SECONDS_PER_YEAR = 365 * 24 * 60 * 60; // seconds per year
        final int BIRTHS_PER_YEAR = SECONDS_PER_YEAR / 7; // number of births per year
        final int DEATHS_PER_YEAR = SECONDS_PER_YEAR / 13; // number of deaths per year
        final int IMMIGRANTS_PER_YEAR = SECONDS_PER_YEAR / 45; // number of immigrants per year
        int currentPopulation = 312032486; // current population
        int year = 1; // starting year

        // Calculate the population for each of the next five years
        for (int i = 0; i < 5; i++) {
            currentPopulation += BIRTHS_PER_YEAR + IMMIGRANTS_PER_YEAR - DEATHS_PER_YEAR;
            System.out.println("Year " + year + ": " + currentPopulation);
            year++;
        }
    }
}

import java.util.Scanner;  // kullanicidan giris almak icin gerekli

public class OgrenciNumarasi {

    // Ogrenci numarasindan kayit yilini cikarir
    int kayitYiliniBul(int numara) {
        // numaranin ust basamaklari yil bilgisini verir, 2000 eklenir
        return (numara / 10000000) + 2000;
    }

    // Ogrenci numarasindan siradaki kayit numarasini cikarir
    int kayitSirasiniBul(int numara) {
        // son 3 hane siralamayi belirtir
        return numara % 1000;
    }

    // Ogrenci numarasindan bolum bilgisini cozer
    String bolumAdiniBul(int numara) {
        int bolumKodu = (numara / 1000) % 10;

        String sonucAdi;
        if (bolumKodu == 7) {
            sonucAdi = "Elektrik Elektronik";
        } else if (bolumKodu == 6) {
            sonucAdi = "Bilgisayar";
        } else if (bolumKodu == 5) {
            sonucAdi = "Makina";
        } else {
            sonucAdi = "Bilinmiyor";
        }
        return sonucAdi;
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.println("Lutfen okul numaranizi giriniz");
        int okunanNumara = tarayici.nextInt();

        // Sabit test degeri ile ustune yazilir
        okunanNumara = 230707123;

        OgrenciNumarasi cozumleyici = new OgrenciNumarasi();

        System.out.println("Kayit yili: " + cozumleyici.kayitYiliniBul(okunanNumara));
        System.out.println("Kayit sirasi: " + cozumleyici.kayitSirasiniBul(okunanNumara));
        System.out.println("Bolum: " + cozumleyici.bolumAdiniBul(okunanNumara));

        tarayici.close();
    }
}

