public class Timer {
    public int countCornerRectangles(int[][] grid) {
        if (grid.length == 0) return 0;
        int m = grid.length, n = grid[0].length, res = 0;
        for (int i = 0; i < m; i++) {
            for (int j = i + 1; j < m; j++) {
                int common = 0;
                for (int k = 0; k < n; k++) {
                    if (grid[i][k] == 1 && grid[j][k] == 1) common++;
                }
                res += common * (common - 1) / 2;
            }
        }
        return res;
    }
}

protected List<ICompositeNode> internalFindValidReplaceRootNodeForChangeRegion(List<ICompositeNode> nodesEnclosingRegion) {
    List<ICompositeNode> validReplaceRootNodes = new ArrayList<>();
    for (ICompositeNode node : nodesEnclosingRegion) {
        ICompositeNode parent = node.getParent();
        if (parent != null) {
            // Check if the parent consumes all its current lookahead tokens
            if (parent.consumesAllLookaheadTokens()) {
                // Check if all lookahead tokens are located before the changed region
                if (areAllLookaheadTokensBeforeChangedRegion(parent)) {
                    validReplaceRootNodes.add(parent);
                }
            }
        }
    }
    return validReplaceRootNodes;
}

