public class BeanLocator implements Serializable {

    private static final Logger LOGGER = Logger.getLogger(BeanLocator.class.getName());
    private static final long serialVersionUID = 1L;

    private transient BeanManager beanManager;
    private static final Map<String, NGSessionScopeContext> SESSION_CONTEXTS = new ConcurrentHashMap<>();

    public BeanLocator() {
        initializeBeanManager();
    }

    private void initializeBeanManager() {
        try {
            InitialContext initialContext = new InitialContext();
            beanManager = (BeanManager) initialContext.lookup("java:comp/BeanManager");
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Bean manager initialization failed", e);
        }
    }

    public <T> T lookup(String beanName, String sessionID) {
        try {
            NGSessionScopeContext sessionContext = getOrCreateSessionContext(sessionID);
            Bean<T> bean = resolveBean(beanName);

            if (bean == null) {
                LOGGER.warning("No bean found for name: " + beanName);
                return null;
            }

            return getBeanInstance(bean, sessionContext);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Bean lookup failed", e);
            return null;
        }
    }

    private <T> Bean<T> resolveBean(String beanName) {
        try {
            return (Bean<T>) beanManager.getBeans(beanName).iterator().next();
        } catch (Exception e) {
            LOGGER.log(Level.WARNING, "Bean resolution failed for: " + beanName, e);
            return null;
        }
    }

    private <T> T getBeanInstance(Bean<T> bean, Context context) {
        CreationalContext<T> creationalContext = beanManager.createCreationalContext(bean);
        return (T) context.get(bean, creationalContext);
    }

    private NGSessionScopeContext getOrCreateSessionContext(String sessionID) {
        return SESSION_CONTEXTS.computeIfAbsent(sessionID, this::createNewSessionContext);
    }

    private NGSessionScopeContext createNewSessionContext(String sessionID) {

 
