public:
  int minSumOfLengths(vector<int>& arr, int target) {
    int n = arr.size();
    vector<int> pre(n + 1, 0);
    vector<int> dp(n + 1, INF);

    for (int i = 0; i < n; i++) {
      pre[i + 1] = pre[i] + arr[i];
    }

    for (int i = n - 1; i >= 0; i--) {
      // look for the pair that sums up to target
      int diff = target - pre[i];
      int start = lower_bound(pre.begin(), pre.end(), diff) - pre.begin();

      if (pre[start] - pre[i] != diff) {
        start = 0;
      }

      dp[i] = min(dp[i + 1], start != i ? dp[start] + (i - start) : INF);
    }

    // ans = best candidate for start of interval and best candidate
    // candidate for end of interval
    return dp[0] < INF ? dp[0] : -1;
  }
};

func minSumOfLengths(arr []int, target int) int {
    n := len(arr)
    presum := make([]int, n+1)
    sums := []int{INF}
    for i := 0; i < n; i++ {
        presum[i+1] = arr[i] + presum[i]
        for idx := len(sums) - 1; idx >= 0; {
            diff := target - presum[i]
            start := binarySearch(arr, diff, presum[:i+1])
            if presum[start] - presum[i] != diff {
                start = 0
            }
            sums[idx] = min(sums[idx], sums[start]+i-start)
            if sums[idx] < INF {
                return sums[idx]
            }
            idx--
        }
        sums = append(sums, INF)
    }
    if sums[len(sums)-1] == INF {
        return -1
    }
    return sums[len(sums)-1]
}

