public class SphericalDistance {
  private static final double Radius = 6371;  // rough radius of the Earth, in kilometers
  
  public static double sphericalDistance(double[] startCoords, double[] endCoords) {
    double[] lat1Long1 = deg2rad(startCoords);
    double[] lat2Long2 = deg2rad(endCoords);
    return 2 * Radius * asin(sqrt(sin((lat2Long2[0]-lat1Long1[0])/2)*sin((lat2Long2[0]-lat1Long1[0])/2) + cos(lat1Long1[0]) * cos(lat2Long2[0]) * sin((lat2Long2[1] - lat1Long1[1])/2)*sin((lat2Long2[1] - lat1Long1[1])/2)));
  }
  
  private static double[] deg2rad(double[] latLong) {
    return new double[] {latLong[0] * PI / 180, latLong[1] * PI / 180};
  }
  
  public static void main(String[] args) {
    double[] bna = {36.12, -86.67};
    double[] lax = {33.94, -118.4};
    System.out.printf("%.1f%n", sphericalDistance(bna, lax));
  }
}

