import javax.swing.tree.TreeNode;

    import java.util.LinkedList;

    public class FlipFlipEquivalent {

        public class TreeNode {
            int val;
            TreeNode left;
            TreeNode right;

            TreeNode() {
            }

            TreeNode(int val) {
                this.val = val;
            }

            TreeNode(int val, TreeNode left, TreeNode right) {
                this.val = val;
                this.left = left;
                this.right = right;
            }
        }

        public boolean flipEquiv(TreeNode root1, TreeNode root2) {
            LinkedList<Integer> firstC = new LinkedList<>();
            LinkedList<Integer> secondC = new LinkedList<>();

            preorder(root1, firstC, true);
            preorder(root2, secondC, true);

            if (firstC.size() == secondC.size()) {
                for (int i = 0; i < firstC.size(); i++) {
                    if (firstC.get(i) != secondC.get(i)) {
                        return false;
                    }
                }
                return true;
            }

            return false;
        }

        void preorder(TreeNode node, LinkedList<Integer> buff, boolean flip) {
            if (node == null) {
                return;
            }

            buff.add(flip ? node.val * 2 - 1 : node.val);

            preorder(node.left, buff, flip);
            preorder(node.right, buff, flip);
        }
    }

