import java.io.Serializable;
import java.util.Arrays;

public class FloatSparseArrayDataRow extends AbstractSparseArrayDataRow implements Serializable {
    private static final long serialVersionUID = 1L;

    private float[] values;
    private int[] indices;
    private int numberOfStoredValues;

    public FloatSparseArrayDataRow(int initialCapacity) {
        this.values = new float[initialCapacity];
        this.indices = new int[initialCapacity];
        this.numberOfStoredValues = 0;
    }

    @Override
    public double getValue(int index) {
        int arrayIndex = findIndex(index);
        return (arrayIndex >= 0) ? values[arrayIndex] : 0.0;
    }

    @Override
    public void setValue(int index, double value) {
        int arrayIndex = findIndex(index);

        if (value != 0.0) {
            if (arrayIndex >= 0) {
                values[arrayIndex] = (float) value;
            } else {
                insertValue(index, (float) value);
            }
        } else if (arrayIndex >= 0) {
            removeValue(arrayIndex);
        }
    }

    private void insertValue(int index, float value) {
        if (numberOfStoredValues == values.length) {
            resizeValues(values.length * 2);
        }

        int insertPos = findInsertPosition(index);
        System.arraycopy(indices, insertPos, indices, insertPos + 1, numberOfStoredValues - insertPos);
        System.arraycopy(values, insertPos, values, insertPos + 1, numberOfStoredValues - insertPos);

        indices[insertPos] = index;
        values[insertPos] = value;
        numberOfStoredValues++;
    }

    private void removeValue(int arrayIndex) {
        System.arraycopy(indices, arrayIndex + 1, indices, arrayIndex, numberOfStoredValues - arrayIndex - 1);
        System.arraycopy(values, arrayIndex + 1, values, arrayIndex, numberOfStoredValues - arrayIndex - 1);
        numberOfStoredValues--;
    }

    private void resizeValues(int newCapacity) {
        float[] newValues = Arrays.copyOf(values, newCapacity);
        int[] newIndices = Arrays.copyOf(indices, newCapacity);

        values = newValues;
        indices = newIndices;
    }

    private int findIndex(int searchIndex) {
        for (int i = 0; i < numberOfStoredValues; i++) {
            if (indices[i] == searchIndex) {
                return i;
            }
            if (indices[i] > searchIndex) {
                break;
            }
        }
        return -1;
    }

