import java.util.Comparator;
import java.util.Locale;

public class ArithmeticGeometricMean {

    private static double arithmeticGeometricMean(double number, double otherNumber, Comparator<Double> comparer) {
        return comparer.compare(number, otherNumber) == 0? number : arithmeticGeometricMean(arithmeticMean(number, otherNumber), geometricMean(number, otherNumber), comparer);
    }

    private static double arithmeticMean(double number, double otherNumber) {
        return 0.5 * (number + otherNumber);
    }

    private static double geometricMean(double number, double otherNumber) {
        return Math.sqrt(number * otherNumber);
    }

    public static void main(String[] args) {
        System.out.println(String.format(Locale.ENGLISH, "%f", arithmeticGeometricMean(1, 0.5 * Math.sqrt(2), new RelativeDifferenceComparer(1e-5))));
    }

    private static class RelativeDifferenceComparer implements Comparator<Double> {

        private final double maximumRelativeDifference;

        public RelativeDifferenceComparer(double maximumRelativeDifference) {
            this.maximumRelativeDifference = maximumRelativeDifference;
        }

        @Override
        public int compare(Double number, Double otherNumber) {
            return relativeDifference(number, otherNumber) <= maximumRelativeDifference? 0 : 1;
        }

        private static double relativeDifference(double number, double otherNumber) {
            return absoluteDifference(number, otherNumber) / norm(number, otherNumber);
        }

        private static double absoluteDifference(double number, double otherNumber) {
            return Math.abs(number - otherNumber);
        }

        private static double norm(double number, double otherNumber) {
            return 0.5 * (Math.abs(number) + Math.abs(otherNumber));
        }
    }
}

import java.util.Scanner;

public class Account {

    public static int count(char[] chars) {
        return count(chars, chars.length - 1);
    }

    public static int count(char[] chars, int high) {
        if (high < 0) {
            return 0;
        } else {
            int count = count(chars, high - 1);
            if (Character.isUpperCase(chars[high])) {
                count++;
            }
            return count;
        }
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a list of characters: ");
        String str = input.nextLine();

        char[] chars = str.toCharArray();
        int uppercaseCount = count(chars);

        System.out.println("The number of uppercase letters is " + uppercaseCount);
    }
}

import java.io.IOException;

import com.orientechnologies.common.thread.OSoftThread;
import com.orientechnologies.orient.core.Orient;
import com.orientechnologies.orient.core.record.ORecordInternal;

/**
 * Service thread that catches internal messages sent by the server
 *
 */
public class OAsynchChannelServiceThread extends OSoftThread {
  private OChannelBinaryAsynchClient network;
  private int                        sessionId;
  private ORemoteServerEventListener remoteServerEventListener;

  public OAsynchChannelServiceThread(final ORemoteServerEventListener iRemoteServerEventListener,
      final OChannelBinaryAsynchClient iChannel) {
    super(Orient.instance().getThreadGroup(), "OrientDB <- Asynch Client (" + iChannel.socket.getRemoteSocketAddress() + ")");
    sessionId = Integer.MIN_VALUE;
    remoteServerEventListener = iRemoteServerEventListener;
    network = iChannel;
    start();
  }

  @Override
  protected void execute() throws Exception {
    try {
      network.beginResponse(sessionId, 0);
      final byte request = network.readByte();

      Object obj = null;

      switch (request) {
      case OChannelBinaryProtocol.REQUEST_PUSH_RECORD:
        obj = (ORecordInternal<?>) OChannelBinaryProtocol.readIdentifiable(network);
        break;

      case OChannelBinaryProtocol.REQUEST_PUSH_DISTRIB_CONFIG:
        obj = network.readBytes();
        break;
      }

      if (remoteServerEventListener != null)
        remoteServerEventListener.onRequest(request, obj);

    } catch (IOException ioe) {
      // EXCEPTION RECEIVED (THE SOCKET HAS BEEN CLOSED?) ASSURE TO UNLOCK THE READ AND EXIT THIS THREAD
      sendShutdown();
      if (network != null) {
        final OChannelBinaryAsynchClient n = network;
        network = null;
        n.close();
      }

    } finally {
      if (network != null)
        network.endResponse();
    }
  }
}

import java.util.*;

public class Checker {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter five points: ");
        double[][] points = new double[5][5];

        for (int i = 0; i < points.length; i++) {
            for (int j = 0; j < 2; j++) {
                points[i][j] = in.nextDouble();
            }
        }

        if (sameLine(points)) {
            System.out.println("The points are on the same line.");
        } else {
            System.out.println("The points are not on the same line.");
        }

    }

    static boolean sameLine(double[][] points) {
        for (int i = 0; i < points.length - 2; i++) {
            double det = findDeterminate(points, 0);
            if (det != 0) {
                return false;
            }
        }
        return true;

    }

    static double findDeterminate(double[][] pts, int index) {
        return (pts[index + 1][0] - pts[index][0]) * (pts[index + 2][1] - pts[index][1]) - (pts[index + 2][0] - pts[index][0]) * (pts[index + 1][1] - pts[index][1]);

    }

}

