public static void transformAndWriteEntry(InputStream in, ZipEntry zipEntry, OutputStream out) throws IOException {
    try {
        if (out != null) {
            out.putNextEntry(zipEntry);
        }
        byte[] buffer = new byte[1024];
        int length;
        while ((length = in.read(buffer)) > 0) {
            // Transform the data here if necessary
            if (out != null) {
                out.write(buffer, 0, length);
            }
        }
        if (out != null) {
            out.closeEntry();
        }
    } finally {
        in.close();
    }
