public class RandomStatistics {
    public static void main(String[] args) {
        generateStatistics(100);
        generateStatistics(1000);
        generateStatistics(10000);
    }

    private static void generateStatistics(int n) {
        double sum = 0.0;
        double sum2 = 0.0;
        int[] hist = new int[10];
        for (int i = 0; i < n; i++) {
            double r = Math.random();
            sum += r;
            sum2 += Math.pow(r, 2);
            hist[(int) (10 * r)]++;
        }
        double mean = sum / n;
        double stddev = Math.sqrt((sum2 / n) - Math.pow(mean, 2));

        System.out.println("size: " + n);
        System.out.println("mean:   " + mean);
        System.out.println("stddev: " + stddev);
        for (int i = 0; i < hist.length; i++) {
            System.out.printf("%.1f:%s\n", 0.1 * i, new String(new char[70 * hist[i] / max(hist)]).replace("\0", "="));
        }
        System.out.println();
    }

    private static int max(int[] hist) {
        int max = 0;
        for (int i = 0; i < hist.length; i++) {
            if (hist[i] > max) {
                max = hist[i];
            }
        }
        return max;
    }
}

/**
 * Message indicating a client's connection attempt was rejected.
 */
public class SOCRejectConnection extends SOCMessage {

    private static final long serialVersionUID = 1L;

    /**
     * Message type identifier for SOCRejectConnection.
     */
    public static final int REJECTCONNECTION = 999;

    /**
     * The reason for the rejection.
     */
    private String text;

    /**
     * Constructor for SOCRejectConnection.
     *
     * @param message the reason for the rejection
     */
    public SOCRejectConnection(String message) {
        super(REJECTCONNECTION);
        this.text = message;
    }

    /**
     * Retrieve the rejection message text.
     *
     * @return the rejection message text
     */
    public String getText() {
        return text;
    }

    /**
     * Serialize the message into a command string.
     *
     * @return the command string representation of the message
     */
    public String toCmd() {
        return toCmd(text);
    }

    /**
     * Static method to serialize a given message text into a command string.
     *
     * @param tm the rejection message text
     * @return the command string representation of the message
     */
    public static String toCmd(String tm) {
        return REJECTCONNECTION + sep + tm;
    }

    /**
     * Deserialize a command string into a SOCRejectConnection object.
     *
     * @param s the command string
     * @return a SOCRejectConnection object created from the command string
     */
    public static SOCRejectConnection parseDataStr(String s) {
        return new SOCRejectConnection(s);
    }

    /**
     * Return a string representation of the message for debugging.
     *
     * @return a string representation of the message
     */
    @Override
    public String toString() {
        return "SOCRejectConnection:text=" + text;
    }

    /**
     * Check if two SOCRejectConnection messages are equal.
     *
     * @param msg the message to compare
     * @return true if the messages are equal, false otherwise
     */
    @Override
    public boolean equals(Object msg) {
        if (msg == null || !(msg instanceof SOCRejectConnection)) {
            return false;
        }
        SOCRejectConnection m = (SOCRejectConnection) msg;
        return text.equals(m.text);
    }

    /**
     * Generate a hash code for the message.
     *
     * @return the hash code
     */
    @Override
    public int hashCode() {
        return text.hashCode();
    }
}

import java.io.File;
import java.io.IOException;
import java.util.Scanner;

public class Runner {
    private static final String FILENAME_PREFIX = "babynameranking";
    private static final String workingDir = "ch_12/exercise12_31";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter the year: ");
        int year = in.nextInt();

        System.out.print("\nEnter the gender: ");
        String gender = in.next().trim();

        System.out.print("\nEnter the name: ");
        String name = in.next();

        int rank = getRank(year, gender.charAt(0), name);
        if (rank == -7) {
            System.out.println("That name is not on the list for that year....");
        }
        System.out.print("\n" + name + " is ranked #" + rank + " in year " + year);

        in.close();

    }

    private static int getRank(int year, char gender, String name) {
        if (year < 2001 || year > 2010) return -1;
        if (gender != 'M' && gender != 'F') return -2;

        int ranking = -7; // invalid name default if not set during do while loop
        String fileName = FILENAME_PREFIX + year + ".txt";
        File file = new File(workingDir, fileName);

        try (Scanner fileScanner = new Scanner(file)) {
            while (fileScanner.hasNextLine()) {
                String[] line = fileScanner.nextLine().split("\\s+"); //Example: 1  Jacob   32,550  Emily   25,057
                if (gender == 'M') {
                    if (line[1].equalsIgnoreCase(name)) {
                        ranking = Integer.parseInt(line[0].trim());
                        break;
                    }
                } else {
                    if (line[3].equalsIgnoreCase(name)) {
                        ranking = Integer.parseInt(line[0].trim());
                        break;
                    }
                }
            }

        } catch (IOException ioException) {
            ioException.printStackTrace();
        }
        return ranking;
    }
}

import java.util.Scanner;

public class CreditCardValidator {

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a credit card number as a long integer: ");
        long number = input.nextLong();
        input.close();
        if (isValid(number)) {
            System.out.println(number + " is valid");
        } else {
            System.out.println(number + " is invalid");
        }
    }

    public static boolean isValid(long number) {
        int sum = sumOfDoubleEvenPlace(number) + sumOfOddPlace(number);
        return sum % 10 == 0;
    }

    public static int sumOfDoubleEvenPlace(long number) {
        int sum = 0;
        int count = 0;
        while (number > 0) {
            count++;
            if (count % 2 == 0) {
                sum += getDigit((int) (2 * (number % 10)));
            }
            number /= 10;
        }
        return sum;
    }

    public static int getDigit(int number) {
        if (number < 10) {
            return number;
        } else {
            return number / 10 + number % 10;
        }
    }

    public static int sumOfOddPlace(long number) {
        int sum = 0;
        while (number > 0) {
            sum += (int) (number % 10);
            number /= 100;
        }
        return sum;
    }

    public static boolean prefixMatched(long number, int d) {
        return getPrefix(number, getSize(d)) == d;
    }

    public static int getSize(long d) {
        int size = 0;
        while (d > 0) {
            size++;
            d /= 10;
        }
        return size;
    }

    public static long getPrefix(long number, int k) {
        int size = getSize(number);
        if (size < k) {
            return number;
        } else {
            long prefix = number;
            for (int i = 0; i < size - k; i++) {
                prefix /= 10;
            }
            return prefix;
        }
    }
}

private static HashSet<String> stringToStringValues(String stringValue)
      throws IOException {

    HashSet<String> stringValues = new HashSet<>();
    JSONParser jsonParser = new JSONParser(stringValue);
    int event = jsonParser.nextEvent();
    if (event == JSONParser.ARRAY_START) {
      while ((event = jsonParser.nextEvent()) != JSONParser.ARRAY_END) {
        if (jsonParser.getLevel() == 1) {
          switch (event) {
          case JSONParser.STRING:
            stringValues.add(jsonParser.getString());
            break;
          case JSONParser.BIGNUMBER:
          case JSONParser.NUMBER:
          case JSONParser.LONG:
            stringValues.add(jsonParser.getNumberChars().toString());
            break;
          case JSONParser.BOOLEAN:
            stringValues.add(Boolean.toString(jsonParser.getBoolean()));
            break;
          default:

            break;
          }
        }
      }
    } else {
      throw new IOException("unsupported json structure");
    }
    return stringValues;
  }

import android.opengl.Matrix;

public final class TdlMath {
    private TdlMath() {}

    public static void perspective(float[] m, float fovY, float aspect, float near, float far) {
        float fovRad = (float) Math.toRadians(fovY);
        float f = 1.0f / (float) Math.tan(fovRad / 2.0f);
        float range = far - near;

        for (int i = 0; i < 16; i++) m[i] = 0.0f;

        m[0] = f / aspect;
        m[5] = f;
        m[10] = -(far + near) / range;
        m[11] = -1.0f;
        m[14] = (-2.0f * far * near) / range;
    }

    public static void pickMatrix(float[] m, float centerX, float centerY, float width, float height, float[] viewport) {
        float x = centerX - width / 2.0f;
        float y = centerY - height / 2.0f;

        float sx = viewport[2] / width;
        float sy = viewport[3] / height;
        float tx = (viewport[2] + 2.0f * (viewport[0] - x)) / width;
        float ty = (viewport[3] + 2.0f * (viewport[1] - y)) / height;

        for (int i = 0; i < 16; i++) m[i] = 0.0f;
        m[0] = sx;
        m[5] = sy;
        m[10] = 1.0f;
        m[12] = tx;
        m[13] = ty;
        m[15] = 1.0f;
    }

    public static float[] subVector(float[] a, float[] b) {
        return new float[]{a[0]-b[0], a[1]-b[1], a[2]-b[2]};
    }

    public static float dot(float[] a, float[] b) {
        return a[0]*b[0] + a[1]*b[1] + a[2]*b[2];
    }

    public static float[] cross(float[] a, float[] b) {
        return new float[]{
            a[1]*b[2] - a[2]*b[1],
            a[2]*b[0] - a[0]*b[2],
            a[0]*b[1] - a[1]*b[0]
        };
    }

    public static float[] normalize(float[] a) {
        float len = Matrix.length(a[0], a[1], a[2]);
        if (len == 0.0f) return new float[3];
        return new float[]{a[0]/len, a[1]/len, a[2]/len};
    }
}

public static int[][] Zig_Zag(final int size)
{
 int[][] data = new int[size][size];
 int i = 1;
 int j = 1;
 for (int element = 0; element < size * size; element++)
 {
  data[i - 1][j - 1] = element;
  if ((i + j) % 2 == 0)
  {
   // Even stripes
   if (j < size)
    j++;
   else
    i+= 2;
   if (i > 1)
    i--;
  }
  else
  {
   // Odd stripes
   if (i < size)
    i++;
   else
    j+= 2;
   if (j > 1)
    j--;
  }
 }
 return data;
}

class Order {
    public int[] sortArrayByParityII(int[] A) {
        int n = A.length;
        int[] ans = new int[n];
        int p1 = 0, p2 = 1;

        for (int a : A) {
            if (a % 2 == 0) {
                ans[p1] = a;
                p1 += 2;
            } else {
                ans[p2] = a;
                p2 += 2;
            }
        }

        return ans;
    }
}

public class AtamaIslemleri {

    public static void main(String[] args) {
        // Atama islemleri
        int x = 5; // x degiskenine 5 atandi
        int y = 10; // y degiskenine 10 atandi
        int z = 15; // z degiskenine 15 atandi

        // Toplama ve atama
        x = x + y; // x, x ve y'nin toplamina esit olur
        System.out.println("Toplama ve Atama: x = " + x + " y = " + y); // x simdi 15

        // Cikarma ve atama
        x -= y; // x, x ve y'nin farkina esit olur
        System.out.println("Cikarma ve Atama: x = " + x + " y = " + y); // x simdi 5

        // Carpma ve atama
        x *= 2; // x, x'in 2 ile carpimina esit olur
        System.out.println("Carpma ve Atama: x = " + x + " y = " + y); // x simdi 10

        // Bolme ve atama
        x /= 4; // x, x'in 4'e bolumune esit olur
        System.out.println("Bolme ve Atama: x = " + x + " y = " + y); // x simdi 2

        // Modul (Kalan) ve atama
        x %= 3; // x, x'in 3'e bolumunden kalanina esit olur
        System.out.println("Mod ve Atama: x = " + x + " y = " + y); // x simdi 2 % 3 = 2

        // x'in z ile toplanmasi
        x += z; // x, x ve z'nin toplamina esit olur
        System.out.println("Toplama ve Atama (x + z): x = " + x + " z = " + z); // x simdi 17

        // x'in z ile carpimi
        x *= z; // x, x ve z'nin carpimina esit olur
        System.out.println("Carpma ve Atama (x * z): x = " + x + " z = " + z); // x simdi 255

        // z'nin x'e bolunmesi
        x = z / x; // z'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (z / x): x = " + x + " z = " + z); // x simdi 0

        // y'nin x'e bolumunden kalan
        x = y % (x + 1); // y'nin x'e bolumunden kalan
        System.out.println("Mod ve Atama (y % (x + 1)): x = " + x + " y = " + y); // x simdi 0

        // y'nin x'e eklenmesi
        x = 10; // x'i 10'a ayarla
        y += x; // y, y ve x'in toplamina esit olur
        System.out.println("Toplama ve Atama (y + x): x = " + x + " y = " + y); // y simdi 20

        // y'nin x'e bolunmesi
        y /= x; // y, y'nin x'e bolumune esit olur
        System.out.println("Bolme ve Atama (y / x): x = " + x + " y = " + y); // y simdi 2

        // x'in negatif degeri
        x = -x; // x'in negatif degeri
        System.out.println("Negatif deger: x = " + x); // x simdi -10
    }
}

private void grow(int minCapacity) {
        int oldCapacity = queue.length;

        int newCapacity = oldCapacity + ((oldCapacity < 64) ?
                                         (oldCapacity + 2) :
                                         (oldCapacity >> 1));

        if (newCapacity - MAX_ARRAY_SIZE > 0)
            newCapacity = hugeCapacity(minCapacity);
        queue = Arrays.copyOf(queue, newCapacity);
    }

import java.io.File;
import java.util.Scanner;

public class Queue {

    public static void main(String[] args) {
        // Prompt the user to enter a directory or a file
        System.out.print("Enter a directory or a file: ");
        Scanner input = new Scanner(System.in);
        String directory = input.nextLine().trim();
        // Display the size
        System.out.println("The file: " + new File(directory).getName() + " contains " + getSize(new File(directory)) +
                " bytes");
    }

    public static long getSize(File file) {
        long TOTAL_BYTES = 0; // Store the total size of all files
        if (file.isDirectory()) {
            File[] files = file.listFiles(); // All files and subdirectories
            if (files != null && files.length > 0) {
                for (File f : files) {
                    if (f.isDirectory()) {
                        System.out.println("Reading Directory: " + f.getName());
                        File[] subFiles = f.listFiles();
                        if (subFiles != null && subFiles.length > 0) {
                            for (File subFile : subFiles) {
                                System.out.println("\t\tReading Sub-File: " + subFile.getName());
                                TOTAL_BYTES += subFile.length();
                            }
                        }

                    } else if (f.isFile()) {
                        System.out.println("Reading File: " + f.getName());
                        TOTAL_BYTES += f.length();

                    }

                }
            }

        } else if (file.isFile()) {
            return file.length();
        }
        return TOTAL_BYTES;
    }
}

