import java.util.*;

public class Calculator {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.println("Enter the loan amount: ");
        double loanAmount = in.nextDouble();

        System.out.println("Number of years: ");
        int numYears = in.nextInt();

        System.out.println("Annual Interest Rate (as a percent (ex. enter '7' for 7%)): ");
        double rate = in.nextDouble();

        /* Monthly interest rate */
        double monthlyInterestRate = rate / 1200;

        /* Monthly payment */
        double monthlyPayment = loanAmount * monthlyInterestRate / (1
                - 1 / Math.pow(1 + monthlyInterestRate, numYears * 12));
        System.out.printf("Monthly Payment: %.2f", monthlyPayment);

        double totalPayment = monthlyPayment * numYears * 12;

        System.out.printf("\nTotal Payment: %.2f", totalPayment);
        System.out.println();
        double balance = totalPayment;
        double principal;

        for (int i = 1; i <= numYears * 12; i++) {

            System.out.println("\nPayment# Interest Principal Balance");
            double interest = monthlyInterestRate * balance;
            principal = monthlyPayment - interest;
            balance = balance - principal;
            System.out.printf("%1d\t\t%4.2f\t\t%4.2f\t\t%.2f", i, interest, principal, balance);
        }

        in.close();
    }
}

import java.util.Scanner;
import java.lang.Math;
 
public class SunDial {
 
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter latitude       => ");
        double lat = sc.nextDouble();
        System.out.print("Enter longitude      => ");
        double lng = sc.nextDouble();
        System.out.print("Enter legal meridian => ");
        double ref = sc.nextDouble();
        System.out.println();
 
        double slat = Math.sin(Math.toRadians(lat));
        System.out.printf("    sine of latitude:   %.3f\n", slat);
        System.out.printf("    diff longitude:     %.3f\n", (lng-ref));
        System.out.println();
        System.out.println("Hour, sun hour angle, dial hour line angle from 6am to 6pm");
 
        for (int h = -6; h < 7; h++) {
            double hra = 15 * h;
            hra -= lng - ref;
            double hla = Math.toDegrees(Math.atan(slat * Math.tan(Math.toRadians(hra))));
            System.out.printf("HR=%3d; HRA=%7.3f; HLA=%7.3f\n", h, hra, hla);
        }
    }
}

public <T> Predicate<T> in (final Collection<? extends T> target)
    {
        return new Predicate<T>() {
            public boolean apply (T arg) {
                try {
                    return target.contains(arg);
                } catch (NullPointerException e) {
                    return false;
