        this.c= new CommandAPDU(c.getCLA(), c.getINS(), c.getP1(), c.getP2(), null);
        byte[] sw12=new byte[2];
        sw12[0]=(byte)r.getSW1();
        sw12[1]=(byte)r.getSW2();
        this.r= new ResponseAPDU(sw12);
