public static double entropy(String s) {
  Map<Character, Double> counts = new HashMap<>();
  for (char c : s.toCharArray()) {
    counts.put(c, counts.getOrDefault(c, 0.0) + 1);
  }
  int leng = s.length();
  return counts.values().stream()
   .mapToDouble(count -> {
      double freq = count / leng;
      return -freq * Math.log(freq) / Math.log(2);
    })
   .sum();
}

