public class HexFormatException extends Exception {
    public HexFormatException(String message) {
        super(message);
    }
}

public class HexConverter {
    public static int hex2Dec(String hexString) throws HexFormatException {
        int decimalValue = 0;
        for (int i = 0; i < hexString.length(); i++) {
            char hexChar = hexString.charAt(i);
            if (!(hexChar >= '0' && hexChar <= '9') &&
                !(hexChar >= 'A' && hexChar <= 'F') &&
                !(hexChar >= 'a' && hexChar <= 'f')) {
                throw new HexFormatException("Invalid hex string: " + hexString);
            }
            decimalValue = decimalValue * 16 + hexToDecimal(hexChar);
        }
        return decimalValue;
    }

    public static int hexToDecimal(char ch) {
        if (ch >= 'A' && ch <= 'F')
            return 10 + ch - 'A';
        else
            return ch - '0';
    }
}

import java.lang.Math;
 
public class Integrate {
 
    public static double leftrect(MathFunction f, double left, double right) {
        return f.call(left);
    }
 
    public static double midrect(MathFunction f, double left, double right) {
        return f.call((left+right)/2.0);
    }
 
    public static double rightrect(MathFunction f, double left, double right) {
        return f.call(right);
    }
 
    public static double trapezium(MathFunction f, double left, double right) {
        return (f.call(left) + f.call(right)) / 2.0;
    }
 
    public static double simpson(MathFunction f, double left, double right) {
        return (f.call(left) + 4*f.call((left+right)/2.0) + f.call(right)) / 6.0;
    }
 
    public static double integrate(MathFunction f, double a, double b, int steps, String method) {
        double delta = 1.0 * (b - a) / steps;
        double total = 0.0;
        for (int i = 0; i < steps; i++) {
            double left = a + i*delta;
            double right = left + delta;
            if (method.equals("leftrect")) {
                total += delta * leftrect(f, left, right);
            } else if (method.equals("midrect")) {
                total += delta * midrect(f, left, right);
            } else if (method.equals("rightrect")) {
                total += delta * rightrect(f, left, right);
            } else if (method.equals("trapezium")) {
                total += delta * trapezium(f, left, right);
            } else if (method.equals("simpson")) {
                total += delta * simpson(f, left, right);
            }
        }
        return total;
    }
 
    public static double square(double x) {
        return x*x;
    }
 
    public static double def_int(MathFunction f, double a, double b) {
        MathFunction l = null;
        if (f.toString().equals("square")) {
            l = new MathFunction() {
                public double call(double x) {
                    return (x*x*x)/3.0;
                }
            };
        } else if (f.toString().equals("sin")) {
            l = new MathFunction() {
                public double call(double x) {
                    return -Math.cos(x);
                }
            };
        }
        return l.call(b) - l.call(a);
    }
 
