        for (MathFunction func : new MathFunction[] {new MathFunction() {
                public double call(double x) {
                    return square(x);
                }
            }, Math.sin}) {

protected final Property parseVendorExtensionContent( String vendorExtension ) {
    // Check if the vendor extension is null or empty
    if ( vendorExtension == null || vendorExtension.isEmpty() ) {
        return null;
    }

    // Remove the curly braces from the vendor extension
    String contentWithoutBraces = vendorExtension.trim().replaceAll( "^\\{(.*)\\}$", "$1" );

    // Check if the content without braces is empty after removing the braces
    if ( contentWithoutBraces.isEmpty() ) {
        return null;
    }

    // Split the content into key-value pairs
    String[] keyValuePairs = contentWithoutBraces.split( "," );

    // Create a new Property object to hold the parsed key-value pairs
    Property property = new Property();

    // Iterate over the key-value pairs and add them to the Property object
    for ( String pair : keyValuePairs ) {
        String[] keyValue = pair.split( ":" );
        if ( keyValue.length == 2 ) {
            String key = keyValue[0].trim();
            String value = keyValue[1].trim();
            property.addProperty( key, value );
        }
    }

    // Return the Property object
    return property;
}

public class DisplayPatterns {

    public static void main(String[] args) {
        displayPatternA();
        displayPatternB();
        displayPatternC();
        displayPatternD();
    }

    public static void displayPatternA() {
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
        System.out.println();
    }

    public static void displayPatternB() {
        for (int i = 6; i >= 1; i--) {
            for (int j = 1; j <= i; j++) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
        System.out.println();
    }

    public static void displayPatternC() {
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6 - i; j++) {
                System.out.print("  ");
            }
            for (int j = i; j >= 1; j--) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
        System.out.println();
    }

    public static void displayPatternD() {
        for (int i = 1; i <= 6; i++) {
            for (int j = 1; j <= 6 - i; j++) {
                System.out.print("  ");
            }
            for (int j = 1; j <= i; j++) {
                System.out.print(j + " ");
            }
            System.out.println();
        }
        System.out.println();
    }
}

import java.util.Scanner;
 
public class NimGame {
 
    public static void main(String[] args) {
        runGame(12);
    }
 
    private static void runGame(int tokens) {
        System.out.printf("Nim game.%n%n");
 
        Scanner in = new Scanner(System.in);;
 
        do {
            boolean humanInputOk = false;
            int humanTokens = 0;
            while ( ! humanInputOk ) {
                System.out.printf("Human takes how many tokens?  ");
                String input = in.next();
                try {
                    humanTokens = Integer.parseInt(input);
                    if ( humanTokens >= 1 && humanTokens <= 3 ) {
                        humanInputOk = true;
                    }
                    else {
                        System.out.printf("Try a number between 1 and 3.%n");
                    }
                }
                catch (NumberFormatException e) {
                    System.out.printf("Invalid input.  Try a number between 1 and 3.%n");
                }
            }
 
            tokens -= humanTokens;
 
            System.out.printf("You take %d token%s.%n%d token%s remaining.%n%n", humanTokens, humanTokens > 1 ? "s" : "", tokens, tokens != 1 ? "s" : "");
            if ( tokens == 0 ) {
                System.out.printf("You win!!.%n%n");
                break;
            }
            int computerTokens = 4 - humanTokens;
            tokens -= computerTokens;
 
            System.out.printf("Computer takes %d token%s.%n%d token%s remaining.%n%n", computerTokens, computerTokens != 1 ? "s" : "", tokens, tokens != 1 ? "s" : "");
            if ( tokens == 0 ) {
                System.out.printf("Computer wins!!.%n%n");
            }
 
        } while (tokens > 0);
 
        in.close();
    }
 
}

