import java.util.ArrayList;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Generator {
    public static void main(String[] args) {
        String s = "entry1, entry2, \"entry, with comma\", entry4";
        List<String> entries = parseCommaSeparatedList(s);
        for (String entry : entries) {
            System.out.println(entry);
        }
    }

    protected static List<String> parseCommaSeparatedList(String s) {
        List<String> matchList = new ArrayList<String>();
        Pattern regex = Pattern.compile("\"([^\"]*)\"|([^,]+)");
        Matcher regexMatcher = regex.matcher(s);
        while (regexMatcher.find()) {
            if (regexMatcher.group(1) != null) {
                // Add double-quote delimited string
                matchList.add(regexMatcher.group(1));
            } else {
                // Add non-comma string
                matchList.add(regexMatcher.group(2));
            }
        }
        return matchList;
    }
}

