public class SecmeliSiralama {

    public static void main(String[] args) {
        int[] degerler = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        siralamayiUygula(degerler);

        System.out.println("Siralanmis Dizi:");
        StringBuilder cikti = new StringBuilder();
        for (int deger : degerler) {
            cikti.append(deger).append(' ');
        }
        System.out.print(cikti);
    }

    // Selection sort - her turda kalan en kucuk elemani one tasir
    public static void siralamayiUygula(int[] degerler) {
        int uzunluk = degerler.length;

        for (int sinir = 0; sinir < uzunluk - 1; sinir++) {
            int enKucukKonum = sinir;

            for (int arayan = sinir + 1; arayan < uzunluk; arayan++) {
                if (degerler[arayan] < degerler[enKucukKonum]) {
                    enKucukKonum = arayan;
                }
            }

            if (enKucukKonum != sinir) {
                int gecici = degerler[sinir];
                degerler[sinir] = degerler[enKucukKonum];
                degerler[enKucukKonum] = gecici;
            }
        }
    }
}

 
import java.util.regex.Pattern;
 
public class Isin {
    private static final Pattern r = Pattern.compile("^[A-Z]{2}[A-Z0-9]{9}[0-9]$");
 
    public static boolean isValid(String s) {
        // check format
        if (!s.matches(r.pattern())) return false;
        // validate checksum
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c >= '0' && c <= '9') {
                sb.append(c);
            } else if (c >= 'A' && c <= 'Z') {
                sb.append(String.format("%02d", c - 55));
            }
        }
        return luhn(sb.toString());
    }
 
    private static boolean luhn(String s) {
        int sumDigits(int n) {
            return n / 10 + n % 10;
        }
        String t = new StringBuilder(s).reverse().toString();
        int s1 = t.chars().filter(i -> i % 2 == 0).map(i -> i - '0').sum();
        int s2 = t.chars().filter(i -> i % 2 == 1).map(i -> sumDigits((i - '0') * 2)).sum();
        return (s1 + s2) % 10 == 0;
    }
}
 
