import java.util.Scanner;

/**
 * A painting, which is an Item with dimensions and style flags.
 */
public class Painting extends Item {
    private int height;
    private int width;
    private boolean isWatercolour;
    private boolean isFramed;

    public Painting() {
    }

    public Painting(int value, String creator, int height, int width, boolean isWatercolour, boolean isFramed) {
        super(value, creator);
        this.height = height;
        this.width = width;
        this.isWatercolour = isWatercolour;
        this.isFramed = isFramed;
    }

    public int getHeight() {
        return height;
    }

    public void setHeight(int height) {
        this.height = height;
    }

    public int getWidth() {
        return width;
    }

    public void setWidth(int width) {
        this.width = width;
    }

    public boolean isIsWatercolour() {
        return isWatercolour;
    }

    public void setIsWatercolour(boolean isWatercolour) {
        this.isWatercolour = isWatercolour;
    }

    public boolean isIsFramed() {
        return isFramed;
    }

    public void setIsFramed(boolean isFramed) {
        this.isFramed = isFramed;
    }

    @Override
    public String toString() {
        return "Painting[" + super.toString() + "height=" + height + ",width=" + width + ",isWatercolour=" + isWatercolour + ",isFramed=" + isFramed + ']';
    }

    public void inputPainting() {
        super.input();
        Scanner scanner = new Scanner(System.in);
        System.out.print("Input a height: ");
        height = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Input a width: ");
        width = scanner.nextInt();
        scanner.nextLine();
        System.out.print("Is watercolour: ");
        isWatercolour = scanner.nextBoolean();
        scanner.nextLine();
        System.out.print("Is Framed: ");
        isFramed = scanner.nextBoolean();
        scanner.nextLine();
    }

    public void outputPainting() {
        super.output();
        System.out.println("Height: " + height);
        System.out.println("Width: " + width);
        System.out.println("Is Watercolour: " + isWatercolour);
        System.out.println("Is Framed: " + isFramed);
    }
}

import java.util.Random;
import java.util.Locale;
import java.io.UnsupportedEncodingException;
import java.util.Arrays;
 
public class ChessRank {
 
    private static char[] rank = new char[9];
 
    private static int[] pos = new int[8];
 
    private static void swap(int i, int j) {
        int temp = pos[i];
        pos[i] = pos[j];
        pos[j] = temp;
    }
 
    private static void generateFirstRank() {
        int kPos, qPos, bPos1, bPos2, rPos1, rPos2, nPos1, nPos2, i;
 
        for (i = 0; i < 8; i++) {
            rank[i] = 'e';
            pos[i] = i;
        }
 
        do {
            kPos = new Random().nextInt(8);
            rPos1 = new Random().nextInt(8);
            rPos2 = new Random().nextInt(8);
        } while ((rPos1 - kPos <= 0 && rPos2 - kPos <= 0) || (rPos1 - kPos >= 0 && rPos2 - kPos >= 0) || (rPos1 == rPos2 || kPos == rPos1 || kPos == rPos2));
 
        rank[pos[rPos1]] = 'R';
        rank[pos[kPos]] = 'K';
        rank[pos[rPos2]] = 'R';
 
        swap(rPos1, 7);
        swap(rPos2, 6);
        swap(kPos, 5);
 
        do {
            bPos1 = new Random().nextInt(5);
            bPos2 = new Random().nextInt(5);
        } while (((pos[bPos1] - pos[bPos2]) % 2 == 0) || (bPos1 == bPos2));
 
        rank[pos[bPos1]] = 'B';
        rank[pos[bPos2]] = 'B';
 
        swap(bPos1, 4);
        swap(bPos2, 3);
 
        do {
            qPos = new Random().nextInt(3);
            nPos1 = new Random().nextInt(3);
        } while (qPos == nPos1);
 
        rank[pos[qPos]] = 'Q';
        rank[pos[nPos1]] = 'N';
 
        for (i = 0; i < 8; i++)
            if (rank[i] == 'e') {
                rank[i] = 'N';
                break;
            }
    }
 
    private static void printRank() {
        int i;
 
        if (System.getProperty("os.name").contains("Windows")) {
            System.out.println(Arrays.toString(rank));
        } else {
            try {
                System.out.println(new String(rank, "UTF-8"));
            } catch (UnsupportedEncodingException e) {
                e.printStackTrace();
            }
        }
    }
 
    public static void main(String[] args) {
        int i;
 
        for (i = 0; i < 9; i++) {
            generateFirstRank();
            printRank();
        }
    }
}

