// Using type coercion
public static void compare(int a, int b) {
  if (a==b) print(a + " equals " + b);
  if (a < b) print(a + " is less than " + b);
  if (a > b) print(a + " is greater than " + b);
}
 
// Without using type coercion and using standards
// Written for browsers
// assumption of a and b are both integers if typeof test passes
public static void compare (int a, int b) {
  if (a.getClass() === b.getClass()) {
    if (a === b) {
      document.writeln(a + " equals " + b);
    }
    if (a < b) {
      document.writeln(a + " is less than " + b);
    }
    if (a > b) {
      document.writeln(a + " is greater than " + b);
    }
  } else {
    // "1" and 1 are an example of this as the first is type string and the second is type number
    print(a + "{" + (typeof a) + "} and " + b + "{" + (typeof b) + "} are not of the same type and cannot be compared.");
  }
}

import com.github.javaparser.JavaParser;
import com.github.javaparser.ast.CompilationUnit;
import com.github.javaparser.ast.body.MethodDeclaration;
import com.github.javaparser.ast.visitor.VoidVisitorAdapter;

public class MethodNamePrinter {
    public static void main(String[] args) {
        // creates an instance of a JavaParser
        JavaParser javaParser = new JavaParser();

        // parses the code into an Abstract Syntax Tree (AST)
        CompilationUnit cu = javaParser.parse("class A { void aMethod() {} }").getResult().get();

        // visits the AST and prints the names of all methods
        cu.accept(new VoidVisitorAdapter() {
            @Override
            public void visit(MethodDeclaration n, Void arg) {
                System.out.println(n.getName());
                super.visit(n, arg);
            }
        }, null);
    }
}

class Utils {
    public String minimizeResult(String expression) {
        String[] strings = expression.split("\\+");
        String minStr = expression;
        int value = Integer.MAX_VALUE;
        for (int i = 0; i < strings[0].length(); i++) {
            for (int j = 1; j <= strings[1].length(); j++) {
                int a = i == 0 ? 1 : Integer.parseInt(strings[0].substring(0, i));
                int b = Integer.parseInt(strings[0].substring(i));
                int c = Integer.parseInt(strings[1].substring(0, j));
                int d = j == strings[1].length() ? 1 : Integer.parseInt(strings[1].substring(j));
                int v = a * (b + c) * d;
                if (v < value) {
                    minStr = "";
                    minStr += (i == 0 ? "" : (a + ""));
                    minStr += "(";
                    minStr += b;
                    minStr += "+";
                    minStr += c;
                    minStr += ")";
                    minStr += (j == strings[1].length() ? "" : d);
                    value=v;
                }
            }
        }
        return minStr;
    }
}

