import java.net.HttpURLConnection;
import java.net.URL;
import java.io.IOException;

public class HttpDeleteRequest {

    public interface Callback {
        void onResponse(int responseCode);
    }

    public void asyncDelete(final String url, final Callback callback) {
        new Thread(new Runnable() {
            @Override
            public void run() {
                try {
                    URL url = new URL(url);
                    HttpURLConnection httpCon = (HttpURLConnection) url.openConnection();
                    httpCon.setRequestMethod("DELETE");

                    int responseCode = httpCon.getResponseCode();
                    callback.onResponse(responseCode);

                    httpCon.disconnect();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }).start();
    }
}

public:
    string shortestFancyString(string s) {

        if(s.size() <= 3)
            return s;

        int size = s.size();
        string ans  = s;
        int ansLen=0;

        stack < pair<string, int> > stk;

        for(int i=0;i<size;i++){
            pair <string, int> temp = make_pair(s[i], 1);
            stk.push(temp);

            while(stk.size() > 2){
                temp= stk.top();
                stk.pop_back();

                if(temp.first[0] == s[i-2][0]){
                    ans[i] = temp.second == 1 ? s[i+1] : s[i-1];
                    ansLen = i-1 == ans[i] ? ansLen - 1 : ansLen;

                }else{
                    ans[i] = temp.first;
                    ansLen = ansLen + 1;
                }

            }

            ans[i] = temp.first;

            if(temp.second == size){
                ansLen =ansLen + temp.second;

                if(ansLen < ans.size()){
                    ans = ans;
                }else{
                    int j=i;
                    while(j>0 && s[j-1]==ans[j-1])
                        j--;
                    ans[j] = '';
                    ansLen = ansLen - size;
                }
            }

        for(int i = ansLen - 1; i<ansLen; i++){
            stk.push(make_pair(s[i], 1));
        }

        int flag = 0;
        for(int i = ansLen - 1; i<ansLen; i++){
             if (!stk.empty() && stk.top().second < i){
                 ans[i] = stk.top().first;
                 stk.pop_back();
                 flag = 1;
             }
        }
        if(flag == 1){
            int j = ansLen;
            while(j>0 && s[j-1]==ans[j-1])
                j--;
            ans[j] = '';
            ansLen = ansLen - size;
        }

        return ans;
    }
};

