import java.util.Scanner;

public class MaxBitwiseSum {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt(); // Number of test cases

        while (t-- > 0) {
            int n = scanner.nextInt(); // Length of binary numbers
            StringBuilder a = new StringBuilder();
            boolean needZero = false; // Flag to handle leading zeroes

            for (int i = 0; i < n; i++) {
                char bChar = scanner.next().charAt(0);
                int bDigit = bChar - '0';
                int sum = a.length() == 0 ? bDigit : a.charAt(a.length() - 1) ^ bDigit;
                a.append(sum == 2 ? '1' : '0');

                // If the last character of 'c' and current 'b' digit are different, append '1' to 'a'
                if (a.length() > 0 && (a.charAt(a.length() - 1) != '1' || bDigit != 0)) {
                    a.append('1');
                }

                // Check if the current 'b' digit is not '0' and insert '0' at the start of 'a'
                if (bDigit != 0 && a.charAt(a.length() - 1) != '1') {
                    a.insert(0, '0');
                    needZero = true;
                }
            }

            // Print the binary number 'a' which gives the maximum 'd'
            System.out.println(a);

            if (needZero) {
                // Print minimal original binary number 'a', equivalent to max 'd'
                System.out.println(Integer.toBinaryString(Integer.parseInt(a.toString() + '0') - 1).length()
                        + Integer.toBinaryString(Integer.parseInt(a.toString() + '0') - 1));
            }
        }

        scanner.close();
    }
}

