import com.alibaba.fastjson.JSON;
import com.alibaba.fastjson.serializer.SerializerFeature;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.nio.charset.Charset;
import org.springframework.http.HttpInputMessage;
import org.springframework.http.HttpOutputMessage;
import org.springframework.http.MediaType;
import org.springframework.http.converter.AbstractHttpMessageConverter;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.http.converter.HttpMessageNotWritableException;
import org.springframework.stereotype.Service;
import org.springframework.util.Base64Utils;

@Service
public class JsonHttpMessageConverter extends AbstractHttpMessageConverter<Object> {

  private Charset charset = Charset.forName("UTF-8");
  private SerializerFeature[] features = new SerializerFeature[0];

  public JsonHttpMessageConverter() {
    super(new MediaType("application", "json", Charset.forName("UTF-8")));
  }

  @Override
  protected boolean supports(Class<?> clazz) {
    return true;
  }

  public Charset getCharset() {
    return this.charset;
  }

  public void setCharset(Charset charset) {
    this.charset = charset;
  }

  public SerializerFeature[] getFeatures() {
    return features;
  }

  public void setFeatures(SerializerFeature... features) {
    this.features = features;
  }

  @Override
  protected Object readInternal(Class<?> clazz, HttpInputMessage inputMessage)
      throws IOException, HttpMessageNotReadableException {

    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    InputStream in = inputMessage.getBody();

    byte[] buf = new byte[1024];
    for (; ; ) {
      int len = in.read(buf);
      if (len == -1) {
        break;
      }
      if (len > 0) {
        baos.write(buf, 0, len);
      }
    }

    byte[] bytes = baos.toByteArray();
    byte[] decodedBytes = Base64Utils.decode(bytes);
    String jsonString = new String(decodedBytes, charset);
    return JSON.parseObject(jsonString, clazz);
  }

  @Override
  protected void writeInternal(Object obj, HttpOutputMessage outputMessage)
      throws IOException, HttpMessageNotWritableException {

    String jsonString = JSON.toJSONString(obj, features);
    byte[] encodedBytes = Base64Utils.encode(jsonString.getBytes(charset));
    OutputStream out = outputMessage.getBody();
    out.write(encodedBytes);
  }
}

import java.util.Scanner;

public class AksTest {
    static long[] c = new long[100];

    public static void main(String[] args) {
        for (int n = 0; n < 10; n++) {
            coef(n);
            System.out.print("(x-1)^" + n + " = ");
            show(n);
            System.out.println("");
        }

        System.out.print("Primes:");
        for (int n = 1; n <= 63; n++)
            if (is_prime(n))
                System.out.print(n + " ");

        System.out.println('\n');
        System.exit(0);
    }

    static void coef(int n) {
        int i, j;

        if (n < 0 || n > 63)
            System.exit(0);

        for (c[i = 0] = 1L; i < n; c[0] = -c[0], i++)
            for (c[1 + (j = i)] = 1L; j > 0; j--)
                c[j] = c[j - 1] - c[j];
    }

    static boolean is_prime(int n) {
        int i;

        coef(n);
        c[0] += 1;
        c[i = n] -= 1;

        while (i--!= 0 && (c[i] % n) == 0)
            ;

        return i < 0;
    }

    static void show(int n) {
        do {
            System.out.print("+" + c[n] + "x^" + n);
        } while (n--!= 0);
    }
}

import java.util.*;

public class Tree {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.println("Enter your packages weight: ");
        String shipping = "";

        double weight = in.nextDouble();

        if (weight > 50) {
            System.out.println("The package cannot be shipped.");
            in.close();
            return;
        } else if (weight > 0 && weight <= 1) {
            shipping += 3.5;

        } else if (weight > 1 && weight <= 3) {
            shipping += 5.5;

        } else if (weight > 3 && weight <= 10) {
            shipping += 8.5;

        } else if (weight > 10 && weight <= 20) {
            shipping += 10.5;

        }
        System.out.println("With a package weight of " + weight + " your cost of shipping will be " + shipping);
        in.close();
    }
}

import java.time.LocalTime;
import javafx.animation.Animation;
import javafx.animation.KeyFrame;
import javafx.animation.Timeline;
import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.scene.shape.Line;
import javafx.scene.text.Font;
import javafx.scene.text.Text;
import javafx.stage.Stage;
import javafx.util.Duration;

public class DefaultClock extends Application {

    private int hour;
    private int minute;
    private int second;

    private double width = 400;
    private double height = 400;

    public DefaultClock() {
        LocalTime now = LocalTime.now();
        this.hour = now.getHour();
        this.minute = now.getMinute();
        this.second = now.getSecond();

        Timeline timeline = new Timeline(new KeyFrame(Duration.seconds(1), e -> {
            tick();
            paintClock();
        }));
        timeline.setCycleCount(Animation.INDEFINITE);
        timeline.play();
    }

    private void tick() {
        second++;
        if (second >= 60) {
            second = 0;
            minute++;
            if (minute >= 60) {
                minute = 0;
                hour++;
                if (hour >= 24) {
                    hour = 0;
                }
            }
        }
    }

    private void paintClock() {
        double centerX = width / 2;
        double centerY = height / 2;
        double radius = Math.min(width, height) * 0.4;

        Circle circle = new Circle(centerX, centerY, radius);
        circle.setFill(Color.WHITE);
        circle.setStroke(Color.BLACK);
        circle.setStrokeWidth(2);

        Text[] numbers = new Text[12];
        for (int i = 0; i < 12; i++) {
            double angle = i * 30 * Math.PI / 180;
            double x = centerX + (radius - 30) * Math.sin(angle);
            double y = centerY - (radius - 30) * Math.cos(angle);
            numbers[i] = new Text(x, y, Integer.toString((i == 0) ? 12 : i));
            numbers[i].setFont(Font.font("Arial", 20));
        }

        Line hourHand = new Line(centerX, centerY, centerX + radius * 0.4 * Math.sin(hour * 30 * Math.PI / 180),
                centerY - radius * 0.4 * Math.cos(hour * 30 * Math.PI / 180));
        hourHand.setStrokeWidth(6);
        hourHand.setStroke(Color.BLACK);

        Line minuteHand = new Line(centerX, centerY, centerX + radius * 0.6 * Math.sin(minute * 6 * Math.PI / 180),
                centerY - radius * 0.6 * Math.cos(minute * 6 * Math.PI / 180));
        minuteHand.setStrokeWidth(4);

