import java.util.logging.Logger;
import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import org.restlet.resource.Get;
import org.restlet.resource.Post;
import org.restlet.resource.ServerResource;
import org.restlet.representation.Representation;
import org.restlet.data.Status;

public class MeetingResource extends ServerResource {
    private static final Logger LOGGER = Logger.getLogger(MeetingResource.class.getName());

    @PersistenceContext
    private EntityManager entityManager;

    private MeetingDao meetingDao;
    private MeetingMapper meetingMapper;

    public MeetingResource() {
        this.meetingDao = new LeanBeanJpaDao();
        this.meetingMapper = new MeetingMapper();
    }

    @Get("json")
    public MeetingViewTO retrieveMeeting() {
        try {
            String encodedId = getAttribute("meetingId");
            if (encodedId == null || encodedId.isEmpty()) {
                setStatus(Status.CLIENT_ERROR_BAD_REQUEST);
                return null;
            }

            Long decodedId = decodeHashedIdentifier(encodedId);
            Meeting meeting = meetingDao.findById(decodedId);

            if (meeting == null) {
                setStatus(Status.CLIENT_ERROR_NOT_FOUND);
                return null;
            }

            MeetingViewTO meetingView = meetingMapper.toViewTransferObject(meeting);
            LOGGER.info("Meeting retrieved successfully: " + decodedId);
            return meetingView;

        } catch (Exception e) {
            LOGGER.severe("Error retrieving meeting: " + e.getMessage());
            setStatus(Status.SERVER_ERROR_INTERNAL);
            return null;
        }
    }

    @Post("json")
    public MeetingViewTO createMeeting(MeetingTO meetingTransferObject) {
        try {
            validateMeetingTO(meetingTransferObject);

            Meeting meetingEntity = meetingMapper.toEntity(meetingTransferObject);
            Meeting savedMeeting = meetingDao.save(meetingEntity);

            MeetingViewTO createdMeetingView = meetingMapper.toViewTransferObject(savedMeeting);
            String encodedId = encodeIdentifier(savedMeeting.getId());
            createdMeetingView.setEncodedId(encodedId);

            LOGGER.info("Meeting created successfully: " + savedMeeting.getId());
            setStatus(Status.SUCCESS_CREATED);
            return createdMeetingView;

        } catch (IllegalArgumentException e) {
            LOGGER.warning("Invalid meeting data: " + e.getMessage());
            setStatus(Status.CLIENT_ERROR_BAD_REQUEST);
            return null;

