public class ActionDeleteWithWorkCompleted extends BaseAction {

    private static Logger logger = LoggerFactory.getLogger(ActionDeleteWithWorkCompleted.class);

    ActionResult<Wo> execute(EffectivePerson effectivePerson, String id, String workCompletedId) throws Exception {
        try (EntityManagerContainer emc = EntityManagerContainerFactory.instance().create()) {
            ActionResult<Wo> result = new ActionResult<>();
            Business business = new Business(emc);

            Attachment attachment = emc.find(id, Attachment.class);
            if (null == attachment) {
                throw new ExceptionEntityNotExist(id, Attachment.class);
            }

            WorkCompleted workCompleted = emc.find(workCompletedId, WorkCompleted.class);
            if (null == workCompleted) {
                throw new ExceptionEntityNotExist(workCompletedId, WorkCompleted.class);
            }

            if (!business.canManageApplicationOrProcess(effectivePerson,
                    business.application().get(attachment.getApplication()),
                    business.process().get(attachment.getProcess()))) {
                throw new ExceptionAccessDenied(effectivePerson);
            }

            Wo wo = ThisApplication.context().applications()
                    .deleteQuery(x_processplatform_service_processing.class,
                            Applications.joinQueryUri("attachment", "workcompleted", id, workCompletedId))
                    .getData(Wo.class);

            result.setData(wo);
            return result;
        }
    }

    public static class Wo extends WoId {
    }

    public static class WoControl extends GsonPropertyObject {
    }
}

