import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.stream.IntStream;
import java.util.stream.Stream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.Base64;
 
public class Brute {
    private static final String[] hashes = {
        "1115dd800feaacefdf481f1f9070374a2a81e27880f187396db67958b207cbad",
        "3a7bd3e2360a3d29eea436fcfb7e44c735d117c42d1c1835420b6b9942dd4f1b",
        "74e1bb62f8dabb8125a58852b63bdf6eaef667cb56ac7f7cdba6d7305c50a22f"
    };
    private static final int THREADS = 26;
    private static final int LENGTH = 5;
    private static final int START = 97;
    private static final int END = 97 + 26;
    private static final int MAX_ATTEMPTS = 1000000000;
    private static final AtomicInteger attempts = new AtomicInteger(0);
    private static final AtomicReference<String> password = new AtomicReference<String>(null);
    private static final ExecutorService executor = Executors.newFixedThreadPool(THREADS);
    private static final char[] letters = new char[LENGTH];
    private static final byte[] buffer = new byte[LENGTH];
    private static final MessageDigest digest;
    static {
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }
    private static void brute(int firstLetterAscii) {
        letters[0] = (char) firstLetterAscii;
        for (int i = 1; i < LENGTH; i++) {
            letters[i] = (char) START;
        }
        while (true) {
            if (password.get()!= null) {
                return;
            }
            if (attempts.get() > MAX_ATTEMPTS) {
                return;
            }
            for (int i = 0; i < LENGTH; i++) {
                buffer[i] = (byte) letters[i];
            }
            String hash = Base64.getEncoder().encodeToString(digest.digest(buffer));
            if (Arrays.asList(hashes).contains(hash)) {
                password.set(new String(letters));
                return;
            }
            for (int i = LENGTH - 1; i >= 0; i--) {
                if (letters[i] < END - 1) {
                    letters[i]++;
                    break;
                } else {
                    letters[i] = (char) START;
                }
            }
            attempts.incrementAndGet();
        }

public String getPageContent(String pageTitle, String queryParams,
      boolean checkNotNull) throws Exception {
    Api api = getQueryResult("&prop=revisions&rvprop=content" + queryParams
        + "&titles=" + normalizeTitle(pageTitle));
    handleError(api);
    List<Page> pages = api.getQuery().getPages();
    String content = null;
    if (pages != null) {
      Page page = pages.get(0);
      if (page != null) {
        if (page.getRevisions().size() > 0) {
          content = page.getRevisions().get(0).getValue();
        }
      }
    }
    if (checkNotNull && content == null) {
      String errMsg = "pageTitle '" + pageTitle + "' not found";
      this.handleError(errMsg);
    }
    return content;
  }

import java.util.Scanner;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.ZoneOffset;

public class TimeZone {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the time zone offset to GMT: ");
        int offset = scanner.nextInt();

        LocalDateTime currentTime = LocalDateTime.now(ZoneOffset.UTC);
        LocalDateTime offsetTime = currentTime.plusHours(offset);

        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

        String utcTime = formatter.format(currentTime);
        String offsetTimeStr = formatter.format(offsetTime);

        System.out.println("UTC Time: " + utcTime);
        System.out.println("Time in GMT+" + offset + ": " + offsetTimeStr);
    }
}

