import org.junit.Test;
import org.junit.Assert;
import java.util.Properties;

public class JGitFileSystemProviderTest {

    @Test
    public void testDefaultProperties() {
        // Create configuration based on the default properties provided by the provider.
        ConfigProperties config = JGitFileSystemProvider.DefaultProperties.getInstance();
        // Verify default settings.
        Assert.assertEquals("false",
            config.getProperty(JGitFileSystemProvider.GIT_DAEMON_ENABLED));
        Assert.assertEquals("false",
            config.getProperty(JGitFileSystemProvider.GIT_SSH_ENABLED));
        Assert.assertEquals("NIOGIT_CASEAPP",
            config.getProperty(JGitFileSystemProvider.GIT_NIO_DIR_NAME));
    }

    @Test
    public void testPropertiesOverride() {
        // Create external properties with override values.
        Properties externalProps = new Properties();
        externalProps.setProperty(JGitFileSystemProvider.GIT_DAEMON_ENABLED, "true");
        externalProps.setProperty(JGitFileSystemProvider.GIT_SSH_ENABLED, "true");
        externalProps.setProperty(JGitFileSystemProvider.GIT_NIO_DIR_NAME, "EXTERNAL_OVERRIDE");

        // Even when external props are provided, the default configuration must take precedence.
        ConfigProperties config = JGitFileSystemProvider.DefaultProperties.getInstance();
        // Check that external values did not override the enforced defaults.
        Assert.assertEquals("false",
            config.getProperty(JGitFileSystemProvider.GIT_DAEMON_ENABLED));
        Assert.assertEquals("false",
            config.getProperty(JGitFileSystemProvider.GIT_SSH_ENABLED));
        Assert.assertEquals("NIOGIT_CASEAPP",
            config.getProperty(JGitFileSystemProvider.GIT_NIO_DIR_NAME));
    }
}

class JGitFileSystemProvider {
    public static final String GIT_DAEMON_ENABLED = "git.daemon.enabled";
    public static final String GIT_SSH_ENABLED = "git.ssh.enabled";
    public static final String GIT_NIO_DIR_NAME = "git.nio.dir.name";

    // Nested class that encapsulates default configuration properties.
    public static class DefaultProperties extends ConfigProperties {
        private static final Properties defaultProps = new Properties();

        static {
            // Set defaults which should not be overridden by external properties.
            defaultProps.setProperty(GIT_DAEMON_ENABLED, "false");
            defaultProps.setProperty(GIT_SSH_ENABLED, "false");
            defaultProps.setProperty(GIT_NIO_DIR_NAME, "NIOGIT_CASEAPP");
        }

class Finder {
    public boolean hasTrailingZeros(int[] nums) {
        int sum = 0;
        for (int i = 0; i < nums.length; i++) {
            if(nums[i] % 2 == 0){
                sum++;
            }
        }
        return sum >= 2;
    }
}

