import java.io.Serializable;
import java.util.Iterator;
import java.util.NoSuchElementException;
import org.jeeventstore.ChangeSet;

/**
 * ChangeSetEventIterator provides a unified way to traverse through individual events
 * that are organized within multiple change sets, effectively abstracting the underlying
 * structure into a single stream of events.
 *
 * @param <E> the type of event this iterator will traverse.
 */
public class ChangeSetEventIterator<E> implements Iterator<E>, Serializable {

    private static final long serialVersionUID = 1L;

    // Iterator over the collection of change sets.
    private final Iterator<? extends ChangeSet<E>> changeSetIterator;

    // Iterator over the events within the current change set.
    private Iterator<E> eventIterator;

    /**
     * Constructs a new ChangeSetEventIterator using the provided change sets.
     *
     * @param changeSets An iterable collection of change sets.
     * @throws IllegalArgumentException if changeSets is null.
     */
    public ChangeSetEventIterator(Iterable<? extends ChangeSet<E>> changeSets) {
        if (changeSets == null) {
            throw new IllegalArgumentException("Change sets cannot be null");
        }
        this.changeSetIterator = changeSets.iterator();
        this.eventIterator = null;

        // Initialize the iterator to point to the first available event.
        advanceToNextEventIterator();
    }

    /**
     * Helper function that advances the eventIterator to the next available event sequence.
     * It skips change sets that are empty or yield null events.
     */
    private void advanceToNextEventIterator() {
        while ((eventIterator == null || !eventIterator.hasNext()) && changeSetIterator.hasNext()) {
            ChangeSet<E> changeSet = changeSetIterator.next();
            if (changeSet != null) {
                // Retrieve the event collection from the current change set.
                Iterable<E> events = changeSet.getEvents();
                if (events != null) {
                    eventIterator = events.iterator();
                } else {
                    eventIterator = null;
                }
            }
        }
    }

    /**
     * Checks whether there is another event available across all change sets.
     *
     * @return true if a subsequent event exists; false otherwise.
     */
    @Override
    public boolean hasNext() {
        // If current iterator has more events, return true.
        if (eventIterator != null && eventIterator.hasNext()) {
            return true;
        }

import java.util.*;

public class LongestSameNumberSequence {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.println("Enter a series of numbers ending with 0:");

        int currentNumber = input.nextInt();
        int currentLength = 1;

        int longestStartIndex = 0;
        int longestLength = 1;

        int currentIndex = 1;
        while (currentNumber != 0) {
            int number = input.nextInt();
            if (number == currentNumber) {
                currentLength++;
            } else {
                if (currentLength > longestLength) {
                    longestStartIndex = currentIndex - currentLength;
                    longestLength = currentLength;
                }
                currentNumber = number;
                currentLength = 1;
            }
            currentIndex++;
        }

        if (currentLength > longestLength) {
            longestStartIndex = currentIndex - currentLength;
            longestLength = currentLength;
        }

        System.out.println("The longest same number sequence starts at index " +
            longestStartIndex + " with " + longestLength + " values of " + currentNumber);
    }
}

