import java.math.BigDecimal;
import java.math.BigInteger;

public class BinomialDistribution implements Distribution {

    private final double p;
    private final int n;

    public BinomialDistribution(double p, int n) {
        this.p = p;
        this.n = n;
    }

    private long nChooseK(int n, int k) {
        if (k < 0 || k > n) {
            return 0;
        }
        if (k == 0 || k == n) {
            return 1;
        }
        if (k > n / 2) {
            k = n - k;
        }
        long result = 1;
        for (int i = 1; i <= k; ++i) {
            result = result * (n - i + 1) / i;
        }
        return result;
    }

    private BigDecimal nChooseKLargeNumbers(int n, int k) {
        if (k < 0 || k > n) {
            return BigDecimal.ZERO;
        }
        if (k == 0 || k == n) {
            return BigDecimal.ONE;
        }
        if (k > n / 2) {
            k = n - k;
        }

        BigDecimal numerator = factorial(n);
        BigDecimal denominator = factorial(k).multiply(factorial(n - k));

        return numerator.divide(denominator, 20, BigDecimal.ROUND_HALF_UP);
    }

    private BigDecimal factorial(int n) {
        BigDecimal result = BigDecimal.ONE;
        for (int i = 2; i <= n; i++) {
            result = result.multiply(new BigDecimal(i));
        }
        return result;
    }

    public double pdf(int k) {
        if (k < 0 || k > n) {
            return 0;
        }

        BigDecimal combination;
        if (n <= 20) {
            combination = new BigDecimal(nChooseK(n, k));
        } else {
            combination = nChooseKLargeNumbers(n, k);
        }

        return combination.doubleValue() * Math.pow(p, k) * Math.pow(1 - p, n - k);
    }

    public double cdf(int k) {
        double result = 0;
        for (int i = 0; i <= k; ++i) {
            result += pdf(i);
        }
        return result;
    }

    public double getMean(){
        return n * p;
    }

    public double getVariance(){
        return n * p * (1-p);
    }
}

import java.util.Random;
import java.util.Scanner;

public class MatrixAnalyzer {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter the size for the matrix: ");
        int n = scanner.nextInt();

        int[][] matrix = new int[n][n];

        Random random = new Random();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                matrix[i][j] = random.nextInt(2);
            }
        }

        System.out.println("The matrix is:");
        printMatrix(matrix);

        boolean allZerosOrOnes;

        // check rows
        for (int i = 0; i < n; i++) {
            allZerosOrOnes = true;
            for (int j = 1; j < n; j++) {
                if (matrix[i][j] != matrix[i][0]) {
                    allZerosOrOnes = false;
                    break;
                }
            }
            if (allZerosOrOnes) {
                System.out.printf("All %ds on row %d\n", matrix[i][0], i + 1);
            }
        }

        // check columns
        for (int j = 0; j < n; j++) {
            allZerosOrOnes = true;
            for (int i = 1; i < n; i++) {
                if (matrix[i][j] != matrix[0][j]) {
                    allZerosOrOnes = false;
                    break;
                }
            }
            if (allZerosOrOnes) {
                System.out.printf("All %ds on column %d\n", matrix[0][j], j + 1);
            }
        }

        // check major diagonal
        allZerosOrOnes = true;
        for (int i = 1; i < n; i++) {
            if (matrix[i][i] != matrix[0][0]) {
                allZerosOrOnes = false;
                break;
            }
        }
        if (allZerosOrOnes) {
            System.out.printf("All %ds on the major diagonal\n", matrix[0][0]);
        }

        // check sub-diagonal
        allZerosOrOnes = true;
        for (int i = 1; i < n; i++) {
            if (matrix[i][n - i - 1] != matrix[0][n - 1]) {
                allZerosOrOnes = false;
                break;
            }
        }
        if (allZerosOrOnes) {
            System.out.printf("All %ds on the sub-diagonal\n", matrix[0][n - 1]);
        }
    }

    public static void printMatrix(int[][] matrix) {
        for (int[] row : matrix) {
            for (int cell : row) {
                System.out.print(cell);
            }
            System.out.println();
        }
    }
}

