import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.ResourceBundle;
import java.util.Set;

// Assuming Expression and ASTNode classes are defined elsewhere
interface Expression {
    ASTNode parse(List<String> tokens);
    Set<String> collectFirsts();
}

class ASTNode {
    private final boolean success;
    private final List<String> remainingTokens;
    private final Object value;

    public ASTNode(boolean success, List<String> remainingTokens, Object value) {
        this.success = success;
        this.remainingTokens = remainingTokens;
        this.value = value;
    }

    public boolean isSuccess() {
        return success;
    }

    public List<String> getRemainingTokens() {
        return remainingTokens;
    }

    public Object getValue() {
        return value;
    }
}

public final class ExpressionSequence implements Expression {
    private final List<Expression> subExpressions;

    public ExpressionSequence(Expression... expressions) {
        this.subExpressions = Collections.unmodifiableList(Arrays.asList(expressions));
    }

    @Override
    public ASTNode parse(List<String> tokens) {
        List<String> currentTokens = new ArrayList<>(tokens);
        StringBuilder matchedValues = new StringBuilder();

        for (Expression expr : subExpressions) {
            ASTNode result = expr.parse(currentTokens);
            if (!result.isSuccess()) {
                return new ASTNode(false, tokens, null);
            }
            currentTokens = result.getRemainingTokens();
            matchedValues.append(result.getValue()).append(" ");
        }

        return new ASTNode(true, currentTokens, matchedValues.toString().trim());
    }

    @Override
    public Set<String> collectFirsts() {
        Set<String> firsts = new HashSet<>();
        if (!subExpressions.isEmpty()) {
            firsts.addAll(subExpressions.get(0).collectFirsts());
        }
        return firsts;
    }

    public List<Expression> getChildExpressions() {
        return subExpressions;
    }

    @Override
    public String toString() {
        return "ExpressionSequence{" +
                "subExpressions=" + subExpressions +
                '}';
    }
}

public class HanoiKuleleri {

    // Disk sayisini belirle
    public static final int NUM_DISKS = 3;

    public static void main(String[] args) {

        coz(NUM_DISKS, 'A', 'B', 'C');
    }

    // Hanoi Kuleleri bulmacasini cozen rekursif metod
    public static void coz(int diskSayisi, char kaynak, char hedef, char yardimci) {
        // Eger sadece bir disk varsa
        if (diskSayisi == 1) {
            // Ustteki diski kaynak'tann hedef'e tasi
            System.out.println("Disk " + diskSayisi + " direk " + kaynak + "'den direk " + hedef + "'e tasi.");
        } else {
            // Ustteki diskSayisi - 1 diski kaynak'tan yardimci'ya, hedef'i yardimci olarak kullanarak tasi
            coz(diskSayisi - 1, kaynak, yardimci, hedef);
            // Kalan diski kaynak'tan hedef'e tasi
            System.out.println("Disk " + diskSayisi + " direk " + kaynak + "'den direk " + hedef + "'e tasi.");
            // diskSayisi - 1 diski yardimci'dan hedef'e, kaynak'i yardimci olarak kullanarak tasi
            coz(diskSayisi - 1, yardimci, hedef, kaynak);
        }
    }

}

