import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class CircularPrimes {
 
    public static boolean isPrime(int n) {
        if (n == 2) {
            return true;
        }
        if (n < 2 || n % 2 == 0) {
            return false;
        }
        for (int p = 3; p * p <= n; p += 2) {
            if (n % p == 0) {
                return false;
            }
        }
        return true;
    }
 
    public static int cycle(int n) {
        int m = n;
        int p = 1;
        while (m >= 10) {
            p *= 10;
            m /= 10;
        }
        return m + 10 * (n % p);
    }
 
    public static boolean isCircularPrime(int p) {
        if (!isPrime(p)) {
            return false;
        }
        int p2 = cycle(p);
        while (p2!= p) {
            if (p2 < p ||!isPrime(p2)) {
                return false;
            }
            p2 = cycle(p2);
        }
        return true;
    }
 
    public static void testRepunit(int digits) {
        String str = "";
        for (int i = 0; i < digits; i++) {
            str += "1";
        }
        BigInteger bignum = new BigInteger(str);
        if (bignum.isProbablePrime(10)) {
            System.out.println("R(" + digits + ") is probably prime.");
        } else {
            System.out.println("R(" + digits + ") is not prime.");
        }
    }
 
    public static void main(String[] args) {
        int p = 2;
        System.out.println("First 19 circular primes:");
        int count = 0;
        while (count < 19) {
            if (isCircularPrime(p)) {
                if (count > 0) {
                    System.out.print(", ");
                }
                System.out.print(p);
                count++;
            }
            p++;
        }
        System.out.println();
        System.out.println("Next 4 circular primes:");
        int repunit = 1;
        int digits = 1;
        while (repunit < p) {
            repunit = 10 * repunit + 1;
            digits++;
        }
        BigInteger bignum = new BigInteger(String.valueOf(repunit));
        count = 0;
        while (count < 4) {
            if (bignum.isProbablePrime(15)) {
                if (count > 0) {
                    System.out.print(", ");
                }
                System.out.print("R(" + digits + ")");
                count++;
            }
            digits++;
            bignum = bignum.multiply(BigInteger.valueOf(10));
            bignum = bignum.add(BigInteger.ONE);
        }
        System.out.println();
        testRepunit(5003);
        testRepunit(9887);

import static java.lang.Math.abs;
import java.util.*;
import java.util.function.IntSupplier;
 
public class Generator {
 
    static void distCheck(IntSupplier f, int nRepeats, double delta) {
        Map<Integer, Integer> counts = new HashMap<>();
 
        for (int i = 0; i < nRepeats; i++)
            counts.compute(f.getAsInt(), (k, v) -> v == null ? 1 : v + 1);
 
        double target = nRepeats / (double) counts.size();
        int deltaCount = (int) (delta / 100.0 * target);
 
        counts.forEach((k, v) -> {
            if (abs(target - v) >= deltaCount)
                System.out.printf("distribution potentially skewed "
                        + "for '%s': '%d'%n", k, v);
        });
 
        counts.keySet().stream().sorted().forEach(k
                -> System.out.printf("%d %d%n", k, counts.get(k)));
    }
 
    public static void main(String[] a) {
        distCheck(() -> (int) (Math.random() * 5) + 1, 1_000_000, 1);
    }
}

