static final long mod = 998244353L;
public static void main(String[] args) throws Exception
{
InputReader reader = new InputReader(System.in);
int n = readInt(reader);
long[] dp = new long[n + 1];
dp[1] = 1;
dp[2] = m;
dp[3] = m * (m - 1);
for (int i = 4; i <= n; i++)
{
dp[i] = dp[i - 1] * (m - (i - 1)) % mod;
for (int j = i - 2; j >= 1; j--)
{
dp[i] += dp[j] * (i - j - 1);
dp[i] %= mod;
}
dp[i] += dp[i - 1] - dp[i - 2];
dp[i]--;
dp[i] %= mod;
dp[i] += mod;
dp[i] %= mod;
}
out.println(dp[n]);
out.flush();
}

