class Writer {
    public int[] findDiagonalOrder(List<List<Integer>> nums) {
        int it = 0;
        List<List<Integer>> lx = new ArrayList();
        int an = 0;
        for(List<Integer> ll : nums) {
            an += ll.size();
            for(int i = 0; i < ll.size(); ++i) {
                int ln = it + i;
                if(lx.size() == ln) lx.add(new ArrayList());
                lx.get(ln).add(ll.get(i));
            }
            ++it;
        }

        int[] res = new int[an];
        int dd = 0;
        for(List<Integer> ll : lx) {
            for(int i = ll.size() - 1; i >= 0; --i) res[dd++] = ll.get(i);
        }
        return res;
    }
}

import ch_09.exercise09_07.Account;

public class CheckingAccount extends Account {

    public double minBalance;

    public CheckingAccount() {

        this.minBalance = -50;

    }

    public CheckingAccount(int id, double newBalance) {

        super(id, newBalance);
        this.minBalance = -50;
    }

    @Override
    public void withdraw(double amount) {

        if (this.getBalance() - amount < minBalance) {
            System.out.println("We cannot complete this transaction. \nIt will put you over your withdrawl limit.");
        } else {
            this.setBalance(this.getBalance() - amount);
        }
    }

    @Override
    public String toString() {

        return super.toString() + "\nOverdraft protection up to : $" + minBalance;

    }
}

public static JSONObject mapToJsonObject(Map<String, Object> map)
    {
        JSONObject jsonObj = new JSONObject();

        try {
            for (String key : map.keySet())
            {
                Object value = map.get(key);
                if (value instanceof Map)
                    jsonObj.put(key, AjaxProxyTask.mapToJsonObject((Map)value));
                else
                    jsonObj.put(key, value);
            }
        } catch (JSONException e) {
            e.printStackTrace();
        }

        return jsonObj;
    }

import java.io.*;
import java.util.Arrays;
import java.util.StringTokenizer;

public class F {
    private FastScanner in;
    private PrintWriter out;

    public F(FastScanner in, PrintWriter out) {
        this.in = in;
        this.out = out;
    }

    public static void main(String[] args) {
        try (
                FastScanner in = new FastScanner(System.in);
                PrintWriter out = new PrintWriter(System.out);
        ) {
            F solution = new F(in, out);
            solution.solve();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void solve() throws IOException {
        int n = in.nextInt();
        int k = in.nextInt();
        String s = in.next();
        String t = in.next();
        int[][][] dp = new int[n + 1][k + 1][n + 1];
        for (int i = 0; i < dp.length; i++) {
            for (int j = 0; j < dp[i].length; j++) {
                Arrays.fill(dp[i][j], Integer.MIN_VALUE);
            }
        }
        dp[0][0][0] = 0;
        int e01 = t.charAt(0) == t.charAt(1) ? 1 : 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= k; j++) {
                for (int cnt = 0; cnt <= i; cnt++) {
                    int e0 = s.charAt(i) == t.charAt(0) ? 1 : 0;
                    int e1 = s.charAt(i) == t.charAt(1) ? 1 : 0;
                    dp[i + 1][j][cnt + e0] = Math.max(dp[i + 1][j][cnt + e0], dp[i][j][cnt] + e1 * cnt);
                    if (j < k) {
                        dp[i + 1][j + 1][cnt + 1] = Math.max(dp[i + 1][j + 1][cnt + 1], dp[i][j][cnt] + e01 * cnt);
                        dp[i + 1][j + 1][cnt + e01] = Math.max(dp[i + 1][j + 1][cnt + e01], dp[i][j][cnt] + cnt);
                    }
                }
            }
        }
        int res = 0;
        for (int z = 0; z <= n; z++) {
            for (int i = 0; i <= k; i++) {
                for (int j = 0; j <= n; j++) {
                    res = Math.max(res, dp[n][i][j]);
                }
            }
        }
        out.println(res);
    }

