import java.awt.Color;
import java.awt.Graphics;
 
import javax.swing.JFrame;
 
public class ColorFrame extends JFrame {
    public ColorFrame(int width, int height) {
        this.setDefaultCloseOperation(EXIT_ON_CLOSE);
        this.setSize(width, height);
        this.setVisible(true);
    }
 
    @Override
    public void paint(Graphics g) {
        Color[] colors = { Color.black, Color.red, Color.green, Color.blue,
                Color.pink, Color.CYAN, Color.yellow, Color.white };
 
        for (int i = 0; i < colors.length; i++) {
            g.setColor(colors[i]);
            g.fillRect(this.getWidth() / colors.length * i, 0, this.getWidth()
                    / colors.length, this.getHeight());
        }
    }
 
    public static void main(String args[]) {
        new ColorFrame(200, 200);
    }
}

/**
 * Exception thrown when we try to use an invalid or expired {@link RowLock}.
 */
public final class UnknownRowLockException extends NonRecoverableException
implements HasFailedRpcException {

  static final String REMOTE_CLASS =
    "org.apache.hadoop.hbase.UnknownRowLockException";

  final HBaseRpc failed_rpc;

  /**
   * Constructor.
   * @param msg The message of the exception, potentially with a stack trace.
   * @param failed_rpc The RPC that caused this exception, if known, or null.
   */
  UnknownRowLockException(final String msg, final HBaseRpc failed_rpc) {
    super(msg + "\nCaused by RPC: " + failed_rpc);
    this.failed_rpc = failed_rpc;
  }

  public HBaseRpc getFailedRpc() {
    return failed_rpc;
  }

  @Override
  UnknownRowLockException make(final Object msg, final HBaseRpc rpc) {
    if (msg == this || msg instanceof UnknownRowLockException) {
      final UnknownRowLockException e = (UnknownRowLockException) msg;
      return new UnknownRowLockException(e.getMessage(), rpc);
    }
    return new UnknownRowLockException(msg.toString(), rpc);
  }

  private static final long serialVersionUID = 1281540942;

}

import java.util.Scanner;  // Kullanicidan girdi almak icin Scanner sinifini ice aktar

public class Faktoriyel {

    // 'faktoriyelAl' metodu, verilen sayinin faktoriyelini hesaplar
    int faktoriyelAl(int sayi) {
        int sonuc = 1;  // Faktoriyel sonucunu tutacak degisken, baslangicta 1 olmali
        // Sayi 0'dan buyuk oldugu surece dongu devam eder
        while(sayi > 0) {
            // Sonuc degiskenini her adimda sayi ile carp
            sonuc *= sayi;
            // Sayi her seferinde 1 azaltilir
            sayi--;
        }
        // Faktoriyel hesaplandiktan sonra sonuc dondurulur
        return sonuc;
    }

    public static void main(String[] args) {

        // Kullanicidan girdi almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini iste
        System.out.println("Lutfen bir sayi giriniz");
        int sayi = okuyucu.nextInt();  // Kullanicinin girdigi sayiyi al

        // Faktoriyel sinifindan bir nesne olustur
        Faktoriyel bulucu = new Faktoriyel();

        // 'faktoriyelAl' metodunu cagirarak sayinin faktoriyelini hesapla
        int sonuc = bulucu.faktoriyelAl(sayi);

        // Hesaplanan faktoriyel sonucunu ekrana yazdir
        System.out.println("Sonuc = " + sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
 
public class RecamanSequence {
    public static void main(String[] args) {
        List<Integer> a = new ArrayList<>();
        a.add(0);
 
        Set<Integer> used = new HashSet<>();
        used.add(0);
 
        Set<Integer> used1000 = new HashSet<>();
        used1000.add(0);
 
        boolean foundDup = false;
        int n = 1;
        while (n <= 15 || !foundDup || used1000.size() < 1001) {
            int next = a.get(n - 1) - n;
            if (next < 1 || used.contains(next)) {
                next += 2 * n;
            }
            boolean alreadyUsed = used.contains(next);
            a.add(next);
            if (!alreadyUsed) {
                used.add(next);
                if (0 <= next && next <= 1000) {
                    used1000.add(next);
                }
            }
            if (n == 14) {
                System.out.printf("The first 15 terms of the Recaman sequence are : %s\n", a);
            }
            if (!foundDup && alreadyUsed) {
                System.out.printf("The first duplicate term is a[%d] = %d\n", n, next);
                foundDup = true;
            }
            if (used1000.size() == 1001) {
                System.out.printf("Terms up to a[%d] are needed to generate 0 to 1000\n", n);
            }
            n++;
        }
    }
}

