public static Map<String,Object> toMap(LoggingEvent e){
        final Map<String,Object> m = Objects.newHashMap(
                "name",e.getLoggerName(),
                "date",new Date(e.getTimeStamp()),
                "level",e.getLevel().toString(),
                "thread",e.getThreadName(),
                "message",""+e.getMessage(),
                "fileName",e.getLocationInformation().getFileName(),
                "methodName",e.getLocationInformation().getMethodName(),
                "lineNumber",e.getLocationInformation().getLineNumber(),
                "requestId",e.getMDC("requestId"),
                "sessionId",e.getMDC("sessionId"),
                "freeMemory",Runtime.getRuntime().freeMemory(),
                "throwable",null
        );
        if(e.getThrowableInformation()!=null && e.getThrowableInformation().getThrowable()!=null){
            Throwable t = e.getThrowableInformation().getThrowable();
            m.put("throwable", Objects.newHashMap(
                    "message",t.getMessage(),
                    "class",t.getClass().getName(),
                    "stackTrace",getStackTrace(t)
            ));
        }
        return m;
    }

class Employee {
    public String largestMultipleOfThree(int[] digits) {
        Arrays.sort(digits);
        int n = digits.length;
        int [] counts = new int[3];
        for(int i = 0, j = n - 1; i < j; i++, j--){
            int temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;
        }
        int oneIndex1 = -1;
        int oneIndex2 = -1;
        int twoIndex1 = -1;
        int twoIndex2 = -1;
        for(int i = 0; i < n; i++){
            int elem = digits[i];
            counts[elem % 3]++;
            if(elem % 3 == 1){
                oneIndex2 = oneIndex1;
                oneIndex1 = i;
            }else if(elem % 3 == 2){
                twoIndex2 = twoIndex1;
                twoIndex1 = i;
            }
        }
        StringBuilder result = new StringBuilder();
        int remove1 = 0;
        int remove2 = 0;
        int total = counts[1] + (2 * counts[2]);
        total %= 3;
        boolean valid = false;
        if(total == 1){
            if(counts[1] > 0){
                remove1 = 1;
            }else if(counts[2] > 1){
                remove2 = 2;
            }
        }else if(total == 2){
            if(counts[2] > 0){
                remove2 = 1;
            }else if(counts[1] > 1){
                remove1 = 2;
            }
        }
        if(total == 0 || (remove1 != 0 || remove2 != 0)){
            valid = true;
        }
        if(valid == false){
            for(int i = 0; i < n; i++){
                int elem = digits[i];
                if(elem % 3 == 0){
                    result.append(elem);
                }
            }
        }else{
            if(remove1 == 0){
                oneIndex1 = -1;
                oneIndex2 = -1;
            }else if(remove1 == 1){
                oneIndex2 = -1;
            }
            if(remove2 == 0){
                twoIndex1 = -1;
                twoIndex2 = -1;
            }else if(remove2 == 1){
                twoIndex2 = -1;
            }
            for(int i = 0; i < n; i++){
                int elem = digits[i];
                if(i == oneIndex1 || i == oneIndex2 || i == twoIndex1 || i == twoIndex2){
                    continue;
                }
                result.append(elem);
            }
        }
        if(result.length() == 0){
            return "";
        }
        if(result.length() > 0 && result.charAt(0) == '0'){
            return "0";
        }
        return result.toString();
    }
}

class SmallestInfiniteSet {
    Set<Integer> st;
    PriorityQueue<Integer> pq;
    int sl;
    public SmallestInfiniteSet() {
        sl = 1;
        st = new HashSet<>();
        pq = new PriorityQueue<>();
    }

    public int popSmallest() {
        if(pq.size()>0){
            int v= pq.poll();
            st.remove(v);
            return v;
        } else {
            int v = sl;
            sl++;
            return v;
        }
    }

    public void addBack(int num) {
        if(num >= sl){
            return;
        }
        if(st.contains(num)){
            return;
        }
        st.add(num);
        pq.offer(num);
    }
}

