import org.eclipse.persistence.testing.models.employee.domain.*;
import org.eclipse.persistence.testing.framework.*;
import org.eclipse.persistence.queries.*;
import org.eclipse.persistence.expressions.*;
import java.util.Vector;

public class ConformResultsPerformanceTest extends PerformanceTestCase {
    protected ReadAllQuery conformedQuery;
    protected long startTime;
    protected int timesUnwrapCalled;

    public ConformResultsPerformanceTest() {
        setDescription("Test the performance of conforming query results within a Unit of Work, ensuring unwrap calls are linear.");
    }

    @Override
    public void prepareTest() {
        // Build the conforming query
        conformedQuery = buildConformQuery();
        UnitOfWork uow = getSession().acquireUnitOfWork();
        conformedQuery.conformResultsInUnitOfWork();
        uow.executeQuery(conformedQuery);
    }

    protected ReadAllQuery buildConformQuery() {
        ReadAllQuery query = new ReadAllQuery(Employee.class);
        ExpressionBuilder builder = new ExpressionBuilder();
        query.setSelectionCriteria(builder.get("lastName").notEqual("Smith"));
        query.setWrapperPolicy(new EmployeeWrapperPolicy());
        return query;
    }

    @Override
    public void test() {
        startTime = System.currentTimeMillis();
        Vector results = (Vector) getSession().executeQuery(conformedQuery);
        timesUnwrapCalled = ((EmployeeWrapperPolicy) conformedQuery.getWrapperPolicy()).getTimesUnwrapCalled();
    }

    @Override
    public void verify() {
        long endTime = System.currentTimeMillis();
        long duration = endTime - startTime;
        int resultSize = conformedQuery.getResultSize();

        // Verify that the number of unwrap calls is linear relative to the result size
        if (timesUnwrapCalled > resultSize * 2 || timesUnwrapCalled < resultSize) {
            throw new TestErrorException("Unwrap calls are not linear. Expected: ~" + resultSize + ", Actual: " + timesUnwrapCalled);
        }

        // Log performance metrics
        getSession().logMessage("Test completed in " + duration + "ms. Unwrap calls: " + timesUnwrapCalled);
    }

    // Inner class to track unwrap calls
    class EmployeeWrapperPolicy extends WrapperPolicy {
        private int timesUnwrapCalled = 0;

        @Override
        public Object unwrapObject(Object object) {
            timesUnwrapCalled++;
            return object;
        }

        public int getTimesUnwrapCalled() {
            return timesUnwrapCalled;
        }
    }
}

import org.apache.hadoop.hdfs.server.protocol.BlockCommand;
import org.apache.hadoop.net.Node;

import java.util.List;
import java.util.Set;

class ReplicationWork extends BlockReconstructionWork {
  public ReplicationWork(BlockInfo block, BlockCollection bc,
      DatanodeDescriptor[] srcNodes, List<DatanodeDescriptor> containingNodes,
      List<DatanodeStorageInfo> liveReplicaStorages, int additionalReplRequired,
      int priority) {
    super(block, bc, srcNodes, containingNodes,
        liveReplicaStorages, additionalReplRequired, priority);
    assert getSrcNodes().length == 1 :
        "There should be exactly 1 source node that have been selected";
    getSrcNodes()[0].incrementPendingReplicationWithoutTargets();
    LOG.debug("Creating a ReplicationWork to reconstruct " + block);
  }

  @Override
  void chooseTargets(BlockPlacementPolicy blockplacement,
      BlockStoragePolicySuite storagePolicySuite,
      Set<Node> excludedNodes) {
    assert getSrcNodes().length > 0
        : "At least 1 source node should have been selected";
    try {
      DatanodeStorageInfo[] chosenTargets = null;
      // HDFS-14720 If the block is deleted, the block size will become
      // BlockCommand.NO_ACK (LONG.MAX_VALUE) . This kind of block we don't need
      // to send for replication or reconstruction
      if (getBlock().getNumBytes() != BlockCommand.NO_ACK) {
        chosenTargets = blockplacement.chooseTarget(getSrcPath(),
            getAdditionalReplRequired(), getSrcNodes()[0],
            getLiveReplicaStorages(), false, excludedNodes, getBlockSize(),
            storagePolicySuite.getPolicy(getStoragePolicyID()), null);
      }
      setTargets(chosenTargets);
    } finally {
      getSrcNodes()[0].decrementPendingReplicationWithoutTargets();
    }
  }

  @Override
  void addTaskToDatanode(NumberReplicas numberReplicas) {
    getSrcNodes()[0].addBlockToBeReplicated(getBlock(), getTargets());
  }
}

import java.io.Serializable;
import java.util.Set;

import javax.enterprise.context.ApplicationScoped;
import javax.enterprise.context.RequestScoped;
import javax.enterprise.context.spi.Context;
import javax.enterprise.context.spi.CreationalContext;
import javax.enterprise.inject.Any;
import javax.enterprise.inject.spi.Bean;
import javax.enterprise.inject.spi.BeanManager;
import javax.enterprise.util.AnnotationLiteral;
import javax.inject.Inject;

import angularBeans.util.AngularBeansUtils;
import angularBeans.util.CommonUtils;

/**
 * provide a lookup method to obtain an angularBean reference from an external context to the HTTP Session context
 * (useful with realTime methods calls)
 *
 */
@SuppressWarnings("serial")
@ApplicationScoped
public class BeanLocator implements Serializable {

    @Inject
    private BeanManager beanManager;

    @Inject
    AngularBeansUtils util;

    public Object lookup(String beanName, String sessionID) {

        NGSessionScopeContext.setCurrentContext(sessionID);

        Set<Bean<?>> beans = beanManager.getBeans(beanName);

        Class beanClass = CommonUtils.beanNamesHolder.get(beanName);
        if (beans.isEmpty()) {
            beans = beanManager.getBeans(beanClass, new AnnotationLiteral<Any>() { //
            });
        }

        Bean bean = beanManager.resolve(beans);

        Class scopeAnnotationClass = bean.getScope();
        Context context;

        if (scopeAnnotationClass.equals(RequestScoped.class)) {
            context = beanManager.getContext(scopeAnnotationClass);
            if (context == null)
                return bean.create(beanManager.createCreationalContext(bean));

        } else {

            if (scopeAnnotationClass.equals(NGSessionScopeContext.class)) {
                context = NGSessionScopeContext.getINSTANCE();
            } else {
                context = beanManager.getContext(scopeAnnotationClass);
            }

        }
        CreationalContext creationalContext = beanManager.createCreationalContext(bean);
        Object reference = context.get(bean, creationalContext);

        // if(reference==null && scopeAnnotationClass.equals(RequestScoped.class)){
        // reference= bean.create(beanManager.createCreationalContext(bean));
        // }

        return reference;
    }

}

