        int k=r.nextInt();

        m/=2;

        ArrayList<pair> trains=new ArrayList<>();

        for(int i=0;i<n;++i){

            int hi=r.nextInt();

            int mi=r.nextInt();

            trains.add(new pair(mi%m,i));

            trains.add(new pair(mi%m+m,i));

        }

        Collections.sort(trains, new Comparator<pair>() {

            @Override

            public int compare(pair o1, pair o2) {

                if(o1.mi>o2.mi) return 1;

                else if(o1.mi==o2.mi){

                    if(o1.id>o2.id) return 1;

                    else if(o1.id==o2.id) return 0;

                    else return -1;

                }

                else return -1;

            }

        });

        pair ans=new pair(n,n);

        for(int run=0,i=n;i<n*2;++i){

            while(trains.get(run).mi<=trains.get(i).mi-k) ++run;

            if(ans.mi>i-run){

                ans=new pair(i-run,trains.get(i).mi);

            }

        }

        System.out.println(ans.mi+" "+(ans.id-m));

        for(int i=0;i<2*n;++i){

            if(trains.get(i).mi<=ans.id-k||trains.get(i).mi>=ans.id) continue;

            System.out.print((trains.get(i).id+1)+" ");

        }

    }

}

import java.util.ArrayList;
import java.util.List;

public class LineCollection {

    private static final long serialVersionUID = 1L;

    private final List<LineSegment2D> segments;
    private boolean[] usePt;

    public LineCollection(List<LineSegment2D> segments) {
        this.segments = new ArrayList<>(segments);
        this.usePt = new boolean[segments.size() + 1];
        for (int i = 0; i < usePt.length; i++) {
            usePt[i] = true;
        }
    }

    public List<LineCollection> splitByColor() {
        List<LineCollection> splitCollections = new ArrayList<>();
        List<LineSegment2D> currentCollection = new ArrayList<>();

        if (segments.isEmpty()) {
            return splitCollections;
        }

        currentCollection.add(segments.get(0));
        for (int i = 1; i < segments.size(); i++) {
            LineSegment2D prevSegment = segments.get(i - 1);
            LineSegment2D currentSegment = segments.get(i);

            if (!prevSegment.isEqualTo(currentSegment)) {
                splitCollections.add(new LineCollection(currentCollection));
                currentCollection = new ArrayList<>();
            }
            currentCollection.add(currentSegment);
        }
        splitCollections.add(new LineCollection(currentCollection));

        return splitCollections;
    }

    public List<LineCollection> splitByTravel(double maxTravelDistance) {
        List<LineCollection> splitCollections = new ArrayList<>();
        List<LineSegment2D> currentCollection = new ArrayList<>();
        double maxTravelDistanceSq = maxTravelDistance * maxTravelDistance;

        if (segments.isEmpty()) {
            return splitCollections;
        }

        currentCollection.add(segments.get(0));
        for (int i = 1; i < segments.size(); i++) {
            Point2D endPointPrev = segments.get(i - 1).getEndPoint();
            Point2D startPointCurrent = segments.get(i).getStartPoint();

            if (endPointPrev.distanceSquared(startPointCurrent) > maxTravelDistanceSq) {
                splitCollections.add(new LineCollection(currentCollection));
                currentCollection = new ArrayList<>();
            }
            currentCollection.add(segments.get(i));
        }
        splitCollections.add(new LineCollection(currentCollection));

        return splitCollections;
    }

    public void simplify(double distanceTolerance) {
        if (segments.size() <= 2) return;

        usePt = new boolean[segments.size() + 1];
        for (int i = 0; i < usePt.length; i++) {
            usePt[i] = true;
        }

