import org.restlet.resource.Get;
import org.restlet.resource.Post;
import org.restlet.resource.ResourceException;
import org.restlet.resource.ServerResource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MeetingResource extends ServerResource {

    private static final Logger logger = LoggerFactory.getLogger(MeetingResource.class);

    private LeanBeanDao<Meeting> meetingDao;

    public MeetingResource() {
        this.meetingDao = new LeanBeanJpaDao<>(Meeting.class);
    }

    @Get("json")
    public MeetingViewTO findMeetingById(String encodedId) {
        try {
            Long meetingId = decodeId(encodedId);
            Meeting meeting = meetingDao.findById(meetingId);
            if (meeting == null) {
                throw new ResourceException(404, "Meeting not found");
            }
            return mapToViewTO(meeting);
        } catch (ResourceException ex) {
            logger.error("Error retrieving meeting: " + ex.getMessage());
            throw ex;
        } catch (Exception e) {
            logger.error("Unexpected error while fetching meeting", e);
            throw new ResourceException(500, "Internal server error");
        }
    }

    @Post("json")
    public MeetingViewTO addMeeting(MeetingTO meetingTO) {
        try {
            Meeting meeting = mapToEntity(meetingTO);
            meetingDao.save(meeting);
            return mapToViewTO(meeting);
        } catch (Exception e) {
            logger.error("Error saving meeting", e);
            throw new ResourceException(400, "Invalid meeting data");
        }
    }

    private Long decodeId(String encodedId) {
        // Logic to decode the hashed ID goes here
        return Long.valueOf(encodedId); // Placeholder for actual implementation
    }

    private Meeting mapToEntity(MeetingTO meetingTO) {
        Meeting meeting = new Meeting();
        meeting.setTitle(meetingTO.getTitle());
        meeting.setDescription(meetingTO.getDescription());
        meeting.setStartTime(meetingTO.getStartTime());
        meeting.setEndTime(meetingTO.getEndTime());
        return meeting;
    }

    private MeetingViewTO mapToViewTO(Meeting meeting) {
        MeetingViewTO viewTO = new MeetingViewTO();
        viewTO.setId(meeting.getId());
        viewTO.setTitle(meeting.getTitle());
        viewTO.setDescription(meeting.getDescription());
        viewTO.setStartTime(meeting.getStartTime());
        viewTO.setEndTime(meeting.getEndTime());
        return viewTO;
    }
}

