import java.util.Arrays;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class WeirdNumbers {
 
    public static void main(String[] args) {
        List<Integer> weirdNumbers = new ArrayList<>();
        for (int i = 2; i < 17000; i += 2) {
            if (isWeird(i)) {
                weirdNumbers.add(i);
            }
        }
        System.out.println("The first 25 weird numbers:");
        System.out.println(weirdNumbers.stream().limit(25).map(String::valueOf).collect(Collectors.joining(" ")));
    }
 
    private static boolean isWeird(int n) {
        List<Integer> divisors = divisors(n);
        return isAbundant(n, divisors) && isSemiPerfect(n, divisors);
    }
 
    private static boolean isAbundant(int n, List<Integer> divisors) {
        return divisors.stream().mapToInt(Integer::intValue).sum() > n;
    }
 
    private static boolean isSemiPerfect(int n, List<Integer> divisors) {
        if (divisors.isEmpty()) {
            return false;
        } else {
            int head = divisors.get(0);
            List<Integer> tail = divisors.subList(1, divisors.size());
            return n == head || isSemiPerfect(n - head, tail) || isSemiPerfect(n, tail);
        }
    }
 
    private static List<Integer> divisors(int n) {
        List<Integer> divisors = new ArrayList<>();
        divisors.add(1);
        for (int i = 2; i * i <= n; i++) {
            if (n % i == 0) {
                divisors.add(i);
                if (i!= n / i) {
                    divisors.add(n / i);
                }
            }
        }
        Collections.sort(divisors);
        return divisors;
    }
}

import java.util.Scanner;

public class Towers {

    public static void main(String[] args) {

//        String str = "RRBRBRB".substring(0, 1);

//        System.out.println(str);

        Scanner sc = new Scanner(System.in);

        int cases = sc.nextInt();

        for (int i = 0; i < cases; i++) {

            int n = sc.nextInt();

            int m = sc.nextInt();

            String s = sc.next();

            String t = sc.next();

            if (!check(s) && !check(t)) {

                System.out.println("YES");

            } else if (check(s) && check(t)) {

                System.out.println("NO");

            } else {

                if (!check(s)) {

                    char c = s.charAt(n-1);

                    int j = m-1;

                    while (c != t.charAt(j)) {

                        c = t.charAt(j--);

                    }

                    String str = t.substring(0, j + 1);

                    if (!check(str)) {

                        System.out.println("YES");

                    } else {

                        System.out.println("NO");

                    }

                } else {

                    char c = t.charAt(m-1);

                    int j = n-1;

                    while (c != s.charAt(j)) {

                        c = s.charAt(j--);

                    }

                    String str = s.substring(0, j + 1);

                    if (!check(str)) {

                        System.out.println("YES");

                    } else {

                        System.out.println("NO");

                    }

                }

            }

        }

    }

    public static boolean check (String s){

        return s.matches("((RR)\\w+)|(\\w+(RR)\\w+)|(\\w+(RR))|(RR)") || s.matches("((BB)\\w+)|(\\w+(BB)\\w+)|(\\w+(BB))|(BB)");

            }

        }

class Parser {
    public int[][] differenceOfDistinctValues(int[][] grid) {
        int n=grid.length;
        int m=grid[0].length;
        int ans[][]=new int[n][m];
        for(int i=0;i<n;i++){
            for(int j=0;j<m;j++){
                Set<Integer> set =new HashSet<>();
                int x=i+1,y=j+1;
                while(x>=0 && y>=0 && x<n && y<m){
                    set.add(grid[x][y]);
                    x++;
                    y++;
                }
                int p=set.size();
                set.clear();
                x=i-1;
                y=j-1;
                while(x>=0 && y>=0 && x<n && y<m){
                    set.add(grid[x][y]);
                    x--;
                    y--;
                }
                ans[i][j]=Math.abs(p-set.size());
            }
        }
        return ans;

    }
}

import java.beans.PropertyDescriptor;
import java.lang.reflect.Method;
import java.util.Map;

public void putAllWriteable(BeanMap map) {
    PropertyDescriptor[] propertyDescriptors = BeanUtils.getPropertyDescriptors(map.getClass());

    for (PropertyDescriptor propertyDescriptor : propertyDescriptors) {
        Method readMethod = propertyDescriptor.getReadMethod();
        Method writeMethod = propertyDescriptor.getWriteMethod();

        if (readMethod != null && writeMethod != null) {
            try {
                Object value = readMethod.invoke(map);
                this.put(propertyDescriptor.getName(), value);
            } catch (Exception e) {
                e.printStackTrace();
            }
        }
    }
}

