import javax.servlet.ServletContext;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;

public class XMLServlet extends HttpServlet {

    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        response.setContentType("text/html");
        PrintWriter out = response.getWriter();
        String userName = request.getParameter("name");
        ServletContext context = getServletContext();

        if (userName != null && !userName.isEmpty()) {
            context.setAttribute("savedUserName", userName);
        }

        out.println("<h3>GET Method</h3>");
        out.println("Hello " + (userName != null ? userName : getServletConfig().getInitParameter("defaultUserName")) + " from GET!");
    }

    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        response.setContentType("text/html");
        PrintWriter out = response.getWriter();

        String userName = request.getParameter("name");
        String fullName = request.getParameter("fullName");
        String profession = request.getParameter("profession");
        String[] location = request.getParameterValues("location");

        out.println("<h3>POST Method</h3>");
        out.println("Hello " + userName + " from POST!<br/>");
        out.println("Your full name is " + fullName + "<br/>");
        out.println("You are a " + profession + "<br/>");
        out.println("You are living in: ");

        if (location != null) {
            for (String loc : location) {
                out.println(loc.toUpperCase() + " ");
            }
        }
        out.println("<br/>");
    }
}

public class Counter {
    public boolean judge(int[] houses , TreeSet<Integer> set , int radius){
        for(int i = 0 ; i < houses.length ; i ++){
            Integer a = set.ceiling(houses[i]);
            Integer b = set.floor(houses[i]);
            if(a == null && b == null) return false;
            if(a != null){
                if(Math.abs(a - houses[i]) - radius <= 0) continue;
            }
            if(b != null){
                if(Math.abs(b - houses[i]) - radius <= 0) continue;
            }
            return false;
        }
        return true;
    }

    public int findRadius(int[] houses, int[] heaters) {
        int left = 0;
        int right = 1000000000;
        TreeSet<Integer> set = new TreeSet<>();
        for(int i = 0 ; i < heaters.length ; i ++){
            set.add(heaters[i]);
        }
        int result = -1;
        while(left <= right){
            int mid = (left + right) / 2;
            boolean tmp = judge(houses , set , mid);
            if(tmp){
                result = mid;
                right = mid - 1;
            }else{
                left = mid + 1;
            }
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.Random;

public class ShuffleArrayList {
    public static void main(String[] args) {
        ArrayList<Integer> numbers = new ArrayList<>();
        for (int i = 1; i <= 10; i++) {
            numbers.add(i);
        }
        System.out.println("Original list: " + numbers);
        shuffle(numbers);
        System.out.println("Shuffled list: " + numbers);
    }

    public static void shuffle(ArrayList<Integer> list) {
        Random rand = new Random();
        for (int i = list.size() - 1; i > 0; i--) {
            int j = rand.nextInt(i + 1);
            int temp = list.get(i);
            list.set(i, list.get(j));
            list.set(j, temp);
        }
    }
}

