class Converter {
    public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies) {
        int n = favoriteCompanies.size();
        Set<String>[] sets = new Set[n];
        for (int i = 0; i < n; i++) {
            sets[i] = new HashSet<>(favoriteCompanies.get(i));
        }

        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            Set<String> set = sets[i];
            boolean isSubset = false;
            for (int j = 0; j < n && !isSubset; j++) {
                if (i == j) {
                    continue;
                }
                if (isSubsetOf(set, sets[j])) {
                    isSubset = true;
                }
            }
            if (!isSubset) {
                result.add(i);
            }
        }
        return result;
    }

    private boolean isSubsetOf(Set<String> set1, Set<String> set2) {
        for (String s : set1) {
            if (!set2.contains(s)) {
                return false;
            }
        }
        return true;
    }
}

void putAttributes(final ByteVector output) {

    int moduleAttributeLength =
        16 + requires.length + exports.length + opens.length + usesIndex.length + provides.length;
    output
        .putShort(symbolTable.addConstantUtf8(Constants.MODULE))
        .putInt(moduleAttributeLength)
        .putShort(moduleNameIndex)
        .putShort(moduleFlags)
        .putShort(moduleVersionIndex)
        .putShort(requiresCount)
        .putByteArray(requires.data, 0, requires.length)
        .putShort(exportsCount)
        .putByteArray(exports.data, 0, exports.length)
        .putShort(opensCount)
        .putByteArray(opens.data, 0, opens.length)
        .putShort(usesCount)
        .putByteArray(usesIndex.data, 0, usesIndex.length)
        .putShort(providesCount)
        .putByteArray(provides.data, 0, provides.length);
    if (packageCount > 0) {
      output
          .putShort(symbolTable.addConstantUtf8(Constants.MODULE_PACKAGES))
          .putInt(2 + packageIndex.length)
          .putShort(packageCount)
          .putByteArray(packageIndex.data, 0, packageIndex.length);
    }
    if (mainClassIndex > 0) {
      output
          .putShort(symbolTable.addConstantUtf8(Constants.MODULE_MAIN_CLASS))
          .putInt(2)
          .putShort(mainClassIndex);
    }
  }

import org.apache.lucene.analysis.TokenStream;
import org.apache.lucene.analysis.payloads.PayloadEncoder;
import org.apache.lucene.analysis.payloads.FloatEncoder;
import org.apache.lucene.analysis.payloads.IntegerEncoder;
import org.apache.lucene.analysis.payloads.IdentityEncoder;
import org.apache.lucene.analysis.payloads.DelimitedPayloadTokenFilter;
import org.elasticsearch.common.settings.Settings;
import org.elasticsearch.env.Environment;
import org.elasticsearch.index.IndexSettings;
import org.elasticsearch.index.analysis.AnalysisModule.AnalysisProvider;
import org.elasticsearch.indices.analysis.AnalysisFactoryTestCase;
import org.elasticsearch.plugins.AnalysisPlugin;

import java.io.IOException;
import java.util.Map;

public class DelimitedPayloadTokenFilterFactory extends AbstractTokenFilterFactory {

    private final char delimiter;
    private final PayloadEncoder encoder;

    @Inject
    public DelimitedPayloadTokenFilterFactory(IndexSettings indexSettings, Environment env, String name, Settings settings) {
        super(indexSettings, name, settings);
        this.delimiter = settings.getChar("delimiter", '|');
        String encoderType = settings.get("encoder", "float");
        switch (encoderType) {
            case "float":
                this.encoder = new FloatEncoder();
                break;
            case "integer":
                this.encoder = new IntegerEncoder();
                break;
            case "identity":
                this.encoder = new IdentityEncoder();
                break;
            default:
                throw new IllegalArgumentException("Unknown encoder type [" + encoderType + "]");
        }
    }

    @Override
    public TokenStream create(TokenStream tokenStream) {
        return new DelimitedPayloadTokenFilter(tokenStream, delimiter, encoder);
    }

    public static class Factory implements AnalysisProvider<DelimitedPayloadTokenFilterFactory> {
        @Override
        public DelimitedPayloadTokenFilterFactory get(IndexSettings indexSettings, Environment environment, String name, Settings settings) throws IOException {
            return new DelimitedPayloadTokenFilterFactory(indexSettings, environment, name, settings);
        }
    }

    public static class Plugin implements AnalysisPlugin {
        @Override
        public Map<String, AnalysisProvider<?>> getTokenFilters() {
            return Map.of("delimited_payload", new Factory());
        }
    }
}

