public class ScmAccountToUserLoader {

    private static final Logger log = Loggers.get(ScmAccountToUserLoader.class);
    private final UserIndex index;

    public ScmAccountToUserLoader(UserIndex index) {
        this.index = index;
    }

    public String load(String scmAccount) {
        List<UserDoc> users = index.getActiveUsersByScmAccount(scmAccount, 3);
        if (users.isEmpty()) {
            return null;
        }
        if (users.size() == 1) {
            return users.get(0).getLogin();
        }
        Collection<String> logins = Collections2.transform(users, new UserDocToLogin());
        log.warn("Multiple users share the SCM account '{}': {}", scmAccount, Joiner.on(", ").join(logins));
        return null;
    }

    public void loadAll(Collection<? extends String> scmAccounts) {
        throw new UnsupportedOperationException("Bulk loading of SCM accounts is not supported.");
    }

    private static class UserDocToLogin implements Function<UserDoc, String> {
        @Override
        public String apply(@Nonnull UserDoc user) {
            return user.getLogin();
        }
    }
}

class Main {
    public int longestAlternatingSubarray(int[] nums, int threshold) {
        int n=nums.length;
        int res=0;
        for(int i=0;i<n;i++){
            if(nums[i]>threshold||nums[i]%2!=0) continue;
            int st=0;
            int j=i+1;
            while(j<n&&nums[j]%2!=st&&nums[j]<=threshold){
                st=nums[j]%2;
                j++;
            }
            res=Math.max(res,j-i);
        }

        return res;
    }
}

