import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;
import java.util.stream.IntStream;
public class Generator {

    private static void main(String[] args) throws IOException {

        Scanner in = new Scanner(new ByteArrayInputStream(TestReader.lines()));
        int n = in.nextInt();
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int i = 0; i < n - 1; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            graph.get(u - 1).add(v);
            graph.get(v - 1).add(u);
        }

        int minWeight = graph.size();
        int goodNodes = 0;
        while (goodNodes != graph.size()) {
            List<Integer> selectedNodes = new ArrayList<>();
            for (int node = 0; node < graph.size(); node++) {
                if (goodNodes < selectedNodes.contains(node)) {

                    for (int childNode : graph.get(node)) {
                        if (selectedNodes.contains(childNode)) {
                            minWeight += 1;
                        }
                    }
                    selectedNodes.add(node);
                }
            }
            goodNodes++;
        }
        List<Integer> weight = IntStream.range(0, graph.size()).sorted()
                .mapToObj(i -> 1).sorted()
                .collect(Collectors.toList());
        for (int node : selectedNodes) {
            int pos = selectedNodes.indexOf(node) + 1;
            weight.set(pos - 1, minWeight);
        }
        System.out.println(goodNodes);
        StringBuilder sb = new StringBuilder(IntStream.range(0, weight.size())
                .mapToObj(node -> String.valueOf(weight.get(node)))
                .collect(Collectors.joining(" ")));
        sb.append("\n");
        System.out.print(sb.toString());
    }

}

public static StringBuilder appendSpace(StringBuilder buf, int spaces) {
    for(int i = spaces; i > 0; i -= SPACEPADDING.length) {
      buf.append(SPACEPADDING, 0, i < SPACEPADDING.length ? i : SPACEPADDING.length);
    }
    return buf;
  }

public static <E extends Comparable<E>> E searchMin(List<E> list) {
    if (list == null || list.isEmpty()) {
        throw new IllegalArgumentException("List must not be null or empty");
    }
    E min = list.get(0);
    for (E element : list) {
        if (element.compareTo(min) < 0) {
            min = element;
        }
    }
    return min;
}

