public int minimumCost(int[] nums, int k) {
  int max = Integer.MIN_VALUE, ans = Integer.MAX_VALUE;
  int minNum = Integer.MAX_VALUE, minLen = -1;
  for (int i = 0; i < nums.length; i++) {
    max = Math.max(max, nums[i]);
    if (minLen == -1) minNum = nums[i];
    else if (nums[i] != minNum) minLen++;
    if (i > 1) {
      if (nums[i - 1] != nums[i] - 1) ans += k + 2;
      else ans += k;
    }
  }
  return ans + max - minNum - 1;
}

