public class Ftree {

    private static final int width = 400;
    private static final int height = 300;
    private static final int depth = 8;
    private static final int angle = 12;
    private static final int length = 50;
    private static final double frac = 0.8;

    public static void main(String[] args) {
        Grmap g = new Grmap(width, height);
        ftree(g, width / 2, height * 9 / 10, length, 0, depth);
        g.bitmap().writePpmFile("ftree.ppm");
    }

    private static void ftree(Grmap g, double x, double y, double distance, double direction, int depth) {
        double x2 = x + distance * Math.sin(direction * Math.PI / 180);
        double y2 = y - distance * Math.cos(direction * Math.PI / 180);
        g.aaLine(x, y, x2, y2);
        if (depth > 0) {
            ftree(g, x2, y2, distance * frac, direction - angle, depth - 1);
            ftree(g, x2, y2, distance * frac, direction + angle, depth - 1);
        }
    }
}

class Grmap {

    private final int width;
    private final int height;
    private final int[] pixels;
    private final Bitmap bitmap;

    public Grmap(int width, int height) {
        this.width = width;
        this.height = height;
        pixels = new int[width * height];
        bitmap = new Bitmap(width, height);
    }

    public Bitmap bitmap() {
        return bitmap;
    }

    public void aaLine(double x1, double y1, double x2, double y2) {
        int x1i = (int) x1;
        int y1i = (int) y1;
        int x2i = (int) x2;
        int y2i = (int) y2;
        int dx = Math.abs(x2i - x1i);
        int dy = Math.abs(y2i - y1i);
        int sx = x1i < x2i? 1 : -1;
        int sy = y1i < y2i? 1 : -1;
        int err = dx - dy;
        int e2;
        while (true) {
            setPixel(x1i, y1i);
            if (x1i == x2i && y1i == y2i) {
                break;
            }
            e2 = 2 * err;
            if (e2 > -dy) {
                err -= dy;
                x1i += sx;
            }
            if (e2 < dx) {
                err += dx;
                y1i += sy;
            }
        }
    }

    private void setPixel(int x, int y) {
        if (x < 0 || x >= width || y < 0 || y >= height) {
            return;
        }
        pixels[y * width + x] = 0xFFFFFF;
    }

