import java.util.*;

public class Task {
    public List<List<Integer>> removeInterval(List<List<Integer>> intervals, List<Integer> toBeRemoved) {
        List<List<Integer>> result = new ArrayList<>();
        int start = intervals.get(0).get(0);
        int end = intervals.get(intervals.size() - 1).get(1);
        for (int i = 0; i < intervals.size(); i++) {
            if (intervals.get(i).get(0) < toBeRemoved.get(0) && toBeRemoved.get(1) < intervals.get(i).get(1)) {
                continue;
            } else if (intervals.get(i).get(0) <= toBeRemoved.get(0) && toBeRemoved.get(1) <= intervals.get(i).get(1)) {
                if (i == 0) {
                    result.add(new ArrayList<>(Arrays.asList(start, toBeRemoved.get(0))));
                }
                result.add(new ArrayList<>(Arrays.asList(toBeRemoved.get(0), toBeRemoved.get(1))));
                if (i == intervals.size() - 1) {
                    result.add(new ArrayList<>(Arrays.asList(toBeRemoved.get(1), end)));
                }
                start = toBeRemoved.get(1);
                continue;
            } else if (intervals.get(i).get(0) < toBeRemoved.get(0)) {
                result.add(intervals.get(i));
                start = toBeRemoved.get(0);
            } else if (toBeRemoved.get(1) < intervals.get(i).get(1)) {
                result.add(new ArrayList<>(Arrays.asList(toBeRemoved.get(1), intervals.get(i).get(1))));
                start = intervals.get(i).get(1);
            }
        }
        return result;
    }
}

