import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;
 
public class Entropy {
 
    public static void main(String[] args) {
        try {
            BufferedReader br = new BufferedReader(new FileReader(Entropy.class.getName() + ".java"));
            String line;
            StringBuilder sb = new StringBuilder();
            while ((line = br.readLine())!= null) {
                sb.append(line);
            }
            br.close();
            System.out.println(entropy(sb.toString()));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public static double entropy(String s) {
        Map<Character, Integer> p = new HashMap<Character, Integer>();
        for (char c : s.toCharArray()) {
            if (p.containsKey(c)) {
                p.put(c, p.get(c) + 1);
            } else {
                p.put(c, 1);
            }
        }
        double lns = s.length();
        double sum = 0;
        for (Entry<Character, Integer> entry : p.entrySet()) {
            double count = entry.getValue();
            sum += count / lns * Math.log(count / lns) / Math.log(2);
        }
        return -sum;
    }
}

