public class MaxVacationDays {

    static public int maxVacationDays(int[][] flights, int[][] days) {
        int [] dp = new int[flights.length];
        Arrays.fill(dp, Integer.MIN_VALUE);
        dp[0] = 0;
        int ans = 0;
        for (int week = 0; week < days[0].length; week++) {
            for (int i = 0; i < flights.length; i++) {
                if (flights[i][0] == 1)
                    dp[0] += days[0][week];
                for (int j = 1; j < flights.length; j++) {
                    if (flights[i][j] == 0)
                        continue;
                    dp[j] = Math.max(dp[j] + days[j][week], dp[i] + days[j][week]);
                }
            }
            for (int i : dp) {
                if (i >= 0)
                    ans += i;
            }
        }
        return ans;
    }
}

