public abstract class GenericAssembler<SOURCE, TARGET> implements Assembler<SOURCE, TARGET> {

    protected Logger logger = LoggerFactory.getLogger(GenericAssembler.class);

    private Class<SOURCE> classSource;
    private Class<TARGET> classTarget;

    public GenericAssembler(Class<SOURCE> classSource, Class<TARGET> classTarget) {
        this.classSource = classSource;
        this.classTarget = classTarget;
    }

    /**
     * @return
     * @throws AssembleException
     */
    protected SOURCE newSourceInstance() {
        try {
            return (classSource!=null) ? (SOURCE) classSource.newInstance() : null;
        } catch (InstantiationException | IllegalAccessException e) {
            return null;
        }
    }

    /**
     * @return
     * @throws AssembleException
     */
    protected TARGET newTargetInstance() {
        try {
            return (classTarget!=null) ? (TARGET) classTarget.newInstance() : null;
        } catch (InstantiationException | IllegalAccessException e) {
            logger.error(e.getMessage());
            return null;
        }
    }

    /**
     * @return
     */
    protected Class<SOURCE> getClassSource() {
        return classSource;
    }

    /**
     * @return
     */
    protected Class<TARGET> getClassTarget() {
        return classTarget;
    }

    /* (non-Javadoc)
     * @see net.bounceme.chronos.utils.assemblers.Assembler#assemble(java.util.Collection)
     */
    public final Collection<TARGET> assemble(Collection<SOURCE> source) {
        if (source == null || source.isEmpty()) {
            return new ArrayList<TARGET>(0);
        }
        List<TARGET> items = new ArrayList<TARGET>(source.size());
        for (SOURCE s : source) {
            items.add(assemble(s));
        }
        return items;
    }

    /* (non-Javadoc)
     * @see net.bounceme.chronos.utils.assemblers.Assembler#assemble(java.util.Collection)
     */
    @SuppressWarnings(Constantes.UNCHECKED)
    public final TARGET[] assemble(SOURCE[] source) {
        if (source == null || source.length == 0) {
            return null;
        }

* Definition for a binary tree node.
 * function TreeNode(val) {
 *     this.val = val;
 *     this.left = this.right = null;
 * }
 */
/**
 * @param {TreeNode} root
 * @param {number} x
 * @param {number} y
 * @return {boolean}
 */
// Solution: preorder
// time complexity: O(logn)
// space complexity: O(1)
var isCousins = function (root, x, y) {
  const pathX = [];

  dfsPathToNode(root, root, x, pathX);
  let isFirstNode, isSecondNode, minDepth, diffNode;

  function isOneLevelCousin(node) {
    const d = findMinDepth(root, node);

    if (!d) {
      return -1
    }

    for (var p in pathX[1]) {
      if (pathX[1][p].val === node.val)
        if (d !== 1) {
          return d
        } else {
          minDepth = null;
          break;
        }
    }

  }

  minDepth = isOneLevelCousin(pathX[0]) // Find minLevel distance of x and y on paths
  diffNode = Math.min(x, y) != Math.min(pathX[0].val, pathX[1].val)
  isFirstNode = minDepth !== null && Math.max(x, y) === pathX[0].val // if x = true, min node should x,
  // so find max is better.
  isSecondNode = 1 - isFirstNode

  return minDepth && diffNode !== isSecondNode && Math.abs(findPathX.idx -  findPathX[1].length) >=  minDepth  + 1;

};

const dfsPre = (root, val, res) => {
  if (res || !root) return;
  root = val == root.val

  dfsPre(root.left, res);
  dfsPre(root.right, root)
  res.push(root);
}
