import com.mysql.cj.util.TimeUtil;

public class TimezoneDump {

    private static final String DEFAULT_URL = "jdbc:mysql://localhost:3306/test";

    public static void main(String[] args) {
        String jdbcUrl = (args.length > 0) ? args[0] : DEFAULT_URL;
        ResultSet rs = null;
        Connection conn = null;

        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
            conn = DriverManager.getConnection(jdbcUrl);

            rs = conn.createStatement().executeQuery("SHOW VARIABLES LIKE 'timezone'");

            String timezoneFromServer = null;
            if (rs.next()) {
                timezoneFromServer = rs.getString(2);
            }

            System.out.println("Server reported timezone: " + timezoneFromServer);

            String canonicalTimezone = null;
            if (timezoneFromServer != null) {
                canonicalTimezone = TimeUtil.getCanonicalTimezone(timezoneFromServer, null);
            }
            System.out.println("Java timezone equivalent: " + canonicalTimezone);

        } catch (ClassNotFoundException | SQLException e) {
            e.printStackTrace();
        } finally {
            if (rs != null) {
                try {
                    rs.close();
                } catch (SQLException e) {
                    e.printStackTrace();
                }
            }
            if(conn != null) {
                try {
                    conn.close();
                } catch (SQLException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}

