/**
 * Interface representing a memory page where data fragments can be inserted.
 */
interface DataPage {
    /**
     * Applies a fragmented update into the page.
     *
     * @param previousFragmentLink Link to the previous fragment, if any.
     * @param payload              Byte array fragment payload.
     * @throws IgniteException if applying the fragment fails.
     */
    void updatePageFragment(long previousFragmentLink, byte[] payload) throws IgniteException;

    /**
     * Returns the current content of the page, for verification or logging.
     *
     * @return a string representation of the content.
     */
    String getPageContent();
}

/**
 * Abstract class representing a generic page delta record.
 * It encapsulates common fields and methods used by all delta records.
 */
abstract class PageDeltaRecord {
    protected final int cacheId;
    protected final long pageId;

    public PageDeltaRecord(int cacheId, long pageId) {
        this.cacheId = cacheId;
        this.pageId = pageId;
    }

    /**
     * Applies this delta to the provided data page.
     *
     * @param page The data page to update.
     * @throws IgniteException if the update fails.
     */
    public abstract void applyDelta(DataPage page) throws IgniteException;

    /**
     * Returns an integer indicating the type of the delta record.
     *
     * @return the record type identifier.
     */
    public abstract int getRecordType();
}

/**
 * Record class that inserts a fragment into a page.
 * It uses a fragment-based approach to allow chaining large pieces of data.
 */
public class InsertPageFragmentRecord extends PageDeltaRecord {
    private final byte[] fragment;
    private final long previousFragmentLink;

    // Constant record type indicator for InsertPageFragmentRecord.
    private static final int RECORD_TYPE = 101;

    /**
     * Constructs an InsertPageFragmentRecord.
     *
     * @param cacheId              Unique identifier for the cache.
     * @param pageId               Unique identifier for the page.
     * @param fragment             Byte array containing the fragment payload.
     * @param previousFragmentLink Link to the previously inserted fragment.
     */

private void writeInt(int i, byte[] buf, int offset) throws IOException {
    buf[offset] = (byte) (i & 0xFF);
    buf[offset + 1] = (byte) ((i >> 8) & 0xFF);
    buf[offset + 2] = (byte) ((i >> 16) & 0xFF);
    buf[offset + 3] = (byte) ((i >> 24) & 0xFF);
}

