import java.util.ArrayList;
import java.util.List;
 
public class Pascal {
 
    private static List<List<Integer>> cache = new ArrayList<List<Integer>>();
 
    static {
        cache.add(new ArrayList<Integer>());
        cache.get(0).add(1);
    }
 
    public static List<Integer> cumu(int n) {
        for (int l = cache.size(); l <= n; l++) {
            List<Integer> r = new ArrayList<Integer>();
            r.add(0);
            for (int x = 1; x <= l; x++) {
                r.add(r.get(r.size() - 1) + cache.get(l - x).get(Math.min(x, l - x)));
            }
            cache.add(r);
        }
        return cache.get(n);
    }
 
    public static List<Integer> row(int n) {
        List<Integer> r = cumu(n);
        List<Integer> result = new ArrayList<Integer>();
        for (int i = 0; i < n; i++) {
            result.add(r.get(i + 1) - r.get(i));
        }
        return result;
    }
 
    public static void main(String[] args) {
        System.out.println("rows:");
        for (int x = 1; x <= 10; x++) {
            System.out.print(x + ":");
            for (int y : row(x)) {
                System.out.print(" " + y);
            }
            System.out.println();
        }
 
        System.out.println("\nsums:");
        for (int x : new int[] { 23, 123, 1234, 12345 }) {
            System.out.println(x + " " + cumu(x).get(cumu(x).size() - 1));
        }
    }
}

