import java.util.concurrent.TimeUnit;

public void sendRequestTimeout(int timeout, int wait, String requestType, String endPoint, String responseVal) throws Exception {
    long startTime = System.nanoTime();
    String response = "";

    while (System.nanoTime() - startTime < TimeUnit.SECONDS.toNanos(timeout)) {
        // Send the request and get the response
        response = sendRequest(requestType, endPoint);

        // Check if the response contains the expected value
        if (response.contains(responseVal)) {
            System.out.println("Response contains expected value!");
            return;
        }

        // Wait for the specified amount of time before checking again
        Thread.sleep(TimeUnit.SECONDS.toMillis(wait));
    }

    throw new Exception("Timeout exceeded before expected value was found in response");
}

