public int findMaxProduct(Node node) {
if (node.left == null && node.right == null) {
return 0;
}
int idx1 = -1, idx2 = -1, max = 0;

for (int i = 0; i < node.children.size(); i++) {
Node child = node.children.get(i);
if (findMaxProduct(child) > max) {
max = findMaxProduct(child);
idx2 = i;
}
}
if (idx1 == -1 && idx2 == -1) {
return max + node.value;
}
int min = node.value, max1 = 0, max2 = 0;
for (int i = 0; i < node.children.size(); i++) {
Node child = node.children.get(i);
if (child == node.children.get(idx1)) {
continue;
}
max1 = Math.max(max1, findMaxProduct(child));
}
for (int i = 0; i < node.children.size(); i++) {
Node child = node.children.get(i);
if (child == node.children.get(idx2)) {
continue;
}
max2 = Math.max(max2, findMaxProduct(child));
}
for (int i = 0; i < node.children.size(); i++) {
Node child = node.children.get(i);
if (child == node.children.get(idx1)) {
min = Math.min(min, findMaxProduct(child));
continue;
}
max = Math.max(min * max2, max);
max = Math.max(min * max1, max);
}

return max;
}

public int findMaxProductII(Node node) {
if (node.left == null && node.right == null) {
return 0;
}
int idxs[] = { 0, 1, 2, 3 };
int idx2 = is_palindrome4(node.value) ? 1 : 2;
int max = findMaxProduct(node);
for (int i = 0; i < 4; i++) {
if (i != idx2) {
int max1 = 0;
int max2 = 0;
for (int j = 0; j < node.children.size(); j++) {
Node child = node.children.get(j);
if (node.children.get(j).id != node.id + i) {
max1 = Math.max(max1, findMaxProduct(node.children.get(j)));
} else {
max2 = Math.max(max2, findMaxProduct(node.children.get(j)));
}
}
max = Math.max(max, Math.min(max1, max2) * max);
}
}
return max;
}

