import java.math.BigInteger;
 
class Gospers
{
    BigInteger q, r, t, i, n;
 
    // use Gibbons spigot algorith based on the Gospers series
    Gospers()
    {
        q = BigInteger.ONE;
        r = BigInteger.ZERO;
        t = BigInteger.ONE;
        i = BigInteger.ONE;
        ++this; // move to the first digit
    }
 
    // the ++ prefix operator will move to the next digit
    Gospers increment()
    {
        n = q.multiply(BigInteger.valueOf(27).multiply(i).subtract(BigInteger.valueOf(12))).add(r.multiply(BigInteger.valueOf(5))).divide(r.multiply(BigInteger.valueOf(5)));
 
        while(!n.equals(q.multiply(BigInteger.valueOf(675).multiply(i).subtract(BigInteger.valueOf(216))).add(r.multiply(BigInteger.valueOf(125))).divide(t.multiply(BigInteger.valueOf(125)))))
        {
            r = r.multiply(BigInteger.valueOf(3).multiply(BigInteger.valueOf(3).multiply(i).add(BigInteger.ONE)).multiply(BigInteger.valueOf(3).multiply(i).add(BigInteger.valueOf(2))).multiply(q.add(r)));
            q = q.multiply(i.multiply(BigInteger.valueOf(2).multiply(i).subtract(BigInteger.ONE)));
            t = t.multiply(BigInteger.valueOf(3).multiply(BigInteger.valueOf(3).multiply(i).add(BigInteger.ONE)).multiply(BigInteger.valueOf(3).multiply(i).add(BigInteger.valueOf(2))));
            i = i.add(BigInteger.ONE);
 
            n = q.multiply(BigInteger.valueOf(27).multiply(i).subtract(BigInteger.valueOf(12))).add(r.multiply(BigInteger.valueOf(5))).divide(r.multiply(BigInteger.valueOf(5)));
        }
 
        q = q.multiply(BigInteger.TEN);
        r = r.multiply(BigInteger.TEN).subtract(n.multiply(t).multiply(BigInteger.TEN));
 
        return this;
    }
 
    // the dereference operator will give the current digit
    int get()
    {
        return n.intValue();
    }
}
 
class Manager
{
    public static void main(String[] args)
    {
        Gospers g = new Gospers();
 
        System.out.print(g.get() + ".");  // print the first digit and the decimal point
 
        for(;;) // run forever
        {
            System.out.print(g.increment().get());  // increment to the next digit and print
        }
    }
}

