public:
    string longestWord(vector<string>& words) {

        unordered_set<string> st;
        string ans="";

        for(string s:words)
        {
            st.insert(s);
        }

        for(string s:words)
        {
            bool flag=true;
            for(int i=0;i<s.length();i++)
            {
                if(st.find(s.substr(i+1))==st.end())
                {
                    flag=false;
                    break;
                }
            }

            if(flag && (s.length()>ans.length() || (s.length()==ans.length() && s<ans)))
            {
                ans=s;
            }
        }
        return ans;

    }
};

import java.util.Scanner;

public class Service {
    static String hexValue = "";

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a decimal number to convert to hex: ");
        int number = in.nextInt();

        System.out.println(number + " is equivalent to hexadecimal number " + dec2Hex(number));
        in.close();
    }

    public static String dec2Hex(int value) {
        if (value < 16) {
            return getAsHexNumber(value) + hexValue;
        }
        hexValue = getAsHexNumber(value % 16) + hexValue;
        return dec2Hex(value / 16);

    }

    static String getAsHexNumber(int value) {
        switch (value) {
            case 10:
                return "A";
            case 11:
                return "B";
            case 12:
                return "C";
            case 13:
                return "D";
            case 14:
                return "E";
            case 15:
                return "F";
            default:
                return String.valueOf(value);
        }

    }
}

class Runner {
    public int splitArray(int[] nums, int k) {
        int left = 0, right = 0;
        for (int num : nums) {
            left = Math.max(left, num);
            right += num;
        }

        while (left < right) {
            int mid = left + (right - left) / 2;
            int pieces = 1, currentSum = 0;
            for (int num : nums) {
                if (currentSum + num > mid) {
                    pieces++;
                    currentSum = num;
                } else {
                    currentSum += num;
                }
            }

            if (pieces > k) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        return left;
    }
}

