class Student {
    String out = "";

    public String longestSubsequenceRepeatedK(String s, int k) {
        int[] cnt = new int[26];
        final int n = s.length();
        for (int i = 0; i < n; ++i) cnt[s.charAt(i) - 'a']++;
        for (int i = 0; i < 26; ++i) cnt[i] /= k;
        explore(new StringBuilder(), cnt, k, s);
        return out;
    }

    private void explore(StringBuilder path, int[] cnt, int k, String s) {
        if (out.length() < path.length() || (out.length() == path.length() && out.compareTo(path.toString()) < 0)) out = path.toString();
        final int sz = path.length();
        for (int i = 0; i < 26; ++i) {
            if (cnt[i] == 0) continue;
            cnt[i] -= 1;
            path.append((char)('a' + i));
            if (check(s, path, k))
                explore(path, cnt, k, s);
            path.deleteCharAt(sz);
            cnt[i] += 1;
        }
    }

    private boolean check(String s, StringBuilder sub, int k) {
        int i = 0, j = 0, ni = s.length(), nj = sub.length();
        while (k > 0 && i < ni) {
            if (s.charAt(i) == sub.charAt(j)) {
                ++j;
                if (j == nj) { --k; j = 0; }
            }
            ++i;
        }
        return k == 0;
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Knapsack {
 
    public static class Item {
        public String name;
        public int value;
        public double weight, volume;
    }
 
    public static class Result {
        public List<Integer> counts = new ArrayList<>();
        public int sum;
    }
 
    public static int min(int a, int b) {
        return a < b? a : b;
    }
 
    public static Result Knapsack(List<Item> items, double weight, double volume) {
        if (items.isEmpty()) {
            return new Result();
        }
        int n = items.size() - 1;
        int maxCount = min((int) (weight / items.get(n).weight), (int) (volume / items.get(n).volume));
        Result best = new Result();
        for (int count = 0; count <= maxCount; count++) {
            Result sol = Knapsack(items.subList(0, n),
                    weight - count * items.get(n).weight,
                    volume - count * items.get(n).volume);
            sol.sum += items.get(n).value * count;
            if (sol.sum > best.sum) {
                sol.counts.add(count);
                best = sol;
            }
        }
        return best;
    }
 
    public static void main(String[] args) {
        List<Item> items = new ArrayList<>();
        items.add(new Item("Panacea", 3000, 0.3, 0.025));
        items.add(new Item("Ichor", 1800, 0.2, 0.015));
        items.add(new Item("Gold", 2500, 2.0, 0.002));
        int sumCount = 0, sumValue = 0;
        double sumWeight = 0, sumVolume = 0;
        Result result = Knapsack(items, 25, 0.25);
        for (int i = 0; i < result.counts.size(); i++) {
            System.out.printf("%-8s x%3d  -> Weight: %4.1f  Volume: %5.3f  Value: %6d\n",
                    items.get(i).name, result.counts.get(i), items.get(i).weight * result.counts.get(i),
                    items.get(i).volume * result.counts.get(i), items.get(i).value * result.counts.get(i));
            sumCount += result.counts.get(i);
            sumValue += items.get(i).value * result.counts.get(i);
            sumWeight += items.get(i).weight * result.counts.get(i);
            sumVolume += items.get(i).volume * result.counts.get(i);
        }
        System.out.printf("TOTAL (%3d items) Weight: %4.1f  Volume: %5.3f  Value: %6d\n",
                sumCount, sumWeight, sumVolume, sumValue);
    }
}

