public int countDifferentSubsequenceGCDs(int[] nums) {
        int n = nums.length;
        int[] max = new int[200006];
        for (int i = 0; i < n; i++) {
            max[nums[i]] = Math.max(nums[i], max[nums[i]]);
        }
        int ans = 0;
        for (int i = 1; i <= 200001; i++) {
            if (max[i] != 0) {
                int g = 0;
                for (int j = i; j <= 200001; j += i) {
                    if (max[j] != 0) {
                        g = gcd(g, j);
                    }
                }
                if (g == i) {
                    ans++;
                }
            }
        }
        return ans;
    }

