int test_mod_a(int n, int a, int b, int x)
{
  int mod_a = (x - a) % b;
  return 0 == mod_a ? true : false;
}

bool test_mod_x(int x, int a, int b, int mod_x)
{
    int mod_a = (x - a) % b;
    if (mod_a == mod_x)
      return true;
    else
      return false;
}

int le_n(int n, int a, int b, int x)
{
  int div_a = (x - a) / b;
  return (div_a + 1) < n ? 0 : div_a;
}

int xtions(int n)
{
  int a, b, x, mod_x, test_cases;
  string input;
  cin >> n;
  while (n)
  {
    a = 1 + n / 10;
    n = n % 100;
    b = 2 + n / 10;
    n = n % 10;
    x = n;
    mod_x = n - (a + b);
    if (!test_mod_x(x, a, b, mod_x))
      continue;
    test_cases = 0;
    for (int i = le_n(n, a, b, x);; i--)
    {
      if (! test_mod_a(4, a, b, i * x))
      {
        cout << i * x;
        return 0;
      }
      else
        test_cases++;
    }
  }
}

void solution()
{
  xtions(0);
}

int main()
{
  solution();
}

