/**
 * Interface for processing modules in the part-of-speech post-processing pipeline.
 */
interface IPostProcessor {
    /**
     * Process the given sentence and update it accordingly.
     *
     * @param sentence the sentence object to process.
     */
    void process(Sentence sentence);

    /**
     * Initialize any required resources.
     */
    void initialize();

    /**
     * Shutdown and cleanup resources.
     */
    void shutdown();
}

/**
 * Class representing a morpheme, which consists of the text and its associated
 * part-of-speech tag.
 */
class Morpheme {
    private String text;
    private String tag;

    public Morpheme(String text, String tag) {
        this.text = text;
        this.tag = tag;
    }

    public String getText() {
        return text;
    }

    public String getTag() {
        return tag;
    }

    public void setTag(String tag) {
        this.tag = tag;
    }
}

/**
 * Class representing a word segment which is composed of multiple morphemes.
 */
class WordSegment {
    private List<Morpheme> morphemes;

    public WordSegment() {
        this.morphemes = new LinkedList<>();
    }

    public List<Morpheme> getMorphemes() {
        return morphemes;
    }

    public void setMorphemes(List<Morpheme> morphemes) {
        this.morphemes = morphemes;
    }

    public void addMorpheme(Morpheme morpheme) {
        this.morphemes.add(morpheme);
    }
}

/**
 * Class representing a sentence, which is a collection of word segments.
 */
class Sentence {
    private List<WordSegment> segments;

    public Sentence() {
        this.segments = new LinkedList<>();
    }

    public List<WordSegment> getSegments() {
        return segments;
    }

    public void setSegments(List<WordSegment> segments) {
        this.segments = segments;
    }

    public void addSegment(WordSegment segment) {
        this.segments.add(segment);
    }
}

