import java.util.ArrayList;
import java.util.List;
 
public class PrimeGaps {
 
    public static void main(String[] args) {
        // sieve up to 10,000,019 - the first prime after 10 million
        final int limit = 10000000;
        boolean[] sieved = sieve(limit);
        // extract primes
        List<Integer> primes = new ArrayList<>();
        primes.add(2);
        for (int i = 3; i <= limit; i += 2) {
            if (!sieved[i]) {
                primes.add(i);
            }
        }
        // extract strong and weak primes
        List<Integer> strong = new ArrayList<>();
        List<Integer> weak = new ArrayList<>();
        weak.add(3); // so can use integer division for rest
        for (int i = 2; i < primes.size() - 1; i++) { // start from 5
            int p = primes.get(i);
            if (p > (primes.get(i - 1) + primes.get(i + 1)) / 2) {
                strong.add(p);
            } else if (p < (primes.get(i - 1) + primes.get(i + 1)) / 2) {
                weak.add(p);
            }
        }
 
        System.out.println("The first 36 strong primes are:");
        System.out.println(strong.subList(0, 36));
        int count = 0;
        for (int p : strong) {
            if (p >= 1000000) {
                break;
            }
            count++;
        }
        System.out.println("\nThe number of strong primes below 1,000,000 is " + commatize(count));
        System.out.println("\nThe number of strong primes below 10,000,000 is " + commatize(strong.size()));
 
        System.out.println("\nThe first 37 weak primes are:");
        System.out.println(weak.subList(0, 37));
        count = 0;
        for (int p : weak) {
            if (p >= 1000000) {
                break;
            }
            count++;
        }
        System.out.println("\nThe number of weak primes below 1,000,000 is " + commatize(count));
        System.out.println("\nThe number of weak primes below 10,000,000 is " + commatize(weak.size()));
    }
 
    private static boolean[] sieve(int limit) {
        limit++;
        // True denotes composite, false denotes prime.
        // Don't bother marking even numbers >= 4 as composite.
        boolean[] c = new boolean[limit];
        c[0] = true;
        c[1] = true;
 
        int p = 3; // start from 3
        while (true) {
            int p2 = p * p;
            if (p2 >= limit) {
                break;
            }
            for (int i = p2; i < limit; i += 2 * p) {
                c[i] = true;
            }
            do {
                p += 2;
            } while (c[p]);
        }

private Date extrapolateStartTimeFromScanRanges(List<ScanRangeStatus> pendingScanRanges, List<ScanRangeStatus> activeScanRanges, List<ScanRangeStatus> completeScanRanges) {
    // Combine all scan ranges into a single list
    List<ScanRangeStatus> allScanRanges = new ArrayList<>();
    allScanRanges.addAll(pendingScanRanges);
    allScanRanges.addAll(activeScanRanges);
    allScanRanges.addAll(completeScanRanges);

    // Find the earliest startTime among all scan ranges
    Date earliestStartTime = null;
    for (ScanRangeStatus scanRange : allScanRanges) {
        Date startTime = scanRange.getStartTime();
        if (startTime != null) {
            if (earliestStartTime == null || startTime.before(earliestStartTime)) {
                earliestStartTime = startTime;
            }
        }
    }

    // If no startTime was found, return null
    if (earliestStartTime == null) {
        return null;
    }

    // If a startTime was found, return it
    return earliestStartTime;
}

