@RunWith(SpringRunner.class)
@SpringBootTest
public class UserControllerRESTfulTest {

    @Autowired
    private WebApplicationContext webApplicationContext;

    private MockMvc mvc;

    @Before
    public void setUp() {
        mvc = MockMvcBuilders.webAppContextSetup(webApplicationContext).build();
    }

    @Test
    public void UserControllerRESTfulTest() throws Exception {
        RequestBuilder request;

        // 1. Get all users (should be empty initially)
        request = MockMvcRequestBuilders.get("/users/")
                .accept(MediaType.APPLICATION_JSON);
        mvc.perform(request)
                .andExpect(status().isOk())
                .andDo(result -> System.out.println("Get all users (empty): " + result.getResponse().getContentAsString()));

        // 2. Create a new user
        request = MockMvcRequestBuilders.post("/users/")
                .param("name", "John Doe")
                .accept(MediaType.APPLICATION_JSON);

        MvcResult result = mvc.perform(request)
                .andExpect(status().isOk())
                .andDo(r -> System.out.println("Create user: " + r.getResponse().getContentAsString()))
                .andReturn();

        // 3. Get all users (should contain the new user)
        request = MockMvcRequestBuilders.get("/users/")
                .accept(MediaType.APPLICATION_JSON);
        mvc.perform(request)
                .andExpect(status().isOk())
                .andDo(r -> System.out.println("Get all users (1 user): " + r.getResponse().getContentAsString()));

        // 4. Update the user
        String userId = result.getResponse().getContentAsString();

        request = MockMvcRequestBuilders.put("/users/" + userId)
                .param("name", "Updated John Doe")
                .accept(MediaType.APPLICATION_JSON);

import xxl.core.functions.AbstractFunction;
import xxl.core.functions.Function;
import xxl.core.indexStructures.BPlusTree.KeyRange;

public class ShortKeyRange extends KeyRange<Short> {

    // Factory function for creating ShortKeyRange instances
    public static final Function<Object, ShortKeyRange> FACTORY_FUNCTION =
        new AbstractFunction<Object, ShortKeyRange>() {
            @Override
            public ShortKeyRange invoke(Object min, Object max) {
                return new ShortKeyRange((Short) min, (Short) max);
            }
        };

    // Constructor for creating a ShortKeyRange with min and max bounds
    public ShortKeyRange(Short min, Short max) {
        super(min, max);
    }

    // Override clone method to ensure deep copying of the key range
    @Override
    public ShortKeyRange clone() {
        return new ShortKeyRange(this.getMin(), this.getMax());
    }

    // Getter for the separator value (used in B+ tree operations)
    public Short getSepValue() {
        return this.getMin();
    }

    // Getter for the maximum bound of the key range
    public Short getMaxBound() {
        return this.getMax();
    }

    // Utility method to check if a key is within the range
    public boolean contains(Short key) {
        return key.compareTo(this.getMin()) >= 0 && key.compareTo(this.getMax()) <= 0;
    }

    // Override toString for better readability
    @Override
    public String toString() {
        return "ShortKeyRange [min=" + this.getMin() + ", max=" + this.getMax() + "]";
    }

    // Example usage of the factory function
    public static void main(String[] args) {
        ShortKeyRange range = FACTORY_FUNCTION.invoke((short) 10, (short) 20);
        System.out.println(range); // Output: ShortKeyRange [min=10, max=20]
    }
}

private boolean setField(Object fld) {
    GridDatatype gg = null;
    if (fld instanceof GridDatatype)
      gg = (GridDatatype) fld;
    else if (fld instanceof String)
      gg = gridDataset.findGridDatatype( (String) fld);
    if (null == gg)
      return false;

    renderGrid.setGeoGrid(gg);
    currentField = gg;

    GridCoordSystem gcs = gg.getCoordinateSystem();
    gcs.setProjectionBoundingBox();

    CoordinateAxis1D vaxis = gcs.getVerticalAxis();
    levelNames = (vaxis == null) ? new ArrayList() : vaxis.getNames();
    if ((levelNames == null) || (currentLevel >= levelNames.size()))
      currentLevel = 0;
    vertPanel.setCoordSys(currentField.getCoordinateSystem(), currentLevel);

    if (gcs.hasTimeAxis()) {
      CoordinateAxis1DTime taxis = gcs.hasTimeAxis1D() ? gcs.getTimeAxis1D() : gcs.getTimeAxisForRun(0);
      timeNames = (taxis == null) ? new ArrayList() : taxis.getNames();
      if ((timeNames == null) || (currentTime >= timeNames.size()))
        currentTime = 0;
      hasDependentTimeAxis = !gcs.hasTimeAxis1D();
    } else
      hasDependentTimeAxis = false;

    CoordinateAxis1D eaxis = gcs.getEnsembleAxis();
    ensembleNames = (eaxis == null) ? new ArrayList() : eaxis.getNames();
    currentEnsemble = ensembleNames.size() > 0 ? 0 : -1;

    CoordinateAxis1DTime rtaxis = gcs.getRunTimeAxis();
    runtimeNames = (rtaxis == null) ? new ArrayList() : rtaxis.getNames();
    currentRunTime = runtimeNames.size() > 0 ? 0 : -1;

    ui.setField(gg);
    return true;
  }

