import org.apache.camel.component.ironmq.IronMQEndpoint;
import org.apache.camel.component.mock.MockEndpoint;
import org.junit.Test;

public class IronMQHeaderPreservationTest extends CamelTestSupport {

    @Override
    protected CamelContext createCamelContext() throws Exception {
        CamelContext context = super.createCamelContext();
        IronMQComponent ironMQComponent = new IronMQComponent();
        ironMQComponent.setProjectId("your_project_id");
        ironMQComponent.setToken("your_token");
        context.addComponent("ironmq", ironMQComponent);
        return context;
    }

    @Override
    protected RouteBuilder createRouteBuilder() throws Exception {
        return new RouteBuilder() {
            @Override
            public void configure() {
                from("direct:start")
                    .to("ironmq://myQueue")
                    .to("mock:result");
            }
        };
    }

    @Test
    public void testPreserveHeaders() throws Exception {
        MockEndpoint resultEndpoint = getMockEndpoint("mock:result");
        resultEndpoint.expectedMessageCount(1);

        String messageBody = "Hello, IronMQ!";
        String customHeaderKey = "X-Custom-Header";
        String customHeaderValue = "CustomValue";

        template.sendBodyAndHeader("direct:start", messageBody, customHeaderKey, customHeaderValue);

        assertMockEndpointsSatisfied();

        // Verify that the result message has the same headers and body
        resultEndpoint.assertIsNotNull();
        var receivedMessage = resultEndpoint.getExchanges().get(0).getIn();

        assertEquals("Message body not preserved", messageBody, receivedMessage.getBody(String.class));
        assertEquals("Custom header not preserved", customHeaderValue,
                     receivedMessage.getHeader(customHeaderKey));
        assertNotNull("Message ID should be present",
                      receivedMessage.getHeader(IronMQEndpoint.HEADER_MESSAGE_ID));
    }

    public static void main(String[] args) {
        IronMQHeaderPreservationTest test = new IronMQHeaderPreservationTest();
        try {
            test.setUp();
            test.testPreserveHeaders();
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            test.tearDown();
        }
    }
}

