/**
 * A bouncing ball, moved and reflected by a Container.
 */
class Ball {

    private float posX;
    private float posY;
    private int radius;
    private float speedX;
    private float speedY;

    public Ball(float posX, float posY, int radius, float speedX, float speedY) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speedX;
        this.speedY = speedY;
    }

    public Ball(float posX, float posY, int radius, int speed, int direction) {
        this.posX = posX;
        this.posY = posY;
        this.radius = radius;
        this.speedX = speed * (float) Math.cos(Math.toRadians(direction));
        this.speedY = -speed * (float) Math.sin(Math.toRadians(direction));
    }

    public float getX() {
        return posX;
    }

    public void setX(float posX) {
        this.posX = posX;
    }

    public float getY() {
        return posY;
    }

    public void setY(float posY) {
        this.posY = posY;
    }

    public int getRadius() {
        return radius;
    }

    public void setRadius(int radius) {
        this.radius = radius;
    }

    public float getXDelta() {
        return speedX;
    }

    public void setXDelta(float speedX) {
        this.speedX = speedX;
    }

    public float getYDelta() {
        return speedY;
    }

    public void setYDelta(float speedY) {
        this.speedY = speedY;
    }

    public int getSpeed() {
        return (int) Math.sqrt(speedX * speedX + speedY * speedY);
    }

    public int getDirection() {
        return (int) Math.toDegrees(Math.atan2(-speedY, speedX));
    }

    public void setXY(int posX, int posY) {
        this.posX = posX;
        this.posY = posY;
    }

    public void move() {
        posX += speedX;
        posY += speedY;
    }

    public void reflectHorizontal() {
        speedX = -speedX;
    }

    public void reflectVertical() {
        speedY = -speedY;
    }

    @Override
    public String toString() {
        return "Ball[(" + posX + "," + posY + "),speed=(" + speedX + "," + speedY + ")]";
    }
}

