import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.util.StringTokenizer;

public class Task {

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int t = Integer.parseInt(br.readLine());
        for (int i = 0; i < t; i++) {
            st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int k = Integer.parseInt(st.nextToken());
            ArrayList<Integer>[] adj = new ArrayList[n + 1];
            for (int j = 0; j <= n; j++) {
                adj[j] = new ArrayList<>();
            }
            for (int j = 0; j < n - 1; j++) {
                st = new StringTokenizer(br.readLine());
                int u = Integer.parseInt(st.nextToken());
                int v = Integer.parseInt(st.nextToken());
                adj[u].add(v);
                adj[v].add(u);
            }
            int[] cnt = new int[n + 1];
            int[] vis = new int[n + 1];
            dfs(adj, cnt, vis, 1, 0, k);
            System.out.println(cnt[0] / k);
        }
    }

    public static void dfs(ArrayList<Integer>[] adj, int[] cnt, int[] vis, int u, int p, int k) {
        vis[u] = 1;
        int child = 0;
        for (int v : adj[u]) {
            if (vis[v] == 0) {
                dfs(adj, cnt, vis, v, u, k);
                child++;
            }
        }
        if (child > 0) {
            int tmp = child % k;
            if (tmp!= 0) {
                child -= tmp;
                child += k;
            }
            cnt[0] += child / k;
        }
    }
}

import java.util.stream.IntStream;
 
public class Finder {
 
    static IntStream getPrimes(int start, int end) {
        return IntStream.rangeClosed(start, end).filter(n -> isPrime(n));
    }
 
    public static boolean isPrime(long x) {
        if (x < 3 || x % 2 == 0)
            return x == 2;
 
        long max = (long) Math.sqrt(x);
        for (long n = 3; n <= max; n += 2) {
            if (x % n == 0) {
                return false;
            }
        }
        return true;
    }
 
    public static void main(String[] args) {
        getPrimes(0, 100).forEach(p -> System.out.printf("%d, ", p));
    }
}

import android.content.Context;
import android.view.LayoutInflater;
