import hrv.band.app.R;
import hrv.band.app.ui.view.fragment.MeasuredParameterFragment;
import hrv.calc.parameter.HRVParameter;

/**
 * Copyright (c) 2017
 * <p>
 * This adapter holds the hrv parameters to show in the {@link MeasuredParameterFragment}.
 */
public class ValueAdapter extends BaseAdapter {

    /**
     * The context of activity holding the adapter.
     **/
    private final Context context;
    /**
     * The hrv parameter to display.
     **/
    private final List<HRVParameter> parameters;

    public ValueAdapter(Context context, List<HRVParameter> parameters) {
        this.context = context;
        this.parameters = parameters;
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        ViewHolder holder;
        if (convertView == null) {
            LayoutInflater inflater = (LayoutInflater) context
                    .getSystemService(Context.LAYOUT_INFLATER_SERVICE);
            convertView = inflater.inflate(R.layout.measure_list_item, parent, false);
            holder = new ViewHolder();
            holder.descText = (TextView) convertView.findViewById(R.id.measure_value_desc);
            holder.valueText = (TextView) convertView.findViewById(R.id.hrv_value);
            holder.unitText = (TextView) convertView.findViewById(R.id.measure_value_unit);
            convertView.setTag(holder);
        } else {
            holder = (ViewHolder) convertView.getTag();
        }

        if (parameters != null) {
            HRVParameter param = (HRVParameter) getItem(position);
            holder.descText.setText(param.getName());
            holder.valueText.setText(new DecimalFormat("#.##").format(param.getValue()));
            holder.unitText.setText(param.getUnit());
        }

        return convertView;
    }

    @Override
    public Object getItem(int i) {
        return parameters.get(i);
    }

    @Override
    public int getCount() {
        return parameters.size();
    }

    @Override
    public long getItemId(int i) {
        return i;
    }

    /**
     * The ViewHolder of this adapter.
     */
    private static class ViewHolder {
        private TextView descText;
        private TextView valueText;
        private TextView unitText;
    }
}

import com.amazonaws.AmazonServiceException;
import com.amazonaws.transform.Unmarshaller;

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;

public abstract class AbstractErrorUnmarshaller<T> implements Unmarshaller<AmazonServiceException, T> {

    private Class<? extends AmazonServiceException> exceptionClass;

    public AbstractErrorUnmarshaller() {
        this(AmazonServiceException.class);
    }

    public AbstractErrorUnmarshaller(Class<? extends AmazonServiceException> exceptionClass) {
        this.exceptionClass = exceptionClass;
    }

    @Override
    public AmazonServiceException unmarshall(T source) throws Exception {
        String message = parseExceptionMessage(source);
        return newException(message);
    }

    protected abstract String parseExceptionMessage(T source);

    protected AmazonServiceException newException(String message) {
        try {
            Constructor<? extends AmazonServiceException> constructor =
                    exceptionClass.getConstructor(String.class);
            return constructor.newInstance(message);
        } catch (NoSuchMethodException e) {
            throw new IllegalStateException("Exception class " + exceptionClass +
                    " must have a constructor that takes a single String argument", e);
        } catch (InvocationTargetException e) {
            throw new IllegalStateException("Failed to invoke constructor of " + exceptionClass, e);
        } catch (InstantiationException e) {
            throw new IllegalStateException("Failed to instantiate " + exceptionClass, e);
        } catch (IllegalAccessException e) {
            throw new IllegalStateException("Unable to access constructor of " + exceptionClass, e);
        }
    }
}

import com.hazelcast.client.impl.protocol.ClientMessage;
