class Processor {
    public int shortestSequence(int[] rolls, int k) {
        int res = 0;
        boolean[] cnts = new boolean[k+1];
        int cnt = 0;
        for (int num : rolls) {
            if (cnts[num]) continue;
            cnts[num] = true;
            cnt++;
            if (cnt == k) {
                Arrays.fill(cnts, false);
                cnt = 0;
                res++;
            }
        }
        return res + 1;
    }
}

