import java.util.*;

class Checker {
  public boolean isReachable(int targetX, int targetY) {
    // Initialize the queue with the starting point (1, 1)
    Queue<int[]> queue = new ArrayDeque<>();
    Set<int[]> visited = new HashSet<>();
    queue.offer(new int[]{1, 1});
    visited.add(new int[]{1, 1});

    // Perform BFS
    while (!queue.isEmpty()) {
      int[] current = queue.poll();
      int x = current[0];
      int y = current[1];

      // If we reach the target, return true
      if (x == targetX && y == targetY) {
        return true;
      }

      // Generate the next possible moves
      int[][] nextMoves = {
        {x, y - x},
        {x - y, y},
        {2 * x, y},
        {x, 2 * y}
      };

      for (int[] move : nextMoves) {
        int nextX = move[0];
        int nextY = move[1];

        // Check if the move is valid and not visited
        if (nextX > 0 && nextY > 0 && !visited.contains(new int[]{nextX, nextY})) {
          queue.offer(new int[]{nextX, nextY});
          visited.add(new int[]{nextX, nextY});
        }
      }
    }

    // If we exhaust the queue without reaching the target, return false
    return false;
  }
}

public:
    bool validTicTacToe(vector<string>& board) {
        int x_cnt = 0, o_cnt = 0;
        int row_cnt[3] = {0, 0, 0};
        int col_cnt[3] = {0, 0, 0};
        int diag1_cnt = 0, diag2_cnt = 0;
        for(int i = 0; i < 3; i++){
            for(int j = 0; j < 3; j++){
                if(board[i][j] == 'X'){
                    x_cnt++;
                }else if(board[i][j] == 'O'){
                    o_cnt++;
                }
                row_cnt[i]++;
                col_cnt[j]++;
                if(i == j){
                    diag1_cnt++;
                }
                if(i == 2 - j){
                    diag2_cnt++;
                }
            }
        }
        if((x_cnt == 1 && o_cnt == 2) || (o_cnt == 1 && x_cnt == 2)){
            return true;
        }
        if((x_cnt == 2 && o_cnt == 1) || (o_cnt == 2 && x_cnt == 1)){
            return false;
        }
        if(x_cnt == 3 || o_cnt == 3){
            return true;
        }
        if(x_cnt + o_cnt == 9){
            return false;
        }
        if((row_cnt[0] == 3 || row_cnt[1] == 3 || row_cnt[2] == 3) || (col_cnt[0] == 3 || col_cnt[1] == 3 || col_cnt[2] == 3) || (diag1_cnt == 3 || diag2_cnt == 3)){
            return true;
        }
        return false;
    }
};

