public List<Object> unwrapLists(List<Object> list) {
    List<Object> result = new ArrayList<>();
    for (Object item : list) {
        if (item instanceof Group && ((Group) item).getFieldCount() == 1
            && ((Group) item).getType(0).isPrimitive()) {
            result.add(((Group) item).get(0, 0));
        } else {
            result.add(item);
        }
    }
    return result;
}

