def maxHappyGroups(batchSize, groups):
    count = [0] * batchSize
    for g in groups:
        count[g % batchSize] += 1
    happy = count[0]
    count[0] = 0
    for i in range(1, (batchSize + 1) // 2):
        happy += max(0, count[i] - count[batchSize - i])
    if batchSize % 2 == 0:
        happy += count[batchSize // 2] // 2 * 2
        count[batchSize // 2] %= 2
    if batchSize % 3 == 0:
        happy += min(count[batchSize // 3], count[batchSize // 6]) * 2
        count[batchSize // 3] = max(0, count[batchSize // 3] - min(count[batchSize // 3], count[batchSize // 6]))
        count[batchSize // 6] = max(0, count[batchSize // 6] - min(count[batchSize // 3], count[batchSize // 6]))
    return happy + sum(count)

import java.net.URI;
import java.net.URISyntaxException;
import org.wso2.carbon.gateway.core.config.ParameterHolder;
import org.wso2.carbon.messaging.CarbonCallback;
import org.wso2.carbon.messaging.CarbonMessage;
import org.wso2.carbon.messaging.Constants;

/**
 *  HTTP Outbound Endpoint.
 */
public class HTTPOutboundEndpoint extends AbstractOutboundEndpoint {

    private String uri;
    private String host;
    private int    port;
    private String urlPath;

    private ParameterHolder parameters;

    public HTTPOutboundEndpoint(String name) {
        super(name);

    }

    @Override
    public boolean receive(CarbonMessage carbonMessage, CarbonCallback carbonCallback) throws Exception {

        processRequest(carbonMessage);

        // Send the message to the backend asynchronously
        ServiceContextHolder.getInstance().getSender().send(carbonMessage, carbonCallback);

        return true;
    }

    private void processRequest(CarbonMessage carbonMessage) throws URISyntaxException {

        URI uri = new URI(this.uri);
        host = uri.getHost();
        port = uri.getPort();
        urlPath = uri.getPath();

        if (port == -1) {
            port = 80;
        }

        carbonMessage.setProperty(Constants.HOST, host);
        carbonMessage.setProperty(Constants.PORT, port);
        carbonMessage.setProperty(Constants.TO, urlPath);

         String  hostHeader = host;

        if (port != 80) {
            hostHeader += ":" + port;
        }

        carbonMessage.setHeader(Constants.HOST, hostHeader);

    }

    public void setUri(String uri) {
        this.uri = uri;
    }

    public String getUri() {
        return uri;
    }

    @Override
    public void setParameters(ParameterHolder parameters) {
        this.parameters = parameters;
        if (parameters.getParameter("URI") != null) {
            uri = parameters.getParameter("URI").getValue();
        }
    }

    @Override
    public String getProtocol() {
        return "http";
    }
}

