import java.io.*;
import java.util.*;

public class ArrangingTheSheep {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        int t = Integer.parseInt(reader.readLine());
        for (int i = 0; i < t; i++) {
            int n = Integer.parseInt(reader.readLine());
            String level = reader.readLine();
            writer.println(minMoves(level));
        }

        writer.close();
    }

    public static int minMoves(String level) {
        int n = level.length();
        int moves = 0;

        // Count the number of sheep
        int sheepCount = 0;
        for (int i = 0; i < n; i++) {
            if (level.charAt(i) == '*') {
                sheepCount++;
            }
        }

        int targetPosition = 0;
        int actualPosition = 0;

        for (int i = 0; i < n; i++) {
            if (level.charAt(i) == '*') {
                moves += Math.abs(i - actualPosition);
                actualPosition += sheepCount - 1;
                sheepCount--;
            }
        }

        return moves;
    }
}

private void initializePattern(final String pattern) {
        final String[] split = pattern.split(Pattern.quote("*"), -1);
        final StringBuilder escapedPattern = new StringBuilder(Pattern.quote(split[0]));
        for (int i = 1; i < split.length; i++) {
            String quoted = Pattern.quote(split[i]);
            escapedPattern.append("([^.]*)").append(quoted);
        }
        final String regex = "^" + escapedPattern.toString() + "$";
        this.patternStr = regex;
        this.pattern = Pattern.compile(regex);
    }

