import java.util.*;

public class SelectionSort {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int test = sc.nextInt();

        sc.nextLine();

        while (test-- > 0) {

            String t = sc.next();

            System.out.println(fun2(t));

        }

    }

    private static int fun2(String t){

        int n = t.length();

        int[] dp = new int[n+1];

        int[] c = new int[26];

        for(int i=1;i<=n;i++){

            if(c[t.charAt(i-1)-'a']!=0){

                dp[i] = 2 + dp[c[t.charAt(i-1)-'a']-1];

            }

            dp[i] = Math.max(dp[i],dp[i-1]);

            c[t.charAt(i-1)-'a'] = i;

        }

        return n-dp[n];

    }

}

