class Reader {
    public int numSimilarGroups(String[] A) {
        int[] rank = new int[A.length];
        int[] paren = new int[A.length];
        int ans = A.length;

        for (int i = 0; i < paren.length; ++i) {
            paren[i] = i;
        }

        for (int i = 0; i < A.length - 1; ++i) {
            for (int j = i + 1; j < A.length; ++j) {
                if (similar(A[i], A[j])) {
                    int p1 = find(paren, i);
                    int p2 = find(paren, j);
                    if (p1 != p2) {
                        --ans;

                        union(rank, paren, p1, p2);
                    }
                }
            }
        }

        return ans;
    }

    private int find(int[] paren, int curr) {
        if (paren[curr] == curr) {
            return curr;
        }

        paren[curr] = find(paren, paren[curr]);
        return paren[curr];
    }

    private void union(int[] rank, int[] paren, int p1, int p2) {
        if (rank[p1] >= rank[p2]) {
            paren[p2] = p1;
        }
        else {
            paren[p1] = p2;
        }

        if (rank[p1] == rank[p2]) {
            ++rank[p1];
        }
    }

    private boolean similar(String s1, String s2) {
        if (s1.length() != s2.length()) {
            return false;
        }

        int count = 0;
        char[] arr1 = new char[2];
        char[] arr2 = new char[2];

        for (int i = 0; i < s1.length(); ++i) {
            if (s1.charAt(i) != s2.charAt(i)) {
                if (count == 2) {
                    return false;
                }
                arr1[count] = s1.charAt(i);
                arr2[count] = s2.charAt(i);

                count++;
            }
        }

        if (count != 2) {
            return false;
        }

        return (arr1[0] == arr2[0] && arr1[1] == arr2[1]) || (arr1[0] == arr2[1] && arr1[1] == arr2[0]);
    }
}

