public class LoadDataErrorFileManager {
    private static final String ERROR_FILE_DIR = "/path/to/error/files/";
    private static final int PACKET_HEADER_LENGTH = 4;
    private static final byte FIELD_COUNT = 1;

    public byte[] execute() {
        List<String> errorFiles = retrieveErrorFiles(new File(ERROR_FILE_DIR));
        return constructResultSet(errorFiles);
    }

    private List<String> retrieveErrorFiles(File directory) {
        List<String> errorFiles = new ArrayList<>();
        if (directory == null || !directory.exists()) {
            return errorFiles;
        }

        File[] files = directory.listFiles();
        if (files == null) {
            return errorFiles;
        }

        for (File file : files) {
            if (file.isDirectory()) {
                errorFiles.addAll(retrieveErrorFiles(file));
            } else if (isValidErrorFile(file)) {
                errorFiles.add(file.getAbsolutePath());
            }
        }

        return errorFiles;
    }

    private boolean isValidErrorFile(File file) {
        return file.getName().endsWith(".err") &&
               file.length() > 0 &&
               file.canRead();
    }

    private byte[] constructResultSet(List<String> errorFiles) {
        int packetSize = calculatePacketSize(errorFiles);
        ByteBuffer buffer = ByteBuffer.allocate(packetSize);

        // Write result set header packet
        writeResultSetHeaderPacket(buffer, errorFiles.size());

        // Write column definition packets
        writeColumnDefinitionPacket(buffer);

        // Write row data packets
        writeRowDataPackets(buffer, errorFiles);

        return buffer.array();
    }

    private void writeResultSetHeaderPacket(ByteBuffer buffer, int rowCount) {
        buffer.put((byte) 1);  // Packet sequence
        buffer.putInt(rowCount);  // Number of columns
        buffer.put(FIELD_COUNT);  // Column count
    }

    private void writeColumnDefinitionPacket(ByteBuffer buffer) {
        String columnName = "Error File Path";
        byte[] columnBytes = columnName.getBytes();

        buffer.put((byte) 3);  // Packet sequence
        buffer.putInt(columnBytes.length);
        buffer.put(columnBytes);
    }

    private void writeRowDataPackets(ByteBuffer buffer, List<String> errorFiles) {
        int packetSequence = 4;
        for (String filePath : errorFiles) {
            byte[] pathBytes = filePath.getBytes();

            buffer.put((byte) packetSequence);

