    HttpClient client = new DefaultHttpClient();

    // create a POST request and add the parameters
    HttpPost post = new HttpPost(request.getUrl());
    List<NameValuePair> form = new ArrayList<>();
    for (Map.Entry<String, String> entry : params.entrySet()) {
        form.add(new BasicNameValuePair(entry.getKey(), entry.getValue()));
    }
    UrlEncodedFormEntity entity = new UrlEncodedFormEntity(form, "UTF-8");
    post.setEntity(entity);

    // set headers
    post.setHeader("Accept", "application/json");
    post.setHeader("Content-Type", "application/x-www-form-urlencoded");
    request.getHeaders().forEach(post::setHeader);

    // execute the request and get the response
    HttpResponse response = client.execute(post);
    HttpEntity httpEntity = response.getEntity();

    // parse the response into a JSONObject
    String json = EntityUtils.toString(httpEntity, "UTF-8");
    return new JSONObject(json);
}

public static long roundUpPow2(long a) {
        if (a <= 0) {
            return 1;
        } else if (a > 0x4000000000000000L) {
            throw new IllegalArgumentException("Rounding " + a + " to the next highest power of two would exceed the int range");
        } else {
            a--;
            a |= a >> 1;
            a |= a >> 2;
            a |= a >> 4;
            a |= a >> 8;
            a |= a >> 16;
            a |= a >> 32;
            a++;
            return a;
        }
    }

import com.google.common.base.Objects;

public class GroupKey {
    private String upperName;
    private String leftName;

    public GroupKey(String upperName) {
        this.upperName = upperName;
        this.leftName = upperName;
    }

    public GroupKey(String upperName, String leftName) {
        this.upperName = upperName;
        this.leftName = leftName;
    }

    public String getUpperName() {
        return upperName;
    }

    public String getLeftName() {
        return leftName;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        GroupKey groupKey = (GroupKey) o;

        if (leftName != null ? !leftName.equals(groupKey.leftName) : groupKey.leftName != null) return false;
        if (upperName != null ? !upperName.equals(groupKey.upperName) : groupKey.upperName != null) return false;

        return true;
    }

    @Override
    public int hashCode() {
        int result = upperName != null ? upperName.hashCode() : 0;
        result = 31 * result + (leftName != null ? leftName.hashCode() : 0);
        return result;
    }

    @Override
    public String toString() {
        return Objects.toStringHelper(this)
                .add("upperName", upperName)
                .add("leftName", leftName)
                .toString();
    }
}

