import java.util.Scanner;

public class BuildThePermutation {

    public static void main (String[] args) {

        Scanner sc = new Scanner(System.in);

        int t = sc.nextInt();

        int i = 0;

        while (i < t) {

            int n = sc.nextInt();

            int a = sc.nextInt();

            int b = sc.nextInt();

            if (Math.abs(a - b) > 1) {

                System.out.println(-1);

                i++;

                continue;

            }

            if (a + b + 2 > n) {

                System.out.println(-1);

                i++;

                continue;

            }

            int[] p = new int[n];

            if (a > b) {

                int cur = n;

                for (int j = 1,count = 0; count < a;j += 2, count++) {

                    p[j] = cur;

                    cur--;

                }

                int r = cur;

                cur = 1;

                for (int j = 2,count = 0; count < b; j += 2, count++) {

                    p[j] = cur;

                    cur++;

                }

                p[0] = r--;

                for (int j = a + b + 1; j < n; j++) p[j] = r--;

            } else if (a < b) {

                int cur = 1;

                for (int j = 1, count = 0; count < b; count++, j += 2) {

                    p[j] = cur;

                    cur++;

                }

                int l = cur;

                cur = n;

                for (int j = 2, count = 0; count < a; count++, j += 2) {

                    p[j] = cur;

                    cur--;

                }

                p[0] = l++;

                for (int j = a + b + 1; j < n; j++) {

                    p[j] = l++;

                }

            } else {

                int cur = n;

                for (int j = 1, count = 0; count < a; count++, j += 2) {

                    p[j] = cur;

                    cur--;

                }

                cur = 1;

                for (int j = 2, count = 0; count < b; count++, j += 2) {

                    p[j] = cur;

                    cur++;

                }

                int left = cur;

                p[0] = left++;

                for (int j = a + b + 1; j < n; j++) {

                    p[j] = left++;

                }

            }

            for (int j = 0; j < n; j++) {

                if (j == n - 1) {

                    System.out.println(p[j]);

                    break;

                }

                System.out.print(p[j] + " ");

            }

            i++;

        }

    }

}

public class Generator {

    private int ans = 0;
    private int[] temp = new int[50010];

    public int reversePairs(int[] nums) {

        ans = 0;
        merge(nums , 0 , nums.length - 1);
        return ans;

    }

    private void merge(int[] nums , int left , int right) {

        if (left < right) {

            int mid = (left + right) / 2;
            merge(nums , left , mid);
            merge(nums , mid + 1 , right);

            int i;
            for (i = left;i <= mid;i ++) {
                int need = 0;
                if (nums[i] > 0) {
                    need = nums[i] / 2;
                    if (nums[i] % 2 == 0)
                        need --;
                } else if (nums[i] < 0) {
                    need = nums[i] / 2 - 1;
                } else {
                    need = - 1;
                }

                // 找nums[mid + 1] nums[right]里面小于等于need的个数
                ans += solve(nums , mid + 1 , right , need);
            }

            int pos1 = left , pos2 = mid + 1 , next = left;
            while (pos1 <= mid && pos2 <= right) {
                if (nums[pos1] <= nums[pos2]) {
                    temp[next ++] = nums[pos1 ++];
                } else {
                    temp[next ++] = nums[pos2 ++];
                }
            }
            while (pos1 <= mid) {
                temp[next ++] = nums[pos1 ++];
            }
            while (pos2 <= right) {
                temp[next ++] = nums[pos2 ++];
            }
            for (i = left;i <= right;i ++)
                nums[i] = temp[i];

        }

    }

    private int solve(int[] nums , int low , int high , int need) {

        int left = low , right = high + 1;
        while (left < right) {
            int mid = (left + right) / 2;
            if (nums[mid] <= need)
                left = mid + 1;
            else
                right = mid;
        }
        return right - low;

    }

}

