public class VariableCheckFunctionDecorator<X extends Field<X>> extends DifferentialFunction<X> {

    private final DifferentialFunction<X> function;
    private final Map<DifferentialFunction<X>, Set<DifferentialFunctionPredicateChecker>> variableCheckerMap;

    public VariableCheckFunctionDecorator(DifferentialFunction<X> function) {
        this.function = function;
        this.variableCheckerMap = new HashMap<>();
    }

    public void addArgTest(DifferentialFunction<X> v, Predicate<DifferentialFunction<X>> predicate,
                           String error) {
        variableCheckerMap.computeIfAbsent(v, k -> new HashSet<>())
                .add(new DifferentialFunctionPredicateChecker(predicate, error));
    }

    @Override
    public X getValue() {
        checkVariables();
        return function.getValue();
    }

    @Override
    public double getReal() {
        checkVariables();
        return function.getReal();
    }

    @Override
    public DifferentialFunction<X> diff(Variable<X> v) {
        checkVariables();
        DifferentialFunction<X> df = function.diff(v);

        VariableCheckFunctionDecorator<X> decorator = new VariableCheckFunctionDecorator<>(df);
        if (this.variableCheckerMap.containsKey(v)) {
            decorator.variableCheckerMap.putAll(this.variableCheckerMap);
        }
        return decorator;
    }

    private void checkVariables() {
        List<DifferentialFunction<X>> vars = function.getVariables();
        for (DifferentialFunction<X> var : vars) {
            checkVariable(var);
        }
    }

    private void checkVariable(DifferentialFunction<X> var) {
        Set<DifferentialFunctionPredicateChecker> checkers = variableCheckerMap.get(var);
        if (checkers != null) {
            for (DifferentialFunctionPredicateChecker checker : checkers) {
                if (!checker.predicate.test(var)) {
                    throw new IllegalArgumentException(checker.error);
                }
            }
        }
    }

    @Override
    public String toString() {
        return function.toString();
    }

    @Override
    public List<DifferentialFunction<X>> getChildren() {
        return this.function.getChildren();
    }

    private static class DifferentialFunctionPredicateChecker {
        Predicate<DifferentialFunction<?>> predicate;
        String error;

        DifferentialFunctionPredicateChecker(Predicate<DifferentialFunction<?>> predicate, String error) {

