        // They are a combination of flood fill method with a plane wave on a 3d array
        // So, this one can be done in 3 minutes

        public IList<IList<int>> FloodFill(int[][] image, int sr, int sc, int newColor)
        {
            int w = image.Length;
            int h = image[0].Length;

            var visited = new bool[w, h];
            var oldColor = image[sr][sc];

            var directions = new (int r, int c)[]
            {
                (0, 1),
                (1, 0),
                (-1, 0),
                (0,-1)
            };

            Func<int, int, int, int> dfs = (i, j, c) =>
            {
                if (i < 0 || j < 0 || i == w || j == h) return;
                if (image[i][j] != oldColor) return;
                image[i][j] = newColor;
                visited[i][j] = true;
                foreach (var (dx, dy) in directions) dfs(i + dx, j + dy, newColor);
            };

            visited[sr][sc] = true;
            dfs(sr, sc,  newColor);

            return image;
        }

    }
}

import java.io.BufferedReader;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class RemoveText {

    public static void main(String[] args) throws IOException {
        if (args.length != 2) {
            System.err.println("Usage: java RemoveText <string> <filename>");
            System.exit(1);
        }
        String stringToRemove = args[0];
        String filename = args[1];
        File inputFile = new File(filename);
        File outputFile = new File(inputFile.getParentFile(), "temp.txt");
        BufferedReader reader = new BufferedReader(new FileReader(inputFile));
        FileWriter writer = new FileWriter(outputFile);
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.replaceAll(stringToRemove, "");
            writer.write(line + System.lineSeparator());
        }
        reader.close();
        writer.close();
        inputFile.delete();
        outputFile.renameTo(inputFile);
    }
}

