            try {
                Class.forName("javax.xml.xpath.XPathFactory");
                return new StandardXPathEvaluator();
            } catch (ClassNotFoundException standardXPathNotFound) {
                try {
                    Class.forName("org.apache.xpath.XPathAPI");
                    return new XalanXPathEvaluator();
                } catch (ClassNotFoundException xalanNotFound) {
                    return new NoOpXPathEvaluator();
                }
            }
        }
    }

