public class Timer {

    static int daysElapsedCurrentYear;
    static int getDaysElapsedCurrentMonth;

    public static void main(String[] args) {
        String time = getCurrentTime(System.currentTimeMillis());
        String date = getCurrentDate(System.currentTimeMillis());
        System.out.println("The current date is " + date + ". And the current time is " + time);
    }

    public static String getCurrentDate(long millis) {
        long seconds = millis / 1000;
        long min = seconds / 60;
        long hours = min / 60;
        long days = hours / 24;
        int year = getYear((int) days);
        int month = getCurrentMonth(year, daysElapsedCurrentYear);
        return month + "/" + getDaysElapsedCurrentMonth + "/" + year;
    }

    private static String getCurrentTime(long millis) {
        long seconds = millis / 1000;
        long currentSecond = seconds % 60;

        long min = seconds / 60;
        long currentMin = min % 60;

        long hours = min / 60;
        long currentHour = hours % 24;

        return currentHour + ":" + currentMin + ":" + currentSecond + "(GMT)";

    }

    public static int getYear(int totalDays) {
        int year = 1970;
        while (totalDays > 365) {
            totalDays -= numberOfDaysInAYear(year);
            year++;
            daysElapsedCurrentYear = totalDays;
        }
        return year;
    }

    public static int numberOfDaysInAYear(int year) {
        return isLeapYear(year) ? 366 : 365;
    }

    static boolean isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    public static int getCurrentMonth(int year, int daysElapsedInYear) {
        int month = 0;
        while (daysElapsedInYear > 0) {
            month++;
            getDaysElapsedCurrentMonth = daysElapsedInYear;
            daysElapsedInYear -= getNumberOfDaysInMonth(year, month);

        }
        return month;

    }

    public static int getNumberOfDaysInMonth(int year, int month) {
        if (month == 1 || month == 3 || month == 5 || month == 7 ||
                month == 8 || month == 10 || month == 12)
            return 31;
        if (month == 4 || month == 6 || month == 9 || month == 11)
            return 30;
        if (month == 2) return isLeapYear(year) ? 29 : 28;

        return 0;
    }
}

import java.math.BigInteger;
 
class MersenneFactorCheck
{
 
  private final static BigInteger TWO = BigInteger.valueOf(2);
 
  public static boolean isPrime(long n)
  {
    if (n == 2)
      return true;
    if ((n < 2) || ((n & 1) == 0))
      return false;
    long maxFactor = (long)Math.sqrt((double)n);
    for (long possibleFactor = 3; possibleFactor <= maxFactor; possibleFactor += 2)
      if ((n % possibleFactor) == 0)
        return false;
    return true;
  }
 
  public static BigInteger findFactorMersenneNumber(int primeP)
  {
    if (primeP <= 0)
      throw new IllegalArgumentException();
    BigInteger bigP = BigInteger.valueOf(primeP);
    BigInteger m = BigInteger.ONE.shiftLeft(primeP).subtract(BigInteger.ONE);
    // There are more complicated ways of getting closer to sqrt(), but not that important here, so go with simple
    BigInteger maxFactor = BigInteger.ONE.shiftLeft((primeP + 1) >>> 1);
    BigInteger twoP = BigInteger.valueOf(primeP << 1);
    BigInteger possibleFactor = BigInteger.ONE;
    int possibleFactorBits12 = 0;
    int twoPBits12 = primeP & 3;
 
    while ((possibleFactor = possibleFactor.add(twoP)).compareTo(maxFactor) <= 0)
    {
      possibleFactorBits12 = (possibleFactorBits12 + twoPBits12) & 3;
      // "Furthermore, q must be 1 or 7 mod 8". We know it's odd due to the +1 done above, so bit 0 is set. Therefore, we only care about bits 1 and 2 equaling 00 or 11
      if ((possibleFactorBits12 == 0) || (possibleFactorBits12 == 3))
        if (TWO.modPow(bigP, possibleFactor).equals(BigInteger.ONE))
          return possibleFactor;
    }
    return null;
  }
 
  public static void checkMersenneNumber(int p)
  {
    if (!isPrime(p))
    {
      System.out.println("M" + p + " is not prime");
      return;
    }
    BigInteger factor = findFactorMersenneNumber(p);
    if (factor == null)
      System.out.println("M" + p + " is prime");
    else
      System.out.println("M" + p + " is not prime, has factor " + factor);
    return;
  }
 
  public static void main(String[] args)
  {
    for (int p = 1; p <= 50; p++)
      checkMersenneNumber(p);
    checkMersenneNumber(929);
    return;
  }
 
}

import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

import com.google.common.collect.ImmutableList;

public abstract class ConfigSection<T extends ConfigValue> {

    public enum MergeStrategy {
        REPLACE,
        APPEND
    }

    private T configValue;
    private final String name;
    private final MergeStrategy mergeStrategy;

    public ConfigSection(String name, T configValue, MergeStrategy mergeStrategy) {
        this.name = name;
        this.configValue = configValue;
        this.mergeStrategy = mergeStrategy;
    }

    public abstract ShellCommands toScript(Combination combination, BuildType buildType);

    public void merge(ConfigSection<T> other) {
        if (other == null || other.configValue == null) {
            return;
        }

        if (this.mergeStrategy == MergeStrategy.REPLACE) {
            this.configValue = other.configValue;
        } else if (this.mergeStrategy == MergeStrategy.APPEND) {
            if (this.configValue != null) {
                this.configValue.append(other.configValue);
            } else {
                this.configValue = other.configValue;
            }
        }
    }

    public T getConfigValue() {
        return configValue;
    }

    public void setConfigValue(T configValue) {
        this.configValue = configValue;
    }

    public String getName() {
        return name;
    }

    public boolean isValid() {
        return getValidationErrors().isEmpty();
    }

    public List<String> getValidationErrors() {
        if (configValue == null) {
            return ImmutableList.of();
        }
        return configValue.validate();
    }

    public T getFinalConfigValue() {
        return configValue;
    }

    public boolean isSpecified() {
        return this.configValue != null && this.configValue.isSpecified();
    }
}

