protected void flushBuffer(boolean commandEnd) throws IOException {
    if (pos > 4) {
      buf[0] = (byte) (pos - 4);
      buf[1] = (byte) ((pos - 4) >>> 8);
      buf[2] = (byte) ((pos - 4) >>> 16);
      buf[3] = (byte) this.seqNo++;
      checkMaxAllowedLength(pos - 4);
      out.write(buf, 0, pos);
      cmdLength += pos - 4;
      if (traceCache != null && permitTrace) {

        traceCache.put(new TraceObject(true, NOT_COMPRESSED,
            Arrays.copyOfRange(buf, 0, pos > 1000 ? 1000 : pos)));
      }
      if (logger.isTraceEnabled()) {
        if (permitTrace) {
          logger.trace("send: {}{}",
              serverThreadLog,
              Utils.hexdump(maxQuerySizeToLog, 0, pos, buf));
        } else {
          logger.trace("send: content length={} {} com=<hidden>",
              pos - 4,
              serverThreadLog);
        }
      }

      if (commandEnd && pos == MAX_PACKET_LENGTH) {
        writeEmptyPacket();
      }
      pos = 4;
    }
  }

public Iterable<DConnections> queryByProfileUrl(String profileUrl) {
    List<DConnections> result = new ArrayList<>();
    // assume connectionsList is a List<DConnections> containing all connections
    for (DConnections conn : connectionsList) {
        if (conn.getProfileUrl().equals(profileUrl)) {
            result.add(conn);
        }
    }
    return result;
}

