protected Response request (String req)
        throws IOException
    {
        System.err.println("REQ:" + req);

        _out.println(req);
        _out.flush();

        String rspstr = _in.readLine();

        if (rspstr == null) {
            throw new EOFException();
        }
        System.err.println("RSP:" + rspstr);

        Response rsp = new Response();
        String codestr = rspstr;

        int sidx = rspstr.indexOf(" ");
        if (sidx != -1) {
            codestr = rspstr.substring(0, sidx);
            rsp.message = rspstr.substring(sidx+1);
        }
        try {
            rsp.code = Integer.parseInt(codestr);
        } catch (NumberFormatException nfe) {
            rsp.code = 599;
            rsp.message = "Unparseable response";
        }
        return rsp;
    }

import java.util.*;

public class CyclicShiftsSorting {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int testCase = 0; testCase < t; testCase++) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }
            List<Integer> operations = new ArrayList<>();
            if (canSortArray(a, operations)) {
                System.out.println(operations.size());
                for (int op : operations) {
                    System.out.print(op + " ");
                }
                System.out.println();
            } else {
                System.out.println(-1);
            }
        }
    }

    private static boolean canSortArray(int[] a, List<Integer> operations) {
        int n = a.length;
        int[] sorted = a.clone();
        Arrays.sort(sorted);
        if (sorted[0] != a[0] || sorted[n - 1] != a[n - 1]) {
            return false;
        }
        for (int i = 1; i < n - 1; ) {
            if (a[i] > a[i + 1]) {
                operations.add(i);
                int temp = a[i];
                a[i] = a[i + 2];
                a[i + 2] = a[i + 1];
                a[i + 1] = temp;
                if (Arrays.equals(a, sorted)) {
                    return true;
                }
            } else {
                i++;
            }
        }
        return Arrays.equals(a, sorted);
    }
}

import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.input.KeyCode;
import javafx.scene.layout.Pane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Circle;
import javafx.stage.Stage;

public class Writer extends javafx.application.Application {
    double x = 300;
    double y = 200;
    double moveText = 150;
    String nuString = "";
    boolean alternate = true;

    @Override
    public void start(Stage primaryStage) throws Exception {
        Pane pane = new Pane();
        Canvas canvas = new Canvas(600, 400);
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.moveTo(x, y);
        gc.setFill(Color.BLACK);
        pane.getChildren().add(canvas);
        Scene scene = new Scene(pane, 600, 400);

        scene.setOnKeyPressed(event -> {
            if (event.getCode() == KeyCode.ENTER) {
                if (alternate) {
                    alternate = false;
                    gc.strokeText(nuString, (x + Math.random() * moveText), (y + Math.random() * moveText));
                } else {
                    gc.strokeText(nuString, (x + Math.random() * -moveText), (y + Math.random() * -moveText));
                }
                nuString = "";
            } else {
                nuString += event.getText();
            }
        });

        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

