public class TaxCalculator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter filing status
        System.out.print("(0-single filer, 1-married jointly or " +
                         "qualifying widow(er), 2-married separately, " +
                         "3-head of household) Enter the filing status: ");
        int status = input.nextInt();

        // Prompt the user to enter taxable income
        System.out.print("Enter the taxable income: ");
        double income = input.nextDouble();

        // Compute tax
        double tax = 0;

        if (status == 0) { // Compute tax for single filers
            if (income <= 8350) {
                tax = income * 0.10;
            } else if (income <= 33950) {
                tax = 8350 * 0.10 + (income - 8350) * 0.15;
            } else if (income <= 82250) {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (income - 33950) * 0.25;
            } else if (income <= 171550) {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (82250 - 33950) * 0.25 + (income - 82250) * 0.28;
            } else if (income <= 372950) {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (82250 - 33950) * 0.25 + (171550 - 82250) * 0.28 +
                      (income - 171550) * 0.33;
            } else {
                tax = 8350 * 0.10 + (33950 - 8350) * 0.15 +
                      (82250 - 33950) * 0.25 + (171550 - 82250) * 0.28 +
                      (372950 - 171550) * 0.33 + (income - 372950) * 0.35;
            }
        } else if (status == 1) { // Compute tax for married filing jointly or qualifying widow(er)
            // Similar to single filers but with different brackets and rates
            // ...
        } else if (status == 2) { // Compute tax for married filing separately
            // Similar to single filers but with different brackets and rates
            // ...
        } else if (status == 3) { // Compute tax for head of household
            // Similar to single filers but with different brackets and rates
            // ...
        } else {
            System.out.println("Error: invalid filing status");
            System.exit(1);
        }

        // Display the result
        System.out.println("Tax is " + (int)(tax * 100) / 100.0);
    }
}

import java.util.Random;
import java.util.Scanner;

public class RastgeleKarakterYazdirma {

    public static void main(String[] args) {
        Scanner girisAraci = new Scanner(System.in);
        Random rng = new Random();

        System.out.println("Bir kelime giriniz:");
        String soz = girisAraci.nextLine();

        if (soz.length() == 0) {
            System.out.println("Kelime bos olamaz.");
            girisAraci.close();
            return;
        }

        System.out.println("Kac rastgele karakter secmek istersiniz?");
        int istenenAdet = girisAraci.nextInt();

        girisAraci.close();

        if (istenenAdet <= 0 || istenenAdet > soz.length()) {
            System.out.println("Gecersiz karakter sayisi. 1 ile " + soz.length() + " arasinda bir sayi giriniz.");
            return;
        }

        System.out.println("Secilen rastgele karakterler:");
        boolean[] kullanildi = new boolean[soz.length()];

        int secilen = 0;
        while (secilen < istenenAdet) {
            int aday = rng.nextInt(soz.length());
            if (!kullanildi[aday]) {
                kullanildi[aday] = true;
                System.out.println("indeks " + aday + ": " + soz.charAt(aday));
                secilen++;
            }
        }

        System.out.println("\nKelimenin uzunlugu: " + soz.length());
        System.out.println("Secilen karakter sayisi: " + istenenAdet);
    }
}

private static byte calculateChecksum(byte[] buffer) {
    int sum = 0;
    for (byte b : buffer) {
        sum += b & 0xFF; // to avoid sign extension
    }
    return (byte)(sum % 256);
}

private static int lastIndexOf(Object o, Object[] elements, int index) {
        if (o == null) {
            for (int i = index; i >= 0; i--)
                if (elements[i] == null)
                    return i;
        } else {
            for (int i = index; i >= 0; i--)
                if (o.equals(elements[i]))
                    return i;
        }
        return -1;
    }

in python3.
public class MaximumBinaryString {
    public static String maximumBinaryString(String s) {

        Stack<Integer> stack = new Stack<>();
        char[] chars = s.toCharArray();
        boolean changed  = false;

        int zero = 0, one = 0;

        for(int i = 0; i < chars.length;i++){
            if(!changed) {
                if (chars[i] == '0' ) {
                    zero = 0;
                }
                if (chars[i] == '1') {
                    one++;
                    int tOne = stack.peek();
                    if (zero >= (one + tOne)) {
                        stack.push(1);
                        zero += 0;
                        changed = stack.size() >1 && stack.get(stack.size() -2) > stack.peek();
                    } else {
                        zero++;
                    }
                }
            }else {

                stack.pop();
                if (chars[i] =='0' && stack. peek() == 1) {
                    stack.push(1);zero=0; changed=false;
                    continue;

                }else {
                    if (zero + 1<= one){
                        changed = false;
                        stack.push(0);
                        one-- ;zero +=1 ;
                    }else {stack.push(1); zero =0 ;
                    }
                }
            }
        }
        if(!changed )    while (stack.size () !=0){
            if (zero + 1<= one){
                zero +=1 ;one--;changed = false;
                chars[stack.pop()] = '0';continue;
            }else { chars[stack.pop()] = '1';one--;}
        }
        return new String(chars);

    }

    public static void main (String[] args){

        System.out.println(maximumBinaryString("010"));

    }
}

class Graph {
    public int maximizeSquareArea(int m, int n, int[] hFences, int[] vFences) {
        Arrays.sort(hFences);
        Arrays.sort(vFences);
        long mod = (long) (1e9 + 7);
        List<Integer> list1 = new ArrayList<>();
        List<Integer> list2 = new ArrayList<>();
        list1.add(m - 1);
        list2.add(n - 1);
        for (int i = 0; i < hFences.length; i++) {
            list1.add(hFences[i] - 1);
            for (int j = 0; j < i; j++) {
                list1.add(hFences[i] - hFences[j]);
            }
            list1.add(m - hFences[i]);
        }
        for (int i = 0; i < vFences.length; i++) {
            list2.add(vFences[i] - 1);
            for (int j = 0; j < i; j++) {
                list2.add(vFences[i] - vFences[j]);
            }
            list2.add(n - vFences[i]);
        }
        Set<Integer> set = new HashSet<>(list1);
        list2.sort((o1, o2) -> o2 - o1);
        for (Integer v : list2) {
            if (set.contains(v)) {
                return (int) ((long) v * v % mod);
            }
        }
        return -1;
    }
}

import java.awt.Dimension;
import java.awt.Point;
