/**
 * Problem 10.1 CTCI Sorted Merge
 *
 * You are given two sorted arrays, a and b, where a has a large enough buffer at the end to hold
 * b. Write a method to merge b into a in sorted order.
 *
 * Examples:
 *
 *    a: 2, 7, 22, 44, 56, 88, 456, 5589
 *    b: 1, 4, 9, 23, 99, 1200
 *
 * Result:
 *
 *    result: 1, 2, 4, 7, 9, 22, 23, 44, 56, 88, 99, 456, 1200, 5589
 *
 * Analysis:
 *
 *    The merge is probably most effective if the values are inserted into the buffer starting with
 *    the end of the input arrays.
 *
 *    a == a0, a1, a2, ..., ai, ... an   i.e. i is range 0..n
 *    b == b0, b1, b2, ..., bj, ... bm   i.e. j is range 0..m
 *
 * Algorithm:
 *
 * 1) Starting at the end of the arrays, compare (a, b) each descending element and place the larger
 * at the end of the result array (a).  If the values are identical, put both elements into the
 * result.
 *
 * 2) Decrement the running index for each array contributing to the result on this iteration.
 *
 * 3) Repeat until the b running index (j) is 0 (all of b have been added to a).
 *
 * i = n;
 * j = m;
 * while j >= 0 do
 *     if i < 0
 *     then
 *         a[j] = b[j]
 *     else if a[i] > b[j]
 *     then
 *         a[i+j+1] = a[i--]
 *     else if b[j] > a[i]
 *         a[i+j] = b[j--]
 *     else
 *         a[i+j] = b[j--]
 *         a[i+j] = a[i--]
 */

import java.util.Arrays;
import java.util.Locale;

public class Employee {

    /** Run the program using the command line arguments. */
    public static void main(String[] args) {
        // Define a and b.
        int[] a = new int[]{2, 7, 22, 44, 56, 88, 456, 5589};
        int[] b = new int[]{1, 4, 9, 23, 99, 1200};
        int[] result = smerge(a, b);
        String format = "Result: %s";
        System.out.println(String.format(Locale.US, format, Arrays.toString(result)));
    }

    /** Return the given value in the given base. */
    private static int[] smerge(final int[] a, final int[] b) {
        final int N = a.length;
        final int M = b.length;
        int [] result = new int[N + M];
        System.arraycopy(a, 0, result, 0, N);
        int i = N - 1;
        int j = M - 1;
        while (j >= 0) {
            if (i < 0)
                result[j] = b[j--];
            else if (a[i] > b[j])
                result[i + j + 1] = a[i--];
            else if (b[j] > a[i])
                result[i + j + 1] = b[j--];
            else {
                result[i + j + 1] = a[i--];
                result[i + j + 1] = b[j--];
            }
        }
        return result;
    }
}

import java.math.BigDecimal;
import java.math.BigInteger;
import java.math.MathContext;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
 
public class EgyptianFractions {
    private static BigInteger gcd(BigInteger a, BigInteger b) {
        if (b.equals(BigInteger.ZERO)) {
            return a;
        }
        return gcd(b, a.mod(b));
    }
 
    private static class Frac implements Comparable<Frac> {
        private BigInteger num, denom;
 
        public Frac(BigInteger n, BigInteger d) {
            if (d.equals(BigInteger.ZERO)) {
                throw new IllegalArgumentException("Parameter d may not be zero.");
            }
 
            BigInteger nn = n;
            BigInteger dd = d;
            if (nn.equals(BigInteger.ZERO)) {
                dd = BigInteger.ONE;
            } else if (dd.compareTo(BigInteger.ZERO) < 0) {
                nn = nn.negate();
                dd = dd.negate();
            }
            BigInteger g = gcd(nn, dd).abs();
            if (g.compareTo(BigInteger.ZERO) > 0) {
                nn = nn.divide(g);
                dd = dd.divide(g);
            }
            num = nn;
            denom = dd;
        }
 
        public Frac(int n, int d) {
            this(BigInteger.valueOf(n), BigInteger.valueOf(d));
        }
 
        public Frac plus(Frac rhs) {
            return new Frac(
                num.multiply(rhs.denom).add(denom.multiply(rhs.num)),
                rhs.denom.multiply(denom)
            );
        }
 
        public Frac unaryMinus() {
            return new Frac(num.negate(), denom);
        }
 
        public Frac minus(Frac rhs) {
            return plus(rhs.unaryMinus());
        }
 
        @Override
        public int compareTo(Frac rhs) {
            BigDecimal diff = this.toBigDecimal().subtract(rhs.toBigDecimal());
            if (diff.compareTo(BigDecimal.ZERO) < 0) {
                return -1;
            }
            if (BigDecimal.ZERO.compareTo(diff) < 0) {
                return 1;
            }
            return 0;
        }
 
        @Override
        public boolean equals(Object obj) {
            if (null == obj || !(obj instanceof Frac)) {
                return false;
            }
            Frac rhs = (Frac) obj;
            return compareTo(rhs) == 0;
        }
 
        @Override
        public String toString() {
            if (denom.equals(BigInteger.ONE)) {
                return num.toString();
            }
            return String.format("%s/%s", num, denom);
        }
 
