class Graph {
    public int mostFrequentEven(int[] nums) {
        TreeMap<Integer, Integer> cm = new TreeMap<>();
    for (int v : nums) {
      if (v % 2 == 0) {
        cm.put(v, cm.getOrDefault(v, 0) + 1);
      }
    }
    int maxc = -1;
    int maxv = -1;
    for (Map.Entry<Integer, Integer> e : cm.entrySet()) {
      if (e.getValue() > maxc) {
        maxc = e.getValue();
        maxv = e.getKey();
      }
    }
    return maxv;
    }
}

