public final class MyString2 {
    char[] chars;

    public MyString2(String s) {
        this.chars = s.toCharArray();
    }

    public int compare(String s) {
        int currObjTotal = 0;
        int sTotal = 0;
        if (this.chars.length != s.length()) {
            int commonLength = 0;
            for (int i = 0; i < chars.length && i < s.length(); i++) {
                commonLength = i;
            }
            return this.chars[commonLength] - s.charAt(commonLength);

        }
        for (int i = 0; i < s.length(); i++) {
            currObjTotal += chars[i];
            sTotal += s.charAt(i);
        }
        return currObjTotal - sTotal;
    }

    public MyString2 substring(int begin) {
        String s = "";
        for (int i = begin; i < chars.length; i++) {
            s += chars[i];
        }
        return new MyString2(s);

    }

    public MyString2 toUpperCase() {
        char[] chs = new char[chars.length];
        for (int i = 0; i < chars.length; i++) {
            chs[i] = Character.toUpperCase(chars[i]);
        }
        return new MyString2(String.copyValueOf(chs));
    }

    public char[] toChars() {
        return chars;
    }

    public static MyString2 valueOf(boolean b) {
        return b ? new MyString2("true") : new MyString2("false");
    }

}

import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.util.Collection;
import org.hibernate.HibernateException;
import org.hibernate.engine.spi.SharedSessionContractImplementor;
import org.hibernate.type.Type;

public class DynamicFilterParameterSpecification {

    private final String filterName;
    private final String parameterName;
    private Type definedParameterType;

    public DynamicFilterParameterSpecification(String filterName, String parameterName) {
        this.filterName = filterName;
        this.parameterName = parameterName;
    }

    public void bind(
            PreparedStatement preparedStatement,
            SharedSessionContractImplementor session,
            int position) throws SQLException {

        Object value = session.getLoadQueryInfluencers().getFilterParameterValue(filterName, parameterName);

        if (value instanceof Collection) {
            Collection<?> collection = (Collection<?>) value;
            int i = position;
            for (Object element : collection) {
                try {
                    definedParameterType.nullSafeSet(preparedStatement, element, i, session);
                } catch (HibernateException he) {
                    throw new SQLException("Error setting filter parameter", he);
                }
                i++;
            }
        } else {
            try {
                definedParameterType.nullSafeSet(preparedStatement, value, position, session);
            } catch (HibernateException he) {
                throw new SQLException("Error setting filter parameter", he);
            }
        }
    }

    public Type getExpectedType() {
        return definedParameterType;
    }

    public void setExpectedType(Type definedParameterType) {
        this.definedParameterType = definedParameterType;
    }

    public String renderDisplayInfo() {
        return "filter=" + filterName + ", parameter=" + parameterName + ", type=" + definedParameterType;
    }
}

