                    return;
                } else {
                    int pos = arg.indexOf('=');
                    if(pos == -1) throw new ArgumentException(s);
                    String argument = arg.substring(0, pos);
                    String value = arg.substring(pos+1);
                    switch(argument) {
                        case "graph" :
                            arguments.put(argument, value);
                            break;
                        case "limit" :
                            arguments.put(argument, Long.valueOf(value));
                            break;
                        case "method" :
                            arguments.put(argument, Integer.valueOf(value));
                            break;
                        case "show" :
                            arguments.put(argument, value);
                            break;
                        default:
                            throw new ArgumentException(argument);
                    }
                }
            } else throw new ArgumentException(s);
        }
        computeMap(arguments);
    }

    private void computeMap(Map<String, Object> M) {
        if(M.get("graph") != null)
            graph = (String) M.get("graph");

        if(M.get("limit") != null)
            limit = (Long) M.get("limit");

        if(M.get("method") != null)
            method = (Integer) M.get("method");

        if(M.get("show") != null)
            show = (String) M.get("show");
    }

    public static void showValidArguments() {
        System.out.println("Usage : clique_issue -graph=<file to graph> -method=<method 0, 1, 2, 3> -limit=<limit time ms> -show=<all, stats, graph> ");
    }

    public static void showHelp() {
        System.out.println("-graph=<file to graph>  :   the file who contains the description of the graphe");

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.util.Log;

import com.achep.acdisplay.App;
import com.achep.acdisplay.Config;
import com.achep.acdisplay.R;
import com.achep.base.utils.ToastUtils;

/**
 */
public class ReceiverPublic extends BroadcastReceiver {

    private static final String TAG = "PublicReceiver";

    @Override
    public void onReceive(Context context, Intent intent) {
        Config config = Config.getInstance();
        String action = intent.getAction();
        switch (action) {
            case App.ACTION_ENABLE:
                Log.i(TAG, "Enabling AcDisplay by intent. " + intent);
                setAcDisplayEnabled(context, config, true);
                break;
            case App.ACTION_DISABLE:
                Log.i(TAG, "Disabling AcDisplay by intent. " + intent);
                setAcDisplayEnabled(context, config, false);
                break;
            case App.ACTION_TOGGLE:
                Log.i(TAG, "Toggling AcDisplay by intent. " + intent);
                setAcDisplayEnabled(context, config, !config.isEnabled());
                break;
        }
    }

    /**
     * Tries to {@link com.achep.acdisplay.Config#setEnabled(android.content.Context, boolean, com.achep.acdisplay.Config.OnConfigChangedListener) enable / disable }
     * AcDisplay and shows toast message about the result.
     *
     * @param enable {@code true} to enable AcDisplay, {@code false} to disable.
     */
    private void setAcDisplayEnabled(Context context, Config config, boolean enable) {
        enable &= App.getAccessManager().getMasterPermissions().isActive();
        config.setEnabled(context, enable, null);
        ToastUtils.showLong(context, enable
                ? R.string.remote_enable_acdisplay
                : R.string.remote_disable_acdisplay);
    }

}

import java.io.DataOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.Collection;
import java.util.IdentityHashMap;
import java.util.Map;

public class HPObjectOutputStream extends DataOutputStream {

    private final ObjectOutputStreamSupport support = new ObjectOutputStreamSupport();

    public HPObjectOutputStream(OutputStream out) {
        super(out);
    }

    public void writeObject(Object obj) throws IOException {
        if (obj == null) {
            writeBoolean(true); // Indicate null
            return;
        }
        writeBoolean(false); // Indicate not null

        Class<?> clazz = obj.getClass();
        String className = clazz.getName();
        writeUTF(className);

        try {
            if(obj instanceof Collection){
                Collection<?> collection = (Collection<?>) obj;
                writeInt(collection.size());
                for(Object item : collection){
                    writeObject(item);
                }
                return;
            }
            if(obj instanceof Map){
                Map<?,?> map = (Map<?,?>)obj;
                writeInt(map.size());
                for(Map.Entry<?,?> entry: map.entrySet()){
                    writeObject(entry.getKey());
                    writeObject(entry.getValue());
                }
                return;
            }

            Field[] fields = clazz.getDeclaredFields();
            for (Field field : fields) {
                if (Modifier.isTransient(field.getModifiers())) {
                  writeObject(null);
                  continue;
                }
                field.setAccessible(true);
                Object fieldValue = field.get(obj);
                writeObject(fieldValue);
            }
        } catch (IllegalAccessException e) {
            throw new IOException("Error writing object: " + e.getMessage());
        }
    }

    private static class ObjectOutputStreamSupport {
    }
}

import java.util.Scanner;

public class rref {
    public static void main(String[] args) {
        int[][] matrix = new int[3][4];
        matrix[0][0] = 1;
        matrix[0][1] = 2;
        matrix[0][2] = -1;
        matrix[0][3] = -4;
        matrix[1][0] = 2;
        matrix[1][1] = 3;
        matrix[1][2] = -1;
        matrix[1][3] = -11;
        matrix[2][0] = -2;
        matrix[2][1] = 0;
        matrix[2][2] = -3;
        matrix[2][3] = 22;
        matrix = rref(matrix);
    }

    private static int[][] rref(int[][] matrix) {
        int lead = 0, rowCount = matrix.length, columnCount = matrix[0].length;
        for (int r = 0; r < rowCount; r++) {
            if (columnCount <= lead) break;
            int i = r;
            while (matrix[i][lead] == 0) {
                i++;
                if (i == rowCount) {
                    i = r;
                    lead++;
                    if (columnCount == lead) {
                        lead--;
                        break;
                    }
                }
            }
            for (int j = 0; j < columnCount; j++) {
                int temp = matrix[r][j];
                matrix[r][j] = matrix[i][j];
                matrix[i][j] = temp;
            }
            int div = matrix[r][lead];
            if (div!= 0)
                for (int j = 0; j < columnCount; j++) matrix[r][j] /= div;
            for (int j = 0; j < rowCount; j++) {
                if (j!= r) {
                    int sub = matrix[j][lead];
                    for (int k = 0; k < columnCount; k++) matrix[j][k] -= (sub * matrix[r][k]);
                }
            }
            lead++;
        }
        return matrix;
    }
}

/**
 * Base class for {@link Operation} implementations.
 *
 * <p>As opposed to {@link Operation} itself, this class is package private and therefore its usage
 * is limited to internal purposes only.
 */
abstract class AbstractOperation implements Operation {

  @Override
  public Output<?>[] outputList(int idx, int length) {
    Output<?>[] outputs = new Output<?>[length];
    for (int i = 0; i < length; ++i) {
      outputs[i] = output(idx + i);
    }
    return outputs;
  }

  @Override
  @SuppressWarnings({"rawtypes", "unchecked"})
  public <T> Output<T> output(int idx) {
    return new Output(this, idx);
  }

  @Override
  public String toString() {
    return String.format("<%s '%s'>", type(), name());
  }

  /**
   * Returns the native handle of the {@code outputIdx}th output of this operation.
   *
   * <p>The nature of the returned value varies depending on current the execution environment.
   *
   * <ul>
   *   <li>In eager mode, the value is a handle to the tensor returned at this output.
   *   <li>In graph mode, the value is a handle to the operation itself, which should be paired with
   *       the index of the output when calling the native layer.
   * </ul>
   *
   * @param outputIdx index of the output in this operation
   * @return a native handle, see method description for more details
   */
  abstract long getUnsafeNativeHandle(int outputIdx);

  /**
   * Returns the shape of the tensor of the {@code outputIdx}th output of this operation.
   *
   * @param outputIdx index of the output of this operation
   * @return output tensor shape
   */
  abstract long[] shape(int outputIdx);

  /**
   * Returns the datatype of the tensor of the {@code outputIdx}th output of this operation.
   *
   * @param outputIdx index of the output of this operation
   * @return output tensor datatype
   */
  abstract DataType dtype(int outputIdx);

  /**
   * Returns the tensor of the {@code outputIdx}th output of this operation.
   *
   * <p>This is only supported in an eager execution environment.
   *
   * @param outputIdx index of the output of this operation
   * @return output tensor
   */
  abstract Tensor<?> tensor(int outputIdx);
}

import com.google.common.collect.ImmutableList;
import com.facebook.presto.spi.connector.ConnectorSplit;
import com.facebook.presto.spi.connector.ConnectorTableLayoutHandle;
import com.facebook.presto.spi.connector.Node;
import com.facebook.presto.spi.connector.NodeManager;

import java.util.List;
import java.util.stream.Collectors;

public class TpchSplitManager {
    private final String connectorId;
    private final NodeManager nodeManager;
    private final int splitsPerNode;

    public TpchSplitManager(String connectorId, NodeManager nodeManager, int splitsPerNode) {
        if (splitsPerNode <= 0) {
            throw new IllegalArgumentException("Splits per node must be greater than zero");
        }
        this.connectorId = connectorId;
        this.nodeManager = nodeManager;
        this.splitsPerNode = splitsPerNode;
    }

    public List<ConnectorSplit> getSplits(ConnectorTableLayoutHandle layoutHandle) {
        List<Node> activeNodes = getActiveNodes();
        int totalSplits = activeNodes.size() * splitsPerNode;

        return createSplits(activeNodes, totalSplits);
    }

    private List<Node> getActiveNodes() {
        return nodeManager.getNodes()
                .stream()
                .filter(Node::isAlive)
                .collect(Collectors.toList());
    }

    private List<ConnectorSplit> createSplits(List<Node> activeNodes, int totalSplits) {
        ImmutableList.Builder<ConnectorSplit> splitsBuilder = ImmutableList.builder();

        for (Node node : activeNodes) {
            for (int i = 0; i < splitsPerNode; i++) {
                splitsBuilder.add(createSplitForNode(node, i));
            }
        }

        return splitsBuilder.build();
    }

    private ConnectorSplit createSplitForNode(Node node, int index) {
        // Sample implementation; customize with actual split creation logic.
        return new ConnectorSplit(connectorId, node.getId(), index);
    }
}

