public static void addStatementToCollection(Statement statement, Collection<StatementGroup> claims) {
    for (StatementGroup group : claims) {
        if (group.getStatements().contains(statement)) {
            group.removeStatement(statement);
            break;
        }
    }
    claims.stream()
            .filter(group -> group.getProperty().equals(statement.getProperty()))
            .findFirst()
            .orElseGet(() -> {
                StatementGroup group = new StatementGroup(statement.getProperty());
                claims.add(group);
                return group;
            }).addStatement(statement);
}

