import java.util.Arrays;
import java.util.List;
 
public class SpellNumber {
 
    private static final String[] smallNumbers = {
        "zero", "one", "two", "three", "four", "five",
        "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve", "thirteen", "fourteen", "fifteen",
        "sixteen", "seventeen", "eighteen", "nineteen"
    };
 
    private static String spellHundreds(int n) {
        String res = "";
        if (n > 99) {
            res = smallNumbers[n/100];
            res += " hundred";
            n %= 100;
            if (n!= 0) res += " and ";
        }
        if (n >= 20) {
            static final String[] Decades = {
                "", "", "twenty", "thirty", "forty",
                "fifty", "sixty", "seventy", "eighty", "ninety"
            };
            res += Decades[n/10];
            n %= 10;
            if (n!= 0) res += "-";
        }
        if (n < 20 && n > 0)
            res += smallNumbers[n];
        return res;
    }
 
 
    private static final String[] thousandPowers = {
        " billion", " million",  " thousand", "" };
 
    private static String spell(long n) {
        if (n < 20) return smallNumbers[(int)n];
        String res = "";
        String[] pScaleName = thousandPowers;
        long scaleFactor = 1000000000;  // 1 billion
        while (scaleFactor > 0) {
            if (n >= scaleFactor) {
                long h = n / scaleFactor;
                res += spellHundreds((int)h) + pScaleName[0];
                n %= scaleFactor;
                if (n!= 0) res += ", ";
            }
            scaleFactor /= 1000;
            pScaleName = Arrays.copyOfRange(pScaleName, 1, pScaleName.length);
        }
        return res;
    }
 
    public static void main(String[] args) {
        System.out.println("99 " + spell(99));
        System.out.println("300 " + spell(300));
        System.out.println("310 " + spell(310));
        System.out.println("1501 " + spell(1501));
        System.out.println("12609 " + spell(12609));
        System.out.println("512609 " + spell(512609));
        System.out.println("43112609 " + spell(43112609));
        System.out.println("1234567890 " + spell(1234567890));
    }
}

protected static <K, V> HashTrieMap<K, V> makeHashTrieMap(int hash0, CompactHashMap<K, V> elem0, int hash1, CompactHashMap<K, V> elem1, int level, int size) {
    // Calculate the bit position to differentiate the hashes
    int bitpos0 = hash0 >>> level & 0x1f;
    int bitpos1 = hash1 >>> level & 0x1f;

    // If the bit positions are the same, we need to create a collision map
    if (bitpos0 == bitpos1) {
        return new HashTrieMap<>(hash0, new CompactHashMapCollision<>(elem0, elem1), level, size);
    }

    // Create an array to hold the child nodes
    HashTrieMap<K, V>[] nodes = new HashTrieMap[32];

    // Place the elements in the correct positions in the array
    nodes[bitpos0] = new HashTrieMap<>(hash0, elem0, level + 5, elem0.size());
    nodes[bitpos1] = new HashTrieMap<>(hash1, elem1, level + 5, elem1.size());

    // Return the new HashTrieMap
    return new HashTrieMap<>(hash0, nodes, level, size);
}

