import java.util.HashMap;
import java.util.Map;

public class DigitalRootBase {
    public static void main(String[] args) {
        System.out.println(digitalRootBase(123456789, 10));
    }

    public static Map<String, Integer> digitalRootBase(int x, int b) {
        if (x < b) {
            Map<String, Integer> map = new HashMap<>();
            map.put("addpers", 0);
            map.put("digrt", x);
            return map;
        }

        int fauxroot = 0;
        while (b <= x) {
            x = (x / b) | 0;
            fauxroot += x % b;
        }

        Map<String, Integer> rootobj = digitalRootBase(fauxroot, b);
        rootobj.put("addpers", rootobj.get("addpers") + 1);
        return rootobj;
    }
}

 
