public class Expression {
 
    private enum Op { ADD, SUB, JOIN }
    private final Op[] code = new Op[NUMBER_OF_DIGITS];
 
    static {
        for (int i = 0; i < NUMBER_OF_DIGITS; i++) code[i] = Op.ADD;
    }
 
    private static final int NUMBER_OF_DIGITS = 9;
    private static final int THREE_POW_4 = 3 * 3 * 3 * 3;
    private static final String FMT = "%9d";
    static final int NUMBER_OF_EXPRESSIONS = 2 * THREE_POW_4 * THREE_POW_4;
 
    public static void print(int givenSum) {
        Expression expression = new Expression();
        for (int i = 0; i < NUMBER_OF_EXPRESSIONS; i++) {
            if (expression.toInt() == givenSum) System.out.println(String.format(FMT, givenSum) + " = " + expression);
            expression.inc();
        }
    }
 
    public void inc() {
        for (int i = 0; i < code.length; i++) {
            code[i] = switch (code[i]) {
                case ADD  -> Op.SUB;
                case SUB  -> Op.JOIN;
                case JOIN -> Op.ADD;
            };
            if (code[i]!= Op.ADD) break;
        }
    }
 
    public int toInt() {
        int value = 0;
        int number = 0;
        int sign = +1;
        for (int digit = 1; digit <= 9; digit++) {
            switch (code[NUMBER_OF_DIGITS - digit]) {
                case ADD  -> { value += sign * number; number = digit; sign = +1; }
                case SUB  -> { value += sign * number; number = digit; sign = -1; }
                case JOIN -> { number = 10 * number + digit; }
            }
        }
        return value + sign * number;
    }
 
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (int digit = 1; digit <= NUMBER_OF_DIGITS; digit++) {
            switch (code[NUMBER_OF_DIGITS - digit]) {
                case ADD  -> if (digit > 1) sb.append(" + ");
                case SUB  -> sb.append(" - ");
                case JOIN -> {}
            }
            sb.append(digit);
        }
        return sb.toString().trim();
    }
}
 
public class Stat {
 
    private final Map<Integer, Integer> countSum = new HashMap<>();
    private final Map<Integer, Set<Integer>> sumCount = new HashMap<>();
 
    public Stat() {
        Expression expression = new Expression();
        for (int i = 0; i < Expression.NUMBER_OF_EXPRESSIONS; i++) {
            int sum = expression.toInt();
            countSum.put(sum, 1 + (countSum.getOrDefault(sum, 0)));
            expression.inc();
        }

public static int littleInt(InputStream input) throws IOException {
    int ch1 = input.read();
    int ch2 = input.read();
    int ch3 = input.read();
    int ch4 = input.read();
    if ((ch1 | ch2 | ch3 | ch4) < 0)
        throw new EOFException();
    return (ch4 << 24) + (ch3 << 16) + (ch2 << 8) + (ch1 << 0);
}

