import com.google.common.base.Preconditions;
import edu.umd.cs.findbugs.annotations.DefaultAnnotation;
import edu.umd.cs.findbugs.annotations.NonNull;
import net.jcip.annotations.Immutable;

@DefaultAnnotation(NonNull.class)
@Immutable
public class BindingSetRow {

    private final String nodeId;
    private final String bindingSetString;

    public BindingSetRow(String nodeId, String bindingSetString) {
        Preconditions.checkNotNull(nodeId, "Node ID cannot be null");
        Preconditions.checkNotNull(bindingSetString, "Binding Set String cannot be null");
        this.nodeId = nodeId;
        this.bindingSetString = bindingSetString;
    }

    public String getNodeId() {
        return nodeId;
    }

    public String getBindingSetString() {
        return bindingSetString;
    }

    public static BindingSetRow make(Bytes row) {
        Preconditions.checkNotNull(row, "Row bytes cannot be null");
        String rowString = row.toString();
        String[] parts = rowString.split(":", 2);

        if (parts.length == 2) {
            return new BindingSetRow(parts[0], parts[1]);
        } else if (parts.length == 1) {
            return new BindingSetRow(parts[0], "");
        } else {
            throw new IllegalArgumentException("Invalid row format");
        }
    }

    @Override
    public String toString() {
        return "BindingSetRow{" +
                "nodeId='" + nodeId + '\'' +
                ", bindingSetString='" + bindingSetString + '\'' +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        BindingSetRow that = (BindingSetRow) o;

        if (!nodeId.equals(that.nodeId)) return false;
        return bindingSetString.equals(that.bindingSetString);
    }

    @Override
    public int hashCode() {
        int result = nodeId.hashCode();
        result = 31 * result + bindingSetString.hashCode();
        return result;
    }
}

public class ViolationBuilder {
    private final Oracle o;

    public ViolationBuilder(Oracle o) {
        this.o = o;
    }

    public void createTrainCrashViolation(Train t1, Train t2, Connectable location, long tick) {
        String msg = String.format("Crash between trains %s and %s at %s",
                o.getId(t1), o.getId(t2), o.getId(location));
        o.registerViolation(new Violation(ViolationType.CRASH, ViolationSeverity.CRITICAL, msg, tick));
    }

    public void createFixedBlockViolation(Section section, Train conflictingTrain, long tick) {
        String msg = String.format("Fixed block section %s illegally occupied by train %s",
                o.getId(section), o.getId(conflictingTrain));
        o.registerViolation(new Violation(ViolationType.FIXED_BLOCK, ViolationSeverity.HIGH, msg, tick));
    }

    public void createVariableBlockViolation(Train t1, Train t2, Section section, long tick) {
        String msg = String.format("Trains %s and %s in variable block %s are in unsafe proximity",
                o.getId(t1), o.getId(t2), o.getId(section));
        o.registerViolation(new Violation(ViolationType.VARIABLE_BLOCK, ViolationSeverity.HIGH, msg, tick));
    }

    public void createOverfullStationViolation(Station station, int capacity, int current, long tick) {
        String msg = String.format("Station %s over capacity: %d/%d",
                o.getId(station), current, capacity);
        o.registerViolation(new Violation(ViolationType.OVERFULL_STATION, ViolationSeverity.MEDIUM, msg, tick));
    }
}

class Violation {
