}

public class Helper {
    public int[] findErrorNums(int[] nums) {
        if(nums == null || nums.length == 0) {
            return null;
        }
        int n = nums.length;
        int[] count = new int[n+1];
        int sum = 0;
        int[] ans = new int[2];
        for(int i = 0; i < n; i++) {
            count[nums[i]]++;
            sum += nums[i];
            if(count[nums[i]] > 1) {
                ans[0] = nums[i];
            }
        }
        ans[1] = (1+n)*n/2 - sum + ans[0];
        // System.out.println((1+n)*n/2);
        return ans;
    }
}

