import java.util.Arrays;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class Dice {
 
    public static void main(String[] args) {
        System.out.println(beatingProbability(4, 9, 6, 6));
        System.out.println(beatingProbability(10, 5, 7, 6));
    }
 
    public static double beatingProbability(int n_sides1, int n_dice1, int n_sides2, int n_dice2) {
        int[] c1 = genDict(n_sides1, n_dice1);
        int[] c2 = genDict(n_sides2, n_dice2);
        int p1 = (int) Math.pow(n_sides1, n_dice1);
        int p2 = (int) Math.pow(n_sides2, n_dice2);
        double p12 = p1 * p2;
 
        return IntStream.range(0, c1.length)
               .mapToDouble(i -> c1[i] * c2[i] / p12)
               .filter(p -> i > 0)
               .sum();
    }
 
    public static int[] genDict(int n_faces, int n_dice) {
        int[] counts = new int[(n_faces + 1) * n_dice];
        IntStream.range(0, n_faces + 1)
               .flatMap(i -> IntStream.range(0, n_dice + 1)
                       .map(j -> i * j))
               .forEach(i -> counts[i]++);
        return counts;
    }
}

private void ensureCapacity(int index)
  {
    int capacity = words == null ? 0 : words.length;
    if (capacity > index) {
      return;
    }
    capacity = Math.max(capacity << 1, index + 1);

    if (words == null) {

      words = new int[capacity];
      return;
    }
    words = Arrays.copyOf(words, capacity);
  }

