public String bestHand(int[] ranks, char[] suits) {
    int[] counts = new int[14];

    for (int rank : ranks) {
        counts[rank]++;
    }

    boolean flush = true;
    char suit = suits[0];

    for (char card : suits) {
        if (card != suit) {
            flush = false;
            break;
        }
    }

    if (flush) {
        return "Flush";
    }

    for (int count : counts) {
        if (count >= 3) {
            return "Three of a Kind";
        }
    }

    int pairCount = 0;

    for (int count : counts) {
        if (count >= 2) {
            pairCount++;
        }
    }

    if (pairCount >= 2 || pairCount > 0 && counts[0] > 0) {
        return "Pair";
    }

    return "High Card";
}

import java.awt.image.*;
