public class ParserErrorHandler implements ErrorHandler {

    /** The warnings. */
    private List<String> warnings;

    /** The errors. */
    private List<String> errors;

    /**
     * Instantiates a new parser error handler.
     *
     * @param warnings
     *            the warnings
     * @param errors
     *            the errors
     */
    public ParserErrorHandler(List<String> warnings, List<String> errors) {
        super();
        this.warnings = warnings;
        this.errors = errors;
    }

    /*
     * (non-Javadoc)
     *
     * @see org.xml.sax.ErrorHandler#warning(org.xml.sax.SAXParseException)
     */
    public void warning(SAXParseException exception) throws SAXException {
        warnings.add(getString("Warning.7", //$NON-NLS-1$
                Integer.toString(exception.getLineNumber()), exception
                        .getMessage()));
    }

    /*
     * (non-Javadoc)
     *
     * @see org.xml.sax.ErrorHandler#error(org.xml.sax.SAXParseException)
     */
    public void error(SAXParseException exception) throws SAXException {
        errors.add(getString("RuntimeError.4", //$NON-NLS-1$
                Integer.toString(exception.getLineNumber()), exception
                        .getMessage()));
    }

    /*
     * (non-Javadoc)
     *
     * @see org.xml.sax.ErrorHandler#fatalError(org.xml.sax.SAXParseException)
     */
    public void fatalError(SAXParseException exception) throws SAXException {
        errors.add(getString("RuntimeError.4", //$NON-NLS-1$
                Integer.toString(exception.getLineNumber()), exception
                        .getMessage()));
    }
}

import org.json.JSONObject;
import android.util.Log;

public class TrackInfo {
    private String mId;
    private String mName;
    private String mUrl;
    private ArtistInfo mArtist;

    public TrackInfo(String jsonData) {
        parseInfo(jsonData);
    }

    private void parseInfo(String jsonData) {
        try {
            JSONObject jsonObject = new JSONObject(jsonData);
            this.mId = jsonObject.optString("id", "Unknown ID");
            this.mName = jsonObject.optString("name", "Unknown Track");
            this.mUrl = jsonObject.optString("url", "Unknown URL");

            JSONObject artistObject = jsonObject.optJSONObject("artist");
            if (artistObject != null) {
                mArtist = new ArtistInfo(artistObject);
            } else {
                Log.e("TrackInfo", "Artist information is missing.");
                mArtist = new ArtistInfo(); // Initialize with empty artist info
            }
        } catch (Exception e) {
            Log.e("TrackInfo", "Error parsing track information: " + e.getMessage());
            this.mId = "Error";
            this.mName = "Error";
            this.mUrl = "Error";
            mArtist = new ArtistInfo(); // Initialize with empty artist info on error
        }
    }

    public String getId() {
        return mId;
    }

    public String getName() {
        return mName;
    }

    public String getUrl() {
        return mUrl;
    }

    public ArtistInfo getArtist() {
        return mArtist;
    }

    public static class ArtistInfo {
        private String mArtistId;
        private String mArtistName;

        public ArtistInfo() {
            // Default constructor for missing artist info
            this.mArtistId = "Unknown Artist ID";
            this.mArtistName = "Unknown Artist";
        }

        public ArtistInfo(JSONObject artistData) {
            try {
                this.mArtistId = artistData.optString("id", "Unknown Artist ID");
                this.mArtistName = artistData.optString("name", "Unknown Artist");
            } catch (Exception e) {
                Log.e("ArtistInfo", "Error parsing artist information: " + e.getMessage());
                this.mArtistId = "Error";
                this.mArtistName = "Error";
            }
        }

        public String getArtistId() {
            return mArtistId;
        }

        public String getArtistName() {
            return mArtistName;
        }
    }
}

public static int gcd(int m, int n) {
    if (m % n == 0) {
        return n;
    } else {
        return gcd(n, m % n);
    }
}

