import com.example.mod.model.SailModel;
import com.example.mod.tileentity.TileEntitySail;

public class TileEntitySailRenderer extends TileEntitySpecialRenderer {

    private static final ResourceLocation SAIL_TEXTURE = new ResourceLocation("examplemod:textures/models/sail.png");
    private SailModel model;

    public TileEntitySailRenderer() {
        this.model = new SailModel();
    }

    @Override
    public void renderTileEntityAt(TileEntity tileEntity, double x, double y, double z, float partialTicks) {
        if (tileEntity instanceof TileEntitySail) {
            TileEntitySail sailTileEntity = (TileEntitySail) tileEntity;
            int metadata = sailTileEntity.getBlockMetadata();

            GL11.glPushMatrix();
            GL11.glTranslatef((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
            GL11.glRotatef(180, 0F, 0F, 1F);

            // Determine rotation based on metadata
            switch (metadata) {
                case 0:
                    GL11.glRotatef(0, 0F, 1F, 0F);
                    break;
                case 1:
                    GL11.glRotatef(90, 0F, 1F, 0F);
                    break;
                case 2:
                    GL11.glRotatef(180, 0F, 1F, 0F);
                    break;
                case 3:
                    GL11.glRotatef(270, 0F, 1F, 0F);
                    break;
            }

            // Bind texture and scale model
            this.bindTexture(SAIL_TEXTURE);
            GL11.glScalef(1F, -1F, -1F);

            // Apply lighting adjustments
            adjustLightFixture(sailTileEntity);

            // Render the model
            model.renderAll();

            GL11.glPopMatrix();
        }
    }

    private void adjustLightFixture(TileEntitySail sailTileEntity) {
        float brightness = sailTileEntity.getWorldObj().getLightBrightness(sailTileEntity.xCoord, sailTileEntity.yCoord, sailTileEntity.zCoord);
