        int combinedLight = skyLight << 20 | blockLight << 4;

        GL11.glPushAttrib(GL11.GL_LIGHTING_BIT);
        GL11.glEnable(GL11.GL_LIGHTING);
        GL11.glEnable(GL11.GL_COLOR_MATERIAL);

