public class MinimizeScore {
    public int minimizeScore(int[] nums, int k) {
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        for (int num : nums) {
            min = Math.min(min, num + k);
            max = Math.max(max, num - k);
        }
        return max - min;
    }
}

