boolean expectNotNullOrUndefined( NodeTraversal t, Node n, JSType type, String msg, JSType expectedType) {
    // Check if the type is null or void
    if (type.isVoidType() || type.isNullType()) {
        // Issue a warning if the type is null or void
        t.getCompiler().report(JSError.make(n, msg));
        return false;
    }
    // Check if the type is a union type that includes void and at least one other type
    if (type.isUnionType()) {
        UnionType unionType = type.toMaybeUnionType();
        if (unionType.getAlternates().contains(JSTypeNative.VOID_TYPE) && unionType.getAlternates().size() > 1) {
            return true;
        }
    }
    // Return true if the type is not null or void and not a union type that includes void and at least one other type
    return true;
}

