import java.net.InetAddress;
import java.net.UnknownHostException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
 
public class ParseIpPort {
    public static void main(String[] args) {
        String[] tests = {
            "127.0.0.1",
            "127.0.0.1:80",
            "::1",
            "[::1]:80",
            "::192.168.0.1",
            "2605:2700:0:3::4713:93e3",
            "[2605:2700:0:3::4713:93e3]:80" };
        for (String address : tests) {
            IpPort ipPort = parseIpPort(address);
            System.out.printf("%39s  %32s  IPv%d  port=%d%n",
                    ipPort.ip, ipPort.hexIp, ipPort.version, ipPort.port);
        }
    }
 
    public static IpPort parseIpPort(String netloc) {
        IpPort ipPort = new IpPort();
        try {
            InetAddress ip = InetAddress.getByName(netloc);
            ipPort.ip = ip.getHostAddress();
            ipPort.version = ip.getAddress().length == 4? 4 : 6;
        } catch (UnknownHostException e) {
            Pattern pattern = Pattern.compile("^(.*):(\\d+)$");
            Matcher matcher = pattern.matcher(netloc);
            if (matcher.matches()) {
                ipPort.ip = matcher.group(1);
                ipPort.port = Integer.parseInt(matcher.group(2));
            }
        }
        ipPort.hexIp = String.format("%0" + ipPort.version * 2 + "X",
                Long.parseLong(ipPort.ip.replaceAll(":", ""), 16));
        return ipPort;
    }
 
    public static class IpPort {
        public String ip;
        public String hexIp;
        public int version;
        public int port;
    }
}

/**
 * An invoice composed with a Customer, applying a discount.
