class Customer {

    private int customerId;
    private String fullName;
    private int discountPercent;

    public Customer(int customerId, String fullName, int discountPercent) {
        this.customerId = customerId;
        this.fullName = fullName;
        this.discountPercent = discountPercent;
    }

    public int getID() {
        return customerId;
    }

    public void setID(int customerId) {
        this.customerId = customerId;
    }

    public String getName() {
        return fullName;
    }

    public void setName(String fullName) {
        this.fullName = fullName;
    }

    public int getDiscount() {
        return discountPercent;
    }

    public void setDiscount(int discountPercent) {
        this.discountPercent = discountPercent;
    }

    @Override
    public String toString() {
        return fullName + "(" + customerId + ")" + "(" + discountPercent + "%)";
    }
}

public class Invoice {

    private int invoiceId;
    private Customer buyer;
    private double amount;

    public Invoice(int invoiceId, Customer buyer, double amount) {
        this.invoiceId = invoiceId;
        this.buyer = buyer;
        this.amount = amount;
    }

    public int getID() {
        return invoiceId;
    }

    public void setID(int invoiceId) {
        this.invoiceId = invoiceId;
    }

    public Customer getCustomer() {
        return buyer;
    }

    public void setCustomer(Customer buyer) {
        this.buyer = buyer;
    }

    public double getAmount() {
        return amount;
    }

    public void setAmount(double amount) {
        this.amount = amount;
    }

    public int getCustomerID() {
        return buyer.getID();
    }

    public String getCustomerName() {
        return buyer.getName();
    }

    public int getCustomerDiscount() {
        return buyer.getDiscount();
    }

    public double getAmountAfterDiscount() {
        return amount - (amount * buyer.getDiscount() / 100);
    }

    @Override
    public String toString() {
        return "Invoice[id=" + invoiceId + ",customer=" + buyer + ",amount=" + amount + "]";
    }
}

