class Builder {
    public String decodeAtIndex(String S, int K) {
        long len = 0;
        for (int i = 0; i < S.length(); i++) {
            char c = S.charAt(i);
            if (Character.isLetter(c)) {
                len++;
                if (len == K) return String.valueOf(c);
            } else {
                long w = len * (c - '0');
                if (w >= K) {
                    return decodeAtIndex(S.substring(0,i), (int)((K-1) % len)+1);
                } else {
                    len = w;
                }
            }
        }
        return "";
    }
}

