private void checkForHosedThisReferences(Node function, JSDocInfo docInfo,
      final Name name) {

    boolean isAllowedToReferenceThis =
        (docInfo != null && (docInfo.isConstructorOrInterface() || docInfo.hasThisType()))
        || function.isArrowFunction();
    if (!isAllowedToReferenceThis) {
      NodeTraversal.traverse(compiler, function.getLastChild(),
          new NodeTraversal.AbstractShallowCallback() {
            @Override
            public void visit(NodeTraversal t, Node n, Node parent) {
              if (n.isThis()) {
                compiler.report(
                    JSError.make(n, UNSAFE_THIS, name.getFullName()));
              }
            }
          });
    }
  }

import com.vividsolutions.jts.geom.Geometry;
import com.vividsolutions.jts.geom.Polygon;
import com.vividsolutions.jts.geom.GeometryFactory;
import com.vividsolutions.jts.geom.Envelope;

public static Polygon getMinimumBoundingPolygon(Geometry geometry) {
    Envelope envelope = geometry.getEnvelopeInternal();
    GeometryFactory factory = geometry.getFactory();
    return factory.createPolygon(factory.createLinearRing(new Coordinate[] {
            new Coordinate(envelope.getMinX(), envelope.getMinY()),
            new Coordinate(envelope.getMinX(), envelope.getMaxY()),
            new Coordinate(envelope.getMaxX(), envelope.getMaxY()),
            new Coordinate(envelope.getMaxX(), envelope.getMinY()),
            new Coordinate(envelope.getMinX(), envelope.getMinY()) }), null);
}

import java.util.*;

public class Practice {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt(); int k = sc.nextInt();

        ArrayList<ArrayList<Integer>> list = new ArrayList<>();

        for(int i=0;i<n;i++) list.add(new ArrayList<>());

        for(int i=0;i<n-1;i++){

            int u = sc.nextInt()-1; int v = sc.nextInt()-1;

            list.get(u).add(v);

            list.get(v).add(u);

        }

        long[] size = new long[n];

        long[] diff = new long[n];

        boolean[] visited = new boolean[n];

        dfs(0, list, 1, size, visited, diff);

        long ans = 0;

        Arrays.sort(diff);

        for(int i=k;i<n;i++){

            ans+=diff[i];

        }

        System.out.println(ans);

    }

    private static long dfs(int root, ArrayList<ArrayList<Integer>> list, int height, long[] size, boolean[] visited, long[] diff) {

        size[root] = 1;

        visited[root] = true;

        for(int x: list.get(root)){

            if(!visited[x]) size[root] += dfs(x,list, height+1, size, visited, diff);

        }

        diff[root] = size[root] - height;

        return size[root];

    }

}

