public abstract class AbstractDataBinding<I, O, P> {
    private final TypedDataDescription description;

    protected AbstractDataBinding(TypedDataDescription description) {
        this.description = description;
    }

    public abstract Class<I> getInputType();
    public abstract Class<O> getOutputType();
    public abstract Class<P> getPayloadType();

    protected Class<?> getMemberType(Field field) {
        Type genericType = field.getGenericType();
        if (genericType instanceof ParameterizedType) {
            ParameterizedType paramType = (ParameterizedType) genericType;
            return (Class<?>) paramType.getActualTypeArguments()[0];
        }
        return field.getType();
    }

    protected boolean isEnum(Class<?> type) {
        return type.isEnum();
    }

    protected String enumToString(Enum<?> enumValue) {
        return enumValue != null ? enumValue.name() : null;
    }

    protected <E extends Enum<E>> E stringToEnum(Class<E> enumType, String value) {
        return value != null ? Enum.valueOf(enumType, value) : null;
    }

    protected Object wrapPrimitiveType(Class<?> type, Object value) {
        if (value == null) return null;

        if (type == int.class) return Ints.tryParse(value.toString());
        if (type == long.class) return Longs.tryParse(value.toString());
        if (type == double.class) return Doubles.tryParse(value.toString());
        if (type == float.class) return Floats.tryParse(value.toString());
        if (type == boolean.class) return Boolean.parseBoolean(value.toString());

        return value;
    }

    protected P outputToPayload(O output) throws Exception {
        if (output == null) return null;

        Method[] methods = getOutputType().getDeclaredMethods();
        Map<String, Object> payloadMap = new HashMap<>();

        for (Method method : methods) {
            if (method.getName().startsWith("get") && method.getParameterCount() == 0) {
                String fieldName = method.getName().substring(3);
                fieldName = Character.toLowerCase(fieldName.charAt(0)) + fieldName.substring(1);

                Object value = method.invoke(output);

                if (isEnum(method.getReturnType())) {
                    value = enumToString((Enum<?>) value);
                }

                payloadMap.put(fieldName, value);
            }
        }

