import java.math.BigInteger;
import java.util.UUID;

public class FriendFoundReplyEventArgs extends EventArgs {
    private final UUID m_AgentID;
    private final BigInteger m_RegionHandle;
    private final Vector3 m_Location;

    public FriendFoundReplyEventArgs(
        UUID agentID,
        BigInteger regionHandle,
        Vector3 location
    ) {
        if (agentID == null) {
            throw new IllegalArgumentException("Agent ID cannot be null");
        }

        if (regionHandle == null || regionHandle.compareTo(BigInteger.ZERO) <= 0) {
            throw new IllegalArgumentException("Invalid region handle");
        }

        if (location == null) {
            throw new IllegalArgumentException("Location cannot be null");
        }

        this.m_AgentID = agentID;
        this.m_RegionHandle = regionHandle;
        this.m_Location = new Vector3(location);
    }

    public UUID getAgentID() {
        return m_AgentID;
    }

    public BigInteger getRegionHandle() {
        return m_RegionHandle;
    }

    public Vector3 getLocation() {
        return new Vector3(m_Location);
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;

        FriendFoundReplyEventArgs other = (FriendFoundReplyEventArgs) obj;
        return m_AgentID.equals(other.m_AgentID) &&
               m_RegionHandle.equals(other.m_RegionHandle) &&
               m_Location.equals(other.m_Location);
    }

    @Override
    public int hashCode() {
        int result = m_AgentID.hashCode();
        result = 31 * result + m_RegionHandle.hashCode();
        result = 31 * result + m_Location.hashCode();
        return result;
    }

    @Override
    public String toString() {
        return String.format(
            "FriendFoundReplyEventArgs[AgentID=%s, RegionHandle=%s, Location=%s]",
            m_AgentID, m_RegionHandle, m_Location
        );
    }
}

