import java.util.*;

public class Sorter {
    static int[] parent = new int[200001];
    static int[] rank = new int[200001];
    static boolean[] deleted = new boolean[200001];
    static ArrayList<ArrayList<int[]>> adj = new ArrayList<>();
    static int[] ans = new int[200001];
    static int tot = 0;

    static int find(int x) {
        if (x != parent[x]) parent[x] = find(parent[x]);
        return parent[x];
    }

    static void merge(int x, int y, int t) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        tot += t;
        if (rank[x] < rank[y]) {
            parent[x] = y;
            adj.get(y).add(new int[]{x, t});
        } else if (rank[x] > rank[y]) {
            parent[y] = x;
            adj.get(x).add(new int[]{y, t});
        } else {
            parent[y] = x;
            adj.get(x).add(new int[]{y, t});
            rank[x]++;
        }
    }

    static void dfs(int u, int p) {
        for (int[] v : adj.get(u)) {
            if (v[0] == p) continue;
            dfs(v[0], u);
        }
        deleted[u] = true;
        for (int[] v : adj.get(u)) {
            if (deleted[v[0]]) continue;
            deleted[v[0]] = true;
            ans[u] -= 2 * v[1];
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            rank[i] = 0;
            adj.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int t = sc.nextInt();
            merge(u, v, t);
        }
        for (int i = 1; i <= n; ans[1] += ans[i++]) {
            dfs(i, 0);
        }
        System.out.println(ans[1] + " " + tot);
    }
}

