import java.io.*;
import java.util.*;
import java.lang.*;
import java.math.*;
 
public class Library {
 
    static final int N = 32;
    static double[] xval = new double[N];
    static double[] t_sin = new double[N];
    static double[] t_cos = new double[N];
    static double[] t_tan = new double[N];
 
    static final int N2 = N * (N - 1) / 2;
    static double[] r_sin = new double[N2];
    static double[] r_cos = new double[N2];
    static double[] r_tan = new double[N2];
 
    static double ρ(double[] x, double[] y, double[] r, int i, int n) {
        if (n < 0)
            return 0;
        if (n == 0)
            return y[i];
 
        int idx = (N - 1 - n) * (N - n) / 2 + i;
        if (r[idx]!= r[idx])
            r[idx] = (x[i] - x[i + n]) / (ρ(x, y, r, i, n - 1) - ρ(x, y, r, i + 1, n - 1)) + ρ(x, y, r, i + 1, n - 2);
        return r[idx];
    }
 
    static double thiele(double[] x, double[] y, double[] r, double xin, int n) {
        return n > N - 1? 1. : ρ(x, y, r, 0, n) - ρ(x, y, r, 0, n - 2) + (xin - x[n]) / thiele(x, y, r, xin, n + 1);
    }
 
    static double i_sin(double x) { return thiele(t_sin, xval, r_sin, x, 0); }
    static double i_cos(double x) { return thiele(t_cos, xval, r_cos, x, 0); }
    static double i_tan(double x) { return thiele(t_tan, xval, r_tan, x, 0); }
 
    public static void main(String[] args) {
        double step =.05;
        for (int i = 0; i < N; i++) {
            xval[i] = i * step;
            t_sin[i] = Math.sin(xval[i]);
            t_cos[i] = Math.cos(xval[i]);
            t_tan[i] = t_sin[i] / t_cos[i];
        }
        for (int i = 0; i < N2; i++)
            r_sin[i] = r_cos[i] = r_tan[i] = Double.NaN;
 
        System.out.printf("%.25f\n", 6 * i_sin(.5));
        System.out.printf("%.25f\n", 3 * i_cos(.5));
        System.out.printf("%.25f\n", 4 * i_tan(1.));
    }
}

