// Pascal's triangle object
public class PascalTriangle {
 
    // Number of rows the triangle contains
    private int rows;
 
    // The 2D array holding the rows of the triangle
    private int[][] triangle;
 
    // Constructor
    public PascalTriangle(int rows) {
        this.rows = rows;
        this.triangle = new int[rows][];
        for (int r = 0; r < rows; r++) {
            this.triangle[r] = new int[r+1];
            for (int i = 0; i <= r; i++) {
                if (i == 0 || i == r)
                    this.triangle[r][i] = 1;
                else
                    this.triangle[r][i] = this.triangle[r-1][i-1]+this.triangle[r-1][i];
            }
        }
    }
 
    // Method to print the triangle
    public void print(int base) {
        if (base == 0)
            base = 10;
 
        // Private method to calculate digits in number
        int digits(int n, int b) {
            int d = 0;
            while (n >= 1) {
                d++;
                n /= b;
            }
            return d;
        }
 
        // Calculate max spaces needed
        int spacing = digits(this.triangle[this.rows-1][Math.round(this.rows/2)],base);
 
        // Private method to add spacing between numbers
        String insertSpaces(int s) {
            String buf = "";
            while (s > 0) {
                s--;
                buf += " ";
            }
            return buf;
        }
 
        // Print the triangle line by line
        for (int r = 0; r < this.triangle.length; r++) {
            String l = "";
            for (int s = 0; s < Math.round(this.rows-1-r); s++) {
                l += insertSpaces(spacing);
            }
            for (int i = 0; i < this.triangle[r].length; i++) {
                if (i!= 0)
                    l += insertSpaces(spacing-Math.ceil(digits(this.triangle[r][i],base)/2));
                l += this.triangle[r][i].toString(base);
                if (i < this.triangle[r].length-1)
                    l += insertSpaces(spacing-Math.floor(digits(this.triangle[r][i],base)/2));
            }
            System.out.println(l);
        }
    }
 
}
 
// Display 4 row triangle in base 10
PascalTriangle tri = new PascalTriangle(4);
tri.print();
// Display 8 row triangle in base 16
tri = new PascalTriangle(8);
tri.print(16);

import java.util.LinkedList;
import java.util.Queue;

class Node {
    int val;
    Node left;
    Node right;

    public Node(int val) {
        this.val = val;
        left = null;
        right = null;
    }
}

class BST {
    Node root;

    public void insert(int val) {
        root = insert(root, val);
    }

    private Node insert(Node node, int val) {
        if (node == null) {
            return new Node(val);
        }
        if (val < node.val) {
            node.left = insert(node.left, val);
        } else if (val > node.val) {
            node.right = insert(node.right, val);
        }
        return node;
    }

    public void inorder() {
        inorder(root);
    }

    private void inorder(Node node) {
        if (node == null) {
            return;
        }
        inorder(node.left);
        System.out.print(node.val + " ");
        inorder(node.right);
    }

    public void breadthFirstTraversal() {
        if (root == null) {
            return;
        }
        Queue<Node> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            Node current = queue.poll();
            System.out.print(current.val + " ");
            if (current.left != null) {
                queue.offer(current.left);
            }
            if (current.right != null) {
                queue.offer(current.right);
            }
        }
    }

    public int height() {
        return height(root);
    }

    private int height(Node node) {
        if (node == null) {
            return 0;
        }
        int leftHeight = height(node.left);
        int rightHeight = height(node.right);
        return 1 + Math.max(leftHeight, rightHeight);
    }
}

public class Manager {
    public static void main(String[] args) {
        BST bst = new BST();
        bst.insert(50);
        bst.insert(30);
        bst.insert(20);
        bst.insert(40);
        bst.insert(70);
        bst.insert(60);
        bst.insert(80);
        System.out.print("Inorder traversal: ");
        bst.inorder();
        System.out.println();
        System.out.print("Breadth-first traversal: ");
        bst.breadthFirstTraversal();
        System.out.println();
        System.out.println("Height of the tree: " + bst.height());
    }
}

