private void deleteEntry(TreeEntry<E> p) {
        entryIDs.remove(p.value.getId());
        treeSize--;

        if (p.left != null && p.right != null) {
            TreeEntry<E> s = successor(p);
            p.low = s.low;
            p.high = s.high;
            p.value = s.value;
            p.maxHigh = s.maxHigh;
            p = s;
        }

        TreeEntry<E> replacement = p.left != null ? p.left : p.right;
        if (replacement != null) {

            replacement.parent = p.parent;
            if (p.parent == null) {
                root = replacement;
            } else if (p == p.parent.left) {
                p.parent.left = replacement;
            } else {
                p.parent.right = replacement;
            }

            p.left = null;
            p.right = null;
            p.parent = null;
            fixUpMaxHigh(replacement.parent);

            if (p.color == BLACK) {
                fixAfterDeletion(replacement);
            }
        } else if (p.parent == null) {
            root = null;
        } else {
            if (p.color == BLACK) {
                fixAfterDeletion(p);
            }
            if (p.parent != null) {
                if (p == p.parent.left) {
                    p.parent.left = null;
                } else if (p == p.parent.right) {
                    p.parent.right = null;
                }
                fixUpMaxHigh(p.parent);
                p.parent = null;
            }
        }
    }

public static void main(String[] args) {
    try {
        // Check that there are three command-line arguments
        if (args.length != 3) {
            throw new IllegalArgumentException("Usage: java Calculator operand1 operator operand2");
        }

        // Parse the operands as doubles
        double operand1 = Double.parseDouble(args[0]);
        double operand2 = Double.parseDouble(args[2]);

        // Perform the operation based on the operator
        double result = 0;
        switch (args[1]) {
            case "+":
                result = operand1 + operand2;
                break;
            case "-":
                result = operand1 - operand2;
                break;
            case "*":
                result = operand1 * operand2;
                break;
            case "/":
                result = operand1 / operand2;
                break;
            default:
                throw new IllegalArgumentException("Invalid operator: " + args[1]);
        }

        // Print the result
        System.out.println(args[0] + " " + args[1] + " " + args[2] + " = " + result);
    } catch (NumberFormatException e) {
        System.err.println("Error: non-numeric operand");
        System.exit(1);
    } catch (IllegalArgumentException e) {
        System.err.println(e.getMessage());
        System.exit(1);
    }
}

