public class FilterScopeProcessor<T extends PsiElement> implements PsiScopeProcessor {

    private final List<T> myResults = new ArrayList<>();
    private PsiElement myCurrentDeclarationHolder;
    private final ElementFilter myFilter;
    private final PsiScopeProcessor myProcessor;

    public FilterScopeProcessor(@NotNull ElementFilter filter, @Nullable PsiScopeProcessor processor) {
        this.myFilter = filter;
        this.myProcessor = processor;
    }

    @Override
    public boolean execute(@NotNull PsiElement element, @NotNull ResolveState state) {
        if (myFilter.isAccepted(element)) {
            if (myProcessor != null && !myProcessor.execute(element, state)) {
                return false;
            }
            // Assuming T is a subclass of PsiElement, cast is safe here
            myResults.add((T) element);
        }
        return true;
    }

    @Override
    public <T> @Nullable T getHint(@NotNull Key<T> hintKey) {
        if (myProcessor != null) {
            return myProcessor.getHint(hintKey);
        }
        return null;
    }

    @Override
    public void handleEvent(@NotNull Event event, @Nullable Object associated) {
        if (event == Event.SET_DECLARATION_HOLDER) {
            myCurrentDeclarationHolder = (PsiElement) associated;
        }
        if (myProcessor != null) {
            myProcessor.handleEvent(event, associated);
        }
    }

    public List<T> getResults() {
        return myResults;
    }

