import java.util.*;

class Tree {
    public int shortestPathLength(int[][] graph) {
        int n = graph.length;
        int allVisitedMask = (1 << n) - 1;
        Queue<int[]> queue = new LinkedList<>();
        boolean[][] visited = new boolean[n][1 << n];

        // Initialize the queue with all nodes and their corresponding masks
        for (int i = 0; i < n; i++) {
            queue.offer(new int[]{i, 1 << i});
            visited[i][1 << i] = true;
        }

        int steps = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] current = queue.poll();
                int node = current[0];
                int mask = current[1];

                if (mask == allVisitedMask) {
                    return steps;
                }

                for (int neighbor : graph[node]) {
                    int nextMask = mask | (1 << neighbor);
                    if (!visited[neighbor][nextMask]) {
                        visited[neighbor][nextMask] = true;
                        queue.offer(new int[]{neighbor, nextMask});
                    }
                }
            }
            steps++;
        }

        return -1; // This line should never be reached if the graph is connected
    }
}

public class MyRectangle2D {
    private double x;
    private double y;
    private double width;
    private double height;

    public MyRectangle2D() {
        this(0, 0, 1, 1);
    }

    public MyRectangle2D(double x, double y, double width, double height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
    }

    public double getX() {
        return x;
    }

    public void setX(double x) {
        this.x = x;
    }

    public double getY() {
        return y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getWidth() {
        return width;
    }

    public void setWidth(double width) {
        this.width = width;
    }

    public double getHeight() {
        return height;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    public double getArea() {
        return width * height;
    }

    public double getPerimeter() {
        return 2 * (width + height);
    }

    public boolean contains(double x, double y) {
        return Math.abs(x - this.x) <= width / 2 && Math.abs(y - this.y) <= height / 2;
    }

    public boolean contains(MyRectangle2D r) {
        return contains(r.getX() - r.getWidth() / 2, r.getY() + r.getHeight() / 2) &&
               contains(r.getX() - r.getWidth() / 2, r.getY() - r.getHeight() / 2) &&
               contains(r.getX() + r.getWidth() / 2, r.getY() + r.getHeight() / 2) &&
               contains(r.getX() + r.getWidth() / 2, r.getY() - r.getHeight() / 2);
    }

    public boolean overlaps(MyRectangle2D r) {
        double x1 = x - width / 2;
        double y1 = y + height / 2;
        double x2 = x + width / 2;
        double y2 = y - height / 2;

        double rx1 = r.getX() - r.getWidth() / 2;
        double ry1 = r.getY() + r.getHeight() / 2;
        double rx2 = r.getX() + r.getWidth() / 2;
        double ry2 = r.getY() - r.getHeight() / 2;

        return !(rx2 < x1 || rx1 > x2 || ry2 > y1 || ry1 < y2);
    }
}

class Builder {
    public boolean sumGame(String num) {

        int a = 0;
        int b = 0;
        int n = num.length();
        int sum = 0;
        for (int i = 0;i<n/2;i++) {
            if (num.charAt(i) == '?') {
                a++;
            } else {
                sum += (int)(num.charAt(i) - '0');
            }
        }
        for (int i = n/2;i<n;i++) {
            if (num.charAt(i) == '?') {
                b++;
            } else {
                sum -= (int)(num.charAt(i) - '0');
            }
        }
        if (a == b && sum != 0) {
            return true;
        } else if (a == b) {
            return false;
        }
        if (a < b && sum >= 0) {
            int d = b-a;
            if (d%2 != 0) {
                return true;
            }
            if (sum < 9*(d/2)) {
                return true;
            } else if (sum > 9*(d/2)) {
                return true;
            }
            return false;
        } else if (a > b && sum <= 0) {
            int d = a-b;
            if (d%2 != 0) {
                return true;
            }
            if (sum == -9*(d/2)) {
                return false;
            }
            return true;
        }
        return true;
    }
}

class Account {
    public int constrainedSubsetSum(int[] nums, int k) {
      int[] mem = new int[nums.length];
      Deque<Integer> q = new ArrayDeque<>();
      int res = 0;
      for(int i=nums.length-1; i>=0; i--) {
        if(i == nums.length-1) {
          mem[i] = nums[i];
          q.add(i);
          res = mem[i];
        }
        else {
          if(q.getLast()-i > k) q.pollLast();
          int cres;
          if(mem[q.getLast()] < 0) cres = nums[i];
          else cres = nums[i] + mem[q.getLast()];
          mem[i] = cres;
          res = Math.max(res, cres);
          while(!q.isEmpty()) {
            if(mem[q.peekFirst()] <= cres) q.pollFirst();
            else break;
          }
          q.addFirst(i);
        }
      }
      return res;
    }
  }

import java.io.PrintWriter;

import java.util.*;

public class C {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        PrintWriter pw = new PrintWriter(System.out);

        int t = sc.nextInt();

        for (int i = 0; i < t; i++) {

            solve(sc, pw);

        }

        pw.close();

    }

    static void solve(Scanner in, PrintWriter out){

        int n = in.nextInt();

        int[] arr = new int[n];

        for (int i = 0; i < n; i++) {

            arr[i] = in.nextInt();

        }

        int[] seen = new int[n + 1];

        Arrays.fill(seen, -1);

        int[] maxdp = new int[n + 1];

        int[] cnt = new int[n + 1];

        for (int i = 0; i < n; i++) {

            if (seen[arr[i]] != -1){

                maxdp[arr[i]] = Math.max(maxdp[arr[i]], i - seen[arr[i]]);

            }else{

                maxdp[arr[i]] = i + 1;

            }

            seen[arr[i]] = i;

            cnt[arr[i]]++;

        }

        for (int i = 0; i < n; i++) {

            maxdp[arr[i]] = Math.max(maxdp[arr[i]], n - seen[arr[i]]);

        }

//        System.out.println(Arrays.toString(maxdp));

        PriorityQueue<Integer> pq = new PriorityQueue<>();

        PriorityQueue<int[]> pqp = new PriorityQueue<>((a, b) -> (a[0] - b[0]));

        for (int i = 1; i <= n; i++) {

            if (cnt[i] > 0){

                pqp.add(new int[]{maxdp[i],  i});

            }

        }

        int[] ans = new int[n + 1];

        Arrays.fill(ans, -1);

        for (int i = 1; i <= n; i++) {

            while (!pqp.isEmpty() && pqp.peek()[0] <= i) pq.add(pqp.poll()[1]);

            if (pq.size() > 0) ans[i] = pq.peek();

        }

        for (int i = 1; i <= n; i++) {

            out.print(ans[i]+" ");

        }

        out.println();

    }

    static boolean isPrime(long n)

    {

        // Corner cases

        if (n <= 1)

            return false;

        if (n <= 3)

            return true;

        // This is checked so that we can skip

        // middle five numbers in below loop

        if (n % 2 == 0 || n % 3 == 0)

            return false;

        for (int i = 5; i * i <= n; i = i + 6)

            if (n % i == 0 || n % (i + 2) == 0)

                return false;

        return true;

    }

    static long gcd(long a, long b)

    {

        if (a == 0)

            return b;

        return gcd(b % a, a);

    }

    // method to return LCM of two numbers

    static long lcm(long a, long b)

    {

        return (a / gcd(a, b)) * b;

    }

