import java.util.HashMap;

public class Student {
    public static int solve(int[] nums, int[] quantity) {
        // Sort the nums array
        Arrays.sort(nums);
        // Create the result and total_available arrays
        boolean[] result = new boolean[nums.length];
        int total_available = nums.length;
        // Create the HashMap to store the integer frequencies
        HashMap<Integer,Integer> map = new HashMap<>();
        // Iterate over the nums array and update the HashMap
        int prev = nums[0];
        int counter = 1;
        for(int i = 1; i < nums.length; i++) {
            if(nums[i] == prev) {
                counter++;
            } else {
                map.put(prev, counter);
                prev = nums[i];
                counter = 1;
            }
        }
        // Put the last integer and its frequency in the HashMap
        map.put(prev, counter);
        // Iterate over the quantity array and assign the integers
        for(int q : quantity) {
            // Initialize the highest_frequency variable
            int highest_frequency = 0;
            int chosen_integer = -1;
            // Find the integer with the highest frequency that satisfies the order
            for(int n : nums) {
                // If the integer frequency is greater than or equal to the order, update the highest_frequency and chosen_integer variables
                int current_frequency = map.getOrDefault(n, 0);
                if(current_frequency >= q && current_frequency > highest_frequency) {
                    highest_frequency = current_frequency;
                    chosen_integer = n;
                }
            }
            // If no such integer exists, return false
            if(chosen_integer == -1) return 0;
            // Assign the integer to the first customer who ordered it
            result[0] = true;
            // Decrement the order quantity, the integer frequency, and the total_available count by one
            quantity[0]--;
            map.put(chosen_integer, map.get(chosen_integer) - 1);
            total_available--;
            // If there are more customers who ordered the same integer, update them
            if(q > 1) {
                for(int i = 1; i < quantity.length; i++) {
                    if(quantity[i] > 0 && nums[i] == chosen_integer) {
                        result[i] = true;
                        quantity[i]--;
                        map.put(chosen_integer, map.get(chosen_integer) - 1);
                        total_available--;

