        // Private constructor to prevent instantiation
    }

    public static <T> T convert(Object fromValue, Function<TypeFactory, JavaType> typeGenerator) {
        JavaType type = generateType(typeGenerator);
        return MAPPER.convertValue(fromValue, type);
    }

    public static ObjectMapper createMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new GuavaModule());
        mapper.registerModule(new Jdk8Module());
        mapper.setSerializationInclusion(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL);
        return mapper;
    }

    public static <T> JavaType createPaginationType(Class<T> clazz) {
        return TYPE_FACTORY.constructParametricType(Page.class, clazz);
    }

    public static JavaType generateType(Function<TypeFactory, JavaType> typeGenerator) {
        return typeGenerator.apply(TYPE_FACTORY);
    }

    // Assumed Page class for pagination
    public static class Page<T> {
        private int pageNumber;
        private int pageSize;
        private long totalElements;
        private T[] content;

        // Getters and setters
        public int getPageNumber() {
            return pageNumber;
        }

        public void setPageNumber(int pageNumber) {
            this.pageNumber = pageNumber;
        }

        public int getPageSize() {
            return pageSize;
        }

        public void setPageSize(int pageSize) {
            this.pageSize = pageSize;
        }

        public long getTotalElements() {
            return totalElements;
        }

        public void setTotalElements(long totalElements) {
            this.totalElements = totalElements;
        }

        public T[] getContent() {
            return content;
        }

        public void setContent(T[] content) {
            this.content = content;
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class PercentileComputation {

    private List<Float> values;

    public PercentileComputation(List<Float> values) {
        this.values = values;
        Collections.sort(this.values);
    }

    private float getMedian(List<Float> list) {
        int size = list.size();
        if (size % 2 == 0) {
            return (list.get(size / 2 - 1) + list.get(size / 2)) / 2;
        } else {
            return list.get(size / 2);
        }
    }

    public float getMedian() {
        return getMedian(this.values);
    }

    public float getLowerQuartile() {
        int size = values.size();
        List<Float> lowerValues;

        if (size % 2 == 0) {
            lowerValues = new ArrayList<>(values.subList(0, size / 2));
        } else {
            lowerValues = new ArrayList<>(values.subList(0, size / 2));
        }

        return getMedian(lowerValues);
    }

    public float getUpperQuartile() {
        int size = values.size();
        List<Float> upperValues;

        if (size % 2 == 0) {
            upperValues = new ArrayList<>(values.subList(size / 2, size));
        } else {
            upperValues = new ArrayList<>(values.subList(size / 2 + 1, size));
        }

        return getMedian(upperValues);
    }

    public static void main(String[] args) {
        List<Float> data = new ArrayList<>();
        data.add(7.0f);
        data.add(15.0f);
        data.add(36.0f);
        data.add(39.0f);
        data.add(40.0f);
        data.add(41.0f);
        data.add(43.0f);
        data.add(50.0f);

        PercentileComputation computation = new PercentileComputation(data);

        System.out.println("Data: " + data);
        System.out.println("Lower Quartile (Q1): " + computation.getLowerQuartile());
        System.out.println("Median (Q2): " + computation.getMedian());
        System.out.println("Upper Quartile (Q3): " + computation.getUpperQuartile());
    }
}

