import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Arrays;
import java.util.List;

public class Library {
    public static void main(String[] args) throws NoSuchAlgorithmException {
        for (String[] p : Arrays.asList(
                // RFC 1321 test cases
                new String[]{"d41d8cd98f00b204e9800998ecf8427e", ""},
                new String[]{"0cc175b9c0f1b6a831c399e269772661", "a"},
                new String[]{"900150983cd24fb0d6963f7d28e17f72", "abc"},
                new String[]{"f96b697d7cb7938d525a2f31aaf161d0", "message digest"},
                new String[]{"c3fcd3d76192e4007dfb496cca67e13b", "abcdefghijklmnopqrstuvwxyz"},
                new String[]{"d174ab98d277d9f5a5611c2c9f419d9f",
                        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"},
                new String[]{"57edf4a22be3c955ac49da2e2107b67a", "12345678901234567890" +
                        "123456789012345678901234567890123456789012345678901234567890"},
                // test case popular with other RC solutions
                new String[]{"e38ca1d920c4b8b8d3946b2c72f01680",
                        "The quick brown fox jumped over the lazy dog's back"})) {
            validate(p[0], p[1]);
        }
    }

    private static MessageDigest h = MessageDigest.getInstance("MD5");

    private static void validate(String check, String s) throws NoSuchAlgorithmException {
        h.reset();
        h.update(s.getBytes());
        String sum = bytesToHex(h.digest());
        if (!sum.equals(check)) {
            System.out.println("MD5 fail");
            System.out.println("  for string, " + s);
            System.out.println("  expected:   " + check);
            System.out.println("  got:        " + sum);
        }
    }

    private static String bytesToHex(byte[] bytes) {
        char[] hexArray = "0123456789abcdef".toCharArray();
        char[] hexChars = new char[bytes.length * 2];
        for (int j = 0; j < bytes.length; j++) {
            int v = bytes[j] & 0xFF;
            hexChars[j * 2] = hexArray[v >>> 4];
            hexChars[j * 2 + 1] = hexArray[v & 0x0F];
        }
        return new String(hexChars);
    }
}

