class Graph {
    ArrayList<int[]>[] G;
    public Graph(int n, int[][] edges) {
        G = new ArrayList[n + 1];
        for(int i = 0; i <= n; i++){
            G[i] = new ArrayList();
        }

        for(int[] e : edges){
            G[e[0]].add(new int[]{e[1], e[2]});
        }
    }

    public void addEdge(int[] e) {
        G[e[0]].add(new int[]{e[1], e[2]});
    }

    public int shortestPath(int n1, int n2) {
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> {
            return a[1] - b[1];
        });
        pq.add(new int[]{n1, 0});
        int[] vis = new int[G.length];

        while(pq.size() > 0){
            int[] rem = pq.remove();
            if(rem[0] == n2) return rem[1];
            if(vis[rem[0]] == 1) continue;
            vis[rem[0]] = 1;
            for(int[] e : G[rem[0]]){
                pq.add(new int[]{e[0], rem[1] + e[1]});
            }
        }
        return -1;
    }
}

