    }
}

import java.util.ArrayList;
import java.util.List;
 
public class QueenPuzzle {
    public static void main(String[] args) {
        System.out.println(queenPuzzle(8, 8));
    }
 
    public static List<List<Integer>> queenPuzzle(int rows, int columns) {
        if (rows <= 0) {
            List<List<Integer>> empty = new ArrayList<List<Integer>>();
            empty.add(new ArrayList<Integer>());
            return empty;
        } else {
            return addQueen(rows - 1, columns);
        }
    }
 
    public static List<List<Integer>> addQueen(int newRow, int columns, List<List<Integer>> prevSolution) {
        List<List<Integer>> newSolutions = new ArrayList<List<Integer>>();
        List<List<Integer>> prev = queenPuzzle(newRow, columns);
        for (List<Integer> solution : prev) {
            for (int newColumn = 0; newColumn < columns; newColumn++) {
                if (!hasConflict(newRow, newColumn, solution)) {
                    List<Integer> newSolution = new ArrayList<Integer>(solution);
                    newSolution.add(newColumn);
                    newSolutions.add(newSolution);
                }
            }
        }
        return newSolutions;
    }
 
    public static boolean hasConflict(int newRow, int newColumn, List<Integer> solution) {
        for (int i = 0; i < newRow; i++) {
            if (solution.get(i) == newColumn ||
                solution.get(i) + i == newColumn + newRow ||
                solution.get(i) - i == newColumn - newRow) {
                return true;
            }
        }
        return false;
    }
}

