public class CompatibilityWaila implements IWailaDataProvider {

    public void register() {
        WailaRegistrar.instance().registerBodyProvider(this, TileSeedContainer.class);
        WailaRegistrar.instance().registerHeadProvider(this, TileSeedContainer.class);
        WailaRegistrar.instance().registerTailProvider(this, TileSeedContainer.class);
    }

    @Override
    public ItemStack getWailaStack(TileEntity tileEntity, List<ItemStack> current, String identifier) {
        if (tileEntity instanceof TileSeedContainer) {
            TileSeedContainer container = (TileSeedContainer) tileEntity;
            Seed seed = container.getSeed();

            if (seed != null) {
                return seed.getSeedItem().copy();
            }
        }
        return ItemStack.EMPTY;
    }

    @Override
    public void getWailaHead(List<String> tooltip, TileEntity tileEntity, List<ItemStack> current, String identifier) {
        tooltip.add(new TextComponentString("Crop Info").getFormattedText());
    }

    @Override
    public void getWailaBody(List<String> tooltip, TileEntity tileEntity, List<ItemStack> current, String identifier) {
        if (tileEntity instanceof TileSeedContainer) {
            TileSeedContainer container = (TileSeedContainer) tileEntity;
            Seed seed = container.getSeed();

            if (seed != null && seed.hasOutputItems()) {
                String output = "";
                for (ItemStack outputItem : seed.getOutputItems()) {
                    output += outputItem.getDisplayName() + ", ";
                }
                if (output.length() > 0) {
                    output = output.substring(0, output.length() - 2);
                }
                tooltip.add(new TextComponentString("Output: " + output).getFormattedText());
            } else {
                tooltip.add(new TextComponentString("No valid seed or outputs.").getFormattedText());
            }
        }
    }

    @Override
    public void getWailaTail(List<String> tooltip, TileEntity tileEntity, List<ItemStack> current, String identifier) {
        tooltip.add(new TextComponentString("Check your crops!").getFormattedText());
    }

class Finder {
    public int maxScoreSightseeingPair(int[] A) {
        if(A==null||A.length==0) return 0;
        int n = A.length;
        int[] addA = new int[n];
        int[] baseA = new int[n];
        for (int i=0; i < n; i++) {
            baseA[i] = A[i]+i;
            addA[i] = A[i]-i;
        }
        for(int i = n-2; i >= 0; i--) {
            addA[i] = Math.max(addA[i], addA[i+1]);
        }
        int max = 0;
        for (int i = 0; i < n-1; i++) {
            max = Math.max(max, baseA[i] + addA[i+1]);
        }
        return max;
    }
}

 
