import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.physics.box2d.*;

public class Bounds implements ContactListener, ContactFilter {
    private static final float DEFAULT_GROUND_Y = 0f;
    private static final float DEFAULT_TOP_Y = 480f;
    private static final float DEFAULT_WIDTH = 800f;
    private final Body groundBody;
    private final Body topBody;
    private final Fixture groundFixture;
    private final Fixture topFixture;

    public Bounds(World world) {
        this(world, DEFAULT_GROUND_Y, DEFAULT_TOP_Y, DEFAULT_WIDTH);
    }

    public Bounds(World world, float groundY, float topY, float width) {
        groundBody = createBoundary(world, groundY, width);
        topBody = createBoundary(world, topY, width);
        world.setContactListener(this);
        world.setContactFilter(this);
    }

    private Body createBoundary(World world, float yPos, float width) {
        BodyDef bodyDef = new BodyDef();
        bodyDef.type = BodyDef.BodyType.StaticBody;
        bodyDef.position.set(new Vector2(0, yPos));
        Body body = world.createBody(bodyDef);

        ChainShape shape = new ChainShape();
        Vector2[] vertices = {
            new Vector2(-width/2, 0),
            new Vector2(width/2, 0)
        };
        shape.createChain(vertices);

        FixtureDef fixtureDef = new FixtureDef();
        fixtureDef.shape = shape;
        fixtureDef.friction = 0.4f;
        fixtureDef.restitution = 0.1f;
        Filter filter = new Filter();
        filter.categoryBits = 0x0001;
        filter.maskBits = 0xFFFF;
        fixtureDef.filter = filter;

        Fixture fixture = body.createFixture(fixtureDef);
        shape.dispose();

        return body;
    }

    @Override
    public void beginContact(Contact contact) {}

    @Override
    public void endContact(Contact contact) {}

    @Override
    public void preSolve(Contact contact, Manifold oldManifold) {}

    @Override
    public void postSolve(Contact contact, ContactImpulse impulse) {}

    @Override
    public boolean shouldCollide(Fixture fixtureA, Fixture fixtureB) {
        return true;
    }

    public void dispose() {
        groundBody.destroyFixture(groundFixture);
        topBody.destroyFixture(topFixture);
    }

    public Body getGroundBody() { return groundBody; }
    public Body getTopBody() { return topBody; }
    public float getGroundY() { return DEFAULT_GROUND_Y; }
    public float getTopY() { return DEFAULT_TOP_Y; }
}

import java.util.HashMap;
import java.util.List;

class XMLDataSourceIterator {
    private XMLDataSource xds;
    private IDataField df;
    private List<XML> nodes;
    private int curIndex;

    public XMLDataSourceIterator(XMLDataSource xds, IDataField df, XML node) {
        this.xds = xds;
        this.df = df;
        this.nodes = df.accept(new NodeSetupVisitor(), node);
        this.curIndex = 0;
    }

    public boolean hasData() {
        return curIndex < nodes.size();
    }

    public void loadNext() {
        if (hasData()) {
            curIndex++;
        }
    }

    public Object fetch(ISig sig) throws DataSourceException {
        if (!hasData()) throw new DataSourceException("No more data");
        return sig.fetch(nodes.get(curIndex));
    }

    public boolean fetchBoolean(ISig sig) throws DataSourceException {
        return (Boolean) fetch(sig);
    }

    public byte fetchByte(ISig sig) throws DataSourceException {
        return (Byte) fetch(sig);
    }

    public char fetchChar(ISig sig) throws DataSourceException {
        return (Character) fetch(sig);
    }

    public double fetchDouble(ISig sig) throws DataSourceException {
        return (Double) fetch(sig);
    }

    public float fetchFloat(ISig sig) throws DataSourceException {
        return (Float) fetch(sig);
    }

    public int fetchInt(ISig sig) throws DataSourceException {
        return (Integer) fetch(sig);
    }

    public String fetchString(ISig sig) throws DataSourceException {
        return (String) fetch(sig);
    }

    public String usageString() {
        return FieldStringPrettyPrint.prettyPrint(df);
    }

    private static class NodeSetupVisitor implements IDFVisitor<List<XML>, XML> {
        @Override
        public List<XML> defaultVisit(IDataField df, XML node) {
            return XMLInstantiator.instantiate(node);
        }

        @Override
        public List<XML> visitListField(ListField lf, XML node) {
            return node.getChildren(lf.getName());
        }

        @Override
        public List<XML> visitPrimField(PrimField pf, XML node) {
            return XMLInstantiator.instantiate(node.getChild(pf.getName()));
        }

        @Override
        public List<XML> visitCompField(CompField cf, XML node) {
            return XMLInstantiator.instantiate(node.getChild(cf.getName()));
        }
    }
}

interface IDataField {
    <T, U> T accept(IDFVisitor<T, U> visitor, U param);
}

class ListField implements IDataField {
    private String name;

    public ListField(String name) {
        this.name = name;
    }

import java.util.HashMap;
import java.util.Map;
import java.util.stream.Stream;

public class Writer {
    public static void main(String[] args) {
        Map<String, Object> baseData = new HashMap<>();
        baseData.put("name", "Rocket Skates");
        baseData.put("price", 12.75);
        baseData.put("color", "yellow");
        Map<String, Object> updateData = new HashMap<>();
        updateData.put("price", 15.25);
        updateData.put("color", "red");
        updateData.put("year", 1974);
        Map<String, Object> mergedData = new HashMap<>();
        Stream.concat(baseData.entrySet().stream(), updateData.entrySet().stream()).forEach(entry -> mergedData.put(entry.getKey(), entry.getValue()));
        mergedData.entrySet().forEach(entry -> System.out.println(entry));
    }
}

