class Cache {
    public int[][] searchRange(TreeNode root, int[] queries) {
        int[][] res = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int val = queries[i];
            int mini = -1, maxi = -1;
            while (root != null) {
                if (val >= root.val) {
                    maxi = root.val;
                    root = root.right;
                } else {
                    mini = root.val;
                    root = root.left;
                }
            }
            res[i] = new int[]{mini, maxi};
        }
        return res;
    }
}

