import com.rapidminer.example.Attribute;
import com.rapidminer.example.Example;
import com.rapidminer.example.ExampleSet;
import com.rapidminer.example.set.AttributeFilteredExampleSet;
import com.rapidminer.example.set.ExampleSetUtilities;
import com.rapidminer.operator.Operator;
import com.rapidminer.operator.OperatorDescription;
import com.rapidminer.operator.OperatorException;
import com.rapidminer.operator.ports.InputPort;
import com.rapidminer.operator.ports.OutputPort;
import com.rapidminer.tools.Ontology;
import com.rapidminer.tools.math.container.Range;

public class AbsoluteValueFilter extends Operator {

    private InputPort exampleSetInput = getInputPort("example set");
    private OutputPort exampleSetOutput = getOutputPort("example set");

    public AbsoluteValueFilter(OperatorDescription description) {
        super(description);
    }

    @Override
    public void doWork() throws OperatorException {
        ExampleSet exampleSet = exampleSetInput.getData();

        // Filter attributes to process only numerical ones
        AttributeFilteredExampleSet filteredSet = ExampleSetUtilities.viewFiltered(exampleSet, Ontology.NUMERICAL);

        // Process the filtered ExampleSet
        applyAbsoluteValue(filteredSet);

        exampleSetOutput.deliver(exampleSet);
    }

    private void applyAbsoluteValue(ExampleSet exampleSet) {
        for (Attribute attribute : exampleSet.getAttributes()) {
            if (attribute.isNumerical()) {
                double maxValue = 0.0;
                for (Example example : exampleSet) {
                    double value = example.getValue(attribute);
                    double absoluteValue = Math.abs(value);
                    example.setValue(attribute, absoluteValue);
                    maxValue = Math.max(maxValue, absoluteValue);
                }

                // Update the attribute's value range
                Range range = new Range(0.0, maxValue);
                attribute.getMetaData().setRange(range);
            }
        }
    }

    @Override
    public boolean writesIntoExistingData() {
        return true;
    }

}

import java.util.Arrays;
 
public class EgyptianDivision {
 
    public static void main(String[] args) {
        print(580, 34);
    }
 
    public static void print(long a, long b) {
        long x = egyptianDivision(a, b);
        System.out.println(a + " / " + b + " = " + x);
        assert a == b * x;
    }
 
    public static long egyptianDivision(long dividend, long divisor) {
        int SIZE = 64;
        long[] powers = new long[SIZE];
        long[] doublings = new long[SIZE];
        int i = 0;
 
        for (; i < SIZE; ++i) {
            powers[i] = 1 << i;
            doublings[i] = divisor << i;
            if (doublings[i] > dividend) {
                break;
            }
        }
 
        long answer = 0;
        long accumulator = 0;
 
        for (i = i - 1; i >= 0; --i) {
            /*
             * If the current value of the accumulator added to the
             * doublings cell would be less than or equal to the
             * dividend then add it to the accumulator
             */
            if (accumulator + doublings[i] <= dividend) {
                accumulator += doublings[i];
                answer += powers[i];
            }
        }
 
        return answer;
    }
}

class Queue {
    public int leastOpsExpressTarget(int x, int target) {
        return leastOpsExpressTarget0(x, target);
    }

    public int leastOpsExpressTarget0(int x, int target)
    {
        int[] parts = new int[32];
        for(int i = 0; i < 32; i++)
        {
            parts[i] = target % x;
            target /= x;
        }

        int[][] dp = new int[32][2];
        dp[31][0] = 0;
        dp[31][1] = 31;

        for(int i = 30; i >= 0; i--)
        {
            int signNeed = i;
            if(i == 0)
            {
                signNeed = 1 + 1;
            }

            int need = parts[i];

            int p0 = dp[i + 1][0] == 0 ? -1 : dp[i + 1][0];
            int p1 = dp[i + 1][1] == 0 ? -1 : dp[i + 1][1];

            dp[i][0] = Math.min(p0 + signNeed * need,
                               p1 + signNeed * (x - need));
            dp[i][0] = Math.max(dp[i][0], 0);
            dp[i][1] = Math.min(p0 + signNeed * (need + 1),
                               p1 + signNeed * (x - need - 1));
            dp[i][1] = Math.max(dp[i][1], 0);
        }
        System.out.println(Arrays.toString(parts));
        System.out.println(Arrays.deepToString(dp));

        return dp[0][0];
    }
}

import java.sql.CallableStatement;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

import org.geolatte.geom.Geometry;
import org.hibernate.type.descriptor.ValueBinder;
import org.hibernate.type.descriptor.ValueExtractor;
import org.hibernate.type.descriptor.WrapperOptions;
import org.hibernate.type.descriptor.java.JavaTypeDescriptor;
import org.hibernate.type.descriptor.sql.BasicBinder;
import org.hibernate.type.descriptor.sql.BasicExtractor;
import org.hibernate.type.descriptor.sql.SqlTypeDescriptor;

public class GeoDBGeometryTypeDescriptor implements SqlTypeDescriptor {

    public static final GeoDBGeometryTypeDescriptor INSTANCE = new GeoDBGeometryTypeDescriptor();

    @Override
    public int getSqlType() {
        return java.sql.Types.VARBINARY; // Or BLOB, depending on the GeoDB configuration
    }

    @Override
    public boolean canBeRemapped() {
        return true;
    }

    @Override
    public <X> ValueBinder<X> getBinder(JavaTypeDescriptor<X> javaTypeDescriptor) {
        return new BasicBinder<X>(javaTypeDescriptor, this) {
            @Override
            protected void doBind(PreparedStatement st, X value, int index, WrapperOptions options) throws SQLException {
                Geometry geometry = (Geometry) value;
                byte[] wkb = GeoDbWkb.toWkb(geometry);
                st.setBytes(index, wkb);
            }
        };
    }

    @Override
    public <X> ValueExtractor<X> getExtractor(JavaTypeDescriptor<X> javaTypeDescriptor) {
        return new BasicExtractor<X>(javaTypeDescriptor, this) {
            @Override
            protected X doExtract(ResultSet rs, String name, WrapperOptions options) throws SQLException {
                byte[] wkb = rs.getBytes(name);
                if (wkb == null) {
                    return null;
                }

                Geometry geometry = GeoDbWkb.fromWkb(wkb);
                return (X) geometry;
            }

            @Override
            protected X doExtract(CallableStatement statement, int index, WrapperOptions options) throws SQLException {
                byte[] wkb = statement.getBytes(index);
                  if (wkb == null) {
                    return null;
                }

                Geometry geometry = GeoDbWkb.fromWkb(wkb);
                return (X) geometry;
            }
        };
    }
}

public void marshalToXml(Object obj, File file) throws JAXBException {
    JAXBContext jaxbContext = JAXBContext.newInstance(obj.getClass());
    Marshaller marshaller = jaxbContext.createMarshaller();
    marshaller.setProperty(Marshaller.JAXB_FORMATTED_OUTPUT, true);
    marshaller.marshal(obj, file);
}

import javax.inject.Inject;
import java.util.List;

public class ReportSynthesisGovernanceManagerImpl implements ReportSynthesisGovernanceManager {

    private final ReportSynthesisGovernanceDAO reportSynthesisGovernanceDAO;

    @Inject
    public ReportSynthesisGovernanceManagerImpl(ReportSynthesisGovernanceDAO reportSynthesisGovernanceDAO) {
        this.reportSynthesisGovernanceDAO = reportSynthesisGovernanceDAO;
    }

    @Override
    public ReportSynthesisGovernance saveReportSynthesisGovernance(ReportSynthesisGovernance entity) {
        return reportSynthesisGovernanceDAO.save(entity);
    }

    @Override
    public void deleteReportSynthesisGovernance(Long id) {
        reportSynthesisGovernanceDAO.delete(id);
    }

    @Override
    public boolean existReportSynthesisGovernance(Long id) {
        return reportSynthesisGovernanceDAO.existsById(id);
    }

    @Override
    public List<ReportSynthesisGovernance> findAll() {
        return reportSynthesisGovernanceDAO.findAll();
    }

    @Override
    public ReportSynthesisGovernance getReportSynthesisGovernanceById(Long id) {
        return reportSynthesisGovernanceDAO.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("No governance report found with ID: " + id));
    }

    @Override
    public ReportSynthesisGovernance updateReportSynthesisGovernance(Long id, ReportSynthesisGovernance updatedEntity) {
        if (!reportSynthesisGovernanceDAO.existsById(id)) {
            throw new IllegalArgumentException("Cannot update non-existent governance report with ID: " + id);
        }
        updatedEntity.setId(id);
        return reportSynthesisGovernanceDAO.save(updatedEntity);
    }

    @Override
    public List<ReportSynthesisGovernance> findByStatus(String status) {
        return reportSynthesisGovernanceDAO.findByApprovalStatus(status);
    }

    @Override
    public void batchSave(List<ReportSynthesisGovernance> entities) {
        reportSynthesisGovernanceDAO.saveAll(entities);
    }

    @Override
    public void softDeleteReportSynthesisGovernance(Long id) {
        ReportSynthesisGovernance entity = getReportSynthesisGovernanceById(id);
        entity.setDeleted(true);
        reportSynthesisGovernanceDAO.save(entity);
    }
}

interface ReportSynthesisGovernanceManager {
    ReportSynthesisGovernance saveReportSynthesisGovernance(ReportSynthesisGovernance entity);
    void deleteReportSynthesisGovernance(Long id);
    boolean existReportSynthesisGovernance(Long id);
    List<ReportSynthesisGovernance> findAll();

