    }
}

class MemOrderBook {
    private final CopyOnWriteArrayList<LimitOrder> list = new CopyOnWriteArrayList<>();
    private final ConcurrentHashMap<String, LimitOrder> map = new ConcurrentHashMap<>();
    private static final int LIMIT = 100;
    private final PersistOrderBook persistOrderBook = new PersistOrderBook();

    public synchronized void put(LimitOrder order) {
        if (list.size() >= LIMIT) {
            LimitOrder oldestOrder = list.remove(0);
            persistOrderBook.persistOrder(oldestOrder);
            map.remove(oldestOrder.getOrderId());
        }
        list.add(order);
        map.put(order.getOrderId(), order);
        Collections.sort(list, Comparator.comparingDouble(LimitOrder::getPrice));
    }

    public synchronized void cancel(String orderId) {
        LimitOrder order = map.get(orderId);
        if (order != null && !order.isCancelled()) {
            order.cancel();
            map.remove(orderId);
            list.remove(order);
        }
    }

    public synchronized void update(String orderId, int newAmount) {
