import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

/**
 * A byte array, wrapped in a {@link org.xbib.web.util.BytesReference}.
 */
public class BytesArray implements BytesReference {

    private static final String EMPTY_STRING = "";

    private byte[] bytes;

    private int offset;

    private int length;

    /**
     * Create {@link BytesArray} from a byte array.
     * @param bytes the byte array
     */
    public BytesArray(byte[] bytes) {
        this.bytes = bytes;
        this.offset = 0;
        this.length = bytes.length;
    }

    /**
     * Create {@link BytesArray} from a part of a byte array.
     * @param bytes the byte array
     * @param offset the offset
     * @param length the length
     */
    public BytesArray(byte[] bytes, int offset, int length) {
        this.bytes = bytes;
        this.offset = offset;
        this.length = length;
    }

    public void write(byte[] b) {
        byte[] c = new byte[length + b.length];
        System.arraycopy(bytes, 0, c, 0, length);
        System.arraycopy(b, 0, c, bytes.length, b.length);
        this.bytes = c;
        this.offset = 0;
        this.length = c.length;
    }

    @Override
    public byte get(int index) {
        return bytes[offset + index];
    }

    @Override
    public int length() {
        return length;
    }

    @Override
    public int indexOf(byte b, int offset, int len) {
        if (offset < 0 || (offset + length) > this.length) {
            throw new IllegalArgumentException();
        }
        for (int i = offset; i < offset + len; i++) {
            if (bytes[i] == b) {
                return i;
            }
        }
        return -1;
    }

    @Override
    public BytesReference slice(int from, int length) {
        if (from < 0 || (from + length) > this.length) {
            throw new IllegalArgumentException("can't slice a buffer with length [" + this.length +
                    "], with slice parameters from [" + from + "], length [" + length + "]");
        }
        return new BytesArray(bytes, offset + from, length);
    }

    @Override
    public byte[] toBytes() {
        if (offset == 0 && bytes.length == length) {
            return bytes;
        }
        return Arrays.copyOfRange(bytes, offset, offset + length);
    }

    @Override
    public String toUtf8() {
        if (length == 0) {
            return EMPTY_STRING;
        }
        return new String(bytes, offset, length, StandardCharsets.UTF_8);
    }
}

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.hateoas.EntityModel;
import org.springframework.hateoas.Link;
import org.springframework.hateoas.Links;
import org.springframework.hateoas.RepresentationModel;
import java.io.IOException;

public class ResourceDeserializer extends JsonDeserializer<EntityModel<?>> implements ContextualDeserializer {

    private final JavaType contentType;

    public ResourceDeserializer(JavaType contentType) {
        this.contentType = contentType;
    }

    public ResourceDeserializer() {
        this.contentType = null;
    }

    @Override
    public EntityModel<?> deserialize(JsonParser jp, DeserializationContext ctxt) throws IOException, JsonProcessingException {

        ObjectMapper mapper = (ObjectMapper) jp.getCodec();
        ObjectNode root = mapper.readTree(jp);

        Links links = extractLinks(root);

        Class<?> resourceType = getResourceDeserializationType(links);
        Object content = deserializeContent(root, resourceType, mapper, ctxt);

        return EntityModel.of(content).add(links);
    }

    private Links extractLinks(ObjectNode root) {
        //Assume the links are stored in a "_links" field
        JsonNode linksNode = root.get("_links");
        if (linksNode != null && !linksNode.isNull()) {
            return Links.valueOf(linksNode.toString());
        }
        return Links.NONE;
    }

    private Class<?> getResourceDeserializationType(Links links) {
        // Use TypeResolver to determine resource type based on links.  Placeholder logic.
        if (links.hasLink("self")) {
            return String.class; // Example, replace with actual TypeResolver logic
        }
        return Object.class; // Default
    }

    private Object deserializeContent(ObjectNode root, Class<?> resourceType, ObjectMapper mapper, DeserializationContext ctxt) throws IOException {
        //Remove _links from the root before deserializing the content
        root.remove("_links");
        return mapper.treeToValue(root, resourceType);

    }

    @Override
    public JsonDeserializer<?> createContextual(DeserializationContext ctxt, BeanProperty property) throws JsonMappingException {
        JavaType contentType = property == null ? ctxt.getContextualType() : property.getType().containedType(0); // Assuming EntityModel<T>
        return new ResourceDeserializer(contentType);
    }
}

