import java.util.function.Function;
import java.util.stream.Stream;

public class Euler {
    public static void main(String[] args) {
        double k =.07;
        double tempRoom = 20.;
        double tempObject = 100.;
        Function<Double, Double> fcr = newCoolingRateDy(k, tempRoom);
        Function<Double, Double> analytic = newTempFunc(k, tempRoom, tempObject);
        for (double deltaTime : new double[]{2, 5, 10}) {
            System.out.printf("Step size = %.1f\n", deltaTime);
            System.out.println(" Time Euler's Analytic");
            double temp = tempObject;
            for (double time = 0.; time <= 100; time += deltaTime) {
                System.out.printf("%5.1f %7.3f %7.3f\n", time, temp, analytic.apply(time));
                temp = eulerStep(fcr, time, temp, deltaTime);
            }
            System.out.println();
        }
    }

    // fdy is a type for function f used in Euler's method.
    @FunctionalInterface
    interface Fdy {
        double apply(double x, double y);
    }

    // eulerStep computes a single new value using Euler's method.
    // Note that step size h is a parameter, so a variable step size
    // could be used.
    static double eulerStep(Fdy f, double x, double y, double h) {
        return y + h * f.apply(x, y);
    }

    // Definition of cooling rate.  Note that this has general utility and
    // is not specific to use in Euler's method.

    // newCoolingRate returns a function that computes cooling rate
    // for a given cooling rate constant k.
    static Function<Double, Double> newCoolingRate(double k) {
        return deltaTemp -> -k * deltaTemp;
    }

    // newTempFunc returns a function that computes the analytical solution
    // of cooling rate integrated over time.
    static Function<Double, Double> newTempFunc(double k, double ambientTemp, double initialTemp) {
        return time -> ambientTemp + (initialTemp - ambientTemp) * Math.exp(-k * time);
    }

    // newCoolingRateDy returns a function of the kind needed for Euler's method.
    // That is, a function representing dy(x, y(x)).
    //
    // Parameters to newCoolingRateDy are cooling constant k and ambient
    // temperature.
    static Fdy newCoolingRateDy(double k, double ambientTemp) {
        Function<Double, Double> crf = newCoolingRate(k);
        // note that result is dependent only on the object temperature.
        // there are no additional dependencies on time, so the x parameter
        // provided by eulerStep is unused.
        return (x, objectTemp) -> crf.apply(objectTemp - ambientTemp);
    }
}

public static int moveBytes(byte[] b1, byte[] b2) {
    int length = Math.min(b1.length, b2.length); // Find the minimum length between b1 and b2
    System.arraycopy(b1, 0, b2, 0, length); // Copy the bytes from b1 to b2
    return length; // Return the number of bytes moved
}

