 * This reply from server means this client currently isn't allowed to connect.
 *
 */
public class SOCRejectConnection extends SOCMessage
{
    private static final long serialVersionUID = 100L;  // last structural change v1.0.0 or earlier

    /**
     * Text message
     */
    private String text;

    /**
     * Create a RejectConnection message.
     *
     * @param message   the text message
     */
    public SOCRejectConnection(String message)
    {
        messageType = REJECTCONNECTION;
        text = message;
    }

    /**
     * @return the text message
     */
    public String getText()
    {
        return text;
    }

    /**
     * REJECTCONNECTION sep text
     *
     * @return the command String
     */
    public String toCmd()
    {
        return toCmd(text);
    }

    /**
     * REJECTCONNECTION sep text
     *
     * @param tm  the text message
     * @return    the command string
     */
    public static String toCmd(String tm)
    {
        return REJECTCONNECTION + sep + tm;
    }

    /**
     * Parse the command String into a RejectConnection message
     *
     * @param s   the String to parse; will be directly used as {@link #getText()} without any parsing
     * @return    a RejectConnection message
     */
    public static SOCRejectConnection parseDataStr(String s)
    {
        return new SOCRejectConnection(s);
    }

    /**
     * @return a human readable form of the message
     */
    public String toString()
    {
        return "SOCRejectConnection:" + text;
    }

}

public static void replaceCodeBetweenLines(String code, int startLine, int endLine, String newCode) {
    String[] lines = code.split("\n");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < lines.length; i++) {
        if (i + 1 >= startLine && i + 1 <= endLine) {
            // Ignore the original code between start and end lines, and replace it with the new code
            result.append(newCode).append('\n');
        } else {
            // Otherwise, keep the original line
            result.append(lines[i]).append('\n');
        }
    }
    System.out.println(result); // or return the modified code as a string if you prefer
}

import java.util.List;
 
public class ShoelaceFormula {
    private static class Point {
        int x, y;
 
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
 
        @Override
        public String toString() {
            return String.format("(%d, %d)", x, y);
        }
    }
 
    private static double shoelaceArea(List<Point> v) {
        int n = v.size();
        double a = 0.0;
        for (int i = 0; i < n - 1; i++) {
            a += v.get(i).x * v.get(i + 1).y - v.get(i + 1).x * v.get(i).y;
        }
        return Math.abs(a + v.get(n - 1).x * v.get(0).y - v.get(0).x * v.get(n - 1).y) / 2.0;
    }
 
    public static void main(String[] args) {
        List<Point> v = List.of(
            new Point(3, 4),
            new Point(5, 11),
            new Point(12, 8),
            new Point(9, 5),
            new Point(5, 6)
        );
        double area = shoelaceArea(v);
        System.out.printf("Given a polygon with vertices %s,%n", v);
        System.out.printf("its area is %f,%n", area);
    }
}

import java.util.Scanner;

public class VowelConsonantCounter {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a string: ");
        String str = input.nextLine().toLowerCase(); // convert all letters to lowercase

        int vowelCount = 0;
        int consonantCount = 0;

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
                vowelCount++;
            } else if (ch >= 'a' && ch <= 'z') {
                consonantCount++;
            }
        }

        System.out.println("The number of vowels is " + vowelCount);
        System.out.println("The number of consonants is " + consonantCount);
    }
}

import java.util.*;
import java.io.*;
import java.math.*;

public class Handler {

    Scanner in = new Scanner(System.in);
    PrintWriter pw = new PrintWriter(System.out);

    public static void main(String[] args) throws IOException {
        new Handler().run();
    }

    private void run() throws IOException {
