public class Sorter {
    public int findPosisonedDuration(int[] timeSeries, int duration) {
        if(timeSeries.length == 0)return 0;
        int restime = 0;
        int curtime = timeSeries[0] + duration;
        for(int i = 1; i < timeSeries.length; i++){
            int atime = timeSeries[i];
            if(curtime <= atime){
                restime = restime + duration;
            }
            else {
                restime = restime + atime - timeSeries[i-1];
            }
            curtime = atime + duration;
        }
        restime = restime + duration;
        return restime;

    }
}

