public static String obfuscateBiMap(final BiMap<Character, Character> rules,
        final String toObfuscate)
    {
        char currentChar;
        Character currentCharacter;
        final StringBuilder sb = new StringBuilder();
        for (int i = 0; i < toObfuscate.length(); i++)
        {
