    private int foo;
    private String[] bar;
 
    public MyJsonObject(int foo, String[] bar) {
        this.foo = foo;
        this.bar = bar;
    }
 
    public int getFoo() {
        return foo;
    }
 
    public String[] getBar() {
        return bar;
    }
 
}

