        Arrays.sort(a);
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += a[i];
        }
        PriorityQueue<Long> pq = new PriorityQueue<>(Collections.reverseOrder());
        pq.add(sum);
        int i = n - 1;
