public class IntArrayWorker {
    private int[][] matrix;

    public void setMatrix(int[][] theMatrix) {
        matrix = theMatrix;
    }

    public int getSum() {
        int total = 0;
        for (int[] row : matrix) {
            for (int value : row) {
                total += value;
            }
        }
        return total;
    }

    public void fillSequential() {
        int count = 1;
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                matrix[i][j] = count++;
            }
        }
    }

    public void printMatrix() {
        for (int[] row : matrix) {
            for (int value : row) {
                System.out.printf("%4d", value);
            }
            System.out.println();
        }
    }

    public int countOccurrences(int target) {
        int count = 0;
        for (int[] row : matrix) {
            for (int value : row) {
                if (value == target) {
                    count++;
                }
            }
        }
        return count;
    }

    public int getColumnTotal(int colIndex) {
        int total = 0;
        if (colIndex < matrix[0].length) {
            for (int[] row : matrix) {
                total += row[colIndex];
            }
        }
        return total;
    }

    public int getLargest() {
        int largest = Integer.MIN_VALUE;
        for (int[] row : matrix) {
            for (int value : row) {
                if (value > largest) {
                    largest = value;
                }
            }
        }
        return largest;
    }

    public void fillPattern() {
        for (int i = 0; i < matrix.length; i++) {
            for (int j = 0; j < matrix[i].length; j++) {
                if ((i + j) % 2 == 0) {
                    matrix[i][j] = 1;
                } else {
                    matrix[i][j] = 0;
                }
            }
        }
    }

    public static void main(String[] args) {
        IntArrayWorker worker = new IntArrayWorker();
        int[][] myMatrix = new int[5][5];

        worker.setMatrix(myMatrix);
        worker.fillSequential();
        System.out.println("Matrix filled with sequential values:");
        worker.printMatrix();

        System.out.println("Total of all elements: " + worker.getSum());

        int targetValue = 10;
        System.out.println("Occurrences of " + targetValue + ": " + worker.countOccurrences(targetValue));

        int columnIndex = 2;
        System.out.println("Total of column " + columnIndex + ": " + worker.getColumnTotal(columnIndex));

