    public static void main(String[] args) throws IOException {

        int t = input.nextInt();

        StringBuilder output = new StringBuilder();

        while(t > 0) {

            n = input.nextInt();

            m = input.nextInt();

            grid = new char[n][];

            for(int i = 0; i < n; ++i) {

                grid[i] = input.next().toCharArray();

            }

            int row = 0, column = 0;

            for(int r = 0; r < n; ++r) {

                for(int c = 0; c < m; ++c) {

                    if(grid[r][c] == 'L') {

                        row = r;

                        column = c;

                        break;

                    }

                }

            }

            bfs(row, column);

            for(int r = 0; r < n; ++r) {

                for(int c = 0; c < m; ++c) {

                    if(r == row && c == column) {

                        output.append('L');

                    } else {

                        output.append(grid[r][c]);

                    }

                }

                output.append('\n');

            }

            --t;

        }

        System.out.print(output);

    }

    static void bfs(int row, int column) {

        Queue<int[]> queue = new LinkedList<int[]>();

        grid[row][column] = '+';

        boolean[][] inQueue = new boolean[n][m];

        for(int[] move : moves) {

            int r = row+move[0], c = column+move[1];

            if(inRange(r, c) && grid[r][c] == '.') {

                queue.add(new int[]{r, c});

                inQueue[r][c] = true;

            }

        }

        int[] node;

        int r, c;

        while(! queue.isEmpty()) {

            node = queue.poll();

            inQueue[node[0]][node[1]] = false;

            int count = 0;

            for(int[] move : moves) {

                r = node[0]+move[0];

                c = node[1]+move[1];

                if(inRange(r, c) && grid[r][c] == '.') {

                    ++count;

                }

            }

            if(count <= 1) {

                grid[node[0]][node[1]] = '+';

                for(int[] move : moves) {

                    r = node[0]+move[0];

