/**
 * time complexity O(m) (ms)
 * space complexity O(1)
 */
public class Account {
    public int maxDistance(int[][] arrays) {
        int[] min = {Integer.MAX_VALUE, -1}, min2 = {Integer.MAX_VALUE, -1};
        int[] max = {Integer.MIN_VALUE, -1}, max2 = {Integer.MIN_VALUE, -1};
        for (int i = 0; i < arrays.length; i++) {
            if (arrays[i][0] < min2[0]) {
                if (arrays[i][0] < min[0]) {
                    min2[0] = min[0];
                    min2[1] = min[1];
                    min[0] = arrays[i][0];
                    min[1] = i;
                } else {
                    min2[0] = arrays[i][0];
                    min2[1] = i;
                }
            }
            if (arrays[i][arrays[i].length - 1] > max2[0]) {
                if (arrays[i][arrays[i].length - 1] > max[0]) {
                    max2[0] = max[0];
                    max2[1] = max[1];
                    max[0] = arrays[i][arrays[i].length - 1];
                    max[1] = i;
                } else {
                    max2[0] = arrays[i][arrays[i].length - 1];
                    max2[1] = i;
                }
            }
        }
        return max[1] == min[1] ? Math.max(Math.abs(max[0] - min2[0]), Math.abs(max2[0] - min[0])): Math.abs(max[0] - min[0]);
    }
}

