class Reader {
    public int numberOfWays(int startPos, int endPos, int k) {
        int dis=endPos-startPos;
        if (dis<0){
            dis=-dis;
        }
        if ((k-dis)%2==1|| k<dis){
            return 0;
        }
        long mod=1000000007;
        int le=(k-dis)/2;
        long[][] yh=new long[k+1][k+1];
        yh[1][0]=1;yh[1][1]=1;
        for (int i=2;i<=k;i++){
            yh[i][0]=1;
            for (int j=1;j<=i;j++){
                yh[i][j]=yh[i-1][j-1]+yh[i-1][j];
                yh[i][j]%=mod;
            }
        }
        return (int)yh[k][le];
    }
}

