import com.amazonaws.transform.JsonUnmarshallerContext;
import com.amazonaws.transform.Unmarshaller;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;

public class UpdateDomainContactResultUnmarshaller implements Unmarshaller<UpdateDomainContactResult, JsonUnmarshallerContext> {

    private static UpdateDomainContactResultUnmarshaller instance;

    public UpdateDomainContactResult unmarshall(JsonUnmarshallerContext context) throws Exception {
        UpdateDomainContactResult result = new UpdateDomainContactResult();
        JsonParser parser = context.getJsonParser();
        int originalDepth = parser.getCurrentDepth();

        while (true) {
            JsonToken token = parser.nextToken();
            if (token == null) {
                break;
            }

            if (token == JsonToken.FIELD_NAME) {
                String fieldName = parser.getCurrentName();
                token = parser.nextToken();

                if ("OperationId".equals(fieldName)) {
                    String operationId = parser.getText();
                    result.setOperationId(operationId);
                } else {
                    parser.skipChildren();
                }
            } else if (token == JsonToken.START_OBJECT || token == JsonToken.START_ARRAY) {
                parser.skipChildren();
            }

            if (parser.getCurrentDepth() <= originalDepth) {
                break;
            }
        }

        return result;
    }

    public static UpdateDomainContactResultUnmarshaller getInstance() {
        if (instance == null) {
            instance = new UpdateDomainContactResultUnmarshaller();
        }
        return instance;
    }
}

public static <T> AsyncCallback<T> disabler (AsyncCallback<T> callback,
                                                 final HasEnabled... disablees)
    {
        for (HasEnabled widget : disablees) {
            widget.setEnabled(false);
        }
        return new ChainedCallback<T, T>(callback) {
            @Override public void onSuccess (T result) {
                for (HasEnabled widget : disablees) {
                    widget.setEnabled(true);
                }
                forwardSuccess(result);
            }
            @Override public void onFailure (Throwable cause) {
                for (HasEnabled widget : disablees) {
                    widget.setEnabled(true);
                }
                super.onFailure(cause);
            }
        };
    }

