public final class CloseableIterators {

    private CloseableIterators() {}

    public static <T> CloseableIterator<T> concat(Iterable<? extends CloseableIterator<? extends T>> iterators) {
        return wrap(Iterators.concat(Iterators.transform(iterators.iterator(), iterator -> iterator)), () -> {
            for (CloseableIterator<?> iterator : iterators) {
                iterator.close();
            }
        });
    }

    public static <T> CloseableIterator<T> mergeSorted(
            List<? extends CloseableIterator<? extends T>> sortedIterators,
            Comparator<? super T> comparator
    ) {
        Preconditions.checkArgument(!sortedIterators.isEmpty(), "Cannot merge empty list of iterators");
        return new CloseableIterator<T>() {
            private final PriorityQueue<PeekingIterator<T>> queue = new PriorityQueue<>(
                    sortedIterators.size(),
                    (a, b) -> comparator.compare(a.peek(), b.peek())
            );

            {
                for (Iterator<? extends T> iterator : sortedIterators) {
                    if (iterator.hasNext()) {
                        queue.offer(new PeekingIterator<>(iterator));
                    }
                }
            }

            @Override
            public boolean hasNext() {
                return !queue.isEmpty();
            }

            @Override
            public T next() {
                if (!hasNext()) {
                    throw new NoSuchElementException();
                }
                PeekingIterator<T> top = queue.poll();
                T result = top.next();
                if (top.hasNext()) {
                    queue.offer(top);
                }
                return result;
            }

            @Override
            public void close() throws IOException {
                List<IOException> exceptions = new ArrayList<>();
                for (CloseableIterator<?> iterator : sortedIterators) {
                    try {
                        iterator.close();
                    } catch (IOException e) {
                        exceptions.add(e);
                    }

