public abstract class GenericAssembler<SOURCE, TARGET> {
    private final Class<SOURCE> classSource;
    private final Class<TARGET> classTarget;
    private static final Logger logger = LoggerFactory.getLogger(GenericAssembler.class);

    protected GenericAssembler(Class<SOURCE> classSource, Class<TARGET> classTarget) {
        this.classSource = classSource;
        this.classTarget = classTarget;
    }

    protected abstract TARGET convert(SOURCE source);

    public List<TARGET> assemble(Collection<SOURCE> sourceCollection) {
        List<TARGET> targetList = new ArrayList<>();
        if (sourceCollection == null || sourceCollection.isEmpty()) {
            return targetList;
        }
        for (SOURCE sourceItem : sourceCollection) {
            try {
                TARGET targetItem = convert(sourceItem);
                targetList.add(targetItem);
            } catch (Exception e) {
                logger.error("Error converting item: {}", sourceItem, e);
            }
        }
        return targetList;
    }

    public TARGET[] assemble(SOURCE[] sourceArray) {
        if (sourceArray == null || sourceArray.length == 0) {
            return (TARGET[]) Array.newInstance(classTarget, 0);
        }
        TARGET[] targetArray = (TARGET[]) Array.newInstance(classTarget, sourceArray.length);
        for (int i = 0; i < sourceArray.length; i++) {
            try {
                targetArray[i] = convert(sourceArray[i]);
            } catch (Exception e) {
                logger.error("Error converting item at index {}: {}", i, sourceArray[i], e);
            }
        }
        return targetArray;
    }

    protected SOURCE createSourceInstance() {
        try {
            return classSource.getDeclaredConstructor().newInstance();
        } catch (InstantiationException | IllegalAccessException |
                 InvocationTargetException | NoSuchMethodException e) {
            logger.error("Error creating source instance", e);
            return null;
        }
    }

    protected TARGET createTargetInstance() {
        try {
            return classTarget.getDeclaredConstructor().newInstance();
        } catch (InstantiationException | IllegalAccessException |
                 InvocationTargetException | NoSuchMethodException e) {

