class PathStep extends Step<List<Object>, List<Object>> {
    public PathStep(FaunusPipeline pipeline) {
        super(pipeline);
    }

    @Override
    public List<Object> processNextStart() {
        List<Object> path = new ArrayList<>();
        Object current = this.starts.next();
        path.add(current);
        while (this.starts.hasNext()) {
            current = this.starts.next();
            path.add(current);
        }
        return path;
    }
}

class Counter {
    public int minLength(String s) {
        boolean b = true;
        while (b) {
            b = false;
            int ab = s.indexOf("AB");
            if (ab >= 0) {
                s = s.substring(0, ab) + s.substring(ab + 2);
                b = true;
            }
            int cd = s.indexOf("CD");
            if (cd >= 0) {
                s = s.substring(0, cd) + s.substring(cd + 2);
                b = true;
            }
        }
        return s.length();
    }
}

public class Program {
    static double[][] points = { { -1, 0, 3 }, { -1, -1, -1 }, { 4, 1, 1 }, { 2, 0.5, 9 }, { 3.5, 2, -1 },
            { 3, 1.5, 3 }, { -1.5, 4, 2 }, { 5.5, 4, -0.5 } };

    public static void main(String[] args) {
        findDistance3D();
    }

    public static void findDistance3D() {

        int p1 = 0, p2 = 1, p3 = 2; // Initial 2 points
        double shortestDistance = distance(points[p1][0], points[p1][1], points[p2][0], points[p2][1], points[p3][0],
                points[p3][1]);

        // Compute distance for every 2 points
        for (int i = 0; i < points.length; i++) {
            for (int j = i + 1; j < points.length; j++) {
                double distance = distance(points[i][0], points[i][1], points[i][2], points[j][0], points[j][1],
                        points[j][2]);
                if (shortestDistance > distance) {
                    p1 = i;
                    p2 = j;
                    p3 = j;
                    shortestDistance = distance; // Update shortestDistance
                }
            }
        }

        System.out.println("The closest 2 points are " + "(" + points[p1][0] + ", " + points[p1][1] + ", "
                + points[p1][2] + ") and (" + points[p2][0] + ", " + points[p2][1] + ", " + points[p2][2] + ")");
    }

    public static double distance(double x1, double y1, double z1, double x2, double y2, double z2) {
        return Math.sqrt(((x2 - x1) * (x2 - x1)) + ((y2 - y1) * (y2 - y1)) + ((z2 - z1) * (z2 - z1)));
    }

}

public class ModularArithmetic {
    private interface Ring<T> {
        Ring<T> plus(Ring<T> rhs);
 
        Ring<T> times(Ring<T> rhs);
 
        int value();
 
        Ring<T> one();
 
        default Ring<T> pow(int p) {
            if (p < 0) {
                throw new IllegalArgumentException("p must be zero or greater");
            }
 
            int pp = p;
            Ring<T> pwr = this.one();
            while (pp-- > 0) {
                pwr = pwr.times(this);
            }
            return pwr;
        }
    }
 
    private static class ModInt implements Ring<ModInt> {
        private int value;
        private int modulo;
 
        private ModInt(int value, int modulo) {
            this.value = value;
            this.modulo = modulo;
        }
 
        @Override
        public Ring<ModInt> plus(Ring<ModInt> other) {
            if (!(other instanceof ModInt)) {
                throw new IllegalArgumentException("Cannot add an unknown ring.");
            }
            ModInt rhs = (ModInt) other;
            if (modulo != rhs.modulo) {
                throw new IllegalArgumentException("Cannot add rings with different modulus");
            }
            return new ModInt((value + rhs.value) % modulo, modulo);
        }
 
        @Override
        public Ring<ModInt> times(Ring<ModInt> other) {
            if (!(other instanceof ModInt)) {
                throw new IllegalArgumentException("Cannot multiple an unknown ring.");
            }
            ModInt rhs = (ModInt) other;
            if (modulo != rhs.modulo) {
                throw new IllegalArgumentException("Cannot multiply rings with different modulus");
            }
            return new ModInt((value * rhs.value) % modulo, modulo);
        }
 
        @Override
        public int value() {
            return value;
        }
 
        @Override
        public Ring<ModInt> one() {
            return new ModInt(1, modulo);
        }
 
        @Override
        public String toString() {
            return String.format("ModInt(%d, %d)", value, modulo);
        }
    }
 
    private static <T> Ring<T> f(Ring<T> x) {
        return x.pow(100).plus(x).plus(x.one());
    }
 
    public static void main(String[] args) {
        ModInt x = new ModInt(10, 13);
        Ring<ModInt> y = f(x);
        System.out.print("x ^ 100 + x + 1 for x = ModInt(10, 13) is ");
        System.out.println(y);
        System.out.flush();
    }
}

