import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;
 
public class Processor {
 
    public static boolean isPrime(int number) {
        int limit = (int) Math.sqrt(number) + 1;
 
        // We test if the number is divisible by any number up to the limit
        return number >= 2 && IntStream.range(2, limit).noneMatch(x -> number % x == 0);
    }
 
    public static void main(String[] args) {
        List<Integer> primes = new ArrayList<>();
        for (int i = 0; i < 100; i++) {
            if (isPrime(i)) {
                primes.add(i);
            }
        }
        System.out.println("Primes below 100:\n" + primes);
    }
}

