  public String getSourceElement(@NotNull Element element) {
    if (element.getName().equals("inspection_tool")) {
      String shortName = element.getAttributeValue("shortName");
      if (shortName != null) {
        for (String oldSourceName : OLD_SOURCE_NAMES) {
          if (oldSourceName.equals(shortName)) {
            return shortName;
          }
        }
      }
    }
    return null;
  }

  @NotNull
  @Override
  public Set<String> getSuppressIds() {
    return ImmutableSet.copyOf(getSourceToolNames());
  }

  @Override
  public void performOldMergerCleanup(@NotNull Element root) {
    //check whether old merger already exist
    for (Element element : root.getChildren("inspection_tool")) {
      if (OLD_MERGER_NAME.equals(element.getAttributeValue("shortName"))) {
        return;
      }
    }

    //check whether sources already merged by another name
    for (String oldSourceName : OLD_SOURCE_NAMES) {
      for (Element element : root.getChildren("inspection_tool")) {
        if (oldSourceName.equals(element.getAttributeValue("shortName"))) {
          return;
        }
      }
    }

    //now create new merged
    Element element = new Element("inspection_tool");
    element.setAttribute("class", "StringOperationCanBeSimplified");
    element.setAttribute("enabled", "true");
    element.setAttribute("level", "WARNING");
    element.setAttribute("enabled_by_default", "true");
    element.setAttribute("group_id", "Performance issues");
    element.setAttribute("group_display_name", "Performance issues");
    element.setAttribute("shortName", OLD_MERGER_NAME);
    element.setAttribute("displayName", "Redundant string operation");
    root.addContent(element);

