import java.util.Scanner;

/*
 * Girilen bir tam sayinin tersten okundugunda da ayni olup olmadigini,
 * yani palindrom olup olmadigini test eder.
 */

public class PalindromKontrol {

    // Sayiyi tersine cevirip orijinaliyle karsilastirarak palindrom kontrolu yapar
    public static boolean palindromMu(int deger) {

        int orijinalDeger = deger;
        int tersCevrilmisDeger = 0;

        for (int kalan = deger; kalan > 0; kalan /= 10) {
            int sonRakam = kalan % 10;
            tersCevrilmisDeger = (tersCevrilmisDeger * 10) + sonRakam;
        }

        return orijinalDeger == tersCevrilmisDeger;
    }

    public static void main(String[] args) {

        Scanner girisAraci = new Scanner(System.in);
        System.out.print("Bir sayi girin: ");
        int girilenSayi = girisAraci.nextInt();
        girisAraci.close();

        if (palindromMu(girilenSayi)) {
            System.out.println(girilenSayi + " bir palindromdur.");
        } else {
            System.out.println(girilenSayi + " bir palindrom degildir.");
        }
    }
}

