public class DogrusalArama {

    void ara(int[] veri, int hedef) {
        boolean eslesmeVarMi = false;

        for (int idx = 0; idx < veri.length; idx++) {
            if (veri[idx] == hedef) {
                eslesmeVarMi = true;
                System.out.println("Aranan oge bulundu: Indis " + idx);
                break;
