    public LoadedBuild load() {
        String basePath = "chromium-browser-snapshots/Linux_x64/";
        BuildDirVisitor dirVisitor = new BuildDirVisitor();
        googleStorage.listResources(basePath, dirVisitor);
        int maxBuild = dirVisitor.getMaxBuild();

        if (maxBuild == -1) throw new RuntimeException("No valid build directories");
        String buildPath = basePath + maxBuild + "/";

        ZipVisitor zipVisitor = new ZipVisitor();
        googleStorage.listResources(buildPath, zipVisitor);
        String zipName = zipVisitor.getZipName();

        if (zipName == null) throw new RuntimeException("No ZIP found in build " + maxBuild);
        File zipFile = downloadHelper.download(buildPath + zipName);
        File chromeBinary = downloadHelper.processArchive(zipFile);

        return new LoadedBuildImpl(chromeBinary, maxBuild);
    }

