import java.util.Arrays;
 
public class LongMultiplication {
 
    // argument validation
    private static byte d(byte b) {
        if (b < '0' || b > '9') {
            throw new IllegalArgumentException("digit 0-9 expected");
        }
        return (byte) (b - '0');
    }
 
    // add two numbers as strings
    private static String add(String x, String y) {
        if (y.length() > x.length()) {
            String tmp = x;
            x = y;
            y = tmp;
        }
        byte[] b = new byte[x.length() + 1];
        byte c = 0;
        for (int i = 1; i <= x.length(); i++) {
            if (i <= y.length()) {
                c += d(y.charAt(y.length() - i));
            }
            int s = d(x.charAt(x.length() - i)) + c;
            c = (byte) (s / 10);
            b[b.length - i] = (byte) ((s % 10) + '0');
        }
        if (c == 0) {
            return new String(Arrays.copyOfRange(b, 1, b.length));
        }
        b[0] = (byte) (c + '0');
        return new String(b);
    }
 
    // multipy a number by a single digit
    private static String mulDigit(String x, byte y) {
        if (y == '0') {
            return "0";
        }
        y = d(y);
        byte[] b = new byte[x.length() + 1];
        byte c = 0;
        for (int i = 1; i <= x.length(); i++) {
            int s = d(x.charAt(x.length() - i)) * y + c;
            c = (byte) (s / 10);
            b[b.length - i] = (byte) ((s % 10) + '0');
        }
        if (c == 0) {
            return new String(Arrays.copyOfRange(b, 1, b.length));
        }
        b[0] = (byte) (c + '0');
        return new String(b);
    }
 
    // multiply two numbers as strings
    private static String mul(String x, String y) {
        String result = mulDigit(x, y.charAt(y.length() - 1));
        for (int i = 2, zeros = ""; i <= y.length(); i++) {
            zeros += "0";
            result = add(result, mulDigit(x, y.charAt(y.length() - i)) + zeros);
        }
        return result;
    }
 
