import java.io.*;
import java.util.jar.*;

public class JarWriter {

    private File jarRootDir;
    private OutputStream os;

    public JarWriter(File rootDir, OutputStream outputStream) {
        this.jarRootDir = rootDir;
        this.os = outputStream;
    }

    public void packToJar() throws IOException {
        Manifest manifest = new Manifest();
        manifest.getMainAttributes().put(Attributes.Name.MANIFEST_VERSION, "1.0");
        try (JarOutputStream jarOutputStream = new JarOutputStream(os, manifest)) {
            add(jarRootDir, jarRootDir, jarOutputStream);
        }
    }

    private void add(File rootDir, File source, JarOutputStream jarOutputStream) throws IOException {
        String entryName = rootDir.toURI().relativize(source.toURI()).getPath();

        if (source.isFile()) {
            JarEntry entry = new JarEntry(entryName);
            entry.setTime(source.lastModified());
            jarOutputStream.putNextEntry(entry);

            try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(source))) {
                byte[] buffer = new byte[1024];
                int count;
                while ((count = bis.read(buffer)) != -1) {
                    jarOutputStream.write(buffer, 0, count);
                }
            }
            jarOutputStream.closeEntry();
        } else if (source.isDirectory()) {
            if (!entryName.isEmpty()) {
                JarEntry entry = new JarEntry(entryName + "/");
                entry.setTime(source.lastModified());
                jarOutputStream.putNextEntry(entry);
                jarOutputStream.closeEntry();
            }

            File[] children = source.listFiles();
            if (children != null) {
                for (File child : children) {
                    add(rootDir, child, jarOutputStream);
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        File rootDir = new File("temp");
        if (!rootDir.exists()) {
            rootDir.mkdirs();
            new File(rootDir, "test.txt").createNewFile();
            new File(rootDir, "test2.txt").createNewFile();
            new File(rootDir, "subdir").mkdirs();
            new File(rootDir + "/subdir", "test3.txt").createNewFile();
        }
