/**
 * A message class used to signal a request to swap content or configurations
 * between two tables identified by TableIdentity.
 */
public class SwapTable extends UnicastApplicationMessage implements Serializable {

    private static final long serialVersionUID = 1L;

    private TableIdentity table1;
    private TableIdentity table2;

    /**
     * Constructs a new SwapTable message.
     *
     * @param targetClass
     *            the target class for the message
     * @param table1
     *            the first table identity
     * @param table2
     *            the second table identity
     */
    public SwapTable(Class<?> targetClass, TableIdentity table1, TableIdentity table2) {
        super(targetClass);
        this.table1 = table1;
        this.table2 = table2;
        setRecipient(table1);
    }

    /**
     * Retrieves the first table identity.
     *
     * @return the first table identity
     */
    public TableIdentity getTable1() {
        return table1;
    }

    /**
     * Retrieves the second table identity.
     *
     * @return the second table identity
     */
    public TableIdentity getTable2() {
        return table2;
    }

    /**
     * Sets the first table identity.
     *
     * @param table1
     *            the first table identity to set
     */
    public void setTable1(TableIdentity table1) {
        this.table1 = table1;
    }

    /**
     * Sets the second table identity.
     *
     * @param table2
     *            the second table identity to set
     */
    public void setTable2(TableIdentity table2) {
        this.table2 = table2;
    }

    @Override
    public String toString() {
        return "SwapTable [table1=" + table1 + ", table2=" + table2 + "]";
    }
}

