import org.eclipse.collections.api.block.predicate.Predicate;
import org.eclipse.collections.api.block.procedure.Procedure;
import org.eclipse.collections.api.list.MutableList;
import org.eclipse.collections.api.tuple.Pair;
import org.eclipse.collections.impl.factory.Lists;
import org.eclipse.collections.impl.tuple.Tuples;

public class CaseProcedure<T> implements Procedure<T> {
    private final MutableList<Pair<Predicate<T>, Procedure<T>>> predicateProcedures;
    private Procedure<T> defaultProcedure;

    public CaseProcedure() {
        this.predicateProcedures = Lists.mutable.empty();
    }

    public CaseProcedure<T> addCase(Predicate<T> predicate, Procedure<T> procedure) {
        this.predicateProcedures.add(Tuples.pair(predicate, procedure));
        return this;
    }

    public CaseProcedure<T> setDefault(Procedure<T> procedure) {
        this.defaultProcedure = procedure;
        return this;
    }

    @Override
    public void value(T input) {
        for (Pair<Predicate<T>, Procedure<T>> casePair : predicateProcedures) {
            if (casePair.getOne().accept(input)) {
                casePair.getTwo().value(input);
                return;
            }
        }
        if (defaultProcedure != null) {
            defaultProcedure.value(input);
        }
    }
}

