import java.awt.Graphics;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.Timer;

/** Pencere sinirlarindan sekerek hareket eden tek bir topu canlandiran ornek. */
public class SekenTop extends JPanel implements ActionListener {

    private static final long serialVersionUiD = -6368396547703393842L;

    private static final int PENCERE_GENISLIGI = 600;
    private static final int PENCERE_YUKSEKLIGI = 400;

    private static final int BASLANGIC_X_KOORDINATI = 50;
    private static final int BASLANGIC_Y_KOORDINATI = 50;

    private static final int TIMER_ARALIGI_MS = 10;
    private static final int TOP_CAPI = 50;

    private int xKoordinati;
    private int yKoordinati;
    private int xHiz;
    private int yHiz;

    public SekenTop() {
        xKoordinati = BASLANGIC_X_KOORDINATI;
        yKoordinati = BASLANGIC_Y_KOORDINATI;
        xHiz = 2;
        yHiz = 2;

        Timer kareZamanlayicisi = new Timer(TIMER_ARALIGI_MS, this);
        kareZamanlayicisi.start();
    }

    @Override
    public void paintComponent(Graphics tuval) {
        super.paintComponent(tuval);
        tuval.fillOval(xKoordinati, yKoordinati, TOP_CAPI, TOP_CAPI);
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        xKoordinati += xHiz;
        yKoordinati += yHiz;

        if (xKoordinati < 0 || xKoordinati > PENCERE_GENISLIGI - 60) {
            xHiz *= -1;
        }
        if (yKoordinati < 0 || yKoordinati > PENCERE_YUKSEKLIGI - 75) {
            yHiz *= -1;
        }

        repaint();
    }

    public static void main(String[] args) {
        JFrame pencere = new JFrame("Seken Top");
        pencere.add(new SekenTop());
        pencere.setSize(PENCERE_GENISLIGI, PENCERE_YUKSEKLIGI);
        pencere.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        pencere.setVisible(true);
    }
}

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.Maps;
import java.util.Map;
import java.util.function.Supplier;

/** Augments an existing SoyRecord with additional fields. */
public class AugmentedParamStore {

  private final SoyRecord backingStore;
  private final Map<String, Object> localStore = Maps.newHashMap();

  public AugmentedParamStore(SoyRecord backingStore) {
    this.backingStore = Preconditions.checkNotNull(backingStore);
  }

  public void setField(String name, Object value) {
    localStore.put(name, value);
  }

  public boolean hasField(String name) {
    return localStore.containsKey(name) || backingStore.hasField(name);
  }

  public Object getFieldProvider(String name) {
    if (localStore.containsKey(name)) {
      return localStore.get(name);
    }
    return backingStore.getFieldProvider(name);
  }

  public SoyRecord recordAsMap() {
    ImmutableMap.Builder<String, Object> builder = ImmutableMap.builder();
    for (String field : backingStore.getFieldNames()) {
      builder.put(field, backingStore.getFieldProvider(field));
    }
    for (Map.Entry<String, Object> entry : localStore.entrySet()) {
      builder.put(entry.getKey(), entry.getValue());
    }
    return new SoyRecord(builder.build());
  }

  /** Simple SoyRecord implementation for demonstration purposes. */
  public static class SoyRecord {
    private final ImmutableMap<String, Object> data;

    public SoyRecord(ImmutableMap<String, Object> data) {
      this.data = data;
    }

    public boolean hasField(String name) {
      return data.containsKey(name);
    }

    public Object getFieldProvider(String name) {
      return data.get(name);
    }

    public Iterable<String> getFieldNames() {
      return data.keySet();
    }
  }
}

