public abstract class Specifics<V, E>
    implements Serializable
{
    private static final long serialVersionUID = 785196247314761183L;

    public abstract void addVertex(V vertex);

    public abstract Set<V> getVertexSet();

    /**
     * .
     *
     * @param sourceVertex
     * @param targetVertex
     *
     * @return
     */
    public abstract Set<E> getAllEdges(V sourceVertex,
        V targetVertex);

    /**
     * .
     *
     * @param sourceVertex
     * @param targetVertex
     *
     * @return
     */
    public abstract E getEdge(V sourceVertex, V targetVertex);

    /**
     * Adds the specified edge to the edge containers of its source and
     * target vertices.
     *
     * @param e
     */
    public abstract void addEdgeToTouchingVertices(E e);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract int degreeOf(V vertex);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract Set<E> edgesOf(V vertex);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract int inDegreeOf(V vertex);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract Set<E> incomingEdgesOf(V vertex);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract int outDegreeOf(V vertex);

    /**
     * .
     *
     * @param vertex
     *
     * @return
     */
    public abstract Set<E> outgoingEdgesOf(V vertex);

    /**
     * Removes the specified edge from the edge containers of its source and
     * target vertices.
     *
     * @param e
     */
    public abstract void removeEdgeFromTouchingVertices(E e);
}

public class VanDerCorput{
    public static double vdc(int n){
        double vdc = 0;
        int denom = 1;
        while(n != 0){
            vdc += n % 2.0 / (denom *= 2);
            n /= 2;
        }
        return vdc;
    }
 
    public static void main(String[] args){
        for(int i = 0; i <= 10; i++){
            System.out.println(vdc(i));
        }
    }
}

import org.json.JSONException;
import org.json.JSONObject;
import android.util.Log;

public class TrackInfo {
    private static final String TAG = "TrackInfo";
    private static final String TRACKINFO_KEY_ARTIST = "artist";
    private static final String TRACKINFO_KEY_ID = "id";
    private static final String TRACKINFO_KEY_NAME = "name";
    private static final String TRACKINFO_KEY_URL = "url";

    private ArtistInfo mArtist;
    private String mId;
    private String mName;
    private String mUrl;

    public void parseInfo(JSONObject rawInfo) {
        try {
            if (rawInfo.has(TRACKINFO_KEY_ARTIST)) {
                JSONObject artistJson = rawInfo.getJSONObject(TRACKINFO_KEY_ARTIST);
                mArtist = new ArtistInfo();
                mArtist.parseInfo(artistJson);
            }

            if (rawInfo.has(TRACKINFO_KEY_ID)) {
                mId = rawInfo.getString(TRACKINFO_KEY_ID);
            }

            if (rawInfo.has(TRACKINFO_KEY_NAME)) {
                mName = rawInfo.getString(TRACKINFO_KEY_NAME);
            }

            if (rawInfo.has(TRACKINFO_KEY_URL)) {
                mUrl = rawInfo.getString(TRACKINFO_KEY_URL);
            }
        } catch (JSONException e) {
            Log.e(TAG, "Error parsing track info: " + e.getMessage());
        }
    }

    public ArtistInfo getArtist() {
        return mArtist;
    }

    public String getId() {
        return mId;
    }

    public String getName() {
        return mName;
    }

    public String getUrl() {
        return mUrl;
    }

    // Inner class for ArtistInfo (simplified for demonstration)
    public static class ArtistInfo {
        private String mName;

        public void parseInfo(JSONObject artistJson) {
            try {
                if (artistJson.has("name")) {
                    mName = artistJson.getString("name");
                }
            } catch (JSONException e) {
                Log.e(TAG, "Error parsing artist info: " + e.getMessage());
            }
        }

        public String getName() {
            return mName;
        }
    }
}

import java.io.BufferedReader;

import java.io.IOException;

import java.io.InputStreamReader;

import java.io.PrintWriter;

import java.util.*;

public class C {

    public static void main(String[] args) throws IOException {

        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));

        PrintWriter out = new PrintWriter(System.out);

        int t = Integer.parseInt(reader.readLine());

        while (t > 0) {

            t--;

            StringTokenizer st = new StringTokenizer(reader.readLine());

            int n = Integer.parseInt(st.nextToken());

            int x = Integer.parseInt(st.nextToken());

            int[] a = new int[n];

            st = new StringTokenizer(reader.readLine());

            int[] prefixSum = new int[n + 1];

            for (int i = 0; i < n; i++) {

                a[i] = Integer.parseInt(st.nextToken());

                prefixSum[i + 1] = prefixSum[i] + a[i];

            }

            Map<Integer, Integer> map = new HashMap<>();

            map.put(0, 0);

            for (int i = 0; i < n; i++) {

                for (int j = i + 1; j <= n; j++) {

                    int subArraySum = prefixSum[j] - prefixSum[i];

                    if (map.containsKey(j - i)) {

                        map.put(j - i, Math.max(map.get(j - i), subArraySum));

                    } else {

                        map.put(j - i, subArraySum);

                    }

                }

            }

            for (int k = 0; k <= n; k++) {

                int max = Integer.MIN_VALUE;

                for (Map.Entry<Integer, Integer> entry : map.entrySet()) {

                    max = Math.max(max, entry.getValue() + (Math.min(k, entry.getKey()) * x));

                }

                out.print(max + " ");

            }

            out.println();

        }

        out.close();

    }

}

