public class Dijkstra {
 
    public static void main(String[] args) {
        List<String[]> graph = new ArrayList<>();
        graph.add(new String[]{"a", "b", "7"});
        graph.add(new String[]{"a", "c", "9"});
        graph.add(new String[]{"a", "f", "14"});
        graph.add(new String[]{"b", "c", "10"});
        graph.add(new String[]{"b", "d", "15"});
        graph.add(new String[]{"c", "d", "11"});
        graph.add(new String[]{"c", "f", "2"});
        graph.add(new String[]{"d", "e", "6"});
        graph.add(new String[]{"e", "f", "9"});
 
        String[] path = dijkstra(graph, "a", "e");
        System.out.println(String.join(",", path)); //a,c,f,e
    }
 
    public static String[] dijkstra(List<String[]> edges, String source, String target) {
        Set<String> Q = new HashSet<>();
        Map<String, String> prev = new HashMap<>();
        Map<String, Integer> dist = new HashMap<>();
        Map<String, Map<String, Integer>> adj = new HashMap<>();
 
        String vertex_with_min_dist(Set<String> Q, Map<String, Integer> dist) {
            int min_distance = Integer.MAX_VALUE;
            String u = null;
 
            for (String v : Q) {
                if (dist.get(v) < min_distance) {
                    min_distance = dist.get(v);
                    u = v;
                }
            }
            return u;
        }
 
        for (String[] edge : edges) {
            String v1 = edge[0], v2 = edge[1];
            int len = Integer.parseInt(edge[2]);
 
            Q.add(v1);
            Q.add(v2);
 
            dist.put(v1, Integer.MAX_VALUE);
            dist.put(v2, Integer.MAX_VALUE);
 
            if (!adj.containsKey(v1)) adj.put(v1, new HashMap<>());
            if (!adj.containsKey(v2)) adj.put(v2, new HashMap<>());
 
            adj.get(v1).put(v2, len);
            adj.get(v2).put(v1, len);
        }
 
        dist.put(source, 0);
 
        while (!Q.isEmpty()) {
            String u = vertex_with_min_dist(Q, dist);
            Q.remove(u);
 
            if (u.equals(target)) break; //Break when the target has been found
 
            for (String v : adj.get(u).keySet()) {
                if (Q.contains(v)) {
                    int alt = dist.get(u) + adj.get(u).get(v);
                    if (alt < dist.get(v)) {
                        dist.put(v, alt);
                        prev.put(v, u);
                    }
                }
            }
        }

