import java.util.Scanner;

public class Finder {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int k = in.nextInt();
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < k; i++) {
            long n = in.nextLong();
            long x = in.nextLong();
            long t = in.nextLong();
            long dissatisfaction = 0;
            for (long j = 0; j < n; j++) {
                long startTime = j * x;
                long endTime = startTime + t;
                long participantsStartedButNotFinished = Math.min(n - j - 1, (endTime - 1) / x - j);
                dissatisfaction += participantsStartedButNotFinished;
            }
            result.append(dissatisfaction).append('\n');
        }
        System.out.print(result);
    }
}

 
