public class Handler {
 
    public static void main(String[] args) {
        ArrayList<Double> x = new ArrayList<Double>();
        x.add(1.0);
        x.add(2.0);
        x.add(3.0);
        x.add(1e11);
        ArrayList<Double> y = new ArrayList<Double>();
        y.add(1.0);
        y.add(1.4142135623730951);
        y.add(1.7320508075688772);
        y.add(316227.76601683791);
 
        int xprecision = 3;
        int yprecision = 5;
 
