import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class RadixSort {
    public static void main(String[] args) {
        int[] a = {1, 3, 8, 9, 0, 0, 8, 7, 1, 6};
        System.out.println(Arrays.toString(radixSort(a)));
        int[] b = {170, 45, 75, 90, 2, 24, 802, 66};
        System.out.println(Arrays.toString(radixSort(b)));
        int[] c = {170, 45, 75, 90, 2, 24, -802, -66};
        System.out.println(Arrays.toString(radixSort(c)));
        int[] d = {100000, -10000, 400, 23, 10000};
        System.out.println(Arrays.toString(radixSort(d)));
    }

    public static int[] radixSort(int[] ary) {
        int[] a = Arrays.copyOf(ary, ary.length);
        int rounds = (int) (Math.log(Math.max(Math.abs(Arrays.stream(a).max().getAsInt()), Math.abs(Arrays.stream(a).min().getAsInt()))) / Math.log(10)) + 1;
        for (int i = 0; i < rounds; i++) {
            List<List<Integer>> buckets = new ArrayList<>();
            for (int j = 0; j < 20; j++) {
                buckets.add(new ArrayList<>());
            }
            int base_i = (int) Math.pow(10, i);
            for (int n : a) {
                int digit = (n / base_i) % 10;
                digit += 10;
                if (n < 0) {
                    digit = -digit;
                }
                buckets.get(digit).add(n);
            }
            a = buckets.stream().flatMap(List::stream).mapToInt(Integer::intValue).toArray();
        }
        return a;
    }
}

