import java.util.HashMap;
import java.util.Map;
 
abstract class Catalan {
    abstract double invoke(int n);
 
    protected Map<Integer, Double> m = new HashMap<>();
}
 
class CatalanI extends Catalan {
    @Override
    public double invoke(int n) {
        if (!m.containsKey(n))
            m.put(n, Math.round(fact(2 * n) / (fact(n + 1) * fact(n))));
        return m.get(n);
    }
 
    private double fact(int n) {
        if (facts.containsKey(n))
            return facts.get(n);
        double f = n * fact(n - 1);
        facts.put(n, f);
        return f;
    }
 
    private Map<Integer, Double> facts = new HashMap<>();
    {
        facts.put(0, 1.0);
        facts.put(1, 1.0);
        facts.put(2, 2.0);
    }
}
 
class CatalanR1 extends Catalan {
    @Override
    public double invoke(int n) {
        if (m.containsKey(n))
            return m.get(n);
 
        double sum = 0.0;
        for (int i = 0; i < n; i++)
            sum += invoke(i) * invoke(n - 1 - i);
        sum = Math.round(sum);
        m.put(n, sum);
        return sum;
    }
}
 
class CatalanR2 extends Catalan {
    @Override
    public double invoke(int n) {
        if (!m.containsKey(n))
            m.put(n, Math.round(2.0 * (2 * (n - 1) + 1) / (n + 1) * invoke(n - 1)));
        return m.get(n);
    }
}
 
public class Catalan {
    public static void main(String[] args) {
        Catalan[] c = new Catalan[] { new CatalanI(), new CatalanR1(), new CatalanR2() };
        for (int i = 0; i < 15; i++) {
            for (Catalan ci : c)
                System.out.printf("%9d", (long) ci.invoke(i));
            System.out.println();
        }
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class NestedList {
    public static class List_t {
        public int is_list, ival;
        public List<List_t> lst;
    }
 
    public static List_t new_list() {
        List_t x = new List_t();
        x.ival = 0;
        x.is_list = 1;
        x.lst = new ArrayList<List_t>();
        return x;
    }
 
    public static void append(List_t parent, List_t child) {
        parent.lst.add(child);
        parent.ival++;
    }
 
    public static List_t from_string(String s, List_t parent) {
        List_t ret = null;
        if (parent == null)
            parent = new_list();
 
        while (s.length() > 0) {
            if (s.charAt(0) == ']') {
                return parent;
            }
            if (s.charAt(0) == '[') {
                ret = new_list();
                ret.is_list = 1;
                ret.ival = 0;
                append(parent, ret);
                from_string(s.substring(1), ret);
                continue;
            }
            if (s.charAt(0) >= '0' && s.charAt(0) <= '9') {
                ret = new List_t();
                ret.is_list = 0;
                ret.ival = Integer.parseInt(s.substring(0, s.indexOf(',')));
                append(parent, ret);
                s = s.substring(s.indexOf(',') + 1);
                continue;
            }
            s = s.substring(1);
        }
 
        return parent;
    }
 
    public static void show_list(List_t l) {
        if (l == null)
            return;
        if (l.is_list == 0) {
            System.out.print(l.ival);
            return;
        }
 
        System.out.print("[");
        for (int i = 0; i < l.ival; i++) {
            show_list(l.lst.get(i));
            if (i < l.ival - 1)
                System.out.print(", ");
        }
        System.out.print("]");
    }
 
    public static List_t flatten(List_t from, List_t to) {
        List_t t;
 
        if (to == null)
            to = new_list();
        if (from.is_list == 0) {
            t = new List_t();
            t.is_list = from.is_list;
            t.ival = from.ival;
            append(to, t);
        } else
            for (int i = 0; i < from.ival; i++)
                flatten(from.lst.get(i), to);
        return to;
    }
 
    public static void delete_list(List_t l) {
        if (l == null)
            return;
        if (l.is_list == 1 && l.ival > 0) {
            for (int i = 0; i < l.ival; i++)
                delete_list(l.lst.get(i));
            l.lst.clear();
        }
    }
 
