import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;
 
public class HeapSort {
    public static void main(String[] args) {
        int[] a = {170, 45, 75, -90, -802, 24, 2, 66};
        System.out.println("before: " + Arrays.toString(a));
        heapSort(a);
        System.out.println("after:  " + Arrays.toString(a));
    }
 
    public static void heapSort(int[] a) {
        PriorityQueue<Integer> q = new PriorityQueue<Integer>(a.length, new Comparator<Integer>() {
            public int compare(Integer i, Integer j) {
                return j - i;
            }
        });
        for (int i : a) {
            q.add(i);
        }
        for (int i = 0; i < a.length; i++) {
            a[i] = q.poll();
        }
    }
}

/**
 * Factory for building events
 */

import java.util.List;

import org.hibernate.Session;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import de.uzk.hki.da.model.Node;
import de.uzk.hki.da.model.SystemEvent;
import de.uzk.hki.da.service.HibernateUtil;

public class SystemEventFactory  {

    protected Logger logger = LoggerFactory.getLogger( this.getClass().getName() );

    private Node localNode;

    private String eventsPackage = "de.uzk.hki.da.event.";

    public void buildStoredEvents() {
        List<SystemEvent> ses = getEventsPerNode();
        if (ses != null) {
            for (SystemEvent se : ses) {
                if (se.getType() == null)
                    continue;
                AbstractSystemEvent ase = null;
                try {
                    ase = (AbstractSystemEvent) Class.forName(eventsPackage + se.getType()).newInstance();
                    injectProperties(ase, se);
                    ase.run();
                } catch (Exception e) {
                    logger.error("could not instantiate " + se.getType());
                }
            }
        } else
            logger.debug("no events to perform");
    }

    private void injectProperties(AbstractSystemEvent ase, SystemEvent se) {
        ase.setNode(localNode);
        ase.setOwner(se.getOwner());
        ase.setStoredEvent(se);
    }

    @SuppressWarnings("unchecked")
    private List<SystemEvent>getEventsPerNode() {
        Session session = HibernateUtil.openSession();
        List<SystemEvent> events=null;
        try{
            events = session
                    .createQuery("from SystemEvent e where e.node.id = ?1")
                    .setParameter("1", localNode.getId()).setCacheable(false).list();

            if ((events == null) || (events.isEmpty())){
                logger.trace("no systemevents found for " + localNode.getName());
                session.close();
                return null;
            }

            session.close();

        }catch(Exception e){
            session.close();
            logger.error("Caught error in getEventsPerNode id: " + localNode.getId() + " " + e.getMessage(),e);

            throw new RuntimeException(e.getMessage(), e);
        }
        return events;
}

    public Node getLocalNode() {
        return localNode;
    }

    public void setLocalNode(Node localNode) {
        this.localNode = localNode;
    }

}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.IntStream;
 
public class UlamSpiral {
 
    public static void main(String[] args) {
        showSpiral(9);
        showSpiral(25);
        showSpiral(25, "# ");
    }
 
    public static void showSpiral(int n) {
        showSpiral(n, null, 1);
    }
 
    public static void showSpiral(int n, String symbol, int start) {
        System.out.println("\nN : " + n);
        int size = (int) Math.log10(start + n * n - 1) + 1;
        String format = "%" + size + "s ";
        for (int y = 0; y < n; y++) {
            for (int x = 0; x < n; x++) {
                int i = cell(n, x, y, start);
                if (symbol!= null) {
                    System.out.print(isPrime(i)? symbol.charAt(0) : symbol.charAt(1));
                } else {
                    System.out.print(isPrime(i)? String.format(format, i) : "");
                }
            }
            System.out.println();
        }
    }
 
    public static int cell(int n, int x, int y, int start) {
        y = y - n / 2;
        x = x - (n - 1) / 2;
        int l = 2 * Math.max(Math.abs(x), Math.abs(y));
        int d = y >= x? l * 3 + x + y : l - x - y;
        return (int) Math.pow(l - 1, 2) + d + start - 1;
    }
 
    public static boolean isPrime(int n) {
        if (n < 2) {
            return false;
        }
        if (n == 2 || n == 3) {
            return true;
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;
        }
        int sqrtN = (int) Math.sqrt(n) + 1;
        for (int i = 6; i <= sqrtN; i += 6) {
            if (n % (i - 1) == 0 || n % (i + 1) == 0) {
                return false;
            }
        }
        return true;
    }
}

