def get_grid(n, m):
    def gray_code(n):
        if n == 0:
            return ["0", "1"]
        else:
            temp = gray_code(n - 1)
            ans = []
            for i in range(len(temp)):
                ans.append("0" + temp[i])
            for i in range(len(temp) - 1, -1, -1):
                ans.append("1" + temp[i])
            return ans

    def get_binary(gray):
        binary = ''
        for i in range(len(gray)):
            if gray[i] == '1':
                binary += '1'
            else:
                binary += '0'
        return binary

    gray = gray_code(n * m)
    binary = get_binary(gray)

    grid = []
    while binary:
        temp = []
        for i in range(m):
            if i < len(binary):
                temp.append(binary[i])
            else:
                break

        binary = binary[len(temp):]

        temp2 = ''.join(temp)
        grid_temp = ''
        for ch in temp2:
            if ch == '1':
                grid_temp = grid_temp + 'W'
            else:
                grid_temp = grid_temp + 'B'

        grid.append(grid_temp)

    return grid

