import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.stage.Stage;

import javafx.scene.shape.Line;

import java.util.Random;

public class Library extends Application {
    private static Stage primaryStage;
    private static double WIDTH = 400;
    private static double HEIGHT = 400;

    private static double x1;
    private static double x2;
    private static double y1;
    private static double y2;
    /* Length of main line body */
    private static double L1;
    /* Length of the lines that make the arrow */
    private static double L2;

    public static void drawArrowLine(double startX, double startY, double endX, double endY, Pane pane) {
        double x3, y3, x4, y4;

        Group group = new Group();
        Line line = new Line(startX, startY, endX, endY); // Draw the line for main body of arrow
        L1 = length(line);
        L2 = L1 / 8;
        //Calculate end points for the tip of the arrow
        x3 = endX + (L2 / L1) * (((startX - endX) * Math.cos(Math.toRadians(45.0))) + ((startY - endY) * Math.sin(Math.toRadians(45.0))));
        y3 = endY + (L2 / L1) * (((startY - endY) * Math.cos(Math.toRadians(45.0))) - ((startX - endX) * Math.sin(Math.toRadians(45.0))));
        x4 = endX + (L2 / L1) * (((startX - endX) * Math.cos(Math.toRadians(45.0))) - ((startY - endY) * Math.sin(Math.toRadians(45.0))));
        y4 = endY + (L2 / L1) * (((startY - endY) * Math.cos(Math.toRadians(45.0))) + ((startX - endX) * Math.sin(Math.toRadians(45.0))));

        Line arrowLine1 = new Line(endX, endY, x3, y3);
        Line arrowLine2 = new Line(endX, endY, x4, y4);

        group.getChildren().addAll(line, arrowLine1, arrowLine2);
        pane.getChildren().add(group);

        Scene scene = new Scene(pane, WIDTH, HEIGHT);
        primaryStage.setScene(scene);
        primaryStage.setTitle(Library.class.getName());
        primaryStage.show();

    }

    @Override
    public void start(Stage primaryStage) throws Exception {
        Library.primaryStage = primaryStage;
        Random random = new Random();
        double bound = WIDTH - 100;
        x1 = random.nextInt((int) bound);
        y1 = random.nextInt((int) bound);
        x2 = random.nextInt((int) bound);
        y2 = random.nextInt((int) bound);
        if (Math.abs(y1 - y2) < 75) {
            y2 += 50;
        }
        if (Math.abs(x1 - x2) < 50) {
            x2 += 50;
        }
        Pane pane = new Pane();
        drawArrowLine(x1, y1, x2, y2, pane);

    }

import com.google.common.testing.TearDown;
import com.google.common.testing.TearDownAccepter;
import com.google.guiceberry.DefaultEnvSelector;
import com.google.guiceberry.GuiceBerryEnvSelector;
import com.google.guiceberry.GuiceBerry;
import com.google.guiceberry.GuiceBerry.GuiceBerryWrapper;
import com.google.inject.Module;

import junit.framework.TestCase;

/**
 * {@link GuiceBerry} adapter for JUnit3 {@link TearDownAccepter}s.
 *
 * @see ManualTearDownGuiceBerry
 *
 */
public class AutoTearDownGuiceBerry {

  /**
   * Sets up the test, by creating an injector for the given
   * {@code guiceBerryEnvClass} and registering a {@link TearDown} against the
   * given {@code testCase}.
   *
   * <p>A canonical test will call this method in the its setUp method, and will
   * pass {@code this} as the testCase argument. See
   * {@code junit3_tdtc.tutorial_0_basic.Example0HelloWorldTest#setUp()}.
   *
   * <p>The parameter {@code T} is a {@link TearDownAccepter} or anything
   * equivalent to it.
   */
  public static <T extends TestCase & TearDownAccepter> void setUp(
      /* TeaDownTestCase */ T testCase,
      Class<? extends Module> guiceBerryEnvClass) {
    setUp(testCase, DefaultEnvSelector.of(guiceBerryEnvClass));
  }

  /**
   * Same as {@link #setUp(TearDownAccepter, Class)}, but with the given
   * {@code guiceBerryEnvSelector}.
   *
   * @see #setUp(TestCase, Class)
   */
  public static <T extends TestCase & TearDownAccepter> void setUp(
      /* TeaDownTestCase */ T testCase,
      GuiceBerryEnvSelector guiceBerryEnvSelector) {
    final GuiceBerryWrapper toTearDown =
      GuiceBerry.INSTANCE.buildWrapper(
          ManualTearDownGuiceBerry.buildTestDescription(testCase, testCase.getName()),
          guiceBerryEnvSelector);
    testCase.addTearDown(new TearDown() {

      public void tearDown() throws Exception {
        toTearDown.runAfterTest();
      }
    })  ;
    toTearDown.runBeforeTest();
  }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Timer {
    public ListNode reverseEvenLengthGroups(ListNode head) {
        ListNode p = head;
        int len = 0;
        while(p != null){
            p = p.next;
            len++;
        }
        //System.out.println(len);
        int exp = 1;
        p = head;
        ListNode last = null;
        while(len > 0){
            if(exp >len){
                exp = len;
            }
            len -= exp;
            //System.out.println(len +" "+exp);
            if(exp % 2 == 0){
                //swap
                ListNode newh = p, cur = p.next, tmp;
                newh.next = null;
                for(int i = 0; i < exp - 1; i++){
                    tmp = cur.next;
                    cur.next = newh;
                    newh = cur;
                    cur = tmp;
                }
                //return newh;
                p.next = cur;
                last.next = newh;
                last = p;
                p = cur;
            } else {
                //do nothing
                for(int i = 0; i < exp; i++){
                    last = p;
                    p = p.next;
                }
            }
            exp++;
        }
        return head;
    }

}

import java.io.*;
import java.util.*;
import java.util.regex.*;
 
public class UpdateConfig {
 
    public static void main(String[] args) {
        if (args[0] == null) {
            System.out.println("filename required");
 
        } else if (readConfig(args[0])) {
            enableOption("seedsremoved");
            disableOption("needspeeling");
            setOption("numberofbananas", "1024");
            addOption("numberofstrawberries", "62000");
            store();
        }
    }
 
    private enum EntryType {
        EMPTY, ENABLED, DISABLED, COMMENT
    }
 
    private static class Entry {
        EntryType type;
        String name, value;
 
        Entry(EntryType t, String n, String v) {
            type = t;
            name = n;
            value = v;
        }
    }
 
    private static Map<String, Entry> entries = new LinkedHashMap<>();
    private static String path;
 
    private static boolean readConfig(String p) {
        path = p;
 
        File f = new File(path);
        if (!f.exists() || f.isDirectory())
            return false;
 
        String regexString = "^(;*)\\s*([A-Za-z0-9]+)\\s*([A-Za-z0-9]*)";
        Pattern regex = Pattern.compile(regexString);
 
        try (Scanner sc = new Scanner(new FileReader(f))){
            int emptyLines = 0;
            String line;
            while (sc.hasNext()) {
                line = sc.nextLine().trim();
 
                if (line.isEmpty()) {
                    addOption("" + emptyLines++, null, EntryType.EMPTY);
 
                } else if (line.charAt(0) == '#') {
                    entries.put(line, new Entry(EntryType.COMMENT, line, null));
 
                } else {
                    line = line.replaceAll("[^a-zA-Z0-9\\x20;]", "");
                    Matcher m = regex.matcher(line);
 
                    if (m.find() && !m.group(2).isEmpty()) {
 
                        EntryType t = EntryType.ENABLED;
                        if (!m.group(1).isEmpty())
                            t = EntryType.DISABLED;
 
                        addOption(m.group(2), m.group(3), t);
                    }
                }
            }
        } catch (IOException e) {
            System.out.println(e);
        }
        return true;
    }
 
    private static void addOption(String name, String value) {
        addOption(name, value, EntryType.ENABLED);
    }
 
    private static void addOption(String name, String value, EntryType t) {
        name = name.toUpperCase();
        entries.put(name, new Entry(t, name, value));
    }

import java.util.Arrays;
import java.util.Locale;

public class Student {

    public static void main(String[] args) {
        int[] a = {1, 3, 5, 7, 9};
        int[] b = {2, 4, 6, 8, 10, 11, 12};

        int[] result = smerge(a, b);

        System.out.println("Merged and Sorted Array: " + Arrays.toString(result));
    }

    public static int[] smerge(int[] a, int[] b) {
        int[] result = new int[a.length + b.length];
        int i = a.length - 1;
        int j = b.length - 1;
        int k = result.length - 1;

        while (i >= 0 && j >= 0) {
            if (a[i] > b[j]) {
                result[k--] = a[i--];
            } else {
                result[k--] = b[j--];
            }
        }

        while (i >= 0) {
            result[k--] = a[i--];
        }

        while (j >= 0) {
            result[k--] = b[j--];
        }

        return result;
    }
}

import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.ByteChannel;
import java.nio.channels.SocketChannel;

public class AbstractWrappedByteChannel implements WrappedByteChannel {

    private final ByteChannel channel;

    public AbstractWrappedByteChannel( ByteChannel towrap ) {
        this.channel = towrap;
    }

    public AbstractWrappedByteChannel( WrappedByteChannel towrap ) {
        this.channel = towrap;
    }

    @Override
    public int read( ByteBuffer dst ) throws IOException {
        return channel.read( dst );
    }

    @Override
    public boolean isOpen() {
        return channel.isOpen();
    }

    @Override
    public void close() throws IOException {
        channel.close();
    }

    @Override
    public int write( ByteBuffer src ) throws IOException {
        return channel.write( src );
    }

    @Override
    public boolean isNeedWrite() {
        return channel instanceof WrappedByteChannel && ((WrappedByteChannel) channel).isNeedWrite();
    }

    @Override
    public void writeMore() throws IOException {
        if( channel instanceof WrappedByteChannel )
            ( (WrappedByteChannel) channel ).writeMore();

    }

    @Override
    public boolean isNeedRead() {
        return channel instanceof WrappedByteChannel && ((WrappedByteChannel) channel).isNeedRead();

    }

    @Override
    public int readMore( ByteBuffer dst ) throws IOException {
        return channel instanceof WrappedByteChannel ? ( (WrappedByteChannel) channel ).readMore( dst ) : 0;
    }

    @Override
    public boolean isBlocking() {
        if( channel instanceof SocketChannel )
            return ( (SocketChannel) channel ).isBlocking();
        else if( channel instanceof WrappedByteChannel )
            return ( (WrappedByteChannel) channel ).isBlocking();
        return false;
    }

}

