java
public int lengthOfLIS(int[] nums, int k) {
    int maxIndex = 0;
    for (int num : nums) {
        maxIndex = Math.max(maxIndex, num);
    }

    int[] bit = new int[maxIndex + 1];
    int maxLength = 0;

    for (int num : nums) {
        int target = Math.max(num - k, 0);
        int index = num;

        // Update the BIT with the new range
        bit[index]++;
        for (int i = index; i <= maxIndex + k; i = i | (i + 1)) {
            bit[i]++;
        }

        // Update the length of subsequence
        maxLength = Math.max(maxLength, find(bit, target));
    }

    return maxLength;
}

// bit-based LIS function. find the maximum index of array "bit"
// at value x equalling or less than "x"
private int find(int[] bit, int x) {
    int cs = 0;
    int s = 0;
    for (; s < bit.length; s = s | (s + 1)) {
        while (cs < bit[s] && x > bit[s]) {
            cs += bit[s];
            x -= bit[s];
        }
    }

    return s - x;
}

