    public static long fact(int n) {

        if(n == 0  ||  n == 1) {

            return 1 ;

        }

        int mod = (int)(1e9+7) ;

        long fac = 1 ;

        while(n > 1) {

            fac = (fac * (long)n)%mod ;

            n-- ;

        }

        return fac ;

    }

