import java.io.*;

/** **
* Program that solves the puzzles for Mocha
*
*
* **/
public class SolvePuzzles {
    public static void main(String[] args) throws Exception {

        Thread thread = new Thread(null, new PuzzleSolver(), "", 1 << 27);
        thread.start();
        thread.join();
    }

    static class PuzzleSolver implements Runnable {
        @Override
        public void run() {
            InputStream inputStream = System.in;
            OutputStream outputStream = System.out;
            InputReader in = new InputReader(inputStream);
            OutputWriter out = new OutputWriter(outputStream);
            Solve(in, out);
            out.close();
        }

        /**
         * This method solves the valid cases of The Cookie Predicament
         *
         * @param in InputReader object
         * @param out OutputWriter object
         */
        public void Solve( InputReader in, OutputWriter out) {
            int t = in.readInt();

            while (t-- > 0) {
                int n = in.readInt();

                String s = in.readString();
                int imperfectness = 0;

                for (int i = 0; i < s.length() - 1; i++) {
                    if (s.charAt(i) == s.charAt(i + 1)) {
                        imperfectness++;
                    }
                }

                s = applyCycle(imperfectness, s);

                while (s.charAt(s.length() - 1) == '?') {
                    s = applyCycle(imperfectness, s);
                }

            out.printLine(s);
            }
        }

        /**
         * This method solves a single case
         *
         * @param imperfectness  maximum imperfectness acyclic coloring
         * @param s              a string containing 'B' and 'R' only
         * @return s
         */
        public String applyCycle(int imperfectness, String s) {
            int i;

            boolean found = false;
            int changes = 0;
            for (i = 0; i < s.charAt(0) == 'R' ? s.length() - 1 : 0; i++) {
                if (s.charAt(i) == 'R')
                    changes++;
                else if (imperfectness <= s.charAt(i + 1) == 'R' ? changes >= imperfectness + 1 : 1) {
                    found = true;
                    break;
                }

                if (i != s.length() - 1)
                    continue;

                s = replace(s, i, 'R');
                while (i < s.length() && s.charAt(i) == 'B')
                    i++;

                if (!found) {
                    i--;
                    break;
                }

