public String evaluate(String s, List<List<String>> knowledge) {
    Map<String, String> map = new HashMap<>();
    for (List<String> item : knowledge) {
        map.put(item.get(0), item.get(1));
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            int j = i + 1;
            while (j < s.length() && s.charAt(j) != ')') {
                j++;
            }
            String key = s.substring(i + 1, j);
            sb.append(map.getOrDefault(key, "?"));
            i = j + 1;
        } else {
            sb.append(s.charAt(i));
            i++;
        }
    }
    return sb.toString();
}

public static void main(String[] args) {
    String s = "(name)is(age)yearsold";
    List<List<String>> knowledge = new ArrayList<>();
    knowledge.add(Arrays.asList("name", "bob"));
    knowledge.add(Arrays.asList("age", "two"));
    System.out.println(new Solution().evaluate(s, knowledge)); // Output: "bobistwoyearsold"

    s = "hi(name)";
    knowledge = new ArrayList<>();
    knowledge.add(Arrays.asList("a", "b"));
    System.out.println(new Solution().evaluate(s, knowledge)); // Output: "hi?"

    s = "(a)(a)(a)aaa";
    knowledge = new ArrayList<>();
    knowledge.add(Arrays.asList("a", "yes"));
    System.out.println(new Solution().evaluate(s, knowledge)); // Output: "yesyesyesaaa"
}

class Helper {
    public int countSpecialSubsequences(int[] nums) {
        int n = nums.length;
        int MOD = 1000000007;
        int[][] f = new int[n + 5][4];
        int[][] s = new int[n + 5][4];
        for (int i = 1;i <= n;i++) {
            if (nums[i - 1] == 0) {
                f[i][0] = (s[i - 1][0] + 1) % MOD;
            } else if (nums[i - 1] == 1) {
                f[i][1] = (s[i - 1][0] + s[i - 1][1]) % MOD;
            } else if (nums[i - 1] == 2) {
                f[i][2] = (s[i - 1][1] + s[i - 1][2]) % MOD;
            }
            if (i > 0) {
                for (int j = 0;j < 3;j++) {
                    s[i][j] = (s[i - 1][j] + f[i][j]) % MOD;
                }
            }
        }
        return s[n][2];
    }
}

