import java.util.HashMap;
 
public class Sterling1 {
    private static HashMap<String, Integer> computed = new HashMap<String, Integer>();
 
    public static int sterling1(int n, int k) {
        String key = n + "," + k;
        if (computed.containsKey(key)) {
            return computed.get(key);
        }
        if (n == k && k == 0) {
            return 1;
        }
        if (n > 0 && k == 0) {
            return 0;
        }
        if (k > n) {
            return 0;
        }
        int result = sterling1(n - 1, k - 1) + (n - 1) * sterling1(n - 1, k);
        computed.put(key, result);
        return result;
    }
 
    public static void main(String[] args) {
        System.out.println("Unsigned Stirling numbers of the first kind:");
        int MAX = 12;
        System.out.print("n/k".ljust(10));
        for (int n = 0; n <= MAX; n++) {
            System.out.print(String.format("%10d", n));
        }
        System.out.println();
        for (int n = 0; n <= MAX; n++) {
            System.out.print(String.format("%10d", n));
            for (int k = 0; k <= n; k++) {
                System.out.print(String.format("%10d", sterling1(n, k)));
            }
            System.out.println();
        }
        System.out.println("The maximum value of S1(100, k) = ");
        int previous = 0;
        for (int k = 1; k <= 100; k++) {
            int current = sterling1(100, k);
            if (current > previous) {
                previous = current;
            } else {
                System.out.println(previous + "\n(" + String.valueOf(previous).length() + " digits, k = " + (k - 1) + ")");
                break;
            }
        }
    }
}

public static void printProperties(String message, Properties properties,
                                     PrintStream stream) {
    if (message != null) {
      stream.println(message);
    }
    if (properties.isEmpty()) {
      stream.println("  [empty]");
    } else {
      List<Map.Entry<String, String>> entries = getSortedEntries(properties);
      for (Map.Entry<String, String> entry : entries) {
        if ( ! "".equals(entry.getKey())) {
          stream.format("  %-30s = %s%n", entry.getKey(), entry.getValue());
        }
      }
    }
    stream.println();
  }

