import java.io.*;
import java.util.*;

public class FindWords {
    public static void main(String[] args) {
        if (args.length != 2) {
            System.out.println("Usage: java FindWords directory word");
            System.exit(1);
        }

        String directory = args[0];
        String word = args[1];

        File dir = new File(directory);
        if (!dir.isDirectory()) {
            System.out.println(directory + " is not a directory");
            System.exit(1);
        }

        findWordsInDirectory(dir, word);
    }

    public static void findWordsInDirectory(File dir, String word) {
        File[] files = dir.listFiles();
        for (File file : files) {
            if (file.isDirectory()) {
                findWordsInDirectory(file, word);
            } else {
                findWordsInFile(file, word);
            }
        }
    }

    public static void findWordsInFile(File file, String word) {
        try (Scanner input = new Scanner(file)) {
            int lineNumber = 0;
            while (input.hasNextLine()) {
                String line = input.nextLine();
                lineNumber++;
                if (line.contains(word)) {
                    System.out.printf("%s:%d: %s%n", file.getAbsolutePath(), lineNumber, line);
                }
            }
        } catch (FileNotFoundException e) {
            System.out.println("File not found: " + file);
        }
    }
}

java
class Matrix {

    private Map<Integer, List<Integer>> map;
    private Random rand;

    public Matrix(int[] nums) {
        map = new HashMap<>();
        rand = new Random();

        for (int i = 0; i < nums.length; i++) {
            if (!map.containsKey(nums[i])) {
                map.put(nums[i], new ArrayList<>());
            }
            map.get(nums[i]).add(i);
        }
    }

    public int pick(int target) {
        List<Integer> indexes = map.get(target);
        return indexes.get(rand.nextInt(indexes.size()));
    }
}

import org.jivesoftware.Spark;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

/**
 * The <code>RolloverButton</code> class is a button that
 * offers more user feedback by changing its graphics for the
 * different states of a button, such as rollover.
 */
public class RolloverButton extends JButton {

    private static final long serialVersionUID = -4067864686434215458L;

    /**
     * Creates a new RolloverButton.
     */
    public RolloverButton() {
        decorate();
    }

    /**
     * Creates a new RolloverButton.
     *
     * @param text the button text.
     */
    public RolloverButton(String text) {
        super(text);
        decorate();
    }

    /**
     * Creates a new RolloverButton.
     *
     * @param icon the button icon.
     */
    public RolloverButton(Icon icon) {
        super(icon);
        decorate();
    }

    /**
     * Creates a new RolloverButton.
     *
     * @param text the button text.
     * @param icon the button icon.
     */
    public RolloverButton(String text, Icon icon) {
        super(text, icon);
        decorate();
    }

    /**
     * Creates a new RolloverButton.
     *
     * @param action the action to use.
     */
    public RolloverButton(Action action) {
        super(action);
        decorate();
    }

    /**
     * Decorates the button with the approriate UI configurations.
     */
    private void decorate() {
        setBorderPainted(false);
        setOpaque(false);

        // Set Default behavior
        setContentAreaFilled(false);
        setMargin(new Insets(1, 1, 1, 1));

        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                if (!RolloverButton.this.isEnabled()) {
                    return;
                }
                setBorderPainted(true);
                if (!Spark.isMac()) {
                    setContentAreaFilled(true);
                }
            }

            @Override
            public void mouseExited(MouseEvent e) {
                setBorderPainted(false);
                setContentAreaFilled(false);
            }
        });
    }
}

