public class VariableCheckFunctionDecorator<X> implements DifferentialFunction<X> {

    private final DifferentialFunction<X> function;
    private final Map<Variable<X>, List<DifferentialFunctionPredicateChecker<X>>> variableCheckerMap;

    public VariableCheckFunctionDecorator(DifferentialFunction<X> function) {
        this.function = function;
        this.variableCheckerMap = new HashMap<>();
    }

    public VariableCheckFunctionDecorator(DifferentialFunction<X> function, Map<Variable<X>, List<DifferentialFunctionPredicateChecker<X>>> variableCheckerMap) {
        this.function = function;
        this.variableCheckerMap = new HashMap<>(variableCheckerMap);
    }

    public void addArgTest(Variable<X> v, Predicate<X> predicate, String errorMessage) {
        variableCheckerMap.computeIfAbsent(v, k -> new ArrayList<>())
                .add(new DifferentialFunctionPredicateChecker<>(predicate, errorMessage));
    }

    private void checkVariables() {
        variableCheckerMap.forEach(this::checkVariable);
    }

    private void checkVariable(Variable<X> variable, List<DifferentialFunctionPredicateChecker<X>> checkers) {
        X value = variable.getReal();
        for (DifferentialFunctionPredicateChecker<X> checker : checkers) {
            if (!checker.test(value)) {
                throw new IllegalArgumentException(checker.getErrorMessage());
            }
        }
    }

    @Override
    public X getValue() {
        checkVariables();
        return function.getValue();
    }

    @Override
    public Double getReal() {
        checkVariables();
        return function.getReal();
    }

    @Override
    public DifferentialFunction<X> diff(Variable<X> v) {
        DifferentialFunction<X> diffFunc = function.diff(v);
        return new VariableCheckFunctionDecorator<>(diffFunc, variableCheckerMap);
    }

    private static class DifferentialFunctionPredicateChecker<X> {
        private final Predicate<X> predicate;
        private final String errorMessage;

        public DifferentialFunctionPredicateChecker(Predicate<X> predicate, String errorMessage) {
            this.predicate = predicate;
            this.errorMessage = errorMessage;
        }

        public boolean test(X value) {
            return predicate.test(value);
        }

