class Main {
    public int minMaxDifference(int[] nums, int p) {
        if (p == 0) {
            return 0;
        }

        int n = nums.length;
        Arrays.sort(nums);

            int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= n - p; i++) {
            ans = Math.min(ans, nums[i + p - 1] - nums[i]);
        }
        return ans;
    }
}

