/**
 * Entity representing a group of stations.
 * This class supports hierarchical structures by linking to a parent group and managing nested groups.
 */
@Entity
@Table(name = "STATION_GROUPS")
@NamedQuery(name = "StationGroup.findAll", query = "SELECT sg FROM StationGroup sg")
public class StationGroup implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @SequenceGenerator(name = "station_group_seq", sequenceName = "station_group_seq", allocationSize = 1)
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "station_group_seq")
    private Long id;

    private String name;

    // A station group may contain many stations.
    @OneToMany(mappedBy = "stationGroup", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Station> stations = new ArrayList<>();

    // A station group can have many child station groups.
    @OneToMany(mappedBy = "parentGroup", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<StationGroup> childGroups = new ArrayList<>();

    // Self-referencing many-to-one: many child groups can belong to one parent group.
    @ManyToOne
    @JoinColumn(name = "PARENT_GROUP_ID")
    private StationGroup parentGroup;

    public StationGroup() {
        // Default constructor required by JPA
    }

    public StationGroup(String name) {
        this.name = name;
    }

    // Getter and Setter methods

    public Long getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    public List<Station> getStations() {
        return stations;
    }

    public void setStations(List<Station> stations) {
        this.stations = stations;
    }

    public List<StationGroup> getChildGroups() {
        return childGroups;
    }

    public void setChildGroups(List<StationGroup> childGroups) {
        this.childGroups = childGroups;
    }

    public StationGroup getParentGroup() {
        return parentGroup;
    }

    public void setParentGroup(StationGroup parentGroup) {

