public class TrackInfo implements Info {

    private final static String TAG = TrackInfo.class.getName();

    public static final String TRACKINFO_KEY_ARTIST = "Artist";

    public static final String TRACKINFO_KEY_ID = "Id";

    public static final String TRACKINFO_KEY_NAME = "Name";

    public static final String TRACKINFO_KEY_URL = "Url";

    private ArtistInfo mArtist;

    private String mId;

    private String mName;

    private String mUrl;

    @Override
    public void parseInfo(JSONObject rawInfo) {
        try {
            if (!rawInfo.isNull(TRACKINFO_KEY_ARTIST)) {
                JSONObject rawArtistInfo = rawInfo.getJSONObject(TRACKINFO_KEY_ARTIST);
                mArtist = new ArtistInfo();
                mArtist.parseInfo(rawArtistInfo);
            }
            if (!rawInfo.isNull(TRACKINFO_KEY_ID)) {
                mId = rawInfo.getString(TRACKINFO_KEY_ID);
            }
            if (!rawInfo.isNull(TRACKINFO_KEY_NAME)) {
                mName = rawInfo.getString(TRACKINFO_KEY_NAME);
            }
            if (!rawInfo.isNull(TRACKINFO_KEY_URL)) {
                mUrl = rawInfo.getString(TRACKINFO_KEY_URL);
            }
        } catch (JSONException e) {
            Log.e(TAG, "parseInfo: " + e.getClass() + ": " + e.getLocalizedMessage());
        }
    }

    public ArtistInfo getArtist() {
        return mArtist;
    }

    public String getId() {
        return mId;
    }

    public String getName() {
        return mName;
    }

    public String getUrl() {
        return mUrl;
    }
}

class Task {
    public List<Boolean> checkIfPrerequisite(int n, int[][] prerequisites, int[][] queries) {
        List<Integer>[] parents = new List[n];
        for (int i = 0; i < n; ++i) parents[i] = new LinkedList();
        for (int[] p : prerequisites) {
            parents[p[1]].add(p[0]);
        }
        List<Boolean> res = new LinkedList();
        Map<Integer, Boolean> memo = new HashMap();
        for (int[] q : queries) res.add(isParent(q[1], q[0], parents, memo));
        return res;
    }
    private boolean isParent(int c, int p, List<Integer>[] parents, Map<Integer, Boolean> memo) {
        int key = (p << 8) | c;
        Boolean cache = memo.get(key);
        if (null != cache) return cache;
        for (int j : parents[c]) {
            if (j == p || isParent(j, p, parents, memo)) {
                memo.put(key, true);
                return true;
            }
        }
        memo.put(key, false);
        return false;
    }
}

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.util.HashMap;
import java.util.Map;

class VCardParameterCaseClasses<T extends VCardParameter> {

    private final Class<T> clazz;
    private final Map<String, T> values = new HashMap<>();

    public VCardParameterCaseClasses(Class<T> clazz, T[] constants) {
        this.clazz = clazz;
        for (T constant : constants) {
            values.put(constant.value().toLowerCase(), constant);
        }
    }

    public T create(String value) {
        try {
            Constructor<T> constructor = null;
            try {
                constructor = clazz.getDeclaredConstructor(String.class);
            } catch (NoSuchMethodException e) {
                // ignore
            }
            if (constructor != null) {
                return constructor.newInstance(value);
            }

            //try constructor with String and VCardVersion[]
            constructor = clazz.getDeclaredConstructor(String.class);

            if (constructor != null) {
                return constructor.newInstance(value);
            }

            return null;

        } catch (NoSuchMethodException | IllegalAccessException | InvocationTargetException | InstantiationException e) {
            return null;
        }
    }

    public T matches(String value) {
        return values.get(value.toLowerCase());
    }

    public interface VCardParameter {
        String value();
    }
}

import java.util.*;

public class Product {

    static int n, m;

    static char[][] g;

    static int[] d = new int[]{1, 0, -1, 0, 1};

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();

        while (T-- > 0) {

            n = sc.nextInt();

            m = sc.nextInt();

            sc.nextLine();

            g = new char[n][m];

            for (int i = 0; i < n; i++) g[i] = sc.nextLine().toCharArray();

            for (int i = 0; i < n; i++) {

                for (int j = 0; j < m; j++) {

                    if (g[i][j] == 'B') {

                        for (int k = 0; k < 4; k++) {

                            int fx = i + d[k];

                            int fy = j + d[k + 1];

                            if (ok(fx, fy) && g[fx][fy] == '.') g[fx][fy] = '#';

                        }

                    }

                }

            }

            //统计多个点是否能到终点 转化思维求终点是否能到多个点即可

            if (bfs()) System.out.println("Yes");

            else System.out.println("No");

        }

    }

    static boolean bfs() {

        boolean[][] vis = new boolean[n][m];

        Queue<int[]> q = new ArrayDeque<>();

        if (g[n - 1][m - 1] != '#') q.add(new int[]{n - 1, m - 1});

        while (!q.isEmpty()) {

            int[] t = q.poll();

            for (int i = 0; i < 4; i++) {

                for (int k = 0; k < 4; k++) {

                    int fx = t[0] + d[k];

                    int fy = t[1] + d[k + 1];

                    if (ok(fx, fy) && !vis[fx][fy] && g[fx][fy] != '#') {

                        q.add(new int[]{fx, fy});

                        vis[fx][fy] = true;

                    }

                }

            }

        }

        boolean flag = true;

        for (int i = 0; i < n; i++) {

            for (int j = 0; j < m; j++) {

                if ((g[i][j] == 'G' && !vis[i][j]) || (g[i][j] == 'B' && vis[i][j])) return false;

            }

        }

        return true;

    }

    static boolean ok(int fx, int fy) {

        return fx >= 0 && fy >= 0 && fx < n && fy < m ;

    }

}

private void updateBundlesDirtyState(List<JoinableResourceBundle> bundles, CssSmartSpritesResourceReader cssSpriteResourceReader) {
    for (JoinableResourceBundle bundle : bundles) {
        if (bundle.isDirty()) {
            continue;
        }
        // Check if the bundle needs to be marked as dirty
        if (cssSpriteResourceReader.isResourceDirty(bundle)) {
            bundle.setDirty(true);
        }
    }
}

import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
 
public class Proper{
    public static List<Integer> properDivs(int n){
        List<Integer> divs = new LinkedList<Integer>();
        if(n == 1) return divs;
        divs.add(1);
        for(int x = 2; x < n; x++){
            if(n % x == 0) divs.add(x);
        }
 
        Collections.sort(divs);
 
        return divs;
    }
 
    public static void main(String[] args){
        for(int x = 1; x <= 10; x++){
            System.out.println(x + ": " + properDivs(x));
        }
 
        int x = 0, count = 0;
        for(int n = 1; n <= 20000; n++){
            if(properDivs(n).size() > count){
                x = n;
                count = properDivs(n).size();
            }
        }
        System.out.println(x + ": " + count);
    }
}

