        ChainShape groundShapeBottom = new ChainShape();
        ChainShape groundShapeTop = new ChainShape();
        Vector2 groundPos = new Vector2(-30, -10);
        Vector2 topPos = new Vector2(-30, 10);

        groundShapeBottom.createChain(new Vector2[]{
                new Vector2(groundPos.x, groundPos.y), new Vector2(30, groundPos.y)
        });

        groundShapeTop.createChain(new Vector2[]{
                new Vector2(topPos.x, topPos.y), new Vector2(30, topPos.y)
        });

        BodyDef bodyDef = new BodyDef();
        bodyDef.type = BodyDef.BodyType.StaticBody;
        body = world.createBody(bodyDef);

        FixtureDef fixtureDef = new FixtureDef();
        fixtureDef.shape = groundShapeBottom;
        fixtureDef.friction = 0;
        fixture = body.createFixture(fixtureDef);

        fixtureDef.shape = groundShapeTop;
        fixture = body.createFixture(fixtureDef);

        groundShapeBottom.dispose();
        groundShapeTop.dispose();
        world.setContactFilter(new ContactFilter() {
            @Override
