--------------------------------
|            Fan               |
--------------------------------
| - SLOW: int = 1              |
| - MEDIUM: int = 2            |
| - FAST: int = 3              |
| - speed: int = SLOW          |
| - on: boolean = false        |
| - radius: double = 5.0       |
| - color: String = "blue"     |
--------------------------------
| + getSpeed(): int            |
| + setSpeed(speed: int): void |
| + isOn(): boolean            |
| + setOn(on: boolean): void   |
| + getRadius(): double        |
| + setRadius(radius: double): void |
| + getColor(): String         |
| + setColor(color: String): void |
| + Fan()                      |
| + toString(): String         |
--------------------------------
 public class Fan {
    // Constants
    public static final int SLOW = 1;
    public static final int MEDIUM = 2;
    public static final int FAST = 3;

    // Fields
    private int speed;
    private boolean on;
    private double radius;
    private String color;

    // Constructors
    public Fan() {
        speed = SLOW;
        on = false;
        radius = 5.0;
        color = "blue";
    }

    // Accessor and mutator methods
    public int getSpeed() {
        return speed;
    }

    public void setSpeed(int speed) {
        this.speed = speed;
    }

    public boolean isOn() {
        return on;
    }

    public void setOn(boolean on) {
        this.on = on;
    }

    public double getRadius() {
        return radius;
    }

    public void setRadius(double radius) {
        this.radius = radius;
    }

    public String getColor() {
        return color;
    }

    public void setColor(String color) {
        this.color = color;
    }

    // toString method
    public String toString() {
        if (on) {
            return "speed=" + speed + ", color=" + color + ", radius=" + radius;
        } else {
            return "color=" + color + ", radius=" + radius + ", fan is off";
        }
    }
}

import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

public class Stack {
    public boolean isBipartite(int[][] graph) {
        int n = graph.length;
        boolean[] visited = new boolean[n];
        Set<Integer> setA = new HashSet<>();
        Set<Integer> setB = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();

        for (int node = 0; node < n; node++) {
            if (!visited[node]) {
                setA.add(node);
                visited[node] = true;
                queue.offer(node);

                while (!queue.isEmpty()) {
                    int current = queue.poll();
                    Set<Integer> currentSet = setA.contains(current) ? setA : setB;
                    Set<Integer> oppositeSet = currentSet == setA ? setB : setA;

                    for (int neighbor : graph[current]) {
                        if (currentSet.contains(neighbor)) {
                            return false;
                        }
                        if (!visited[neighbor]) {
                            oppositeSet.add(neighbor);
                            visited[neighbor] = true;
                            queue.offer(neighbor);
                        }
                    }
                }
            }
        }
        return true;
    }
}

public class MinimumElamaninIndisi {

    public static int minimumIndis(int[] dizi) {
        // Eger dizi bos veya null ise -1 dondur
        if (dizi == null || dizi.length == 0) {
            return -1;
        }

        int minIndis = 0; // Minimum elemanin indisi
        for (int i = 1; i < dizi.length; i++) {
            // Her elemani minimum eleman ile karsilastir
            System.out.println(dizi[i] + " ile " + dizi[minIndis] + " karsilastir.");
            if (dizi[i] < dizi[minIndis]) {
                minIndis = i; // Yeni minimum elemanin indisini guncelle
            }
        }
        return minIndis; // Minimum elemanin indisini dondur
    }

    public static void main(String[] args) {
        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};
        int minIndis = minimumIndis(dizi);

        // Minimum elemanin indisini kontrol et ve yazdir
        if (minIndis != -1) {
            System.out.println("Dizideki minimum elemanin indisi: " + minIndis);
        } else {
            System.out.println("Dizi bos veya null.");
        }
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public boolean matches(String digest) {
    try {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        String computedDigest = bytesToHex(md.digest());
        return computedDigest.equals(digest);
    } catch (NoSuchAlgorithmException e) {
        e.printStackTrace();
        return false;
    }
}

private String bytesToHex(byte[] bytes) {
    StringBuilder hexString = new StringBuilder();
    for (byte aByte : bytes) {
        String hex = Integer.toHexString(0xFF & aByte);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString();
}

