import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.InitializingBean;
import org.springframework.context.annotation.Scope;
import org.springframework.stereotype.Component;

import java.io.Serializable;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;

@Component
@Scope("prototype")
public class StatefulObject implements InitializingBean, Serializable {
    private static final long serialVersionUID = 1L;
    private static final Logger logger = LoggerFactory.getLogger(StatefulObject.class);

    private transient Object processInstance;
    private String customerId;
    private AtomicInteger visitedCount;
    private UUID processInstanceId;
    private String processDefinitionKey;
    private boolean processed;

    public StatefulObject() {
        this.visitedCount = new AtomicInteger(0);
        this.processInstanceId = UUID.randomUUID();
        this.processed = false;
    }

    public void increment() {
        int currentVisits = visitedCount.incrementAndGet();
        logger.info("Process interaction incremented: {} for customer {}", currentVisits, customerId);
    }

    public void setCustomerId(String customerId) {
        this.customerId = customerId;
        logger.debug("Customer ID set: {}", customerId);
    }

    public String getCustomerId() {
        return customerId;
    }

    public int getVisitedCount() {
        return visitedCount.get();
    }

