import java.util.*;
import java.io.*;

public class Shape {
    static final long MOD = 998244353;

    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);

        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }

        long[] ways = new long[n];
        ways[0] = a[0];
        for (int i = 1; i < n; i++) {
            long same = ways[i - 1] * (a[i - 1] - 1) % MOD;
            long diff = (ways[i - 1] + a[i - 1]) * (a[i] - 1) % MOD;
            ways[i] = ((same + diff) % MOD * a[i]) % MOD;
        }

        out.println((ways[n - 1] * (a[n - 1] - 1) % MOD) + MOD) % MOD);
        out.close();
    }

    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}

/*
 * Ornek: birden fazla arka plan islemini ayri thread'lerde paralel
 * yurutup, ana thread bir sure kendi isini yaptiktan sonra hepsini
 * kontrollu bicimde durduran ve tamamlanmalarini bekleyen program.
 */

public class ArkaPlanGorevi implements Runnable {

    private final String etiket;
    private volatile boolean aktif = true;

    public ArkaPlanGorevi(String etiket) {
        this.etiket = etiket;
    }

    /** Gorev durdurulana ya da 10 tur tamamlanana kadar ilerleme mesaji basar. */
    @Override
    public void run() {
        int turSayaci = 0;
        while (aktif && turSayaci < 10) {
            System.out.println(etiket + " calisiyor: " + turSayaci);
            try {
                Thread.sleep(400);
            } catch (InterruptedException kesinti) {
                System.out.println(etiket + " kesildi.");
                return;
            }
            turSayaci++;
        }
        System.out.println(etiket + " tamamlandi.");
    }

    /** Calisan gorevi bir sonraki kontrol noktasinda sonlandirmak icin bayragi indirir. */
    public void durdur() {
        aktif = false;
    }

    public static void main(String[] args) throws InterruptedException {
        ArkaPlanGorevi ilkGorev = new ArkaPlanGorevi("Gorev-1");
        ArkaPlanGorevi ikinciGorev = new ArkaPlanGorevi("Gorev-2");
        ArkaPlanGorevi ucuncuGorev = new ArkaPlanGorevi("Gorev-3");

        Thread ilkIsParcacigi = new Thread(ilkGorev, "Thread-1");
        Thread ikinciIsParcacigi = new Thread(ikinciGorev, "Thread-2");
        Thread ucuncuIsParcacigi = new Thread(ucuncuGorev, "Thread-3");

        ilkIsParcacigi.start();
        ikinciIsParcacigi.start();
        ucuncuIsParcacigi.start();

        anaThreadMesguletmesi();

        beklemeSuresiTanimla(5000);

        System.out.println("Tum gorevler durduruluyor...");
        ilkGorev.durdur();
        ikinciGorev.durdur();
        ucuncuGorev.durdur();

        ilkIsParcacigi.join();
        ikinciIsParcacigi.join();
        ucuncuIsParcacigi.join();

        System.out.println("Tum isler tamamlandi. Program sonlandi.");
    }

    private static void anaThreadMesguletmesi() {
        for (int i = 0; i < 5; i++) {
            System.out.println("Ana thread is yapiyor: " + i);
            beklemeSuresiTanimla(500);
        }
    }

    private static void beklemeSuresiTanimla(long milisaniye) {
        try {
            Thread.sleep(milisaniye);
        } catch (InterruptedException kesinti) {
            kesinti.printStackTrace();
        }
    }
}

public class SummaryParser {

    private static final int SUMMARY_LENGTH = 200;
    private static final int IN = 1;
    private static final int OUT = 0;

    public static String getSummary(String sourceStr) {
        if (StringUtils.isBlank(sourceStr)) {
            return "";
        }

        String cleanedStr = removeHTML(sourceStr);
        cleanedStr = cleanedStr.replaceAll("[\\t\\n\\r\\f]", " ").replace("&nbsp;", " ").trim();
        cleanedStr = cleanedStr.replaceAll(" +", " ");

        if (cleanedStr.length() <= SUMMARY_LENGTH) {
            return cleanedStr;
        } else {
            return cleanedStr.substring(0, SUMMARY_LENGTH) + "...";
        }
    }

    private static String removeHTML(String source) {
        if (StringUtils.isBlank(source))
        {
            return "";
        }
        StringBuilder result = new StringBuilder();
        int currentState = OUT;
        int currentIndex = 0;
        int nextIndex;

        while (currentIndex < source.length()) {
            if (source.charAt(currentIndex) == '<') {
                currentState = IN;
            } else if (source.charAt(currentIndex) == '>') {
                currentState = OUT;
            } else if (currentState == OUT) {
                if (source.charAt(currentIndex) == '&') {
                  nextIndex = checkInHTMLCode(source, currentIndex);
                    if (nextIndex != -1)
                    {
                        currentIndex = nextIndex;
                    }
                    else {
                        result.append(source.charAt(currentIndex));
                    }
                }
                else {
                    result.append(source.charAt(currentIndex));
                }
            }
            currentIndex++;
        }
        return result.toString();
    }
     private static int checkInHTMLCode(String source, int start) {
        int end = source.indexOf(';', start);

        if(end == -1) return -1;

        String subStr = source.substring(start, end+1);

        if(subStr.startsWith("&#") || subStr.startsWith("&lt") || subStr.startsWith("&gt")
                || subStr.startsWith("&amp") || subStr.startsWith("&quot")|| subStr.startsWith("&nbsp"))
            return end;
        return -1;
    }
}
