def countGoodTriplets(nums1, nums2):
    x1 = {num: i for i, num in enumerate(nums1)}
    x2 = {num: i for i, num in enumerate(nums2)}

    good_triplets = 0
    for x, y in combinations(range(len(nums1)), 2):
        if x < y:
            for z in range(x+1, len(nums1)):
                if x1[nums1[x]] < x1[nums1[y]] < x1[nums1[z]] and x2[nums2[x]] < x2[nums2[y]] < x2[nums2[z]]:
                    good_triplets += 1
    return good_triplets

def countGoodTriplets(nums1, nums2):
    dp1 = [0] * len(nums1)
    dp2 = [0] * len(nums2)

    for i in range(len(nums1)-1):
        for j in range(i):
            if nums1[j] < nums1[i]:
                dp1[i] += dp1[j]

    for i in range(len(nums2)-1):
        for j in range(i):
            if nums2[j] < nums2[i]:
                dp2[i] += dp2[j]

    total_triplets = 0
    for i in range(len(nums1)-2):
        for j in range(i+1, len(nums1)-1):
            total_triplets += dp1[i] * dp2[j]

    return total_triplets

