import java.util.Scanner;

public class Library {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();

        for (int i = 0; i < T; i++) {
            int h = scanner.nextInt();
            int m = scanner.nextInt();
            String s = scanner.next();

            String reflectedTime = calculateReflectedTime(h, m, s);
            System.out.println(reflectedTime);
        }
    }

    private static String calculateReflectedTime(int h, int m, String s) {
        int normalizedH = 24 - h;
        int normalizedM = 60 - m;
        int minutesUntilNextHour = normalizedH * 60;
        int minutesUntilNextDay = (24 - h) * 1440 + (60 - m) * 60;

        if (minUntilNextHour <= Integer.parseInt(s.substring(0, 2))) {
            return s;
        } else if (minUntilNextDay <= Integer.parseInt(s.substring(0, 2))) {
            return Integer.toString(normalizedH).concat(":").concat(Integer.toString(normalizedM));
        }

        return "Error: Invalid input";
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Kolakoski {
 
    public static int nextInCycle(List<Integer> c, int index) {
        return c.get(index % c.size());
    }
 
    public static List<Integer> kolakoski(List<Integer> c, int slen) {
        List<Integer> s = new ArrayList<>(slen);
        int i = 0, k = 0;
        while (true) {
            s.add(nextInCycle(c, k));
            if (s.get(k) > 1) {
                for (int j = 1; j < s.get(k); j++) {
                    i++;
                    if (i == slen) {
                        return s;
                    }
                    s.add(s.get(i - 1));
                }
            }
            i++;
            if (i == slen) {
                return s;
            }
            k++;
        }
    }
 
    public static boolean possibleKolakoski(List<Integer> s) {
        int slen = s.size();
        List<Integer> rle = new ArrayList<>(slen);
        int prev = s.get(0);
        int count = 1;
        for (int i = 1; i < slen; i++) {
            if (s.get(i) == prev) {
                count++;
            } else {
                rle.add(count);
                count = 1;
                prev = s.get(i);
            }
        }
        // no point adding final 'count' to rle as we're not going to compare it anyway
        for (int i = 0; i < rle.size(); i++) {
            if (rle.get(i)!= s.get(i)) {
                return false;
            }
        }
        return true;
    }
 
    public static void printInts(List<Integer> ia, String suffix) {
        System.out.print("[");
        int alen = ia.size();
        for (int i = 0; i < alen; i++) {
            System.out.print(ia.get(i));
            if (i < alen - 1) {
                System.out.print(", ");
            }
        }
        System.out.printf("]%s\n", suffix);
    }
 
    public static void main(String[] args) {
        List<List<Integer>> ias = new ArrayList<>(4);
        ias.add(List.of(1, 2));
        ias.add(List.of(2, 1));
        ias.add(List.of(1, 3, 1, 2));
        ias.add(List.of(1, 3, 2, 1));
        int[] slens = {20, 20, 30, 30};
        for (int i = 0; i < ias.size(); i++) {
            int slen = slens[i];
            List<Integer> kol = kolakoski(ias.get(i), slen);
            System.out.printf("First %d members of the sequence generated by ", slen);
            printInts(ias.get(i), ":");
            printInts(kol, "");
            boolean p = possibleKolakoski(kol);
            String poss = "Yes";
            if (!p) {
                poss = "No";
            }

