import javax.ws.rs.client.Client;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class XosApi {

    private static final Logger log = LoggerFactory.getLogger(XosApi.class);

    private final String baseUrl;
    private final XosAccess access;
    private final Client client;

    private static final String EMPTY_STRING = "";
    private static final String EMPTY_JSON_STRING = "{}";

    public XosApi(XosAccess access) {
        this.access = access;
        this.baseUrl = access.getEndpoint();
        this.client = ClientBuilder.newClient();
    }

    public XosAccess access() {
        return this.access;
    }

    public String baseUrl() {
        return this.baseUrl;
    }

    public String restGet(String path) {
        try {
            WebTarget target = client.target(baseUrl).path(path);

            Response response = target.request(MediaType.APPLICATION_JSON_TYPE).get();

            if (response.getStatus() == 200) {
                return response.readEntity(String.class);
            } else {
                log.warn("REST GET request failed with status code: {}", response.getStatus());
                return EMPTY_JSON_STRING;
            }
        } catch (Exception e) {
            log.warn("Error processing REST GET request: {}", e.getMessage());
            return EMPTY_JSON_STRING;
        }
    }

    public interface XosAccess {
        String getEndpoint();
    }

    public static void main(String[] args) {
        // Example usage (replace with your actual implementation)
        XosAccess mockAccess = () -> "http://localhost:8080/api";
        XosApi xosApi = new XosApi(mockAccess);

        String path = "users";
        String response = xosApi.restGet(path);

        System.out.println("Response: " + response);
    }
}

