"""
import time
from typing import List
from typing import Optional

def _solve(str_nums: List[int], n: int) -> Optional[int]:
    n = 2 * n + 1
    str_nums.insert(0, 0)
    str_nums.append(0)
    dp = [0] * n
    max_cost = 0
    for i in range(n):
        for j in range(i, n):
            if str_nums[i] == 0 and str_nums[j] == 0:
                dp[j] = max(dp[j], dp[i])
            elif str_nums[i] == 1 and str_nums[j] == 1:
                dp[j] = max(dp[j], dp[i] + (j - i + 1))
            if dp[j] > max_cost:
                max_cost = dp[j]
    return max_cost

class Student:
    def solve(self, nums: List[int]) -> Optional[int]:
        start = time.perf_counter()
        res = _solve(nums, len(nums) // 2)
        print(f"{time.perf_counter() - start}")
        return res

if __name__ == "__main__":
    nums = list(map(int, input().split()))
    solver = Student()
    solver.solve(nums)

