public class CommandPingDispatcher implements PingDispatcher {

    public CommandPingDispatcher() {
    }

    public boolean isPingSupported(Device device) {
        DCServerFactory dcsFact = (device != null) ? device.getDCServerFactory() : null;
        return ((dcsFact != null) && dcsFact.isCommandSupported(DCServerFactory.COMMAND_PING));
    }

    public boolean sendPing(Device device, String cmdName, String cmdArgs[]) {
        DCServerFactory dcsFact = (device != null) ? device.getDCServerFactory() : null;
        if (dcsFact == null) {
            return false;
        }
        DCServerConfig dcsConfig = dcsFact.getDCServerConfig();
        String cmdType = DCServerFactory.COMMAND_PING;

        byte resp[] = dcsConfig.sendDeviceCommand(device, cmdType, cmdName, cmdArgs);
        return ((resp != null) && (resp.length > 0));
    }
}

private void executeConnectionLostDetection(WebSocket webSocket, long minimumPongTime) {
        if (!(webSocket instanceof WebSocketImpl)) {
            return;
        }
        WebSocketImpl webSocketImpl = (WebSocketImpl) webSocket;
        if( webSocketImpl.getLastPong() < minimumPongTime ) {
            log.trace("Closing connection due to no pong received: {}", webSocketImpl);
            webSocketImpl.closeConnection( CloseFrame.ABNORMAL_CLOSE, "The connection was closed because the other endpoint did not respond with a pong in time. For more information check: https://github.com/TooTallNate/Java-WebSocket/wiki/Lost-connection-detection" );
        } else {
            if( webSocketImpl.isOpen() ) {
                webSocketImpl.sendPing();
            } else {
                log.trace("Trying to ping a non open connection: {}", webSocketImpl);
            }
        }
    }

class Employee {
    public boolean findTarget(TreeNode root, int k) {
        Set<Integer> set = new HashSet<>();
        return dfs(root, set, k);
    }

    private boolean dfs(TreeNode root, Set<Integer> set, int k) {
        if (root == null) return false;
        if (set.contains(k - root.val)) return true;
        set.add(root.val);
        return dfs(root.left, set, k) || dfs(root.right, set, k);
    }
}

 
/**
 * Defines a function to calculate the Kronecker product of two
 * rectangular matrices and tests it with two examples.
 */
public class Product {
  /**
   * Find the Kronecker product of the arguments.
   * @param a The first matrix to multiply.
   * @param b The second matrix to multiply.
   * @return A new matrix: the Kronecker product of the arguments.
   */
  public static int[][] product(final int[][] a, final int[][] b) {
    // Create matrix c as the matrix to fill and return.
    // The length of a matrix is its number of rows.
    final int[][] c = new int[a.length*b.length][];
    // Fill in the (empty) rows of c.
    // The length of each row is the number of columns.
    for (int ix = 0; ix < c.length; ix++) {
      final int num_cols = a[0].length*b[0].length;
      c[ix] = new int[num_cols];
    }
    // Now fill in the values: the products of each pair.
    // Go through all the elements of a.
    for (int ia = 0; ia < a.length; ia++) {
      for (int ja = 0; ja < a[ia].length; ja++) {
        // For each element of a, multiply it by all the elements of b.
        for (int ib = 0; ib < b.length; ib++) {
          for (int jb = 0; jb < b[ib].length; jb++) {
             c[b.length*ia+ib][b[ib].length*ja+jb] = a[ia][ja] * b[ib][jb];
          }
        }
      }
    }
 
    // Return the completed product matrix c.
    return c;
  }
 
