import railo.commons.io.res.Resources;
import railo.commons.io.res.util.ResourceLockImpl;
import railo.commons.io.res.util.ResourceUtil;
import railo.commons.lang.StringUtil;
import railo.runtime.op.Caster;

public class HTTPResourceProvider implements ResourceProvider {

    private int lockTimeout=20000;
    private final ResourceLockImpl lock=new ResourceLockImpl(lockTimeout,false);
    private String scheme="http";
    private int clientTimeout=30000;
    private int socketTimeout=20000;
    private Map arguments;

    public String getScheme() {
        return scheme;
    }

    public String getProtocol() {
        return scheme;
    }

    public void setScheme(String scheme) {
        if(!StringUtil.isEmpty(scheme))this.scheme=scheme;
    }

    public ResourceProvider init(String scheme, Map arguments) {
        setScheme(scheme);

        if(arguments!=null) {
            this.arguments=arguments;
            // client-timeout
            String strTimeout=(String) arguments.get("client-timeout");
            if(strTimeout!=null) {
                clientTimeout = Caster.toIntValue(strTimeout,clientTimeout);
            }
            // socket-timeout
            strTimeout=(String) arguments.get("socket-timeout");
            if(strTimeout!=null) {
                socketTimeout=Caster.toIntValue(strTimeout,socketTimeout);
            }
            // lock-timeout
            strTimeout = (String) arguments.get("lock-timeout");
            if(strTimeout!=null) {
                lockTimeout=Caster.toIntValue(strTimeout,lockTimeout);
            }
        }
        lock.setLockTimeout(lockTimeout);
        return this;
    }

    @Override
    public Resource getResource(String path) {

        int indexQ=path.indexOf('?');
        if(indexQ!=-1){
            int indexS=path.lastIndexOf('/');
            while((indexS=path.lastIndexOf('/'))>indexQ){
                path=path.substring(0,indexS)+"%2F"+path.substring(indexS+1);
            }
        }

        path=ResourceUtil.translatePath(ResourceUtil.removeScheme(scheme,path),false,false);

        return new HTTPResource(this,new HTTPConnectionData(path,getSocketTimeout()));
    }

    public boolean isAttributesSupported() {
        return false;
    }

    public boolean isCaseSensitive() {
        return false;
    }

    public boolean isModeSupported() {
        return false;
    }

    public void setResources(Resources resources) {
    }

    @Override

import java.util.*;

public class Writer {
    public static void main(String[] args) {
        Random random = new Random();
        int lottery = random.nextInt(999);
        if (lottery < 100) {
            lottery += 99;
        }
        String lotAsStr = lottery + "";

        Scanner input = new Scanner(System.in);
        System.out.print("Enter your lottery pick as an integer of three digits: ");
        String guess = input.nextLine().trim();

        ArrayList<Integer> playedNums = new ArrayList<>();
        ArrayList<Integer> lotNums = new ArrayList<>();
        for (int i = 0; i < guess.length(); i++) {
            playedNums.add(Integer.parseInt(guess.charAt(i) + ""));
        }
        for (int i = 0; i < lotAsStr.length(); i++) {
            lotNums.add(Integer.parseInt(lotAsStr.charAt(i) + ""));
        }

        int matches = numberOfMatches(lotNums, playedNums);
        System.out.println("The lottery number is " + lottery);
        input.close();

        if (lottery == Integer.parseInt(guess)) {
            System.out.println("Exact match: you win $10,000");
        } else if (matches == 3) {
            System.out.println("Match all digits: you win $3,000");
        } else if (matches == 2) {
            System.out.println("Match two digits: you win $2,000");
        } else if (matches == 1) {
            System.out.println("Match one digit: you win $1,000");
        } else {
            System.out.println("Sorry no match, play again!!!");
        }

    }

    static int numberOfMatches(ArrayList<Integer> lotNums, ArrayList<Integer> playedNums) {
        int matched = 0;

        for (int i = 0; i < playedNums.size(); i++) {
            if (lotNums.contains(playedNums.get(i))) {
                matched++;
            }
        }
        return matched;
    }

}

