import java.util.*;
public class Matrix {
 public static void main(String[] args) {
  try (Scanner sc = new Scanner(System.in)) {
   int n = sc.nextInt();
   long[] a = new long[n];
   for (int i = 0; i < n; i++) {
    a[i] = sc.nextLong();
   }
   for (int i = 0; i < n; i++) {
    long num = a[i];
    ArrayList<Long> factors = new ArrayList<>();
    for (long j = 2; j * j <= num; j++) {
     while (num % j == 0) {
      factors.add(j);
      num /= j;
     }
    }
    if (num > 1) {
     factors.add(num);
    }
    Collections.sort(factors);
    long[] divisors = new long[factors.size()];
    for (int k = 0; k < factors.size(); k++) {
     divisors[k] = factors.get(k);
    }
    for (int j = 0; j < divisors.length; j++) {
     for (int l = 0; l < divisors.length; l++) {
      if (j != l && gcd(divisors[j], divisors[l]) == 1) {
       System.out.println(divisors[j] + " " + divisors[l]);
       return;
      }
     }
    }
    System.out.println(-1 + " " -1);
   }
  }
 }

 static long gcd(long a, long b) {
  return (b == 0) ? a : gcd(b, a % b);
 }
}

import java.util.ArrayList;
import java.util.List;

public class Matrix {
    public static void main(String[] args) {
        int[] nums = {10, 6, -30, 9, 18, 1, -20};
        patienceSort(nums);
        for (int i = 0; i < nums.length; i++) {
            System.out.print(nums[i] + " ");
        }
    }

    public static void patienceSort(int[] nums) {
        List<List<Integer>> piles = new ArrayList<>();

        for (int i = 0; i < nums.length; i++) {
            int num = nums[i];
            int destinationPileIndex = -1;
            for (int j = 0; j < piles.size(); j++) {
                List<Integer> pile = piles.get(j);
                if (num >= pile.get(pile.size() - 1)) {
                    destinationPileIndex = j;
                    break;
                }
            }
            if (destinationPileIndex == -1) {
                List<Integer> newPile = new ArrayList<>();
                newPile.add(num);
                piles.add(newPile);
            } else {
                piles.get(destinationPileIndex).add(num);
            }
        }

        for (int i = 0; i < nums.length; i++) {
            int destinationPileIndex = 0;
            for (int j = 1; j < piles.size(); j++) {
                List<Integer> pile = piles.get(j);
                if (pile.get(0) < piles.get(destinationPileIndex).get(0)) {
                    destinationPileIndex = j;
                }
            }
            List<Integer> distPile = piles.get(destinationPileIndex);
            nums[i] = distPile.get(0);
            distPile.remove(0);
            if (distPile.size() == 0) {
                piles.remove(destinationPileIndex);
            }
        }
    }
}

