class CvsCheckinHandlerFactory extends VcsCheckinHandlerFactory {

  CvsCheckinHandlerFactory() {
    super(CvsVcs2.getKey());
  }

  @NotNull
  @Override
  protected CheckinHandler createVcsHandler(final CheckinProjectPanel panel) {
    return new CheckinHandler() {
      @Nullable
      public RefreshableOnComponent getAfterCheckinConfigurationPanel(Disposable parentDisposable) {
        final Project project = panel.getProject();
        final CvsVcs2 cvs = CvsVcs2.getInstance(project);
        final ProjectLevelVcsManager vcsManager = ProjectLevelVcsManager.getInstance(project);
        final Collection<VirtualFile> roots = panel.getRoots();
        final Collection<FilePath> files = new HashSet<>();
        for (VirtualFile root : roots) {
          final VcsRoot vcsRoot = vcsManager.getVcsRootObjectFor(root);
          if (vcsRoot == null || vcsRoot.getVcs() != cvs) {
            continue;
          }
          files.add(VcsContextFactory.SERVICE.getInstance().createFilePathOn(root));
        }
        return new AdditionalOptionsPanel(CvsConfiguration.getInstance(project), files, project);
      }
    };
  }
}

import java.util.Random;
 
public class Average {
    private static final int NMAX = 20;
    private static final int TESTS = 10000;
    private static final Random RANDOM = new Random();
    private static final double EPSILON = 1e-10;
    private static final double[] FACTORIAL = new double[NMAX + 1];
    static {
        FACTORIAL[0] = 1;
        for (int i = 1; i <= NMAX; i++) {
            FACTORIAL[i] = FACTORIAL[i - 1] * i;
        }
    }
    public static void main(String[] args) {
        System.out.println(" N    average    analytical    (error)");
        System.out.println("===  =========  ============  =========");
        for (int n = 1; n <= NMAX; n++) {
            double a = avg(n);
            double b = ana(n);
            System.out.printf("%3d  %9.4f  %12.4f  (%6.2f%%)\n",
                    n, a, b, Math.abs(a - b) / b * 100);
        }
    }
    private static double avg(int n) {
        int sum = 0;
        for (int t = 0; t < TESTS; t++) {
            boolean[] v = new boolean[n];
            for (int x = 0;!v[x]; x = RANDOM.nextInt(n)) {
                v[x] = true;
                sum++;
            }
        }
        return (double) sum / TESTS;
    }
    private static double ana(int n) {
        double nn = n;
        double term = 1;
        double sum = 1;
        for (int i = n - 1; i >= 1; i--) {
            term *= i / nn;
            sum += term;
        }
        return sum;
    }
}

import static com.google.common.base.Preconditions.checkArgument;
import static com.google.common.base.Preconditions.checkNotNull;

import com.google.common.io.ByteStreams;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.zip.CRC32;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

public class ZipOutputFileProvider implements OutputFileProvider {

  private static final long FIXED_TIMESTAMP = 315532800000L; // 1980-01-01 00:00

  private final ZipOutputStream out;

  public ZipOutputFileProvider(Path destination) throws IOException {
    out =
        new ZipOutputStream(
            new BufferedOutputStream(Files.newOutputStream(checkNotNull(destination))));
  }

  @Override
  public void copyFrom(InputFileProvider inputFileProvider, String filename) throws IOException {
    try (InputStream content = inputFileProvider.getInputStream(filename)) {
      ZipEntry entry = inputFileProvider.getZipEntry(filename);
      out.putNextEntry(entry);
      ByteStreams.copy(content, out);
      out.closeEntry();
    }
  }

  @Override
  public void write(String filename, byte[] content) throws IOException {
        checkArgument(filename.endsWith(".class") || filename.equals(DESUGAR_DEPS_FILENAME));
    writeStoredEntry(out, filename, content);
  }

  private static void writeStoredEntry(ZipOutputStream out, String filename, byte[] content)
      throws IOException {
    CRC32 crc = new CRC32();
    crc.update(content);

    ZipEntry entry = new ZipEntry(filename);
    entry.setTime(FIXED_TIMESTAMP);
    entry.setMethod(ZipEntry.STORED);
    entry.setSize(content.length);
    entry.setCompressedSize(content.length);
    entry.setCrc(crc.getValue());
    out.putNextEntry(entry);
    out.write(content);
    out.closeEntry();
  }

  @Override
  public void close() throws IOException {
    out.close();
  }
}

