import java.util.Scanner;

public class MinCostString {

    public static int[][] pairs = new int[26][26];
    public static int[] counts = new int[26];
    static int letters;

    public static void main(String[] args) {
        var input = new Scanner(System.in);
        var len = input.nextInt();
        letters = input.nextInt();

        var chars = new char[len];
        chars[0] = 'a';
        counts[0] = 1;
        char last = 'a';
        for (int i = 1; i < chars.length; i++) {
            last = findNext(last);
            chars[i] = last;
        }
        System.out.println(chars);
    }

    private static char findNext(char last) {
        int lastIdx = last - 'a';
        int minCount = Integer.MAX_VALUE;
        int[] srcArr = pairs[lastIdx];
        char minChar = '#';
        for (byte i = 0; i < letters; i++) {
            if(srcArr[i] < minCount) {
                minCount = srcArr[i];
                minChar = (char) (i + 'a');
            } else if(srcArr[i] <= minCount && counts[i] < counts[minChar - 'a']) {
                minCount = srcArr[i];
                minChar = (char) (i + 'a');
            }
        }

        srcArr[minChar - 'a']++;

        return minChar;
    }
}

/**
 * Used to evaluate an XPath Expression in a JMS selector.
 */
public final class XPathExpression implements BooleanExpression {

   public static XPathEvaluatorFactory XPATH_EVALUATOR_FACTORY = null;

   static {
      // Install the xalan xpath evaluator if it available.
      new XalanXPathEvaluator("//root").evaluate("<root></root>");
      try {
         XPATH_EVALUATOR_FACTORY = new XPathExpression.XPathEvaluatorFactory() {
            @Override
            public XPathExpression.XPathEvaluator create(String xpath) {
               return new XalanXPathEvaluator(xpath);
            }
         };
      } catch (Throwable e) {
      }
   }

   private final String xpath;
   private final XPathEvaluator evaluator;

   public interface XPathEvaluatorFactory {

      XPathEvaluator create(String xpath);
   }

   public interface XPathEvaluator {

      boolean evaluate(Filterable message) throws FilterException;
   }

   XPathExpression(String xpath) {
      if (XPATH_EVALUATOR_FACTORY == null) {
         throw new IllegalArgumentException("XPATH support not enabled.");
      }
      this.xpath = xpath;
      this.evaluator = XPATH_EVALUATOR_FACTORY.create(xpath);
   }

   @Override
   public Object evaluate(Filterable message) throws FilterException {
      return evaluator.evaluate(message) ? Boolean.TRUE : Boolean.FALSE;
   }

   @Override
   public String toString() {
      return "XPATH " + ConstantExpression.encodeString(xpath);
   }

   /**
    * @param message
    * @return true if the expression evaluates to Boolean.TRUE.
    * @throws FilterException
    */
   @Override
   public boolean matches(Filterable message) throws FilterException {
      Object object = evaluate(message);
      return object == Boolean.TRUE;
   }

}

import java.util.*;

public class LatinSquareChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter number n: ");
        int n = scanner.nextInt();

        // Read the array of characters
        char[][] grid = new char[n][n];
        System.out.println("Enter " + n + " rows of letters separated by spaces:");
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                String s = scanner.next();
                if (s.length() != 1 || s.charAt(0) < 'A' || s.charAt(0) >= 'A' + n) {
                    System.out.println("Wrong input: the letters must be from A to " + (char)('A' + n - 1));
                    return;
                }
                grid[i][j] = s.charAt(0);
            }
        }

        // Check if it's a Latin square
        for (int i = 0; i < n; i++) {
            boolean[] rowUsed = new boolean[n];
            boolean[] colUsed = new boolean[n];
            for (int j = 0; j < n; j++) {
                if (rowUsed[grid[i][j] - 'A'] || colUsed[grid[j][i] - 'A']) {
                    System.out.println("The input array is not a Latin square");
                    return;
                }
                rowUsed[grid[i][j] - 'A'] = true;
                colUsed[grid[j][i] - 'A'] = true;
            }
        }
        System.out.println("The input array is a Latin square");
    }
}

