import java.util.*;

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

public class Parser {

    public TreeNode str2tree(String s) {
        Stack<TreeNode> stack = new Stack<TreeNode>();
        for (int i = 0, j = 0; i < s.length(); i = j) {
            if (s.charAt(i) == '-') {
                j = s.indexOf('-', i + 1);
            } else {
                j = s.indexOf('(', i);
            }
            String numString = (j > 0 ? s.substring(i, j) : s.substring(i));
            int num = Integer.parseInt(numString);
            TreeNode node = new TreeNode(num);

            if (stack.isEmpty()) {
                stack.push(node);
            } else {
                TreeNode tmp = stack.peek();
                if (tmp.left != null) {
                    stack.push(tmp.right = node);
                } else {
                    stack.push(tmp.left = node);
                }
            }
            if (j < 0) {
                break;
            }
            char c;
            while ((c = s.charAt(j)) != '(' && c != ')') {
                j++;
            }
        }
         return stack.isEmpty() ? null : stack.peek().left;
    }
}

