@Override
    @PreAuthorize("hasRole(@configHolder.getSuperAdminRoleName()) or hasPermission(#plugin, 'DELETE')")
    public void delete(E plugin) {
        if (applicationService == null) {
            LOG.error("Plugin cannot be deleted, failed to autowire application service");
            return;
        }
        List<Application> apps = applicationService.findAllWithCollectionContaining("plugins", plugin);
        Integer pluginId = plugin.getId();
        for (Application app : apps) {
            List<Plugin> plugins = app.getPlugins();
            if (plugins != null && plugins.contains(plugin)) {
                String msg = String.format(
                    "Remove plugin (id=%s) from application (id=%s)",
                    pluginId, app.getId()
                );
                LOG.debug(msg);
                plugins.remove(plugin);

                applicationService.saveOrUpdate(app);
            }
        }
        LOG.debug(String.format("Delete plugin (id=%s)", pluginId));

        super.delete(plugin);
    }

import java.util.function.IntPredicate;
import java.util.stream.IntStream;
 
public class Converter {
    public static void main(String[] args) throws Exception {
        print("Java Identifier start:     ", 0, 0x10FFFF, 72,
                Character::isJavaIdentifierStart, "%c");
 
        print("Java Identifier part:      ", 0, 0x10FFFF, 25,
                Character::isJavaIdentifierPart, "[%d]");
 
        print("Identifier ignorable:      ", 0, 0x10FFFF, 25,
                Character::isIdentifierIgnorable, "[%d]");
 
        print("Unicode Identifier start:  ", 0, 0x10FFFF, 72,
                Character::isUnicodeIdentifierStart, "%c");
 
        print("Unicode Identifier part :  ", 0, 0x10FFFF, 25,
                Character::isUnicodeIdentifierPart, "[%d]");
    }
 
    static void print(String msg, int start, int end, int limit,
        IntPredicate p, String fmt) {
 
        System.out.print(msg);
        IntStream.rangeClosed(start, end)
                .filter(p)
                .limit(limit)
                .forEach(cp -> System.out.printf(fmt, cp));
        System.out.println("...");
    }
}

import java.util.Scanner;  // Kullanicidan giris almak icin Scanner sinifini ice aktar

public class UsAlma {

    // 'usAl' metodu, verilen tabanin belirtilen usse gore ussunu hesaplar
    int usAl(int taban, int us) {
        int sonuc = 1;  // Sonuc degiskeni 1 ile baslar cunku herhangi bir sayinin 0. kuvveti 1'dir

        // Dongu, us sayisi kadar doner ve her adimda sonucu taban ile carpar
        for(int i = 0; i < us; i++) {
            sonuc *= taban;
        }

        // Hesaplanan sonuc dondurulur
        return sonuc;
    }

    public static void main(String[] args) {

        // Kullanicidan giris almak icin Scanner nesnesi olustur
        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan taban sayisini girmesini iste
        System.out.println("Lutfen tabani giriniz:");
        int taban = okuyucu.nextInt();  // Kullanicinin girdigi taban sayisi alinir

        // Kullanicidan us sayisini girmesini iste
        System.out.println("Lutfen ussu giriniz:");
        int us = okuyucu.nextInt();  // Kullanicinin girdigi us sayisi alinir

        // UsAlma sinifindan bir nesne olustur
        UsAlma bulucu = new UsAlma();

        // 'usAl' metodunu cagir
        int sonuc = bulucu.usAl(taban, us);

        // Hesaplanan sonuc ekrana yazdirilir
        System.out.println("Sonuc = " + sonuc);

        // Scanner nesnesini kapat
        okuyucu.close();
    }
}

import java.io.DataOutputStream;
import java.io.IOException;
import org.web3d.vrml.lang.*;
import org.web3d.vrml.nodes.VRMLNodeType;

class CompressionTools {
    static int[] rangeCompressIntArray(int[] data, int len) { return data; }
    static float[] compressFloatArray(float[] data, int type, int len) { return data;}
}

public class BinaryFieldEncoder {

    public void compress(DataOutputStream dos, int fieldType, int[] data) throws IOException {
        if (data == null) {
            return;
        }
        int[] compressed_data = CompressionTools.rangeCompressIntArray(data, data.length);
        for (int i = 0; i < compressed_data.length; i++) {
             dos.writeInt(compressed_data[i]);
        }
    }

    public void compress(DataOutputStream dos, int fieldType, float[] data) throws IOException {
        if (data == null) {
            return;
        }

        switch (fieldType) {
            case FieldConstants.SFCOLOR:
            case FieldConstants.SFVEC3F:
                for (int i = 0; i < data.length; i++) {
                    dos.writeFloat(data[i]);
                }
                break;
            case FieldConstants.SFROTATION:
            case FieldConstants.SFCOLORRGBA:
            case FieldConstants.SFVEC2F:
                float[] comp_data1 = CompressionTools.compressFloatArray(data, fieldType, data.length);
                for(int i = 0; i < comp_data1.length; i++){
                    dos.writeFloat(comp_data1[i]);
                }
                break;

            case FieldConstants.MFCOLOR:
            case FieldConstants.MFVEC3F:
            case FieldConstants.MFFLOAT:
            case FieldConstants.MFROTATION:
            case FieldConstants.MFCOLORRGBA:
            case FieldConstants.MFVEC2F:
                float[] comp_data2 = CompressionTools.compressFloatArray(data, fieldType, data.length);
                for (float v : comp_data2) {
                    dos.writeFloat(v);
                }
                break;
            default:
                for(int i=0; i< data.length; i++) {
                    dos.writeFloat(data[i]);
                }
        }
    }
}

