public class HizliSiralama {

    // Quicksort (Hoare tipi bolme) - ayni algoritma, farkli isimlendirme
    public static void sirala(int[] tablo, int baslangic, int bitis) {

        int ortaNokta = baslangic + (bitis - baslangic) / 2;
        int pivot = tablo[ortaNokta];

        int soldanIsaretci = baslangic;
        int sagdanIsaretci = bitis;

        while (soldanIsaretci <= sagdanIsaretci) {

            while (tablo[soldanIsaretci] < pivot) {
                soldanIsaretci++;
            }

            while (tablo[sagdanIsaretci] > pivot) {
                sagdanIsaretci--;
            }

            if (soldanIsaretci <= sagdanIsaretci) {
                takasEt(tablo, soldanIsaretci, sagdanIsaretci);
                soldanIsaretci++;
                sagdanIsaretci--;
            }

            if (baslangic < soldanIsaretci) {
                sirala(tablo, baslangic, sagdanIsaretci);
            }

            if (bitis > soldanIsaretci) {
                sirala(tablo, soldanIsaretci, bitis);
            }
        }
    }

    private static void takasEt(int[] tablo, int a, int b) {
        int yedek = tablo[a];
        tablo[a] = tablo[b];
        tablo[b] = yedek;
    }

    public static void main(String[] args) {
        int[] sayilar = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        sirala(sayilar, 0, sayilar.length - 1);

        StringBuilder cikti = new StringBuilder();
        for (int deger : sayilar) {
            cikti.append(deger).append(' ');
        }
        System.out.println(cikti.toString().trim());
    }
}

public class Vector {
    public int longestSubstring(String s, int k) {
            if (k<0)
                k = 0;
            int[] remaining = new int[26];
            int[] current = new int[26];
            boolean isValid = false;
            int max = 0;
            int len = 0;
            for (int i=0; i<s.length(); i++)
                remaining[s.charAt(i)-'a']++;

            for (int i=0; i<s.length(); i++){
                int c = s.charAt(i)-'a';
                remaining[c]--;
                current[c]++;
                len++;
                if (isValid(current, k))
                    max = Math.max(max, len);
                else if (remaining[c]+current[c] < k){
                    len = 0;
                    current = new int[26];
                }
            }
            return max;
    }

    private boolean isValid(int[] arr, int k){
            for (int i: arr) {
                if (i != 0 && i<k)
                    return false;
            }
            return true;
    }
}

import java.io.BufferedReader;

import java.io.IOException;

import java.io.InputStreamReader;

import java.util.StringTokenizer;

public class Service {

    public static void main(String[] args) throws IOException {

        Reader input = new Reader();

        int t = input.nextInt();

        StringBuilder output = new StringBuilder();

        while(t > 0) {

            int n = input.nextInt();

            int[] r = new int[n];

            for(int i = 0; i < n; ++i) {

                r[i] = input.nextInt();

            }

            int m = input.nextInt();

            int[] b = new int[m];

            for(int i = 0; i < m; ++i) {

                b[i] = input.nextInt();

            }

            int[] sum1 = new int[n];

            sum1[0] = r[0];

            for(int i = 1; i < n; ++i) {

                sum1[i] = r[i]+sum1[i-1];

            }

            int[] sum2 = new int[m];

            sum2[0] = b[0];

            for(int i = 1; i < m; ++i) {

                sum2[i] = b[i]+sum2[i-1];

            }

            output.append(solve(0, 0, r, b, new Integer[n+1][m+1], sum1, sum2));

            --t;

            output.append("\n");

        }

        System.out.print(output);

    }

    static int solve(int p1, int p2, int[] r, int[] b, Integer[][] memo, int[] sum1, int[] sum2) {

        if(p1 >= r.length && p2 >= b.length) {

            return 0;

        }

        if(memo[p1][p2] != null) {

            return memo[p1][p2];

        }

        if(p1 < r.length) {

            memo[p1][p2] = Math.max(sum1[p1]+(p2-1 > -1 ? sum2[p2-1]:0), solve(p1+1, p2, r, b, memo, sum1, sum2));

        }

        if(p2 < b.length) {

            int test = Math.max(sum2[p2]+(p1 > 0 ? sum1[p1-1] : 0), solve(p1, p2+1, r, b, memo, sum1, sum2));

            if(memo[p1][p2] == null || test > (int)memo[p1][p2]) {

                memo[p1][p2] = test;

            }

        }

        return memo[p1][p2];

    }

    static class Reader {

        BufferedReader bufferedReader;

        StringTokenizer string;

        public Reader() {

            InputStreamReader inr = new InputStreamReader(System.in);

            bufferedReader = new BufferedReader(inr);

        }

        public String next() throws IOException {

            while(string == null || ! string.hasMoreElements()) {

                string = new StringTokenizer(bufferedReader.readLine());

            }

            return string.nextToken();

        }

        public int nextInt() throws IOException {

            return Integer.parseInt(next());

        }

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.println("Enter two integers: ");
        int m = in.nextInt();
        int n = in.nextInt();

        System.out.println("The GCD of " + m + " and " + n + " is " + gcd(m, n));

    }

    static int gcd(int m, int n) {
        if (m % n == 0) {
            return n;
        }
        return gcd(n, m % n);
    }
}

private ClassDescriptor getRealClassDescriptor(ClassDescriptor aCld, Object anObj) {
    if (aCld.isInterface()) {
        Class<?>[] interfaces = anObj.getClass().getInterfaces();
        for (Class<?> iface : interfaces) {
            if (iface.getName().equals(aCld.getName())) {
                return new ClassDescriptor(iface);
            }
        }
    }
    return aCld;
}

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class CSV_data_manipulation {
 
    public static void main(String[] args) throws IOException {
        List<String> input = Files.readAllLines(Paths.get("test_in.csv"));
        List<String> output = input.stream().map((line, i) -> {
            if (i == 0)
                return line + ",SUM";
            int sum = Arrays.stream(line.split(",")).mapToInt(Integer::parseInt).sum();
            return line + "," + sum;
        }).collect(Collectors.toList());
        Files.write(Paths.get("test_out.csv"), output);
    }
}

