import org.w3c.dom.Node;
import org.w3c.dom.Document;

public class NodeUtils {

    public static void setNameNS(Node node, String namespaceURI, String qualifiedName) {
        Document doc = node.getOwnerDocument();
        String prefix = qualifiedName.split(":")[0];
        String localName = qualifiedName.split(":")[1];
        node.setPrefix(prefix);
        node.setNamespaceURI(namespaceURI);
        node.setLocalName(localName);
    }
}

import java.util.*;

public class ShortestPathWithObstacle {
    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            scanner.nextLine(); // consume empty line
            Point A = new Point(scanner.nextInt(), scanner.nextInt());
            Point B = new Point(scanner.nextInt(), scanner.nextInt());
            Point F = new Point(scanner.nextInt(), scanner.nextInt());

            // Calculate Manhattan distance considering the forbidden cell F
            int distDirect = Math.abs(A.x - B.x) + Math.abs(A.y - B.y);
            int distAtoF = Math.abs(A.x - F.x) + Math.abs(A.y - F.y);
            int distBtoF = Math.abs(B.x - F.x) + Math.abs(B.y - F.y);

            if (A.equals(F) || B.equals(F)) {
                System.out.println(-1); // unreachable if A or B is F
            } else if (F.x == A.x && F.x == B.x) {
                // If A, B, and F are in the same column
                if (A.y < F.y && F.y < B.y || B.y < F.y && F.y < A.y) {
                    System.out.println(distAtoF + distBtoF + 2); // path through F is blocked
                } else {
                    System.out.println(distDirect);
                }
            } else if (F.y == A.y && F.y == B.y) {
                // If A, B, and F are in the same row
                if (A.x < F.x && F.x < B.x || B.x < F.x && F.x < A.x) {
                    System.out.println(distAtoF + distBtoF + 2); // path through F is blocked
                } else {
                    System.out.println(distDirect);
                }
            } else {
                System.out.println(distDirect);
            }
        }
    }
}

