import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import org.apache.camel.util.ObjectHelper;

public class LocalDatePatternFormat implements PatternFormat<LocalDate> {

  private String pattern;
  private Locale locale;

  public LocalDatePatternFormat() {}

  @Override
  public String format(LocalDate object) throws Exception {
    ObjectHelper.notNull(this.pattern, "pattern");
    return this.getDateFormat().format(object);
  }

  @Override
  public LocalDate parse(String string) throws Exception {
    ObjectHelper.notNull(this.pattern, "pattern");

    if (!doesStringFitLengthOfPattern(string)) {
      throw new IllegalArgumentException(
          "Date provided does not fit the pattern defined, and is not parsable. Date: "
              + string
              + ", pattern: "
              + this.pattern);
    }

    return LocalDate.parse(string, this.getDateFormat());
  }

  protected DateTimeFormatter getDateFormat() {
    DateTimeFormatter result;

    if (locale != null) {
      result = DateTimeFormatter.ofPattern(this.pattern, this.locale);
    } else {
      result = DateTimeFormatter.ofPattern(this.pattern);
    }

    return result;
  }

  public String getPattern() {
    return pattern;
  }

  public void setPattern(String pattern) {
    this.pattern = pattern;
  }

  public Locale getLocale() {
    return locale;
  }

  public void setLocale(Locale locale) {
    this.locale = locale;
  }

  private boolean doesStringFitLengthOfPattern(String string) {
    return string.length() <= this.pattern.length();
  }
}

import java.util.*;

import java.io.*;

public class File {

    public static class FastScanner {

        BufferedReader br;

        StringTokenizer st;

        public FastScanner() {

            br = new BufferedReader(new InputStreamReader(System.in));

        }

        String next() {

            while (st == null || !st.hasMoreElements()) {

                try {

                    st = new StringTokenizer(br.readLine());

                }

                catch (IOException e) {

                    e.printStackTrace();

                }

            }

            return st.nextToken();

        }

        int nextInt() {

            return Integer.parseInt(next());

        }

        long nextLong() {

            return Long.parseLong(next());

        }

    }

    public static void main(String[] args) {

        FastScanner sc = new FastScanner();

        PrintWriter out = new PrintWriter(new BufferedOutputStream(System.out));

        int test=sc.nextInt();

        while(test>0)

        {

            int n=sc.nextInt();

            int arr[]=new int[n];

            for(int i=0;i<n;i++)

            {

                arr[i]=sc.nextInt();

            }

            int f=0;

            for(int i=0;i<n;i++)

            {

                double s=Math.sqrt(arr[i]);

                if(s%1!=0){

                    f=1;

                    break;

                }

            }

            if(f==1)out.println("YES");

            else out.println("NO");

            test--;

        }

        out.close();

    }

}

