/**
 * Reads student names and title-cases each word before storing them.
 */
public class Part3 {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ArrayList<Student> students = new ArrayList<>();
        System.out.print("Enter number student: ");
        int n = scanner.nextInt();
        scanner.nextLine();
        for (int i = 0; i < n; i++) {
            System.out.print("Enter name student " + (i + 1) + ": ");
            String rawName = scanner.nextLine();
            rawName = rawName.trim().replaceAll("\\s+", " ");
            StringTokenizer tokenizer = new StringTokenizer(rawName, " ");
            StringBuilder titled = new StringBuilder();
            while (tokenizer.hasMoreTokens()) {
                String part = tokenizer.nextToken();
                titled.append(part.substring(0, 1).toUpperCase()).append(part.substring(1)).append(" ");
            }
            students.add(new Student(titled.toString().trim()));
        }
        for (Student student : students) {
            System.out.println(student.toString());
        }
    }
}

public void sendJsonToUser(Object data, String username) {
    // Convert data object to JSON string
    String jsonString = convertToJson(data);

    // Get all connections for the user
    List<Connection> connections = getUserConnections(username);

    // Send JSON string to each connection
    for (Connection connection : connections) {
        sendJson(connection, jsonString);
    }
}

private String convertToJson(Object data) {
    // Use Gson to convert data object to JSON string
    Gson gson = new Gson();
    return gson.toJson(data);
}

private List<Connection> getUserConnections(String username) {
    // Retrieve connections from a data structure (e.g., a map)
    return userConnectionsMap.get(username);
}

private void sendJson(Connection connection, String jsonString) {
    // Send JSON string over the connection
    connection.send(jsonString);
}

