class Utils {
    public List<Integer> addToArrayForm(int[] A, int K) {
        List<Integer> res = new ArrayList<>();
        int carrier = 0;
        int i = A.length - 1;
        while (i >= 0 || K > 0 || carrier != 0) {
            int a = 0, b = 0;
            if (i >= 0) {
                a = A[i--];
            }
            if (K > 0) {
                b = K % 10;
                K /= 10;
            }
            int num = a + b + carrier;
            int digit = num % 10;
            carrier = num / 10;
            res.add(digit);
        }
        Collections.reverse(res);
        return res;
    }
}

