@Beta
protected SortedMap<K, V> standardSubMap(K fromKey, K toKey) {
    checkArgument(compare(fromKey, toKey) <= 0, "fromKey must be <= toKey");
  return new SubMap(fromKey, toKey);
}

  @Override
  public SortedMap<K, V> subMap(K fromKey, K toKey) {
    checkArgument(compare(fromKey, this.fromKey) >= 0, "fromKey out of range");
    checkArgument(compare(toKey, this.toKey) <= 0, "toKey out of range");
    return new SubMap(fromKey, toKey);
  }

  @Override
  public SortedMap<K, V> headMap(K toKey) {
    checkArgument(compare(toKey, this.toKey) <= 0, "toKey out of range");
    return new SubMap(this.fromKey, toKey);
  }

  @Override
  public SortedMap<K, V> tailMap(K fromKey) {
    checkArgument(compare(fromKey, this.fromKey) >= 0, "fromKey out of range");
    return new SubMap(fromKey, this.toKey);
  }

  @Override
  public Comparator<? super K> comparator() {
    return SortedMap.this.comparator();
  }

  @Override
  public K firstKey() {
    SortedMap<K, V> headMap = SortedMap.this.headMap(toKey);
    K firstKey = headMap.firstKey();
    if (compare(firstKey, fromKey) < 0) {
      throw new NoSuchElementException();
    }
    return firstKey;
  }

