import java.util.Scanner;

public class NearestBeautifulNumber {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int testCases = scanner.nextInt();

        while (testCases-- > 0) {
            int n = scanner.nextInt();
            int k = scanner.nextInt();
            int x = findNearestBeautifulNumber(n, k);
            System.out.println(x);
        }

        scanner.close();
    }

    private static int findNearestBeautifulNumber(int n, int k) {
        if (k == 1) {
            return n;
        }

        int maxDigit = 9;
        int digitCount = 0;
        int x = n;

        while (digitCount <= k) {
            x++;
            int currentDigitCount = 0;
            while (x > 0) {
                int digit = x % 10;
                if (digitCount == 0 || digit != lastDigit) {
                    digitCount++;
                    lastDigit = digit;
                }
                x /= 10;
            }
            if (digitCount <= k) {
                return x;
            }
        }

        return x - 1;
    }

    private static int lastDigit = -1;
}

class Queue {
        int r,c;
        long max = 0;
        int dir[][] = new int [][]{
            {-1,0} , {1,0},{0,-1},{0,1}
        };
        boolean check(int i,int j)
        {
            if(i>=r || i<0) return false;
            if(j>=c || j<0) return false;
            return true;
        }
        class Node
        {
            int i,j;
            Node(int ii,int jj){
                i = ii;
                j = jj;
            }
        }
        public int maximumMinimumPath(int[][] A) {
            r = A.length;
            c = A[0].length;
            int dp[][] = new int [r][c];
            List<Node> list = new ArrayList<>();
            list.add(new Node(0,0));

            boolean visit[][] = new boolean[r][c];
            visit[0][0] = true;
            for(int i=0;i<r;i++)
            {
                for(int j=0;j<c;j++)
                {
                    dp[i][j] = -1;
                }
            }
            dp[0][0] = A[0][0];

            while(list.size()>0)
            {
                Node top = list.get(0);
                list.remove(0);
                for(int i=0;i<4;i++)
                {
                    int nowI = top.i + dir[i][0];
                    int nowJ = top.j + dir[i][1];
                    if(check(nowI,nowJ))
                    {
                        if(dp[nowI][nowJ]==-1){
                            dp[nowI][nowJ] = dp[top.i][top.j] < A[nowI][nowJ] ?  dp[top.i][top.j] : A[nowI][nowJ];
                            list.add(new Node(nowI,nowJ));
                        }else{
                            int tmp = dp[top.i][top.j] < A[nowI][nowJ] ?  dp[top.i][top.j] : A[nowI][nowJ];
                            if(dp[nowI][nowJ] < tmp)
                            {
                                list.add(new Node(nowI,nowJ));
                                dp[nowI][nowJ] = tmp;
                            }
                        }
                    }
                }
            }
            return dp[r-1][c-1];
        }
    }

