        Result ret = new Result();
        if (res.error != null) {
            ret.error = res.error;
            return ret;
        }

        UpdateDiskOfferingResult value = res.getResult(UpdateDiskOfferingResult.class);
        ret.value = value == null ? new UpdateDiskOfferingResult() : value;

        return ret;
    }

