class Account {
public:
    int findKthLargest(vector<int>& nums, int k) {
        priority_queue<int> r_fin, l_fin, l_fin1, r_fin1;
        int total = nums.size();
        if(total == 1)
            return nums[0];
        int mid = (total%2==0)?(total/2):(total/2);
        for(int i = 0; i < total; i++)
            if(i < mid)
                l_fin.push(nums[i]);
            else
                r_fin.push(nums[i]);
        l_fin1 = l_fin;
        r_fin1 = r_fin;

        int i = 0;
        while(i < k){
            if(!l_fin.empty() &&!r_fin.empty()){
                if(l_fin.top() > r_fin.top()){
                    r_fin.push(l_fin.top());
                    l_fin.pop();
                }
                else{
                    l_fin.push(r_fin.top());
                    r_fin.pop();
                }
            }
            else if(l_fin.empty() &&!r_fin.empty())
                i++;
            else if(!l_fin.empty() && r_fin.empty())
                break;
            else
                break;
            i++;
        }
        if(i == k-1){
            while(!r_fin.empty()){
                if(l_fin1.top() > r_fin1.top()){
                    r_fin1.push(l_fin1.top());
                    l_fin1.pop();
                }
                else{
                    l_fin1.push(r_fin1.top());
                    r_fin1.pop();
                }
            }
        }
        i = 0;

        if(i < k){
            int t = l_fin1.top();
            if(r_fin1.size() == 0)
                return t;
            else
                l_fin1.push(r_fin1.top());
                r_fin1.pop();
            l_fin1.push(t);
        }

        return l_fin1.top();
    }
