     *
     * @param targetPrefabName Name of the prefab to search for.
     * @param callback         Callback to execute once the prefab is found.
     * @param checkInterval    Time interval between scene graph scans.
     * @param sceneRoot        The root node of the scene graph.
     */
    public PlaceholderPrefab(String targetPrefabName, PrefabFoundCallback callback, float checkInterval, Node sceneRoot) {
        this.targetPrefabName = targetPrefabName;
        this.callback = callback;
        this.checkInterval = checkInterval;
        this.sceneRoot = getSceneRoot(sceneRoot);
    }

    /**
     * Traverses up the node hierarchy to identify the scene's root node.
     *
     * @param node The starting node for the traversal.
     * @return The root node of the scene graph.
     */
    private Node getSceneRoot(Node node) {
        Node current = node;
        while (current.getParent() != null && current.getParent() instanceof Node) {
            current = (Node) current.getParent();
        }
        return current;
    }

