import com.opensymphony.xwork2.ActionSupport;
import com.opensymphony.xwork2.ValidationAware;
import com.example.portfolio.model.Portfolio;
import com.example.portfolio.service.PortfolioService;

public class ViewPortfolio extends ActionSupport implements ValidationAware {

    private String username;
    private String portfolioName;
    private Portfolio portfolio;

    public String execute() {
        PortfolioService portfolioService = new PortfolioService();
        try {
            portfolio = portfolioService.getPortfolioByUsernameAndName(username, portfolioName);
            if (portfolio != null) {
                return SUCCESS;
            } else {
                addActionError(getText("error.portfolio.not.found"));
                return ERROR;
            }
        } catch (Exception e) {
            addActionError(getText("error.portfolio.retrieval"));
            return ERROR;
        }
    }

    @Override
    public void validate() {
        if (username == null || username.trim().isEmpty()) {
            addFieldError("username", getText("error.username.required"));
        }
        if (portfolioName == null || portfolioName.trim().isEmpty()) {
            addFieldError("portfolioName", getText("error.portfolioname.required"));
        }
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

    public String getPortfolioName() {
        return portfolioName;
    }

    public void setPortfolioName(String portfolioName) {
        this.portfolioName = portfolioName;
    }

    public Portfolio getPortfolio() {
        return portfolio;
    }

    public void setPortfolio(Portfolio portfolio) {
        this.portfolio = portfolio;
    }

    private PortfolioService getPortfolioService() {
        // This method can be enhanced to use a dependency injection framework
        return new PortfolioService();
    }
}

