/**
 * Utility class encapsulating basic string operations.
 */
public class StringUtils {

    /**
     * Checks if the provided string is numeric.
     * @param s The string to check.
     * @return True if the string is numeric, false otherwise.
     */
    public static boolean isNumeric(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (char c : s.toCharArray()) {
            if (!Character.isDigit(c)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Checks if the provided string contains only alphabetic characters.
     * @param s The string to check.
     * @return True if the string is alphabetic, false otherwise.
     */
    public static boolean isAlphabetic(String s) {
        if (s == null || s.isEmpty()) {
            return false;
        }
        for (char c : s.toCharArray()) {
            if (!Character.isLetter(c)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Converts a string to its hexadecimal representation.
     * @param s The input string.
     * @return The hexadecimal representation of the string.
     */
    public static String toHex(String s) {
        if (s == null) {
            return null;
        }
        StringBuilder hex = new StringBuilder();
        for (char c : s.toCharArray()) {
            hex.append(Integer.toHexString(c));
        }
        return hex.toString();
    }

    /**
     * Checks if string 's' starts with the specified prefix.
     * @param s The main string.
     * @param prefix The prefix to check.
     * @return True if 's' starts with 'prefix', false otherwise.
     */
    public static boolean startsWith(String s, String prefix) {
        if (s == null || prefix == null) {
            return false;
        }
        return s.startsWith(prefix);
    }
}

