import java.util.Scanner;

public class ISBNChecker {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the first 12 digits of the ISBN-13: ");
        String input = scanner.nextLine();

        // Convert input to integer array
        int[] digits = new int[12];
        for (int i = 0; i < 12; i++) {
            digits[i] = Character.getNumericValue(input.charAt(i));
        }

        // Calculate checksum
        int sum = 0;
        for (int i = 0; i < 12; i++) {
            if (i % 2 == 0) {
                sum += digits[i];
            } else {
                sum += digits[i] * 3;
            }
        }
        int checksum = 10 - (sum % 10);
        if (checksum == 10) {
            checksum = 0;
        }

        // Output complete ISBN-13
        System.out.println("The complete ISBN-13 is: " + input + checksum);
    }
}

class Parser {
    public String strWithout3a3b(int A, int B) {
        StringBuilder sb = new StringBuilder();
        if (A < 3 && B < 3 || A == 0 || B == 0) {
            for (int i = 0; i < A; i++) sb.append('a');
            for (int i = 0; i < B; i++) sb.append('b');
            return sb.toString();
        }
        if (A > B) {
            if (A == B + 1) {
                sb.append('a');
                for (int i = 0; i < B; i++) sb.append("ba");
            } else {
                sb.append("aab");
                sb.append(strWithout3a3b(A-2, B-1));
            }
        } else if (A < B) {
            if (A == B - 1) {
                sb.append('b');
                for (int i = 0; i < A; i++) sb.append("ab");
            } else {
                sb.append("bba");
                sb.append(strWithout3a3b(A-1, B-2));
            }
        } else {
            for (int i = 0; i < A; i++) sb.append("ab");
        }
        return sb.toString();
    }
}

