import java.util.Scanner;

public class Validator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int T = scanner.nextInt();
        while (T-- > 0) {
            int n = scanner.nextInt();
            int m = scanner.nextInt();
            int k = scanner.nextInt();
            int[] a = new int[n + 1];
            int f = 0;
            for (int i = 1; i <= n; i++) {
                a[i] = 1;
            }
            while (true) {
                int p = 0;
                for (int i = 1; i <= m; i++) {
                    int op = scanner.nextInt();
                    int x = scanner.nextInt();
                    int y = scanner.nextInt();
                    if (op == 1) {
                        if (a[x] == y) {
                            a[x]++;
                            p = 1;
                        }
                    } else if (op == 2) {
                        int z = scanner.nextInt();
                        if (a[x] + a[y] > z) {
                            if (a[y] > a[x]) {
                                a[y]--;
                            } else {
                                a[x]--;
                            }
                            p = 1;
                        }
                    } else {
                        int z = scanner.nextInt();
                        if (a[x] + a[y] < z) {
                            if (a[y] < a[x]) {
                                a[y]++;
                            } else {
                                a[x]++;
                            }
                            p = 1;
                        }
                    }
                }
                if (p == 0) break;
                if (a[1] > k) {
                    f = 1;
                    break;
                }
                for (int i = 1; i < n; i++) {
                    if (a[i] > a[i + 1]) {
                        a[i + 1] = a[i];
                        p = 1;
                    }
                }
                if (p == 0) break;
                if (a[n] > k) {
                    f = 1;
                    break;
                }
            }
            if (f > 0) {
                System.out.println("-1");
            } else {
                for (int i = 1; i <= n; i++) {
                    System.out.print(a[i] + " ");
                }
                System.out.println();
            }
        }
    }
}

