import java.math.BigInteger;
import java.util.LinkedList;
 
public class SternBrocot {
    static LinkedList<Integer> sequence = new LinkedList<Integer>(){{
        add(1); add(1);
    }};
 
    private static void genSeq(int n){
        for(int conIdx = 1; sequence.size() < n; conIdx++){
            int consider = sequence.get(conIdx);
            int pre = sequence.get(conIdx - 1);
            sequence.add(consider + pre);
            sequence.add(consider);
        }
 
    }
 
    public static void main(String[] args){
        genSeq(1200);
        System.out.println("The first 15 elements are: " + sequence.subList(0, 15));
        for(int i = 1; i <= 10; i++){
            System.out.println("First occurrence of " + i + " is at " + (sequence.indexOf(i) + 1));
        }
 
        System.out.println("First occurrence of 100 is at " + (sequence.indexOf(100) + 1));
 
        boolean failure = false;
        for(int i = 0; i < 999; i++){
            failure |= !BigInteger.valueOf(sequence.get(i)).gcd(BigInteger.valueOf(sequence.get(i + 1))).equals(BigInteger.ONE);
        }
        System.out.println("All GCDs are" + (failure ? " not" : "") + " 1");
    }
}

/**
 * Demonstrates an abstract class with template method pattern.
 */
abstract class Vehicle {
    protected String model;

    public Vehicle(String model) {
        this.model = model;
    }

    // Template method
    public void startJourney() {
        checkFuel();
        start();
        System.out.println(model + " is on its way!");
    }

    protected void checkFuel() {
        System.out.println("Checking fuel level...");
    }

    protected abstract void start();
}

class Car extends Vehicle {
    public Car(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Turning ignition key...");
    }
}

class ElectricScooter extends Vehicle {
    public ElectricScooter(String model) {
        super(model);
    }

    @Override
    protected void start() {
        System.out.println("Pressing power button...");
    }
}

public class VehicleDemo {
    public static void main(String[] args) {
        Vehicle[] vehicles = {new Car("Toyota"), new ElectricScooter("Xiaomi")};
        for (Vehicle vehicle : vehicles) {
            vehicle.startJourney();
        }
    }
}

import com.google.common.base.Joiner;
import com.google.common.collect.Iterables;
import eu.the5zig.mod.The5zigAPI;
import eu.the5zig.util.minecraft.ChatColor;

import java.util.Arrays;
import java.util.Iterator;
import java.util.List;

public class ColorCommandHandler {

    private static final Iterable<ChatColor> RAINBOW_IT = Iterables.cycle(
            ChatColor.RED, ChatColor.GOLD, ChatColor.YELLOW, ChatColor.GREEN,
            ChatColor.AQUA, ChatColor.BLUE, ChatColor.LIGHT_PURPLE, ChatColor.DARK_PURPLE
    );

    public void run(String cmd, List<String> args, CommandOutputPrinter printer) {
        if (args.isEmpty()) {
            StringBuilder lineBuf = new StringBuilder();
            for (ChatColor color : ChatColor.values()) {
                if (color.isColor()) {
                    lineBuf.append(color).append(color.getChar()).append(" = ").append(color.name()).append("\n");
                }
            }
            printer.print(lineBuf.toString());
        } else {
            String text = Joiner.on(' ').join(args);
            StringBuilder fancy = new StringBuilder();
            Iterator<ChatColor> rainbowColors = RAINBOW_IT.iterator();

            for (char c : text.toCharArray()) {
                if (c != ' ') {
                    fancy.append(rainbowColors.next()).append(c);
                } else {
                    fancy.append(c);
                }
            }
            The5zigAPI.getAPI().sendPlayerMessage(fancy.toString());
        }
    }

    public void printUsage(String cmd, CommandOutputPrinter printer) {
        printer.print("Usage: /" + cmd + " [text]");
        printer.print("  - Without arguments: Displays Minecraft color codes.");
        printer.print("  - With text: Applies rainbow colors to the text (Ranked players only).");
    }

    public static void main(String[] args) {
        ColorCommandHandler handler = new ColorCommandHandler();
        CommandOutputPrinter printer = new CommandOutputPrinter() {
            @Override
            public void print(String message) {
                System.out.println(message);
            }
        };

        if (args.length == 0) {
            handler.run("color", Arrays.asList(), printer);
        } else {
            handler.run("color", Arrays.asList(args), printer);
        }
    }
}

import com.intellij.codeInsight.intention.LowPriorityAction;
import com.intellij.codeInspection.LocalQuickFix;
import com.intellij.codeInspection.ProblemDescriptor;
import com.intellij.codeInspection.ex.InspectionProfileModifiableModelKt;
import com.intellij.openapi.project.Project;
import com.intellij.psi.PsiElement;
import com.intellij.psi.util.QualifiedName;
import com.jetbrains.python.inspections.unresolvedReference.PyUnresolvedReferencesInspection;
import org.jetbrains.annotations.NotNull;

/**
 */
public class AddIgnoredIdentifierQuickFix implements LocalQuickFix, LowPriorityAction {
  public static final String END_WILDCARD = ".*";

  @NotNull private final QualifiedName myIdentifier;
  private final boolean myIgnoreAllAttributes;

  public AddIgnoredIdentifierQuickFix(@NotNull QualifiedName identifier, boolean ignoreAllAttributes) {
    myIdentifier = identifier;
    myIgnoreAllAttributes = ignoreAllAttributes;
  }

  @NotNull
  @Override
  public String getName() {
    if (myIgnoreAllAttributes) {
      return "Mark all unresolved attributes of '" + myIdentifier + "' as ignored";
    }
    else {
      return "Ignore unresolved reference '" + myIdentifier + "'";
    }
  }

  @NotNull
  @Override
  public String getFamilyName() {
    return "Ignore unresolved reference";
  }

  @Override
  public boolean startInWriteAction() {
    return false;
  }

  @Override
  public void applyFix(@NotNull Project project, @NotNull ProblemDescriptor descriptor) {
    final PsiElement context = descriptor.getPsiElement();
    InspectionProfileModifiableModelKt.modifyAndCommitProjectProfile(project, model -> {
      PyUnresolvedReferencesInspection inspection =
        (PyUnresolvedReferencesInspection)model.getUnwrappedTool(PyUnresolvedReferencesInspection.class.getSimpleName(), context);
      String name = myIdentifier.toString();
      if (myIgnoreAllAttributes) {
        name += END_WILDCARD;
      }
      assert inspection != null;
      if (!inspection.ignoredIdentifiers.contains(name)) {
        inspection.ignoredIdentifiers.add(name);
      }
    });
  }
}

public class CharVeBooleanOrnegi {

    public static void main(String[] args) {

        // char ve boolean veri turlerini kullanarak degiskenler tanimla
        char karakter = 'A';
        boolean dogruMu = true;

        // Degerleri yazdir
        System.out.println("Karakter: " + karakter);
        System.out.println("Boolean Degeri: " + dogruMu);

        // char verisini int'e donustur (casting)
        int karakterInt = karakter; // char'dan int'e donusum (casting)
        System.out.println("Karakterin ASCII Degeri: " + karakterInt);

        // boolean verisini kullanarak kosullu ifade olusturalim
        if (dogruMu) {
            System.out.println("Bu ifade dogru.");
        } else {
            System.out.println("Bu ifade yanlis.");
        }

        // int verisini char'a donustur (casting)
        int intDeger = 66;
        char charDeger = (char) intDeger; // int'ten char'a donusum (casting)
        System.out.println("ASCII Degerinden Karakter: " + charDeger);

        // char degerini baska bir char ile toplama
        char char1 = 'B';
        char char2 = 'C';
        int toplam = char1 + char2; // char'larin ASCII degerlerinin toplami
        System.out.println("Char1 ve Char2'nin toplami (ASCII Degerleri): " + toplam);

        // boolean veri tipini kullanarak tersini alma islemi
        boolean yanlisMi = !dogruMu; // dogruMu'nun tersi
        System.out.println("Ters deger: " + yanlisMi);

        // boolean ile kosul testi
        if (dogruMu && !yanlisMi) {
            System.out.println("Her iki kosul dogru.");
        } else {
            System.out.println("Kosullardan biri yanlis.");
        }

        // char'in kucuk harfe donusumu
        char kucukHarf = Character.toLowerCase(karakter); // char'i kucuk harfe cevirme
        System.out.println("Karakterin kucuk harfi: " + kucukHarf);

        // char'in buyuk harfe donusumu
        char buyukHarf = Character.toUpperCase(kucukHarf); // char'i buyuk harfe cevirme
        System.out.println("Char'in buyuk harfi: " + buyukHarf);
    }
}

import java.util.concurrent.atomic.AtomicIntegerArray;
import java.util.ArrayList;
import java.util.List;

public class AtomicIntegerArrayTest {
    private static final AtomicIntegerArray ATOMIC_INTEGER_ARRAY = new AtomicIntegerArray(10);

    public static void main(String[] args) throws InterruptedException {
        List<Thread> threads = new ArrayList<>();

        for (int i = 0; i < 100; i++) {
            final int threadNum = i;
            Thread thread = new Thread(() -> {
                int index = threadNum % 10;
                int increment = index + 1;
                int updatedValue = ATOMIC_INTEGER_ARRAY.addAndGet(index, increment);
                System.out.printf("Thread %2d incremented index %d by %d -> %d%n",
                        threadNum, index, increment, updatedValue);
            });
            threads.add(thread);
            thread.start();
        }

        for (Thread thread : threads) {
            thread.join();
        }

        System.out.print("Final array values: [");
        for (int i = 0; i < ATOMIC_INTEGER_ARRAY.length(); i++) {
            System.out.print(ATOMIC_INTEGER_ARRAY.get(i));
            if (i < ATOMIC_INTEGER_ARRAY.length() - 1) {
                System.out.print(", ");
            }
        }
        System.out.println("]");
    }
}

