import java.util.Scanner;

public class MyTriangle {
    public static boolean isValid(double side1, double side2, double side3) {
        return side1 + side2 > side3 && side1 + side3 > side2 && side2 + side3 > side1;
    }

    public static double area(double side1, double side2, double side3) {
        double s = (side1 + side2 + side3) / 2;
        return Math.sqrt(s * (s - side1) * (s - side2) * (s - side3));
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter three sides of a triangle: ");
        double side1 = input.nextDouble();
        double side2 = input.nextDouble();
        double side3 = input.nextDouble();

        if (isValid(side1, side2, side3)) {
            double area = area(side1, side2, side3);
            System.out.println("The area of the triangle is " + area);
        } else {
            System.out.println("Invalid input. The sum of any two sides must be greater than the third side.");
        }
    }
}

import org.json.JSONArray;
import org.json.JSONException;

public class Generator {
    public static void main(String[] args) {
        JSONArray src = new JSONArray("[1, 2, 3]");
        JSONArray dest = new JSONArray("[4, 5, 6]");

        try {
            JSONArray merged = merge(src, dest);
            System.out.println(merged.toString());
        } catch (JSONException e) {
            e.printStackTrace();
        }
    }

    public static JSONArray merge(JSONArray src, JSONArray dest) throws JSONException {
        JSONArray merged = new JSONArray(dest, JSONArray.WRAPPER_ARRAY);
        for (int i = 0; i < src.length(); i++) {
            merged.put(src.get(i));
        }
        return merged;
    }
}

public class SafeAddition {
    private static double stepDown(double d) {
        return Math.nextAfter(d, Double.NEGATIVE_INFINITY);
    }
 
    private static double stepUp(double d) {
        return Math.nextUp(d);
    }
 
    private static double[] safeAdd(double a, double b) {
        return new double[]{stepDown(a + b), stepUp(a + b)};
    }
 
    public static void main(String[] args) {
        double a = 1.2;
        double b = 0.03;
        double[] result = safeAdd(a, b);
        System.out.printf("(%.2f + %.2f) is in the range %.16f..%.16f", a, b, result[0], result[1]);
    }
}

public class ContinuousCommandExecutor {
    private boolean isStarted;

    public void start() {
        isStarted = true;
    }

    public void stop() {
        isStarted = false;
    }

    public void executeCommandContinuously(String command) {
        while (isStarted) {
            try {
                // Execute command here
                Runtime.getRuntime().exec(command);
                Thread.sleep(1000);
            } catch (Exception ex) {
                // Handle exception here
            }
        }
    }
}

class Logger {
  public int countOperations(int num1, int num2) {
    int res = 0;
    while (num1 != 0 && num2 != 0) {
      if (num1 == num2) {
        res++;
        num1=0;
      } else if (num1 < num2) {
        res += num2 / num1;
        num2 %= num1;
      } else {
        res += num1 / num2;
        num1 %= num2;
      }
    }
    return res;
  }
}

