import java.util.*;

public class Counter {
    static final int firstYear = 1;
    static final int lastYear = 30;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        System.out.println("Enter the amount invested: ");
        double amount = in.nextDouble();

        System.out.println("The Annual interest rate as (ex: 5.25 for 5.25%:):  ");
        double yearRate = in.nextDouble();
        yearRate /= 100;

        double monthRate = yearRate / 12;

        System.out.println("Years --- Future Value ");

        for (int i = firstYear; i <= lastYear; i++) {
            System.out.print(i);
            System.out.printf("      %.2f", futureInvestmentValue(amount, monthRate, i));
            System.out.println();
        }

        in.close();
    }

    public static double futureInvestmentValue(double investmentAmount, double monthlyInterestRate, int years) {
        return investmentAmount * Math.pow(1 + monthlyInterestRate, years * 12);
    }
}

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.util.TimeZone;

public class TimezoneDump {
    private static final String DEFAULT_URL = "jdbc:mysql://localhost:3306/mysql?serverTimezone=UTC";
    private static final String TIMEZONE_QUERY = "SELECT @@global.time_zone, @@session.time_zone";

    public static void main(String[] args) {
        String jdbcUrl = args.length > 0 ? args[0] : DEFAULT_URL;

        try {
            Connection connection = getConnection(jdbcUrl);
            if (connection != null) {
                displayTimezoneInfo(connection);
                connection.close();
            }
        } catch (SQLException e) {
            System.err.println("Database connection error: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private static Connection getConnection(String jdbcUrl) throws SQLException {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
            return DriverManager.getConnection(jdbcUrl);
        } catch (ClassNotFoundException e) {
            System.err.println("JDBC Driver not found: " + e.getMessage());
            return null;
        }
    }

    private static void displayTimezoneInfo(Connection connection) throws SQLException {
        try (Statement statement = connection.createStatement();
             ResultSet resultSet = statement.executeQuery(TIMEZONE_QUERY)) {

            if (resultSet.next()) {
                String globalTimezone = resultSet.getString(1);
                String sessionTimezone = resultSet.getString(2);

                System.out.println("MySQL Server Timezones:");
                System.out.println("Global Timezone: " + globalTimezone);
                System.out.println("Session Timezone: " + sessionTimezone);

                String canonicalGlobalTimezone = getCanonicalTimezone(globalTimezone);
                String canonicalSessionTimezone = getCanonicalTimezone(sessionTimezone);

                System.out.println("\nCanonical Java Timezones:");
                System.out.println("Global Canonical Timezone: " + canonicalGlobalTimezone);
                System.out.println("Session Canonical Timezone: " + canonicalSessionTimezone);
            }
        }
    }

    private static String getCanonicalTimezone(String mysqlTimezone) {
        if (mysqlTimezone == null || mysqlTimezone.equals("SYSTEM")) {
            return TimeZone.getDefault().getID();
        }

