public class Rosetta {
 
    public static void main(String[] args) {
        for (int[] test : new int[][] {
            {99809, 1},
            {18, 2},
            {19, 3},
            {20, 4},
            {2017, 24},
            {22699, 1},
            {22699, 2},
            {22699, 3},
            {22699, 4},
            {40355, 3}
        }) {
            System.out.println(partition(test[0], test[1]));
        }
    }
 
    public static String partition(int x, int n) {
        if (x < 1 || n < 1) throw new IllegalArgumentException("Parameters must be positive.");
        String header = x + " with " + n + " " + (n == 1 ? "prime" : "primes") + ": ";
        int[] primes = sievePrimes(x).toArray();
        if (primes.length < n) return header + "not enough primes";
        int[] solution = combinationsOf(n, primes).stream().filter(c -> IntStream.of(c).sum() == x).findFirst().orElse(null);
        return header + (solution == null? "not possible" : Arrays.stream(solution).mapToObj(String::valueOf).collect(Collectors.joining("+")));
    }
 
    static List<Integer> sievePrimes(int bound) {
        if (bound < 2) return new ArrayList<>();
        List<Integer> primes = new ArrayList<>();
        primes.add(2);
 
        BitSet composite = new BitSet((bound - 1) / 2);
        int limit = ((int)(Math.sqrt(bound)) - 1) / 2;
        for (int i = 0; i < limit; i++) {
            if (composite.get(i)) continue;
            int prime = 2 * i + 3;
            primes.add(prime);
            for (int j = (prime * prime - 2) / 2; j < composite.size(); j += prime) composite.set(j);
        }
        for (int i = limit; i < composite.size(); i++) {
            if (!composite.get(i)) primes.add(2 * i + 3);
        }
        return primes;
    }
 
    static List<int[]> combinationsOf(int count, int[] input) {
        List<int[]> result = new ArrayList<>();
        for (int[] indices : combinations(input.length, count)) {
            int[] combination = new int[count];
            for (int i = 0; i < count; i++) combination[i] = input[indices[i]];
            result.add(combination);
        }
        return result;
    }
 
