from collections import deque

def solve():
    mod = 10**9 +7
    t = int(input())
    for _ in range(t):
        n = int(input())
        nums = list(map(int,input().split()))
        counter = {-1:1,1:1}
        next_val = deque([-1])
        res = 0
        for i in range(n):
            temp_counter = {}
            for val in counter:
                if val == nums[i]:
                    res+=counter[val]
                    res%=mod
                elif val + nums[i] in counter:
                    temp_counter[val+nums[i]] = (counter[val] + temp_counter.get(val+nums[i],0)) % mod
                if nums[i] - val in counter:
                    temp_counter[nums[i]-val] = (counter[nums[i]-val] + temp_counter.get(nums[i]-val,0)) % mod
