import java.lang.reflect.AccessibleObject;
import java.lang.reflect.Member;
import java.lang.reflect.Type;
import java.util.Objects;

import org.n52.javaps.description.TypedDataDescription;

import com.google.common.primitives.Primitives;

/**
 * TODO JavaDoc
 *
 */
abstract class AbstractDataBinding<M extends AccessibleObject & Member, D extends TypedDataDescription<?>> extends
        AnnotationBinding<M> {

    private D description;

    AbstractDataBinding(M member) {
        super(member);
    }

    public abstract Type getMemberType();

    public Type getType() {
        return getMemberType();
    }

    public Type getPayloadType() {
        Type type = getType();
        if (isEnum(type)) {
            return String.class;
        }
        if (type instanceof Class<?>) {
            return Primitives.wrap((Class<?>) type);
        }
        return type;
    }

    protected Object outputToPayload(Object outputValue) {
        Type type = getType();
        if (isEnum(type)) {
            return ((Enum<?>) outputValue).name();
        } else {
            return outputValue;
        }
    }

    @SuppressWarnings({ "unchecked", "rawtypes" })
    protected Object payloadToInput(Object payload) {
        Type type = getType();
        if (isEnum(type)) {
            Class<? extends Enum> enumClass = (Class<? extends Enum>) type;
            return Enum.valueOf(enumClass, (String) payload);
        }
        return payload;
    }

    public boolean isEnum() {
        return isEnum(getType());
    }

    public static boolean isEnum(Type type) {
        return (type instanceof Class<?>) && ((Class<?>) type).isEnum();
    }

    public void setDescription(D description) {
        this.description = Objects.requireNonNull(description);
    }

    public D getDescription() {
        return description;
    }

}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
import java.util.stream.Collectors;
 
public class Reader {
    public static void main(String[] args) {
        // Case-sensitive comparisons.
        String a = (args.length > 0)? args[0] : "1.2.Foo";
        String b = (args.length > 1)? args[1] : "1.3.Bar";
        demo_compare(a, b, "lexically");
 
        // Case-insensitive comparisons by folding both strings to a common case.
        a = a.toLowerCase();
        b = b.toLowerCase();
        demo_compare(a, b, "lexically");
 
        // Numeric comparisons; here 'double' could be any type for which the
        // relevant >> operator is defined, eg int, long, etc.
        double numA = Double.parseDouble(a);
        double numB = Double.parseDouble(b);
        demo_compare(numA, numB, "numerically");
    }
 
    public static <T> void demo_compare(T a, T b, String semantically) {
        System.out.println(a + " and " + b + " are " + ((a.equals(b))? "" : "not ")
                + "exactly " + semantically + " equal.");
 
        System.out.println(a + " and " + b + " are " + ((a.equals(b))? "" : "not ")
                + semantically + "inequal.");
 
        System.out.println(a + " is " + ((a.compareTo(b) < 0)? "" : "not ") + semantically
                + " ordered before " + b + '.');
 
        System.out.println(a + " is " + ((a.compareTo(b) > 0)? "" : "not ") + semantically
                + " ordered after " + b + '.');
    }
}

class Builder {
    public int minimumSum(int[] nums) {
        int res=Integer.MAX_VALUE;
        int n=nums.length;
        int[] a=new int[n];
        int[] b=new int[n];
        a[0]=nums[0];
        for(int i=1;i<n;i++){
            a[i]=Math.min(a[i-1],nums[i]);
        }
        b[n-1]=nums[n-1];
        for(int j=n-2;j>=0;j--){
            b[j]=Math.min(b[j+1],nums[j]);
        }
        for(int i=1;i<n-1;i++){
            if(nums[i]>a[i-1] && nums[i]>b[i+1]){
                res=Math.min(res,nums[i]+a[i-1]+b[i+1]);
            }
        }
        if(res==Integer.MAX_VALUE){
            return -1;
        }
        return res;
    }
}

