public String buildScriptName(String scriptContent) {
    String scriptName = "Script";
    try {
        StringReader reader = new StringReader(scriptContent);
        GroovyClassLoader classLoader = new GroovyClassLoader();
        Class parsedClass = classLoader.parseClass(reader, scriptName);
        scriptName = parsedClass.getName();
    } catch (Exception e) {
        // Do nothing, return the default script name
    }
    return scriptName;
}

