class Builder {
    public int countPairs(int[] nums, int k) {
        final int N = nums.length;

        int count = 0;
        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                if (nums[i] == nums[j] && i * j % k == 0) {
                    ++count;
                }
            }
        }
        return count;
    }
}

public String smallestString(String s) {
    char[] chars = s.toCharArray();
    int n = chars.length, i = 0;

    // Find the first non-'a' character
    while (i < n && chars[i] == 'a') {
        i++;
    }

    // If the entire string is 'a', change the last 'a' to 'z'
    if (i == n) {
        chars[n - 1] = 'z';
    } else {
        // Decrement each character in the substring starting from the first non-'a' character until we encounter another 'a'
        while (i < n && chars[i] != 'a') {
            chars[i] = (char) (chars[i] - 1);
            i++;
        }
    }

    return new String(chars);
}

class Checker {
    public String minRemoveToMakeValid(String s) {
        int n = s.length();
        StringBuilder sb = new StringBuilder();
        int x = -1;
        for (int i=0; i<n; i++) {
            if (x == -1) {
                if (s.charAt(i) == '(')
                    x = i;
                else if (s.charAt(i) != ')')
                    sb.append(s.charAt(i));
            } else {
                if (s.charAt(i) == ')') {
                    sb.append('(');
                    for (int j=x+1; j<=i; j++) {
                        if (s.charAt(j) == '(') {
                            x = j;
                            break;
                        }
                        if (j == i)
                            x = -1;
                        sb.append(s.charAt(j));
                    }
                }
            }
        }
        if (x != -1)
            for (int i=x+1; i<n; i++)
                if (s.charAt(i) != '(')
                    sb.append(s.charAt(i));
        return sb.toString();
    }
}

public void evict(int maxSize) {
    if (maxSize == 0) {
        cache.clear();  // Remove all entries if requested size is 0.
    } else if (maxSize > 0 && cache.size() > maxSize) {
        int entriesToRemove = cache.size() - maxSize;
        Iterator<Map.Entry<K, V>> iterator = cache.entrySet().iterator();
        while (iterator.hasNext() && entriesToRemove > 0) {
            iterator.next();
            iterator.remove();
            entriesToRemove--;
        }
    } else if (maxSize == -1) {
        cache.clear();  // Remove all entries if requested size is -1.
    }
}

 
import javax.swing.JFrame;
import javax.swing.JLabel;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
 
class KeyboardMacroDemo {
    public static void main( String [] args ) {
        final JFrame frame = new JFrame();
 
        String directions = "<html><b>Ctrl-S</b> to show frame title<br>"
                                 +"<b>Ctrl-H</b> to hide it</html>";
 
        frame.add( new JLabel(directions));
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
 
        frame.addKeyListener( new KeyAdapter(){
            public void keyReleased( KeyEvent e ) {
                if( e.isControlDown() && e.getKeyCode() == KeyEvent.VK_S){
                    frame.setTitle("Hello there");
                }else if( e.isControlDown() && e.getKeyCode() == KeyEvent.VK_H){
                    frame.setTitle("");
                }
            }
        });
        frame.pack();
        frame.setVisible(true);
    }
}

import com.google.common.util.concurrent.ThreadFactoryBuilder;
import io.gatekeeper.configuration.Configuration;
import io.gatekeeper.configuration.data.ReplicationConfiguration;
import io.gatekeeper.logging.Loggers;
import io.gatekeeper.node.service.replication.common.Node;
import io.gatekeeper.node.service.replication.common.ReplicationInformation;

import java.io.IOException;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Logger;

public abstract class ReplicationService<ReplicationConfigurationType extends ReplicationConfiguration> implements Service {

    protected final ReplicationConfigurationType replicationConfiguration;

    protected final Configuration configuration;

    protected final Logger logger;

    protected final ThreadPoolExecutor executor;

    public ReplicationService(Configuration configuration) {
        assert null != configuration;

        this.configuration = configuration;
        this.replicationConfiguration = (ReplicationConfigurationType) configuration.replication;
        this.logger = Loggers.getReplicationLogger();
        this.executor = (ThreadPoolExecutor) Executors.newCachedThreadPool(
            (new ThreadFactoryBuilder())
                .setNameFormat("Replication Service %d")
                .build()
        );

        this.executor.prestartCoreThread();
        this.executor.prestartAllCoreThreads();
    }

    public abstract CompletableFuture<Void> start();

    public abstract CompletableFuture<Integer> countNodes();

    public abstract CompletableFuture<List<Node>> fetchNodes();

    public void lock() throws InterruptedException {
        this.lock(".global");
    }

    public abstract void lock(String name) throws InterruptedException;

    public abstract void unlock(String name) throws InterruptedException;

    public void unlock() throws InterruptedException {
        this.unlock(".global");
    }

    public abstract CompletableFuture<ReplicationInformation> getInformation();

    @Override
    public void close() throws IOException {
        this.logger.info(String.format("Shutting down %d replication threads", this.executor.getActiveCount()));

        this.executor.shutdown();

        try {
            this.executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            this.logger.warning(String.format(
                "Killing %d replication threads that did not shut down in time",
                this.executor.getActiveCount()
            ));
        }

        this.logger.info("Replication threads halted");

