        this.curso = curso;
        return this;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        Matricula matricula = (Matricula) o;
        if (matricula.getId() == null || getId() == null) {
            return false;
        }
        return Objects.equals(getId(), matricula.getId());
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(getId());
    }

