import com.thoughtworks.xstream.XStream;
import java.io.Externalizable;
import java.io.IOException;
import java.io.ObjectInput;
import java.io.ObjectOutput;
import java.util.ArrayList;
import java.util.List;

public class WorkingMemoryInMemoryLogger implements Externalizable {

    private List<LogEvent> events;
    private transient XStream xstream;

    public WorkingMemoryInMemoryLogger() {
        this.events = new ArrayList<>();
        this.xstream = new XStream();
    }

    public void logEventCreated(LogEvent logEvent) {
        if (logEvent != null) {
            events.add(logEvent);
        }
    }

    public List<LogEvent> getLogEvents() {
        return new ArrayList<>(events);
    }

    public String getEvents() {
        return xstream.toXML(events);
    }

    public void clear() {
        events.clear();
    }

    @Override
    public void writeExternal(ObjectOutput out) throws IOException {
        out.writeObject(getEvents());
    }

    @Override
    public void readExternal(ObjectInput in) throws IOException, ClassNotFoundException {
        String serializedEvents = (String) in.readObject();
        events = (List<LogEvent>) xstream.fromXML(serializedEvents);
    }

    public static class LogEvent {
        private String eventType;
        private String description;
        private long timestamp;

        public LogEvent(String eventType, String description) {
            this.eventType = eventType;
            this.description = description;
            this.timestamp = System.currentTimeMillis();
        }

        public String getEventType() {
            return eventType;
        }

        public String getDescription() {
            return description;
        }

        public long getTimestamp() {
            return timestamp;
        }

        @Override
        public String toString() {
            return "LogEvent{" +
                    "eventType='" + eventType + '\'' +
                    ", description='" + description + '\'' +
                    ", timestamp=" + timestamp +
                    '}';
        }
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public class Puzzle {

    public static void main(String[] args) {
        Puzzle puzzle = new Puzzle();
        puzzle.sumTo(100);
        puzzle.maxSolve();
        puzzle.minSolve();
        puzzle.highestSums();
    }

    private void sumTo(int val) {
        List<String> exprs = genExpr();
        exprs.stream()
               .filter(e -> eval(e) == val)
               .forEach(System.out::println);
    }

    private void maxSolve() {
        Map<Integer, Integer> values = allExprs();
        int max = values.entrySet().stream()
               .max((e1, e2) -> e1.getValue() - e2.getValue())
               .get()
               .getKey();
        System.out.println("Sum " + max + " has the maximum number of solutions: " + values.get(max));
    }

    private void minSolve() {
        Map<Integer, Integer> values = allExprs();
        for (int i = 1; i < 123456789; i++) {
            if (!values.containsKey(i)) {
                System.out.println("Lowest positive sum that can't be expressed: " + i);
                return;
            }
        }
    }

    private void highestSums() {
        Map<Integer, Integer> values = allExprs();
        List<Integer> sums = values.entrySet().stream()
               .sorted((e1, e2) -> e2.getKey() - e1.getKey())
               .limit(10)
               .map(Map.Entry::getKey)
               .collect(Collectors.toList());
        System.out.println("Highest Sums: " + sums);
    }

    private List<String> genExpr() {
        List<String> exprs = new ArrayList<>();
        for (String op1 : new String[]{"+", "-", ""}) {
            for (String op2 : new String[]{"+", "-", ""}) {
                for (String op3 : new String[]{"+", "-", ""}) {
                    for (String op4 : new String[]{"+", "-", ""}) {
                        for (String op5 : new String[]{"+", "-", ""}) {
                            for (String op6 : new String[]{"+", "-", ""}) {
                                for (String op7 : new String[]{"+", "-", ""}) {
                                    for (String op8 : new String[]{"+", "-", ""}) {
                                        for (String op9 : new String[]{"+", "-", ""}) {
                                            exprs.add("1" + op1 + "2" + op2 + "3" + op3 + "4" + op4 + "5" + op5 + "6" + op6 + "7" + op7 + "8" + op8 + "9");
                                        }

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.Locale;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
 
public class WriteToWindowsEventLog {
    public static void main(String[] args) throws IOException, InterruptedException {
        String osName = System.getProperty("os.name").toUpperCase(Locale.ENGLISH);
        if (!osName.startsWith("WINDOWS")) {
            System.err.println("Not windows");
            return;
        }
 
        Process process = Runtime.getRuntime().exec("EventCreate /t INFORMATION /id 123 /l APPLICATION /so Java /d \"Rosetta Code Example\"");
        process.waitFor(10, TimeUnit.SECONDS);
        int exitValue = process.exitValue();
        System.out.printf("Process exited with value %d\n", exitValue);
        if (exitValue != 0) {
            InputStream errorStream = process.getErrorStream();
            String result = new BufferedReader(new InputStreamReader(errorStream))
                .lines()
                .collect(Collectors.joining("\n"));
            System.err.println(result);
        }
    }
}

import com.google.gwt.json.client.JSONArray;
import com.google.gwt.json.client.JSONNumber;
import com.google.gwt.json.client.JSONObject;
import com.google.gwt.json.client.JSONParser;
import com.google.gwt.json.client.JSONString;
import com.google.gwt.json.client.JSONValue;

public class JSONUtil {

    private JSONUtil() {
        // Utility class.
    }

    public static JSONValue parse(final String json) {
        if (json != null && !json.isEmpty()) {
            return JSONParser.parseStrict(json);
        }

        return null;
    }

    public static JSONObject getObject(final JSONValue v) {
        if (v != null) {
            return v.isObject();
        }
        return null;
    }

    public static JSONArray getArray(final JSONValue v) {
        if (v != null) {
            return v.isArray();
        }
        return null;
    }

    public static String getString(final JSONValue v) {
        if (v != null) {
            final JSONString jsonString = v.isString();
            if (jsonString != null) {
                return jsonString.stringValue();
            }
        }
        return null;
    }

    public static Integer getInteger(final JSONValue v) {
        if (v != null) {
            final JSONNumber jsonNumber = v.isNumber();
            if (jsonNumber != null) {
                return Integer.valueOf((int) jsonNumber.doubleValue());
            }
        }
        return null;
    }

    public static Double getDouble(final JSONValue v) {
        if (v != null) {
            final JSONNumber jsonNumber = v.isNumber();
            if (jsonNumber != null) {
                return Double.valueOf(jsonNumber.doubleValue());
            }
        }
        return null;
    }

    public static String[] getStrings(final JSONValue v) {
        String[] strings = new String[0];
        final JSONArray array = getArray(v);
        if (array != null) {
            strings = new String[array.size()];
            for (int i = 0; i < array.size(); i++) {
                strings[i] = getString(array.get(i));
            }
        }

        return strings;
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.apache.log4j.Logger;

import com.cloud.utils.exception.CloudRuntimeException;

public class DriverLoader {

    private static final Logger LOGGER = Logger.getLogger(DriverLoader.class.getName());
    private static final List<String> LOADED_DRIVERS;
    private static final Map<String, String> DRIVERS;

    static {
        DRIVERS = new HashMap<String, String>();
        DRIVERS.put("jdbc:mysql", "com.mysql.cj.jdbc.Driver");
        DRIVERS.put("jdbc:postgresql", "org.postgresql.Driver");
        DRIVERS.put("jdbc:h2", "org.h2.Driver");

        LOADED_DRIVERS = new ArrayList<String>();
    }

    public static void loadDriver(String dbDriver) {
        String driverClass = DRIVERS.get(dbDriver);
        if (driverClass == null) {
            LOGGER.error("DB driver type " + dbDriver + " is not supported!");
            throw new CloudRuntimeException("DB driver type " + dbDriver + " is not supported!");
        }

        if (LOADED_DRIVERS.contains(dbDriver)) {
            if (LOGGER.isDebugEnabled()) {
                LOGGER.debug("DB driver " + driverClass + " was already loaded.");
            }
            return;
        }

        try {
            Class.forName(driverClass).newInstance();
            LOADED_DRIVERS.add(dbDriver);
            if (LOGGER.isDebugEnabled()) {
                LOGGER.debug("Successfully loaded DB driver " + driverClass);
            }
        } catch (ClassNotFoundException | InstantiationException | IllegalAccessException e) {
            LOGGER.error("Failed to load DB driver " + driverClass);
            throw new CloudRuntimeException("Failed to load DB driver " + driverClass, e);
        }
    }

}

