import java.util.Arrays;
import java.util.ArrayList;
import java.util.List;

public abstract class DOMonitor {
    protected final String protocolID;
    protected final String[] metricsName;
    protected double[] metricsMeasures;

    public DOMonitor(String protocolID, String metricNames) {
        if (protocolID == null || protocolID.isEmpty()) {
            throw new IllegalArgumentException("Protocol ID cannot be null/empty");
        }
        if (metricNames == null || metricNames.trim().isEmpty()) {
            throw new IllegalArgumentException("Metric names cannot be null/empty");
        }

        this.protocolID = protocolID;
        this.metricsName = Arrays.stream(metricNames.split(","))
                .map(String::trim)
                .filter(name -> !name.isEmpty())
                .toArray(String[]::new);

        if (this.metricsName.length == 0) {
            throw new IllegalArgumentException("At least one metric required");
        }
        this.metricsMeasures = new double[this.metricsName.length];
    }

    public abstract void measure();

    public boolean[] verifyObjectives() {
        boolean[] statuses = new boolean[metricsName.length];
        for (int i = 0; i < metricsName.length; i++) {
            DOObjective obj = DesignObjectives.getObjective(protocolID, metricsName[i]);
            statuses[i] = (obj != null) && obj.isSatisfiedBy(metricsMeasures[i]);
        }
        return statuses;
    }

    public String measurementsToString() {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < metricsName.length; i++) {
            if (i > 0) sb.append("; ");
            sb.append(metricsName[i]).append(":").append(String.format("%.2f", metricsMeasures[i]));
        }
        return sb.toString();
    }

    public String metricsToString() {
        boolean[] statuses = verifyObjectives();
        StringBuilder sb = new StringBuilder();
        sb.append(String.format("%-20s %-10s %-15s %-10s%n", "Metric", "Value", "Objective", "Status"));
        sb.append("-------------------------------------------------%n");

        for (int i = 0; i < metricsName.length; i++) {
            DOObjective obj = DesignObjectives.getObjective(protocolID, metricsName[i]);
            String objStr = (obj != null) ? obj.toString() : "N/A";
            String status = (obj != null) ? (statuses[i] ? "PASS" : "FAIL") : "N/A";
            sb.append(String.format("%-20s %-10.2f %-15s %-10s%n",
                metricsName[i], metricsMeasures[i], objStr, status));
        }
        return sb.toString();
    }

