import java.util.*;
 
public class FWord {
    private /*v*/ String fWord0 = "";
    private /*v*/ String fWord1 = "";
 
    private String nextFWord () {
        final String result;
 
        if ( "".equals ( fWord1 ) )      result = "1";
        else if ( "".equals ( fWord0 ) ) result = "0";
        else                             result = fWord1 + fWord0;
 
        fWord0 = fWord1;
        fWord1 = result;
 
        return result;
    }
 
    public static double entropy ( final String source ) {
        final int                        length = source.length ();
        final Map < Character, Integer > counts = new HashMap < Character, Integer > ();
        /*v*/ double                     result = 0.0;
 
        for ( int i = 0; i < length; i++ ) {
            final char c = source.charAt ( i );
 
            if ( counts.containsKey ( c ) ) counts.put ( c, counts.get ( c ) + 1 );
            else                            counts.put ( c, 1 );
        }
 
        for ( final int count : counts.values () ) {
            final double proportion = ( double ) count / length;
 
            result -= proportion * ( Math.log ( proportion ) / Math.log ( 2 ) );
        }
 
        return result;
    }
 
    public static void main ( final String [] args ) {
        final FWord fWord = new FWord ();
 
        for ( int i = 0; i < 37;  ) {
            final String word = fWord.nextFWord ();
 
            System.out.printf ( "%3d %10d %s %n", ++i, word.length (), entropy ( word ) );
        }
    }
}

import java.io.*;
import java.util.jar.*;
import java.util.jar.Attributes.Name;

public class JarWriter {

    public static void packToJar(File rootDir, OutputStream out) throws IOException {
        Manifest manifest = new Manifest();
        manifest.getMainAttributes().put(Name.MANIFEST_VERSION, "1.0");
        JarOutputStream target = new JarOutputStream(out, manifest);
        add(rootDir, rootDir, target);
        target.close();
    }

    private static void add(File root, File source, JarOutputStream target) throws IOException {
        BufferedInputStream in = null;
        try {
            String relativePath = root.toURI().relativize(source.toURI()).getPath();
            relativePath = relativePath.replace("\\", "/");

            if (source.isDirectory()) {
                if (!relativePath.isEmpty() && !relativePath.endsWith("/")) {
                    relativePath += "/";
                }
                JarEntry entry = new JarEntry(relativePath);
                entry.setTime(source.lastModified());
                target.putNextEntry(entry);
                target.closeEntry();
                for (File nestedFile : source.listFiles()) {
                    add(root, nestedFile, target);
                }
                return;
            }

            JarEntry entry = new JarEntry(relativePath);
            entry.setTime(source.lastModified());
            target.putNextEntry(entry);
            in = new BufferedInputStream(new FileInputStream(source));

            byte[] buffer = new byte[1024];
            while (true) {
                int count = in.read(buffer);
                if (count == -1) {
                    break;
                }
                target.write(buffer, 0, count);
            }
            target.closeEntry();
        } finally {
            if (in != null) {
                in.close();
            }
        }
    }
}

