            mainHolder.Bidder.setText(notification.getBidder());
            mainHolder.BidAmt.setText(notification.getBidAmt());
            mainHolder.Date.setText(notification.getDate());
        }

import java.util.AbstractMap;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class HashMultimap<K, V> {
    private final Map<K, List<V>> map;
    private int total;

    public HashMultimap() {
        this.map = new HashMap<>();
        this.total = 0;
    }

    public int size() {
        return total;
    }

    public boolean isEmpty() {
        return total == 0;
    }

    public List<V> get(K key) {
        return map.getOrDefault(key, new ArrayList<>());
    }

    public void put(K key, V value) {
        map.computeIfAbsent(key, k -> new ArrayList<>()).add(value);
        total++;
    }

    public boolean remove(K key, V value) {
        List<V> values = map.get(key);
        if (values != null && values.remove(value)) {
            total--;
            if (values.isEmpty()) {
                map.remove(key);
            }
            return true;
        }
        return false;
    }

    public List<V> removeAll(K key) {
        List<V> values = map.remove(key);
        if (values != null) {
            total -= values.size();
        }
        return values != null ? values : new ArrayList<>();
    }

    public List<Map.Entry<K, V>> entries() {
        List<Map.Entry<K, V>> entries = new ArrayList<>();
        for (Map.Entry<K, List<V>> entry : map.entrySet()) {
            K key = entry.getKey();
            for (V value : entry.getValue()) {
                entries.add(new AbstractMap.SimpleEntry<>(key, value));
            }
        }
        return entries;
    }

    @Override
    public String toString() {
        return map.toString();
    }
}

public class StackTracer {
    public static void printStackTrace() {
    StackTraceElement[] elems = Thread.currentThread().getStackTrace();
 
    System.out.println("Stack trace:");
    for (int i = elems.length-1, j = 2 ; i >= 3 ; i--, j+=2) {
        System.out.printf("%" + j + "s%s.%s%n", "",
            elems[i].getClassName(), elems[i].getMethodName());
    }
    }
}

