def min_operations(nums):
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    max_count = max(count.values())
    if max_count % 3 == 0:
        return max_count // 3
    elif max_count % 3 == 1:
        return -1
    else:
        return (max_count // 3) + (max_count % 3)

import java.io.File;
import java.io.IOException;
import java.util.Scanner;

public class Runner {
    public static void main(String[] args) throws IOException {

        File sourceFile = new File(args[0]);
        if (!sourceFile.exists()) {
            System.out.println("Please check your file name and try again");
            System.exit(1);
        }

        int numChars = 0, numWords = 0, numLines = 0;
        String temp = "";

        try (Scanner input = new Scanner(sourceFile);) {

            while (input.hasNext()) {

                temp = input.nextLine();
                numLines++;

                String[] tempArr = temp.split(" ");

                numWords += tempArr.length;

                for (int i = tempArr.length - 1; i >= 0; i--) {
                    numChars += tempArr[i].length();
                }
            }

        }

        System.out.println("The file " + sourceFile.getName() + " has:");
        System.out.println(numChars + " Characters");
        System.out.println(numWords + " words");
        System.out.println(numLines + " lines");

    }
}

