import java.util.ArrayList;
import java.util.Arrays;
import java.util.Random;

public class Logger {
    public static void main(String[] args) {
        ArrayList<Integer> test = new ArrayList<>();

        for (int i = 0; i < 15; i++) {
            test.add((int) (1 + Math.random() * 99));
        }
        System.out.println("Initial List = " + test.toString());
        ArrayList<Integer> initialList = new ArrayList<>();
        initialList.addAll(test);

        shuffle(test);

        System.out.println("Shuffled List = " + test.toString());

        System.out.println("TEST: Values in shuffled list = values in initial list = " + runTest(test, initialList));
    }

    private static String runTest(ArrayList<Integer> test, ArrayList<Integer> initialList) {
        for (Integer integer : test) {
            if (!initialList.contains(integer)) {
                return "False";
            }
        }
        return "True";
    }

    public static void shuffle(ArrayList<Integer> list) {
        int upperBound = list.size() - 1;
        Random random = new Random();
        int shuffles = 0;
        Integer i = list.remove(random.nextInt(upperBound));
        while (shuffles++ < 100) {
            i = list.set(random.nextInt(upperBound), i);
        }
        list.add(upperBound, i);
    }
}

import com.intellij.openapi.project.Project;
import com.intellij.openapi.vcs.CheckinHandler;
import com.intellij.openapi.vcs.CheckinHandlerFactory;
import com.intellij.openapi.vcs.VcsException;
import com.intellij.openapi.vcs.changes.Change;
import com.intellij.openapi.vcs.changes.ChangesUtil;
import com.intellij.openapi.vfs.VirtualFile;
import com.intellij.cvsSupport2.CvsVcs2;
import com.intellij.cvsSupport2.config.CvsConfiguration;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import javax.swing.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

public class CvsCheckinHandlerFactory extends CheckinHandlerFactory {

    @Override
    public @NotNull CheckinHandler createHandler(@NotNull Project project) {
        return new CheckinHandler() {
            @Override
            public @Nullable JComponent getAfterCheckinConfigurationPanel() {
                return createCvsOptionsPanel(project);
            }
        };
    }

    private JComponent createCvsOptionsPanel(@NotNull Project project) {
        CvsVcs2 cvs = CvsVcs2.getInstance(project);
        CvsConfiguration cvsConfig = cvs.getConfiguration();
        Collection<VirtualFile> roots = cvs.getVcsManager().getRootsUnderVcs(cvs);

        List<VirtualFile> cvsFiles = new ArrayList<>();
        for (VirtualFile root : roots) {
            try {
                cvsFiles.addAll(ChangesUtil.getFilesUnderVcs(project, root, cvs));
            } catch (VcsException e) {
                e.printStackTrace();
            }
        }

        if (cvsFiles.isEmpty()) {
            return null;
        }

        AdditionalOptionsPanel panel = new AdditionalOptionsPanel(project, cvsConfig, cvsFiles);
        return panel.getComponent();
    }

    private static class AdditionalOptionsPanel {
        private final JPanel panel;
        private final Project project;
        private final CvsConfiguration cvsConfig;
        private final List<VirtualFile> files;

        public AdditionalOptionsPanel(Project project, CvsConfiguration cvsConfig, List<VirtualFile> files) {
            this.project = project;
            this.cvsConfig = cvsConfig;
            this.files = files;
            this.panel = new JPanel();
            initializePanel();
        }

        private void initializePanel() {
            // Add UI components for CVS-specific options
            // Example: Checkboxes, text fields, etc.
        }

        public JComponent getComponent() {
            return panel;
        }
    }
}

import org.apache.commons.lang3.StringUtils;

public class SummaryParser {

    private static final int SUMMARY_LENGTH = 256;
    private static final int IN = 1; // Inside HTML tag
    private static final int OUT = 0; // Outside HTML tag

    public String getSummary(String sourceStr) {
        if (StringUtils.isBlank(sourceStr)) {
            return "";
        }

        String cleanedText = removeHTML(sourceStr);
        cleanedText = normalizeWhitespace(cleanedText);
        return truncateText(cleanedText, SUMMARY_LENGTH);
    }

    private String removeHTML(String source) {
        StringBuilder result = new StringBuilder();
        int state = OUT;
        int i = 0;

        while (i < source.length()) {
            char currentChar = source.charAt(i);

            if (currentChar == '<') {
                state = IN;
                i++;
            } else if (currentChar == '>') {
                state = OUT;
                i++;
            } else if (state == IN) {
                i++;
            } else {
                if (checkInHTMLCode(source, i)) {
                    i += skipHTMLCode(source, i);
                } else {
                    result.append(currentChar);
                    i++;
                }
            }
        }

        return result.toString();
    }

    private boolean checkInHTMLCode(String source, int start) {
        return source.startsWith("&", start);
    }

    private int skipHTMLCode(String source, int start) {
        int end = source.indexOf(';', start);
        if (end == -1) {
            return 0;
        }
        return end - start + 1;
    }

    private String normalizeWhitespace(String source) {
        return source.replaceAll("\\s+", " ").trim();
    }

    private String truncateText(String source, int maxLength) {
        if (source.length() <= maxLength) {
            return source;
        }
        return source.substring(0, maxLength) + "...";
    }

    public static void main(String[] args) {
        SummaryParser parser = new SummaryParser();
        String htmlContent = "<p>This is a <b>sample</b> text with &nbsp; HTML tags and entities.</p>";
        String summary = parser.getSummary(htmlContent);
        System.out.println("Summary: " + summary);
    }
}

