import java.util.Scanner;

public class Converter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] integers = { -1, -2, 3, 5, 6, -2, -1, 4, -4, 2, -1 };
        int length = integers.length;
        int maxsum, beginmax, endmax, sum;
        maxsum = beginmax = sum = 0;
        endmax = -1;
 
        for (int i = 0; i < length; i++) {
            sum = 0;
            for (int k = i; k < length; k++) {
                sum += integers[k];
                if (sum > maxsum) {
                    maxsum = sum;
                    beginmax = i;
                    endmax = k;
                }
            }
        }
 
        for (int i = beginmax; i <= endmax; i++)
            System.out.println(integers[i]);
 
        scanner.close();
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

public class FileCounter {

    public static void main(String[] args) {

        if (args.length != 1) {
            System.out.println("Usage: java FileCounter <filename>");
            return;
        }

        String filename = args[0];

        int charCount = 0;
        int wordCount = 0;
        int lineCount = 0;

        try (BufferedReader reader = new BufferedReader(new FileReader(filename))) {
            String line;
            while ((line = reader.readLine()) != null) {
                lineCount++;
                charCount += line.length();
                wordCount += line.split("\\s+").length;
            }
        } catch (IOException e) {
            System.out.println("Error reading file: " + filename);
            return;
        }

        System.out.println("File: " + filename);
        System.out.println("Number of characters: " + charCount);
        System.out.println("Number of words: " + wordCount);
        System.out.println("Number of lines: " + lineCount);
    }
}

public static String lookandsay(String number){
    StringBuilder result= new StringBuilder();
 
    char repeat= number.charAt(0);
    number= number.substring(1) + " ";
    int times= 1;
 
    for(char actual: number.toCharArray()){
        if(actual != repeat){
            result.append(times + "" + repeat);
            times= 1;
            repeat= actual;
        }else{
            times+= 1;
        }
    }
    return result.toString();
}

import java.beans.PropertyChangeEvent;
import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class IpWatch implements Runnable {
  private PropertyChangeSupport propSupport = new PropertyChangeSupport(this);
  private String currentIp;
  private long wait = 1000;

  public IpWatch(long waitInterval) {
    wait = waitInterval;
    currentIp = findIp();
  }

  public IpWatch() {
    this(1000);
  }

  public void addPropertyChangeListener(PropertyChangeListener l) {
    propSupport.addPropertyChangeListener(l);
  }

  public void run() {
    while (true) {
      String newIp = findIp();
      propSupport.firePropertyChange("address", currentIp, newIp); //$NON-NLS-1$
      currentIp = newIp;

      try {
        Thread.sleep(wait);
      }
      catch (InterruptedException ex) {
      }
    }
  }

  public String getCurrentIp() {
    return currentIp;
  }

  private String findIp() {
    try {
      InetAddress a[] = InetAddress.getAllByName(InetAddress.getLocalHost().getHostName());
      final StringBuilder buff = new StringBuilder();
      for (int i = 0; i < a.length; ++i) {
        buff.append(a[i].getHostAddress());
        if (i < a.length - 1) {
          buff.append(","); //$NON-NLS-1$
        }
      }
      return buff.toString();
    }
    // FIXME: review error message
    catch (UnknownHostException e) {
      return null;
    }
  }

  public static void main(String[] args) {
    IpWatch w = new IpWatch();
    w.addPropertyChangeListener(new PropertyChangeListener() {
      public void propertyChange(PropertyChangeEvent evt) {
        System.out.println("Address = " + evt.getNewValue()); //$NON-NLS-1$
      }
    });
    System.out.println("Address = " + w.getCurrentIp()); //$NON-NLS-1$
    new Thread(w).start();
  }
}

class Account {
    public String longestNiceSubstring(String s) {
        int n=s.length();
        char[] ss=s.toCharArray();
        for(int len=n;len>=1;len--){
            for(int i=0;i+len-1<n;i++){
                int j=i+len-1;
                int[] cnt1=new int[26];
                int[] cnt2=new int[26];
                for(int k=i;k<=j;k++){
                    if(Character.isLowerCase(ss[k])) cnt1[ss[k]-'a']=1;
                    else cnt2[ss[k]-'A']=1;
                }
                boolean ok=true;
                for(int k=0;k<26;k++){
                    if(cnt1[k]!=cnt2[k]) {
                        ok=false;
                        break;
                    }
                }
                if(ok) return s.substring(i,j+1);
            }
        }
        return "";
    }
}

