import java.lang.Long;
import java.lang.System;
 
public final class MainKt {
    public static final void main(String[] args) {
        System.out.println("\nTimings (nanoseconds) : ");
        for (long time : benchmark(10, MainKt::cube, 5)) {
            System.out.println(time);
        }
    }
 
    public static final long[] benchmark(int n, Func func, int arg) {
        long[] times = new long[n];
        for (int i = 0; i < n; i++) {
            long m = System.nanoTime();
            func.invoke(arg);
            times[i] = System.nanoTime() - m;
        }
        return times;
    }
 
    public static final int cube(int n) {
        return n * n * n;
    }
}

