                i, j, x, y = min(i, r[0]), min(j, r[1]), max(x, r[2]), max(y, r[3])
            if i > x or j > y:
                continue
            for r in rectangles:
                if r[0] < i or r[1] < j or r[2] > x or r[3] > y:
                    changes = True
                    break
            if changes:
                break
            if len(rectangles) == 1:
                continue
            colors[color] = [rectangles[0]]
            for rect in rectangles[1:]:
                if rect in colors[color]:
                    colors[color].remove(rect)
                    changes = True
            if not changes:
                return False
        if not changes:
            break
    return True

