public class ColumnAlignerProgram {
    public static void main(String[] args) {
        String[] input = { "Given$a$text$file$of$many$lines,$where$fields$within$a$line$",
                "are$delineated$by$a$single$'dollar'$character,$write$a$program",
                "that$aligns$each$column$of$fields$by$ensuring$that$words$in$each$",
                "column$are$separated$by$at$least$one$space.",
                "Further,$allow$for$each$word$in$a$column$to$be$either$left$",
                "justified,$right$justified,$or$center$justified$within$its$column." };

        for (String line : AlignColumns(input, ColumnAlignerProgram::JustifyCenter)) {
            System.out.println(line);
        }
    }

    public static String[] AlignColumns(String[] lines, Justification justification) {
        final char Separator = '$';
        // build input table and calculate columns count
        String[][] table = new String[lines.length][];
        int columns = 0;
        for (int i = 0; i < lines.length; i++) {
            String[] row = lines[i].trim().split(String.valueOf(Separator));
            if (columns < row.length)
                columns = row.length;
            table[i] = row;
        }
        // create formatted table
        String[][] formattedTable = new String[table.length][];
        for (int i = 0; i < formattedTable.length; i++) {
            formattedTable[i] = new String[columns];
        }
        for (int j = 0; j < columns; j++) {
            // get max column width
            int columnWidth = 0;
            for (int i = 0; i < table.length; i++) {
                if (j < table[i].length && columnWidth < table[i][j].length)
                    columnWidth = table[i][j].length;
            }
            // justify column cells
            for (int i = 0; i < formattedTable.length; i++) {
                if (j < table[i].length)
                    formattedTable[i][j] = justification.justify(table[i][j], columnWidth);
                else
                    formattedTable[i][j] = new String(new char[columnWidth]).replace("\0", " ");
            }
        }
        // create result
        String[] result = new String[formattedTable.length];
        for (int i = 0; i < result.length; i++) {
            result[i] = String.join(" ", formattedTable[i]);
        }
        return result;
    }

