        // Temel char ve boolean degiskenler
        char harf = 'A';
        boolean durum = true;

        System.out.println("Karakter: " + harf);
        System.out.println("Boolean Degeri: " + durum);

        // char -> int donusumu ASCII kodunu verir
        int asciiKodu = harf;
        System.out.println("Karakterin ASCII Degeri: " + asciiKodu);

        // Boolean degere gore dallanma
        String yorum = durum ? "Bu ifade dogru." : "Bu ifade yanlis.";
        System.out.println(yorum);

        // int -> char donusumu (explicit cast)
        int kodDegeri = 66;
        char harfeDonusen = (char) kodDegeri;
        System.out.println("ASCII Degerinden Karakter: " + harfeDonusen);

        // iki karakterin ASCII degerlerinin toplanmasi
        char birinciHarf = 'B';
        char ikinciHarf = 'C';
        int harfToplami = birinciHarf + ikinciHarf;
        System.out.println("Char1 ve Char2'nin toplami (ASCII Degerleri): " + harfToplami);

        // Mantiksal degil (NOT) islemi
        boolean tersDurum = !durum;
        System.out.println("Ters deger: " + tersDurum);

        // iki kosulun VE ile birlikte degerlendirilmesi
