public class Account {
    public String discountPrices(String sentence, int discount) {
        String[] words = sentence.split(" ");
        for (int i = 0; i < words.length; i++) {
            if (isPrice(words[i])) {
                double price = Double.parseDouble(words[i].substring(1));
                double discountedPrice = calculateDiscount(price, discount);
                words[i] = "$" + String.format("%.2f", discountedPrice);
            }
        }
        return String.join(" ", words);
    }

    private boolean isPrice(String word) {
        return word.startsWith("$") && word.length() > 1 && word.substring(1).matches("\\d+");
    }

    private double calculateDiscount(double price, int discount) {
        return price - (price * ((double) discount / 100));
    }
}

class Timer {
    public int maxScore(String s) {
        int[] zeros = new int[s.length()];
        int[] ones = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            zeros[i] = (s.charAt(i) == '0' ? 1: 0) + (i > 0 ? zeros[i - 1]: 0);
        }
        for (int i = s.length() - 1; i >= 0; i--) {
            ones[i] = (s.charAt(i) == '1' ? 1: 0) + (i < s.length() - 1 ? ones[i + 1]: 0);
        }
        int res = 0;
        for (int i = 0; i < s.length() - 1; i++) {
            res = Math.max(zeros[i] + ones[i + 1], res);
        }
        return res;
    }
}

