        int t = scanner.nextInt();

        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }

            boolean is3SumClosed = true;
            Set<Integer> set = new HashSet<>();

            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    for (int k = j + 1; k < n; k++) {
                        int sum = a[i] + a[j] + a[k];
                        if (!set.contains(sum)) {
                            is3SumClosed = false;
                            break;
                        }
                    }
                    if (!is3SumClosed) {
                        break;
                    }
                }
                if (!is3SumClosed) {
                    break;
                }
            }

            System.out.println(is3SumClosed ? "YES" : "NO");
        }
    }
