class Bank {

        private long[] accounts;
        public Bank(long[] balance) {
            accounts = balance;
        }

        public boolean transfer(int account1, int account2, long money) {
            account1--;
            account2--;
            if (account1 < 0 || account1 >= accounts.length) return false;
            if (account2 < 0 || account2 >= accounts.length) return false;
            if (money < 0) return false;
            if (accounts[account1] < money) return false;
            accounts[account1] -= money;
            accounts[account2] += money;
            return true;
        }

        public boolean deposit(int account, long money) {
            if (money < 0) return false;
            account--;
            if (account < 0 || account >= accounts.length) return false;
            accounts[account] += money;
            return true;
        }

        public boolean withdraw(int account, long money) {
            if (money < 0) return false;
            account--;
            if (account < 0 || account >= accounts.length) return false;
            if (accounts[account] < money) return false;
            accounts[account] -= money;
            return true;
        }
}

