public int maxChunksToSorted(int[] arr) {
        int[] sorted = Arrays.copyOfRange(arr, 0, arr.length);
        Arrays.sort(sorted);
        int chunks = 0;
        int prefixSumA = 0;
        int prefixSumB = 0;
        for(int i=0; i<sorted.length; i++){
            prefixSumA += arr[i];
            prefixSumB += sorted[i];
            if(prefixSumA == prefixSumB){
                chunks++;
            }
        }
        return chunks;
    }
}

