class Account {
    private final int MOD = (int)Math.pow(10,9) +7;

    public int squareFreeSubsets(int[] nums) {
        int[] count = new int[31];
        int n = nums.length;
        for (int num : nums) {
            if (num % 4 != 0) {
                count[num]++;
            }
        }

        int result = 1;
        for (int k = 2; k <= 30; k += 2) {
            if (count[k] != 0) {
                for (int i = 0; i <= 30; i += k) {
                    result = (result * count[i]) % MOD;
                }
            }
        }

        return (result - 1 + MOD) % MOD;
    }
}

import java.util.Scanner;

public class LoanAmortizationSchedule {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Get loan details from user
        System.out.print("Loan Amount: ");
        double loanAmount = input.nextDouble();

        System.out.print("Number of Years: ");
        int numberOfYears = input.nextInt();

        System.out.print("Annual Interest Rate: ");
        double annualInterestRate = input.nextDouble();

        // Calculate monthly interest rate
        double monthlyInterestRate = annualInterestRate / 1200;

        // Calculate monthly payment and total payment
        double monthlyPayment = loanAmount * monthlyInterestRate /
                (1 - 1 / Math.pow(1 + monthlyInterestRate, numberOfYears * 12));
        double totalPayment = monthlyPayment * numberOfYears * 12;

        // Display monthly payment and total payment
        System.out.printf("Monthly Payment: %.2f\n", monthlyPayment);
        System.out.printf("Total Payment: %.2f\n", totalPayment);

        // Display amortization schedule
        System.out.println("Payment#\tInterest\tPrincipal\tBalance");
        double balance = loanAmount;
        for (int i = 1; i <= numberOfYears * 12; i++) {
            double interest = monthlyInterestRate * balance;
            double principal = monthlyPayment - interest;
            balance -= principal;

            System.out.printf("%-10d\t%-10.2f\t%-10.2f\t%.2f\n", i, interest, principal, balance);

            // Check if balance is zero or negative
            if (balance <= 0) {
                // If balance is negative, add it to the last payment
                if (balance < 0) {
                    monthlyPayment += balance;
                    totalPayment = monthlyPayment * i;
                }
                break;
            }
        }

        // Display last payment if balance is not zero
        if (balance > 0) {
            System.out.printf("%-10d\t%-10.2f\t%-10.2f\t0.00\n", numberOfYears * 12, monthlyInterestRate * balance, balance);
        }
    }
}

import android.content.Context;
import android.database.Cursor;
import android.support.v4.content.CursorLoader;
import za.co.cporm.model.query.Select;
import za.co.cporm.util.CPOrmCursor;
import za.co.cporm.model.generate.TableDetails;

public class CPOrmLoader<T> extends CursorLoader {

    private final Select<T> select;
    private CPOrmCursor<T> cursor;
    private boolean cacheEnabled;
    private int cacheSize = 100;

    public CPOrmLoader(Context context, Select<T> select) {
        super(context);
        this.select = select;
        TableDetails tableDetails = new TableDetails(select.getTable());
        ContentResolverValues contentResolverValues = select.asContentResolverValue();

        setUri(tableDetails.getContentUri());
        setProjection(contentResolverValues.getProjection());
        setSelection(contentResolverValues.getWhere());
        setSelectionArgs(contentResolverValues.getWhereArgs());
        setSortOrder(contentResolverValues.getSortOrder());
    }

    public void enableCursorCache(int cacheSize) {
        this.cacheEnabled = true;
        this.cacheSize = cacheSize;
    }

    @Override
    public Cursor loadInBackground() {

        Cursor baseCursor = super.loadInBackground();
        cursor = new CPOrmCursor<>(baseCursor, select.getTable());

        if(cacheEnabled){
            cursor.enableCache(cacheSize);
            try {
                if (cursor.getCount() > 0) {

                    int count = 0;
                    while (cursor.moveToPosition(count) && count < 100)
                    {
                        cursor.inflate();
                        count++;
                    }
                }
            } catch (Exception ex) {
                throw new RuntimeException("Failed to prefetch objects: " + ex.getMessage(), ex);
            }
        }

        return cursor;
    }

    @Override
    protected void onReset() {
        super.onReset();

        if(cursor != null) {
            cursor.close();
            cursor = null;
        }
    }
}

public //any class may access this member directly
 
protected //only this class, subclasses of this class,
//and classes in the same package may access this member directly
 
private //only this class may access this member directly
 
static //for use with other modifiers
//limits this member to one reference for the entire JVM
 
//adding no modifier (sometimes called "friendly") allows access to the member by classes in the same package
 
// Modifier    | Class | Package | Subclass | World
// ------------|-------|---------|----------|-------
// public      |  Y    |    Y    |    Y     |   Y
// protected   |  Y    |    Y    |    Y     |   N
// no modifier |  Y    |    Y    |    N     |   N
// private     |  Y    |    N    |    N     |   N
 
//method parameters are available inside the entire method
 
//Other declarations follow lexical scoping,
//being in the scope of the innermost set of braces ({}) to them.
//You may also create local scopes by surrounding blocks of code with braces.
 
public void function(int x){
   //can use x here
   int y;
   //can use x and y here
   {
      int z;
      //can use x, y, and z here
   }
   //can use x and y here, but NOT z
}

