public Observable<ServiceResponse<Page<SiteInner>>> beginResumeWithServiceResponseAsync(final String resourceGroupName, final String name) {
        return beginResumeSinglePageAsync(resourceGroupName, name)
            .concatMap(new Func1<ServiceResponse<Page<SiteInner>>, Observable<ServiceResponse<Page<SiteInner>>>>() {
                @Override
                public Observable<ServiceResponse<Page<SiteInner>>> call(ServiceResponse<Page<SiteInner>> page) {
                    String nextPageLink = page.body().nextPageLink();
                    if (nextPageLink == null) {
                        return Observable.just(page);
                    }
                    return Observable.just(page).concatWith(beginResumeNextWithServiceResponseAsync(nextPageLink));
                }
            });
    }

import java.io.*;
import java.awt.Point;
import java.util.HashMap;
import java.util.Scanner;
 
public class CSV {
 
    private HashMap<Point, String> _map = new HashMap<Point, String>();
    private int _cols;
    private int _rows;
 
    public void open(File file) throws FileNotFoundException, IOException {
        open(file, ',');
    }
 
    public void open(File file, char delimiter)
            throws FileNotFoundException, IOException {
        Scanner scanner = new Scanner(file);
        scanner.useDelimiter(Character.toString(delimiter));
 
        clear();
 
        while(scanner.hasNextLine()) {
            String[] values = scanner.nextLine().split(Character.toString(delimiter));
 
            int col = 0;
            for ( String value: values ) {
                _map.put(new Point(col, _rows), value);
                _cols = Math.max(_cols, ++col);
            }
            _rows++;
        }
        scanner.close();
    }
 
    public void save(File file) throws IOException {
        save(file, ',');
    }
 
    public void save(File file, char delimiter) throws IOException {
        FileWriter fw = new FileWriter(file);
        BufferedWriter bw = new BufferedWriter(fw);
 
        for (int row = 0; row < _rows; row++) {
            for (int col = 0; col < _cols; col++) {
                Point key = new Point(col, row);
                if (_map.containsKey(key)) {
                    bw.write(_map.get(key));
                }
 
                if ((col + 1) < _cols) {
                    bw.write(delimiter);
                }
            }
            bw.newLine();
        }
        bw.flush();
        bw.close();
    }
 
    public String get(int col, int row) {
        String val = "";
        Point key = new Point(col, row);
        if (_map.containsKey(key)) {
            val = _map.get(key);
        }
        return val;
    }
 
    public void put(int col, int row, String value) {
        _map.put(new Point(col, row), value);
        _cols = Math.max(_cols, col+1);
        _rows = Math.max(_rows, row+1);
    }
 
    public void clear() {
        _map.clear();
        _cols = 0;
        _rows = 0;
    }
 
    public int rows() {
        return _rows;
    }
 
    public int cols() {
        return _cols;
    }
 
    public static void main(String[] args) {
        try {
            CSV csv = new CSV();
 
            csv.open(new File("test_in.csv"));
            csv.put(0, 0, "Column0");
            csv.put(1, 1, "100");
            csv.put(2, 2, "200");
            csv.put(3, 3, "300");
            csv.put(4, 4, "400");

import java.util.ArrayList;
import java.util.List;
 
public class Wilson {
 
    public static void main(String[] args) {
        System.out.println("  n | prime?\n------------");
        for (int p : new int[]{2, 3, 9, 15, 29, 37, 47, 57, 67, 77, 87, 97, 237, 409, 659}) {
            System.out.printf("%3d | %b\n", p, isPrime(p));
        }
        System.out.println("\nFirst 120 primes by Wilson's theorem:");
        int n = 0;
        int p = 1;
        while (n < 120) {
            if (isPrime(p)) {
                n++;
                System.out.printf("%3d%s", p, n % 20 == 0? "\n" : " ");
            }
            p++;
        }
        System.out.println("\n1000th through 1015th primes:");
        n = 0;
        p = 1;
        int i = 0;
        while (n < 1015) {
            if (isPrime(p)) {
                n++;
                if (n >= 1000) {
                    i++;
                    System.out.printf("%3d%s", p, i % 16 == 0? "\n" : " ");
                }
            }
            p++;
        }
    }
 
    private static boolean isPrime(int p) {
        return p > 1 && factorialMod(p - 1, p) == p - 1;
    }
 
    private static int factorialMod(int n, int p) {
        int f = 1;
        while (n!= 0 && f!= 0) {
            f = (f * n) % p;
            n--;
        }
        return f;
    }
}

