import java.util.Random;

public class GuessNumber {
    public static void main(String[] args) {
        Random rand = new Random();
        int n = 1 + rand.nextInt(20);
        System.out.println("Guess which number I've chosen in the range 1 to 20\n");
        while (true) {
            System.out.print(" Your guess : ");
            int guess = Integer.parseInt(System.console().readLine());
            switch (guess) {
                case n:
                    System.out.println("Correct, well guessed!");
                    return;
                case n + 1... 20:
                    System.out.println("Your guess is higher than the chosen number, try again");
                    break;
                case 1... n - 1:
                    System.out.println("Your guess is lower than the chosen number, try again");
                    break;
                default:
                    System.out.println("Your guess is inappropriate, try again");
            }
        }
    }
}

