import org.apache.commons.lang.StringUtils;
import org.ovirt.engine.api.model.Domain;
import org.ovirt.engine.api.model.Group;
import org.ovirt.engine.api.restapi.utils.DirectoryEntryIdUtils;
import org.ovirt.engine.api.restapi.utils.GuidUtils;
import org.ovirt.engine.core.aaa.DirectoryGroup;
import org.ovirt.engine.core.common.businessentities.aaa.DbGroup;

public class GroupMapper {

    @Mapping(from = DbGroup.class, to = Group.class)
    public static Group map(DbGroup entity, Group template) {
        Group model = template != null ? template : new Group();
        model.setName(entity.getName());
        model.setId(entity.getId().toString());
        if (!StringUtils.isEmpty(entity.getDomain())) {
            Domain dom = new Domain();
            dom.setName(entity.getDomain());
            dom.setId(DirectoryEntryIdUtils.encode(dom.getName()));
            model.setDomain(dom);
        }
        model.setDomainEntryId(DirectoryEntryIdUtils.encode(entity.getExternalId()));
        model.setNamespace(entity.getNamespace());
        return model;
    }

    @Mapping(from = DirectoryGroup.class, to = Group.class)
    public static Group map(DirectoryGroup entity, Group template) {
        Group model = template != null ? template : new Group();
        model.setName(entity.getName());
        if (!StringUtils.isEmpty(entity.getDirectoryName())) {
            Domain dom = new Domain();
            dom.setName(entity.getDirectoryName());
            dom.setId(DirectoryEntryIdUtils.encode(dom.getName()));
            model.setDomain(dom);
        }
        model.setId(DirectoryEntryIdUtils.encode(entity.getId()));
        model.setNamespace(entity.getNamespace());
        return model;
    }

    @Mapping(from = Group.class, to = DbGroup.class)
    public static DbGroup map(Group model, DbGroup template) {
        DbGroup entity = template != null? template: new DbGroup();
        if (model.isSetName()) {
            entity.setName(model.getName());
        }
        if (model.isSetId()) {
            String id = model.getId();
            entity.setId(GuidUtils.asGuid(id));
        }
        if (model.isSetDomain()) {
            Domain domain = model.getDomain();
            if (domain.isSetName()) {
                entity.setDomain(domain.getName());
            }
        }
        if (model.isSetDomainEntryId()) {
            entity.setExternalId(DirectoryEntryIdUtils.decode(model.getDomainEntryId()));
        }
        if (model.isSetNamespace()) {
            entity.setNamespace(model.getNamespace());
        }
        return entity;
    }

}

public class DotProduct {
 
    public static void main(String[] args) {
        double[] a = {1, 3, -5};
        double[] b = {4, -2, -1};
 
        System.out.println(dotProd(a,b));
    }
 
    public static double dotProd(double[] a, double[] b){
        if(a.length != b.length){
            throw new IllegalArgumentException("The dimensions have to be equal!");
        }
        double sum = 0;
        for(int i = 0; i < a.length; i++){
            sum += a[i] * b[i];
        }
        return sum;
    }
}

import java.math.*;
 
public class Hickerson {
 
    final static String LN2 = "0.693147180559945309417232121458";
 
    public static void main(String[] args) {
        for (int n = 1; n <= 17; n++)
            System.out.printf("%2s is almost integer: %s%n", n, almostInteger(n));
    }
 
    static boolean almostInteger(int n) {
        BigDecimal a = new BigDecimal(LN2);
        a = a.pow(n + 1).multiply(BigDecimal.valueOf(2));
 
        long f = n;
        while (--n > 1)
            f *= n;
 
        BigDecimal b = new BigDecimal(f);
        b = b.divide(a, MathContext.DECIMAL128);
 
        BigInteger c = b.movePointRight(1).toBigInteger().mod(BigInteger.TEN);
 
        return c.toString().matches("0|9");
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Knapsack {

    public static void main(String[] args) {
        List<Item> items = new ArrayList<>();
        items.add(new Item("map", 9, 150, 1));
        items.add(new Item("compass", 13, 35, 1));
        items.add(new Item("water", 153, 200, 3));
        items.add(new Item("sandwich", 50, 60, 2));
        items.add(new Item("glucose", 15, 60, 2));
        items.add(new Item("tin", 68, 45, 3));
        items.add(new Item("banana", 27, 60, 3));
        items.add(new Item("apple", 39, 40, 3));
        items.add(new Item("cheese", 23, 30, 1));
        items.add(new Item("beer", 52, 10, 3));
        items.add(new Item("suntan cream", 11, 70, 1));
        items.add(new Item("camera", 32, 30, 1));
        items.add(new Item("t-shirt", 24, 15, 2));
        items.add(new Item("trousers", 48, 10, 2));
        items.add(new Item("umbrella", 73, 40, 1));
        items.add(new Item("w-trousers", 42, 70, 1));
        items.add(new Item("w-overcoat", 43, 75, 1));
        items.add(new Item("note-case", 22, 80, 1));
        items.add(new Item("sunglasses", 7, 20, 1));
        items.add(new Item("towel", 18, 12, 2));
        items.add(new Item("socks", 4, 50, 1));
        items.add(new Item("book", 30, 10, 2));

        int[] result = chooseItem(400, items.size() - 1, new HashMap<>(), items);
        int w = 0;
        for (int i = 0; i < result.length; i++) {
            if (result[i] > 0) {
                System.out.println(result[i] + " " + items.get(i).name);
                w += items.get(i).weight * result[i];
            }
        }
        System.out.println("Total weight: " + w + ", Value: " + result[0]);
    }

    private static int[] chooseItem(int weight, int id, Map<String, int[]> cache, List<Item> items) {
        if (id < 0) {
            return new int[]{0, 0};
        }
        String key = weight + " " + id;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }
        int value = items.get(id).value;
        int bestV = 0;
        int[] bestList = new int[items.size()];
        for (int i = 0; i <= items.get(id).count; i++) {
            int wlim = weight - i * items.get(id).weight;
            if (wlim < 0) {
                break;
            }
