import java.io.*;
import java.util.*;

public class Checker {
    public static void main(String[] args) {
        var fastScanner = new FastScanner();
        int t = fastScanner.nextInt();
        while (t > 0) {
            int n = fastScanner.nextInt();
            int x = fastScanner.nextInt();
            int[] ar = new int[n];
            for(int i=0; i<n; i++) {
                ar[i] = fastScanner.nextInt();
            }
            int[] prefixSum = new int[n];
            prefixSum[0] = ar[0];
            for (int i = 1; i < n; i++) {
                prefixSum[i] = prefixSum[i - 1] + ar[i];
            }
            int l = 0;
            int r = n - 1;
            int res = -1;
            while (l <= r) {
                int sum = query(prefixSum, l, r);
                if(sum%x != 0) {
                    res = Math.max(res, (r - l) + 1);
                }
                l++;
            }

            l = 0;
            while (l <= r) {
                int sum = query(prefixSum, l, r);
                if(sum%x != 0) {
                    res = Math.max(res, r - l + 1);
                }
                r--;
            }

            System.out.println(res);
            t--;
        }
    }

    private static int query(int[] prefixSum, int l, int r) {
        if (l == 0) return prefixSum[r];

        return prefixSum[r] - prefixSum[l - 1];
    }

    public static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }

    }
}

