class Cache {
    public int[] longestObstacleCourseAtEachPosition(int[] obstacles) {
        int n = obstacles.length;
        int[] dp = new int[n];
        int[] len = new int[n];
        int idx = 0;

        for (int i = 0; i < n; i++) {
            int left = 0, right = idx;
            while (left < right) {
                int mid = left + (right - left) / 2;
                if (dp[mid] <= obstacles[i]) {
                    left = mid + 1;
                } else {
                    right = mid;
                }
            }
            dp[left] = obstacles[i];
            len[i] = left + 1;
            if (left == idx) {
                idx++;
            }
        }

        return len;
    }
}

