public List<Boolean> canMakePaliQueries(String s, int[][] queries) {
int n = s.length();
List<Boolean> ans = new ArrayList<>();
for (int[] q : queries) {
int i = q[0], j = q[1], k = q[2], l = q[3];
int a = (j - i + 1) / 2;
int b = (l - k + 1) / 2;
int[] count = new int[26];
for (int m = i; m <= j; m++) {
count[s.charAt(m) - 'a']++;
}
for (int m = k; m <= l; m++) {
count[s.charAt(m) - 'a']--;
}
int num = 0;
for (int m = 0; m < 26; m++) {
if (count[m] % 2 != 0) {
num++;
}
}
if (num / 2 >= a && num / 2 >= b) {
ans.add(true);
} else {
ans.add(false);
}
}
return ans;
}
}

