/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Account {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        FFullTurn solver = new FFullTurn();
        int testCount = Integer.parseInt(in.next());
        for (int i = 1; i <= testCount; i++)
            solver.solve(i, in, out);
        out.close();
    }

    static class FFullTurn {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt();
            HashMap<Double, int[]> hm = new HashMap<>();
            while (n-- > 0) {
                int x = in.nextInt(), y = in.nextInt(), u = in.nextInt(), v = in.nextInt();
                double num = y - v;
                double den = x - u;
                double m = (den == 0 ? Integer.MAX_VALUE : num / den);
                if (num == 0) m = 0;
                if (!hm.containsKey(m)) {
//                out.print(p.m+" "+p.c+" ");
                    hm.put(m, new int[2]);
                }
                if (m == Integer.MAX_VALUE) {
                    if (y - v > 0) {
                        hm.get(m)[0]++;
                    } else {
                        hm.get(m)[1]++;
                    }
                    continue;
                }
                if (x - u > 0) {
                    hm.get(m)[0]++;
                } else {
                    hm.get(m)[1]++;
                }
            }
            long ans = 0;
            for (Double s : hm.keySet()) {
                int[] arr = hm.get(s);
//            out.println(s+" "+arr[0]+" "+arr[1]);
                ans += (long) arr[0] * (long) arr[1];
            }
            out.println(ans);
        }

    }

    static class InputReader {
        BufferedReader reader;
        StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

