//  Title:  Hofstadter-Conway $10,000 sequence
 
public class HofstadterConwaySequence {
 
    private static int MAX = (int) Math.pow(2, 20) + 1;
    private static int[] HCS = new int[MAX];
    static {
        HCS[1] = 1;
        HCS[2] = 1;
        for ( int n = 3 ; n < MAX ; n++ ) {
            int nm1 = HCS[n - 1];
            HCS[n] = HCS[nm1] + HCS[n - nm1];
        }
    }
 
    public static void main(String[] args) {
        int mNum = 0;
        for ( int m = 1 ; m < 20 ; m++ ) {
            int min = (int) Math.pow(2, m);
            int max = min * 2;
            double maxRatio = 0.0;
            int nVal = 0;
            for ( int n = min ; n <= max ; n ++ ) {
                double ratio = (double) HCS[n] / n;
                if ( ratio > maxRatio ) {
                    maxRatio = Math.max(ratio,  maxRatio);
                    nVal = n;
                }
                if ( ratio >= 0.55 ) {
                    mNum = n;
                }
            }
            System.out.printf("Max ratio between 2^%d and 2^%d is %f at n = %,d%n", m, m+1, maxRatio, nVal);
        }
        System.out.printf("Mallow's number is %d.%n", mNum);
    }
 
}

public static <T, U> T[] copyOfRange(final U[] original, final int from, final int to, final Class<? extends T[]> newType) {
        final int newLength = to - from;
        final T[] copy = Object[].class.equals(newType) ? (T[]) new Object[newLength] : (T[]) N.newArray(newType.getComponentType(), newLength);
        copy(original, from, copy, 0, Math.min(original.length - from, newLength));
        return copy;
    }

public static PrioritizationStrategy getPrioritizationStrategy(String attributeValue, Long processInstanceId) throws StrategyException {
        Package packageVO = processInstanceId == null ? null : getPackage(processInstanceId);
        TaskInstanceStrategyFactory factory = getInstance();
        String className = factory.getStrategyClassName(attributeValue, StrategyType.PrioritizationStrategy);
        PrioritizationStrategy strategy = (PrioritizationStrategy) factory.getStrategyInstance(PrioritizationStrategy.class, className, packageVO);
        return strategy;
    }

import java.awt.GridLayout;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
 
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
 
public class Interact extends JFrame{
    final JTextField numberField;
    final JButton incButton, decButton;
 
    public Interact(){
        //stop the GUI threads when the user hits the X button
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
 
        numberField = new JTextField();
        incButton = new JButton("Increment");
        decButton = new JButton("Decrement");
 
        numberField.setText("0");//start at 0
        decButton.setEnabled(false);//we're already at 0
 
        //listen for button presses in the text field
        numberField.addKeyListener(new KeyListener(){
            @Override
            public void keyTyped(KeyEvent e) {
                //if the entered character is not a digit
                if(!Character.isDigit(e.getKeyChar())){
                    //eat the event (i.e. stop it from being processed)
                    e.consume();
                }else if(Character.isDigit(e.getKeyChar())){
                    //This method is executed from the event thread and updating the GUI
                    //from there doesn't always work. invokeLater will ensure that the
                    //GUI is updated
                    SwingUtilities.invokeLater(new Runnable() {
                        @Override
                        public void run() {
                            String text = numberField.getText();
                            if(text.isEmpty()){//default to 0 when all text is erased
                                numberField.setText("0");
                                decButton.setEnabled(false);
                                incButton.setEnabled(true);
                                return;
                            }
                            if(Long.valueOf(text) <= 0){
                                decButton.setEnabled(false);
                                incButton.setEnabled(true);
                            }else if(Long.valueOf(text) >= 10){
                                incButton.setEnabled(false);
                                decButton.setEnabled(true);
                            }else{
                                incButton.setEnabled(true);
                                decButton.setEnabled(true);
                            }

import java.util.*;

import java.io.*;

import static java.lang.Math.*;

public class Codeforces {

    static Scanner sc=new Scanner(System.in);

    static PrintWriter pw= new PrintWriter(System.out);

    public static void main(String[] args) {

        int t= sc.nextInt();

        in:

        while(t-->0) {

            int n =sc.nextInt();

            if(n%2==1) {

                System.out.println("Bob");

                continue in;

            }

            int cnt=0;

            while(n%2==0) {

                cnt++;n/=2;

            }

            if(n>1) {

                System.out.println("Alice");

            }else {

                System.out.println(cnt%2==0?"Alice":"Bob");

            }

        }

    }

}

public class WaterBetweenTowers {
    public static void main(String[] args) {
        int i = 1;
        int[][] tba = new int[][]{
            new int[]{1, 5, 3, 7, 2},
            new int[]{5, 3, 7, 2, 6, 4, 5, 9, 1, 2},
            new int[]{2, 6, 3, 5, 2, 8, 1, 4, 2, 2, 5, 3, 5, 7, 4, 1},
            new int[]{5, 5, 5, 5},
            new int[]{5, 6, 7, 8},
            new int[]{8, 7, 7, 6},
            new int[]{6, 7, 10, 7, 6}
        };
 
        for (int[] tea : tba) {
            int rht, wu = 0, bof;
            do {
                for (rht = tea.length - 1; rht >= 0; rht--) {
                    if (tea[rht] > 0) {
                        break;
                    }
                }
 
                if (rht < 0) {
                    break;
                }
 
                bof = 0;
                for (int col = 0; col <= rht; col++) {
                    if (tea[col] > 0) {
                        tea[col]--;
                        bof += 1;
                    } else if (bof > 0) {
                        wu++;
                    }
                }
                if (bof < 2) {
                    break;
                }
            } while (true);
 
            System.out.printf("Block %d", i++);
            if (wu == 0) {
                System.out.print(" does not hold any");
            } else {
                System.out.printf(" holds %d", wu);
            }
            System.out.println(" water units.");
        }
    }
}

protected String resolveNamespace(String namespace, String name,
                                    @Nullable URI location) {
    if (getMetaStoreUtil().exists(namespace, name)) {
      return namespace;
    }
    try {
      DatasetDescriptor descriptor = HiveUtils.descriptorForTable(
          conf, getMetaStoreUtil().getTable(URIBuilder.NAMESPACE_DEFAULT, name));
      URI expectedLocation = location;
      if (location == null) {
        expectedLocation = expectedLocation(namespace, name);
      }
      if ((expectedLocation == null) ||
          pathsEquivalent(expectedLocation, descriptor.getLocation())) {

        return URIBuilder.NAMESPACE_DEFAULT;
      }

    } catch (DatasetNotFoundException e) {

    }
    return null;
  }

/*
 * RossetaCode: Law of cosines - triples
 *
 * An quick and dirty brute force solutions with O(N^3) cost.
 * Anyway it is possible set MAX_SIDE_LENGTH equal to 10000
 * and use fast computer to obtain the "extra credit" badge.
 *
 * Obviously, there are better algorithms.
 */
 
import java.lang.Math;
 
public class LawOfCosinesTriples {
 
    public static void main(String[] args) {
        String[] description = {
            "gamma =  90 degrees,  a*a + b*b       == c*c",
            "gamma =  60 degrees,  a*a + b*b - a*b == c*c",
            "gamma = 120 degrees,  a*a + b*b + a*b == c*c"
        };
        int[] coeff = { 0, 1, -1 };
 
        for (int k = 0; k < 3; k++) {
            int counter = 0;
            for (int a = 1; a <= MAX_SIDE_LENGTH; a++)
                for (int b = 1; b <= a; b++)
                    for (int c = 1; c <= MAX_SIDE_LENGTH; c++)
                        if (a * a + b * b - coeff[k] * a * b == c * c) {
                            counter++;
#ifdef DISPLAY_TRIANGLES
                            System.out.printf("  %d  %d  %d\n", a, b, c);
#endif
                        }
            System.out.printf("%s,  number of triangles = %d\n", description[k], counter);
        }
    }
 
    private static final int MAX_SIDE_LENGTH = 13;
}

