import java.util.*;

public class D {

    static Scanner sc = new Scanner(System.in);

    public static void main(String[] args) {

        // TODO Auto-generated method stub

        int testCases = Integer.parseInt(sc.nextLine());

        for (int i = 1; i <= testCases; ++i) {

            solve(i);

        }

    }

    private static void solve(int t) {

        int k = Integer.parseInt(sc.nextLine().split(" ")[1]);

        String s = sc.nextLine();

        int [] arr = new int [26];

        for (char c : s.toCharArray()) {

            ++arr[c - 'a'];

        }

        int ones = 0;

        int twos = 0;

        for (int num : arr) {

            twos += num / 2;

            ones += num % 2;

        }

        int low = 1;

        int high = s.length();

        if (canAssign(high, k,twos, ones)) {

            System.out.println(high);

            return;

        }

        int mid;

        while (high - low > 1) {

            mid = (high + low) / 2;

            if (canAssign(mid, k,twos, ones)) {

                low = mid;

            }else {

                high = mid;

            }

        }

        System.out.println(low);

    }

    private static boolean canAssign(int length, long k, int two, int one) {

        if (length == 1 || k*length <= 2*two)

            return true;

        if (length % 2 == 0) {

            return k*length <= 2*two;

        }

        int unused = (int)Math.max(0, one - k);

        int total = 2*two + one - unused;

        return k * length <= total;

    }

    public static void print(int test, long result) {

        System.out.println("Case #" + test + ": " + result);

    }

}

