        for (int i = 0; i < randomMatrix.length; i++) {
            for (int j = 0; j < randomMatrix[i].length; j++) {
                randomMatrix[i][j] = (int) (Math.random() * 2);
            }
        }

        for (int i = 0; i < randomMatrix.length; i++) {
            for (int j = 0; j < randomMatrix[i].length; j++) {
                System.out.print(randomMatrix[i][j]);
            }
            System.out.println();
        }

        System.out.println("The largest row index is: " +
                findLargerow(randomMatrix));

        System.out.println("The largest column index is: " +
                findLargecolumn(randomMatrix));

    }

    public static int findLargecolumn(int[][] a) {

        int largeColumn = 0;
        int largeSum = a[0][0] + a[1][0] + a[2][0] + a[3][0];
        int Sum = 0;

        for (int i = 1; i < a[0].length; i++) {

            Sum = a[0][i] + a[1][i] + a[2][i] + a[3][i];
            if (Sum > largeSum) {
                largeSum = Sum;
                largeColumn = i;
            }
        }
        return largeColumn;

    }

    public static int findLargerow(int[][] a) {

        int largeRow = 0;
        int largeSum = a[0][0] + a[0][1] + a[0][2] + a[0][3];
        int Sum = 0;

        for (int i = 1; i < a.length; i++) {

            Sum = a[i][0] + a[i][1] + a[i][2] + a[i][3];
            if (Sum > largeSum) {
                largeSum = Sum;
                largeRow = i;
            }

        }

        return largeRow;
    }

}

import com.google.common.base.MoreObjects;
import io.trino.plugin.hive.FileFormatDataSourceStats;
import io.trino.rcfile.RcFileDataSource;
import org.apache.hadoop.fs.FSDataInputStream;

import java.io.IOException;

import static com.google.common.base.Preconditions.checkState;
import static java.util.Objects.requireNonNull;

public class HdfsRcFileDataSource
        implements RcFileDataSource
{
    private final String path;
    private final long size;
    private final FSDataInputStream inputStream;
    private final FileFormatDataSourceStats stats;

    private long readBytes;
    private long readTimeNanos;

    public HdfsRcFileDataSource(
            String path,
            long size,
            FSDataInputStream inputStream,
            FileFormatDataSourceStats stats)
    {
        this.path = requireNonNull(path, "path is null");
        this.size = size;
        this.inputStream = requireNonNull(inputStream, "inputStream is null");
        this.stats = requireNonNull(stats, "stats is null");
    }

    @Override
    public String getId()
    {
        return path;
    }

    @Override
    public void close()
            throws IOException
    {
        inputStream.close();
    }

    @Override
    public long getReadBytes()
    {
        return readBytes;
    }

    @Override
    public long getReadTimeNanos()
    {
        return readTimeNanos;
    }

    @Override
    public long getSize()
    {
        return size;
    }

    @Override
    public void readFully(long position, byte[] buffer, int bufferOffset, int bufferLength)
            throws IOException
    {
        long start = System.nanoTime();
        inputStream.readFully(position, buffer, bufferOffset, bufferLength);
        long duration = System.nanoTime() - start;

        readBytes += bufferLength;
        readTimeNanos += duration;
        stats.readDataBytes(bufferLength);
        stats.readDataTime(duration);
    }

    @Override
    public String toString()
    {
        return MoreObjects.toStringHelper(this)
                .add("path", path)
                .add("size", size)
                .toString();
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.ServerSocket;
import java.net.Socket;
 
public class Checker {
 
    public static void main(String[] args) throws IOException {
        ServerSocket listener = new ServerSocket(12321);
        while (true) {
            Socket conn = listener.accept();
            new Thread(() -> handleClient(conn)).start();
        }
    }
 
    private static void handleClient(Socket conn) {
        try (Socket conn1 = conn) {
            BufferedReader input = new BufferedReader(new InputStreamReader(conn1.getInputStream()));
            BufferedWriter output = new BufferedWriter(new OutputStreamWriter(conn1.getOutputStream()));
 
            String line;
            while ((line = input.readLine())!= null) {
                output.write(line);
                output.newLine();
                output.flush();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

