/**
 * BusinessProcessState is a stateful component designed to manage business process-specific state
 * across the lifecycle of a workflow process instance.
 */
@Component
public class BusinessProcessState {

    private static final Logger logger = LoggerFactory.getLogger(BusinessProcessState.class);

    // Process context variables injected from the process engine
    @Value("#{processInstance.id}")
    private String processInstanceId;

    @Value("#{execution.id}")
    private String executionId;

    // Business process state properties
    private String customerId;
    private String name;
    private long visitCount;

    /**
     * Default constructor.
     */
    public BusinessProcessState() {
        // Initialize default values
        this.visitCount = 0;
        this.name = "Default Process State";
    }

    /**
     * Initialization method to check the process context and log initial state.
     */
    @PostConstruct
    public void init() {
        logger.info("Initializing BusinessProcessState component...");
        logger.info("Process Instance ID: {}", processInstanceId);
        logger.info("Execution ID: {}", executionId);

        if (processInstanceId == null || processInstanceId.trim().isEmpty()) {
            logger.error("Process Instance ID not configured properly!");
            throw new IllegalStateException("Process Instance ID is missing.");
        }
        if (executionId == null || executionId.trim().isEmpty()) {
            logger.error("Execution ID not configured properly!");
            throw new IllegalStateException("Execution ID is missing.");
        }

        logger.info("BusinessProcessState component initialized successfully.");
    }

    /**
     * Sets the customer identifier from process variables.
     * @param customerId the unique customer ID provided by the process variables.
     */
    public void setCustomerId(String customerId) {
        logger.info("Setting customerId to: {}", customerId);
        this.customerId = customerId;
    }

    /**
     * Increments the visit counter and logs the operation.
     */
    public void incrementVisitCount() {
        visitCount++;
        logger.info("Visit count incremented. Current count: {}", visitCount);
    }

