    @JsonProperty("price")
    private long price;

    public static final Coder<SellerPrice> CODER = new CustomCoder<SellerPrice>() {
        private final VarLongCoder longCoder = VarLongCoder.of();

        @Override
        public void encode(SellerPrice value, OutputStream outStream) throws IOException {
            longCoder.encode(value.seller, outStream);
            longCoder.encode(value.price, outStream);
        }

        @Override
        public SellerPrice decode(InputStream inStream) throws IOException {
            long seller = longCoder.decode(inStream);
            long price = longCoder.decode(inStream);
            return new SellerPrice(seller, price);
        }

        @Override
        public boolean isRegisterByteSizeObserverCheap() {
            return true;
        }

        @Override
        public void registerByteSizeObserver(SellerPrice value, Coder.Context context, Coder.ByteSizeObserver observer) throws Exception {
            longCoder.registerByteSizeObserver(value.seller, context, observer);
            longCoder.registerByteSizeObserver(value.price, context, observer);
        }
    };

    public SellerPrice() {
    }

    public SellerPrice(long seller, long price) {
        this.seller = seller;
        this.price = price;
    }

