/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */

public class Calculator {
    private int maxDepth = 0;
    private TreeNode deepest = null;
    public int deepestLeaftValue(TreeNode root) {
        depth(root);
        return deepest.val;
    }
    public int depth(TreeNode node) {
        if (node == null) {
            return 0;
        }
        int left = depth(node.left);
        int right = depth(node.right);
        int res = Math.max(left, right) + 1;
        if (res > maxDepth) {
            maxDepth = res;
            deepest = node;
        }
        return res;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ProcessChecker {

    public static boolean isWindowsProcessAlive(String pid) {
        try {
            String line;
            StringBuilder output = new StringBuilder();

            Process p = Runtime.getRuntime().exec(System.getenv("SystemRoot") + "\\System32\\" + "tasklist.exe");
            BufferedReader input = new BufferedReader(new InputStreamReader(p.getInputStream()));
            while ((line = input.readLine()) != null) {
                output.append(line).append("\n");
            }
            input.close();

            if (output.toString().contains(pid)) {
                return true;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
        return false;
    }

    public static void main(String[] args) {
        String pid = "12345"; // replace with your process id
        System.out.println("Process with PID " + pid + " is running: " + isWindowsProcessAlive(pid));
    }
}

