public class EklemeliSiralama {

    // Insertion sort: grows a sorted prefix one slot at a time.
    public static void sirala(int[] veriler) {
        int boyut = veriler.length;

        for (int mevcut = 1; mevcut < boyut; mevcut++) {
            int tasinacak = veriler[mevcut];
            int bakilan = mevcut;

            // Kaydirarak bosluk ac, sonra degeri yerine koy
            while (bakilan > 0 && veriler[bakilan - 1] > tasinacak) {
                veriler[bakilan] = veriler[bakilan - 1];
                bakilan--;
            }

            veriler[bakilan] = tasinacak;
        }
    }

    private static int[] rastgeleDiziUret(int adet, int ustSinir) {
        int[] sonuc = new int[adet];
        int k = 0;
        do {
            sonuc[k] = (int) (Math.random() * ustSinir);
            k++;
        } while (k < adet);
        return sonuc;
    }

    private static void yazdir(String etiket, int[] veriler) {
        StringBuilder sb = new StringBuilder(etiket);
        for (int deger : veriler) {
            sb.append(deger).append(' ');
        }
        System.out.println(sb.toString().trim());
    }

    public static void main(String[] args) {
        int[] rakamlar = rastgeleDiziUret(20, 100);

        yazdir("Orjinal: ", rakamlar);

        sirala(rakamlar);

        yazdir("Sirali : ", rakamlar);
    }
}

import java.util.Scanner;

class Builder {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        for (int tc = 0; tc < t; tc++) {
            int n = scanner.nextInt();
            int q = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }

            for (int i = 0; i < q; i++) {
                int type = scanner.nextInt();
                if (type == 1) {
                    int l = scanner.nextInt() - 1;
                    int r = scanner.nextInt() - 1;
                    for (int j = l; j <= r; j++) {
                        a[j] = sumOfDigits(a[j]);
                    }
                } else {
                    int x = scanner.nextInt() - 1;
                    System.out.println(a[x]);
                }
            }
        }
    }

    private static int sumOfDigits(int num) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
}

