import java.util.ArrayList;
import java.util.List;
import java.util.Stack;

class DataFrame {
  int sum;
  List<Integer> coins;
  List<Integer> avail_coins;
}

public class Program {
  public static void main(String[] args) {
    Stack<DataFrame> s = new Stack<>();
    s.push(new DataFrame());
    s.peek().sum = 100;
    s.peek().coins = new ArrayList<>();
    s.peek().avail_coins = new ArrayList<>();
    s.peek().avail_coins.add(25);
    s.peek().avail_coins.add(10);
    s.peek().avail_coins.add(5);
    s.peek().avail_coins.add(1);
    int ways = 0;
    while (!s.empty()) {
      DataFrame top = s.pop();
      if (top.sum < 0) continue;
      if (top.sum == 0) {
        ++ways;
        continue;
      }
      if (top.avail_coins.isEmpty()) continue;
      DataFrame d = new DataFrame();
      d.sum = top.sum - top.avail_coins.get(0);
      d.coins = new ArrayList<>(top.coins);
      d.coins.add(top.avail_coins.get(0));
      s.push(d);
      d = new DataFrame();
      d.sum = top.sum;
      d.coins = new ArrayList<>(top.coins);
      d.avail_coins = new ArrayList<>(top.avail_coins);
      d.avail_coins.remove(0);
      s.push(d);
    }
    System.out.println(ways);
  }
}

