        Element copy = (Element) document.importNode(plfChild, false);
        parent.appendChild(copy);

        String id = copy.getAttribute(Constants.ATT_ID);
        if (id != null && !id.equals("")) copy.setIdAttribute(Constants.ATT_ID, true);
        if (copyChildren) {
