import java.util.ArrayList;
import java.util.List;
 
public class SierpinskiCarpet {
    public static void main(String[] args) {
        for (int i = 0; i < 4; i++) {
            System.out.println("\nN=" + i);
            System.out.println(sierpinskiCarpet(i));
        }
    }
 
    public static String sierpinskiCarpet(int n) {
        List<String> carpet = new ArrayList<>();
        carpet.add("#");
        for (int i = 0; i < n; i++) {
            List<String> top = new ArrayList<>();
            for (String x : carpet) {
                top.add(x.repeat(3));
            }
            List<String> middle = new ArrayList<>();
            for (String x : carpet) {
                middle.add(x + x.replace("#", " ") + x);
            }
            List<String> bottom = new ArrayList<>(top);
 
            top.addAll(middle);
            top.addAll(bottom);
            carpet = top;
        }
        return String.join("\n", carpet);
    }
}

