import java.util.Scanner;

public class PizzaForces {

    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);

        int t = in.nextInt();

        for ( int p = 0; p < t; p++) {

            long n = in.nextLong();

            if (n <= 6) {

                System.out.println(15);

            } else if (n <= 8) {

                System.out.println(20);

            } else if (n <= 10) {

                System.out.println(25);

            } else {

                if (n % 6 == 0) {

                    System.out.println((n / 6) * 15);

                } else if (n % 6 == 1 || n % 6 == 2) {

                    System.out.println(((n/6)-1) * 15 + (20));

                } else if (n % 6 == 3 || n % 6 == 4) {

                    System.out.println(((n/6)-2) * 15 + (2 * 20));

                } else {

                    System.out.println(((n/6)-2) * 15 + (20) + (25));

                }

            }

        }

    }

}

