    public static String[] life(String[] dish){
        String[] newGen= new String[dish.length];
        for(int row= 0;row < dish.length;row++){//each row
            newGen[row]= "";
            for(int i= 0;i < dish[row].length();i++){//each char in the row
                String above= "";//neighbors above
                String same= "";//neighbors in the same row
                String below= "";//neighbors below
                if(i == 0){//all the way on the left
                    //no one above if on the top row
                    //otherwise grab the neighbors from above
                    above= (row == 0) ? null : dish[row - 1].substring(i,
                                    i + 2);
                    same= dish[row].substring(i + 1, i + 2);
                    //no one below if on the bottom row
                    //otherwise grab the neighbors from below
                    below= (row == dish.length - 1) ? null : dish[row + 1]
                                    .substring(i, i + 2);
                }else if(i == dish[row].length() - 1){//right
                    //no one above if on the top row
                    //otherwise grab the neighbors from above
                    above= (row == 0) ? null : dish[row - 1].substring(i - 1,
                                    i + 1);
                    same= dish[row].substring(i - 1, i);
                    //no one below if on the bottom row
                    //otherwise grab the neighbors from below
                    below= (row == dish.length - 1) ? null : dish[row + 1]
                                    .substring(i - 1, i + 1);
                }else{//anywhere else
                    //no one above if on the top row
                    //otherwise grab the neighbors from above
                    above= (row == 0) ? null : dish[row - 1].substring(i - 1,
                                    i + 2);
                    same= dish[row].substring(i - 1, i)
                                    + dish[row].substring(i + 1, i + 2);
                    //no one below if on the bottom row
                    //otherwise grab the neighbors from below
                    below= (row == dish.length - 1) ? null : dish[row + 1]

import java.math.BigInteger;
import java.util.Scanner;
 
public class Helper {
    static BigInteger tmp1, tmp2, t5, t239, pows;
    static void actan(BigInteger res, int base, BigInteger pows) {
        int i, neg = 1;
        res = pows.divide(BigInteger.valueOf(base));
        tmp1 = res;
        for (i = 3; ; i += 2) {
            tmp1 = tmp1.divide(BigInteger.valueOf(base * base));
            tmp2 = tmp1.divide(BigInteger.valueOf(i));
            if (tmp2.compareTo(BigInteger.ZERO) == 0) break;
            if (neg) res = res.subtract(tmp2);
            else      res = res.add(tmp2);
            neg =!neg;
        }
    }
    static String get_digits(int n) {
        pows = BigInteger.TEN.pow(n + 20);
        actan(t5, 5, pows);
        t5 = t5.multiply(BigInteger.valueOf(16));
        actan(t239, 239, pows);
        t239 = t239.multiply(BigInteger.valueOf(4));
        t5 = t5.subtract(t239);
        pows = BigInteger.TEN.pow(20);
        t5 = t5.divide(pows);
        return t5.toString();
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int accu = 16384, done = 0;
        String s;
        tmp1 = BigInteger.ZERO;
        tmp2 = BigInteger.ZERO;
        t5 = BigInteger.ZERO;
        t239 = BigInteger.ZERO;
        pows = BigInteger.ZERO;
        while (true) {
            s = get_digits(accu);
            int got = s.length();
            while (s.charAt(got - 1) == '0' || s.charAt(got - 1) == '9') got--;
            System.out.print(s.substring(done, got));
            done = got;
            accu *= 2;
        }
    }
}

