class Sorter {
    public int reachNumber(int target) {
         if (target == 0) {
            return 0;
        }

        target = Math.abs(target);
        int n = (int) Math.floor(Math.sqrt(target));
        for (int i = n; ; i++) {
            int x = (i + 1) * i / 2;
            if (x == target) {
                return i;
            }
            if (x < target) {
                continue;
            }
            if ((x - target) % 2 == 0) {
                return i;
            }
        }
