        private void calc(int n)
            /* Translated from C */
        {
            p[n] = BigInteger.ZERO;
 
            for (int k = 1; k <= n; k++)
            {
                int d = n - k * (3 * k - 1) / 2;
                if (d < 0) break;
 
                if ((k & 1)!= 0) p[n] = p[n].add(p[d]);
                else p[n] = p[n].subtract(p[d]);
 
                d -= k;
                if (d < 0) break;
 
                if ((k & 1)!= 0) p[n] = p[n].add(p[d]);
                else p[n] = p[n].subtract(p[d]);
            }
 
        }
