import java.lang.Byte;
import java.lang.System;

class Order {
    public static void main(String[] args) {
        // add 10+9  result should be 1 0 0 1 1
        System.out.println(add4(1, 0, 1, 0, 1, 0, 0, 1));
    }

    public static byte xor(byte a, byte b) {
        return (byte) (a & (~b) | b & (~a));
    }

    public static byte[] ha(byte a, byte b) {
        byte s = xor(a, b);
        byte c = (byte) (a & b);
        return new byte[]{s, c};
    }

    public static byte[] fa(byte a, byte b, byte c0) {
        byte[] sa_ca = ha(a, c0);
        byte sa = sa_ca[0];
        byte ca = sa_ca[1];
        byte[] s_cb = ha(sa, b);
        byte s = s_cb[0];
        byte cb = s_cb[1];
        byte c1 = (byte) (ca | cb);
        return new byte[]{s, c1};
    }

    public static byte[] add4(byte a3, byte a2, byte a1, byte a0, byte b3, byte b2, byte b1, byte b0) {
        byte[] s0_c0 = fa(a0, b0, (byte) 0);
        byte s0 = s0_c0[0];
        byte c0 = s0_c0[1];
        byte[] s1_c1 = fa(a1, b1, c0);
        byte s1 = s1_c1[0];
        byte c1 = s1_c1[1];
        byte[] s2_c2 = fa(a2, b2, c1);
        byte s2 = s2_c2[0];
        byte c2 = s2_c2[1];
        byte[] s3_v = fa(a3, b3, c2);
        byte s3 = s3_v[0];
        byte v = s3_v[1];
        return new byte[]{v, s3, s2, s1, s0};
    }
}

private void generatePeerLinks(final Metadata m, final Element e) {
    // Check if the metadata contains peer links
    if (m.getPeerLinks() != null && !m.getPeerLinks().isEmpty()) {
        // Iterate over each peer link in the metadata
        for (PeerLink peerLink : m.getPeerLinks()) {
            // Create a new element for the peer link
            Element peerLinkElement = new Element("peerLink");
            // Set the attributes of the peer link element
            peerLinkElement.setAttribute("id", peerLink.getId());
            peerLinkElement.setAttribute("url", peerLink.getUrl());
            // Attach the peer link element to the parent element
            e.addContent(peerLinkElement);
        }
    }
}

public class JSON {
