    public static JSON createInstance() {
        // Create a new instance
        return new JSON();
    }

    // Assuming you have a method to apply changes from a MapBuilder
    public JSON applyChanges(MapBuilder b) {
        // Apply changes from the MapBuilder
        // If there are no changes, return this instance
        if (b.hasChanges()) {
            return this;
        }

        // Otherwise, create a new instance with the changes
        JSON newInstance = createInstance();
        newInstance.applyChanges(b);
