public class HesapMakinesi {

    // Hafiza degiskeni
    private double hafiza;

    // Toplama islemi yapan metod
    public double topla(int a, int b) {
        hafiza = a + b; // Sonucu hafizada sakla
        return hafiza;
    }

    // Cikarma islemi yapan metod
    public double cikart(int a, int b) {
        hafiza = a - b; // Sonucu hafizada sakla
        return hafiza;
    }

    // Carpma islemi yapan metod
    public double carp(int a, int b) {
        hafiza = a * b; // Sonucu hafizada sakla
        return hafiza;
    }

    // Bolme islemi yapan metod
    public double bol(int a, int b) {
        if (b != 0) {
            hafiza = (double) a / b; // Sonucu hafizada sakla
            return hafiza;
        } else {
            System.out.println("Sifira bolme hatasi!");
            return Double.NaN; // Hata durumu
        }
    }

    // Hafiza degiskeninin degeri donduruluyor
    public double hafizayiGoruntule() {
        return hafiza;
    }

    // Hafizayi sifirla
    public void hafizayiSifirla() {
        hafiza = 0;
    }

    public static void main(String[] args) {
        // HesapMakinesi nesnesi olusturuluyor
        HesapMakinesi hesap = new HesapMakinesi();

        // Toplama islemi yapiliyor
        double sonuc = hesap.topla(5, 3);
        System.out.println("Toplama Sonucu: " + sonuc); // 8 olarak yazdirir

        // Hafizayi goruntuleme
        System.out.println("Hafiza: " + hesap.hafizayiGoruntule()); // 8

        // Hafizayi sifirlama
        hesap.hafizayiSifirla();
        System.out.println("Hafiza sifirlandiktan sonra: " + hesap.hafizayiGoruntule()); // 0

        // Yeni bir islemi yapma
        sonuc = hesap.cikart(10, 4);
        System.out.println("Cikarma Sonucu: " + sonuc); // 6 olarak yazdirir
    }
}

public int compareTo(Field field)
    {
        if (field instanceof BaseField) if (!this.isSameType((BaseField)field))
            return super.compareTo(field);
        short short1 = Short.MIN_VALUE, short2 = Short.MAX_VALUE;
        Short tempShort = (Short)this.getData();
        if (tempShort != null)
            short1 = tempShort.shortValue();
        tempShort = (Short)field.getData();
        if (tempShort != null)
            short2 = tempShort.shortValue();
        if (short1 == short2)
            return 0;
        if (short1 < short2)
            return -1;
        else
            return 1;
    }

/*----------------------------------------------------------------------
gjinv - Invert a matrix, Gauss-Jordan algorithm
A is destroyed.  Returns 1 for a singular matrix.
 
___Name_____Type______In/Out____Description_____________________________
   a[n*n]   double*   In        An N by N matrix
   n        int       In        Order of matrix
   b[n*n]   double*   Out       Inverse of A
----------------------------------------------------------------------*/
public static int gjinv(double[] a, int n, double[] b)
{
    int i, j, k, p;
    double f, g, tol;
    if (n < 1) return -1;  /* Function Body */
    f = 0.;  /* Frobenius norm of a */
    for (i = 0; i < n; ++i) {
        for (j = 0; j < n; ++j) {
            g = a[j+i*n];
            f += g * g;
        }
    }
    f = Math.sqrt(f);
    tol = f * 2.2204460492503131e-016;
    for (i = 0; i < n; ++i) {  /* Set b to identity matrix. */
        for (j = 0; j < n; ++j) {
            b[j+i*n] = (i == j)? 1. : 0.;
        }
    }
    for (k = 0; k < n; ++k) {  /* Main loop */
        f = Math.abs(a[k+k*n]);  /* Find pivot. */
        p = k;
        for (i = k+1; i < n; ++i) {
            g = Math.abs(a[k+i*n]);
            if (g > f) {
                f = g;
                p = i;
            }
        }
        if (f < tol) return 1;  /* Matrix is singular. */
        if (p!= k) {  /* Swap rows. */
            for (j = k; j < n; ++j) {
                f = a[j+k*n];
                a[j+k*n] = a[j+p*n];
                a[j+p*n] = f;
            }
            for (j = 0; j < n; ++j) {
                f = b[j+k*n];
                b[j+k*n] = b[j+p*n];
                b[j+p*n] = f;
            }
        }
        f = 1. / a[k+k*n];  /* Scale row so pivot is 1. */
        for (j = k; j < n; ++j) a[j+k*n] *= f;
        for (j = 0; j < n; ++j) b[j+k*n] *= f;
        for (i = 0; i < n; ++i) {  /* Subtract to get zeros. */
            if (i == k) continue;
            f = a[k+i*n];
            for (j = k; j < n; ++j) a[j+i*n] -= a[j+k*n] * f;
            for (j = 0; j < n; ++j) b[j+i*n] -= b[j+k*n] * f;
        }
    }
    return 0;
} /* end of gjinv */

