import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugins.annotations.LifecyclePhase;
import org.apache.maven.plugins.annotations.Mojo;
import sh.isaac.api.LookupService;

//~--- classes ----------------------------------------------------------------

/**
 * Goal which shuts down an open data store.
 */
@Mojo(
   defaultPhase = LifecyclePhase.PROCESS_RESOURCES,
   name         = "shutdown-isaac"
)
public class Shutdown
        extends AbstractMojo {
   /**
    * Execute.
    *
    * @throws MojoExecutionException the mojo execution exception
    */
   @Override
   public void execute()
            throws MojoExecutionException {
      Headless.setHeadless();
      try {
         long start = System.currentTimeMillis();
         getLog().info("Shutdown terminology store");

         // ASSUMES setup has run already
         getLog().info("  Shutting Down");

         LookupService.shutdownSystem();

         getLog().info("Done shutting down terminology store in " + (System.currentTimeMillis() - start) + " ms");
      } catch (final Exception e) {
         throw new MojoExecutionException("Database shutdown failure", e);
      }
   }
}

class Parser {
    int max = 0;

    public int maximumRequests(int n, int[][] requests) {
        dfs(0, requests, new int[n], n, 0);
        return max;
    }

    private void dfs(int start, int[][] requests, int[] map, int n, int num) {
        if (start == requests.length) {
            for (int i = 0; i < n; i++) {
                if (map[i] != 0) return;
            }
            max = Math.max(max, num);
            return;
        }
        dfs(start + 1, requests, map, n, num); // 不选
        map[requests[start][1]]++;
        map[requests[start][0]]--;
        dfs(start + 1, requests, map, n, num + 1);
        map[requests[start][1]]--;
        map[requests[start][0]]++;   //回溯
    }

