//        }));
//    }
}

import java.math.BigInteger;
import java.util.*;
 
public class IBAN {
    private static final String DEFSTRS = ""
            + "AL28 AD24 AT20 AZ28 BE16 BH22 BA20 BR29 BG22 "
            + "HR21 CY28 CZ24 DK18 DO28 EE20 FO18 FI18 FR27 GE22 DE22 GI23 "
            + "GL18 GT28 HU28 IS26 IE22 IL23 IT27 KZ20 KW30 LV21 LB28 LI21 "
            + "LT20 LU20 MK19 MT31 MR27 MU30 MC27 MD24 ME22 NL18 NO15 PK24 "
            + "PS29 PL28 PT25 RO24 SM27 SA24 RS22 SK24 SI19 ES24 SE24 CH21 "
            + "TN24 TR26 AE23 GB22 VG24 GR27 CR21";
    private static final Map<String, Integer> DEFINITIONS = new HashMap<>();
 
    static {
        for (String definition : DEFSTRS.split(" "))
            DEFINITIONS.put(definition.substring(0, 2), Integer.parseInt(definition.substring(2)));
    }
 
    public static void main(String[] args) {
        String[] ibans = {
                "GB82 WEST 1234 5698 7654 32",
                "GB82 TEST 1234 5698 7654 32",
                "GB81 WEST 1234 5698 7654 32",
                "SA03 8000 0000 6080 1016 7519",
                "CH93 0076 2011 6238 5295 7",
                "XX00 0000",
                "",
                "DE",
                "DE13 äöü_ 1234 1234 1234 12"};
        for (String iban : ibans)
            System.out.printf("%s is %s.%n", iban, validateIBAN(iban) ? "valid" : "not valid");
    }
 
    static boolean validateIBAN(String iban) {
        iban = iban.replaceAll("\\s", "").toUpperCase(Locale.ROOT);
 
        int len = iban.length();
        if (len < 4 || !iban.matches("[0-9A-Z]+") || DEFINITIONS.getOrDefault(iban.substring(0, 2), 0) != len)
            return false;
 
        iban = iban.substring(4) + iban.substring(0, 4);
 
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < len; i++)
            sb.append(Character.digit(iban.charAt(i), 36));
 
        BigInteger bigInt = new BigInteger(sb.toString());
 
        return bigInt.mod(BigInteger.valueOf(97)).intValue() == 1;
    }
}

import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import javax.swing.JButton;
import javax.swing.JFrame;
import javax.swing.JPanel;

public class TwoDColorChooser extends JPanel {
    private static final int GRID_ROWS = 4;
    private static final int GRID_COLS = 4;
    private static final Color[][] COLORS = {
        {Color.RED, Color.ORANGE, Color.YELLOW, Color.GREEN},
        {Color.CYAN, Color.BLUE, Color.MAGENTA, Color.PINK},
        {Color.GRAY, Color.LIGHT_GRAY, Color.DARK_GRAY, Color.BLACK},
        {Color.WHITE, Color.RED, Color.ORANGE, Color.YELLOW}
    };
    private JButton[][] colorButtons = new JButton[GRID_ROWS][GRID_COLS];
    private JPanel displayPanel;

    public TwoDColorChooser() {
        setLayout(new GridLayout(1, 2));

        // Create the grid of color buttons
        JPanel gridPanel = new JPanel(new GridLayout(GRID_ROWS, GRID_COLS));
        ColorButtonListener listener = new ColorButtonListener();
        for (int row = 0; row < GRID_ROWS; row++) {
            for (int col = 0; col < GRID_COLS; col++) {
                colorButtons[row][col] = new JButton();
                colorButtons[row][col].setBackground(COLORS[row][col]);
                colorButtons[row][col].setPreferredSize(new Dimension(50, 50));
                colorButtons[row][col].addActionListener(listener);
                gridPanel.add(colorButtons[row][col]);
            }
        }

        // Create the display panel
        displayPanel = new JPanel();
        displayPanel.setBackground(Color.WHITE);
        displayPanel.setPreferredSize(new Dimension(150, 150));

        add(gridPanel);
        add(displayPanel);
    }

    private class ColorButtonListener implements ActionListener {
        @Override
        public void actionPerformed(ActionEvent e) {
            JButton button = (JButton) e.getSource();
            Color selectedColor = button.getBackground();
            displayPanel.setBackground(selectedColor);
        }
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("2D Color Chooser");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.getContentPane().add(new TwoDColorChooser());
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);
    }
}

