public boolean canThreePartsEqualSum(int[] A) {
    int sum = 0;
    for (int x : A)
        sum += x;
    if (sum % 3 != 0)
        return false;
    int target = sum / 3;
    int cur = 0;
    int cnt = 0;
    for (int x : A) {
        cur += x;
        if (cur == target) {
            cur = 0;
            ++cnt;
        }
    }
    return cnt == 3;
}
}

