import java.util.Scanner;

public class Service {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        while (t-- > 0) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = scanner.nextInt();
            }
            if (canSort(a)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
        scanner.close();
    }

    public static boolean canSort(int[] a) {
        int count = 0;
        for (int i = 0; i < a.length - 1; i++) {
            if (a[i] > a[i + 1]) {
                count++;
            }
        }
        return count <= (a.length - 1) * (a.length - 2) / 2;
    }
}

import java.lang.reflect.Field;

public final void copyPrimitiveField(Object source, Object copy, Field field) {
    try {
        Field sourceField = source.getClass().getDeclaredField(field.getName());
        sourceField.setAccessible(true);
        Object value = sourceField.get(source);

        Field copyField = copy.getClass().getDeclaredField(field.getName());
        copyField.setAccessible(true);
        copyField.set(copy, value);
    } catch (NoSuchFieldException | IllegalAccessException e) {
        e.printStackTrace();
    }
}

