import java.io.IOException;
import java.util.Arrays;
import java.util.Objects;

public class EdgeListPropertyFilter implements EdgeListStream {
    private final EdgeListStream sourceStream;
    private final int[] propertyIndicesToKeep;
    private EdgeData cachedEdge;

    public EdgeListPropertyFilter(EdgeListStream sourceStream, int[] propertyIndicesToKeep) {
        this.sourceStream = Objects.requireNonNull(sourceStream, "Source stream cannot be null");
        this.propertyIndicesToKeep = validateAndNormalizeIndices(propertyIndicesToKeep);
    }

    private int[] validateAndNormalizeIndices(int[] indices) {
        if (indices == null || indices.length == 0) {
            throw new IllegalArgumentException("Property indices must be non-empty");
        }

        return Arrays.stream(indices)
                .filter(index -> index >= 0)
                .sorted()
                .toArray();
    }

    @Override
    public boolean hasNextEdge() throws IOException {
        if (cachedEdge != null) {
            return true;
        }

        while (sourceStream.hasNextEdge()) {
            EdgeData originalEdge = sourceStream.getNextEdge();
            if (isValidEdge(originalEdge)) {
                cachedEdge = transformEdge(originalEdge);
                return true;
            }
        }

        return false;
    }

    private boolean isValidEdge(EdgeData originalEdge) {
        return originalEdge != null &&
               originalEdge.getProperties().length >= propertyIndicesToKeep[propertyIndicesToKeep.length - 1] + 1;
    }

    private EdgeData transformEdge(EdgeData originalEdge) {
        String[] sourceProperties = originalEdge.getProperties();
        String[] transformedProperties = new String[propertyIndicesToKeep.length];

        for (int i = 0; i < propertyIndicesToKeep.length; i++) {
            transformedProperties[i] = sourceProperties[propertyIndicesToKeep[i]];
        }

        return new EdgeData(
            originalEdge.getSourceNode(),
            originalEdge.getTargetNode(),
            transformedProperties
        );
    }

    @Override
    public EdgeData getNextEdge() throws IOException {
        if (!hasNextEdge()) {
            throw new IllegalStateException("No more edges available");
        }

        EdgeData result = cachedEdge;
        cachedEdge = null;
        return result;
    }

    @Override
    public void close() throws IOException {
        sourceStream.close();
    }

    // Inner class representing edge data
    public static class EdgeData {
        private final String sourceNode;

