import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class BAN_BAN {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());

        for (int i = 0; i < t; i++) {
            int n = Integer.parseInt(br.readLine());
            int m = n;
            StringBuilder sb = new StringBuilder();

            if (validSubstring(s, s.substring(lastOccurrence(sb, 'B'), lastOccurrence(sb, 'N')))) {
                performOperation(sb, lastOccurrence(sb, 'B') + 1, lastOccurrence(sb, 'N') - 2);
            }

            while (m-- > 0) {
                int[] tuple = getSwappingPoints(sb);
                performOperation(sb, tuple[0], tuple[1]);
            }

            System.out.println(m);
            for (int i = 0; i < m; i++) {
                System.out.println(sb.charAt(tuple[0] - 1) + " " + sb.charAt(tuple[1] - 1));
            }
        }
    }

    static boolean validSubstring(String s, String substring) {
        int maxLength = s.length() - substring.length() + 1;
        for (int i = 0; i < maxLength; i++) {
            if (s.substring(i, i + substring.length()).equals(substring)) {
                return true;
            }
        }
        return false;
    }

    static void performOperation(StringBuilder sb, int i, int j) {
        char temp = sb.charAt(i - 1);
        sb.setCharAt(i - 1, sb.charAt(j - 1));
        sb.setCharAt(j - 1, temp);
    }

    static int[] getSwappingPoints(StringBuilder sb) {
        int i = -1, j = -1;
        for (int k = 1; k < sb.length() - 1; k++) {
            if (sb.charAt(k - 1) == 'B' && sb.charAt(k) == 'N' && sb.charAt(k + 1) == 'B') {
                i = k;
            } else if (sb.charAt(k - 1) == 'N' && sb.charAt(k) == 'B' && sb.charAt(k + 1) == 'N') {
                j = k;
            }
        }
        return new int[]{i, j};
    }

    static int lastOccurrence(StringBuilder sb, char c) {
        for (int i = sb.length() - 1; i >= 0; i--) {
            if (sb.charAt(i) == c) {
                return i;
            }
        }
        return -1;
    }
}

