public class Colorful {
    static boolean colorful(int n) {
        // A colorful number cannot be greater than 98765432.
        if (n < 0 || n > 98765432)
            return false;
        int[] digitCount = new int[10];
        int[] digits = new int[8];
        int numDigits = 0;
        for (int m = n; m > 0; m /= 10) {
            int d = m % 10;
            if (n > 9 && (d == 0 || d == 1))
                return false;
            if (++digitCount[d] > 1)
                return false;
            digits[numDigits++] = d;
        }
        // Maximum number of products is (8 x 9) / 2.
        int[] products = new int[36];
        for (int i = 0, productCount = 0; i < numDigits; ++i) {
            for (int j = i, p = 1; j < numDigits; ++j) {
                p *= digits[j];
                for (int k = 0; k < productCount; ++k) {
                    if (products[k] == p)
                        return false;
                }
                products[productCount++] = p;
            }
        }
        return true;
    }
 
    static int[] count = new int[8];
    static boolean[] used = new boolean[10];
    static int largest = 0;
 
    static void countColorful(int taken, int n, int digits) {
        if (taken == 0) {
            for (int d = 0; d < 10; ++d) {
                used[d] = true;
                countColorful(d < 2? 9 : 1, d, 1);
                used[d] = false;
            }
        } else {
            if (colorful(n)) {
                ++count[digits - 1];
                if (n > largest)
                    largest = n;
            }
            if (taken < 9) {
                for (int d = 2; d < 10; ++d) {
                    if (!used[d]) {
                        used[d] = true;
                        countColorful(taken + 1, n * 10 + d, digits + 1);
                        used[d] = false;
                    }
                }
            }
        }
    }
 
    public static void main(String[] args) {
        Locale.setDefault(Locale.US);
 
        Date start = new Date();
 
        System.out.println("Colorful numbers less than 100:");
        for (int n = 0, count = 0; n < 100; ++n) {
            if (colorful(n))
                System.out.printf("%2d%c", n, ++count % 10 == 0? '\n' :'');
        }
 
        countColorful(0, 0, 0);
        System.out.printf("\n\nLargest colorful number: %'d\n", largest);
 
        System.out.printf("\nCount of colorful numbers by number of digits:\n");
