import jakarta.enterprise.context.spi.Context;
import org.jboss.weld.Container;
import org.jboss.weld.context.ApplicationContext;
import org.jboss.weld.context.DependentContext;
import org.jboss.weld.context.ManagedContext;
import org.jboss.weld.context.http.HttpRequestContext;
import org.jboss.weld.util.ForwardingContext;

public class ContextsImpl {
    private final Container container = Container.instance();

    public Context getRequestContext() {
        return container.requestContext();
    }

    public void setActive(Context context) {
        Context unwrapped = unwrapContext(context);
        if (unwrapped instanceof ApplicationContext) {
            return;
        }
        if (unwrapped instanceof ManagedContext) {
            ((ManagedContext) unwrapped).activate();
        }
    }

    public void setInactive(Context context) {
        Context unwrapped = unwrapContext(context);
        if (unwrapped instanceof ApplicationContext) {
            return;
        }
        if (unwrapped instanceof ManagedContext) {
            ManagedContext managed = (ManagedContext) unwrapped;
            if (managed.isActive()) {
                managed.deactivate();
            }
        }
    }

    public Context getDependentContext() {
        return container.services().get(DependentContext.class);
    }

    public void destroyContext(Context context) {
        Context unwrapped = unwrapContext(context);
        if (unwrapped instanceof ManagedContext) {
            ManagedContext managed = (ManagedContext) unwrapped;
            managed.invalidate();
            if (managed.isActive()) {
                managed.deactivate();
            }
        }
    }

    private Context unwrapContext(Context context) {
        while (context instanceof ForwardingContext) {
            context = ((ForwardingContext) context).delegate();
        }
        return context;
    }

    // Additional utility method for session context (implied by ManagedContext)
    public void activateSessionContext() {
        ManagedContext sessionContext = container.select(ManagedContext.class)
                                                .identifier("Session")
                                                .get();
        sessionContext.activate();
    }

    // Helper to check context activity status
    public boolean isContextActive(Context context) {
        Context unwrapped = unwrapContext(context);
        if (unwrapped instanceof ManagedContext) {
            return ((ManagedContext) unwrapped).isActive();
        }
        return false;
    }
}

