        Class<?>[] params = mConstr != null ? mConstr.getParameterTypes() : new Class[0];
        if (params.length > 1 && MergedClass.InvocationEventObserver.class.equals(params[1])) {
            return mConstr.newInstance(new Object[] {
                new MergingContextFactory(param),
                new MergedClass.InvocationEventObserver() {
                    public void invokedEvent(String caller, String callee, long elapsedTime) { }
                    public long currentTime() { return 0L; }
            }});
        }
        else {
            return mConstr.newInstance(new Object[] {
                new MergingContextFactory(param)});
        }
    }

import java.lang.reflect.*;
 
class Cache {
    private String _name;
    public Cache(String name) { _name = name; }
    public String toString() { return "Hello, I am " + _name; }
}
 
public class BreakPrivacy {
    public static final void main(String[] args) throws Exception {
        Cache foo = new Cache("Eric");
 
        for (Field f : Cache.class.getDeclaredFields()) {
            if (f.getName().equals("_name")) {
                // make it accessible
                f.setAccessible(true);
 
                // get private field
                System.out.println(f.get(foo));
 
                // set private field
                f.set(foo, "Edith");
                System.out.println(foo);
 
                break;
            }
        }
    }
}

import java.util.*;
 
public class HolyKnightsTour {
 
    final static String[] board = {
        " xxx    ",
        " x xx   ",
        " xxxxxxx",
        "xxx  x x",
        "x x  xxx",
        "1xxxxxx ",
        "  xx x  ",
        "   xxx  "};
 
    private final static int base = 12;
    private final static int[][] moves = {{1, -2}, {2, -1}, {2, 1}, {1, 2},
    {-1, 2}, {-2, 1}, {-2, -1}, {-1, -2}};
    private static int[][] grid;
    private static int total = 2;
 
    public static void main(String[] args) {
        int row = 0, col = 0;
 
        grid = new int[base][base];
 
        for (int r = 0; r < base; r++) {
            Arrays.fill(grid[r], -1);
            for (int c = 2; c < base - 2; c++) {
                if (r >= 2 && r < base - 2) {
                    if (board[r - 2].charAt(c - 2) == 'x') {
                        grid[r][c] = 0;
                        total++;
                    }
                    if (board[r - 2].charAt(c - 2) == '1') {
                        row = r;
                        col = c;
                    }
                }
            }
        }
 
        grid[row][col] = 1;
 
        if (solve(row, col, 2))
            printResult();
    }
 
    private static boolean solve(int r, int c, int count) {
        if (count == total)
            return true;
 
        List<int[]> nbrs = neighbors(r, c);
 
        if (nbrs.isEmpty() && count != total)
            return false;
 
        Collections.sort(nbrs, (a, b) -> a[2] - b[2]);
 
        for (int[] nb : nbrs) {
