import java.io.IOException;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Scanner;
 
public class PrimeGaps {
 
    private static final int limit1 = 1000000;
    private static final int limit2 = 10000000;
 
    private static class PrimeInfo {
        private final int maxPrint;
        private int count1 = 0;
        private int count2 = 0;
        private final List<Integer> primes = new ArrayList<>();
 
        public PrimeInfo(int max) {
            maxPrint = max;
        }
 
        public void addPrime(int prime) {
            ++count2;
            if (prime < limit1) {
                ++count1;
            }
            if (count2 <= maxPrint) {
                primes.add(prime);
            }
        }
 
        public void print(PrintWriter os, String name) {
            os.print("First " + maxPrint + " " + name + " primes: ");
            for (int prime : primes) {
                os.print(prime + " ");
            }
            os.println();
            os.println("Number of " + name + " primes below " + limit1 + ": " + count1);
            os.println("Number of " + name + " primes below " + limit2 + ": " + count2);
        }
    }
 
    public static void main(String[] args) throws IOException {
        PrimeSieve sieve = new PrimeSieve(limit2 + 100);
 
        // write numbers with groups of digits separated according to the system default locale
        PrintWriter os = new PrintWriter(new OutputStreamWriter(System.out, Locale.getDefault()));
 
        // count and print strong/weak prime numbers
        PrimeInfo strongPrimes = new PrimeInfo(36);
        PrimeInfo weakPrimes = new PrimeInfo(37);
        int p1 = 2, p2 = 3;
        for (int p3 = 5; p2 < limit2; ++p3) {
            if (!sieve.isPrime(p3)) {
                continue;
            }
            int diff = p1 + p3 - 2 * p2;
            if (diff < 0) {
                strongPrimes.addPrime(p2);
            } else if (diff > 0) {
                weakPrimes.addPrime(p2);
            }
            p1 = p2;
            p2 = p3;
        }
        strongPrimes.print(os, "strong");
        weakPrimes.print(os, "weak");
    }
}
 
class PrimeSieve {
    private final boolean[] sieve;
 
    public PrimeSieve(int max) {
        sieve = new boolean[max];
        sieve[0] = true;
        sieve[1] = true;
        for (int i = 2; i < max; ++i) {
            if (!sieve[i]) {
                for (int j = 2 * i; j < max; j += i) {
                    sieve[j] = true;
                }

