    public String toString() {
        return "Point{" +
                "x=" + x +
                ", y=" + y +
                "}\n";
    }

    @Override
    public int compareTo(Point that) {
        if (this.x == that.x) {
            if (this.y < that.y) {
                return -1;
            }
            if (this.y > that.y) {
                return 1;
            }
            return 0; // this.y == that.y

        } else {
            if (this.x < that.x) {
                return -1;
            }
            if (this.x > that.x) {
                return 1;
            }
            return 0;//this.x == that.x

        }

    }

}

