public class Eertree {
    private static final int EVEN_ROOT = 0;
    private static final int ODD_ROOT = 1;
 
    private static class Node {
        private final int length;
        private final Map<Character, Integer> edges;
        private int suffix;
 
        public Node(int length, Map<Character, Integer> edges, int suffix) {
            this.length = length;
            this.edges = edges;
            this.suffix = suffix;
        }
 
        public int getLength() {
            return length;
        }
 
        public Map<Character, Integer> getEdges() {
            return edges;
        }
 
        public int getSuffix() {
            return suffix;
        }
 
        public void setSuffix(int suffix) {
            this.suffix = suffix;
        }
    }
 
    private static List<Node> eertree(String s) {
        List<Node> tree = new ArrayList<Node>();
        tree.add(new Node(0, new HashMap<Character, Integer>(), ODD_ROOT));
        tree.add(new Node(-1, new HashMap<Character, Integer>(), ODD_ROOT));
        int suffix = ODD_ROOT;
        for (int i = 0; i < s.length(); i++) {
            int n = suffix;
            int k = 0;
            while (true) {
                k = tree.get(n).getLength();
                int b = i - k - 1;
                if (b >= 0 && s.charAt(b) == s.charAt(i)) {
                    break;
                }
                n = tree.get(n).getSuffix();
            }
            if (tree.get(n).getEdges().containsKey(s.charAt(i))) {
                suffix = tree.get(n).getEdges().get(s.charAt(i));
                continue;
            }
            suffix = tree.size();
            tree.add(new Node(k + 2, new HashMap<Character, Integer>(), 0));
            tree.get(n).getEdges().put(s.charAt(i), suffix);
            if (tree.get(suffix).getLength() == 1) {
                tree.get(suffix).setSuffix(0);
                continue;
            }
            while (true) {
                n = tree.get(n).getSuffix();
                int b = i - tree.get(n).getLength() - 1;
                if (b >= 0 && s.charAt(b) == s.charAt(i)) {
                    break;
                }
            }
            tree.get(suffix).setSuffix(tree.get(n).getEdges().get(s.charAt(i)));
        }
        return tree;
    }
 
