            System.out.println(str[0] + " > " + str[1] + "\t" + str[0].compareTo(str[1]) > 0);
            System.out.println(str[0] + " >= " + str[1] + "\t" + str[0].compareTo(str[1]) >= 0);
            System.out.println(str[0] + " < " + str[1] + "\t" + str[0].compareTo(str[1]) < 0);
            System.out.println(str[0] + " <= " + str[1] + "\t" + str[0].compareTo(str[1]) <= 0);
            System.out.println(str[0] + " <=> " + str[1] + "\t" + str[0].compareTo(str[1]));
            System.out.println(str[0] + " casecmp " + str[1] + "\t" + str[0].compareToIgnoreCase(str[1]));
            System.out.println();
        }
    }
}

import android.content.Context;
import android.os.Looper;
import android.util.Log;
import android.widget.Toast;
import org.acra.ACRA;

public class ContextUtils {
    private static final String TAG = "ContextUtils";

    public static void toast(Context context, String toast) {
        toast(context, toast, Toast.LENGTH_SHORT);
    }

    public static void toast(Context context, String toast, int duration) {
        if (context == null || toast == null) {
            Log.e(TAG, "Context or toast message is null");
            return;
        }

        if (Looper.myLooper() != Looper.getMainLooper()) {
            IllegalStateException exception = new IllegalStateException("Toast must be shown on the main thread");
            Log.e(TAG, "Attempted to show toast on non-main thread", exception);
            ACRA.getErrorReporter().handleSilentException(exception);
            return;
        }

        try {
            Toast.makeText(context, toast, duration).show();
        } catch (NullPointerException e) {
            Log.e(TAG, "NullPointerException while showing toast", e);
            ACRA.getErrorReporter().handleSilentException(e);
        }
    }
}

