public class CqueryBuildTool extends PostAnalysisQueryBuildTool<KeyedConfiguredTarget> {

  public CqueryBuildTool(CommandEnvironment env, BuildRequestOptions buildRequestOptions) {
    super(env, buildRequestOptions);
  }

  @Override
  public QueryEnvironment<KeyedConfiguredTarget> getQueryEnvironment(
      String queryExpression,
      WalkableGraph walkableGraph,
      LoadingOptions loadingOptions,
      BuildRequestOptions buildRequestOptions,
      CqueryOptions cqueryOptions,
      Reporter reporter,
      CommandEnvironment env,
      Set<SkyKey> transitiveConfigurationKeys,
      List<BuildConfiguration> configurations)
      throws TargetParsingException, QueryException {
    BuildConfiguration hostConfiguration = env.getHostConfiguration();
    ImmutableList.Builder<QueryFunction> extraFunctions = ImmutableList.builder();
    extraFunctions.addAll(env.getRuntime().getQueryFunctions());

    return new ConfiguredTargetQueryEnvironment(
        walkableGraph,
        hostConfiguration,
        configurations,
        transitiveConfigurationKeys,
        reporter,
        loadingOptions,
        buildRequestOptions,
        cqueryOptions,
        env.getPackageManager().getPackagePathResolver(),
        env.getRelativeWorkingDirectory(),
        TopLevelConfigurations.getOutputFilter(buildRequestOptions),
        extraFunctions.build());
  }
}

public static String rtrim(String expression, String characters) {
    // Convert characters string to a character array
    char[] charArray = characters.toCharArray();

    // Create a StringBuilder to build the regular expression
    StringBuilder regex = new StringBuilder("[").append(charArray[0]);
    for (int i = 1; i < charArray.length; i++) {
        regex.append("|").append(charArray[i]);
    }
    regex.append("]*$");

    // Use replaceAll method to remove trailing characters
    return expression.replaceAll(regex.toString(), "");
}

import java.util.Scanner;

public class Q1689D {

    public static void main(String[] args) {

        Scanner k = new Scanner(System.in);

        int t=0,m=0,n=0;

        t=k.nextInt();

        for(int i=1; i<=t; i++)

        {

            n=k.nextInt();

            m=k.nextInt();

            int maxSum=1, minSum=m+n+1, maxDiff=-n-1, minDiff=m+1;

            for(int j=1; j<=n; j++)

            {

                String Line = k.next();

                int first = Line.indexOf('B');

                int last = Line.lastIndexOf('B');

                if(first>=0)

                {

                    int Sum = first+1+j, Diff = first+1-j;

                    if(Sum<minSum)

                    {

                        minSum = Sum;

                    }

                    if(Diff<minDiff)

                    {

                        minDiff = Diff;

                    }

                    Sum = last+1+j;

                    Diff = last+1-j;

                    if(Sum>maxSum)

                    {

                        maxSum = Sum;

                    }

                    if(Diff>maxDiff)

                    {

                        maxDiff = Diff;

                    }

                }

            }

            int midSum = (int) Math.round((maxSum+minSum)/2.0);

            int midDiff = (int) Math.round((maxDiff+minDiff)/2.0);

            if((midSum+midDiff)%2!=0&&maxSum-minSum>maxDiff-minDiff) midDiff--;

            else if((midSum+midDiff)%2!=0&&maxSum-minSum<=maxDiff-minDiff) midSum--;

            System.out.println((midSum-midDiff)/2 + " " + (midSum+midDiff)/2);

        }

    }

}

public class PCG32 {
    private static final long N = 6364136223846793005L;
 
    private long state = 0x853c49e6748fea9bL;
    private long inc = 0xda3e39cb94b95bdbL;
 
    public void seed(long seedState, long seedSequence) {
        state = 0;
        inc = (seedSequence << 1) | 1;
        nextInt();
        state = state + seedState;
        nextInt();
    }
 
    public int nextInt() {
        long old = state;
        state = old * N + inc;
        int shifted = (int) (((old >>> 18) ^ old) >>> 27);
        int rot = (int) (old >>> 59);
        return (shifted >>> rot) | (shifted << ((~rot + 1) & 31));
    }
 
    public double nextFloat() {
        var u = Integer.toUnsignedLong(nextInt());
        return (double) u / (1L << 32);
    }
 
    public static void main(String[] args) {
        var r = new PCG32();
 
        r.seed(42, 54);
        System.out.println(Integer.toUnsignedString(r.nextInt()));
        System.out.println(Integer.toUnsignedString(r.nextInt()));
        System.out.println(Integer.toUnsignedString(r.nextInt()));
        System.out.println(Integer.toUnsignedString(r.nextInt()));
        System.out.println(Integer.toUnsignedString(r.nextInt()));
        System.out.println();
 
        int[] counts = {0, 0, 0, 0, 0};
        r.seed(987654321, 1);
        for (int i = 0; i < 100_000; i++) {
            int j = (int) Math.floor(r.nextFloat() * 5.0);
            counts[j]++;
        }
 
        System.out.println("The counts for 100,000 repetitions are:");
        for (int i = 0; i < counts.length; i++) {
            System.out.printf("  %d : %d\n", i, counts[i]);
        }
    }
}

import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.apache.commons.codec.binary.Base64;
import javax.enterprise.inject.Typed;

interface PasswordEncryptor {
    String encodePassword(String password, Object salt);
    boolean isPasswordValid(String encPass, String rawPass, Object salt);
}

@Typed(PasswordEncryptor.class)
public class MD5PasswordEncryptor implements PasswordEncryptor {

    private static final long serialVersionUID = 1L;

    @Override
    public String encodePassword(String password, Object salt) {
        String encodedPassword = null;
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            String saltedPass = mergePasswordAndSalt(password, salt, false);
            byte[] passwordHash = digest.digest(saltedPass.getBytes());
            byte[] encoded = Base64.encodeBase64(passwordHash);
            encodedPassword = new String(encoded);
        } catch (NoSuchAlgorithmException ex) {
            System.err.println("MD5 Algorithm not found: " + ex.getMessage());
            return null;
        }
        return encodedPassword;
    }

    @Override
    public boolean isPasswordValid(String encPass, String rawPass, Object salt) {
        String pass2 = encodePassword(rawPass, salt);
        return encPass.equals(pass2);
    }

    protected String mergePasswordAndSalt(String password, Object salt, boolean strict) {
        if (password == null) {
            password = "";
        }

        if (strict && (salt != null)) {
            if ((salt.toString().lastIndexOf("{") != -1) || (salt.toString().lastIndexOf("}") != -1)) {
                throw new IllegalArgumentException("Cannot use { or } in salt.toString()");
            }
        }

        if ((salt == null) || "".equals(salt)) {
            return password;
        } else {
            return password + "{" + salt.toString() + "}";
        }
    }
}

import com.mattunderscore.specky.model.SpecDesc;
import com.mattunderscore.specky.model.TypeDesc;
import com.squareup.javapoet.TypeSpec;

import static com.mattunderscore.specky.javapoet.javadoc.JavaDocBuilder.docType;
import static com.squareup.javapoet.TypeSpec.interfaceBuilder;
import static javax.lang.model.element.Modifier.PUBLIC;

/**
 * {@link TypeInitialiser} for abstract types.
 */
public final class AbstractTypeInitialiser implements TypeInitialiser<TypeDesc> {

    /**
     * @return a type builder for abstract types
     */
    public TypeSpec.Builder create(SpecDesc specDesc, TypeDesc typeDesc) {
        return interfaceBuilder(typeDesc.getName())
            .addModifiers(PUBLIC)
            .addJavadoc(
                docType()
                    .setDescription(
                        typeDesc.getDescription() == null ?
                            "View type $L.\n\nAuto-generated from specification." :
                            typeDesc.getDescription())
                    .setAuthor(typeDesc.getAuthor())
                    .toJavaDoc(),
                typeDesc.getName());
    }
}

import com.google.common.collect.ImmutableSet;
import com.intellij.codeInspection.ex.InspectionElementsMergerBase;
import com.intellij.util.ArrayUtilRt;
import org.jdom.Element;
import org.jetbrains.annotations.NotNull;

import java.util.Map;
