public static byte[] decodeBase16(String stringParam) {
        if(stringParam == null)
        {
            return null;
        }
        if(stringParam.trim().isEmpty())
        {
            return new byte[]{};
        }
        int len = stringParam.length();
        byte[] data = new byte[len / 2];
        for (int i = 0; i < len; i += 2) {
            data[i / 2] = (byte) ((Character.digit(stringParam.charAt(i), 16) << 4)
                    + Character.digit(stringParam.charAt(i+1), 16));
        }
        return data;
    }

private static int decodeHex(final char c) {
    if (c < '0') {
      return INVALID;
    }
    if (c <= '9') {
      return c - '0';
    }
    if (c < 'A') {
      return INVALID;
    }
    if (c <= 'F') {
      return c - 'A' + 10;
    }
    if (c < 'a') {
      return INVALID;
    }
    if (c <= 'f') {
      return c - 'a' + 10;
    }
    return INVALID;
  }

