// Base class for all AST tree nodes.
class TreeNode {
    protected LinkedList<TreeNode> children = new LinkedList<>();

    public TreeNode() {}

    public void addChild(TreeNode child) {
        children.add(child);
    }

    public TreeNode getChild(int index) {
        if (index < 0 || index >= children.size()) {
            throw new IndexOutOfBoundsException("Child index out of range: " + index);
        }
        return children.get(index);
    }

    public void setChild(int index, TreeNode child) {
        if (index < 0 || index >= children.size()) {
            throw new IndexOutOfBoundsException("Child index out of range: " + index);
        }
        children.set(index, child);
    }

    public String toString() {
        return this.getClass().getSimpleName() + "@" + hashCode();
    }
}

// Interface defining common declaration operations.
interface CommonDeclaration {
    public CommonSpecifiers getCommonSpecifiers();
    public CommonDeclarator getDeclarator();
}

// Stub for common specifiers.
class CommonSpecifiers extends TreeNode {
    // Constructor that takes a list of TreeNodes and adds them as specifiers.
    public CommonSpecifiers(LinkedList<TreeNode> specNodes) {
        if (specNodes == null || specNodes.isEmpty()) {
            throw new CXInternalError("Specifiers list cannot be null or empty");
        }
        for (TreeNode node : specNodes) {
            addChild(node);
        }
    }

    public String toString() {
        return "CommonSpecifiers with " + children.size() + " child(ren)";
    }
}

