import org.hibernate.engine.jdbc.connections.spi.ConnectionProvider;
import org.hibernate.engine.jdbc.connections.spi.ConnectionProviderMetaData;
import org.hibernate.service.spi.ServiceRegistryImplementor;
import org.hibernate.service.spi.ServiceRegistry;
import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.SQLException;
import java.util.Properties;

public class DSConnectionProvider implements ConnectionProvider {
    private DataSource _ds;
    private boolean _isClosed = false;

    public void configure(Properties properties) {
        try {
            String dataSourceJndi = properties.getProperty("dataSourceJndi");
            _ds = (DataSource) new InitialContext().lookup(dataSourceJndi);
        } catch (NamingException e) {
            throw new HibernateException("Failed to lookup DataSource", e);
        }
    }

    public Connection getConnection() throws SQLException {
        if (_isClosed) {
            throw new SQLException("ConnectionProvider has been closed");
        }
        return _ds.getConnection();
    }

    public void closeConnection(Connection conn) {
        if (conn != null) {
            try {
                if (conn.getAutoCommit()) {
                    conn.close();
                }
            } catch (SQLException e) {
                // Log exception while closing connection
            }
        }
    }

    public boolean isUnwrappingSupported() {
        return false;
    }

    public <T> T unwrap(Class<T> iface) {
        throw new SQLException("Unwrapping not supported");
    }

    public boolean supportsAggressiveRelease() {
        return true;
    }

    public void close() {
        _isClosed = true;
    }

    public boolean isStatementCache() {
        return false; // specify if statement cache should be implemented
    }

    public ConnectionProviderMetaData getMetaData() {
        return new ConnectionProviderMetaData() {
            public boolean supportsUserTransactions() {
                return true;
            }

            public boolean supportsXA() {
                return false;
            }
        };
    }

    public boolean isClosed() {
        return _isClosed;
    }

    public int getMaxConnections() {
        return 10; // specify the max connections
    }

    public void prepare() {
        // Perform any pre-connection setup if needed
    }

    public void releaseConnection(Connection conn) {
        closeConnection(conn);
    }
}

