public static <T extends Comparable<? super T>> void quickSortWithFallbackToHeapSort(T[] arr, int low, int high) {
    if (low < high) {
        if (high - low < getMaxDepth()) {
            HeapSort.heapSort(arr, low, high);
        } else {
            int pi = partition(arr, low, high);
            quickSortWithFallbackToHeapSort(arr, low, pi - 1);
            quickSortWithFallbackToHeapSort(arr, pi + 1, high);
        }
    }
}

private static <T extends Comparable<? super T>> int partition(T[] arr, int low, int high) {
    T pivot = arr[high];
    int i = low - 1;

    for (int j = low; j < high; j++) {
        if (arr[j].compareTo(pivot) < 0) {
            i++;
            swap(arr, i, j);
        }
    }
    swap(arr, i + 1, high);
    return i + 1;
}

private static <T extends Comparable<? super T>> void swap(T[] arr, int i, int j) {
    T temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

