def find_final_value(s: str, shifts: List[List[int]]) -> str:
    start_shift, end_shift, direction = zip(*shifts)
    count = collections.Counter()
    for a, b in zip(start_shift, end_shift):
        count[a] += 1
        count[b + 1] -= 1

    final_char = []
    cur = 0
    for char in s:
        cur += count[cur]
        if direction[cur - 1]:
            final_char.append(chr((ord(char) - 97 + 1) % 26 + 97))
        else:
            final_char.append(chr((ord(char) - 97 - 1) % 26 + 97))

    return ''.join(final_char)

