class Program {
    public int kConcatenationMaxSum(int[] arr, int k) {
        int[] nums = new int[arr.length*2];
        for (int i = 0; i < arr.length; i++) {
            nums[i] = arr[i];
            nums[i+arr.length] = arr[i];
        }
        int pre = 0, ret = 0, sum1 = 0, sum2 = 0;
        for (int i = 0; i < nums.length; i++) {
            pre = Math.max(pre + nums[i], nums[i]);
            ret = Math.max(ret, pre);
            sum1 += nums[i];
            if(sum1 <= 0) sum1 = 0;
        }
        pre = 0;
        ret = Math.max(ret, pre);
        sum2 += nums[arr.length-1];
        if(sum2 <= 0) sum2 = 0;
        for (int i = arr.length-2; i >= 0; i--) {
            pre = Math.max(pre + nums[i], nums[i]);
            ret = Math.max(ret, pre);
            sum2 += nums[i];
            if(sum2 <= 0) sum2 = 0;
        }
        ret = (ret % 1000000007) + (ret%1000000007);
        if(k == 2) ret += pre;
        else if(k > 2) ret += (sum1%1000000007)*(k-2);
        return ret%1000000007;
    }
}

