import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
 
public class PrimeTransitions {
 
    public static void main(String[] args) {
        // sieve up to the 100 millionth prime
        boolean[] sieved = sieve(2038074743);
 
        Map<Integer, Integer> transMap = new HashMap<>();
        int i = 2; // last digit of first prime
        long p = 3 - 2; // next prime, -2 since we +=2 first
        int n = 1;
        for (int num : new int[]{10000, 1000000, 100000000}) {
            for (; n < num; n++) {
                // Set p to next prime by skipping composites.
                p += 2;
                while (sieved[(int) p]) {
                    p += 2;
                }
                // Count transition of i -> j.
                int j = (int) (p % 10);
                transMap.put(i * 10 + j, transMap.getOrDefault(i * 10 + j, 0) + 1);
                i = j;
            }
            reportTransitions(transMap, n);
        }
    }
 
    private static void reportTransitions(Map<Integer, Integer> transMap, int num) {
        Map<Integer, Integer> sortedMap = new TreeMap<>(transMap);
        System.out.println("First " + num + " primes. Transitions prime % 10 -> next-prime % 10.");
        for (Map.Entry<Integer, Integer> entry : sortedMap.entrySet()) {
            int key = entry.getKey();
            int count = entry.getValue();
            double freq = (double) count / num * 100;
            System.out.printf("%d -> %d  count: %7d", key / 10, key % 10, count);
            System.out.printf("  frequency: %4.2f%%\n", freq);
        }
        System.out.println();
    }
 
    private static boolean[] sieve(int limit) {
        limit++;
        // True denotes composite, false denotes prime.
        // We don't bother filling in the even composites.
        boolean[] c = new boolean[limit];
        c[0] = true;
        c[1] = true;
        int p = 3; // Start from 3.
        while (true) {
            int p2 = p * p;
            if (p2 >= limit) {
                break;
            }
            for (int i = p2; i < limit; i += 2 * p) {
                c[i] = true;
            }
            do {
                p += 2;
            } while (c[p]);
        }
        return c;
    }
}

import java.io.IOException;

import org.junit.Test;
import org.springframework.boot.cli.infrastructure.CommandLineInvoker;
import org.springframework.boot.cli.infrastructure.CommandLineInvoker.Invocation;

import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.startsWith;
import static org.junit.Assert.assertThat;

/**
 * Integration Tests for the command line application.
 *
 */
public class CommandLineIT {

    private final CommandLineInvoker cli = new CommandLineInvoker();

    @Test
    public void hintProducesListOfValidCommands() throws IOException,
            InterruptedException {
        Invocation cli = this.cli.invoke("hint");
        assertThat(cli.await(), equalTo(0));
        assertThat(cli.getErrorOutput().length(), equalTo(0));
        assertThat(cli.getStandardOutputLines().size(), equalTo(10));
    }

    @Test
    public void invokingWithNoArgumentsDisplaysHelp() throws IOException,
            InterruptedException {
        Invocation cli = this.cli.invoke();
        assertThat(cli.await(), equalTo(1));
        assertThat(cli.getErrorOutput().length(), equalTo(0));
        assertThat(cli.getStandardOutput(), startsWith("usage:"));
    }

    @Test
    public void unrecognizedCommandsAreHandledGracefully() throws IOException,
            InterruptedException {
        Invocation cli = this.cli.invoke("not-a-real-command");
        assertThat(cli.await(), equalTo(1));
        assertThat(cli.getErrorOutput(),
                containsString("'not-a-real-command' is not a valid command"));
        assertThat(cli.getStandardOutput().length(), equalTo(0));
    }

    @Test
    public void version() throws IOException, InterruptedException {
        Invocation cli = this.cli.invoke("version");
        assertThat(cli.await(), equalTo(0));
        assertThat(cli.getErrorOutput().length(), equalTo(0));
        assertThat(cli.getStandardOutput(), startsWith("Spring CLI v"));
    }

    @Test
    public void help() throws IOException, InterruptedException {
        Invocation cli = this.cli.invoke("help");
        assertThat(cli.await(), equalTo(1));
        assertThat(cli.getErrorOutput().length(), equalTo(0));
        assertThat(cli.getStandardOutput(), startsWith("usage:"));
    }

}

