import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class LookAndSay {
 
    public static String lookandsay(String number) {
        StringBuilder result = new StringBuilder();
 
        char repeat = number.charAt(0);
        number = number.substring(1, number.length()) + " ";
        int times = 1;
 
        for (char actual : number.toCharArray()) {
            if (actual!= repeat) {
                result.append(times).append(repeat);
                times = 1;
                repeat = actual;
            } else {
                times += 1;
            }
        }
        return result.toString();
    }
 
    public static void main(String[] args) {
        String num = "1";
 
        IntStream.range(1, 11).forEach(i -> {
            System.out.println(num);
            num = lookandsay(num);
        });
    }
}

import com.google.gwt.json.client.JSONArray;
import com.google.gwt.json.client.JSONNumber;
import com.google.gwt.json.client.JSONObject;
import com.google.gwt.json.client.JSONParser;
import com.google.gwt.json.client.JSONString;
import com.google.gwt.json.client.JSONValue;

public class JSONUtil {

    // Parses a JSON string into a JSONValue
    public static JSONValue parse(String json) {
        if (json == null || json.trim().isEmpty()) {
            return null;
        }
        return JSONParser.parseStrict(json);
    }

    // Extracts a JSONObject from a JSONValue
    public static JSONObject getObject(JSONValue v) {
        if (v == null || !v.isObject().booleanValue()) {
            return null;
        }
        return v.isObject();
    }

    // Extracts a JSONArray from a JSONValue
    public static JSONArray getArray(JSONValue v) {
        if (v == null || !v.isArray().booleanValue()) {
            return null;
        }
        return v.isArray();
    }

    // Extracts a String from a JSONValue
    public static String getString(JSONValue v) {
        if (v == null || !v.isString().booleanValue()) {
            return null;
        }
        return v.isString().stringValue();
    }

    // Extracts an Integer from a JSONValue
    public static Integer getInteger(JSONValue v) {
        if (v == null || !v.isNumber().booleanValue()) {
            return null;
        }
        return (int) v.isNumber().doubleValue();
    }

    // Extracts a Double from a JSONValue
    public static Double getDouble(JSONValue v) {
        if (v == null || !v.isNumber().booleanValue()) {
            return null;
        }
        return v.isNumber().doubleValue();
    }

    // Extracts an array of Strings from a JSONValue
    public static String[] getStrings(JSONValue v) {
        JSONArray array = getArray(v);
        if (array == null) {
            return null;
        }

        String[] strings = new String[array.size()];
        for (int i = 0; i < array.size(); i++) {
            JSONValue element = array.get(i);
            strings[i] = getString(element);
        }
        return strings;
    }

    // Example usage
    public static void main(String[] args) {
        String json = "{\"name\":\"John\", \"age\":30, \"scores\":[90, 85, 95]}";
        JSONValue jsonValue = parse(json);

        String name = getString(getObject(jsonValue).get("name"));
        Integer age = getInteger(getObject(jsonValue).get("age"));
        String[] scores = getStrings(getObject(jsonValue).get("scores"));

        System.out.println("Name: " + name);

import java.util.ArrayList;
import java.util.List;
 
// These headers are only needed for the demonstration
import java.util.Collections;
import java.util.Iterator;
 
// This is a template function that works for any array-like object
public class ArrayLike {
    public static <Array> void demonstrate(Array array) {
        // Array element access
        array[2] = "Three";  // Fast, but unsafe - if the index is out of bounds you
                             // get undefined behaviour
        array.at(1) = "Two"; // *Slightly* less fast, but safe - if the index is out
                             // of bounds, an exception is thrown
 
        // Arrays can be used with standard algorithms
        Collections.reverse(array);
        for (Iterator<Array> it = array.iterator(); it.hasNext(); ) {
            Array element = it.next();
            System.out.print(element + " ");
        }
 
        System.out.println();
    }
 
    public static void main(String[] args) {
        // Compile-time sized fixed-size array
        List<String> fixed_size_array = new ArrayList<String>(3);
        fixed_size_array.add("One");
        fixed_size_array.add("Four");
        fixed_size_array.add("Eight");
        // If you do not supply enough elements, the remainder are default-initialized
 
        // Dynamic array
        List<String> dynamic_array = new ArrayList<String>();
        dynamic_array.add("One");
        dynamic_array.add("Four");
        dynamic_array.add("Eight");
        // Dynamically grows to accept new element
 
        // All types of arrays can be used more or less interchangeably
        demonstrate(fixed_size_array);
        demonstrate(dynamic_array);
    }
}

