        StringBuilder content = new StringBuilder();
        while ((line = reader.readLine()) != null) {
            content.append(line).append("\n");
        }
        return parse(content.toString());
    } catch (IOException e) {
        throw new FileParsingException("Failed to read file: " + path, e);
    }
}

