import java.util.HashMap;
import java.util.Map;

public class Vector {
    public int largestExclusive(int[] nums) {
        Map<Integer, Integer> countMap = new HashMap<>();

        // Count the occurrences of each number
        for (int num : nums) {
            countMap.put(num, countMap.getOrDefault(num, 0) + 1);
        }

        // Find the largest integer that occurs exactly once
        int largest = -1;
        for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
            if (entry.getValue() == 1 && entry.getKey() > largest) {
                largest = entry.getKey();
            }
        }

        return largest;
    }
}

class Timer {
    public int getMaximumGenerated(int n) {
        if (n <= 1) return n;
        int[] nums = new int[n + 1];
        nums[0] = 0;
        nums[1] = 1;
        for (int i = 1; i <= n; i++) {
            if (2 * i <= n) nums[2 * i] = nums[i];
            if (2 * i + 1 <= n) nums[2 * i + 1] = nums[i] + nums[i + 1];
        }
        int ans = 0;
        for (int i = 0; i <= n; i++)
            ans = Math.max(ans, nums[i]);
        return ans;
    }
}

class Matrix {
    public int countCharacters(String[] words, String chars) {
        int[] count = new int[26];
        for (char c : chars.toCharArray()) {
            count[c - 'a']++;
        }
        int len = 0;
        for (String word : words) {
            int[] currCount = new int[26];
            boolean isGood = true;
            for (char c : word.toCharArray()) {
                if (++currCount[c - 'a'] > count[c - 'a']) {
                    isGood = false;
                    break;
                }
            }
            if (isGood) {
                len += word.length();
            }
        }
        return len;
    }
}

