public class CF1360G extends PrintWriter {
    CF1360G() { super(System.out); }
    Scanner sc = new Scanner(System.in);
    public static void main(String[] $) {
        CF1360G o = new CF1360G(); o.main(); o.flush();
    }

    void main() {
        int t = sc.nextInt();
        while (t-- > 0) {
            int n = sc.nextInt();
            int m = sc.nextInt();
            int a = sc.nextInt();
            int b = sc.nextInt();
            if (n * a != m * b) {
                println("NO");
                continue;
            }
            println("YES");
            byte[][] cc = new byte[n][m];
            for (int i = 0, j = 0; i < n; i++)
                for (int h = 0; h < a; h++) {
                    cc[i][j] = 1;
                    j = (j + 1) % m;
                }
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++)
                    cc[i][j] += '0';
                println(new String(cc[i]));
            }
        }
    }
}

class Counter {
    public boolean rotateString(String A, String B) {
        if (A.length() != B.length()) return false;
        char start = B.charAt(0);
        for (int i = 0; i < A.length(); i++) {
            if (A.charAt(i) == start) {
                String as = A.substring(i, A.length());
                String bs = B.substring(0, as.length());
                String al = A.substring(0, i);
                String bl = B.substring(as.length(), B.length());
                if (as.equals(bs) && al.equals(bl)) return true;
            }
        }
        return false;
    }
}

public class RN {
 
    enum Numeral {
        I(1), IV(4), V(5), IX(9), X(10), XL(40), L(50), XC(90), C(100), CD(400), D(500), CM(900), M(1000);
        int weight;
 
        Numeral(int weight) {
            this.weight = weight;
        }
    };
 
    public static String roman(long n) {
 
        if( n <= 0) {
            throw new IllegalArgumentException();
        }
 
        StringBuilder buf = new StringBuilder();
 
        final Numeral[] values = Numeral.values();
        for (int i = values.length - 1; i >= 0; i--) {
            while (n >= values[i].weight) {
                buf.append(values[i]);
                n -= values[i].weight;
            }
        }
        return buf.toString();
    }
 
    public static void test(long n) {
        System.out.println(n + " = " + roman(n));
    }
 
    public static void main(String[] args) {
        test(1999);
        test(25);
        test(944);
        test(0);
    }
 
}

