private static void getAssignableTypes( JClass t, Set<JClass> s ) {
        if(!s.add(t))
            return;

        s.add(t.erasure());

        JClass _super = t._extends();
        if(_super!=null)
            getAssignableTypes(_super,s);

        Iterator<JClass> itr = t._implements();
        while(itr.hasNext())
        {
            getAssignableTypes(itr.next(),s);
        }
    }

