import java.util.Scanner;

public class TestDrive {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Main simulation loop: continue until user enters 0 for fuel efficiency
        while (true) {
            System.out.print("Enter fuel efficiency (distance per unit fuel, 0 to exit): ");
            double efficiency = scanner.nextDouble();
            if (efficiency == 0) {
                System.out.println("Exiting simulation. Goodbye!");
                break;
            }

            // Create a new car with the specified fuel efficiency
            Car myCar = new Car(efficiency);
            System.out.println("New car created with fuel efficiency: " + efficiency);

            // Loop for adding fuel: enter 0 to stop adding fuel for the current car
            while (true) {
                System.out.print("Enter amount of fuel to add (0 to stop adding fuel): ");
                double fuel = scanner.nextDouble();
                if (fuel == 0) {
                    System.out.println("Stopped adding fuel for this car.");
                    break;
                }
                myCar.addFuel(fuel);

                // Nested loop for driving: enter 0 to stop driving with current fuel addition
                while (true) {
                    System.out.print("Enter distance to drive (0 to stop driving for current fuel addition): ");
                    double distance = scanner.nextDouble();
                    if (distance == 0) {
                        System.out.println("Stopped driving for current fuel addition.");
                        break;
                    }
                    double actualDistance = myCar.drive(distance);
                    System.out.println("Attempted to drive: " + distance + " units.");
                    System.out.println("Actual distance driven: " + actualDistance + " units.");
                    System.out.println("Remaining fuel: " + myCar.getFuelLevel() + " units.");
                    System.out.println("Odometer reading: " + myCar.getOdometer() + " units.");
                    System.out.println();

                    // If no fuel remains after the drive, exit the driving loop
                    if (myCar.getFuelLevel() <= 0) {
                        System.out.println("No fuel left in the car.");
                        break;
                    }
                } // End of driving loop
            } // End of fuel addition loop
            System.out.println("Session for current car ended.\n");

import java.math.BigInteger;
 
public class Isqrt {
    private static BigInteger isqrt(BigInteger x) {
        if (x.compareTo(BigInteger.ZERO) < 0) {
            throw new IllegalArgumentException("Argument cannot be negative");
        }
        var q = BigInteger.ONE;
        while (q.compareTo(x) <= 0) {
            q = q.shiftLeft(2);
        }
        var z = x;
        var r = BigInteger.ZERO;
        while (q.compareTo(BigInteger.ONE) > 0) {
            q = q.shiftRight(2);
            var t = z;
            t = t.subtract(r);
            t = t.subtract(q);
            r = r.shiftRight(1);
            if (t.compareTo(BigInteger.ZERO) >= 0) {
                z = t;
                r = r.add(q);
            }
        }
        return r;
    }
 
    public static void main(String[] args) {
        System.out.println("The integer square root of integers from 0 to 65 are:");
        for (int i = 0; i <= 65; i++) {
            System.out.printf("%s ", isqrt(BigInteger.valueOf(i)));
        }
        System.out.println();
 
        System.out.println("The integer square roots of powers of 7 from 7^1 up to 7^73 are:");
        System.out.println("power                                    7 ^ power                                                 integer square root");
        System.out.println("----- --------------------------------------------------------------------------------- -----------------------------------------");
        var pow7 = BigInteger.valueOf(7);
        var bi49 = BigInteger.valueOf(49);
        for (int i = 1; i < 74; i += 2) {
            System.out.printf("%2d %,84d %,41d\n", i, pow7, isqrt(pow7));
            pow7 = pow7.multiply(bi49);
        }
    }
}

