                        if ((i!= 1) || (i!= 89)) {
                                result = sum_square_digits(i);
                        } else {
                                result = i;
                        }
                        while ((result!= 1) && (result!= 89)) {
                                result = sum_square_digits(result);
                        }
                        if (result == 89) {
                                count++;
                        }
                }
                System.out.println(count);
        }
 
        public static int sum_square_digits(int n) {
                int i, num = n, sum = 0;
                while (num > 0) {
                        int digit = num % 10;
                        num = (num - digit) / 10;
                        sum += digit * digit;
                }
                return sum;
        }
}

