public class Utils {
    public String originalDigits(String s) {
        int[] strCount = new int[26];
        int[] numCount = new int[10];

        for(char c : s.toCharArray()) {
            strCount[c - 'a']++;
            numCount[c - 'a' + 26]++;
        }

        numCount[0] = strCount['z' - 'a'];
        numCount[2] = strCount['w' - 'a'] - numCount[0];
        numCount[4] = strCount['u' - 'a'] - numCount[2];
        numCount[6] = strCount['x' - 'a'];
        numCount[8] = strCount['g' - 'a'] - numCount[6];

        numCount[1] = strCount['o' - 'a'] - numCount[0] - numCount[2] - numCount[4];
        numCount[5] = strCount['f' - 'a'] - numCount[4];
        numCount[7] = strCount['s' - 'a'] - numCount[6];
        numCount[9] = strCount['i' - 'a'] - numCount[5] - numCount[6] - numCount[8];

        StringBuffer res = new StringBuffer();

        for(int i = 0; i < 10; ++i) {
            for(int j = 0; j < numCount[i]; ++j) {
                res.append(i);
            }
        }

        return res.toString();
    }
}

class Calculator {
    public int minimumMountainRemovals(int[] nums) {

        int n=nums.length;

        int[] inc=new int[n];
        int[] dec=new int[n];
        inc[0]=1;
        for(int i=1;i<n;i++){

            for(int j=i-1;j>=0;j--){
                if(nums[j]<nums[i]){
                    inc[i]=Math.max(inc[i],inc[j]+1);
                }
            }
            if(inc[i]==0){
                inc[i]=1;
            }
        }
        dec[n-1]=1;
        for(int i=n-2;i>=0;i--){

            for(int j=i+1;j<n;j++){
                if(nums[j]<nums[i]){
                    dec[i]=Math.max(dec[i],dec[j]+1);
                }
            }
            if(dec[i]==0){
                dec[i]=1;
            }
        }

        //p(Arrays.toString(inc));
        //p(Arrays.toString(dec));
        int max=0;

        for(int i=1;i<n-1;i++){
            max=Math.max(max,inc[i]+dec[i]-1);
        }

        return n-max;
    }

