}

private void organize() {
    // Get the number of plots in the frame
    int numPlots = plots.size();

    // Calculate the number of rows and columns for the grid layout
    int rows = (int) Math.sqrt(numPlots);
    int cols = (int) Math.sqrt(numPlots);

    // Adjust the number of rows and columns if necessary
    if (rows * cols < numPlots) {
        cols++;
    }
    if (rows * cols < numPlots) {
        rows++;
    }

    // Set the layout of the frame to a grid layout with the calculated rows and columns
    setLayout(new GridLayout(rows, cols));

    // Add each plot to the frame
    for (Plot plot : plots) {
        add(plot);
    }
}

