                // if(ttype == null) ttype = "dumb";

                // XXX Add try around here to catch missing DLL/.so.
                pty = new HandlerPTY();

                if (pty.start(shellCommand) == 0) {
                    bus.broadcast(new OnlineStatus(true));
                } else {
                    bus.broadcast(new OnlineStatus(false));
                }
            }

            public void disconnect() {
                bus.broadcast(new OnlineStatus(false));
