import java.util.Arrays;
import java.util.List;
import static java.util.function.Function.identity;
import static java.util.stream.Collectors.toList;
import static java.util.stream.IntStream.range;
public interface PythagComp{
    static void main(String... args){
        System.out.println(run(20));
    }
 
    static List<List<Integer>> run(int n){
        return
            // Here comes the list comprehension bit
            // input stream - bit clunky
            range(1, n).mapToObj(
                x -> range(x, n).mapToObj(
                    y -> range(y, n).mapToObj(
                        z -> new Integer[]{x, y, z}
                    )
                )
            )
                .flatMap(identity())
                .flatMap(identity())
                // predicate
                .filter(a -> a[0]*a[0] + a[1]*a[1] == a[2]*a[2])
                // output expression
                .map(Arrays::asList)
                // the result is a list
                .collect(toList())
        ;
    }
}

class Order {
    public int largestInteger(int num) {
        String str = Integer.toString(num);
        char[] abuff = str.toCharArray();
        int[] ibuff = new int[abuff.length];
        for (int i = 0; i < abuff.length; i++) ibuff[i] = abuff[i] - '0';

        for (int i = 0; i < ibuff.length; i++) {
            int k = i, max = ibuff[i];
            for (int j = i + 1; j < ibuff.length; j++) {
                if (ibuff[i] % 2 == ibuff[j] % 2) {
                    if (ibuff[j] > max) {
                        max = ibuff[j];
                        k = j;
                    }
                }
            }
            if (max > ibuff[i]) {  // swap
                int tmp = ibuff[i];
                ibuff[i] = max;
                ibuff[k] = tmp;
            }
        }
        for (int i = 0; i < abuff.length; i++)
            abuff[i] = (char) ('0' + ibuff[i]);
        String s = new String(abuff);
        return Integer.parseInt(s);
    }
}

