private static List<CategorizedMonomer> deserializeEditorCategorizationConfig(JsonParser parser)
            throws JsonParseException, IOException {
        List<CategorizedMonomer> config = new LinkedList<CategorizedMonomer>();
        CategorizedMonomer currentMonomer = null;

        parser.nextToken();
        while (parser.hasCurrentToken()) {
            String fieldName = parser.getCurrentName();
            JsonToken token = parser.getCurrentToken();

            if (JsonToken.START_OBJECT.equals(token)) {
                currentMonomer = new CategorizedMonomer();
            } else if (JsonToken.END_OBJECT.equals(token)) {
                config.add(currentMonomer);
            }

            if (fieldName != null) {
                switch (fieldName) {

                case "monomerID":
                    parser.nextToken();
                    currentMonomer.setMonomerID(parser.getText());
                    break;
                case "monomerName":
                    parser.nextToken();
                    currentMonomer.setMonomerName(parser.getText());
                    break;
                case "naturalAnalogon":
                    parser.nextToken();
                    currentMonomer.setNaturalAnalogon(parser.getText());
                    break;
                case "monomerType":
                    parser.nextToken();
                    currentMonomer.setMonomerType(parser.getText());
                    break;
                case "polymerType":
                    parser.nextToken();
                    currentMonomer.setPolymerType(parser.getText());
                    break;
                case "category":
                    parser.nextToken();
                    currentMonomer.setCategory(parser.getText());
                    break;
                case "shape":
                    parser.nextToken();
                    currentMonomer.setShape(parser.getText());
                    break;
                case "fontColor":
                    parser.nextToken();
                    currentMonomer.setFontColor(parser.getText());
                    break;
                case "backgroundColor":
                    parser.nextToken();
                    currentMonomer.setBackgroundColor(parser.getText());
                    break;
                default:
                    break;
                }
            }
            parser.nextToken();
        }

        return config;
    }

import java.sql.ParameterMetaData;
import java.sql.SQLException;
import org.apache.phoenix.jdbc.PhoenixConnection;
import org.apache.phoenix.jdbc.PhoenixParameterMetaData;
import org.apache.phoenix.jdbc.PhoenixStatement;
import org.apache.phoenix.parse.DropSequenceStatement;
import org.apache.phoenix.schema.MetaDataClient;
import org.apache.phoenix.execute.MutationState;

public class DropSequenceCompiler {

    private final PhoenixStatement statement;
    private final DropSequenceStatement dropSequence;

    public DropSequenceCompiler(PhoenixStatement statement, DropSequenceStatement dropSequence) {
        this.statement = statement;
        this.dropSequence = dropSequence;
    }

    public MutationPlan compile() throws SQLException {
        final PhoenixConnection connection = statement.getConnection();
        final StatementContext context = new StatementContext(statement);
        final MetaDataClient client = new MetaDataClient(connection);

        return new MutationPlan() {
            @Override
            public MutationState execute() throws SQLException {
                return client.dropSequence(dropSequence);
            }

            @Override
            public ExplainPlan getExplainPlan() throws SQLException {
                return new ExplainPlan("DROP SEQUENCE " + dropSequence.getSequenceName());
            }

            @Override
            public StatementContext getContext() {
                return context;
            }

            @Override
            public PhoenixConnection getConnection() {
                return connection;
            }

            @Override
            public ParameterMetaData getParameterMetaData() {
                return PhoenixParameterMetaData.EMPTY_PARAMETER_META_DATA;
            }
        };
    }
}

import org.nd4j.linalg.api.buffer.DataBuffer;
