public class Mean extends Sum {

    public Mean() {
        super();
    }

    public Mean(INDArray x, INDArray y, INDArray z, long n) {
        super(x, y, z, n);
    }

    public Mean(INDArray x, INDArray y, long n) {
        super(x, y, n);
    }

    public Mean(INDArray x) {
        super(x);
    }

    @Override
    public String name() {
        return "mean";
    }

    @Override
    public Op opForDimension(int index, int dimension) {
        INDArray xForDimension = x.vectorAlongDimension(index, dimension);
        return new Mean(xForDimension, y.vectorAlongDimension(index, dimension), xForDimension.length());
    }

    @Override
    public Op opForDimension(int index, int... dimension) {
        INDArray xForDimension = x.tensorAlongDimension(index, dimension);
        return new Mean(xForDimension, y.tensorAlongDimension(index, dimension), xForDimension.length());
    }

    @Override
    public double getAndSetFinalResult(double accum) {
        double result = calculateFinalResult(accum, n);
        this.finalResult = result;
        return result;
    }

    @Override
    public float getAndSetFinalResult(float accum) {
        float result = calculateFinalResult(accum, n);
        this.finalResult = result;
        return result;
    }

    @Override
    public IComplexNumber getAndSetFinalResult(IComplexNumber accum) {
        IComplexNumber result = accum.div(n);
        this.finalResultComplex = result;
        return result;
    }

    @Override
    public double calculateFinalResult(double accum, int n) {
        return accum / n;
    }

    @Override
    public float calculateFinalResult(float accum, int n) {
        return accum / n;
    }

    @Override
    public IComplexNumber calculateFinalResult(IComplexNumber accum, int n) {
        return accum.div(n);
    }

    @Override
    public void exec() {
        super.exec();
        if (x.isScalar()) {
            this.finalResult = x.getDouble(0);
        } else {
            if (x.data().dataType() == DataBuffer.Type.DOUBLE) {
                double accum = (double) this.accumulation();
                this.finalResult = calculateFinalResult(accum, n);
            } else if (x.data().dataType() == DataBuffer.Type.FLOAT) {
                float accum = (float) this.accumulation();
                this.finalResult = calculateFinalResult(accum, n);

import io.fabric8.kubernetes.api.model.rbac.ClusterRoleBinding;
