import java.util.stream.IntStream;
import java.util.stream.Collectors;
 
public class Sorter {
    public static void main(String[] args) {
        System.out.println(Primes(100).collect(Collectors.joining(" ")));
    }
 
    static IntStream Primes(int limit) {
        return IntStream.range(2, limit).filter(Sorter::IsPrime);
    }
 
    static boolean IsPrime(int n) {
        return IntStream.range(2, (int)Math.sqrt(n)).allMatch(i -> n % i!= 0);
    }
}

import java.awt.Graphics;
import java.util.Random;

import com.snake.system.Core;
import com.snake.system.Painter;
import com.snake.system.Updater;
import com.snake.system.model.CellElement;
import com.snake.system.model.Sprite;

public class Seed extends CellElement {

    public enum SeedType {
        BOMB,
        WALL
    }

    private SeedType type;
    private int power;
    private static int seedsCounter = 0;
    private static final int MAX_SEEDS = 3;
    private static Sprite bomb;

    public Seed(int x, int y) {
        super(x, y);
        Random random = Core.getRandom();
        this.type = random.nextDouble() < 0.5 ? SeedType.BOMB : SeedType.WALL;
        this.power = random.nextInt(3) + 1;
        seedsCounter++;
    }

    public static void tryToSpawn() {
        if (seedsCounter < MAX_SEEDS && Core.getRandom().nextDouble() < 0.01) {
            int x, y;
            do {
                x = Core.getRandom().nextInt(Painter.GRID_WIDTH);
                y = Core.getRandom().nextInt(Painter.GRID_HEIGHT);
            } while (Updater.getGrid()[x][y] != null);

            Updater.getGrid()[x][y] = new Seed(x, y);
        }
    }

    @Override
    public void draw(Graphics g) {
        if (type == SeedType.BOMB) {
            if (bomb == null) {
                bomb = new Sprite("/bomb.png");
            }
            Painter.drawSprite(g, bomb, x, y);
        } else {
            // Draw wall sprite, to be implemented
            Painter.drawSquare(g, x, y, "green"); //temp
        }
    }

    public int getPower() {
        return power;
    }

    public SeedType getType() {
        return type;
    }

    public static void decreaseSeedCounter(){
        seedsCounter--;
    }
}

import static org.junit.Assert.assertEquals;
import org.junit.Before;
import org.junit.Test;
import org.w3c.dom.Document;

public class VanillaCajaHtmlSerializerTest {

    private VanillaCajaHtmlParser parser;
    private VanillaCajaHtmlSerializer serializer;

    @Before
    public void setUp() {
        parser = new VanillaCajaHtmlParser();
        serializer = new VanillaCajaHtmlSerializer();
    }

    @Test
    public void testParseAndSerializeNonASCIINotEscaped() throws Exception {
        String inputHtml = "<div>Non-ASCII: こんにちは</div>";
        Document document = parser.parse(inputHtml);
        String outputHtml = serializer.serialize(document);

        // Validate that the output matches the input
        assertEquals("Serialized HTML should match input HTML", inputHtml, outputHtml);
    }

    @Test
    public void testParseAndSerializeCommentsNotRemoved() throws Exception {
        String inputHtml = "<!-- Comment Here --> <span>Hello World</span>";
        Document document = parser.parse(inputHtml);
        String outputHtml = serializer.serialize(document);

        // Validate that the output includes the original comment
        assertEquals("Serialized HTML should include comments", inputHtml, outputHtml);
    }

    @Test
    public void testParseAndSerializeMultipleNonASCIICharacters() throws Exception {
        String inputHtml = "<p>Test with emojis 😊 and other chars: 你好</p>";
        Document document = parser.parse(inputHtml);
        String outputHtml = serializer.serialize(document);

        // Ensure that output matches input
        assertEquals("Serialized HTML should match input with multiple non-ASCII", inputHtml, outputHtml);
    }

    @Test
    public void testSerializeEmptyDocument() throws Exception {
        String inputHtml = "";
        Document document = parser.parse(inputHtml);
        String outputHtml = serializer.serialize(document);

        // Validate empty input and output
        assertEquals("Serialized HTML of an empty document should be empty", inputHtml, outputHtml);
    }

    @Test
    public void testParseAndSerializeWithNestedTags() throws Exception {
        String inputHtml = "<div><h1>Title</h1><p>Paragraph with <a href='#'>link</a>.</p></div>";
        Document document = parser.parse(inputHtml);
        String outputHtml = serializer.serialize(document);

        // Validate that the nested tags are preserved
        assertEquals("Serialized HTML should match input with nested tags", inputHtml, outputHtml);
    }

