import java.util.Collections;
import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * A specialized class evolution mutation strategy that allows for the deletion of
 * secondary keys associated with entity classes during schema evolution.
 * <p>
 * This class allows converting instances of an entity class from a specific
 * version to the current version, while also enabling the specification of
 * secondary key names that should be deleted.
 */
public class EntityConverter {

    private final String entityClassName;
    private final int classVersion;
    private final Object conversion;
    private final Set<String> deletedKeys;

    /**
     * Creates a new instance of EntityConverter.
     *
     * @param entityClassName The name of the entity class.
     * @param classVersion    The class version being converted from.
     * @param conversion      The general conversion object.
     * @param deletedKeys     The set of key names to delete.
     */
    public EntityConverter(String entityClassName, int classVersion, Object conversion, Set<String> deletedKeys) {
        this.entityClassName = entityClassName;
        this.classVersion = classVersion;
        this.conversion = conversion;
        this.deletedKeys = (deletedKeys != null) ? Collections.unmodifiableSet(new HashSet<>(deletedKeys)) : Collections.emptySet();
    }

    /**
     * Returns an immutable set of the key names that will be deleted.
     *
     * @return An immutable set of deleted key names.
     */
    public Set<String> getDeletedKeys() {
        return deletedKeys;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        EntityConverter that = (EntityConverter) o;
        return classVersion == that.classVersion &&
                Objects.equals(entityClassName, that.entityClassName) &&
                Objects.equals(conversion, that.conversion) &&
                Objects.equals(deletedKeys, that.deletedKeys);
    }

    @Override
    public int hashCode() {
        return Objects.hash(entityClassName, classVersion, conversion, deletedKeys);
    }

    @Override
    public String toString() {
        return "EntityConverter{" +
                "entityClassName='" + entityClassName + '\'' +
                ", classVersion=" + classVersion +
                ", conversion=" + conversion +
                ", deletedKeys=" + deletedKeys +
                '}';
    }
}

