class Timer {

    int mod = (int) 1e9 + 7;

    public int countPalindromes(String s) {
        int n = s.length();

        int[] cnt1 = new int[10];
        int[][] dp1 = new int[n][100];
        for (int i = 0; i < n; i++) {
            if (i > 0) {
                for (int x = 0; x < 100; x++) {
                    dp1[i][x] = dp1[i - 1][x];
                }
            }
            int a = s.charAt(i) - '0';
            for (int b = 0; b < 10; b++) {
                int x = b * 10 + a;
                // if (a == 3 && cnt1[b] != 0) System.out.println(i + " " + x + " " + a + " " + b + " " + cnt1[b]);
                dp1[i][x] += cnt1[b];
            }
            cnt1[a]++;
        }

        // for (int i = 0; i < n; i++) {
        //     System.out.println(dp1[i][3]);
        // }

        int[] cnt2 = new int[10];
        int[][] dp2 = new int[n][100];
        for (int i = n - 1; i >= 0; i--) {
            if (i < n - 1) {
                for (int x = 0; x < 100; x++) {
                    dp2[i][x] = dp2[i + 1][x];
                }
            }
            int a = s.charAt(i) - '0';
            for (int b = 0; b < 10; b++) {
                int x = b * 10 + a;
                dp2[i][x] += cnt2[b];
            }
            cnt2[a]++;
        }

        // System.out.println(dp1);
        // System.out.println(Arrays.deepToString(dp2));

        long ans = 0;
        for (int i = 2; i < n - 2; i++) {
            for (int x = 0; x < 100; x++) {
                // if (dp1[i - 1][x] != 0 && dp2[i + 1][x] != 0)
                //     System.out.println(i + " " + x + " " + dp1[i - 1][x] + " " + dp2[i + 1][x]);
                ans = (ans + (long) dp1[i - 1][x] * dp2[i + 1][x]) % mod;
            }
        }
        return (int) ans;
    }
}

import java.util.Scanner;

public class PointInCircle {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt user to enter point (x, y)
        System.out.print("Enter a point (x, y): ");
        double x = scanner.nextDouble();
        double y = scanner.nextDouble();

        // Calculate distance between (x, y) and (0, 0)
        double distance = Math.sqrt(Math.pow(x, 2) + Math.pow(y, 2));

        // Check if point is within circle with radius 10
        if (distance <= 10) {
            System.out.println("The point (" + x + ", " + y + ") is inside the circle.");
        } else {
            System.out.println("The point (" + x + ", " + y + ") is outside the circle.");
        }

        scanner.close();
    }
}

