        JobDetail jobDetail = JobBuilder.newJob(TwitterFeedScheduler.class)
                .withIdentity("TwitterFeedRefreshJob")
                .build();

        Trigger trigger = TriggerBuilder.newTrigger()
                .withIdentity("TwitterFeedRefreshTrigger")
                .withSchedule(SimpleScheduleBuilder.simpleSchedule()
                        .withIntervalInMinutes(REFRESH_INTERVAL_MINUTES)
                        .repeatForever())

import com.amazonaws.transform.JsonUnmarshallerContext;
import com.amazonaws.transform.Unmarshaller;
import com.fasterxml.jackson.core.JsonToken;
import com.amazonaws.services.elasticmapreduce.model.Cluster;
import com.amazonaws.services.elasticmapreduce.model.DescribeClusterResult;
import com.fasterxml.jackson.core.JsonParser;

public class DescribeClusterResultJsonUnmarshaller implements Unmarshaller<DescribeClusterResult, JsonUnmarshallerContext> {

    private static DescribeClusterResultJsonUnmarshaller instance;

    public static DescribeClusterResultJsonUnmarshaller getInstance() {
        if (instance == null) {
            instance = new DescribeClusterResultJsonUnmarshaller();
        }
        return instance;
    }

    public DescribeClusterResult unmarshall(JsonUnmarshallerContext context) throws Exception {
        DescribeClusterResult result = new DescribeClusterResult();
        if (context == null) return result;

        JsonParser parser = context.getJsonParser();
        if (parser.getCurrentToken() == null) parser.nextToken();

        if (parser.getCurrentToken() != JsonToken.START_OBJECT) {
            parser.nextToken();
            if (parser.getCurrentToken() != JsonToken.START_OBJECT) return result;
        }

        int originalDepth = parser.getCurrentDepth();

        while (true) {
            JsonToken token = parser.nextToken();
            if (token == null || (token == JsonToken.END_OBJECT && parser.getCurrentDepth() <= originalDepth))
                break;

            if (token == JsonToken.FIELD_NAME) {
                String fieldName = parser.getCurrentName();
                parser.nextToken();

                if ("Cluster".equals(fieldName)) {
                    Cluster cluster = ClusterJsonUnmarshaller.getInstance().unmarshall(context);
                    result.setCluster(cluster);
                } else {
                    parser.skipChildren();
                }
            } else {
                parser.skipChildren();
            }
        }
        return result;
    }
}

import java.util.Objects;
import java.util.function.Predicate;
 
public class RealNumberSet {
    public enum RangeType {
        CLOSED,
        BOTH_OPEN,
        LEFT_OPEN,
        RIGHT_OPEN,
    }
 
    public static class RealSet {
        private Double low;
        private Double high;
        private Predicate<Double> predicate;
        private double interval = 0.00001;
 
        public RealSet(Double low, Double high, Predicate<Double> predicate) {
            this.low = low;
            this.high = high;
            this.predicate = predicate;
        }
 
        public RealSet(Double start, Double end, RangeType rangeType) {
            this(start, end, d -> {
                switch (rangeType) {
                    case CLOSED:
                        return start <= d && d <= end;
                    case BOTH_OPEN:
                        return start < d && d < end;
                    case LEFT_OPEN:
                        return start < d && d <= end;
                    case RIGHT_OPEN:
                        return start <= d && d < end;
                    default:
                        throw new IllegalStateException("Unhandled range type encountered.");
                }
            });
        }
 
        public boolean contains(Double d) {
            return predicate.test(d);
        }
 
        public RealSet union(RealSet other) {
            double low2 = Math.min(low, other.low);
            double high2 = Math.max(high, other.high);
            return new RealSet(low2, high2, d -> predicate.or(other.predicate).test(d));
        }
 
        public RealSet intersect(RealSet other) {
            double low2 = Math.min(low, other.low);
            double high2 = Math.max(high, other.high);
            return new RealSet(low2, high2, d -> predicate.and(other.predicate).test(d));
        }
 
        public RealSet subtract(RealSet other) {
            return new RealSet(low, high, d -> predicate.and(other.predicate.negate()).test(d));
        }
 
        public double length() {
            if (low.isInfinite() || high.isInfinite()) return -1.0; // error value
            if (high <= low) return 0.0;
            Double p = low;
            int count = 0;
            do {
                if (predicate.test(p)) count++;
                p += interval;
            } while (p < high);
            return count * interval;
        }
 
        public boolean isEmpty() {
            if (Objects.equals(high, low)) {
                return predicate.negate().test(low);
            }
            return length() == 0.0;
        }
    }

