            System.out.println("Usage: java Counter sourceFile");
            return;
        }
        File file = new File(args[0]);

        if (file.exists()) {

            try {
                Scanner scanner = new Scanner(file);
                while (scanner.hasNextLine()) {
                    String line = scanner.nextLine();
                    lines.add(line);

                }

                for (int i = 1; i < lines.size(); i++) {
                    if (lines.get(i).contains("{")) {
                        String orgLine = lines.get(i);
                        orgLine = orgLine.replace('{', ' '); //Remove open bracket
                        String targetLine = lines.get(i - 1); //Get preceding line of open bracket
                        targetLine = targetLine + " {"; // Add the bracket to the end of line
                        lines.set(i, orgLine);
                        lines.set(i - 1, targetLine);
                    }
                }
                PrintWriter writer = new PrintWriter(file);

                for (String line : lines) {
                    writer.println(line);
                }
                writer.close();

            } catch (FileNotFoundException e) {
                System.out.println("File could not be found to exist: " + e);

            }
        }
    }
}

import android.content.Context;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ArrayAdapter;
import android.widget.Button;
import android.widget.TextView;

public class SharesAdapter extends ArrayAdapter<String> {

    private final Context context;
    private final String[] strings;
    private final String[] regions;
    private final String[] shares;
    private final String[] ticks;
    private final SharesGraphicsBuilder graph;

    public SharesAdapter(Context context, String[] strings, String[] regions, String[] shares, String[] ticks,
            SharesGraphicsBuilder graph) {
        super(context, R.layout.shares_box, strings);
        this.context = context;
        this.strings = strings;
        this.regions = regions;
        this.shares = shares;
        this.ticks = ticks;
        this.graph = graph;
    }

    @Override
    public View getDropDownView(int position, View convertView, ViewGroup parent) {
        return getCustomView(position, convertView, parent);
    }

    @Override
    public View getView(int position, View convertView, ViewGroup parent) {
        return getCustomView(position, convertView, parent);
    }

    public View getCustomView(int position, View convertView, ViewGroup parent) {
        LayoutInflater inflater = (LayoutInflater) context.getSystemService(Context.LAYOUT_INFLATER_SERVICE);
        View rowView = inflater.inflate(R.layout.shares_box, parent, false);

        TextView label = rowView.findViewById(R.id.company);
        TextView labelRegion = rowView.findViewById(R.id.region);
        TextView labelChange = rowView.findViewById(R.id.change);
        Button minus = rowView.findViewById(R.id.minus);
        Button plus = rowView.findViewById(R.id.plus);

        label.setText(strings[position]);
        labelRegion.setText(regions[position]);
        labelChange.setText(shares[position]);

        minus.setOnClickListener(v -> changeShare(ticks[position], -1, labelChange));
        plus.setOnClickListener(v -> changeShare(ticks[position], 1, labelChange));

        return rowView;
    }

    private void changeShare(String tick, int delta, TextView labelChange) {
        FileHandler fileHandler = new FileHandler(context);
        if (delta < 0) {
            int currentShares = fileHandler.getSharesFromTick(tick);
            if (currentShares == 0) {
                return;
            }
        }
        fileHandler.changeShare(tick, delta);
        labelChange.setText(String.valueOf(fileHandler.getSharesFromTick(tick)));

class Employee {
    public int commonFactors(int a, int b) {
        int cnt = 0;
        for(int i=1;i<=Math.min(a,b);i++) {
            if(a%i==0 && b %i==0) cnt++;
        }
        return cnt;
    }
}

import java.util.Scanner;

public class Helper {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Enter the first positive integer: ");
        int n1 = input.nextInt();

        System.out.println("Enter the second positive integer: ");
        int n2 = input.nextInt();

        int gcd = Math.min(n1, n2);

        while (n1 % gcd != 0 || n2 % gcd != 0) {
            gcd--;
        }
        System.out.println("The GCD of " + n1 + " and " + n2 + " is " + gcd);

    }

}

