class Helper {
    public int twoSumLessThanK(int[] A, int K) {
        int max = -1;
        for(int i = 0; i < A.length; i++) {
            for(int j = i + 1; j < A.length; j++) {
                if(A[i] + A[j] < K) {
                    max = Math.max(max, A[i] + A[j]);
                }
            }
        }
        return max;
    }
}

class Cache {
    public int maxFrequency(int[] nums, int k) {
        if (nums.length == 0) return 0;
        Arrays.sort(nums);
        int best = 1;
        for (int i=0; i<nums.length; i++) {
            if (i+1 < nums.length && nums[i+1] == nums[i]) continue;
            int j = i-1;
            int used = 0;
            while (j>=0 && used < k) {
                used += nums[i] - nums[j];
                if (used <= k) best = Math.max(best, i-j+1);
                j--;
            }
        }
        return best;
    }
}

import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.Pane;
import javafx.scene.text.Text;
import javafx.stage.Stage;

public class MousePositionOnPress extends Application {
    @Override
    public void start(Stage primaryStage) {
        Text positionText = new Text();

        Pane pane = new Pane();
        pane.getChildren().add(positionText);

        pane.setOnMousePressed(e -> {
            double x = e.getX();
            double y = e.getY();

            positionText.setText("Mouse position: (" + x + ", " + y + ")");
            positionText.setX(x);
            positionText.setY(y);
        });

        pane.setOnMouseReleased(e -> {
            positionText.setText("");
        });

        Scene scene = new Scene(pane, 400, 400);
        primaryStage.setScene(scene);
        primaryStage.setTitle("Mouse Position On Press");
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

@Override
    public void contextInitialized(
            final ServletContextEvent servletContextEvent) {
        logger.info("Rebuilding Search Index...");

        SessionFactory factory = createSessionFactory();

        Session session = factory.openSession();

        FullTextSession fullTextSession = Search.getFullTextSession(session);
        try {
            fullTextSession
                    .createIndexer()
                    .startAndWait();
        } catch (InterruptedException e) {
            logger.warn("Search reindex interrupted. Good luck!");
            logger.trace("Error:", e);
        } finally {

            session.close();
            factory.close();
        }
    }

