import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.MemoryUsage;

public class TestMemoryMXBeans {

    public static void main(String[] args) {
        if (args.length != 2) {
            throw new IllegalArgumentException("Usage: java TestMemoryMXBeans <expectedInitSizeMB> <expectedMaxSizeMB>");
        }

        try {
            long expectedInitSizeMB = Long.parseLong(args[0]);
            long expectedMaxSizeMB = Long.parseLong(args[1]);

            testMemoryBean(expectedInitSizeMB, expectedMaxSizeMB);
            System.out.println("Memory settings are correct.");
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Expected memory sizes must be valid numbers.", e);
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }
    }

    private static void testMemoryBean(long initSize, long maxSize) {
        MemoryMXBean memoryMXBean = ManagementFactory.getMemoryMXBean();
        MemoryUsage heapMemoryUsage = memoryMXBean.getHeapMemoryUsage();

        long heapInit = heapMemoryUsage.getInit() / (1024 * 1024);
        long heapMax = heapMemoryUsage.getMax() / (1024 * 1024);

        if (heapInit != initSize) {
            throw new IllegalStateException("Initial heap size mismatch. Expected: " + initSize + " MB, Actual: " + heapInit + " MB");
        }

        if (heapMax != maxSize) {
            throw new IllegalStateException("Maximum heap size mismatch. Expected: " + maxSize + " MB, Actual: " + heapMax + " MB");
        }

        // Optionally, retrieve and print non-heap memory usage
        MemoryUsage nonHeapMemoryUsage = memoryMXBean.getNonHeapMemoryUsage();
        long nonHeapInit = nonHeapMemoryUsage.getInit() / (1024 * 1024);
        long nonHeapMax = nonHeapMemoryUsage.getMax() / (1024 * 1024);

        System.out.println("Non-Heap Initial Size: " + nonHeapInit + " MB");
        System.out.println("Non-Heap Maximum Size: " + (nonHeapMax == -1 ? "Undefined" : nonHeapMax + " MB"));
    }
}

