public String okcolors(String input) {
    HashMap<String, String> colors = new HashMap<String, String>();
    colors.put("r", "red");
    colors.put("b", "blue");
    colors.put("g", "green");
    colors.put("y", "yellow");
    colors.put("o", "orange");

    String output = input;
    for (String key : colors.keySet()) {
        output = output.replaceAll(key+"(?=[A-Z])", colors.get(key));
    }
    return output;
}

