import java.util.*;

public class sol {

    public static void main(String[] args)

    {

        Scanner sc=new Scanner(System.in);

        int t=sc.nextInt();

        //sc.nextLine();

        while(t-->0){

            long n=sc.nextLong();

            long k=sc.nextLong();

            long b=sc.nextLong();

            long s=sc.nextLong();

            if(s/k<b){

                System.out.println(-1);

                continue;

            }

            if(((n-1)*(k-1))<s-(((b+1)*k)-1)){

                System.out.println(-1);

                continue;

            }

            if((b*k)<=s && k*(b+1)>s){

               int y=0;

               while(y<n-1){

                   System.out.print(0+" ");

                   y++;

               }

               System.out.println(s);

               continue;

            }

            long x=(k*(b+1))-1;

            System.out.print(x+" ");

            s=s-x;

            int c=0;

            while(c<n-2){

                if(s>=k-1){System.out.print(k-1+" ");s=s-(k-1);}

                else if(s>0){System.out.print(s+" ");s=0;}

                else System.out.print(0+" ");

             c++;

            }

            if(s>=k-1){System.out.print(k-1);s=s-(k-1);}

                else if(s>0){System.out.print(s);s=0;}

                else System.out.print(0);

             System.out.println();

    }

  }

}

import java.io.BufferedOutputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
 
public class PPMWriter {
 
    public void bitmapToPPM(File file, BasicBitmapStorage bitmap) throws IOException {
        file.delete();
 
        try (var os = new FileOutputStream(file, true);
             var bw = new BufferedOutputStream(os)) {
            var header = String.format("P6\n%d %d\n255\n",
                    bitmap.getWidth(), bitmap.getHeight());
 
            bw.write(header.getBytes(StandardCharsets.US_ASCII));
 
            for (var y = 0; y < bitmap.getHeight(); y++) {
                for (var x = 0; x < bitmap.getWidth(); x++) {
                    var pixel = bitmap.getPixel(x, y);
                    bw.write(pixel.getRed());
                    bw.write(pixel.getGreen());
                    bw.write(pixel.getBlue());
                }
            }
        }
    }
}

import java.io.DataInputStream;
import java.io.FileInputStream;
import java.io.IOException;

public class Handler {
    public static void main(String[] args) {
        String fileName = "PrimeNumbers.dat";
        long[] primes = readPrimesFromFile(fileName);

        int[] numbers = {10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000, 10000000000L};

        System.out.printf("%12s %10s\n", "Number", "Primes");
        System.out.println("------------------------");

        for (int i = 0; i < numbers.length; i++) {
            int count = countPrimes(primes, numbers[i]);
            System.out.printf("%12d %10d\n", numbers[i], count);
        }
    }

    public static long[] readPrimesFromFile(String fileName) {
        try (DataInputStream input = new DataInputStream(new FileInputStream(fileName))) {
            int size = input.readInt();
            long[] primes = new long[size];

            for (int i = 0; i < size; i++) {
                primes[i] = input.readLong();
            }

            return primes;
        } catch (IOException e) {
            e.printStackTrace();
        }

        return null;
    }

    public static int countPrimes(long[] primes, int n) {
        int count = 0;

        for (int i = 0; i < primes.length; i++) {
            if (primes[i] <= n) {
                count++;
            } else {
                break;
            }
        }

        return count;
    }
}

import java.util.Random;
 
public class Weasel {
    private static final String target = "METHINKS IT IS LIKE A WEASEL";
    private static final String tbl = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";
    private static final int CHOICE = tbl.length();
    private static final int MUTATE = 15;
    private static final int COPIES = 30;
    private static final Random rand = new Random();
 
    /* returns random integer from 0 to n - 1 */
    private static int irand(int n) {
        int r, rand_max = Integer.MAX_VALUE - (Integer.MAX_VALUE % n);
        while ((r = rand.nextInt()) >= rand_max);
        return r / (rand_max / n);
    }
 
    /* number of different chars between a and b */
    private static int unfitness(String a, String b) {
        int sum = 0;
        for (int i = 0; i < a.length(); i++)
            sum += (a.charAt(i)!= b.charAt(i))? 1 : 0;
        return sum;
    }
 
    /* each char of b has 1/MUTATE chance of differing from a */
    private static void mutate(String a, char[] b) {
        for (int i = 0; i < a.length(); i++)
            b[i] = (rand.nextInt(MUTATE) == 0)? tbl.charAt(irand(CHOICE)) : a.charAt(i);
    }
 
    public static void main(String[] args) {
        int best_i, unfit, best, iters = 0;
        char[] specimen = new char[COPIES][target.length()];
 
        /* init rand string */
        for (int i = 0; i < target.length(); i++)
            specimen[0][i] = tbl.charAt(irand(CHOICE));
 
        do {
            for (int i = 1; i < COPIES; i++)
                mutate(new String(specimen[0]), specimen[i]);
 
            /* find best fitting string */
            for (best_i = 0, best = Integer.MAX_VALUE; best_i < COPIES; best_i++) {
                unfit = unfitness(target, new String(specimen[best_i]));
                if (unfit < best) {
                    best = unfit;
                    best_i = best_i;
                }
            }
 
            if (best_i!= 0)
                specimen[0] = specimen[best_i];
            System.out.println("iter " + iters++ + ", score " + best + ": " + new String(specimen[0]));
        } while (best!= 0);
    }
}

