| +RegularPolygon(n: int, side: double, x: double, y: double)|
| +getN(): int                       |
| +setN(n: int): void                |
| +getSide(): double                 |
| +setSide(side: double): void       |
| +getX(): double                    |
| +setX(x: double): void             |
| +getY(): double                    |
