    static void ruffleSort(int[] a) {

        int n=a.length;//shuffle, then sort

        for (int i=0; i<n; i++) {

            int oi=random.nextInt(n), temp=a[oi];

            a[oi]=a[i]; a[i]=temp;

        }

        Arrays.sort(a);

    }

    private static void solve(Reader r) {

        int n = r.nextInt();

        int m = r.nextInt();

        int[] nums = new int[n];

        for (int i = 0; i < n; i++) {

            nums[i] = r.nextInt();

        }

        ruffleSort(nums);

        int ans = Integer.MAX_VALUE;

        int right = 0;

        int[] used = new int[m + 1];

        int count = 0;

        for (int left = 0; left < n; left++) {

            while (count < m && right < n) {

                for (Integer item : d[nums[right]]) {

                    if (item > m)

                        break;

                    if (used[item] == 0) count++;

                    used[item]++;

                }

                right++;

            }

            if (count != m) break;

            ans = Math.min(nums[right - 1] - nums[left], ans);

            for (Integer item : d[nums[left]]) {

                if (item > m)

                    break;

                used[item]--;

                if (used[item] == 0) count--;

            }

        }

        println(ans == Integer.MAX_VALUE ? -1 : ans);

    }

