public:
        int minTotalCost(vector<int>& nums1, vector<int>& nums2) {
            /*
            https://www.geeksforgeeks.org/minimum-cost-of-swap-elements/
            https://leetcode-cn.com/problems/minimum-cost-to-swap-elements-with-same-value/solution/fen-sui-wang-zhi-l-wei-zhet-liang-fa-by-leetcode/
            */
            sort(nums1.begin(), nums1.end());
            sort(nums1.begin(), nums1.end());
            vector<pair<int, int> > curNum;
            map<int, int> bintwo;
            for (auto item : nums1) {
                if (bintwo.find(item) != bintwo.end()) {
                    curNum.push_back({bintwo[item], item});
                } else {
                    bintwo[item] = item;
                }
            }
            map<int, int> query;
            for (auto item : nums2) {
                if (query.find(item) != query.end()) {
                    curNum.push_back({query[item], item});
                } else {
                    query[item] = item;
                }
            }
            vector<pair<int, int> >::iterator it;
            int sum, minCost = Integer.MAX_VALUE;
            for (it = curNum.begin(); it != curNum.end(); ++it) {
                if (it->second != it->first) {
                    sum = it->first + 1 + it->second + 1;
                    minCost = min(minCost, sum);
                }
            }
            if (minCost == Integer.MAX_VALUE) return -1;
            else return minCost;
        }
};

