class Sorter {
    long dfs(int i, List<List<Integer>> tree, char[] s, Map<Integer, Long> cache, int mask) {
        if (i > 0) {
            mask ^= 1 << (s[i] - 'a');
        }
        long last = cache.getOrDefault(mask, 0L);
        cache.put(mask, last + 1);
        long ans = last;
        for (int c = 0; c < 26; c++) {
            int k = mask ^ (1 << c);
            ans += cache.getOrDefault(k, 0L);
        }
        for (int j : tree.get(i)) {
            ans += dfs(j, tree, s, cache, mask);
        }
        return ans;
    }

    public long countPalindromePaths(List<Integer> parent, String _s) {
        char[] s = _s.toCharArray();
        List<List<Integer>> tree = new ArrayList<>(parent.size());
        for (int i = 0; i < parent.size(); i++) {
            tree.add(new ArrayList<>());
        }
        for (int i = 1; i < parent.size(); i++) {
            tree.get(parent.get(i)).add(i);
        }
        return dfs(0, tree, s, new HashMap<>(), 0);
    }
}

