            return false;
        }
        int target=sum[0]/2;
        boolean[] res={false};
        calSum(root,res,target);
        return res[0];
    }
    public int calSum(TreeNode curr,boolean[] res,int target){
        if(curr==null){
            return 0;
        }
        int l=calSum(curr.left,res,target);
        int r=calSum(curr.right,res,target);
        if(l+r+curr.val==target){
            res[0]=true;
        }
        return l+r+curr.val;
    }
    public void findSum(TreeNode curr,int[] sum){
        if(curr==null){
            return;
        }
        sum[0]=sum[0]+curr.val;
        findSum(curr.left,sum);
        findSum(curr.right,sum);
    }
}

