def ValidWordAbbr(words: [str], puzzles: [str]) -> [int]:
  def abbr(word: str) -> str:
    valid: collections.Counter = collections.Counter()

    for w in filter(lambda word1: word1 in word, words):
      valid[word[0:1]] += 1
      valid[word[-1]] += 1

    word = list(word)
    for i,w in enumerate(word):
      if int(valid[w] > 1) and len({w for w in word if w != w[0]}) == 1:
        word[i] = ''
      if word.count('') == 7:
        break

    return ''.join(word)

