class Builder {
    public List<Integer> selfDividingNumbers(int left, int right) {
        List<Integer> ll=new LinkedList<Integer>();
        for (int k=left;k<=right;k++)
        {
            int r=k%10;
            int j=k/10;
            boolean flag=true;
            if (r==0)
                continue;
            if (k%r!=0)
                continue;
            while (j>0)
            {
                r=j%10;
                j=j/10;
                if ((r==0)||(k%r!=0))
                {
                    flag=false;
                    break;
                }
            }
            if (flag)
            {
                ll.add(k);
            }
        }
        return ll;
    }
}

import java.util.Scanner;

public class NotHesaplama {

    // 'harfNotunaCevir' metodu, girilen sayisal notu harf notuna cevirir
    public static void harfNotunaCevir(int not) {
        // Not 90 veya daha yuksekse 'A' harf notu verilir
        if (not >= 90) {
            System.out.println("A");
        }
        // Not 80 veya daha yuksekse 'B' harf notu verilir
        else if (not >= 80) {
            System.out.println("B");
        }
        // Not 70 veya daha yuksekse 'C' harf notu verilir
        else if (not >= 70) {
            System.out.println("C");
        }
        // Not 60 veya daha yuksekse 'D' harf notu verilir
        else if (not >= 60) {
            System.out.println("D");
        }
        // Diger durumlar icin 'F' harf notu verilir
        else {
            System.out.println("F");
        }
    }

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullaniciya notunu girmesini iste
        System.out.print("Notunuzu girin: ");
        int not = scanner.nextInt();

        // 'harfNotunaCevir' metodu ile sayisal not harf notuna cevir
        harfNotunaCevir(not);

        // Scanner nesnesi kapat
        scanner.close();
    }
}

import org.junit.Assert;
import org.junit.Test;

/**
 * Unit tests for {@link UnderFileSystem}
 */
public final class UnderFileSystemTest {

  @Test
  public void parseTest() {
    Pair<String, String> result = UnderFileSystem.parse("/path");
    Assert.assertEquals(result.getFirst(), "/");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("file:///path");
    Assert.assertEquals(result.getFirst(), "/");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("tachyon://localhost:19998");
    Assert.assertEquals(result.getFirst(), "tachyon://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/");

    result = UnderFileSystem.parse("tachyon://localhost:19998/");
    Assert.assertEquals(result.getFirst(), "tachyon://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/");

    result = UnderFileSystem.parse("tachyon://localhost:19998/path");
    Assert.assertEquals(result.getFirst(), "tachyon://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("tachyon-ft://localhost:19998/path");
    Assert.assertEquals(result.getFirst(), "tachyon-ft://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("hdfs://localhost:19998/path");
    Assert.assertEquals(result.getFirst(), "hdfs://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("s3://localhost:19998/path");
    Assert.assertEquals(result.getFirst(), "s3://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/path");

    result = UnderFileSystem.parse("s3n://localhost:19998/path");
    Assert.assertEquals(result.getFirst(), "s3n://localhost:19998");
    Assert.assertEquals(result.getSecond(), "/path");

    Assert.assertEquals(UnderFileSystem.parse(null), null);
    Assert.assertEquals(UnderFileSystem.parse(""), null);
    Assert.assertEquals(UnderFileSystem.parse("anythingElse"), null);
  }
}

import java.util.Scanner; // Kullanicidan veri girisi almak icin Scanner sinifini ice aktarir.

public class AsalSayiMi { // Ana sinif

    public static void main(String[] args) {

        // Kullanicidan bir sayi almak icin Scanner nesnesi olusturur.
        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir sayi girmesini ister. Bu sayi, asal olup olmadigini kontrol edilir.
        System.out.println("Bir sayi giriniz:");
        int sayi = scanner.nextInt(); // Kullanicinin girdigi sayiyi okur ve 'sayi' degiskenine atar.

        // Asal olup olmadigini kontrol etmek icin 'asal' adinda bir boolean degiskeni tanimlanir.
        // Baslangicta sayinin asal oldugu varsayilir.
        boolean asal = true;

        // 'for' dongusu, sayinin asal olup olmadigini kontrol etmek icin kullanilir.
        // Dongu 2'den baslayarak (cunku asal sayi 1 ve kendisi disinda tam boleni olmayan sayidir)
        // girilen sayiya kadar devam eder.
        for(int i = 2; i < sayi; i++) {

            // Eger sayi, 2 ile 'sayi' arasindaki herhangi bir sayiya tam bolunurse, asal degildir.
            // Tam bolunebilme kontrolu icin sayi % i == 0 ifadesi kullanilir.
            if(sayi % i == 0) {

                // Eger sayinin bir boleni bulunursa, ekrana "sayi asal degil" yazdirilir.
                System.out.println("Sayi asal degil.");

                // Sayinin asal olmadigini belirtmek icin 'asal' degiskeni false yapilir.
                asal = false;

                // Ilk boleni bulduktan sonra kontrol etmeye gerek olmadigi icin donguden cikilir (break).
                break;
            }
        }

        // Eger dongu tamamlandiysa ve hicbir bolen bulunmadiysa (asal degiskeni hala true ise),
        // sayinin asal oldugu kabul edilir ve ekrana "sayi asal" yazdirilir.
        if(asal == true) {
            System.out.println("Sayi asal.");
        }

        // Scanner nesnesini kapatir. Kaynak yonetimi acisindan onemli bir adimdir.
        scanner.close();
    }
}

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.JsonInclude.Include;

@JsonInclude(Include.NON_NULL)
public class OperationResult {

    public enum OPERATION_RESULT_TYPE {
        success, warning, failure, confirm
    }

    private String type;
    private String message;
    private Object userdata;

    public OperationResult() {
    }

    public OperationResult(String type, String message) {
        this(type, message, null);
    }

    public OperationResult(String type, String message, Object userdata) {
        this.type = type;
        this.message = message;
        this.userdata = userdata;
    }

    public static OperationResult buildSuccessResult() {
        return new OperationResult(OPERATION_RESULT_TYPE.success.name(), null, null);
    }

    public static OperationResult buildSuccessResult(String message) {
        return new OperationResult(OPERATION_RESULT_TYPE.success.name(), message, null);
    }

    public static OperationResult buildSuccessResult(String message, Object userdata) {
        return new OperationResult(OPERATION_RESULT_TYPE.success.name(), message, userdata);
    }

    public static OperationResult buildWarningResult(String message) {
        return new OperationResult(OPERATION_RESULT_TYPE.warning.name(), message, null);
    }

    public static OperationResult buildWarningResult(String message, Object userdata) {
        return new OperationResult(OPERATION_RESULT_TYPE.warning.name(), message, userdata);
    }

    public static OperationResult buildFailureResult(String message) {
        return new OperationResult(OPERATION_RESULT_TYPE.failure.name(), message, null);
    }

    public static OperationResult buildFailureResult(String message, Object userdata) {
        return new OperationResult(OPERATION_RESULT_TYPE.failure.name(), message, userdata);
    }

    public static OperationResult buildConfirmResult(String message) {
        return new OperationResult(OPERATION_RESULT_TYPE.confirm.name(), message, null);
    }

    public static OperationResult buildConfirmResult(String message, Object userdata) {
        return new OperationResult(OPERATION_RESULT_TYPE.confirm.name(), message, userdata);
    }

    public String getType() {
        return type;
    }

    public void setType(String type) {
        this.type = type;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public Object getUserdata() {
        return userdata;
    }

import io.netty.buffer.ByteBuf;
import se.sics.gvod.common.VodAddress;

public class DisconnectMsg {

    public static class Request extends BasicMsg.Request {
        private final VodAddress peer;
        private final int ref;

        public Request(VodAddress src, VodAddress peer, int ref) {
            super(src);
            this.peer = peer;
            this.ref = ref;
        }

        @Override
        public int getOpcode() {
            return DISCONNECT_REQUEST;
        }

        @Override
        public int getSize() {
            return super.getSize() + peer.size() + 4;
        }

        @Override
        public void toByteArray(ByteBuf buf) {
            super.toByteArray(buf);
            peer.toByteArray(buf);
            buf.writeInt(ref);
        }

        public VodAddress getPeer() {
            return peer;
        }

        public int getRef() {
            return ref;
        }

        @Override
        public Request copy() {
            return new Request(src, peer, ref);
        }
    }

    public static class Response extends BasicMsg.Response {
        private final VodAddress peer;
        private final int ref;
        private final boolean success;

        public Response(VodAddress src, VodAddress peer, int ref, boolean success) {
            super(src);
            this.peer = peer;
            this.ref = ref;
            this.success = success;
        }

        @Override
        public int getOpcode() {
            return DISCONNECT_RESPONSE;
        }

        @Override
        public int getSize() {
            return super.getSize() + peer.size() + 8;
        }

        @Override
        public void toByteArray(ByteBuf buf) {
            super.toByteArray(buf);
            peer.toByteArray(buf);
            buf.writeInt(ref);
            buf.writeBoolean(success);
        }

        public VodAddress getPeer() {
            return peer;
        }

        public int getRef() {
            return ref;
        }

        public boolean isSuccess() {
            return success;
        }

        @Override
        public Response copy() {
            return new Response(src, peer, ref, success);
        }
    }

    public static class RequestTimeout implements Timeout {
        private final Request request;
        private final TimeoutId timeoutId;

        public RequestTimeout(Request request, TimeoutId timeoutId) {
            this.request = request;
            this.timeoutId = timeoutId;
        }

        @Override
        public Request getRequest() {
            return request;
        }

import java.util.ArrayList;
...//class definition, etc.
public static void genPyrN(int rows){
    if(rows < 0) return;
    //save the last row here
    ArrayList<Integer> last = new ArrayList<Integer>();
    last.add(1);
    System.out.println(last);
    for(int i= 1;i <= rows;++i){
        //work on the next row
        ArrayList<Integer> thisRow= new ArrayList<Integer>();
        thisRow.add(last.get(0)); //beginning
        for(int j= 1;j < i;++j){//loop the number of elements in this row
            //sum from the last row
            thisRow.add(last.get(j - 1) + last.get(j));
        }
        thisRow.add(last.get(0)); //end
        last= thisRow;//save this row
        System.out.println(thisRow);
    }
}

import java.io.File;
import java.util.Map;
import java.util.Scanner;
import java.util.Set;
import java.util.TreeMap;

public class Reader {
    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println(
                    "Usage: java Reader ch_21/exercise21_08/test.txt");
            System.exit(1);
        }

        String filePath = args[0];
        TreeMap<String, Integer> treeMap = new TreeMap<String, Integer>();

        try {
            File file = new File(filePath);
            if (!file.exists() || !file.isFile()) {
                System.out.println("Error: " + file.getCanonicalPath() + " does not exist or is not a file.");
                System.exit(2);
            }

            Scanner input = new Scanner(file);

            while (input.hasNext()) {
                String line = input.nextLine();
                // Split input file contents by delimiters
                String[] words = line.split("[ @!~{}\\[\\]$#^&*\n\t\r.,;?'\")(]");

                for (int i = 0; i < words.length; i++) {
                    // Check for uppercase letters in words and make them lowercase (case-insensitive)
                    if (words[i].trim().length() > 0 && words[i].trim().matches("[A-Z|a-z]+")) {
                        String key = words[i].toLowerCase();
                        if (treeMap.get(key) != null) {
                            int count = treeMap.get(key);
                            count++;
                            treeMap.put(key, count);
                        } else {
                            treeMap.put(key, 1);
                        }
                    }
                }
            }
        } catch (Exception ex) {
            ex.printStackTrace();
        }

        // Get an entry set for the tree map
        Set<Map.Entry<String, Integer>> entrySet = treeMap.entrySet();

        // Display words in alphabetical order
        System.out.println("\nDisplay the output in alphabetical order of words, with each word preceded by\n" +
                "its occurrence count");
        for (Map.Entry<String, Integer> entry : entrySet)
            System.out.println(entry.getValue() + "\t" + entry.getKey());
    }
}

