import java.util.Arrays;

public class MakeChange {
    public static int makeChange(int[] coins, int cents) {
        int size = cents + 1;
        int[] ways = new int[size];
        ways[0] = 1;
        for (int coin : coins) {
            for (int amount = coin; amount < size; amount++) {
                ways[amount] += ways[amount - coin];
            }
        }
        return ways[cents];
    }

    public static void main(String[] args) {
        System.out.println(makeChange(new int[]{1, 5, 10, 25}, 100));
        System.out.println(makeChange(new int[]{1, 5, 10, 25, 50, 100}, 100_000));
    }
}

