import java.util.Arrays;

public final class MyStringBuilder2 {

    char[] values;

    public MyStringBuilder2() {
        this("".toCharArray());
    }

    public MyStringBuilder2(char[] chars) {
        this.values = chars;
    }

    public MyStringBuilder2(String s) {
        this(s.toCharArray());
    }

    public MyStringBuilder2 insert(int offset, MyStringBuilder2 s) {
        char[] nuVals = new char[s.values.length + offset];
        System.arraycopy(this.values, 0, nuVals, 0, offset);
        System.arraycopy(s.values, 0, nuVals, offset, s.values.length);
        this.values = nuVals;

        return this;
    }

    public MyStringBuilder2 reverse() {
        char[] nuVals = new char[values.length];
        for (int i = values.length - 1, j = 0; i >= 0; i--, j++) {
            nuVals[j] = values[i];
        }
        this.values = nuVals;
        return this;

    }

    public MyStringBuilder2 substring(int begin) {
        String s = "";
        for (int i = begin; i < values.length; i++) {
            s += values[i];
        }
        return new MyStringBuilder2(s);

    }

    public MyStringBuilder2 toUpperCase() {
        String s = String.valueOf(values);
        String UC = s.toUpperCase();
        values = Arrays.copyOf(UC.toCharArray(), values.length);
        return this;
    }

    @Override
    public String toString() {
        return String.valueOf(values);
    }
}

import com.jcwhatever.nucleus.Nucleus;
import com.jcwhatever.nucleus.managed.scripting.IScriptManager;
import com.jcwhatever.nucleus.managed.scripting.NamedLocation;
import com.jcwhatever.nucleus.utils.PreCon;
import org.bukkit.Location;

import java.util.Collection;
import java.util.HashSet;
import java.util.Set;

public class SAPI_Locations implements IDisposable {

    private boolean _isDisposed;

    @Override
    public void dispose() {
        if (_isDisposed) return;
        _isDisposed = true;
        // Perform any necessary cleanup here
    }

    @Override
    public boolean isDisposed() {
        return _isDisposed;
    }

    /**
     * Fetches a location by its name.
     *
     * @param name The name of the location.
     * @return The Location object if found, otherwise null.
     */
    public Location get(String name) {
        PreCon.notNull(name);
        checkDisposed();

        NamedLocation namedLocation = getScriptManager().getLocation(name);
        return namedLocation != null ? namedLocation.getLocation() : null;
    }

    /**
     * Retrieves all stored named locations into a default collection.
     *
     * @return A set of Location objects.
     */
    public Set<Location> getScriptLocations() {
        checkDisposed();

        Collection<NamedLocation> namedLocations = getScriptManager().getLocations();
        Set<Location> locations = new HashSet<>();
        for (NamedLocation namedLocation : namedLocations) {
            locations.add(namedLocation.getLocation());
        }
        return locations;
    }

    /**
     * Retrieves all stored named locations into a user-provided collection.
     *
     * @param output The collection to store the locations in.
     * @param <T>    The type of the collection.
     * @return The provided collection containing Location objects.
     */
    public <T extends Collection<Location>> T getScriptLocations(T output) {
        PreCon.notNull(output);
        checkDisposed();

        Collection<NamedLocation> namedLocations = getScriptManager().getLocations();
        for (NamedLocation namedLocation : namedLocations) {
            output.add(namedLocation.getLocation());
        }
        return output;
    }

    private IScriptManager getScriptManager() {
        return Nucleus.getScriptManager();
    }

    private void checkDisposed() {
        if (_isDisposed) {
            throw new IllegalStateException("Object has been disposed.");
        }
    }
}

