public class Program {
    public static void main(String[] args) {
        Arrays.stream(new String[]{
                "127.0.0.1",
                "127.0.0.1:80",
                "::1",
                "[::1]:80",
                "2605:2700:0:3::4713:93e3",
                "[2605:2700:0:3::4713:93e3]:80",
        }).map(Program::parseAddr).forEach(System.out::println);
    }
 
    private static String parseAddr(String s) {
        return Optional.ofNullable(parseInetAddr(s))
               .map(addr -> String.format("address: %s, port: %s, hex: %s (IPv%s)",
                        addr.getAddress(), addr.getPort(), addr.getHex(), addr.getIpv()))
               .orElseGet(() -> String.format("%s not a valid address", s));
    }
 
    private static InetAddr parseInetAddr(String s) {
        try {
            InetAddress addr = InetAddress.getByName(s);
            return new InetAddr(addr, null);
        } catch (UnknownHostException e) {
            try {
                InetSocketAddress sock = new InetSocketAddress(s);
                return new InetAddr(sock.getAddress(), sock.getPort());
            } catch (Exception e1) {
                return null;
            }
        }
    }
 
    private static class InetAddr {
        private final InetAddress address;
        private final Integer port;
 
        public InetAddr(InetAddress address, Integer port) {
            this.address = address;
            this.port = port;
        }
 
        public InetAddress getAddress() {
            return address;
        }
 
        public Integer getPort() {
            return port;
        }
 
        public String getHex() {
            return Long.toHexString(address.getAddress().length == 4?
                    bytesToLong(address.getAddress()) :
                    bytesToLong(address.getAddress(), 0, 8) + bytesToLong(address.getAddress(), 8, 8));
        }
 
        public String getIpv() {
            return address.getAddress().length == 4? "4" : "6";
        }
 
        private long bytesToLong(byte[] bytes) {
            return bytesToLong(bytes, 0, bytes.length);
        }
 
        private long bytesToLong(byte[] bytes, int start, int end) {
            return Arrays.stream(bytes, start, end)
                   .map(b -> (long) b & 0xff)

class Generator {
    int arr[];
    int length;
    int quantity[];
    int dp[][];
    int m;
    public boolean canDistribute(int[] nums, int[] q) {
        HashMap<Integer,Integer> map=new HashMap<>();
        quantity=q;
        for(int i:nums)
        {
            map.put(i,map.getOrDefault(i,0)+1);
        }
        m=quantity.length;
        arr=new int[map.size()];
        int cnt=0;
        for(Map.Entry<Integer,Integer> entry:map.entrySet())
        {
            int value=(entry.getValue());
            arr[cnt++]=value;
        }
        length=arr.length;
        dp=new int[length][1<<m];
        return distribute(0,(1<<quantity.length)-1)==1;
    }
    public int distribute(int pos,int mask)
    {
        if(pos==length||mask==0)
        {
            if(mask==0)
                return 1;
            return 2;
        }
        if(dp[pos][mask]!=0)
        {
            return dp[pos][mask];
        }
        ArrayList<Integer> p=new ArrayList<>();
        ArrayList<Integer> ap=new ArrayList<>();
        for(int i=0;i<m;i++)
        {
            if((mask&(1<<i))!=0)
            {
                p.add(quantity[i]);
                ap.add(i);
            }
        }
        boolean poss=false;
        poss=poss||(distribute(pos+1,mask)==1);
        for(int i=0;i<(1<<p.size());i++)
        {

            int sum=0;
            int nm=mask;
            for(int j=0;j<p.size();j++)
            {
                if((i&(1<<j))!=0)
                {
                    sum+=p.get(j);
                    if(sum>arr[pos])
                    {
                        break;
                    }
                    nm=(nm&~(1<<ap.get(j)));
                }
            }
            if(arr[pos]>=sum)
            {
                poss=poss||(distribute(pos+1,nm)==1);
                if(poss)
                {
                    dp[pos][mask]=1;
                    return 1;
                }
            }
        }
        if(poss)
        {
            dp[pos][mask]=1;
            return 1;
        }
        dp[pos][mask]=2;
        return 2;
    }
}

