import java.util.Scanner;

public class CharacterCount {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a list of characters: ");
        String input = scanner.nextLine();
        char[] chars = input.toCharArray();
        System.out.print("Enter a character to count: ");
        char ch = scanner.nextLine().charAt(0);
        int count = count(chars, ch);
        System.out.printf("The character %c occurs %d times in the list.%n", ch, count);
    }

    public static int count(char[] chars, char ch) {
        return countHelper(chars, ch, chars.length - 1);
    }

    public static int countHelper(char[] chars, char ch, int high) {
        if (high < 0) {
            return 0;
        } else {
            int count = countHelper(chars, ch, high - 1);
            if (chars[high] == ch) {
                count++;
            }
            return count;
        }
    }
}

import org.opencv.core.Mat;
import org.opencv.imgproc.Imgproc;
import org.simpleframework.xml.Element;
import org.simpleframework.xml.Root;

@Root(name = "ThresholdAdaptive")
public class ThresholdAdaptive extends CvStage {
    public enum AdaptiveMethod {
        Mean, Gaussian
    }

    @Element(required = false)
    protected AdaptiveMethod adaptiveMethod = AdaptiveMethod.Mean;

    @Element(required = false)
    protected boolean invert = false;

    @Element(required = false)
    protected int blockSize = 51;

    @Element(required = false)
    protected double cParm = 10;

    public ThresholdAdaptive() {
        super();
        name = "Adaptive Threshold";
    }

    private int getCode(AdaptiveMethod method) {
        if (method == AdaptiveMethod.Mean)
        {
            return Imgproc.ADAPTIVE_THRESH_MEAN_C;
        }
        else
        {
            return Imgproc.ADAPTIVE_THRESH_GAUSSIAN_C;
        }
    }

    @Override
    public Mat process(Mat matIn, CvPipeline pipeline) {
        Mat matOut = new Mat();

        int type = invert ? Imgproc.THRESH_BINARY_INV : Imgproc.THRESH_BINARY;

        int blockSize = Math.max(3, this.blockSize);
        if (blockSize % 2 == 0) {
            blockSize++;
        }

        Imgproc.adaptiveThreshold(
                matIn,
                matOut,
                255,
                getCode(adaptiveMethod),
                type,
                blockSize,
                cParm);

        return matOut;
    }
}

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.io.Serializable;

public class CenterLayout implements LayoutManager, Serializable {
    private static final long serialVersionUID = 469319532333015042L;

    public Dimension preferredLayoutSize(Container parent) {
        Dimension dimension;
        synchronized (parent.getTreeLock()) {
            Insets insets = parent.getInsets();
            if (parent.getComponentCount() > 0) {
                Dimension d = parent.getComponent(0).getPreferredSize();
                dimension = new Dimension((((int) d.getWidth()) + insets.left) + insets.right, (((int) d.getHeight()) + insets.top) + insets.bottom);
            } else {
                dimension = new Dimension(insets.left + insets.right, insets.top + insets.bottom);
            }
        }
        return dimension;
    }

    public Dimension minimumLayoutSize(Container parent) {
        Dimension dimension;
        synchronized (parent.getTreeLock()) {
            Insets insets = parent.getInsets();
            if (parent.getComponentCount() > 0) {
                Dimension d = parent.getComponent(0).getMinimumSize();
                dimension = new Dimension((d.width + insets.left) + insets.right, (d.height + insets.top) + insets.bottom);
            } else {
                dimension = new Dimension(insets.left + insets.right, insets.top + insets.bottom);
            }
        }
        return dimension;
    }

    public void layoutContainer(Container parent) {
        synchronized (parent.getTreeLock()) {
            if (parent.getComponentCount() > 0) {
                Insets insets = parent.getInsets();
                Dimension parentSize = parent.getSize();
                Component component = parent.getComponent(0);
                Dimension componentSize = component.getPreferredSize();
                component.setBounds(insets.left + Math.max((((parentSize.width - insets.left) - insets.right) - componentSize.width) / 2, 0), insets.top + Math.max((((parentSize.height - insets.top) - insets.bottom) - componentSize.height) / 2, 0), componentSize.width, componentSize.height);
            }
        }
    }

    public void addLayoutComponent(Component comp) {
    }

    public void removeLayoutComponent(Component comp) {
    }

    public void addLayoutComponent(String name, Component comp) {
    }

    public void removeLayoutComponent(String name, Component comp) {
    }
}

