import java.util.ArrayList;
 
public class Josephus {
    public static int execute(int n, int k){
        int killIdx = 0;
        ArrayList<Integer> prisoners = new ArrayList<Integer>(n);
        for(int i = 0;i < n;i++){
            prisoners.add(i);
        }
        System.out.println("Prisoners executed in order:");
        while(prisoners.size() > 1){
            killIdx = (killIdx + k - 1) % prisoners.size();
            System.out.print(prisoners.get(killIdx) + " ");
            prisoners.remove(killIdx);
        }
        System.out.println();
        return prisoners.get(0);
    }
 
    public static ArrayList<Integer> executeAllButM(int n, int k, int m){
        int killIdx = 0;
        ArrayList<Integer> prisoners = new ArrayList<Integer>(n);
        for(int i = 0;i < n;i++){
            prisoners.add(i);
        }
        System.out.println("Prisoners executed in order:");
        while(prisoners.size() > m){
            killIdx = (killIdx + k - 1) % prisoners.size();
            System.out.print(prisoners.get(killIdx) + " ");
            prisoners.remove(killIdx);
        }
        System.out.println();
        return prisoners;
    }
 
    public static void main(String[] args){
        System.out.println("Survivor: " + execute(41, 3));
        System.out.println("Survivors: " + executeAllButM(41, 3, 3));
    }
}

import java.io.DataOutputStream;
import java.io.IOException;

import org.web3d.vrml.lang.FieldConstants;
import org.web3d.vrml.nodes.VRMLNodeType;
import org.web3d.vrml.export.BinaryFieldEncoder;

/**
 * Utility class for compressing numerical field data in VRML export.
 */
public class RangeCompressor {

    private CompressionTools compressionTools = new CompressionTools();

    /**
     * Compress an integer array.
     *
     * @param dos The output stream to write the compressed data to.
     * @param fieldType The field type as defined in VRML.
     * @param data The integer data to compress.
     * @throws IOException If an I/O error occurs.
     */
    public void compress(DataOutputStream dos, int fieldType, int[] data) throws IOException {
        compressionTools.rangeCompress(dos, data);
    }

    /**
     * Compress a float array.
     *
     * @param dos The output stream to write the compressed data to.
     * @param fieldType The field type as defined in VRML.
     * @param data The float data to compress.
     * @throws IOException If an I/O error occurs.
     */
    public void compress(DataOutputStream dos, int fieldType, float[] data) throws IOException {
        switch (fieldType) {
            case FieldConstants.SFCOLOR:
            case FieldConstants.MFCOLOR:
            case FieldConstants.SFVEC2F:
            case FieldConstants.MFVEC2F:
            case FieldConstants.SFVEC3F:
            case FieldConstants.MFVEC3F:
            case FieldConstants.SFVEC4F:
            case FieldConstants.MFVEC4F:
            case FieldConstants.SFROTATION:
            case FieldConstants.MFROTATION:
                for (float value : data) {
                    dos.writeFloat(value);
                }
                break;
            default:
                compressionTools.compressFloats(dos, data);
                break;
        }
    }

    /**
     * Sets the compression tools.
     * @param compressionTools the compression tools
     */
    public void setCompressionTools(CompressionTools compressionTools){
        this.compressionTools = compressionTools;
    }
}

