import org.apache.flink.api.java.functions.FlatMapFunction;
import org.apache.flink.api.java.tuple.Tuple3;
import org.apache.flink.util.Collector;
import java.util.HashMap;
import java.util.ArrayList;
import java.util.List;

public class JoinTask implements FlatMapFunction<Tuple3<String, String, Double>, Tuple3<String, Double, Double>> {

    private HashMap<String, List<Double>> gradeHashMap = new HashMap<>();
    private HashMap<String, List<Double>> salaryHashMap = new HashMap<>();

    @Override
    public void flatMap(Tuple3<String, String, Double> input, Collector<Tuple3<String, Double, Double>> out) {
        String streamId = input.f0;
        String name = input.f1;
        Double value = input.f2;

        if ("grade".equals(streamId)) {
            handleGrade(name, value, out);
        } else {
            handleSalary(name, value, out);
        }
    }

    private void handleGrade(String name, Double grade, Collector<Tuple3<String, Double, Double>> out) {
        if (salaryHashMap.containsKey(name)) {
            for (Double salary : salaryHashMap.get(name)) {
                out.collect(new Tuple3<>(name, grade, salary));
            }
        }
        if (!gradeHashMap.containsKey(name)) {
            gradeHashMap.put(name, new ArrayList<>());
        }
        gradeHashMap.get(name).add(grade);
    }

    private void handleSalary(String name, Double salary, Collector<Tuple3<String, Double, Double>> out) {
        if (gradeHashMap.containsKey(name)) {
            for (Double grade : gradeHashMap.get(name)) {
                out.collect(new Tuple3<>(name, grade, salary));
            }
        }
        if (!salaryHashMap.containsKey(name)) {
            salaryHashMap.put(name, new ArrayList<>());
        }
        salaryHashMap.get(name).add(salary);
    }
}

import org.onosproject.xosclient.api.XosAccess;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import javax.ws.rs.client.Client;
import javax.ws.rs.client.ClientBuilder;
import javax.ws.rs.client.Invocation;
import javax.ws.rs.client.WebTarget;
import javax.ws.rs.core.Response;

import static com.google.common.net.MediaType.JSON_UTF_8;
import static java.net.HttpURLConnection.HTTP_OK;

/**
 * XOS common REST API implementation.
 */
public class XosApi {

    private final Logger log = LoggerFactory.getLogger(getClass());

    protected static final String EMPTY_STRING = "";
    protected static final String EMPTY_JSON_STRING = "{}";

    protected final String baseUrl;
    protected final XosAccess access;
    protected final Client client;

    /**
     * Default constructor.
     *
     * @param baseUrl base url of this api
     * @param xosAccess xos access
     */
    public XosApi(String baseUrl, XosAccess xosAccess) {
        this.baseUrl = baseUrl;
        this.access = xosAccess;
        this.client = ClientBuilder.newClient();
    }

    /**
     * Returns the access of this api.
     *
     * @return xos access
     */
    public XosAccess access() {
        return this.access;
    }

    /**
     * Returns the base url of this api.
     *
     * @return base url
     */
    public String baseUrl() {
        return this.baseUrl;
    }

    /**
     * Returns response of the REST get operation with a given additional path.
     *
     * @param path path or null
     * @return response json string
     */
    public String restGet(String path) {
        WebTarget wt = client.target(access.endpoint() + baseUrl).path(path);
        Invocation.Builder builder = wt.request(JSON_UTF_8.toString());
        try {
            Response response = builder.get();
            if (response.getStatus() != HTTP_OK) {
                log.warn("Failed to get resource {}", access.endpoint() + baseUrl + path);
                return EMPTY_JSON_STRING;
            }
        } catch (javax.ws.rs.ProcessingException e) {
            return EMPTY_JSON_STRING;
        }
        return builder.get(String.class);
    }
}

public static double[] linearEquation(double[][] a, double[] b) {
    double determinant = a[0][0] * a[1][1] - a[0][1] * a[1][0];
    if (determinant == 0) {
        System.out.println("The equation has no solution.");
        return null;
    } else {
        double x = (b[0] * a[1][1] - b[1] * a[0][1]) / determinant;
        double y = (b[1] * a[0][0] - b[0] * a[1][0]) / determinant;
        return new double[] {x, y};
    }
}   import java.util.Scanner;

public class LinearEquationTest {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a00, a01, a10, a11, b0, b1: ");
        double[][] a = {{input.nextDouble(), input.nextDouble()},
                        {input.nextDouble(), input.nextDouble()}};
        double[] b = {input.nextDouble(), input.nextDouble()};

        double[] solution = linearEquation(a, b);
        if (solution != null) {
            System.out.printf("x = %f, y = %f\n", solution[0], solution[1]);
        }
    }
}

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

/**
 * Demonstrates line-based text I/O with the buffered reader/writer pair:
 * reads an existing text file line by line and prints it, then produces
 * a fresh output file with a couple of sample lines.
 */
public class MetinDosyasiOkuma {

    private static final String KAYNAK = "girdi.txt";
    private static final String HEDEF = "cikti.txt";

    public static void main(String[] args) {
        kaynakDosyayiEkraniBas();
        hedefDosyayiOlustur();
    }

    /** girdi.txt dosyasini satir satir okuyup konsola yansitir. */
    private static void kaynakDosyayiEkraniBas() {
        try (BufferedReader giris = new BufferedReader(new FileReader(KAYNAK))) {
            String mevcutSatir;
            while ((mevcutSatir = giris.readLine()) != null) {
                System.out.println(mevcutSatir);
            }
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }

    /** cikti.txt dosyasina iki ornek satir yazar. */
    private static void hedefDosyayiOlustur() {
        try (BufferedWriter cikis = new BufferedWriter(new FileWriter(HEDEF))) {
            cikis.write("Bu bir metin satiridir.");
            cikis.newLine();
            cikis.write("Bu da baska bir metin satiridir.");
        } catch (IOException hata) {
            hata.printStackTrace();
        }
    }
}

import crafttweaker.CraftTweakerAPI;
import crafttweaker.annotations.ZenRegister;
import crafttweaker.api.item.IItemStack;
import crafttweaker.api.item.IIngredient;
import stanhebben.zenscript.annotations.ZenClass;
import stanhebben.zenscript.annotations.ZenMethod;
import techreborn.api.recipe.AlloySmelterRecipe;
import techreborn.api.recipe.RecipeHandler;

@ZenRegister
@ZenClass("mods.techreborn.AlloySmelter")
public class CTAlloySmelter {

    @ZenMethod
    public static void addRecipe(IItemStack output, IIngredient input1, IIngredient input2, int ticks, int euPerTick) {
        if (output == null || input1 == null || input2 == null) {
            CraftTweakerAPI.logError("Invalid parameters provided for Alloy Smelter recipe.");
            return;
        }
        RecipeHandler.addRecipe(new AlloySmelterRecipe(input1.toStack(), input2.toStack(), output.toStack(), ticks, euPerTick));
    }

    @ZenMethod
    public static void removeInputRecipe(IIngredient input) {
        if (input == null) {
            CraftTweakerAPI.logError("Invalid input provided for removing Alloy Smelter recipe.");
            return;
        }
        RecipeHandler.getAlloySmelterRecipes().removeIf(recipe -> recipe.getInput1().matches(input) || recipe.getInput2().matches(input));
    }

    @ZenMethod
    public static void removeRecipe(IItemStack output) {
        if (output == null) {
            CraftTweakerAPI.logError("Invalid output provided for removing Alloy Smelter recipe.");
            return;
        }
        RecipeHandler.getAlloySmelterRecipes().removeIf(recipe -> recipe.getOutput().matches(output));
    }

    @ZenMethod
    public static void removeAll() {
        RecipeHandler.getAlloySmelterRecipes().clear();
        CraftTweakerAPI.logInfo("All Alloy Smelter recipes have been removed.");
    }
}

