        // Keep the context running for some time to simulate testing
        Thread.sleep(10000);

        // Stop the context
        context.stop();
    }
}

/*
 * Reverses an int array in place and reports its smallest value.
 */
public class DiziyiTersCevirme {

    public static void main(String[] args) {
        int[] sayilar = {5, 2, 8, 1, 9, 4, 7};

        cevir(sayilar);

        System.out.println("Ters Cevrilmis Dizi Elemanlari:");
        goster(sayilar);

        int kucuk = enKucuguBul(sayilar);
        System.out.println("\nDizideki Minimum Eleman: " + kucuk);
    }

    public static void cevir(int[] sayilar) {
        int sol = 0;
        int sag = sayilar.length - 1;

        while (sol < sag) {
            int gecici = sayilar[sol];
            sayilar[sol] = sayilar[sag];
            sayilar[sag] = gecici;
            sol++;
            sag--;
        }
    }

    public static void goster(int[] sayilar) {
        for (int deger : sayilar) {
            System.out.print(deger + " ");
        }
        System.out.println();
    }

    public static int enKucuguBul(int[] sayilar) {
        int enKucuk = sayilar[0];
        for (int i = 1; i < sayilar.length; i++) {
            if (sayilar[i] < enKucuk) {
                enKucuk = sayilar[i];
            }
        }
        return enKucuk;
    }
}

class Order {
    long mod = (long) (1e9 + 7);
    public int maximumScore(List<Integer> nums, int k) {

        int len = nums.size();
        int[] arr = new int[len];
        for (int i = 0; i < len; i++) {
            int x = nums.get(i);
            if (x == 1){
                continue;
            }
            HashSet<Integer> set = new HashSet<>();

            for (int j = 2; j * j <= x; j++) {
                while (x % j == 0){
                    x /= j;
                    set.add(j);
                }
            }

            if (x > 1){
                set.add(x);
            }

            arr[i] = set.size();

//            System.out.println(nums.get(i) + " " + arr[i]);
        }

        int[] preLessThanMe = new int[len];
        //要找到值 严格小于 当前位置的数
        LinkedList<Integer> list = new LinkedList<>();
        for (int i = 0; i < len; i++) {
            while (!list.isEmpty() && arr[list.getLast()] < arr[i]){
                list.removeLast();
            }

            if (list.isEmpty()){
                preLessThanMe[i] = 0;
            }else {
                preLessThanMe[i] = list.getLast() + 1;
            }

            list.addLast(i);
        }

        int[] afterBiggerOrEqual = new int[len];
        //要找到值 严格小于 当前位置的数
        list = new LinkedList<>();
        for (int i = len - 1; i >= 0; i--) {
            while (!list.isEmpty() && arr[list.getLast()] <= arr[i]){
                list.removeLast();
            }

            if (list.isEmpty()){
                afterBiggerOrEqual[i] = len - 1;
            }else {
                afterBiggerOrEqual[i] = list.getLast() - 1;
            }

            list.addLast(i);
        }

        PriorityQueue<Integer> queueIdx = new PriorityQueue<>(new Comparator<Integer>() {
            @Override
            public int compare(Integer o1, Integer o2) {
                if (nums.get(o2) - nums.get(o1) == 0){
                    return o2 - o1;
                }
                return nums.get(o2) - nums.get(o1);
            };
        });

        for (int i = 0; i < len; i++) {
            queueIdx.add(i);
        }

        long ans = 1;

        while (k > 0){
            int idx = queueIdx.poll();
            int left = idx - preLessThanMe[idx];
            int right = afterBiggerOrEqual[idx] - idx;
            long kind = (long) (left + 1) * (right + 1);
            long min = Math.min(kind, k);
//            System.out.println(nums.get(idx) + " " + arr[idx] + " " + kind);
            ans *= quickpow((long)nums.get(idx), min);
            ans %= mod;

            k -= min;

import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import java.util.List;
import java.util.Map;

class DownloadFile {
    private String url;
    private String fileName;
    private long contentLength;
    private String seedName;

    public DownloadFile setUrl(String url) {
        this.url = url;
        return this;
    }

    public DownloadFile setFileName(String fileName) {
        this.fileName = fileName;
        return this;
    }

    public DownloadFile setContentLength(long contentLength) {
        this.contentLength = contentLength;
        return this;
    }

    public DownloadFile setSeedName(String seedName) {
        this.seedName = seedName;
        return this;
    }

    public String getUrl() {
        return url;
    }

    public String getFileName() {
        return fileName;
    }

    public long getContentLength() {
        return contentLength;
    }

    public String getSeedName() {
        return seedName;
    }
}

public class DownloadManager {
    private static final Map<String, List<DownloadFile>> download_big_file_list = Maps.newConcurrentMap();
    private static final OkHttpClientEngine engine = new OkHttpClientEngine();

    public static void add(DownloadFile file) {
        String seed = file.getSeedName();
        download_big_file_list.computeIfAbsent(seed, k -> Lists.newArrayList()).add(file);
    }

    public static boolean isExist(String seedName) {
        List<DownloadFile> files = download_big_file_list.get(seedName);
        return files != null && !files.isEmpty();
    }

    public static void downloadBigFile(String seedName) {
        List<DownloadFile> files = download_big_file_list.get(seedName);
        if (files == null || files.isEmpty()) {
            return;
        }

        for (DownloadFile file : files) {
            try {
                engine.download(file.getUrl(), file.getFileName(), file.getContentLength());
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

        download_big_file_list.remove(seedName);
    }

    public static void main(String[] args) {
        DownloadFile file1 = new DownloadFile()
            .setUrl("http://example.com/file1.bin")
            .setFileName("file1.bin")
            .setContentLength(1048576L)
            .setSeedName("seed_alpha");

        DownloadFile file2 = new DownloadFile()
            .setUrl("http://example.com/file2.bin")
            .setFileName("file2.bin")
            .setContentLength(2097152L)
            .setSeedName("seed_alpha");

public class Program {
    public boolean areAlmostEqual(String word1, String word2) {
        if (word1.equals(word2)) return true;
        int[] count1 = new int[26];
        int[] count2 = new int[26];
        for (char c : word1.toCharArray()) count1[c - 'a']++;
        for (char c : word2.toCharArray()) count2[c - 'a']++;
        int diff = 0;
        for (int i = 0; i < 26; i++) {
            if (count1[i]!= count2[i]) diff++;
        }
        return diff == 2 || (diff == 0 && word1.length() == word2.length());
    }
}

/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) { val = x; }
 * }
 */
public class Reader {
    public List<Integer> ret = new ArrayList<>();
    private void check(int[] old, int [] nw) {
        for(int i = 0; i < 3; ++i) {
            if(nw[i] > old[i]) old[i] = nw[i];
        }
    }
    private int[] create(int a, int b, int c) {
        return new int[]{a, b, c};
    }
    private int[] helper(TreeNode root) {
        if(root == null) {
            return new int[]{0,0,0};
        }

        int[] ret = new int[]{1,1,1};
        int[] left = helper(root.left);
        int[] right = helper(root.right);

        check(ret, create(left[0], 0, 0));
        check(ret, create(right[0], 0, 0));

        if(root.left != null) {
            if(root.left.val + 1 == root.val) {
                check(ret, create(left[1] + 1, left[1] + 1, 0));
            }
            if(root.left.val - 1 == root.val) {
                check(ret, create(left[2] + 1, 0, left[2] + 1));
            }
        }
        if(root.right != null) {
            if(root.right.val + 1 == root.val) {
                check(ret, create(right[1] + 1, right[1] + 1, 0));
            }
            if(root.right.val - 1 == root.val) {
                check(ret, create(right[2] + 1, 0, right[2] + 1));
            }
        }
        if(root.left != null && root.right != null) {
            if(root.left.val + 1 == root.val && root.right.val - 1 == root.val) {
                check(ret, create(left[1] + right[2] + 1, 0, 0));
            }
            if(root.left.val - 1 == root.val && root.right.val + 1 == root.val) {
                check(ret, create(left[2] + right[1] + 1, 0, 0));
            }
        }
        return ret;

    }
    public int longestConsecutive(TreeNode root) {
        return helper(root)[0];
    }
}

/**
 * A student record comparable by mark (descending).
 */
public class Student implements Comparable<Student> {
    String code;
    String name;
    int mark;

    public Student() {
        code = "";
        name = "";
        mark = 0;
    }

    public Student(String code, String name, int mark) {
        this.code = code.toUpperCase();
        this.name = name.toUpperCase();
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        if (name.length() > 0) {
            this.name = name.trim().toUpperCase();
        }
    }

    public int getMark() {
        return mark;
    }

    public void setMark(int mark) {
        this.mark = (mark >= 0 && mark <= 10) ? mark : 0;
    }

    @Override
    public String toString() {
        return code + ", " + name + ", " + mark;
    }

    @Override
    public int compareTo(Student other) {
        return -(mark - other.getMark());
    }
}

