public class Fields {

    static int n, m, k;

    static ArrayList<ArrayList<Integer>> adj;

    static boolean[] special, visited;

    static int[] distance1, distanceN;

    public static void main(String[] args) throws Exception {

        FastIO in = new FastIO();

        n = in.nextInt();

        m = in.nextInt();

        k = in.nextInt();

        special = new boolean[n];

        visited = new boolean[n];

        distance1 = new int[n];

        distanceN = new int[n];

        adj = new ArrayList<ArrayList<Integer>>();

        for (int i=0; i<k; i++) {

            int s = in.nextInt()-1;

            special[s] = true;

        }

        for (int i=0; i<n; i++) {

            adj.add(new ArrayList<Integer>());

        }

        for (int i=0; i<m; i++) {

            int a = in.nextInt()-1;

            int b = in.nextInt()-1;

            adj.get(a).add(b);

            adj.get(b).add(a);

        }

        bfs(0, distance1);

        visited = new boolean[n];

        bfs(n-1, distanceN);

        Pair[] specialPairs = new Pair[k];

        int index = 0;

        for (int i=0; i<n; i++) {

            if (special[i]) {

                specialPairs[index] = new Pair(distance1[i], distanceN[i]);

                index++;

            }

        }

        Arrays.parallelSort(specialPairs, (o1, o2) -> Integer.compare(o1.x, o2.x));

        int[] suffixMaxY = new int[k];

        suffixMaxY[k-1] = specialPairs[k-1].y;

        for (int i=k-2; i>=0; i--) {

            suffixMaxY[i] = Math.max(specialPairs[i].y, suffixMaxY[i+1]);

        }

        int maxDist = 0;

        for (int i=0; i<k-1; i++) {

            int longestPath = specialPairs[i].x+1+Math.min(specialPairs[i].y, suffixMaxY[i+1]);

            maxDist = Math.max(maxDist, longestPath);

        }

        System.out.println(Math.min(maxDist, distance1[n-1]));

    }

    public static void bfs(int node, int[] distance) {

        Queue<Pair> queue = new LinkedList<Pair>();

        queue.add(new Pair(node, 0));

        while (!queue.isEmpty()) {

            Pair curr = queue.poll();

            if (visited[curr.x]) continue;

//          if (curr.x==3) System.out.println(curr.y);

            distance[curr.x] = curr.y;

            visited[curr.x] = true;

            for (int next: adj.get(curr.x)) {

                if (!visited[next]) {

                    queue.add(new Pair(next, curr.y+1));

                }

            }

        }

    }

    static class Pair {

        int x, y;

import org.apache.maven.plugin.AbstractMojo;
import org.apache.maven.plugin.MojoExecutionException;
import org.apache.maven.plugins.annotations.Mojo;
import org.apache.maven.plugins.annotations.LifecyclePhase;
import sh.isaac.api.LookupService;
import sh.isaac.api.ShutdownService;

import java.util.Date;

@Mojo(name = "shutdown-isaac", defaultPhase = LifecyclePhase.POST_INTEGRATION_TEST)
public class Shutdown extends AbstractMojo {

    @Override
    public void execute() throws MojoExecutionException {
        // Set the system to headless mode
        System.setProperty("java.awt.headless", "true");

        // Log the initiation of the shutdown process
        getLog().info("Initiating shutdown of the Isaac terminology store...");

        // Record the start time
        Date startTime = new Date();

        try {
            // Retrieve the ShutdownService from LookupService
            ShutdownService shutdownService = LookupService.getService(ShutdownService.class);

            if (shutdownService == null) {
                throw new MojoExecutionException("ShutdownService not found.");
            }

            // Perform the shutdown
            shutdownService.shutdown();

            // Record the end time
            Date endTime = new Date();

            // Calculate the duration
            long duration = endTime.getTime() - startTime.getTime();

            // Log the completion of the shutdown process and the duration
            getLog().info("Isaac terminology store successfully shut down in " + duration + " ms.");
        } catch (Exception e) {
            // Handle any exceptions that occur during the shutdown
            getLog().error("An error occurred while shutting down the Isaac terminology store:", e);
            throw new MojoExecutionException("Failed to shut down the Isaac terminology store.", e);
        }
    }
}

public static int[][] ZigZag(int n)
{
    int[][] result = new int[n][n];
    int i = 0, j = 0;
    int d = -1; // -1 for top-right move, +1 for bottom-left move
    int start = 0, end = n * n - 1;
    do
    {
        result[i][j] = start++;
        result[n - i - 1][n - j - 1] = end--;

        i += d; j -= d;
        if (i < 0)
        {
            i++; d = -d; // top reached, reverse
        }
        else if (j < 0)
        {
            j++; d = -d; // left reached, reverse
        }
    } while (start < end);
    if (start == end)
        result[i][j] = start;
    return result;
}

