        FastScanner sc = new FastScanner();
        int t = sc.nextInt();
        while(t-->0){
            int x = sc.nextInt();
            int d = sc.nextInt();
            if(x==d){
                System.out.println("NO");
                continue;
            }
            if(x%d!=0){
                System.out.println("YES");
                continue;
            }
            int count = 0;
            while(x%d==0){
                x/=d;
                count++;
            }
            if(count==1){
                System.out.println("NO");
                continue;
            }
            if(count==2){
                if(x==1){
                    System.out.println("NO");
                    continue;
                }
                else{
                    System.out.println("YES");
                    continue;
                }
            }
            if(count==3){
                if(x==1){
                    System.out.println("NO");
                    continue;
                }
                else{
                    System.out.println("YES");
                    continue;
                }
            }
            if(count>3){
                System.out.println("YES");
                continue;
            }
        }
    }

    static class FastScanner {
        BufferedReader br;
        StringTokenizer st;

        public FastScanner() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
