class Service {

    Integer[][][] cache1;

    public int mergeStones(int[] stones, int K) {
        // condition on the last interval to link
        // (N-1)%(K-1) == 0
        int N = stones.length;
        if ((N-1)%(K-1) != 0) return -1;
        cache1 = new Integer[N][N+1][K];

        return dp1(stones, 0, N, K-1, K);

    }

    private int dp1(int[] stones, int start, int end, int rem, int K) {
        if (end - start == 1) return 0;
        if (rem == 0) rem = K-1;
        if (cache1[start][end][rem] == null) {

            int sum = 0;
            for (int i = start; i < end; ++i) sum += stones[i];
            int min = Integer.MAX_VALUE;

            for (int i = start; i < end-1; ++i) {
                // if place between i and i+1
                // first confirm validity
                if ((i!= start) && (i-start)%(K-1) != 0) continue;
                int tmp1 = dp1(stones, start, i+1, K-1, K);
                int tmp2 = dp1(stones, i+1, end, rem-1, K);
                int tmp = tmp1 + tmp2;
                if (rem == K-1) tmp += sum;
                if (tmp < min) min = tmp;
            }
            cache1[start][end][rem] = min;
        }
        return cache1[start][end][rem];
    }
}

import org.apache.ignite.IgniteCheckedException;
import org.apache.ignite.internal.pagemem.PageMemory;
import org.apache.ignite.internal.processors.cache.database.tree.io.DataPageIO;

/**
 * Insert fragment to data page record.
 */
public class DataPageInsertFragmentRecord extends PageDeltaRecord {
    /** Link to the last entry fragment. */
    private final long lastLink;

    /** Actual fragment data. */
    private final byte[] payload;

    /**
     * @param cacheId Cache ID.
     * @param pageId Page ID.
     * @param payload Fragment payload.
     * @param lastLink Link to the last entry fragment.
     */
    public DataPageInsertFragmentRecord(
        final int cacheId,
        final long pageId,
        final byte[] payload,
        final long lastLink
    ) {
        super(cacheId, pageId);

        this.lastLink = lastLink;
        this.payload = payload;
    }

    /** {@inheritDoc} */
    @Override public void applyDelta(PageMemory pageMem, long pageAddr) throws IgniteCheckedException {
        DataPageIO io = DataPageIO.VERSIONS.forPage(pageAddr);

        io.addRowFragment(pageAddr, payload, lastLink, pageMem.pageSize());
    }

    /** {@inheritDoc} */
