import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;

import javax.swing.Icon;
import javax.swing.JLabel;
import javax.swing.JTable;
import javax.swing.table.DefaultTableCellRenderer;

public class GeneralRenderer extends DefaultTableCellRenderer {

    private Color rendererBackground;
    private Color selBackground;

    public GeneralRenderer() {
        super();
        rendererBackground = null;
        selBackground = Color.LIGHT_GRAY;
    }

    public GeneralRenderer(Color rendererBackground, Color selBackground) {
        super();
        this.rendererBackground = rendererBackground;
        this.selBackground = selBackground;
    }

    @Override
    public Component getTableCellRendererComponent(JTable table, Object value,
            boolean isSelected, boolean hasFocus, int row, int column) {

        JLabel label = new JLabel();

        if (value instanceof String) {
            label.setText((String) value);
        } else if (value instanceof Icon) {
            label.setIcon((Icon) value);
        } else if (value instanceof JLabel) {
            label = (JLabel) value;
        } else if (value != null){
            label.setText(value.toString());
        } else {
            label.setText("");
        }

        if (isSelected) {
            label.setBackground(selBackground);
        } else {
            if (rendererBackground != null) {
                label.setBackground(rendererBackground);
            } else {
                label.setBackground(table.getBackground());
            }

        }

        label.setOpaque(true);
        return label;
    }

    @Override
    protected void firePropertyChange(String propertyName, Object oldValue, Object newValue) {
        // Do nothing to prevent properties being updated.
    }

    @Override
    public void setValue(Object value) {
        // Override setValue to prevent default behavior
    }
}

public class Complex implements Cloneable {
    private double a;
    private double b;

    public Complex() {
        this(0, 0);
    }

    public Complex(double a) {
        this(a, 0);
    }

    public Complex(double a, double b) {
        this.a = a;
        this.b = b;
    }

    public double getRealPart() {
        return a;
    }

    public double getImaginaryPart() {
        return b;
    }

    public Complex add(Complex c) {
        double real = a + c.a;
        double imaginary = b + c.b;
        return new Complex(real, imaginary);
    }

    public Complex subtract(Complex c) {
        double real = a - c.a;
        double imaginary = b - c.b;
        return new Complex(real, imaginary);
    }

    public Complex multiply(Complex c) {
        double real = a * c.a - b * c.b;
        double imaginary = b * c.a + a * c.b;
        return new Complex(real, imaginary);
    }

    public Complex divide(Complex c) {
        double denominator = c.a * c.a + c.b * c.b;
        double real = (a * c.a + b * c.b) / denominator;
        double imaginary = (b * c.a - a * c.b) / denominator;
        return new Complex(real, imaginary);
    }

    public double abs() {
        return Math.sqrt(a * a + b * b);
    }

    @Override
    public String toString() {
        if (b == 0) {
            return a + "";
        }
        if (a == 0) {
            return b + "i";
        }
        if (b < 0) {
            return a + " - " + (-b) + "i";
        }
        return a + " + " + b + "i";
    }

    @Override
    public Complex clone() {
        return new Complex(a, b);
    }
}

