public class PAdESOCSPSigningCertificateTest extends AbstractPAdESTestValidation {

    @Test
    public void test() {
        DSSDocument signedDocument = getSignedDocument();
        DiagnosticData diagnosticData = getDiagnosticData(signedDocument);
        assertNotNull(diagnosticData);

        for (RevocationWrapper revocationWrapper : diagnosticData.getAllRevocationData()) {
            List<RelatedCertificateWrapper> relatedCertificates = revocationWrapper.getRelatedCertificates();
            if (!relatedCertificates.isEmpty()) {
                for (RelatedCertificateWrapper relatedCertificate : relatedCertificates) {
                    for (CertificateRefWrapper certificateRefWrapper : relatedCertificate.getReferences()) {
                        if (revocationWrapper.getSigningCertificate() != null) {
                            assertEquals(revocationWrapper.getSigningCertificate(), certificateRefWrapper.getCertificate());
                            assertEquals(CertificateRefOrigin.SIGNING_CERTIFICATE, certificateRefWrapper.getOrigin());
                        }
                    }
                }
                assertEquals(0, revocationWrapper.getOrphanCertificates().size());

            }
        }
    }

