        return new InMemoryDocument(
                getClass().getResourceAsStream("/pades-ocsp-sign-cert.pdf"));
    }

    private List<CertificateRefWrapper> foundCertificates(RevocationWrapper revocationWrapper) {
        return revocationWrapper.getCertificates();
    }

