public class GfuiBorder {
    private PenAdp left, right, top, bottom;
    private boolean uniform;

    public GfuiBorder() {
        this.left = PenAdp.new_();
        this.right = PenAdp.new_();
        this.top = PenAdp.new_();
        this.bottom = PenAdp.new_();
        this.uniform = false;
    }

    public GfuiBorder Edge_set(GfuiBorderEdge edge, PenAdp pen) {
        switch (edge) {
            case Left: left = pen; break;
            case Right: right = pen; break;
            case Top: top = pen; break;
            case Bottom: bottom = pen; break;
        }
        return this;
    }

    public GfuiBorder Uniform_set(PenAdp pen) {
        left = right = top = bottom = pen;
        uniform = true;
        return this;
    }

    public void SyncPens() {
        if (uniform) {
            right = left;
            top = left;
            bottom = left;
        }
    }

    public void Draw(GfxAdp gfx, RectAdp rect) {
        SyncPens();

        // Draw left border
        if (left != null) {
            gfx.Line_draw(left,
                rect.X(), rect.Y(),
                rect.X(), rect.Y() + rect.Height());
        }

        // Draw right border
        if (right != null) {
            gfx.Line_draw(right,
                rect.X() + rect.Width(), rect.Y(),
                rect.X() + rect.Width(), rect.Y() + rect.Height());
        }

        // Draw top border
        if (top != null) {
            gfx.Line_draw(top,
                rect.X(), rect.Y(),
                rect.X() + rect.Width(), rect.Y());
        }

        // Draw bottom border
        if (bottom != null) {
            gfx.Line_draw(bottom,
                rect.X(), rect.Y() + rect.Height(),
                rect.X() + rect.Width(), rect.Y() + rect.Height());
        }
    }

    public String To_str() {
        return String.format("Left=%s;Right=%s;Top=%s;Bottom=%s",
            left.To_str(), right.To_str(), top.To_str(), bottom.To_str());
    }

    public void Clear() {
        left = right = top = bottom = null;
        uniform = false;
    }
}

