public class BeliefSystem {
    private Map<String, Integer> beliefs = new HashMap<>();

    public void updateIntegerBelief(String name, int value) {
        if (beliefs.containsKey(name)) {
            beliefs.put(name, beliefs.get(name) + value);
        } else {
            beliefs.put(name, value);
        }
    }

    public int getBelief(String name) {
        return beliefs.getOrDefault(name, 0);
    }
}

