import com.fasterxml.jackson.databind.ObjectMapper;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.ComponentScan;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.env.Environment;
import org.springframework.http.converter.HttpMessageConverter;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.scheduling.annotation.EnableAsync;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurationSupport;
import org.springframework.web.servlet.i18n.SessionLocaleResolver;
import org.springframework.web.servlet.mvc.method.annotation.RequestMappingHandlerMapping;

import java.util.List;

@Configuration
@ComponentScan(value = {"org.flowable.app.rest.api", "org.flowable.app.rest.exception"})
@EnableAsync
public class ApiDispatcherServletConfiguration extends WebMvcConfigurationSupport {

    @Autowired
    protected ObjectMapper objectMapper;

    @Autowired
    protected Environment environment;

    @Bean
    public SessionLocaleResolver localeResolver() {
        return new SessionLocaleResolver();
    }

    @Bean
    public RequestMappingHandlerMapping requestMappingHandlerMapping() {
        RequestMappingHandlerMapping requestMappingHandlerMapping = new RequestMappingHandlerMapping();
        requestMappingHandlerMapping.setUseSuffixPatternMatch(false);
        requestMappingHandlerMapping.setRemoveSemicolonContent(false);
        requestMappingHandlerMapping.setInterceptors(getInterceptors());
        return requestMappingHandlerMapping;
    }

    @Override
    public void configureMessageConverters(List<HttpMessageConverter<?>> converters) {
        addDefaultHttpMessageConverters(converters);
        for (HttpMessageConverter<?> converter: converters) {
            if (converter instanceof MappingJackson2HttpMessageConverter) {
                MappingJackson2HttpMessageConverter jackson2HttpMessageConverter = (MappingJackson2HttpMessageConverter) converter;
                jackson2HttpMessageConverter.setObjectMapper(objectMapper);
                break;
            }
        }
    }
}

import java.io.IOException;

public class CopyStreamException extends IOException {
    private static final long serialVersionUID = 1L;
    private final long totalBytesTransferred;

    public CopyStreamException(String message, long totalBytesTransferred, IOException cause) {
        super(message, cause);
        this.totalBytesTransferred = totalBytesTransferred;
    }

    public long getTotalBytesTransferred() {
        return totalBytesTransferred;
    }

    public IOException getIOException() {
        return (IOException) getCause();
    }

    @Override
    public String toString() {
        return String.format("CopyStreamException: %s, totalBytesTransferred=%d, cause=%s",
                              getMessage(),
                              totalBytesTransferred,
                              getIOException());
    }

    public static void main(String[] args) {
        try {
            // Simulate a stream copy operation with an error
            long bytesCopied = 0;
            long totalBytes = 1000; // Let's say we want to copy 1000 bytes

            // Simulating a reading operation that causes an IOException
            while (bytesCopied < totalBytes) {
                // Simulate success for some bytes
                bytesCopied += 100;

                // Simulating an error after copying 500 bytes
                if (bytesCopied == 500) {
                    throw new IOException("Simulated IO failure.");
                }
            }
        } catch (IOException e) {
            // Handling the original IOException by wrapping it in our custom exception
            throw new CopyStreamException("Stream copy operation failed.",
                                           500, // bytes copied before exception
                                           e);
        }
    }
}

class Queue {
public:
    const int mod=1e9+7;
    int slow(long long n) {
        std::string res;
        while(n--) {
            if(n%2==0) {
                res+'0';
            } else {
                int total=0;
                for(int i=2;i<10;i++){
                    if(isPrime(i)){
                        total++;
                    }
                }
                res+=std::to_string(total);
            }
        }
        std::cout<<res<<std::endl;
        return 0;
    }
private:
    bool isPrime(int n) {
        if(n<=1) {
            return false;
        }
        for(int i=2;i*i<=n;i++){
            if(n%i==0) {
                return false;
            }
        }
        return true;
    }
};

import java.util.ArrayList;
import java.util.List;

public abstract class AbstractOperation implements Operation {

    protected AbstractOperation(Graph graph, String type, String name) {
        this.graph = graph;
        this.type = type;
        this.name = name;
    }

    @Override
    public List<Output<?>> outputList(int index) {
        List<Output<?>> outputs = new ArrayList<>();
        long numOutputs = numOutputs(index);
        for (int i = 0; i < numOutputs; i++) {
            outputs.add(output(index, i));
        }
        return outputs;
    }

    @Override
    public Output<?> output(int index) {
        return output(0, index);
    }

    @Override
    public String toString() {
        return "Operation(type=" + type + ", name=" + name + ")";
    }

    protected abstract long numOutputs(int index);

    protected abstract Output<?> output(int outputIndex, int index);

    protected abstract long getNativeHandle();

    protected abstract Shape shape(int outputIndex);

    protected abstract DataType dataType(int outputIndex);

    protected abstract Tensor<?> tensor(int outputIndex);

    private final Graph graph;
    private final String type;
    private final String name;
}

interface Operation {
    List<Output<?>> outputList(int index);
    Output<?> output(int index);
    String toString();
}

class Output<T extends Tensor<T>> {
    private final AbstractOperation op;
    private final int index;

    public Output(AbstractOperation op, int index) {
        this.op = op;
        this.index = index;
    }

    public Shape shape() {
        return op.shape(index);
    }

    public DataType dataType() {
        return op.dataType(index);
    }

    public T tensor() {
        // Cast is safe because the constructor ensures the correct type
        return (T) op.tensor(index);
    }

    @Override
    public String toString() {
        return "Output(op=" + op + ", index=" + index + ")";
    }
}

