import java.io.Serializable;
import java.util.Iterator;
import java.util.NoSuchElementException;
import org.jeeventstore.ChangeSet;

class EventsIterator implements Iterator<Object>, Serializable {

    private static final long serialVersionUID = 1L;

    private final Iterator<ChangeSet> cit;
    private Iterator<?> it = null;

    public EventsIterator(final Iterator<ChangeSet> cit) {
        if (cit == null)
            throw new IllegalArgumentException("iterator must not be null");
        this.cit = cit;
        advance();
    }

    private void advance() {
        if (this.it != null && this.it.hasNext())
            return;

        while (this.cit.hasNext()) {
            ChangeSet changeset = this.cit.next();
            if (changeset == null)
                continue;
            if (changeset.events() == null)
                continue;

            Iterator<?> iterator = changeset.events().iterator();
            if (iterator != null && iterator.hasNext()) {
                this.it = iterator;
                return;
            }
        }
        this.it = null;
    }

    @Override
    public boolean hasNext() {
        return (this.it != null && this.it.hasNext());
    }

    @Override
    public Object next() {
        if (!hasNext())
            throw new NoSuchElementException();
        Object next = this.it.next();
        advance();
        return next;
    }

    @Override
    public void remove() {
        throw new UnsupportedOperationException("Not supported.");
    }

}

public static int searchCharArray(char[] charArray, char value, int occurrence) {
    int index = -1;
    int count = 0;
    for(int i=0; i<charArray.length; i++) {
        if(charArray[i] == value) {
            count++;
            if(count == occurrence) {
                index = i;
                break;
            }
        }
    }
    return index;
}

public class LogicPuzzle
{
    boolean S[] = new boolean[13];
    int Count = 0;
 
    public boolean check2 ()
    {
        int count = 0;
        for (int k = 7; k <= 12; k++)
            if (S[k]) count++;
        return S[2] == (count == 3);
    }
 
    public boolean check3 ()
    {
        int count = 0;
        for (int k = 2; k <= 12; k += 2)
            if (S[k]) count++;
        return S[3] == (count == 2);
    }
 
    public boolean check4 ()
    {
        return S[4] == ( !S[5] || S[6] && S[7]);
    }
 
    public boolean check5 ()
    {
        return S[5] == ( !S[2] && !S[3] && !S[4]);
    }
 
    public boolean check6 ()
    {
        int count = 0;
        for (int k = 1; k <= 11; k += 2)
            if (S[k]) count++;
        return S[6] == (count == 4);
    }
 
    public boolean check7 ()
    {
        return S[7] == ((S[2] || S[3]) && !(S[2] && S[3]));
    }
 
    public boolean check8 ()
    {
        return S[8] == ( !S[7] || S[5] && S[6]);
    }
 
    public boolean check9 ()
    {
        int count = 0;
        for (int k = 1; k <= 6; k++)
            if (S[k]) count++;
        return S[9] == (count == 3);
    }
 
    public boolean check10 ()
    {
        return S[10] == (S[11] && S[12]);
    }
 
    public boolean check11 ()
    {
        int count = 0;
        for (int k = 7; k <= 9; k++)
            if (S[k]) count++;
        return S[11] == (count == 1);
    }
 
    public boolean check12 ()
    {
        int count = 0;
        for (int k = 1; k <= 11; k++)
            if (S[k]) count++;
        return S[12] == (count == 4);
    }
 
    public void check ()
    {
        if (check2() && check3() && check4() && check5() && check6()
            && check7() && check8() && check9() && check10() && check11()
            && check12())
        {
            for (int k = 1; k <= 12; k++)
                if (S[k]) System.out.print(k + " ");
            System.out.println();
            Count++;
        }
    }
 
    public void recurseAll (int k)
    {
        if (k == 13)
            check();
        else
        {
            S[k] = false;
            recurseAll(k + 1);
            S[k] = true;
            recurseAll(k + 1);
        }
    }
 
    public static void main (String args[])
    {
        LogicPuzzle P = new LogicPuzzle();
        P.S[1] = true;
        P.recurseAll(2);
        System.out.println();
        System.out.println(P.Count + " Solutions found.");
    }
}

