import java.util.*;

public class Generator {
    public static void main(String[] args) {
        int[][] test = new int[6][6];

        Scanner in = new Scanner(System.in);
        System.out.println("Enter a 6 x 6 matrix row by row: ");

        int invalidRow = -1; //Initialize

        for (int i = 0; i < 6; i++) {
            int rowCountOnes = 0;
            for (int j = 0; j < 6; j++) {
                int n = in.nextInt();
                if (n == 1) {
                    rowCountOnes++;
                }
                test[i][j] = n;
            }
            if (rowCountOnes % 2 != 0) {
                invalidRow = i;
            }
        }
        int invalidCol = evalColumns(test);
        System.out.println("The flipped cell is at (" + invalidRow + ", " + invalidCol + ")");
        in.close();
    }

    static int evalColumns(int[][] array) {
        int invalidColumn = -1;
        for (int i = 0; i < 6; i++) {
            int colCount = 0;
            for (int j = 0; j < 6; j++) {
                if (array[j][i] == 1) {
                    colCount++;
                }

            }
            if (colCount % 2 != 0) {
                invalidColumn = i;
            }
        }
        return invalidColumn;
    }

}

import com.jme3.scene.Node;
import com.jme3.scene.Spatial;
import dae.animation.rig.Prefab;

public class PrefabPlaceHolder extends Prefab {
    private String prefabName;
    private OnPrefabFound onPrefabFound;
    private float checkInterval = 0.5f;
    private float time;
    private boolean prefabFound;
    private Node topLevelNode;

    public PrefabPlaceHolder(String prefabName, OnPrefabFound onPrefabFound, float checkInterval) {
        this.prefabName = prefabName;
        this.onPrefabFound = onPrefabFound;
    }

    @Override
    public void updateLogicalState(float tpf) {
        super.updateLogicalState(tpf);
        if (prefabFound) return;

        time += tpf;
        if (time >= checkInterval) {
            time = 0;
            topLevelNode = findRootNode();
            if (topLevelNode != null) {
                Spatial prefab = topLevelNode.getChild(prefabName);
                if (prefab != null) {
                    onPrefabFound.onPrefabFound(this, prefab);
                    prefabFound = true;
                }
            }
        }
    }

    private Node findRootNode() {
        Spatial current = this;
        while (current.getParent() != null) {
            current = current.getParent();
        }
        return (Node) current;
    }

    @Override
    public String toString() {
        return prefabName;
    }

    public interface OnPrefabFound {
        void onPrefabFound(PrefabPlaceHolder placeholder, Spatial prefab);
    }
}

private static String alias(SqlNode item) {
        assert item instanceof SqlCall;
