        return identifier.getSimple();
    }

private static final int binarySearchForRootPrimaryNode(int[] rootPrimaryIndexes, int length, long[] nodes, long p) {
    int low = 0;
    int high = length - 1;

    while (low <= high) {
        int mid = (low + high) >>> 1;
        long midVal = nodes[rootPrimaryIndexes[mid]];

        if (midVal < p)
            low = mid + 1;
        else if (midVal > p)
            high = mid - 1;
        else
            return mid; // key found
    }
    return -(low + 1);  // key not found, return negative index for insertion
}

public class RabinMiller {
    public static boolean isPrime(int n, int k) {
        if ((n < 2) || (n % 2 == 0)) return (n == 2);

        int s = n - 1;
        while (s % 2 == 0)  s >>= 1;

        Random r = new Random();
        for (int i = 0; i < k; i++) {
            int a = r.nextInt(n - 1) + 1;
            int temp = s;
            long mod = 1;
            for (int j = 0; j < temp; ++j)  mod = (mod * a) % n;
            while (temp!= n - 1 && mod!= 1 && mod!= n - 1) {
                mod = (mod * mod) % n;
                temp *= 2;
            }

            if (mod!= n - 1 && temp % 2 == 0) return false;
        }
        return true;
    }
}

