import java.nio.channels.spi.SelectorProvider;
import java.security.AccessController;
import java.security.PrivilegedAction;
import sun.security.action.GetPropertyAction;

/**
 * Creates this platform's default SelectorProvider
 */

public class DefaultSelectorProvider {

    /**
     * Prevent instantiation.
     */
    private DefaultSelectorProvider() { }

    /**
     * Returns the default SelectorProvider.
     */
    public static SelectorProvider create() {
        String osname = AccessController.doPrivileged(
            new GetPropertyAction("os.name"));
        if ("SunOS".equals(osname)) {
            return new sun.nio.ch.DevPollSelectorProvider();
        }

        // use EPollSelectorProvider for Linux kernels >= 2.6
        if ("Linux".equals(osname)) {
            String osversion = AccessController.doPrivileged(
                new GetPropertyAction("os.version"));
            String[] vers = osversion.split("\\.", 0);
            if (vers.length >= 2) {
                try {
                    int major = Integer.parseInt(vers[0]);
                    int minor = Integer.parseInt(vers[1]);
                    if (major > 2 || (major == 2 && minor >= 6)) {
                        return new sun.nio.ch.EPollSelectorProvider();
                    }
                } catch (NumberFormatException x) {
                    // format not recognized
                }
            }
        }

        return new sun.nio.ch.PollSelectorProvider();
    }

}

import java.util.*;
 
public class PrimeGenerator {
    private int limit_;
    private int index_ = 0;
    private int increment_;
    private int count_ = 0;
    private List<Integer> primes_ = new ArrayList<>();
    private BitSet sieve_ = new BitSet();
    private int sieveLimit_ = 0;
 
    public PrimeGenerator(int initialLimit, int increment) {
        limit_ = nextOddNumber(initialLimit);
        increment_ = increment;
        primes_.add(2);
        findPrimes(3);
    }
 
    public int nextPrime() {
        if (index_ == primes_.size()) {
            if (Integer.MAX_VALUE - increment_ < limit_)
                return 0;
            int start = limit_ + 2;
            limit_ = nextOddNumber(limit_ + increment_);
            primes_.clear();
            findPrimes(start);
        }
        ++count_;
        return primes_.get(index_++);
    }
 
    public int count() {
        return count_;
    }
 
    private void findPrimes(int start) {
        index_ = 0;
        int newLimit = sqrt(limit_);
        for (int p = 3; p * p <= newLimit; p += 2) {
            if (sieve_.get(p/2 - 1))
                continue;
            int q = p * Math.max(p, nextOddNumber((sieveLimit_ + p - 1)/p));
            for (; q <= newLimit; q += 2*p)
                sieve_.set(q/2 - 1, true);
        }
        sieveLimit_ = newLimit;
        int count = (limit_ - start)/2 + 1;
        BitSet composite = new BitSet(count);
        for (int p = 3; p <= newLimit; p += 2) {
            if (sieve_.get(p/2 - 1))
                continue;
            int q = p * Math.max(p, nextOddNumber((start + p - 1)/p)) - start;
            q /= 2;
            for (; q >= 0 && q < count; q += p)
                composite.set(q, true);
        }
        for (int p = 0; p < count; ++p) {
            if (!composite.get(p))
                primes_.add(p * 2 + start);
        }
    }
 
    private static int sqrt(int n) {
        return nextOddNumber((int)Math.sqrt(n));
    }
 
    private static int nextOddNumber(int n) {
        return 1 + 2 * (n/2);
    }
 
    public static void main(String[] args) {
        PrimeGenerator pgen = new PrimeGenerator(20, 200000);
        System.out.println("First 20 primes:");
        for (int i = 0; i < 20; ++i) {
            if (i > 0)
                System.out.print(", ");
            System.out.print(pgen.nextPrime());
        }
        System.out.println();
        System.out.println("Primes between 100 and 150:");
        for (int i = 0; ; ) {
            int prime = pgen.nextPrime();
            if (prime > 150)
                break;

import io.cloudslang.content.vmware.utils.InputUtils;

public class HttpInputs {

    private final String host;
    private final int port;
    private final String protocol;
    private final String username;
    private final String password;
    private final boolean trustEveryone;

    private HttpInputs(String host, int port, String protocol, String username, String password, boolean trustEveryone) {
        this.host = host;
        this.port = port;
        this.protocol = protocol;
        this.username = username;
        this.password = password;
        this.trustEveryone = trustEveryone;
    }

    public String getHost() {
        return host;
    }

    public int getPort() {
        return port;
    }

    public String getProtocol() {
        return protocol;
    }

    public String getUsername() {
        return username;
    }

    public String getPassword() {
        return password;
    }

    public boolean isTrustEveryone() {
        return trustEveryone;
    }

    public static class HttpInputsBuilder {
        private String host;
        private int port;
        private String protocol;
        private String username;
        private String password;
        private boolean trustEveryone;

        public HttpInputsBuilder() {
            this.port = 443;
            this.trustEveryone = false;
        }

        public HttpInputsBuilder withHost(String host) {
            this.host = host;
            return this;
        }

        public HttpInputsBuilder withPort(String port) {
            this.port = InputUtils.getIntInput(port, 443);
            return this;
        }

        public HttpInputsBuilder withProtocol(String protocol) {
            this.protocol = protocol;
            return this;
        }

        public HttpInputsBuilder withUsername(String username) {
            this.username = username;
            return this;
        }

        public HttpInputsBuilder withPassword(String password) {
            this.password = password;
            return this;
        }

        public HttpInputsBuilder withTrustEveryone(String trustEveryone) {
            this.trustEveryone = Boolean.parseBoolean(trustEveryone);
            return this;
        }

        public HttpInputs build() {
            return new HttpInputs(host, port, protocol, username, password, trustEveryone);
        }
    }

    public static HttpInputsBuilder builder() {
        return new HttpInputsBuilder();
    }
}

import java.util.*;

import java.io.*;

public class cf923B {

  public static void main(String[] args) throws IOException{

    BufferedReader br=new BufferedReader(new InputStreamReader(System.in));

    int n=Integer.parseInt(br.readLine());

    StringTokenizer st=new StringTokenizer(br.readLine());

    StringTokenizer st1=new StringTokenizer(br.readLine());

    int[] arr=new int[n];

    for (int j=0;j<n;j++) arr[j]=Integer.parseInt(st.nextToken());

    PriorityQueue<Long> pq=new PriorityQueue<Long>();

    long cumTemp=0;

    for (int i=0;i<n;i++) {

      long melted=0;

      int v=arr[i];

      long t=Long.parseLong(st1.nextToken());

      pq.add(v+cumTemp);

      long lim=t+cumTemp;

      while (pq.size()>0 && pq.peek()<=lim)

          melted+=pq.poll()-cumTemp;

      cumTemp+=t;

      melted+=pq.size()*t;

      System.out.print(melted+" ");

    }

    System.out.println("");

  }

}

private boolean isAuthorized(EventHandler handler, Map<String,String> headers)
    throws AuthorizationException {

        if (!Listener.METAINFO_PROTOCOL_REST.equals(headers.get(Listener.METAINFO_PROTOCOL)) && !Listener.METAINFO_PROTOCOL_SOAP.equals(headers.get(Listener.METAINFO_PROTOCOL)))
            return true;
        String userId = headers.get(Listener.AUTHENTICATED_USER_HEADER);
        User user = null;
        List<String> roles = handler.getRoles();
        if (roles != null && !roles.isEmpty()) {
            if (userId != null)
                user = UserGroupCache.getUser(userId);
            if (user == null)
                throw new AuthorizationException(ServiceException.NOT_AUTHORIZED, "Event Handler " + handler.getClass().getSimpleName() + " requires authenticated user");
            for (String role : roles) {
                if (user.hasRole(role))
                    return true;
            }
            throw new AuthorizationException(ServiceException.NOT_AUTHORIZED, "User: " + userId + " not authorized for: " + handler.getClass().getSimpleName());
        }
        return true;
    }

