public class Poker {
    static final String s_suits = "♣♦♥♠";
    static final String s_nums = "A23456789TJQK";
    static final int RMAX32 = ((1 << 31) - 1);
    static int seed = 1;
    static int rnd() { return (seed = (seed * 214013 + 2531011) & RMAX32) >> 16; }
    static void srnd(int x) { seed = x; }
    static void show(int[] c) {
        int i;
        for (i = 0; i < 52; i++) {
            System.out.printf("  \033[%dm%lc\033[m%lc", 32 - (1 + c[i]) % 4 / 2, s_suits.charAt(c[i] % 4), s_nums.charAt(c[i] / 4));
            if (!(++i % 8) || i == 52) System.out.println();
        }
    }
    static void deal(int s, int[] t) {
        int i, j;
        srnd(s);
        for (i = 0; i < 52; i++) t[i] = 51 - i;
        for (i = 0; i < 51; i++) {
            j = 51 - rnd() % (52 - i);
            int s = t[i]; t[i] = t[j]; t[j] = s;
        }
    }
    public static void main(String[] args) {
        int s, card[] = new int[52];
        if (args.length < 1 || (s = Integer.parseInt(args[0])) <= 0) s = 11982;
        Locale.setDefault(Locale.US);
        deal(s, card);
        System.out.printf("Hand %d\n", s);
        show(card);
    }
}

