public static Map<String, Object> putAllIfNew(Map<String, Object> dest, Map<String, Object> source)
    {
        if (dest == null)
            return source;
        if (source == null)
            return dest;
        for (String key : source.keySet())
        {
            if (dest.get(key) == null)
                dest.put(key, source.get(key));
        }
        return dest;
    }

import java.util.Scanner;

public class Product {
    public static void main(String[] args) {

        System.out.print("Enter an integer to discover the sum of its digits: ");

        Scanner input = new Scanner(System.in);

        int userNumber = input.nextInt();

        System.out.println(sumDigits(userNumber));

    }

    private static int sumDigits(int a) {

        int sum = 0;
        while (a > 0) {

            sum += (a % 10);

            a /= 10;
        }

        return sum;

    }

}

class Service {
    public int maxArea(int h, int w, int[] horizontalCuts, int[] verticalCuts) {
        int width = 0, height = 0, left = 0, top = 0;
        int MOD = (int) 1e9 + 7;
        Arrays.sort(horizontalCuts);
        Arrays.sort(verticalCuts);
        for (int num : horizontalCuts) {
            height = Math.max(height, num - top);
            top = num;
        }
        height = Math.max(height, h - top);
        for (int num : verticalCuts) {
            width = Math.max(width, num - left);
            left = num;
        }
        width = Math.max(width, w - left);
        return (int) ((long) height * width % MOD);
    }
}

