    public double getPerimeter() {
        return 2 * Math.PI * radius;
    }
}

 
public class BaseConversion {
    public static void main(String[] args) {
        for (int b = 2; b <= 36; b++) {
            String s = convertToBase(36, b);
            String f = String.format("%2d", b);
            System.out.println("36 base " + f + " = " + s.padEnd(6) + " -> base " + f + " = " + convertToDecimal(s, b));
        }
    }
 
    public static int min(int x, int y) {
        return x < y? x : y;
    }
 
    public static String convertToBase(int n, int b) {
        if (n < 2 || b < 2 || b == 10 || b > 36) return Integer.toString(n); // leave as decimal
        StringBuilder sb = new StringBuilder();
        int digit;
        int nn = n;
        while (nn > 0) {
            digit = nn % b;
            if (digit < 10) sb.append(digit);
            else            sb.append((char)(digit + 87));
            nn /= b;
        }
        return sb.reverse().toString();
    }
 
    public static int convertToDecimal(String s, int b) {
        if (b < 2 || b > 36) throw new IllegalArgumentException("Base must be between 2 and 36");
        if (b == 10) return Integer.parseInt(s);
        String t = s.toLowerCase();
        int result = 0;
        int digit;
        int multiplier = 1;
        for (int i = t.length() - 1; i >= 0; i--) {
            digit = -1;
            if (t.charAt(i) >= '0' && t.charAt(i) <= (char)min(57, 47 + b))
                digit = t.charAt(i) - 48;
            else if (b > 10 && t.charAt(i) >= 'a' && t.charAt(i) <= (char)min(122, 87 + b))
                digit = t.charAt(i) - 87;
            if (digit == -1) throw new IllegalArgumentException("Invalid digit present");
            if (digit > 0) result += multiplier * digit;
            multiplier *= b;
        }
        return result;
    }
}

import java.util.Scanner;

public class ArrayTest {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter the number of rows and columns in the array
        System.out.print("Enter the number of rows and columns in the array: ");
        int rows = input.nextInt();
        int cols = input.nextInt();

        // Create a two-dimensional array
        double[][] arr = new double[rows][cols];

        // Prompt the user to enter the array
        System.out.println("Enter the array:");
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                arr[i][j] = input.nextDouble();
            }
        }

        // Find the location of the largest element in the array
        double max = arr[0][0];
        int maxRow = 0;
        int maxCol = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                if (arr[i][j] > max) {
                    max = arr[i][j];
                    maxRow = i;
                    maxCol = j;
                }
            }
        }

        // Display the location of the largest element in the array
        System.out.println("The location of the largest element is " + max +
                " at (" + maxRow + ", " + maxCol + ")");
    }
}

