import java.util.Collection;
import java.util.concurrent.CountDownLatch;

import net.rubyeye.xmemcached.command.Command;
import net.rubyeye.xmemcached.command.CommandType;
import net.rubyeye.xmemcached.transcoders.CachedData;

import com.google.code.yanf4j.buffer.IoBuffer;

public class TextGetOneCommand extends Command {

  private TextGetCommand mergeGetCommand;

  public TextGetOneCommand(String key, byte[] keyBytes, CommandType cmdType, CountDownLatch latch) {
    super(key, keyBytes, cmdType, latch);
    this.result = null;
  }

  @Override
  public final void dispatch() {
    CachedData value = (CachedData) this.result;
    if (this.mergeGetCommand == null) {
      setResult(value);
      countDownLatch();
    } else {
      this.mergeGetCommand.returnValues.put(getKey(), value);
      this.mergeGetCommand.mergeCount--;
      if (this.mergeGetCommand.mergeCount == 0) {
        this.mergeGetCommand.countDownLatch();
      }
      countDownLatch();
    }
  }

  @Override
  protected void decodeError(String line) {
    if (this.mergeGetCommand == null) {
      if (this.wasFirst) {
        setResult(null);
      }
      countDownLatch();
    } else {
      this.mergeGetCommand.mergeCount--;
      if (this.mergeGetCommand.mergeCount == 0) {
        this.mergeGetCommand.countDownLatch();
      }
      countDownLatch();
    }
  }

  @Override
  public final IoBuffer getIoBuffer() {
    return null;
  }

  public final void setMergeGetCommand(TextGetCommand mergeGetCommand) {
    this.mergeGetCommand = mergeGetCommand;
  }
}

