import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.stream.Collectors;
import java.util.stream.Stream;
 
public class SleepSort {
 
    public static void main(String[] args) throws InterruptedException {
        List<Integer> items = Stream.of(args).map(Integer::parseInt).collect(Collectors.toList());
        sleepSort(items);
    }
 
    private static void sleepSort(List<Integer> items) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(items.size());
        for (Integer item : items) {
            executor.submit(() -> {
                try {
                    Thread.sleep(1000 * item);
                    System.out.println(item);
                } catch (InterruptedException e) {
                    e.printStackTrace();
                }
            });
        }
        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.DAYS);
    }
}

import java.util.Scanner;

public class GreatCircleDistance {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter point 1 (latitude and longitude) in degrees: ");
        double x1 = input.nextDouble();
        double y1 = input.nextDouble();

        System.out.print("Enter point 2 (latitude and longitude) in degrees: ");
        double x2 = input.nextDouble();
        double y2 = input.nextDouble();

        double radius = 6371.01; // average earth radius in km

        // convert degrees to radians
        double x1Radians = Math.toRadians(x1);
        double y1Radians = Math.toRadians(y1);
        double x2Radians = Math.toRadians(x2);
        double y2Radians = Math.toRadians(y2);

        // calculate great circle distance
        double distance = radius * Math.acos(Math.sin(x1Radians) * Math.sin(x2Radians)
                + Math.cos(x1Radians) * Math.cos(x2Radians) * Math.cos(y1Radians - y2Radians));

        System.out.println("The distance between the two points is " + distance + " km.");
    }
}

