/**
 * Data page insert fragment record.
 */
public class DataPageInsertFragmentRecord extends DataPagePayloadRecord {
    /** */
    private final long lastLink;

    /** */
    private final byte[] payload;

    /**
     * @param grpId Cache group ID.
     * @param pageId  Page ID.
     * @param payload Data.
     * @param lastLink Last link.
     */
    public DataPageInsertFragmentRecord(
        int grpId,
        long pageId,
        byte[] payload,
        long lastLink
    ) {
        super(grpId, pageId, null, 0, payload.length);
        this.lastLink = lastLink;
        this.payload = payload;
    }

    /** {@inheritDoc} */
    @Override public void applyDelta(PageMemory pageMem, long pageAddr) {
        DataPageIO io = DataPageIO.VERSIONS.forPage(pageAddr);

        io.addRowFragment(pageMem, pageAddr, payload, 0, payloadSize(), lastLink, pageId);
    }

    /** {@inheritDoc} */
    @Override public RecordType type() {
        return RecordType.DATA_PAGE_INSERT_FRAGMENT_RECORD;
    }

    /**
     * @return Last link.
     */
    public long lastLink() {
        return lastLink;
    }
    /**
     * @return payload size.
     */
    public int payloadSize(){
        return payload.length;
    }
        /**
     * @return payload.
     */
    public byte[] payload(){
        return payload;
    }
}

