        public Top(int x, int y, int xYon, int yYon) {
            this.x = x;
            this.y = y;
            this.xYon = xYon;
            this.yYon = yYon;
        }

        // Topun hareketini hesaplayan metot
        public void hareketEt() {
            x += xYon;
            y += yYon;

            // Kenarlara carpinca yonu ters cevir
            if (x <= 0 || x >= GENISLIK - 1) {
                xYon *= -1;
            }
            if (y <= 0 || y >= YUKSEKLIK - 1) {
                yYon *= -1;
            }
        }
