        Random rastgele = new Random();
        for (int i = 0; i < 5; i++) {
            toplar.add(new Top(
                rastgele.nextInt(GENISLIK),
                rastgele.nextInt(YUKSEKLIK),
                rastgele.nextBoolean() ? 1 : -1,
                rastgele.nextBoolean() ? 1 : -1
            ));
        }
    }

    // Toplarin hareket etmesini saglayan metot
    private static void toplariHareketEttir(List<Top> toplar) {
        for (Top top : toplar) {
