    private AdaptiveMethod adaptiveMethod;

    @Attribute(name = "invert")
    private boolean invert;

    @Attribute(name = "blockSize")
    private int blockSize;

    @Attribute(name = "cParm")
    private double cParm;

    public ThresholdAdaptive(@Attribute(name = "adaptiveMethod") AdaptiveMethod adaptiveMethod,
                             @Attribute(name = "invert") boolean invert,
                             @Attribute(name = "blockSize") int blockSize,
                             @Attribute(name = "cParm") double cParm) {
        this.adaptiveMethod = adaptiveMethod;
        this.invert = invert;
        this.blockSize = ensureOdd(blockSize);
        this.cParm = cParm;
    }

    private int ensureOdd(int value) {
        return (value % 2 == 0) ? value + 1 : value;
    }

    public void process(CvPipeline pipeline) {
        Mat image = pipeline.getWorkingImage();
        int thresholdType = invert ? Imgproc.THRESH_BINARY_INV : Imgproc.THRESH_BINARY;
        Imgproc.adaptiveThreshold(image, image, 255, adaptiveMethod.getValue(), thresholdType, blockSize, cParm);
    }
}

