public:
    /// solution: Using DP and backtracking see if we have already
    /// generated perimeters with the side lengths of the current array
    /// an utility function which takes a vector of integers,
    /// MaX is used to keep the max perimeter you can get from the
    /// current set side lengths
    int dp(const vector<int>& nums, int MaX, vector<int>& which, int start)
    {
        /// if you get to the end of the arr of sides in nums,
        /// check the length of the current longest side length
        /// and the Max perimeter to see if you can get these sides
        /// through backtracking
        if (start == nums.size())
        {
            /// if you have reached the end of the array look at
            /// the max you can get from current set of
            /// side numbers
            return MaX;
        }
        /// for all squres on each side
        for (int i = 0; i < nums.size() - start; i++)
        {
            int nextMax = MaX;
            /// look at all the possible adjacent pairs on each side
            for (int j = i+1 ; j <= i + nums[start]; j++)
            {
                /// check if this pair is either in the current set of
                /// sides nums and are not greater by more than the
                /// Max perimeter
                if (nums[start] != nums[j])
                    which[j] = MAX(which[j], nums[j]);
              sort(which.begin(), which.end());
            }

            /// template is the side lengths for the n sides in nums
            /// a summary containing the sides in percentage of numeric side lengths
            /// n sides (each a percentage of num range 0-1)
            n = nums[start];
            int edge[n];
            edge(edge);
            int summary[n];
            int tc = 0;
            int tot = 0;
            for (int j=0; j<n; ++j)
            {
                  tc = tc + which[j];
                  if (tc > MAX) break;
                  edge[j] = nums[j];
                  tot = tot + edge[j];
            }
            if (tc > MAX || 2*nextMax < ans)
              ans = MAX;
            else
              ans = dp(nums, MAXX, which, start + 1);
        }
    }
}

