public class Floyd {
    public static void main(String[] args){
        printTriangle(5);
        printTriangle(14);
    }
 
    private static void printTriangle(int n){
        System.out.println(n + " rows:");
        for(int rowNum = 1, printMe = 1, numsPrinted = 0;
                rowNum <= n; printMe++){
            int cols = (int)Math.ceil(Math.log10(n*(n-1)/2 + numsPrinted + 2));
            System.out.printf("%"+cols+"d ", printMe);
            if(++numsPrinted == rowNum){
                System.out.println();
                rowNum++;
                numsPrinted = 0;
            }
        }
    }
}

import java.util.*;
import org.biopax.paxtools.model.*;
import org.biopax.paxtools.query.*;
import org.biopax.paxtools.query.algorithm.Direction;

public Set<BioPAXElement> getCommonUpDownElements(Set<BioPAXElement> sourceSet, Model model, Direction direction, int limit, Set<Filter> filters) {
    Set<BioPAXElement> result = new HashSet<>();

    QueryExecutor executor = QueryExecutors.getCorrectQueryExecutor(model);
    Query query = executor.createQuery();
    query.addSeed(sourceSet);

    if (filters != null) {
        for (Filter filter : filters) {
            query.addFilter(filter);
        }
    }

    if (direction.equals(Direction.UPSTREAM)) {
        query.setLimit(limit);
        result.addAll(executor.execute(query, model).getUpstreamNodes());
    } else if (direction.equals(Direction.DOWNSTREAM)) {
        query.setLimit(limit);
        result.addAll(executor.execute(query, model).getDownstreamNodes());
    } else {
        throw new IllegalArgumentException("Invalid direction specified. Please specify either 'UPSTREAM' or 'DOWNSTREAM'");
    }

    return result;
}

