def minElements(nums, limit, goal):
    current_sum = sum(nums)
    difference = goal - current_sum

    # Calculate the minimum number of elements needed
    # Use ceiling division to ensure we round up if there's a remainder
    if difference > 0:
        return (difference + limit - 1) // limit  # Equivalent to math.ceil(difference / limit)
    else:
        return (-difference + limit - 1) // limit  # Equivalent to math.ceil(-difference / limit)

# Example usage:
# Example 1
print(minElements([1, -1, 1], 3, -4))  # Output: 2

# Example 2
print(minElements([1, -10, 9, 1], 100, 0))  # Output: 1

