import java.util.Arrays;

public class dm {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int p = scanner.nextInt();

        int[][] weapons = new int[n][2];
        int[][] armorSets = new int[m][2];

        int[][] dp = new int[n + 1][m + 1];

        for (int i = 0; i < n; i++) {
            weapons[i][0] = scanner.nextInt();
            weapons[i][1] = scanner.nextInt();
        }

        for (int i = 0; i < m; i++) {
            armorSets[i][0] = scanner.nextInt();
            armorSets[i][1] = scanner.nextInt();
        }

        for (int i = 0; i < p; i++) {
            int x = scanner.nextInt();
            int y = scanner.nextInt();
            int z = scanner.nextInt();

            for (int j = n; j >= weapons[i][0]; j--) {
                for (int k = m; k >= armorSets[i][0]; k--) {
                    dp[j][k] = Math.max(dp[j][k], dp[j - weapons[i][0]][k - armorSets[i][0]] + z);
                }
            }
        }

        System.out.println(dp[n][m]);
    }
}

