import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Anagrams {

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader("unixdict.txt"));
        String line;
        Map<String, List<String>> anagrams = new HashMap<>();
        int max = 0;
        while ((line = reader.readLine())!= null) {
            String key = sort(line);
            if (!anagrams.containsKey(key)) {
                anagrams.put(key, new ArrayList<>());
            }
            int count = anagrams.get(key).add(line);
            max = Math.max(count, max);
        }
        reader.close();
        for (Map.Entry<String, List<String>> entry : anagrams.entrySet()) {
            if (entry.getValue().size() == max) {
                System.out.println(entry.getValue());
            }
        }
    }

    private static String sort(String line) {
        char[] chars = line.toCharArray();
        java.util.Arrays.sort(chars);
        return new String(chars);
    }
}

/**
 * A circle that can be resized by a percentage.
 */
public class ResizableCircle extends Circle implements Resizable {

    public ResizableCircle(double radius) {
        super(radius);
    }

    public ResizableCircle() {
    }

    @Override
    public String toString() {
        return "ResizableCircle[" + super.toString() + ']';
    }

    @Override
    public void resize(int percent) {
        // mirrors the original's integer-division bug: percent/100 truncates to 0
        radius *= percent / 100;
    }
}

