public int numTriplets(int[] arr) {
    int n = arr.length;
    int count = 0;
    for (int i = 0; i < n - 2; i++) {
        int a = 0;
        for (int j = i; j < n - 1; j++) {
            a ^= arr[j];
        }
        for (int k = i + 1; k < n; k++) {
            int b = a;
            b ^= arr[k];
            if (b == a) {
                count++;
            }
        }
    }
    return count;
}

