class Validator {
    public long interchangeableRectangles(int[][] rectangles) {
        Map<Double, Integer> counts = new HashMap<>();

        for (int[] rectangle : rectangles) {
            double ratio = (rectangle[0] * 1.0) / (rectangle[1] * 1.0);
            counts.put(ratio, counts.getOrDefault(ratio, 0) + 1);
        }

        long res = 0l;
        for (double ratio : counts.keySet()) {
            if (counts.get(ratio) > 1) {
                for (int i = 1; i < counts.get(ratio); i++) {
                    res += i;
                }
            }
        }

        return res;
    }
}

