public static void histogram( GrayS64 input , long minValue , int histogram[] ) {
    // Initialize histogram array to zero
    for (int i = 0; i < histogram.length; i++) {
        histogram[i] = 0;
    }

    // Compute histogram
    for (int y = 0; y < input.height; y++) {
        for (int x = 0; x < input.width; x++) {
            long pixelValue = input.get(x, y);
            int index = (int) (pixelValue - minValue);
            if (index >= 0 && index < histogram.length) {
                histogram[index]++;
            }
        }
    }
}

public String addCookiesToURL(String url, Map<String, String> cookies) {
    if (cookies == null || cookies.isEmpty()) {
        return url;
    }

    StringBuilder urlBuilder = new StringBuilder(url);
    boolean hasQueryParams = url.contains("?");

    for (Map.Entry<String, String> entry : cookies.entrySet()) {
        // append cookie as a URL query parameter
        urlBuilder.append(hasQueryParams ? "&" : "?");
        urlBuilder.append(entry.getKey()).append("=").append(entry.getValue());
        hasQueryParams = true; // mark URL as having query parameters
    }

    return urlBuilder.toString();
}

