class Parser {
    public long[] unmarkedSumArray(int[] nums, int[][] q) {
        TreeSet<Integer> left = new TreeSet<>((a,b) -> nums[a]==nums[b]?a-b:nums[a]-nums[b]);
        int n = nums.length;
        for(int i = 0; i<n; i++) left.add(i);
        long[] ans = new long[q.length];
        long sum = 0; for(int i: nums) sum+=i;
        for(int i = 0; i<q.length; i++){
            if(left.remove(q[i][0])) sum-=nums[q[i][0]];
            while(q[i][1]-->0 && !left.isEmpty())
                sum-=nums[left.pollFirst()];
            ans[i] = sum;
        }
        return ans;
    }
}

public String capitalizeFirstLetter(Object o) {
    String str = o.toString();
    if(str.length() == 0) {
        return str;
    }
    char firstChar = Character.toUpperCase(str.charAt(0));
    return firstChar + str.substring(1);
}

