/**
 */
public class MeetingResource extends ServerResource {

  final private static Logger logger = LoggerFactory.getLogger(MeetingResource.class);

  final private LeanBeanDao dao = new LeanBeanJpaDao();

  @Get("json")
  public MeetingViewTO findMeetingById() {
    String hash = getRequestAttributes().get("meeting-id").toString();
    long meetingId = LeanBeanUtil.idDecode(hash);
    return findMeetingById(meetingId);
  }

  public MeetingViewTO findMeetingById(long meetingId) {
    if(meetingId < 0) {
      // If the hash cannot be decoded to an integer, no need to check the database
      getResponse().setStatus(Status.CLIENT_ERROR_NOT_FOUND);
      throw new ResourceException(Status.CLIENT_ERROR_NOT_FOUND);
    }

    Meeting meeting = dao.findByMeetingId(meetingId);
    try {
      dao.close();
    } catch (Exception e) {
      logger.debug(e.getMessage());
    }

    if (meeting == null) {
      // No meeting with decoded id found in the database
      getResponse().setStatus(Status.CLIENT_ERROR_NOT_FOUND);
      throw new ResourceException(Status.CLIENT_ERROR_NOT_FOUND);
    }
    MeetingViewTO meetingViewTO = DAO2DTOMapper.mapMeeting(meeting);

    return meetingViewTO;
  }

  @Post("json")
  public MeetingViewTO addMeeting(MeetingTO meetingTO) {
    Meeting meeting = DTO2DAOMapper.mapMeeting(meetingTO);
    logger.info("Meeting: " + meeting.getTitle() + ", Device: " + meeting.getDevice().getId());
    try {
      dao.addMeeting(meeting);
      getResponse().setStatus(Status.SUCCESS_CREATED);
    } catch (Exception e) {
      logger.debug(e.getMessage());
      throw new ResourceException(Status.CLIENT_ERROR_BAD_REQUEST, e.getMessage(), e);
    } finally {
      try {
        dao.close();
      } catch (Exception e) {
        logger.error(e.getMessage());
      }
    }

    return DAO2DTOMapper.mapMeeting(meeting);
  }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.IntStream;

public class MultiplicativeDigitalRoot {

    public static void main(String[] args) {
        System.out.println("Number: (MP, MDR)\n======  ==========");
        for (int n : new int[]{123321, 7739, 893, 899998}) {
            System.out.printf("%6d: %s\n", n, mdroot(n));
        }

        Map<Integer, List<Integer>> table = new HashMap<>();
        for (int i = 0; i < 10; i++) {
            table.put(i, new ArrayList<>());
        }
        int n = 0;
        while (table.values().stream().mapToInt(List::size).min().getAsInt() < 5) {
            int[] mdroot = mdroot(n);
            table.get(mdroot[1]).add(n);
            n++;
        }
        System.out.println("\nMP: [n0..n4]\n==  =========");
        table.entrySet().stream().sorted((e1, e2) -> e1.getKey() - e2.getKey()).forEach(e -> {
            System.out.printf("%2d: %s\n", e.getKey(), e.getValue().stream().limit(5).collect(Collectors.toList()));
        });
    }

    private static int[] mdroot(int n) {
        List<Integer> mdr = new ArrayList<>();
        mdr.add(n);
        while (mdr.get(mdr.size() - 1) > 9) {
            mdr.add(mdr.get(mdr.size() - 1).toString().chars().map(Character::getNumericValue).reduce(1, (a, b) -> a * b));
        }
        return new int[]{mdr.size() - 1, mdr.get(mdr.size() - 1)};
    }
}

