public class Writer {
    public int smallestFactorization(int num) {
       if (num < 2) return num;
        int[] arr = new int[10];
        int count = 0;
        for (int i = 9; i > 1; i--) {
            while (num % i == 0) {
                num /= i;
                arr[count++] = i;
            }
        }
        if (num > 1) return 0;
        long res = 0;
        for (int i = count - 1; i >= 0; i--) {
            res = res * 10 + arr[i];
            if (res > Integer.MAX_VALUE) return 0;
        }
        return (int) res;
    }
}

