        try {
            db = factory.getDatabase();
            // Parameterized SQL command to insert key-value pair using a specified cluster
            String sql = "INSERT INTO " + DatabaseClasses.LINK_COLLECTION + " CLUSTER " + cluster + " SET key = ?, value = ?";
            // Execute the command with provided parameters
            db.command(new OCommandSQL(sql)).execute(key, value);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (db != null) {
                db.close();
            }
        }
    }

    // Retrieves all records from a specified cluster and populates the given map
    public void fillMap(Map<String, String> map, String cluster) {
        ODatabaseDocumentTx db = null;
        try {
            db = factory.getDatabase();
            // SQL command to select key-value pairs from the specified cluster
            String sql = "SELECT key, value FROM " + DatabaseClasses.LINK_COLLECTION + " CLUSTER " + cluster;
            List<ODocument> results = db.query(new OCommandSQL(sql));
            // Iterate over query results and populate the local map
            for (ODocument doc : results) {
                String k = doc.field("key");
                String v = doc.field("value");
                map.put(k, v);
            }
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (db != null) {
                db.close();
            }
        }
    }

