import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableSet;
import com.google.common.collect.Sets;

import javax.annotation.Nullable;
import java.util.Collection;
import java.util.Collections;
import java.util.Objects;
import java.util.Set;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public final class TcSets {

    private TcSets() {
        throw new UnsupportedOperationException("Utility class cannot be instantiated");
    }

    /**
     * Creates an immutable set from the given collection
     *
     * @param collection source collection
     * @param <T> type of elements
     * @return immutable set
     */
    public static <T> ImmutableSet<T> immutableSet(@Nullable Collection<T> collection) {
        if (collection == null || collection.isEmpty()) {
            return ImmutableSet.of();
        }
        return ImmutableSet.copyOf(collection);
    }

    /**
     * Creates an immutable set without specific elements
     *
     * @param collection source collection
     * @param excludeElements elements to exclude
     * @param <T> type of elements
     * @return immutable set without specified elements
     */
    @SafeVarargs
    public static <T> ImmutableSet<T> immutableSetWithout(
            @Nullable Collection<T> collection,
            @Nullable T... excludeElements
    ) {
        if (collection == null || collection.isEmpty()) {
            return ImmutableSet.of();
        }

        if (excludeElements == null || excludeElements.length == 0) {
            return ImmutableSet.copyOf(collection);
        }

        Set<T> excludeSet = Sets.newHashSet(excludeElements);
        return collection.stream()
                .filter(element -> !excludeSet.contains(element))
                .collect(ImmutableSet.toImmutableSet());
    }

    /**
     * Creates an immutable set with elements matching a predicate
     *
     * @param collection source collection
     * @param predicate filtering predicate
     * @param <T> type of elements
     * @return immutable set matching predicate
     */
    public static <T> ImmutableSet<T> immutableSetWithFilter(
            @Nullable Collection<T> collection,
            @Nullable Predicate<T> predicate
    ) {
        if (collection == null || collection.isEmpty() || predicate == null) {
            return ImmutableSet.of();
        }

        return collection.stream()
                .filter(Objects::nonNull)
                .filter(predicate)
                .collect(ImmutableSet.toImmutableSet());
    }

