import java.io.*;

import java.util.*;

public class Parser {

  static int T;

  public static void main(String[] args) throws IOException {

    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

    PrintWriter pw = new PrintWriter(System.out);

    StringTokenizer st = new StringTokenizer(br.readLine());

    T = Integer.parseInt(st.nextToken());

    for (int t = 0; t < T; t++) {

      st = new StringTokenizer(br.readLine());

      int a = Integer.parseInt(st.nextToken());

      int b = Integer.parseInt(st.nextToken());

      int c = Integer.parseInt(st.nextToken());

      if(a == b  && b == c){

        for(int i = 0; i<3; i++) pw.print(1 + " ");

        continue;

      }

      int[] arr =  {a,b,c};

      int max = Math.max(a, Math.max(b,c));

      int cnt = 0;

      for(int i = 0; i<3;i++) {

        if(arr[i] == max) cnt++;

      }

      for(int i = 0; i<3; i++){

        if(arr[i] == max){

          if(cnt == 2) arr[i] = 1;

          else arr[i] = 0;

        }

        else arr[i] = max - arr[i] + 1;

      }

      for(int i: arr) pw.print(i + " ");

      pw.println();

    }

    pw.close();

  }

}

import org.apache.directory.api.i18n.I18n;
import org.apache.directory.api.ldap.model.entry.Value;
import org.apache.directory.api.ldap.model.exception.LdapException;
import org.apache.directory.api.ldap.model.exception.LdapInvalidAttributeValueException;
import org.apache.directory.api.ldap.model.schema.Normalizer;
import org.apache.directory.api.ldap.model.schema.SchemaConstants;
import org.apache.directory.api.ldap.model.schema.options.StringType;
import org.apache.directory.api.util.StringConstants;
import org.apache.directory.api.util.Strings;
import java.io.IOException;

/**
 * A normalizer for NumericString.
 *
 */
public class NumericNormalizer extends Normalizer {

  /**
   * Serial version UID
   */
  private static final long serialVersionUID = 2L;

  /**
   * Creates a new instance of NumericNormalizer.
   */
  public NumericNormalizer() {
    super(SchemaConstants.NUMERIC_STRING_MATCH_MR_OID);
  }

  /**
   * {@inheritDoc}
   */
  @Override
  public Value<?> normalize(Value<?> value) throws LdapException {
    if (value.isHumanReadable()) {
      return new Value(normalize(value.getString()));
    } else {
      return value;
    }
  }

  /**
   * {@inheritDoc}
   */
  @Override
  public String normalize(String value) throws LdapException {
    if (Strings.isEmpty(value)) {
      return StringConstants.EMPTY;
    }

    try {
      return Strings.normalize(value, StringType.NUMERIC_STRING);
    } catch (IOException ioe) {
      String msg = I18n.err(I18n.ERR_13776_CANNOT_NORMALIZE_NUMERIC_STRING, value);
      LdapInvalidAttributeValueException liave =
          new LdapInvalidAttributeValueException(msg, ioe);
      liave.setResolvedName(getOid());

      throw liave;
    }
  }
}

public class Tax {
    private int filingStatus;
    private int[][] brackets;
    private double[] rates;
    private double taxableIncome;

    public static final int SINGLE_FILER = 0;
    public static final int MARRIED_JOINTLY_OR_QUALIFYING_WIDOW = 1;
    public static final int MARRIED_SEPARATELY = 2;
    public static final int HEAD_OF_HOUSEHOLD = 3;

    public Tax() {
    }

    public Tax(int filingStatus, int[][] brackets, double[] rates, double taxableIncome) {
        this.filingStatus = filingStatus;
        this.brackets = brackets;
        this.rates = rates;
        this.taxableIncome = taxableIncome;
    }

    public int getFilingStatus() {
        return filingStatus;
    }

    public void setFilingStatus(int filingStatus) {
        this.filingStatus = filingStatus;
    }

    public int[][] getBrackets() {
        return brackets;
    }

    public void setBrackets(int[][] brackets) {
        this.brackets = brackets;
    }

    public double[] getRates() {
        return rates;
    }

    public void setRates(double[] rates) {
        this.rates = rates;
    }

    public double getTaxableIncome() {
        return taxableIncome;
    }

    public void setTaxableIncome(double taxableIncome) {
        this.taxableIncome = taxableIncome;
    }

    public double getTax() {
        double tax = 0.0;
        int i;
        for (i = 0; i < brackets[filingStatus].length; i++) {
            if (taxableIncome <= brackets[filingStatus][i]) {
                break;
            }
        }
        if (i == 0) {
            tax = taxableIncome * rates[i];
        } else {
            tax = brackets[filingStatus][i - 1] * rates[i - 1];
            tax += (taxableIncome - brackets[filingStatus][i - 1]) * rates[i];
        }
        return tax;
    }
}

