public class BlackjackKarte {

    // Attribute der Karte
    private int kartenId;
    private int wert;
    private String farbe;
    private String rangWort;

    // Konstruktor: Initialisiert eine Karte basierend auf der eindeutigen Karten-ID (0-51)
    public BlackjackKarte(int kartenId) {
        this.kartenId = kartenId;
        // Berechne und setze Kartenwerte bei Erstellung
        this.wert = berechneWert(kartenId);
        this.farbe = bestimmeFarbe(kartenId);
        this.rangWort = bestimmeRang(kartenId);
    }

    // Berechnet den Zahlenwert der Karte für Blackjack
    // Numerische Karten: face value, Bube, Dame, König: 10, Ass: 11
    private int berechneWert(int id) {
        int rang = id % 13; // Ermittelt den Rang 0-12
        if (rang == 0) {
            // Ass wird traditionell als 11 im Blackjack gewertet
            return 11;
        } else if (rang >= 10) {
            // Bube (10), Dame (11) und König (12) haben den Wert 10
            return 10;
        } else {
            // Karten 2 bis 10: rang+1, da rang 1 für 2 steht
            return rang + 1;
        }
    }

    // Bestimmt die Farbe (Suit) der Karte
    // 0-12: Karo, 13-25: Herz, 26-38: Pik, 39-51: Kreuz
    private String bestimmeFarbe(int id) {
        int farbenIndex = id / 13;
        switch (farbenIndex) {
            case 0:
                return "Karo";
            case 1:
                return "Herz";
            case 2:
                return "Pik";
            case 3:
                return "Kreuz";
            default:
                return "Unbekannt";
        }
    }

    // Wandelt den numerischen Rang in einen textbasierten Rang um
    private String bestimmeRang(int id) {
        int rang = id % 13;
        switch (rang) {
            case 0:
                return "Ass";
            case 1:
                return "Zwei";
            case 2:
                return "Drei";
            case 3:
                return "Vier";
            case 4:
                return "Fünf";
            case 5:
                return "Sechs";
            case 6:
                return "Sieben";
            case 7:
                return "Acht";
            case 8:
                return "Neun";
            case 9:
                return "Zehn";
            case 10:
                return "Bube";
            case 11:
                return "Dame";
            case 12:
                return "König";
            default:
                return "Unbekannt";
        }
    }

    // Accessor-Methoden

    // Gibt die eindeutige Karten-ID zurück

import java.util.Scanner;

public class EnBuyukOrtakBolen {

    // Iki sayinin en buyuk ortak bolenini hesaplayan metod
    public static int ebob(int a, int b) {
        // b sifir ise a geri don
        if (b == 0)
            return a;
        // Aksi halde, ebob(b, a % b) olarak tekrar cagirilir
        return ebob(b, a % b);
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);
        System.out.print("Ebobu bulmak icin bir sayi girin: ");
        int sayi1 = sc.nextInt();
        System.out.print("Ebob bulmak icin bir sayi daha girin: ");
        int sayi2 = sc.nextInt();
        sc.close();

        // En buyuk ortak boleni hesaplamak icin ebob metodu cagrilir
        int sonuc = ebob(sayi1, sayi2);
        // Sonuc ekrana yazdirilir
        System.out.print("En buyuk ortak bolen: " + sonuc);
    }
}

