                new Item("note-case", 22, 80),
                new Item("sunglasses", 7, 20),
                new Item("towel", 18, 12),
                new Item("socks", 4, 50),
                new Item("book", 30, 10)
        );
        List<Item> bagged = max(anycomb(items), Knapsack::totalvalue);
        System.out.println("Bagged the following items\n  " +
                bagged.stream().map(Item::getName).collect(Collectors.joining("\n  ")));
        int val = totalvalue(bagged);
        int wt = bagged.stream().mapToInt(Item::getWeight).sum();
        System.out.println("for a total value of " + val + " and a total weight of " + wt);
    }
 
    private static <T> List<T> max(List<List<T>> lists, Comparator<List<T>> comparator) {
        return lists.stream().max(comparator).get();
    }
 
    private static List<List<Item>> anycomb(List<Item> items) {
        return IntStream.rangeClosed(1, items.size())
               .flatMapToObj(r -> combinations(items, r))
               .collect(Collectors.toList());
    }
 
