        List<T> tail = items.subList(1, items.size());
        return Stream.concat(

import java.util.*;

public class Cache {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        double[][] arrTwoDim = new double[2][5];
        System.out.println("To input a two dimensional array, input: 5 floating point numbers now: ");

        for (int i = 0; i < 5; i++) {
            arrTwoDim[0][i] = in.nextDouble();
        }

        System.out.println("Input more 5 floating point numbers now: ");

        for (int i = 0; i < 5; i++) {
            arrTwoDim[1][i] = in.nextDouble();
        }

        System.out.println("The largest is located at " + Arrays.toString(locateLargest(arrTwoDim)));

    }

    public static int[] locateLargest(double[][] a) {
        int[] largeIdx = new int[2];
        double largest = Double.MIN_VALUE;

        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a[i].length; j++) {
                if (a[i][j] > largest) {
                    largest = a[i][j];
                    largeIdx[0] = i;
                    largeIdx[1] = j;
                }
            }
        }
        return largeIdx;
    }
}

class Reader {
    public int minimumOperationsToMakeEqual(int x, int y) {
        int ls=-2;
        Set<Integer> visi= new HashSet<>();
        Queue<int[]> queue = new LinkedList<>();

        visi.add(x);
        ls++;
 queue.offer(new int[]{x, 0});
        while (!queue.isEmpty()) {
            int[] cur = queue.poll();
            int op = cur[1];
            int val = cur[0];

            if (val == y) {
                return op;
            }

            if (!visi.contains(val + 1)) {
                queue.offer(new int[]{val + 1, op + 1});
                visi.add(val + 1);
            }

            if (!visi.contains(val - 1)) {
                queue.offer(new int[]{val - 1, op + 1});
                visi.add(val - 1);
            }

            if (val % 5 == 0 && !visi.contains(val / 5)) {
                queue.offer(new int[]{val / 5, op + 1});
                visi.add(val / 5);
            }

            if (val % 11 == 0 && !visi.contains(val / 11)) {
                queue.offer(new int[]{val / 11, op + 1});
                visi.add(val / 11);
            }
        }

        return -1;

    }
}

import java.util.Scanner;

public class SortNumbers {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter three numbers
        System.out.print("Enter three numbers: ");
        double num1 = input.nextDouble();
        double num2 = input.nextDouble();
        double num3 = input.nextDouble();

        // Display the numbers in increasing order
        displaySortedNumbers(num1, num2, num3);
    }

    public static void displaySortedNumbers(double num1, double num2, double num3) {
        double temp;
        if (num2 < num1 && num2 < num3) {
            temp = num1;
            num1 = num2;
            num2 = temp;
        } else if (num3 < num1 && num3 < num2) {
            temp = num1;
            num1 = num3;
            num3 = temp;
        }
        if (num3 < num2) {
            temp = num2;
            num2 = num3;
            num3 = temp;
        }
        System.out.println(num1 + " " + num2 + " " + num3);
    }
}

import java.net.URI;

/**
 * Interface for a file browser component.
 * Defines essential operations for interacting with files and directories.
 */
public interface FileBrowser {

    /**
     * Sets the current path within the file system.
     *
     * @param path The new path to set.
     * @throws IllegalArgumentException if the path is invalid or inaccessible.
     */
    void setPath(URI path) throws IllegalArgumentException;

    /**
     * Gets the current path within the file system.
     *
     * @return The current path.
     */
    URI getPath();

    /**
     * Selects a specific file by its name within the current directory.
     *
     * @param fileName The name of the file to select.
     * @throws IllegalArgumentException if the file does not exist in the current directory.
     */
    void setSelected(String fileName) throws IllegalArgumentException;

    /**
     * Gets the name of the currently selected file.
     *
     * @return The name of the selected file, or null if no file is selected.
     */
    String getSelected();

    /**
     * Checks if a file with given name exists in the current directory.
     *
     * @param fileName The name of the file to check.
     * @return True if the file exists, false otherwise.
     */
    boolean exists(String fileName);

    /**
     * Navigates up one level in the directory structure.
     */
    void navigateUp();

    /**
     * Refreshes the current view of the file browser.
     */
    void refresh();

    /**
     * Creates a new directory in the current path.
     * @param directoryName Name of the new directory.
     */
    void createDirectory(String directoryName);
}

