import javafx.application.Application;
import javafx.scene.Scene;
import javafx.scene.layout.GridPane;
import javafx.scene.paint.Color;
import javafx.scene.shape.Rectangle;
import javafx.stage.Stage;

public class Checkerboard extends Application {
    @Override
    public void start(Stage primaryStage) {
        // create a GridPane to hold the rectangles
        GridPane gridPane = new GridPane();

        // set the size of each rectangle
        int rectSize = 50;

        // create the rectangles and add them to the GridPane
        for (int i = 0; i < 8; i++) {
            for (int j = 0; j < 8; j++) {
                Rectangle rect = new Rectangle(rectSize, rectSize);
                rect.setFill((i + j) % 2 == 0 ? Color.WHITE : Color.BLACK);
                gridPane.add(rect, j, i);
            }
        }

        // create a scene and add the GridPane to it
        Scene scene = new Scene(gridPane, rectSize * 8, rectSize * 8);

        // set the title of the stage and show it
        primaryStage.setTitle("Checkerboard");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import org.jooq.DSLContext;
import org.jooq.Field;
import org.jooq.Table;
import org.jooq.impl.DSL;

import java.util.Collection;

public class CommandsManyImpl<Left, Right> {

    private final DSLContext sql;
    private final Table<?> table;
    private final Field<Left> leftField;
    private final Field<Right> rightField;

    public CommandsManyImpl(DSLContext sql, Table<?> table, Field<Left> leftField, Field<Right> rightField) {
        this.sql = sql;
        this.table = table;
        this.leftField = leftField;
        this.rightField = rightField;
    }

    public void setUniversalCondition() {
        throw new UnsupportedOperationException("Setting universal conditions is not supported.");
    }

    public void create(Collection<Left> leftValues, Collection<Right> rightValues) {
        if (leftValues == null || leftValues.isEmpty()) {
            throw new IllegalArgumentException("Left values cannot be null or empty.");
        }
        if (rightValues == null || rightValues.isEmpty()) {
            throw new IllegalArgumentException("Right values cannot be null or empty.");
        }

        for (Left left : leftValues) {
            for (Right right : rightValues) {
                sql.insertInto(table)
                    .set(leftField, left)
                    .set(rightField, right)
                    .execute();
            }
        }
    }

    public void deleteLeft(Collection<Left> leftValues) {
        if (leftValues == null || leftValues.isEmpty()) {
            throw new IllegalArgumentException("Left values cannot be null or empty.");
        }

        sql.deleteFrom(table)
           .where(leftField.in(leftValues))
           .execute();
    }

    public void deleteRight(Collection<Right> rightValues) {
        if (rightValues == null || rightValues.isEmpty()) {
            throw new IllegalArgumentException("Right values cannot be null or empty.");
        }

        sql.deleteFrom(table)
           .where(rightField.in(rightValues))
           .execute();
    }
}

import java.io.IOException;
import java.util.Locale;

public class Vector {
    public static void main(String[] args) throws IOException, InterruptedException {
        String url = "https://www.google.com";
        String[] command = getOpenBrowserCommand(url);
        for (String cmd : command) {
            System.out.println(cmd);
        }
    }

    private static String[] getOpenBrowserCommand(String url) throws IOException, InterruptedException {
        String os = System.getProperty("os.name").toLowerCase(Locale.getDefault());
        if (os.contains("win")) {
            return new String[]{"cmd", "/c", "start", url};
        } else if (os.contains("mac")) {
            return new String[]{"open", url};
        } else if (os.contains("nix") || os.contains("nux")) {
            return new String[]{"xdg-open", url};
        } else {
            throw new IOException("Unsupported operating system");
        }
    }
}

