    }

import javafx.application.Application;
import javafx.geometry.Point2D;
import javafx.scene.Scene;
import javafx.scene.canvas.Canvas;
import javafx.scene.canvas.GraphicsContext;
import javafx.scene.layout.BorderPane;
import javafx.scene.paint.Color;
import javafx.stage.Stage;

public class CircleIntersection extends Application {
    private Circle circle1 = new Circle(new Point2D(100, 100), 50);
    private Circle circle2 = new Circle(new Point2D(200, 200), 50);
    private Canvas canvas;

    public void start(Stage primaryStage) {
        BorderPane root = new BorderPane();
        canvas = new Canvas(400, 400);
        root.setCenter(canvas);

        drawCircles();

        canvas.setOnMousePressed(event -> {
            if (circle1.contains(event.getX(), event.getY())) {
                circle1.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            } else if (circle2.contains(event.getX(), event.getY())) {
                circle2.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            }
        });

        canvas.setOnMouseDragged(event -> {
            if (circle1.contains(event.getX(), event.getY())) {
                circle1.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            } else if (circle2.contains(event.getX(), event.getY())) {
                circle2.setCenter(new Point2D(event.getX(), event.getY()));
                drawCircles();
            }
        });

        Scene scene = new Scene(root, 400, 400);
        primaryStage.setScene(scene);
        primaryStage.show();
    }

    private void drawCircles() {
        GraphicsContext gc = canvas.getGraphicsContext2D();
        gc.clearRect(0, 0, canvas.getWidth(), canvas.getHeight());

        if (circle1.intersects(circle2)) {
            gc.setFill(Color.RED);
        } else {
            gc.setFill(Color.GREEN);
        }
        gc.fillOval(circle1.getCenter().getX() - circle1.getRadius(), circle1.getCenter().getY() - circle1.getRadius(),
                circle1.getRadius() * 2, circle1.getRadius() * 2);

        if (circle2.intersects(circle1)) {
            gc.setFill(Color.RED);
        } else {
            gc.setFill(Color.GREEN);
        }
        gc.fillOval(circle2.getCenter().getX() - circle2.getRadius(), circle2.getCenter().getY() - circle2.getRadius(),
                circle2.getRadius() * 2, circle2.getRadius() * 2);
    }

    public static void main(String[] args) {
        launch(args);
    }
}

public class ShortestCommonSuperSequence {
    private static boolean isEmpty(String s) {
        return null == s || s.isEmpty();
    }
 
    private static String scs(String x, String y) {
        if (isEmpty(x)) {
            return y;
        }
        if (isEmpty(y)) {
            return x;
        }
 
        if (x.charAt(0) == y.charAt(0)) {
            return x.charAt(0) + scs(x.substring(1), y.substring(1));
        }
 
        if (scs(x, y.substring(1)).length() <= scs(x.substring(1), y).length()) {
            return y.charAt(0) + scs(x, y.substring(1));
        } else {
            return x.charAt(0) + scs(x.substring(1), y);
        }
    }
 
    public static void main(String[] args) {
        System.out.println(scs("abcbdab", "bdcaba"));
    }
}

class Writer {
    public boolean checkPalindromeFormation(String a, String b) {
        int n = a.length();
        if(isPalindrome(a) || isPalindrome(b)) return true;
        boolean[] boo = new boolean[n];
        boolean[] boob = new boolean[n];
        if(n%2==1){
            boo[n/2] = true;
            boob[n/2] = true;
        }
        for(int i = n/2 -1; i>=0; i--){
                if(a.charAt(i) == a.charAt(n-i-1)) boo[i] = boo[n-i-1] = true;
                else break;
            }
        for(int i = n/2 -1; i>=0; i--){
                if(b.charAt(i) == b.charAt(n-i-1)) boob[i] = boob[n-i-1] = true;
                else break;
            }

        int i = 0;
        for(i = 0; i < n/2; i++){
            if(a.charAt(i) != b.charAt(n-1-i)){
                if(boo[i] || boob[i]) return true;
                break;
            }
        }
        //System.out.println(i);
        if(i >= (n/2)) return true;
        for(i = 0; i < n/2; i++){
            if(b.charAt(i) != a.charAt(n-1-i)) {
                if(boo[i] || boob[i]) return true;
                break;
            }

        }
        //System.out.println(i);
        if(i >= (n/2)) return true;
        return false;
    }

    public boolean isPalindrome(String s){
        StringBuilder sb = new StringBuilder(s);
        return s.equals(sb.reverse().toString());
    }
}

/**
 * A cylinder that both extends Circle (its own top face) and composes
 * a Circle as its base, to contrast composition vs inheritance.
 */
public class Cylinder extends Circle {

    private Circle base;
    private double height = 1.0;

    public Cylinder() {
        this.base = new Circle();
    }

    public Cylinder(double radius) {
        super(radius);
        this.base = new Circle();
    }

    public Cylinder(double radius, String color) {
        super(radius, color);
        this.base = new Circle();
    }

    public Cylinder(double radius, double height) {
        super(radius);
        this.base = new Circle();
        this.height = height;
    }

    public Cylinder(double radius, double height, String color) {
        super(radius, color);
        this.height = height;
        this.base = new Circle();
    }

    public Cylinder(double radius1, String color1, double radius2, String color2) {
        super(radius1, color1);
        this.base = new Circle(radius2, color2);
    }

    public Cylinder(double height, double radius1, String color1, double radius2, String color2) {
        super(radius1, color1);
        this.height = height;
        this.base = new Circle(radius2, color2);
    }

    public Cylinder(double radius1, String color1, double radius2, String color2, double height) {
        super(radius1, color1);
        this.height = height;
        this.base = new Circle(radius2, color2);
    }

    public double getHeight() {
        return height;
    }

    public void setHeight(double height) {
        this.height = height;
    }

    public double getVolume() {
        return getArea() * height;
    }

    public Circle getBase() {
        return base;
    }

    public void setBase(Circle base) {
        this.base = base;
    }

    @Override
    public String toString() {
        return "Cylinder[" + "circle=" + super.toString() + "" + "base=" + base + ", height=" + height + '}';
    }
}

