import java.util.*;
import java.io.*;

public class Parser {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null ||!st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }

    public static void main(String[] args) {
        FastReader input = new FastReader();
        int T = input.nextInt();
        while (T-- > 0) {
            solve(input);
        }
    }

    public static void solve(FastReader input) {
        int n = input.nextInt();
        int[] c = new int[n];
        for (int i = 0; i < n; i++) {
            c[i] = input.nextInt();
        }

        int[] ans = new int[n];
        int cnt = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (c[i] == 0) {
                ans[i] = 0;
            } else {
                ans[i] = 1;
                cnt++;
                if (cnt == c[i]) {
                    cnt = 0;
                } else {
                    cnt = c[i] - cnt;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.print(ans[i] + " ");
        }
        System.out.println();
    }
}

import java.net.URL;
import org.deegree.db.ConnectionProvider;
import org.deegree.db.ConnectionProviderProvider;
import org.deegree.workspace.ResourceLocation;
import org.deegree.workspace.Workspace;
import org.deegree.workspace.ResourceMetadata;
import org.deegree.workspace.ResourceMetadataBuilder;

public class SpringConnectionProviderProvider extends ConnectionProviderProvider {

    private static final String CONFIG_NS = "http://www.deegree.org/datasource/spring";
    private static final String CONFIG_SCHEMA = "/META-INF/schemas/datasource/spring/3.4.0/spring.xsd";

    @Override
    public String getNamespace() {
        return CONFIG_NS;
    }

    @Override
    public ResourceMetadata<ConnectionProvider> createFromLocation(Workspace workspace,
            ResourceLocation<ConnectionProvider> location) {
        return new ResourceMetadataBuilder<ConnectionProvider>(location, this, workspace)
                .build();
    }

    @Override
    public URL getSchema() {
        return SpringConnectionProviderProvider.class.getResource(CONFIG_SCHEMA);
    }

    @Override
    public ResourceMetadata<ConnectionProvider> createMetadata(Workspace workspace,
            ResourceLocation<ConnectionProvider> location) {
        return createFromLocation(workspace, location);
    }

    @Override
    public ConnectionProvider create(ResourceMetadata<ConnectionProvider> metadata) {
        return new SpringConnectionProvider(metadata);
    }

    @Override
    public Class<ConnectionProvider> getResourceType() {
        return ConnectionProvider.class;
    }

    @Override
    public boolean supports(ResourceLocation<ConnectionProvider> location) {
        return location.getIdentifier().getNamespace().equals(CONFIG_NS);
    }

    @Override
    public String getResourceName() {
        return "Spring Connection Provider";
    }

    @Override
    public String getResourceDescription() {
        return "A connection provider that integrates with Spring for database connections.";
    }
}

