import java.util.*;

public class Helper {
    public static void main(String[] args) {

        LinkedHashSet<String> names1 = new LinkedHashSet<>(); // Creates a LinkedHashSet object with a default capacity
        // of 16
        LinkedHashSet<String> names2 = new LinkedHashSet<>(); // and default load factor of 0.75

        names1.add("George");
        names1.add("Jim");
        names1.add("John");
        names1.add("Blake");
        names1.add("Kevin");
        names1.add("Michael");

        names2.add("George");
        names2.add("Katie");
        names2.add("Kevin");
        names2.add("Michelle");
        names2.add("Ryan");

        LinkedHashSet<String> lhs1 = new LinkedHashSet<>();
        lhs1.addAll(names1);

        LinkedHashSet<String> lhs2 = new LinkedHashSet<>();
        lhs2.addAll(names2);

        // The union is a combination of all unique values from both sets
        names1.addAll(names2);
        System.out.println("Union is: " + names1);

        // The intersection is only the values occur in both sets
        LinkedHashSet<String> copyNames1 = new LinkedHashSet<String>(lhs1);
        copyNames1.retainAll(names2);
        System.out.println("Intersection is: " + copyNames1);

        // The difference is the union excluding common values
        names1.removeAll(copyNames1);
        System.out.println("Difference is: " + names1);

    }

}

@SuppressWarnings("unchecked")
    void cleanup(Ringbuffer ringbuffer) {
        if (ringbuffer.headSequence() > ringbuffer.tailSequence()) {
            return;
        }
        long now = currentTimeMillis();
        while (ringbuffer.headSequence() <= ringbuffer.tailSequence()) {
            final long headSequence = ringbuffer.headSequence();
            if (ringExpirationMs[toIndex(headSequence)] > now) {
                return;
            }

            ringbuffer.set(headSequence, null);

            ringbuffer.setHeadSequence(ringbuffer.headSequence() + 1);
        }
    }

class Parser {
    public int[] corpFlightBookings(int[][] bookings, int n) {
        int[] temp = new int[n+1];
        int[] ans = new int[n];
        for (int i=0;i<bookings.length;i++){
            temp[bookings[i][0]-1] +=  bookings[i][2];
            temp[bookings[i][1]] -=  bookings[i][2];
        }
        int now = 0;
        for (int i=0;i<n;i++){

            now = now + temp[i];
            ans[i] = now;
        }
        return ans;
    }
}

