 * and its associated child records by mapping the respective SQL column identifiers for key propagation.
 */
public class InsertRelationshipManager {

    // Represents the parent record for the insertion.
    private InsertionRecord parentRecord;

    // Configuration defining how key values are propagated from parent to children.
    private KeyPropagationConfig keyPropagationConfig;

    // Mapping between child records and their associated foreign key SQL column identifiers.
    private Map<InsertionRecord, String> childColumnMapping;

    /**
     * Constructor to initialize the parent record and its key propagation configuration.
     *
     * @param parentRecord         The parent insertion record.
     * @param keyPropagationConfig The configuration for propagating keys.
     */
    public InsertRelationshipManager(InsertionRecord parentRecord, KeyPropagationConfig keyPropagationConfig) {
        this.parentRecord = parentRecord;
        this.keyPropagationConfig = keyPropagationConfig;
        this.childColumnMapping = new HashMap<>();
    }

    /**
     * Retrieves the parent insertion record.
     *
     * @return The parent InsertionRecord.
     */
    public InsertionRecord getParentRecord() {
        return this.parentRecord;
    }

    /**
     * Retrieves the key propagation configuration.
     *
     * @return The KeyPropagationConfig object.
     */
    public KeyPropagationConfig getKeyPropagationConfig() {
        return this.keyPropagationConfig;
    }

    /**
     * Adds a reference between a child record and the SQL column identifier where the foreign key will reside.
     *
     * @param childRecord        The child insertion record.
     * @param sqlColumnIdentifier The SQL column identifier for the foreign key.
     */
    public void addChildReference(InsertionRecord childRecord, String sqlColumnIdentifier) {
        if (childRecord == null || sqlColumnIdentifier == null) {
            throw new IllegalArgumentException("Child record and SQL column identifier cannot be null");
        }
        childColumnMapping.put(childRecord, sqlColumnIdentifier);
    }

    /**
     * Checks if a specific child record is already referenced for key propagation.
     *
     * @param childRecord The child insertion record.
