    public boolean isChildReferenced(InsertionRecord childRecord) {

class Library {
    public double mincostToHireWorkers(int[] quality, int[] wage, int k) {
        int len = quality.length;
        double[][] rate = new double[len][2];
        for (int i = 0; i< len; i++) {
            rate[i] = new double[]{((double) wage[i])/quality[i], (double) quality[i]};
        }
        Arrays.sort(rate, (a,b)->a[0]-b[0]>0? 1:-1);
        Queue<Double> pq = new PriorityQueue<>((a,b)->b-a>0? 1:-1);
        int sum = 0;
        double min = Double.MAX_VALUE;
        for (int i = 0; i<k;i++) {
            sum+=rate[i][1];
            pq.offer(rate[i][1]);
        }
        min = Math.min(min, sum * rate[k-1][0]);
        for (int i = k; i<len; i++) {
            if (rate[i][1] < pq.peek()) {
                sum += rate[i][1]-pq.poll();
                pq.offer(rate[i][1]);
                min = Math.min(min, sum * rate[i][0]);
            }
        }
        return min;
    }
}

public:
    int getMinimumFuelCost(vector<vector<int>>& triangle) {
        int len = triangle.size();
        // dp, dpprev
        // i 表示第 i 层的总节点数
        vector<int> dp(len, 0);
        vector<int> dp_prev(len, 0);

        for (int i = 1; i < len; ++i) {
            for (int j = 0; j <= i; ++j) {
                if (i == 1) {
                    dp[j] = triangle[1][j] + dp_prev[j];
                } else {
                    dp[j] = min(triangle[i - 1][j] + dp_prev[j],
                                 triangle[i - 1][j + 1] + dp_prev[j + 1]) +
                             triangle[i][j];
                }
            }
            swap(dp, dp_prev);
        }

        return dp_prev[0];
    }
};

