public:
    int getMinimumFuelCost(vector<vector<int>>& triangle) {
        int size = triangle.size();
        v[0].push_back(0);

        // k 代表 1 阶， 2 阶，，n 阶的变换即可。
        for (int i = size - 2; i >= 0; i--) {
            int len = v[i].size();
            for (int j = 0; j < len; ++j) {
                int val = triangle[i + 1][j];
                if (j > 0) val += v[i][j - 1];
                if (j < len - 1) val += v[i][j];

                v[i + 1].push_back(min(val, v[i + 1][j]));
            }
        }
        return v[size - 1][size - 1];
    }

private:
    vector<vector<int>> v;
};

