import java.io.*;
 
public class Multifactorial {
 
   public static final int HIGHEST_DEGREE = 5;
   public static final int LARGEST_NUMBER = 10;
 
   /* Recursive implementation of multifactorial function */
   public static int multifact(int n, int deg){
      return n <= deg? n : n * multifact(n - deg, deg);
   }
 
   /* Iterative implementation of multifactorial function */
   public static int multifact_i(int n, int deg){
      int result = n;
      while (n >= deg + 1){
         result *= (n - deg);
         n -= deg;
      }
      return result;
   }
 
   /* Test function to print out multifactorials */
   public static void main(String[] args) throws IOException{
      int i, j;
      for (i = 1; i <= HIGHEST_DEGREE; i++){
         System.out.print("\nDegree " + i + ": ");
         for (j = 1; j <= LARGEST_NUMBER; j++){
            System.out.print(multifact(j, i) + " ");
         }
      }
   }
}

