class Parser {
    List<Integer> [] adj;
    int [] subTreeSun;

    public int componentValue(int[] nodes, int[][] edges) {
        int n = nodes.length;
        int totalSum = 0;
        int minNode = Integer.MAX_VALUE;
        adj = new ArrayList[n];
        subTreeSun = new int[n];

        for (int i = 0; i < n; i++){
            adj[i] = new ArrayList<>();
            totalSum+=nodes[i];
            minNode = Math.min(minNode, nodes[i]);
        }

        for (int[] edge:edges) {
            int a = edge[0];
            int b = edge[1];
            adj[a].add(b);
            adj[b].add(a);
        }
        List<Integer> factors = calculateFactors(totalSum, minNode);
        factors.forEach(System.out::println);
        dfsSubTreeSum(0, -1, nodes);
        System.out.println(Arrays.toString(subTreeSun));

        int ans =0;
        for (int fact: factors) {
            int count = dfsCountComponents(0, -1, fact);
            if(count * fact==totalSum){
                ans = count;
                break;
            }
        }
        return ans==0?0:ans-1;
    }

    public int dfsCountComponents(int node, int parent, int factor) {

        if(subTreeSun[node]==factor) return 1;
        int totalComponents =0;
        for (int val:adj[node]) {
            if(val==parent)continue;
            totalComponents+=dfsCountComponents(val, node, factor);
        }
        if(subTreeSun[node] - factor*totalComponents == factor) totalComponents++;
        return totalComponents;
    }

    public List<Integer> calculateFactors(int totalSum, int minNode) {
        List<Integer> factors = new ArrayList<>();
        while (minNode <= totalSum/2){
            if(totalSum%minNode==0) factors.add(minNode);
            minNode++;
        }
        return factors;
    }

    public void dfsSubTreeSum(int node, int parent, int[] nodes) {
        subTreeSun[node] = nodes[node];
        for(int child:adj[node]){
            if(child==parent)continue;
            dfsSubTreeSum(child, node, nodes);
            subTreeSun[node] += subTreeSun[child];
        }
    }

}

