import org.apache.ignite.IgniteCheckedException;
import org.apache.ignite.internal.pagemem.PageMemory;
import org.apache.ignite.internal.processors.cache.database.tree.io.DataPageIO;

import java.nio.ByteBuffer;

/**
 * WAL record for data page insert fragment.
 */
public class DataPageInsertFragmentRecord {
    private long pageId;
    private byte[] payload;
    private long lastLink;

    public DataPageInsertFragmentRecord(long pageId, byte[] payload, long lastLink) {
        this.pageId = pageId;
        this.payload = payload;
        this.lastLink = lastLink;
    }

    /**
     * @return Page ID.
     */
    public long pageId() {
        return pageId;
    }

    /**
     * @return Payload.
     */
    public byte[] payload() {
        return payload;
    }

    /**
     * @return Last link.
     */
    public long lastLink() {
        return lastLink;
    }

    /**
     * Applies delta to the page.
     *
     * @param pageMem Page memory.
     * @param pageAddr Page address.
     * @throws IgniteCheckedException If failed.
     */
    public void applyDelta(PageMemory pageMem, long pageAddr) throws IgniteCheckedException {
        ByteBuffer buf = pageMem.pageBuffer(pageAddr);

        DataPageIO io = DataPageIO.VERSIONS.latest();

        io.appendData(pageMem, pageAddr, buf, payload, lastLink);
    }

    /**
     * @return Record type.
     */
    public byte type() {
        return (byte) 10; // Example type
    }

    /**
     * @return Payload size.
     */
    public int payloadSize() {
        return payload.length;
    }

    @Override public String toString() {
        return "DataPageInsertFragmentRecord{" +
            "pageId=" + pageId +
            ", payloadSize=" + (payload == null ? 0 : payload.length) +
            ", lastLink=" + lastLink +
            '}';
    }
}

