        out.close();

    }

    public static void solve(FastReader f, PrintWriter out, int pre[][]) {

        int l = f.nextInt();

        int r = f.nextInt();

        int len = maxSetBit(r);

        int ans = Integer.MAX_VALUE;

        for(int i = 0; i < len; i++) {

            int count = pre[r][i] - pre[l-1][i];

            ans = min(ans, count);

        }

        out.println(ans);

    }

    public static int maxSetBit(int n) {

        int ans = 0;

        while(n > 0) {

            n >>= 1;

            ans++;

        }

        return ans;

    }

