public static <T> Gather<T> dropWhile(Predicate<? super T> predicate, Gather<T> gather) {
    Objects.requireNonNull(predicate);
    Objects.requireNonNull(gather);

    return new AbstractGather<T>() {
        private boolean dropped = false;
        @Override
        protected boolean tryAdvance(GatherAction<? super T> action) throws Throwable {
            while (!dropped && gather.tryAdvance(elem -> {
                if (!predicate.test(elem)) {
                    dropped = true;
                    action.accept(elem);
                }
            }));
            return dropped && gather.tryAdvance(action);
        }

        @Override
        protected void forEachRemaining(GatherAction<? super T> action) throws Throwable {
            if (!dropped) {
                dropped = true;
                gather.forEachRemaining(elem -> {
                    if (!predicate.test(elem)) {
                        dropped = true;
                        action.accept(elem);
                    }
                });
            }
            if (dropped) {
                gather.forEachRemaining(action);
            }
        }

        @Override
        public Spliterator<T> spliterator() {
            return new Spliterators.AbstractSpliterator<T>(gather.estimateSize(), 0) {
                private boolean dropped = false;
                final Spliterator<T> s = gather.spliterator();
                @Override
                public boolean tryAdvance(Consumer<? super T> action) {
                    while (!dropped && s.tryAdvance(elem -> {
                        if (!predicate.test(elem)) {
                            dropped = true;
                            action.accept(elem);
                        }
                    }));
                    return dropped && s.tryAdvance(action);
                }

                @Override
                public void forEachRemaining(Consumer<? super T> action) {
                    if (!dropped) {
                        dropped = true;
                        s.forEachRemaining(elem -> {
                            if (!predicate.test(elem)) {
                                dropped = true;
                                action.accept(elem);
                            }
                        });
                    }
                    if (dropped) {
                        s.forEachRemaining(action);
                    }
                }
            };
        }
    };
}

import java.util.LinkedList;
import java.util.List;

/**
 * Description of media constraints for {@code MediaStream} and
 * {@code PeerConnection}.
 */
public class MediaConstraints {
  /** Simple String key/value pair. */
  public static class KeyValuePair {
    private final String key;
    private final String value;

    public KeyValuePair(String key, String value) {
      this.key = key;
      this.value = value;
    }

    public String getKey() {
      return key;
    }

    public String getValue() {
      return value;
    }

    public String toString() {
      return key + ": " + value;
    }
  }

  public final List<KeyValuePair> mandatory;
  public final List<KeyValuePair> optional;

  public MediaConstraints() {
    mandatory = new LinkedList<KeyValuePair>();
    optional = new LinkedList<KeyValuePair>();
  }

  private static String stringifyKeyValuePairList(List<KeyValuePair> list) {
    StringBuilder builder = new StringBuilder("[");
    for (KeyValuePair pair : list) {
      if (builder.length() > 1) {
        builder.append(", ");
      }
      builder.append(pair.toString());
    }
    return builder.append("]").toString();
  }

  public String toString() {
    return "mandatory: " + stringifyKeyValuePairList(mandatory) +
        ", optional: " + stringifyKeyValuePairList(optional);
  }
}

