class Thread1 extends Thread {
    Display objd;

    Thread1(Display objd) {
        this.objd = objd;
    }

    public void run() {
        int n = 5;
        long fact = 1;
        for (int i = 1; i <= n; i++) {
            fact = fact * i;
        }
        objd.disp("Factorial of " + n + " is: " + fact + " Thread: " + Thread.currentThread().getName());
    }
}

class Thread2 extends Thread {
    Display objd;

    Thread2(Display objd) {
        this.objd = objd;
    }

    public void run() {
        int n = 10;
        int a = 0, b = 1, c;
        for (int i = 0; i < n; i++) {
            c = a + b;
            a = b;
            b = c;
        }
        objd.disp("Fibonacci number at position " + n + " is: " + a + " Thread: " + Thread.currentThread().getName());
    }
}

class Thread3 extends Thread {
    Display objd;

    Thread3(Display objd) {
        this.objd = objd;
    }

    public void run() {
        int arr[] = {5, 1, 4, 2, 8};
        int n = arr.length;

        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    // swap arr[j+1] and arr[j]
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }

        String sortedArray = "Sorted array: ";
        for (int i = 0; i < n; i++) {
            sortedArray += arr[i] + " ";
        }

        objd.disp(sortedArray + " Thread: " + Thread.currentThread().getName());
    }
}

public class ThreadDemo {
    public static void main(String[] args) {
        Display objd = new Display();

        Thread1 t1 = new Thread1(objd);
        Thread2 t2 = new Thread2(objd);
        Thread3 t3 = new Thread3(objd);

        t1.setName("FactorialThread");
        t2.setName("FibonacciThread");
        t3.setName("SortingThread");

        t1.start();
        t2.start();
        t3.start();

        try {
            t1.join();
            t2.join();
            t3.join();
        } catch (InterruptedException e) {
            System.out.println("Interrupted Exception caught");
        }

        System.out.println("All threads completed. Main thread exiting.");
    }
}

