import java.util.ArrayList;
import java.util.Hashtable;
import java.util.List;
import java.util.Random;

public class BayesNetNode {
    private String variable;
    private List<BayesNetNode> parents;
    private List<BayesNetNode> children;
    private Hashtable<String, Double> distribution;
    private Random randomGenerator;

    public BayesNetNode(String variableName) {
        this.variable = variableName;
        this.parents = new ArrayList<>();
        this.children = new ArrayList<>();
        this.distribution = new Hashtable<>();
        this.randomGenerator = new Random();
    }

    public void influencedBy(BayesNetNode parentNode) {
        if (!parents.contains(parentNode)) {
            parents.add(parentNode);
            parentNode.addChild(this);
        }
    }

    private void addChild(BayesNetNode childNode) {
        if (!children.contains(childNode)) {
            children.add(childNode);
        }
    }

    public void setProbability(String configuration, double probability) {
        distribution.put(configuration, probability);
    }

    public double probabilityOf(boolean value, List<Boolean> parentValues) {
        String configuration = convertToConfiguration(value, parentValues);
        return distribution.getOrDefault(configuration, 0.0);
    }

    private String convertToConfiguration(boolean value, List<Boolean> parentValues) {
        StringBuilder config = new StringBuilder(value ? "T" : "F");
        for (Boolean parentValue : parentValues) {
            config.append(parentValue ? "T" : "F");
        }
        return config.toString();
    }

    public boolean isTrueFor(List<Boolean> parentStates) {
        double randomValue = randomGenerator.nextDouble();
        double trueProb = probabilityOf(true, parentStates);
        return randomValue <= trueProb;
    }

    public boolean sample() {
        if (parents.isEmpty()) {
            return randomGenerator.nextDouble() <= distribution.getOrDefault("T", 0.5);
        }

        List<Boolean> parentValues = new ArrayList<>();
        for (BayesNetNode parent : parents) {
            parentValues.add(parent.sample());
        }

        return isTrueFor(parentValues);
    }

    public List<BayesNetNode> getParents() {
        return new ArrayList<>(parents);
    }

    public List<BayesNetNode> getChildren() {
        return new ArrayList<>(children);
    }

    public String getVariable() {
        return variable;
    }

    public void clearRelationships() {
        parents.clear();
        children.clear();
        distribution.clear();
    }

