public int[] solution(int[] arr) {
    int[] answer = new int[arr.length];
    if(arr[arr.length - 1] >= arr[arr.length - 2]) {
        answer[arr.length - 1] = (2 * arr[arr.length - 1]);
    } else {
        answer[arr.length - 1] = arr[arr.length - 1];
    }
    for(int i = 0; i < arr.length - 2; i++) {
        if((arr[i] >= arr[i + 1]) && (arr[i] >= arr[i + 2])) {
            answer[i] = (arr[i] + (2 * arr[i + 2]));
        } else {
            answer[i] = arr[i];
        }
        if((arr[i + 1] >= arr[i + 2]) && (arr[i + 1] >= arr[i + 3])) {
                answer[i + 1] = (arr[i + 1] + (2 * arr[i + 3]));
        } else {
            answer[i + 1] = arr[i + 1];
        }
        if((arr[i + 2] >= arr[i + 3]) && (arr[i + 2] >= arr[i + 4])) {
            answer[i + 2] = (arr[i + 2] + (2 * arr[i + 4]));
        } else {
            answer[i + 2] = arr[i + 2];
        }
    }
    return answer;
}
}

