import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.BufferedReader;
import java.io.IOException;
import java.io.UnsupportedEncodingException;
import java.util.Hashtable;

public class LangBundle {
    private Hashtable<String, String> wordMap;
    private Hashtable<String, String> defaultMap;
    private Comcraft cc;

    public LangBundle(Comcraft cc) {
        this.cc = cc;
        wordMap = new Hashtable<>();
        defaultMap = new Hashtable<>();
    }

    public void setDefaultMap(String fileName) {
        loadMap(fileName, defaultMap);
    }

    public void loadBundle(String fileName) {
        wordMap.clear();
        loadMap(fileName, wordMap);
    }

    private void loadMap(String fileName, Hashtable<String, String> map) {
        try (InputStream is = cc.getResourceAsStream(fileName);
             InputStreamReader isr = new InputStreamReader(is, "UTF-8");
             BufferedReader br = new BufferedReader(isr)) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split("=", 2);
                if (parts.length == 2) {
                    map.put(parts[0].trim(), parts[1].trim());
                }
            }
        } catch (UnsupportedEncodingException e) {
            System.err.println("Unsupported encoding: " + e.getMessage());
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

    public String getText(String key) {
        String text = wordMap.get(key);
        if (text != null) {
            return text;
        }
        text = defaultMap.get(key);
        if (text != null) {
            return text;
        }
        return "???";
    }

    public static void main(String[] args) {
        Comcraft cc = new Comcraft();
        LangBundle langBundle = new LangBundle(cc);

        // Load default language map
        langBundle.setDefaultMap("lang/default.lang");

        // Load current language map
        langBundle.loadBundle("lang/en_US.lang");

        // Retrieve translations
        System.out.println(langBundle.getText("greeting")); // Output: Hello
        System.out.println(langBundle.getText("farewell")); // Output: Goodbye
        System.out.println(langBundle.getText("unknown_key")); // Output: ???
    }
}

class Comcraft {
    public InputStream getResourceAsStream(String fileName) {
        return getClass().getClassLoader().getResourceAsStream(fileName);
    }
}

@Override
    public void permissionDenied(final ProtectionDomain pd, final Permission perm) {
        if (filePermissionToSkip.equals(perm)) {
            return;
        }
        final CodeSource codeSource = pd.getCodeSource();
        Set<Permission> permSet = missingPermissions.get(codeSource);
        if (permSet == null) {
            synchronized (missingPermissions) {
                permSet = missingPermissions.get(codeSource);
                if (permSet == null) {
                    permSet = Collections.synchronizedSet(new TreeSet<Permission>(new PermissionComparator()));
                    missingPermissions.put(codeSource, permSet);
                }
            }
        }
        if (permSet.add(perm)) {
            AccessController.doPrivileged(WRITE_TO_FILE_ACTION);
        }
    }

import java.util.*;

public class Handler {

    public static double[][] sortColumns(double[][] m) {
        double[][] sorted = new double[m.length][m.length];

        for (int i = 0; i < sorted.length; i++) {
            for (int j = 0; j < sorted[i].length; j++) {
                sorted[i][j] = m[i][j];
            }
        }

        for (int col = 0; col < sorted.length; col++) {
            boolean keepSorting = true;
            while (keepSorting) {
                keepSorting = false;
                for (int row = 0; row < sorted[col].length - 1; row++) {
                    if (sorted[row][col] < sorted[row + 1][col]) {
                        keepSorting = true;
                        double temp = sorted[row][col];
                        sorted[row][col] = sorted[row + 1][col];
                        sorted[row + 1][col] = temp;
                    }

                }
            }
        }
        return sorted;

    }
}

