        fahrenheit = 77.0;
        celsius = TemperatureConverter.fahrenheitToCelsius(fahrenheit);
        System.out.println(fahrenheit + " Fahrenheit is equal to " + celsius + " Celsius");
    }
}

class Builder {
    public int minimumXORSum(int[] nums1, int[] nums2) {
        return sln1(nums1, nums2);
    }

    private int sln1(int[] nums1, int[] nums2){
        int n = nums1.length;
        return dfs(nums1,nums2, 0, 0, n, new Integer[n][1<<n]);
    }

    private int dfs(int[] nums1, int[] nums2, int curr, int mask, int n, Integer[][] dp){
        if(curr == n) return 0;
        int min = Integer.MAX_VALUE;
        if(dp[curr][mask]!=null) return dp[curr][mask];
        for(int i = 0;i< n;i++){
            if(((mask>>i)&1)==1) continue;
            min = Math.min(min, dfs(nums1, nums2, curr+1, mask|(1<<i), n, dp) + (nums1[curr]^nums2[i]));
        }
        dp[curr][mask] = min;
        //System.out.printf("%d %d %d\n", curr, mask, min);
        return min;
    }
}

public synchronized <T> T load(final PluggableService<T> service, final String providerName) throws ProviderLoaderException {
    try {
