public static <E extends Comparable<E>> void mergeSort(E[] list) {
    if (list.length > 1) {
        // Split the array into two sub-arrays
        int mid = list.length / 2;
        E[] left = Arrays.copyOfRange(list, 0, mid);
        E[] right = Arrays.copyOfRange(list, mid, list.length);

        // Recursively sort the sub-arrays
        mergeSort(left);
        mergeSort(right);

        // Merge the sorted sub-arrays
        merge(left, right, list);
    }
}

private static <E extends Comparable<E>> void merge(E[] left, E[] right, E[] list) {
    int i = 0; // Index of left sub-array
    int j = 0; // Index of right sub-array
    int k = 0; // Index of merged array

    while (i < left.length && j < right.length) {
        if (left[i].compareTo(right[j]) <= 0) {
            list[k++] = left[i++];
        } else {
            list[k++] = right[j++];
        }
    }

    // Copy remaining elements from left sub-array (if any)
    while (i < left.length) {
        list[k++] = left[i++];
    }

    // Copy remaining elements from right sub-array (if any)
    while (j < right.length) {
        list[k++] = right[j++];
    }
}

public static <E> void mergeSort(E[] list, Comparator<? super E> comparator) {
    if (list.length > 1) {
        // Split the array into two sub-arrays
        int mid = list.length / 2;
        E[] left = Arrays.copyOfRange(list, 0, mid);
        E[] right = Arrays.copyOfRange(list, mid, list.length);

        // Recursively sort the sub-arrays
        mergeSort(left, comparator);
        mergeSort(right, comparator);

        // Merge the sorted sub-arrays
        merge(left, right, list, comparator);
    }
}

private static <E> void merge(E[] left, E[] right, E[] list, Comparator<? super E> comparator) {
    int i = 0; // Index of left sub-array
    int j = 0; // Index of right sub-array
    int k = 0; // Index of merged array

    while (i < left.length && j < right.length) {
        if (comparator.compare(left[i], right[j]) <= 0) {
            list[k++] = left[i++];
        } else {
            list[k++] = right[j++];
        }
    }

    // Copy remaining elements from left sub-array (if any)
    while (i < left.length) {
        list[k++] = left[i++];
    }

    // Copy remaining elements from right sub-array (if any)
    while (j < right.length) {
        list[k++] = right[j++];
    }
}

@JsonRpcService("/iwxxm-validation")
public class IwxxmWebServiceImpl implements IwxxmValidationService {

    private static final Logger logger = LoggerFactory.getLogger(IwxxmWebServiceImpl.class);
    private final IwxxmValidator validator;
    private final ValidationConfigurationManager configManager;

    @Autowired
    public IwxxmWebServiceImpl(IwxxmValidator validator, ValidationConfigurationManager configManager) {
        this.validator = Preconditions.checkNotNull(validator, "Validator cannot be null");
        this.configManager = Preconditions.checkNotNull(configManager, "Configuration manager cannot be null");
    }

    @Override
    @JsonRpcMethod("validate")
    public ValidationResponse validate(ValidationRequest request) {
        try {
            checkRequestVersion(request);

            ValidationResult result = validator.validate(
                request.getContent(),
                request.getVersion(),
                configManager.getRulesForVersion(request.getVersion())
            );

            return buildValidationResponse(result);
        } catch (ValidationException e) {
            logger.error("Validation process failed", e);
            return ValidationResponse.builder()
                .status(ValidationStatus.ERROR)
                .addError(createSystemError(e))
                .build();
        }
    }

    private void checkRequestVersion(ValidationRequest request) throws ValidationException {
        Preconditions.checkArgument(
            configManager.isSupportedVersion(request.getVersion()),
            "Unsupported IWXXM version: %s",
            request.getVersion()
        );
    }

    private ValidationResponse buildValidationResponse(ValidationResult result) {
        ValidationResponse.Builder responseBuilder = ValidationResponse.builder()
            .status(result.isValid() ? ValidationStatus.VALID : ValidationStatus.INVALID)
            .processingTime(result.getProcessingDuration());

        if (!result.isValid()) {
            result.getErrors().forEach(responseBuilder::addError);
        }

        return responseBuilder.build();
    }

    private ValidationError createSystemError(Exception e) {
        return ValidationError.builder()
            .type(ErrorType.SYSTEM)
            .message(e.getMessage())
            .build();
    }
}

public boolean moveToWaitingRoom(Path path) throws IOException {

    if (!path.isAbsolute()) path = new Path(dfs.getWorkingDirectory(), path);

    if (!dfs.exists(path)) throw new FileNotFoundException(path.toString());

    String qPath = path.makeQualified(dfs).toString();
    if (qPath.startsWith(WR.toString())) return false;

    if (WR.toString().startsWith(qPath)) {
      throw new IOException("Can't delete " + path +
                        " as it contains the waiting room directory.");
    }
    String fName = path.getName();
    Path baseWRPath = getWaitingRoomPath(path.getParent());

    Stack<Path> parentDirs = new Stack<Path>();
    do {
      parentDirs.push(baseWRPath);
      baseWRPath = baseWRPath.getParent();
    } while (baseWRPath != null);
    while (!parentDirs.empty()) {
      baseWRPath = parentDirs.pop();

      for (int i = 0; dfs.exists(baseWRPath) && !dfs.getFileStatus(baseWRPath).isDir(); i++) {
        baseWRPath = new Path(baseWRPath.toString() + ".WR" + i);
      }
      if (!dfs.mkdirs(baseWRPath, PERMISSION)) {
        LOG.warn("Couldn't create base dir path in waiting room for " + baseWRPath);
        return false;
      }
    }

    Path myWRPath = new Path(baseWRPath.toString(), fName);
    for (int i = 0; dfs.exists(myWRPath); i++) {
      myWRPath = new Path(myWRPath.toString() + ".WR" + i);
    }
    if (dfs.rename(path, myWRPath)) return true;
    return false;
  }

public Object fromStream(final byte[] iStream) throws IOException {
        if (iStream == null || iStream.length == 0)

            return null;

        final ORecordInternal<?> obj = Orient.instance().getRecordFactoryManager().newInstance();

        final ORID rid = new ORecordId().fromStream(iStream);

        obj.setIdentity(rid.getClusterId(), rid.getClusterPosition());
        return obj;
    }

import java.math.BigInteger;

public class SquareNumbers {
    public static void main(String[] args) {
        BigInteger max = BigInteger.valueOf(Long.MAX_VALUE);
        BigInteger low = BigInteger.valueOf(1);
        BigInteger high = max.sqrt();

        for (int i = 0; i < 10; i++) {
            BigInteger mid = (low.add(high)).shiftRight(1);
            BigInteger square = mid.multiply(mid);

            if (square.compareTo(max) > 0) {
                System.out.println(square);
                low = mid.add(BigInteger.ONE);
            } else {
                high = mid.subtract(BigInteger.ONE);
            }
        }
    }
}

