public class PrimeNumbers {
    public static void main(String[] args) {
        StackOfIntegers stack = new StackOfIntegers();
        for (int i = 2; i < 120; i++) {
            if (isPrime(i)) {
                stack.push(i);
            }
        }
        System.out.println("Prime numbers less than 120 in decreasing order:");
        while (!stack.isEmpty()) {
            System.out.print(stack.pop() + " ");
        }
    }

    public static boolean isPrime(int number) {
        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }
        return true;
    }
}

import java.math.BigInteger;

public class Generator {
    public String smallestGoodBase(String n) {
        BigInteger N = new BigInteger(n);
        int maxDigits = N.bitLength() - 1;

        for (int m = maxDigits; m > 1; m--) {
            BigInteger k = N.pow(1, m + 1).subtract(BigInteger.ONE).divide(BigInteger.valueOf(m));
            if (k.compareTo(BigInteger.valueOf(1)) <= 0) continue;
            BigInteger sum = BigInteger.ONE;
            BigInteger current = BigInteger.ONE;
            for (int i = 1; i <= m; i++) {
                current = current.multiply(k);
                sum = sum.add(current);
            }
            if (sum.equals(N)) return k.toString();
        }
        return N.subtract(BigInteger.ONE).toString();
    }
}

private void updateDisplay(boolean allowEmptyDisplay) {
        if (!allowEmptyDisplay && mTypedTimes.isEmpty()) {
            int hour = mTimePicker.getHours();
            int minute = mTimePicker.getMinutes();
            setHour(hour, true);
            setMinute(minute);
            if (!mIs24HourMode) {
                updateAmPmDisplay(hour < 12 ? AM : PM);
            }
            setCurrentItemShowing(mTimePicker.getCurrentItemShowing(), true, true, true);
            mDoneButton.setEnabled(true);
        } else {
            Boolean[] enteredZeros = {false, false};
            int[] values = getEnteredTime(enteredZeros);
            String hourFormat = enteredZeros[0] ? "%02d" : "%2d";
            String minuteFormat = (enteredZeros[1]) ? "%02d" : "%2d";
            String hourStr = (values[0] == -1) ? mDoublePlaceholderText :
                    String.format(hourFormat, values[0]).replace(' ', mPlaceholderText);
            String minuteStr = (values[1] == -1) ? mDoublePlaceholderText :
                    String.format(minuteFormat, values[1]).replace(' ', mPlaceholderText);
            mHourView.setText(hourStr);
            mHourSpaceView.setText(hourStr);
            mHourView.setSelected(false);
            mMinuteView.setText(minuteStr);
            mMinuteSpaceView.setText(minuteStr);
            mMinuteView.setSelected(false);
            if (!mIs24HourMode) {
                updateAmPmDisplay(values[2]);
            }
        }
    }

import java.io.Serializable;
import javax.xml.bind.annotation.XmlAccessType;
import javax.xml.bind.annotation.XmlAccessorType;
import javax.xml.bind.annotation.XmlAttribute;
import javax.xml.bind.annotation.XmlType;
import javax.xml.bind.annotation.XmlValue;

@XmlAccessorType(XmlAccessType.FIELD)
@XmlType(name = "PositionInteractionRangeType", propOrder = {
    "value"
})
public class PositionInteractionRangeType implements Serializable {

    private static final long serialVersionUID = -1L;

    @XmlValue
    protected float value;

    @XmlAttribute(name = "coordinate")
    protected String coordinate;

    @XmlAttribute(name = "bound")
    protected String bound;

    public float getValue() {
        return value;
    }

    public void setValue(float value) {
        this.value = value;
    }

    public String getCoordinate() {
        return coordinate;
    }

    public void setCoordinate(String coordinate) {
        this.coordinate = coordinate;
    }

    public String getBound() {
        return bound;
    }

    public void setBound(String bound) {
        this.bound = bound;
    }

    @Override
    public String toString() {
        return "PositionInteractionRangeType{" +
                "value=" + value +
                ", coordinate='" + coordinate + '\'' +
                ", bound='" + bound + '\'' +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        PositionInteractionRangeType that = (PositionInteractionRangeType) o;

        if (Float.compare(that.value, value) != 0) return false;
        if (coordinate != null ? !coordinate.equals(that.coordinate) : that.coordinate != null) return false;
        return bound != null ? bound.equals(that.bound) : that.bound == null;
    }

    @Override
    public int hashCode() {
        int result = (value != +0.0f ? Float.floatToIntBits(value) : 0);
        result = 31 * result + (coordinate != null ? coordinate.hashCode() : 0);
        result = 31 * result + (bound != null ? bound.hashCode() : 0);
        return result;
    }
}

import java.util.Iterator;
import java.util.List;
import java.util.ListIterator;

import org.jaxen.BaseXPath;
import org.jaxen.FunctionContext;
import org.jaxen.JaxenException;
import org.jaxen.XPathFunctionContext;

/**
 *
 *
 */
class JaxenConnector extends BaseXPath {

    private static final long serialVersionUID = 9025734269448515308L;

    private static FunctionContext functionContext = new XPathFunctionContext(false);

    JaxenConnector(String expression) throws JaxenException {
        super(expression, new JaxenNavigator());
        // possible thread-safety issue????
        this.setFunctionContext(functionContext);
    }

    public List selectNodes(Object expression) throws JaxenException {

        List result = super.selectNodes(expression);
        // Text objects are returned wrapped in a List.
        // We need to unwrap them here.
        ListIterator iterator = result.listIterator();
        while (iterator.hasNext()) {
            Object next = iterator.next();
            if (next instanceof List) {
                List list = (List) next;
                // replace the list with the first item in the list
                iterator.set(list.get(0));
                // insert any subsequent Text objects into the list
                if (list.size() > 1) {
                    Iterator texts = list.listIterator(1);
                    while (texts.hasNext()) {
                        iterator.add(texts.next());
                    }
                }
            }
        }
        return result;

    }

}

