import java.net.InetSocketAddress;
import java.util.Map;
import java.util.Properties;
import java.util.Scanner;
import java.util.function.Predicate;

class Checker {
    private static final String DIRECTORY_PROPERTY_NAME = "controller.data.dir";

    public static void main(String[] args) throws Exception {
        Properties properties = new Properties();
        properties.setProperty(DIRECTORY_PROPERTY_NAME, "./data");

        Configuration config = new Configuration(properties);
        Reaktor reaktor = Reaktor.launch(config, s -> true, s -> true);

        TcpController tcpctl = reaktor.getTcpController();
        HttpController httpctl = reaktor.getHttpController();
        WsController wsctl = reaktor.getWsController();

        tcpctl.bind(8081);
        httpctl.bind(8082);
        wsctl.bind(8080);

        Predicate<String> tcpInitRef = s -> s.startsWith("TCP:");
        Predicate<String> httpInitRef = s -> s.startsWith("HTTP:");
        Predicate<String> wsInitRef = s -> s.startsWith("WS:");

        Predicate<String> wsReplyRef = s -> s.startsWith("ECHO:");
        Predicate<String> httpReplyRef = s -> s.startsWith("HTTP-ECHO:");
        Predicate<String> tcpReplyRef = s -> s.startsWith("TCP-ECHO:");

        tcpctl.route(tcpInitRef, 1000, "WS:", 1000, new InetSocketAddress("localhost", 8080));
        httpctl.route(httpInitRef, 1000, "WS:", 1000, new InetSocketAddress("localhost", 8080));
        wsctl.route(wsInitRef, 1000, "ECHO:", 1000, Map.of());

        wsctl.route(wsReplyRef, 1000, "WS:", 1000, Map.of());
        httpctl.route(httpReplyRef, 1000, "HTTP:", 1000, Map.of());
        tcpctl.route(tcpReplyRef, 1000, "TCP:", 1000, new InetSocketAddress("localhost", 8081));

        System.out.println("Network Controller System is running. Press Enter to stop...");
        Scanner scanner = new Scanner(System.in);
        scanner.nextLine();
        scanner.close();
    }
}

