import org.apache.ignite.IgniteCheckedException;
import org.apache.ignite.internal.pagemem.PageMemory;
import org.apache.ignite.internal.processors.cache.persistence.tree.io.DataPageIO;
import org.apache.ignite.internal.util.typedef.internal.S;

/**
 * Represents a WAL record for inserting a data fragment into a data page.
 */
public class DataPageInsertFragmentRecord extends PageDeltaRecord {
    /** Link to the last fragment in the chain. */
    private final long lastLink;

    /** Payload of the fragment. */
    private final byte[] payload;

    /**
     * Constructor.
     *
     * @param groupId Cache group ID.
     * @param pageId Page ID.
     * @param lastLink Link to the last fragment.
     * @param payload Fragment payload.
     */
    public DataPageInsertFragmentRecord(int groupId, long pageId, long lastLink, byte[] payload) {
        super(groupId, pageId);
        this.lastLink = lastLink;
        this.payload = payload;
    }

    /**
     * Applies the fragment insertion to the specified page.
     *
     * @param pageMem Page memory.
     * @param pageAddr Page address.
     * @throws IgniteCheckedException If the operation fails.
     */
    @Override
    public void applyDelta(PageMemory pageMem, long pageAddr) throws IgniteCheckedException {
        DataPageIO io = DataPageIO.VERSIONS.forPage(pageAddr);

        io.addRowFragment(pageAddr, payload, lastLink, pageMem.realPageSize(groupId()));
    }

    /**
     * Returns the type of this record.
     *
     * @return Record type.
     */
    @Override
    public RecordType type() {
        return RecordType.DATA_PAGE_INSERT_FRAGMENT_RECORD;
    }

    /**
     * Returns the size of the payload.
     *
     * @return Payload size.
     */
    public int payloadSize() {
        return payload.length;
    }

    /**
     * Returns the payload of the fragment.
     *
     * @return Fragment payload.
     */
    public byte[] payload() {
        return payload;
    }

    /**
     * Returns the link to the last fragment.
     *
     * @return Last fragment link.
     */
    public long lastLink() {
        return lastLink;
    }

    @Override
    public String toString() {
        return S.toString(DataPageInsertFragmentRecord.class, this, "super", super.toString());
    }
}

 
public final class ImprovedNoise {
   static public double noise(double x, double y, double z) {
      int X = (int)Math.floor(x) & 255,                  // FIND UNIT CUBE THAT
          Y = (int)Math.floor(y) & 255,                  // CONTAINS POINT.
          Z = (int)Math.floor(z) & 255;
      x -= Math.floor(x);                                // FIND RELATIVE X,Y,Z
      y -= Math.floor(y);                                // OF POINT IN CUBE.
      z -= Math.floor(z);
      double u = fade(x),                                // COMPUTE FADE CURVES
             v = fade(y),                                // FOR EACH OF X,Y,Z.
             w = fade(z);
      int A = p[X  ]+Y, AA = p[A]+Z, AB = p[A+1]+Z,      // HASH COORDINATES OF
          B = p[X+1]+Y, BA = p[B]+Z, BB = p[B+1]+Z;      // THE 8 CUBE CORNERS,
 
      return lerp(w, lerp(v, lerp(u, grad(p[AA  ], x  , y  , z   ),  // AND ADD
                                     grad(p[BA  ], x-1, y  , z   )), // BLENDED
                             lerp(u, grad(p[AB  ], x  , y-1, z   ),  // RESULTS
                                     grad(p[BB  ], x-1, y-1, z   ))),// FROM  8
                     lerp(v, lerp(u, grad(p[AA+1], x  , y  , z-1 ),  // CORNERS
                                     grad(p[BA+1], x-1, y  , z-1 )), // OF CUBE
                             lerp(u, grad(p[AB+1], x  , y-1, z-1 ),
                                     grad(p[BB+1], x-1, y-1, z-1 ))));
   }
   static double fade(double t) { return t * t * t * (t * (t * 6 - 15) + 10); }
   static double lerp(double t, double a, double b) { return a + t * (b - a); }
   static double grad(int hash, double x, double y, double z) {
      int h = hash & 15;                      // CONVERT LO 4 BITS OF HASH CODE
      double u = h<8 ? x : y,                 // INTO 12 GRADIENT DIRECTIONS.
             v = h<4 ? y : h==12||h==14 ? x : z;
      return ((h&1) == 0 ? u : -u) + ((h&2) == 0 ? v : -v);
   }
   static final int p[] = new int[512], permutation[] = { 151,160,137,91,90,15,
   131,13,201,95,96,53,194,233,7,225,140,36,103,30,69,142,8,99,37,240,21,10,23,
   190, 6,148,247,120,234,75,0,26,197,62,94,252,219,203,117,35,11,32,57,177,33,
   88,237,149,56,87,174,20,125,136,171,168, 68,175,74,165,71,134,139,48,27,166,
   77,146,158,231,83,111,229,122,60,211,133,230,220,105,92,41,55,46,245,40,244,
   102,143,54, 65,25,63,161, 1,216,80,73,209,76,132,187,208, 89,18,169,200,196,
   135,130,116,188,159,86,164,100,109,198,173,186, 3,64,52,217,226,250,124,123,
