import com.google.common.collect.ImmutableMap;
import com.google.common.collect.ImmutableList;
import com.dd.plist.NSArray;
import com.dd.plist.NSDictionary;
import com.dd.plist.NSObject;
import com.dd.plist.PropertyListParser;
import com.buck.project.filesystem.ProjectFilesystem;
import com.buck.step.Step;

import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.util.Map;

public class PlistProcessStep extends Step {
    private final String input;
    private final String output;
    private final ImmutableMap<String, NSObject> additionalKeys;
    private final ImmutableMap<String, NSObject> overrideKeys;

    public PlistProcessStep(String input, String output,
                            ImmutableMap<String, NSObject> additionalKeys,
                            ImmutableMap<String, NSObject> overrideKeys) {
        this.input = input;
        this.output = output;
        this.additionalKeys = additionalKeys;
        this.overrideKeys = overrideKeys;
    }

    @Override
    public int execute() {
        try {
            // Read the input plist file
            NSDictionary plistDict = (NSDictionary) PropertyListParser.parse(new File(input));

            // Modify the plist as per additional keys
            for (Map.Entry<String, NSObject> entry : additionalKeys.entrySet()) {
                String key = entry.getKey();
                if (!plistDict.containsKey(key)) {
                    plistDict.put(key, entry.getValue());
                }
            }

            // Override existing keys with new values
            for (Map.Entry<String, NSObject> entry : overrideKeys.entrySet()) {
                plistDict.put(entry.getKey(), entry.getValue());
            }

            // Write the updated plist back to the specified output path
            savePlist(plistDict, output);
            return 0; // Success
        } catch (Exception e) {
            System.err.println("An error occurred while processing the plist: " + e.getMessage());
            return 1; // Error
        }
    }

    private void savePlist(NSDictionary plistDict, String outputPath) {
        try {
            // Serialize the NSDictionary back to XML format
            String xmlString = plistDict.toXMLPropertyList();
            try (FileWriter writer = new FileWriter(new File(outputPath))) {
                writer.write(xmlString);
            }
        } catch (IOException e) {
            System.err.println("Failed to write plist to output: " + e.getMessage());
        }
    }

