import java.util.Random;

public class RastgeleSayiUretme {

    public static void main(String[] args) {

        // Random nesnesi olusturulur
        Random rastgele = new Random();

        // 35'ten kucuk ve buyuk sayilarin sayilari icin sayaclar
        int otuzbesdenkucukler = 0;
        int otuzbesdenbuyukler = 0;

        // 10,000 rastgele sayi uretilecek dongu
        for (int i = 0; i < 10000; i++) {
            // 0 ile 99 arasinda rastgele bir sayi uret
            int sayi = rastgele.nextInt(100);

            // Uretilen sayiyi ekrana yazdir
            System.out.println(sayi + " ");

            // Sayi 35'ten kucukse, sayaci bir artir
            if (sayi < 35) {
                otuzbesdenkucukler++;
            } else {
                // Sayi 35 veya daha buyukse, sayaci bir artir
                otuzbesdenbuyukler++;
            }
        }

        // Sonuclari ekrana yazdir
        System.out.println("\nKucukler: " + otuzbesdenkucukler +
                           " Buyukler: " + otuzbesdenbuyukler);
    }
}

import com.google.common.base.Joiner;
import com.google.common.collect.Iterables;
import eu.the5zig.mod.The5zigAPI;
import eu.the5zig.util.minecraft.ChatColor;
import net.frozenbit.plugin5zig.cubecraft.commands.CommandHandler;
import net.frozenbit.plugin5zig.cubecraft.commands.CommandOutputPrinter;
import net.frozenbit.plugin5zig.cubecraft.commands.UsageException;

import java.util.Iterator;
import java.util.List;

/**
 * Handler for .color
 * Shows help for minecrafts color codes
 */
public class ColorCommandHandler extends CommandHandler {
    public static final Iterable<ChatColor> RAINBOW_IT =
            Iterables.cycle(ChatColor.DARK_RED, ChatColor.RED, ChatColor.GOLD, ChatColor.YELLOW,
                    ChatColor.GREEN, ChatColor.DARK_GREEN, ChatColor.DARK_AQUA, ChatColor.AQUA,
                    ChatColor.BLUE, ChatColor.LIGHT_PURPLE, ChatColor.DARK_PURPLE);

    public ColorCommandHandler() {
        super("color", "Show all color codes", "c");
    }

    @Override
    public void run(String cmd, List<String> args, CommandOutputPrinter printer) throws UsageException {
        if (args.isEmpty()) {
            StringBuilder lineBuf = new StringBuilder();
            for (ChatColor chatColor : ChatColor.values()) {
                lineBuf.append(chatColor)
                        .append(chatColor.getCode())
                        .append(ChatColor.RESET)
                        .append(chatColor == ChatColor.MAGIC ? "(k)" : "")
                        .append(" ");
            }
            printer.println(lineBuf.toString());
        } else {
            String text = Joiner.on(' ').join(args);
            StringBuilder fancy = new StringBuilder();
            Iterator<ChatColor> rainbowColors = RAINBOW_IT.iterator();
            for (char c : text.toCharArray()) {
                if (c != ' ') {
                    fancy.append("&")
                            .append(rainbowColors.next().getCode());
                }
                fancy.append(c);
            }
            The5zigAPI.getAPI().sendPlayerMessage(fancy.toString());
        }
    }

    @Override
    public void printUsage(String cmd, CommandOutputPrinter printer) {
        printer.println(".color - show a cheatsheet of the color codes")
                .println(".color <text> - makes the given text colorful and posts it")
                .println(ChatColor.ITALIC + "Note that only ranked players can use colors on CubeCraft")
                .println("Alias: .c");
    }
}

import java.util.Random;

public class CoinFlip {
    public static void main(String[] args) {
        Random random = new Random();
        int heads = 0;
        int tails = 0;

        for (int i = 0; i < 1000000; i++) {
            if (random.nextBoolean()) {
                heads++;
            } else {
                tails++;
            }
        }

        System.out.printf("Heads: %d%n", heads);
        System.out.printf("Tails: %d%n", tails);
    }
}

/**
 * Contains the elements that define the contents of a playlist.
 * The contents of a playlist are organized within a seq element that is contained within the body element.
 * Typically there is either one seq element that defines a static set of media items and contains media elements,
 * or there is one that defines a dynamic set of media items and contains a smartPlaylist element.
 * <br>
 * Windows Media Player 9 Series or later.
 * @castor.class xml="body"
 */
public class Body
{
    /**
     * The body sequence.
     */
    private Seq _seq = new Seq();

    /**
     * Returns the body sequence.
     * @return a sequence. Shall not be <code>null</code>.
     * @see #setSeq
     * @castor.field
     *  get-method="getSeq"
     *  set-method="setSeq"
     *  required="true"
     * @castor.field-xml
     *  name="seq"
     *  node="element"
     */
    public Seq getSeq()
    {
        return _seq;
    }

    /**
     * Initializes the body sequence.
     * @param seq a sequence. Shall not be <code>null</code>.
     * @throws NullPointerException if <code>seq</code> is <code>null</code>.
     * @see #getSeq
     */
    public void setSeq(final Seq seq)
    {
        if (seq == null)
        {
            throw new NullPointerException("No body sequence");
        }

        _seq = seq;
    }
}

