import org.seedstack.business.internal.BusinessException;
import org.seedstack.seed.testing.junit4.SeedITRunner;

@RunWith(SeedITRunner.class)
public class IdentityServiceIT {

    @Inject
    private IdentityService identityService;

    @Test
    public void identify_entity() {
        MyAggregate myAggregate = new MyAggregate();
        identityService.identify(myAggregate);
        Assertions.assertThat(myAggregate.getId())
                .isNotNull();
    }

    @Test(expected = IdentityExistsException.class)
    public void allready_identify_entity() {
        MyAggregate myAggregate = new MyAggregate(UUID.randomUUID());
        identityService.identify(myAggregate);
        Assertions.fail("no exception occured");
    }

    @Test
    public void identify_entity_with_configuration() {
        MyAggregateWithConfiguration myAggregate = new MyAggregateWithConfiguration();
        identityService.identify(myAggregate);
        Assertions.assertThat(myAggregate.getId())
                .isNotNull();
    }

    @Test
    public void aggregate_with_bad_identity_Management() {
        MyAggregateWithBadIdentityManagement myAggregate = new MyAggregateWithBadIdentityManagement();
        try {
            identityService.identify(myAggregate);
            Assertions.fail("no exception occurred");
        } catch (BusinessException e) {
            Assertions.assertThat(e.getErrorCode())
                    .isEqualTo(BusinessErrorCode.INCOMPATIBLE_IDENTITY_TYPES);
        }
    }

    @Test
    public void aggregate_with_no_identity_Management() {
        MyAggregateWithNoIdentityManagement myAggregate = new MyAggregateWithNoIdentityManagement();
        identityService.identify(myAggregate);
    }
}

import java.io.*;
import java.util.*;
 
public class Hofstadter {
 
    public static int hofstadter(int rlistSize, int slistSize) {
        int n = rlistSize > slistSize? rlistSize : slistSize;
        Vector<Integer> rlist = new Vector<Integer>();
        rlist.add(1);
        rlist.add(3);
        rlist.add(7);
        Vector<Integer> slist = new Vector<Integer>();
        slist.add(2);
        slist.add(4);
        slist.add(5);
        slist.add(6);
        Vector<Integer> list = rlistSize > 0? rlist : slist;
        int target_size = rlistSize > 0? rlistSize : slistSize;
 
        while (list.size() > target_size) {
            list.removeElementAt(list.size() - 1);
        }
 
        while (list.size() < target_size) {
            int lastIndex = rlist.size() - 1;
            int lastr = rlist.get(lastIndex);
            int r = lastr + slist.get(lastIndex);
            rlist.add(r);
            for (int s = lastr + 1; s < r && list.size() < target_size; s++) {
                slist.add(s);
            }
        }
 
        int v = list.get(n - 1);
        return v;
    }
 
    public static void main(String[] args) {
        int v1 = Integer.parseInt(args[0]);
        int v2 = Integer.parseInt(args[1]);
        Set<Integer> r = new TreeSet<Integer>();
        Set<Integer> s = new TreeSet<Integer>();
        for (int n = 1; n <= v2; n++) {
            if (n <= v1) {
                r.add(hofstadter(n, 0));
            }
            s.add(hofstadter(0, n));
        }
        System.out.println("R" + r);
        System.out.println("S" + s);
 
        int m = Math.max(Collections.max(r), Collections.max(s));
        for (int n = 1; n <= m; n++) {
            if (r.contains(n) == s.contains(n)) {
                System.out.println("integer " + n + " either in both or neither set");
            }
        }
    }
}

