import java.io.*;

public class Builder {

    public static void main(String[] args) {
        Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int t = in.nextInt();
        for (int i = 1; i <= t; ++i) {
            int n = in.nextInt();
            int c = in.nextInt();
            int[] a = new int[n];
            for (int j = 0; j < n; ++j) {
                a[j] = in.nextInt();
            }
            int result = solve(n, c, a);
            System.out.println(result);
        }
    }

    private static int solve(int n, int c, int[] a) {
        int[] count = new int[101];
        for (int i = 0; i < n; ++i) {
            count[a[i]]++;
        }
        int result = 0;
        for (int i = 1; i <= 100; ++i) {
            result += Math.min(count[i], c);
        }
        return result;
    }
}

