import java.io.*;
import java.util.*;

public class Stack {
    public static void main(String[] args) throws IOException, ClassNotFoundException {
        // Create array of integers, date object, and double value
        int[] nums = {1, 2, 3, 4, 5};
        Date date = new Date();
        double value = 5.5;

        // Create output stream to write to file
        ObjectOutputStream output = new ObjectOutputStream(new FileOutputStream("Stack.dat"));

        // Write objects to file
        output.writeObject(nums);
        output.writeObject(date);
        output.writeDouble(value);

        // Close output stream
        output.close();

        // Create input stream to read from file
        ObjectInputStream input = new ObjectInputStream(new FileInputStream("Stack.dat"));

        // Read objects from file and print them
        int[] readNums = (int[]) input.readObject();
        Date readDate = (Date) input.readObject();
        double readValue = input.readDouble();

        System.out.println("Array of integers: " + Arrays.toString(readNums));
        System.out.println("Date object: " + readDate);
        System.out.println("Double value: " + readValue);

        // Close input stream
        input.close();
    }
}

public class Logger {
    public int findLHS(int[] nums) {
        HashMap<Integer, Integer> freq=new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if(freq.containsKey(nums[i])){
                freq.put(nums[i], freq.get(nums[i])+1);
            }else {
                freq.put(nums[i], 1);
            }
        }
        int maxF=0;
        for (Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            int n=entry.getKey();
            int tmp=entry.getValue();
            if(freq.containsKey(n+1)){
                tmp+=freq.get(n+1);
                if(maxF<tmp){
                    maxF=tmp;
                }
            }
        }
        return maxF;
    }
}

