import java.util.Arrays;
import java.util.stream.IntStream;
 
public class Ulam {
    public static void generate(int n, int i, char c) {
        if (n <= 1) {
            throw new IllegalArgumentException("n must be > 1");
        }
        String[][] s = new String[n][n];
        for (int j = 0; j < n; j++) {
            Arrays.fill(s[j], "---");
        }
        Direction dir = Direction.RIGHT;
        int y = n / 2;
        int x = n % 2 == 0? y - 1 : y;
        for (int j = i; j <= n * n - 1 + i; j++) {
            s[y][x] = isPrime(j)? (c >= '0' && c <= '9'? String.format("%4d", j) : "  " + c + " ") : " ---";
 
            switch (dir) {
                case RIGHT:
                    if (x <= n - 1 && s[y - 1][x].isEmpty() && j > i) {
                        dir = Direction.UP;
                    }
                    break;
                case UP:
                    if (s[y][x - 1].isEmpty()) {
                        dir = Direction.LEFT;
                    }
                    break;
                case LEFT:
                    if (x == 0 || s[y + 1][x].isEmpty()) {
                        dir = Direction.DOWN;
                    }
                    break;
                case DOWN:
                    if (s[y][x + 1].isEmpty()) {
                        dir = Direction.RIGHT;
                    }
                    break;
            }
 
            switch (dir) {
                case RIGHT:
                    x++;
                    break;
                case UP:
                    y--;
                    break;
                case LEFT:
                    x--;
                    break;
                case DOWN:
                    y++;
                    break;
            }
        }
        for (String[] row : s) {
            System.out.println("[" + String.join("", row) + ']');
        }
        System.out.println();
    }
 
    private enum Direction {
        RIGHT, UP, LEFT, DOWN
    }
 
    private static boolean isPrime(int a) {
        switch (a) {
            case 2:
                return true;
            case 1:
            case 0:
            case -1:
            case -2:
                return false;
            default:
                if (a % 2 == 0) {
                    return false;
                }
                int max = (int) Math.sqrt(a);
                for (int n = 3; n <= max; n += 2) {
                    if (a % n == 0) {
                        return false;
                    }
                }
                return true;
        }
    }

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class MianChowla {
 
    private static final int n = 100;
    private static final int nn = (n * (n + 1)) >> 1;
 
    private static boolean contains(int[] lst, int item, int size) {
        for (int i = size - 1; i >= 0; i--) {
            if (item == lst[i]) {
                return true;
            }
        }
        return false;
    }
 
    private static int[] mianChowla() {
        int[] mc = new int[n];
        mc[0] = 1;
        int[] sums = new int[nn];
        sums[0] = 2;
        int sum, le, ss = 1;
        for (int i = 1; i < n; i++) {
            le = ss;
            for (int j = mc[i - 1] + 1; ; j++) {
                mc[i] = j;
                for (int k = 0; k <= i; k++) {
                    sum = mc[k] + j;
                    if (contains(sums, sum, ss)) {
                        ss = le;
                        break;
                    }
                    sums[ss++] = sum;
                }
                break;
            }
        }
        return mc;
    }
 
    public static void main(String[] args) {
        int[] mc = mianChowla();
        System.out.println("The first 30 terms of the Mian-Chowla sequence are:");
        System.out.println(Arrays.toString(Arrays.copyOfRange(mc, 0, 30)));
        System.out.println("\nTerms 91 to 100 of the Mian-Chowla sequence are:");
        System.out.println(Arrays.toString(Arrays.copyOfRange(mc, 90, 100)));
    }
}

public class Pythagorean {
    public static void main(String[] args) {
        double sum = 0.0;
        for (int x = 1; x < 1001; x++) {
            sum += 1.0 / (x * x);
        }
        System.out.println(sum);
    }
}

public static<E> Set<E> retainKeys(Counter<E> counter, Collection<E> matchKeys) {
    Set<E> removed = new HashSet<E>();
    for (E key : counter.keySet()) {
      boolean matched = matchKeys.contains(key);
      if (!matched) {
        removed.add(key);
      }
    }
    for (E key : removed) {
      counter.remove(key);
    }
    return removed;
  }

import jetbrains.jetpad.model.collections.CollectionItemEvent;
import jetbrains.jetpad.model.collections.CollectionListener;
import jetbrains.jetpad.model.collections.ObservableList;
import jetbrains.jetpad.base.Registration;
import java.util.ArrayList;
import java.util.List;

public class ObservableCollectionRoleSynchronizer<SourceType, TargetType> {
    private final ObservableList<SourceType> mySource;
    private final List<TargetType> myTarget;
    private final MapperFactory<SourceType, TargetType> myMapperFactory;
    private final List<Mapper<SourceType, TargetType>> myMappers = new ArrayList<>();
    private Registration mySourceRegistration;

    public ObservableCollectionRoleSynchronizer(
            ObservableList<SourceType> source,
            List<TargetType> target,
            MapperFactory<SourceType, TargetType> mapperFactory) {
        mySource = source;
        myTarget = target;
        myMapperFactory = mapperFactory;
    }

    public void onAttach() {
        mySourceRegistration = mySource.addListener(new CollectionListener<SourceType>() {
            @Override
            public void onItemAdded(CollectionItemEvent<? extends SourceType> event) {
                SourceType addedItem = event.getItem();
                int index = event.getIndex();
                Mapper<SourceType, TargetType> mapper = createMapper(addedItem);
                myMappers.add(index, mapper);
                myTarget.add(index, mapper.getTarget());
            }

            @Override
            public void onItemRemoved(CollectionItemEvent<? extends SourceType> event) {
                int index = event.getIndex();
                Mapper<SourceType, TargetType> removedMapper = myMappers.remove(index);
                myTarget.remove(index);
                removedMapper.onDetach();
            }
        });

        // Initial synchronization
        for (SourceType sourceItem : mySource) {
            Mapper<SourceType, TargetType> mapper = createMapper(sourceItem);
            myMappers.add(mapper);
            myTarget.add(mapper.getTarget());
        }
    }

    public void onDetach() {
        if (mySourceRegistration != null) {
            mySourceRegistration.remove();
            mySourceRegistration = null;
        }

        for (Mapper<SourceType, TargetType> mapper : myMappers) {
            mapper.onDetach();
        }

        myMappers.clear();
        myTarget.clear();
    }

    private Mapper<SourceType, TargetType> createMapper(SourceType source) {
        return myMapperFactory.createMapper(source);
    }

import javafx.application.Application;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.layout.GridPane;
import javafx.scene.layout.Pane;
