import javafx.scene.shape.Circle;
import javafx.stage.Stage;

public class Counter extends Application {

    @Override
    public void start(Stage primaryStage) throws Exception {

        StackPane[] stackPanes = new StackPane[4];
        GridPane gridPane = new GridPane();

        int paneArrayIdx = 0;
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                Circle circle = new Circle(100);
                circle.setStroke(Color.BLACK);
                circle.setFill(Color.WHITE);
                StackPane stackPane = new StackPane();
                stackPane.getChildren().add(circle);
                stackPane.getChildren().add(new ArcPane());
                gridPane.add(stackPane, j, i);
                stackPanes[paneArrayIdx++] = stackPane;
            }
        }
        gridPane.setAlignment(Pos.CENTER);
        gridPane.setPadding(new Insets(10, 10, 10, 10));
        gridPane.setVgap(10);
        gridPane.setHgap(10);
        Scene scene = new Scene(gridPane);
        primaryStage.setTitle(getClass().getName());
        primaryStage.setScene(scene);
        primaryStage.show();

    }
}

class ArcPane extends Pane {

    ArcPane() {
        super();
        create();
    }

    void create() {
        int angle = 120;
        int numArcs = 4;
        while (numArcs > 0) {
            Arc arc = new Arc(100, 100, 80, 80, angle, 35);
            numArcs--;
            angle += 90;
            arc.setFill(Color.GREY);
            arc.setType(ArcType.ROUND);
            super.getChildren().add(arc);
        }
    }

}

// Verilen sabit bir dizide dogrusal tarama ile en kucuk degeri bulan ornek

public class EnKucukElemaniBul {

    public static void main(String[] args) {
        // Test amacli sabit degerler
        int[] veriSeti = {5, 2, 8, 1, 9, 4, 7};

        int enKucuk = bulEnKucugu(veriSeti);

        System.out.println("Dizideki Minimum Eleman: " + enKucuk);
    }

    // Diziyi bastan sona tarayarak en dusuk degeri dondurur
    private static int bulEnKucugu(int[] degerler) {
        int aday = degerler[0];

        int indeks = degerler.length - 1;
        while (indeks >= 1) {
            if (degerler[indeks] < aday) {
                aday = degerler[indeks];
            }
            indeks--;
        }

        return aday;
    }
}

public interface RunnableLauncher extends Runnable {

    /**
     * Shuts down the launcher.
     */
    void shutdown();

    /**
     * Checks if the launcher has been initialized.
     *
     * @return true if the launcher is initialized, false otherwise
     */
    boolean isInitialized();

    /**
     * Checks if the associated WebDriver instance is currently running.
     *
     * @return true if the instance is running, false otherwise
     */
    boolean isRunning();

    /**
     * Enumeration representing different types of WebDriver instances.
     */
    enum InstanceType {
        SELENIUM_HUB("Selenium Hub"),
        NODE("Node"),
        STANDALONE("Standalone"),
        SAUCE_LABS("Sauce Labs"),
        BROWSER_STACK("Browser Stack"),
        GRID_EXTRAS("Grid Extras"),
        OTHER("Other");

        private final String value;

        InstanceType(String value) {
            this.value = value;
        }

        public String getValue() {
            return value;
        }

        @Override
        public String toString() {
            return this.value;
        }

        /**
         * Returns the InstanceType corresponding to the given string.
         *
         * @param value the string representation of the instance type
         * @return the InstanceType enum constant
         * @throws IllegalArgumentException if the string does not match any known instance type
         */
        public static InstanceType fromValue(String value) {
            for (InstanceType type : InstanceType.values()) {
                if (type.getValue().equalsIgnoreCase(value)) {
                    return type;
                }
            }
            throw new IllegalArgumentException("Unknown instance type: " + value);
        }
    }
}

