import java.util.*;

public class Employee {
    public int reachableNodes(int n, int[][] edges, int[] restricted) {
        List<List<Integer>> tree = new ArrayList<>();
        for (int i = 0; i < n; i++) tree.add(new ArrayList<>());
        for (int[] edge : edges) tree.get(edge[0]).add(edge[1]);
        Set<Integer> restrictedSet = new HashSet<>(Arrays.asList(restricted));
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(0);
        Set<Integer> visited = new HashSet<>();
        visited.add(0);
        int startWith = 0;
        while (!queue.isEmpty()) {
            startWith = queue.size();
            for (int i = 0; i < startWith; i++) {
                int node = queue.poll();
                for (int nextNode : tree.get(node)) {
                    if (!restrictedSet.contains(nextNode) && !visited.contains(nextNode)) {
                        queue.offer(nextNode);
                        visited.add(nextNode);
                    }
                }
            }
        }
        int count = visited.size();
        for (int[] edge : edges) {
            if (restrictedSet.contains(edge[0]) && !visited.contains(edge[1])) count++;
            else if (restrictedSet.contains(edge[1]) && !visited.contains(edge[0])) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        new Employee();
    }
}

public class Parens {
    public static void main(String[] args) {
        for (List<Integer> l : parens(3)) {
            System.out.println(l);
        }
    }

    public static List<List<Integer>> parens(int n) {
        return aux(n, 0);
    }

    public static List<List<Integer>> aux(int n, int k) {
        List<List<Integer>> result = new ArrayList<>();
        if (n == 1) {
            List<Integer> l = new ArrayList<>();
            l.add(k);
            result.add(l);
        } else if (n == 2) {
            List<Integer> l = new ArrayList<>();
            l.add(k);
            l.add(k + 1);
            result.add(l);
        } else {
            for (int i = 1; i < n; i++) {
                for (List<Integer> u : aux(i, k)) {
                    for (List<Integer> v : aux(n - i, k + i)) {
                        List<Integer> l = new ArrayList<>();
                        l.addAll(u);
                        l.addAll(v);
                        result.add(l);
                    }
                }
            }
        }
        return result;
    }
}

import java.util.Calendar;
import java.util.GregorianCalendar;

public class MyDate {
    private int year;
    private int month; // 0-based
    private int day;

    // no-arg constructor for the current date
    public MyDate() {
        GregorianCalendar cal = new GregorianCalendar();
        year = cal.get(Calendar.YEAR);
        month = cal.get(Calendar.MONTH);
        day = cal.get(Calendar.DAY_OF_MONTH);
    }

    // constructor with elapsed time since 1/1/1970
    public MyDate(long elapsedTime) {
        setDate(elapsedTime);
    }

    // constructor with specified year, month, and day
    public MyDate(int year, int month, int day) {
        this.year = year;
        this.month = month;
        this.day = day;
    }

    // getter methods for year, month, and day
    public int getYear() {
        return year;
    }

    public int getMonth() {
        return month;
    }

    public int getDay() {
        return day;
    }

    // set the date based on elapsed time since 1/1/1970
    public void setDate(long elapsedTime) {
        GregorianCalendar cal = new GregorianCalendar();
        cal.setTimeInMillis(elapsedTime);
        year = cal.get(Calendar.YEAR);
        month = cal.get(Calendar.MONTH);
        day = cal.get(Calendar.DAY_OF_MONTH);
    }
}

