// from https://en.wikipedia.org/wiki/De_Bruijn_sequence
 
public class DeBruijn {
 
    public static void main(String[] args) {
 
        String db = deBruijn(10, 4);
 
        System.out.println(" ");
        System.out.println("The length of the de Bruijn sequence is " + db.length());
        System.out.println(" ");
        System.out.println("The first 130 digits of the de Bruijn sequence are: " + db.substring(0, 130));
        System.out.println(" ");
        System.out.println("The last 130 digits of the de Bruijn sequence are: " + db.substring(db.length() - 130));
        System.out.println(" ");
        System.out.println("Validating the deBruijn sequence:");
        validate(db);
        String dbreversed = new StringBuilder(db).reverse().toString();
        System.out.println(" ");
        System.out.println("Validating the reversed deBruijn sequence:");
        validate(dbreversed);
        String dboverlaid = db.substring(0, 4443) + "." + db.substring(4444);
        System.out.println(" ");
        System.out.println("Validating the overlaid deBruijn sequence:");
        validate(dboverlaid);
 
    }
 
    public static String deBruijn(int k, int n) {
        /*
         * de Bruijn sequence for alphabet k and subsequences of length n.
         */
        String alphabet;
        if (k < 10) {
            alphabet = "0123456789";
        } else {
            alphabet = "";
            for (int i = 0; i < k; i++) {
                alphabet += i;
            }
        }
 
        int[] a = new int[k * n];
        StringBuilder sequence = new StringBuilder();
 
        db(1, 1, a, sequence, alphabet, n, k);
 
        return sequence.toString();
    }
 
    public static void db(int t, int p, int[] a, StringBuilder sequence, String alphabet, int n, int k) {
        if (t > n) {
            if (n % p == 0) {
                for (int i = 1; i <= p; i++) {
                    sequence.append(alphabet.charAt(a[i]));
                }
            }
        } else {
            a[t] = a[t - p];
            db(t + 1, p, a, sequence, alphabet, n, k);
            for (int j = a[t - p] + 1; j < k; j++) {
                a[t] = j;
                db(t + 1, t, a, sequence, alphabet, n, k);
            }
        }
    }
 
    public static void validate(String db) {
        /*
         * Check that all 10,000 combinations of 0-9 are present in De Bruijn
         * string db.
         */
 
        String dbwithwrap = db + db.substring(0, 3);
 
        String digits = "0123456789";
 
        ArrayList<String> errorstrings = new ArrayList<String>();

