import java.util.Iterator;
import java.util.List;
import java.util.Map;
 
public class ConstructFromRationalNumber {
    private static class R2cf implements Iterator<Integer> {
        private int num;
        private int den;
 
        R2cf(int num, int den) {
            this.num = num;
            this.den = den;
        }
 
        @Override
        public boolean hasNext() {
            return den != 0;
        }
 
        @Override
        public Integer next() {
            int div = num / den;
            int rem = num % den;
            num = den;
            den = rem;
            return div;
        }
    }
 
    private static void iterate(R2cf generator) {
        generator.forEachRemaining(n -> System.out.printf("%d ", n));
        System.out.println();
    }
 
    public static void main(String[] args) {
        List<Map.Entry<Integer, Integer>> fracs = List.of(
                Map.entry(1, 2),
                Map.entry(3, 1),
                Map.entry(23, 8),
                Map.entry(13, 11),
                Map.entry(22, 7),
                Map.entry(-151, 77)
        );
        for (Map.Entry<Integer, Integer> frac : fracs) {
            System.out.printf("%4d / %-2d = ", frac.getKey(), frac.getValue());
            iterate(new R2cf(frac.getKey(), frac.getValue()));
        }
 
        System.out.println("\nSqrt(2) ->");
        List<Map.Entry<Integer, Integer>> root2 = List.of(
                Map.entry(    14_142,     10_000),
                Map.entry(   141_421,    100_000),
                Map.entry( 1_414_214,  1_000_000),
                Map.entry(14_142_136, 10_000_000)
        );
        for (Map.Entry<Integer, Integer> frac : root2) {
            System.out.printf("%8d / %-8d = ", frac.getKey(), frac.getValue());
            iterate(new R2cf(frac.getKey(), frac.getValue()));
        }
 
        System.out.println("\nPi ->");
        List<Map.Entry<Integer, Integer>> pi = List.of(
                Map.entry(         31,        10),
                Map.entry(        314,       100),
                Map.entry(      3_142,      1_000),
                Map.entry(     31_428,     10_000),
                Map.entry(    314_285,    100_000),
                Map.entry(  3_142_857,   1_000_000),
                Map.entry( 31_428_571,  10_000_000),
                Map.entry(314_285_714, 100_000_000)
        );
        for (Map.Entry<Integer, Integer> frac : pi) {
            System.out.printf("%9d / %-9d = ", frac.getKey(), frac.getValue());
            iterate(new R2cf(frac.getKey(), frac.getValue()));
        }
    }
}

protected String composeError(Exception error) {
        StringBuilder builder = new StringBuilder();
        Throwable t = error;
        while (t != null) {
            if (builder.length() > 0)
                builder.append(" Caused by error: ");
            builder.append(t.getMessage()).append(" StackTrace: ").append(t.getStackTrace());
            t = t.getCause();
        }
        return builder.toString();
    }

import java.util.HashMap;
import java.util.Map;

import org.camunda.bpm.engine.ProcessEngineException;
import org.camunda.bpm.engine.impl.test.PluggableProcessEngineTestCase;
import org.camunda.bpm.engine.runtime.ProcessInstance;
import org.camunda.bpm.engine.task.Task;
import org.camunda.bpm.engine.test.Deployment;

/**
 * Example of using the exclusive gateway.
 *
 */
public class ExclusiveGatewayTest extends PluggableProcessEngineTestCase {

  /**
   * The test process has an XOR gateway where, the 'input' variable is used to
   * select one of the outgoing sequence flow. Every one of those sequence flow
   * goes to another task, allowing us to test the decision very easily.
   */
  @Deployment
  public void testDecisionFunctionality() {

    Map<String, Object> variables = new HashMap<String, Object>();

    // Test with input == 1
    variables.put("input", 1);
    ProcessInstance pi = runtimeService.startProcessInstanceByKey("exclusiveGateway", variables);
    Task task = taskService.createTaskQuery().processInstanceId(pi.getId()).singleResult();
    assertEquals("Send e-mail for more information", task.getName());

    // Test with input == 2
    variables.put("input", 2);
    pi = runtimeService.startProcessInstanceByKey("exclusiveGateway", variables);
    task = taskService.createTaskQuery().processInstanceId(pi.getId()).singleResult();
    assertEquals("Check account balance", task.getName());

    // Test with input == 3
    variables.put("input", 3);
    pi = runtimeService.startProcessInstanceByKey("exclusiveGateway", variables);
    task = taskService.createTaskQuery().processInstanceId(pi.getId()).singleResult();
    assertEquals("Call customer", task.getName());

    // Test with input == 4
    variables.put("input", 4);
    try {
      runtimeService.startProcessInstanceByKey("exclusiveGateway", variables);
      fail();
    } catch (ProcessEngineException e) {
      // Exception is expected since no outgoing sequence flow matches
    }

  }

}

public static String[] getServiceName(String[] argv, String[] serviceId) throws IllegalArgumentException {
    if (argv == null || serviceId == null || serviceId.length != 1) {
        throw new IllegalArgumentException("Invalid arguments");
    }
    List<String> filteredArgs = new ArrayList<>();
    boolean serviceIdFound = false;
    for (String arg : argv) {
        if (arg.startsWith("--service=")) {
            serviceId[0] = arg.substring("--service=".length());
            serviceIdFound = true;
        } else {
            filteredArgs.add(arg);
        }
    }
    if (!serviceIdFound) {
        serviceId[0] = "";
    }
    return filteredArgs.toArray(new String[0]);
}

import org.flowable.dmn.engine.DmnEngine;
import org.flowable.dmn.engine.DmnEngineConfiguration;
import org.springframework.beans.BeansException;
import org.springframework.beans.factory.DisposableBean;
import org.springframework.beans.factory.FactoryBean;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationContextAware;

public class DmnEngineFactoryBean implements FactoryBean<DmnEngine>, DisposableBean, ApplicationContextAware {

    protected DmnEngineConfiguration dmnEngineConfiguration;
    protected ApplicationContext applicationContext;
    protected DmnEngine dmnEngine;

    @Override
    public void destroy() {
        if (dmnEngine != null) {
            dmnEngine.close();
        }
    }

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
        this.applicationContext = applicationContext;
    }

    @Override
    public DmnEngine getObject() {
        if (dmnEngineConfiguration == null) {
            throw new IllegalStateException("DmnEngineConfiguration is required");
        }

        configureExternallyManagedTransactions();

        dmnEngine = dmnEngineConfiguration.buildDmnEngine();
        return dmnEngine;
    }

    protected void configureExternallyManagedTransactions() {
        if (dmnEngineConfiguration instanceof SpringDmnEngineConfiguration) {
            SpringDmnEngineConfiguration springConfiguration = (SpringDmnEngineConfiguration) dmnEngineConfiguration;
            if (springConfiguration.getTransactionManager() != null) {
              dmnEngineConfiguration.setUsingExternallyManagedTransactions(true);
            }
        }
    }

    @Override
    public Class<?> getObjectType() {
        return DmnEngine.class;
    }

    @Override
    public boolean isSingleton() {
        return true;
    }

    public DmnEngineConfiguration getDmnEngineConfiguration() {
        return dmnEngineConfiguration;
    }

    public void setDmnEngineConfiguration(DmnEngineConfiguration dmnEngineConfiguration) {
        this.dmnEngineConfiguration = dmnEngineConfiguration;
    }
}

