public class NotHesaplama {

    // Sayisal notu karsilik gelen harf notuna cevirip ekrana basar
    public static void notuGoster(int puan) {
        char harf;

        if (puan < 60) {
            harf = 'F';
        } else if (puan < 70) {
            harf = 'D';
        } else if (puan < 80) {
            harf = 'C';
        } else if (puan < 90) {
            harf = 'B';
        } else {
            harf = 'A';
        }

        System.out.println(harf);
    }

    public static void main(String[] args) {

        Scanner tarayici = new Scanner(System.in);

        System.out.print("Notunuzu girin: ");
        int ogrenciNotu = tarayici.nextInt();

        notuGoster(ogrenciNotu);

        tarayici.close();
    }
}

