import java.util.ArrayList;
import java.util.Collections;

public class Loto {

    // Loto cekilisi yapan metod
    public static Integer[] lotoYap(int toplamSayi, int cekilecekSayi) {
        // Sayilari tutacak bir ArrayList olustur
        ArrayList<Integer> sayilar = new ArrayList<Integer>();

        // 1'den toplamSayi'ya kadar sayilari listeye ekle
        for (int i = 0; i < toplamSayi; i++) {
            sayilar.add(i + 1);
        }

        // Sayilari karistir
        Collections.shuffle(sayilar);

        // Cekilecek sayi kadar elemani yeni bir Integer dizisine kopyala
        Integer[] cekilenSayilar = new Integer[cekilecekSayi];
        for (int i = 0; i < cekilecekSayi; i++) {
            cekilenSayilar[i] = sayilar.get(i);
        }

        return cekilenSayilar;
    }

    public static void main(String[] args) {
        // 49 sayidan 6 tane cekilis sonucu al
        Integer[] sonuc = lotoYap(49, 6);

        // Sonuclari ekrana yazdir
        for (Integer item : sonuc) {
            System.out.print(item + " ");
        }
    }
}

import java.nio.file.*;
import static java.util.Arrays.stream;
 
public class MaxPathSum {
 
    public static void main(String[] args) throws Exception {
        int[][] data = Files.lines(Paths.get("triangle.txt"))
                .map(s -> stream(s.trim().split("\\s+"))
                        .mapToInt(Integer::parseInt)
                        .toArray())
                .toArray(int[][]::new);
 
        for (int r = data.length - 1; r > 0; r--)
            for (int c = 0; c < data[r].length - 1; c++)
                data[r - 1][c] += Math.max(data[r][c], data[r][c + 1]);
 
        System.out.println(data[0][0]);
    }
}

import org.conqat.engine.commons.util.ConQATInputProcessorBase;
import org.conqat.engine.core.core.ConQATException;
import org.conqat.engine.sourcecode.resource.ITokenElement;
import org.conqat.engine.sourcecode.resource.ITokenResource;
import org.conqat.engine.sourcecode.resource.TokenElementUtils;
import org.conqat.lib.scanner.ETokenType.ETokenClass;
import org.conqat.lib.scanner.IToken;

/**
 * Base class for processors working on identifiers.
 *
 * @param <T>
 *            the return type of this processor.
 *
 * @ConQAT.Rating GREEN Hash: 69177F56B4A8847260A2E8EDB12F972C
 */
public abstract class IdentifierProcessorBase<T> extends
        ConQATInputProcessorBase<ITokenResource> {

    /** {@inheritDoc} */
    @Override
    public T process() throws ConQATException {
        for (ITokenElement element : TokenElementUtils.listTokenElements(input)) {
            processElement(element);
        }
        return obtainResult();
    }

    /** Template method that calculates and returns the processor's result. */
    protected abstract T obtainResult();

    /** Process a single source element. */
    private void processElement(ITokenElement element) throws ConQATException {
        for (IToken token : element.getTokens(getLogger())) {
            if (token.getType().getTokenClass() == ETokenClass.IDENTIFIER) {
                processIdentifier(token.getText());
            }
        }
    }

    /** Template method that is called for each identifier. */
    protected abstract void processIdentifier(String identifier);
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class Median {
    public static double median(List<Double> xs) {
        // sort in ascending order, panic on f64::NaN
        List<Double> sorted = xs.stream().sorted().collect(Collectors.toList());
        int n = sorted.size();
        if (n % 2 == 0) {
            return (sorted.get(n/2) + sorted.get(n/2 - 1)) / 2.0;
        } else {
            return sorted.get(n/2);
        }
    }
 
    public static void main(String[] args) {
        List<Double> nums = Arrays.asList(2.,3.,5.,0.,9.,82.,353.,32.,12.);
        System.out.println(median(nums));
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Stack;
 
public class TruthTable {
    public static void main( final String... args ) {
        System.out.println( new TruthTable( args ) );
    }
 
    private interface Operator {
        boolean evaluate( Stack<Boolean> s );
    }
 
    /**
     * Supported operators and what they do. For more ops, add entries here.
     */
    private static final Map<String,Operator> operators = new HashMap<String,Operator>() {{
        // Can't use && or || because shortcut evaluation may mean the stack is not popped enough
        put( "&", stack -> Boolean.logicalAnd( stack.pop(), stack.pop() ) );
        put( "|", stack -> Boolean.logicalOr( stack.pop(), stack.pop() ) );
        put( "!", stack -> ! stack.pop() );
        put( "^", stack -> ! stack.pop().equals ( stack.pop() ) );
    }};
 
    private final List<String> variables;
    private final String[]     symbols;
 
    /**
     * Constructs a truth table for the symbols in an expression.
     */
    public TruthTable( final String... symbols ) {
        final Set<String> variables = new LinkedHashSet<>();
 
        for ( final String symbol : symbols ) {
            if ( ! operators.containsKey( symbol ) ) {
                variables.add( symbol );
            }
        }
        this.variables = new ArrayList<>( variables );
        this.symbols = symbols;
    }
 
    @Override
    public String toString () {
        final StringBuilder result = new StringBuilder();
 
        for ( final String variable : variables ) {
            result.append( variable ).append( ' ' );
        }
        result.append( ' ' );
        for ( final String symbol : symbols ) {
            result.append( symbol ).append ( ' ' );
        }
        result.append( '\n' );
        for ( final List<Boolean> values : enumerate( variables.size () ) ) {
            final Iterator<String> i = variables.iterator();
 
            for ( final Boolean value : values ) {
                result.append(
                    String.format(
                        "%-" + i.next().length() + "c ",
                        value ? 'T' : 'F'
                    )
                );
            }
            result.append( ' ' )
                .append( evaluate( values ) ? 'T' : 'F' )
                .append( '\n' );
        }
 
        return result.toString ();
    }
 
    /**
     * Recursively generates T/F values
     */

public boolean containsRevisionSpecTopic(Level level) {
    if (level.getSpecTopics().stream().anyMatch(specTopic -> specTopic.isRevision())) {
        return true;
    }
    for (Level child : level.getChildren()) {
        if (containsRevisionSpecTopic(child)) {
            return true;
        }
    }
    return false;
}

