public class GHDiscussionBuilder<S> extends AbstractBuilder<GHDiscussion, S> {

    private final GHTeam team;
    private final @CheckForNull GHDiscussion existingDiscussion;
    private final Requester requester;

    public GHDiscussionBuilder(@Nonnull Class<S> intermediateReturnType, @Nonnull GHTeam team) {
        this(intermediateReturnType, team, null);
    }

    public GHDiscussionBuilder(@Nonnull Class<S> intermediateReturnType, @Nonnull GHTeam team, @CheckForNull GHDiscussion existingDiscussion) {
        super(intermediateReturnType);
        this.team = team;
        this.existingDiscussion = existingDiscussion;
        this.requester = new Requester();
    }

    public GHDiscussionBuilder<S> title(@Nonnull String value) {
        requester.with("title", value);
        return this;
    }

    public GHDiscussionBuilder<S> body(@Nonnull String value) {
        requester.with("body", value);
        return this;
    }

    @Override
    public S done() {
        if (existingDiscussion != null) {
            // Update the existing discussion
            requester.patch(GHDiscussion.class, existingDiscussion.getUrl(), item -> {
                return new GHDiscussion(item, team.getRoot());
            });
        } else {
            // Create a new discussion
            requester.with("category_id", team.getDefaultCategoryId()); // Assuming a default category ID
            requester.post(GHDiscussion.class, team.getDiscussionsUrl(), item -> {
                return new GHDiscussion(item, team.getRoot());
            });
        }
        return returnToIntermediate();
    }

