public class UntagResourceRequestProtocolMarshaller implements Marshaller<UntagResourceRequest, Request<UntagResourceRequest>> {

    private static final OperationInfo SDK_OPERATION_BINDING = OperationInfo.builder()
            .protocol("rest-json")
            .httpMethod("DELETE")
            .hasPayload(false)
            .hasExplicitPayloadMember(false)
            .serviceName("AWSLambda")
            .operationIdentifier("UntagResource")
            .build();

    private final SdkJsonProtocolFactory protocolFactory;

    public UntagResourceRequestProtocolMarshaller(SdkJsonProtocolFactory protocolFactory) {
        this.protocolFactory = protocolFactory;
    }

    @Override
    public Request<UntagResourceRequest> marshall(UntagResourceRequest untagResourceRequest) {
        if (untagResourceRequest == null) {
            throw new IllegalArgumentException("UntagResourceRequest cannot be null");
        }

        ProtocolMarshaller<Request<UntagResourceRequest>> protocolMarshaller = protocolFactory.createProtocolMarshaller(
                SDK_OPERATION_BINDING, untagResourceRequest);

        Request<UntagResourceRequest> request = protocolMarshaller.startMarshalling();

        try {
            request.setResourcePath("/2017-03-31/tags/" + untagResourceRequest.getResourceArn());
            request.addParameter("tagKeys", String.join(",", untagResourceRequest.getTagKeys()));
        } catch (Exception e) {
            throw new RuntimeException("Failed to marshal UntagResourceRequest", e);
        }

        protocolMarshaller.finishMarshalling(request);
        return request;
