            Graph graph = new Graph(n);
            for (int i = 0; i < n - 1; i++) {
                int a = sc.nextInt() - 1, b = sc.nextInt() - 1;
                graph.addEdge(a, b);
            }

            TreeMap<Integer, Integer> leafCounts = new TreeMap<>();
            for (int i = 0; i < n; i++) {
                if (graph.adj.length == 1) {
                    leafCounts.put(graph.adj[0], leafCounts.getOrDefault(graph.adj[0], 0) + 1);
                }
            }

            int result = 0;
            while (leafCounts.size() > 0) {
                Integer v = leafCounts.lastKey();
                int ct = leafCounts.get(v);
                if (ct < k) {
                    break;
                }
                int toRemove = ct - ct % k;
                leafCounts.put(v, ct - toRemove);

                for (int i = 0; i < toRemove; i += k) {
                    result++;
                    graph.removeFrom(v, k);
                }
                if (leafCounts.get(v) == 0) {
                    leafCounts.remove(v);
                }
            }

            System.out.println(result);
        }
    }

