public class Array {
    public void cocktailsort() {
        boolean swapped;
        do {
            swapped = false;
            for (int i = 0; i < length - 1; i++) {
                if (this[i] > this[i + 1]) {
                    this[i] = this[i + 1];
                    this[i + 1] = this[i];
                    swapped = true;
                }
            }
            if (!swapped) {
                break;
            }
            swapped = false;
            for (int i = length - 1; i > 0; i--) {
                if (this[i] > this[i + 1]) {
                    this[i] = this[i + 1];
                    this[i + 1] = this[i];
                    swapped = true;
                }
            }
        } while (swapped);
    }
}

public static String inputStream2String(InputStream inputStream, String encoding) throws IOException {
    StringBuilder sb = new StringBuilder();
    try (Reader reader = new BufferedReader(new InputStreamReader(inputStream, encoding))) {
        int c = 0;
        while ((c = reader.read()) != -1) {
            sb.append((char) c);
        }
    }
    return sb.toString();
}

