public class E1632D {

    public static void main(String[] args) {

        FastIO io = new FastIO();

        int n = io.nextInt();

        long[] arr = new long[n];

        for (int i = 0; i < n; i++) arr[i] = io.nextInt();

        SparseTable st = new SparseTable(arr);

        int nextEnd = n;

        int ans = 0;

        for (int i = 0; i < n; i++) {

            int finalI = i;

            int r = lastTrue(i, n - 1, (x) -> st.query(finalI, x) >= x - finalI + 1);

            if (st.query(i, r) == r - finalI + 1)

                nextEnd = Math.min(nextEnd, r);

            if (i == nextEnd) {

                nextEnd = n;

                ans++;

            }

            io.print(ans + " ");

        }

        io.close();

    }

    public static int lastTrue(int lo, int hi, Predicate<Integer> test) {

        lo--;

        for (int dif = hi - lo; dif > 0; dif /= 2) {

            while (lo + dif <= hi && test.test(lo + dif)) {

                lo += dif;

            }

        }

        return lo;

    }

    private static long gcd(long a, long b) {

        return b == 0 ? a : gcd(b, a % b);

    }

    private static class SparseTable {

        long[][] ST;

        int n;

        SparseTable(long[] A) {

            n = A.length;

            int k = 31 - Integer.numberOfLeadingZeros(n);

            ST = new long[k + 1][n];

            for (int i = 0; i < n; ++i)

                ST[0][i] = A[i];

            for (int i = 1; i <= k; ++i)

                for (int j = 0; j + (1 << i) <= n; ++j)

                    ST[i][j] = gcd(ST[i - 1][j], ST[i - 1][j + (1 << i - 1)]);

        }

        long query(int l, int r) {

            int k = 31 - Integer.numberOfLeadingZeros(r - l + 1);

            return gcd(ST[k][l], ST[k][r - (1 << k) + 1]);

        }

    }

