import android.webkit.WebViewClient;
import androidx.annotation.NonNull;
import androidx.fragment.app.Fragment;

public class BeamFragment extends Fragment {

    private WebView webView;
    private boolean nfcSupported = false;

    @Override
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setHasOptionsMenu(true);
    }

    @Override
    public View onCreateView(LayoutInflater inflater, ViewGroup container, Bundle savedInstanceState) {
        return inflater.inflate(R.layout.fragment_beam, container, false);
    }

    @SuppressLint("SetJavaScriptEnabled")
    @Override
    public void onViewCreated(@NonNull View view, Bundle savedInstanceState) {
        super.onViewCreated(view, savedInstanceState);
        webView = view.findViewById(R.id.webview);
        webView.setWebViewClient(new BeamClient());
        webView.getSettings().setJavaScriptEnabled(true);
        webView.loadUrl("https://www.google.com");
    }

    @Override
    public void onCreateOptionsMenu(@NonNull Menu menu, @NonNull MenuInflater inflater) {
        inflater.inflate(R.menu.actions, menu);
        MenuItem nfcItem = menu.findItem(R.id.action_nfc);
        nfcItem.setVisible(nfcSupported);
    }

    @Override
    public boolean onOptionsItemSelected(@NonNull MenuItem item) {
        if (item.getItemId() == R.id.action_nfc) {
            getContract().beamUrl(getUrl());
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    private String getUrl() {
        return webView.getUrl();
    }

    private WebBeamActivity getContract() {
        return (WebBeamActivity) getActivity();
    }

    private static class BeamClient extends WebViewClient {
        @Override
        public boolean shouldOverrideUrlLoading(WebView view, String url) {
            view.loadUrl(url);
            return true;
        }
    }

    public void setNfcSupported(boolean supported) {
        nfcSupported = supported;
        requireActivity().invalidateOptionsMenu();
    }

    public WebView getWebView() {
        return webView;
    }
}

