class Cache {

    public static int mapper(int[] nums, int start, int end) {
        int key = nums[start];

        while (start < end) {
            while (start < end && nums[end] >= key) {
                end--;
            }

            nums[start] = nums[end];

            while (start < end && nums[start] <= key) {
                start++;
            }

            nums[end] = nums[start];
        }

        nums[start] = key;

        return start;
    }

    public static int find_kth_largest(int[] nums, int k) {
        int start = 0;
        int end = nums.length - 1;

        while (start < end) {
            int index = mapper(nums, start, end);

            if (index == k) return nums[index];
            if (index > k) end = index - 1;
            if (index < k) start = index + 1;
        }

        return nums[k];
    }

    public static int[] frequencySort(int[] nums) {
        Arrays.sort(nums);

        for (int i = 0; i < nums.length;) {
            int k = i;

            while (k < nums.length - 1 && nums[i] == nums[k + 1]) {
                k++;
            }

            if (i != k) {
                find_kth_largest(nums, i);
            }

            i = k + 1;
        }

        return nums;
    }
}

