import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class BusRoutes {
    public int findBusNumberOfRoutes(int[][] routes, int source, int target) {
        Set<Integer> set = new HashSet<>();
        for (int[] route : routes) {
            set.addAll(Arrays.stream(route).boxed().collect(Collectors.toList()));
        }

        if (!set.contains(source) || !set.contains(target)) {
            return -1;
        }

        int[][] graph = new int[set.size()][set.size()];
        boolean[] visited = new boolean[set.size()];

        for (int i = 0; i < routes.length; i++) {
            int from = -1, to = -1;
            for (int j = 0; j < routes[i].length; j++) {
                if (routes[i][j] == source) {
                    from = i;
                    break;
                }
            }
            for (int j = 0; j < routes[i].length; j++) {
                if (routes[i][j] == target) {
                    to = i;
                    break;
                }
            }
            if (from != -1 && to != -1) {
                for (int j = 0; j < routes[i].length - 1; j++) {
                    int prev = routes[i][j];
                    int next = routes[i][j + 1];
                    int index1 = set.indexOf(prev);
                    int index2 = set.indexOf(next);
                    graph[index1][index2] = 1;
                }
            }
        }

        int[][] distances = new int[set.size()][set.size()];
        for (int i = 0; i < set.size(); i++) {
            for (int j = 0; j < set.size(); j++) {
                if (i == j) {
                    distances[i][j] = 0;
                } else {
                    distances[i][j] = Integer.MAX_VALUE;
                }
            }
        }

        for (int k = 0; k < set.size(); k++) {
            for (int i = 0; i < set.size(); i++) {
                for (int j = 0; j < set.size(); j++) {
                    if (graph[i][k] != 0 && graph[k][j] != 0) {
                        distances[i][j] = Math.min(distances[i][j], distances[i][k] + distances[k][j]);
                    }
                }
            }
        }

        return distances[source][target] == Integer.MAX_VALUE ? -1 : distances[source][target];
    }
}

