import javax.persistence.EntityManager;
import javax.persistence.EntityTransaction;
import javax.persistence.PersistenceException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.util.List;

public interface Persistable<ID> {
    ID getId();
}

public interface BaseDAO<T extends Persistable<ID>, ID> {
    ID save(T entity);
    void delete(T entity);
    void delete(List<T> entityList);
    T findById(ID id);
}

public class BaseDAOImpl<T extends Persistable<ID>, ID> implements BaseDAO<T, ID> {
    private static final Logger logger = LoggerFactory.getLogger(BaseDAOImpl.class);
    private final EntityManager entityManager;

    public BaseDAOImpl(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public ID save(T entity) {
        EntityTransaction transaction = entityManager.getTransaction();
        try {
            transaction.begin();
            if (entityManager.contains(entity)) {
                logger.info("Entity is already managed, merging it.");
                entity = entityManager.merge(entity);
            } else {
                logger.info("Persisting new entity.");
                entityManager.persist(entity);
            }
            transaction.commit();
            logger.info("Entity saved successfully with ID: " + entity.getId());
            return entity.getId();
        } catch (PersistenceException e) {
            logger.error("Failed to save entity: " + entity, e);
            transaction.rollback();
            throw e;
        }
    }

    @Override
    public void delete(T entity) {
        EntityTransaction transaction = entityManager.getTransaction();
        try {
            transaction.begin();
            entity = entityManager.merge(entity);
            entityManager.remove(entity);
            transaction.commit();
            logger.info("Entity deleted successfully with ID: " + entity.getId());
        } catch (PersistenceException e) {
            logger.error("Failed to delete entity: " + entity, e);
            transaction.rollback();
            throw e;
        }
    }

    @Override
    public void delete(List<T> entityList) {
        EntityTransaction transaction = entityManager.getTransaction();
        try {
            transaction.begin();
            for (T entity : entityList) {
                entity = entityManager.merge(entity);
                entityManager.remove(entity);
            }
            transaction.commit();
            logger.info("Entities deleted successfully, count: " + entityList.size());

