public String addSpaces(String s, int[] spaces) {
    StringBuilder sb = new StringBuilder();
    int j = 0;
    for (int i = 0; i <= s.length(); i++) {
        if (i < s.length() || i == spaces[j] + 1) {
            sb.append(s.charAt(i));
            if (i < s.length() && i == spaces[j]) {
                sb.append(' ');
                j++;
            }
        }
    }
    return sb.toString();
}

