import java.nio.ByteBuffer;
import java.util.List;

public interface MessageStreamDecoder {

    /**
     * Decodes messages from the provided transport.
     *
     * @param transport the network transport to read from
     * @param max_bytes the maximum number of bytes to process in this call
     * @return the number of bytes processed
     */
    int performStreamDecode(Transport transport, int max_bytes);

    /**
     * Retrieves any fully decoded messages.
     *
     * @return a list of fully decoded messages
     */
    List<Message> removeDecodedMessages();

    /**
     * Returns the count of protocol bytes decoded.
     *
     * @return the count of protocol bytes
     */
    long getProtocolBytesDecoded();

    /**
     * Returns the count of data bytes decoded.
     *
     * @return the count of data bytes
     */
    long getDataBytesDecoded();

    /**
     * Provides the completion percentage of the current message being decoded.
     *
     * @return the completion percentage as a double between 0.0 and 1.0
     */
    double getPercentDoneOfCurrentMessage();

    /**
     * Pauses the decoding process.
     */
    void pauseDecoding();

    /**
     * Resumes the decoding process.
     */
    void resumeDecoding();

    /**
     * Cleans up the decoder and returns any remaining buffered data.
     *
     * @return a ByteBuffer containing any remaining data
     */
    ByteBuffer destroy();

    /**
     * Represents a decoded message.
     */
    interface Message {
        /**
         * Gets the type of the message.
         *
         * @return the message type
         */
        String getType();

        /**
         * Gets the payload of the message.
         *
         * @return the message payload as a ByteBuffer
         */
        ByteBuffer getPayload();
    }
}

