import java.util.Arrays;

public class MinimumDeletions {

    public int minDeletions(int[] nums) {
        if (nums.length <= 1) {
            return nums.length;
        }

        int minIndex = 0, maxIndex = 0;

        // Find the indices of the minimum and maximum elements
        for (int i = 1; i < nums.length; i++) {
            if (nums[i] < nums[minIndex]) {
                minIndex = i;
            }
            if (nums[i] > nums[maxIndex]) {
                maxIndex = i;
            }
        }

        // Calculate the minimum number of deletions
        int left = Math.min(minIndex, maxIndex);
        int right = Math.max(minIndex, maxIndex);
        int n = nums.length;

        // Options to remove both elements:
        // 1. Remove from the front
        // 2. Remove from the back
        // 3. Remove from both ends
        int fromFront = right + 1;
        int fromBack = n - left;
        int fromBothEnds = (left + 1) + (n - right);

        return Math.min(Math.min(fromFront, fromBack), fromBothEnds);
    }

    public static void main(String[] args) {
        MinimumDeletions solution = new MinimumDeletions();
        int[] nums1 = {2, 10, 7, 5, 4, 1, 8, 6};
        int[] nums2 = {0, -4, 19, 1, 8, -2, -3, 5};
        int[] nums3 = {101};

        System.out.println(solution.minDeletions(nums1)); // Output: 5
        System.out.println(solution.minDeletions(nums2)); // Output: 3
        System.out.println(solution.minDeletions(nums3)); // Output: 1
    }
}

