        Wo wo = ThisApplication
                .context().applications().deleteQuery(effectivePerson.getDebugger(),
                        x_processplatform_service_processing.class, Applications.joinQueryUri("attachment",
                                attachment.getId(), "workcompleted", workCompleted.getId()),
                        workCompleted.getJob())
                .getData(Wo.class);
        wo.setId(attachment.getId());
        result.setData(wo);

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import org.apache.camel.dataformat.bindy.PatternFormat;
import org.apache.camel.util.ObjectHelper;

public class LocalDatePatternFormat implements PatternFormat<LocalDate> {

    private String pattern;
    private Locale locale;

    public LocalDatePatternFormat() {
    }

    public LocalDatePatternFormat(String pattern, Locale locale) {
        this.pattern = pattern;
        this.locale = locale;
    }

    public String format(LocalDate object) throws Exception {
        ObjectHelper.notNull(this.pattern, "pattern");
        return this.getDateFormat().format(object);
    }

    public LocalDate parse(String string) throws Exception {

        LocalDate date;
        DateTimeFormatter df = this.getDateFormat();

        ObjectHelper.notNull(this.pattern, "pattern");

        if (doesStringFitLengthOfPattern(string)) {
            date = LocalDate.parse(string, df);
            return date;
        } else {
            throw new FormatException("Date provided does not fit the pattern defined");
        }

    }

    private boolean doesStringFitLengthOfPattern(String string) {
        return string.length() <= this.pattern.length();
    }

    protected DateTimeFormatter getDateFormat() {
        DateTimeFormatter result;
        if (locale != null) {
            result = DateTimeFormatter.ofPattern(pattern, locale);
        } else {
            result = DateTimeFormatter.ofPattern(pattern);
        }
        return result;
    }

    public String getPattern() {
        return pattern;
    }

    /**
     * Sets the pattern
     *
     * @param pattern the pattern
     */
    public void setPattern(String pattern) {
        this.pattern = pattern;
    }
}

import java.math.BigInteger;
import java.util.*;
 
public class Lychrel {
 
    static Map<BigInteger, Tuple> cache = new HashMap<>();
 
    static class Tuple {
        final Boolean flag;
        final BigInteger bi;
 
        Tuple(boolean f, BigInteger b) {
            flag = f;
            bi = b;
        }
    }
 
    static BigInteger rev(BigInteger bi) {
        String s = new StringBuilder(bi.toString()).reverse().toString();
        return new BigInteger(s);
    }
 
    static Tuple lychrel(BigInteger n) {
        Tuple res;
        if ((res = cache.get(n)) != null)
            return res;
 
        BigInteger r = rev(n);
        res = new Tuple(true, n);
        List<BigInteger> seen = new ArrayList<>();
 
        for (int i = 0; i < 500; i++) {
            n = n.add(r);
            r = rev(n);
 
            if (n.equals(r)) {
                res = new Tuple(false, BigInteger.ZERO);
                break;
            }
 
            if (cache.containsKey(n)) {
                res = cache.get(n);
                break;
            }
 
            seen.add(n);
        }
 
        for (BigInteger bi : seen)
            cache.put(bi, res);
 
        return res;
    }
 
    public static void main(String[] args) {
 
        List<BigInteger> seeds = new ArrayList<>();
        List<BigInteger> related = new ArrayList<>();
        List<BigInteger> palin = new ArrayList<>();
 
        for (int i = 1; i <= 10_000; i++) {
            BigInteger n = BigInteger.valueOf(i);
 
            Tuple t = lychrel(n);
 
            if (!t.flag)
                continue;
 
            if (n.equals(t.bi))
                seeds.add(t.bi);
            else
                related.add(t.bi);
 
            if (n.equals(t.bi))
                palin.add(t.bi);
        }
 
        System.out.printf("%d Lychrel seeds: %s%n", seeds.size(), seeds);
        System.out.printf("%d Lychrel related%n", related.size());
        System.out.printf("%d Lychrel palindromes: %s%n", palin.size(), palin);
    }
}

