import java.util.Arrays;
import java.util.Scanner;

public class Parser {

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter list: ");
        int length = in.nextInt();
        int[] list = new int[length];

        for (int i = 0; i < list.length; i++) {
            list[i] = in.nextInt();

        }
        int indexOfPivot = partition(list);
        System.out.println("After the partition the list is ");
        for (int j : list) {
            System.out.print(j + " ");
        }
        System.out.println("Pivot point is " + indexOfPivot);

    }

    public static int partition(int[] list) {
        int pivotPoint = 0;
        int pivot = list[0];

        while (true) {
            boolean partitioned = true;
            for (int j = 0; j < list.length; j++) {
                if (j == pivotPoint) {
                    continue;
                }

                if (list[j] < pivot) {
                    if (j > pivotPoint) {
                        partitioned = false;
                        int tmp = list[j];
                        list[j] = pivot;
                        list[pivotPoint] = tmp;
                        pivotPoint = j;
                    }

                } else if (list[j] > pivot) {
                    if (j < pivotPoint) {
                        partitioned = false;
                        int tmp = list[j];
                        list[j] = pivot;
                        list[pivotPoint] = tmp;
                        pivotPoint = j;
                    }

                }

            }
            if (partitioned) break;
        }
        return pivotPoint;

    }

}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import com.google.common.base.Charsets;
import org.apache.jackrabbit.oak.segment.RecordId;
import org.apache.jackrabbit.oak.segment.Revisions;
import org.apache.jackrabbit.oak.segment.spi.persistence.Options;

public class HttpStoreRevisions implements Revisions {

    private final HttpStore store;

    public HttpStoreRevisions(HttpStore store) {
        this.store = store;
    }

    @Override
    public RecordId getHead() {
        try {
            URL url = new URL(store.getHeadRevisionUrl());
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(5000);
            connection.setReadTimeout(5000);

            int responseCode = connection.getResponseCode();
            if (responseCode == HttpURLConnection.HTTP_OK) {
                try (InputStream inputStream = connection.getInputStream();
                     BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream, Charsets.UTF_8))) {
                    String line;
                    StringBuilder response = new StringBuilder();
                    while ((line = reader.readLine()) != null) {
                        response.append(line);
                    }
                    return RecordId.fromString(response.toString().trim());
                }
            } else {
                throw new RuntimeException("Failed to retrieve head revision, HTTP error code: " + responseCode);
            }
        } catch (IOException e) {
            throw new RuntimeException("Error connecting to the remote HTTP store", e);
        }
    }

    @Override
    public void setHead(RecordId expectedBefore, RecordId newHead, Options... options) {
        throw new UnsupportedOperationException("Setting head revision is not supported.");
    }

    @Override
    public void setHead(java.util.function.Function<RecordId, RecordId> update, Options... options) {
        throw new UnsupportedOperationException("Setting head revision is not supported.");
    }
}

public class Writer {

    public static void main(String[] args) {
        /* calculate the Fibonacci numbers from index 40 to index 45 */
        int[] fibs = calcFibIndexes40to45();
        System.out.println("\t\t\t\t\t\t40    41    42    43    44    45");
        System.out.println("---------------------------------------------------------");
        System.out.print("Listing 22.3 GCD\t\t");
        for (int i = 0; i < fibs.length - 1; i++) {
            long startTime = System.currentTimeMillis();
            int gcd = gcd(fibs[i], fibs[i + 1]);
            long endTime = System.currentTimeMillis();
            long executionTime = endTime - startTime;
            System.out.print("   " + executionTime);
        }
        System.out.print("\nListing 22.4 GCDEuclid ");
        for (int i = 0; i < fibs.length - 1; i++) {
            long startTime = System.currentTimeMillis();
            int gcd = gcdEuclid(fibs[i], fibs[i + 1]);
            long endTime = System.currentTimeMillis();
            long executionTime = endTime - startTime;
            System.out.print("     " + executionTime);
        }
    }

    public static int gcdEuclid(int m, int n) {
        if (m % n == 0)
            return n;
        else
            return gcdEuclid(n, m % n);
    }

    public static int gcd(int m, int n) {
        int gcd = 1;
        if (m % n == 0) return n;
        for (int k = n / 2; k >= 1; k--) {
            if (m % k == 0 && n % k == 0) {
                gcd = k;
                break;
            }
        }

        return gcd;
    }

    private static int[] calcFibIndexes40to45() {
        int[] fibs = new int[6];
        int i = 2;
        int f0 = 0;
        int f1 = 1;
        int f2 = 0;
        // Find fib numbers up to 39
        while (i < 40) {
            f2 = f0 + f1;
            f0 = f1;
            f1 = f2;
            i++;
        }
        // Next fib will be at index 40
        for (int j = 0; j < fibs.length; j++) {
            f2 = f0 + f1;
            fibs[j] = f2;
            f0 = f1;
            f1 = f2;
        }

        return fibs;
    }

}

