void reExecutePeriodic(RunnableScheduledFuture<?> task) {
    if (!canRunInCurrentRunState(task.isPeriodic())) {
        return;
    }
    scheduledTaskQueue.add(task);
    if (!workerCanRun()) {
        ensurePrestart();
    }
}

