abstract class AbstractOperation {
    private final long nativeHandle;
    private final Graph graph;
    private final int numOutputs;
    private final List<Output<?>> outputs;
    private final ExecutionEnvironment executionEnvironment;

    AbstractOperation(Graph graph, long nativeHandle, int numOutputs, ExecutionEnvironment env) {
        this.graph = graph;
        this.nativeHandle = nativeHandle;
        this.numOutputs = numOutputs;
        this.executionEnvironment = env;
        this.outputs = new ArrayList<>(numOutputs);
        initializeOutputs();
    }

    private void initializeOutputs() {
        for (int i = 0; i < numOutputs; i++) {
            outputs.add(createOutput(i));
        }
    }

    protected abstract Output<?> createOutput(int index);

    public List<Output<?>> outputList() {
        return Collections.unmodifiableList(outputs);
    }

    public Output<?> output() {
        return output(0);
    }

    public Output<?> output(int index) {
        if (index < 0 || index >= numOutputs) {
            throw new IndexOutOfBoundsException("Invalid output index: " + index);
        }
        return outputs.get(index);
    }

    public long getUnsafeNativeHandle() {
        return nativeHandle;
    }

    public Graph graph() {
        return graph;
    }

    public ExecutionEnvironment executionEnvironment() {
        return executionEnvironment;
    }

    public DataType dtype() {
        return output().dtype();
    }

    public Shape shape() {
        return output().shape();
    }

    public Tensor<?> tensor() {
        return output().tensor();
    }

    public int numberOfOutputs() {
        return numOutputs;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("Operation(")
          .append("handle=").append(nativeHandle)
          .append(", outputs=[");

        for (int i = 0; i < outputs.size(); i++) {
            sb.append(outputs.get(i));
            if (i < outputs.size() - 1) {
                sb.append(", ");
            }
        }

        sb.append("])");
        return sb.toString();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof AbstractOperation)) return false;
        AbstractOperation that = (AbstractOperation) o;
        return nativeHandle == that.nativeHandle;
    }

    @Override
    public int hashCode() {
        return Objects.hash(nativeHandle);
    }

    public void close() {
        if (nativeHandle != 0) {

import java.util.Scanner;

public class FirstDayOfMonth {
    public static void main(String[] args) {
        // Prompt the user to enter the year and first day of the year
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the year: ");
        int year = input.nextInt();
        System.out.print("Enter the first day of the year (0 for Sunday, 1 for Monday, etc.): ");
        int firstDay = input.nextInt();

        // Define a list of month names and the number of days in each month
        String[] monthNames = {"January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"};
        int[] daysInMonth = {31, 28 + (year % 4 == 0 && year % 100 != 0 || year % 400 == 0 ? 1 : 0), 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

        // Display the first day of each month in the year
        for (int i = 0; i < 12; i++) {
            // Determine the first day of the current month
            int firstDayOfMonth = (firstDay + ((i == 0) ? 0 : daysInMonth[i - 1])) % 7;

            // Display the first day of the current month
            System.out.printf("%s 1, %d is %s\n", monthNames[i], year, getDayName(firstDayOfMonth));

            // Update the first day for the next month
            firstDay = firstDayOfMonth;
        }
    }

    // Returns the name of a day given its number (0 = Sunday, 1 = Monday, etc.)
    private static String getDayName(int day) {
        String[] dayNames = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
        return dayNames[day];
    }
}

class Writer {
    public int dayOfYear(String date) {
        int[] dayOfMonth = new int[]{31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        String[] strs = date.split("-");
        int year = Integer.valueOf(strs[0]);
        int month = Integer.valueOf(strs[1]);
        int day = Integer.valueOf(strs[2]);
        if (isSpe(year)) {
            dayOfMonth[1] = 29;
        }
        int ans = 0;
        for (int i = 1; i < month; i++) {
            ans += dayOfMonth[i - 1];
        }
        return ans + day;
    }

    private boolean isSpe(int year) {
        if (year % 100 == 0) {
            return year % 400 == 0;
        } else {
            return year % 4 == 0;
        }
    }

}

import org.eclipse.emf.ecore.EObject;

/**
 * Interface representing an override operation in the Alloy language modeling framework.
 * Defines a binary operation where one term can override or replace another.
 */
public interface ALSOverride extends EObject {

    /**
     * Retrieves the left operand of the override operation.
     *
     * @return The term representing the left side of the override operation
     */
    ALSTerm getLeftOperand();

    /**
     * Sets the left operand for the override operation.
     *
     * @param value The term to be set as the left operand
     */
    void setLeftOperand(ALSTerm value);

    /**
     * Retrieves the right operand of the override operation.
     *
     * @return The term representing the right side of the override operation
     */
    ALSTerm getRightOperand();

    /**
     * Sets the right operand for the override operation.
     *
     * @param value The term to be set as the right operand
     */
    void setRightOperand(ALSTerm value);

    /**
     * Checks if the left operand is set and not null.
     *
     * @return true if the left operand is present, false otherwise
     */
    boolean isSetLeftOperand();

    /**
     * Checks if the right operand is set and not null.
     *
     * @return true if the right operand is present, false otherwise
     */
    boolean isSetRightOperand();

    /**
     * Unsets the left operand, removing its current reference.
     */
    void unsetLeftOperand();

    /**
     * Unsets the right operand, removing its current reference.
     */
    void unsetRightOperand();
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
 
public class EchoServer {
 
    public static void main(String[] args) throws IOException {
        try (ServerSocket listener = new ServerSocket(12321)) {
            while (true) {
                Socket conn = listener.accept();
                Thread clientThread = new Thread(() -> handleClient(conn));
                clientThread.start();
            }
        }
    }
 
    private static void handleClient(Socket connArg) {
        Charset utf8 = StandardCharsets.UTF_8;
 
        try (Socket conn = connArg) {
            BufferedReader in = new BufferedReader(
                    new InputStreamReader(conn.getInputStream(), utf8));
 
            PrintWriter out = new PrintWriter(
                    new OutputStreamWriter(conn.getOutputStream(), utf8),
                    true);
 
            String line;
            while ((line = in.readLine()) != null) {
                out.println(line);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.net.HttpURLConnection;
import java.net.MalformedURLException;
import java.net.URL;

import com.rockagen.commons.http.RequestMethod;

public static String sendHttpRequest(String target, String body, String proxy, RequestMethod method) throws IOException {

    URL url = null;
    try {
        url = new URL(target);
    } catch (MalformedURLException e) {
        e.printStackTrace();
    }

    HttpURLConnection conn = null;
    InputStream inputStream = null;
    String result = null;

    try {
        conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod(method.toString());
        conn.setDoInput(true);
        conn.setDoOutput(true);

        if (proxy != null && !proxy.isEmpty()) {
            String[] proxySplit = proxy.split(":");
            String proxyHost = proxySplit[0];
            int proxyPort = Integer.parseInt(proxySplit[1]);
            conn = (HttpURLConnection) url.openConnection(new java.net.Proxy(java.net.Proxy.Type.HTTP,
                    new java.net.InetSocketAddress(proxyHost, proxyPort)));
        }

        if (body != null && !body.isEmpty()) {
            conn.getOutputStream().write(body.getBytes("UTF-8"));
            conn.getOutputStream().flush();
            conn.getOutputStream().close();
        }

        if (conn.getResponseCode() == HttpURLConnection.HTTP_OK || conn.getResponseCode() == HttpURLConnection.HTTP_CREATED) {
            inputStream = conn.getInputStream();
            Reader reader = new InputStreamReader(inputStream);
            StringBuilder sb = new StringBuilder();
            char[] buffer = new char[1024];
            int n;
            while ((n = reader.read(buffer)) != -1) {
                sb.append(buffer, 0, n);
            }
            result = sb.toString();
        }

    } catch (IOException e) {
        e.printStackTrace();
    } finally {
        if (inputStream != null) {
            try {
                inputStream.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
        if (conn != null) {
            conn.disconnect();
        }
    }

    return result;
}

public DynamoDBScanExpression withFilterConditionEntry(String attributeName, Condition condition) {
    if (filterCondition == null) {
        filterCondition = new HashMap<String, Condition>();
    }
    filterCondition.put(attributeName, condition);
    return this;
}

/**
 * Employee record with salary operations.
 */
public class Employee {
    private int employeeId;
    private String firstName;
    private String lastName;
    private int monthlySalary;

    public Employee() {
    }

    public Employee(int employeeId, String firstName, String lastName, int monthlySalary) {
        this.employeeId = employeeId;
        this.firstName = firstName;
        this.lastName = lastName;
        this.monthlySalary = monthlySalary;
    }

    public int getID() {
        return employeeId;
    }

    public void setID(int employeeId) {
        this.employeeId = employeeId;
    }

    public String getFirstName() {
        return firstName;
    }

    public void setFirstName(String firstName) {
        this.firstName = firstName;
    }

    public String getLastName() {
        return lastName;
    }

    public void setLastName(String lastName) {
        this.lastName = lastName;
    }

    public int getSalary() {
        return monthlySalary;
    }

    public void setSalary(int monthlySalary) {
        this.monthlySalary = monthlySalary;
    }

    public String getName() {
        return firstName + " " + lastName;
    }

    public int getAnnualSalary() {
        return monthlySalary * 12;
    }

    public int raiseSalary(int percent) {
        int raise = (monthlySalary * percent) / 100;
        monthlySalary += raise;
        return monthlySalary;
    }

    @Override
    public String toString() {
        return "Employee[id=" + employeeId + ",name=" + firstName + " " + lastName + ",salary=" + monthlySalary + ']';
    }
}

