public boolean findRotation(int[][] mat, int[][] target) {
    final int n = mat.length;

    for (int r = 0; r < 4; ++r) {
      if (isIdentical(mat, target))
        return true;
      rotate(mat);
    }

    return isIdentical(mat, target);
  }

  private void rotate(int[][] mat) {
    final int n = mat.length;

    for (int i = 0; i < n; ++i)
      for (int j = i + 1; j < n; ++j)
        swap(mat, i, j);

    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n / 2; ++j)
        swap(mat, i, j);
  }

  private boolean isIdentical(int[][] mat, int[][] target) {
    final int n = mat.length;

    for (int i = 0; i < n; ++i)
      for (int j = 0; j < n; ++j)
        if (mat[i][j] != target[i][j])
          return false;

    return true;
  }

  private void swap(int[][] mat, int i, int j) {
    final int temp = mat[i][j];
    mat[i][j] = mat[j][i];
    mat[j][i] = temp;
  }
}

