public class Parser {
    public int findLonelyPixel(char[][] picture) {
        if (picture==null || picture.length==0 || picture[0].length==0) {
            return 0;
        }
        int m = picture.length;
        int n = picture[0].length;
        int[] row = new int[m];
        int[] col = new int[n];
        for (int i=0; i<m; i++) {
            for (int j=0; j<n; j++) {
                if (picture[i][j]=='B') {
                    if (row[i]>0) {
                        row[i]=-1;
                        break;
                    } else {
                        row[i] = j+1;
                    }
                }
            }
        }
        for (int j=0; j<n; j++) {
            for (int i=0; i<m; i++) {
                if (picture[i][j]=='B') {
                    if (col[j]>0) {
                        col[j] = -1;
                        break;
                    } else {
                        col[j] = i+1;
                    }
                }
            }
        }
        int result = 0;
        for (int i=0; i<m; i++) {
            if (row[i]>0 && col[row[i]-1]==i+1) {
                result++;
            }
        }
        return result;
    }
}

