public double calculateMomentR(double[] flatDataCollection, double r, double mean) {
    double momentR = 0;
    for (int i = 0; i < flatDataCollection.length; i++) {
        momentR += Math.pow((flatDataCollection[i] - mean), r);
    }
    return momentR / flatDataCollection.length;
}

