import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import org.apache.commons.codec.binary.Base64;

public class MD5PasswordEncryptor implements PasswordEncryptor {

    private MessageDigest digest;
    private Base64 encoder;

    public MD5PasswordEncryptor() {
        try {
            digest = MessageDigest.getInstance("MD5");
            encoder = new Base64();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not available", e);
        }
    }

    @Override
    public String encodePassword(String password, Object salt) {
        if (password == null || salt == null) {
            throw new IllegalArgumentException("Password and salt cannot be null");
        }

        String saltedPassword = password + salt.toString();
        byte[] passwordHash = digest.digest(saltedPassword.getBytes());
        return new String(encoder.encode(passwordHash));
    }

    @Override
    public boolean isPasswordValid(String cypherPass, String password, Object salt) {
        if (cypherPass == null || password == null || salt == null) {
            throw new IllegalArgumentException("CypherPass, password, and salt cannot be null");
        }

        String encryptedPassword = encodePassword(password, salt);
        return cypherPass.equals(encryptedPassword);
    }

    public static void main(String[] args) {
        MD5PasswordEncryptor encryptor = new MD5PasswordEncryptor();
        String password = "securePassword123";
        String salt = "randomSaltValue";

        String encryptedPassword = encryptor.encodePassword(password, salt);
        System.out.println("Encrypted Password: " + encryptedPassword);

        boolean isValid = encryptor.isPasswordValid(encryptedPassword, password, salt);
        System.out.println("Password Validation Result: " + isValid);
    }
}

interface PasswordEncryptor {
    String encodePassword(String password, Object salt);
    boolean isPasswordValid(String cypherPass, String password, Object salt);
}

import java.util.Arrays;
 
public class MatrixChainMultiplication {
 
    public static void main(String[] args) {
        runMatrixChainMultiplication(new int[] {5, 6, 3, 1});
        runMatrixChainMultiplication(new int[] {1, 5, 25, 30, 100, 70, 2, 1, 100, 250, 1, 1000, 2});
        runMatrixChainMultiplication(new int[] {1000, 1, 500, 12, 1, 700, 2500, 3, 2, 5, 14, 10});
    }
 
    private static void runMatrixChainMultiplication(int[] dims) {
        System.out.printf("Array Dimension  = %s%n", Arrays.toString(dims));
        System.out.printf("Cost             = %d%n", matrixChainOrder(dims));
        System.out.printf("Optimal Multiply = %s%n%n", getOptimalParenthesizations());
    }
 
    private static int[][]cost;
    private static int[][]order;
 
    public static int matrixChainOrder(int[] dims) {
        int n = dims.length - 1;
        cost = new int[n][n];
        order = new int[n][n];
 
        for (int lenMinusOne = 1 ; lenMinusOne < n ; lenMinusOne++) {
            for (int i = 0; i < n - lenMinusOne; i++) {
                int j = i + lenMinusOne;
                cost[i][j] = Integer.MAX_VALUE;
                for (int k = i; k < j; k++) {
                    int currentCost = cost[i][k] + cost[k+1][j] + dims[i]*dims[k+1]*dims[j+1];
                    if (currentCost < cost[i][j]) {
                        cost[i][j] = currentCost;
                        order[i][j] = k;
                    }
                }
            }
        }
        return cost[0][n-1];
    }
 
    private static String getOptimalParenthesizations() {
        return getOptimalParenthesizations(order, 0, order.length - 1);
    }
 
    private static String getOptimalParenthesizations(int[][]s, int i, int j) {
        if (i == j) {
            return String.format("%c", i+65);
        }
        else {
            StringBuilder sb = new StringBuilder();
            sb.append("(");
            sb.append(getOptimalParenthesizations(s, i, s[i][j]));
            sb.append(" * ");
            sb.append(getOptimalParenthesizations(s, s[i][j] + 1, j));
            sb.append(")");
            return sb.toString();
        }
    }
 
}

