public class QuickSortImproved {

    public static void quickSort(int[] list) {
        quickSort(list, 0, list.length - 1);
    }

    private static void quickSort(int[] list, int first, int last) {
        if (last > first) {
            int pivotIndex = partition(list, first, last);
            quickSort(list, first, pivotIndex - 1);
            quickSort(list, pivotIndex + 1, last);
        }
    }

    private static int partition(int[] list, int first, int last) {
        int pivotIndex = medianOfThree(list, first, last);
        int pivotValue = list[pivotIndex];
        int left = first + 1;
        int right = last;
        while (true) {
            while (left <= right && list[left] <= pivotValue) {
                left++;
            }
            while (left <= right && list[right] >= pivotValue) {
                right--;
            }
            if (right < left) {
                break;
            }
            int temp = list[left];
            list[left] = list[right];
            list[right] = temp;
        }
        int temp = list[first];
        list[first] = list[right];
        list[right] = temp;
        return right;
    }

    private static int medianOfThree(int[] list, int first, int last) {
        int mid = (first + last) / 2;
        if (list[first] > list[mid]) {
            int temp = list[first];
            list[first] = list[mid];
            list[mid] = temp;
        }
        if (list[mid] > list[last]) {
            int temp = list[mid];
            list[mid] = list[last];
            list[last] = temp;
        }
        if (list[first] > list[mid]) {
            int temp = list[first];
            list[first] = list[mid];
            list[mid] = temp;
        }
        return mid;
    }

    public static void main(String[] args) {
        int[] list = {3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5};
        quickSort(list);
        System.out.println(Arrays.toString(list));
    }
}

public class CompoundDuration {
 
    public static void main(String[] args) {
        compound(7259);
        compound(86400);
        compound(6000_000);
    }
 
    private static void compound(long seconds) {
        StringBuilder sb = new StringBuilder();
 
        seconds = addUnit(sb, seconds, 604800, " wk, ");
        seconds = addUnit(sb, seconds, 86400, " d, ");
        seconds = addUnit(sb, seconds, 3600, " hr, ");
        seconds = addUnit(sb, seconds, 60, " min, ");
        addUnit(sb, seconds, 1, " sec, ");
 
        sb.setLength(sb.length() > 2 ? sb.length() - 2 : 0);
 
        System.out.println(sb);
    }
 
    private static long addUnit(StringBuilder sb, long sec, long unit, String s) {
        long n;
        if ((n = sec / unit) > 0) {
            sb.append(n).append(s);
            sec %= (n * unit);
        }
        return sec;
    }
}

import java.util.Scanner;

public class Calculator {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        int ans = 0;

        while (m > n) {
            if (m % 2 == 0) {
                m /= 2;
            } else if (m % 3 == 0) {
                m /= 3;
            } else {
                System.out.println(-1);
                return;
            }
            ans++;
        }

        if (n!= m) {
            System.out.println(-1);
        } else {
            System.out.println(ans);
        }
    }
}

import java.util.Scanner;

public class Builder {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter a String and a character to count it's occurrences:");
        String str = in.next();
        char ch = in.next().charAt(0);

        System.out.println("Character " + ch + " occurs " + count(str, ch) + " times in " + str);
        in.close();
    }

    public static int count(String str, char a, int high) {
        if (high > 0) {
            return str.charAt(high) == a ? (1 + count(str, a, high - 1)) : (count(str, a, high - 1));
        } else {
            return 0;
        }
    }

    public static int count(String str, char a) {
        return count(str, a, str.length() - 1);
    }
}

import java.util.Random;
import java.util.Scanner;
 
public class CoinToss {
    public static void main(String[] args) {
        Random random = new Random();
        Scanner scanner = new Scanner(System.in);
        boolean first = random.nextBoolean();
        String you = "";
        String me = "";
        if (first) {
            me = random.nextBoolean()? "HHH" : "TTT";
            System.out.printf("I choose first and will win on first seeing %s in the list of tosses\n", me);
            do {
                System.out.print("What sequence of three Heads/Tails will you win with: ");
                you = scanner.nextLine();
            } while (you.length()!= 3 ||!you.matches("[HT]{3}"));
        } else {
            do {
                System.out.print("After you: What sequence of three Heads/Tails will you win with: ");
                you = scanner.nextLine();
            } while (you.length()!= 3 ||!you.matches("[HT]{3}"));
            me = (you.charAt(1) == 'T'? "H" : "T") + you.substring(0, 2);
            System.out.printf("I win on first seeing %s in the list of tosses\n", me);
        }
        System.out.print("Rolling:\n  ");
        String rolled = "";
        while (true) {
            rolled += random.nextBoolean()? "H" : "T";
            System.out.print(rolled.charAt(rolled.length() - 1));
            if (rolled.endsWith(you)) {
                System.out.println("\n  You win!");
                break;
            }
            if (rolled.endsWith(me)) {
                System.out.println("\n  I win!");
                break;
            }
            try {
                Thread.sleep(1000);
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
        }
    }
}

