import collections
from typing import List

class Shape:

    def __init__(self):
        self.mst = collections.defaultdict(set)

    def findRequiredPreRequisite(self, numCourses: int, prerequisites: List[List[int]], queries: List[List[int]]) -> List[bool]:
        res = [False] * len(queries)
        people = [[] for _ in range(numCourses)]
        compress_finish = [False] * numCourses
        q = collections.deque()
        for sponsor, course in prerequisites:
            people[course].append(sponsor)

        for course in range(numCourses):
            if self.gcd(people[course]):
                if not compress_finish[course]:
                    while True:
                        compress_finish[course] = True
                        count = len(people[course])
                        for pre_course in people[course]:
                            if pre_course in compress_finish:
                                continue
                            people[pre_course] = []

                        if count == 0:
                            break

                        q.append(course)

                    while q:
                        c = q.popleft()
                        for pre_course in people[c]:
                            if not compress_finish[pre_course]:
                                q.append(pre_course)
                                compress_finish[pre_course] = True
        for u, v in queries:
            res[queries.index([u, v])] = v in self.mst[u]
        return res

    @staticmethod
    def gcd(nums):
        gcd = 0
        for num in nums:
            if num == 0:
                continue
            gcd = Shape.gcd(num, gcd)
        return gcd

