import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class ReflectionUtils {

    public static List<Field> getAllDeclaredFields(Class<?> leafClass) {
        List<Field> fieldsList = new ArrayList<>();
        Class<?> currentClass = leafClass;
        while (currentClass != null) {
            fieldsList.addAll(Arrays.asList(currentClass.getDeclaredFields()));
            currentClass = currentClass.getSuperclass();
        }
        return fieldsList;
    }
}

import java.util.Scanner;

public class PolygonAreaCalculator {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Read in the coordinates of the four vertices
        double[][] vertices = new double[4][2];
        System.out.print("Enter x1, y1, x2, y2, x3, y3, x4, y4: ");
        for (int i = 0; i < 4; i++) {
            vertices[i][0] = input.nextDouble();
            vertices[i][1] = input.nextDouble();
        }

        // Calculate the areas of the four triangles
        double[] areas = new double[4];
        areas[0] = getTriangleArea(vertices[0], vertices[1], vertices[2]);
        areas[1] = getTriangleArea(vertices[0], vertices[1], vertices[3]);
        areas[2] = getTriangleArea(vertices[1], vertices[2], vertices[3]);
        areas[3] = getTriangleArea(vertices[2], vertices[3], vertices[0]);

        // Sort the areas in increasing order
        java.util.Arrays.sort(areas);

        // Print the areas
        System.out.print("The areas are ");
        for (double area : areas) {
            System.out.printf("%.2f ", area);
        }
        System.out.println();
    }

    public static double getTriangleArea(double[] p1, double[] p2, double[] p3) {
        // Calculate the area of the triangle using the cross product
        double a = distance(p1, p2);
        double b = distance(p2, p3);
        double c = distance(p3, p1);
        double s = (a + b + c) / 2;
        double area = Math.sqrt(s * (s - a) * (s - b) * (s - c));
        return area;
    }

    public static double distance(double[] p1, double[] p2) {
        double dx = p2[0] - p1[0];
        double dy = p2[1] - p1[1];
        double distance = Math.sqrt(dx * dx + dy * dy);
        return distance;
    }
}

import com.intellij.codeInsight.AnnotationUtil;
import com.intellij.codeInspection.ProblemHighlightType;
import com.intellij.psi.*;
import com.siyeh.InspectionGadgetsBundle;
import com.siyeh.ig.BaseInspection;
import com.siyeh.ig.BaseInspectionVisitor;
import com.siyeh.ig.InspectionGadgetsFix;
import com.siyeh.ig.fixes.RemoveModifierFix;
import org.jetbrains.annotations.NotNull;

public class FinalMethodInFinalClassInspection extends BaseInspection {

    @Override
    @NotNull
    public String getDisplayName() {
        return InspectionGadgetsBundle.message("final.method.in.final.class.display.name");
    }

    @Override
    @NotNull
    public String buildErrorString(Object... infos) {
        return InspectionGadgetsBundle.message("final.method.in.final.class.problem.descriptor");
    }

    @Override
    public BaseInspectionVisitor buildVisitor() {
        return new FinalMethodInFinalClassVisitor();
    }

    private static class FinalMethodInFinalClassVisitor extends BaseInspectionVisitor {

        @Override
        public void visitMethod(@NotNull PsiMethod method) {
            super.visitMethod(method);
            if (!method.hasModifierProperty(PsiModifier.FINAL)) {
                return;
            }
            final PsiClass containingClass = method.getContainingClass();
            if (containingClass == null || !containingClass.hasModifierProperty(PsiModifier.FINAL)) {
                return;
            }
            if (method.hasModifierProperty(PsiModifier.STATIC) && AnnotationUtil.isAnnotated(method, SafeVarargs.class.getName(), true)) {
                return;
            }

            registerModifierError(PsiModifier.FINAL, method.getModifierList().getNode().findChildByType(JavaTokenType.FINAL_KEYWORD).getPsi(), ProblemHighlightType.WARNING, buildErrorString(), (InspectionGadgetsFix) new RemoveModifierFix(PsiModifier.FINAL, method));
        }
    }
}

public class ComputeWeeklyHours {
   public static void main(String[] args) {
      int[][] weeklyHours = {
         {2, 4, 3, 4, 5, 8, 8},
         {7, 3, 4, 3, 3, 4, 4},
         {3, 3, 4, 3, 3, 2, 2},
         {9, 3, 4, 7, 3, 4, 1},
         {3, 5, 4, 3, 6, 3, 8},
         {3, 4, 4, 6, 3, 4, 4},
         {3, 7, 4, 8, 3, 8, 4},
         {6, 3, 5, 9, 2, 7, 9}
      };

      int[] totalHours = new int[weeklyHours.length];

      // Compute the total hours for each employee
      for (int i = 0; i < weeklyHours.length; i++) {
         int sum = 0;
         for (int j = 0; j < weeklyHours[i].length; j++) {
            sum += weeklyHours[i][j];
         }
         totalHours[i] = sum;
      }

      // Create a list of tuples containing employee number and total hours
      List<Tuple<Integer, Integer>> employeeHours = new ArrayList<>();
      for (int i = 0; i < totalHours.length; i++) {
         employeeHours.add(new Tuple<>(i, totalHours[i]));
      }

      // Sort the list in decreasing order of total hours
      employeeHours.sort((a, b) -> b.getSecond() - a.getSecond());

      // Display the sorted list
      for (Tuple<Integer, Integer> employee : employeeHours) {
         System.out.printf("Employee %d: %d hours\n", employee.getFirst(), employee.getSecond());
      }
   }
}

