class Library {
    public int minimumAddedCoins(int[] coins, int target) {
        int ret = 0;
        int max = 0;
        Arrays.sort(coins);
        for (int coin : coins) {
            if (max >= target)
                break;
            while (coin > max+1 && max < target) {
                ret++;
                max += max+1;
            }
            max += coin;
        }
        while (max < target) {
            ret++;
            max += max + 1;
        }
        return ret;
    }
}

