public synchronized InitImpl buildInit(final Method initMethod, final boolean isLazy) {
    if (initMethod == null) {
        throw new IllegalArgumentException("initMethod cannot be null");
    }
    if (!Modifier.isPublic(initMethod.getModifiers())) {
        throw new IllegalArgumentException("initMethod must be public");
    }
    if (!Modifier.isStatic(initMethod.getModifiers())) {
        throw new IllegalArgumentException("initMethod must be static");
    }
    if (initMethod.getParameterCount() != 0) {
        throw new IllegalArgumentException("initMethod must not have parameters");
    }
    if (initMethod.getReturnType() != void.class) {
        throw new IllegalArgumentException("initMethod must have a void return type");
    }
    return new InitImpl(initMethod, isLazy);
}

