    for (Map.Entry<Integer, E> entry : blocks.entrySet()) {
        if (entry.getKey() % numShards == shardId) {
            shardedMap.put(entry.getKey(), entry.getValue());
        }
    }

    // Return an iterator over the values in the new map
    return shardedMap.values().iterator();
}

