PdfChunk add(PdfChunk chunk) {

        if (chunk == null || chunk.toString().equals("")) {
            return null;
        }

        PdfChunk overflow = chunk.split(width);
        newlineSplit = (chunk.isNewlineSplit() || overflow == null);

        if (chunk.isTab()) {
            Object[] tab = (Object[])chunk.getAttribute(Chunk.TAB);
            float tabPosition = ((Float)tab[1]).floatValue();
            boolean newline = ((Boolean)tab[2]).booleanValue();
            if (newline && tabPosition < originalWidth - width) {
                return chunk;
            }
            width = originalWidth - tabPosition;
            chunk.adjustLeft(left);
            addToLine(chunk);
        }

        else if (chunk.length() > 0 || chunk.isImage()) {
            if (overflow != null)
                chunk.trimLastSpace();
            width -= chunk.width();
            addToLine(chunk);
        }

        else if (line.size() < 1) {
            chunk = overflow;
            overflow = chunk.truncate(width);
            width -= chunk.width();
            if (chunk.length() > 0) {
                addToLine(chunk);
                return overflow;
            }

            else {
                if (overflow != null)
                    addToLine(overflow);
                return null;
            }
        }
        else {
            width += ((PdfChunk)(line.get(line.size() - 1))).trimLastSpace();
        }
        return overflow;
    }

import java.util.List;
import java.util.ArrayList;
import java.util.Scanner;
import java.util.Collections;
 
 
public class ReversalGame {
    private List<Integer> gameList;
 
    public ReversalGame() {
        initialize();
    }
 
    public void play() throws Exception {
        int i = 0;
        int moveCount = 0;
        Scanner scanner = new Scanner(System.in);
        while (true) {
            System.out.println(gameList);
            System.out.println("Please enter a index to reverse from 2 to 9. Enter 99 to quit");
            i = scanner.nextInt();
            if (i == 99) {
                break;
            }
            if (i < 2 || i > 9) {
                System.out.println("Invalid input");
            } else {
                moveCount++;
                reverse(i);
                if (isSorted()) {
                    System.out.println("Congratulations you solved this in " + moveCount + " moves!");
                    break;
                }
            }
 
        }
        scanner.close();
    }
 
    private void reverse(int position) {
        Collections.reverse(gameList.subList(0, position));
    }
 
    private boolean isSorted() {
        for (int i=0; i < gameList.size() - 1; ++i) {
            if (gameList.get(i).compareTo(gameList.get(i + 1)) > 0) {
                return false;
            }
        }
        return true;
    }
 
    private void initialize() {
        this.gameList = new ArrayList<Integer>(9);
        for (int i=1; i < 10; ++i) {
            gameList.add(i);
        }
        while (isSorted()) {
            Collections.shuffle(gameList);
        }
    }
 
 
    public static void main(String[] args) {
        try {
            ReversalGame game = new ReversalGame();
            game.play();
        } catch (Exception e) {
            System.out.println(e.getMessage());
            e.printStackTrace();
        }
    }
}

import java.util.Comparator;

public class HeapSort {

    public static <E extends Comparable<E>> void heapSort(E[] list) {
        int n = list.length;

        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(list, n, i);
        }

        for (int i = n - 1; i >= 0; i--) {
            E temp = list[0];
            list[0] = list[i];
            list[i] = temp;
            heapify(list, i, 0);
        }
    }

    public static <E> void heapSort(E[] list, Comparator<? super E> comparator) {
        int n = list.length;

        for (int i = n / 2 - 1; i >= 0; i--) {
            heapify(list, n, i, comparator);
        }

        for (int i = n - 1; i >= 0; i--) {
            E temp = list[0];
            list[0] = list[i];
            list[i] = temp;
            heapify(list, i, 0, comparator);
        }
    }

    private static <E extends Comparable<E>> void heapify(E[] list, int n, int i) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && list[left].compareTo(list[largest]) > 0) {
            largest = left;
        }

        if (right < n && list[right].compareTo(list[largest]) > 0) {
            largest = right;
        }

        if (largest != i) {
            E temp = list[i];
            list[i] = list[largest];
            list[largest] = temp;
            heapify(list, n, largest);
        }
    }

    private static <E> void heapify(E[] list, int n, int i, Comparator<? super E> comparator) {
        int largest = i;
        int left = 2 * i + 1;
        int right = 2 * i + 2;

        if (left < n && comparator.compare(list[left], list[largest]) > 0) {
            largest = left;
        }

        if (right < n && comparator.compare(list[right], list[largest]) > 0) {
            largest = right;
        }

        if (largest != i) {
            E temp = list[i];
            list[i] = list[largest];
            list[largest] = temp;
            heapify(list, n, largest, comparator);
        }
    }

}

private void populateTranslatedTopicDatabase(final BuildData buildData,
            final Map<String, BaseTopicWrapper<?>> translatedTopics) throws BuildProcessingException {
        final List<ITopicNode> topicNodes = buildData.getContentSpec().getAllTopicNodes();
        final int showPercent = 10;
        final float total = topicNodes.size();
        float current = 0;
        int lastPercent = 0;

        for (final ITopicNode topicNode : topicNodes) {
            getTranslatedTopicForTopicNode(buildData, topicNode, translatedTopics);
            ++current;
            final int percent = Math.round(current / total * 100);
            if (percent - lastPercent >= showPercent) {
                lastPercent = percent;
                log.info("\tPopulate " + buildData.getBuildLocale() + " Database Pass " + percent + "% Done");
            }
        }
    }

protected void initialize(SarlCapacity source, JvmGenericType inferredJvmType) {

        assert source != null;
        assert inferredJvmType != null;
        if (Strings.isNullOrEmpty(source.getName())) {
            return;
        }

        final GenerationContext context = openContext(source, inferredJvmType,
                Collections.singleton(SarlAction.class));
        try {

            this.typeBuilder.copyDocumentationTo(source, inferredJvmType);

            inferredJvmType.setInterface(true);
            inferredJvmType.setAbstract(true);
            setVisibility(inferredJvmType, source);
            inferredJvmType.setStatic(false);
            inferredJvmType.setStrictFloatingPoint(false);
            inferredJvmType.setFinal(false);

            translateAnnotationsTo(source.getAnnotations(), inferredJvmType);

            appendConstrainedExtends(context, inferredJvmType, Capacity.class, SarlCapacity.class, source.getExtends());

            if (Utils.isCompatibleSARLLibraryOnClasspath(this.typeReferences, source)) {

                appendAOPMembers(
                        inferredJvmType,
                        source,
                        context);
            }

            appendFunctionalInterfaceAnnotation(inferredJvmType);

            appendSARLSpecificationVersion(context, source, inferredJvmType);

            appendSARLElementType(source, inferredJvmType);

            this.nameClashResolver.resolveNameClashes(inferredJvmType);
        } finally {
            closeContext(context);
        }

        appendCapacityContextAwareWrapper(source, inferredJvmType);
    }

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
 
public class Subleq {
 
    private List<Integer> memory = new ArrayList<Integer>();
 
    public void loadAndRun( String file ) {
        try {
            BufferedReader f = new BufferedReader( new FileReader( file ) );
            String line;
            while( ( line = f.readLine() )!= null ) {
                memory.add( Integer.parseInt( line ) );
            }
            f.close();
        } catch( IOException e ) {
            System.out.println( "Error reading file: " + e.getMessage() );
        }
        run();
    }
 
    private void run() {
        int pc = 0, next, a, b, c;
        char z;
        do {
            next = pc + 3;
            a = memory.get( pc ); b = memory.get( pc + 1 ); c = memory.get( pc + 2 );
            if( a == -1 ) {
                try {
                    z = (char) System.in.read();
                    memory.set( b, (int) z );
                } catch( IOException e ) {
                    System.out.println( "Error reading from stdin: " + e.getMessage() );
                }
            } else if( b == -1 ) {
                System.out.print( (char) memory.get( a ) );
            } else {
                memory.set( b, memory.get( b ) - memory.get( a ) );
                if( memory.get( b ) <= 0 ) next = c;
            }
            pc = next;
        } while( pc >= 0 );
    }
 
    public static void main( String[] args ) {
        Subleq s = new Subleq();
        if( args.length > 0 ) {
            s.loadAndRun( args[0] );
        } else {
            System.out.println( "usage: subleq <filename>" );
        }
    }
}

