import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;

public class TwoDColorChooser extends JFrame {
    private JButton[][] colorButtons;
    private JPanel displayPanel;
    private final Color[][] colors = {
        {Color.RED, Color.GREEN, Color.BLUE},
        {Color.YELLOW, Color.ORANGE, Color.PINK},
        {Color.CYAN, Color.MAGENTA, Color.LIGHT_GRAY}
    };

    public TwoDColorChooser() {
        setTitle("2D Color Chooser");
        setSize(400, 400);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        displayPanel = new JPanel();
        displayPanel.setPreferredSize(new Dimension(400, 200));
        displayPanel.setBackground(Color.WHITE);
        add(displayPanel, BorderLayout.SOUTH);

        JPanel colorButtonPanel = new JPanel();
        colorButtonPanel.setLayout(new GridLayout(colors.length, colors[0].length));
        colorButtons = new JButton[colors.length][colors[0].length];

        ColorButtonListener listener = new ColorButtonListener();

        for (int row = 0; row < colors.length; row++) {
            for (int col = 0; col < colors[row].length; col++) {
                colorButtons[row][col] = new JButton();
                colorButtons[row][col].setBackground(colors[row][col]);
                colorButtons[row][col].setOpaque(true);
                colorButtons[row][col].setBorderPainted(false);
                colorButtons[row][col].addActionListener(listener);
                colorButtonPanel.add(colorButtons[row][col]);
            }
        }

        add(colorButtonPanel, BorderLayout.CENTER);
    }

    private class ColorButtonListener implements ActionListener {
        @Override
        public void actionPerformed(ActionEvent e) {
            JButton clickedButton = (JButton) e.getSource();
            displayPanel.setBackground(clickedButton.getBackground());
        }
    }

    public static void main(String[] args) {
        SwingUtilities.invokeLater(() -> {
            TwoDColorChooser colorChooser = new TwoDColorChooser();
            colorChooser.setVisible(true);
        });
    }
}

public static String escape(String text) {
    return text.replaceAll("[-[\\]{}()*+?.\\\\^$|#\\s]", "\\\\$0");
}

public static String[] multisplit(String string, String[] seps) {
    String sep_regex = String.join("|", Arrays.stream(seps).map(RegExp::escape).collect(Collectors.toList()));
    return string.split(sep_regex);
}

import java.util.List;
import java.util.Optional;
import org.activiti.api.process.runtime.events.ProcessRuntimeEvent;
import org.activiti.api.runtime.event.impl.ToMessageSubscriptionCancelledConverter;
import org.activiti.engine.delegate.event.ActivitiEvent;
import org.activiti.engine.delegate.event.ActivitiEventListener;
import org.activiti.engine.delegate.event.ActivitiEventType;
import org.activiti.engine.delegate.event.impl.ActivitiEntityEventImpl;
import org.activiti.engine.impl.persistence.entity.MessageEventSubscriptionEntity;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.util.CollectionUtils;

public class MessageSubscriptionCancelledListenerDelegate implements ActivitiEventListener {

    private static final Logger LOGGER = LoggerFactory.getLogger(MessageSubscriptionCancelledListenerDelegate.class);

    private List<ProcessRuntimeEventListener> processRuntimeEventListeners;
    private ToMessageSubscriptionCancelledConverter converter;

    public MessageSubscriptionCancelledListenerDelegate(List<ProcessRuntimeEventListener> processRuntimeEventListeners,
                                                        ToMessageSubscriptionCancelledConverter converter) {
        this.processRuntimeEventListeners = processRuntimeEventListeners;
        this.converter = converter;
    }

    @Override
    public void onEvent(ActivitiEvent event) {
        if (isValidEvent(event)) {
            Optional.ofNullable(converter.from((ActivitiEntityEventImpl) event))
                .ifPresent(convertedEvent -> {
                    if (!CollectionUtils.isEmpty(processRuntimeEventListeners)) {
                        processRuntimeEventListeners.forEach(listener -> {
                            try {
                                listener.onEvent(convertedEvent);
                            } catch (Exception ex) {
                                LOGGER.error("Error processing message subscription cancelled event", ex);
                            }
                        });
                    }
                });
        }
    }

    private boolean isValidEvent(ActivitiEvent event) {
        return ActivitiEventType.ENTITY_DELETED.equals(event.getType()) &&
            event instanceof ActivitiEntityEventImpl &&
            ((ActivitiEntityEventImpl) event).getEntity() instanceof MessageEventSubscriptionEntity;
    }

    @Override
    public boolean isFailOnException() {
        return false;
    }
}

