public class Matrix {
    public static double shoelaceArea(List<Point> v) {
        int n = v.size();
        double a = 0.0;
        for (int i = 0; i < n - 1; i++) {
            a += v.get(i).x * v.get(i + 1).y - v.get(i + 1).x * v.get(i).y;
        }
        return Math.abs(a + v.get(n - 1).x * v.get(0).y - v.get(0).x * v.get(n - 1).y) / 2.0;
    }
 
    public static void main(String[] args) {
        List<Point> v = Arrays.asList(
            new Point(3, 4), new Point(5, 11), new Point(12, 8), new Point(9, 5), new Point(5, 6)
        );
        double area = shoelaceArea(v);
        System.out.println("Given a polygon with vertices at " + v + ",");
        System.out.println("its area is " + area);
    }
}

public class AlmostPrime {
    public static void main(String[] args) {
        for (int k = 1; k <= 5; k++) {
            System.out.print("k = " + k + ":");
 
            for (int i = 2, c = 0; c < 10; i++) {
                if (kprime(i, k)) {
                    System.out.print(" " + i);
                    c++;
                }
            }
 
            System.out.println("");
        }
    }
 
    public static boolean kprime(int n, int k) {
        int f = 0;
        for (int p = 2; f < k && p * p <= n; p++) {
            while (n % p == 0) {
                n /= p;
                f++;
            }
        }
        return f + ((n > 1) ? 1 : 0) == k;
    }
}

