private boolean isPalindrome(String s) {
        int left = 0, right = s.length() - 1;
        while (left <= right) {
            if (s.charAt(left) != s.charAt(right)) return false;
            left++;
            right--;
        }
        return true;
    }

    void helper(String s, int k, Set<String> set) {
        Stack<String> stack = new Stack<> ();
        for (int i = 0; i < s.length() - k + 1; i++) {
            String subStr = s.substring(i, i + k);
            if (isPalindrome(subStr)) set.add(subStr);
            else {
                while (!stack.isEmpty() && stack.peek().length() >= s.length() - i - 1)
                    stack.pop();
                stack.push(subStr);
            }
        }
        while (!stack.isEmpty()) set.add(stack.pop());
    }

    public int kLengthPalindrome(String s, int k) {
        int count = 0;
        Set<String> set = new HashSet<> ();
        helper(s, k, set);
        for (String str : set) {
            if (str.length() == k) {
                count++;
            }
        }
        return count;
    }
}

