class Tree {
    public int destroyTargets(int[] arr, int space) {
        Map<Integer, int[]> map = new HashMap<>();
        for (int a : arr) {
            map.computeIfAbsent(a % space, key -> new int[1])[0]++;
        }
        int max = -1;
        int ans = -1;

        for (int a : arr) {
            int[] ints = map.get(a % space);
            if (ints[0] > max) {
                ans = a;
                max = ints[0];
            } else if (ints[0] == max && a < ans) {
                ans = a;
            }
        }
        return ans;
    }

}

