import org.apache.commons.lang3.StringUtils;
import org.apache.sling.api.resource.ResourceResolver;

public String getAbsoluteParent(String path, int parentLevel, ResourceResolver resourceResolver) {
    if (StringUtils.isBlank(path) || parentLevel < 1) {
        return "";
    }
    String absoluteParent = path;
    for (int i = 0; i < parentLevel; i++) {
        absoluteParent = resourceResolver.getParent(absoluteParent);
        if (null != absoluteParent && ("/jcr:content").equals(absoluteParent)) {
            absoluteParent = StringUtils.substringBeforeLast(absoluteParent, "/");
            absoluteParent = resourceResolver.getParent(absoluteParent);
        }
    }
    return (null != absoluteParent && !"/".equals(absoluteParent)) ? absoluteParent : "";
}

