@ContextConfiguration(locations = {
        "classpath:/applicationContext-resources.xml",
        "classpath:/applicationContext-dao.xml"
})
public abstract class BaseDaoTestCase extends AbstractJUnit4SpringContextTests {

    protected final Logger log = LoggerFactory.getLogger(getClass());
    protected ResourceBundle rb;

    public BaseDaoTestCase() {
        String className = this.getClass().getName();

        try {
            rb = ResourceBundle.getBundle(className);
        } catch (MissingResourceException mre) {
            log.warn("No resource bundle found for: " + className);
        }
    }

    protected void populate(Object obj) {
        if (rb == null) {
            return;
        }

        try {
            Enumeration<String> keys = rb.getKeys();
            while (keys.hasMoreElements()) {
                String key = keys.nextElement();
                BeanUtils.setProperty(obj, key, rb.getString(key));
            }
        } catch (Exception e) {
            log.error("Failed to populate object: " + e.getMessage());
            e.printStackTrace();
        }
    }

    protected String[] getConfigLocations() {
        return new String[]{
                "classpath:/applicationContext-resources.xml",
                "classpath:/applicationContext-dao.xml"
        };
    }
}

