import org.camunda.bpm.engine.test.Deployment;
import org.camunda.bpm.engine.test.PluggableProcessEngineTestCase;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class ExclusiveGatewayTest extends PluggableProcessEngineTestCase {

    @Deployment(resources = "exclusiveGatewayProcess.bpmn")
    public void testDecisionFunctionality() {
        // Test case 1: Input value 'email'
        Map<String, Object> variables = new HashMap<>();
        variables.put("input", "email");
        ProcessInstance processInstance = runtimeService.startProcessInstanceByKey("exclusiveGatewayProcess", variables);
        Task task = taskService.createTaskQuery().processInstanceId(processInstance.getId()).singleResult();
        assertEquals("Send e-mail for more information", task.getName());
        taskService.complete(task.getId());

        // Test case 2: Input value 'balance'
        variables.put("input", "balance");
        processInstance = runtimeService.startProcessInstanceByKey("exclusiveGatewayProcess", variables);
        task = taskService.createTaskQuery().processInstanceId(processInstance.getId()).singleResult();
        assertEquals("Check account balance", task.getName());
        taskService.complete(task.getId());

        // Test case 3: Input value 'call'
        variables.put("input", "call");
        processInstance = runtimeService.startProcessInstanceByKey("exclusiveGatewayProcess", variables);
        task = taskService.createTaskQuery().processInstanceId(processInstance.getId()).singleResult();
        assertEquals("Call customer", task.getName());
        taskService.complete(task.getId());

        // Test case 4: No matching sequence flow
        variables.put("input", "unknown");
        try {
            processInstance = runtimeService.startProcessInstanceByKey("exclusiveGatewayProcess", variables);
            fail("Expected ProcessEngineException to be thrown");
        } catch (ProcessEngineException e) {
            // Expected exception
        }

        // Ensure no remaining tasks
        List<Task> remainingTasks = taskService.createTaskQuery().list();
        assertTrue(remainingTasks.isEmpty());
    }
}

public GeometryCollection extrudePolygon(Polygon polygon, double height) {
