import java.util.*;

public class Coloring {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read input
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        int[] l = new int[m];
        for (int i = 0; i < m; i++) {
            l[i] = scanner.nextInt();
        }

        // Check feasibility
        if (m > n) {
            System.out.println("-1");
            scanner.close();
            return;
        }

        // Determine p_i values
        long[] colorCounts = new long[n - m + 1];
        Arrays.fill(colorCounts, -1);
        for (int i = 0; i < m; i++) {
            long color = i + 1;
            for (int j = i; j < i + l[i]; j++) {
                colorCounts[j] = Math.max(colorCounts[j], color);
            }
        }

        StringBuilder result = new StringBuilder();
        for (long color : colorCounts) {
            if (color == -1) {
                System.out.println("-1");
                scanner.close();
                return;
            }
            result.append(color).append(" ");
        }

        System.out.println(result.toString().trim());
        scanner.close();
    }
}

