// Context class to abstract JSON parsing state.
class JsonUnmarshallerContext {
    private JsonParser jsonParser;
    private int currentDepth;

    public JsonUnmarshallerContext(JsonParser jsonParser) {
        this.jsonParser = jsonParser;
        this.currentDepth = 0;
    }

    public JsonToken getCurrentToken() throws IOException {
        return jsonParser.getCurrentToken();
    }

    public JsonToken nextToken() throws IOException {
        JsonToken token = jsonParser.nextToken();
        updateDepth(token);
        return token;
    }

    public int getCurrentDepth() {
        return currentDepth;
    }

    private void updateDepth(JsonToken token) {
        if (token == JsonToken.START_OBJECT || token == JsonToken.START_ARRAY) {
            currentDepth++;
        } else if (token == JsonToken.END_OBJECT || token == JsonToken.END_ARRAY) {
            currentDepth--;
        }
    }

    public boolean testExpression(String expression, int targetDepth) throws IOException {
        if (jsonParser.getCurrentToken() == JsonToken.FIELD_NAME
                && jsonParser.getCurrentName().equals(expression)
                && currentDepth == targetDepth) {
            return true;
        }
        return false;
    }
}

