public Class<?> translateStringToRealType(String type) throws TemplateException {
    try {
        if(type.equals("int")) {
            return int.class;
        } else if(type.equals("double")) {
            return double.class;
        } else if(type.equals("float")) {
            return float.class;
        } else if(type.equals("long")) {
            return long.class;
        } else if(type.equals("boolean")) {
            return boolean.class;
        } else if(type.equals("char")) {
            return char.class;
        } else if(type.equals("short")) {
            return short.class;
        } else if(type.equals("byte")) {
            return byte.class;
        } else {
            return Class.forName(type);
        }
    } catch(ClassNotFoundException ex) {
        throw new TemplateException("Invalid class name: " + type, ex);
    }
}

