public int minMoves(int[] nums, int limit) {
        int[] dynamicRange = new int[2 * limit + 2];

        int minMoves = Integer.MAX_VALUE;
        for (int i = 0; i < nums.length / 2; i++) {
            int left = nums[i];
            int right = nums[nums.length - 1 - i];

            int temp = Math.min(left, right);
            dynamicRange[temp] -= 2;
            dynamicRange[left + 1] += 1;
            dynamicRange[right + 1] += 1;
            dynamicRange[left + right + 1] -= 1;
            dynamicRange[left + right + 2] += 1;
            dynamicRange[2 * limit + 1] += 1;
        }

        int moves = nums.length;
        for (int i = 2; i <= 2 * limit; i++) {
            moves += dynamicRange[i];
            minMoves = Math.min(moves, minMoves);
        }

        return minMoves;
    }
}

import java.util.Scanner;

public class LeapYearChecker {
    public static boolean isLeapYear(int year) {
        // A year is leap if divisible by 4, except centuries
        // that are not divisible by 400
        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a year: ");
        int year = scanner.nextInt();

        if (isLeapYear(year)) {
            System.out.println(year + " is a leap year");
        } else {
            System.out.println(year + " is not a leap year");
        }
        scanner.close();
    }
}

import android.app.Activity;
import android.content.Context;
import android.net.ConnectivityManager;
import android.net.DhcpInfo;
import android.net.NetworkInfo;
import android.net.wifi.WifiManager;

public class PhoneStatus {

    private static Activity activity;

    public PhoneStatus(Activity activity) {
        this.activity = activity;
    }

    public String getWifiIpAddress() {
        if (isConnected()) {
            WifiManager wifiManager = (WifiManager) activity.getSystemService(Context.WIFI_SERVICE);
            DhcpInfo dhcpInfo = wifiManager.getDhcpInfo();
            int ipAddress = dhcpInfo.ipAddress;
            return intToIp(ipAddress);
        } else {
            return "Error: Not connected to WiFi";
        }
    }

    public boolean isConnected() {
        ConnectivityManager connectivityManager = (ConnectivityManager) activity.getSystemService(Context.CONNECTIVITY_SERVICE);
        NetworkInfo networkInfo = connectivityManager.getNetworkInfo(ConnectivityManager.TYPE_WIFI);
        return networkInfo != null && networkInfo.isConnected();
    }

    private String intToIp(int ip) {
        return ((ip >> 24) & 0xFF) + "." +
               ((ip >> 16) & 0xFF) + "." +
               ((ip >> 8) & 0xFF) + "." +
               (ip & 0xFF);
    }

    // Example usage
    public static void main(String[] args) {
        // This is just for demonstration purposes and won't work in a standalone Java environment
