import java.io.*;
import java.util.*;

public class PortalFinder {

    private static final int EMPTY_BLOCK = 0;
    private static final int OBSIDIAN_BLOCK = 1;

    private static class Block {
        int x, y;

        Block(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    private static class Portal {
        int a, b;

        Portal(int a, int b) {
            this.a = a;
            this.b = b;
        }
    }

    private static int findPortal(int[][] grid) {
        int n = grid.length;
        int m = grid[0].length;
        int count = 0;

        // Iterate through all possible portals
        for (int a = 5; a <= n; a++) {
            for (int b = 4; b <= m; b++) {
                int operations = 0;

                // Check portal conditions
                for (int x = 1; x < a; x++) {
                    if (grid[x-1][0] != OBSIDIAN_BLOCK || grid[x-1][b] != OBSIDIAN_BLOCK) {
                        operations += 1;
                        continue;
                    }

                    for (int y = 1; y < b; y++) {
                        if (grid[x-1][y] != EMPTY_BLOCK || grid[a-1][y] != EMPTY_BLOCK ||
                            grid[x][y-1] != EMPTY_BLOCK || grid[x][b-1] != EMPTY_BLOCK) {
                            operations += 1;
                            break;
                        }
                    }

                    if (operations > 0) {
                        break;
                    }
                }

                if (operations == 0) {
                    return a * b;
                }
            }
        }

        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());

        for (int i = 0; i < t; i++) {
            int n = Integer.parseInt(br.readLine());
            int m = Integer.parseInt(br.readLine());
            int[][] grid = new int[n][m];

            for (int j = 0; j < n; j++) {
                String line = br.readLine();
                for (int k = 0; k < line.length(); k++) {
                    grid[j][k] = line.charAt(k) - '0';
                }
            }

            System.out.println(findPortal(grid));
        }
    }
}
