class Main {
    public static final long MODULO = 1000000007;

    public int[] pathsWithMaxScore(List<String> board) {
        int length = board.size();
        int[][][] states = new int[2][length][2];

        states[(length - 1) % 2][length-1][0] = 1;
        states[(length - 1) % 2][length-1][1] = 1;
        int value1, value2, value3, max;
        long count = 0L;
        int curr, pre;
        char c;

        for (int i = length - 1; i >= 0; i--) {
            curr = i % 2;
            pre = (i+1) % 2;
            for (int j = length - 1; j >= 0; j--) {
                if (i == length - 1 && j == length - 1) {
                    continue;
                }

                c = board.get(i).charAt(j);
                if (c == 'X') {
                    states[curr][j][0] = 0;
                    states[curr][j][1] = 0;
                    continue;
                }

                value1 = states[pre][j][0];
                value2 = -1;
                value3 = -1;
                if (j < length - 1) {
                    value2 = states[pre][j+1][0];
                    value3 = states[curr][j+1][0];
                }
                max = Math.max(value1, Math.max(value2, value3));
                count = 0L;
                if (max > 0) {
                    if (max == value1) {
                        count += (long)(states[pre][j][1]);
                    }
                    if (max == value2) {
                        count += (long)(states[pre][j+1][1]);
                    }
                    if (max == value3) {
                        count += (long)(states[curr][j+1][1]);
                    }
                    states[curr][j][0] = max + (c == 'E'? 0: (c - '0'));
                    states[curr][j][1] = (int)(count % MODULO);
                } else {
                    states[curr][j][0] = 0;
                    states[curr][j][1] = 0;
                }
            }
        }

        return new int[]{states[0][0][0] > 0 ? states[0][0][0] - 1: 0, states[0][0][1]};
    }
}

