/**
 * Definition for a binary tree node.
 * public class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode() {}
 *     TreeNode(int val) { this.val = val; }
 *     TreeNode(int val, TreeNode left, TreeNode right) {
 *         this.val = val;
 *         this.left = left;
 *         this.right = right;
 *     }
 * }
 */
class Queue {
    public long kthLargestLevelSum(TreeNode root, int k) {
        Deque<TreeNode> dq = new ArrayDeque<>();
        dq.offer(root);
        PriorityQueue<Long> pq = new PriorityQueue<Long>((t0, t1) -> Long.compare(t1, t0));
        while (!dq.isEmpty()) {
            int size = dq.size();
            long v = 0L;
            for (int i = 0; i < size; ++i) {
                TreeNode node = dq.pollFirst();
                if (node.left != null) dq.offerLast(node.left);
                if (node.right != null) dq.offerLast(node.right);
                v += node.val;
            }
            pq.offer(v);
        }
        long v = -1;
        while (k-- != 0) {
            if (pq.isEmpty()) {
                return -1L;
            }
            v = pq.poll();
        }
        return v;

    }
}

public Location intersection(Location other) {
        if (isSameStrand(other)) {
            return intersect(mStart, mEnd, other.mStart, other.mEnd);
        } else {
            throw new IllegalArgumentException("Locations are on opposite strands.");
        }
    }

import java.util.HashMap;

import easy.data.*;
import easy.data.field.*;
import easy.data.sig.*;
import easy.data.util.*;

public class XMLDataSourceIterator implements DataSourceIterator {
    XMLDataSource xds;
    IDataField df;
    XML[] nodes;
    int curIndex;

    public XMLDataSourceIterator(XMLDataSource xds, final IDataField df, final XML xml) {
        this.xds = xds;
        this.curIndex = 0;
        df.apply(new IDFVisitor<Void>() {
            public Void defaultVisit(IDataField df) {
                XMLDataSourceIterator.this.df = df;
                XMLDataSourceIterator.this.nodes = new XML[] { xml };
                return null;
            }
            public Void visitListField(ListField f, String b, String d, String ep, IDataField ef) {
                XMLDataSourceIterator.this.df = ef;
                XMLDataSourceIterator.this.nodes = xml.getChildren(ep);
                return null;
            }
            public Void visitPrimField(PrimField f, String b, String d) { return defaultVisit(f); }
            public Void visitCompField(CompField f, String b, String d, HashMap<String, IDataField> fm) { return defaultVisit(f); }
        });
    }

    public boolean hasData() {
        return curIndex < nodes.length;
    }

    public DataSourceIterator loadNext() {
        if (hasData()) curIndex++;
        //if (!hasData()) throw new DataSourceException("Attempted to move past end of iterator");
        //curIndex++;
        return this;
    }

    @SuppressWarnings("unchecked")
    public <T> T fetch(String clsName, String... keys) {
        return (T) fetch(SigBuilder.classFor(clsName), keys);
    }

    public <T> T fetch(Class<T> cls, String... keys) {
        //if (curIndex < 0) throw new DataSourceException("Must call loadNext() before attempting to fetch from iterator");
        if (!hasData()) throw new DataSourceException("No more data available through iterator: " + xds.getName());
        ISig sig = SigBuilder.buildCompSig(cls, keys);
        return df.apply(new XMLInstantiator<T>(nodes[curIndex], sig));
    }

    public boolean fetchBoolean(String key) { return fetch(Boolean.class, key); }
    public byte fetchByte(String key) { return fetch(Byte.class, key); }
    public char fetchChar(String key) { return fetch(Character.class, key); }
    public double fetchDouble(String key) { return fetch(Double.class, key); }
    public float fetchFloat(String key) { return fetch(Float.class, key); }
    public int fetchInt(String key) { return fetch(Integer.class, key); }

public synchronized void resetAllUsageParameters(SbbID sbbId) throws NullPointerException, UnrecognizedSbbException, InvalidArgumentException, ManagementException {
    if (sbbId == null) {
        throw new NullPointerException("SbbID cannot be null");
    }

    // Assuming you have a list of SBBs in your Service
    for (Sbb sbb : service.getSbbs()) {
        if (sbb.getId().equals(sbbId)) {
            // Reset the usage parameters of the SBB
            sbb.resetUsageParameters();
            return;
        }
    }

    // If the SBB is not found
    throw new UnrecognizedSbbException("No SBB found with the given SbbID");
}

import java.util.Arrays;
import java.util.Scanner;

public class Converter {

    public static void main(String[] args) {
        double[][] pts = new double[6][2];

        Scanner in = new Scanner(System.in);
        System.out.print("Enter 6 points: ");
        for (int p = 0; p < 6; p++) {
            for (int n = 0; n < 2; n++) {
                pts[p][n] = in.nextDouble();
            }
        }
        System.out.print("The rightmost point is " + Arrays.toString(getRightmostLowestPoint(pts)));

    }

    public static double[] getRightmostLowestPoint(double[][] points) {
        double[] lowestRight = points[0];
        double[][] multiLowRights = new double[3][2];

        for (int i = 1; i < points.length; i++) {
            if (lowestRight[1] > points[i][1]) {
                lowestRight = points[i];
            } else if (lowestRight[1] == points[i][1]) {
                for (int z = 0; z < multiLowRights.length; z++) {
                    if (multiLowRights[z][0] == 0.0 && multiLowRights[z][1] == 0.0) {
                        multiLowRights[z] = points[i];
                        multiLowRights[z + 1] = lowestRight;
                        break;
                    }
                }
            }
        }
        if (multiLowRights[0][0] != 0.0 && multiLowRights[0][1] != 0.0 && multiLowRights[1][0] != 0.0 && multiLowRights[1][1] != 0.0) {
            for (int i = 0; i < multiLowRights.length - 1; i++) {
                if (i == 0) {
                    if (multiLowRights[i][0] > multiLowRights[i + 1][0]) {
                        lowestRight = multiLowRights[i];
                    } else {
                        lowestRight = multiLowRights[i + 1];
                    }
                } else {
                    if (multiLowRights[i][0] > lowestRight[0]) {
                        lowestRight = multiLowRights[i];
                    }
                }
            }
        }
        return lowestRight;

    }
}

class Game {
    public long maximumImportance(int n, int[][] roads) {
        long[] degree = new long[n];
        for (int[] r : roads) {
            degree[r[0]]++;
            degree[r[1]]++;
        }
        Arrays.sort(degree);
        long res = 0;
        for (int i = n - 1; i >= 0; i--) {
            res += degree[i] * (i + 1);
        }
        return res;
    }
}

