public class Person {

    private String name;
    private String address;
    private String phoneNumber;
    private String emailAddress;

    public Person() {}

    public Person(String name, String address, String phoneNumber, String emailAddress) {
        this.name = name;
        this.address = address;
        this.phoneNumber = phoneNumber;
        this.emailAddress = emailAddress;
    }

    public String getName() {
        return name;
    }

    public Person setName(String name) {
        this.name = name;
        return this;
    }

    public String getAddress() {
        return address;
    }

    public Person setAddress(String address) {
        this.address = address;
        return this;
    }

    public String getPhoneNumber() {
        return phoneNumber;
    }

    public Person setPhoneNumber(String phoneNumber) {
        this.phoneNumber = phoneNumber;
        return this;
    }

    public String getEmailAddress() {
        return emailAddress;
    }

    public Person setEmailAddress(String emailAddress) {
        this.emailAddress = emailAddress;
        return this;
    }

    @Override
    public String toString() {
        return "Person.class: { " +
                "Name= " + name +
                " }";
    }

}

import com.tle.beans.entity.LanguageBundle;
import java.util.Map;

public abstract class HarvesterProfileSettings {
  private LanguageBundle name;
  private Map<String, String> attributes;

  public HarvesterProfileSettings() {
    super();
  }

  public HarvesterProfileSettings(HarvesterProfile gateway) {
    this();
    load(gateway);
  }

  public void load(HarvesterProfile gateway1) {
    this.attributes = gateway1.getAttributes();
    this.name = gateway1.getName();
    _load();
  }

  public void save(HarvesterProfile gateway1) {
    gateway1.setType(getType());
    this.attributes = gateway1.getAttributes();
    gateway1.setName(name);
    _save();
    for (Map.Entry<String, String> entry : attributes.entrySet()) {
      gateway1.setAttribute(entry.getKey(), entry.getValue());
    }
  }

  public String get(String key, String defaultValue) {
    String value = attributes.get(key);
    if (value == null) {
      value = defaultValue;
    }
    return value;
  }

  public boolean get(String key, boolean defaultValue) {
    String value = attributes.get(key);
    boolean v;
    if (value == null) {
      v = defaultValue;
    } else {
      v = Boolean.valueOf(value);
    }
    return v;
  }

  public int get(String key, int defaultValue) {
    String value = attributes.get(key);
    int v;
    if (value != null) {
      try {
        v = Integer.parseInt(value);
      } catch (Exception e) {
        v = defaultValue;
      }
    } else {
      v = defaultValue;
    }
    return v;
  }

  public void put(String key, Object value) {
    attributes.put(key, value.toString());
  }

  public void put(String key, String value) {
    attributes.put(key, value);
  }

  protected abstract String getType();

  protected abstract void _load();

  protected abstract void _save();

  public LanguageBundle getName() {
    return name;
  }

  public void setName(LanguageBundle name) {
    this.name = name;
  }
}

public class ContinueOrnegi {

    // Sayilari tek ve cift olarak ayirt eden ornek
    public static void tekCiftAyristir() {
        System.out.println("Tek ve Cift Sayilar Ornegi:");
        int n = 1;
        while (n <= 10) {
            if (n % 2 == 0) { // cift sayi kontrolu
                System.out.println("Cift sayi: " + n);
                n++;
                continue; // cift oldugunda alttaki satir atlanir
            }
            System.out.println("Tek sayi: " + n);
            n++;
        }
    }

    // 3 veya 5 ile tam bolunen sayilari atlayan ornek
    public static void ucBesKatlariniAtla() {
        System.out.println("\n3 ve 5'in Katlarini Atlayan Ornek:");
        for (int n = 1; n <= 15; n++) {
            if (n % 3 == 0 || n % 5 == 0) { // 3 ya da 5'in kati mi kontrol edilir
                System.out.println("Atlanan sayi: " + n);
                continue; // katlar icin devam eden kod calismaz
            }
            System.out.println("Gecerli sayi: " + n);
        }
    }

    // Ic ice donguler icerisinde continue kullanan ornek
    public static void icIceContinueOrnek() {
        System.out.println("\nIc Ice Dongulerde Continue Ornegi:");
        int satir = 1;
        while (satir <= 3) {
            for (int sutun = 1; sutun <= 3; sutun++) {
                if (satir == sutun) { // indeksler esitse atla
                    System.out.println("i: " + satir + ", j: " + sutun + " -> Continue uygulandi");
                    continue; // esitlik durumunda geri kalan kod calismaz
                }
                System.out.println("i: " + satir + ", j: " + sutun);
            }
            satir++;
        }
    }

    public static void main(String[] args) {
        // Ornekleri sirayla calistir
        tekCiftAyristir();
        ucBesKatlariniAtla();
        icIceContinueOrnek();
    }
}

public class SmarandachePrimeDigitalSequence {
 
    public static void main(String[] args) {
        long s = getNextSmarandache(7);
        System.out.printf("First 25 Smarandache prime-digital sequence numbers:%n2 3 5 7 ");
        for ( int count = 1 ; count <= 21 ; s = getNextSmarandache(s) ) {
            if ( isPrime(s) ) {
                System.out.printf("%d ", s);
                count++;
            }
        }
        System.out.printf("%n%n");
        for (int i = 2 ; i <=5 ; i++ ) {
            long n = (long) Math.pow(10, i);
            System.out.printf("%,dth Smarandache prime-digital sequence number = %d%n", n, getSmarandachePrime(n));
        }
    }
 
    private static final long getSmarandachePrime(long n) {
        if ( n < 10 ) {
            switch ((int) n) {
            case 1:  return 2;
            case 2:  return 3;
            case 3:  return 5;
            case 4:  return 7;
            }
        }
        long s = getNextSmarandache(7);
        long result = 0;
        for ( int count = 1 ; count <= n-4 ; s = getNextSmarandache(s) ) {
            if ( isPrime(s) ) {
                count++;
                result = s;
            }
        }
        return result;
    }
 
    private static final boolean isPrime(long test) {
        if ( test % 2 == 0 ) return false;
        for ( long i = 3 ; i <= Math.sqrt(test) ; i += 2 ) {
            if ( test % i == 0 ) {
                return false;
            }
        }
        return true;
    }
 
    private static long getNextSmarandache(long n) {
        //  If 3, next is 7
        if ( n % 10 == 3 ) {
            return n+4;
        }
        long retVal = n-4;
 
        //  Last digit 7.  k = largest position from right where we have a 7.
        int k = 0;
        while ( n % 10 == 7 ) {
            k++;
            n /= 10;
        }
 
        //  Determine first digit from right where digit != 7.
        long digit = n % 10;
 
        //  Digit is 2, 3, or 5.  3-2 = 1, 5-3 = 2, 7-5 = 2, so digit = 2, coefficient = 1, otherwise 2.
        long coeff = (digit == 2 ? 1 : 2);
 
        //  Compute next value
        retVal += coeff * Math.pow(10, k);
 
        //  Subtract values for digit = 7.
        while ( k > 1 ) {
            retVal -= 5 * Math.pow(10, k-1);
            k--;
        }
 
        //  Even works for 777..777 --> 2222...223
        return retVal;
    }
 
}

import java.io.IOException;
import java.io.ObjectOutputStream;
import java.io.OutputStream;

import org.itas.xcnet.common.serialize.ObjectOutput;

/**
 * Java Object output.
 *
 * @createTime 2015年5月15日下午3:10:18
 */
public class JavaObjectOutput implements ObjectOutput {

    private final ObjectOutputStream out;

    public JavaObjectOutput(OutputStream os) throws IOException {
        out = new ObjectOutputStream(os);
    }

    public JavaObjectOutput(OutputStream os, boolean compact) throws IOException {
        out = compact ? new CompactedObjectOutputStream(os) : new ObjectOutputStream(os);
    }

    @Override
    public void writeBool(boolean v) throws IOException {
        out.writeBoolean(v);
    }

    @Override
    public void writeByte(byte v) throws IOException {
        out.writeByte(v);
    }

    @Override
    public void writeShort(short v) throws IOException {
        out.writeShort(v);
    }

    @Override
    public void writeInt(int v) throws IOException {
        out.writeInt(v);
    }

    @Override
    public void writeLong(long v) throws IOException {
        out.writeLong(v);
    }

    @Override
    public void writeFloat(float v) throws IOException {
        out.writeFloat(v);
    }

    @Override
    public void writeDouble(double v) throws IOException {
        out.writeDouble(v);
    }

    @Override
    public void writeBytes(byte[] v) throws IOException {
        if (v == null)
            out.writeInt(-1);
        else
            out.write(v);
    }

    @Override
    public void writeBytes(byte[] v, int off, int len) throws IOException {
        out.writeInt(len);
        out.write(v, off, len);
    }

    @Override
    public void writeUTF8(String v) throws IOException {
        if (v == null) {
            out.writeInt(-1);
        } else {
            out.writeInt(v.length());
            out.writeUTF(v);
        }
    }

    @Override
    public void writeObject(Object o) throws IOException {
        if (o == null) {
            out.writeInt(-1);
        } else {
            out.writeInt(1);
            out.writeObject(o);
        }
    }

    @Override
    public void flushBuffer() throws IOException {
        out.flush();
    }

}

