import java.lang.annotation.Documented;
import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

/**
 * Configures the core pool size of reusable instances for asynchronous method invocations.
 * <p>
 * This annotation declaratively specifies the number of core instances maintained in a pool
 * dedicated to processing annotated asynchronous methods. When applied to a method, the JRT
 * framework creates a fixed-size thread pool to handle invocations, ensuring controlled
 * concurrency and automatic resource reuse without manual synchronization.
 * </p>
 *
 * <p>
 * The annotation is processed at runtime to generate thread-safe execution contexts.
 * Annotated methods must have non-private visibility to allow framework interception.
 * </p>
 *
 * <h3>Proguard Retention:</h3>
 * <pre>
 * -keep @interface com.jrt.annotations.CoreInstances
 * -keepclassmembers class * {
 *     @com.jrt.annotations.CoreInstances *;
 * }
 * </pre>
 *
 * @see RetentionPolicy#RUNTIME
 */
@Documented
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
public @interface CoreInstances {

    /**
     * Specifies the core number of reusable instances in the execution pool.
     * <p>
     * Determines the fixed concurrency level for asynchronous method processing.
     * Must be a positive integer. Defaults to 5 if unspecified.
     * </p>
     *
     * @return Positive integer representing pool size (default=5)
     */
    int value() default 5;

    /**
     * Optional flag to enable dynamic pool resizing based on workload.
     * <p>
     * When true, the framework may temporarily exceed the core pool size
     * during high load, up to the maximum specified by {@link #maxInstances()}.
     * Requires JRT framework version 2.1+.
     * </p>
     */
    boolean elastic() default false;

    /**
     * Maximum allowed instances when elastic mode is enabled.
     * <p>
     * Ignored if {@link #elastic()} is false. Must be greater than or equal
     * to the core pool size specified by {@link #value()}.
     * </p>
     */
    int maxInstances() default Integer.MAX_VALUE;

    /**
     * Timeout in milliseconds before terminating idle excess instances
     * in elastic mode.
     * <p>
     * Applies only to instances created beyond the core pool size when
     * {@link #elastic()} is active.
     * </p>
     */
    long idleTimeout() default 60000;
}

#include<iostream>
#include<vector>
using namespace std;
inline int manhattan(int a, int b, int index){
    return abs(index+a-b) + abs(index-a)+abs(index-b);
}
int main(){
    int t = 0, n = 0;
    cin >> t;
    while(t--){
        cin >> n;
        vector<int> a(n);
        for(auto val : a){
            cin >> val;
        }
        int good_subarrays = 0;
        for(int i=0; i<n; i++){
            for(int j=i; j<n; j++){
                if(manhattan(a[i],a[j],i) <=\
                    manhattan(a[i],a[j],j) + manhattan(a[j],a[n-1],j)){
                    break;
                }
                if(j==n-1){
                    good_subarrays += (n-j-1)*(n-j);
                }
                else{
                    good_subarrays += (n-j-1);
                }
            }
        }
        cout << good_subarrays/2 << endl;
    }
    return 0;
}

protected void addBuffer() {
        if (buffers == null) {
            buffers = new LinkedList<byte[]>();
        }
        buffers.addLast(buffer);
        buffer = new byte[blockSize];
        size += index;
        index = 0;
    }

static byte[] asByteArray(final InputStream in) throws IllegalArgumentException {

        if (in == null) {
            throw new IllegalArgumentException("stream must be specified");
        }

        final ByteArrayOutputStream out = new ByteArrayOutputStream(8192);
        final int len = 4096;
        final byte[] buffer = new byte[len];
        int read = 0;
        try {
            while (((read = in.read(buffer)) != -1)) {
                out.write(buffer, 0, read);
            }
        } catch (final IOException ioe) {
            throw new RuntimeException("Error in obtainting bytes from " + in, ioe);
        } finally {
            try {
                in.close();
            } catch (final IOException ignore) {
                if (log.isLoggable(Level.FINER)) {
                    log.finer("Could not close stream due to: " + ignore.getMessage() + "; ignoring");
                }
            }

        }

        final byte[] content = out.toByteArray();

        return content;
    }

import java.io.File;
import java.io.FileNotFoundException;
import java.io.PrintWriter;
import java.util.Scanner;
 
public class PeanoCurve {
    public static void main(String[] args) {
        try {
            PrintWriter out = new PrintWriter(new File("peano_curve.svg"));
            peano_curve pc = new peano_curve();
            pc.write(out, 656, 8, 4);
            out.close();
        } catch (FileNotFoundException e) {
            System.err.println("Cannot open output file");
            System.exit(1);
        }
    }
}
 
class peano_curve {
    public void write(PrintWriter out, int size, int length, int order) {
        length_ = length;
        x_ = length;
        y_ = length;
        angle_ = 90;
        out.println("<svg xmlns='http://www.w3.org/2000/svg' width='"
                + size + "' height='" + size + "'>");
        out.println("<rect width='100%' height='100%' fill='white'/>");
        out.print("<path stroke-width='1' stroke='black' fill='none' d='");
        String s = "L";
        for (int i = 0; i < order; ++i)
            s = rewrite(s);
        execute(out, s);
        out.println("'/>");
        out.println("</svg>");
    }
 
    private String rewrite(String s) {
        String t = "";
        for (char c : s.toCharArray()) {
            switch (c) {
            case 'L':
                t += "LFRFL-F-RFLFR+F+LFRFL";
                break;
            case 'R':
                t += "RFLFR+F+LFRFL-F-RFLFR";
                break;
            default:
                t += c;
                break;
            }
        }
        return t;
    }
 
    private void line(PrintWriter out) {
        double theta = (3.14159265359 * angle_)/180.0;
        x_ += length_ * Math.cos(theta);
        y_ += length_ * Math.sin(theta);
        out.print(" L" + x_ + ',' + y_);
    }
 
    private void execute(PrintWriter out, String s) {
        out.print('M' + x_ + ',' + y_);
        for (char c : s.toCharArray()) {
            switch (c) {
            case 'F':
                line(out);
                break;
            case '+':
                angle_ = (angle_ + 90) % 360;
                break;
            case '-':
                angle_ = (angle_ - 90) % 360;
                break;
            }
        }
    }
 
    private double x_;
    private double y_;
    private int angle_;
    private int length_;
}

class Finder {
    public int largestMagicSquare(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int maxK = 1;
        int[][] rowSum = new int[m + 1][n + 1];
        int[][] columnSum = new int[m + 1][n + 1];
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid[i].length; j++) {
                rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
                columnSum[i + 1][j] = columnSum[i][j] + grid[i][j];
            }
        }

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int maxPossibleK = Math.min(m - i, n - j);
                if (maxPossibleK <= maxK) {
                    continue;
                }
                for (int k = maxPossibleK; k > maxK; k--) {
                    int firstRowSum = rowSum[i][j + k] - rowSum[i][j];
                    boolean match = true;
                    for (int l = 1; l < k && match; l++) {
                        int currentRowSum = rowSum[i + l][j + k] - rowSum[i + l][j];
                        match = firstRowSum == currentRowSum;
                    }
                    for (int l = 0; l < k && match; l++) {
                        int currentRowSum = columnSum[i + k][j + l] - columnSum[i][j + l];
                        match = firstRowSum == currentRowSum;
                    }
                    if (match && checkDiagonal(grid, i, j, k, firstRowSum)) {
                        maxK = k;
                        break;
                    }
                }

            }
        }

        return maxK;
    }

    public boolean checkDiagonal(int[][] grid, int x, int y, int k, int requestedSum) {
        int sum1 = 0, sum2 = 0;
        for (int i = 0; i < k; i++) {
            sum1 += grid[x + i][y + i];
            sum2 += grid[x + i][y + k - 1 - i];
        }
        return sum1 == requestedSum && sum2 == requestedSum;
    }
}

class Validator {
    private static final int MOD = (int) 1e9 + 7;

    public int rearrangeSticks(int n, int k) {
        long[] dp = new long[k + 1];
        dp[0] = 1;
        for (int i = 1; i <= n; i++) {
            long[] next = new long[k + 1];
            for (int j = 1; j <= Math.min(i, k); j++) {
                next[j] = (next[j - 1] * i + dp[j]) % MOD;
            }
            dp = next;
        }
        return (int) dp[k];
    }
}

public class MinimumElamaninIndisi {

