    public static int minimumIndis(int[] kaynakDizi) {
        if (kaynakDizi == null || kaynakDizi.length == 0) {
            return -1;
        }

        int enKucukIndeks = 0;
        int i = 1;
        while (i < kaynakDizi.length) {
            System.out.println(kaynakDizi[i] + " ile " + kaynakDizi[enKucukIndeks] + " karsilastir.");
            if (kaynakDizi[i] < kaynakDizi[enKucukIndeks]) {
                enKucukIndeks = i;
            }
            i++;
        }
        return enKucukIndeks;
