            System.out.println("Dizideki minimum elemanin indisi: " + sonucIndeks);
        } else {
            System.out.println("Dizi bos veya null.");
        }
    }
}

 
import java.awt.*;
import java.awt.geom.Path2D;
import java.util.Random;
import javax.swing.*;
 
class SierpinskiPentagon extends JPanel {
    // exterior angle
    private final double degrees072 = Math.toRadians(72.0);
 
    /* After scaling we'll have 2 sides plus a gap occupying the length
       of a side before scaling. The gap is the base of an isosceles triangle
       with a base angle of 72 degrees. */
    private final double scaleFactor = 1.0 / (2.0 + Math.cos(degrees072) * 2.0);
 
    private final int margin = 20;
    private int limit = 0;
    private final Random r = new Random();
 
    public SierpinskiPentagon() {
        setPreferredSize(new Dimension(640, 640));
        setBackground(Color.white);
        new Timer(3000, e -> {
            limit++;
            if (limit >= 5) limit = 0;
            repaint();
        }).start();
    }
 
    private void drawPentagon(Graphics2D g, double x, double y, double s, int depth) {
        double angle = 3.0 * degrees072;  // starting angle
        double xx = x;
        double yy = y;
        double side = s;
        if (depth == 0) {
            Path2D p = new Path2D.Double();
            p.moveTo(xx, yy);
 
            // draw from the top
            for (int i = 0; i < 5; i++) {
                xx += Math.cos(angle) * side;
                yy -= Math.sin(angle) * side;
                p.lineTo(xx, yy);
                angle += degrees072;
            }
 
            g.setColor(RandomHue.next());
            g.fill(p);
        }
        else {
            side *= scaleFactor;
            /* Starting at the top of the highest pentagon, calculate
               the top vertices of the other pentagons by taking the
               length of the scaled side plus the length of the gap. */
            double distance = side + side * Math.cos(degrees072) * 2.0;
 
            /* The top positions form a virtual pentagon of their own,
               so simply move from one to the other by changing direction. */
            for (int i = 0; i < 5; i++) {
                xx += Math.cos(angle) * distance;
                yy -= Math.sin(angle) * distance;
                drawPentagon(g, xx, yy, side, depth - 1);
                angle += degrees072;
            }
        }
    }
 
    @Override
    public void paintComponent(Graphics gg) {
        super.paintComponent(gg);
        Graphics2D g = (Graphics2D) gg;
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int hw = getWidth() / 2;
        double radius = hw - 2.0 * margin;

import java.util.ArrayList;
import java.util.Scanner;

public class Manager {
    public static void main(String[] args) {
        ArrayList<Integer> list = new ArrayList<>();
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a sequence of numbers (end with 0): ");
        int number;
        do {
            number = scanner.nextInt();
            if (number != 0) {
                list.add(number);
            }
        } while (number != 0);

        Integer max = max(list);
        if (max != null) {
            System.out.println("The largest number is " + max);
        } else {
            System.out.println("The list is empty.");
        }
    }

    public static Integer max(ArrayList<Integer> list) {
        if (list == null || list.size() == 0) {
            return null;
        }

        int max = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            int number = list.get(i);
            if (number > max) {
                max = number;
            }
        }

        return max;
    }
}

import java.util.List;
import java.util.Random;
import java.util.stream.Stream;
 
import static java.util.stream.Collectors.toList;
 
public class Rpg {
 
    private static final Random random = new Random();
 
    public static int genAttribute() {
        return random.ints(1, 6 + 1) // Throw dices between 1 and 6
            .limit(4) // Do 5 throws
            .sorted() // Sort them
            .limit(3) // Take the top 3
            .sum();   // Sum them
    }
 
    public static void main(String[] args) {
        while (true) {
            List<Integer> stats =
                Stream.generate(Rpg::genAttribute) // Generate some stats
                    .limit(6) // Take 6
                    .collect(toList()); // Save them in an array
            int sum = stats.stream().mapToInt(Integer::intValue).sum();
            long count = stats.stream().filter(v -> v >= 15).count();
            if (count >= 2 && sum >= 75) {
                System.out.printf("The 6 random numbers generated are: %s\n", stats);
                System.out.printf("Their sum is %s and %s of them are >= 15\n", sum, count);
                return;
            }
        }
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class FairSharing {
    private static class Digits {
        private final int rest;
        private final int base;
 
        public Digits(int rest, int base) {
            this.rest = rest;
            this.base = base;
        }
 
        public int next() {
            if (rest == 0) {
                return -1;
            }
            int digit = rest % base;
            rest = rest / base;
            return digit;
        }
    }
 
    private static class FairSharing {
        private final int participants;
        private int index;
 
        public FairSharing(int participants) {
            this.participants = participants;
            this.index = 0;
        }
 
        public int next() {
            int digitSum = IntStream.iterate(index, i -> i!= 0, i -> i / participants)
                   .map(i -> i % participants)
                   .sum();
            int selected = digitSum % participants;
            index++;
            return selected;
        }
    }
 
    public static void main(String[] args) {
        List<Integer> fairSharing = new ArrayList<>();
        for (int i = 0; i < 25; i++) {
            fairSharing.add(new FairSharing(2).next());
        }
        System.out.println("2: " + fairSharing.stream().map(Object::toString).collect(Collectors.joining(", ")));
 
        fairSharing.clear();
        for (int i = 0; i < 25; i++) {
            fairSharing.add(new FairSharing(3).next());
        }
        System.out.println("3: " + fairSharing.stream().map(Object::toString).collect(Collectors.joining(", ")));
 
        fairSharing.clear();
        for (int i = 0; i < 25; i++) {
            fairSharing.add(new FairSharing(5).next());
        }
        System.out.println("5: " + fairSharing.stream().map(Object::toString).collect(Collectors.joining(", ")));
 
        fairSharing.clear();
        for (int i = 0; i < 25; i++) {
            fairSharing.add(new FairSharing(7).next());
        }
        System.out.println("7: " + fairSharing.stream().map(Object::toString).collect(Collectors.joining(", ")));
    }
}

class Main {

    public char slowestKey(int[] releaseTimes, String keysPressed) {
        int n=releaseTimes.length,prev=0,max=-1;
        char maxC='a';
        for (int i = 0; i < n; i++) {
            int dur=releaseTimes[i]-prev;
            if(dur==max){
                maxC=maxC<keysPressed.charAt(i)?keysPressed.charAt(i):maxC;
            }else if(dur>max){
                max=dur;
                maxC=keysPressed.charAt(i);
            }
            prev=releaseTimes[i];
        }
        return maxC;
    }

}

