class ListNode {
    int val;
    ListNode next;
    ListNode(int x) { val = x; }
}

public class Product {
    public int[] nodesBetweenCriticalPoints(ListNode head) {
        ListNode prev = head;
        head = head.next;
        int idx = 2, min = Integer.MAX_VALUE, max = Integer.MIN_VALUE, prevIdx = -1;
        int[] res = new int[] {-1, -1};

        while (head.next!= null) {
            if ((prev.val < head.val && head.val > head.next.val) ||
                (prev.val > head.val && head.val < head.next.val)) {
                if (prevIdx!= -1) {
                    min = Math.min(min, idx - prevIdx);
                    max = Math.max(max, idx - prevIdx);
                }
                prevIdx = idx;
            }
            prev = head;
            head = head.next;
            idx++;
        }

        return prevIdx == -1? res : new int[] {min, max};
    }
}

