public int maxNumOfMarkedIndices(int[] nums) {
    // Sort the array in non-decreasing order.
    Arrays.sort(nums);

    // Get indices `i` and `j` from opposite ends.
    // Initialize `target` as the smallest number possible.
    int i = 0, n = nums.length, res = 0;
    int target = Integer.MIN_VALUE;

    // Iterate until `j` reaches the middle of the array.
    for (int j = n - 1; j >= n / 2; j--) {
      // Once `nums[j]` satisfies the condition, mark both indices `i` and `j`.
      // Check `nums[j]` against `target` too, to avoid unnecessary searching.
      while (i < n / 2 && (nums[j] < target || nums[j] < 2 * nums[i]))
        target = nums[i++];

      // If marked, increment the result, and search from the next index `i`.
      if (i < n / 2 && nums[j] >= 2 * nums[i]) {
        res += 2;
        i++;
      }
    }

    // Return the maximum number of marked indices.
    return res;
  }
