class Runner {
    public int[] numberOfLines(int[] widths, String S) {
        char[] arr = S.toCharArray();

        int line = 1;
        int len = 0;
        for(char c : arr){
            int w = widths[c-'a'];
            if(len + w <= 100){
                len += w;
            }else{
                line++;
                len = w;
            }
        }
        int[] res = {line, len};
        return res;
    }
}

import net.sourceforge.plantuml.LineLocation;
