import net.sourceforge.plantuml.command.regex.IRegex;
import net.sourceforge.plantuml.command.regex.RegexConcat;
import net.sourceforge.plantuml.command.regex.RegexLeaf;
import net.sourceforge.plantuml.command.regex.RegexResult;
import net.sourceforge.plantuml.cucadiagram.IEntity;
import net.sourceforge.plantuml.objectdiagram.AbstractClassOrObjectDiagram;
import net.sourceforge.plantuml.skin.VisibilityModifier;
import net.sourceforge.plantuml.ugraphic.color.NoSuchColorException;

public class CommandAddData extends SingleLineCommand2<AbstractClassOrObjectDiagram> {

    public CommandAddData() {
        super(getRegexConcat());
    }

    static IRegex getRegexConcat() {
        return RegexConcat.build(CommandAddData.class.getName(), RegexLeaf.start(), //
                new RegexLeaf("NAME", "([%pLN_.]+)"), //
                RegexLeaf.spaceZeroOrMore(), //
                new RegexLeaf(":"), //
                RegexLeaf.spaceZeroOrMore(), //
                new RegexLeaf("DATA", "(.*)"), RegexLeaf.end()); //
    }

    @Override
    protected CommandExecutionResult executeArg(AbstractClassOrObjectDiagram diagram, LineLocation location,
            RegexResult arg) throws NoSuchColorException {
        final String name = arg.get("NAME", 0);
        final IEntity entity = diagram.getOrCreateLeaf(diagram.buildLeafIdent(name),
                diagram.buildCode(name), null, null);

        final String field = arg.get("DATA", 0);
        if (field.length() > 0 && VisibilityModifier.isVisibilityCharacter(field)) {
            diagram.setVisibilityModifierPresent(true);
        }
        entity.getBodier().addFieldOrMethod(field);
        return CommandExecutionResult.ok();
    }
}

class Builder {
    public int shortestPath(int[][] grid, int k) {
        int M=50;
        int N=2000;
        int m=grid.length;
        int n=grid[0].length;
        boolean[][][] vis=new boolean[M][M][M*M];
        Queue<Integer> q=new LinkedList<>();
        q.add((0*M+0)*N+0);
        vis[0][0][0]=true;
        int[][] dir={{1,0},{-1,0},{0,1},{0,-1}};
        int step=0;
        while(!q.isEmpty()){
            int sz=q.size();
            for(int s=0;s<sz;s++){
                int u=q.poll();
                int x=(u/N)/M;
                int y=(u/N)%M;
                int tk=u%N;
                if(x==m-1&&y==n-1) return step;
                for(int i=0;i<4;i++){
                    int nx=x+dir[i][0];
                    int ny=y+dir[i][1];
                    if(nx>=0&&nx<m&&ny>=0&&ny<n){
                        if(grid[nx][ny]==1){
                            if(tk+1>k||vis[nx][ny][tk+1]) continue;
                            vis[nx][ny][tk+1]=true;
                            q.add((nx*M+ny)*N+tk+1);
                        }
                        else if(vis[nx][ny][tk]) continue;
                            else {
                                vis[nx][ny][tk]=true;
                                q.add((nx*M+ny)*N+tk);
                            }

                    }
                }
            }
            step++;
        }
        return -1;
    }
}

