def resolve_board(grid):
    n = len(grid)
    moves = {'R': (0, 1), 'L': (0, -1), 'U': (-1, 0), 'D': (1, 0)}
    limit = (n+1)**2+1
    cells = {(r, c): [] for r in range(n) for c in range(n)}
    for r in range(n):
        for c in range(n):
            if grid[r][2*c] != 'X':
                cells[(r, c)].append(moves[grid[r][2*c-1]])
    for (r, c) in cells:
        current = (r, c)
        path = [grid[r][2*c-1]]
        done = {current}
        while True:
            (m_r, m_c) = cells[current][0]
            if (m_r, m_c) not in done:
                done.add((m_r, m_c))
                current = (current[0]+m_r, current[1]+m_c)
                path.append(grid[m_r][2*c-1])
            else:
                break
        if len(path) >= limit:
            return ('INVALID', '')
        else:
            string = ''.join(path)
            for cell in cells[current]:
                if len(string) < limit:
                    string += grid[cell[0]][2*c-1]
            return ('VALID', string)

public class PermutationGenerator {
    private int[] array;
    private int firstNum;
    private boolean firstReady = false;
 
    public PermutationGenerator(int n, int firstNum_) {
        if (n < 1) {
            throw new IllegalArgumentException("The n must be min. 1");
        }
        firstNum = firstNum_;
        array = new int[n];
        reset();
    }
 
    public void reset() {
        for (int i = 0; i < array.length; i++) {
            array[i] = i + firstNum;
        }
        firstReady = false;
    }
 
    public boolean hasMore() {
        boolean end = firstReady;
        for (int i = 1; i < array.length; i++) {
            end = end && array[i] < array[i-1];
        }
        return !end;
    }
 
    public int[] getNext() {
 
        if (!firstReady) {
            firstReady = true;
            return array;
        }
 
        int temp;
        int j = array.length - 2;
        int k = array.length - 1;
 
        // Find largest index j with a[j] < a[j+1]
 
        for (;array[j] > array[j+1]; j--);
 
        // Find index k such that a[k] is smallest integer
        // greater than a[j] to the right of a[j]
 
        for (;array[j] > array[k]; k--);
 
        // Interchange a[j] and a[k]
 
        temp = array[k];
        array[k] = array[j];
        array[j] = temp;
 
        // Put tail end of permutation after jth position in increasing order
 
        int r = array.length - 1;
        int s = j + 1;
 
        while (r > s) {
            temp = array[s];
            array[s++] = array[r];
            array[r--] = temp;
        }
 
        return array;
    } // getNext()
 
    // For testing of the PermutationGenerator class
    public static void main(String[] args) {
        PermutationGenerator pg = new PermutationGenerator(3, 1);
 
        while (pg.hasMore()) {
            int[] temp =  pg.getNext();
            for (int i = 0; i < temp.length; i++) {
                System.out.print(temp[i] + " ");
            }
            System.out.println();
        }
    }
 
} // class

