public static byte[] modifyConstructors(byte[] bytes, Class<?> clazz, String methodName) throws Exception {
    ClassReader cr = new ClassReader(bytes);
    ClassWriter cw = new ClassWriter(cr, ClassWriter.COMPUTE_MAXS | ClassWriter.COMPUTE_FRAMES);
    ClassVisitor cv = new ClassVisitor(Opcodes.ASM5, cw) {
        @Override
        public MethodVisitor visitMethod(int access, String name, String descriptor, String signature, String[] exceptions) {
            MethodVisitor mv = super.visitMethod(access, name, descriptor, signature, exceptions);
            // check if it is constructor
            if (name.equals("<init>")) {
                mv = new MethodVisitor(Opcodes.ASM5, mv) {
                    @Override
                    public void visitCode() {
                        // invoke the specified class/method
                        mv.visitLdcInsn(Type.getType("L" + clazz.getName().replace(".", "/") + ";"));
                        mv.visitMethodInsn(Opcodes.INVOKESTATIC, "java/lang/Class", "forName",
                                "(Ljava/lang/String;)Ljava/lang/Class;", false);
                        mv.visitLdcInsn(methodName);
                        mv.visitInsn(Opcodes.ACONST_NULL);
                        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/Class", "getMethod",
                                "(Ljava/lang/String;[Ljava/lang/Class;)Ljava/lang/reflect/Method;", false);
                        mv.visitInsn(Opcodes.ACONST_NULL);
                        mv.visitTypeInsn(Opcodes.NEW, cr.getClassName());
                        mv.visitInsn(Opcodes.DUP);
                        int count = Type.getArgumentTypes(descriptor).length;
                        for (int i = 0; i < count; i++) {
                            mv.visitVarInsn(Type.getType(descriptor).getOpcode(Opcodes.ILOAD), i);
                        }
                        mv.visitMethodInsn(Opcodes.INVOKESPECIAL, cr.getClassName(), "<init>", descriptor, false);
                        mv.visitMethodInsn(Opcodes.INVOKEVIRTUAL, "java/lang/reflect/Method", "invoke",
                                "(Ljava/lang/Object;[Ljava/lang/Object;)Ljava/lang/Object;", false);
                        mv.visitInsn(Opcodes.POP);
                        super.visitCode();
                    }
                };
            }
            return mv;
        }
    };
    cr.accept(cv, Opcodes.ASM5);
    return cw.toByteArray();
}

public void initialize(MethodNode method) {
    Type[] argumentTypes = Type.getArgumentTypes(method.desc);
    List<LocalVariableNode> methodLocalVariables = method.localVariables;

    for (int i = 0; i < argumentTypes.length; i++) {
        Type argumentType = argumentTypes[i];
        String argumentName = "arg" + i;

        int argumentIndex = -1;
        for (int j = 0; j < methodLocalVariables.size(); j++) {
            LocalVariableNode localVariable = methodLocalVariables.get(j);
            if (localVariable.index == i + (method.access == Opcodes.ACC_STATIC ? 0 : 1)
                && localVariable.name.equals(argumentName)
                && localVariable.desc.equals(argumentType.getDescriptor())) {
                argumentIndex = j;
                break;
            }
        }

        if (argumentIndex == -1) {
            methodLocalVariables.add(new LocalVariableNode(argumentName, argumentType.getDescriptor(),
                null, new LabelNode(), new LabelNode(), i + (method.access == Opcodes.ACC_STATIC ? 0 : 1)));
            argumentIndex = methodLocalVariables.size() - 1;
        }

        if (!(method.instructions.get(0) instanceof VarInsnNode
            && ((VarInsnNode) method.instructions.get(0)).var == argumentIndex)) {
            method.instructions.insertBefore(method.instructions.get(0),
                new VarInsnNode(argumentType.getOpcode(Opcodes.ISTORE), argumentIndex));

            // increment the maximum stack size by the size of the argument type
            method.maxStack += argumentType.getSize();
        }
    }
}

