class Helper {
    public int minMaxDifference(int num) {
        ArrayList<Integer> arr = new ArrayList<>();

        int n = num;

        while(n > 0)
        {
            arr.add(n % 10);
            n = n / 10;
        }

        Collections.reverse(arr);

        int max = 0;
        int digit = -1;

        for(int val : arr)
        {
            if(val == 9)
            {
                max = max * 10;
                max += val;
            }
            else{
                if(digit == -1)
                {
                    digit = val;
                    max = max * 10;
                    max += 9;
                }
                else if(val == digit){
                    max = max * 10;
                    max += 9;
                }
                else{
                    max = max * 10;
                    max += val;
                }
            }
        }

        int min = 0;
        digit = -1;

        for(int val : arr)
        {
            if(val == 0)
            {
                min = min * 10;
                min += val;
            }
            else{
                if(digit == -1)
                {
                    digit = val;
                    min = min * 10;
                    min += 0;
                }
                else if(val == digit){
                    min = min * 10;
                    min += 0;
                }
                else{
                    min = min * 10;
                    min += val;
                }
            }
        }

        return max - min;

    }
}

