import java.util.*;

class Converter {
    final static long M = 1_000_000_007;

    long mod(long x) {
        return ((x % M) + M) % M;
    }

    public int countSubMultisets(List<Integer> nums, int l, int r) {
        Map<Integer, Integer> count = new HashMap<>();
        for (int num : nums) {
            count.put(num, count.getOrDefault(num, 0) + 1);
        }
        int[] keys = count.keySet().stream().mapToInt(x -> x).sorted().toArray();
        long[] dp = new long[20001];
        long[] cum = new long[20001];
        dp[0] = 1;
        for (int num : keys) {
            int c = count.get(num);
            if (num == 0) {
                for (int i = 0; i < dp.length; i++) {
                    dp[i] = mod(dp[i] * (c + 1));
                }
                continue;
            }
            for (int i = 0; i < dp.length; i++) {
                cum[i] = mod(dp[i] + (i >= num ? cum[i - num] : 0));
                long dif = mod(cum[i] - (i >= num * (c + 1) ? cum[i - num * (c + 1)] : 0));
                dp[i] = mod(dif);
            }
        }
        long ans = 0;
        for (int i = l; i <= r; i++) {
            ans = mod(ans + dp[i]);
        }
        return (int) ans;
    }
}

import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.CreateMode;
import org.apache.zookeeper.data.ACL;
import org.apache.zookeeper.data.Stat;
import org.apache.zookeeper.KeeperException;
import org.apache.zookeeper.ZooDefs.Ids;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;

public class CreateOperation extends ZooKeeperOperation<String> {

    private static final Logger LOG = LoggerFactory.getLogger(CreateOperation.class);
    private static final List<ACL> DEFAULT_PERMISSIONS = Ids.OPEN_ACL_UNSAFE;
    private static final CreateMode DEFAULT_MODE = CreateMode.EPHEMERAL;

    private byte[] data;
    private List<ACL> permissions = DEFAULT_PERMISSIONS;
    private CreateMode createMode = DEFAULT_MODE;

    public CreateOperation(ZooKeeper connection, String node) {
        super(connection, node);
    }

    public void setData(byte[] data) {
        this.data = data;
    }

    public void setPermissions(List<ACL> permissions) {
        this.permissions = permissions;
    }

    public void setCreateMode(CreateMode createMode) {
        this.createMode = createMode;
    }

    @Override
    public OperationResult<String> getResult() {
        try {
            String createdPath = connection.create(node, data, permissions, createMode);
            if (LOG.isDebugEnabled()) {
                LOG.debug("Created node '{}' with mode '{}'", createdPath, createMode);
            }
            return new OperationResult<>(createdPath, new Stat());
        } catch (KeeperException | InterruptedException e) {
            return new OperationResult<>(e);
        }
    }
}

