import org.zstack.test.*;
import org.zstack.utils.Utils;
import org.zstack.utils.logging.CLogger;

public class TestFirstAvailableIpAllocatorStrategyReturnIp {
    private static final CLogger logger = Utils.getLogger(TestFirstAvailableIpAllocatorStrategyReturnIp.class);
    @Autowired
    ComponentLoader loader;
    @Autowired
    DatabaseFacade dbf;
    @Autowired
    CloudBus bus;
    Api api;
    ComponentCreator creator;

    @Before
    public void setUp() throws Exception {
        TestUtils.setUpLogging();
        BeanConstructor con = new BeanConstructor();
        con.scanXmls = new String[]{"PortalForUnitTest.xml", "ZoneManager.xml", "NetworkManager.xml", "AccountManager.xml"};
        con.addAutowiredBean(dbf);
        con.addAutowiredBean(bus);
        loader = con.build();
        api = new Api();
        api.startServer();
    }

    @After
    public void tearDown() throws Exception {
        api.stopServer();
    }

    @Test
    public void test() throws ApiSenderException {
        ZoneInventory zone = api.createZones(1).get(0);
        L2NetworkInventory l2 = api.createNoVlanL2Network(zone.getUuid(), "eth0");
        L3NetworkInventory l3 = api.createL3BasicNetwork(l2.getUuid());
        IpRangeInventory ipRange = api.addIpRange(l3.getUuid(), "192.168.0.10", "192.168.0.20", "192.168.0.1", "255.255.255.0");
        AllocateIpMsg amsg = new AllocateIpMsg();
        amsg.setL3NetworkUuid(l3.getUuid());
        amsg.setAllocateStrategy("FirstAvailableIp");
        AllocateIpReply areply = (AllocateIpReply) bus.call(amsg);
        Assert.assertEquals("192.168.0.10", areply.getIpInventory().getIp());
        UsedIpVO uvo = dbf.findByUuid(areply.getIpInventory().getUuid(), UsedIpVO.class);
        Assert.assertNotNull(uvo);

        ReturnIpMsg rmsg = new ReturnIpMsg();
        rmsg.setL3NetworkUuid(l3.getUuid());
        rmsg.setUsedIpUuid(areply.getIpInventory().getUuid());
        bus.send(rmsg);
        uvo = dbf.findByUuid(areply.getIpInventory().getUuid(), UsedIpVO.class);
        Assert.assertNull(uvo);
    }
}

