// Interface representing a read-only record.
public interface Record {
    @Nullable
    Object getField(String key);
}

// Interface representing a value provider.
public interface ValueProvider {
    Object getValue();
}

// Simple implementation of Record that stores fields immutably.
public class BaseRecord implements Record {
    private final Map<String, Object> fields;

    public BaseRecord(Map<String, Object> fields) {
        Preconditions.checkNotNull(fields, "Fields map cannot be null.");
        this.fields = ImmutableMap.copyOf(fields);
    }

    @Override
    @Nullable
    public Object getField(String key) {
        return fields.get(key);
    }

    // Returns an immutable copy of the underlying fields.
    public ImmutableMap<String, Object> getFields() {
        return ImmutableMap.copyOf(fields);
    }
}

// Class that augments an underlying record with additional parameters.
public class AugmentedTemplateParameters implements Record {
    private final Record underlyingRecord;
    private final Map<String, Object> overrides;

    public AugmentedTemplateParameters(Record underlyingRecord) {
        Preconditions.checkNotNull(underlyingRecord, "Underlying record cannot be null.");
        this.underlyingRecord = underlyingRecord;
        this.overrides = Maps.newLinkedHashMap();
    }

    // Sets or overrides a field value.
    public void setField(String key, Object value) {
        Preconditions.checkNotNull(key, "Key cannot be null.");
        overrides.put(key, value);
    }

    // Checks if a field exists either in the overrides or the underlying record.
    public boolean containsField(String key) {
        Preconditions.checkNotNull(key, "Key cannot be null.");
        return overrides.containsKey(key) || (underlyingRecord.getField(key) != null);
    }

    // Retrieves a field value, first checking overrides then falling back to the underlying record.
    @Override
    @Nullable
    public Object getField(String key) {
        Preconditions.checkNotNull(key, "Key cannot be null.");
        if (overrides.containsKey(key)) {
            return overrides.get(key);
        }
        return underlyingRecord.getField(key);
    }

    // Combines the underlying record's fields with the overrides into an immutable map.
    public ImmutableMap<String, Object> getCombinedFields() {

