import javax.swing.UIDefaults;
import javax.swing.UIManager;

public class UIDefaultsHelper {

    public static UIDefaults getUIDefaultsOfClass(String className) {
        UIDefaults defaults = UIManager.getDefaults();
        Map<Object, Object> filteredDefaults = new HashMap<>();

        for (Object key : defaults.keySet()) {
            if (key.toString().startsWith(className)) {
                filteredDefaults.put(key, defaults.get(key));
            }
        }

        UIDefaults classDefaults = new UIDefaults(filteredDefaults);
        return classDefaults;
    }

    public static void main(String[] args) {
        UIDefaults classDefaults = getUIDefaultsOfClass("javax.swing.JButton");
        System.out.println(classDefaults.get("javax.swing.JButton.text"));
    }
}

