public class Tournament {

    // Main function to calculate the total number of matches
    public static int numberOfMatches(int n) {
        if (n == 1) {
            return 0; // No matches needed if there's only one team
        }
        return (n - 1) + numberOfMatches(n / 2);
    }

    // Main function to call and test the output
    public static void main(String[] args) {
        System.out.println(numberOfMatches(7)); // Expected output: 6
        System.out.println(numberOfMatches(14)); // Expected output: 13
    }
}

