import java.util.ArrayList;
import java.util.List;
 
public class StringTest {
    public static void main(String[] args) {
        // Create new string
        String string = "Hello world!";
        System.out.println(string);
        assert string.equals("Hello world!");
 
        // Create and assign value to string
        String assignedStr = "";
        assert assignedStr.equals("");
        assignedStr += "Text has been assigned!";
        System.out.println(assignedStr);
        assert assignedStr.equals("Text has been assigned!");
 
        // String comparison, compared lexicographically byte-wise same as the asserts above
        if (string.equals("Hello world!") && assignedStr.equals("Text has been assigned!")) {
            System.out.println("Strings are equal");
        }
 
        // Cloning -> string can still be used after cloning
        String cloneStr = string;
        System.out.println("String is:" + string + "  and  Clone string is: " + cloneStr);
        assert cloneStr.equals(string);
 
        // Copying, string won't be usable anymore, accessing it will cause compiler failure
        String copyStr = string;
        System.out.println("String copied now: " + copyStr);
 
        // Check if string is empty
        String emptyStr = "";
        assert emptyStr.isEmpty();
 
        // Append byte, Rust strings are a stream of UTF-8 bytes
        String byteStr = "A";
        assert byteStr.equals("A");
 
        // Substrings can be accessed through slices
        String testStr = "Blah String";
        String subStr = testStr.substring(0, 11);
        assert subStr.equals("Blah String");
        subStr = testStr.substring(1, 5);
        assert subStr.equals("lah ");
        subStr = testStr.substring(3);
        assert subStr.equals("h String");
        subStr = testStr.substring(0, 2);
        assert subStr.equals("Bl");
 
        // String replace, note string is immutable
        String orgStr = "Hello";
        assert orgStr.replace("l", "a").equals("Heaao");
        assert orgStr.replace("ll", "r").equals("Hero");
 
        // Joining strings requires a `String` and an &str or a two `String`s one of which needs an & for coercion
        String str1 = "Hi";
        String str2 = " There";
        String finStr = str1 + str2;
        assert finStr.equals("Hi There");
 
        // Joining strings requires a `String` and an &str or two `Strings`s, one of which needs an & for coercion
        str1 = "Hi";
        str2 = " There";
        finStr = str1 + str2;
        assert finStr.equals("Hi There");

