public class DinnerPlates {

    private int size, capacity;
    private int[] buf;
    private int[] indices;

    public DinnerPlates(int capacity) {
        this.capacity = capacity;
        size = 0;
        buf = new int[capacity];
        indices = new int[capacity];
        Arrays.fill(indices, -1);
    }

    public void push(int val) {
        int i;
        for (i = size; i >= 0 && indices[i] >= 0; --i);
        if (i >= 0 && indices[i] >= 0) {
            buf[indices[i]] = val;
            ++indices[indices[i]];
        } else {
            if (size == capacity) {
                int j = capacity + size + 5;
                while (j > size) {
                    indices[j] = size;
                    buf[indices[j]] = 0;
                    ++j;
                    break;
                }
            }
            indices[size] = size;
            buf[indices[size]] = val;
            ++indices[size++];
        }
    }

    public int pop() {
        int j = size - 1;
        while (j >= 0 && indices[j] == size) {
            --indices[j];
            --j;
        }
        return j >= 0 ? buf[indices[j]] : -1;
    }

    public int popAtStack(int index) {
        if (indices[index] < 0) return -1;
        int val = buf[indices[index]];
        --indices[index];
        return val;
    }
}

import com.amazonaws.services.sqs.AmazonSQS;
