public class SQSQueueCreator {

    public static String createQueue(String name) {
        final AmazonSQS sqs = AmazonSQSClientBuilder.defaultClient();

        // Create a new CreateQueueRequest
        final CreateQueueRequest createQueueRequest = new CreateQueueRequest(name);

        // Create the queue and get the result
        final CreateQueueResult createQueueResult = sqs.createQueue(createQueueRequest);

        // Return the queue URL
        return createQueueResult.getQueueUrl();
    }

    public static void main(String[] args) {
        String queueName = "MyQueue";
        String queueUrl = createQueue(queueName);
        System.out.println("Queue URL: " + queueUrl);
    }
}

public class Topswops {
    static final int maxBest = 32;
    static int[] best;
 
    static private void trySwaps(int[] deck, int f, int d, int n) {
        if (d > best[n])
            best[n] = d;
 
        for (int i = n - 1; i >= 0; i--) {
            if (deck[i] == -1 || deck[i] == i)
                break;
            if (d + best[i] <= best[n])
                return;
        }
 
        int[] deck2 = deck.clone();
        for (int i = 1; i < n; i++) {
            final int k = 1 << i;
            if (deck2[i] == -1) {
                if ((f & k) != 0)
                    continue;
            } else if (deck2[i] != i)
                continue;
 
            deck2[0] = i;
            for (int j = i - 1; j >= 0; j--)
                deck2[i - j] = deck[j]; // Reverse copy.
            trySwaps(deck2, f | k, d + 1, n);
        }
    }
 
    static int topswops(int n) {
        assert(n > 0 && n < maxBest);
        best[n] = 0;
        int[] deck0 = new int[n + 1];
        for (int i = 1; i < n; i++)
            deck0[i] = -1;
        trySwaps(deck0, 1, 0, n);
        return best[n];
    }
 
    public static void main(String[] args) {
        best = new int[maxBest];
        for (int i = 1; i < 11; i++)
            System.out.println(i + ": " + topswops(i));
    }
}

public abstract class MyAbstractList<E> implements MyList<E> {

  protected int size;

  protected MyAbstractList() {
  }

  protected MyAbstractList(E[] objects) {
    for (int i = 0; i < objects.length; i++)
      add(objects[i]);
  }

  @Override
  public boolean addAll(MyList<E> otherList) {
    int oldSize = size;
    for (E e : otherList)
      add(e);
    return size > oldSize;
  }

  @Override
  public boolean removeAll(MyList<E> otherList) {
    int oldSize = size;
    for (E e : otherList)
      remove(e);
    return size < oldSize;
  }

  @Override
  public boolean retainAll(MyList<E> otherList) {
    int oldSize = size;
    MyList<E> tempList = new MyArrayList<>();
    for (E e : this) {
      if (otherList.contains(e))
        tempList.add(e);
    }
    clear();
    addAll(tempList);
    return size < oldSize;
  }

  @Override
  public int size() {
    return size;
  }

  @Override
  public boolean isEmpty() {
    return size == 0;
  }

  @Override
  public boolean contains(E e) {
    return indexOf(e) >= 0;
  }

  @Override
  public boolean add(E e) {
    add(size, e);
    return true;
  }

  @Override
  public void add(int index, E e) {
    if (index < 0 || index > size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);
    ensureCapacity();

    for (int i = size - 1; i >= index; i--)
      this.set(i + 1, this.get(i));

    this.set(index, e);

    size++;
  }

  @Override
  public E remove(int index) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E e = get(index);

    for (int j = index; j < size - 1; j++)
      this.set(j, this.get(j + 1));

    this.set(size - 1, null);

    size--;

    return e;
  }

  @Override
  public int indexOf(E e) {
    for (int i = 0; i < size; i++)
      if (e.equals(get(i)))
        return i;

    return -1;
  }

  @Override
  public int lastIndexOf(E e) {
    for (int i = size - 1; i >= 0; i--)
      if (e.equals(get(i)))
        return i;

    return -1;
  }

  @Override
  public E set(int index, E e) {
    if (index < 0 || index >= size)
      throw new IndexOutOfBoundsException("Index: " + index + ", Size: " + size);

    E old = get(index);
    data[index] = e;
    return old;
  }

  @Override
  public String toString() {
    StringBuilder result = new StringBuilder("[");

    for (int i = 0; i < size; i++) {
      result.append(data[i]);
      if (i < size - 1)
        result.append(", ");
    }

    return result.toString() + "]";
  }
}

