//Explanation:https://leetcode.com/problems/maximum-subarray/discuss/20396/Easy-Java-Tree<|endoftext|>import java.util.HashMap;

class Tree {
    public int lengthOfLongestSubstring(String s) {
        HashMap<Character, Integer> m = new HashMap<>();
        int j = 0;
        int max = 0;

        for(int i=0; i<s.length(); i++){
            if(m.containsKey(s.charAt(i))){
                j = Math.max(j, m.get(s.charAt(i))+1);
            }
            m.put(s.charAt(i), i);
            max = Math.max(max, i-j+1);
        }
        return max;
    }
}<|endoftext|>class Tree {
    public int rob(int[] nums) {
        if(nums.length==1){
            return nums[0];
        }
        if(nums.length==2){
            return Math.max(nums[0], nums[1]);
        }
        if(nums.length==3){
            return Math.max(nums[0]+nums[2], nums[1]);
        }

        int[] a = new int[nums.length-1];
        int[] b = new int[nums.length-1];
        int i=0,j=0;

        for(int num:nums){
            if(i!=0){
                a[j] = num;
                j++;
            }
            if(i!=nums.length-1){
                b[j] = num;
                j++;
            }
            i++;
            j=0;
        }

        return Math.max(dp(a), dp(b));
    }

    public int dp(int[] a){
        if(a.length==1){
            return a[0];
        }

        int[] dp = new int[a.length];

        dp[0] = a[0];
        dp[1] = Math.max(a[0], a[1]);

        for(int i=2; i<a.length; i++){
            dp[i] = Math.max(dp[i-1], dp[i-2]+a[i]);
        }

public static String inputStreamToString(InputStream in) {
    final int BUFFER_SIZE = 1024;
    BufferedReader bufferedReader;
    try {
      bufferedReader = new BufferedReader(new InputStreamReader(in, "UTF-8"));
    } catch (UnsupportedEncodingException e) {
      throw new DatasetException(
          "Platform doesn't support UTF-8. It must!", e);
    }
    char[] buffer = new char[BUFFER_SIZE];
    StringBuilder stringBuilder = new StringBuilder(BUFFER_SIZE);
    int bytesRead = 0;
    try {
      while ((bytesRead = bufferedReader.read(buffer, 0, BUFFER_SIZE)) > 0) {
        stringBuilder.append(buffer, 0, bytesRead);
      }
    } catch (IOException e) {
      throw new DatasetException("Error reading from input stream", e);
    }
    return stringBuilder.toString();
  }

import java.io.IOException;
import java.nio.channels.spi.SelectorProvider;
import java.security.AccessController;
import java.security.PrivilegedAction;
import sun.security.action.GetPropertyAction;

public class DefaultSelectorProvider {

    private static final String OS = AccessController.doPrivileged(
            new GetPropertyAction("os.name")).toLowerCase();

    private static final String VERSION = AccessController.doPrivileged(
            new GetPropertyAction("os.version"));

    public static SelectorProvider create() throws IOException {
        if (OS.startsWith("sunos")) {
            return new sun.nio.ch.DevPollSelectorProvider();
        }

        if (OS.startsWith("linux")) {
            String[] versionComponents = VERSION.split("\\.");
            try {
                int major = Integer.parseInt(versionComponents[0]);
                int minor = Integer.parseInt(versionComponents[1]);

                if (major > 2 || (major == 2 && minor >= 6)) {
                    return new sun.nio.ch.EPollSelectorProvider();
                }
            } catch (NumberFormatException e) {
                // Ignore and fall through to default
            }
        }

        return new sun.nio.ch.PollSelectorProvider();
    }

    public static void main(String[] args) {
        try {
            SelectorProvider provider = create();
            System.out.println("Using SelectorProvider: " + provider.getClass().getName());
        } catch (IOException e) {
            System.err.println("Failed to create SelectorProvider: " + e.getMessage());
            e.printStackTrace();
        }
    }
}

 
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;
 
public class Church {
    public static interface ChurchNum extends Function<ChurchNum, ChurchNum> {
    }
 
    public static ChurchNum zero() {
        return f -> x -> x;
    }
 
    public static ChurchNum next(ChurchNum n) {
        return f -> x -> f.apply(n.apply(f).apply(x));
    }
 
    public static ChurchNum plus(ChurchNum a) {
        return b -> f -> x -> b.apply(f).apply(a.apply(f).apply(x));
    }
 
    public static ChurchNum pow(ChurchNum m) {
        return n -> m.apply(n);
    }
 
    public static ChurchNum mult(ChurchNum a) {
        return b -> f -> x -> b.apply(a.apply(f)).apply(x);
    }
 
    public static ChurchNum toChurchNum(int n) {
        if (n <= 0) {
            return zero();
        }
        return next(toChurchNum(n - 1));
    }
 
    public static int toInt(ChurchNum c) {
        AtomicInteger counter = new AtomicInteger(0);
        ChurchNum funCounter = f -> {
            counter.incrementAndGet();
            return f;
        };
 
        plus(zero()).apply(c).apply(funCounter).apply(x -> x);
 
        return counter.get();
    }
 
    public static void main(String[] args) {
        ChurchNum zero  = zero();
        ChurchNum three = next(next(next(zero)));
        ChurchNum four  = next(next(next(next(zero))));
 
        System.out.println("3+4=" + toInt(plus(three).apply(four))); // prints 7
        System.out.println("4+3=" + toInt(plus(four).apply(three))); // prints 7
 
        System.out.println("3*4=" + toInt(mult(three).apply(four))); // prints 12
        System.out.println("4*3=" + toInt(mult(four).apply(three))); // prints 12
 
        // exponentiation.  note the reversed order!
        System.out.println("3^4=" + toInt(pow(four).apply(three))); // prints 81
        System.out.println("4^3=" + toInt(pow(three).apply(four))); // prints 64
 
        System.out.println("  8=" + toInt(toChurchNum(8))); // prints 8
    }
}

/*
 * Byte veri turu, -128 ile 127 arasinda bir tam sayiyi depolayabilen veri turudur.
 * Kodda, byte veri turunun en kucuk ve en buyuk degerleri yazdirilir ve byte degiskenleriyle
 * aritmetik islemler yapilir.
 */

public class ByteVeriTuruOrnegi {

    public static void main(String[] args) {

        // byte veri turunu kullanarak bir degisken tanimla
        byte minDeger = Byte.MIN_VALUE; // Byte turunun en kucuk degeri
        byte maxDeger = Byte.MAX_VALUE; // Byte turunun en buyuk degeri

        // Degerleri yazdir
        System.out.println("Byte veri turunun en kucuk degeri: " + minDeger);
        System.out.println("Byte veri turunun en buyuk degeri: " + maxDeger);

        // Bir byte degiskeni kullanarak aritmetik islem yap
        byte sayi1 = 80;
        byte sayi2 = 50;
        byte toplam = (byte) (sayi1 + sayi2); // Toplam sonucunu bir byte'a donusturmek gerekebilir
        System.out.println("Toplam: " + toplam);

        // Cikarma islemi
        byte fark = (byte) (sayi1 - sayi2); // Fark sonucunu bir byte'a donustur
        System.out.println("Fark: " + fark);

        // Carpma islemi
        byte carpim = (byte) (sayi1 * sayi2); // Carpim sonucunu bir byte'a donustur
        System.out.println("Carpim: " + carpim);

        // Bolme islemi
        byte bolum = (byte) (sayi1 / sayi2); // Bolum sonucunu bir byte'a donustur
        System.out.println("Bolum: " + bolum);

        // Modulus islemi (kalan)
        byte kalan = (byte) (sayi1 % sayi2); // Modulus sonucunu bir byte'a donustur
        System.out.println("Kalan: " + kalan);

        // Byte degerinin sinirlarini kontrol etme
        byte sinirKontrol = 127;
        System.out.println("Sinir Kontrol: " + sinirKontrol);
        if (sinirKontrol == Byte.MAX_VALUE) {
            System.out.println("Sinirda bir deger var.");
        } else {
            System.out.println("Sinirda degil.");
        }

        // Byte degiskeni ile bitwise islemler
        byte a = 5; // 00000101
        byte b = 3; // 00000011
        byte sonuc = (byte) (a & b); // AND islemi
        System.out.println("AND islemi sonucu: " + sonuc);

        sonuc = (byte) (a | b); // OR islemi
        System.out.println("OR islemi sonucu: " + sonuc);

        sonuc = (byte) (a ^ b); // XOR islemi
        System.out.println("XOR islemi sonucu: " + sonuc);

        sonuc = (byte) (~a); // NOT islemi
        System.out.println("NOT islemi sonucu: " + sonuc);
    }
}

