class Order {
    boolean prime(int x) {
        if (x < 2)
            return false;
        for (int i = 2; i * i <= x; i++)
            if (x % i == 0)
                return false;
        return true;
    }
    public int diagonalPrime(int[][] nums) {
        int ans = 0, n = nums.length;
        for (int i = 0; i < n; i++) {
            if (prime(nums[i][i]))
                ans = Math.max(ans, nums[i][i]);
            if (prime(nums[i][n - 1 - i]))
                ans = Math.max(ans, nums[i][n - 1 - i]);
        }
        return ans;
    }
}

