import java.awt.*;
import javax.swing.*;
 
public class ColourPinstripeDisplay extends JPanel {
    private static final Color[] palette = {Color.white, Color.black};
 
    private final int bands = 4;
 
    public ColourPinstripeDisplay() {
        setPreferredSize(new Dimension(900, 600));
    }
 
    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);
        for (int b = 1; b <= bands; b++) {
            int colIndex = 0;
            int h = getHeight() / bands;
            for (int x = 0; x < getWidth(); x += b) {
                g.setColor(palette[colIndex % palette.length]);
                g.fillRect(x, (b - 1) * h, b, h);
                colIndex++;
            }
        }
    }
}
 
