import android.content.Context;
import android.util.AttributeSet;
import android.view.View;
import android.view.animation.DecelerateInterpolator;
import android.view.animation.AccelerateInterpolator;

import androidx.coordinatorlayout.widget.CoordinatorLayout;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;

import com.daimajia.androidanimations.library.Techniques;
import com.daimajia.androidanimations.library.YoYo;

public class ScaleTitlebarBehavior extends CoordinatorLayout.Behavior<View> {

    private static final int ANIMATION_DURATION = 300;
    private boolean isTitleBarVisible = true;

    public ScaleTitlebarBehavior() {
        super();
    }

    public ScaleTitlebarBehavior(Context context, AttributeSet attrs) {
        super(context, attrs);
    }

    @Override
    public boolean onStartNestedScroll(@NonNull CoordinatorLayout coordinatorLayout, @NonNull View child, @NonNull View target, int nestedScrollAxes, int type) {
        return (nestedScrollAxes & View.SCROLL_AXIS_VERTICAL) != 0;
    }

    @Override
    public void onNestedScroll(@NonNull CoordinatorLayout coordinatorLayout, @NonNull View child, @NonNull View target, int dxConsumed, int dyConsumed, int dxUnconsumed, int dyUnconsumed, int type) {
        if (dyConsumed < 0) {
            // Scrolling up
            if (!isTitleBarVisible) {
                showTitleBar(child);
            }
        } else if (dyConsumed > 0) {
            // Scrolling down
            if (isTitleBarVisible) {
                hideTitleBar(child);
            }
        }
    }

    private void showTitleBar(View titleBar) {
        isTitleBarVisible = true;
        titleBar.setVisibility(View.VISIBLE);
        YoYo.with(Techniques.ScaleIn)
                .duration(ANIMATION_DURATION)
                .interpolate(new DecelerateInterpolator())
                .playOn(titleBar);
    }

    private void hideTitleBar(View titleBar) {
        isTitleBarVisible = false;
        YoYo.with(Techniques.ScaleOut)
                .duration(ANIMATION_DURATION)
                .interpolate(new AccelerateInterpolator())
                .withListener(new com.daimajia.androidanimations.listener.AnimatorListenerAdapter() {
                    @Override
                    public void onAnimationEnd(android.animation.Animator animator) {
                        titleBar.setVisibility(View.GONE);
                    }
                })
                .playOn(titleBar);
    }

