import com.google.common.collect.ImmutableList;
import org.apache.calcite.sql.SqlIdentifier;
import org.apache.calcite.sql.parser.SqlParserPos;
import java.util.List;
import java.util.Objects;

public class SqlMonikerImpl implements SqlMoniker {
    private final ImmutableList<String> names;
    private final SqlMonikerType type;

    public SqlMonikerImpl(List<String> names, SqlMonikerType type) {
        this.names = ImmutableList.copyOf(Objects.requireNonNull(names, "names"));
        this.type = Objects.requireNonNull(type, "type");
        if (this.names.isEmpty()) {
            throw new IllegalArgumentException("Names list cannot be empty");
        }
        for (String name : this.names) {
            if (name == null || name.trim().isEmpty()) {
                throw new IllegalArgumentException("Name cannot be null or empty");
            }
        }
    }

    public SqlMonikerImpl(String name, SqlMonikerType type) {
        this(ImmutableList.of(Objects.requireNonNull(name, "name")), type);
    }

    @Override
    public SqlMonikerType getType() {
        return type;
    }

    @Override
    public ImmutableList<String> getFullyQualifiedNames() {
        return names;
    }

    @Override
    public SqlIdentifier id() {
        return new SqlIdentifier(names, SqlParserPos.ZERO);
    }

    public SqlIdentifier toIdentifier() {
        return id();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        SqlMonikerImpl that = (SqlMonikerImpl) o;
        return type == that.type && names.equals(that.names);
    }

    @Override
    public int hashCode() {
        return Objects.hash(type, names);
    }

    @Override
    public String toString() {
        return String.join(".", names);
    }
}

