        @Override
        public ByteBuf toByteArray() {
            return createChannelBufferWithHeader();
        }

        @Override
        public byte getOpcode() {
            return DISCONNECT_REQUEST;
        }
    }

    public static class Response extends DirectMsgNetty.Response {

        private static final byte DISCONNECT_RESPONSE = (byte) 0x21;
        private final int ref;

        public Response(Address src, Address dest, TimeoutId timeoutId, int ref) {
            super(src, dest, timeoutId);
            this.ref = ref;
        }

        public int getRef() {
            return ref;
        }

        @Override
        public int getSize() {
            return 2;
        }

        @Override
        public RewriteableMsg copy() {
            return new Response(vodSrc, vodDest, timeoutId, ref);
        }

        @Override
        public ByteBuf toByteArray() {
            ByteBuf buffer = createChannelBufferWithHeader();
            UserTypesEncoderFactory.writeUnsignedintAsTwoBytes(buffer, ref);
            return buffer;
        }

        @Override
        public byte getOpcode() {
            return DISCONNECT_RESPONSE;
        }
    }

