import java.util.*;

public class Sorter {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        for (int i = 0; i < t; i++) {
            int n = scanner.nextInt();
            int[] a = new int[n];
            for (int j = 0; j < n; j++) {
                a[j] = scanner.nextInt();
            }

            int maxLength = findMaxLength(a);
            System.out.println(maxLength == -1 ? -1 : maxLength);
        }

        scanner.close();
    }

    private static int findMaxLength(int[] a) {
        int n = a.length;
        int maxLength = -1;

        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = i; j < n; j++) {
                if (a[j] == a[i]) {
                    count++;
                } else {
                    break;
                }
            }

            if (count > 1) {
                int subLength = count / 2;
                if (subLength > maxLength) {
                    maxLength = subLength;
                }
            }
        }

        return maxLength;
    }
}

import java.util.Scanner;

public class SubstringSearch {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter a string s1: ");
        String s1 = input.nextLine();

        System.out.print("Enter a string s2: ");
        String s2 = input.nextLine();

        int i = 0;
        int j = 0;
        int index = -1;

        while (i < s1.length() && j < s2.length()) {
            if (s1.charAt(i) == s2.charAt(j)) {
                if (index == -1) {
                    index = i;
                }
                j++;
            } else {
                j = 0;
                index = -1;
            }
            i++;
        }

        if (j == s2.length()) {
            System.out.println("matched at index " + (index - j + 1));
        } else {
            System.out.println("not matched");
        }
    }
}

public Long returnLongObject(Object value) {
    if(value == null) {
        return null;
    }
    if(value instanceof Long) {
        return (Long) value;
    }
    if(value instanceof Number) {
        return ((Number) value).longValue();
    }
    try {
        return Long.parseLong(String.valueOf(value));

    } catch(NumberFormatException e) {
        throw new IllegalArgumentException("Cannot convert value to long: " + value, e);
    }
}

import java.util.Arrays;
 
public class OEIS_A005179 {
 
    static int count_divisors(int n) {
        int count = 0;
        for (int i = 1; i * i <= n; ++i) {
            if (n % i == 0) {
                if (i == n / i)
                    count++;
                else
                    count += 2;
            }
        }
        return count;
    }
 
    public static void main(String[] args) {
        final int max = 15;
        int[] seq = new int[max];
        System.out.printf("The first %d terms of the sequence are:\n", max);
        for (int i = 1, n = 0; n < max; ++i) {
            int k = count_divisors(i);
            if (k <= max && seq[k - 1] == 0) {
                seq[k- 1] = i;
                n++;
            }
        }
        System.out.println(Arrays.toString(seq));
    }
}

