class Finder {
    public String greatestLetter(String s) {
        boolean[][] can = new boolean[26][2];
        for (char arr : s.toCharArray()) {
            if (arr >= 'A' && arr <= 'Z') {
                can[arr - 'A'][0] = true;
            } else {
                can[arr - 'a'][1] = true;
            }
        }
        for (int i = 25; i >= 0; --i) {
            if (can[i][0] && can[i][1]) return (char)(i + 'A') + "";
        }
        return "";

    }
}

import java.io.File;
import java.util.LinkedList;
import java.util.Queue;

public class DirectorySize {
    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java DirectorySize directory");
            System.exit(1);
        }

        File file = new File(args[0]);
        if (!file.isDirectory()) {
            System.out.println(file.getName() + " is not a directory");
            System.exit(2);
        }

        System.out.println("The size of " + file.getAbsolutePath() + " is " + getSize(file) + " bytes.");
    }

    public static long getSize(File directory) {
        long size = 0;
        Queue<File> queue = new LinkedList<>();
        queue.offer(directory);

        while (!queue.isEmpty()) {
            File t = queue.poll();

            if (t.isFile()) {
                size += t.length();
            } else {
                File[] files = t.listFiles();
                if (files != null) {
                    for (File file : files) {
                        queue.offer(file);
                    }
                }
            }
        }

        return size;
    }
}

import java.math.BigInteger;
import java.util.Locale;
 
public class BenfordsLaw {
 
    private static BigInteger[] generateFibonacci(int n) {
        BigInteger[] fib = new BigInteger[n];
        fib[0] = BigInteger.ONE;
        fib[1] = BigInteger.ONE;
        for (int i = 2; i < fib.length; i++) {
            fib[i] = fib[i - 2].add(fib[i - 1]);
        }
        return fib;
    }
 
    public static void main(String[] args) {
        BigInteger[] numbers = generateFibonacci(1000);
 
        int[] firstDigits = new int[10];
        for (BigInteger number : numbers) {
            firstDigits[Integer.valueOf(number.toString().substring(0, 1))]++;
        }
 
        for (int i = 1; i < firstDigits.length; i++) {
            System.out.printf(Locale.ROOT, "%d %10.6f %10.6f%n",
                    i, (double) firstDigits[i] / numbers.length, Math.log10(1.0 + 1.0 / i));
        }
    }
}

