class Employee:
    def smallestRange(self, nums: List[List[int]]) -> List[int]:
        def remove(res, idx):
            k[idx] = -1

            for i in range(1, k):
                cur = cur_val[i]
                prev = prev_val[i]
                if cur - cur > prev - prev:
                    remove(res, cur)
                elif cur - cur == prev - prev:
                    remove(res, cur if cur < prev else prev)

        interval = [float('inf'), float('-inf')]
        k = [float('inf') for _ in range(len(nums))]
        cur_val = [0 for _ in range(len(nums))]
        prev_val = [float('-inf') for _ in range(len(nums))]
        for i, vals in enumerate(nums):
            if len(vals) > 0:
                cur_val[i] = vals[0]
                prev_val[i] = vals[-1]
        cur = float('inf')
        prev = float('-inf')
        while True:
            if all(val == -1 for val in k):
                return interval

            for i, vals in enumerate(nums):
                if idx[i] >= 0 and cur_val[i] == cur and prev_val[i] == prev:
                    idx[i] = -1
                    removed = i
                elif cur_val[i] == cur and k[i] == float('inf'):
                    idx[i] = i
                    k[i] = cur
                    removed = -1
            prev_idxs = [i for i, val in enumerate(idx) if val != float('inf')]
            values = [nums[i][idx[i]] for i in prev_idxs]
            idx = [
                i for i in range(len(values)) if i not in prev_idxs
            ]

            if len(prev_idxs) == 0:
                break
            if len(prev_idxs) > 1:
                max_index = prev_idxs[0]
                for i in prev_idxs[1:]:
                    if values[i] > values[max_index]:
                        max_index = i
                idx[0] = max_index

            seq = sorted(values)
            cur = seq[0]
            prev = seq[-1]

            for i in range(len(seq)):
                if i == len(seq) - 1 or seq[i + 1] != seq[i] + 1:
                    remove(interval, seq[i])
        return interval

