@Entity
@Table(name = "auditoria_dados")
public class AuditoriaDados implements Serializable {

    // Serialization unique identifier for compatibility.
    private static final long serialVersionUID = 1L;

    // Unique identifier for each audit record.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false)
    private Long id;

    // Name of the attribute being audited.
    @Column(name = "nome_atributo", nullable = false)
    private String nomeAtributo;

    // Value of the attribute at the time of the audit.
    @Column(name = "valor_atributo", nullable = false)
    private String valorAtributo;

    // Operational state indicating before or after a change.
    @Column(name = "situacao_operacao", nullable = false)
    private String situacaoOperacao;

