// Reference: https://en.wikipedia.org/wiki/Lah_number#Identities_and_relations
 
import java.math.BigInteger;
import java.util.HashMap;
import java.util.Map;
 
public class LahNumbers {
    public static void main(String[] args) {
        printLahNumbers(12);
        System.out.println("Maximum value of L(n,k) where n == 100:");
        BigInteger max = BigInteger.ZERO;
        for (int k = 0; k <= 100; ++k)
            max = max.max(getLahNumber(100, k));
        System.out.println(max);
    }
 
    private static void printLahNumbers(int n) {
        System.out.print("Unsigned Lah numbers up to L(12,12):\nn/k");
        for (int j = 1; j <= n; ++j)
            System.out.printf("%11d", j);
        System.out.println();
        for (int i = 1; i <= n; ++i) {
            System.out.printf("%2d ", i);
            for (int j = 1; j <= i; ++j)
                System.out.printf("%11d", getLahNumber(i, j));
            System.out.println();
        }
    }
 
    private static BigInteger getLahNumber(int n, int k) {
        if (k == n)
            return BigInteger.ONE;
        if (k == 0 || k > n)
            return BigInteger.ZERO;
        Map.Entry<Integer, Map<Integer, BigInteger>> entry = cache.floorEntry(n);
        if (entry!= null) {
            Map<Integer, BigInteger> map = entry.getValue();
            BigInteger result = map.get(k);
            if (result!= null)
                return result;
        }
        BigInteger result = getLahNumber(n - 1, k).multiply(BigInteger.valueOf(n - 1 + k))
               .add(getLahNumber(n - 1, k - 1));
        cache.computeIfAbsent(n, x -> new HashMap<>()).put(k, result);
        return result;
    }
 
    private static final Map<Integer, Map<Integer, BigInteger>> cache = new HashMap<>();
}

public class Calculator {

    // Iki sayiyi toplama islemi yapan method
    public int add(int a, int b) {
        return a + b;
    }

    // Iki sayiyi cikarma islemi yapan method
    public int subtract(int a, int b) {
        return a - b;
    }

    // Iki sayiyi carpma islemi yapan method
    public int multiply(int a, int b) {
        return a * b;
    }

    // Iki sayiyi bolme islemi yapan method
    public int divide(int a, int b) throws IllegalArgumentException {
        if (b == 0) {
            // Sifira bolme yapilamaz, hata firlatilir
            throw new IllegalArgumentException("Sifira bolme yapilamaz.");
        }
        return a / b;
    }

    // Iki sayiyi mod alma islemi yapan method
    public int modulus(int a, int b) throws IllegalArgumentException {
        if (b == 0) {
            // Sifira bolme yapilamaz, hata firlatilir
            throw new IllegalArgumentException("Sifira mod alma yapilamaz.");
        }
        return a % b;
    }

    // Bir sayinin faktoryelini hesaplayan method
    public long factorial(int n) throws IllegalArgumentException {
        if (n < 0) {
            // Negatif sayi ile faktoriyel hesaplanamaz, hata firlatilir
            throw new IllegalArgumentException("Negatif sayilarin faktoriyeli hesaplanamaz.");
        }
        long result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        return result;
    }

    // Iki sayinin us alarak hesaplamasini yapan method
    public double power(double base, double exponent) {
        return Math.pow(base, exponent);
    }

    // Bir sayinin karekokunu hesaplayan method
    public double squareRoot(double a) throws IllegalArgumentException {
        if (a < 0) {
            // Negatif sayinin karekoku hesaplanamaz, hata firlatilir
            throw new IllegalArgumentException("Negatif sayilarin karekoku hesaplanamaz.");
        }
        return Math.sqrt(a);
    }

    // Iki sayinin maksimum degerini bulan method
    public int max(int a, int b) {
        return (a > b) ? a : b;
    }

    // Iki sayinin minimum degerini bulan method
    public int min(int a, int b) {
        return (a < b) ? a : b;
    }

    // Iki sayinin ortalamasini hesaplayan method
    public double average(int a, int b) {
        return (a + b) / 2.0;
    }
}

import java.util.Scanner;

public class AsalSayiKontrolu {

    public static void main(String[] args) {

        Scanner okuyucu = new Scanner(System.in);

        // Kullanicidan gecerli bir sayi gelene kadar sormaya devam ediyoruz
        System.out.print("Bir sayi girin: ");
        int deger = okuyucu.nextInt();

        while (deger <= 1) {
            System.out.println("Lutfen 2'den buyuk bir pozitif sayi girin.");
            deger = okuyucu.nextInt();
        }

        okuyucu.close();

        // Asalligi kontrol etmek icin bolen arayan bir yardimci metot cagiriyoruz
        boolean sonuc = asalMi(deger);

        if (sonuc) {
            System.out.println(deger + " asal sayidir.");
        } else {
            System.out.println(deger + " asal sayi degildir.");
        }
    }

    // Verilen sayinin asal olup olmadigini dondurur
    private static boolean asalMi(int sayi) {
        int bolen = 2;
        while (bolen <= sayi / 2) {
            if (sayi % bolen == 0) {
                return false;
            }
            bolen++;
        }
        return true;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public class ElementaryCellularAutomaton {
    public static void main(String[] args) {
        int lines = 50;
        String start = "0000000001000000000";
        int[] rules = {90, 30, 122};
        List<String> zipped = Stream.of(IntStream.range(0, lines).boxed().collect(Collectors.toList()),
                Arrays.stream(rules).mapToObj(rule -> eca(start, rule)).collect(Collectors.toList()))
               .map(l -> l.stream().map(Object::toString).collect(Collectors.toList()))
               .flatMap(l -> l.stream())
               .collect(Collectors.toList());
        System.out.println("   Rules: " + Arrays.toString(rules));
        for (int i = 0; i < zipped.size(); i += rules.length) {
            System.out.println(String.format("%2d: %s", i / rules.length,
                    zipped.subList(i, i + rules.length).stream().collect(Collectors.joining("    ")).replace('0', '.')
                           .replace('1', '#')));
        }
    }

    private static Stream<String> eca(String cells, int rule) {
        int lencells = cells.length();
        String c = "0" + cells + "0"; // Zero pad the ends
        String rulebits = String.format("%8s", Integer.toBinaryString(rule)).replace(' ', '0');
        String[] neighbours2next = new String[8];
        for (int n = 0; n < 8; n++) {
            neighbours2next[n] = rulebits.charAt(7 - n) + "";
        }
        return Stream.of(c.substring(1, lencells + 1)).peek(System.out::println).flatMap(s -> {
            c = "0" + IntStream.range(1, lencells + 1).mapToObj(i -> neighbours2next[c.charAt(i - 1) - '0' + (c.charAt(i) - '0') * 2 + (c.charAt(i + 1) - '0') * 4])
                   .collect(Collectors.joining()) + "0";
            return eca(c.substring(1, lencells + 1), rule);
        });
    }
}

