public class SubtleSubstringSubtraction {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            String s = sc.next();
            String winner = playGame(s);
            int scoreDifference = getFinalScores(s, winner).getAliceScore() - getFinalScores(s, winner).getBobScore();
            System.out.println(winner + " " + scoreDifference);
        }
        sc.close();
    }

    private static int getCharValue(char c) {
        return c - 'a' + 1;
    }

    private static String playGame(String s) {
        boolean aliceTurn = true;
        while (!s.isEmpty()) {
            String nextString = "";
            if (aliceTurn) {
                int maxValIndex = 0, maxVal = 0;
                for (int i = 0; i < s.length() - 1; i++) {
                    if ((i + 2) <= s.length()) {
                        int val = getCharValue(s.charAt(i + 1)) + getCharValue(s.charAt(i + 2));
                        if (val > maxVal) {
                            maxVal = val;
                            maxValIndex = i;
                        }
                    }
                }
                nextString = s.substring(0, maxValIndex) + s.substring(maxValIndex + 2);
            } else {
                int maxValIndex = 0, maxVal = 0;
                for (int i = 0; i < s.length(); i++) {
                    int val = getCharValue(s.charAt(i));
                    if (val > maxVal) {
                        maxVal = val;
                        maxValIndex = i;
                    }
                }
                nextString = s.substring(0, maxValIndex) + s.substring(maxValIndex + 1);
            }
            s = nextString;
            aliceTurn = !aliceTurn;
        }
        return aliceTurn ? "Alice" : "Bob";
    }

    private static Score getFinalScores(String s, String winner) {
        Score scores = new Score();
        if (winner.equals("Alice")) {
            for (int i = 0; i < s.length() - 1; i++) {
                int val = getCharValue(s.charAt(i + 1)) * (i % 2 == 0 ? 2 : 1);
                scores.addAliceScore(val);
            }
        } else {
            for (int i = 0; i < s.length(); i++) {
                int val = getCharValue(s.charAt(i)) * (i % 2 == 0 ? 2 : 1);
                scores.addBobScore(val);
            }
        }
        return scores;
    }

    static class Score {
        int aliceScore = 0;
        int bobScore = 0;

import java.util.ArrayList;
import java.util.List;
 
public class SquareFree
{
    private static List<Long> sieve(long limit) {
        List<Long> primes = new ArrayList<Long>();
        primes.add(2L);
        boolean[] c = new boolean[(int)limit + 1]; // composite = true
        // no need to process even numbers > 2
        long p = 3;
        for (;;) {
            long p2 = p * p;
            if (p2 > limit) break;
            for (long i = p2; i <= limit; i += 2 * p) c[(int)i] = true;
            for (;;) {
                p += 2;
                if (!c[(int)p]) break;
            }
        }
        for (long i = 3; i <= limit; i += 2) {
            if (!c[(int)i]) primes.add(i);
        }
        return primes;
    }
 
    private static List<Long> squareFree(long from, long to) {
        long limit = (long)Math.sqrt((double)to);
        List<Long> primes = sieve(limit);
        List<Long> results = new ArrayList<Long>();
 
        outer: for (long i = from; i <= to; i++) {
            for (long p : primes) {
                long p2 = p * p;
                if (p2 > i) break;
                if (i % p2 == 0) continue outer;
            }
            results.add(i);
        }
        return results;
    }
 
    private final static long TRILLION = 1000000000000L;
 
    public static void main(String[] args) {
        System.out.println("Square-free integers from 1 to 145:");
        List<Long> sf = squareFree(1, 145);
        for (int i = 0; i < sf.size(); i++) {
            if (i > 0 && i % 20 == 0) {
                System.out.println();
            }
            System.out.printf("%4d", sf.get(i));
        }
 
        System.out.print("\n\nSquare-free integers");
        System.out.printf(" from %d to %d:\n", TRILLION, TRILLION + 145);
        sf = squareFree(TRILLION, TRILLION + 145);
        for (int i = 0; i < sf.size(); i++) {
            if (i > 0 && i % 5 == 0) System.out.println();
            System.out.printf("%14d", sf.get(i));
        }
 
        System.out.println("\n\nNumber of square-free integers:\n");
        long[] tos = {100, 1000, 10000, 100000, 1000000};
        for (long to : tos) {
            System.out.printf("  from %d to %d = %d\n", 1, to, squareFree(1, to).size());
        }
    }
}

public static boolean[] and(final INDArray n, final Condition condition, int... dimension) {
        if (!(condition instanceof BaseCondition))
            throw new UnsupportedOperationException("Only static Conditions are supported");
        MatchCondition op = new MatchCondition(n, condition);
        INDArray arr = Nd4j.getExecutioner().exec(op, dimension);
        boolean[] result = new boolean[(int) arr.length()];
        long tadLength = Shape.getTADLength(n.shape(), dimension);
        for (int i = 0; i < arr.length(); i++) {
            if (arr.getDouble(i) == tadLength)
                result[i] = true;
            else
                result[i] = false;
        }
        return result;
    }

