public Set<String> collectUnionStates(List<List<String>> parallelSubtaskStates){
    Set<String> unionStates = new HashSet<>();
    for(List<String> subtaskStates : parallelSubtaskStates){
        unionStates.addAll(subtaskStates);
    }
    return unionStates;
}

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class CircularPrimes {
 
    public static boolean isPrime(BigInteger n, int reps) {
        return n.isProbablePrime(reps);
    }
 
    public static String toString(BigInteger n) {
        return n.toString();
    }
 
    public static boolean isCircularPrime(BigInteger p) {
        if (!isPrime(p, 50)) {
            return false;
        }
        String str = toString(p);
        for (int i = 0, n = str.length(); i + 1 < n; ++i) {
            str = str.substring(1) + str.charAt(0);
            BigInteger p2 = new BigInteger(str);
            if (p2.compareTo(p) < 0 ||!isPrime(p2, 50)) {
                return false;
            }
        }
        return true;
    }
 
    public static BigInteger nextRepunit(BigInteger n) {
        BigInteger p = BigInteger.ONE;
        while (p.compareTo(n) < 0) {
            p = p.multiply(BigInteger.TEN).add(BigInteger.ONE);
        }
        return p;
    }
 
    public static BigInteger repunit(int digits) {
        String str = String.format("%0" + digits + "d", 0).replace('0', '1');
        BigInteger p = new BigInteger(str);
        return p;
    }
 
    public static void testRepunit(int digits) {
        if (isPrime(repunit(digits), 10)) {
            System.out.println("R(" + digits + ") is probably prime");
        } else {
            System.out.println("R(" + digits + ") is not prime");
        }
    }
 
    public static void main(String[] args) {
        BigInteger p = BigInteger.valueOf(2);
        System.out.println("First 19 circular primes:");
        for (int count = 0; count < 19; p = p.add(BigInteger.ONE)) {
            if (isCircularPrime(p)) {
                if (count > 0) {
                    System.out.print(", ");
                }
                System.out.print(p);
                ++count;
            }
        }
        System.out.println();
        System.out.println("Next 4 circular primes:");
        p = nextRepunit(p);
        String str = toString(p);
        int digits = str.length();
        for (int count = 0; count < 4; ) {
            if (isPrime(p, 15)) {
                if (count > 0) {
                    System.out.print(", ");
                }
                System.out.print("R(" + digits + ")");
                ++count;
            }
            p = repunit(++digits);
        }
        System.out.println();
        testRepunit(5003);
        testRepunit(9887);
        testRepunit(15073);
        testRepunit(25031);
        testRepunit(35317);
        testRepunit(49081);
    }
}

