import java.util.Stack;

public class Handler {
    public static void main(String[] args) {
        String content = "/* This is a multi-line comment\n" +
                "It spans multiple lines\n" +
                "And it's still open\n" +
                "*/\n" +
                "This is a line after the comment";
        int line = 4;
        System.out.println(commentLinesBefore(content, line));
    }

    private static boolean commentLinesBefore(String content, int line) {
        Stack<Character> commentStack = new Stack<>();
        String[] lines = content.split("\n");
        for (int i = 0; i < line; i++) {
            String lineContent = lines[i];
            for (char c : lineContent.toCharArray()) {
                if (c == '/' && !commentStack.isEmpty() && commentStack.peek() == '*') {
                    commentStack.pop();
                } else if (c == '*' && !commentStack.isEmpty() && commentStack.peek() == '/') {
                    commentStack.pop();
                } else {
                    commentStack.push(c);
                }
            }
            if (!commentStack.isEmpty()) {
                return true;
            }
        }
        return false;
    }
}

