        dn = dn.next;
        while (dn != null) {
            discAL.add(dn.disc);
            dn = dn.next;
        }
        if (TraceComponent.isAnyTracingEnabled() && tc.isEntryEnabled()) {
            Tr.exit(tc, "rebuildDiscriminatorList");
        }
    }

