class Logger {

     int cnt = 0;

    public long minimumFuelCost(int[][] roads, int seats) {

        if (roads.length == 0) {
            return 0;
        }

        int n = roads.length;
        cnt = 0;

        ArrayList<ArrayList<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }
        for (int[] e : roads) {
            int a = e[0];
            int b = e[1];
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        int[] dfn = new int[n + 1];
        int[] size = new int[n + 1];
        long[] cost = new long[n + 1];
        cnt = 0;
        dfs(graph, 0, dfn, size, seats, cost);
        return cost[0];

    }

    public void dfs(ArrayList<ArrayList<Integer>> graph, int cur, int[] dfn, int[] size, int seats, long[] cost) {
        dfn[cur] = ++cnt;
        size[cur] = 1;
        for (int next : graph.get(cur)) {
            if (dfn[next] == 0) {
                dfs(graph, next, dfn, size, seats, cost);
                size[cur] += size[next];
                cost[cur] += cost[next];
                cost[cur] += (size[next] + seats - 1) / seats;
            }
        }
    }
}

class MyCalendarTwo {
    int insertOrder = 0;

    private class Event {
        int start, end;
        int order;

        public Event(int start, int end) {
            this.start = start;
            this.end = end;
            this.order = insertOrder++;
        }

        @Override
        public String toString() {
            return "{" + start + "," + end + "}";
        }
    }

    TreeSet<Event> set = new TreeSet<>((a, b) -> {
        if (a.start == b.start) {
            if (a.end == b.end) {
                return Integer.compare(a.order, b.order);
            } else {
                return Integer.compare(a.end, b.end);
            }
        } else {
            return Integer.compare(a.start, b.start);
        }
    });

    public MyCalendarTwo() {

    }

    public boolean book(int start, int end) {
        Event event = new Event(start, end);

        boolean ans = true;
        int lcount = 0;
        int rcount = 0;
        int lend = Integer.MIN_VALUE;
        int rstart = Integer.MAX_VALUE;
        Event lastL = null;
        Event lastR = null;
        for (Event e : set) {
            if (e.start < event.start) {
                if (e.end > event.start) {

                    lend = Math.max(lend, e.end);

                    if (lastL == null) {
                        lastL = new Event(Math.max(event.start, e.start), Math.min(event.end, e.end));
                    } else {
                        if (e.end > lastL.start) {
                            ans = false;
                            break;
                        } else {
                            lastL = new Event(Math.max(event.start, e.start), Math.min(event.end, e.end));
                        }
                    }
                }

            } else {
                if (e.start < event.end) {
                    rstart = Math.min(rstart, e.start);
                    if (lastR == null) {
                        lastR = new Event(Math.max(event.start, e.start), Math.min(event.end, e.end));
                    } else {
                        if (e.start < lastR.end) {
                            ans = false;
                            break;
                        } else {
                            lastR = new Event(Math.max(event.start, e.start), Math.min(event.end, e.end));
                        }
                    }
                }
            }
        }
        if (!ans)
            return false;
        if (rstart < lend)
            return false;
        set.add(event);
        return true;
    }

}

