public class HTTPResourceProvider {
    private ReentrantLock lock;
    private long lockTimeout;
    private long clientTimeout;
    private long socketTimeout;
    private String[] arguments;

    public HTTPResourceProvider(long lockTimeout, long clientTimeout, long socketTimeout, String[] arguments) {
        this.lock = new ReentrantLock();
        this.lockTimeout = lockTimeout;
        this.clientTimeout = clientTimeout;
        this.socketTimeout = socketTimeout;
        this.arguments = arguments;
    }

    public void init() {
        // Initialize settings based on arguments, if necessary
        System.out.println("Initializing HTTP Resource Provider with custom settings.");
        for (String arg : arguments) {
            System.out.println("Argument: " + arg);
        }
    }

    public Resource getResource(String path) throws Exception {
        if (!lock.tryLock()) {
            throw new IllegalStateException("Resource is locked, cannot access: " + path);
        }
        try {
            long startTime = System.currentTimeMillis();
            URL url = new URL(encodeUrl(path));
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setConnectTimeout((int) clientTimeout);
            connection.setReadTimeout((int) socketTimeout);

            if (connection.getResponseCode() != HttpURLConnection.HTTP_OK) {
                throw new RuntimeException("Failed to fetch resource, HTTP code: " + connection.getResponseCode());
            }

            System.out.println("Successfully retrieved resource from: " + path);
            return ResourceUtils.createResource(connection.getInputStream(), path);
        } finally {
            unlock();
        }
    }

    private String encodeUrl(String path) {
        try {
            return java.net.URLEncoder.encode(path, "UTF-8");
        } catch (Exception e) {
            throw new RuntimeException("Failed to encode URL: " + path, e);
        }
    }

