        try {
            if (!lock.tryLock()) {
                throw new RuntimeException("Resource is already locked.");
            }
            System.out.println("Resource locked.");
        } catch (Exception e) {

import java.util.Scanner;

public class SimpleCalculator {
    /**
     * A basic console calculator supporting +, -, *, /.
     */
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter first number: ");
        double first = scanner.nextDouble();
        System.out.print("Enter operator (+, -, *, /): ");
        char operator = scanner.next().charAt(0);
        System.out.print("Enter second number: ");
        double second = scanner.nextDouble();

        double result;
        switch (operator) {
            case '+':
                result = first + second;
                break;
            case '-':
                result = first - second;
                break;
            case '*':
                result = first * second;
                break;
            case '/':
                if (second == 0) {
                    System.out.println("Cannot divide by zero");
                    scanner.close();
                    return;
                }
                result = first / second;
                break;
            default:
                System.out.println("Unknown operator");
                scanner.close();
                return;
        }

        System.out.println("Result: " + result);
        scanner.close();
    }
}

import java.util.Arrays;
import java.util.Comparator;

public class StringSorter {
    public static void main(String[] args) {
        String[] words = {"banana", "Apple", "cherry", "date", "Elderberry"};

        // Sort ignoring case
        Arrays.sort(words, String.CASE_INSENSITIVE_ORDER);
        System.out.println("Case-insensitive: " + Arrays.toString(words));

        // Sort by length using a comparator
        Arrays.sort(words, Comparator.comparingInt(String::length));
        System.out.println("By length: " + Arrays.toString(words));
    }
}

