            System.out.print("Enter the RMB amount: ");
            double rmb = input.nextDouble();
            double dollars = rmb / rate;
            System.out.println(rmb + " yuan is $" + dollars + ".");
        } else {
            System.out.println("Invalid input.");
        }
    }
