public class Array_balancing

{

    public static void main(String[] args)

    {

        Scanner Scanf=new Scanner(System.in);

        int t=Scanf.nextInt();

        for(int i=0;i<t;i++)

        {

            int n=Scanf.nextInt();

            long  data[]=new long[n];

            for(int j=0;j<n;j++)

            {

                data[j]=Scanf.nextLong();

            }

            long data2[]=new long[n];

            for(int j=0;j<n;j++)

            {

                data2[j]=Scanf.nextLong();

            }

            long sum=0;

            long sum1=0;

            for(int j=0;j<n;j++)

            {

                if(data[j]<data2[j])

                {

                    long temp=data[j];

                    data[j]=data2[j];

                    data2[j]=temp;

                }

            }

            for(int j=0;j<n-1;j++)

            {

                sum=sum+abs(abs(data[j]-data[j+1]));

                sum1=sum1+abs(abs(data2[j]-data2[j+1]));

            }

            System.out.println(sum+sum1);

            sum=0;

            sum1=0;

        }

    }

}

