import java.util.ArrayList;
import java.util.Scanner;

public class Game {
    public static void main(String[] args) {
        ArrayList<Integer> guesses = new ArrayList<>();

        Scanner input = new Scanner(System.in);

        int number1 = (int) (Math.random() * 10);
        int number2 = (int) (Math.random() * 10);

        System.out.print("What is " + number1 + " + " + number2 + "? ");
        int answer = input.nextInt();

        while (answer != number1 + number2) {

            if (guesses.contains(answer)) {
                System.out.println("You've already entered " + answer);
                System.out.print("Try again. What is " + number1 + " + " + number2 + "? ");
                answer = input.nextInt();

            } else {
                guesses.add(answer);
                System.out.print("Wrong answer. Try again. What is " + number1 + " + " + number2 + "? ");
                answer = input.nextInt();
            }

        }

        input.close();
        System.out.println("You got it!");
    }

}

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.Maps;
import com.google.template.soy.data.SoyRecord;
import com.google.template.soy.data.SoyValueProvider;
import java.util.Map;

/**
 * A layered parameter store.
 *
 * <p>Important: Do not use outside of Soy code (treat as superpackage-private).
 */
final class AugmentedParamStore implements SoyRecord {

  private final SoyRecord backingStore;
  private final Map<String, SoyValueProvider> localStore;

  AugmentedParamStore(int numParams, SoyRecord base) {
    this.backingStore = base;
    this.localStore = Maps.newHashMapWithExpectedSize(numParams);
  }

  @Override
  public boolean hasField(String name) {
    return localStore.containsKey(name) || (backingStore != null && backingStore.hasField(name));
  }

  @Override
  public SoyValueProvider getFieldProvider(String name) {
    SoyValueProvider provider = localStore.get(name);
    if (provider != null) {
      return provider;
    }
    if (backingStore != null) {
      return backingStore.getFieldProvider(name);
    }
    return null;
  }

  /**
   * Important: Do not use outside of Soy code (treat as superpackage-private).
   *
   * <p>Sets a field.
   *
   * @param name The name of the field.
   * @param value The field value.
   */
  public void setField(String name, SoyValueProvider value) {
    Preconditions.checkNotNull(value);
    localStore.put(name, value);
  }

  @Override
  public ImmutableMap<String, SoyValueProvider> recordAsMap() {
    ImmutableMap.Builder<String, SoyValueProvider> builder = ImmutableMap.builder();
    if (backingStore != null) {
      builder.putAll(backingStore.recordAsMap());
    }
    builder.putAll(localStore);
    return builder.build();
  }
}

