import java.util.ArrayList;
import java.util.List;
 
public class Birthday {
 
    public enum Month {
        MAY, JUNE, JULY, AUGUST
    }
 
    public static class Birthday {
        public Month month;
        public int day;
 
        public Birthday(Month month, int day) {
            this.month = month;
            this.day = day;
        }
 
        public boolean monthUniqueIn(List<Birthday> birthdays) {
            return birthdays.stream().filter(birthday -> birthday.month == this.month).count() == 1;
        }
 
        public boolean dayUniqueIn(List<Birthday> birthdays) {
            return birthdays.stream().filter(birthday -> birthday.day == this.day).count() == 1;
        }
 
        public boolean monthWithUniqueDayIn(List<Birthday> birthdays) {
            return birthdays.stream().anyMatch(birthday -> this.month == birthday.month && birthday.dayUniqueIn(birthdays));
        }
 
        @Override
        public String toString() {
            return "Birthday{" +
                    "month=" + month +
                    ", day=" + day +
                    '}';
        }
    }
 
    public static Birthday solution() {
        List<Birthday> choices = new ArrayList<>();
        choices.add(new Birthday(Month.MAY, 15));
        choices.add(new Birthday(Month.MAY, 16));
        choices.add(new Birthday(Month.MAY, 19));
        choices.add(new Birthday(Month.JUNE, 17));
        choices.add(new Birthday(Month.JUNE, 18));
        choices.add(new Birthday(Month.JULY, 14));
        choices.add(new Birthday(Month.JULY, 16));
        choices.add(new Birthday(Month.AUGUST, 14));
        choices.add(new Birthday(Month.AUGUST, 15));
        choices.add(new Birthday(Month.AUGUST, 17));
 
        // Albert knows the month but doesn't know the day.
        // So the month can't be unique within the choices.
        List<Birthday> choicesCopy = new ArrayList<>(choices);
        choices.removeIf(birthday -> birthday.monthUniqueIn(choicesCopy));
 
        // Albert also knows that Bernard doesn't know the answer.
        // So the month can't have a unique day.
        choicesCopy = new ArrayList<>(choices);
        choices.removeIf(birthday -> birthday.monthWithUniqueDayIn(choicesCopy));
 
        // Bernard now knows the answer.
        // So the day must be unique within the remaining choices.
        choicesCopy = new ArrayList<>(choices);
        choices.removeIf(birthday ->!birthday.dayUniqueIn(choicesCopy));
 
        // Albert now knows the answer too.
        // So the month must be unique within the remaining choices.

