import com.google.common.collect.Sets;
import org.hisp.dhis.common.ValueType;
import org.hisp.dhis.commons.filter.Filter;
import org.hisp.dhis.dataelement.DataElement;

import java.util.Set;

/**
 */
public class AggregatableDataElementFilter
    implements Filter<DataElement>
{
    public static final AggregatableDataElementFilter INSTANCE = new AggregatableDataElementFilter();

    private static final Set<ValueType> VALUE_TYPES = Sets.newHashSet(
        ValueType.BOOLEAN, ValueType.TRUE_ONLY, ValueType.TEXT, ValueType.LONG_TEXT, ValueType.LETTER,
        ValueType.INTEGER, ValueType.INTEGER_POSITIVE, ValueType.INTEGER_NEGATIVE, ValueType.INTEGER_ZERO_OR_POSITIVE,
        ValueType.NUMBER, ValueType.UNIT_INTERVAL, ValueType.PERCENTAGE, ValueType.COORDINATE
    );

    @Override
    public boolean retain( DataElement object )
    {
        return object != null && VALUE_TYPES.contains( object.getValueType() );
    }
}

public class ShortVeriTuruOrnegi {

    public static void main(String[] args) {

        // iki short degeri ile temel islemler yapiliyor
        short a = 300;
        short b = 500;

        // short + short sonucu int'e genisledigi icin geri cast ediyoruz
        short toplamSonuc = (short) (a + b);
        System.out.println("Toplam: " + toplamSonuc);

        short farkSonuc = (short) (b - a);
        System.out.println("Fark: " + farkSonuc);

        short carpimSonuc = (short) (a * b);
        System.out.println("Carpim: " + carpimSonuc);

        short bolumSonuc = (short) (b / a);
        System.out.println("Bolum: " + bolumSonuc);

        short kalanSonuc = (short) (b % a);
        System.out.println("Kalan: " + kalanSonuc);

        // Bir arttirma ve bir azaltma ornegi
        short arttirilmisA = (short) (a + 1);
        short azaltilmisB = (short) (b - 1);

        System.out.println("Arttirilmis Sayi1: " + arttirilmisA);
        System.out.println("Azaltilmis Sayi2: " + azaltilmisB);

        // Pozitif/negatif kontrolu
        String isaret = (a > 0) ? "pozitif bir degerdir." : "negatif bir degerdir.";
        System.out.println("Sayi1 " + isaret);

        // short turunun sinir degerleri
        System.out.println("\nShort veri turunun minimum degeri: " + Short.MIN_VALUE);
        System.out.println("Short veri turunun maksimum degeri: " + Short.MAX_VALUE);

        short ustSinir = Short.MAX_VALUE;
        short altSinir = Short.MIN_VALUE;

        // Sinir degerleri arasindaki farkin hesaplanmasi
        short sinirFarki = (short) (ustSinir - altSinir);
        System.out.println("Short veri turunun max ve min degeri arasindaki fark: " + sinirFarki);

        // Ek bir toplama ornegi daha
        short c = 1500;
        short d = 1200;
        short sonToplam = (short) (c + d);
        System.out.println("Yeni toplam: " + sonToplam);
    }
}

import java.util.Scanner;
import java.util.Random;

public class ScissorRockPaper {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        Random rand = new Random();

        // Generate a random number for the computer's choice
        int computerChoice = rand.nextInt(3);

        // Prompt the user to enter their choice
        System.out.print("Enter 0 for scissor, 1 for rock, or 2 for paper: ");
        int userChoice = input.nextInt();

        // Determine the winner
        if (userChoice == computerChoice) {
            System.out.println("It's a draw!");
        } else if (userChoice == 0 && computerChoice == 2 ||
                   userChoice == 1 && computerChoice == 0 ||
                   userChoice == 2 && computerChoice == 1) {
            System.out.println("You win!");
        } else {
            System.out.println("You lose!");
        }

        // Display the computer's choice
        switch (computerChoice) {
            case 0:
                System.out.println("Computer chose scissor.");
                break;
            case 1:
                System.out.println("Computer chose rock.");
                break;
            case 2:
                System.out.println("Computer chose paper.");
                break;
            default:
                System.out.println("Invalid choice.");
        }
    }
}

import java.math.BigInteger;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.List;
 
public class PierpontPrimes {
 
    public static void main(String[] args) {
        NumberFormat nf = NumberFormat.getNumberInstance();
        display("First 50 Pierpont primes of the first kind:", pierpontPrimes(50, true));
        display("First 50 Pierpont primes of the second kind:", pierpontPrimes(50, false));
        System.out.printf("250th Pierpont prime of the first kind:     %s%n%n", nf.format(pierpontPrimes(250, true).get(249)));
        System.out.printf("250th Pierpont prime of the second kind: %s%n%n", nf.format(pierpontPrimes(250, false).get(249)));
    }
 
    private static void display(String message, List<BigInteger> primes) {
        NumberFormat nf = NumberFormat.getNumberInstance();
        System.out.printf("%s%n", message);
        for ( int i = 1 ; i <= primes.size() ; i++ ) {
            System.out.printf("%10s  ", nf.format(primes.get(i-1)));
            if ( i % 10 == 0 ) {
                System.out.printf("%n");
            }
        }
        System.out.printf("%n");
    }
 
    public static List<BigInteger> pierpontPrimes(int n, boolean first) {
        List<BigInteger> primes = new ArrayList<BigInteger>();
        if ( first ) {
            primes.add(BigInteger.valueOf(2));
            n -= 1;
        }
 
        BigInteger two = BigInteger.valueOf(2);
        BigInteger twoTest = two;
        BigInteger three = BigInteger.valueOf(3);
        BigInteger threeTest = three;
        int twoIndex = 0, threeIndex = 0;
        List<BigInteger> twoSmooth = new ArrayList<BigInteger>();
 
        BigInteger one = BigInteger.ONE;
        BigInteger mOne = BigInteger.valueOf(-1);
        int count = 0;
        while ( count < n ) {
            BigInteger min = twoTest.min(threeTest);
            twoSmooth.add(min);
            if ( min.compareTo(twoTest) == 0 ) {
                twoTest = two.multiply(twoSmooth.get(twoIndex));
                twoIndex++;
            }
            if ( min.compareTo(threeTest) == 0 ) {
                threeTest = three.multiply(twoSmooth.get(threeIndex));
                threeIndex++;
            }
            BigInteger test = min.add(first ? one : mOne);
            if ( test.isProbablePrime(10) ) {
                primes.add(test);
                count++;
            }
        }
        return primes;
    }
 
}

import java.util.Scanner;

public class SmallestFactors {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt the user to enter an integer
        System.out.print("Enter an integer: ");
        int number = input.nextInt();

        // Find and display the smallest factors
        System.out.print("The smallest factors of " + number + " are: ");
        int factor = 2;
        while (factor <= number) {
            if (number % factor == 0) {
                System.out.print(factor + " ");
                number /= factor;
            } else {
                factor++;
            }
        }
    }
}

