public static List<Integer> oneHundredDoors() {
    boolean[] doors = new boolean[100];
    for (int i = 0; i < 100; i++) {
        for (int j = i; j < 100; j += i + 1) {
            doors[j] =!doors[j];
        }
    }
    List<Integer> result = new ArrayList<>();
    for (int i = 0; i < 100; i++) {
        if (doors[i]) {
            result.add(i + 1);
        }
    }
    return result;
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
 
public class Solution {
 
    public static void main(String[] args) throws IOException {
        String[] dicts = new String[]{"mit_10000.txt", "unixdict.txt"}; // local copies
        for (String dict : dicts) {
            System.out.printf("Using %s:\n\n", dict);
            List<String> words = readWords(dict);
            int n = words.size();
            Map<String, Boolean> used = new HashMap<>();
            outer:
            for (String word : words) {
                char[] runes = word.toCharArray();
                List<String> variants = new ArrayList<>();
                variants.add(word);
                for (int i = 0; i < runes.length - 1; i++) {
                    rotate(runes);
                    String word2 = new String(runes);
                    if (word.equals(word2) || used.containsKey(word2)) {
                        continue outer;
                    }
                    int ix = Arrays.binarySearch(words.toArray(), word2);
                    if (ix == n ||!words.get(ix).equals(word2)) {
                        continue outer;
                    }
                    variants.add(word2);
                }
                for (String variant : variants) {
                    used.put(variant, true);
                }
                System.out.println(variants);
            }
            System.out.println();
        }
    }
 
    private static List<String> readWords(String fileName) throws IOException {
        List<String> words = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new FileReader(fileName))) {
            String line;
            while ((line = reader.readLine())!= null) {
                String word = line.toLowerCase().trim();
                if (word.length() >= 3) {
                    words.add(word);
                }
            }
        }
        return words;
    }
 
    private static void rotate(char[] runes) {
        char first = runes[0];
        System.arraycopy(runes, 1, runes, 0, runes.length - 1);
        runes[runes.length - 1] = first;
    }
}

class Graph {
  // m * n -> 1e4 So we can use n^2
  // A Rhombus is determined by top corner and length 0~x
  // All nums on the edge should be included
  static final int size = 3;
  public int[] getBiggestThree(int[][] grid) {
    int m = grid.length, n = grid[0].length;
    // int psum[][] = new int[m][n]
    TreeSet<Integer> heap = new TreeSet<>();

    // try use every grid as center, then try all length
    for(int i = 0; i < m; i++) for(int j = 0; j < n; j++) {
      // len 0
      heap.add(grid[i][j]);
      if(heap.size() > size) heap.pollFirst();

      for (int len = 1; len < Math.min(m, n); len++) {
        if(j - len < 0 || j + len >= n || i + 2 * len >= m) break;
        // System.out.println(grid[i][j] + grid[i + len][j - len] + grid[i + len][j + len] + grid[i + 2 * len][j]);
        // heap.add(grid[i][j] + grid[i + len][j - len] + grid[i + len][j + len] + grid[i + 2 * len][j]);

        heap.add(getSum(grid, i, j, len));
        if(heap.size() > size) heap.pollFirst();
      }
    }

    int res[] = new int[heap.size()];
    for (int i = heap.size() - 1; i >= 0; i--) res[i] = heap.pollFirst();
    return res;
  }

  private int getSum(int[][] grid, int x, int y, int len) {
    int res = 0;
    for (int i = x, j = y; i < x + len; i++, j--) res += grid[i][j];
    for (int i = x + len, j = y - len; i < x + 2 * len; i++, j++) res += grid[i][j];
    for (int i = x + 2 * len, j = y; i > x + len; i--, j++) res += grid[i][j];
    for (int i = x + len, j = y + len; i > x; i--, j--) res += grid[i][j];
    return res;
  }
}

import java.util.Scanner;

public class Vector {
    public static class vector {
        public double x;
        public double y;
        public double z;
    }

    public static vector a = new vector();
    public static vector b = new vector();
    public static vector c = new vector();

    public static double dot(vector a, vector b) {
        return a.x * b.x + a.y * b.y + a.z * b.z;
    }

    public static vector cross(vector a, vector b) {
        vector c = new vector();
        c.x = a.y * b.z - a.z * b.y;
        c.y = a.z * b.x - a.x * b.z;
        c.z = a.x * b.y - a.y * b.x;
        return c;
    }

    public static double s3(vector a, vector b, vector c) {
        return dot(a, cross(b, c));
    }

    public static vector v3(vector a, vector b, vector c) {
        return cross(a, cross(b, c));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        a.x = sc.nextDouble();
        a.y = sc.nextDouble();
        a.z = sc.nextDouble();
        b.x = sc.nextDouble();
        b.y = sc.nextDouble();
        b.z = sc.nextDouble();
        c.x = sc.nextDouble();
        c.y = sc.nextDouble();
        c.z = sc.nextDouble();
        System.out.println(dot(a, b));
        System.out.println(cross(a, b));
        System.out.println(s3(a, b, c));
        System.out.println(v3(a, b, c));
    }
}

import java.util.Arrays;
import java.util.HashSet;
 
public class VampireNumbers{
    private static int numDigits(long num){
        return Long.toString(Math.abs(num)).length();
    }
 
    private static boolean fangCheck(long orig, long fang1, long fang2){
        if(Long.toString(fang1).endsWith("0") && Long.toString(fang2).endsWith("0")) return false;
 
        int origLen = numDigits(orig);
        if(numDigits(fang1) != origLen / 2 || numDigits(fang2) != origLen / 2) return false;
 
        byte[] origBytes = Long.toString(orig).getBytes();
        byte[] fangBytes = (Long.toString(fang1) + Long.toString(fang2)).getBytes();
        Arrays.sort(origBytes);
        Arrays.sort(fangBytes);
        return Arrays.equals(origBytes, fangBytes);
    }
 
    public static void main(String[] args){
        HashSet<Long> vamps = new HashSet<Long>();
        for(long i = 10; vamps.size() <= 25; i++ ){
            if((numDigits(i) % 2) != 0) {i = i * 10 - 1; continue;}
            for(long fang1 = 2; fang1 <= Math.sqrt(i) + 1; fang1++){
                if(i % fang1 == 0){
                    long fang2 = i / fang1;
                    if(fangCheck(i, fang1, fang2) && fang1 <= fang2){
                        vamps.add(i);
                        System.out.println(i + ": [" + fang1 + ", " + fang2 +"]");
                    }
                }
            }
        }
        Long[] nums = {16758243290880L, 24959017348650L, 14593825548650L};
        for(Long i : nums){
            for(long fang1 = 2; fang1 <= Math.sqrt(i) + 1; fang1++){
                if(i % fang1 == 0){
                    long fang2 = i / fang1;
                    if(fangCheck(i, fang1, fang2) && fang1 <= fang2){
                        System.out.println(i + ": [" + fang1 + ", " + fang2 +"]");
                    }
                }
            }
        }
    }
}

 
import java.util.ArrayList;
import java.util.List;
 
public class Validator {
 
    public static int[] JosephusProblem(int n, int m) {
        List<Integer> circle = new ArrayList<Integer>();
        int[] order = new int[n];
 
        for (int i = 0; i < n; ++i) {
            circle.add(i);
        }
 
        int l = 0;
        int j = 0;
        int k = 0;
 
        while (circle.size()!= 0) {
            j++;
            if (j == m) {
                order[k] = circle.get(l);
                circle.remove(l);
 
                k++;
                l--;
                j = 0;
            }
 
            if (k == n - 1) {
                order[k] = circle.get(0);
                circle.remove(0);
            }
 
            if (l == circle.size() - 1) {
                l = 0;
            } else {
                l++;
            }
        }
 
        return order;
    }
 
    public static void main(String[] args) {
        try {
            int n = 7;
            int m = 2;
 
            int[] result = JosephusProblem(n, m);
 
            for (int i = 0; i < result.length; i++) {
                System.out.println(result[i]);//1 3 5 0 4 2 6
            }
        } catch (Exception e) {
            System.out.println(e);
        }
    }
}

import java.util.Collection;
import java.util.LinkedList;

import org.debian.alioth.shootout.u32.nbody.NBodySystem;

import com.tantaman.commons.concurrent.Parallel;

public class ParallelForDemo {
    public static void main(String[] args) {
        Collection<Integer> elems = new LinkedList<Integer>();
        for (int i = 0; i < 40; ++i) {
            elems.add(i*55000 + 100);
        }

        Parallel.For(elems, new Parallel.Operation<Integer>() {
            public void perform(Integer pParameter) {
                // do something with the parameter
            };
        });

        Parallel.Operation<Integer> bodiesOp = new Parallel.Operation<Integer>() {
            @Override
            public void perform(Integer pParameter) {
                NBodySystem bodies = new NBodySystem();
                for (int i = 0; i < pParameter; ++i)
                    bodies.advance(0.01);
            }
        };

        System.out.println("RUNNING THE Parallel.For vs Parallel.ForFJ performance comparison");
        System.out.println("This could take a while.");
        // warm up.. it really does have a large impact.
        Parallel.ForFJ(elems, bodiesOp);

        long start = System.currentTimeMillis();
        Parallel.For(elems, bodiesOp);
        long stop = System.currentTimeMillis();

        System.out.println("DELTA TIME VIA NORMAL PARALLEL FOR: " + (stop - start));

        start = System.currentTimeMillis();
        Parallel.ForFJ(elems, bodiesOp);
        stop = System.currentTimeMillis();

        System.out.println("DELTA TIME VIA FOR FORK JOIN: " + (stop - start));

        System.out.println("Finished");
    }
}

