import org.apache.log4j.Logger;
import org.hibernate.event.spi.PostDeleteEvent;
import org.hibernate.event.spi.PostDeleteEventListener;
import org.hibernate.Transaction;
import org.hibernate.Session;
import org.hibernate.engine.spi.SessionImplementor;

import java.lang.reflect.ParameterizedType;
import java.util.concurrent.CompletableFuture;

public class PostDeleteEventListenerImpl implements PostDeleteEventListener {

    private static final Logger log = Logger.getLogger(PostDeleteEventListenerImpl.class);
    private final HiveIndexer hiveIndexer;

    public PostDeleteEventListenerImpl(HiveIndexer hiveIndexer) {
        this.hiveIndexer = hiveIndexer;
    }

    @Override
    public void onPostDelete(PostDeleteEvent event) {
        Session session = event.getSession();
        Object entity = event.getEntity();
        Class<?> entityClass = resolveEntityClass(entity);

        Transaction tx = session.getTransaction();
        if (tx != null && tx.getStatus().isOneOf(Transaction.STATUS_COMMITTED)) {
            CompletableFuture.runAsync(() -> {
                try {
                    deleteIndexes(entityClass, entity);
                } catch (HiveLockableException e) {
                    log.warn("Failed to delete hive indexes due to locking issue", e);
                } catch (Exception e) {
                    log.error("Failed to delete hive indexes", e);
                }
            });
        }
    }

    private Class<?> resolveEntityClass(Object entity) {
        Class<?> clazz = entity.getClass();
        if (clazz.getGenericSuperclass() instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) clazz.getGenericSuperclass();
            return (Class<?>) parameterizedType.getActualTypeArguments()[0];
        }
        return clazz;
    }

    private void deleteIndexes(Class<?> entityClass, Object entity) throws HiveLockableException {
        EntityHiveConfig config = EntityHiveConfig.getConfigForEntity(entityClass);
        if (config != null) {
            String indexName = config.getIndexName();
            hiveIndexer.deleteIndex(indexName, entity);
        } else {
            log.warn("No hive configuration found for entity class: " + entityClass.getName());
        }
    }

    @Override
    public boolean requiresPostCommitHanding(EntityPersister persister) {
        return true;
    }
}

