        // Logic to delete the index from Hive

public ClassFile addInnerClass(String innerClassName,
                                   String superClassName) {
        String fullInnerClassName;
        if (innerClassName == null) {
            fullInnerClassName =
                mClassName + '$' + (++mAnonymousInnerClassCount);
        }
        else {
            fullInnerClassName = mClassName + '$' + innerClassName;
        }
        ClassFile inner = new ClassFile(fullInnerClassName, superClassName);
        Modifiers access = inner.getModifiers();
        access.setPrivate(true);
        access.setStatic(true);
        inner.mInnerClassName = innerClassName;
        inner.mOuterClass = this;
        if (mInnerClasses == null) {
            mInnerClasses = new ArrayList<ClassFile>();
        }
        mInnerClasses.add(inner);

        if (mInnerClassesAttr == null) {
            addAttribute(new InnerClassesAttr(mCp));
        }
        mInnerClassesAttr.addInnerClass(fullInnerClassName, mClassName,
                                        innerClassName, access);

        inner.addAttribute(new InnerClassesAttr(inner.getConstantPool()));
        inner.mInnerClassesAttr.addInnerClass(fullInnerClassName, mClassName,
                                              innerClassName, access);
        return inner;
    }

import org.apache.zookeeper.CreateMode;
import org.apache.zookeeper.KeeperException;
import org.apache.zookeeper.ZooDefs;
import org.apache.zookeeper.ZooKeeper;
import org.apache.zookeeper.data.ACL;
import java.io.UnsupportedEncodingException;
import java.util.List;

public class CreateOperation extends ZooKeeperOperation<String> {
    private static final List<ACL> DEFAULT_PERMISSIONS = ZooDefs.Ids.OPEN_ACL_UNSAFE;
    private static final CreateMode DEFAULT_MODE = CreateMode.EPHEMERAL;

    private String path;
    private byte[] data;
    private List<ACL> permissions = DEFAULT_PERMISSIONS;
    private CreateMode createMode = DEFAULT_MODE;

    @Override
    public String getResult() throws Exception {
        validateParameters();
        ZooKeeper zk = getConnection();
        try {
            String createdPath = zk.create(path, data, permissions, createMode);
            return createdPath;
        } catch (KeeperException e) {
            throw new Exception("ZK node creation failed: " + e.code() +
                " - " + e.getMessage(), e);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new Exception("Node creation interrupted for '" + path + "'", e);
        }
    }

    private void validateParameters() {
        if (path == null || path.trim().isEmpty()) {
            throw new IllegalArgumentException("Node path must be specified");
        }
        if (data == null) {
            data = new byte[0];
        }
    }

    public void setPath(String path) {
        if (path == null || path.trim().isEmpty()) {
            throw new IllegalArgumentException("Path cannot be null/empty");
        }
        this.path = path;
    }

    public void setData(byte[] data) {
        this.data = data;
    }

    public void setData(String data, String charset) throws UnsupportedEncodingException {
        this.data = (data != null) ? data.getBytes(charset) : new byte[0];
    }

    public void setPermissions(List<ACL> permissions) {
        this.permissions = (permissions != null && !permissions.isEmpty())
            ? permissions
            : DEFAULT_PERMISSIONS;
    }

    public void setCreateMode(CreateMode createMode) {
