import com.google.common.base.Joiner;
import com.google.common.collect.Iterators;
import eu.the5zig.mod.MinecraftFactory;
import eu.the5zig.mod.chat.Chat;
import eu.the5zig.util.minecraft.ChatColor;

import java.util.Arrays;
import java.util.Iterator;
import java.util.List;

public class ColorCommandHandler {

    private static final List<ChatColor> RAINBOW = Arrays.asList(ChatColor.RED, ChatColor.GOLD, ChatColor.YELLOW, ChatColor.GREEN, ChatColor.AQUA, ChatColor.BLUE, ChatColor.DARK_PURPLE);
    private static final Iterator<ChatColor> RAINBOW_IT = Iterators.cycle(RAINBOW);

    public void run(String[] args) {
        if (args.length == 0) {
            printUsage();
        } else {
            String message = Joiner.on(" ").join(Arrays.copyOfRange(args, 0, args.length));
            StringBuilder coloredMessage = new StringBuilder();
            for (char c : message.toCharArray()) {
                if (c == ' ') {
                    coloredMessage.append(c);
                } else {
                    coloredMessage.append(RAINBOW_IT.next()).append(c);
                }
            }
            Chat.sendMessage(coloredMessage.toString());
        }
    }

    private void printUsage() {
        Chat.sendMessage(ChatColor.YELLOW + "Available Color Codes:");
        for (ChatColor color : ChatColor.values()) {
            Chat.sendMessage(color + color.name() + ChatColor.WHITE + " = " + color + "Example");
        }
    }

    public List<String> getAliases() {
        return Arrays.asList("color", "colour");
    }
}

import org.bouncycastle.cert.X509CertificateHolder;
import org.bouncycastle.cert.jcajce.JcaX509CertificateConverter;
import org.bouncycastle.crypto.params.AsymmetricKeyParameter;
import org.bouncycastle.crypto.util.PrivateKeyFactory;
import org.bouncycastle.crypto.util.PublicKeyFactory;
import org.bouncycastle.openssl.PEMKeyPair;
import org.bouncycastle.openssl.PEMParser;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.cert.CertificateException;
import java.security.cert.X509Certificate;

public final class CertificateAuthority {
    private final X509CertificateHolder certificate;
    private final X509Certificate jcaCertificate;
    private final AsymmetricKeyParameter publicKey;
    private final AsymmetricKeyParameter privateKey;

    public CertificateAuthority(Path certificateFile, Path keyFile) throws IOException, CertificateException {
        try (PEMParser parser = new PEMParser(Files.newBufferedReader(certificateFile, StandardCharsets.UTF_8))) {
            Object object = parser.readObject();
            if (!(object instanceof X509CertificateHolder))
                throw new IOException("Failed to read CA certificate file");

            certificate = (X509CertificateHolder) object;
            jcaCertificate = new JcaX509CertificateConverter().getCertificate(certificate);
        }

        try (PEMParser parser = new PEMParser(Files.newBufferedReader(keyFile, StandardCharsets.UTF_8))) {
            Object object = parser.readObject();
            if (!(object instanceof PEMKeyPair))
                throw new IOException("Failed to read CA key file");

            PEMKeyPair pair = (PEMKeyPair) object;
            publicKey = PublicKeyFactory.createKey(pair.getPublicKeyInfo());
            privateKey = PrivateKeyFactory.createKey(pair.getPrivateKeyInfo());
        }
    }

    public X509CertificateHolder getCertificate() {
        return certificate;
    }

    public X509Certificate getJcaCertificate() {
        return jcaCertificate;
    }

    public AsymmetricKeyParameter getPublicKey() {
        return publicKey;
    }

    public AsymmetricKeyParameter getPrivateKey() {
        return privateKey;
    }
}

