public String longestCommonSuffix(String other) {
    int i = 0;
    while (i < this.length() && i < other.length() && this.charAt(this.length() - 1 - i) == other.charAt(other.length() - 1 - i)) {
        i++;
    }
    return this.substring(this.length() - i);
}

/**
 * A simple car model.
 */
public class Car {
    private String colour;
    private int enginePower;
    private boolean convertible;
    private boolean parkingBrake;

    public Car() {
    }

    public Car(String colour, int enginePower, boolean convertible, boolean parkingBrake) {
        this.colour = colour;
        this.enginePower = enginePower;
        this.convertible = convertible;
        this.parkingBrake = parkingBrake;
    }

    public String getColour() {
        return colour;
    }

    public void setColour(String colour) {
        this.colour = colour;
    }

    public int getEnginePower() {
        return enginePower;
    }

    public void setEnginePower(int enginePower) {
        this.enginePower = enginePower;
    }

    public boolean isConvertible() {
        return convertible;
    }

    public void setConvertible(boolean convertible) {
        this.convertible = convertible;
    }

    public boolean isParkingBrake() {
        return parkingBrake;
    }

    public void setParkingBrake(boolean parkingBrake) {
        this.parkingBrake = parkingBrake;
    }

    public void pressStartButton() {
        System.out.println("You have pressed the start button");
    }

    public void pressAcceleratorButton() {
        System.out.println("You have pressed the accelerator button");
    }

    public void output() {
        System.out.println("Colour: " + colour);
        System.out.println("EnginePower: " + enginePower);
        // mirrors the original's bug: prints enginePower instead of convertible
        System.out.println("Convertible: " + enginePower);
        System.out.println("ParkingBrake: " + parkingBrake);
    }

    @Override
    public String toString() {
        return "Car{colour=" + colour + ", enginePower=" + enginePower + ", convertible=" + convertible + ", parkingBrake=" + parkingBrake + '}';
    }
}

private static double[] toDoubleAray(Integer[] intArray, HashSet<Integer> skipIndex) {
    double[] res = new double[intArray.length - skipIndex.size()];
    int skip = 0;
    for (int i = 0; i < intArray.length; i++) {
      if (skipIndex.contains(i)) {
        skip++;
        continue;
      }
      res[i - skip] = intArray[i].doubleValue();
    }
    return res;
  }

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class SimpleThreadPoolDemo {
    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(3);

        for (int i = 1; i <= 6; i++) {
            final int taskId = i;
            executor.submit(() -> {
                String threadName = Thread.currentThread().getName();
                System.out.println("Task " + taskId + " running on " + threadName);
            });
        }

        executor.shutdown();
        executor.awaitTermination(5, TimeUnit.SECONDS);
        System.out.println("All tasks completed.");
    }
}

