public class Account {
    public boolean stoneGameIX(int[] stones) {
        int[] count = new int[3];
        // Count the number of stones that have a remainder of 0, 1, or 2 when divided by 3.
        for (int stone : stones) {
            count[stone % 3]++;
        }

        // If both Alice and Bob can take stones that will not result in losing, and Alice's turn is first, she can always win.
        if (count[0] % 2 == 0) {
            return count[1] > 0 && count[2] > 0;
        }

        // If Alice is not able to take a stone that leaves Bob with no option but to lose, she cannot win.
        return Math.abs(count[1] - count[2]) > 2;
    }
}

