import java.io.File;
import java.util.Scanner;

public class FileCount {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a directory: ");
        String directoryPath = input.nextLine();
        File directory = new File(directoryPath);
        int fileCount = countFiles(directory);
        System.out.println("The directory " + directoryPath + " contains " + fileCount + " files.");
    }

    public static int countFiles(File directory) {
        int count = 0;
        File[] files = directory.listFiles();
        if (files != null) {
            // Count the files in the current directory
            for (File file : files) {
                if (file.isFile()) {
                    count++;
                }
            }
            // Recursively count the files in the subdirectories
            for (File subdir : files) {
                if (subdir.isDirectory()) {
                    count += countFiles(subdir);
                }
            }
        }
        return count;
    }
}

import java.util.Scanner;

public class IdealKiloHesaplayici {

    public static void main(String[] args) {

        Scanner okuyucu = new Scanner(System.in);

        System.out.print("Boyunuzu metre cinsinden giriniz: ");
        double boyMetre = okuyucu.nextDouble();
        okuyucu.close();

        // 1.5 metre esik degeri kabul edilerek ideal kilo hesaplaniyor
        double esikBoy = 1.5;
        double katsayi = 90;
        double tabanKilo = 50;

        double sonucKilo = (boyMetre > esikBoy)
                ? tabanKilo + (boyMetre - esikBoy) * katsayi
                : tabanKilo;

        System.out.println("Ideal kilonuz: " + sonucKilo + " kilogram");
    }
}

