private void decodePublicationsFile(TLVInputStream input) throws KSIException, IOException {
        while (input.hasNextElement()) {
            TLVElement element = input.readElement();
            switch (element.getType()) {
                case PublicationsFileHeader.ELEMENT_TYPE:
                    if (header != null) {
                        throw new InvalidPublicationsFileException("Publications file contains multiple header components");
                    }
                    this.header = new PublicationsFileHeader(element);
                    break;
                case InMemoryCertificateRecord.ELEMENT_TYPE:
                    certificateRecords.add(new InMemoryCertificateRecord(element));
                    break;
                case PublicationsFilePublicationRecord.ELEMENT_TYPE:
                    publicationRecords.add(new PublicationsFilePublicationRecord(element));
                    break;
                case ELEMENT_TYPE_CMS_SIGNATURE:
                    cmsSignature = element.getContent();
                    break;
                default:
                    throw new InvalidPublicationsFileException("Invalid publications file element type=0x" + Integer.toHexString(element.getType()));
            }
            verifyElementOrder(element);
            elements.add(element);
        }
    }

public int maxAbsValExpr(int[] arr1, int[] arr2) {
        int min1 = arr1[0], min2 = arr2[0];
        int max1 = arr1[0], max2 = arr2[0];

        int result = 0;
        for(int i = 0; i<arr1.length;i++){
            min1 = Math.min(arr1[i] + arr2[i] , min1);
            min2 = Math.min(arr1[i] - arr2[i] , min2);
            max1 = Math.max(arr1[i] - arr2[i] , max1);
            max2 = Math.max(arr1[i] + arr2[i] , max2);

            result = Math.max(Math.max(Math.abs(max1 - arr1[i] + arr2[i] - min1), Math.abs(max2 - arr1[i] - arr2[i] - min2)),
                     Math.max(Math.abs(max1 - arr1[i] - arr2[i] - min1), Math.abs(max2 - arr1[i] + arr2[i] - min2)));

        }
        return result;
    }
}

static public String doubleToString(double d) {
    if (Double.isInfinite(d) || Double.isNaN(d)) {
      return "null";
    }

    String s = Double.toString(d);
    if (s.indexOf('.') > 0 && s.indexOf('e') < 0 && s.indexOf('E') < 0) {
      while (s.endsWith("0")) {
        s = s.substring(0, s.length() - 1);
      }
      if (s.endsWith(".")) {
        s = s.substring(0, s.length() - 1);
      }
    }
    return s;
  }

public class HTML {
 
    public static String array2HTML(Object[][] array){
        StringBuilder html = new StringBuilder(
                "<table>");
        for(Object elem:array[0]){
            html.append("<th>" + elem.toString() + "</th>");
        }
        for(int i = 1; i < array.length; i++){
            Object[] row = array[i];
            html.append("<tr>");
            for(Object elem:row){
                html.append("<td>" + elem.toString() + "</td>");
            }
            html.append("</tr>");
        }
        html.append("</table>");
        return html.toString();
    }
 
    public static void main(String[] args){
        Object[][] ints = {{"","X","Y","Z"},{1,1,2,3},{2,4,5,6},{3,7,8,9},{4,10,11,12}};
        System.out.println(array2HTML(ints));
    }
}

import java.util.HashSet;
import java.util.Random;
import java.util.Set;
 
public class AverageLoopLength {
 
    public static void main(String[] args) {
        int maxN = 20;
        int trials = 1000;
 
        if (args.length == 2) {
            maxN = Integer.parseInt(args[0]);
            trials = Integer.parseInt(args[1]);
        }
 
        System.out.println(" N    average    analytical    (error)");
        System.out.println("===  =========  ============  =========");
        for (int n = 1; n <= maxN; n++) {
            double theAnalytical = analytical(n);
            double theEmpirical = empirical(n, trials);
            System.out.printf("%3d  %9.4f  %12.4f  (%+6.2f%%)\n",
                    n,
                    theEmpirical,
                    theAnalytical,
                    100 * (theEmpirical / theAnalytical - 1));
        }
    }
 
    private static double factorial(int n) {
        double result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        return result;
    }
 
    private static double analytical(int n) {
        double sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += factorial(n) / Math.pow(n, i) / factorial(n - i);
        }
        return sum;
    }
 
    private static double empirical(int n, int trials) {
        double sum = 0;
        Random random = new Random();
        for (int t = 0; t < trials; t++) {
            int item = 1;
            Set<Integer> seen = new HashSet<>();
            for (int step = 0; step < n; step++) {
                if (seen.contains(item)) {
                    sum += step;
                    break;
                }
                seen.add(item);
                item = random.nextInt(n) + 1;
            }
            if (item!= 1) {
                sum += n;
            }
        }
        return sum / trials;
    }
}

