/**
 */
public final class CacheSynchronization implements Synchronization {

    private static final Log log = LogFactory.getLog(CacheSynchronization.class);

    private final TransactionFactory.Context ctx;
    private JDBCContext jdbcContext;
    private final Transaction transaction;
    private final org.hibernate.Transaction hibernateTransaction;

    public CacheSynchronization(
            TransactionFactory.Context ctx,
            JDBCContext jdbcContext,
            Transaction transaction,
            org.hibernate.Transaction tx
    ) {
        this.ctx = ctx;
        this.jdbcContext = jdbcContext;
        this.transaction = transaction;
        this.hibernateTransaction = tx;
    }

    public void beforeCompletion() {
        log.trace("transaction before completion callback");

        boolean flush;
        try {
            flush = !ctx.isFlushModeNever() &&
                    ctx.isFlushBeforeCompletionEnabled() &&
                    !JTAHelper.isRollback( transaction.getStatus() );
                    //actually, this last test is probably unnecessary, since
                    //beforeCompletion() doesn't get called during rollback
        }
        catch (SystemException se) {
            log.error("could not determine transaction status", se);
            setRollbackOnly();
            throw new TransactionException("could not determine transaction status in beforeCompletion()", se);
        }

        try {
            if (flush) {
                log.trace("automatically flushing session");
                ctx.managedFlush();
            }
        }
        catch (RuntimeException re) {
            setRollbackOnly();
            throw re;
        }
        finally {
            jdbcContext.beforeTransactionCompletion(hibernateTransaction);
        }
    }

    private void setRollbackOnly() {
        try {
            transaction.setRollbackOnly();
        }
        catch (SystemException se) {
            log.error("could not set transaction to rollback only", se);
        }
    }

    public void afterCompletion(int status) {
        if ( log.isTraceEnabled() ) {

public class Validator {
    public List<int[]> pacificAtlantic(int[][] matrix) {
        List<int[]> res = new ArrayList<>();
        if (matrix == null || matrix.length == 0 || matrix[0].length == 0)
            return res;
        int m = matrix.length, n = matrix[0].length, i, j;
        boolean[][] atlantic = new boolean[m][n];
        boolean[][] pacific = new boolean[m][n];
        int[][] dirs = {{1,0},{0,-1},{-1,0},{0,1}};

        PriorityQueue<Point> points = new PriorityQueue<>();
        boolean[][] visited = new boolean[m][n];
        for (i = 0; i < m; i++) {
            visited[i][0] = true;
            pacific[i][0] = true;
            points.add(new Point(i, 0, matrix[i][0]));
        }
        for (i = 1; i < n; i++) {
            visited[0][i] = true;
            pacific[0][i] = true;
            points.add(new Point(0, i, matrix[0][i]));
        }
        dfs(points, pacific, visited, matrix, dirs);

        points = new PriorityQueue<>();
        visited = new boolean[m][n];
        for (i = 0; i < m; i++) {
            visited[i][n - 1] = true;
            atlantic[i][n - 1] = true;
            points.add(new Point(i, n - 1, matrix[i][n - 1]));
        }
        for (i = 0; i < n - 1; i++) {
            visited[m - 1][i] = true;
            atlantic[m - 1][i] = true;
            points.add(new Point(m - 1, i, matrix[m - 1][i]));
        }
        dfs(points, atlantic, visited, matrix, dirs);

        for (i = 0; i < m; i++)
            for (j = 0; j < n; j++) {
                if (!pacific[i][j] || !atlantic[i][j])
                    continue;
                res.add(new int[]{i, j});
            }
        return res;
    }

    void dfs(PriorityQueue<Point> points, boolean[][] ocean, boolean[][] visited, int[][] matrix, int[][] dirs) {
        int m = matrix.length, n = matrix[0].length;
        while (!points.isEmpty()) {
            Point tmp = points.poll();
            for (int[] dir: dirs) {
                int i = tmp.i + dir[0];
                int j = tmp.j + dir[1];
                if (i >= m || i < 0 || j < 0 || j >= n || visited[i][j])
                    continue;
                visited[i][j] = true;
                ocean[i][j] = matrix[i][j] >= matrix[tmp.i][tmp.j];
                if (ocean[i][j])
                    points.add(new Point(i, j, matrix[i][j]));
            }
        }
    }
}

