import org.apache.jena.query.*;
import org.apache.jena.rdf.model.*;

public InputStream runSparqlQuery(String query) throws IOException {
    // Create a model
    Model model = ModelFactory.createDefaultModel();

    // Load your data into the model
    // model.read(...);

    // Create a query
    Query sparqlQuery = QueryFactory.create(query);

    // Create a query execution
    QueryExecution qexec = QueryExecutionFactory.create(sparqlQuery, model);

    // Execute the query and get the result
    ResultSet results = qexec.execSelect();

    // Convert the result to JSON
    String json = ResultSetConvert.convert(results, "JSON");

    // Convert the JSON string to an InputStream
    InputStream inputStream = new ByteArrayInputStream(json.getBytes(StandardCharsets.UTF_8));

    // Close the query execution
    qexec.close();

    return inputStream;
}

import java.util.Scanner;

/**
 * Console input helpers with validation loops.
 */
public class Inputter {

    public static Scanner scanner = new Scanner(System.in);

    public static int inputInt(String msg, int min, int max) {
        if (min > max) {
            int tmp = min;
            min = max;
            max = tmp;
        }
        int data;
        do {
            System.out.print(msg);
            data = Integer.parseInt(scanner.nextLine());
        } while (data < min || data > max);
        return data;
    }

    public static String inputStr(String msg) {
        System.out.print(msg);
        return scanner.nextLine().trim();
    }

    public static String inputNonBlankStr(String msg) {
        String data;
        do {
            System.out.print(msg);
            data = scanner.nextLine().trim();
        } while (data.length() == 0);
        return data;
    }

    public static String inputPattern(String msg, String pattern) {
        String data;
        do {
            System.out.print(msg);
            data = scanner.nextLine().trim();
        } while (!data.matches(pattern));
        return data;
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.stream.Collectors;
 
public class Abbrev {
 
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new FileReader("daynames.txt"));
        String line;
        while ((line = reader.readLine())!= null) {
            if (line.trim().isEmpty()) {
                continue;
            }
            Map<String, List<String>> abbr = new HashMap<>();
            for (String word : line.split(" ")) {
                for (int i = 1; i <= word.length(); i++) {
                    String key = word.substring(0, i);
                    if (!abbr.containsKey(key)) {
                        abbr.put(key, new ArrayList<>());
                    }
                    abbr.get(key).add(word);
                }
            }
            System.out.println("Minimum size: " + abbr.values().stream().mapToInt(List::size).max().getAsInt());
            System.out.println(abbr.entrySet().stream().map(e -> e.getKey() + " => " + e.getValue()).collect(Collectors.joining("\n")));
            System.out.println();
        }
    }
}

import org.apache.geode.cache.*;
import org.apache.geode.internal.offheap.MemoryAllocatorImpl;
import org.junit.Test;
import org.junit.After;
import org.junit.Before;
import static org.junit.Assert.assertEquals;

public class TxReleasesOffHeapOnCloseJUnitTest {

  private Cache cache;
  private Region<String, String> r;
  private CacheTransactionManager txmgr;
  private RegionFactory rf;
  private MemoryAllocatorImpl sma;

  @Before
  public void setUp() {
    CacheFactory cf = new CacheFactory();
    cf.set("off-heap-memory-size", "100m");
    cache = cf.create();

    sma = (MemoryAllocatorImpl) cache.getInternalResourceManager().getHeap();

    rf = cache.createRegionFactory();
    rf.setDataPolicy(DataPolicy.NORMAL);
    rf.setOffHeap(true);
    r = rf.create("r");

    txmgr = cache.getCacheTransactionManager();
  }

  @After
  public void tearDown() {
    if (cache != null && !cache.isClosed()) {
      cache.close();
    }
  }

  @Test
  public void testTxReleasesOffHeapOnClose() {
    r.put("k1", "v1");
    long bytesBeforeTx = sma.getStats().getUsedMemory();

    txmgr.begin();
    r.put("k1", "v2");
    long bytesInTx = sma.getStats().getUsedMemory();

    assertEquals(bytesBeforeTx + 1, bytesInTx);

    cache.close();

    assertEquals(0, sma.getStats().getUsedMemory());
  }
}

