                    for (Map.Entry<Integer, Integer> lenDistanceEntry : repeatedEntry.getValue().entrySet()) {
                        // keep character
                        boolean repeatChar = prevCharEntry.getKey().equals(c);
                        int keepLen = lenDistanceEntry.getKey() + repeatIncrease(repeatedEntry.getKey(), repeatChar);
                        int keepDel = lenDistanceEntry.getValue();

                        nextStates
                            .computeIfAbsent(c, k -> new HashMap<>())
                            .computeIfAbsent((repeatChar ? (repeatedEntry.getKey() + 1) : 1), k -> new HashMap<>())
                            .compute(keepLen, (k, v) -> (v != null && v < keepDel) ? v : keepDel);

                        int deleteLen = lenDistanceEntry.getKey();
                        int deleteDel = lenDistanceEntry.getValue() + 1;

                        if (deleteDel <= maxDel) {
                            nextStates
                                .computeIfAbsent(prevCharEntry.getKey(), k -> new HashMap<>())
                                .computeIfAbsent(repeatedEntry.getKey(), k -> new HashMap<>())
                                .compute(deleteLen, (k, v) -> (v != null && v < deleteDel) ? v : deleteDel);
                        }
                    }
                }
            }

            states = nextStates;
