public class IdenticalArrays {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        // Prompt user to enter list1
        System.out.print("Enter list1: ");
        int[] list1 = readArray(input);

        // Prompt user to enter list2
        System.out.print("Enter list2: ");
        int[] list2 = readArray(input);

        // Check if the arrays are identical
        if (equals(list1, list2)) {
            System.out.println("Two lists are identical");
        } else {
            System.out.println("Two lists are not identical");
        }
    }

    // Reads an array from user input
    public static int[] readArray(Scanner input) {
        int length = input.nextInt();
        int[] array = new int[length];
        for (int i = 0; i < length; i++) {
            array[i] = input.nextInt();
        }
        return array;
    }

    // Implements the equals method as described earlier
    public static boolean equals(int[] list1, int[] list2) {
        if (list1.length != list2.length) {
            return false;
        }
        Arrays.sort(list1);
        Arrays.sort(list2);
        for (int i = 0; i < list1.length; i++) {
            if (list1[i] != list2[i]) {
                return false;
            }
        }
        return true;
    }
}

public class Foo {
    public void ValueMethod(int x) { }
    public void PointerMethod(int x) { }
}
 
public class FooTest {
    public static void main(String[] args) {
        Foo myValue = new Foo();
        Foo myPointer = new Foo();
 
        // Calling value method on value
        myValue.ValueMethod(someParameter);
        // Calling pointer method on pointer
        myPointer.PointerMethod(someParameter);
 
        // Value methods can always be called on pointers
        // equivalent to (*myPointer).ValueMethod(someParameter)
        myPointer.ValueMethod(someParameter);
 
        // In a special case, pointer methods can be called on values that are addressable (i.e. lvalues)
        // equivalent to (&myValue).PointerMethod(someParameter)
        myValue.PointerMethod(someParameter);
 
        // You can get the method out of the type as a function, and then explicitly call it on the object
        Foo.ValueMethod(myValue, someParameter);
        Foo.PointerMethod(myPointer, someParameter);
        Foo.ValueMethod(myPointer, someParameter);
    }
}

public boolean hasPurgeableTombstones(int gcBefore) {
    // Check if the top-level tombstone should be purged
    if (topLevelTombstone != null && topLevelTombstone.timestamp < gcBefore) {
        return true;
    }

    // Check if any of the range tombstones should be purged
    for (RangeTombstone rt : rangeTombstones) {
        if (rt.timestamp < gcBefore) {
            return true;
        }
    }

    return false;
}

