public boolean hasNext() {
                    if (valueIterator == null || !valueIterator.hasNext()) {
                        while (entryIterator.hasNext()) {
                            Map.Entry<K, Collection<V>> entry = entryIterator.next();
                            valueIterator = entry.getValue().iterator();
                            if (valueIterator.hasNext()) {
                                return true;
                            }
                        }
                        return false;
                    }
                    return true;
                }

                public V next() {
                    if (!hasNext()) {
                        throw new NoSuchElementException();
                    }
                    return valueIterator.next();
                }

                public void remove() {
                    if (valueIterator == null || !valueIterator.hasNext()) {
                        throw new IllegalStateException();
                    }
                    valueIterator.remove();
                }

class Stack {
    public boolean gcdSort(int[] nums) {
        int[] copy = Arrays.copyOf(nums, nums.length);
        Arrays.sort(copy);
        List<Set<Integer>> lmao = new ArrayList<>();
        Set<Integer> todo = new HashSet<>();
        for (int i = 0; i < nums.length; i++) todo.add(i);
        for (int i = 0; i < nums.length; i++) {
            int n = 0;
            for (int num : todo) {
                n = num;
                break;
            }
            todo.remove(n);
            Set<Integer> group = new HashSet<>();
            group.add(n);
            Set<Integer> factors = new HashSet<>();
            int tmp = nums[n];
            for (int ii = 2; ii * ii <= tmp; ++ii) {
                if (tmp % ii == 0) {
                    factors.add(ii);
                    while (tmp % ii == 0) tmp /= ii;
                }
            }
            if (tmp > 1) factors.add(tmp);
            while (true) {
                boolean done = false;
                Set<Integer> newTodo = new HashSet<>();
                for (int num : todo) {
                    tmp = nums[num];
                    boolean cand = false;
                    for (int factor : factors) {
                        if (tmp % factor == 0) {
                            cand = true;
                            break;
                        }
                    }
                    if (!cand) {

                    newTodo.add(num);
                        continue;
                    }
                    done = true;
                    group.add(num);
                 for (int ii = 2; ii * ii <= tmp; ++ii) {
                       if (tmp % ii == 0) {
                          factors.add(ii);
                         while (tmp % ii == 0) tmp /= ii;
                       }
                    }
                    if (tmp > 1) factors.add(tmp);

                }
                todo = newTodo;
                if (!done) break;
            }
            lmao.add(group);
            if (todo.isEmpty()) break;
        }
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) map.put(copy[i], i);
        for (int i = 0; i < nums.length; i++) {
            int j = map.get(nums[i]);
            boolean found = false;
            for (Set<Integer> group : lmao) {
                if (group.contains(i) && group.contains(j)) {
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }
}

