public class ReversePrint {
 
    public static void rev_print(String s, int n) {
        for (; s.length() > 0 && Character.isWhitespace(s.charAt(0)); s = s.substring(1));
        if (s.length() > 0) {
            int e;
            for (e = 0; e < s.length() &&!Character.isWhitespace(s.charAt(e)); e++);
            rev_print(s.substring(e), 0);
            System.out.printf("%s%s", s.substring(0, e), " " + n);
        }
        if (n!= 0) System.out.println();
    }
 
    public static void main(String[] args) {
        String[] s = {
                "---------- Ice and Fire ------------",
                "                                    ",
                "fire, in end will world the say Some",
                "ice. in say Some                    ",
                "desire of tasted I've what From     ",
                "fire. favor who those with hold I   ",
                "                                    ",
                "... elided paragraph last...       ",
                "                                    ",
                "Frost Robert -----------------------",
                null
        };
        int i;
        for (i = 0; s[i]!= null; i++) rev_print(s[i], 1);
    }
}

