public class Complex {
    private double real;
    private double imaginary;

    public Complex(double real, double imaginary) {
        this.real = real;
        this.imaginary = imaginary;
    }

    public double getReal() {
        return real;
    }

    public double getImaginary() {
        return imaginary;
    }

    public Complex multiply(Complex c) {
        double real = this.real * c.getReal() - this.imaginary * c.getImaginary();
        double imaginary = this.real * c.getImaginary() + this.imaginary * c.getReal();
        return new Complex(real, imaginary);
    }

    @Override
    public String toString() {
        return "Complex{" +
                "real=" + real +
                ", imaginary=" + imaginary +
                '}';
    }
}

import java.util.Comparator;

public class OrderChecker {

    public static boolean ordered(int[] list) {
        return ordered(list, true);
    }

    public static boolean ordered(int[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] > list[i+1]) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i+1]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static boolean ordered(double[] list) {
        return ordered(list, true);
    }

    public static boolean ordered(double[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] > list[i+1]) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i] < list[i+1]) {
                    return false;
                }
            }
        }
        return true;
    }

    public static <E extends Comparable<E>> boolean ordered(E[] list) {
        return ordered(list, true);
    }

    public static <E extends Comparable<E>> boolean ordered(E[] list, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i].compareTo(list[i+1]) > 0) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (list[i].compareTo(list[i+1]) < 0) {
                    return false;
                }
            }
        }
        return true;
    }

    public static <E> boolean ordered(E[] list, Comparator<? super E> comparator) {
        return ordered(list, comparator, true);
    }

    public static <E> boolean ordered(E[] list, Comparator<? super E> comparator, boolean ascending) {
        if (ascending) {
            for (int i = 0; i < list.length - 1; i++) {
                if (comparator.compare(list[i], list[i+1]) > 0) {
                    return false;
                }
            }
        } else {
            for (int i = 0; i < list.length - 1; i++) {
                if (comparator.compare(list[i], list[i+1]) < 0) {
                    return false;
                }
            }
        }
        return true;
    }
}

import java.util.function.IntSupplier;
import static java.util.stream.IntStream.generate;
 
public class SubtractiveGenerator implements IntSupplier {
    static final int MOD = 1_000_000_000;
    private int[] state = new int[55];
    private int si, sj;
 
    public SubtractiveGenerator(int p1) {
        subrandSeed(p1);
    }
 
    void subrandSeed(int p1) {
        int p2 = 1;
 
        state[0] = p1 % MOD;
        for (int i = 1, j = 21; i < 55; i++, j += 21) {
            if (j >= 55)
                j -= 55;
            state[j] = p2;
            if ((p2 = p1 - p2) < 0)
                p2 += MOD;
            p1 = state[j];
        }
 
        si = 0;
        sj = 24;
        for (int i = 0; i < 165; i++)
            getAsInt();
    }
 
    @Override
    public int getAsInt() {
        if (si == sj)
            subrandSeed(0);
 
        if (si-- == 0)
            si = 54;
        if (sj-- == 0)
            sj = 54;
 
        int x = state[si] - state[sj];
        if (x < 0)
            x += MOD;
 
        return state[si] = x;
    }
 
    public static void main(String[] args) {
        generate(new SubtractiveGenerator(292_929)).limit(10)
                .forEach(System.out::println);
    }
}

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.stream.IntStream;
 
public class Entropy {
    public static void main(String[] args) {
        try {
            File file = new File(args[0]);
            FileInputStream stream = new FileInputStream(file);
            System.out.println("Entropy is " + entropy(stream));
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
 
    public static float entropy(FileInputStream stream) {
        long[] histogram = new long[256];
        long len = 0;
 
        try {
            int b;
            while ((b = stream.read())!= -1) {
                histogram[b] += 1;
                len += 1;
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
 
        return (float) IntStream.of(histogram)
               .filter(h -> h > 0)
               .mapToDouble(h -> h / (double) len)
               .map(ratio -> -ratio * Math.log(ratio) / Math.log(2))
               .sum();
    }
}

