import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class PrimeTriangle {
 
    private static boolean isPrime(int n) {
        assert n > 0 && n < 64;
        return (1L << n) == 0x28208a20a08a28acL;
    }
 
    private static boolean primeTriangleRow(List<Integer> list) {
        if (list.size() == 2) {
            return isPrime(list.get(0) + list.get(1));
        }
        for (int i = 1; i < list.size() - 1; i++) {
            if (isPrime(list.get(0) + list.get(i))) {
                int temp = list.get(i);
                list.set(i, list.get(1));
                list.set(1, temp);
                if (primeTriangleRow(list.subList(1, list.size()))) {
                    return true;
                }
                temp = list.get(i);
                list.set(i, list.get(1));
                list.set(1, temp);
            }
        }
        return false;
    }
 
    private static int primeTriangleCount(List<Integer> list) {
        if (list.size() == 2) {
            return isPrime(list.get(0) + list.get(1))? 1 : 0;
        }
        int count = 0;
        for (int i = 1; i < list.size() - 1; i++) {
            if (isPrime(list.get(0) + list.get(i))) {
                int temp = list.get(i);
                list.set(i, list.get(1));
                list.set(1, temp);
                count += primeTriangleCount(list.subList(1, list.size()));
                temp = list.get(i);
                list.set(i, list.get(1));
                list.set(1, temp);
            }
        }
        return count;
    }
 
    private static void print(List<Integer> list) {
        if (list.isEmpty()) {
            return;
        }
        System.out.print(String.format("%2d", list.get(0)));
        for (int i = 1; i < list.size(); i++) {
            System.out.print(String.format(" %2d", list.get(i)));
        }
        System.out.println();
    }
 
    public static void main(String[] args) {
        long start = System.nanoTime();
        for (int n = 2; n < 21; n++) {
            List<Integer> list = IntStream.range(1, n + 1).boxed().collect(Collectors.toList());
            if (primeTriangleRow(list)) {
                print(list);
            }
        }
        System.out.println();
        for (int n = 2; n < 21; n++) {
            List<Integer> list = IntStream.range(1, n + 1).boxed().collect(Collectors.toList());
            int count = primeTriangleCount(list);
            if (n > 2) {
                System.out.print(" ");
