import java.util.Scanner;

public class Checker {
    public static void main(String[] args) {

        double highScore = 0, secondHigh = 0;

        String highName = "";
        String secondName = "";
        String tempName = "";
        double tempScore = 0;

        Scanner input = new Scanner(System.in);

        System.out.print("Enter the number of students: ");

        int numStudents = input.nextInt();

        System.out.print("Enter a students name: ");
        highName = input.next();

        System.out.print("Enter the students score: ");
        highScore = input.nextDouble();

        while (numStudents > 1) {
            System.out.print("Enter a students name: ");
            tempName = input.next();

            System.out.print("Enter the students score: ");
            tempScore = input.nextDouble();

            if (tempScore > highScore) {
                secondHigh = highScore;
                secondName = highName;
                highScore = tempScore;
                highName = tempName;
                numStudents--;
                continue;
            }

            if (tempScore < highScore && tempScore > secondHigh) {
                secondHigh = tempScore;
                secondName = tempName;
            }
            numStudents--;

        }
        System.out.println("The top two students are: ");
        System.out.print(highName + "'s score of " + highScore);
        System.out.print(" and " + secondName + "'s score of " + secondHigh);
    }

}

import java.util.ArrayList;
import java.util.Scanner;

public class RepeatAdditionQuiz {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        ArrayList<Integer> answers = new ArrayList<>();
        int num1 = (int)(Math.random() * 10);
        int num2 = (int)(Math.random() * 10);
        System.out.print("What is " + num1 + " + " + num2 + "? ");
        int answer = input.nextInt();
        while (num1 + num2 != answer) {
            if (answers.contains(answer)) {
                System.out.println("You already entered " + answer);
            } else {
                System.out.print("Wrong answer. Try again. What is " + num1 + " + " + num2 + "? ");
                answers.add(answer);
            }
            answer = input.nextInt();
        }
        System.out.println("You got it!");
    }
}

class Handler {
    public String pushDominoes(String dominoes) {
        if (dominoes == null || dominoes.length() <= 1) {
            return dominoes;
        }
        int n = dominoes.length();
        int[] leftDst = new int[n];
        int[] rightDst = new int[n];
        for (int i = 1; i < n; ++i) {
            if (dominoes.charAt(i) != '.') {
                continue;
            }
            if (dominoes.charAt(i - 1) == 'R') {
                rightDst[i] = n;
            } else if (rightDst[i - 1] > 0) {
                rightDst[i] = rightDst[i - 1] - 1;
            }
        }
        for (int i = n - 2; i >= 0; --i) {
            if (dominoes.charAt(i) != '.') {
                continue;
            }
            if (dominoes.charAt(i + 1) == 'L') {
                leftDst[i] = n;
            } else if (leftDst[i + 1] > 0) {
                leftDst[i] = leftDst[i + 1] - 1;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; ++i) {
            if (leftDst[i] == rightDst[i]) {
                sb.append(dominoes.charAt(i));
            } else if (leftDst[i] > rightDst[i]) {
                sb.append('L');
            } else {
                sb.append('R');
            }
        }
        return sb.toString();
    }
}

