import java.util.*;

public class Timer {
    public int similarPairs(String[] words) {
        int count = 0;
        for (int i = 0; i < words.length; i++) {
            Set<Character> set1 = new HashSet<>();
            for (char c : words[i].toCharArray()) {
                set1.add(c);
            }
            for (int j = i + 1; j < words.length; j++) {
                Set<Character> set2 = new HashSet<>();
                for (char c : words[j].toCharArray()) {
                    set2.add(c);
                }
                if (set1.equals(set2)) {
                    count++;
                }
            }
        }
        return count;
    }
}

public class DoublyLinkedList {
    private int value;
    private DoublyLinkedList next;
    private DoublyLinkedList prev;
    public DoublyLinkedList(int value, DoublyLinkedList next, DoublyLinkedList prev) {
        this.value = value;
        this.next = next;
        this.prev = prev;
    }
    public int value() {
        return value;
    }
    public DoublyLinkedList next() {
        return next;
    }
    public DoublyLinkedList prev() {
        return prev;
    }
    public void next(DoublyLinkedList next) {
        this.next = next;
    }
    public void prev(DoublyLinkedList prev) {
        this.prev = prev;
    }
    public void traverse() {
        DoublyLinkedList node = this;
        while (node!= null) {
            System.out.print(node.value + " ");
            node = node.next;
        }
        System.out.println();
    }
    public void print() {
        DoublyLinkedList node = this;
        while (node!= null) {
            System.out.print(node.value + " ");
            node = node.prev;
        }
        System.out.println();
    }
    public static DoublyLinkedList createDoublyLinkedListFromArray(int[] ary) {
        DoublyLinkedList node, prev, head = new DoublyLinkedList(ary[0], null, null);
        prev = head;
        for (int i = 1; i < ary.length; i++) {
            node = new DoublyLinkedList(ary[i], null, prev);
            prev.next(node);
            prev = node;
        }
        return head;
    }
    public static void main(String[] args) {
        DoublyLinkedList head = createDoublyLinkedListFromArray(new int[] {10,20,30,40});
        head.traverse();
        head.print();
    }
}

