public class DeletiveEditing {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        scanner.nextLine(); // Consume newline

        for (int i = 0; i < n; i++) {
            String[] words = scanner.nextLine().split(" ");
            String s = words[0];
            String t = words[1];

            if (canTransform(s, t)) {
                System.out.println("YES");
            } else {
                System.out.println("NO");
            }
        }
    }

    private static boolean canTransform(String s, String t) {
        if (t.length() > s.length()) return false;

        int[] tCount = new int[26];
        for (char c : t.toCharArray()) {
            tCount[c - 'A']++;
        }

        int[] sCount = new int[26];
        int j = 0;

        for (int i = 0; i < s.length() && j < t.length(); i++) {
            char sc = s.charAt(i);
            char tc = t.charAt(j);

            sCount[sc - 'A']++;

            if (sc == tc) {
                if (sCount[sc - 'A'] == tCount[sc - 'A']) {
                    j++;
                }
            } else if (tCount[sc - 'A'] > 0 && sCount[sc - 'A'] == tCount[sc - 'A']) {
                return false;
            }
        }

        return j == t.length();
    }
}

import javax.jdo.annotations.IdentityType;
import javax.jdo.annotations.Inheritance;
import javax.jdo.annotations.InheritanceStrategy;
import javax.jdo.annotations.PersistenceCapable;
import javax.jdo.annotations.Persistent;

import org.apache.isis.applib.annotation.Programmatic;
import org.apache.isis.applib.util.ObjectContracts;

//import dom.AbstractNamedChatsDomainEntity; // Consider extending a custom base class

/**
 * Base class for representing named classifications or coded values.
 * Uses {@link #name} as (primary key) natural key (and title).
 */
@PersistenceCapable(
        identityType = IdentityType.NATURAL,
        objectIdClass=ClassificationValueId.class
)
@Inheritance(strategy = InheritanceStrategy.SUBCLASS_TABLE)
// could use a Map, but see https://issues.apache.org/jira/browse/ISIS-863
public abstract class ClassificationValue
        /*implements Comparable<ClassificationValue>,*/
        /*Locatable*/ {

    //region > name (property)

    private String name;

    @javax.jdo.annotations.Column(allowsNull = "false", length = 255)
    @Persistent
    public String getName() {
        return name;
    }

    public void setName(final String name) {
        this.name = name;
    }

    //endregion

    //region > title

    public String title() {
        return getName();
    }

    //endregion

    //region > equals, hashCode, toString

    private final static String propertyNames = "name";

    @Programmatic
    @Override
    public boolean equals(final Object obj) {
        if(obj == this) {
            return true;
        }
        if (obj == null || obj.getClass() != getClass()) {
            return false;
        }
        return equals((ClassificationValue) obj);
    }

    public boolean equals(final ClassificationValue other) {
        return ObjectContracts.compare(this, other, propertyNames);
    }

    @Override
    public String toString() {
        return ObjectContracts.toString(this, propertyNames);
    }

    //region > (int)hashCode

    @Programmatic
    @Override
    public int hashCode() {
        return java.util.Objects.hash(getName());
    }

    //endregion

}

import java.util.Scanner;

public class DecimalToBinary {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a decimal number: ");
        int decimal = scanner.nextInt();
        String binary = dec2Bin(decimal);
        System.out.printf("The binary equivalent of %d is %s%n", decimal, binary);
    }

    public static String dec2Bin(int value) {
        if (value == 0) {
            return "0";
        } else if (value == 1) {
            return "1";
        } else {
            int quotient = value / 2;
            int remainder = value % 2;
            return dec2Bin(quotient) + remainder;
        }
    }
}

public class SelfDescribingNumbers{
    public static boolean isSelfDescribing(int a){
        String s = Integer.toString(a);
        for(int i = 0; i < s.length(); i++){
            String s0 = s.charAt(i) + "";
            int b = Integer.parseInt(s0); // number of times i-th digit must occur for it to be a self describing number
            int count = 0;
            for(int j = 0; j < s.length(); j++){
                int temp = Integer.parseInt(s.charAt(j) + "");
                if(temp == i){
                    count++;
                }
                if (count > b) return false;
            }
            if(count != b) return false;
        }
        return true;
    }
 
    public static void main(String[] args){
        for(int i = 0; i < 100000000; i++){
            if(isSelfDescribing(i)){
                System.out.println(i);
             }
        }
    }
}

public class DijitalSaat {

    private int saat = 0;         // Saat degerini tutar
    private int dakika = 0;       // Dakika degerini tutar
    private int saniye = 0;       // Saniye degerini tutar

    // Saniye degerini donduren metod
    public int getSaniye() {
        return this.saniye;
    }

    // Saniye degerini ayarlayan metod (0-59 arasinda olmali)
    public void setSaniye(int saniye) {
        if(saniye >= 0 && saniye < 60) {
            this.saniye = saniye;
        }
    }

    // Saati, dakikayi ve saniyeyi gosteren metod
    public void goster() {
        System.out.println(saat + ":" + dakika + ":" + saniye);
    }

    // Saati arttiran metod (0-23 arasinda doner)
    private void saatiArttir() {
        saat++;
        if(saat > 23) {
            saat = 0;   // Saat 23'ten sonra 0'a doner
        }
    }

    // Dakikayi arttiran metod (0-59 arasinda doner)
    private void dakikayiArttir() {
        dakika++;
        if(dakika > 59) {
            dakika = 0;  // Dakika 59'dan sonra 0'a doner
            saatiArttir();  // Her dakika arttiginda saati de arttirir
        }
    }

    // Saniyeyi arttiran metod (0-59 arasinda doner)
    public void saniyeyiArttir() {
        saniye++;
        if(saniye > 59) {
            saniye = 0;   // Saniye 59'dan sonra 0'a doner
            dakikayiArttir();  // Her saniye arttiginda dakikayi arttirir
        }
    }

    // Saatin guncellenmesini saglayan metod
    public void saatiGuncelle(int saat, int dakika, int saniye) {
        this.saat = saat;
        this.dakika = dakika;
        this.saniye = saniye;
    }

    // Ana metod (main method) icinde kullanimi
    public static void main(String[] args) {
        // Dijital saat nesnesi olusturuluyor
        DijitalSaat saat = new DijitalSaat();

        // Baslangic saati, dakika ve saniye ayarlari
        saat.saatiGuncelle(10, 58, 50);
        System.out.println("Baslangic saati:");
        saat.goster();  // ilk gosterim

        // 70 saniye boyunca saniye arttirma islemi
        for(int i = 0; i < 70; i++) {
            saat.saniyeyiArttir();  // Saniyeyi arttir
            System.out.print("Saniye " + (i + 1) + ": ");
            saat.goster();  // Guncellenmis saati goster
        }

        // 120 saniye ekleyerek saati bir saat ileri alalim
        System.out.println("\nSaati bir saat ileri aliyoruz...");
        for(int i = 0; i < 120; i++) {
            saat.saniyeyiArttir();  // Yine saniyeleri arttir
        }
        System.out.print("Yeni saat: ");
        saat.goster();  // Guncellenmis saati goster
    }
}

import javax.swing.* ;
import java.awt.* ;
 
public class Greybars extends JFrame {
   private int width ;
   private int height ;
 
   public Greybars( )  {
      super( "grey bars example!" ) ;
      width = 640 ;
      height = 320 ;
      setSize( width , height ) ;
      setDefaultCloseOperation( JFrame.EXIT_ON_CLOSE ) ;
      setVisible( true ) ;
    }
 
    public void paint ( Graphics g ) {
      int run = 0 ;
      double colorcomp = 0.0 ; //component of the color
      for ( int columncount = 8 ; columncount < 128 ; columncount *= 2 ) {
     double colorgap = 255.0 / (columncount - 1) ; //by this gap we change the background color
     int columnwidth = width / columncount ;
     int columnheight = height / 4 ;
     if ( run % 2 == 0 ) //switches color directions with every for loop
        colorcomp = 0.0 ;
     else {
        colorcomp = 255.0 ;
        colorgap *= -1.0 ;
     }
     int ystart = 0 + columnheight * run ;
     int xstart = 0 ;
     for ( int i = 0 ; i < columncount ; i++ ) {
            int icolor = (int)Math.round(colorcomp) ; //round to nearer integer
        Color nextColor = new Color( icolor , icolor, icolor ) ;
        g.setColor( nextColor ) ;
        g.fillRect( xstart , ystart , columnwidth , columnheight ) ;
        xstart += columnwidth ;
        colorcomp += colorgap ;
     }
     run++ ;
      }
    }
 
    public static void main( String[ ] args ) {
       Greybars gb = new Greybars( ) ;
    }
}

