import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
 
public class SemiPrime{
    private static final BigInteger TWO = BigInteger.valueOf(2);
 
    public static List<BigInteger> primeDecomp(BigInteger a){
        // impossible for values lower than 2
        if(a.compareTo(TWO) < 0){
            return null;
        }
 
        //quickly handle even values
        List<BigInteger> result = new ArrayList<BigInteger>();
        while(a.and(BigInteger.ONE).equals(BigInteger.ZERO)){
            a = a.shiftRight(1);
            result.add(TWO);
        }
 
        //left with odd values
        if(!a.equals(BigInteger.ONE)){
            BigInteger b = BigInteger.valueOf(3);
            while(b.compareTo(a) < 0){
                if(b.isProbablePrime(10)){
                    BigInteger[] dr = a.divideAndRemainder(b);
                    if(dr[1].equals(BigInteger.ZERO)){
                        result.add(b);
                        a = dr[0];
                    }
                }
                b = b.add(TWO);
            }
            result.add(b); //b will always be prime here...
        }
        return result;
    }
 
    public static boolean isSemi(BigInteger x){
        List<BigInteger> decomp = primeDecomp(x);
        return decomp != null && decomp.size() == 2;
    }
 
    public static void main(String[] args){
        for(int i = 2; i <= 100; i++){
            if(isSemi(BigInteger.valueOf(i))){
                System.out.print(i + " ");
            }
        }
        System.out.println();
        for(int i = 1675; i <= 1680; i++){
            if(isSemi(BigInteger.valueOf(i))){
                System.out.print(i + " ");
            }
        }
    }
}

public static Bitmap convertGrayU8ToBitmap(GrayU8 input, Bitmap.Config config) {
    Bitmap output = Bitmap.createBitmap(input.width, input.height, config);
    byte[] data = ((DataBufferByte) output.getRaster().getDataBuffer()).getData();
    byte[] pixels = input.data;

    for (int i = 0; i < pixels.length; i++) {
        data[i] = pixels[i];
    }

    return output;
}

import java.util.Scanner;

public class AsalSayiKontrolu {

    public static void main(String[] args) {

        Scanner scanner = new Scanner(System.in);

        // Kullanicidan bir sayi alinmasi
        System.out.print("Bir sayi girin: ");
        int sayi = scanner.nextInt();

        // Girilen sayi 1 veya daha kucukse, kullanicidan tekrar dogru bir sayi istenir
        while (sayi <= 1) {
            System.out.println("Lutfen 2'den buyuk bir pozitif sayi girin.");
            sayi = scanner.nextInt();
        }

        scanner.close(); // Scanner kaynaginin kapatilmasi

        boolean asal = true; // Asal olup olmadigini kontrol eden degisken

        // Asallik kontrolu icin dongu
        for (int i = 2; i <= sayi / 2; i++) {
            if (sayi % i == 0) { // Sayi, i'ye tam bolunuyorsa asal degildir
                asal = false;
                break; // Kontrolu sonlandir
            }
        }

        // Asallik durumunun yazdirilmasi
        if (asal) {
            System.out.println(sayi + " asal sayidir.");
        } else {
            System.out.println(sayi + " asal sayi degildir.");
        }
    }
}

public void emitAsync(Enum event, Object... args) {
    ExecutorService executor = Executors.newSingleThreadExecutor();
    executor.submit(() -> {
        emit(event, args);
    });
    executor.shutdown();
}

