/**
 * An interface defining the browser parts that need to be initialized asynchronously during
 * browser startup.
 */
interface BrowserParts {
    /**
     * Called at the start of startup, before UI inflation.  Any non-UI dependencies
     * should be initialized at this point.
     */
    void preInflationStartup();

    /**
     * Called to set the content view of the activity and start loading libraries in the
     * background.
     */
    void setContentViewAndLoadLibrary();

    /**
     * Called after UI inflation and library loading has finished.  This should start
     * any asynchronous startup tasks.
     */
    void postInflationStartup();

    /**
     * Called to preconnect based on the launch intent.  This is optional and may not
     * be called during every startup.
     * @param url The URL to preconnect to.
     */
    void maybePreconnect(String url);

    /**
     * Called to initialize the compositor.
     */
    void initializeCompositor();

    /**
     * Called to restore or create tabs.
     */
    void initializeState();

    /**
     * Called to finish native initialization.
     */
    void finishNativeInitialization();

    /**
     * Called when startup fails.  This should clean up any resources that were allocated
     * during startup.
     */
    void onStartupFailure();

    /**
     * Checks if the activity is destroyed.
     * @return Whether the activity is destroyed.
     */
    boolean isActivityDestroyed();

    /**
     * Checks if the activity is finishing.
     * @return Whether the activity is finishing.
     */
    boolean isActivityFinishing();
}

public class Builder {
    public int findLUSlength(String a, String b) {
        if(a.length() == 0 && b.length() == 0) return -1;
        if(a.length() != b.length()) return a.length() > b.length() ? a.length() : b.length();
        if(a.equals(b)) return -1;
        return a.length();
    }
}

