import java.util.Scanner;

public class Complex implements Cloneable {
    private double a;
    private double b;

    public Complex() {
        this(0, 0);
    }

    public Complex(double a) {
        this(a, 0);
    }

    public Complex(double a, double b) {
        this.a = a;
        this.b = b;
    }

    public double getRealPart() {
        return a;
    }

    public double getImaginaryPart() {
        return b;
    }

    public Complex add(Complex secondComplex) {
        return new Complex(a + secondComplex.getRealPart(), b + secondComplex.getImaginaryPart());
    }

    public Complex subtract(Complex secondComplex) {
        return new Complex(a - secondComplex.getRealPart(), b - secondComplex.getImaginaryPart());
    }

    public Complex multiply(Complex secondComplex) {
        double newA = a * secondComplex.getRealPart() - b * secondComplex.getImaginaryPart();
        double newB = b * secondComplex.getRealPart() + a * secondComplex.getImaginaryPart();
        return new Complex(newA, newB);
    }

    public Complex divide(Complex secondComplex) {
        double c = secondComplex.getRealPart();
        double d = secondComplex.getImaginaryPart();
        double newA = (a * c + b * d) / (c * c + d * d);
        double newB = (b * c - a * d) / (c * c + d * d);
        return new Complex(newA, newB);
    }

    public double abs() {
        return Math.sqrt(a * a + b * b);
    }

    @Override
    public String toString() {
        if (b == 0) {
            return a + "";
        } else {
            return "(" + a + " + " + b + "i)";
        }
    }

    @Override
    protected Object clone() throws CloneNotSupportedException {
        return super.clone();
    }

    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        System.out.print("Enter the first complex number: ");
        double a1 = input.nextDouble();
        double b1 = input.nextDouble();
        System.out.print("Enter the second complex number: ");
        double a2 = input.nextDouble();
        double b2 = input.nextDouble();
        Complex c1 = new Complex(a1, b1);
        Complex c2 = new Complex(a2, b2);
        System.out.println(c1 + " + " + c2 + " = " + c1.add(c2));
        System.out.println(c1 + " - " + c2 + " = " + c1.subtract(c2));
        System.out.println(c1 + " * " + c2 + " = " + c1.multiply(c2));
        System.out.println(c1 + " / " + c2 + " = " + c1.divide(c2));
        System.out.println("|" + c1 + "| = " + c1.abs());
    }
}

public static String trim(String s, char bad) {
    if (s == null) {
        return null;
    }
    int start = 0;
    int end = s.length() - 1;
    while (start <= end) {
        final char startChar = s.charAt(start);
        final char endChar = s.charAt(end);
        if (startChar != bad && endChar != bad) {
            return s.substring(start, end + 1);
        }
        if (startChar == bad) {
            start++;
        }
        if (endChar == bad) {
            end--;
        }
    }
    return "";
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Scanner;

public class BullsAndCows {
    public static void main(String[] args) {
        int size = 4;
        List<List<Integer>> scores = new ArrayList<>();
        List<List<Integer>> guesses = new ArrayList<>();
        System.out.println("Playing Bulls & Cows with " + size + " unique digits.");
        List<List<Integer>> possibleGuesses = new ArrayList<>();
        for (int i = 1; i <= 9; i++) {
            for (int j = 1; j <= 9; j++) {
                for (int k = 1; k <= 9; k++) {
                    for (int l = 1; l <= 9; l++) {
                        if (i!= j && i!= k && i!= l && j!= k && j!= l && k!= l) {
                            possibleGuesses.add(Arrays.asList(i, j, k, l));
                        }
                    }
                }
            }
        }
        possibleGuesses.sort((o1, o2) -> {
            int sum1 = 0;
            int sum2 = 0;
            for (int i = 0; i < o1.size(); i++) {
                sum1 += o1.get(i);
                sum2 += o2.get(i);
            }
            return sum1 - sum2;
        });
        while (true) {
            List<Integer> currentGuess = possibleGuesses.remove(possibleGuesses.size() - 1);
            guesses.add(currentGuess);
            System.out.print("Guess " + guesses.size() + " is " + currentGuess + ". Answer (bulls,cows)? ");
            Scanner scanner = new Scanner(System.in);
            String[] split = scanner.nextLine().split(",");
            List<Integer> score = new ArrayList<>();
            for (String s : split) {
                score.add(Integer.parseInt(s));
            }
            scores.add(score);
            if (score.get(0) == size && score.get(1) == 0) {
                System.out.println("Yeah!");
                break;
            }
            possibleGuesses.removeIf(guess -> {
                int bulls = 0;
                for (int i = 0; i < guess.size(); i++) {
                    if (guess.get(i) == currentGuess.get(i)) {
                        bulls++;
                    }
                }
                int cows = size - (guess.size() - currentGuess.size()) - bulls;
                return!((bulls == score.get(0)) && (cows == score.get(1)));
            });
            if (possibleGuesses.isEmpty()) {
                System.out.println("Error in scoring?");
                for (int i = 0; i < guesses.size(); i++) {
                    System.out.println(guesses.get(i) + " => bulls " + scores.get(i).get(0) + " cows " + scores.get(i).get(1));

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class DiceRoller {
    public static void main(String[] args) {
        Stats rolledCharacter = roll();

        while (rolledCharacter.total < 75 || rolledCharacter.rolls.stream().filter(a -> a >= 15).count() < 2) {
            rolledCharacter = roll();
        }

        System.out.println("The 6 random numbers generated are:");
        System.out.println(String.join(", ", rolledCharacter.rolls.toString()));
        System.out.println("Their sum is " + rolledCharacter.total + " and " + rolledCharacter.rolls.stream().filter(a -> a >= 15).count() + " of them are >= 15");
    }

    public static Stats roll() {
        Stats stats = new Stats();
        stats.rolls = new ArrayList<>();
        stats.total = 0;

        for (int i = 0; i <= 5; i++) {
            List<Integer> d6s = new ArrayList<>();

            for (int j = 0; j <= 3; j++) {
                d6s.add(new Random().nextInt(6) + 1);
            }

            Collections.sort(d6s);
            d6s.remove(0);
            int rollTotal = d6s.stream().mapToInt(Integer::intValue).sum();

            stats.rolls.add(rollTotal);
            stats.total += rollTotal;
        }

        return stats;
    }

    public static class Stats {
        public List<Integer> rolls;
        public int total;
    }
}

class Graph {
    public int[] secondGreaterElement(int[] nums) {
        int[] ans = new int[nums.length];
        for(int i = 0; i < ans.length; i++){
            ans[i] = -1;
        }
        PriorityQueue<Integer[]> queue = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        Deque<Integer[]> deque = new ArrayDeque<>();
        for(int i = 0; i < nums.length; i++){
            while(!queue.isEmpty() && queue.peek()[0] < nums[i]){
                Integer[] tmp = queue.poll();
                tmp[2]++;
                if(tmp[2] >= 2){
                    ans[tmp[1]] = nums[i];
                }
                else{
                    deque.offer(tmp);
                }
            }
            queue.offer(new Integer[]{nums[i], i, 0});
            while(!deque.isEmpty()){
                queue.offer(deque.poll());
            }
        }
        return ans;
    }
}

public class Cache {
    public int maxVacationDays(int[][] flights, int[][] days) {
        int n = days.length;
        if (n == 0) return 0;
        int K = days[0].length;

        int[][] memo = new int[K][n];

        Set<Integer> set1 = new HashSet<>();
        set1.add(0);
        for (int j = 0; j < n; j++) {
            Set<Integer> set2 = new HashSet<>();
            for (int k: set1) {
                if (j == k || flights[k][j] == 1) {
                    memo[0][j] = days[j][0];
                    //if (k == 0 && j == 1) System.out.println(memo[0][j]);
                    set2.add(j);
                }
            }
            set1.addAll(set2);
        }
        //System.out.println();
        int res = 0;
        for (int i = 1; i < K; i++) {
            Set<Integer> set2 = new HashSet<>();
            for (int j = 0; j < n; j++) {
                for (int k: set1) {
                    if (j == k || flights[k][j] == 1) {
                        memo[i][j] = Math.max(memo[i][j], memo[i - 1][k] + days[j][i]);
                        res = Math.max(memo[i][j], res);
                        set2.add(j);
                    }
                }
            }
            set1 = set2;
        }

        return res;
    }
}

import java.util.Collections;
import java.util.LinkedList;
import java.util.List;
 
/**
 * A class for an "Integer with a history".
 * <p>
 * Note that it is not possible to create an empty Variable (so there is no "null") with this type. This is a design
 * choice, because if "empty" variables were allowed, reading of empty variables must return a value. Null is a
 * bad idea, and Java 8's Optional<T> (which is somewhat like the the official fix for the null-bad-idea) would
 * make things more complicated than an example should be.
 */
public class IntegerWithHistory {
 
    /**
     * The "storage Backend" is a list of all values that have been ever assigned to this variable. The List is
     * populated front to back, so a new value is inserted at the start (position 0), and older values move toward the end.
     */
    private final List<Integer> history;
 
    /**
     * Creates this variable and assigns the initial value
     *
     * @param value initial value
     */
    public IntegerWithHistory(Integer value) {
        history = new LinkedList<>();
        history.add(value);
    }
 
    /**
     * Sets a new value, pushing the older ones back in the history
     *
     * @param value the new value to be assigned
     */
    public void set(Integer value) {
        //History is populated from the front to the back, so the freshest value is stored a position 0
        history.add(0, value);
    }
 
    /**
     * Gets the current value. Since history is populuated front to back, the current value is the first element
     * of the history.
     *
     * @return the current value
     */
    public Integer get() {
        return history.get(0);
    }
 
    /**
     * Gets the entire history all values that have been assigned to this variable.
     *
     * @return a List of all values, including the current one, ordered new to old
     */
    public List<Integer> getHistory() {
        return Collections.unmodifiableList(this.history);
    }
 
    /**
     * Rolls back the history one step, so the current value is removed from the history and replaced by it's predecessor.
     * This is a destructive operation! It is not possible to rollback() beyond the initial value!
     *
     * @return the value that had been the current value until history was rolled back.
     */
    public Integer rollback() {
        if (history.size() > 1) {
            return history.remove(0);
        } else {
            return history.get(0);
        }
    }
}

