public class ZookeeperBomb {

    public static void main(String[] args) {
        // Read the number of test cases
        int t = Integer.parseInt(System.in);

        // Loop through each test case
        for (int i = 0; i < t; i++) {
            // Read the input string
            String s = System.in.next();

            // Get the length of the input string
            int n = s.length();

            // Initialize the DP table
            int[][] dp = new int[n + 1][n + 1];

            // Fill the DP table
            for (int len = 1; len <= n; len++) {
                for (int i = 0, j = len - 1; j < n; i++, j++) {
                    if (i == 0 && j == 0) {
                        // Base case: if strings are empty, they are equal
                        dp[i][j] = 0;
                    } else if (i == 0) {
                        // If first string is empty, it can be concatenated with the second string
                        dp[i][j] = dp[i][j - 1] + (s.charAt(j) == 'B' ? 1 : 0);
                    } else if (j == 0) {
                        // If second string is empty, it can be concatenated with the first string
                        dp[i][j] = dp[i - 1][j] + (s.charAt(i - 1) == 'B' ? 1 : 0);
                    } else {
                        // If neither string is empty, we need to consider substrings
                        if (s.charAt(i - 1) == 'A' && s.charAt(j) == 'B') {
                            // If the last characters are 'A' and 'B', we can concatenate them
                            dp[i][j] = dp[i - 1][j - 1];
                        } else if (s.charAt(i - 1) == 'B' && s.charAt(j) == 'B') {
                            // If the last characters are both 'B', we take one 'B'
                            dp[i][j] = dp[i - 1][j - 1] + 1;
                        } else if (s.charAt(i - 1) == 'A' && s.charAt(j) == 'A') {
                            // If the last characters are both 'A', we take one 'A'
                            dp[i][j] = dp[i - 1][j - 1] + 1;
                        } else {
                            // If the last characters are different, we take the minimum of the two possible options
                            dp[i][j] = Math.min(dp[i - 1][j - 1] + 1, Math.min(dp[i][j - 1] + 1, dp[i - 1][j] + 1));
                        }
                    }
                }
            }

            // The answer is the one with the minimum difference from 0
            System.out.println(n - dp[n][n]);
        }
    }
}

