public class Device {
    private String name;

    public Device(String name) {
        this.name = name;
    }

    public String getName() {
        return name;
    }
}

public class DeviceManager {
    private Vector<Device> devices;

    public DeviceManager() {
        devices = new Vector<>();
        // Add some devices to the list
        devices.add(new Device("Device1"));
        devices.add(new Device("Device2"));
        devices.add(new Device("AnotherDevice"));
    }

    public Vector<Device> getDeviceList(String pattern) {
        Vector<Device> matchingDevices = new Vector<>();

        for (Device device : devices) {
            if (device.getName().contains(pattern)) {
                matchingDevices.add(device);
            }
        }

        return matchingDevices;
    }
}

public static double daleChallGrade(String strText) {
    // Calculate the number of words
    int wordCount = strText.split("\\s+").length;

    // Calculate the number of sentences
    int sentenceCount = strText.split("[.!?]+").length;

    // Calculate the number of syllables
    int syllableCount = 0;
    String[] words = strText.split("\\s+");
    for (String word : words) {
        syllableCount += countSyllables(word);
    }

    // Calculate the Dale Chall Grade
    double averageSentenceLength = (double) wordCount / sentenceCount;
    double averageSyllablesPerWord = (double) syllableCount / wordCount;
    double daleChallScore = 0.1579 * averageSentenceLength + 0.0496 * averageSyllablesPerWord;

    return daleChallScore;
}

private static int countSyllables(String word) {
    // A simple heuristic to count syllables in a word
    word = word.toLowerCase();
    int count = 0;
    boolean isPrevVowel = false;
    for (int i = 0; i < word.length(); i++) {
        char c = word.charAt(i);
        if (isVowel(c)) {
            if (!isPrevVowel) {
                count++;
                isPrevVowel = true;
            }
        } else {
            isPrevVowel = false;
        }
    }
    // Adjust for silent 'e' at the end of the word
    if (word.endsWith("e")) {
        count--;
    }
    // Ensure at least one syllable
    if (count == 0) {
        count = 1;
    }
    return count;
}

private static boolean isVowel(char c) {
    return "aeiou".indexOf(c) != -1;
}

