import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
 
public class CombinationsWithRepetitions {
    private final List<String> arr;
    private final int k;
    private final int[] counts;
    private boolean remaining;
 
    public CombinationsWithRepetitions(List<String> arr, int k) {
        this.arr = arr;
        this.k = k;
        this.counts = new int[arr.size()];
        Arrays.fill(this.counts, 0);
        this.counts[arr.size() - 1] = k;
        this.remaining = true;
    }
 
    public List<String> next() {
        if (!this.remaining) {
            return null;
        }
        List<String> comb = new ArrayList<>();
        for (int i = 0; i < this.counts.length; i++) {
            for (int j = 0; j < this.counts[i]; j++) {
                comb.add(this.arr.get(i));
            }
        }
        // this is lexicographically largest, and thus the last combination
        if (this.counts[0] == this.k) {
            this.remaining = false;
        } else {
            int n = this.counts.length;
            for (int i = n - 1; i > 0; i--) {
                if (this.counts[i] > 0) {
                    int originalValue = this.counts[i];
                    this.counts[i - 1] += 1;
                    for (int j = i; j < n - 1; j++) {
                        this.counts[j] = 0;
                    }
                    this.counts[n - 1] = originalValue - 1;
                    break;
                }
            }
        }
        return comb;
    }
 
    public static void main(String[] args) {
        List<String> collection = Arrays.asList("iced", "jam", "plain");
        CombinationsWithRepetitions combinations = new CombinationsWithRepetitions(collection, 2);
        while (true) {
            List<String> comb = combinations.next();
            if (comb == null) {
                break;
            }
            for (String item : comb) {
                System.out.print(item + " ");
            }
            System.out.println();
        }
    }
}

