import java.io.*;
import java.util.*;
 
public class Stack {
 
    public static long factorial(long n) {
        long product = 1;
 
        if (n < 2) {
            return 1;
        }
 
        for (; n > 0; n--) {
            long prev = product;
            product *= n;
            if (product < prev) {
                System.err.println("Overflowed");
                return product;
            }
        }
 
        return product;
    }
 
    // uses wilson's theorem
    public static boolean isPrime(long n) {
        long large = factorial(n - 1) + 1;
        return (large % n) == 0;
    }
 
    public static void main(String[] args) {
        long n;
 
        // Can check up to 21, more will require a big integer library
        for (n = 2; n < 22; n++) {
            System.out.printf("Is %d prime: %b\n", n, isPrime(n));
        }
    }
}

