public class Time {
    public static void main(String[] args) {
        int MINUTE = 60;
        int HOUR = MINUTE * 60;
        int DAY = HOUR * 24;
        int WEEK = DAY * 7;

        int[] sec = {7259, 86400, 6000000};
        for (int i = 0; i < sec.length; i++) {
            System.out.println(sec[i] + "\t: " + sec_to_str(sec[i]));
        }
    }

    public static String sec_to_str(int sec) {
        int w = sec / WEEK;
        int rem = sec % WEEK;
        int d = rem / DAY;
        rem = rem % DAY;
        int h = rem / HOUR;
        rem = rem % HOUR;
        int m = rem / MINUTE;
        int s = rem % MINUTE;
        String[] units = {w + " wk", d + " d", h + " h", m + " min", s + " sec"};
        String result = "";
        for (int i = 0; i < units.length; i++) {
            if (!units[i].startsWith("0")) {
                result += units[i] + ", ";
            }
        }
        return result.substring(0, result.length() - 2);
    }
}

