public class FilterSignal {
    private static class vector {
        float[] values;
        int size;
    }
 
    private static vector extractVector(String str) {
        vector coeff = new vector();
        int i = 0, count = 1;
        String token;
 
        while (str.charAt(i)!= 00) {
            if (str.charAt(i++) =='')
                count++;
        }
 
        coeff.values = new float[count];
        coeff.size = count;
 
        StringTokenizer st = new StringTokenizer(str, " ");
 
        i = 0;
 
        while (st.hasMoreTokens()) {
            coeff.values[i++] = Float.parseFloat(st.nextToken());
        }
 
        return coeff;
    }
 
    private static vector processSignalFile(String fileName) {
        int i, j;
        float sum;
        String str;
        vector coeff1, coeff2, signal, filteredSignal;
 
