            filteredSignal.values = new float[signal.size];
            filteredSignal.size = signal.size;
 
            for (i = 0; i < signal.size; i++) {
                sum = 0;
 
                for (j = 0; j < coeff2.size; j++) {
                    if (i - j >= 0)
                        sum += coeff2.values[j] * signal.values[i - j];
