import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import static org.hamcrest.CoreMatchers.is;
import static org.junit.Assert.assertThat;

public class LombokUtilsAllGetterTest {

  private static final AccessorsInfo DEFAULT_ACCESSORS = AccessorsInfo.build(false, false, false);
  private final List<String> lombokResult = new ArrayList<String>();
  private final List<String> result = new ArrayList<String>();

  private void makeResults(String fieldName, boolean isBoolean, AccessorsInfo accessorsInfo) {
    lombokResult.clear();
    result.clear();

    lombokResult.addAll(LombokHandlerUtil.toAllGetterNames(accessorsInfo, fieldName, isBoolean));
    result.addAll(LombokUtils.toAllGetterNames(accessorsInfo, fieldName, isBoolean));

    assertThat(result, is(lombokResult));
  }

  @Test
  public void testToAllGetterNames_NonBoolean() throws Exception {
    makeResults("myField", false, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getMyField")));
  }

  @Test
  public void testToAllGetterNames_NonBoolean_Uppercase() throws Exception {
    makeResults("myField", false, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getMyField")));
  }

  @Test
  public void testToAllGetterNames_NonBoolean_Uppercase_Multiple() throws Exception {
    makeResults("MYField", false, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getMYField")));
  }

  @Test
  public void testToAllGetterNames_Boolean() throws Exception {
    makeResults("myField", true, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getMyField", "isMyField")));
  }

  @Test
  public void testToAllGetterNames_Boolean_Uppercase() throws Exception {
    makeResults("MyField", true, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getMyField", "isMyField")));
  }

  @Test
  public void testToAllGetterNames_Boolean_is_Lowercase() throws Exception {
    makeResults("ismyField", true, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("isIsmyField", "getIsmyField")));
  }

  @Test
  public void testToAllGetterNames_Boolean_is_Uppercase() throws Exception {
    makeResults("isMyField", true, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("isIsMyField", "getIsMyField", "getMyField", "isMyField")));
  }

  @Test
  public void testToAllGetterNames_Boolean_IS() throws Exception {
    makeResults("ISmyField", true, DEFAULT_ACCESSORS);

    assertThat(result, is(Arrays.asList("getISmyField", "isISmyField")));
  }

public class Builder {
    public static void main(String[] args) {
        System.out.print("Celsius     ");
        System.out.print("Fahrenheit     ");
        System.out.print("|     Fahrenheit     ");
        System.out.println("Celsius   ");
        System.out.print("-------------------------------------------------------");
        double celsius = 40.0;
        double fahrenheit = 120.0;

        while (celsius >= 31.0 && fahrenheit >= 30.0) {
            System.out.println();
            System.out.printf("%-12.1f%-14.1f", celsius, celsiusToFahrenheit(celsius));
            System.out.printf(" |%10.1f%15.2f", fahrenheit, fahrenheitToCelsius(fahrenheit));

            celsius -= 1.0;
            fahrenheit -= 10.0;

        }
    }

    public static double celsiusToFahrenheit(double celsius) {
        return (9.0 / 5) * celsius + 32;
    }

    public static double fahrenheitToCelsius(double fahrenheit) {
        return (5.0 / 9) * (fahrenheit - 32);
    }
}

private void putElement(final String elemName, final Attributes atts, final boolean removeConref) throws SAXException {

        final Set<String> namespaces = new HashSet<>();
        try {
            pushcontentWriter.writeStartElement(elemName);
            for (int index = 0; index < atts.getLength(); index++) {
                final String name = atts.getQName(index);
                if (!removeConref ||
                        !ATTRIBUTE_NAME_CONREF.equals(name) && !ATTRIBUTE_NAME_CONACTION.equals(name)) {
                    String value = atts.getValue(index);
                    if (ATTRIBUTE_NAME_HREF.equals(name) || ATTRIBUTE_NAME_CONREF.equals(name)) {

                        value = replaceURL(value);
                    }
                    final int offset = atts.getQName(index).indexOf(":");
                    final String prefix = offset != -1 ? atts.getQName(index).substring(0, offset) : "";
                    if (!namespaces.contains(prefix)) {
                        namespaces.add(prefix);
                        if (!prefix.isEmpty()) {
                            pushcontentWriter.writeNamespace(prefix, atts.getURI(index));
                        }
                    }
                    pushcontentWriter.writeAttribute(prefix, atts.getURI(index), atts.getLocalName(index), value);
                }
            }

            if (ATTR_CONACTION_VALUE_PUSHREPLACE.equals(pushType) &&
                    atts.getValue(ATTRIBUTE_NAME_ID) == null &&
                    level == 1) {
                final String fragment = target.getFragment();
                if (fragment == null) {

                    logger.error(MessageUtils.getMessage("DOTJ041E", target.toString()).toString());
                } else {
                    String id;

                    if (fragment.contains(SLASH)) {
                        id = fragment.substring(fragment.lastIndexOf(SLASH) + 1);
                    } else {
                        id = fragment;
                    }

                    pushcontentWriter.writeAttribute(ATTRIBUTE_NAME_ID, id);
                }
            }
        } catch (final XMLStreamException e) {
            throw new SAXException(e);
        }
    }

import java.util.Scanner;

public class CrapsGame {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        int point = 0;
        int sum = rollDice();

        if (sum == 2 || sum == 3 || sum == 12) {
            System.out.println("You rolled " + sum + ". You lose.");
        } else if (sum == 7 || sum == 11) {
            System.out.println("You rolled " + sum + ". You win.");
        } else {
            point = sum;
            System.out.println("You rolled " + sum + ". Point is " + point + ".");
            sum = rollDice();

            while (sum != 7 && sum != point) {
                System.out.println("You rolled " + sum + ".");
                sum = rollDice();
            }

            if (sum == 7) {
                System.out.println("You rolled " + sum + ". You lose.");
            } else {
                System.out.println("You rolled " + sum + ". You win.");
            }
        }
    }

    public static int rollDice() {
        int die1 = (int) (Math.random() * 6) + 1;
        int die2 = (int) (Math.random() * 6) + 1;
        int sum = die1 + die2;
        System.out.println("You rolled " + die1 + " + " + die2 + " = " + sum);
        return sum;
    }
}

import java.util.Arrays;
 
public class Median {
 
    // inputs must be random-access iterators of doubles
    // Note: this function modifies the input range
    public static double median(double[] a, int begin, int end) {
        // this is middle for odd-length, and "upper-middle" for even length
        int middle = begin + (end - begin) / 2;
 
        // This function runs in O(n) on average, according to the standard
        Arrays.sort(a, begin, end);
 
        if ((end - begin) % 2!= 0) { // odd length
            return a[middle];
        } else { // even length
            // the "lower middle" is the max of the lower half
            int lower_middle = Arrays.binarySearch(a, begin, middle, a[middle]);
            return (a[middle] + a[lower_middle]) / 2.0;
        }
    }
 
    public static void main(String[] args) {
        double[] a = {4.1, 5.6, 7.2, 1.7, 9.3, 4.4, 3.2};
        double[] b = {4.1, 7.2, 1.7, 9.3, 4.4, 3.2};
 
        System.out.println(median(a, 0, a.length)); // 4.4
        System.out.println(median(b, 0, b.length)); // 4.25
    }
}

import java.util.Arrays;
 
public class DiversityTheorem {
    public static double averageSquareDiff(double f, double[] preds) {
        double av = 0.0;
        for (double pred : preds) {
            av += (pred - f) * (pred - f);
        }
        av /= preds.length;
        return av;
    }
 
    public static double[] diversityTheorem(double truth, double[] preds) {
        double av = 0.0;
        for (double pred : preds) {
            av += pred;
        }
        av /= preds.length;
        double avErr = averageSquareDiff(truth, preds);
        double crowdErr = (truth - av) * (truth - av);
        double div = averageSquareDiff(av, preds);
        return new double[]{avErr, crowdErr, div};
    }
 
    public static void main(String[] args) {
        double[][] predsArray = new double[][]{{48, 47, 51}, {48, 47, 51, 42}};
        double truth = 49.0;
        for (double[] preds : predsArray) {
            double[] result = diversityTheorem(truth, preds);
            System.out.printf("Average-error : %6.3f\n", result[0]);
            System.out.printf("Crowd-error   : %6.3f\n", result[1]);
            System.out.printf("Diversity     : %6.3f\n\n", result[2]);
        }
    }
}

