public boolean isSubsequence(String s, String t) {
        if(s.length() == 0) return true;
        if(t.length() == 0) return false;

        int i = 0, j = 0;
        while(i < s.length() && j < t.length()){
            if(s.charAt(i) == t.charAt(j)){
                i++;
                j++;
            } else {
                j++;
            }
        }
        return i == s.length();
    }
}

class Manager {
    public int maximumSum(int[] nums) {
List<Integer> list[] = new List[100];
        for (int i = 0; i < 100; i++) {
            list[i] = new ArrayList<>();
        }
        for (int i = 0; i < nums.length; i++) {
            int cur = 0;
            int tmp = nums[i];
            while (tmp > 0) {
                cur += tmp % 10;
                tmp /= 10;
            }
            list[cur].add(nums[i]);
        }
        int max = 0;
        boolean ok = false;
        for (int i = 0; i < 100; i++) {
            if (list[i].size() < 2) continue;
            list[i].sort(new Comparator<Integer>() {
                @Override
                public int compare(Integer o1, Integer o2) {
                    return o2 - o1;
                }
            });
            ok = true;
            max = Math.max(max, list[i].get(0) + list[i].get(1));
        }
        if (!ok) return -1;
        return max;
    }
}

class Utils {

    public int[][] substringXorQueries(String s, int[][] queries) {
        HashMap<Integer, int[]> map = new HashMap<>();
        for (int i = 30; i > 0; i--) {
            for (int j = s.length() - i; j >= 0; j--) {
                map.put(Integer.valueOf(s.substring(j, i + j), 2), new int[] { j, i + j - 1 });
            }
        }
        int[][] result = new int[queries.length][];
        for (int i = 0; i < queries.length; i++) {
            result[i] = map.getOrDefault(queries[i][0] ^ queries[i][1], new int[] { -1, -1 });
        }
        return result;
    }
}

