public static int[] locateLargest(double[][] a) {
    int[] result = {0, 0};
    double max = a[0][0];
    for (int i = 0; i < a.length; i++) {
        for (int j = 0; j < a[i].length; j++) {
            if (a[i][j] > max) {
                max = a[i][j];
                result[0] = i;
                result[1] = j;
            }
        }
    }
    return result;
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
import java.util.stream.Stream;
 
public class Integer {
 
    public static List<Integer> properDivisors(int n) {
        if (n == 1) {
            return new ArrayList<>();
        }
        List<Integer> primes = primeDivision(n).stream()
               .flatMap(p -> Stream.generate(() -> p).limit(p.getValue()))
               .collect(Collectors.toList());
        return IntStream.range(1, primes.size())
               .mapToObj(n -> primes.subList(0, n))
               .flatMap(combi -> combi.stream().reduce(1, (a, b) -> a * b))
               .boxed()
               .collect(Collectors.toList());
    }
 
    public static List<Pair<Integer, Integer>> generatorOddAbundants(int from) {
        if (from % 2 == 0) {
            from++;
        }
        return IntStream.iterate(from, n -> n + 2)
               .mapToObj(n -> new Pair<>(n, properDivisors(n).stream().reduce(0, (a, b) -> a + b)))
               .filter(p -> p.getValue() > p.getKey())
               .collect(Collectors.toList());
    }
 
    public static List<Pair<Integer, Integer>> generatorOddAbundants() {
        return generatorOddAbundants(1);
    }
 
    public static List<Pair<Integer, Integer>> generatorOddAbundants(long from) {
        return generatorOddAbundants((int) from);
    }
 
    public static void main(String[] args) {
        generatorOddAbundants().stream().limit(25).forEach(p -> System.out.println(p.getKey() + " with sum " + p.getValue()));
        System.out.println("\n" + generatorOddAbundants().get(999).getKey() + " with sum " + generatorOddAbundants().get(999).getValue());
        System.out.println("\n" + generatorOddAbundants(1_000_000_000).get(0).getKey() + " with sum " + generatorOddAbundants(1_000_000_000).get(0).getValue());
    }
 
    private static List<Pair<Integer, Integer>> primeDivision(int n) {
        List<Pair<Integer, Integer>> result = new ArrayList<>();
        int prime = 2;
        while (n > 1) {
            int freq = 0;
            while (n % prime == 0) {
                n /= prime;
                freq++;
            }
            if (freq > 0) {
                result.add(new Pair<>(prime, freq));
            }
            prime = nextPrime(prime);
        }
        return result;
    }
 
    private static int nextPrime(int n) {
        if (n == 2) {
            return 3;
        }
        int next = n + 2;
        while (!isPrime(next)) {
            next += 2;
        }

import java.io.File;
import java.io.FileOutputStream;
import java.io.OutputStream;
import java.util.ArrayList;

public class ReduceConllResponse {

    public static void main(String[] args) {
        String pathToKeyFolder = "path/to/key/folder";
        String pathToResponseFolder = "path/to/response/folder";

        ArrayList<File> keyFiles = Util.makeFlatFileList(new File(pathToKeyFolder), ".conll");
        ArrayList<File> responseFiles = Util.makeFlatFileList(new File(pathToResponseFolder), ".conll");

        for (File keyFile : keyFiles) {
            ArrayList<String> sentenceIds = Util.getSentenceIdsConllFile(keyFile);
            String firstSentenceKey = Util.readFirstSentence(keyFile);
            boolean MATCH = false;

            for (File responseFile : responseFiles) {
                String firstSentenceResponse = Util.readFirstSentence(responseFile);

                if (firstSentenceKey.equals(firstSentenceResponse)) {
                    MATCH = true;
                    ArrayList<String> reducedResponse = Util.reduceConllFileForSentenceIds(responseFile, sentenceIds);

                    try (OutputStream os = new FileOutputStream(responseFile)) {
                        for (String line : reducedResponse) {
                            os.write((line + "\n").getBytes());
                        }
                    } catch (Exception e) {
                        e.printStackTrace();
                    }
                    break;
                }
            }

            if (!MATCH) {
                System.out.println("No matching response file found for key file: " + keyFile.getName());
            }
        }
    }
}

public class LCS {
    public static String lcs(String a, String b) {
        String aSub = a.substring(0, a.length() - 1);
        String bSub = b.substring(0, b.length() - 1);

        if (a.length() == 0 || b.length() == 0) {
            return "";
        } else if (a.charAt(a.length() - 1) == b.charAt(b.length() - 1)) {
            return lcs(aSub, bSub) + a.charAt(a.length() - 1);
        } else {
            String x = lcs(a, bSub);
            String y = lcs(aSub, b);
            return (x.length() > y.length())? x : y;
        }
    }
}

