import java.util.Iterator;

public static <E extends Comparable<E>> E minimum(Iterator<E> iterator, E init) {
    E min = init;
    while (iterator.hasNext()) {
        E next = iterator.next();
        if (next.compareTo(min) < 0) {
            min = next;
        }
    }
    return min;
}

