class Helper {
    public List<Integer> fallingSquares(int[][] positions) {
        TreeSet<List<Integer>> bottomLine = new TreeSet<>(new Comparator<List<Integer>>() {
            @Override
            public int compare(List<Integer> a, List<Integer> b) {
                return a.get(0) - b.get(0);
            }
        });
        List<Integer> result = new ArrayList<>();

        for (int[] position : positions) {
            int left = position[0], right = position[0] + position[1] - 1, height = position[1];

            int maxHeight = 0;
            List<Integer> leftmost = null, rightmost = null;

            Iterator<List<Integer>> iterator = bottomLine.iterator();
            while (iterator.hasNext()) {
                List<Integer> square = iterator.next();

                if (right >= square.get(0) && left <= square.get(1)) {
                    if (square.get(0) < left) {
                        leftmost = square;
                    }
                    rightmost = square;
                    maxHeight = Math.max(maxHeight, square.get(2));

                    iterator.remove();
                }
            }

            if (maxHeight == 0) {
                bottomLine.add(Arrays.asList(left, right, height));

                if (result.isEmpty()) {
                    result.add(height);
                } else {
                    result.add(Math.max(result.get(result.size() - 1), height));
                }
            } else {
                if (leftmost != null) {
                    bottomLine.add(Arrays.asList(leftmost.get(0), left - 1, leftmost.get(2)));
                }
                if (rightmost != null) {
                    bottomLine.add(Arrays.asList(right + 1, rightmost.get(1), rightmost.get(2)));
                }

                bottomLine.add(Arrays.asList(left, right, maxHeight + height));

                result.add(Math.max(result.get(result.size() - 1), maxHeight + height));
            }
        }

        return result;
    }
}

public boolean hasText() {
        for (Node child: childNodes) {
            if (child instanceof TextNode) {
                TextNode textNode = (TextNode) child;
                if (!textNode.isBlank())
                    return true;
            } else if (child instanceof Element) {
                Element el = (Element) child;
                if (el.hasText())
                    return true;
            }
        }
        return false;
    }

class Writer {
    public int[] findMissingAndRepeatedValues(int[][] grid) {
        int n = grid.length;
        int[] ans = new int[2];
        boolean[] vis = new boolean[n * n + 1];
        for(int i = 0; i < n; i ++) {
            for(int j = 0; j < n; j++) {
                if(vis[grid[i][j]]) {
                    ans[0] = grid[i][j];
                } else {
                    vis[grid[i][j]] = true;
                }
            }
        }
        for(int i = 1; i <= n * n; i ++) {
            if(!vis[i]) {
                ans[1] = i;
            }
        }
        return ans;
    }
}

/*
 * Models a 24-hour digital clock that can tick forward second by
 * second, cascading into minutes and hours as needed.
 */
public class DijitalSaat {

    private int saatDegeri = 0;
    private int dakikaDegeri = 0;
    private int saniyeDegeri = 0;

    public int getSaniye() {
        return this.saniyeDegeri;
    }

    // Only accepts values within the valid 0-59 range.
    public void setSaniye(int saniyeDegeri) {
        if (saniyeDegeri >= 0 && saniyeDegeri < 60) {
            this.saniyeDegeri = saniyeDegeri;
        }
    }

    // Prints the current time as saat:dakika:saniye.
    public void goster() {
        System.out.println(saatDegeri + ":" + dakikaDegeri + ":" + saniyeDegeri);
    }

    // Rolls the hour over back to 0 after 23.
    private void saatiArttir() {
        saatDegeri = saatDegeri + 1;
        if (saatDegeri > 23) {
            saatDegeri = 0;
        }
    }

    // Rolls the minute over after 59, cascading into the hour.
    private void dakikayiArttir() {
        dakikaDegeri = dakikaDegeri + 1;
        if (dakikaDegeri > 59) {
            dakikaDegeri = 0;
            saatiArttir();
        }
    }

    // Advances one second, cascading into minute/hour as needed.
    public void saniyeyiArttir() {
        saniyeDegeri = saniyeDegeri + 1;
        if (saniyeDegeri > 59) {
            saniyeDegeri = 0;
            dakikayiArttir();
        }
    }

    // Directly overwrites the clock with a new time.
    public void saatiGuncelle(int saatDegeri, int dakikaDegeri, int saniyeDegeri) {
        this.saatDegeri = saatDegeri;
        this.dakikaDegeri = dakikaDegeri;
        this.saniyeDegeri = saniyeDegeri;
    }

    public static void main(String[] args) {
        DijitalSaat saatNesnesi = new DijitalSaat();

        saatNesnesi.saatiGuncelle(10, 58, 50);
        System.out.println("Baslangic saati:");
        saatNesnesi.goster();

        for (int adim = 0; adim < 70; adim++) {
            saatNesnesi.saniyeyiArttir();
            System.out.print("Saniye " + (adim + 1) + ": ");
            saatNesnesi.goster();
        }

        System.out.println("\nSaati bir saat ileri aliyoruz...");
        for (int adim = 0; adim < 120; adim++) {
            saatNesnesi.saniyeyiArttir();
        }
        System.out.print("Yeni saat: ");
        saatNesnesi.goster();
    }
}

import java.util.Random;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;
 
public class Buckets {
 
    private static final int N_BUCKETS = 15;
 
    private static final Lock[] bucket_mutex = new Lock[N_BUCKETS];
    private static final int[] buckets = new int[N_BUCKETS];
 
    private static final Random random = new Random();
 
    private static final Thread equalizer = new Thread(new Equalizer());
    private static final Thread randomizer = new Thread(new Randomizer());
 
    private static void transfer_value(int from, int to, int howmuch) {
        boolean swapped = false;
 
        if ( (from == to) || ( howmuch < 0 ) ||
             (from < 0 ) || (to < 0) || (from >= N_BUCKETS) || (to >= N_BUCKETS) ) return;
 
        if ( from > to ) {
            int temp1 = from;
            from = to;
            to = temp1;
            swapped = true;
            howmuch = -howmuch;
        }
 
        bucket_mutex[from].lock();
        bucket_mutex[to].lock();
 
        if ( howmuch > buckets[from] &&!swapped )
            howmuch = buckets[from];
        if ( -howmuch > buckets[to] && swapped )
            howmuch = -buckets[to];
 
        buckets[from] -= howmuch;
        buckets[to] += howmuch;
 
        bucket_mutex[from].unlock();
