public static int countDigit(int d, int low, int high) {
    long start = 1;
    long end = high;
    int res = 0;
    for(int i = 0; i < 19; i++){
        long mid = (start + end) / 2;
        if(mid * mid > high)
            break;
        if((mid % 10 == d) || ((mid / 10) % 10 == d) || ((mid / 100) % 10 == d))
            res += (mid - mid/10 + 1);
        start = mid + 1;
    }
    return res;
}

