class Order {
    public long minimumRemoval(int[] beans) {
        Arrays.sort(beans);
        int length = beans.length;
        if (length == 1)
            return 0;
        if (length == 2)
            return (long) Math.min(beans[0], beans[1] - beans[0]);
        long[] prefixSums = new long[length];
        prefixSums[0] = beans[0];
        for (int i = 1; i < length; i++)
            prefixSums[i] = prefixSums[i - 1] + beans[i];
        long[] postfixRemoves = new long[length];
        for (int i = length - 2; i >= 0; i--)
            postfixRemoves[i] = postfixRemoves[i + 1] + (long) (beans[i + 1] - beans[i]) * (length - 1 - i);
        long minRemove = prefixSums[length - 1];
        minRemove = Math.min(minRemove, postfixRemoves[0]);
        for (int i = length - 1; i >= 1; i--) {
            long curRemove = prefixSums[i - 1] + postfixRemoves[i];
            minRemove = Math.min(minRemove, curRemove);
        }
        return minRemove;
    }
}

import java.util.Random;

public class Sorter {
    public static double MonteCarloPi(int n) {
        int inside = 0;
        Random r = new Random();

        for (int i = 0; i < n; i++) {
            if (Math.pow(r.nextDouble(), 2) + Math.pow(r.nextDouble(), 2) <= 1) {
                inside++;
            }
        }

        return 4.0 * inside / n;
    }

    public static void main(String[] args) {
        int value = 1000;
        for (int n = 0; n < 5; n++) {
            value *= 10;
            System.out.println(String.format("%11s:%s", String.format("%,d", value), MonteCarloPi(value)));
        }
    }
}

