private static ChannelBuffer createDataTerminatingChannelBuffer(byte[] data) {
        int length = data.length;
        if (length < 1) {
            return ChannelBuffers.wrappedBuffer(CRLF_DOT_CRLF);
        } else {
            byte[] terminating;

            byte last = data[length -1];

            if (length == 1) {
                if (last == CR) {
                    terminating = LF_DOT_CRLF;
                } else {
                    terminating = CRLF_DOT_CRLF;
                }
            } else {
                byte prevLast = data[length - 2];

                if (last == LF) {
                    if (prevLast == CR) {
                        terminating = DOT_CRLF;
                    } else {
                        terminating = CRLF_DOT_CRLF;
                    }
                } else if (last == CR) {
                    terminating = LF_DOT_CRLF;
                } else {
                    terminating = CRLF_DOT_CRLF;

                }
            }
            return ChannelBuffers.wrappedBuffer(data, terminating);
        }

    }

import java.io.*;
import java.net.*;

public void downloadFile(String stringUrl, String parameters, File fileToSave) throws IOException {

    URL url = new URL(stringUrl);
    HttpURLConnection connection = (HttpURLConnection) url.openConnection();

    connection.setRequestMethod("GET");

    // set headers if any
    if(parameters != null && !parameters.isEmpty()) {
        String[] headers = parameters.split(",");
        for(String header: headers) {
            String[] headerValues = header.split(":");
            connection.setRequestProperty(headerValues[0], headerValues[1]);
        }
    }

    InputStream inputStream = connection.getInputStream();

    FileOutputStream outputStream = new FileOutputStream(fileToSave);

    byte[] buffer = new byte[4096];
    int bytesRead = -1;
    while ((bytesRead = inputStream.read(buffer)) != -1) {
        outputStream.write(buffer, 0, bytesRead);
    }

    outputStream.close();
    inputStream.close();

    System.out.println("File downloaded successfully!");
}

