public class D1 {
    static int[] dx = {1, -1, 0, 0};
    static int[] dy = {0, 0, 1, -1};
    public static void main (String[] args) throws IOException {
        Kattio io = new Kattio();
        int n = io.nextInt();
        HashSet<Long> set = new HashSet<Long>();
        Long[] arr = new Long[n];
        for (int i=0; i<n; i++) {
            int x = io.nextInt();
            int y = io.nextInt();
            set.add(val(x, y));
            arr[i] = val(x, y);
            //set.add(new Point(x, y));
            //arr[i] = new Point(x, y);
        }
        HashMap<Long, Long> map = new HashMap<Long, Long>();

        Queue<Long> bfs = new LinkedList<>();
        for (long p : set) {
            long x = p/1000000;
            long y = p%1000000;
            for (int i=0; i<4; i++) {
                long xx = x + dx[i];
                long yy = y + dy[i];
                if (!set.contains(val(xx, yy))) {
                    map.put(p, val(xx, yy));
                    bfs.add(p);
                    break;
                }
            }
        }
        while (!bfs.isEmpty()) {
            long p = bfs.poll();
            long x = p/1000000;
            long y = p%1000000;
            for (int i=0; i<4; i++) {
                long xx = x + dx[i];
                long yy = y + dy[i];
                long pp = val(xx, yy);
                if (set.contains(pp) && !map.containsKey(pp)) {
                    bfs.add(pp);
                    map.put(pp, map.get(p));
                }
            }
        }

        for (int i=0; i<n; i++) {
            long p = arr[i];
            long ans = map.get(p);
            io.println(ans/1000000 + " " + ans%1000000);
        }
        io.close();
    }

