class Runner {
    List<Integer> lists[];
    public int squareFreeSubsets(int[] nums) {
        lists = new ArrayList[31];
        Arrays.setAll(lists, a->new ArrayList<>());
        for(int i = 2;i<31;i++){
            int t = i;
            for(int j = 2;j*j<=t;j++){
                if(t%j==0){
                    while(t%j==0)t/=j;
                    lists[i].add(j);
                }
            }
            if(t>1)lists[i].add(t);
        }
        int mod = (int)1e9+7;
        int[] cnt = new int[31];
        for(int a : nums)cnt[a]++;
        int[] arr = new int[]{1, 2, 3, 5, 6, 7, 10, 11, 13, 14, 15, 17, 19, 21, 22, 23, 26, 29, 30};
        // int[] pos = new int[31];
        // for(int i = 0;i<19;i++)pos[arr[i]] = i;
        long re = 0;
        for(int i = 1; i<1<<19; i++){
            int[] tmp = new int[31];
            boolean flag = true;
            long tt = 1;
            for(int j = 0; j<19; j++){
                if(((i>>j)&1) == 1){
                    if(cnt[arr[j]]==0){
                        flag = false;
                        break;
                    }
                    for(int x : lists[arr[j]])if(x>0 && tmp[x]++ > 0) {
                        flag = false;
                        break;
                    }
                    if(j==0)tt = tt * ((qmi(2, cnt[1],mod) - 1 + mod)%mod) % mod;
                    else tt = (tt * cnt[arr[j]]) % mod;
                }
            }
            if (flag){
                re = (re + tt)%mod;
                // System.out.println(i + " " + tt);
            }
        }
        return (int)(re%mod);
    }
    static int qmi(long a, int b, int p) {
        long ans = 1;
        a = (a % p + p) % p;
        for (; b>0; b >>= 1) {
            if ((b & 1)!=0) ans = (a * ans) % p;
            a = (a * a) % p;
        }
        return (int)ans;
    }
}

