    byte[] encryptedPayload = Arrays.copyOfRange(cipherData, INIT_VECTOR_SIZE, cipherData.length - SIGNATURE_SIZE);
    byte[] signature = Arrays.copyOfRange(cipherData, cipherData.length - SIGNATURE_SIZE, cipherData.length);

    // Decrypt the payload using the initialization vector
    byte[] decryptedPayload = decryptPayload(encryptedPayload, initVector);

    // Verify the signature
    if (!verifySignature(initVector, decryptedPayload, signature)) {
        throw new SignatureException("Signature verification failed");
    }

    // Return the initialization vector, decrypted payload, and the original signature
    return concatenate(initVector, decryptedPayload, signature);
}

