import android.content.Context;
import android.support.v7.widget.RecyclerView;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.TextView;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;
import java.util.ArrayList;
import java.util.List;

public class RSSAdapter extends RecyclerView.Adapter<RSSAdapter.ArticleViewHolder> implements DocumentConsumer {
    private List<ItemEntity> rssFI = new ArrayList<>();
    private Context context;
    private String feedId;

    public RSSAdapter(Context context, String feedId) {
        this.context = context;
        this.feedId = feedId;
        refreshData();
    }

    @Override
    public void setXMLDocument(Document document) {
        parseDocument(document);
        refreshData();
    }

    private void parseDocument(Document document) {
        List<ItemEntity> items = new ArrayList<>();
        NodeList itemNodes = document.getElementsByTagName("item");
        for (int i = 0; i < itemNodes.getLength(); i++) {
            Element item = (Element) itemNodes.item(i);
            items.add(new ItemEntity(
                getElementValue(item, "title"),
                getElementValue(item, "description"),
                getElementValue(item, "link"),
                getElementValue(item, "pubDate"),
                feedId
            ));
        }
        ItemEntity.deleteByFeedId(feedId);
        ItemEntity.insertAll(items);
    }

    private String getElementValue(Element element, String tagName) {
        NodeList nodes = element.getElementsByTagName(tagName);
        return nodes.getLength() > 0 ? nodes.item(0).getTextContent() : "";
    }

    private void refreshData() {
        rssFI = ItemEntity.getAllForFeed(feedId);
        notifyDataSetChanged();
    }

    @Override
    public ArticleViewHolder onCreateViewHolder(ViewGroup parent, int viewType) {
        View view = LayoutInflater.from(context).inflate(R.layout.item_article, parent, false);
        return new ArticleViewHolder(view);
    }

    @Override
    public void onBindViewHolder(ArticleViewHolder holder, int position) {
        ItemEntity item = rssFI.get(position);
        holder.title.setText(item.getTitle());
        holder.description.setText(item.getDescription());
        holder.date.setText(item.getPubDate());
        holder.link.setText(item.getLink());
    }

    @Override
    public int getItemCount() {
        return rssFI.size();
    }

    static class ArticleViewHolder extends RecyclerView.ViewHolder {

