// IWMPMedia interface that defines the behaviors and properties of media items
public interface IWMPMedia {

    // Get the duration of the media item in seconds
    long getDuration();

    // Get the source URL of the media item
    String getSourceURL();

    // Set the source URL of the media item
    void setSourceURL(String sourceURL);

    // Get the name of the media item
    String getName();

    // Set the name of the media item
    void setName(String name);

    // Get the attribute name by index
    String getAttributeName(int index);

    // Get the number of attributes
    int getAttributeCount();

    // Gets a specific attribute value by index
    String getAttribute(int index);

    // Set a specific attribute value by index
    void setAttribute(int index, String value);

    // Check if the attribute is read-only
    boolean isAttributeReadOnly(int index);

    // Get the image source width
    int getImageSourceWidth();

    // Get the image source height
    int getImageSourceHeight();

    // Retrieve media information as a formatted string
    String getItemInfo(String name);

    // Set media information with a name-value pair
    void setItemInfo(String name, String value);

    // Check if this media item is a member of a given playlist
    boolean isMemberOf(String playlistName);

    // Get the marker time by index
    long getMarkerTime(int index);

    // Get the marker count for the media item
    int getMarkerCount();

    // Retrieve specific marker information using the marker index
    String getMarkerInfo(int index);

    // Get the name associated with the media item
    String getShortName();

    // Get the media type (e.g., audio, video)
    String getMediaType();

    // Get the album from which the media item comes
    String getAlbumName();

    // Get the artist associated with the media item
    String getArtistName();

    // Set the album name for the media item
    void setAlbumName(String albumName);

    // Set the artist name for the media item
    void setArtistName(String artistName);

    // Get the year when the media item was released
    int getReleaseYear();

    // Set the release year for the media item
    void setReleaseYear(int year);

    // Get the genre of the media item
    String getGenre();

    // Set the genre for the media item
    void setGenre(String genre);

    // Get custom data associated with the media item
    String getCustomData(String key);

    // Set custom data associated with the media item
    void setCustomData(String key, String value);

