import java.util.ArrayList;
import java.util.List;
 
public class Bell {
    private static class BellTriangle {
        private List<Integer> arr;
 
        BellTriangle(int n) {
            int length = n * (n + 1) / 2;
            arr = new ArrayList<>(length);
            for (int i = 0; i < length; ++i) {
                arr.add(0);
            }
 
            set(1, 0, 1);
            for (int i = 2; i <= n; ++i) {
                set(i, 0, get(i - 1, i - 2));
                for (int j = 1; j < i; ++j) {
                    int value = get(i, j - 1) + get(i - 1, j - 1);
                    set(i, j, value);
                }
            }
        }
 
        private int index(int row, int col) {
            if (row > 0 && col >= 0 && col < row) {
                return row * (row - 1) / 2 + col;
            } else {
                throw new IllegalArgumentException();
            }
        }
 
        public int get(int row, int col) {
            int i = index(row, col);
            return arr.get(i);
        }
 
        public void set(int row, int col, int value) {
            int i = index(row, col);
            arr.set(i, value);
        }
    }
 
    public static void main(String[] args) {
        final int rows = 15;
        BellTriangle bt = new BellTriangle(rows);
 
        System.out.println("First fifteen Bell numbers:");
        for (int i = 0; i < rows; ++i) {
            System.out.printf("%2d: %d\n", i + 1, bt.get(i + 1, 0));
        }
 
        for (int i = 1; i <= 10; ++i) {
            System.out.print(bt.get(i, 0));
            for (int j = 1; j < i; ++j) {
                System.out.printf(", %d", bt.get(i, j));
            }
            System.out.println();
        }
    }
}

class Logger {
    public String largestMultipleOfThree(int[] digits) {
        int n = digits.length;
        int[] a = new int[10];
        int sum = 0;
        for (int i=0; i<n; i++) {
            a[digits[i]]++;
            sum += digits[i];
        }
        if (sum % 3 == 1) {
            if (a[1] > 0)
                a[1]--;
            else if (a[4] > 0)
                a[4]--;
            else if (a[7] > 0)
                a[7]--;
            else {
                int x = 2;
                int i = 2;
                while (i<10 && x > 0) {
                    while (a[i] > 0 && x > 0) {
                        a[i]--;
                        x--;
                    }
                    i += 3;
                }
                if (x > 0)
                    return "";
            }
        }
        else if (sum % 3 == 2) {
            if (a[2] > 0)
                a[2]--;
            else if (a[5] > 0)
                a[5]--;
            else if (a[8] > 0)
                a[8]--;
            else {
                int x = 2;
                int i = 1;
                while (i<10 && x > 0) {
                    while (a[i] > 0 && x > 0) {
                        a[i]--;
                        x--;
                    }
                    i += 3;
                }
                if (x > 0)
                    return "";
            }
        }
        int i = 9;
        boolean z = true;
        boolean y = true;
        StringBuilder sb = new StringBuilder();
        while (i >= 0) {
            while (a[i] > 0) {
                if (i>0)
                    z = false;
                else y = false;
                a[i]--;
                sb.append(i);
            }
            i--;
        }
        if (z) return y ? "" : "0";
        return sb.toString();
    }
}

class Stack {
    public int minMoves(int target, int maxDoubles) {
        int remain = maxDoubles;
        int res = 0;
        while (target != 1 && remain > 0) {
            if (target % 2 == 1) {
                res += 1;
                target -= 1;
            }
            target /= 2;
            res += 1;
            remain -= 1;
        }
        if (target != 1) {
            res += target - 1;
        }
        return res;
    }
}

