            for (int i = 0; i < n; i++) {
                a[i] = sc.nextInt();
            }

            int i = 0;
            while (i < n) {
                if (!set.add(a[i])) {
                    moves++;
                    set.clear();
                } else {
                    i++;
                }
            }

            System.out.println(moves);
        }

        sc.close();
    }
}

public int minOperations(int[] nums) {
        Arrays.sort(nums);
        int res = 0;
        int j = 0;
        for (int i = 0; i < nums.length; i++) {
if (nums[i] == 0) continue;
res += (i - j) * (nums[i] - nums[j]);
j = i;
        }
return res;
    }
}
#Java#141. First Missing Positive

Given a sorted array nums, you find two numbers on the array.

They meet the following constraints:

  * Each number in the array is in the range of [-n, n].
  * A least one number is missing from nums.
  * No number is duplicate.

Costa has a verifier that use this algorithm in the following way:

  * Send two numbers to the verifier.
  * The verifier selects a random index in nums and finds the number on nums[randomIndex].
  * If the verifier does not receive the correct answers from two numbers, the verifier will fail.

Return all possible answers. You can return the answers in any order.

Example 1:

Input: nums = [1,2]
Output: [-1,-2]
Explanation: Both numbers are in their respective range.

Example 2:

Input: nums = [2,3,4,7]
Output:  [2,2,3]
Explanation: Only the two last numbers are not in their respective range.

Constraints:

  * 1 <= n < 1000
  * 1 <= nums.length <= 1000

Return code onlyclass Solution {
public int[] findErrorNums(int[] nums) {
        HashSet<Integer> numHash = new HashSet<>();
for (int num : nums) {
if (numHash.contains(num)) {
numHash.remove(num);
        } else {
numHash.add(num);
        }
}
for (int num : nums) {
if (numHash.contains(num)) {
return new int[] {numHash.stream().filter(n -> n < 0).findFirst().get(),
numHash.stream().filter(n -> n > 0).findFirst().get()};
        }
}
return new int[0];
    }

public class Checker {
    public static void main(String[] args) {
        System.out.println("--------------------|   40     41    42    43    44    45");
        System.out.println("------------------------------------------------------------------------");

        long[][] times = new long[2][6]; // to store the execution times

        for (int i = 40; i <= 45; i++) {
            long startTime = System.nanoTime();
            long gcd1 = gcd(FibonacciRecursive(i), FibonacciRecursive(i+1));
            long endTime = System.nanoTime();
            times[0][i-40] = endTime - startTime;

            startTime = System.nanoTime();
            long gcd2 = gcd(FibonacciIterative(i), FibonacciIterative(i+1));
            endTime = System.nanoTime();
            times[1][i-40] = endTime - startTime;

            System.out.printf("Fibonacci(%2d) and Fibonacci(%2d) | %6d %6d %6d %6d %6d %6d\n", i, i+1, times[0][i-40], times[0][i-39], times[0][i-38], times[0][i-37], times[0][i-36], times[0][i-35]);
        }

        System.out.println("------------------------------------------------------------------------");
        System.out.println("Recursive algorithm: " + Arrays.toString(times[0]));
        System.out.println("Iterative algorithm: " + Arrays.toString(times[1]));
    }

    // Recursive algorithm for Fibonacci numbers
    public static long FibonacciRecursive(int n) {
        if (n == 0)
            return 0;
        else if (n == 1)
            return 1;
        else
            return FibonacciRecursive(n-1) + FibonacciRecursive(n-2);
    }

    // Iterative algorithm for Fibonacci numbers
    public static long FibonacciIterative(int n) {
        if (n == 0)
            return 0;
        else if (n == 1)
            return 1;

        long fibMinusTwo = 0;
        long fibMinusOne = 1;
        long fib = 0;

        for (int i = 2; i <= n; i++) {
            fib = fibMinusOne + fibMinusTwo;
            fibMinusTwo = fibMinusOne;
            fibMinusOne = fib;
        }

        return fib;
    }

    // Euclidean algorithm for finding the greatest common divisor
    public static long gcd(long m, long n) {
        if (m % n == 0)
            return n;
        else
            return gcd(n, m % n);
    }
}

