class Task {
    public int[] countRectangles(int[][] rectangles, int[][] points) {
        int[][] mypoints = new int[points.length][3];
        for(int i = 0; i < points.length; i++){
            mypoints[i][0] = points[i][0];
            mypoints[i][1] = points[i][1];
            mypoints[i][2] = i;
        }
        Arrays.sort(mypoints, (a, b) -> {
            if(a[0] < b[0]) return - 1;
            else if(a[0] > b[0]) return 1;
            else if(a[1] < b[1]) return -1;
            else if(a[1] > b[1]) return 1;
            else return a[2] - b[2];
        });

        Arrays.sort(rectangles, (a, b) -> {
           if(a[0] < b[0]) return - 1;
            else if(a[0] > b[0]) return 1;
            else if(a[1] < b[1]) return -1;
            else if(a[1] > b[1]) return 1;
            return 0;
        });

        int[] ans = new int[points.length];
        int idx = 0;

        int[] height = new int[101];
        for(int i = 0; i < rectangles.length; i++){
            height[rectangles[i][1]]++;
        }
        //System.out.println(Arrays.toString(height));

        for(int i = 0; i < mypoints.length; i++){
            int x = mypoints[i][0];
            int y = mypoints[i][1];
            while(idx < rectangles.length && rectangles[idx][0] < x){
                height[rectangles[idx][1]]--;
                idx++;
            }

            for(int j = y; j <= 100; j++){
                ans[mypoints[i][2]] += height[j];
            }
        }

        return ans;
    }
}

class Runner {
    public int[] circularGameLosers(int n, int k) {
        int[] count = new int[n];
        int start = 0;
        count[start] = 1;
        int times = 1;
        while (true) {
            start = (start + k * times) % (n);
            count[start]++;
            if (count[start] > 1) {
                break;
            }
            times++;
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (count[i] == 0) {
                res.add(i + 1);
            }
        }
        int[] arr = new int[res.size()];
        for (int i = 0; i < res.size(); i++) {
            arr[i] = res.get(i);
        }
        return arr;
    }
}

