import com.gluonhq.cloudlink.client.data.DataClient;
import com.gluonhq.cloudlink.client.data.DataClientBuilder;
import com.gluonhq.cloudlink.client.data.SyncFlag;
import com.gluonhq.connect.GluonObservableObject;
import com.gluonhq.connect.ConnectState;
import com.gluonhq.connect.provider.DataProvider;
import javax.annotation.PostConstruct;
import javafx.beans.property.SimpleStringProperty;
import javafx.beans.property.StringProperty;

public class MotdService {

    private static final String MOTD_ENDPOINT = "motd";
    private static final String DEFAULT_MESSAGE = "Welcome! Check back daily for updates.";
    private DataClient cloudDataClient;
    private StringProperty currentMotd;

    @PostConstruct
    public void initializeDataClient() {
        cloudDataClient = DataClientBuilder.create()
                .entityIdentifier(MOTD_ENDPOINT)
                .syncFlag(SyncFlag.OBJECT_READ_THROUGH)
                .syncFlag(SyncFlag.AUTO_SYNC)
                .build();
        currentMotd = new SimpleStringProperty(DEFAULT_MESSAGE);
    }

    public GluonObservableObject<String> retrieveMOTD() {
        GluonObservableObject<String> cloudMotd = DataProvider.retrieveObject(
                cloudDataClient.createObjectDataReader(MOTD_ENDPOINT, String.class),
                SyncFlag.OBJECT_READ_THROUGH,
                SyncFlag.AUTO_SYNC
        );

        cloudMotd.stateProperty().addListener((obs, oldState, newState) -> {
            if (newState == ConnectState.SUCCEEDED) {
                handleCloudDataUpdate(cloudMotd.get());
            } else if (newState == ConnectState.FAILED) {
                currentMotd.set(DEFAULT_MESSAGE);
            }
        });

        cloudMotd.valueProperty().addListener((obs, oldVal, newVal) -> {
            if (newVal != null && !newVal.isEmpty()) {
                currentMotd.set(newVal);
            } else {
                currentMotd.set(DEFAULT_MESSAGE);
            }
        });

        return cloudMotd;
    }

    private void handleCloudDataUpdate(String cloudValue) {
        if (cloudValue == null || cloudValue.trim().isEmpty()) {
            currentMotd.set(DEFAULT_MESSAGE);
        } else {
            currentMotd.set(cloudValue);
        }
    }

    public StringProperty motdProperty() {
        return currentMotd;
    }

    public String getCurrentMotd() {
        return currentMotd.get();
    }
}

