class ProductOfNumbers:

    def __init__(self):
        self.s = 0
        self.cache = {}
        self.k = 0
        self.curr = 0

    def add(self, num: int) -> None:
        self.cache[self.k] = num
        if num == 0:
            self.k = 0
            self.curr = 0
            self.cache = {}
        else:
            self.k = self.k + 1
            self.curr = self.curr * num

    def getProduct(self, k: int) -> int:
        if self.s == 0:
            return 0
        if k > self.s:
            return self.curr
        return self.curr // (self.cache[self.s-k] or 1)

