public boolean hasConnectionUpgradeHeader(Method method) {
    String connectionHeader = method.getHeader("Connection");
    if (connectionHeader != null && connectionHeader.toLowerCase().contains("upgrade")) {
        String upgradeHeader = method.getHeader("Upgrade");
        if (upgradeHeader != null && upgradeHeader.equalsIgnoreCase("Connection")) {
            return true;
        }
    }
    return false;
}

