            builder.headless(false);

            ConfigurableApplicationContext ctx = builder.run(args);
            logger.info("main finished: ctx={}.", ctx);
        } catch (Exception e) {
            logger.error("Exiting because initialization failed.");
            System.exit(9);
        }
    }

