import java.awt.Image;
import java.awt.image.BufferedImage;
import java.awt.image.RenderedImage;
import java.io.IOException;
import java.io.OutputStream;
import java.util.Iterator;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.ImageInputStream;
import net.coobird.thumbnailator.Thumbnails;
import org.springframework.stereotype.Component;
import javax.inject.Singleton;
import javax.inject.Named;

@Component
@Singleton
@Named("thumbnailator")
public class ThumbnailatorImageProcessor extends DefaultImageProcessor {

    @Override
    public void writeImage(RenderedImage image, String mimeType, float quality, OutputStream out) throws IOException {
        if (image instanceof BufferedImage) {
            String formatName = getFormatNameForMimeType(mimeType);
            Thumbnails.of((BufferedImage) image)
                      .outputFormat(formatName)
                      .outputQuality(quality)
                      .toOutputStream(out);
        } else {
            super.writeImage(image, mimeType, quality, out);
        }
    }

    @Override
    public Image scaleImage(Image image, int width, int height) throws IOException {
        if (image instanceof BufferedImage) {
            return Thumbnails.of((BufferedImage) image)
                             .size(width, height)
                             .asBufferedImage();
        } else {
            return super.scaleImage(image, width, height);
        }
    }

    private String getFormatNameForMimeType(String mimeType) {
        Iterator<ImageReader> readers = ImageIO.getImageReadersByMIMEType(mimeType);
        if (readers.hasNext()) {
            ImageReader reader = readers.next();
            return reader.getFormatName();
        }
        throw new IllegalArgumentException("Unsupported MIME type: " + mimeType);
    }
}

