public class BasamakDegeri {

    public static void main(String[] args) {

        tumKombinasyonlariListele();

        System.out.println("Basamak Sayisi: " + basamakAdediniHesapla(345987));

        System.out.println("Rakamlar Toplami: " + digitToplamiHesapla(24653));

    }

    // Onlar ve birler basamagi olasi tum kombinasyonlarini ekrana basar
    public static void tumKombinasyonlariListele() {
        int onlarHanesi = 0;
        // Onlar hanesi 0'dan 4'e kadar donuyor
        while (onlarHanesi <= 4) {
            int birlerHanesi = 1;
            // Birler hanesi 1'den 9'a kadar donuyor
            while (birlerHanesi <= 9) {
                int birlesikSayi = onlarHanesi * 10 + birlerHanesi;
                System.out.println("Onlar basamagi: " + onlarHanesi + ", Birler basamagi: " + birlerHanesi + " --> " + birlesikSayi);
                birlerHanesi++;
            }
            onlarHanesi++;
        }
    }

    // Bir sayinin butun rakamlarinin toplamini dondurur
    public static int digitToplamiHesapla(int deger) {
        int toplam = 0;
        // Rakamlar tek tek ayristirilip toplama eklenir
        for (int kalan = deger; kalan > 0; kalan /= 10) {
            toplam += kalan % 10;
        }
        return toplam;
    }

    // Bir sayinin kac basamaktan olustugunu dondurur
    public static int basamakAdediniHesapla(int deger) {
        int adet = 0;
        // Sayi sifira dusene kadar her adimda bir basamak sayilir
        for (int kalan = deger; kalan > 0; kalan /= 10) {
            adet++;
        }
        return adet;
    }
}

import java.util.Random;
import java.util.Scanner;
 
public class PigGame
{
    private static final int PLAYERS = 2, MAX_POINTS = 100;
    private static final Scanner sc = new Scanner( System.in );
    private static final Random rand = new Random();
    private static final Player[] players = new Player[PLAYERS];
 
    public static void main( String[] args )
    {
    for( int p = 0; p < PLAYERS; p++ )
        players[p] = new Player();
 
//  while( true )
    {
        System.out.println( "Enter name player 1: " );
        players[0].setName( sc.nextLine() );
        System.out.println( "Enter name player 2: " );
        players[1].setName( sc.nextLine() );
 
        int p = 0;
        while( true )
        {
        if( turn( p ) )
        {
            praise( p );
            break;
        }
 
        ++p %= PLAYERS;
        }
 
//      String r;
//      System.out.print( "Do you want to play again ( y / n )? " );
//      r = sc.nextLine();
//      if( r!= "Y" && r!= "y" ) return;
//      resetPlayers();
    }
    }
 
    private static void praise( int p )
    {
    System.out.println( "CONGRATULATIONS " + players[p].getName() + ", you are the winner!" );
    System.out.println( "Final Score" );
    drawScoreboard();
    System.out.println();
    }
 
    private static void drawScoreboard()
    {
    for( int p = 0; p < PLAYERS; p++ )
        System.out.println( players[p].getName() + ": " + players[p].getCurrScore() + " points" );
    System.out.println();
    }
 
    private static boolean turn( int p )
    {
    System.out.println( players[p].getName() + ", your round score is: " + players[p].getRoundScore() );
    String r;
    int die;
    while( true )
    {
        System.out.print( "What do you want to do (H)old or (R)oll? " );
        r = sc.nextLine();
        if( r.equals( "h" ) || r.equals( "H" ) )
        {
        players[p].addCurrScore();
        return players[p].getCurrScore() >= MAX_POINTS;
        }
        if( r.equals( "r" ) || r.equals( "R" ) )
        {
        die = rand.nextInt( 6 ) + 1;
        if( die == 1 )
        {
                System.out.println( players[p].getName() + ", your turn is over." );
            return false;
        }
        players[p].addRoundScore( die );
        }
        System.out.println();
    }
    return false;
    }
}
 
