import java.util.Arrays;
 
public class DecimalToFraction {
 
    public static void main(String[] args) {
        for (double d : Arrays.asList(0.9054054, 0.518518, 0.75, 0.4285714, 0.833333,
                0.90909, 3.14159265358979, 2.7182818284590451)) {
            Fraction f = new Fraction(d, d >= 2? 65536 : 4096);
            System.out.printf("%20.10f → %s%n", d, f);
        }
    }
 
    public static class Fraction {
        public long numerator;
        public long denominator;
 
        public Fraction(double f, long maximumDenominator) {
            /* Translated from the C version. */
            /*  a: continued fraction coefficients. */
            long a;
            long[] h = new long[] { 0, 1, 0 };
            long[] k = new long[] { 1, 0, 0 };
            long x, d, n = 1;
            int i, neg = 0;
 
            if (maximumDenominator <= 1) {
                denominator = 1;
                numerator = (long) f;
                return;
            }
 
            if (f < 0) {
                neg = 1;
                f = -f;
            }
 
            while (f!= Math.floor(f)) {
                n <<= 1;
                f *= 2;
            }
            d = (long) f;
 
            /* continued fraction and check denominator each step */
            for (i = 0; i < 64; i++) {
                a = (n!= 0)? d / n : 0;
                if ((i!= 0) && (a == 0))
                    break;
 
                x = d;
                d = n;
                n = x % n;
 
                x = a;
                if (k[1] * a + k[0] >= maximumDenominator) {
                    x = (maximumDenominator - k[0]) / k[1];
                    if (x * 2 >= a || k[1] >= maximumDenominator)
                        i = 65;
                    else
                        break;
                }
 
                h[2] = x * h[1] + h[0];
                h[0] = h[1];
                h[1] = h[2];
                k[2] = x * k[1] + k[0];
                k[0] = k[1];
                k[1] = k[2];
            }
            denominator = k[1];
            numerator = neg!= 0? -h[1] : h[1];
        }
 
        @Override
        public String toString() {
            return String.format("%d / %d", numerator, denominator);
        }
    }
}

