/**
 * Aligns fields into columns, separated by "|"
 */
public class ColumnAligner {
    private List<String[]> words = new ArrayList<>();
    private int columns = 0;
    private List<Integer> columnWidths = new ArrayList<>();
 
    /**
     * Initialize columns aligner from lines in a single string
     *
     * @param s
     *            lines in a single string. Empty string does form a column.
     */
    public ColumnAligner(String s) {
        String[] lines = s.split("\\n");
        for (String line : lines) {
            processInputLine(line);
        }
    }
 
    /**
     * Initialize columns aligner from lines in a list of strings
     *
     * @param lines
     *            lines in a single string. Empty string does form a column.
     */
    public ColumnAligner(List<String> lines) {
        for (String line : lines) {
            processInputLine(line);
        }
    }
 
    private void processInputLine(String line) {
        String[] lineWords = line.split("\\$");
        words.add(lineWords);
        columns = Math.max(columns, lineWords.length);
        for (int i = 0; i < lineWords.length; i++) {
            String word = lineWords[i];
            if (i >= columnWidths.size()) {
                columnWidths.add(word.length());
            } else {
                columnWidths.set(i, Math.max(columnWidths.get(i), word.length()));
            }
        }
    }
 
    interface AlignFunction {
        String align(String s, int length);
    }
 
    /**
     * Left-align all columns
     *
     * @return Lines, terminated by "\n" of columns, separated by "|"
     */
    public String alignLeft() {
        return align(new AlignFunction() {
            @Override
            public String align(String s, int length) {
                return StringUtils.rightPad(s, length);
            }
        });
    }
 
    /**
     * Right-align all columns
     *
     * @return Lines, terminated by "\n" of columns, separated by "|"
     */
    public String alignRight() {
        return align(new AlignFunction() {
            @Override
            public String align(String s, int length) {
                return StringUtils.leftPad(s, length);
            }
        });
    }
 
    /**
     * Center-align all columns
     *
     * @return Lines, terminated by "\n" of columns, separated by "|"
     */

import java.util.ArrayList;
import java.util.List;

public class Fibonacci {

    // n. Fibonacci sayisini asagidan yukariya (iteratif) hesaplar
    public static int fibonacci(int n) {
        List<Integer> hesaplananlar = new ArrayList<>();
        hesaplananlar.add(0);
        hesaplananlar.add(1);

        int sayac = 2;
        while (sayac <= n) {
            int oncekiIki = hesaplananlar.get(sayac - 2);
            int oncekiBir = hesaplananlar.get(sayac - 1);
            hesaplananlar.add(oncekiIki + oncekiBir);
            sayac++;
        }

        return hesaplananlar.get(n);
    }

    public static void main(String[] args) {
        int hedefIndeks = 10;
        int deger = fibonacci(hedefIndeks);
        System.out.println(deger);
    }
}

public class Roman {
    private static int decodeSingle(char letter) {
        switch(letter) {
            case 'M': return 1000;
            case 'D': return 500;
            case 'C': return 100;
            case 'L': return 50;
            case 'X': return 10;
            case 'V': return 5;
            case 'I': return 1;
            default: return 0;
        }
    }
    public static int decode(String roman) {
        int result = 0;
        String uRoman = roman.toUpperCase(); //case-insensitive
        for(int i = 0;i < uRoman.length() - 1;i++) {//loop over all but the last character
            //if this character has a lower value than the next character
            if (decodeSingle(uRoman.charAt(i)) < decodeSingle(uRoman.charAt(i+1))) {
                //subtract it
                result -= decodeSingle(uRoman.charAt(i));
            } else {
                //add it
                result += decodeSingle(uRoman.charAt(i));
            }
        }
        //decode the last character, which is always added
        result += decodeSingle(uRoman.charAt(uRoman.length()-1));
        return result;
    }
 
    public static void main(String[] args) {
        System.out.println(decode("MCMXC")); //1990
        System.out.println(decode("MMVIII")); //2008
        System.out.println(decode("MDCLXVI")); //1666
    }
}

public class UcluIslec {

    public static void main(String[] args) {

        int deger = 10;

        // Tek seviyeli kosul (ternary) operatoru ornegi
        String karsilastirma = (deger > 5) ? "Buyuk" : "Kucuk"; // 5'i gecerse Buyuk, gecmezse Kucuk
        System.out.println("Sayi 5ten Buyuk mu? " + karsilastirma);

        karsilastirma = (deger > 15) ? "Buyuk" : "Kucuk"; // 15'i gecerse Buyuk, gecmezse Kucuk
        System.out.println("Sayi 15ten Buyuk mu? " + karsilastirma);

        // Birden fazla kosulun zincirlenerek kullanilmasi
        String durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        // 25 ustu Sicak, 15 ustu Ilik, digerleri Soguk olarak degerlendirilir
        System.out.println("Hava Durumu: 10 derece " + durum);

        deger = 20;
        durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        System.out.println("Hava Durumu: 20 derece " + durum);

        deger = 30;
        durum = (deger > 25) ? "Sicak" : (deger > 15) ? "Ilik" : "Soguk";
        System.out.println("Hava Durumu: 30 derece " + durum);
    }
}

