import java.util.*;

import java.io.*;

public class numgame {

    public static void main(String[] args) throws IOException {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        StringTokenizer st = new StringTokenizer(br.readLine());

        int t = Integer.parseInt(st.nextToken());

        while (t-- > 0) {

            st = new StringTokenizer(br.readLine());

            int n = Integer.parseInt(st.nextToken());

            st = new StringTokenizer(br.readLine());

            int[] a = new int[n];

            for (int i = 0; i < n; i++) {

                a[i] = Integer.parseInt(st.nextToken());

            }

            if(check(a, n)) {

                pw.println(n);

                continue;

            }

            boolean test = check(a, 2);

            int ans = bs(a);

            pw.println(ans);

        }

        pw.close();

    }

    public static int bs(int[] a) {

        int l = 0;

        int r = a.length - 1;

        while (l < r) {

            int m = (r + l + 1) / 2;

            if (check(a, m)) {

                l = m + 1;

            } else {

                r = m - 1;

            }

        }

        if(r > 0 && !check(a, r)) {

            return (r - 1);

        }

        return r;

    }

    public static boolean check(int[] a, int k) {

        HashMap<Integer, Integer> num = new HashMap<Integer, Integer>();

        for (int i : a) {

            if (num.containsKey(i)) {

                num.put(i, num.get(i) + 1);

            } else {

                num.put(i, 1);

            }

        }

        for (int i = 1; i <= k; i++) {

            int lim = k - i + 1;

            boolean good = false;

            for (int j = lim; j >= 1; j--) {

                if (num.containsKey(j) && num.get(j) > 0) {

                    good = true;

                    num.put(j, num.get(j) - 1);

                    break;

                }

            }

            for (int j = 1; j <= lim; j++) {

                if (num.containsKey(j) && num.get(j) > 0) {

                    good = true;

                    num.put(j, num.get(j) - 1);

                    break;

                }

            }

            if (!good) {

                return false;

            }

        }

        return true;

    }

}

