import com.github.scribejava.apis.GoogleApi20;
import com.github.scribejava.core.builder.api.BaseApi;
import edu.harvard.iq.dataverse.authorization.AuthenticatedUserDisplayInfo;
import edu.harvard.iq.dataverse.authorization.providers.oauth2.AbstractOAuth2AuthenticationProvider;
import edu.harvard.iq.dataverse.util.BundleUtil;
import java.io.StringReader;
import java.util.UUID;
import javax.json.Json;
import javax.json.JsonObject;
import javax.json.JsonReader;

/**
 *
 */
public class GoogleOAuth2AP extends AbstractOAuth2AuthenticationProvider {

    public GoogleOAuth2AP(String aClientId, String aClientSecret) {
        id = "google";
        title = BundleUtil.getStringFromBundle("auth.providers.title.google");
        clientId = aClientId;
        clientSecret = aClientSecret;
        scope =  "https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/userinfo.email";
        baseUserEndpoint = "https://www.googleapis.com/oauth2/v2/userinfo";
    }

    @Override
    public BaseApi getApiInstance() {
        return GoogleApi20.instance();
    }

    @Override
    protected ParsedUserResponse parseUserResponse(String responseBody) {
        try ( StringReader rdr = new StringReader(responseBody);
              JsonReader jrdr = Json.createReader(rdr) )  {
            JsonObject response = jrdr.readObject();

            AuthenticatedUserDisplayInfo displayInfo = new AuthenticatedUserDisplayInfo(
                    response.getString("given_name",""),
                    response.getString("family_name",""),
                    response.getString("email",""),
                    "",
                    ""
            );
            String persistentUserId = response.getString("id");
            String username = response.getString("email");
            if ( username != null ) {
                username = username.split("@")[0].trim();
            } else {
                // compose a username from given and family names
                username = response.getString("given_name","") + "."
                           + response.getString("family_name","");
                username = username.trim();
                if ( username.isEmpty() ) {
                    username = UUID.randomUUID().toString();
                } else {
                    username = username.replaceAll(" ", "-");
                }
            }
            return new ParsedUserResponse(displayInfo, persistentUserId, username);
        }
    }

    @Override
    public boolean isDisplayIdentifier() {
        return false;
    }

}

public class Arrays {

    // Appends a single string to an array of strings
    public static String[] append(String[] array, String element) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        String[] result = new String[array.length + 1];
        System.arraycopy(array, 0, result, 0, array.length);
        result[array.length] = element;
        return result;
    }

    // Appends another array of strings to an existing array of strings
    public static String[] append(String[] array, String[] elements) {
        if (array == null || elements == null) {
            throw new IllegalArgumentException("Input arrays cannot be null");
        }
        String[] result = new String[array.length + elements.length];
        System.arraycopy(array, 0, result, 0, array.length);
        System.arraycopy(elements, 0, result, array.length, elements.length);
        return result;
    }

    // Slices an array from a start index to the end of the array
    public static String[] slice(String[] array, int start) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        int startIndex = calculateIndex(start, array.length);
        return slice(array, startIndex, array.length);
    }

    // Slices an array from a start index to an end index
    public static String[] slice(String[] array, int start, int end) {
        if (array == null) {
            throw new IllegalArgumentException("Input array cannot be null");
        }
        int startIndex = calculateIndex(start, array.length);
        int endIndex = calculateIndex(end, array.length);

        if (startIndex > endIndex) {
            return new String[0]; // Return an empty array if start is greater than end
        }

        String[] result = new String[endIndex - startIndex];
        System.arraycopy(array, startIndex, result, 0, endIndex - startIndex);
        return result;
    }

    // Calculates the effective index, handling negative indices
    private static int calculateIndex(int index, int length) {
        if (index < 0) {
            index += length;
        }
        return Math.max(0, Math.min(index, length));
    }

    public static void main(String[] args) {
        // Example usage
        String[] array1 = {"a", "b", "c", "d"};
        String[] array2 = {"e", "f"};

        // Append single element
        String[] result1 = append(array1, "g");
        System.out.println(java.util.Arrays.toString(result1)); // [a, b, c, d, g]

import java.util.Arrays;
import java.util.concurrent.ThreadLocalRandom;
 
public class AtomicUpdates {
 
    private static final int NUM_BUCKETS = 10;
 
    public static class Buckets {
        private final int[] data;
 
        public Buckets(int[] data) {
            this.data = data.clone();
        }
 
        public int getBucket(int index) {
            synchronized (data) {
                return data[index];
            }
        }
 
        public int transfer(int srcIndex, int dstIndex, int amount) {
            if (amount < 0)
                throw new IllegalArgumentException("negative amount: " + amount);
            if (amount == 0)
                return 0;
 
            synchronized (data) {
                if (data[srcIndex] - amount < 0)
                    amount = data[srcIndex];
                if (data[dstIndex] + amount < 0)
                    amount = Integer.MAX_VALUE - data[dstIndex];
                if (amount < 0)
                    throw new IllegalStateException();
                data[srcIndex] -= amount;
                data[dstIndex] += amount;
                return amount;
            }
        }
 
        public int[] getBuckets() {
            synchronized (data) {
                return data.clone();
            }
        }
    }
 
    private static long getTotal(int[] values) {
        long total = 0;
        for (int value : values) {
            total += value;
        }
        return total;
    }
 
    public static void main(String[] args) {
        ThreadLocalRandom rnd = ThreadLocalRandom.current();
 
        int[] values = new int[NUM_BUCKETS];
        for (int i = 0; i < values.length; i++)
            values[i] = rnd.nextInt() & Integer.MAX_VALUE;
        System.out.println("Initial Array: " + getTotal(values) + " " + Arrays.toString(values));
 
        Buckets buckets = new Buckets(values);
        new Thread(() -> equalize(buckets), "equalizer").start();
        new Thread(() -> transferRandomAmount(buckets), "transferrer").start();
        new Thread(() -> print(buckets), "printer").start();
    }
 
    private static void transferRandomAmount(Buckets buckets) {
        ThreadLocalRandom rnd = ThreadLocalRandom.current();
        while (true) {
            int srcIndex = rnd.nextInt(NUM_BUCKETS);
            int dstIndex = rnd.nextInt(NUM_BUCKETS);
            int amount = rnd.nextInt() & Integer.MAX_VALUE;
            buckets.transfer(srcIndex, dstIndex, amount);
        }
    }
 
