public interface HashJoinProbe {
  public static TemplateClassDefinition<HashJoinProbe> TEMPLATE_DEFINITION = new TemplateClassDefinition<HashJoinProbe>(HashJoinProbe.class, HashJoinProbeTemplate.class);

  /* The probe side of the hash join can be in the following two states
   * 1. PROBE_PROJECT: Inner join case, we probe our hash table to see if we have a
   *    key match and if we do we project the record
   * 2. PROJECT_RIGHT: Right Outer or Full Outer joins where we are projecting the records
   *    from the build side that did not match any records on the probe side. For Left outer
   *    case we handle it internally by projecting the record if there isn't a match on the build side
   * 3. DONE: Once we have projected all possible records we are done
   */
  public static enum ProbeState {
    PROBE_PROJECT, PROJECT_RIGHT, DONE
  }

  void setupHashJoinProbe(
      FunctionContext functionContext,
      VectorAccessible buildBatch,
      VectorAccessible probeBatch,
      VectorAccessible outgoing,
      HashTable hashTable,
      JoinRelType joinRelType,
      List<BuildInfo> buildInfos,
      List<ArrowBuf> startIndices,
      List<BitSet> keyMatchBitVectors,
      int maxHashTableIndex,
      int targetRecordsPerBatch);

  /**
   * Project any remaining build items that were not matched. Only used when doing a FULL or RIGHT join.
   * @return Negative output if records were output but batch wasn't completed. Postive output if batch was completed.
   */
  int projectBuildNonMatches();

  /**
   * Probe with current batch.
   * @return number of records matched. negative if we failed to output all records.
   */
  int probeBatch();

}

public int minPartitions(String n) {
    int maxDigit = 0;
    for (char c : n.toCharArray()) {
        maxDigit = Math.max(maxDigit, c - '0');
    }
    return maxDigit;
}

public static int bin2Dec(String binaryString) throws NumberFormatException {
    int decimal = 0;
    for (int i = 0; i < binaryString.length(); i++) {
        char ch = binaryString.charAt(i);
        if (ch < '0' || ch > '1') {
            throw new NumberFormatException("Invalid binary string: " + binaryString);
        }
        decimal = decimal * 2 + (ch - '0');
    }
    return decimal;
}

import java.util.logging.Logger;
import java.util.List;
import org.deepmehta.TypeRegistry;
import org.deepmehta.service.DeepaMehtaService;
import org.deepmehta.contentmodel.TopicTypeModel;
import org.deepmehta.kernel.AttachedType;

public class AttachedTopicType extends AttachedType {
    private static final Logger logger = Logger.getLogger(AttachedTopicType.class.getName());
    private final TopicTypeModel model;
    private final DeepaMehtaService dms;
    private final TypeRegistry typeCache;

    public AttachedTopicType(TopicTypeModel model, DeepaMehtaService dms, TypeRegistry typeCache) {
        this.model = model;
        this.dms = dms;
        this.typeCache = typeCache;
    }

    public synchronized void update(List<Directive> directives) {
        logger.info(() -> "Audit: Starting update cycle for type " + model.getUri());
        processPhase(directives, Directive.UPDATE_METADATA);
        processPhase(directives, Directive.SYNC_CONTENT);
        processPhase(directives, Directive.FINALIZE_CACHE);
        logger.info(() -> "Audit: Completed update cycle for type " + model.getUri());
    }

    private void processPhase(List<Directive> directives, Directive phase) {
        directives.stream()
            .filter(d -> d == phase)
            .forEach(d -> {
                switch (d) {
                    case UPDATE_METADATA:
                        dms.commitMetadata(model);
                        typeCache.invalidate(model.getId());
                        logger.fine("Metadata committed and cache invalidated");
                        break;
                    case SYNC_CONTENT:
                        dms.propagateTypeChanges(model);
                        logger.fine("Content changes propagated to services");
                        break;
                    case FINALIZE_CACHE:
                        typeCache.put(model.getId(), this);
                        logger.fine("Type instance cached in registry");
                        break;
                    default:
                        logger.warning("Unhandled directive phase: " + d);
                }
            });
    }

    public TopicTypeModel getModel() {
        return model;
    }

    public void putInTypeCache() {
        typeCache.put(model.getId(), this);
    }

    public void removeFromTypeCache() {
        typeCache.remove(model.getId());
    }

    public List<Topic> getAllInstances() {
        return dms.queryTopics("type_uri=\"" + model.getUri() + "\"", model.getAssociatedAspect());
    }

