public class RedisTransactionExecutor {
    private final CacheTransactionManager txManager;
    private final TransactionId transactionId;
    private final TransactionQueue transactionQueue;

    public RedisTransactionExecutor(CacheTransactionManager txManager,
                                   TransactionId transactionId,
                                   TransactionQueue transactionQueue) {
        this.txManager = txManager;
        this.transactionId = transactionId;
        this.transactionQueue = transactionQueue;
    }

    public ByteBuf executeCommand() {
        if (transactionId == null) {
            return ErrorResponses.NO_TRANSACTION;
        }

        try {
            txManager.resume(transactionId);
            List<Object> commandResults = new ArrayList<>();

            if (hasError()) {
                txManager.rollback();
                return constructErrorResponse();
            }

            try {
                for (Transaction.QueuedCommand cmd : transactionQueue) {
                    commandResults.add(cmd.getResult());
                }
                txManager.commit();
                return constructResponseExec(commandResults);
            } catch (CommitConflictException cce) {
                txManager.rollback();
                return ErrorResponses.EXEC_CONFLICT;
            }
        } catch (CacheException ce) {
            return ErrorResponses.transactionError(ce.getMessage());
        } finally {
            txManager.suspend();
        }
    }

    private boolean hasError() {
        for (Transaction.QueuedCommand cmd : transactionQueue) {
            if (cmd.getStatus() == Transaction.Status.FAILED) {
                return true;
            }
        }
        return false;
    }

    private ByteBuf constructResponseExec(List<Object> results) {
        ByteBuf buffer = ByteBufAllocator.DEFAULT.buffer();
        buffer.writeByte('*');
        buffer.writeBytes(String.valueOf(results.size()).getBytes());
        buffer.writeByte('\r').writeByte('\n');

        for (Object result : results) {
            if (result instanceof ByteBuf) {
                ByteBuf resultBuf = (ByteBuf) result;

