    public int shoppingOffers(List<Integer> price, List<List<Integer>> special, List<Integer> needs) {

        if(price.size() < 1) return maxPrice;

        for(int i =0;i<price.size();i++)
        {
            maxPrice += (price.get(i)*needs.get(i));
        }

        calculate(price, special, needs, 0);

        return maxPrice;

    }

    void calculate(List<Integer> price, List<List<Integer>> special, List<Integer> needs, int curPrice)
    {
        boolean allZero = true;
        for(int i = 0;i<needs.size();i++)
        {
            if(needs.get(i)!=0) allZero = false;
        }

        if(!allZero);

        {for(List<Integer> list : special)
        {
            boolean valid = true;
            int temp = 0;
            for(int i = 0;i<list.size()-1;i++)
            {
                if(list.get(i) > needs.get(i))
                {
                    valid = false;
                    break;
                }
            }
            if(valid)
            {
                temp=(list.get(list.size()-1));
                //System.out.println(curPrice);
                List<Integer> newNeeds = new ArrayList<Integer>();
                for(int i = 0;i<list.size()-1;i++)
                {
                    newNeeds.add(needs.get(i)-list.get(i));

                }
                calculate(price, special, newNeeds, curPrice + temp);
            }
        }

        for(int i =0;i<price.size();i++)
        {
            curPrice += (price.get(i)*needs.get(i));
        }
        }

        if(curPrice < maxPrice ) maxPrice = curPrice;
    }

}

