@Override
public void selectInputStreams(Collection<EditLogInputStream> streams, long fromTxnId, boolean inProgressOk, boolean validateInProgressSegments) throws IOException {
    // Filter streams based on the fromTxnId and inProgressOk flag
    for (EditLogInputStream stream : streams) {
        if (stream.getFirstTxId() > fromTxnId) {
            continue; // Skip streams that start after the requested fromTxnId
        }
        if (!inProgressOk && stream.getLastTxId() == HdfsConstants.INVALID_TXID) {
            continue; // Skip in-progress streams if inProgressOk is false
        }
        if (validateInProgressSegments && stream.getLastTxId() == HdfsConstants.INVALID_TXID) {
            validateStream(stream); // Validate in-progress streams if required
        }
        // Add the stream to the selected streams
        selectedStreams.add(stream);
    }
}

private static ArrayList<double[]> getVisibleEdges(Projection2D proj, double[] s_min, double[] s_max) {
    ArrayList<double[]> edges = new ArrayList<>();
    int dim = s_min.length;
    int numVertices = (int) Math.pow(2, dim);
    double[][] vertices = new double[numVertices][dim];

    // Generate all vertices of the hypercube
    for (int i = 0; i < numVertices; i++) {
        for (int j = 0; j < dim; j++) {
            vertices[i][j] = (i & (1 << j)) == 0 ? s_min[j] : s_max[j];
        }
    }

    // Check each edge to see if it is visible
    for (int i = 0; i < numVertices; i++) {
        for (int j = i + 1; j < numVertices; j++) {
            if (isEdgeVisible(proj, vertices[i], vertices[j])) {
                edges.add(new double[]{i, j});
            }
        }
    }

    return edges;
}

private static boolean isEdgeVisible(Projection2D proj, double[] v1, double[] v2) {
    // Check if both vertices are within the projection bounds
    if (!proj.isWithinBounds(v1) || !proj.isWithinBounds(v2)) {
        return false;
    }

    // Check if the edge intersects with the projection plane
    return proj.intersects(v1, v2);
}

