import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.event.ActionEvent;
import java.io.File;
import java.io.IOException;

public class OpenProjectAction extends AbstractAction {
    private JFileChooser fileChooser;
    private ApplicationWorkspace workspace;
    private JTree projectTree;

    public OpenProjectAction(ApplicationWorkspace workspace, JTree projectTree) {
        this.workspace = workspace;
        this.projectTree = projectTree;
        initializeFileChooser();
        configureAction();
    }

    private void initializeFileChooser() {
        fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Open KROKI Project");
        fileChooser.setFileFilter(new FileNameExtensionFilter("KROKI Files (*.kroki)", "kroki"));
        fileChooser.setAcceptAllFileFilterUsed(false);
    }

    private void configureAction() {
        putValue(Action.NAME, "Open Project");
        putValue(Action.SHORT_DESCRIPTION, "Load existing business subsystem project");
    }

    @Override
    public void actionPerformed(ActionEvent e) {
        int result = fileChooser.showOpenDialog(null);
        if (result != JFileChooser.APPROVE_OPTION) return;

        File selectedFile = fileChooser.getSelectedFile();
        if (!selectedFile.exists()) {
            showError("Selected file does not exist");
            return;
        }

        String canonicalPath = getCanonicalPath(selectedFile);
        if (canonicalPath == null || workspace.isProjectLoaded(canonicalPath)) {
            showError("Project is already open or invalid path");
            return;
        }

        loadProjectFile(selectedFile, canonicalPath);
    }

    private String getCanonicalPath(File file) {
        try {
            return file.getCanonicalPath();
        } catch (IOException ex) {
            return null;
        }
    }

    private void loadProjectFile(File file, String path) {
        try {
            BussinesSubsystem subsystem = SaveUtil.deserialize(file);
            workspace.registerProject(subsystem, path);
            refreshProjectHierarchy();
        } catch (IOException ex) {
            showError("File read error: " + ex.getMessage());
        } catch (ClassNotFoundException ex) {
            showError("Invalid project format");
        } catch (Exception ex) {
            showError("Unexpected error: " + ex.getClass().getSimpleName());
        }
    }

