    private static final List<String> thousandNames = Arrays.asList(
            "", "thousand", "million", "billion", "trillion", "quadrillion",
            "quintillion");
 
    public static String numToText(long n, boolean uk) {
        if (n == 0L) return "zero";
        boolean neg = n < 0L;
        boolean maxNeg = n == Long.MIN_VALUE;
        long nn = maxNeg? -(n + 1) : (neg? -n : n);
        int[] digits3 = new int[7];
