            digits3[i] = (int) (nn % 1000);
            nn /= 1000;
        }
        if (maxNeg) digits3[0]++;
 
        String threeDigitsToText(int number) {
            StringBuilder sb = new StringBuilder();
            if (number == 0) return "";
            int hundreds = number / 100;
            int remainder = number % 100;
            if (hundreds > 0) {
                sb.append(oneNames.get(hundreds), " hundred");
                if (remainder > 0) sb.append(uk? " and " : " ");
            }
            if (remainder > 0) {
                int tens = remainder / 10;
                int units = remainder % 10;
                if (tens > 1) {
                    sb.append(tenNames.get(tens));
                    if (units > 0) sb.append("-", oneNames.get(units));
                } else sb.append(oneNames.get(remainder));
            }
            return sb.toString();
        }
 
        String[] triplets = new String[7];
        for (int i = 0; i <= 6; i++) triplets[i] = threeDigitsToText(digits3[i]);
        String text = triplets[0];
        boolean andNeeded = uk && digits3[0] in 1..99;
        for (int i = 1; i <= 6; i++) {
            if (digits3[i] > 0) {
                String text2 = triplets[i] + " " + thousandNames.get(i);
                if (text!= "") {
                    text2 += andNeeded? " and " : ", ";
                    andNeeded = false;
                } else andNeeded = uk && digits3[i] in 1..99;
                text = text2 + text;
            }
        }

