    {
        pty = new HandlerPTY(shellCommand, null);
          if (pty.start()) {
              sendOnlineStatus("pty", OnlineStatus.ONLINE);
          } else {
              sendOnlineStatus("pty", OnlineStatus.OFFLINE);
          }
    }

    public void disconnect(String name) {
        if (name.equals("pty")) {
            if (pty != null) {
                pty.close();
                pty = null;
            }
            sendOnlineStatus("pty", OnlineStatus.OFFLINE);
        }
    }

