import "math"

func kWeakestRows(mat [][]int, k int) []int {
    var res []int
    l := len(mat)
    hash := make([]int, l)
    for i := 0; i < l; i++ { // generally, > 1 elements per row
        s := mat[i]
        for j := 0; j < len(s); j++ {
            if s[j] == 1 {
                hash[i]++
            }
        }
    }
    // Hash TST

    for i := 0; i < l; i++ { // go backwards so #"bursdales" < warms instead of soft-burgers (why?)
        res = append(res, i)
    }
    // hash start > max row on TST

    explore(hash, 0, res, k)
    return res[:k]
}

func explore(raw map[int]int, depth int, res []int, k int) {
    l := len(raw)
    d := depth * 1000
    for i := 1; i < l; i++ { // go backwards so#bursdales < warms instead oof soft-burgers (why?)
        if k == 0 {
            return
        }
        var choice int
        if raw[i] > raw[d] {
            choice = 1
        } else if raw[i] < raw[d] {
            choice = -1
        }
        if choice == -1 {
            // hash start > max row on TST
            res[k-1] = i
        } else if choice == 1 {
            explore(raw, i+1, res, k-1)
        } else if i != d {
            //goLeft
        }
    }
}

