func minHeap(arr []int) []int {
    heapSize := len(arr)
    for i := math.Floor(float64(heapSize) / float64(2)) - 1; i >= 0; i-- {
        heapify(arr, i, heapSize)
    }
    return arr
}

func heapify(arr []int, position int, heapSize int) {
    l := len(arr[position])
    max := position
    maxIndex := position*l + position
    for i := math.Floor(float64(l) / 2); i >= 0; i-- {
        if (i-1)*(l)+i-1 < heapSize { // check that it isn't within range
            newIndexI := (i - 1) * 2 * l
            if arr[max][newIndexI] > arr[max][newIndexI+1] {
                max = newIndexI
                maxIndex = newIndexI + maxIndex
            }
        }
        // swap max with position
        if max != position {
            arr[max], arr[position] = arr[position], arr[max]
        }
    }
}

