import java.sql.Connection;
import java.sql.DatabaseMetaData;
import java.sql.ResultSet;
import java.sql.SQLException;

public void validateRelationship(String baseTableName, String relatedTableName, String relationName) {
    try {
        // Assuming you have a Connection object named conn
        DatabaseMetaData meta = conn.getMetaData();
        ResultSet rs = meta.getExportedKeys(null, null, baseTableName);

        while (rs.next()) {
            String fkTableName = rs.getString("FKTABLE_NAME");
            String fkColumnName = rs.getString("FKCOLUMN_NAME");
            if (fkTableName.equals(relatedTableName) && fkColumnName.equals(relationName)) {
                System.out.println("Relation is valid");
                return;
            }
        }
        System.out.println("Relation is not valid");
    } catch (SQLException e) {
        e.printStackTrace();
    }
}

