    public static String solve(String s) {

        if (s.charAt(0) == s.charAt(s.length() - 1))

            return "NO";

        Stack<Character> stack = new Stack<>();

        char open = s.charAt(0);

        char close = s.charAt(s.length() - 1);

        boolean underflow = false;

        for (int i = 0; i < s.length(); i++) {

            if (s.charAt(i) == open) {

                stack.push(open);

            } else if (s.charAt(i) == close) {

                if (stack.empty()) {

                    underflow = true;

                    break;

                }

                stack.pop();

            } else {

                stack.push(open);

            }

        }

        if (stack.isEmpty() && !underflow)

            return "YES";

        stack.clear();

        for (int i = 0; i < s.length(); i++) {

            if (s.charAt(i) == open) {

                stack.push(open);

            } else if (s.charAt(i) == close) {

                if (stack.empty()) {

                    underflow = true;

                    break;

                }

                stack.pop();

            } else {

                if (stack.empty()) {

                    underflow = true;

                    break;

                }

                stack.pop();

            }

        }

        if (stack.isEmpty() && !underflow)

            return "YES";

        return "NO";

    }

}

class Reader {

    class IntervalComp implements Comparator<int[]>
    {
        public int compare(int[] a, int[] b)
        {
            if(a[0] == b[0])
                return a[1] - b[1];
            return a[0] - b[0];
        }
    }

    public int videoStitching(int[][] clips, int T) {

        Arrays.sort(clips, new IntervalComp());

        int start = 0;
        int res = 0;
        int next = -1;
        for(int i = 0; i < clips.length;)
        {
            if(start >= T)
                return res;
            if(start < clips[i][0])
            {
                if(next == -1)
                    return -1;
                res++;
                start = next;
                next = -1;
            }
            else
            {
                next = Math.max(next, clips[i][1]);
                i++;
            }
        }

        if(next != -1)
        {
            res++;
            start = next;
        }

        if(start >= T)
            return res;
        return -1;
    }
}

