private void expandTo(int wordIndex) {
    // Ensure the set can accommodate the word index
    if (wordIndex >= capacity) {
        // Calculate new capacity
        int newCapacity = (capacity * 3) / 2 + 1;
        // Create a new array with the new capacity
        boolean[] newSet = new boolean[newCapacity];
        // Copy the old array to the new array
        System.arraycopy(oldSet, 0, newSet, 0, capacity);
        // Update the old array reference to the new array
        oldSet = newSet;
        // Update the capacity
        capacity = newCapacity;
    }
}

