class Service {
    public int minOperations(int[] nums) {

 int cost = Integer.MAX_VALUE, bd = 0;
        HashSet<Integer> set = new HashSet<>();
        Arrays.sort(nums);
        final int n = nums.length;
        for (int i = 0; i < n; ++i) {
            if (i > 0 && nums[i] == nums[i - 1]) continue;
            while (bd < n && nums[bd] - nums[i] <= n - 1) {
                set.add(nums[bd]);
                ++bd;
            }
            cost = Math.min(cost, n - set.size());
            set.remove(nums[i]);
        }
        return cost;
    }
}

