        long[] prefixSum = new long[n];
        long totalSum = 0;

        // Calculate prefix sums and total sum
        for (int i = 0; i < n; i++) {
            totalSum += nums[i];
            prefixSum[i] = totalSum;
        }

        int maxWays = 0;

        // Case 1: Without changing any element
        Map<Long, Integer> rightCount = new HashMap<>();
        for (int i = 1; i < n; i++) {
            long balance = prefixSum[i - 1] - (totalSum - prefixSum[i - 1]);
            rightCount.put(balance, rightCount.getOrDefault(balance, 0) + 1);
        }
        maxWays = rightCount.getOrDefault(0L, 0);

        // Case 2: Changing one element to k
        Map<Long, Integer> leftCount = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long newSum = totalSum + k - nums[i];
            long balance = (newSum - 2 * prefixSum[i]);
            int ways = leftCount.getOrDefault(balance, 0) + rightCount.getOrDefault(-balance, 0);
            maxWays = Math.max(maxWays, ways);

            // Update counts for the next iteration
            if (i < n - 1) {
                long currentBalance = prefixSum[i] - (totalSum - prefixSum[i]);
                leftCount.put(currentBalance, leftCount.getOrDefault(currentBalance, 0) + 1);
                rightCount.put(-currentBalance, rightCount.getOrDefault(-currentBalance, 0) - 1);
            }
        }

        return maxWays;
    }
}

