public int countPrefixes(String[] words, String s) {
return wave(Arrays.asList(words), s);
}

private static int wave(List<String> wordList, String s) {
    int prefixCount = 0;
    for (String word : wordList) {
        if (s.startsWith(word)) {
            prefixCount++;
        }
    }
    return prefixCount;
}

import org.eclipse.core.runtime.Assert;
import org.eclipse.jface.text.IInformationControl;
import org.eclipse.jface.text.IInformationControlCreator;
import org.eclipse.jface.text.IInformationControlCreatorExtension;
import org.eclipse.swt.SWT;
import org.eclipse.swt.events.DisposeEvent;
import org.eclipse.swt.events.DisposeListener;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.wst.jsdt.internal.ui.text.java.hover.SourceViewerInformationControl;

public class TemplateInformationControlCreator implements IInformationControlCreator, IInformationControlCreatorExtension {

    private SourceViewerInformationControl fControl;
    private int fOrientation;

    public TemplateInformationControlCreator(int orientation) {
        Assert.isLegal(orientation == SWT.LEFT_TO_RIGHT || orientation == SWT.RIGHT_TO_LEFT, "Invalid orientation");
        fOrientation = orientation;
    }

    @Override
    public IInformationControl createInformationControl(Shell parent) {
        if (fControl != null && !fControl.isDisposed()) {
            fControl.dispose();
        }
        fControl = new SourceViewerInformationControl(parent, SWT.NONE, fOrientation);
        fControl.addDisposeListener(new DisposeListener() {
            @Override
            public void widgetDisposed(DisposeEvent e) {
                fControl = null;
            }
        });
        return fControl;
    }

    @Override
    public boolean canReuse(IInformationControl control) {
        return control instanceof SourceViewerInformationControl && !control.isDisposed();
    }

    @Override
    public boolean canReplace(IInformationControlCreator creator) {
        return creator instanceof TemplateInformationControlCreator;
    }

    public void setOrientation(int orientation) {
        Assert.isLegal(orientation == SWT.LEFT_TO_RIGHT || orientation == SWT.RIGHT_TO_LEFT, "Invalid orientation");
        fOrientation = orientation;
        if (fControl != null && !fControl.isDisposed()) {
            fControl.setOrientation(orientation);
        }
    }
}

