class Shape {
    public int longestOnes(int[] nums) {
        int count = 0;
        int left = 0, right = 0;
        int maxCount = 0;
        while (right < nums.length) {
            if (nums[right] == 1) {
                count++;
                maxCount = Math.max(maxCount, count);
            } else {
                count = 0;
                left = right + 1;
            }
            right++;
        }
        return maxCount;
    }
}

