public int solve(String s) {
int n = s.length(), i = 0, j = 0, res = 0;
for(int k = 0; k < n; ++k) {
if(s.charAt(k) == s.charAt(j)) res = Math.max(res, k - i);
else {
++i;
j = k;
}
}
return res;
}
}

def solve(arr):
    from collections import Counter

    count = Counter()
    left = 0
    answer = 0

    for right , char in enumerate(arr):
        count[char] += 1

        while count[char]>1:
            count[arr[left]] -= 1
            left += 1

        answer = max(answer, right - left + 1)

    return answer

