public class VigenereCipher {
    public static void main(String[] args) {
        String key = "VIGENERECIPHER";
        String ori = "Beware the Jabberwock, my son! The jaws that bite, the claws that catch!";
        String enc = encrypt(ori, key);
        System.out.println(enc);
        System.out.println(decrypt(enc, key));
    }
 
    static String encrypt(String text, final String key) {
        String res = "";
        text = text.toUpperCase();
        for (int i = 0, j = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c < 'A' || c > 'Z') continue;
            res += (char)((c + key.charAt(j) - 2 * 'A') % 26 + 'A');
            j = ++j % key.length();
        }
        return res;
    }
 
    static String decrypt(String text, final String key) {
        String res = "";
        text = text.toUpperCase();
        for (int i = 0, j = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c < 'A' || c > 'Z') continue;
            res += (char)((c - key.charAt(j) + 26) % 26 + 'A');
            j = ++j % key.length();
        }
        return res;
    }
}

public class DefaultLinkAnchorDelegate {
    private static final int MIN_SIZE_LA = 50; // Minimum size for multiple anchors
    private GraphicalElement parent;
    private DrawingCanvas canvas;
    private int numLinkanchorsH = 1; // Number of horizontal anchors
    private int numLinkanchorsV = 1; // Number of vertical anchors
    private List<LinkAnchor> linkAnchors = new ArrayList<>();

    public DefaultLinkAnchorDelegate(GraphicalElement parent, DrawingCanvas canvas) {
        this.parent = parent;
        this.canvas = canvas;
    }

    public void showLinkAnchors() {
        if (parent.isInGroup() && !parent.getGroup().allowsLinks()) {
            return; // Skip if parent is in a group that disallows links
        }

        int width = parent.getWidth();
        int height = parent.getHeight();

        // Determine number of anchors based on size
        numLinkanchorsH = (width >= MIN_SIZE_LA) ? 2 : 1;
        numLinkanchorsV = (height >= MIN_SIZE_LA) ? 2 : 1;

        // Clear existing anchors
        hideLinkAnchors();

        // Create and position horizontal anchors
        for (int i = 0; i < numLinkanchorsH; i++) {
            double x = parent.getX() + (i + 1) * (width / (numLinkanchorsH + 1));
            double yTop = parent.getY();
            double yBottom = parent.getY() + height;

            linkAnchors.add(new LinkAnchor(x, yTop, canvas)); // Top edge
            linkAnchors.add(new LinkAnchor(x, yBottom, canvas)); // Bottom edge
        }

        // Create and position vertical anchors
        for (int i = 0; i < numLinkanchorsV; i++) {
            double y = parent.getY() + (i + 1) * (height / (numLinkanchorsV + 1));
            double xLeft = parent.getX();
            double xRight = parent.getX() + width;

            linkAnchors.add(new LinkAnchor(xLeft, y, canvas)); // Left edge
            linkAnchors.add(new LinkAnchor(xRight, y, canvas)); // Right edge
        }
    }

    public void hideLinkAnchors() {
        for (LinkAnchor anchor : linkAnchors) {
            anchor.removeFromCanvas();
        }
        linkAnchors.clear();
    }

    private class LinkAnchor {
        private double x, y;
        private DrawingCanvas canvas;

        public LinkAnchor(double x, double y, DrawingCanvas canvas) {
            this.x = x;
            this.y = y;
            this.canvas = canvas;
            draw();
        }

        private void draw() {
            // Draw the anchor on the canvas (implementation depends on framework)
        }

