public static double pixelYToLatitude(double pixelY, long mapSize) {
    if (pixelY < 0 || pixelY > mapSize) {
        throw new IllegalArgumentException("Invalid pixelY coordinate");
    }

    double y = Math.PI - (2.0 * Math.PI * pixelY / Math.pow(2.0, mapSize));
    return Math.toDegrees(Math.atan(Math.sinh(y)));
}

