public class WayPointDeserializer implements JsonDeserializer<WayPoint> {

    @Override
    public WayPoint deserialize(JsonElement json, Type typeOfT, JsonDeserializationContext context) throws JsonParseException {
        if (!json.isJsonObject()) {
            throw new JsonParseException("Expected a JSON object");
        }

        JsonObject jsonObject = json.getAsJsonObject();
        if (!jsonObject.has("tile")) {
            throw new JsonParseException("Missing 'tile' field in JSON object");
        }

        if (SoldierDeserializer.currentSoldier == null) {
            throw new JsonParseException("Current soldier not set");
        }

        Tile tile = context.deserialize(jsonObject.get("tile"), Tile.class);
        WeightedPath<Tile> path = null;
        if (jsonObject.has("path")) {
            path = context.deserialize(jsonObject.get("path"), WeightedPath.class);
        }

        Integer aim = null;
        if (jsonObject.has("aim")) {
            aim = jsonObject.get("aim").getAsInt();
        }

        Integer wait = null;
        if (jsonObject.has("wait")) {
            wait = jsonObject.get("wait").getAsInt();
        }

        return new WayPoint(tile, path, aim, wait);
    }
}

