    private String mavenLocalRepository;
    private ImmutableList<String> mavenRemoteRepository = ImmutableList.of();

    public ImmutableList<String> getPlugins() {
        return plugins;
    }

    @Config("plugins")
    public DevelopmentLoaderConfig setPlugins(List<String> plugins) {
        this.plugins = ImmutableList.copyOf(plugins);
        return this;
    }

    @Config("plugins")
    public DevelopmentLoaderConfig setPlugins(String plugins) {
        this.plugins = ImmutableList.copyOf(SPLITTER.splitToList(plugins));
        return this;
    }

    public String getMavenLocalRepository() {
        return mavenLocalRepository;
    }

    @Config("maven.local-repository")
    public DevelopmentLoaderConfig setMavenLocalRepository(String mavenLocalRepository) {
        this.mavenLocalRepository = mavenLocalRepository;
        return this;
    }

    public ImmutableList<String> getMavenRemoteRepository() {
        return mavenRemoteRepository;
    }

    @Config("maven.remote-repository")
    public DevelopmentLoaderConfig setMavenRemoteRepository(List<String> mavenRemoteRepository) {
        this.mavenRemoteRepository = ImmutableList.copyOf(mavenRemoteRepository);
        return this;
    }

    @Config("maven.remote-repository")
    public DevelopmentLoaderConfig setMavenRemoteRepository(String mavenRemoteRepository) {
        this.mavenRemoteRepository = ImmutableList.copyOf(SPLITTER.splitToList(mavenRemoteRepository));
        return this;
    }
}

private void setReportFormTabs(final TabRenderReportForm report) {
    // Assuming report.getTabs() returns a list of Tab objects
    List<Tab> tabs = report.getTabs();
    if (tabs != null && !tabs.isEmpty()) {
        // Set the first tab as selected
        tabs.get(0).setSelected(true);
        // Optionally, you can deselect all other tabs
        for (int i = 1; i < tabs.size(); i++) {
            tabs.get(i).setSelected(false);
        }
    }
}

