import com.google.common.base.Preconditions;
import java.nio.charset.StandardCharsets;

public final class BindingSetRow {
    private static final String NODEID_BS_DELIM = "|";
    private final String nodeId;
    private final String bindingSetString;

    private BindingSetRow(String nodeId, String bindingSetString) {
        Preconditions.checkNotNull(nodeId, "Node ID cannot be null");
        Preconditions.checkNotNull(bindingSetString, "Binding set string cannot be null");
        this.nodeId = nodeId;
        this.bindingSetString = bindingSetString;
    }

    public String getNodeId() {
        return nodeId;
    }

    public String getBindingSetString() {
        return bindingSetString;
    }

    public static BindingSetRow make(byte[] row) {
        String rowString = new String(row, StandardCharsets.UTF_8);
        String[] parts = rowString.split(NODEID_BS_DELIM);

        Preconditions.checkArgument(parts.length == 2,
                "Row must contain exactly two parts separated by '" + NODEID_BS_DELIM + "'");

        return new BindingSetRow(parts[0], parts[1]);
    }

    @Override
    public String toString() {
        return "BindingSetRow{" +
                "nodeId='" + nodeId + '\'' +
                ", bindingSetString='" + bindingSetString + '\'' +
                '}';
    }

    @Override
    public int hashCode() {
        int result = nodeId.hashCode();
        result = 31 * result + bindingSetString.hashCode();
        return result;
    }

    @Override
    public boolean equals(Object obj) {
        if (this == obj) return true;
        if (obj == null || getClass() != obj.getClass()) return false;

        BindingSetRow that = (BindingSetRow) obj;

        if (!nodeId.equals(that.nodeId)) return false;
        return bindingSetString.equals(that.bindingSetString);
    }

    public static void main(String[] args) {
        String testRow = "node123|bindingA,bindingB,bindingC";
        byte[] rowBytes = testRow.getBytes(StandardCharsets.UTF_8);

        BindingSetRow bindingSetRow = BindingSetRow.make(rowBytes);

        System.out.println(bindingSetRow);
        System.out.println("Node ID: " + bindingSetRow.getNodeId());
        System.out.println("Binding Set: " + bindingSetRow.getBindingSetString());
    }
}

public void ensureNavigationProperties(StructuredType entityType) throws ODataException {
    // Check if the entityType has any navigation properties
    List<NavigationProperty> navigationProperties = entityType.getNavigationProperties();
    if (navigationProperties == null || navigationProperties.isEmpty()) {
        throw new ODataException("Entity type " + entityType.getName() + " does not have any navigation properties.");
    }

    // Ensure each navigation property is not null
    for (NavigationProperty navProp : navigationProperties) {
        if (navProp == null) {
            throw new ODataException("Navigation property in entity type " + entityType.getName() + " is null.");
        }
    }
}

class U0 extends Exception { }
class U1 extends Exception { }
 
public class ExceptionsTest {
    public static void foo() throws U1 {
        for (int i = 0; i <= 1; i++) {
            try {
                bar(i);
            } catch (U0 e) {
                System.out.println("Function foo caught exception U0");
            }
        }
    }
 
    public static void bar(int i) throws U0, U1 {
        baz(i); // Nest those calls
    }
 
    public static void baz(int i) throws U0, U1 {
        if (i == 0)
            throw new U0();
        else
            throw new U1();
    }
 
    public static void main(String[] args) throws U1 {
        foo();
    }
}

import org.opencv.core.Scalar;

import ftc.electronvolts.util.TeamColor;

public class BeaconColorResult {
    public enum BeaconColor {
        RED(ImageUtil.RED, "R"),
        GREEN(ImageUtil.GREEN, "G"),
        BLUE(ImageUtil.BLUE, "B"),
        UNKNOWN(ImageUtil.BLACK, "U");

        private final Scalar color;
        private final String name;

        BeaconColor(Scalar color, String name) {
            this.color = color;
            this.name = name;
        }

        public Scalar getColor() {
            return color;
        }

        @Override
        public String toString() {
            return name;
        }
    }

    private final BeaconColor leftColor;
    private final BeaconColor rightColor;

    public BeaconColorResult(BeaconColor leftColor, BeaconColor rightColor) {
        this.leftColor = leftColor;
        this.rightColor = rightColor;
    }

    public BeaconColor getLeftColor() {
        return leftColor;
    }

    public BeaconColor getRightColor() {
        return rightColor;
    }

    public static BeaconColor fromTeamColor(TeamColor teamColor) {
        if (teamColor == TeamColor.RED) {
            return BeaconColor.RED;
        } else if (teamColor == TeamColor.BLUE) {
            return BeaconColor.BLUE;
        } else {
            return BeaconColor.UNKNOWN;
        }
    }

    public static TeamColor toTeamColor(BeaconColor beaconColor) {
        if (beaconColor == BeaconColor.RED) {
            return TeamColor.RED;
        } else if (beaconColor == BeaconColor.BLUE) {
            return TeamColor.BLUE;
        } else {
            return null;
        }
    }

    @Override
    public String toString() {
        return "Left: " + leftColor + ", Right: " + rightColor;
    }

    public static class ImageUtil {
        public static final Scalar RED = new Scalar(255, 0, 0);
        public static final Scalar GREEN = new Scalar(0, 255, 0);
        public static final Scalar BLUE = new Scalar(0, 0, 255);
        public static final Scalar BLACK = new Scalar(0, 0, 0);
    }
}

import org.opensaml.xacml.policy.AttributeSelectorType;
import org.opensaml.xml.XMLObject;
import org.opensaml.xml.io.UnmarshallingException;
import org.opensaml.xml.schema.XSBooleanValue;
import org.opensaml.xml.util.DatatypeHelper;
import org.w3c.dom.Attr;

public class AttributeSelectorTypeUnmarshaller extends AbstractXACMLObjectUnmarshaller {

    @Override
    protected void processAttribute(XMLObject xmlObject, Attr attribute) throws UnmarshallingException {
        AttributeSelectorType attributeSelector = (AttributeSelectorType) xmlObject;

        if (attribute.getLocalName().equals(AttributeSelectorType.REQUEST_CONTEXT_PATH_ATTRIB_NAME)) {
            attributeSelector.setRequestContextPath(DatatypeHelper.safeTrimOrNullString(attribute.getValue()));
        } else if (attribute.getLocalName().equals(AttributeSelectorType.DATA_TYPE_ATTRIB_NAME)) {
            attributeSelector.setDataType(DatatypeHelper.safeTrimOrNullString(attribute.getValue()));
        } else if (attribute.getLocalName().equals(AttributeSelectorType.MUST_BE_PRESENT_ATTRIB_NAME)) {
            attributeSelector.setMustBePresent(XSBooleanValue.valueOf(attribute.getValue()));
        } else {
            super.processAttribute(xmlObject, attribute);
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class AlgorithmAnnotations {

    private static AlgorithmAnnotations INSTANCE = new AlgorithmAnnotations();

    private AlgorithmAnnotations() {
    }

    public static AlgorithmAnnotations getInstance() {
        return INSTANCE;
    }

    public List<Class<? extends Algorithm>> filterOutExperimental(List<Class<? extends Algorithm>> algorithms) {
        List<Class<? extends Algorithm>> filtered = new ArrayList<>();

        for (Class<? extends Algorithm> algorithm : algorithms) {
            if (!algorithm.isAnnotationPresent(Experimental.class)) {
                filtered.add(algorithm);
            }
        }

        return filtered;
    }

    public boolean acceptMultipleDataset(Class<?> algorithm) {
        return MultiDataSetAlgorithm.class.isAssignableFrom(algorithm);
    }

    public boolean acceptKnowledge(Class<?> algorithm) {
        return HasKnowledge.class.isAssignableFrom(algorithm);
    }

    public boolean requireIndependenceTest(Class<?> algorithm) {
        return TakesIndependenceWrapper.class.isAssignableFrom(algorithm);
    }

    public boolean requireScore(Class<?> algorithm) {
        return UsesScoreWrapper.class.isAssignableFrom(algorithm);
    }

    public boolean handleUnmeasuredConfounder(Class<?> algorithm) {
        return algorithm.isAnnotationPresent(UnmeasuredConfounder.class);
    }

    private interface Algorithm {
    }

    private interface MultiDataSetAlgorithm extends Algorithm {
    }

    private interface HasKnowledge extends Algorithm {
    }

    private interface TakesIndependenceWrapper extends Algorithm {
    }

    private interface UsesScoreWrapper extends Algorithm {
    }

    private @interface Experimental {
    }

    private @interface UnmeasuredConfounder {
    }

    private interface AbstractAnnotations {
    }

    private interface AnnotatedClass {
    }
}

public String transformTempDir(String path) {
  if (path == null || path.isEmpty()) {
    return path;
  }
  String[] parts = path.split("/");
  if (parts.length < 6) {
    return path;
  }
  parts[4] = "";
  String transformedPath = String.join("/", Arrays.copyOfRange(parts, 0, 5)) + "/";
  transformedPath += String.join("/", Arrays.copyOfRange(parts, 5, parts.length));
  return transformedPath;
}

