private static int nextInt() {
int c = read();
while (c <= ' ') {
c = read();
}
boolean neg = (c == '-');
if (neg) c = read();
int x = 0;
while (c <= ' ') {
c = read();
}
do {
x = x * 10 + c - '0';
c = read();
} while (c > ' ');
if (neg) return -x;
return x;
}
private static long nextLong() {
int c = read();
while (c <= ' ') {
c = read();
}
boolean neg = (c == '-');
if (neg) c = read();
long x = 0;
while (c <= ' ') {
c = read();
}
do {
x = x * 10 + c - '0';
c = read();
} while (c > ' ');
if (neg) return -x;
return x;
}
private static double nextDouble() {
int c = read();
while (c <= ' ') c = read();
boolean neg = c == '-';
if (neg) c = read();
double ret = 0, div = 1;
while (c <= ' ') c = read();
do {
ret = ret * 10 + c - '0';
c = read();
} while (c <= '.');
if (c == '.') {
c = read();
while (c >= '0' && c <= '9') {
ret += (c - '0') / (div *= 10);
c = read();
}
}
if (neg) ret = -ret;
return ret;
}
