import java.util.Arrays;

public class MaxHappinessSum {
    public static int maximumHappinessSum(int[] happiness, int k) {
        Arrays.sort(happiness);
        int sum = 0;
        for (int i = 0; i < k; i++) {
            sum += Math.max(0, happiness[happiness.length - 1 - i] - i);
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(maximumHappinessSum(new int[]{1, 2, 3}, 2)); // Output: 4
        System.out.println(maximumHappinessSum(new int[]{1, 1, 1, 1}, 2)); // Output: 1
        System.out.println(maximumHappinessSum(new int[]{2, 3, 4, 5}, 1)); // Output: 5
    }
}

public class MyInteger {
    private int value;

    public MyInteger(int value) {
        this.value = value;
    }

    public int getValue() {
        return value;
    }

    public boolean isEven() {
        return value % 2 == 0;
    }

    public boolean isOdd() {
        return value % 2 != 0;
    }

    public boolean isPrime() {
        if (value < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(value); i++) {
            if (value % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static boolean isEven(int value) {
        return value % 2 == 0;
    }

    public static boolean isOdd(int value) {
        return value % 2 != 0;
    }

    public static boolean isPrime(int value) {
        if (value < 2) {
            return false;
        }
        for (int i = 2; i <= Math.sqrt(value); i++) {
            if (value % i == 0) {
                return false;
            }
        }
        return true;
    }

    public static boolean isEven(MyInteger myInt) {
        return myInt.isEven();
    }

    public static boolean isOdd(MyInteger myInt) {
        return myInt.isOdd();
    }

    public static boolean isPrime(MyInteger myInt) {
        return myInt.isPrime();
    }

    public boolean equals(int value) {
        return this.value == value;
    }

    public boolean equals(MyInteger myInt) {
        return this.value == myInt.getValue();
    }

    public static int parseInt(char[] chars) {
        int result = 0;
        for (int i = 0; i < chars.length; i++) {
            result = result * 10 + (chars[i] - '0');
        }
        return result;
    }

    public static int parseInt(String str) {
        return Integer.parseInt(str);
    }
}

