        try {
            rb = ResourceBundle.getBundle(getClass().getSimpleName());
        } catch (MissingResourceException mre) {
            log.warn("No resource bundle found for: " + getClass().getSimpleName());
        }
    }

    protected String[] getConfigLocations() {
        return new String[]{
                "classpath*:/**/applicationContext-dao.xml",
                "classpath*:**/applicationContext.xml", // For modular projects
                "classpath*:applicationContext.xml", // for web projects
        };
    }

    public void populate(final Object obj) {
        if (rb == null) {
            return;
        }

        Properties props = new Properties();
        for (Enumeration keys = rb.getKeys(); keys.hasMoreElements(); ) {
            final String key = (String) keys.nextElement();
            final String value = rb.getString(key);
            props.put(key, value);
        }

        try {
            BeanUtils.copyProperties(obj, props);
        } catch (Exception e) {
            log.error("Error populating object", e);
        }
    }
     public void onSetUp() throws Exception {

        super.onSetUp();

        if (rb != null) {

            Properties props = new Properties();
            for (Enumeration keys = rb.getKeys(); keys.hasMoreElements(); ) {
                final String key = (String) keys.nextElement();
                final String value = rb.getString(key);
                 props.put(key,value);

            }
        }

    }

    public void onTearDown() throws Exception {
         super.onTearDown();

    }
}

