public Observable<ServiceResponse<PersonGroup>> getWithServiceResponseAsync(String personGroupId) {
    // Validate the input parameters
    if (personGroupId == null || personGroupId.isEmpty()) {
        throw new IllegalArgumentException("personGroupId cannot be null or empty");
    }

    // Construct the URL for the API request
    String url = String.format("%s/persongroups/%s", this.baseUrl, personGroupId);

    // Create the request object
    HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(url))
            .header("Ocp-Apim-Subscription-Key", this.subscriptionKey)
            .GET()
            .build();

    // Send the request and handle the response
    return Observable.create(emitter -> {
        try {
            HttpResponse<String> response = this.httpClient.send(request, HttpResponse.BodyHandlers.ofString());
            if (response.statusCode() == 200) {
                // Parse the response body to a PersonGroup object
                PersonGroup personGroup = this.gson.fromJson(response.body(), PersonGroup.class);
                emitter.onNext(new ServiceResponse<>(response.statusCode(), personGroup));
                emitter.onComplete();
            } else {
                emitter.onError(new RuntimeException("Failed to retrieve person group: " + response.statusCode()));
            }
        } catch (IOException | InterruptedException e) {
            emitter.onError(e);
        }
    });
}

import java.util.ArrayList;
import java.util.List;
 
public class PerfectTotientNumbers {
 
    public static void main(String[] args) {
        computePhi();
        int n = 20;
        System.out.printf("The first %d perfect totient numbers:%n%s%n", n, perfectTotient(n));
    }
 
    private static final List<Integer> perfectTotient(int n) {
        int test = 2;
        List<Integer> results = new ArrayList<Integer>();
        for ( int i = 0 ; i < n ; test++ ) {
            int phiLoop = test;
            int sum = 0;
            do {
                phiLoop = phi[phiLoop];
                sum += phiLoop;
            } while ( phiLoop > 1);
            if ( sum == test ) {
                i++;
                results.add(test);
            }
        }
        return results;
    }
 
    private static final int max = 100000;
    private static final int[] phi = new int[max+1];
 
    private static final void computePhi() {
        for ( int i = 1 ; i <= max ; i++ ) {
            phi[i] = i;
        }
        for ( int i = 2 ; i <= max ; i++ ) {
            if (phi[i] < i) continue;
            for ( int j = i ; j <= max ; j += i ) {
                phi[j] -= phi[j] / i;
            }
        }
    }
 
}

