import java.util.Arrays;
import java.util.Scanner;

public class Parser {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter list 1: ");
        int l1Size = in.nextInt();

        int[] l1 = new int[l1Size];
        for (int i = 0; i < l1.length; i++) {
            l1[i] = in.nextInt();
        }

        System.out.print("\nEnter list 2: ");
        int l2Size = in.nextInt();
        int[] l2 = new int[l2Size];

        for (int i = 0; i < l2.length; i++) {
            l2[i] = in.nextInt();
        }

        if (equals(l1, l2)) {
            System.out.println("The Two lists are identical.");
        } else {
            System.out.println("The two lists are not identical.");
        }
        in.close();
    }

    public static boolean equals(int[] list1, int[] list2) {
        Arrays.sort(list1);
        Arrays.sort(list2);

        if (list1.length != list2.length) {
            return false;
        }
        for (int i = 0; i < list1.length; i++) {
            if (list1[i] != list2[i]) {
                return false;
            }
        }
        return true;
    }
}

import com.googlecode.jsonrpc4j.JsonRpcParam;
import com.google.common.base.Preconditions;
import com.iblsoft.iwxxm.webservice.IwxxmValidator;
import com.iblsoft.iwxxm.webservice.ValidationRequest;
import com.iblsoft.iwxxm.webservice.ValidationResponse;
import com.iblsoft.iwxxm.webservice.ValidationResult;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class IwxxmWebServiceImpl {

    private static final Logger Log = LoggerFactory.getLogger(IwxxmWebServiceImpl.class);
    private static final String DEFAULT_IWXXM_VERSION = "1.1";
    private final IwxxmValidator iwxxmValidator;

    public IwxxmWebServiceImpl(String catalogFile, String ruleFile) {
        this.iwxxmValidator = new IwxxmValidator(catalogFile, ruleFile, DEFAULT_IWXXM_VERSION);
    }

    public ValidationResponse validate(@JsonRpcParam("request") ValidationRequest request) {
        Log.debug("Starting validation request: {}", request);

        Preconditions.checkNotNull(request, "Validation request cannot be null");
        Preconditions.checkArgument(checkRequestVersion(request.getVersion()), "Unsupported IWXXM version: " + request.getVersion());

        ValidationResult validationResult = iwxxmValidator.validate(request.getData(), request.getVersion());
        ValidationResponse response = ValidationResponse.builder()
                .withErrors(validationResult.getErrors())
                .build();

        Log.debug("Completed validation request: {}. Errors found: {}", request, response.getErrors().size());
        return response;
    }

    private boolean checkRequestVersion(String version) {
        return iwxxmValidator.supportsVersion(version);
    }
}

class ValidationResponse {
    private final java.util.List<String> errors;

    private ValidationResponse(Builder builder) {
        this.errors = builder.errors;
    }

    public static Builder builder() {
        return new Builder();
    }

    public java.util.List<String> getErrors() {
        return errors;
    }

    public static final class Builder {
        private java.util.List<String> errors;

        private Builder() {
            this.errors = new java.util.ArrayList<>();
        }

        public Builder withErrors(java.util.List<String> errors) {
            this.errors = errors;
            return this;
        }

        public ValidationResponse build() {
            return new ValidationResponse(this);
        }
    }
}

