public class StackOfIntegers {
    private int[] elements;
    private int size;
    public static final int DEFAULT_CAPACITY = 16;

    public StackOfIntegers() {
        this(DEFAULT_CAPACITY);
    }

    public StackOfIntegers(int capacity) {
        elements = new int[capacity];
    }

    public void push(int value) {
        if (size >= elements.length) {
            int[] temp = new int[elements.length * 2];
            System.arraycopy(elements, 0, temp, 0, elements.length);
            elements = temp;
        }
        elements[size++] = value;
    }

    public int pop() {
        return elements[--size];
    }

    public int peek() {
        return elements[size - 1];
    }

    public boolean empty() {
        return size == 0;
    }

    public int getSize() {
        return size;
    }
}

private static boolean needsEncoding(String s, boolean relax, boolean[] unreserved) {
        int len = s.length();
        for (int i = 0; i < len; ++i) {
            char c = s.charAt(i);
            if (c == '%' && relax) {
                continue;
            }
            if (c > unreserved.length) {
                return true;
            }
            if (unreserved[c] == false) {
                return true;
            }
        }
        return false;
    }

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Scanner;

/*
 * A minimal trivia-quiz game. Questions and their answers are loaded from
 * a text file ("sorular.txt"), where each line holds one question and its
 * answer separated by a colon (:). The player gets up to three guesses per
 * question, and a final tally of right/wrong answers is printed at the end.
 */

public class BilgiYarismasi {

    private static final int MAX_ATTEMPTS = 3;

    public static void main(String[] args) {

        int questionCount = 0;
        int correctCount = 0;

        try (BufferedReader fileReader = new BufferedReader(new FileReader("sorular.txt"))) {
            String line;
            Scanner console = new Scanner(System.in);

            while ((line = fileReader.readLine()) != null) {
                questionCount++;

                String[] fields = line.split(":");
                String question = fields[0];
                String answer = fields[1];

                System.out.println(question);
                boolean guessedRight = false;

                for (int attempt = 0; attempt < MAX_ATTEMPTS; attempt++) {
                    System.out.print("Tahmininizi girin: ");
                    String guess = console.nextLine();

                    if (guess.equalsIgnoreCase(answer)) {
                        System.out.println("Dogru!");
                        correctCount++;
                        guessedRight = true;
                        break;
                    }

                    if (attempt == MAX_ATTEMPTS - 1) {
                        System.out.println("Dogru cevap: " + answer);
                    } else {
                        System.out.println("Yanlis. Tekrar deneyin.");
                    }
                }
                // guessedRight isn't needed further; loop already reported results
            }
            console.close();
        } catch (IOException fileError) {
            System.out.println("Dosyadan okuma sirasinda hata: " + fileError.getMessage());
        }

        System.out.println("Dogru cevaplar: " + correctCount);
        System.out.println("Yanlis cevaplar: " + (questionCount - correctCount));
    }
}

@SuppressWarnings("restriction") public static long[] hash(final Memory mem, final long offsetBytes, final long lengthBytes, final long seed, final long[] hashOut) {
    // Implementation of the hash function
    // This is a placeholder for the actual hash function logic
    // For demonstration purposes, let's assume we are using a simple hash function
    long hash1 = 0;
    long hash2 = 0;
    for (long i = offsetBytes; i < offsetBytes + lengthBytes; i++) {
        byte b = mem.getByte(i);
        hash1 = (hash1 * 31 + b) % Long.MAX_VALUE;
        hash2 = (hash2 * 31 + b) % Long.MAX_VALUE;
    }
    hash1 ^= seed;
    hash2 ^= seed;
    hashOut[0] = hash1;
    hashOut[1] = hash2;
    return hashOut;
}

