public class Matrix {
    private static final int MOD = 1_000_000_7;

    public int uniquePathsIII(int m, int n, int maxMove, int startRow, int startColumn) {
        int[][][] dp = new int[m][n][maxMove + 1][2];

        // Initialize DP states for the starting position
        dp[startRow][startColumn][0][0] = 1;
        dp[startRow][startColumn][0][1] = 1;

        for (int moves = 0; moves <= maxMove; moves++) {
            for (int row = 0; row < m; row++) {
                for (int col = 0; col < n; col++) {
                    // If the current position is already out of boundary, skip it
                    if (row < 0 || col < 0 || row >= m || col >= n) continue;

                    // Check all possible moves
                    for (int[] dir : new int[][]{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}) {
                        int newRow = row + dir[0];
                        int newCol = col + dir[1];

                        // If the move is valid, update DP states
                        if (newRow >= 0 && newCol >= 0 && newRow < m && newCol < n) {
                            int nextState = (moves + 1) % 2;
                            dp[newRow][newCol][moves + 1][nextState] += (dp[row][col][moves][1 - nextState] + dp[row][col][moves][nextState]) % MOD;
                            dp[newRow][newCol][moves + 1][nextState] %= MOD;
                        }
                    }
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 || j == 0 || i == m - 1 || j == n - 1) {
                    sum = (sum + dp[i][j][maxMove][1]) % MOD;
                }
            }
        }

        return sum;
    }
}

class Utils {
        private static final int[][] MOVE = {
                {0, 1, 0, 1}, // right
                {1, 0, 1, 0}, // down
                {0, 0, 1, -1}, // cw
                {0, 0, -1, 1}, // ccw
        };

        public int minimumMoves(int[][] a) {
            int n = a.length;
            ArrayDeque<int[]> deque = new ArrayDeque<>(); // 0,1: tail, 2,3: head, 4: moves
            int[] init = {0, 0, 0, 1, 0};
            deque.add(init);

            Set<String> been = new HashSet<>();
            been.add(key(init));

            while (!deque.isEmpty()) {
                int[] cur = deque.removeFirst();
//                System.out.println("cur = " + Arrays.toString(cur));
                for (int j = 0; j < 4; j++) {
                    if (j == 2) {
                        if (!isHorizontal(cur) || !other(cur, a)) continue;
                    }
                    if (j == 3) {
                        if (!isVertical(cur) || !other(cur, a)) continue;
                    }
                    if (isHorizontal(cur) && j == 3) continue;
                    if (isVertical(cur) && j == 2) continue;
                    int[] m = MOVE[j];
                    int[] next = Arrays.copyOf(cur, 5);
                    for (int i = 0; i < 4; i++) next[i] += m[i];
                    next[4]++;

                    if (goal(next, n)) return next[4];

                    if (!valid(next, n, a)) continue;

                    String key = key(next);
                    if (been.contains(key)) continue;
                    been.add(key);
                    deque.add(next);
                }
            }

            return -1;
        }

        private boolean isHorizontal(int[] a) {
            return a[0] == a[2];
        }

        private boolean other(int[] cur, int[][] g) {
            int n = g.length;
            int row = cur[0] + 1;
            int col = cur[1] + 1;
            if (row >= n || col >= n || g[row][col] == 1) return false;
            return true;
        }

        private boolean isVertical(int[] a) {
            return a[1] == a[3];
        }

        private boolean goal(int[] a, int n) {
            return a[0] == n-1 && a[1] == n-2 && a[2] == n-1 && a[3] == n-1;
        }

        private boolean valid(int[] a, int n, int[][] g) {
            for (int i = 0; i < 4; i++) {
                if (a[i] < 0 || a[i] >= n) return false;
            }
            if (a[0] == a[2] && a[1] == a[3]) return false;
            return g[a[0]][a[1]] != 1 && g[a[2]][a[3]] != 1;
        }

