import java.util.Scanner;
import java.util.ArrayList;

public class Graph {
    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        ArrayList<Integer> testList = new ArrayList<>();

        System.out.println("Enter ten integers to put into the list now:");

        for (int i = 0; i < 10; i++) {
            testList.add(input.nextInt());
        }

        removeDuplicate(testList);

        System.out.print("The distinct integers are ");
        for (Integer integer : testList) {
            System.out.print(integer + " ");
        }
        input.close();
    }

    public static void removeDuplicate(ArrayList<Integer> list) {
        Integer temp;
        for (int i = 0; i < list.size(); i++) {

            temp = list.get(i);

            list.remove(i);

            while (list.contains(temp)) {

                list.remove(temp);
            }

            list.add(i, temp);

        }

    }
}

import java.util.Vector;
 
public class MertensNumbers {
    public static Vector<Integer> mertens_numbers(int max) {
        Vector<Integer> m = new Vector<Integer>(max + 1);
        for (int i = 0; i <= max; ++i)
            m.add(1);
        for (int n = 2; n <= max; ++n) {
            for (int k = 2; k <= n; ++k)
                m.set(n, m.get(n) - m.get(n / k));
        }
        return m;
    }
 
    public static void main(String[] args) {
        int max = 1000;
        Vector<Integer> m = mertens_numbers(max);
        System.out.println("First 199 Mertens numbers:");
        for (int i = 0, column = 0; i < 200; ++i) {
            if (column > 0)
                System.out.print(' ');
            if (i == 0)
                System.out.print("  ");
            else
                System.out.printf("%2d", m.get(i));
            ++column;
            if (column == 20) {
                System.out.println();
                column = 0;
            }
        }
        int zero = 0, cross = 0, previous = 0;
        for (int i = 1; i <= max; ++i) {
            if (m.get(i) == 0) {
                ++zero;
                if (previous!= 0)
                    ++cross;
            }
            previous = m.get(i);
        }
        System.out.printf("M(n) is zero %d times for 1 <= n <= 1000.\n", zero);
        System.out.printf("M(n) crosses zero %d times for 1 <= n <= 1000.\n", cross);
    }
}

public static void writeAtomically(File file, byte[] bytes) throws IOException {
        AtomicFile atomicFile = new AtomicFile(file);
        FileOutputStream stream = null;
        try {
            stream = atomicFile.startWrite();
            stream.write(bytes);
            atomicFile.finishWrite(stream);
        } catch (Exception e) {
            atomicFile.failWrite(stream);
            throw new IOException(e);
        }
    }

