class Helper {
    public String orderlyQueue(String S, int K) {
        if(K==1){
            char[] res = S.toCharArray();
            int idx = -1;
            char cur = (char)('z'+1);
            for(int i=0;i<res.length;i++){
                if(res[i]<cur){
                    idx = i;
                    cur = res[i];
                }
            }
            String min = S;
            for(int i=0;i<res.length;i++){
                if(res[i]==cur){
                    String curstr = S.substring(i)+S.substring(0,i);
                    if(curstr.compareTo(min)<0){
                        min=curstr;
                    }
                }
            }
            return min;
        }
        char[] res = S.toCharArray();
        Arrays.sort(res);
        return new String(res);
    }
}

