class Logger {

    private boolean check(String corridor) {
        int cnt = 0;
        for (char ch : corridor.toCharArray()) {
            if (ch == 'S') {
                cnt ++;
            }
        }
        return cnt % 2 == 0 && cnt > 0;
    }

    private long MOD = 1000_000_007L;

    public int numberOfWays(String corridor) {
        if (check(corridor)) {
            List<Integer> seats = new ArrayList<>();
            for (int i = 0;i < corridor.length();i ++) {
                if (corridor.charAt(i) == 'S') {
                    seats.add(i);
                }
            }
            long ans = 1;
            for (int i = 1;i < seats.size();i += 2) {
                if (i + 1 < seats.size()) {
                    long diff = seats.get(i + 1) - seats.get(i);
                    ans = (ans * diff) % MOD;
                }
            }
            return (int) ans;
        } else {
            return 0;
        }
    }

}

