class Student {

    private double prob = 1.0 / 8;
    private int[] dir1 = {1, -1};
    private int[] dir2 = {2, -2};

    private Map<String, Double> mem = new HashMap<>();

    public double knightProbability(int N, int K, int r, int c) {
        return probSurvive(N, K, r, c, 1.0);
    }

    private double probSurvive(int N, int K, int r, int c, double p) {
        String key = (r * N + c) + "a" + K;
        if (mem.containsKey(key)) return mem.get(key);

        if (K == 0) {
            mem.put(key, p);
            return p;
        }

        double res = 0.0;

        for(int dx : dir1) {
            for(int dy : dir2) {
                int row = r + dx, col = c + dy;
                if (row < 0 || row >= N || col < 0 || col >= N) continue;
                res += probSurvive(N, K - 1, row, col, p * prob);
            }
        }
        for(int dx : dir2) {
            for(int dy : dir1) {
                int row = r + dx, col = c + dy;
                if (row < 0 || row >= N || col < 0 || col >= N) continue;
                res += probSurvive(N, K - 1, row, col, p * prob);
            }
        }
        mem.put(key, res);
        return res;
    }
}

public String customSortString(String order, String s) {
        char[] oriOrder = order.toCharArray();
        char[] input = s.toCharArray();
        char[] output = new char[input.length];
        int index = 0;
        for(int i=0; i<oriOrder.length; i++){
            for(int j=0; j<s.length(); j++){
                if(input[j] == oriOrder[i]){
                    output[index] = oriOrder[i];
                    index++;
                }
            }
        }
        for(int i=0; i<s.length(); i++){
            for(int j=0; j<output.length; j++){
                if(s.charAt(i) == output[j]){
                    break;
                }else if(j == output.length-1){
                    output[index] = s.charAt(i);
                    index++;
                }
            }
        }
        return String.valueOf(output);
    }
}

