import java.util.HashMap;
import java.util.Map;
import javax.persistence.Column;
import javax.persistence.Entity;
import javax.persistence.Id;
import javax.persistence.MapKeyColumn;
import javax.persistence.MapKeyJoinColumn;
import javax.persistence.Table;
import javax.persistence.ElementCollection;
import javax.persistence.CollectionTable;
import javax.persistence.JoinColumn;

@Entity
@Table(name = "invalid_map_strategy_test")
public class InvalidMapStrategyTestEntity {

    @Id
    @Column(name = "entity_id")
    private Long id;

    @ElementCollection
    @CollectionTable(
        name = "map_field_collection",
        joinColumns = @JoinColumn(name = "parent_entity_id")
    )
    @MapKeyColumn(name = "map_key")
    @MapKeyJoinColumn(name = "map_key_reference")
    private Map<String, Integer> mapField;

    public InvalidMapStrategyTestEntity() {
        this.mapField = new HashMap<>();
    }

    public InvalidMapStrategyTestEntity(Long id) {
        this.id = id;
        this.mapField = new HashMap<>();
    }

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Map<String, Integer> getMapField() {
        return mapField;
    }

    public void setMapField(Map<String, Integer> mapField) {
        this.mapField = mapField;
    }

    public void addMapEntry(String key, Integer value) {
        if (this.mapField == null) {
            this.mapField = new HashMap<>();
        }
        this.mapField.put(key, value);
    }

    public void removeMapEntry(String key) {
        if (this.mapField != null) {
            this.mapField.remove(key);
        }
    }

    public boolean containsMapKey(String key) {
        return this.mapField != null && this.mapField.containsKey(key);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        InvalidMapStrategyTestEntity that = (InvalidMapStrategyTestEntity) o;

        if (id != null ? !id.equals(that.id) : that.id != null) return false;
        return mapField != null ? mapField.equals(that.mapField) : that.mapField == null;
    }

    @Override
    public int hashCode() {
        int result = id != null ? id.hashCode() : 0;
        result = 31 * result + (mapField != null ? mapField.hashCode() : 0);
        return result;
    }

    @Override
    public String toString() {
        return "InvalidMapStrategyTestEntity{" +
                "id=" + id +
                ", mapField=" + mapField +
                '}';
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;
 
public class PrimeGaps {
 
    public static void main(String[] args) {
        final int limit = 1000000;
        final int maxGroupSize = 4;
        PrimeSieve sieve = new PrimeSieve(limit);
        List<Diffs> diffs = new ArrayList<>();
        diffs.add(new Diffs(new int[]{2}));
        diffs.add(new Diffs(new int[]{1}));
        diffs.add(new Diffs(new int[]{2, 2}));
        diffs.add(new Diffs(new int[]{2, 4}));
        diffs.add(new Diffs(new int[]{4, 2}));
        diffs.add(new Diffs(new int[]{6, 4, 2}));
        List<Integer> group = new ArrayList<>();
        for (int p = 0; p < limit; ++p) {
            if (!sieve.isPrime(p)) {
                continue;
            }
            if (group.size() >= maxGroupSize) {
