class Reader {
    public boolean areAlmostEqual(String s1, String s2) {
        if (s1.equals(s2)) {
            return true;
        }
        for (int i = 0; i < s1.length(); i++) {
            for (int j = i+1; j < s1.length(); j++) {
                String s11 = s1.substring(0, i) + s1.charAt(j) + s1.substring(i+1, j) + s1.charAt(i) + s1.substring(j+1);
                if (s11.equals(s2)) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.util.InputMismatchException;
import java.util.Scanner;
 
public class Handler {
    public static void main(String[] args) {
        String s = grabInput("Give me a string")
               .orElseGet(e -> exitErr(e, e.getRawOsError().orElse(-1)));
 
        System.out.printf("You entered: %s%n", s.trim());
 
        int n = grabInput("Give me an integer")
               .map(String::trim)
               .map(Integer::parseInt)
               .orElseGet(e -> exitErr(e, e.getRawOsError().orElse(-1)));
 
        System.out.printf("You entered: %d%n", n);
    }
 
    private static String grabInput(String msg) {
        try (Scanner scanner = new Scanner(System.in)) {
            System.out.printf("%s: ", msg);
            return scanner.nextLine();
        }
    }
 
    private static RuntimeException exitErr(Throwable e, int code) {
        System.err.printf("Error: %s%n", e.getMessage());
        System.exit(code);
        return null;
    }
}

import java.util.Scanner;

public class OgrenciNumarasi {

    public static void main(String[] args) {

        Scanner input = new Scanner(System.in);

        System.out.println("Ogrenci numarasini giriniz:");
        int studentId = input.nextInt();

        // The leading two digits encode the enrollment year (offset from 2000).
        int enrollmentYear = studentId / 10000000 + 2000;
        System.out.println("Kayit yili: " + enrollmentYear);

        // The trailing three digits encode the student's registration order.
        int registrationOrder = studentId % 1000;
        System.out.println("Kayit sirasi: " + registrationOrder);

        // The fifth digit encodes the department code.
        int departmentCode = studentId / 100000 % 10;

        String departmentName;
        switch (departmentCode) {
            case 7:
                departmentName = "Elektrik Elektronik";
                break;
            case 6:
                departmentName = "Bilgisayar";
                break;
            case 5:
                departmentName = "Makina";
                break;
            default:
                departmentName = null;
        }

        if (departmentName != null) {
            System.out.println("Bolum: " + departmentName);
        } else {
            System.out.println("Bilinmeyen bolum");
        }

        input.close();
    }
}

import android.content.Intent;
import android.os.Bundle;
import android.view.MenuItem;
import android.support.v4.app.NavUtils;
import android.support.v7.app.AppCompatActivity;

public class FBListEventDetailActivity extends AppCompatActivity {
    public static final String ARG_ITEM_ID = "item_id";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_fblistevent_detail);

        if (getSupportActionBar() != null) {
            getSupportActionBar().setDisplayHomeAsUpEnabled(true);
        }

        if (savedInstanceState == null) {
            Bundle arguments = new Bundle();
            String itemId = getIntent().getStringExtra(ARG_ITEM_ID);

            if (itemId == null) {
                finish();
                return;
            }

            arguments.putString(ARG_ITEM_ID, itemId);
            FBListEventDetailFragment fragment = new FBListEventDetailFragment();
            fragment.setArguments(arguments);

            getSupportFragmentManager().beginTransaction()
                .add(R.id.fblistevent_detail_container, fragment)
                .commit();
        }
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        int id = item.getItemId();
        if (id == android.R.id.home) {
            Intent parentIntent = NavUtils.getParentActivityIntent(this);
            if (parentIntent == null) {
                parentIntent = new Intent(this, FBListEventListActivity.class);
                parentIntent.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP);
            }
            NavUtils.navigateUpTo(this, parentIntent);
            return true;
        }
        return super.onOptionsItemSelected(item);
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        outState.putString(ARG_ITEM_ID, getIntent().getStringExtra(ARG_ITEM_ID));
    }
}

class Comp implements Comparator<int[]>{
    public int compare(int[] a, int[] b){
        if (a[1] != b[1]) return a[1]-b[1];
        return a[0]-b[0];
    }
}
class Tree {
    private int getLatestIdx(int[][] arr, int start){
        int left = 0;
        int right = arr.length-1;
        while (left <= right){
            int mid = (left+right)/2;
            if (arr[mid][1] > start){
                right = mid-1;
            }
            else if (arr[mid][1] <= start){
                if (mid+1 < arr.length && arr[mid+1][1] <= start){
                    left = mid+1;
                }
                else{
                    return mid;
                }
            }
        }
        if (right >= 0) return left;
        return -1;
    }
    private void fillDp(int[][] arr, int[] dp){
        int n = arr.length;
        dp[0] = arr[0][2];
        for (int i = 1; i < n; i++){
            int lastIdx = getLatestIdx(arr,arr[i][0]);
            int lastVal = 0;
            if (lastIdx != -1){
                lastVal = dp[lastIdx];
            }
            dp[i] = Math.max(dp[i-1],arr[i][2] + lastVal);
        }
    }
    public int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int n = profit.length;
        int[][] arr = new int[n][];
        for (int i = 0; i < profit.length; i++){
            arr[i] = new int[]{startTime[i],endTime[i],profit[i]};
        }
        Arrays.sort(arr,new Comp());
        int[] dp = new int[n];
        fillDp(arr,dp);
        return dp[n-1];

    }
}

import java.io.*;

import java.util.*;

public class D {

    public static void main(String args[]) throws Exception {

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        PrintWriter pw = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));

        int t = Integer.parseInt(br.readLine());

        while(t --> 0) {

            int n = Integer.parseInt(br.readLine());

            int[] par = new int[n+1];

            int min = n;

            StringTokenizer st = new StringTokenizer(br.readLine());

            for(int i = 0; i < n; i++) {

                par[i+1] = Integer.parseInt(st.nextToken());

                par[i+1] ^= par[i];

            }

            HashMap<Integer, Integer> prev = new HashMap<Integer, Integer>();

            prev.put(0, 0);

            for(int i = 1; i <= n; i++) {

                if(prev.containsKey(par[i])) {

                    int ind = prev.get(par[i]);

                    prev.clear();

                    prev.put(par[ind], ind);

                    min--;

                }else {

                    prev.put(par[i], i);

                }

            }

            pw.println(min);

        }

        pw.close();

    }

}

