import org.apache.http.client.methods.HttpGet;
import org.proactive.command.utils.HttpResponseWrapper;
import org.proactive.core.StringUtility;
import org.proactive.rm.topology.TopologyView;
import org.proactive.utils.OperatingSystem;

public class GetTopologyCommand extends AbstractCommand {

    @Override
    public void execute(ApplicationContext applicationContext) throws Exception {
        String url = applicationContext.rmURL + "/topology";
        HttpGet request = new HttpGet(url);

        HttpResponseWrapper response = execute(request, applicationContext);

        if (statusCode(response, 200)) {
            TopologyView topology = readValue(response, TopologyView.class);
            applicationContext.resultStack().push(topology);

            if (!applicationContext.isSilent()) {
                writeLine(StringUtility.string(topology));
            }
        } else {
           handleError("Error getting topology: " + response.response.getStatusLine(), applicationContext);
        }
    }
}
