    public void testInvalidBrokerUrl() throws Exception {
        MqttClientConfigBean commonConf = new MqttClientConfigBean();
        commonConf.brokerUrl = "tcp://localhost:1833"; // Invalid MQTT Port
        commonConf.clientId = "testClient";
        commonConf.connectionTimeout = 10;
        commonConf.keepAlive = 20;

        MqttClientSourceConfigBean subscriberConf = new MqttClientSourceConfigBean();
        subscriberConf.topicFilters = ImmutableList.of("testTopic");
        subscriberConf.dataFormat = DataFormat.JSON;
        subscriberConf.dataFormatConfig.jsonContent = JsonMode.MULTIPLE_OBJECTS;

        MqttClientSource source = new MqttClientSource(commonConf, subscriberConf);

        PushSourceRunner runner = new PushSourceRunner.Builder(MqttClientDSource.class, source)
                .addOutputLane("lane")
                .build();

        AtomicBoolean stop = new AtomicBoolean(false);
        List<Record> records = null;
        try {
           runner.runInit();

           runner.runProduce(new PushSourceRunner.Callback() {
                @Override
                public void processBatch(StageRunner.Output output) {
                  stop.set(true);
                }
            });

            runner.waitOnProduce();

        } catch (StageException e) {

            Throwable cause = e.getCause();
            assertTrue(cause instanceof com.hivemq.client.mqtt.exceptions.ConnectionFailedException);

            assertEquals(Errors.MQTT_04, e.getErrorCode());
        } finally {
            runner.runDestroy();
        }
    }
}

