using namespace std;
typedef long long ll;
ll dp[10000+10],cost[10000+10],n,c,p2;
vector<ll> adj[10000+10];
void dfs(ll i) {
    for(auto x : adj[i])
        dp[i] = min(dp[i], dp[x]+1);
}
void solve(){
    cin >> n >> c >> p2;
    for(ll i = 1; i<=n;i++)
        cin >> cost[i];
    for(ll i=1;i<=n;i++){
        adj[i].clear();
    }
    for(ll i = 1; i < n; i++){
        ll a,b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    for(ll i=1;i<=n;i++) dp[i] = 1e18;
    dp[1]=0;
    dfs(1);
    ll ans=0;
    for(ll i=1;i<=n;i++){
        ll tmp = 1e18;
        if(dp[i] <= c*p2 && dp[i]<tmp){tmp=dp[i];}
        if(dp[i]<= c*(p2-1) && dp[i]<tmp){tmp=dp[i];}
    if(tmp==1e18){
                cout<<"-1\n";
            }
        else{
            cout<<tmp<<'\n';
        }

    }
}
int main(){
    ios_base::sync_with_stdio(false);cin.tie(NULL);
    cout.tie(NULL);
    ll t;cin>>t;
    while(t--)solve();
    return 0;
}

