import java.util.Collection;
import java.util.LinkedList;
import org.debian.alioth.shootout.u32.nbody.NBodySystem;

import com.tantaman.commons.concurrent.Parallel;

public class ParallelForDemo {

  public static void main(String[] args) {
    int numElements = 1000;
    int innerLoops = 100;

    Collection<Integer> elems = new LinkedList<>();
    for (int i = 0; i < numElements; i++) {
      elems.add(i);
    }

    NBodySystem system = new NBodySystem();

    // Warm up, do an empty operation to start with.
    Parallel.For(elems, i -> {
    });

    System.out.println("Beginning Parallel.For test.");
    long start = System.currentTimeMillis();

    Parallel.For(elems, i -> {
      for (int j = 0; j < innerLoops; j++) {
        system.advance(i);
      }
    });

    long end = System.currentTimeMillis();
    System.out.println("Parallel.For took " + (end - start) + " ms");

    system = new NBodySystem(); // Reset

    System.out.println("Beginning Parallel.ForFJ test.");
    start = System.currentTimeMillis();

    Parallel.ForFJ(elems, i -> {
      for (int j = 0; j < innerLoops; j++) {
        system.advance(i);
      }
    });

    end = System.currentTimeMillis();
    System.out.println("Parallel.ForFJ took " + (end - start) + " ms");
  }
}

