public class Triangle implements GLEventListener
{
  public void init(GLAutoDrawable drawable)
  {
    GL gl = drawable.getGL();
    GLU glu = new GLU();
    GLUT glut = new GLUT();
 
    gl.glClearColor(0.3f, 0.3f, 0.3f, 0.0f);
    gl.glShadeModel(GL.GL_SMOOTH);
    glu.gluOrtho2D(-30.0, 30.0, -30.0, 30.0);
  }
 
  public void reshape(GLAutoDrawable drawable, int x, int y, int width, int height)
  {
    GL gl = drawable.getGL();
 
    if (height <= 0)
    {
      height = 1;
    }
 
    final float h = (float) width / (float) height;
    gl.glViewport(0, 0, width, height);
    gl.glMatrixMode(GL.GL_PROJECTION);
    gl.glLoadIdentity();
    gl.glOrtho(-30.0, 30.0, -30.0, 30.0, -30.0, 30.0);
    gl.glMatrixMode(GL.GL_MODELVIEW);
    gl.glLoadIdentity();
  }
 
  public void display(GLAutoDrawable drawable)
  {
    GL gl = drawable.getGL();
 
    gl.glClear(GL.GL_COLOR_BUFFER_BIT | GL.GL_DEPTH_BUFFER_BIT);
    gl.glLoadIdentity();
    gl.glTranslatef(-15.0f, -15.0f, 0.0f);
 
    gl.glBegin(GL.GL_TRIANGLES);
    gl.glColor3f(1.0f, 0.0f, 0.0f);
    gl.glVertex2f(0.0f, 0.0f);
    gl.glColor3f(0.0f, 1.0f, 0.0f);
    gl.glVertex2f(30.0f, 0.0f);
    gl.glColor3f(0.0f, 0.0f, 1.0f);
    gl.glVertex2f(0.0f, 30.0f);
    gl.glEnd();
 
    gl.glFlush();
  }
 
  public void displayChanged(GLAutoDrawable drawable, boolean modeChanged, boolean deviceChanged)
  {
  }
 
  public static void main(String[] args)
  {
    Frame frame = new Frame("Triangle");
    GLCanvas canvas = new GLCanvas();
 
    canvas.addGLEventListener(new Triangle());
    frame.add(canvas);
    frame.setSize(640, 480);
    final GLCanvas finalCanvas = canvas;
    frame.addWindowListener(new WindowAdapter()
    {
      public void windowClosing(WindowEvent e)
      {
        finalCanvas.destroy();
        System.exit(0);
      }
    });
    frame.setVisible(true);
  }
}

public class Processor {
    public long maxHeightCuts(int[] maxHeights) {
        int n = maxHeights.length;
        int[] left = new int[n];
        int[] right = new int[n];

        left[0] = maxHeights[0];
        for (int i = 1; i < n; i++) {
            left[i] = Math.min(maxHeights[i], left[i - 1] + 1);
        }

        right[n - 1] = maxHeights[n - 1];
        for (int i = n - 2; i >= 0; i--) {
            right[i] = Math.min(maxHeights[i], right[i + 1] + 1);
        }

        long maxSum = 0;
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += left[i];
            maxSum = Math.max(maxSum, sum);
            if (i < n - 1) {
                sum -= left[i];
                sum += Math.min(left[i], right[i + 1]);
            }
        }

        for (int i = n - 1; i >= 0; i--) {
            sum += right[i];
            maxSum = Math.max(maxSum, sum);
            if (i > 0) {
                sum -= right[i];
                sum += Math.min(right[i], left[i - 1]);
            }
        }

        return maxSum;
    }
}

