public synchronized Rect getFramingRectInPreview() {
    if (framingRectInPreview == null) {
      Rect framingRect = getFramingRect();
      if (framingRect == null) {
        return null;
      }
      Rect rect = new Rect(framingRect);
      Point cameraResolution = configManager.getCameraResolution();
      Point screenResolution = configManager.getScreenResolution();
      if (cameraResolution == null || screenResolution == null) {

        return null;
      }
      rect.left = rect.left * cameraResolution.x / screenResolution.x;
      rect.right = rect.right * cameraResolution.x / screenResolution.x;
      rect.top = rect.top * cameraResolution.y / screenResolution.y;
      rect.bottom = rect.bottom * cameraResolution.y / screenResolution.y;
      framingRectInPreview = rect;
    }
    return framingRectInPreview;
  }

private static String readArrayValue(String ref, TypeDef source, Property property) {
        TypeRef typeRef = property.getTypeRef();
        if (typeRef instanceof ClassRef) {

            return readObjectArrayValue(ref, source, property);
        }
        if (typeRef instanceof PrimitiveRef) {
            return readPrimitiveArrayValue(ref, source, property);
        }
        throw new IllegalStateException("Property should be either an object or a primitive.");
    }

class Tree {
    public int atMostNGivenDigitSet(String[] D, int N) {
        int count = 0;
        int[] nums = new int[D.length];
        for (int i = 0; i < D.length; ++i) {
            nums[i] = Integer.parseInt(D[i]);
        }
        int po = 0;
        Stack<Integer> stack = new Stack<>();
        while (N >= 10) {
            stack.push(N % 10);
            N = N / 10;
            po++;
        }
        stack.push(N);
        for (int i = 1; i <= po; ++i) {
            count += Math.pow(nums.length, i);
        }

        while (!stack.isEmpty()) {
            int cur = stack.pop();
            boolean has = false;
            for (int num : nums) {
                if (num < cur) {
                    count += Math.pow(nums.length, po);
                } else if (num == cur) {
                    has = true;
                    break;
                }
            }
            if (!has) {
                break;
            } else {
                po--;
                if (stack.isEmpty()) {
                    count++;
                }
            }
        }
        return count;

    }
}

