class Manager {
    public int countDistinctIntegers(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int num : nums) {
            set.add(num);
            int tmp = num;
            int res = 0;
            while (tmp > 0) {
                res *= 10;
                res += tmp % 10;
                tmp /= 10;
            }
            set.add(res);
        }
        return set.size();
    }
}

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
 
public class FloydWarshall {
 
    public static final int Infinity = Integer.MAX_VALUE;
 
    public static void main(String[] args) {
        Graph g = new Graph();
        g.edge(1, 3, -2);
        g.edge(3, 4, 2);
        g.edge(4, 2, -1);
        g.edge(2, 1, 4);
        g.edge(2, 3, 3);
 
        Map<Integer, Map<Integer, Integer>> dist = FloydWarshall(g);
        Map<Integer, Map<Integer, Integer>> next = FloydWarshall(g);
        System.out.println("pair\tdist\tpath");
        for (int u : dist.keySet()) {
            for (int v : dist.get(u).keySet()) {
                if (u!= v) {
                    System.out.printf("%d -> %d\t%3d\t%s\n", u, v, dist.get(u).get(v), g.path(Path(u, v, next)));
                }
            }
        }
    }
 
    public static Map<Integer, Map<Integer, Integer>> FloydWarshall(Graph g) {
        List<Integer> vert = g.Vertices();
        Map<Integer, Map<Integer, Integer>> dist = new HashMap<>();
        Map<Integer, Map<Integer, Integer>> next = new HashMap<>();
        for (int u : vert) {
            dist.put(u, new HashMap<>());
            next.put(u, new HashMap<>());
            for (int v : vert) {
                dist.get(u).put(v, Infinity);
            }
            dist.get(u).put(u, 0);
            for (int v : g.Neighbors(u)) {
                dist.get(u).put(v, g.Weight(u, v));
                next.get(u).put(v, v);
            }
        }
        for (int k : vert) {
            for (int i : vert) {
                for (int j : vert) {
                    if (dist.get(i).get(k) < Infinity && dist.get(k).get(j) < Infinity) {
                        if (dist.get(i).get(j) > dist.get(i).get(k) + dist.get(k).get(j)) {
                            dist.get(i).put(j, dist.get(i).get(k) + dist.get(k).get(j));
                            next.get(i).put(j, next.get(i).get(k));
                        }
                    }
                }
            }
        }
        return dist;
    }
 
    public static List<Integer> Path(int u, int v, Map<Integer, Map<Integer, Integer>> next) {
        if (next.get(u).get(v) == null) {
            return new ArrayList<>();
        }
        List<Integer> path = new ArrayList<>();
        path.add(u);
        while (u!= v) {
            u = next.get(u).get(v);
            path.add(u);
        }
        return path;
    }
 
