import com.badlogic.gdx.math.Vector2;
import com.badlogic.gdx.scenes.scene2d.Group;
import com.badlogic.gdx.scenes.scene2d.actions.Actions;
import com.badlogic.gdx.scenes.scene2d.ui.Dialog;
import java.util.Optional;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class Tray extends Group {

    private static final Logger logger = LogManager.getLogger(Tray.class);
    private boolean isHidden = true;
    private final TrayCard taskCard;
    private final ConversationDialog dialog;
    private final TaskList taskList;
    private Optional<Quest> quest = Optional.empty();

    public Tray(TaskList taskList, TrayCard card, ConversationDialog dialog) {
        this.taskList = taskList;
        this.taskCard = card;
        this.dialog = dialog;
        addActor(dialog);
        addActor(taskCard);
        setY(-100); // Initially off-screen
    }

    @Override
    public void act(float delta) {
        super.act(delta);
        Optional<Quest> currentQuest = taskList.getCurrentQuest();

        if (currentQuest.isPresent() && !currentQuest.equals(quest)) {
            quest = currentQuest;
            showTray();
        } else if (currentQuest.isEmpty()) {
            hideTray();
        }
    }

    public void showTray() {
        quest.ifPresent(q -> {
            String name = q.zone.map(z -> z.personName).orElse("");
            String text = q.zone.map(z -> z.text).orElse("");

            taskCard.setText(text, name);
            dialog.setText(name, text);

        });
        isHidden = false;
        this.clearActions();
        this.addAction(Actions.moveTo(getX(), 0, 0.5f)); // Slide down
         logger.info("Tray shown");
    }

    public void hideTray() {
        isHidden = true;
        this.clearActions();
        this.addAction(Actions.moveTo(getX(), -100, 0.5f)); // Slide up
        logger.info("Tray hidden");
    }

    public void toggle() {
        if (isHidden) {
            showTray();
        } else {
            hideTray();
        }
    }
}

/**
 * A line segment that extends Point to reuse the "begin" coordinate,
 * while composing a second Point for the "end" coordinate.
 */
public class LineSub extends Point {

    private Point endPoint;

    public LineSub(Point begin, Point end) {
        super(begin.getX(), begin.getY());
        this.endPoint = end;
    }

    public LineSub(int beginX, int beginY, int endX, int endY) {
        super(beginX, beginY);
        this.endPoint = new Point(endX, endY);
    }

    @Override
    public String toString() {
        return "LineSub[begin=" + super.toString() + ",end=" + endPoint + ']';
    }

    public Point getBegin() {
        return new Point(getX(), getY());
    }

    public Point getEnd() {
        return endPoint;
    }

    public void setBegin(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEnd(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getBeginX() {
        return getX();
    }

    public int getBeginY() {
        return getY();
    }

    public int getEndX() {
        return endPoint.getX();
    }

    public int getEndY() {
        return endPoint.getY();
    }

    public void setBeginX(int beginX) {
        setX(beginX);
    }

    public void setBeginY(int beginY) {
        setY(beginY);
    }

    public void setBeginXY(int beginX, int beginY) {
        setXY(beginX, beginY);
    }

    public void setEndX(int endX) {
        endPoint.setX(endX);
    }

    public void setEndY(int endY) {
        endPoint.setY(endY);
    }

    public void setEndXY(int endX, int endY) {
        endPoint.setXY(endX, endY);
    }

    public int getLength() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        double distance = Math.sqrt(dx * dx + dy * dy);
        return (int) distance;
    }

    public double getGradient() {
        int dx = endPoint.getX() - getX();
        int dy = endPoint.getY() - getY();
        return Math.atan2(dy, dx);
    }
}

class TestLineSub {
    public static void main(String[] args) {
        LineSub lineSub = new LineSub(8, 9, 6, 7);
        System.out.println(lineSub.getBegin());
        System.out.println(lineSub.getEnd());
        System.out.println(lineSub.getLength());
        System.out.println(lineSub.getGradient());
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;

/*
 * Reads arithmetic expressions line by line from "islemler.txt". Each line
 * holds two numbers and an operator separated by spaces; the computed
 * result for each line is printed to the console.
 */

public class HesapMakinesi {

    public static void main(String[] args) {

        try {
            BufferedReader lineSource = new BufferedReader(new FileReader("islemler.txt"));
            String line;

            while ((line = lineSource.readLine()) != null) {
                String[] tokens = line.split(" ");
                int operandA = Integer.parseInt(tokens[0]);
                int operandB = Integer.parseInt(tokens[2]);
                char operator = tokens[1].charAt(0);
                int result;

                switch (operator) {
                    case '+':
                        result = operandA + operandB;
                        break;
                    case '-':
                        result = operandA - operandB;
                        break;
                    case '*':
                        result = operandA * operandB;
                        break;
                    case '/':
                        if (operandB == 0) {
                            System.out.println("Hata: Sifira bolme yapilamaz!");
                            continue; // skip printing, move to the next line
                        }
                        result = operandA / operandB;
                        break;
                    default:
                        result = 0;
                        break;
                }

                System.out.println(operandA + " " + operator + " " + operandB + " = " + result);
            }

            lineSource.close();
        } catch (IOException fileEx) {
            System.out.println("Dosya okunurken bir hata olustu: " + fileEx.getMessage());
        } catch (NumberFormatException parseEx) {
            System.out.println("Sayilari parse ederken bir hata olustu: " + parseEx.getMessage());
        }
    }
}

import org.lwjgl.LWJGLException;
import org.lwjgl.opengl.Display;
import org.lwjgl.opengl.DisplayMode;
import static org.lwjgl.opengl.GL11.*;
 
 
public class OpenGlExample {
 
    public void run() throws LWJGLException {
        Display.setDisplayMode(new DisplayMode(640, 480));
        Display.create();
 
        glMatrixMode(GL_PROJECTION);
        glLoadIdentity();
        glOrtho(-30, 30, -30, 30, -30, 30);
        glMatrixMode(GL_MODELVIEW);
 
        while(!Display.isCloseRequested()) {
            render();
 
            Display.update();
        }
 
        Display.destroy();
    }
 
    public void render() {
 
        glClearColor(0.3f, 0.3f, 0.3f, 0.0f);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
 
        glShadeModel(GL_SMOOTH);
 
        glLoadIdentity();
        glTranslatef(-15.0f, -15.0f, 0.0f);
 
        glBegin(GL_TRIANGLES);
        glColor3f(1.0f, 0.0f, 0.0f);
        glVertex2f(0.0f, 0.0f);
        glColor3f(0.0f, 1.0f, 0.0f);
        glVertex2f(30f, 0.0f);
        glColor3f(0.0f, 0.0f, 1.0f);
        glVertex2f(0.0f, 30.0f);
        glEnd();
 
    }
 
    public static void main(String[] args) {
        OpenGlExample openGlExmpl = new OpenGlExample();
        try {
            openGlExmpl.run();
        } catch(LWJGLException e) {
            System.err.println(e);
        }
    }
 
}

