     * @return
     */
    Collision getCollision(GanttCalendar calendar);

    /**
     * @param calendar
     * @return
     */
    Collision getBackwardCollision(GanttCalendar calendar);

    /**
     * Returns the name of this constraint
     *
     * @return
     */
    String getName();

    ActivityBinding getActivityBinding();

    interface Collision {
        /**
         * @return The acceptable date to start the bound task
         */
        Date getAcceptableStart();

        /**
         * Gets the variation needed for task to be scheduled.
         * <br>
         * Possible values are
         * {@link TaskDependencyConstraint#NO_VARIATION} - No variation needed
         * {@link TaskDependencyConstraint#START_EARLIER_VARIATION} - Task should be started earlier
         * {@link TaskDependencyConstraint#START_LATER_VARIATION} - Task should be started later
         *
         * @return
         */
        int getVariation();
        /**
         * @return true if collision is caused by active constraint
         */
        boolean isActive();
    }

    TaskDependencyConstraint clone();

    class DefaultCollision implements Collision{
        private final Date acceptableStart;
        private final int variation;
        private final boolean active;

        public DefaultCollision(Date acceptableStart, int variation, boolean active) {
            this.acceptableStart = acceptableStart;
            this.variation = variation;
            this.active = active;
        }

        @Override
        public Date getAcceptableStart() {
            return acceptableStart;
        }

        @Override
        public int getVariation() {
            return variation;
        }

        @Override
        public boolean isActive() {
            return active;
        }
    }
}

public class Time {
    private int hour;
    private int minute;
    private int second;

    public Time() {
        this(System.currentTimeMillis());
    }

    public Time(long elapsedTime) {
        setTime(elapsedTime);
    }

    public Time(int hour, int minute, int second) {
        this.hour = hour;
        this.minute = minute;
        this.second = second;
    }

    public int getHour() {
        return hour;
    }

    public int getMinute() {
        return minute;
    }

    public int getSecond() {
        return second;
    }

    public void setTime(long elapsedTime) {
        long totalSeconds = elapsedTime / 1000;
        second = (int) (totalSeconds % 60);
        long totalMinutes = totalSeconds / 60;
        minute = (int) (totalMinutes % 60);
        long totalHours = totalMinutes / 60;
        hour = (int) (totalHours % 24);
    }

    @Override
    public String toString() {
        return String.format("%02d:%02d:%02d", hour, minute, second);
    }
}

