class Game {
  public String firstPalindrome(String[] words) {
    for (String s : words) {
      if (check(s)) {
        return s;
      }
    }
    return "";
  }

  private boolean check(String s) {
    int le = 0, ri = s.length() - 1;
    while (le < ri) {
      if (s.charAt(le++) != s.charAt(ri--)) {
        return false;
      }
    }
    return true;
  }
}

class Checker {
    public int maxIncreasingCells(int[][] a) {
        int n = a.length, m = a[0].length;
        List<int[]> list = new ArrayList<>();
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                list.add(new int[]{a[i][j], i, j});
            }
        }

        int res = 0;
        Collections.sort(list, (x, y) -> {
            return x[0] - y[0];
        });

        int rdp[] = new int[n];
        int cdp[] = new int[m];

        int N = list.size();
        for(int i = 0; i < N; i++) {
            int j = i;
            List<int[]> info = new ArrayList<>();
            while(j < list.size() && list.get(j)[0] == list.get(i)[0]) {
                int p[] = list.get(j);
                int r = p[1], c = p[2];
                int mx = Math.max(1 + rdp[r], 1 + cdp[c]);
                info.add(new int[]{mx, r, c});
                j++;
            }

            for(int p[] : info) {
                res = Math.max(res, p[0]);
                int  r = p[1], c = p[2], v = p[0];
                rdp[r] = Math.max(rdp[r], v);
                cdp[c] = Math.max(cdp[c], v);
            }

            i = j - 1;
        }

        return res;
    }
}

