/**
 * Manages the list of pre-defined values for a parameter that consists of a
 * single String value.
 * @param <T> the parameter class
 */
public class VCardParameterCaseClasses<T extends VCardParameter> extends CaseClasses<T, String> {
    public VCardParameterCaseClasses(Class<T> clazz) {
        super(clazz);
    }

    @Override
    protected T create(String value) {
        //reflection: return new ClassName(value);
        try {
            //try (String) constructor
            Constructor<T> constructor = clazz.getDeclaredConstructor(String.class);
            constructor.setAccessible(true);
            return constructor.newInstance(value);
        } catch (Exception e) {
            try {
                //try (String, VCardVersion...) constructor
                Constructor<T> constructor = clazz.getDeclaredConstructor(String.class, VCardVersion[].class);
                constructor.setAccessible(true);
                return constructor.newInstance(value, new VCardVersion[] {});
            } catch (Exception e2) {
                throw new RuntimeException(e2);
            }
        }
    }

    @Override

class Display {
    synchronized void disp(int value) {
        try {
            Thread.sleep(100); // Simulate delay for thread-safe output
        } catch (InterruptedException e) {
            System.out.println("Thread interrupted");
        }
        System.out.println("Value: " + value);
    }
}

class Thread1 implements Runnable {
    Display d1;
    int num;

    Thread1(Display d1, int num) {
        this.d1 = d1;
        this.num = num;
    }

    public void run() {
        int factorial = 1;
        for (int i = 1; i <= num; i++) {
            factorial *= i;
        }
        synchronized (d1) {
            d1.disp(factorial);
        }
    }
}

class Thread2 implements Runnable {
    Display d1;
    int n;

    Thread2(Display d1, int n) {
        this.d1 = d1;
        this.n = n;
    }

    public void run() {
        int a = 0, b = 1, c = 0;
        for (int i = 2; i <= n; i++) {
            c = a + b;
            a = b;
            b = c;
        }
        synchronized (d1) {
            d1.disp(c);
        }
    }
}

class Thread3 implements Runnable {
    Display d1;
    int[] arr;

    Thread3(Display d1, int[] arr) {
        this.d1 = d1;
        this.arr = arr;
    }

    public void run() {
        int n = arr.length;
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - i - 1; j++) {
                if (arr[j] > arr[j + 1]) {
                    int temp = arr[j];
                    arr[j] = arr[j + 1];
                    arr[j + 1] = temp;
                }
            }
        }
        synchronized (d1) {
            System.out.print("Sorted Array: ");
            for (int i : arr) {
                System.out.print(i + " ");
            }
            System.out.println();
        }
    }
}

public class ThreadDemo {
    public static void main(String[] args) {
        Display d1 = new Display();

        Thread1 t1 = new Thread1(d1, 5);
        Thread2 t2 = new Thread2(d1, 10);
        int[] arr = {5, 3, 8, 1, 2};
        Thread3 t3 = new Thread3(d1, arr);

        Thread ob1 = new Thread(t1);
        Thread ob2 = new Thread(t2);
        Thread ob3 = new Thread(t3);

        ob1.start();
        ob2.start();
        ob3.start();

        try {
            ob1.join();
            ob2.join();
            ob3.join();
        } catch (InterruptedException e) {
            System.out.println("Main thread interrupted");
        }

        System.out.println("All threads have finished execution.");
    }
}

@Override
    protected int handleGetMonthLength(int extendedYear, int month) {
        int length;
        if (cType == CalculationType.ISLAMIC_CIVIL
                || cType == CalculationType.ISLAMIC_TBLA
                || (cType == CalculationType.ISLAMIC_UMALQURA && (extendedYear < UMALQURA_YEAR_START  || extendedYear > UMALQURA_YEAR_END) )) {
            length = 29 + (month+1) % 2;
            if (month == DHU_AL_HIJJAH && civilLeapYear(extendedYear)) {
                length++;
            }
        }
        else if (cType == CalculationType.ISLAMIC) {
            month = 12*(extendedYear-1) + month;
            length = (int)( trueMonthStart(month+1) - trueMonthStart(month) );
        }
        else {
            int idx = (extendedYear - UMALQURA_YEAR_START);
            int mask = (0x01 << (11 - month));
            if((UMALQURA_MONTHLENGTH[idx] & mask) == 0 ) {
                length = 29;
            }
            else {
                length = 30;
            }
        }
        return length;
    }

// Shannon entropy in bits per symbol.
public static double entropy(String str) {
  int len = str.length();

  // Build a frequency map from the string.
  Map<Character, Integer> frequencies = new HashMap<>();
  for (char c : str.toCharArray()) {
    frequencies.put(c, frequencies.getOrDefault(c, 0) + 1);
  }

  // Sum the frequency of each character.
  return frequencies.values().stream()
   .mapToDouble(f -> -f / len * Math.log(f / len) / Math.log(2))
   .sum();
}

System.out.println(entropy("1223334444")); // 1.8464393446710154
System.out.println(entropy("0"));          // 0
System.out.println(entropy("01"));         // 1
System.out.println(entropy("0123"));       // 2
System.out.println(entropy("01234567"));   // 3
System.out.println(entropy("0123456789abcdef")); // 4

/**
 * A triangle composed of three MyPoint vertices.
 */
class MyPoint {

    private int x;
    private int y;

    public MyPoint() {
    }

    public MyPoint(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public int getX() {
        return x;
    }

    public void setX(int x) {
        this.x = x;
    }

    public int getY() {
        return y;
    }

    public void setY(int y) {
        this.y = y;
    }

    public int[] getXY() {
        return new int[]{x, y};
    }

    public void setXY(int x, int y) {
        this.x = x;
        this.y = y;
    }

    public double distance(int x, int y) {
        return Math.sqrt(Math.pow(x - this.x, 2) + Math.pow(y - this.y, 2));
    }

    public double distance(MyPoint another) {
        return Math.sqrt(Math.pow(another.x - x, 2) + Math.pow(another.y - y, 2));
    }

    public double distance() {
        return Math.sqrt(Math.pow(-x, 2) + Math.pow(-y, 2));
    }

    @Override
    public String toString() {
        return "(" + x + "," + y + ')';
    }
}

public class MyTriangle {
    private MyPoint v1;
    private MyPoint v2;
    private MyPoint v3;

    public MyTriangle(int x1, int y1, int x2, int y2, int x3, int y3) {
        this.v1 = new MyPoint(x1, y1);
        this.v2 = new MyPoint(x2, y2);
        this.v3 = new MyPoint(x3, y3);
    }

    public MyTriangle(MyPoint v1, MyPoint v2, MyPoint v3) {
        this.v1 = v1;
        this.v2 = v2;
        this.v3 = v3;
    }

    public MyPoint getV1() {
        return v1;
    }

    public void setV1(MyPoint v1) {
        this.v1 = v1;
    }

    public MyPoint getV2() {
        return v2;
    }

    public void setV2(MyPoint v2) {
        this.v2 = v2;
    }

    public MyPoint getV3() {
        return v3;
    }

    public void setV3(MyPoint v3) {
        this.v3 = v3;
    }

    public double getPerimeter() {
        return v1.distance(v2) + v2.distance(v3) + v3.distance(v1);
    }

    public String getType() {
        double side12 = v1.distance(v2);
        double side23 = v2.distance(v3);
        double side31 = v3.distance(v1);
        if (side12 == side23 && side12 == side31) {
            return "Equilateral";
        } else if (side12 == side23 || side12 == side31 || side31 == side23) {
            return "Isosceles";
        } else {
            return "Scalene";
        }
    }

    @Override
    public String toString() {
        return "MyTriangle[v1=" + v1.toString() + ",v2=" + v2.toString() + ",v3=" + v3.toString() + ']';
    }
}

