/**
 * A key-value map that can be saved to the database.
 */
@SuppressWarnings("rawtypes")
public interface BSONObject {

    /**
     * Sets a name/value pair in this object.
     *
     * @param key Name to set
     * @param v   Corresponding value
     * @return the previous value associated with <tt>key</tt>, or <tt>null</tt> if there was no mapping for <tt>key</tt>. (A <tt>null</tt>
     * return can also indicate that the map previously associated <tt>null</tt> with <tt>key</tt>.)
     */
    Object put(String key, Object v);

    /**
     * Sets all key/value pairs from an object into this object
     *
     * @param o the object
     */
    void putAll(BSONObject o);

    /**
     * Sets all key/value pairs from a map into this object
     *
     * @param m the map
     */
    void putAll(Map m);

    /**
     * Gets a field from this object by a given name.
     *
     * @param key The name of the field fetch
     * @return The field, if found
     */
    Object get(String key);

    /**
     * Returns a map representing this BSONObject.
     *
     * @return the map
     */
    Map toMap();

    /**
     * Removes a field with a given name from this object.
     *
     * @param key The name of the field to remove
     * @return The value removed from this object
     */
    Object removeField(String key);

    /**
     * Deprecated
     *
     * @param key the key to check
     * @return True if the key is present
     * @deprecated Please use {@link #containsField(String)} instead
     */
    @Deprecated
    boolean containsKey(String key);

    /**
     * Checks if this object contains a field with the given name.
     *
     * @param s Field name for which to check
     * @return True if the field is present
     */
    boolean containsField(String s);

    /**
     * Returns this object's fields' names
     *
     * @return The names of the fields in this object
     */
    Set<String> keySet();
}

public void removeChildNode() throws ChildNodeException {
    Node parentLast;
    Node thisLast;

    if (!isLeaf() && hasParent()) {
      parentLast = getParentNode().getFirstChild().getPrevSibling();
      thisLast = getFirstChild().getPrevSibling();

      parentLast.setNextSibling(getFirstChild());

      thisLast.setNextSibling(getParentNode().getFirstChild());

      getParentNode().removeChild(this);
    }
  }

public class Writer {
    public int minSteps(int n) {
        Integer[][] dp = new Integer[n + 1][n + 1];
        return dfs(1, 0, n, dp);
    }
    private int dfs(int i, int j, int n, Integer[][] dp) {
        if (i > n) return Integer.MAX_VALUE;
        if (i == n) return 0;
        if (dp[i][j] != null) return dp[i][j];
        int ans = Integer.MAX_VALUE;
        if (i != j) { // copy
            ans = dfs(i, i, n, dp);
        }
        if (j != 0) {
            ans = Math.min(ans, dfs(i + j, j, n, dp));
        }
        if (ans == Integer.MAX_VALUE) return Integer.MAX_VALUE;
        return dp[i][j] = ans + 1;
    }
}

