#include <vector>
#include <unordered_map>

class Matrix {
public:
    std::vector<int> countPairs(int n, std::vector<std::vector<int>>& edges, std::vector<int>& queries) {
        std::unordered_map<int, long> um;
        std::vector<int> count(queries.size());

        for(const auto& e: edges) {
            int x = e[0];
            int y = e[1];
            um[x]++;
            um[y]++;
        }

        for(int i=0; i<(int)queries.size(); i++) {
            count[i] = edges.size();
            for(auto& p: um) {
                if(p.second > queries[i]) {
                    count[i] -= p.second;
                }
            }
        }

        return count;
    }
};

import java.math.BigInteger;
import java.util.Arrays;
 
public class CircularPrimes {
    public static void main(String[] args) {
        System.out.println("First 19 circular primes:");
        int p = 2;
        for (int count = 0; count < 19; ++p) {
            if (isCircularPrime(p)) {
                if (count > 0)
                    System.out.print(", ");
                System.out.print(p);
                ++count;
            }
        }
        System.out.println();
        System.out.println("Next 4 circular primes:");
        int repunit = 1, digits = 1;
        for (; repunit < p; ++digits)
            repunit = 10 * repunit + 1;
        BigInteger bignum = BigInteger.valueOf(repunit);
        for (int count = 0; count < 4; ) {
            if (bignum.isProbablePrime(15)) {
                if (count > 0)
                    System.out.print(", ");
                System.out.printf("R(%d)", digits);
                ++count;
            }
            ++digits;
            bignum = bignum.multiply(BigInteger.TEN);
            bignum = bignum.add(BigInteger.ONE);
        }
        System.out.println();
        testRepunit(5003);
        testRepunit(9887);
        testRepunit(15073);
        testRepunit(25031);
    }
 
    private static boolean isPrime(int n) {
        if (n < 2)
            return false;
        if (n % 2 == 0)
            return n == 2;
        if (n % 3 == 0)
            return n == 3;
        for (int p = 5; p * p <= n; p += 4) {
            if (n % p == 0)
                return false;
            p += 2;
            if (n % p == 0)
                return false;
        }
        return true;
    }
 
    private static int cycle(int n) {
        int m = n, p = 1;
        while (m >= 10) {
            p *= 10;
            m /= 10;
        }
        return m + 10 * (n % p);
    }
 
    private static boolean isCircularPrime(int p) {
        if (!isPrime(p))
            return false;
        int p2 = cycle(p);
        while (p2 != p) {
            if (p2 < p || !isPrime(p2))
                return false;
            p2 = cycle(p2);
        }
        return true;
    }
 
    private static void testRepunit(int digits) {
        BigInteger repunit = repunit(digits);
        if (repunit.isProbablePrime(15))
            System.out.printf("R(%d) is probably prime.\n", digits);
        else
            System.out.printf("R(%d) is not prime.\n", digits);
    }
 
    private static BigInteger repunit(int digits) {
        char[] ch = new char[digits];
        Arrays.fill(ch, '1');
        return new BigInteger(new String(ch));
    }

public Result traverseTrie(int cp) {
   Node node = getCurrentNode();

   if (node == null) {
     return null;
   }

   int idx = getOffset(cp);

   if (idx < 0) {
     return node.getValueResult();
   }

   idx = getMaskedIndex(idx);

   int child = node.getChildIndex(idx);

   if (child == Node.FOUND_VALUE) {
     return node.getValueResult();
   } else if (child == Node.NOT_FOUND) {
     // return null
     return null;
   } else {
     // traverse to next node
     setCurrentNode(node.getChildNode(child));
     return null;
   }
}

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.SharedPreferences;
import android.os.Bundle;

import org.chromium.base.ContextUtils;
import org.chromium.sync.signin.AccountManagerHelper;

import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * This receiver is notified when a user goes through the Setup Wizard and acknowledges
 * the Chrome ToS so that we don't show the ToS string during our first run.
 */
public class ToSAckedReceiver extends BroadcastReceiver {
    private static final String TOS_ACKED_ACCOUNTS = "ToS acknowledged accounts";
    private static final String EXTRA_ACCOUNT_NAME = "TosAckedReceiver.account";

    @Override
    public void onReceive(Context context, Intent intent) {
        Bundle args = intent.getExtras();
        if (args == null) return;
        String accountName = args.getString(EXTRA_ACCOUNT_NAME, null);
        if (accountName == null) return;

        SharedPreferences prefs = ContextUtils.getAppSharedPreferences();
        // Make sure to construct a new set so it can be modified safely. See crbug.com/568369.
        Set<String> accounts =
                new HashSet<String>(prefs.getStringSet(TOS_ACKED_ACCOUNTS, new HashSet<String>()));
        accounts.add(accountName);
        prefs.edit().remove(TOS_ACKED_ACCOUNTS).apply();
        prefs.edit().putStringSet(TOS_ACKED_ACCOUNTS, accounts).apply();
    }

    /**
     * Checks whether any of the current google accounts has seen the ToS in setup wizard.
     * @param context Context for the app.
     * @return Whether or not the the ToS has been seen.
     */
    public static boolean checkAnyUserHasSeenToS(Context context) {
        Set<String> toSAckedAccounts =
                ContextUtils.getAppSharedPreferences().getStringSet(
                        TOS_ACKED_ACCOUNTS, null);
        if (toSAckedAccounts == null || toSAckedAccounts.isEmpty()) return false;
        AccountManagerHelper accountHelper = AccountManagerHelper.get(context);
        List<String> accountNames = accountHelper.getGoogleAccountNames();
        if (accountNames.isEmpty()) return false;
        for (int k = 0; k < accountNames.size(); k++) {
            if (toSAckedAccounts.contains(accountNames.get(k))) return true;
        }
        return false;
    }
}

public class Compose {
 
    // Java doesn't have function type so we define an interface
    // of function objects instead
    public interface Fun<A,B> {
        B call(A x);
    }
 
    public static <A,B,C> Fun<A,C> compose(final Fun<B,C> f, final Fun<A,B> g) {
        return new Fun<A,C>() {
            public C call(A x) {
                return f.call(g.call(x));
            }
        };
    }
 
    public static void main(String[] args) {
        Fun<Double,Double> sin = new Fun<Double,Double>() {
            public Double call(Double x) {
                return Math.sin(x);
            }
        };
        Fun<Double,Double> asin = new Fun<Double,Double>() {
            public Double call(Double x) {
                return Math.asin(x);
            }
        };
 
        Fun<Double,Double> sin_asin = compose(sin, asin);
 
        System.out.println(sin_asin.call(0.5)); // prints "0.5"
    }
}

import android.content.Context;
import android.util.Log;

public class ArchivePublisher extends PublisherBase {

    private static final String TAG = "ArchivePublisher";
    private static final String ARCHIVE_URL_DOWNLOAD = "https://archive.org/download/";
    private static final String ARCHIVE_API_ENDPOINT = "https://archive.org/upload/";

    private Context mContext;
    private Job mPublishJob;
    private Controller mController;

    public ArchivePublisher(Context context, Controller controller) {
        this.mContext = context;
        this.mController = controller;
    }

    public void startUpload(Job job) {
        this.mPublishJob = job;
        Log.d(TAG, "Starting upload for job: " + job.getId());

        // Enqueue the job for execution
        mController.enqueueJob(job);
    }

    public String getEmbed(Job job) {
        String mediaType = job.getMediaType();
        int width = job.getWidth();
        int height = job.getHeight();
        String fileUrl = cleanFileURL(job.getFileUrl());

        StringBuilder embedCode = new StringBuilder();

        switch (mediaType) {
            case "photo":
                embedCode.append("<img src=\"")
                        .append(fileUrl)
                        .append("\" width=\"")
                        .append(width)
                        .append("\" height=\"")
                        .append(height)
                        .append("\" alt=\"Uploaded Photo\">");
                break;
            case "video":
                embedCode.append("<video width=\"")
                        .append(width)
                        .append("\" height=\"")
                        .append(height)
                        .append("\" controls>")
                        .append("<source src=\"")
                        .append(fileUrl)
                        .append("\" type=\"video/mp4\">")
                        .append("Your browser does not support the video tag.")
                        .append("</video>");
                break;
            case "audio":
                embedCode.append("<audio controls>")
                        .append("<source src=\"")
                        .append(fileUrl)
                        .append("\" type=\"audio/mpeg\">")
                        .append("Your browser does not support the audio element.")
                        .append("</audio>");
                break;
            default:
                Log.e(TAG, "Unsupported media type: " + mediaType);
                return null;
        }

        return embedCode.toString();
    }

private void executeFallbacks(
          TransformerImpl transformer)
            throws TransformerException
  {
    for (ElemTemplateElement child = m_firstChild; child != null;
             child = child.m_nextSibling)
    {
      if (child.getXSLToken() == Constants.ELEMNAME_FALLBACK)
      {
        try
        {
          transformer.pushElemTemplateElement(child);
          ((ElemFallback) child).executeFallback(transformer);
        }
        finally
        {
          transformer.popElemTemplateElement();
        }
      }
    }
  }

