class Helper {
public:
//
void dfs(int cur, int depth, vector<int>& ans, stack<int>& mp_)
{
if (!cur)
{
return;
}

dfs(cur->left, depth + 1, ans, mp_);
dfs(cur->right, depth + 1, ans, mp_);

if (mp_.size() == depth)
{
mp_.push(cur->val);
ans.push_back(mp_.top());
}

if (mp_.size() >= depth)
{
int count = mp_.size() - depth - 1;
//we just need a peak value, so use AND operation to caculate if we come to "00"
int peak = ans[count] & mp_[-mp_.size() - 1];
ans[count] = a[depth];
if (ans[count] != peak)
{
ans.push_back(ans[count]);
}
}
return;
}
};

