import java.util.function.Function;
import java.util.function.DoubleFunction;
import java.util.function.DoubleBinaryOperator;
import java.util.function.DoubleUnaryOperator;
 
public class RungeKutta4 {
 
    public static void main(String[] args) {
        double TIME_MAXIMUM = 10.0;
        double WHOLE_TOLERANCE = 1.0e-5;
        double T_START = 0.0;
        double Y_START = 1.0;
        double DT = 0.10;
 
        Function<Double,Double> my_diff_eqn = (t) -> t * Math.sqrt(t);
        Function<Double,Double> my_solution = (t) -> Math.pow(t*t + 4, 2) / 16;
        Function<Double,Double> find_error = (t) -> Math.abs(t - my_solution.apply(t));
        Function<Double,Boolean> is_whole = (t) -> Math.abs(t - Math.round(t)) < WHOLE_TOLERANCE;
 
        DoubleBinaryOperator dy = calc_rk4( (t,y) -> my_diff_eqn.apply(t) );
 
        double t = T_START;
        double y = Y_START;
        while (t <= TIME_MAXIMUM) {
            if (is_whole.apply(t)) {
                System.out.printf("y(%4.1f)\t= %12.6f \t error: %12.6e\n", t, y, find_error.apply(t));
            }
            t = t + DT;
            y = y + dy.applyAsDouble(t,y,DT);
        }
    }
 
    public static DoubleBinaryOperator calc_rk4(DoubleFunction<Double> f) {
        return (t,y,dt) -> {
            DoubleUnaryOperator dy1 = (dy1) -> {
            DoubleUnaryOperator dy2 = (dy2) -> {
            DoubleUnaryOperator dy3 = (dy3) -> {
            DoubleUnaryOperator dy4 = (dy4) -> ( dy1 + 2*dy2 + 2*dy3 + dy4 ) / 6;
            return dy4.applyAsDouble(dt * f.apply( t + dt , y + dy3   ));
            };
            return dy3.applyAsDouble(dt * f.apply( t + dt/2, y + dy2/2 ));
            };
            return dy2.applyAsDouble(dt * f.apply( t + dt/2, y + dy1/2 ));
            };
            return dy1.applyAsDouble(dt * f.apply( t      , y         ));
        };
    }
}

