import java.nio.ByteBuffer;

import org.exist.storage.DBBroker;
import org.exist.storage.journal.LogException;
import org.exist.storage.txn.Txn;

public class SetParentLoggable extends AbstractBTreeLoggable {

    private long pageNum;
    private long parentNum;

    public SetParentLoggable(Txn transaction, int fileId, long pageNum, long parentNum) {
        super(transaction, fileId);
        this.pageNum = pageNum;
        this.parentNum = parentNum;
    }

    /**
     * Empty constructor for de-serialization
     */
    public SetParentLoggable() {
    }

    @Override
    public void write(ByteBuffer buffer) {
        super.write(buffer);
        buffer.putLong(pageNum);
        buffer.putLong(parentNum);
    }

    @Override
    public void read(ByteBuffer buffer) {
        super.read(buffer);
        pageNum = buffer.getLong();
        parentNum = buffer.getLong();
    }

    @Override
    public int getLogSize() {
        return super.getLogSize() + 16; // 2 longs = 16 bytes
    }

    @Override
    public void redo(DBBroker broker) throws LogException {
        try {
            broker.setParent(fileId, pageNum, parentNum);
        } catch (Exception e) {
            throw new LogException("Failed to redo setParent for page " + pageNum + " to " + parentNum + ": " + e.getMessage(), e);
        }
    }

    @Override
    public String dump() {
        return "SetParentLoggable [fileId=" + fileId + ", pageNum=" + pageNum + ", parentNum=" + parentNum + "]";
    }

    public long getPageNum() {
        return pageNum;
    }

    public long getParentNum() {
        return parentNum;
    }

    @Override
    public String toString() {
        return "SetParentLoggable{" +
                "pageNum=" + pageNum +
                ", parentNum=" + parentNum +
                ", fileId=" + fileId +
                '}';
    }

     @Override
    public byte getType() {
        return LoggableTypes.SET_PARENT;
    }

    public static class LoggableTypes {
        public static final byte SET_PARENT = 0x03;
    }

}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;

public class Account {

    private String ownerName;
    private ArrayList<Transaction> transactions;

    private int id;
    private double balance;
    private double annualInterestRate;
    private Date dateCreated;

    public Account() {
        id = 0;
        balance = 0;
        annualInterestRate = 0;
        transactions = new ArrayList<>();
    }

    public Account(String ownerName, int id, double balance) {
        this.ownerName = ownerName;
        this.id = id;
        this.balance = balance;
        transactions = new ArrayList<>();
    }

    public Account(int newId, double newBalance) {
        this.id = newId;
        this.balance = newBalance;
        dateCreated = new Date();
        annualInterestRate = 0;
        transactions = new ArrayList<>();

    }

    public int getID() {

        return id;
    }

    public void setID(int newID) {

        this.id = newID;
    }

    public double getBalance() {

        return balance;
    }

    public void setBalance(double newBalance) {

        this.balance = newBalance;
    }

    public double getAnnualInterestRate() {
        return annualInterestRate;
    }

    public void setAnnualInterestRate(double newInterestRate) {

        this.annualInterestRate = newInterestRate;
    }

    public Date getDateCreated() {

        Date startDate = dateCreated;

        return startDate;
    }

    public double getMonthlyInterestRate() {

        return (annualInterestRate / 12);
    }

    public double getMonthlyInterest() {

        return balance * (this.getMonthlyInterestRate() / 100);
    }

    public void withdraw(double amount) {
        balance -= amount;
        Transaction transaction = new Transaction(Transaction.WITHDRAWAL, amount, this.balance, "Standard");
        transactions.add(transaction);

    }

    public void deposit(double amountDeposit) {
        balance += amountDeposit;
        Transaction transaction = new Transaction(Transaction.DEPOSIT, amountDeposit, this.balance, "Standard");
        transactions.add(transaction);

    }

    @Override
    public String toString() {
        return "Account Summary: \n" +
                "ownerName=" + ownerName +
                ", annualInterestRate=" + annualInterestRate + "%" +
                ", balance=$" + balance + "\n" +
                "Transactions:\n" + Arrays.toString(transactions.toArray());
    }

}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        double[][] points = new double[4][2];
        System.out.print("Enter four points: ");
        for (int i = 0; i < points.length; i++) {
            for (int j = 0; j < points[i].length; j++) {
                points[i][j] = input.nextDouble();
            }
        }
        double[] intersectingPoint = getIntersectingPoint(points);
        if (intersectingPoint == null) {
            System.out.println("The two lines are parallel.");
        } else {
            System.out.printf("The intersecting point is at (%.4f, %.4f)\n",
                    intersectingPoint[0], intersectingPoint[1]);
        }
    }

    public static double[] getIntersectingPoint(double[][] points) {
        double x1 = points[0][0], y1 = points[0][1];
        double x2 = points[1][0], y2 = points[1][1];
        double x3 = points[2][0], y3 = points[2][1];
        double x4 = points[3][0], y4 = points[3][1];
        double a = y1 - y2;
        double b = x2 - x1;
        double c = y3 - y4;
        double d = x4 - x3;
        double e = a * x1 + b * y1;
        double f = c * x3 + d * y3;
        double determinant = a * d - b * c;
        if (determinant == 0) {
            return null;
        } else {
            double x = (e * d - b * f) / determinant;
            double y = (a * f - e * c) / determinant;
            return new double[]{x, y};
        }
    }
}

import java.util.logging.Handler;
import java.util.logging.LogRecord;
import java.util.Objects;
import com.caucho.util.L10N;

public class SubHandler extends Handler {
    private final Handler _handler;

    public SubHandler(Handler handler) {
        this._handler = Objects.requireNonNull(handler, "Handler cannot be null");
    }

    @Override
    public void publish(LogRecord record) {
        if (isLoggable(record)) {
            _handler.publish(record);
        }
    }

    @Override
    public void flush() {
        _handler.flush();
    }

    @Override
    public void close() throws SecurityException {
        _handler.close();
    }

    @Override
    public boolean isLoggable(LogRecord record) {
        return _handler.isLoggable(record);
    }

    @Override
    public int hashCode() {
        return _handler.hashCode();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        SubHandler that = (SubHandler) o;
        return _handler.equals(that._handler);
    }

    @Override
    public String toString() {
        return "SubHandler{" +
                "_handler=" + _handler +
                '}';
    }
}

private void processInput(boolean endOfInput) throws IOException {
    // Decode the input ByteBuffer into a CharBuffer
    CoderResult coderResult = decoder.decode(inputByteBuffer, outputCharBuffer, endOfInput);
    if (coderResult.isError()) {
        coderResult.throwException();
    }
    if (coderResult.isOverflow()) {
        // Handle overflow by resizing the output CharBuffer
        resizeOutputCharBuffer();
    }
    // Check if the input ByteBuffer is fully consumed
    if (!inputByteBuffer.hasRemaining() && endOfInput) {
        // Handle end of input
        handleEndOfInput();
    }
}

private void resizeOutputCharBuffer() {
    // Create a new CharBuffer with double the capacity
    CharBuffer newCharBuffer = CharBuffer.allocate(outputCharBuffer.capacity() * 2);
    // Copy the existing content to the new CharBuffer
    outputCharBuffer.flip();
    newCharBuffer.put(outputCharBuffer);
    // Update the outputCharBuffer reference
    outputCharBuffer = newCharBuffer;
}

private void handleEndOfInput() {
    // Perform any necessary actions when the end of input is reached
    // For example, flush any remaining data or perform cleanup
    flushOutput();
}

private void flushOutput() {
    // Implement the logic to flush the output CharBuffer to the destination
    // For example, write the contents to a file or a network socket
    outputCharBuffer.flip();
    // Assuming there's a method to write the CharBuffer to a destination
    writeOutput(outputCharBuffer);
}

public static double[][] createKernel(double sigma, int radius, boolean odd, boolean normalize) {
    int size = radius * 2 + 1;
    double[][] kernel = new double[size][size];
    double sum = 0;

    for (int i = -radius; i <= radius; i++) {
        for (int j = -radius; j <= radius; j++) {
            double x = i;
            double y = j;
            double val = Math.exp(-(x * x + y * y) / (2 * sigma * sigma));
            kernel[i + radius][j + radius] = val;
            sum += val;
        }
    }

    if (normalize) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                kernel[i][j] /= sum;
            }
        }
    }

    if (odd && size % 2 == 0) {
        // make the kernel odd size
        double[][] oddKernel = new double[size + 1][size + 1];
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                oddKernel[i][j] = kernel[i][j];
            }
        }
        kernel = oddKernel;
    }

    return kernel;
}

