    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);

        // Configuring mock build execution context
        when(mockBuildExecution.getId()).thenReturn(123L);
        when(mockBuildExecution.getUser()).thenReturn("testUser");

        Map<String, String> repositoryConfig = new HashMap<>();
        repositoryConfig.put("maven-repo-url", "https://example.com/maven-repo");

        repositorySession = createBuildRepository(
            mockBuildExecution,
            repositoryManagerDriver,
            repositoryConfig
        );
    }

    @Test
    public void formatRepositoryURLForSimpleInfo_AllURLsMatch() throws Exception {
        // Retrieve repository connection information
        RepositoryConnectionInfo connectionInfo = repositorySession.getConnectionInfo();

        // Validate repository URLs across different access types
        assertThat(connectionInfo.getDependencyURL(), notNullValue());
        assertThat(connectionInfo.getToolchainURL(), notNullValue());

        URL dependencyUrl = new URL(connectionInfo.getDependencyURL());
        URL toolchainUrl = new URL(connectionInfo.getToolchainURL());

