import org.jspresso.framework.action.IActionHandler;
import org.jspresso.framework.application.action.AbstractActionContextAware;
import org.jspresso.framework.model.descriptor.IFileFilterable;
import org.jspresso.framework.model.descriptor.IModelDescriptor;

/**
 * Default handler implementation to deal with getting binary properties storing
 * them in files.
 *
 */
public class ConnectorValueGetterCallback extends AbstractActionContextAware
    implements IFileSaveCallback {

  /**
   * {@inheritDoc}
   */
  @Override
  public void cancel(IActionHandler actionHandler, Map<String, Object> context) {
    // NO-OP
  }

  /**
   * {@inheritDoc}
   */
  @Override
  public void fileChosen(String name, OutputStream out,
      IActionHandler actionHandler, Map<String, Object> context)
      throws IOException {
    OutputStream os = new BufferedOutputStream(out);
    // Do not use getSelectedModel() since it will return
    // the component holding the binary property
    Object connectorValue = getViewConnector(context).getConnectorValue();
    byte[] content;
    if (connectorValue instanceof String) {
      content = ((String) connectorValue).getBytes();
    } else {
      content = (byte[]) connectorValue;
    }
    if (connectorValue != null) {
      os.write(content);
      os.flush();
    }
  }

  /**
   * {@inheritDoc}
   */
  @Override
  public String getFileName(Map<String, Object> context) {
    IModelDescriptor modelDescriptor = getModelDescriptor(context);
    if (modelDescriptor instanceof IFileFilterable) {
      return ((IFileFilterable) modelDescriptor).getFileName();
    }
    return null;
  }
}

import java.io.File;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.TreeSet;

public class FileSearch {
    public static final int TYPE_FILE_OR_DIR = 0;
    public static final int TYPE_FILE = 1;
    public static final int TYPE_DIR = 2;

    private TreeSet<File> set;
    private String directoryPath;
    private String fileNamePattern;
    private int type;
    private boolean isRecursive;
    private int period;

    public FileSearch() {
        set = new TreeSet<>();
    }

    public File[] listFiles(String directoryPath, String fileNamePattern) {
        return listFiles(directoryPath, fileNamePattern, TYPE_FILE_OR_DIR, false, 0);
    }

    public File[] listFiles(String directoryPath, String fileNamePattern, int type, boolean isRecursive, int period) {
        this.directoryPath = directoryPath;
        this.fileNamePattern = fileNamePattern;
        this.type = type;
        this.isRecursive = isRecursive;
        this.period = period;

        File directory = new File(directoryPath);
        if (!directory.isDirectory()) {
            throw new IllegalArgumentException("Invalid directory path: " + directoryPath);
        }

        searchDirectory(directory);
        return set.toArray(new File[0]);
    }

    private void searchDirectory(File directory) {
        File[] files = directory.listFiles();
        if (files == null) return;

        for (File file : files) {
            if (file.isDirectory() && isRecursive) {
                searchDirectory(file);
            }
            if (matchesCriteria(file)) {
                set.add(file);
            }
        }
    }

    private boolean matchesCriteria(File file) {
        if (type == TYPE_FILE && !file.isFile()) return false;
        if (type == TYPE_DIR && !file.isDirectory()) return false;

        if (fileNamePattern != null && !fileNamePattern.isEmpty()) {
            String fileName = file.getName();
            if (!fileName.matches(fileNamePattern.replace("*", ".*"))) {
                return false;
            }
        }

        if (period > 0) {
            long lastModified = file.lastModified();
            long currentTime = System.currentTimeMillis();
            long timeDifference = currentTime - lastModified;
            if (timeDifference > period * 24 * 60 * 60 * 1000L) {
                return false;
            }
        }

        return true;
    }

    public void clear() {
        set.clear();
    }

    public static void main(String[] args) {
        FileSearch fileSearch = new FileSearch();

