def maxPermutationSum(arr, requests):
    idx_hash = {val: idx for idx, val in enumerate(arr)}
    requests.sort(key=lambda x: x[1])

    sum_arr = [[0]*len(arr) for _ in range(len(arr))]
    for i, j in requests:
        sum_arr[i][j] = sum(arr[i:j+1])

    dp_arr = [[0]*len(arr) for _ in range(len(arr))]
    for i in range(len(arr)-1, -1, -1):
        for j in range(len(arr)):

            if i == j:
                dp_arr[i][j] = sum_arr[i][j]
            else:
                best_idx = 0
                best_value = 0
                for k in range(i, j):
                    included_value = sum_arr[i][k+1] + dp_arr[k+1][j]
                    excluded_value = dp_arr[i][k]

                    if included_value > excluded_value:
                        best_idx = idx_hash[arr[best_idx]]
                        best_value = included_value
                    dp_arr[i][j] = max(dp_arr[i][j], included_value, excluded_value)

    return dp_arr[0][-1]

