public class ConstructorArrObjSNS {

    public interface FactoryObjectSNSDeportivo {
        ObjectSNSDeportivo crear();
    }

    public static ObjectSNSDeportivo[] producirArrayObjetoSNS(FactoryObjectSNSDeportivo factory, JSONArray jsonArray) {
        ObjectSNSDeportivo[] objetos = new ObjectSNSDeportivo[jsonArray.length()];
        for (int i = 0; i < jsonArray.length(); i++) {
            try {
                JSONObject jsonObject = jsonArray.getJSONObject(i);
                String jsonString = jsonObject.toString();
                ObjectSNSDeportivo objeto = factory.crear();
                objeto.deserializarJson(jsonString);
                objetos[i] = objeto;

            } catch (Exception e) {
                e.printStackTrace();
            }
        }
        return objetos;
    }

    public static ArrayList<KeyValueItem> producirArrayAdapterObjSNS(ArrayList<ObjectSNSDeportivo> objetos, String[] campos) {
        ArrayList<KeyValueItem> items = new ArrayList<>();
        for (ObjectSNSDeportivo objeto : objetos) {
            String valor = objeto.retornoToString(campos);
            items.add(new KeyValueItem(valor, objeto));
        }
        return items;
    }

    public static ArrayList<KeyValueItem> producirArrayAdapterObjSNS(ArrayList<ObjectSNSDeportivo> objetos, String[] campos, String separador) {
        ArrayList<KeyValueItem> items = new ArrayList<>();
        for (ObjectSNSDeportivo objeto : objetos) {
            String valor = objeto.retornoToStringSeparadores(campos, separador);
            items.add(new KeyValueItem(valor, objeto));
        }
        return items;
    }
}

