    private static boolean isGoodArray(final int[] a, final int l, final int r) {
        boolean has1 = false;
        for (int i = l - 1; i < r; i++) {
            if (a[i] < i + 1) {
                return false;
            } else if (a[i] == 1) {
                has1 = true;
            }
        }
        return has1;
    }

