        int[] a = new int[inputArray.length];
        for (int i = 0; i < a.length; i++) {
            a[i] = Integer.parseInt(inputArray[i]);
        }
        int count = 0;
        int length = a.length;
        for (int l = 1; l <= length; l++) {
            for (int r = 1; r <= length; r++) {
                if (l <= r && isGoodArray(a, l, r)) {
                    count++;
                }
            }
        }
        System.out.println(count);
        in.close();
    }
