      {
         String feature = scan.nextToken();
         if (feature.startsWith(FEATURE_STRING_PREFIX)) {
            result.add(feature.substring(FEATURE_STRING_PREFIX.length()));
         } else {

            result.add("UNSUPPORTED");
         }
         scan.skipWhitespace();
      }
      return result;
