import java.util.Arrays;
import java.util.stream.IntStream;
 
public class HofstadterConway10000 {
 
    private int[] sequence;
 
    public HofstadterConway10000() {
        sequence = new int[3];
        sequence[0] = 0;
        sequence[1] = 1;
        sequence[2] = 1;
    }
 
    public int get(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("n must be >= 1");
        }
        int[] a = sequence;
        int length = a.length;
        for (int i = length; i <= n; i++) {
            a[i] = a[a[i - 1]] + a[i - a[i - 1]];
        }
        return a[n];
    }
 
    public static void main(String[] args) {
        HofstadterConway10000 hc = new HofstadterConway10000();
 
        int mallows = 0;
        for (int i = 1; i < 20; i++) {
            int j = i + 1;
            int max_n = -1;
            double max_v = -1;
            for (int n = (int) Math.pow(2, i); n < Math.pow(2, j); n++) {
                double v = hc.get(n) / (double) n;
                if (v > max_v) {
                    max_n = n;
                    max_v = v;
                }
                // Mallows number
                if (v >= 0.55) {
                    mallows = n;
                }
            }
            System.out.printf("maximum between 2^%2d and 2^%2d occurs at%7d: %.8f%n", i, j, max_n, max_v);
        }
 
        System.out.printf("the mallows number is %d%n", mallows);
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;
 
public class VisualizeTree {
    public static void main(String[] args) {
        new Tree("A",
                new Tree("B0",
                        "C1",
                        new Tree("C2",
                                "D",
                                "E1",
                                "E2",
                                "E3"),
                        "C3",
                        new Tree("F1",
                                "F2",
                                "F3",
                                new Tree("G"),
                                "F4",
                                "H1",
                                "H2")),
                new Tree("B1",
                        "K1",
                        new Tree("K2",
                                "L1",
                                new Tree("M"),
                                "L2",
                                "L3"),
                        "K3")
        ).print(true, "");
    }
 
    private static Tree t(String value, Tree... children) {
        return new Tree(value, children);
    }
 
    private void print(Tree tree) {
        tree.print(true, "");
    }
 
    private void print(Tree tree, boolean last, String prefix) {
        String current = last? prefix + "└─" + tree.value : prefix + "├─" + tree.value;
        String next = last? prefix + "  " : prefix + "| ";
        System.out.println(current.substring(2));
        for (int c = 0; c < tree.children.length; c++) {
            tree.children[c].print(c == tree.children.length - 1, next);
        }
    }
 
    private static class Tree {
        private final String value;
        private final Tree[] children;
 
        private Tree(String value, Tree... children) {
            this.value = value;
            this.children = children;
        }
 
        private static Tree valueOf(String value) {
            return new Tree(value);
        }
 
        private void print(boolean last, String prefix) {
            String current = last? prefix + "└─" + value : prefix + "├─" + value;
            String next = last? prefix + "  " : prefix + "| ";
            System.out.println(current.substring(2));
            for (int c = 0; c < children.length; c++) {
                children[c].print(c == children.length - 1, next);
            }
        }
    }
}

