import junit.framework.TestCase;

import java.lang.management.ManagementFactory;
import java.lang.management.MemoryMXBean;
import java.lang.management.MemoryUsage;

public class MemoryMXBeanTest extends TestCase {

    private MemoryMXBean mb;

    @Override
    protected void setUp() throws Exception {
        super.setUp();
        mb = ManagementFactory.getMemoryMXBean();
        assertNotNull(mb);
    }

    @Override
    protected void tearDown() throws Exception {
        super.tearDown();
        mb = null;
    }

    public void testHeapMemoryUsage() {
        MemoryUsage heapUsage = mb.getHeapMemoryUsage();
        assertNotNull(heapUsage);
        assertTrue(heapUsage.getCommitted() >= 0);
        assertTrue(heapUsage.getUsed() >= 0);
        assertTrue(heapUsage.getCommitted() >= heapUsage.getUsed());
        if (heapUsage.getMax() > 0) {
            assertTrue(heapUsage.getCommitted() <= heapUsage.getMax());
            assertTrue(heapUsage.getUsed() <= heapUsage.getMax());
        }
    }

    public void testNonHeapMemoryUsage() {
        MemoryUsage nonHeapUsage = mb.getNonHeapMemoryUsage();
        assertNotNull(nonHeapUsage);
        assertTrue(nonHeapUsage.getCommitted() >= 0);
        assertTrue(nonHeapUsage.getUsed() >= 0);
        assertTrue(nonHeapUsage.getCommitted() >= nonHeapUsage.getUsed());
        if (nonHeapUsage.getMax() > 0) {
            assertTrue(nonHeapUsage.getCommitted() <= nonHeapUsage.getMax());
            assertTrue(nonHeapUsage.getUsed() <= nonHeapUsage.getMax());
        }
    }

    public void testObjectPendingFinalizationCount() {
        long count = mb.getObjectPendingFinalizationCount();
        assertTrue(count >= 0);
    }

    public void testVerbose() {
        boolean initialVerbose = mb.isVerbose();
        mb.setVerbose(!initialVerbose);
        assertEquals(!initialVerbose, mb.isVerbose());
        mb.setVerbose(initialVerbose); // Restore initial value
        assertEquals(initialVerbose, mb.isVerbose());
    }

   public void testVerbosePersistence() {
        boolean initialVerbose = mb.isVerbose();
        try {
            mb.setVerbose(!initialVerbose);
            // Create a new MemoryMXBean instance to check persistence
            MemoryMXBean newMb = ManagementFactory.getMemoryMXBean();
            assertEquals(!initialVerbose, newMb.isVerbose());
        } finally {
            // Restore the initial verbose state to avoid side effects
            mb.setVerbose(initialVerbose);
        }
    }
}

class Service {
    public int sumBase(int n, int k) {
        int res = 0;
        while(n != 0) {
            int t = n % k;
            res += t;
            n /= k;
        }
        return res;
    }
}

