public static void translateM(float[] tm, int tmOffset,
            float[] m, int mOffset,
            float x, float y, float z) {
        for (int i=0 ; i<12 ; i++) {
            tm[tmOffset + i] = m[mOffset + i];
        }
        for (int i=0 ; i<4 ; i++) {
            int tmi = tmOffset + i;
            int mi = mOffset + i;
            tm[12 + tmi] = m[mi] * x + m[4 + mi] * y + m[8 + mi] * z +
                m[12 + mi];
        }
    }

@Path("/incomes")
public class Incomes {
    private IncomeDao getDao() {
        return JndiUtil.lookup("java:app/IncomeDaoImpl");
    }

    @POST
    @Consumes(MediaType.APPLICATION_FORM_URLENCODED)
    public Response addNew(@FormParam("createDate") String dateStr,
                          @FormParam("userId") String userId,
                          @FormParam("amount") double amount,
                          @FormParam("descr") String descr) throws ParseException {
        Date createDate = new SimpleDateFormat("yyyy-MM-dd").parse(dateStr);
        getDao().create(new Income(createDate, userId, amount, descr));
        return Response.status(Response.Status.CREATED).build();
    }

    @GET
    @Path("/latest")
    @Produces({MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML})
    public List<Income> getLatest(@QueryParam("page") @DefaultValue("0") int page,
                                 @QueryParam("size") @DefaultValue("20") int size) {
        return getDao().findRecent(page, size);
    }

    @GET
    @Path("/list")
    @Produces({MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML})
    public List<Income> getList(@QueryParam("dateFrom") String fromStr,
                               @QueryParam("dateTo") String toStr,
                               @QueryParam("userId") String userId) throws ParseException {
        Date from = parseDate(fromStr);
        Date to = parseDate(toStr);
        return getDao().findByCriteria(from, to, userId);
    }

    @GET
    @Path("/summary")
    @Produces({MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML})
    public List<SummaryBean> getSummarySimple() {
        return getDao().getSummary();
    }

    @GET
    @Path("/summary/monthly")
    @Produces({MediaType.APPLICATION_JSON, MediaType.APPLICATION_XML})
    public List<SummaryBean> getSummaryMonth() {
        return getDao().getMonthlySummary();
    }

    private Date parseDate(String dateStr) throws ParseException {
        if (dateStr == null || dateStr.isEmpty()) return null;
        return new SimpleDateFormat("yyyy-MM-dd").parse(dateStr);
    }
}

