public class Cache {
    public static void main(String[] args) {
        String nextStr = "";
        String lastStr = "";
        int strCount = 0;
        try (BufferedReader bufferedReader =
                     new BufferedReader(new FileReader("src\\ch_12\\exercise12_21\\SortedStrings.txt"))) {

            while ((nextStr = bufferedReader.readLine()) != null) {
                if (strCount++ == 0) {
                    lastStr = nextStr;
                    continue;
                }
                if (!isIncreasingOrder(lastStr, nextStr)) {
                    System.out.println("The strings are not in increasing order...");
                    System.out.println("The first occurrence of two Strings out of order are " + lastStr +
                            " " +
                            "and " + nextStr);
                    break;
                }

                lastStr = nextStr;
            }

        } catch (Exception e) {
            e.printStackTrace();
        }

    }

    static boolean isIncreasingOrder(String s1, String s2) {
        return s1.compareTo(s2) < 0;
    }

}

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

interface BytesReference {
    byte get(int index);
    int length();
    int indexOf(byte b, int offset, int len);
    BytesReference slice(int from, int length);
    byte[] toBytes();
    String toUtf8();
}

public class BytesArray implements BytesReference {
    private final byte[] bytes;
    private final int offset;
    private final int length;

    public BytesArray(byte[] bytes) {
        this(bytes, 0, bytes.length);
    }

    public BytesArray(byte[] bytes, int offset, int length) {
        if (offset < 0 || length < 0 || offset + length > bytes.length) {
            throw new IllegalArgumentException("Invalid offset or length");
        }
        this.bytes = bytes;
        this.offset = offset;
        this.length = length;
    }

    public void write(byte[] b) {
        if (b == null || b.length == 0) {
            return;
        }
        byte[] newBytes = Arrays.copyOfRange(bytes, offset, offset + length);
        newBytes = Arrays.copyOf(newBytes, newBytes.length + b.length);
        System.arraycopy(b, 0, newBytes, length, b.length);
        this.bytes = newBytes;
        this.offset = 0;
        this.length = newBytes.length;
    }

    @Override
    public byte get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("Index " + index + " out of bounds for length " + length);
        }
        return bytes[offset + index];
    }

    @Override
    public int length() {
        return length;
    }

    @Override
    public int indexOf(byte b, int offset, int len) {
        if (offset < 0 || len < 0 || offset + len > length) {
            throw new IllegalArgumentException("Invalid offset or length");
        }
        for (int i = offset; i < offset + len; i++) {
            if (bytes[this.offset + i] == b) {
                return i;
            }
        }
        return -1;
    }

    @Override
    public BytesReference slice(int from, int length) {
        if (from < 0 || length < 0 || from + length > this.length) {
            throw new IllegalArgumentException("Invalid from or length");
        }
        return new BytesArray(bytes, this.offset + from, length);
    }

    @Override
    public byte[] toBytes() {
        return Arrays.copyOfRange(bytes, offset, offset + length);
    }

    @Override
    public String toUtf8() {
        return new String(bytes, offset, length, StandardCharsets.UTF_8);
    }

