import java.util.Scanner;
 
public class Perfect {
 
    public static boolean computePerfect(long n) {
        long sum = 0;
        for (long i = 1; i < n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        return sum == n;
    }
 
    // following function satisfies the task, returning true for all
    // perfect numbers representable in the argument type
    public static boolean isPerfect(long n) {
        switch ((int) n) {
            case 6:
            case 28:
            case 496:
            case 8128:
            case 33550336:
            case 8589869056L:
            case 137438691328L:
            case 2305843008139952128L:
                return true;
        }
        return false;
    }
 
    // validation
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (long n = 1; ; n++) {
            if (isPerfect(n)!= computePerfect(n)) {
                throw new RuntimeException("bug");
            }
            if (n % 1e3 == 0) {
                System.out.println("tested " + n);
            }
        }
    }
}

