import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Map.Entry;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class PrimeTransitions {
 
    public static void main(String[] args) {
        List<Integer> primes = IntStream.iterate(2, i -> i + 2)
               .filter(PrimeTransitions::isPrime)
               .limit(1000000)
               .boxed()
               .collect(Collectors.toList());
        Map<Pair, Integer> conspiracy = new HashMap<>();
        for (int i = 0; i < primes.size() - 1; i++) {
            int a = primes.get(i) % 10;
            int b = primes.get(i + 1) % 10;
            Pair pair = new Pair(a, b);
            conspiracy.put(pair, conspiracy.getOrDefault(pair, 0) + 1);
        }
        System.out.println("1000000 first primes. Transitions prime % 10 → next-prime % 10.");
        List<Entry<Pair, Integer>> list = new ArrayList<>(conspiracy.entrySet());
        Collections.sort(list, new Comparator<Entry<Pair, Integer>>() {
            @Override
            public int compare(Entry<Pair, Integer> o1, Entry<Pair, Integer> o2) {
                int result = Integer.compare(o1.getKey().a, o2.getKey().a);
                if (result == 0) {
                    result = Integer.compare(o1.getKey().b, o2.getKey().b);
                }
                return result;
            }
        });
        for (Entry<Pair, Integer> entry : list) {
            System.out.printf("%d -> %d count: %15d frequency: %5.2f %%\n", entry.getKey().a, entry.getKey().b, entry.getValue(),
                    (double) entry.getValue() / 1000000 * 100);
        }
    }
 
    private static boolean isPrime(int i) {
        int stop = (int) Math.sqrt(i);
        for (int d = 2; d <= stop; d++) {
            if (i % d == 0) {
                return false;
            }
        }
        return true;
    }
 
    private static class Pair {
        private final int a;
        private final int b;
 
        public Pair(int a, int b) {
            this.a = a;
            this.b = b;
        }
 
        @Override
        public int hashCode() {
            return a * 10 + b;
        }
 
        @Override
        public boolean equals(Object obj) {
            if (obj instanceof Pair) {
                Pair other = (Pair) obj;
                return a == other.a && b == other.b;
            }
            return false;
        }
    }
}

