import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
 
public class Disjoint {
    public static <T extends Comparable<? super T>> void sortDisjoint(
            List<T> array, int[] idxs) {
        Arrays.sort(idxs);
        List<T> disjoint = new ArrayList<T>();
        for (int idx : idxs) {
            disjoint.add(array.get(idx));
        }
        Collections.sort(disjoint);
        int i = 0;
        for (int idx : idxs) {
            array.set(idx, disjoint.get(i++));
        }
    }
 
    public static void main(String[] args) {
        List<Integer> list = Arrays.asList(7, 6, 5, 4, 3, 2, 1, 0);
        int[] indices = {6, 1, 7};
        System.out.println(list);
        sortDisjoint(list, indices);
        System.out.println(list);
    }
}

public int longestOnes(int[] nums) {
        int n=nums.length;
        int max=0;
        int temp=0;
        int l=0;
        int r=n-1;

        if(n==0)
            return 0;
        while(l<r)
        {
            if(nums[l]==1&&nums[r]==1)
            {
                l++;
                r--;
            }
            else
            {
                temp++;
            }

            if(nums[l]==1&&nums[r]==0)
            {
                temp=2;
                l++;
                r--;
            }
            else if(nums[l]==1&&nums[r]==1)
            {
                max=temp;
                temp=0;
                notwin(nums,r,l,max,temp,n);
            }
        }
        return max;
    }

    private void notwin(int[] an,int left,int right,int temp,int count,int a)
    {
        count++;
        temp++;
        while(left<right && count>2)
        {
            if(an[count]==0)
                break;
            count++;
            temp++;
        }
        if(count>2)
        {
            notwin(an,left+1,right,0,0,count);
            return;
        }

        int l=left+temp-count;
        int r=right-temp;
        int m=l+r;
        if(l<0||r>a)
            return;
        for(;l<m&&an[l]==0;l++)
            continue;
        for(;r>m&&an[r]==0;r--)
            continue;

        l=right-temp;
        if(l<0||r>a)
            return;
        temp=0;

        for(;l<=r;l++,r--)
        {
            System.out.println(an[0]+" "+an[l]+" "+an[r]);
        }
    }
}

Approach 2: Find subarray within array
Complexity Analysis

Time Complexity: O(N), where N is the length of nums. We iterate through the array exactly once.
Space Complexity: O(1). The amount of memory we use only depends on the value of the input, and does not grow with the size of the input.

class Matrix {
    public int longestOnes(int[] nums) {
        int l=0,r=0,max=0;
        int maxTemp=0;
        int current=0;

        while(l<r)
        {
            if(nums[l]==1&&nums[r]==1)
            {
                l++;
                r--;
            }
            else
            {
                if(maxTemp<current)
                    maxTemp=current;
                current++;
            }
        }
        if(maxTemp>current)
            return current;
        while(r>=0&&current>0)
        {
            if(nums[r]==1)
                ++current;
            else
                if(maxTemp<current)
                    maxTemp=current;
                current--;
            --r;
        }
        return maxTemp;
    }
}

