public class KlasorIslemleri {

    /** Verilen yoldaki alt klasorleri (sadece klasorleri) dondurur. */
    public static File[] altKlasorler(String kokYol) {
        return new File(kokYol).listFiles(File::isDirectory);
    }

    /** Verilen klasordeki dosyalari (sadece dosyalari) dondurur. */
    public static File[] icindekiDosyalar(final File klasor) {
        return klasor.listFiles(File::isFile);
    }

    /** Kok yoldan baslayarak tum agaci gezip her dosyayi biriktirir (BFS benzeri). */
    public static Queue<File> agaciTaraVeTopla(String kokYol) {
        Queue<File> sonuclar = new LinkedList<>();
        Queue<File> bekleyenKlasorler = new LinkedList<>();
        bekleyenKlasorler.add(new File(kokYol));

        while (!bekleyenKlasorler.isEmpty()) {
            File guncelKlasor = bekleyenKlasorler.poll();
            File[] icerik = guncelKlasor.listFiles();
            if (icerik == null) {
                continue; // erisim yok veya klasor degil
            }
            for (File eleman : icerik) {
                if (eleman.isDirectory()) {
                    bekleyenKlasorler.add(eleman);
                } else {
                    sonuclar.add(eleman.getAbsoluteFile());
                }
            }
        }
        return sonuclar;
    }

    /** Tek bir dosyayi diskten kaldirir. */
    public static boolean dosyaKaldir(String tamYol) {
        return new File(tamYol).delete();
    }

    /** Yeni, bos bir klasor uretir. */
    public static boolean klasorUret(String hedefYol) {
        return new File(hedefYol).mkdir();
    }

    /** Klasoru icindeki her seyle birlikte (derinlemesine) temizler. */
    public static boolean agaciTemizle(File hedef) {
        if (hedef.isDirectory()) {
            File[] altElemanlar = hedef.listFiles();
            if (altElemanlar != null) {
                for (File altEleman : altElemanlar) {
                    agaciTemizle(altEleman);
                }
            }
        }
        return hedef.delete();
    }

