        rapor.append("Dosya adi: ").append(hedef.getName()).append('\n');

public class InsertionSort {
    public static void main(String[] args) {
        int[] ary = {7,6,5,9,8,4,3,1,2,0};
        System.out.println(Arrays.toString(insertionsort(ary)));
    }

    public static int[] insertionsort(int[] ary) {
        for (int i = 1; i < ary.length; i++) {
            int value = ary[i];
            int j = i - 1;
            while (j >= 0 && ary[j] > value) {
                ary[j+1] = ary[j];
                j--;
            }
            ary[j+1] = value;
        }
        return ary;
    }
}

class Timer {

    public boolean checkValidGrid(int[][] grid) {
        int[][] index = new int[grid.length * grid.length][];
        for (int i = 0; i < grid.length; i++) {
            for (int j = 0; j < grid.length; j++) {
                index[grid[i][j]] = new int[] { i, j };
            }
        }
        for (int i = 1; i < index.length; i++) {
            if (Math.abs(index[i][0] - index[i - 1][0]) * Math.abs(index[i][1] - index[i - 1][1]) != 2) {
                return false;
            }
        }
        return grid[0][0] == 0;
    }
}

public String convertOperatorToken(int operator) {
    switch(operator) {
        case Token.PLUS: return "+";
        case Token.MINUS: return "-";
        case Token.MULTIPLY: return "*";
        case Token.DIVIDE: return "/";
        default: throw new Error("Token value is not an operator");
    }
}

