import java.util.List;

import org.eclipse.collections.api.block.predicate.Predicate;
import org.eclipse.collections.api.block.procedure.Procedure;
import org.eclipse.collections.api.tuple.Pair;
import org.eclipse.collections.impl.factory.Lists;
import org.eclipse.collections.impl.tuple.Tuples;

public class CaseProcedure<T> implements Procedure<T> {
    private static final long serialVersionUID = 1L;
    private final List<Pair<Predicate<? super T>, Procedure<? super T>>> predicateProcedures =
            Lists.mutable.empty();
    private Procedure<? super T> defaultProcedure = null;

    public CaseProcedure<T> addCase(
            Predicate<? super T> predicate, Procedure<? super T> procedure) {
        this.predicateProcedures.add(Tuples.pair(predicate, procedure));
        return this;
    }

    public CaseProcedure<T> setDefault(Procedure<? super T> procedure) {
        this.defaultProcedure = procedure;
        return this;
    }

    @Override
    public void value(T argument) {
        int localSize = this.predicateProcedures.size();
        for (int i = 0; i < localSize; i++) {
            Pair<Predicate<? super T>, Procedure<? super T>> pair =
                    this.predicateProcedures.get(i);
            if (pair.getOne().accept(argument)) {
                pair.getTwo().value(argument);
                return;
            }
        }
        if (this.defaultProcedure != null) {
            this.defaultProcedure.value(argument);
        }
    }
}

