class Writer {
    public TreeNode mergeTrees(int[][] trees) {
        int n = trees.length;
        if (n == 1) {
            return trees[0][0];
        }
        List<TreeNode> treeNodes = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            treeNodes.add(createTree(trees[i]));
        }
        for (int i = 0; i < n - 1; i++) {
            TreeNode node = treeNodes.get(i);
            for (int j = i + 1; j < n; j++) {
                TreeNode root = treeNodes.get(j);
                if (node.val == root.val) {
                    TreeNode newTree = merge(node, root);
                    treeNodes.set(i, newTree);
                    treeNodes.remove(j);
                    i--;
                    break;
                }
            }
        }
        return treeNodes.size() == 1 ? treeNodes.get(0) : null;
    }

    private TreeNode createTree(int[] tree) {
        if (tree.length == 1) {
            return new TreeNode(tree[0]);
        }
        return new TreeNode(tree[0], new TreeNode(tree[1]), new TreeNode(tree[2]));
    }

    private TreeNode merge(TreeNode root1, TreeNode root2) {
        TreeNode root = new TreeNode(root1.val);
        if (root1.left != null) {
            root.left = root1.left;
        } else {
            root.left = root2;
        }
        if (root1.right != null) {
            root.right = root1.right;
        } else {
            root.right = root2;
        }
        return root;
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) {
        this.val = val;
        this.left = left;
        this.right = right;
    }
}

