import org.junit.Test;
import static org.junit.Assert.*;

public class HashThreeTest {

    static class ObjectTest {
        int hashCode;
        String name;

        public ObjectTest(int hashCode, String name) {
            this.hashCode = hashCode;
            this.name = name;
        }

        @Override
        public int hashCode() {
            return hashCode;
        }

        @Override
        public String toString() {
            return "ObjectTest{" +
                    "hashCode=" + hashCode +
                    ", name='" + name + '\'' +
                    '}';
        }
    }

    @Test
    public void test1() {
        HashThree<ObjectTest> three = new HashThree<>();
        ObjectTest test1 = new ObjectTest(1, "test1");
        ObjectTest test2 = new ObjectTest(2, "test2");
        ObjectTest test3 = new ObjectTest(3, "test3");
        ObjectTest test4 = new ObjectTest(1, "test4");
        ObjectTest test5 = new ObjectTest(5, "test5");
        ObjectTest test6 = new ObjectTest(6, "test6");

        three.add(test1);
        assertEquals(1, three.getSize());
        assertTrue(three.exist(test1));

        three.add(test2);
        assertEquals(2, three.getSize());

        three.add(test3);
        assertEquals(3, three.getSize());

        three.add(test4); // Duplicate hashCode
        assertEquals(3, three.getSize());

        assertTrue(three.remove(test1));
        assertEquals(2, three.getSize());
        assertFalse(three.exist(test1));

        three.add(test5);
        assertEquals(3, three.getSize());

        three.replace(test2,test6);
        assertTrue(three.exist(test6));
        assertFalse(three.exist(test2));

        three.remove(test3);
        three.remove(test5);
        three.remove(test6);
        assertEquals(0, three.getSize());
    }
}

public class Order {
    public static void main(String[] args) {
        int N = 15;
        int[] t = new int[N + 2];
        t[1] = 1;
 
        for (int i = 1; i <= N; i++) {
 
            for (int j = i; j > 1; j--)
                t[j] = t[j] + t[j - 1];
 
            t[i + 1] = t[i];
 
            for (int j = i + 1; j > 1; j--)
                t[j] = t[j] + t[j - 1];
 
            System.out.printf("%d ", t[i + 1] - t[i]);
        }
    }
}

public static void heapSort(int[] a){
    int count = a.length;
 
    //first place a in max-heap order
    heapify(a, count);
 
    int end = count - 1;
    while(end > 0){
        //swap the root(maximum value) of the heap with the
        //last element of the heap
        int tmp = a[end];
        a[end] = a[0];
        a[0] = tmp;
        //put the heap back in max-heap order
        siftDown(a, 0, end - 1);
        //decrement the size of the heap so that the previous
        //max value will stay in its proper place
        end--;
    }
}
 
public static void heapify(int[] a, int count){
    //start is assigned the index in a of the last parent node
    int start = (count - 2) / 2; //binary heap
 
    while(start >= 0){
        //sift down the node at index start to the proper place
        //such that all nodes below the start index are in heap
        //order
        siftDown(a, start, count - 1);
        start--;
    }
    //after sifting down the root all nodes/elements are in heap order
}
 
public static void siftDown(int[] a, int start, int end){
    //end represents the limit of how far down the heap to sift
    int root = start;
 
    while((root * 2 + 1) <= end){      //While the root has at least one child
        int child = root * 2 + 1;           //root*2+1 points to the left child
        //if the child has a sibling and the child's value is less than its sibling's...
        if(child + 1 <= end && a[child] < a[child + 1])
            child = child + 1;           //... then point to the right child instead
        if(a[root] < a[child]){     //out of max-heap order
            int tmp = a[root];
            a[root] = a[child];
            a[child] = tmp;
            root = child;                //repeat to continue sifting down the child now
        }else
            return;
    }
}

import edu.the.way.of.testing.Flight;
import edu.the.way.of.testing.SeatClass;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

/**
 * User: pcierpiatka
 */
public class FlightTestBuilder {

    private Flight flight;
    private DateTimeFormatter dateFormat = DateTimeFormatter.ofPattern("yyyy-MM-dd");

    private FlightTestBuilder(String flightCode) {
        flight = new Flight(flightCode);
    }

    public static FlightTestBuilder flight(String flightCode) {
        return new FlightTestBuilder(flightCode);
    }

    public Flight build() {
        return flight;
    }

    public FlightTestBuilder withSeats(int seatCount) {
        return withSeatsInPrice(seatCount, 0);
    }

    public FlightTestBuilder withSeatsInPrice(int seatsCount, double price) {
        return withSeats(SeatClass.ECONOMIC, seatsCount, price);
    }

    public FlightTestBuilder withBookedSeatsInPrice(int seatsCount, double price) {
        int paddedSeatsCount = flight.getSeatsCount() + seatsCount;
        String seatNumber;

        for (int seatIndex = flight.getSeatsCount(); seatIndex < paddedSeatsCount; ++seatIndex) {
            seatNumber = "seat" + seatIndex;
            flight.addSeat(SeatClass.ECONOMIC, seatNumber, price);
            flight.bookSeat(seatNumber);
        }
        return this;
    }

    public FlightTestBuilder withSeatInPrice(String seatNumber, double price) {
        flight.addSeat(SeatClass.ECONOMIC, seatNumber, price);
        return this;
    }

    public FlightTestBuilder withSeat(String seatNumber) {
        flight.addSeat(SeatClass.ECONOMIC, seatNumber, 0);
        return this;
    }

    public FlightTestBuilder withBookedSeat(String seatNumber) {
        flight.addSeat(SeatClass.ECONOMIC, seatNumber, 0);
        flight.bookSeat(seatNumber);
        return this;
    }

    public FlightTestBuilder withSeats(SeatClass seatClass, int seatsCount, double price) {
        int paddedSeatsCount = flight.getSeatsCount() + seatsCount;

        for (int seatIndex = flight.getSeatsCount(); seatIndex < paddedSeatsCount; ++seatIndex) {
            flight.addSeat(seatClass, "seat" + seatIndex, price);
        }
        return this;
    }

    public FlightTestBuilder from(String from) {
        flight.setOrigin(from);
        return this;
    }

    public FlightTestBuilder to(String destination) {
        flight.setDestination(destination);
        return this;
    }

    public FlightTestBuilder on(String dateOfFlight) {
        flight.setFlightDate(LocalDate.parse(dateOfFlight, dateFormat));
        return this;
    }
}

