import java.awt.Color;
import java.awt.Graphics;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JFrame;
 
public class DragonCurve extends JFrame {
    private final List<Integer> turns;
    private final double startingAngle;
    private final double side;
 
    public DragonCurve(int iter) {
        super("Dragon Curve");
        setBounds(100, 100, 800, 600);
        setDefaultCloseOperation(EXIT_ON_CLOSE);
        turns = getSequence(iter);
        startingAngle = -iter * Math.PI / 4;
        side = 400.0 / Math.pow(2.0, iter / 2.0);
    }
 
    public List<Integer> getSequence(int iterations) {
        List<Integer> turnSequence = new ArrayList<>();
        for (int i = 0; i < iterations; i++) {
            List<Integer> copy = new ArrayList<>(turnSequence);
            for (int j = copy.size() - 1; j >= 0; j--) {
                copy.add(-copy.get(j));
            }
            turnSequence.add(1);
            turnSequence.addAll(copy);
        }
        return turnSequence;
    }
 
    @Override
    public void paint(Graphics g) {
        g.setColor(Color.BLUE);
        double angle = startingAngle;
        int x1 = 230;
        int y1 = 350;
        int x2 = x1 + (int) (Math.cos(angle) * side);
        int y2 = y1 + (int) (Math.sin(angle) * side);
        g.drawLine(x1, y1, x2, y2);
        x1 = x2;
        y1 = y2;
        for (int turn : turns) {
            angle += turn * Math.PI / 2.0;
            x2 = x1 + (int) (Math.cos(angle) * side);
            y2 = y1 + (int) (Math.sin(angle) * side);
            g.drawLine(x1, y1, x2, y2);
            x1 = x2;
            y1 = y2;
        }
    }
}
 
public class Logger {
    public static void main(String[] args) {
        new DragonCurve(14).setVisible(true);
    }
}

import java.util.ArrayList;
import java.util.List;
 
public class Brazilian {
 
    public static boolean sameDigits(long x, long base) {
        long f = x % base;
        long n = x;
        while (n > 0) {
            if (n % base!= f) {
                return false;
            }
            n /= base;
        }
 
        return true;
    }
 
    public static boolean isBrazilian(long x) {
        if (x < 7) {
            return false;
        }
        if (x % 2 == 0) {
            return true;
        }
 
        for (long base = 2; base < (x - 1); base++) {
            if (sameDigits(x, base)) {
                return true;
            }
        }
        return false;
    }
 
    public static void main(String[] args) {
        int counter = 0;
        int limit = 20;
        int bigLimit = 100_000;
        long bigResult = 0;
        List<Long> br = new ArrayList<>();
        List<Long> o = new ArrayList<>();
        List<Long> p = new ArrayList<>();
 
        for (long x = 7; ; x++) {
            if (isBrazilian(x)) {
                counter++;
                if (br.size() < limit) {
                    br.add(x);
                }
                if (o.size() < limit && x % 2 == 1) {
                    o.add(x);
                }
                if (p.size() < limit && Primes.isPrime(x)) {
                    p.add(x);
                }
                if (counter == bigLimit) {
                    bigResult = x;
                    break;
                }
            }
        }
        System.out.println("First " + limit + " Brazilian numbers:");
        System.out.println(br);
        System.out.println("\nFirst " + limit + " odd Brazilian numbers:");
        System.out.println(o);
        System.out.println("\nFirst " + limit + " prime Brazilian numbers:");
        System.out.println(p);
 
        System.out.println("\nThe " + bigLimit + "th Brazilian number: " + bigResult);
    }
}

