import java.util.regex.Pattern;
import java.util.regex.Matcher;
 
public class StripComment {
 
    private static final String COMMENT_CHARS = "#;";
 
    public static String stripComment(String source) {
        Matcher matcher = Pattern.compile(COMMENT_CHARS).matcher(source);
        if (matcher.find()) {
            return source.substring(0, matcher.start()).trim();
        }
        return source;
    }
 
    public static void main(String[] args) {
        for (String s : new String[] {
                "apples, pears # and bananas",
                "apples, pears ; and bananas",
                "no bananas",
        }) {
            System.out.printf("source:   %s%n", s);
            System.out.printf("stripped: %s%n", stripComment(s));
        }
    }
}

import java.io.File;
import java.util.List;

/**
 * Gets a fresh Chromium build from build site in internet.
 */
class BuildLoader {

  interface LoadedBuild {
    java.io.File getChromeBinary();
    int getBuildNumber();
  }

  static LoadedBuild load() {
    GoogleStorage googleStorage =
        new GoogleStorage("http://commondatastorage.googleapis.com/chromium-browser-continuous");
    List<GoogleStorage.Resource> buildList = googleStorage.readNodes("Linux_x64/");
    int maxBuildNum = -1;
    GoogleStorage.Dir dir = null;
    for (GoogleStorage.Resource res : buildList) {
      GoogleStorage.Dir nextDir = res.accept(
          new GoogleStorage.Resource.Visitor<GoogleStorage.Dir>() {
        @Override public GoogleStorage.Dir visitFile(GoogleStorage.File file) {
          return null;
        }
        @Override public GoogleStorage.Dir visitDir(GoogleStorage.Dir dir) {
          return dir;
        }
      });
      if (nextDir == null) {
        continue;
      }
      int buildNum = Integer.parseInt(nextDir.getShortName());
      if (buildNum > maxBuildNum) {
        maxBuildNum = buildNum;
        dir = nextDir;
      }
    }
    if (dir == null) {
      throw new RuntimeException();
    }

    final int buildVersion = maxBuildNum;

    GoogleStorage.File zipFile = null;
    for (GoogleStorage.Resource res : dir.getChildren()) {
      GoogleStorage.File nextFile =
          res.accept(new GoogleStorage.Resource.Visitor<GoogleStorage.File>() {
        @Override public GoogleStorage.File visitFile(GoogleStorage.File file) {
          return file;
        }
        @Override public GoogleStorage.File visitDir(GoogleStorage.Dir dir) {
          return null;
        }
      });
      if (nextFile == null) {
        continue;
      }
      String shortName = nextFile.getShortName();
      if (!shortName.endsWith(".zip")) {
        continue;
      }
      zipFile = nextFile;
      break;
    }

    if (zipFile == null) {
      throw new RuntimeException();
    }

    String url = zipFile.getUrl();

    final java.io.File chromeFile = ICustom.INSTANCE.downloadChrome(url);

    return new LoadedBuild() {
      @Override public File getChromeBinary() {
        return chromeFile;
      }
      @Override public int getBuildNumber() {
        return buildVersion;
      }
    };
  }

  // Simply loads a new build.
  public static void main(String[] args) {
    LoadedBuild loadedBuild = load();
    System.out.println("Build #" + loadedBuild.getBuildNumber() + " put into " +
        loadedBuild.getChromeBinary().getPath());
  }
}

public static String pad(String value, int length) {
        value = StringUtil.trimToEmpty(value);
        if (value.length() >= length) {
            return value;
        }
        return value + StringUtil.repeat(" ", length - value.length());
    }

import java.io.BufferedInputStream;
import java.io.FileInputStream;
import java.util.ArrayList;
import java.util.Scanner;

public class Graph {
    static BufferedInputStream bufferedInputStream;
    static ArrayList<String> strBytes;

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        strBytes = new ArrayList<>();
        System.out.println("Enter a filename: ");
        String fileName = in.nextLine().trim();
        try {
            bufferedInputStream = new BufferedInputStream(new FileInputStream(fileName));
            int b;
            while ((b = bufferedInputStream.read()) != -1) {
                String val = getBits(b);
                strBytes.add(val);
            }
        } catch (Exception e) {
            e.printStackTrace();
        }
        System.out.println("The contents of the file, converted to bytes are: ");
        System.out.println(strBytes.toString());

        in.close();
    }

    public static String getBits(int value) {
        StringBuilder bits = new StringBuilder();
        long i;
        for (i = 128; i > 0; i /= 2) {
            bits.append((value & i) != 0 ? "1" : "0");
        }
        return bits.toString();
    }
}

public MeasurementGroup findOrCreateGroup(String label) {
    // Assuming you have a list of MeasurementGroup objects
    List<MeasurementGroup> groups = getExistingGroups();

    // Try to find an existing group with the given label
    for (MeasurementGroup group : groups) {
        if (group.getLabel().equals(label)) {
            return group;
        }
    }

    // If no group was found, create a new one
    MeasurementGroup newGroup = new MeasurementGroup(label);
    groups.add(newGroup);
    return newGroup;
}

import java.util.Random;
import java.util.Scanner;

public class Lottery {
    public static void main(String[] args) {
        // Create a Random object to generate random integers
        Random random = new Random();

        // Generate a three-digit lottery number
        int lottery = random.nextInt(900) + 100; // ensure the number is three-digit

        // Prompt the user to enter a three-digit number
        Scanner input = new Scanner(System.in);
        System.out.print("Enter a three-digit number: ");
        int guess = input.nextInt();

        // Check if the guess matches the lottery number
        if (guess == lottery) {
            System.out.println("Exact match: you win $10,000!");
        } else {
            // Check if all digits in the guess match all digits in the lottery number
            int lotteryDigit1 = lottery / 100;
            int lotteryDigit2 = (lottery / 10) % 10;
            int lotteryDigit3 = lottery % 10;

            int guessDigit1 = guess / 100;
            int guessDigit2 = (guess / 10) % 10;
            int guessDigit3 = guess % 10;

            if (guessDigit1 == lotteryDigit1 && guessDigit2 == lotteryDigit2 && guessDigit3 == lotteryDigit3) {
                System.out.println("Match all digits: you win $3,000!");
            } else if (guessDigit1 == lotteryDigit1 || guessDigit2 == lotteryDigit2 || guessDigit3 == lotteryDigit3) {
                System.out.println("Match one digit: you win $1,000!");
            } else {
                System.out.println("Sorry, no match. Try again next time!");
            }
        }
    }
}

import java.util.Calendar;
import java.util.GregorianCalendar;
 
public class FiveFSS {
    private static boolean[] years = new boolean[201];
    private static int[] month31 = {Calendar.JANUARY, Calendar.MARCH, Calendar.MAY,
        Calendar.JULY, Calendar.AUGUST, Calendar.OCTOBER, Calendar.DECEMBER};
 
    public static void main(String[] args) {
        StringBuilder months = new StringBuilder();
        int numMonths = 0;
        for (int year = 1900; year <= 2100; year++) {
            for (int month : month31) {
                Calendar date = new GregorianCalendar(year, month, 1);
                if (date.get(Calendar.DAY_OF_WEEK) == Calendar.FRIDAY) {
                    years[year - 1900] = true;
                    numMonths++;
                    //months are 0-indexed in Calendar
                    months.append((date.get(Calendar.MONTH) + 1) + "-" + year +"\n");
                }
            }
        }
        System.out.println("There are "+numMonths+" months with five weekends from 1900 through 2100:");
        System.out.println(months);
        System.out.println("Years with no five-weekend months:");
        for (int year = 1900; year <= 2100; year++) {
            if(!years[year - 1900]){
                System.out.println(year);
            }
        }
    }
}

