import java.util.stream.IntStream;

public class Multifactorial {

    public static void main(String[] args) {
        System.out.println(IntStream.range(1, 6)
               .mapToObj(degree -> IntStream.range(1, 11)
                       .mapToObj(number -> multifactorial(number, degree))
                       .reduce((a, b) -> a + " " + b)
                       .get())
               .reduce((a, b) -> a + "\n" + b)
               .get());
    }

    private static int multifactorial(int number, int degree) {
        if (degree < 1) {
            throw new IllegalArgumentException("degree");
        }

        int count = 1 + (number - 1) / degree;
        if (count < 1) {
            throw new IllegalArgumentException("number");
        }

        return IntStream.range(0, count)
               .reduce(1, (accumulator, index) -> accumulator * (number - degree * index));
    }
}

