import java.util.Stack;

public class PostfixEvaluator {

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java PostfixEvaluator \"postfix expression\"");
            return;
        }

        String postfixExpr = args[0];
        double result = evaluatePostfix(postfixExpr);
        System.out.println("Result: " + result);
    }

    public static double evaluatePostfix(String postfixExpr) {
        Stack<Double> stack = new Stack<>();

        String[] tokens = postfixExpr.split("\\s+");

        for (String token : tokens) {
            if (isOperator(token)) {
                double operand2 = stack.pop();
                double operand1 = stack.pop();
                double result = applyOperator(token, operand1, operand2);
                stack.push(result);
            } else {
                double operand = Double.parseDouble(token);
                stack.push(operand);
            }
        }

        return stack.pop();
    }

    public static boolean isOperator(String token) {
        return token.equals("+") || token.equals("-") || token.equals("*") || token.equals("/");
    }

    public static double applyOperator(String operator, double operand1, double operand2) {
        if (operator.equals("+")) {
            return operand1 + operand2;
        } else if (operator.equals("-")) {
            return operand1 - operand2;
        } else if (operator.equals("*")) {
            return operand1 * operand2;
        } else {
            return operand1 / operand2;
        }
    }

}

class Finder {
    public int maximizeSum(int[] nums, int k) {
        int ans = 0;
        for (int i = 0; i < k; i++) {
            ans += solve(nums);
        }
        return ans;
    }

    private int solve(int[] nums) {
        int max = -1;
        int index = -1;
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > max) {
                index = i;
                max = nums[i];
            }
        }
        nums[index] = max + 1;
        return max;
    }
}

import java.util.Scanner;

public class AralikToplama {

    // Iki sinir arasindaki (kucukten buyuge) tum sayilarin toplamini dondurur
    public static void toplaAralik(int alt, int ust) {
        int birikim = 0; // toplami tutan degisken
        int sayac = alt;
        while (sayac <= ust) { // alt sinirdan ust sinira kadar ilerler
            birikim += sayac; // her adimda sayac degeri toplama katilir
            sayac++;
        }
        // Sonucu ekrana bas
        System.out.println(alt + " ile " + ust + " arasindaki sayilarin toplami: " + birikim);
    }

    public static void main(String[] args) {
        Scanner giris = new Scanner(System.in);

        // Kullanicidan ilk siniri al
        System.out.print("Baslangic degerini girin (a): ");
        int deger1 = giris.nextInt();

        // Kullanicidan ikinci siniri al
        System.out.print("Bitis degerini girin (b): ");
        int deger2 = giris.nextInt();

        // Kucuk olan deger once, buyuk olan sonra gelecek sekilde metodu cagir
        if (deger1 < deger2) {
            toplaAralik(deger1, deger2);
        } else {
            toplaAralik(deger2, deger1);
        }

        giris.close();
    }
}

