import java.util.*;

interface Generator<T> {
    T next();
}

class FilmGenerator implements Generator<String> {
    private static String[] FILMNAME = {
            "Film1", "Film2", "Film3", "Film4", "Film5",
            "Film6", "Film7", "Film8", "Film9", "Film10"
    };
    private static int count = 0;
    private int cursor = 0;

    public String next() {
        if (cursor == FILMNAME.length) {
            cursor = 0;
        }
        return FILMNAME[cursor++];
    }

    public static FilmGenerator getFilmGenerator() {
        return new FilmGenerator();
    }

    public String[] getFilms(String[] array) {
        for (int i = 0; i < array.length; i++) {
            array[i] = next();
        }
        return array;
    }

    public Collection<String> getFilms(Collection<String> c, int filmNum) {
        for (int i = 0; i < filmNum; i++) {
            c.add(next());
        }
        return c;
    }
}

