        gen.getFilms(filmHashSet, 6);
        System.out.println("HashSet: " + filmHashSet);
    }
}

public boolean uniqueOccurrences(int[] arr) {
HashMap<Integer, Integer> cnts = new HashMap<>();
Set set = new HashSet();

for (int elem : arr) {
cnts.put(elem, cnts.getOrDefault(elem, 0) + 1);
}

for (Integer cnt : cnts.values()) {
if (set.contains(cnt)) {
return false;
}

set.add(cnt);
}

return true;
}
}

### Technique

Use HashMap to store the frequency of each element in the given array. Then use set to store the elements that have occurred more than once.

Pseudocode

for each element in arr

increment its frequency in the HashMap

check if the frequency of any element exists in HashSet

return true for successfully unique occurrences, otherwise, return false
