public enum Stereo {
    CLOCKWISE, ANTI_CLOCKWISE;
}

public Stereo getStereoChemistry(Atom atom1, Atom atom2, Atom atom3, Atom atom4) {
    // Find the vectors between the atoms
    double[] vector1 = {atom2.getX() - atom1.getX(), atom2.getY() - atom1.getY(), atom2.getZ() - atom1.getZ()};
    double[] vector2 = {atom3.getX() - atom1.getX(), atom3.getY() - atom1.getY(), atom3.getZ() - atom1.getZ()};
    double[] vector3 = {atom4.getX() - atom1.getX(), atom4.getY() - atom1.getY(), atom4.getZ() - atom1.getZ()};

    // Calculate the cross product of the vectors
    double[] crossProduct1 = {vector1[1] * vector2[2] - vector1[2] * vector2[1], vector1[2] * vector2[0] - vector1[0] * vector2[2], vector1[0] * vector2[1] - vector1[1] * vector2[0]};
    double[] crossProduct2 = {vector3[1] * vector2[2] - vector3[2] * vector2[1], vector3[2] * vector2[0] - vector3[0] * vector2[2], vector3[0] * vector2[1] - vector3[1] * vector2[0]};

    // Calculate the dot product of the cross products
    double dotProduct = crossProduct1[0] * crossProduct2[0] + crossProduct1[1] * crossProduct2[1] + crossProduct1[2] * crossProduct2[2];

    // Determine the stereochemistry based on the sign of the dot product
    if(dotProduct > 0) {
        return Stereo.CLOCKWISE;
    } else {
        return Stereo.ANTI_CLOCKWISE;
    }
}

import java.util.Scanner;
 
public class IntegerArithmetic {
    public static void main(String[] args) {
        // Get the 2 numbers from command line arguments
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
 
        int sum = a + b;        // The result of adding 'a' and 'b' (Note: integer addition is discouraged in print statements due to confusion with string concatenation)
        int difference = a - b; // The result of subtracting 'b' from 'a'
        int product = a * b;    // The result of multiplying 'a' and 'b'
        int division = a / b;   // The result of dividing 'a' by 'b' (Note: 'division' does not contain the fractional result)
        int remainder = a % b;  // The remainder of dividing 'a' by 'b'
 
        System.out.println("a + b = " + sum);
        System.out.println("a - b = " + difference);
        System.out.println("a * b = " + product);
        System.out.println("quotient of a / b = " + division);   // truncates towards 0
        System.out.println("remainder of a / b = " + remainder);   // same sign as first operand
    }
}

