import java.util.Arrays;
 
public class KnightTour {
    static int[][] moves = {
        {-1, -2}, { 1, -2}, {-1,  2}, {1, 2},
        {-2, -1}, {-2,  1}, { 2, -1}, {2, 1}
    };
 
    static String board1 =
        " xxx    " +
        " x xx   " +
        " xxxxxxx" +
        "xxx  x x" +
        "x x  xxx" +
        "sxxxxxx " +
        "  xx x  " +
        "   xxx  ";
 
    static String board2 =
        ".....s.x....." +
        ".....x.x....." +
        "....xxxxx...." +
        ".....xxx....." +
        "..x..x.x..x.." +
        "xxxxx...xxxxx" +
        "..xx.....xx.." +
        "xxxxx...xxxxx" +
        "..x..x.x..x.." +
        ".....xxx....." +
        "....xxxxx...." +
        ".....x.x....." +
        ".....x.x.....";
 
    static boolean solve(int[][] pz, int sz, int sx, int sy, int idx, int cnt) {
        if (idx > cnt) return true;
        for (int i = 0; i < moves.length; i++) {
            int x = sx + moves[i][0];
            int y = sy + moves[i][1];
            if ((x >= 0) && (x < sz) && (y >= 0) && (y < sz) && (pz[x][y] == 0)) {
                pz[x][y] = idx;
                if (solve(pz, sz, x, y, idx + 1, cnt)) return true;
                pz[x][y] = 0;
            }
        }
        return false;
    }
 
    static void findSolution(String b, int sz) {
        int[][] pz = new int[sz][sz];
        for (int[] row: pz) Arrays.fill(row, -1);
        int x = 0;
        int y = 0;
        int idx = 0;
        int cnt = 0;
        for (int j = 0; j < sz; j++) {
            for (int i = 0; i < sz; i++) {
                if (b.charAt(idx) == 'x') {
                    pz[i][j] = 0;
                    cnt++;
                }
                else if (b.charAt(idx) =='s') {
                    pz[i][j] = 1;
                    cnt++;
                    x = i;
                    y = j;
                }
                idx++;
            }
        }
 
        if (solve(pz, sz, x, y, 2, cnt)) {
            for (int j = 0; j < sz; j++) {
                for (int i = 0; i < sz; i++) {
                    if (pz[i][j]!= -1)
                        System.out.printf("%02d  ", pz[i][j]);
                    else
                        System.out.print("--  ");
                }
                System.out.println();
            }
        }
        else System.out.println("Cannot solve this puzzle!");
    }
 
    public static void main(String[] args) {
        findSolution(board1,  8);
        System.out.println();
        findSolution(board2, 13);
    }
}

