import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class DataCenterFilter {
    private List<String> dataCenters;

    public DataCenterFilter(List<String> dataCenters) {
        this.dataCenters = dataCenters;
    }

    public List<String> nameContains(String... names) {
        return dataCenters.stream()
                .filter(dataCenter -> Arrays.stream(names)
                        .anyMatch(name -> dataCenter.toLowerCase().contains(name.toLowerCase())))
                .collect(Collectors.toList());
    }
}

