public int numSplits(String s) {
        Map<Character, Integer> leftMap = new HashMap<>();
        Map<Character, Integer> rightMap = new HashMap<>();
        for(int i=0;i<s.length();i++){
            rightMap.put(s.charAt(i), rightMap.getOrDefault(s.charAt(i), 0)+1);
        }
        int count=0;
        for(int i=0;i<s.length()-1;i++){
            rightMap.put(s.charAt(i), rightMap.get(s.charAt(i))-1);
            if(rightMap.get(s.charAt(i))==0){
                rightMap.remove(s.charAt(i));
            }
            leftMap.put(s.charAt(i), leftMap.getOrDefault(s.charAt(i), 0)+1);
            if(rightMap.size()==leftMap.size()){
                count++;
            }
        }
        return count;
    }
}

import java.io.*;

public class Cache {
    public static void main(String[] args) {
        if (args.length < 2) {
            System.out.println("Usage: java Cache SourceFile1 . . . SourceFilen TargetFile");
            System.exit(0);
        }

        try {
            FileOutputStream outputStream = new FileOutputStream(args[args.length - 1]);

            for (int i = 0; i < args.length - 1; i++) {
                FileInputStream inputStream = new FileInputStream(args[i]);
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    outputStream.write(buffer, 0, bytesRead);
                }
                inputStream.close();
            }

            outputStream.close();
            System.out.println("Files combined successfully into " + args[args.length - 1]);
        } catch (IOException e) {
            System.out.println("Error: " + e.getMessage());
        }
    }
}

