public static void convolve(Kernel2D_S32 kernel, GrayS16 src, GrayI16 dst ) {
    // Check if the dimensions of the source and destination images are the same
    if (src.width != dst.width || src.height != dst.height) {
        throw new IllegalArgumentException("Source and destination images must have the same dimensions.");
    }

    // Get the width and height of the kernel
    int kernelWidth = kernel.getWidth();
    int kernelHeight = kernel.getHeight();

    // Calculate the padding needed for the convolution
    int padX = kernelWidth / 2;
    int padY = kernelHeight / 2;

    // Iterate over each pixel in the source image
    for (int y = 0; y < src.height; y++) {
        for (int x = 0; x < src.width; x++) {
            int sum = 0;

            // Iterate over each element in the kernel
            for (int ky = 0; ky < kernelHeight; ky++) {
                for (int kx = 0; kx < kernelWidth; kx++) {
                    // Calculate the corresponding pixel in the source image
                    int pixelX = x + kx - padX;
                    int pixelY = y + ky - padY;

                    // Check if the pixel is within the bounds of the source image
                    if (pixelX >= 0 && pixelX < src.width && pixelY >= 0 && pixelY < src.height) {
                        // Multiply the pixel value by the kernel value and add to the sum
                        sum += src.get(pixelX, pixelY) * kernel.get(ky, kx);
                    }
                }
            }

            // Normalize the sum by dividing by the sum of the kernel values
            int kernelSum = kernel.computeSum();
            if (kernelSum != 0) {
                sum /= kernelSum;
            }

            // Set the pixel value in the destination image
            dst.set(x, y, (short) sum);
        }
    }
}

import java.math.BigInteger;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.List;
 
public class PellsEquation {
 
    public static void main(String[] args) {
        NumberFormat format = NumberFormat.getInstance();
        for ( int n : new int[] {61, 109, 181, 277, 8941} ) {
            BigInteger[] pell = pellsEquation(n);
            System.out.printf("x^2 - %3d * y^2 = 1 for:%n    x = %s%n    y = %s%n%n", n,  format.format(pell[0]),  format.format(pell[1]));
        }
    }
 
    private static final BigInteger[] pellsEquation(int n) {
        int a0 = (int) Math.sqrt(n);
        if ( a0*a0 == n ) {
            throw new IllegalArgumentException("ERROR 102:  Invalid n = " + n);
        }
        List<Integer> continuedFrac = continuedFraction(n);
        int count = 0;
        BigInteger ajm2 = BigInteger.ONE;
        BigInteger ajm1 = new BigInteger(a0 + "");
        BigInteger bjm2 = BigInteger.ZERO;
        BigInteger bjm1 = BigInteger.ONE;
        boolean stop = (continuedFrac.size() % 2 == 1);
        if ( continuedFrac.size() == 2 ) {
            stop = true;
        }
        while ( true ) {
            count++;
            BigInteger bn = new BigInteger(continuedFrac.get(count) + "");
            BigInteger aj = bn.multiply(ajm1).add(ajm2);
            BigInteger bj = bn.multiply(bjm1).add(bjm2);
            if ( stop && (count == continuedFrac.size()-2 || continuedFrac.size() == 2) ) {
                return new BigInteger[] {aj, bj};
            }
            else if (continuedFrac.size() % 2 == 0 && count == continuedFrac.size()-2 ) {
                stop = true;
            }
            if ( count == continuedFrac.size()-1 ) {
                count = 0;
            }
            ajm2 = ajm1;
            ajm1 = aj;
            bjm2 = bjm1;
            bjm1 = bj;
        }
    }
 
    private static final List<Integer> continuedFraction(int n) {
        List<Integer> answer = new ArrayList<Integer>();
        int a0 = (int) Math.sqrt(n);
        answer.add(a0);
        int a = -a0;
        int aStart = a;
        int b = 1;
        int bStart = b;
 
        while ( true ) {
            //count++;
            int[] values = iterateFrac(n, a, b);
            answer.add(values[0]);
            a = values[1];
            b = values[2];
            if (a == aStart && b == bStart) break;
        }
        return answer;
    }
 
