public void mapPatternsToColumns(List<Pattern> patterns, SparseMatrix matrix) {
    Map<Pattern, Integer> patternColumnMap = new HashMap<>();
    int column = 0;

    for (Pattern pattern : patterns) {
        patternColumnMap.put(pattern, column++);
    }

    for (int i = 0; i < matrix.getNumRows(); i++) {
        List<Integer> indicesToUpdate = new ArrayList<>();

        for (int j = 0; j < matrix.getNumCols(); j++) {
            if (matrix.getElement(i, j) != 0 && patternColumnMap.containsKey(matrix.getElement(i, j))) {
                indicesToUpdate.add(patternColumnMap.get(matrix.getElement(i, j)));
            }
        }

        for (Integer index : indicesToUpdate) {
            matrix.setElement(i, index, 1);
        }
    }
}

import java.util.Collection;
import java.util.LinkedList;
import org.debian.alioth.shootout.u32.nbody.NBodySystem;
import com.tantaman.commons.concurrent.Parallel;

public class ParallelForDemo {

    public static void main(String[] args) {
        // Warm-up phase to allow JVM optimizations
        warmUp();

        // Initialize collection of integers
        Collection<Integer> elems = new LinkedList<>();
        for (int i = 0; i < 10000; i++) {
            elems.add(i);
        }

        // Define the N-body system operation
        Parallel.Operation<Integer> bodiesOp = new Parallel.Operation<Integer>() {
            @Override
            public void perform(Integer param) {
                NBodySystem system = new NBodySystem();
                system.advance(0.01); // Simulate N-body system computation
            }
        };

        // Measure execution time for standard parallel loop
        long startTime = System.nanoTime();
        Parallel.For(elems, bodiesOp);
        long endTime = System.nanoTime();
        System.out.println("Standard Parallel.For time: " + (endTime - startTime) / 1_000_000 + " ms");

        // Measure execution time for Fork-Join parallel loop
        startTime = System.nanoTime();
        Parallel.ForFJ(elems, bodiesOp);
        endTime = System.nanoTime();
        System.out.println("Fork-Join Parallel.ForFJ time: " + (endTime - startTime) / 1_000_000 + " ms");
    }

    private static void warmUp() {
        // Perform a warm-up phase to allow JVM optimizations
        Collection<Integer> warmUpElems = new LinkedList<>();
        for (int i = 0; i < 1000; i++) {
            warmUpElems.add(i);
        }

        Parallel.Operation<Integer> warmUpOp = new Parallel.Operation<Integer>() {
            @Override
            public void perform(Integer param) {
                NBodySystem system = new NBodySystem();
                system.advance(0.01);
            }
        };

        Parallel.For(warmUpElems, warmUpOp);
        Parallel.ForFJ(warmUpElems, warmUpOp);
    }
}

public class BosReferansHatasi {

    public static void main(String[] args) {

        // Null degeri atanmis bir nesne olustur
        String str = null;

        try {
            // Null olan nesne uzerinde bir metod cagirilmaya calisilir
            int uzunluk = str.length(); // Burada NullPointerException olusur
            System.out.println("String uzunlugu: " + uzunluk);
        } catch (NullPointerException e) {
            // NullPointerException yakalanir ve kullaniciya mesaj verilir
            System.out.println("Hata: Null deger uzerinde islem yapilamaz!");
            System.out.println("Hata mesaji: " + e.getMessage());
            e.printStackTrace(); // Istisnanin izini yazdir
        } finally {
            // Kaynak temizleme veya islemin tamamlandigini bildirmek icin kullanilir
            System.out.println("Islem tamamlandi.");
        }

        // Alternatif bir ornek: Null degeri olmayan bir nesne
        String str2 = "Merhaba";
        System.out.println("String uzunlugu: " + str2.length()); // Bu islem basariyla calisir
    }
}

import java.util.Scanner;

public class DivisibleBy5And6 {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);

        System.out.print("Enter an integer: ");
        int number = input.nextInt();

        boolean divisibleBy5And6 = (number % 5 == 0) && (number % 6 == 0);
        boolean divisibleBy5Or6 = (number % 5 == 0) || (number % 6 == 0);
        boolean divisibleBy5Or6ButNotBoth = (number % 5 == 0) ^ (number % 6 == 0);

        System.out.println(number + " is divisible by 5 and 6? " + divisibleBy5And6);
        System.out.println(number + " is divisible by 5 or 6? " + divisibleBy5Or6);
        System.out.println(number + " is divisible by 5 or 6, but not both? " + divisibleBy5Or6ButNotBoth);
    }
}

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class RDDSampleUtilsTest
{

    /**
     * Test get sample numbers.
     */
    @Test
    public void testGetSampleNumbers()
    {
        assertEquals(10, RDDSampleUtils.getSampleNumbers(2, 10, -1));
        assertEquals(100, RDDSampleUtils.getSampleNumbers(2, 100, -1));
        assertEquals(10, RDDSampleUtils.getSampleNumbers(5, 1000, -1));
        assertEquals(100, RDDSampleUtils.getSampleNumbers(5, 10000, -1));
        assertEquals(100, RDDSampleUtils.getSampleNumbers(5, 10001, -1));
        assertEquals(1000, RDDSampleUtils.getSampleNumbers(5, 100011, -1));
        assertEquals(99, RDDSampleUtils.getSampleNumbers(6, 100011, 99));
        assertEquals(999, RDDSampleUtils.getSampleNumbers(20, 999, -1));
        assertEquals(40, RDDSampleUtils.getSampleNumbers(20, 1000, -1));
    }

    /**
     * Test too many partitions.
     */
    @Test
    public void testTooManyPartitions()
    {
        assertFailure(505, 999);
        assertFailure(505, 1000);
        assertFailure(10, 1000, 2100);
    }

    private void assertFailure(int numPartitions, long totalNumberOfRecords)
    {
        assertFailure(numPartitions, totalNumberOfRecords, -1);
    }

    private void assertFailure(int numPartitions, long totalNumberOfRecords, int givenSampleNumber)
    {
        try {
            RDDSampleUtils.getSampleNumbers(numPartitions, totalNumberOfRecords, givenSampleNumber);
            fail("Expected IllegalArgumentException");
        }
        catch (IllegalArgumentException e) {
            // expected
        }
    }
}

