public class CF_692_E{

    public static void main(String[] args) throws Exception{

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        PrintWriter pw = new PrintWriter(new OutputStreamWriter(System.out));

        StringTokenizer st;

        st = new StringTokenizer(br.readLine().trim());

        int n = Integer.parseInt(st.nextToken());

        long t = Long.parseLong(st.nextToken());

        String s = br.readLine();

        t -= 1<<s.charAt(n-1)-'a';

        t += 1<<s.charAt(n-2)-'a';

        n-=2;

        int c[] = new int[26];

        for(int i=0;i<n;i++)

            c[s.charAt(i)-'a']++;

        for(int i=25;i>=0;i--){

            while(c[i]-->0){

                if(t>0)

                    t -= 1<<i;

                else

                    t += 1<<i;

            }

        }

        if(t==0)

            pw.print("Yes");

        else

            pw.print("No");

        pw.flush();

        pw.close();

    }

}

public class Manager {
    class Point implements Comparable<Point>{
        boolean isStart;
        int x;
        int index;
        Point(boolean isStart, int x,int index){
            this.isStart = isStart;
            this.x = x;
            this.index = index;
        }

        public int compareTo(Point b){
            if(b.x!=this.x) return this.x - b.x;
            return this.isStart?-1:1;
        }

        public int hashCode(){
            return this.index;
        }

        public boolean equals(Object obj){
            Point p = (Point) obj;
            return this.index == p.index;
        }
    }
    public int findMinArrowShots(int[][] points) {
        int m = points.length;
        if(m==0) return 0;
        int n= points[0].length;
        if(n==0) return 0;
        int count = 0;
        HashSet<Point> shoted = new HashSet<>();
        PriorityQueue<Point> pq = new PriorityQueue<>();
        Stack<Point> stack = new Stack<>();
        int j=0;
        for(int [] p : points){
            Point s = new Point(true,p[0],j);
            Point e = new Point(false,p[1],j);
            j++;
            pq.add(s);
            pq.add(e);
        }
        while(!pq.isEmpty()){
            Point p = pq.poll();
            if(p.isStart){
                stack.push(p);
            }else{
                if(shoted.add(p)){
                    count++;
                    while(!stack.isEmpty()){
                        shoted.add(stack.pop());
                    }
                }
            }
        }
        return count;
    }
}

