            if (n2 > 0) {
                if (n2 % b!= f) {
                    return false;
                }
            } else {
                break;
            }
        }
        return true;
    }

    public static boolean isBrazilian(int n) {
        if (n < 7) return false;
        if (n % 2 == 0) return true;
        for (int b = 2; b < n - 1; b++) {
            if (sameDigits(n, b)) {
                return true;
            }
        }
        return false;
    }

    public static boolean isPrime(int n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        if (n % 3 == 0) return n == 3;
        int d = 5;
        while (d * d <= n) {
            if (n % d == 0) return false;
            d += 2;
            if (n % d == 0) return false;
            d += 4;
        }
        return true;
    }

    public static void main(String[] args) {
        int bigLim = 99999;
        int limit = 20;
        for (String kind : ",odd,prime".split(",")) {
            boolean quiet = false;
            System.out.println("First " + limit + " " + kind + "Brazilian numbers:");
            int c = 0;
            int n = 7;
            while (c < bigLim) {
                if (isBrazilian(n)) {
                    if (!quiet) System.out.print(String.format("%,d ", n));
                    if (++c == limit) {
                        System.out.print("\n\n");
                        quiet = true;
                    }
                }
                if (quiet &&!kind.equals("")) continue;
                switch (kind) {
                    case "":
                        n++;
                        break;
                    case "odd ":
                        n += 2;
                        break;
                    case "prime":
                        while (true) {
                            n += 2;
                            if (isPrime(n)) break;
                        }
                        break;
                }
            }
            if (kind.equals("")) System.out.println("The " + String.format("%,dth Brazilian number is: %,d", bigLim + 1, n));
        }
    }
}

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.IOException;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;
 
public class Ordered {
 
    private static boolean isOrderedWord(String word){
        char[] sortedWord = word.toCharArray();
        Arrays.sort(sortedWord);
        return word.equals(new String(sortedWord));
    }
 
    public static void main(String[] args) throws IOException{
        List<String> orderedWords = new LinkedList<String>();
        BufferedReader in = new BufferedReader(new FileReader(args[0]));
        while(in.ready()){
            String word = in.readLine();
            if(isOrderedWord(word)) orderedWords.add(word);
        }
        in.close();
 
        Collections.<String>sort(orderedWords, new Comparator<String>() {
            @Override
            public int compare(String o1, String o2) {
                return new Integer(o2.length()).compareTo(o1.length());
            }
        });
 
        int maxLen = orderedWords.get(0).length();
        for(String word: orderedWords){
            if(word.length() == maxLen){
                System.out.println(word);
            }else{
                break;
            }
        }
    }
}

