public static <U> List<List<U>> createBatchFromList(List<U> list, int batchLimit) {
    List<List<U>> batches = new ArrayList<>();
    for (int i = 0; i < list.size(); i += batchLimit) {
        int endIndex = Math.min(i + batchLimit, list.size());
        batches.add(list.subList(i, endIndex));
    }
    return batches;
}

