import java.util.Scanner;

public class HikingGameStrategy {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] permutation = new int[n];
        int leftFingers = 0, rightFingers = 0;

        for(int i = 0; i < n; i++) {
            permutation[i] = scanner.nextInt();
            if(permutation[i] > permutation[i-1]){
                leftFingers++;
            }
            if(permutation[i] < permutation[i+1]){
                rightFingers++;
            }
        }

        scanner.close();

        // Qingshan wins if there's a position with exactly 2 fingers on the left
        System.out.println(rightFingers - 2 + leftFingers - 1);
    }
}

