class Processor {
    public int nthUglyNumber(int n, int a, int b, int c) {

        long left = 1;
        long right = 2 * 1_000_000_009;

        long gcd1 = gcd(a, b);
        long gcd2 = gcd(b, c);
        long gcd3 = gcd(a, c);
        long gcd4 = gcd(gcd1, gcd2);

        long lcm1 = (long)a * (long)b / gcd1;
        long lcm2 = (long)b * (long)c / gcd2;
        long lcm3 = (long)a * (long)c / gcd3;
        long gcd5 = gcd(lcm1, lcm2);
        long lcm4 = lcm1 / gcd5 * (lcm2 / gcd5) * gcd5;

        // System.out.println(lcm1);
        // System.out.println(lcm2);
        // System.out.println(lcm3);
        // System.out.println(lcm4);

        while(left < right - 1)
        {
            long mid = left + (right - left) / 2;
            long cnt = getCnt(mid, a, b, c, lcm1, lcm2, lcm3, lcm4);

            if(cnt >= n)
                right = mid;
            else
                left = mid;
        }

        if(getCnt(left, a, b, c, lcm1, lcm2, lcm3, lcm4) == n)
            return (int)left;

        return (int)right;
    }

    private long getCnt(long target, int a, int b, int c, long lcm1, long lcm2, long lcm3, long lcm4)
    {
        return target/a + target/b + target/c - (lcm1 > 0 ? target/lcm1 : 0) - (lcm2 > 0 ? target/lcm2 : 0) - (lcm2 > 0 ? target/lcm3 : 0) + (lcm2 > 0 ? target/lcm4 : 0);
    }

    private long gcd(long a, long b)
    {
        if(a == 0)
            return b;
        return gcd(b % a, a);
    }
}

import java.io.BufferedReader;
import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.InputStreamReader;
import java.net.Socket;

/**
 * Simple echo-style client: reads a line from the console, sends it
 * with DataOutputStream, then prints whatever comes back until the
 * user types "stop".
 */
public class Client {

    private static final String HOST = "localhost";
    private static final int PORT = 4444;

    public static void main(String[] args) {
        Socket connection = null;
        DataInputStream fromServer = null;
        DataOutputStream toServer = null;
        BufferedReader console = null;

        try {
            System.out.println("Sunucuya baglanmaya calisiliyor...");
            connection = new Socket(HOST, PORT);
            System.out.println("Sunucuya basariyla baglanildi!");

            fromServer = new DataInputStream(connection.getInputStream());
            toServer = new DataOutputStream(connection.getOutputStream());
            console = new BufferedReader(new InputStreamReader(System.in));

            String typed = "";
            String echoed;

            while (!typed.equals("stop")) {
                System.out.print("Sunucuya gondermek icin bir mesaj girin: ");
                typed = console.readLine();
                toServer.writeUTF(typed);
                toServer.flush();

                echoed = fromServer.readUTF();
                System.out.println("Sunucudan gelen mesaj: " + echoed);
            }

        } catch (Exception e) {
            System.err.println("Bir hata olustu: " + e.getMessage());
            e.printStackTrace();
        } finally {
            closeQuietly(fromServer, toServer, console, connection);
        }
    }

    private static void closeQuietly(DataInputStream in, DataOutputStream out, BufferedReader reader, Socket socket) {
        try {
            if (in != null) in.close();
            if (out != null) out.close();
            if (reader != null) reader.close();
            if (socket != null) socket.close();
            System.out.println("Baglanti kapatildi.");
        } catch (Exception e) {
            System.err.println("Kaynaklar kapatilirken bir hata olustu: " + e.getMessage());
        }
    }
}

