public class Timer {
    static final int MOD = (int) 1e9 + 7;
    static final int MAXN = (int) 1e6 + 10;

    static long[] fac = new long[MAXN];
    static long[] inv = new long[MAXN];

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        init();
        int n = sc.nextInt();

        long ans = fac[n];
        for (int i = 1; i <= n - 1; i++) {
            ans -= fac[i] * fac[n - i] % MOD * (n - i) % MOD;
            ans %= MOD;
            ans += MOD;
            ans %= MOD;
        }

        pw.println(ans);

        pw.close();
    }

    static void init() {
        fac[0] = 1;
        for (int i = 1; i < MAXN; i++)
            fac[i] = fac[i - 1] * i % MOD;

        inv[MAXN - 1] = pow(fac[MAXN - 1], MOD - 2);
        for (int i = MAXN - 2; i >= 0; i--)
            inv[i] = inv[i + 1] * (i + 1) % MOD;
    }

    static long pow(long a, long b) {
        long ret = 1;
        while (b > 0) {
            if ((b & 1) > 0)
                ret = ret * a % MOD;
            a = a * a % MOD;
            b >>= 1;
        }
        return ret;
    }

