        int idx = 0;
        for (int i = 0; i < nums.length; i++) {
            squares[i] = nums[i]*nums[i];
        }
        for (int i = 0; i < squares.length; i++) {    // Here is different from my previous solutions as I iterated through the output array.
            while (idx < squares.length-1 && Math.abs(squares[i]) > Math.abs(squares[idx+1])) {   // This part is more like the partition method in quick sort
                idx++;
            }
            System.out.println("The position of " + squares[i] + " is " + idx);
            System.out.println("Arrays.toString(squares) = " + Arrays.toString(squares));
            if (idx < squares.length-1) {
                swap(squares, i, idx+1);
            }
        }
        return squares;
    }
    public void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

public class SayiOkuma {

    // Basamak degerlerine karsilik gelen Turkce kelimeler, index sifirdan basladigi icin ilk eleman kullanilmaz
    private static final String[] BIRLER_KELIME = {
            "", "bir", "iki", "uc", "dort", "bes", "alti", "yedi", "sekiz", "dokuz"
    };

    private static final String[] ONLAR_KELIME = {
            "", "on", "yirmi", "otuz", "kirk", "elli", "altmis", "yetmis", "seksen", "doksan"
    };

    private static final String[] YUZLER_KELIME = {
            "", "yuz", "iki yuz", "uc yuz", "dort yuz", "bes yuz", "alti yuz", "yedi yuz", "sekiz yuz", "dokuz yuz"
    };

    private static final String[] BINLER_KELIME = {
            "", "bin", "iki bin", "uc bin", "dort bin", "bes bin", "alti bin", "yedi bin", "sekiz bin", "dokuz bin"
    };

    public static void main(String[] args) {

        System.out.println(sayiyiYaziyaCevir(1234));

        System.out.println(sayiyiYaziyaCevir(7248));

        System.out.println(sayiyiYaziyaCevir(297));

        System.out.println(sayiyiYaziyaCevir(505));

        System.out.println(sayiyiYaziyaCevir(300));
    }

    // 0-9999 arasindaki bir sayiyi Turkce okunusuna cevirir
    public static String sayiyiYaziyaCevir(int deger) {
        if (deger == 0) {
            return "sifir";
        }

        int binBasamagi = deger / 1000;
        int yuzBasamagi = (deger / 100) % 10;
        int onBasamagi = (deger / 10) % 10;
        int birBasamagi = deger % 10;

        StringBuilder metin = new StringBuilder();

        metin.append(BINLER_KELIME[binBasamagi]);
        if (binBasamagi > 0) {
            metin.append(" ");
        }

        metin.append(YUZLER_KELIME[yuzBasamagi]);
        if (yuzBasamagi > 0) {
            metin.append(" ");
        }

        metin.append(ONLAR_KELIME[onBasamagi]);
        if (onBasamagi > 0) {
            metin.append(" ");
        }

        metin.append(BIRLER_KELIME[birBasamagi]);

        return metin.toString();
    }
}

