import javafx.application.Application;
import javafx.scene.Group;
import javafx.scene.Scene;
import javafx.scene.paint.Color;
import javafx.scene.shape.Line;
import javafx.stage.Stage;

public class GridDisplay extends Application {

    public void start(Stage stage) {
        Group root = new Group();
        Scene scene = new Scene(root, 400, 400);

        double width = scene.getWidth();
        double height = scene.getHeight();
        double lineLength = 0.9 * Math.min(width, height) / 3;
        double x0 = 0.5 * (width - lineLength);
        double y0 = 0.5 * (height - lineLength);

        for (int i = 0; i < 4; i++) {
            Line line1 = new Line(x0 + i * lineLength, y0, x0 + i * lineLength, y0 + 3 * lineLength);
            line1.setStroke(Color.RED);
            Line line2 = new Line(x0, y0 + i * lineLength, x0 + 3 * lineLength, y0 + i * lineLength);
            line2.setStroke(Color.BLUE);
            root.getChildren().addAll(line1, line2);
        }

        stage.setScene(scene);
        stage.show();
    }

    public static void main(String[] args) {
        launch(args);
    }
}

import java.lang.reflect.Field;
import java.util.stream.Stream;

/**
 * Some common utility methods for analyzing classes with reflection.
 *
 */
public final class ReflectionUtil {

    /**
     * Returns a stream of all the member fields for the specified class,
     * including inherited fields from any ancestors. This includes public,
     * private, protected and package private fields.
     *
     * @param clazz  the class to traverse
     * @return       stream of fields
     */
    public static Stream<Field> traverseFields(Class<?> clazz) {
        final Class<?> parent = clazz.getSuperclass();
        final Stream<Field> inherited;

        if (parent != null) {
            inherited = traverseFields(parent);
        } else {
            inherited = Stream.empty();
        }

        return Stream.concat(inherited, Stream.of(clazz.getDeclaredFields()));
    }

    /**
     * Returns a stream of all the classes upwards in the inheritance tree of
     * the specified class, including the class specified as the first element
     * and {@code java.lang.Object} as the last one.
     *
     * @param clazz  the first class in the tree
     * @return       stream of ancestors (including {@code clazz})
     */
    public static Stream<Class<?>> traverseAncestors(Class<?> clazz) {
        final Class<?>[] interfaces = clazz.getInterfaces();
        if (clazz.getSuperclass() == null) {
            if (interfaces.length == 0) {
                return Stream.of(clazz);
            } else {
                return Stream.concat(
                    Stream.of(clazz),
                    Stream.of(clazz.getInterfaces())
                        .flatMap(ReflectionUtil::traverseAncestors)
                ).distinct();
            }
        } else {
            return Stream.concat(
                Stream.of(clazz),
                Stream.concat(
                    Stream.of(clazz.getSuperclass()),
                    Stream.of(clazz.getInterfaces())
                ).flatMap(ReflectionUtil::traverseAncestors)
            ).distinct();
        }
    }

    /**
     * Should never be invoked.
     */
    private ReflectionUtil() {}
}

import java.util.Scanner;
 
public class NegativeBase {
 
    private static final String DIGITS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private static final int DIGITS_LEN = 64;
 
    public static void encodeNegativeBase(long n, long base, StringBuilder out) {
        if (base > -1 || base < -62) {
            /* Bounds check*/
            out.setLength(0);
            return;
        }
        if (n == 0) {
            /* Trivial case */
            out.setLength(0);
            out.append("0");
            return;
        }
 
        /* Convert the number into a string (in reverse) */
        while (n!= 0) {
            long rem = n % base;
            n = n / base;
            if (rem < 0) {
                n++;
                rem = rem - base;
            }
            out.append(DIGITS.charAt((int) rem));
        }
 
        /* Reverse the current string to get the final result */
        int len = out.length();
        for (int i = 0; i < len / 2; i++) {
            char t = out.charAt(i);
            out.setCharAt(i, out.charAt(len - i - 1));
            out.setCharAt(len - i - 1, t);
        }
    }
 
    public static long decodeNegativeBase(String ns, long base) {
        long value, bb;
        int i;
        int ptr;
 
        if (base < -62 || base > -1) {
            /* Bounds check */
            return 0;
        }
        if (ns.length() == 0 || (ns.length() == 1 && ns.charAt(0) == '0')) {
            /* Trivial case */
            return 0;
        }
 
        /* Find the end of the string */
        ptr = ns.length() - 1;
 
        /* Convert */
        value = 0;
        bb = 1;
        while (ptr >= 0) {
            for (i = 0; i < DIGITS_LEN; i++) {
                if (ns.charAt(ptr) == DIGITS.charAt(i)) {
                    value = value + i * bb;
                    bb = bb * base;
                    break;
                }
            }
            ptr--;
        }
 
        return value;
    }
 
    public static void driver(long n, long b) {
        StringBuilder buf = new StringBuilder();
        long value;
 
        encodeNegativeBase(n, b, buf);
        System.out.printf("%12d encoded in base %3d = %12s\n", n, b, buf.toString());
 
        value = decodeNegativeBase(buf.toString(), b);
        System.out.printf("%12s decoded in base %3d = %12d\n", buf.toString(), b, value);
 
        System.out.println();
    }
 
    public static void main(String[] args) {
        driver(10, -2);
        driver(146, -3);
        driver(15, -10);
        driver(12, -62);
    }
}

