public class MS_6_F {

    private void solveOne() {

        int n = nextInt();

        int[] a = nextIntArr(n);

        int[] ans = new int[n];

//        int p = 0;

        Set<Integer> used = new HashSet<>();

        int max = Integer.MIN_VALUE;

        int maxInd = -1;

        for (int i = 0; i < n; i++) {

            if (max <= a[i]) {

                max = a[i];

                maxInd = i;

            }

        }

        used.add(maxInd);

        ans[0] = max;

        int curGcd = ans[0];

        for (int i = 1; i < n; i++) {

            //for position i let's find the gcd that will give us maximal value

            int localMaxGcd = Integer.MIN_VALUE;

            int localMaxGcdIndex = -1;

            for (int j = 0; j < n; j++) {

                if (!used.contains(j)) {

                    int gcd = gcd(curGcd, a[j]);

                    if (localMaxGcd <= gcd) {

                        localMaxGcd = gcd;

                        localMaxGcdIndex = j;

                    }

                }

            }

            curGcd = localMaxGcd;

            ans[i] = a[localMaxGcdIndex];

            used.add(localMaxGcdIndex);

        }

        System.out.println(ans);

    }

    public int gcd(int a, int b) {

        while (b != 0) {

            int temp = a % b;

            a = b;

            b = temp;

        }

        return a;

    }

    private void solve() {

        int t = nextInt();

        for (int tt = 0; tt < t; tt++) {

            solveOne();

        }

    }

