import java.util.ArrayList;
import java.util.List;
 
public class DeBruijn {
 
    private static final String ALPHABET = "0123456789";
    private int[] a;
    private List<Integer> seq;
 
    private void db(int k, int n, int t, int p) {
        if (t > n) {
            if (n % p == 0) {
                for (int i = 1; i < p; i++) {
                    seq.add(a[i]);
                }
            }
        } else {
            a[t] = a[t - p];
            db(k, n, t + 1, p);
            int j = a[t - p] + 1;
            while (j < k) {
                a[t] = j;
                db(k, n, t + 1, t);
                j++;
            }
        }
    }
 
    private String deBruijn(int k, int n) {
        a = new int[k * n];
        seq = new ArrayList<Integer>();
        db(k, n, 1, 1);
 
        StringBuilder buf = new StringBuilder();
        for (int i : seq) {
            buf.append(ALPHABET.charAt(i));
        }
        return buf.toString() + buf.substring(0, n - 1);
    }
 
    private void validate(String db) {
        int le = db.length();
        int[] found = new int[10000];
        List<String> errs = new ArrayList<String>();
        // Check all strings of 4 consecutive digits within 'db'
        // to see if all 10,000 combinations occur without duplication.
        for (int i = 0; i < le - 4; i++) {
            String s = db.substring(i, i + 4);
            if (s.matches("\\d+")) {
                int index = Integer.parseInt(s);
                found[index]++;
            }
        }
        for (int i = 0; i < found.length; i++) {
            if (found[i] == 0) {
                errs.add(String.format("    PIN number %04d missing", i));
            } else if (found[i] > 1) {
                errs.add(String.format("    PIN number %04d occurs %d times", i, found[i]));
            }
        }
        if (errs.isEmpty()) {
            System.out.println("  No errors found");
        } else {
            String pl = (errs.size() == 1) ? "" : "s";
            System.out.println("  " + errs.size() + " error" + pl + " found:");
            for (String err : errs) {
                System.out.println(err);
            }
        }
    }
 
    public static void main(String[] args) {
        DeBruijn db = new DeBruijn();
        String deBruijn = db.deBruijn(10, 4);
        System.out.println("The length of the de Bruijn sequence is " + deBruijn.length());
        System.out.println("The first 130 digits of the de Bruijn sequence are: " + deBruijn.substring(0, 129));

public int canBeTypedWords(String text, String brokenLetters) {
    Set<Character> brokenSet = new HashSet<>();
    for (char c : brokenLetters.toCharArray()) {
        brokenSet.add(c);
    }

    int count = 0;
    String[] words = text.split(" ");
    for (String word : words) {
        boolean canType = true;
        for (char c : word.toCharArray()) {
            if (brokenSet.contains(c)) {
                canType = false;
                break;
            }
        }
        if (canType) {
            count++;
        }
    }
    return count;
}

public:
    bool reach(int x,int y){
        while(x%2==0 && y%2==0){
            x/=2;
            y/=2;
        }
        if(x==2 && y==1)
            return true;
        if(x==1 && y==2)
            return true;
        return false;
    }
    bool isReachable(int x, int y) {
        if(x==1 && y==1)
            return true;
        if(reach(x,y))
            return true;
        return false;
    }
};

