        if (currentIllustration == null) {
            return "";
        }

        NodeImage nodeImage = currentIllustration.getNodeImage();
        ImageVersion preferredVersion = findPreferredImageVersion(nodeImage);

        return preferredVersion != null
            ? buildImageUrl(preferredVersion)
            : "";
    }

    private ImageVersion findPreferredImageVersion(NodeImage nodeImage) {
        if (nodeImage == null || nodeImage.getImageVersions().isEmpty()) {
            return null;
        }

        return nodeImage.getImageVersions().stream()
            .filter(version -> version.getType().equals("MEDIUM"))
            .findFirst()
            .orElse(nodeImage.getImageVersions().get(0));
    }

