/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Checker {
    public ListNode deleteMiddle(ListNode head) {
        if (head == null || head.next == null) {
            return null;
        }
        int v = 0;
        ListNode node = head;
        while(node != null) {
            v ++;
            node = node.next;
        }
        int half = v/2;
        node = head;
        while(half > 1) {
            node = node.next;
            half --;
        }
        node.next = node.next.next;
        return head;

    }
}

protected JsonToken handleBinary() throws IOException {
        int size = _in.readInt();
        byte subtype = _in.readByte();
        Context ctx = getContext();
        switch (subtype) {
        case BsonConstants.SUBTYPE_BINARY_OLD:
            int size2 = _in.readInt();
            byte[] buf2 = new byte[size2];
            _in.readFully(buf2);
            ctx.value = buf2;
            break;

        case BsonConstants.SUBTYPE_UUID:
            long l1 = _in.readLong();
            long l2 = _in.readLong();
            ctx.value = new UUID(l1, l2);
            break;

        default:
            byte[] buf = new byte[size];
            _in.readFully(buf);
            ctx.value = buf;
            break;
        }

        return JsonToken.VALUE_EMBEDDED_OBJECT;
    }

import java.util.Random;
import java.util.Scanner;
public class Checker
{
    public static void main(String[] args)
    {
        Scanner scan = new Scanner(System.in);
        Random random = new Random();
        long from = 1;
        long to = 100;
        int randomNumber = random.nextInt(to - from + 1) + from;
        int guessedNumber = 0;
 
        System.out.printf("The number is between %d and %d.\n", from, to);
 
        do
        {
            System.out.print("Guess what the number is: ");
            guessedNumber = scan.nextInt();
            if (guessedNumber > randomNumber)
                System.out.println("Your guess is too high!");
            else if (guessedNumber < randomNumber)
                System.out.println("Your guess is too low!");
            else
                System.out.println("You got it!");
        } while (guessedNumber != randomNumber);
    }
}

