import java.util.*;

public class TokenManager {
    private Map<String, List<String>> data = new HashMap<>();

    public void addTokens(String metadata, StringTokenizer tokens) {
        if (metadata.equals("*")) {
            // Add tokens to all top level nodes
            for (List<String> tokenList : data.values()) {
                while (tokens.hasMoreTokens()) {
                    tokenList.add(tokens.nextToken());
                }
            }
        } else {
            // Add tokens to a specific object
            List<String> tokenList = data.get(metadata);
            if (tokenList == null) {
                tokenList = new ArrayList<>();
                data.put(metadata, tokenList);
            }
            while (tokens.hasMoreTokens()) {
                tokenList.add(tokens.nextToken());
            }
        }
    }
}

public class ExtremelyRound {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int t = sc.nextInt();
        while (t-- > 0) {
            int n = sc.nextInt();
            int count = 0;
            for (int i = 1; i <= n; i++) {
                if (isExtremelyRound(i)) {
                    count++;
                }
            }
            System.out.println(count);
        }
    }
    public static boolean isExtremelyRound(int n) {
        int count = 0;
        while (n > 0) {
            if (n % 10 != 0) {
                count++;
            }
            n /= 10;
        }
        return count == 1;
    }
}

public class BMI {
   private String name;
   private int age;
   private double weight; // in pounds
   private double height; // in inches
   private double feet; // in feet
   private double inches; // in inches

   public BMI(String name, int age, double weight, double height) {
      this.name = name;
      this.age = age;
      this.weight = weight;
      this.height = height;
   }

   public BMI(String name, int age, double weight, double feet, double inches) {
      this.name = name;
      this.age = age;
      this.weight = weight;
      this.feet = feet;
      this.inches = inches;
      this.height = (feet * 12) + inches;
   }

   public double getBMI() {
      double bmi = weight / Math.pow(height, 2) * 703;
      return Math.round(bmi * 100) / 100.0;
   }

   public String getStatus() {
      double bmi = getBMI();
      if (bmi < 18.5)
         return "Underweight";
      else if (bmi < 25)
         return "Normal";
      else if (bmi < 30)
         return "Overweight";
      else
         return "Obese";
   }

   public String getName() {
      return name;
   }

   public int getAge() {
      return age;
   }

   public double getWeight() {
      return weight;
   }

   public double getHeight() {
      return height;
   }

   public double getFeet() {
      return feet;
   }

   public double getInches() {
      return inches;
   }
}

