using namespace std;

class Cache {
public:
    int minOperations(vector<int> &nums, int x) {
        int target = accumulate(nums.begin(), nums.end(), 0) - x;
        if (target < 0) {
            return -1;
        }

        int left = 0, right = 0, sum = 0, maxLength = -1;
        while (right < nums.size()) {
            sum += nums[right];
            ++right;

            while (sum > target) {
                sum -= nums[left];
                ++left;
            }

            if (sum == target) {
                maxLength = max(maxLength, right - left);
            }
        }

        return maxLength == -1 ? -1 : nums.size() - maxLength;
    }
};

int main() {
    vector<int> nums{1, 1, 4, 2, 3};
    int x = 5;
    Cache s;
    cout << s.minOperations(nums, x) << endl;

    return 0;
