class Cache {
public:
    int removeDuplicates(vector<int> &nums) {
        if (nums.empty()) {
            return 0;
        }

        int i = 0, j = 1;
        while (j < nums.size()) {
            if (nums[i] != nums[j]) {
                nums[++i] = nums[j];
            }
            ++j;
        }

        return i + 1;
    }
};

int main() {
    vector<int> nums = {0, 0, 1, 1, 1, 2, 2, 3, 3, 4};
    Cache s;
    int result = s.removeDuplicates(nums);
    cout << result << endl;
    for (int i = 0; i < result; ++i) {
        cout << nums[i] << " ";
    }
    cout << endl;
