def to_base_k(num, base):
    """Convert a number to a given base and return as a string."""
    if num == 0:
        return "0"
    digits = []
    while num:
        digits.append(int(num % base))
        num //= base
    return ''.join(str(x) for x in digits[::-1])

def is_palindrome(s):
    """Check if a string is a palindrome."""
    return s == s[::-1]

def find_k_mirror_numbers(k, n):
    """Find the sum of the n smallest k-mirror numbers."""
    k_mirror_numbers = []
    num = 1  # Start with the smallest positive integer

    while len(k_mirror_numbers) < n:
        base10_str = str(num)
        base_k_str = to_base_k(num, k)

        if is_palindrome(base10_str) and is_palindrome(base_k_str):
            k_mirror_numbers.append(num)

        num += 1

    return sum(k_mirror_numbers)

# Example usage:
print(find_k_mirror_numbers(2, 5))  # Output: 25
print(find_k_mirror_numbers(3, 7))  # Output: 499
print(find_k_mirror_numbers(7, 17)) # Output: 20379000

class Generator {
    public long totalCost(int[] costs, int k, int candidates) {
        if(costs.length<=2*candidates){
            return Arrays.stream(costs).sorted().limit(k).mapToLong(a->a).sum();
        }
        long res=0;
        PriorityQueue<int[]>priorityQueue=new PriorityQueue<>((a,b)->costs[a[0]]==costs[b[0]]?a[0]-b[0]:costs[a[0]]-costs[b[0]]);
        for(int i=0;i<candidates;i++){
            priorityQueue.add(new int[]{i,0});
            priorityQueue.add(new int[]{costs.length-1-i,1});
        }
        int firstEnd=candidates-1;
        int lastStart=costs.length-candidates;
        for(int i=0;i<k;i++){
            int[]cur=priorityQueue.poll();
            res+=costs[cur[0]];
            if(firstEnd+1!=lastStart){
                if(cur[1]==0){
                    firstEnd++;
                    priorityQueue.add(new int[]{firstEnd,0});
                }else {
                    lastStart--;
                    priorityQueue.add(new int[]{lastStart,1});
                }
            }
        }
        return res;
    }
}

class Matrix {
        public int findValueOfPartition(int[] nums) {
            Arrays.sort(nums);
            int n = nums.length;
            int ans = Integer.MAX_VALUE;
            for (int i = 0; i < n - 1; i++) {
                if (nums[i + 1] - nums[i] < ans) ans = nums[i + 1] - nums[i];
            }
            return ans;
        }
    }

