public static Document buildPDFDocument (com.snowtide.pdf.Document pdf, LucenePDFConfiguration config) throws IOException {
    Document luceneDoc = new Document();
    // Add text content to the Lucene document
    luceneDoc.add(new TextField(config.getTextFieldName(), pdf.getText(), Field.Store.YES));
    // Add metadata fields to the Lucene document
    for (Map.Entry<String, String> entry : pdf.getMetadata().entrySet()) {
        luceneDoc.add(new StringField(entry.getKey(), entry.getValue(), Field.Store.YES));
    }
    return luceneDoc;
}

private CompiledPlan getNextUnionPlan() {
    // Check if there are any more plans to process
    if (this.plans.isEmpty()) {
        return null;
    }

    // Initialize a list to hold the compiled plans for each individual statement in the UNION
    List<CompiledPlan> compiledPlans = new List<>();

    // Iterate over each plan in the list of plans
    for (Plan plan : this.plans) {
        // Generate the best plan for the current statement
        CompiledPlan compiledPlan = this.getBestPlan(plan);
        // Add the compiled plan to the list of compiled plans
        compiledPlans.add(compiledPlan);
    }

    // Create a union plan from the compiled plans
    UnionPlan unionPlan = new UnionPlan(compiledPlans);

    // Return the union plan
    return unionPlan;
}

