import static java.lang.Math.*;

import java.awt.Point;

import java.io.*;

import java.util.*;

public class Main {

    static StringTokenizer st;

    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));

    public static void solve() throws Exception{

        st = new StringTokenizer(in.readLine());

        int n = nextInt(); int k = nextInt();

        st = new StringTokenizer(in.readLine());

        String letters = st.nextToken();

        int total = 0;

        for(int i = 0; i < ceil(k/2.0); i++) {

            int f = i; int l = n - 1 - i;

            List<Character> diff = new ArrayList<>();

            boolean[] visited = new boolean[n]; char[] nlet = new char[26]; int mx = 0;

            for(int b = 1; b <= n/k; b++) {

                if(!visited[f]) {

                    diff.add(letters.charAt(f)); nlet[letters.charAt(f) - 'a']++;

                    mx = max(nlet[letters.charAt(f) - 'a'], mx); visited[f] = true;

                }

                if(!visited[l]) {

                    diff.add(letters.charAt(l)); nlet[letters.charAt(l) - 'a']++;

                    mx = max(nlet[letters.charAt(l) - 'a'], mx); visited[l] = true;

                }

                f += k; l -= k;

            }

            total += diff.size() - mx;

        }

        System.out.println(total);

    }

    public static int nextInt() {

         return Integer.parseInt(st.nextToken());

    }

    public static void main(String args[]) throws Exception {

        st = new StringTokenizer(in.readLine());

        int testcases = nextInt();

        while(testcases-- != 0) solve();

    }

}

