import java.util.HashMap;
import java.util.Map;
 
public class Oldrus {
 
    public static void main(String[] args) {
        Map<String, Float> units = new HashMap<String, Float>();
        units.put("arshin", 0.7112f);
        units.put("centimeter", 0.01f);
        units.put("diuym", 0.0254f);
        units.put("fut", 0.3048f);
        units.put("kilometer", 1000.0f);
        units.put("liniya", 0.00254f);
        units.put("meter", 1.0f);
        units.put("milia", 7467.6f);
        units.put("piad", 0.1778f);
        units.put("sazhen", 2.1336f);
        units.put("tochka", 0.000254f);
        units.put("vershok", 0.04445f);
        units.put("versta", 1066.8f);
 
        if (args.length < 2) {
            System.err.println("A correct use is oldrus [amount] [unit].");
            System.exit(1);
        }
 
        float length_float;
        try {
            length_float = Float.parseFloat(args[0]);
        } catch (NumberFormatException e) {
            length_float = 1;
        }
 
        String unit = args[1];
        if (!units.containsKey(unit)) {
            String keys = "";
            for (String i : units.keySet()) {
                keys += i + ", ";
            }
            System.err.println("The correct units are: " + keys);
            System.exit(1);
        }
 
        System.out.println(length_float + " " + unit + " to:");
        for (String lunit : units.keySet()) {
            System.out.println("\t" + lunit + ": " + length_float * units.get(unit) / units.get(lunit));
        }
    }
}

public void ejbCreate() {
    try {
        // Lookup the OJB ODMG implementation from JNDI
        Context ctx = new InitialContext();
        Implementation impl = (Implementation) ctx.lookup("java:comp/env/ojb/odmg");
        // Open the database
        Database db = impl.newDatabase();
        db.open(Database.OPEN_READ_WRITE);
        // Set the database for the current transaction
        Transaction tx = impl.newTransaction();
        tx.begin();
        // Perform database operations here
        // Commit the transaction
        tx.commit();
    } catch (NamingException e) {
        e.printStackTrace();
    } catch (DatabaseException e) {
        e.printStackTrace();
    }
}

public class Generator {
    public static void main(String[] args) {
        for (int i = 0; i < 200; i++) {

            if (i % 10 == 0 && i > 0) {
                System.out.println();
            }
            if (i < 100) {
                System.out.print(getRandomUpperCaseLetter());
                System.out.print(" ");
            } else {
                System.out.print(getRandomDigitCharacter());
                System.out.print(" ");
            }
        }
    }

    public static char getRandomCharacter(char ch1, char ch2) {
        return (char) (ch1 + Math.random() * (ch2 - ch1 + 1));
    }

    public static char getRandomLowerCaseLetter() {
        return getRandomCharacter('a', 'z');
    }

    public static char getRandomUpperCaseLetter() {
        return getRandomCharacter('A', 'Z');
    }

    public static char getRandomDigitCharacter() {
        return getRandomCharacter('0', '9');
    }

    public static char getRandomCharacter() {
        return getRandomCharacter('\u0000', '\uFFFF');
    }
}

import java.util.*;

public class Service {
    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);
        System.out.print("\nEnter weight(Integer) and price(Float) for package 1: ");
        int weightP1 = in.nextInt();
        double p1 = in.nextDouble();
        System.out.print("\nEnter weight and price for package 2: ");
        int weightP2 = in.nextInt();
        double p2 = in.nextDouble();
        int low = 0, high = 0, lcm = 0;

        String betterPrice = "";
        if (weightP1 <= 0 || weightP2 <= 0) {
            System.out.println("Weight must be a positive number. ");
        } else if (p1 <= 0 || p2 <= 0) {
            System.out.println("Price must be a positive number. ");

        } else { // Find greater number
            if (weightP1 > weightP2) {
                low = weightP2;
                high = weightP1;
            } else if (weightP1 < weightP2) {
                low = weightP1;
                high = weightP2;
            } else { //Weights are equal, return lowest price.
                betterPrice += (p1 < p2 ? "1" : "2");
                System.out.println("Package " + betterPrice + " has a better price.");
                System.exit(0);
            }
            lcm = high; // Start lcm with higher number as multiple
            //Calculate LCM
            while (lcm % low != 0) {
                lcm += high;
            }
            int adjustP1 = lcm / weightP1; //Divide by LCM to get multiple
            int adjustP2 = lcm / weightP2;

            double adjustedPrice1 = p1 * adjustP1; //Use multiple to adjust the price for weight difference
            double adjustedPrice2 = p2 * adjustP2;

            betterPrice += adjustedPrice1 < adjustedPrice2 ? "1" : "2";
        }

        System.out.println("Package " + betterPrice + " has a better price.");
    }
}

//  Title:  Determine if a string is squeezable
 
public class StringSqueezable {
 
    public static void main(String[] args) {
        String[] testStrings = new String[] {
                "",
                "\"If I were two-faced, would I be wearing this one?\" --- Abraham Lincoln ",
                "..1111111111111111111111111111111111111111111111111111111111111117777888",
                "I never give 'em hell, I just tell the truth, and they think it's hell. ",
                "                                                    --- Harry S Truman  ",
                "122333444455555666666777777788888888999999999",
                "The better the 4-wheel drive, the further you'll be from help when ya get stuck!",
                "headmistressship"};
 
        String[] testChar = new String[] {
                " ",
                "-",
                "7",
                ".",
                " -r",
                "5",
                "e",
                "s"};
        for ( int testNum = 0 ; testNum < testStrings.length ; testNum++ ) {
            String s = testStrings[testNum];
            for ( char c : testChar[testNum].toCharArray() ) {
                String result = squeeze(s, c);
                System.out.printf("use: '%c'%nold:  %2d <<<%s>>>%nnew:  %2d <<<%s>>>%n%n", c, s.length(), s, result.length(), result);
            }
        }
    }
 
    private static String squeeze(String in, char include) {
        StringBuilder sb = new StringBuilder();
        for ( int i = 0 ; i < in.length() ; i++ ) {
            if ( i == 0 || in.charAt(i-1) != in.charAt(i) || (in.charAt(i-1) == in.charAt(i) && in.charAt(i) != include)) {
                sb.append(in.charAt(i));
            }
        }
        return sb.toString();
    }
 
}

class Utils {

    public String largestMerge(String word1, String word2) {

        StringBuilder sbd1 = new StringBuilder(word1);
        StringBuilder sbd2 = new StringBuilder(word2);

        StringBuilder res = new StringBuilder();

        while (sbd1.length() != 0 && sbd2.length() != 0) {

            char a = sbd1.charAt(0);
            char b = sbd2.charAt(0);

            if (a > b || (a == b && sbd1.compareTo(sbd2) > 0)) {
                res.append(sbd1.charAt(0));
                sbd1.deleteCharAt(0);
            } else if (a < b || (a == b && sbd1.compareTo(sbd2) <= 0)) {
                res.append(sbd2.charAt(0));
                sbd2.deleteCharAt(0);
            }

        }

        if (sbd1.length() != 0) {
            res.append(sbd1);
        }

        if(sbd2.length() != 0) {
            res.append(sbd2);
        }

        return res.toString();
    }

}

