import com.google.zxing.BarcodeFormat;
import com.google.zxing.BinaryBitmap;
import com.google.zxing.DecodeHintType;
import com.google.zxing.Result;
import com.google.zxing.ResultMetadataType;
import com.google.zxing.ResultPoint;
import com.google.zxing.FormatException;
import com.google.zxing.NotFoundException;
import com.google.zxing.ChecksumException;
import com.google.zxing.common.BitArray;
import com.google.zxing.oned.UPCEANReader;
import com.google.zxing.oned.EAN13Reader;
import java.util.Map;

public final class UPCAReader extends UPCEANReader {
    private final EAN13Reader ean13Reader = new EAN13Reader();

    @Override
    public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType, ?> hints)
            throws NotFoundException, ChecksumException, FormatException {
        Result result = ean13Reader.decodeRow(rowNumber, row, hints);
        return maybeReturnResult(result);
    }

    @Override
    public Result decode(BinaryBitmap image, Map<DecodeHintType, ?> hints)
            throws NotFoundException, ChecksumException, FormatException {
        Result result = ean13Reader.decode(image, hints);
        return maybeReturnResult(result);
    }

    @Override
    public BarcodeFormat getBarcodeFormat() {
        return BarcodeFormat.UPC_A;
    }

    @Override
    public void reset() {
        ean13Reader.reset();
    }

    private static Result maybeReturnResult(Result result) throws FormatException {
        String text = result.getText();
        if (text == null || text.length() < 12 || text.charAt(0) != '0') {
            throw FormatException.getFormatInstance();
        }

        String upcaText = text.substring(1);
        ResultPoint[] points = result.getResultPoints();
        Result upcaResult = new Result(
                upcaText,
                null,
                new ResultPoint[]{points[0], points[1]},
                BarcodeFormat.UPC_A);

        Map<ResultMetadataType, Object> metadata = result.getResultMetadata();
        if (metadata != null) {
            upcaResult.putAllMetadata(metadata);
        }
        return upcaResult;
    }

    @Override
    protected int decodeMiddle(BitArray row, int[] startRange, StringBuilder result)
            throws NotFoundException {
        return ean13Reader.decodeMiddle(row, startRange, result);
    }
}

import org.springframework.http.*;
import org.springframework.validation.*;
import org.springframework.web.bind.*;
import org.springframework.web.bind.annotation.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.dao.DataIntegrityViolationException;
import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorDTO> processValidationError(MethodArgumentNotValidException ex) {
        BindingResult result = ex.getBindingResult();
        ErrorDTO dto = new ErrorDTO();
        dto.timestamp = Instant.now();
        dto.error = ErrorConstants.ERR_VALIDATION;
        dto.message = "Validation error";
        dto.fieldErrors = processFieldErrors(result.getFieldErrors());
        return new ResponseEntity<>(dto, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorDTO> processAccessDeniedException() {
        ErrorDTO dto = new ErrorDTO();
        dto.timestamp = Instant.now();
        dto.error = ErrorConstants.ERR_ACCESS_DENIED;
        dto.message = "Access denied";
        return new ResponseEntity<>(dto, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(DataIntegrityViolationException.class)
    public ResponseEntity<ErrorDTO> processConcurrencyError() {
        ErrorDTO dto = new ErrorDTO();
        dto.timestamp = Instant.now();
        dto.error = ErrorConstants.ERR_CONCURRENCY_FAILURE;
        dto.message = "Concurrency conflict";
        return new ResponseEntity<>(dto, HttpStatus.CONFLICT);
    }

    @ExceptionHandler(CustomParameterizedException.class)
    public ResponseEntity<ParameterizedErrorDTO> processParameterizedValidationError(CustomParameterizedException ex) {
        ParameterizedErrorDTO dto = new ParameterizedErrorDTO();
        dto.timestamp = Instant.now();
        dto.error = ErrorConstants.ERR_PARAMETERIZED;
        dto.message = ex.getMessage();
        dto.params = ex.getParams();
        return new ResponseEntity<>(dto, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
    public ResponseEntity<ErrorDTO> processMethodNotSupportedException() {
        ErrorDTO dto = new ErrorDTO();
        dto.timestamp = Instant.now();
        dto.error = ErrorConstants.ERR_METHOD_NOT_SUPPORTED;
        dto.message = "HTTP method not supported";
        return new ResponseEntity<>(dto, HttpStatus.METHOD_NOT_ALLOWED);

import java.util.*;

public class Training1 {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int t=sc.nextInt();

        for (int k = 0; k < t; k++) {

            long x=sc.nextLong();

            long n=sc.nextLong();

            long res=0;

            if (x%2==0) {

                if ((n-2)%4==0) {

                    res=x+1;

                }else if((n-2)%4==1){

                    res=x+1+n;

                }else if((n-2)%4==2){

                    res=x+0;

                }else {

                    res=x+0-n;

                }

            }else{

                if ((n-2)%4==0) {

                    res=x-1;

                }else if((n-2)%4==1){

                    res=x-1-n;

                }else if((n-2)%4==2){

                    res=x+0;

                }else {

                    res=x+0+n;

                }

            }

            System.out.println(res);

        }

    }

}

import static com.google.common.base.Charsets.UTF_8;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.net.MalformedURLException;
import java.net.URLConnection;

import javax.annotation.Nonnull;

import com.google.common.base.Function;
import org.apache.jackrabbit.oak.segment.RecordId;
import org.apache.jackrabbit.oak.segment.Revisions;

public class HttpStoreRevisions implements Revisions {

    @Nonnull
    private final HttpStore store;

    public HttpStoreRevisions(@Nonnull HttpStore store) {
        this.store = store;
    }

    @Nonnull
    @Override
    public RecordId getHead() {
        try {
            URLConnection connection = store.get(null);
            try (
                InputStream stream = connection.getInputStream();
                BufferedReader reader = new BufferedReader(new InputStreamReader(stream, UTF_8))
            ) {
                return RecordId.fromString(store, reader.readLine());
            }
        } catch (IllegalArgumentException | MalformedURLException e) {
            throw new IllegalStateException(e);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    @Override
    public boolean setHead(
            @Nonnull RecordId base, @Nonnull RecordId head,
            @Nonnull Option... options) {
        throw new UnsupportedOperationException();
    }

    @Override
    public boolean setHead(
            @Nonnull Function<RecordId, RecordId> newHead,
            @Nonnull Option... options) throws InterruptedException {
        throw new UnsupportedOperationException();
    }
}

 
public class CumStdDev {
    private int n = 0;
    private double sum = 0.0;
    private double sum2 = 0.0;
 
    public double sd(double x) {
        n++;
        sum += x;
        sum2 += x * x;
        return Math.sqrt(sum2 / n - sum * sum / n / n);
    }
}
 
public class Validator {
    public static void main(String[] args) {
        double[] testData = new double[]{2.0, 4.0, 4.0, 4.0, 5.0, 5.0, 7.0, 9.0};
        CumStdDev csd = new CumStdDev();
        for (double d : testData) System.out.println("Add " + d + " => " + csd.sd(d));
    }
}

