public final class Digests {
    public static final String SHA1 = "SHA-1";
    public static final String MD5 = "MD5";
    private static final SecureRandom random = new SecureRandom();

    private Digests() {
        throw new AssertionError("Cannot instantiate utility class");
    }

    public static byte[] generateSalt(int length) {
        Validate.isTrue(length > 0, "Salt length must be positive");
        byte[] salt = new byte[length];
        random.nextBytes(salt);
        return salt;
    }

    public static byte[] sha1(byte[] data) {
        return digest(SHA1, data, null, 1);
    }

    public static byte[] sha1(byte[] data, byte[] salt, int iterations) {
        return digest(SHA1, data, salt, iterations);
    }

    public static byte[] sha1(InputStream input) {
        return digest(SHA1, input, null, 1);
    }

    public static byte[] sha1(InputStream input, byte[] salt, int iterations) {
        return digest(SHA1, input, salt, iterations);
    }

    public static byte[] md5(byte[] data) {
        return digest(MD5, data, null, 1);
    }

    public static byte[] md5(byte[] data, byte[] salt, int iterations) {
        return digest(MD5, data, salt, iterations);
    }

    public static byte[] md5(InputStream input) {
        return digest(MD5, input, null, 1);
    }

    public static byte[] md5(InputStream input, byte[] salt, int iterations) {
        return digest(MD5, input, salt, iterations);
    }

    private static byte[] digest(String algorithm, byte[] data, byte[] salt, int iterations) {
        Validate.notNull(data, "Data must not be null");
        Validate.isTrue(iterations > 0, "Iterations must be positive");

        try {
            MessageDigest md = MessageDigest.getInstance(algorithm);
            if (salt != null) {
                byte[] combined = new byte[data.length + salt.length];
                System.arraycopy(data, 0, combined, 0, data.length);
                System.arraycopy(salt, 0, combined, data.length, salt.length);
                data = combined;
            }

            byte[] hash = data;
            for (int i = 0; i < iterations; i++) {
                hash = md.digest(hash);
            }
            return hash;
        } catch (NoSuchAlgorithmException e) {
            throw Exceptions.unchecked(e);
        }
    }

