/**
 * Broadcast-style chat server. Every connected client gets a unique
 * screen name and every message a client sends is relayed to everyone.
 */
public class ChatServer {

    private static final int PORT = 59001;
    private static final int POOL_SIZE = 500;

    // Names currently taken, guards against duplicates
    private static final Set<String> takenNames = new HashSet<>();

    // Output streams for every connected client, used to broadcast
    private static final Set<PrintWriter> subscribers = new HashSet<>();

    public static void main(String[] args) throws Exception {
        System.out.println("Chat server calisiyor...");
        var workers = Executors.newFixedThreadPool(POOL_SIZE);

        try (var serverSocket = new ServerSocket(PORT)) {
            System.out.println(serverSocket.getInetAddress().toString());
            while (true) {
                workers.execute(new ClientSession(serverSocket.accept()));
            }
        }
    }

    // One instance per connected client; owns the negotiation and relay loop
    private static class ClientSession implements Runnable {
        private String screenName;
        private final Socket socket;
        private PrintWriter out;

        ClientSession(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try (var in = new Scanner(socket.getInputStream())) {
                out = new PrintWriter(socket.getOutputStream(), true);

                negotiateName(in);

                out.println("NAMEACCEPTED " + screenName);
                announce(screenName + " katildi");
                subscribers.add(out);

                relayMessages(in);
            } catch (Exception e) {
                System.out.println(e);
            } finally {
                cleanup();
            }
        }

        // Keeps asking for a name until it gets a unique, non-blank one
        private void negotiateName(Scanner in) {
            while (true) {
                out.println("SUBMITNAME");
                screenName = in.nextLine();
                if (screenName == null) {
                    return;
                }
                synchronized (takenNames) {
                    if (!screenName.isBlank() && !takenNames.contains(screenName)) {
                        takenNames.add(screenName);

private <T> BindingImpl<T> createImplementedByBinding(
      Key<T> key, Scoping scoping, ImplementedBy implementedBy, Errors errors)
      throws ErrorsException {
    Class<?> rawType = key.getTypeLiteral().getRawType();
    Class<?> implementationType = implementedBy.value();

    if (implementationType == rawType) {
      throw errors.recursiveImplementationType().toException();
    }

    if (!rawType.isAssignableFrom(implementationType)) {
      throw errors.notASubtype(implementationType, rawType).toException();
    }
    @SuppressWarnings("unchecked")
    Class<? extends T> subclass = (Class<? extends T>) implementationType;

    final Key<? extends T> targetKey = Key.get(subclass);
    Object source = rawType;
    FactoryProxy<T> factory = new FactoryProxy<>(this, key, targetKey, source);
    factory.notify(errors);
    return new LinkedBindingImpl<T>(
        this,
        key,
        source,
        Scoping.<T>scope(key, this, factory, source, scoping),
        scoping,
        targetKey);
  }

import java.util.Arrays;

public class Program {
    public int countWays(int[] nums) {
        int n = nums.length;
        Arrays.sort(nums);

        int ways = 0;

        // Check if selecting 0 students makes everyone happy
        if (nums[0] > 0) {
            ways++;
        }

        // Check for each possible number of selected students
        for (int i = 0; i < n; i++) {
            if (i + 1 > nums[i] && (i + 1 < n ? i + 1 < nums[i + 1] : true)) {
                ways++;
            }
        }

        // Check if selecting all students makes everyone happy
        if (n > nums[n - 1]) {
            ways++;
        }

        return ways;
    }
}

class Task {
    public int[] sortArrayByParityII(int[] A) {
        int oddIdx = 1;
        int evenIdx = 0;
        while (oddIdx < A.length) {
            while (oddIdx < A.length && A[oddIdx] % 2 == 1) {
                oddIdx+=2;
            }
            if (oddIdx >= A.length) {
                return A;
            }
            while (evenIdx < A.length && A[evenIdx] % 2 == 0) {
                evenIdx+=2;
            }
            if (evenIdx >= A.length) {
                // something is wrong here, just return
                return A;
            }
            int tmp = A[oddIdx];
            A[oddIdx] = A[evenIdx];
            A[evenIdx] = tmp;
            oddIdx += 2;
            evenIdx += 2;
        }
        return A;
    }
}

