public static void addItemToList(final Object target, final String fieldName, final Object value) {
    try {
        Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        List<?> list = (List<?>) field.get(target);
        list.add(value);
    } catch (NoSuchFieldException | IllegalAccessException e) {
        e.printStackTrace();
    }
}

class Cache {
    public int countOrders(int n) {
        long[] fn = new long[n];
        fn[0] = 1;
        for (int idx=1;idx<n;idx++) {
            long size = (2 * idx) + 1;
            fn[idx] = (((size * (size + 1) / 2) % 1000000007) * fn[idx -1]) % (1000000007);
        }
        return (int)fn[n-1];
    }
}

import java.time.Duration;

/**
 * Define the Circuit Breaker policy
 */
public interface CircuitBreakerPolicy {

    /**
     * Define the failure criteria
     *
     * @return the failure exception
     */
    public Class<? extends Throwable>[] getFailOn();

    @SuppressWarnings("unchecked")
    public void setFailOn(Class<? extends Throwable>... failOn);

    /**
     * Define the skip criteria
     *
     * @return the skip exception
     */
    Class<? extends Throwable>[] getSkipOn();

    @SuppressWarnings("unchecked")
    public void setSkipOn(Class<? extends Throwable>... skipOn);

    /**
     *
     * @return The delay time after the circuit is open
     */
    public Duration getDelay();

    public void setDelay(Duration delay);

    /**
     * The number of consecutive requests in a rolling window
     * that will trip the circuit.
     *
     * @return the number of the consecutive requests in a rolling window
     *
     */
    public int getRequestVolumeThreshold();

    public void setRequestVolumeThreshold(int threshold);

    /**
     * The failure threshold to trigger the circuit to open.
     * e.g. if the requestVolumeThreshold is 20 and failureRation is .50,
     * more than 10 failures in 20 consecutive requests will trigger
     * the circuit to open.
     *
     * @return The failure threshold to open the circuit
     */
    public double getFailureRatio();

    public void setFailureRatio(double ratio);

    /**
     * For an open circuit, after the delay period is reached, once the successThreshold
     * is reached, the circuit is back to close again.
     *
     * @return The success threshold to fully close the circuit
     */
    public int getSuccessThreshold();

    public void setSuccessThreshold(int threshold);

}

public void addTreeAsElement(Tree tree) {
    if (tree == null) {
        throw new IllegalArgumentException("Tree cannot be null");
    }
    int maxPriority = Integer.MIN_VALUE;
    for (Node node: tree.getAllNodes()) {
        if (node.getPriority() > maxPriority) {
            maxPriority = node.getPriority();
        }
        this.addNode(node);
    }
    this.setMaxPriority(maxPriority);
}

public Object lookupName(String name) {
        final Node childNode = getNode().getChild(name);
        if (childNode == null) {
            return null;
        } else {
            return childNode.get(CACHE_NODE_MAP_KEY);
        }
    }

public class SecmeliSiralama {

    public static void main(String[] args) {
        // Ornek bir dizi olustur
        int[] dizi = {5, 7, 10, 13, 12, 9, 9, 21, 22, 11, 17, 6, 5, 2, 44, 3, 14};

        // Secmeli siralama uygula
        secimSiralama(dizi);

        // Siralanmis diziyi ekrana yazdir
        System.out.println("Siralanmis Dizi:");
        for (int i = 0; i < dizi.length; i++) {
            System.out.print(dizi[i] + " ");
        }
    }

    public static void secimSiralama(int[] dizi) {

        // Her eleman icin uygun yeri bul
        for (int i = 0; i < dizi.length - 1; i++) {
            int minIndis = i;

            // Kalan elemanlar arasinda minimumu bul
            for (int j = i + 1; j < dizi.length; j++) {
                if (dizi[j] < dizi[minIndis]) {
                    minIndis = j;
                }
            }

            // Minimum elemani yer degistir
            int gecici = dizi[minIndis];
            dizi[minIndis] = dizi[i];
            dizi[i] = gecici;
        }
    }
}

