import java.util.Arrays;
import java.util.Map;
import java.util.TreeMap;

class Order {
    public int sumOfFlooredPairs(int[] nums) {
        TreeMap<Integer, Integer> map = new TreeMap<>();
        for (int n: nums) {
            map.put(n, map.getOrDefault(n,0) + 1);
        }
        int [] val = new int[map.size()];
        int [] sums = new int[map.size() + 1];
        int sum = 0;
        int idx = 0;
        for (Map.Entry<Integer, Integer> e: map.entrySet()) {
            val[idx] = e.getKey();
            sum += e.getValue();
            sums[++idx] = sum;
        }
        int ans = 0;
        for (int i = 0; i < val.length; i++) {
            long cnt = (sums[i+1] - sums[i]);
            ans =(int)( (ans + cnt * cnt) % 1000000007);
            idx = i + 1;
            for (int j = 2; ; j ++) {
                int next = Arrays.binarySearch(val, j * val[i]);
                // System.out.println(next);
                if (next < 0){
                    next = - next - 1;
                }
                // System.out.println(idx + "," + next + ">"+ j);
                // System.out.println(sums[next-1] - sums[idx]);
                ans = (int)((ans + (sums[next] - sums[idx]) * (j-1) * cnt) % 1000000007);
                if (next >= val.length){
                    break;
                }
                idx = next;
            }
        }
        return ans;
    }
}

import java.io.File;
