public class Student {
    public static <T extends Serializable> T deepCopy(T obj) {
        if (obj == null) return null;
        try {
            ByteArrayOutputStream baos = new ByteArrayOutputStream();
            ObjectOutputStream oos = new ObjectOutputStream(baos);
            oos.writeObject(obj);
            oos.close();
            ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
            ObjectInputStream ois = new ObjectInputStream(bais);
            @SuppressWarnings("unchecked")
            T result = (T) ois.readObject();
            return result;
        }
        catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
 
    public static void printDetails(Person p1, Person p2, Person p3, Person p4) {
        System.out.println("Name    : " + p3.name);
        System.out.println("Age     : " + p3.age);
        System.out.println("Sex     : " + p3.sex);
        System.out.println("Income  : " + p3.income);
        if (p4 == null) {
            System.out.println("Partner : None");
        }
        else {
            System.out.println("Partner :-");
            System.out.println("  Name   : " + p4.name);
            System.out.println("  Age    : " + p4.age);
            System.out.println("  Sex    : " + p4.sex);
            System.out.println("  Income : " + p4.income);
        }
        System.out.println("\nSame person as original '" + p1.name + "' == " + (p1 == p3));
        if (p4!= null) {
            System.out.println("Same person as original '" + p2.name + "' == " + (p2 == p4));
        }
        System.out.println();
    }
 
    public static void main(String[] args) {
        Person p1 = new Person("John", 35, 'M', 50000.0, null);
        Person p2 = new Person("Jane", 32, 'F', 25000.0, p1);
        p1.partner = p2;
        Person p3 = deepCopy(p1);
        Person p4 = p3.partner;
        printDetails(p1, p2, p3, p4);
 
        System.out.println("..or, say, after 2 years have elapsed:-\n");

import java.awt.Color;
import java.awt.Graphics;
import java.awt.Image;
import java.awt.image.BufferedImage;
 
public class BasicBitmapStorage {
 
    private final BufferedImage image;
 
    public BasicBitmapStorage(int width, int height) {
        image = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
    }
 
    public void fill(Color c) {
        Graphics g = image.getGraphics();
        g.setColor(c);
        g.fillRect(0, 0, image.getWidth(), image.getHeight());
    }
 
    public void setPixel(int x, int y, Color c) {
        image.setRGB(x, y, c.getRGB());
    }
 
    public Color getPixel(int x, int y) {
        return new Color(image.getRGB(x, y));
    }
 
    public Image getImage() {
        return image;
    }
}

class Student {
    public boolean sumOfNumberAndReverse(int num) {
        for (int i = 0; i <= num; i++) {
            int x0 = i, x = i, y = 0;
            while (x > 0) {
                y = y * 10 + x % 10;
                x /= 10;
            }
            if (x0 + y == num)
                return true;
        }
        return false;
    }
}

