import org.jboss.aesh.edit.actions.Action;
import org.jboss.aesh.terminal.Key;

import java.util.Arrays;
import java.util.Objects;

public class KeyOperation {
    private final Key key;
    private final Operation operation;
    private final Action workingMode;

    public KeyOperation(Key key, Operation operation) {
        this(key, operation, null);
    }

    public KeyOperation(Key key, Operation operation, Action workingMode) {
        this.key = Objects.requireNonNull(key, "Key cannot be null");
        this.operation = Objects.requireNonNull(operation, "Operation cannot be null");
        this.workingMode = workingMode;
    }

    public Key getKey() {
        return key;
    }

    public int[] getKeyValues() {
        return key.getValues();
    }

    public int getFirstValue() {
        int[] values = key.getValues();
        return values.length > 0 ? values[0] : -1;
    }

    public Operation getOperation() {
        return operation;
    }

    public Action getWorkingMode() {
        return workingMode;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        KeyOperation that = (KeyOperation) o;
        return Objects.equals(key, that.key) &&
               Objects.equals(operation, that.operation) &&
               Objects.equals(workingMode, that.workingMode);
    }

    @Override
    public int hashCode() {
        return Objects.hash(key, operation, workingMode);
    }

    @Override
    public String toString() {
        return "KeyOperation{" +
               "key=" + Arrays.toString(key.getValues()) +
               ", operation=" + operation +
               ", workingMode=" + workingMode +
               '}';
    }
}

