    public void raisesToPower() {
        assertEquals(8, math.power(2, 3), 0.001);

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;
 
public class Calculator {
 
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        String input;
        String delimiters = "#;";
        while ((input = br.readLine())!= null &&!input.isEmpty()) {
            System.out.println(strip_comments(input, delimiters));
        }
    }
 
    public static String strip_white(String input) {
        int b = input.indexOf(' ');
        if (b == -1) {
            b = 0;
        }
        return input.substring(b, input.lastIndexOf(' ') + 1 - b);
    }
 
    public static String strip_comments(String input, String delimiters) {
        return strip_white(input.substring(0, input.indexOf(delimiters)));
    }
}

/**
 * Adds the product of this random variable and a given factor to another random variable.
 *
 * @param factor The factor.
 * @param value The value to be accrued to the other random variable.
 * @return The new random variable.
 */
@Override
public RandomVariableInterface accrue(final RandomVariableInterface factor, final double value) {
    if(factor == null) {
        return this;
    }

    final double factorAverage = factor.getAverage();
    final double factorSquaredAverage = factor.getSquaredAverage();
    final double covariance = this.getCovarianceWith(factor);

    final double newAverage = this.getAverage() * factorAverage + value;
    final double newVariance = factorSquaredAverage * this.getVariance() + this.getSquaredAverage() * factor.getVariance() + 2 * covariance * value;
    final double newNumeraire = this.numeraire.mult(factor.numeraire).getAverage();

    return new RandomVariable(newAverage, newVariance, newNumeraire);
}

class Product {
    public boolean isSumEqual(String firstWord, String secondWord, String targetWord) {
        return helper(firstWord) + helper(secondWord) == helper(targetWord);
    }

    static int helper(String s) {
        int v = 0;
        for(char ch : s.toCharArray()) {
            int i = ch - 'a';
            v = v * 10 + i;
        }
        return v;
    }
}

