#include<bits/stdc++.h>

using namespace std;

#define MAXN 10010
int n, a[MAXN], b[MAXN], s1[MAXN], e[MAXN];

void check()
{
    int x;
    for(int i = 1; i < n; i++)
    {
        s1[i] = s1[i - 1] + a[i];
        e[i] = s1[n - 1] - s1[i];
    }

    if(!(b[0] = s1[n - 1] % e[n - 1] && b[0] == e[0] && b[0] == a[1]))
    {
        cout << -1;
        return;
    }

    int i, operation = 0;
    for(i = 1; i < n; i++)
    {
        int k = e[i] / b[0];
        while(i + k <= n && s1[i + k] - s1[i] != k * b[0])
            k--;

        if(k == 0)
        {
            cout << operation << endl;
            cout << i << " " << i + k << " " << b[0] << endl;
            operation++;
        }
    }
}

int main()
{
    int t;
    cin >> t;

    while(t--)
    {
        cin >> n;
        for(int i = 1; i <= n; i++)
            cin >> a[i];

        check();
    }
    return 0;
}

