public class Handler {
    public static void main(String[] args) {
        var data = GetData();
        var result = ExecuteHashJoin(data);
        WriteResultToConsole(result);
    }
 
    private static void WriteResultToConsole(List<AgeNameNemesis> result) {
        result.forEach(ageNameNemesis -> System.out.println(String.format("Age: %s, Name: %s, Nemesis: %s",
                ageNameNemesis.Age, ageNameNemesis.Name, ageNameNemesis.Nemesis)));
    }
 
    private static List<AgeNameNemesis> ExecuteHashJoin(DataContext data) {
        return data.AgeName.stream()
               .map(ageName -> new AgeNameNemesis(ageName.Age, ageName.Name, data.NameNemesis.stream()
                       .filter(nameNemesis -> nameNemesis.Name.equals(ageName.Name))
                       .map(nameNemesis -> nameNemesis.Nemesis)
                       .collect(Collectors.joining(", "))))
               .collect(Collectors.toList());
    }
 
    private static DataContext GetData() {
        var context = new DataContext();
 
        context.AgeName.addAll(new ArrayList<AgeName>() {{
            add(new AgeName((byte) 27, "Jonah"));
            add(new AgeName((byte) 18, "Alan"));
            add(new AgeName((byte) 28, "Glory"));
