            add(new AgeName((byte) 28, "Alan"));
        }});
 
        context.NameNemesis.addAll(new ArrayList<NameNemesis>() {{
            add(new NameNemesis("Jonah", "Whales"));
            add(new NameNemesis("Jonah", "Spiders"));
            add(new NameNemesis("Alan", "Ghosts"));
            add(new NameNemesis("Alan", "Zombies"));

