public class PdfView extends AbstractITextPdfView {

    @Override
    protected void buildPdfDocument(Map<String, Object> model, Document document, PdfWriter writer,
                                    HttpServletRequest request, HttpServletResponse response) throws Exception {
        Face face = (Face) model.get("face");
        Rectangle pageSize = document.getPageSize();
        float pageWidth = pageSize.getWidth();
        float pageHeight = pageSize.getHeight();

        // Calculate vertical positions using proportional offsets
        float eyeVerticalPosition = pageHeight * 0.75f;
        float noseVerticalPosition = pageHeight * 0.55f;
        float mouthVerticalPosition = pageHeight * 0.35f;

        // Load and position left eye
        Image leftEye = loadFeatureImage(face.getLeftEyePath());
        float leftEyeX = (pageWidth / 2) - leftEye.getScaledWidth() - 20;
        leftEye.setAbsolutePosition(leftEyeX, eyeVerticalPosition);

        // Load and position right eye
        Image rightEye = loadFeatureImage(face.getRightEyePath());
        float rightEyeX = (pageWidth / 2) + 20;
        rightEye.setAbsolutePosition(rightEyeX, eyeVerticalPosition);

        // Position nose centered below eyes
        Image nose = loadFeatureImage(face.getNosePath());
        float noseX = (pageWidth - nose.getScaledWidth()) / 2;
        nose.setAbsolutePosition(noseX, noseVerticalPosition);

        // Position mouth centered below nose
        Image mouth = loadFeatureImage(face.getMouthPath());
        float mouthX = (pageWidth - mouth.getScaledWidth()) / 2;
        mouth.setAbsolutePosition(mouthX, mouthVerticalPosition);

        // Assemble document components
        document.add(leftEye);
        document.add(rightEye);
        document.add(nose);
        document.add(mouth);

        // Add debug header
        Paragraph header = new Paragraph("Generated Face Document",
            new Font(Font.FontFamily.HELVETICA, 18, Font.BOLD));
        header.setSpacingAfter(20);
        document.add(header);
    }

