public static void shell(int[] a) {
    int increment = a.length / 2;
    while (increment > 0) {
        for (int i = increment; i < a.length; i++) {
            int j = i;
            int temp = a[i];
            while (j >= increment && a[j - increment] > temp) {
                a[j] = a[j - increment];
                j = j - increment;
            }
            a[j] = temp;
        }
        if (increment == 2) {
            increment = 1;
        } else {
            increment *= (5.0 / 11);
        }
    }
}

import java.util.*;

public class Utils {
    public static void main(String[] args) {
        final double TARGET = 30000;
        double actual = 0;
        double bal = 0;
        double sales = 0;
        do {
            bal = actual = 0;
            sales += 0.01;

            if (sales > 10000)
                actual += (bal = sales - 10000) * 0.12;

            if (sales > 5000)
                actual += (bal -= bal - 5000) * 0.10;

            if (sales > 0)
                actual += bal * 0.08;

        } while (actual < TARGET);

        System.out.printf("Sales required to earn $30,000 of commission is $%.2f\n", sales);
    }
}

import java.util.Scanner;

public class CommonPrefix {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter the first string: ");
        String str1 = scanner.nextLine();
        System.out.print("Enter the second string: ");
        String str2 = scanner.nextLine();

        // Find length of common prefix
        int len = Math.min(str1.length(), str2.length());
        int i;
        for (i = 0; i < len; i++) {
            if (str1.charAt(i) != str2.charAt(i)) {
                break;
            }
        }

        // Output common prefix
        String commonPrefix = str1.substring(0, i);
        if (commonPrefix.length() > 0) {
            System.out.println("The common prefix is: " + commonPrefix);
        } else {
            System.out.println("There is no common prefix.");
        }
    }
}

import java.util.SortedSet;
import java.util.TreeSet;

public class Solution {
    public static void main(String[] args) {
        SortedSet<String> set = new TreeSet<>();
        set.add("One");
        set.add("Two");
        set.add("Three");
        set.add("Four");
        set.add("Five");

        System.out.println(lastElement(set)); // Output: Five
    }

    public static <T> T lastElement(SortedSet<T> set) {
        if (set == null || set.isEmpty()) {
            return null;
        }
        return set.last();
    }
}

import java.net.URL;
import java.util.MissingResourceException;
import java.util.ResourceBundle;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.swing.*;

/**
 */
public class ResourceManager {

    private static final Logger logger = Logger.getLogger(ResourceManager.class.getName());

    private final Class<?> demoClass;

    // Resource bundle for internationalized and accessible text
    private ResourceBundle bundle = null;

    public ResourceManager(Class<?> demoClass) {
        this.demoClass = demoClass;

        String bundleName = demoClass.getPackage().getName() + ".resources." + demoClass.getSimpleName();

        try {
            bundle = ResourceBundle.getBundle(bundleName);
        } catch (MissingResourceException e) {
            logger.log(Level.SEVERE, "Couldn't load bundle: " + bundleName);
        }
    }

    public String getString(String key) {
        return bundle != null ? bundle.getString(key) : key;
    }

    public char getMnemonic(String key) {
        return (getString(key)).charAt(0);
    }

    public ImageIcon createImageIcon(String filename, String description) {
        String path = "resources/images/" + filename;

        URL imageURL = demoClass.getResource(path);

        if (imageURL == null) {
            logger.log(Level.SEVERE, "unable to access image file: " + path);

            return null;
        } else {
            return new ImageIcon(imageURL, description);
        }
    }
}

public class Pali23 {
    public static boolean isPali(String x){
        return x.equals(new StringBuilder(x).reverse().toString());
    }
 
    public static void main(String[] args){
 
        for(long i = 0, count = 0; count < 6;i++){
            if((i & 1) == 0 && (i != 0)) continue; //skip non-zero evens, nothing that ends in 0 in binary can be in this sequence
            //maybe speed things up through short-circuit evaluation by putting toString in the if
            //testing up to 10M, base 2 has slightly fewer palindromes so do that one first
            if(isPali(Long.toBinaryString(i)) && isPali(Long.toString(i, 3))){
                System.out.println(i + ", " + Long.toBinaryString(i) + ", " + Long.toString(i, 3));
                count++;
            }
        }
    }
}

