class Node {
    int data;
    Node left, right;

    public Node(int data) {
        this.data = data;
        this.left = null;
        this.right = null;
    }
}

class BinaryTree {
    Node root;

    public BinaryTree() {
        this.root = null;
    }

    public boolean isFullBinaryTree(Node node) {
        // If the tree is empty, it is a full binary tree
        if (node == null) {
            return true;
        }

        // If both the left and right subtrees are null, it is a leaf node
        if (node.left == null && node.right == null) {
            return true;
        }

        // If either the left or right subtree is null, it is not a full binary tree
        if (node.left == null || node.right == null) {
            return false;
        }

        // Recursively check if both the left and right subtrees are full binary trees
        return isFullBinaryTree(node.left) && isFullBinaryTree(node.right);
    }

    public static void main(String[] args) {
        BinaryTree tree = new BinaryTree();
        tree.root = new Node(1);
        tree.root.left = new Node(2);
        tree.root.right = new Node(3);
        tree.root.left.left = new Node(4);
        tree.root.left.right = new Node(5);
        tree.root.right.left = new Node(6);
        tree.root.right.right = new Node(7);

        if (tree.isFullBinaryTree(tree.root)) {
            System.out.println("The tree is a full binary tree.");
        } else {
            System.out.println("The tree is not a full binary tree.");
        }
    }
}

private double getMinStringSize(String[] tTokens, String[] uTokens) {
    double tSize = 0, uSize = 0;
    for (int i = 0; i < tTokens.length; i++) {
      tSize += tTokens[i].length();
    }
    for (int i = 0; i < uTokens.length; i++) {
      uSize += uTokens[i].length();
    }
    return Math.min(tSize, uSize);
  }

import java.io.IOException;
import java.io.OutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

interface BytesReference {
    byte get(int index);
    int length();
    BytesReference slice(int offset, int length);
    byte[] toBytes();
}

class BytesArray implements BytesReference {
    private final byte[] bytes;
    private final int offset;
    private final int length;

    public BytesArray(byte[] bytes) {
        this(bytes, 0, bytes.length);
    }

    public BytesArray(byte[] bytes, int offset, int length) {
        this.bytes = bytes;
        this.offset = offset;
        this.length = length;
    }

    public void write(OutputStream out) throws IOException {
        out.write(bytes, offset, length);
    }

    @Override
    public byte get(int index) {
        if (index < 0 || index >= length) {
            throw new IndexOutOfBoundsException("Index: " + index + ", Length: " + length);
        }
        return bytes[offset + index];
    }

    @Override
    public int length() {
        return length;
    }

    public int indexOf(byte value) {
        for (int i = 0; i < length; i++) {
            if (bytes[offset + i] == value) {
                return i;
            }
        }
        return -1;
    }

    @Override
    public BytesReference slice(int offset, int length) {
        if (offset < 0 || offset + length > this.length) {
            throw new IndexOutOfBoundsException("Offset: " + offset + ", Length: " + length + ", Total Length: " + this.length);
        }
        return new BytesArray(bytes, this.offset + offset, length);
    }

    @Override
    public byte[] toBytes() {
        return Arrays.copyOfRange(bytes, offset, offset + length);
    }

    public String toUtf8() {
        return new String(bytes, offset, length, StandardCharsets.UTF_8);
    }

    @Override
    public String toString() {
        return "BytesArray{" +
                "offset=" + offset +
                ", length=" + length +
                '}';
    }
}

private byte[] verifyMagic(byte[] payload) {
        int payloadLen = payload.length-MAGIC.length;
        if (payloadLen<0)   return null;
        for (int i=0; i<MAGIC.length; i++) {
            if (payload[payloadLen+i]!=MAGIC[i])
                return null;
        }
        byte[] truncated = new byte[payloadLen];
        System.arraycopy(payload,0,truncated,0,truncated.length);
        return truncated;
    }

class MajorityChecker {
    private SegmentTree st;
    private HashMap<Integer, FreqTracker> fts = new HashMap<>();

    public MajorityChecker(int[] arr) {
        st = new SegmentTree(arr.length);
        for (int i = 0; i < arr.length; ++i) {
            st.insert(i, new IntFreq(arr[i], 1));
        }

        for (int i = 0; i < arr.length; ++i) {
            FreqTracker ft = fts.getOrDefault(arr[i], null);
            if (ft == null) {
                ft = new FreqTracker();
                fts.put(arr[i], ft);
            }
            ft.add(i);
        }
    }

    public int query(int left, int right, int threshold) {
        // System.out.format("query(%d, %d, %d)\n", left, right, threshold);
        IntFreq best = st.get(left, right);
        // System.out.format("  -> best = %s\n", best);
        FreqTracker ft = fts.getOrDefault(best.value, null);
        if (ft == null) {
            return -1;
        }
        int actualCount = fts.get(best.value).getCount(left, right);
        // System.out.format("  -> actualCount = %d\n", actualCount);
        // System.out.format("query(%d, %d, %d) -> best = %s, actualCount = %d\n", left, right, threshold, best, actualCount);
        if (actualCount < threshold) {
            return -1;
        }
        return best.value; // NYI
    }

    private static class FreqTracker extends TreeMap<Integer, Integer> {
        public void add(int index) {
            put(index, size());
        }

        public int getCount(int L, int R) {
            Integer rk = floorKey(R);
            if (rk == null) {
                return 0;
            }
            Integer lk = ceilingKey(L);
            if (lk == null) {
                return 0;
            }
            return get(rk) - get(lk) + 1;
        }
    }

    private static class IntFreq {
        public int value;
        public int count;

        public IntFreq(int v, int c) {
            value = v;
            count = c;
        }

        @Override
        public String toString() {
            return String.format("(%d, freq = %d)", value, count);
        }
    }

    /**
     * Here is a Segment Tree implementation.  It currently does sums of longs.
     * See the comments to find where to change the data-type and function of this Segment Tree.
     */
    public static class SegmentTree {
        public SegmentTreeNode[] leaves;
        public SegmentTreeNode root;

        public SegmentTree(int n) {
            this.leaves = new SegmentTreeNode[n];
            this.root = new SegmentTreeNode(this, null, 0, n - 1);
        }

protected String extractProjectName(final BuildEvent event) {
    if (event == null) {
        return null;
    }

    Project project = event.getProject();
    if (project == null) {
        return null;
    }

    return project.getName();
}

