private static Map<String, Integer> invocationCount = new HashMap<>();

public static String generateFilename() {
    String packageName = Thread.currentThread().getStackTrace()[2].getClassName();
    String className = Thread.currentThread().getStackTrace()[2].getClassName().substring(packageName.lastIndexOf('.') + 1);
    String methodName = Thread.currentThread().getStackTrace()[2].getMethodName();
    int count = invocationCount.getOrDefault(methodName, 0);
    invocationCount.put(methodName, count + 1);
    return String.format("%s__%s__%s__%d.txt", packageName, className, methodName, count);
}

