import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.IntStream;
 
public class LexicographicallySortedVector {
    public static void lexicographicalSort(List<Integer> numbers) {
        List<String> strings = numbers.stream().map(String::valueOf).collect(Collectors.toList());
        Collections.sort(strings);
        for (int i = 0; i < numbers.size(); i++) {
            numbers.set(i, Integer.valueOf(strings.get(i)));
        }
    }
 
    public static List<Integer> lexicographicallySortedVector(int n) {
        List<Integer> numbers = new ArrayList<>();
        if (n >= 1) {
            for (int i = 1; i <= n; i++) {
                numbers.add(i);
            }
        } else {
            for (int i = 2 + n; i <= 1; i++) {
                numbers.add(i);
            }
        }
        lexicographicalSort(numbers);
        return numbers;
    }
 
    public static void printVector(List<Integer> v) {
        System.out.print("[");
        if (!v.isEmpty()) {
            System.out.print(v.get(0));
            for (int i = 1; i < v.size(); i++) {
                System.out.print("," + v.get(i));
            }
        }
        System.out.println("]");
    }
 
    public static void main(String[] args) {
        for (int i : new int[] { 0, 5, 13, 21, -22 }) {
            System.out.print(i + ": ");
            printVector(lexicographicallySortedVector(i));
        }
    }
}

public void detachEntities(List<Object> entities) {
    if (entities == null || entities.isEmpty()) {
        return;
    }
    EntityManager entityManager = getEntityManager();
    for (Object entity : entities) {
        if (entityManager.contains(entity)) {
            entityManager.detach(entity);
        }
    }
}

private void renderInstructions(Iterable<WAMInstruction> instructions, int row, int address)
    {
        for (WAMInstruction instruction : instructions)
        {
            WAMLabel label = instruction.getLabel();
            labeledTable.put(ADDRESS, row, String.format("%08X", address));
            labeledTable.put(LABEL, row, (label == null) ? "" : (label.toPrettyString() + ":"));
            labeledTable.put(MNEMONIC, row, instruction.getMnemonic().getPretty());
            int fieldMask = instruction.getMnemonic().getFieldMask();
            String arg = "";
            for (int i = 2; i < 32; i = i * 2)
            {
                if ((fieldMask & i) != 0)
                {
                    if (!"".equals(arg))
                    {
                        arg += ", ";
                    }
                    switch (i)
                    {
                    case 2:
                        arg += Integer.toString(instruction.getReg1());
                        break;
                    case 4:
                        arg += Integer.toString(instruction.getReg2());
                        break;
                    case 8:
                        FunctorName fn = instruction.getFn();
                        if (fn != null)
                        {
                            arg += fn.getName() + "/" + fn.getArity();
                        }
                        break;
                    case 16:
                        WAMLabel target1 = instruction.getTarget1();
                        if (target1 != null)
                        {
                            arg += target1.getName() + "/" + target1.getArity() + "_" + target1.getId();
                        }
                        break;
                    }
                }
            }
            labeledTable.put(ARG_1, row, arg);
            row++;
            address += instruction.sizeof();
        }
    }

import edu.cmu.tetrad.algcomparison.algorithm.MultiDataSetAlgorithm;
