        // Create a scene with the stack pane as the root node
        Scene scene = new Scene(stackPane, 300, 300);

        // Set the title of the window and display it
        primaryStage.setTitle("STOP Sign");
        primaryStage.setScene(scene);
        primaryStage.show();
    }

