public class Knapsack {
    public static void main(String[] args) {
        List<KnapsackItem> potentialItems = Arrays.asList(
                new KnapsackItem("map", 9, 150),
                new KnapsackItem("compass", 13, 35),
                new KnapsackItem("water", 153, 200),
                new KnapsackItem("sandwich", 50, 160),
                new KnapsackItem("glucose", 15, 60),
                new KnapsackItem("tin", 68, 45),
                new KnapsackItem("banana", 27, 60),
                new KnapsackItem("apple", 39, 40),
                new KnapsackItem("cheese", 23, 30),
                new KnapsackItem("beer", 52, 10),
                new KnapsackItem("suntan cream", 11, 70),
                new KnapsackItem("camera", 32, 30),
                new KnapsackItem("t-shirt", 24, 15),
                new KnapsackItem("trousers", 48, 10),
                new KnapsackItem("umbrella", 73, 40),
                new KnapsackItem("waterproof trousers", 42, 70),
                new KnapsackItem("waterproof overclothes", 43, 75),
                new KnapsackItem("note-case", 22, 80),
                new KnapsackItem("sunglasses", 7, 20),
                new KnapsackItem("towel", 18, 12),
                new KnapsackItem("socks", 4, 50),
                new KnapsackItem("book", 30, 10)
        );
        int knapsackCapacity = 400;

        List<List<KnapsackItem>> powerSet = powerSet(potentialItems);
        List<List<KnapsackItem>> solutions = powerSet.stream()
               .filter(subset -> {
                    int weight = subset.stream().mapToInt(KnapsackItem::getWeight).sum();
                    return weight <= knapsackCapacity;
                })
               .collect(Collectors.toList());

        int maxVal = solutions.stream()
               .mapToInt(subset -> subset.stream().mapToInt(KnapsackItem::getValue).sum())
               .max()
               .getAsInt();

        System.out.println("value: " + maxVal);
        solutions.stream()
               .filter(subset -> subset.stream().mapToInt(KnapsackItem::getValue).sum() == maxVal)
               .forEach(subset -> {
                    int weight = subset.stream().mapToInt(KnapsackItem::getWeight).sum();
                    List<String> items = subset.stream().map(KnapsackItem::getName).collect(Collectors.toList());
                    System.out.println("weight: " + weight);
                    System.out.println("items: " + String.join(",", items));

import java.util.*;
 
public class PatienceSort {
    public static <E extends Comparable<? super E>> void sort (E[] n) {
        List<Pile<E>> piles = new ArrayList<Pile<E>>();
        // sort into piles
        for (E x : n) {
            Pile<E> newPile = new Pile<E>();
            newPile.push(x);
            int i = Collections.binarySearch(piles, newPile);
            if (i < 0) i = ~i;
            if (i != piles.size())
                piles.get(i).push(x);
            else
                piles.add(newPile);
        }
 
        // priority queue allows us to retrieve least pile efficiently
        PriorityQueue<Pile<E>> heap = new PriorityQueue<Pile<E>>(piles);
        for (int c = 0; c < n.length; c++) {
            Pile<E> smallPile = heap.poll();
            n[c] = smallPile.pop();
            if (!smallPile.isEmpty())
                heap.offer(smallPile);
        }
        assert(heap.isEmpty());
    }
 
    private static class Pile<E extends Comparable<? super E>> extends Stack<E> implements Comparable<Pile<E>> {
        public int compareTo(Pile<E> y) { return peek().compareTo(y.peek()); }
    }
 
    public static void main(String[] args) {
    Integer[] a = {4, 65, 2, -31, 0, 99, 83, 782, 1};
    sort(a);
    System.out.println(Arrays.toString(a));
    }
}

@RequirePOST
public HttpResponse doDiscard(StaplerRequest req, StaplerResponse rsp) {
    // Get the data map from the request
    Map<String, byte[]> dataMap = (Map<String, byte[]>) req.getAttribute("dataMap");

    // Iterate over the data map to find files with only unreadable data
    Iterator<Map.Entry<String, byte[]>> iterator = dataMap.entrySet().iterator();
    while (iterator.hasNext()) {
        Map.Entry<String, byte[]> entry = iterator.next();
        byte[] data = entry.getValue();

        // Check if the data is unreadable (e.g., empty or contains only non-printable characters)
        if (isUnreadable(data)) {
            // Save the file with only unreadable data
            saveUnreadableFile(entry.getKey(), data);

            // Remove the entry from the data map
            iterator.remove();
        }
    }

    // Return a success response
    return HttpResponses.ok();
}

private boolean isUnreadable(byte[] data) {
    // Check if the data is empty or contains only non-printable characters
    if (data == null || data.length == 0) {
        return true;
    }
    for (byte b : data) {
        if (isPrintable(b)) {
            return false;
        }
    }
    return true;
}

private boolean isPrintable(byte b) {
    // Check if the byte represents a printable ASCII character
    return b >= 32 && b <= 126;
}

private void saveUnreadableFile(String fileName, byte[] data) {
    // Save the file with only unreadable data to a specific directory
    File file = new File("/path/to/unreadable/files/" + fileName);
    try (FileOutputStream fos = new FileOutputStream(file)) {
        fos.write(data);
    } catch (IOException e) {
        // Handle the exception (e.g., log it)
        e.printStackTrace();
    }
}

