import java.util.HashMap;
import java.util.Map;

public class MorseCoder {

    private static final HashMap<Character, String> morsemap = new HashMap<>();
    private static final HashMap<String, Character> inversemap = new HashMap<>();

    public MorseCoder() {
        initMorseMap();
    }

    private void initMorseMap() {
        morsemap.put('a', ".-");
        morsemap.put('b', "-...");
        morsemap.put('c', "-.-.");
        morsemap.put('d', "-..");
        morsemap.put('e', ".");
        morsemap.put('f', "..-.");
        morsemap.put('g', "--.");
        morsemap.put('h', "....");
        morsemap.put('i', "..");
        morsemap.put('j', ".---");
        morsemap.put('k', "-.-");
        morsemap.put('l', ".-..");
        morsemap.put('m', "--");
        morsemap.put('n', "-.");
        morsemap.put('o', "---");
        morsemap.put('p', ".--.");
        morsemap.put('q', "--.-");
        morsemap.put('r', ".-.");
        morsemap.put('s', "...");
        morsemap.put('t', "-");
        morsemap.put('u', "..-");
        morsemap.put('v', "...-");
        morsemap.put('w', ".--");
        morsemap.put('x', "-..-");
        morsemap.put('y', "-.--");
        morsemap.put('z', "--..");
        morsemap.put('1', ".----");
        morsemap.put('2', "..---");
        morsemap.put('3', "...--");
        morsemap.put('4', "....-");
        morsemap.put('5', ".....");
        morsemap.put('6', "-....");
        morsemap.put('7', "--...");
        morsemap.put('8', "---..");
        morsemap.put('9', "----.");
        morsemap.put('0', "-----");

        for (Map.Entry<Character, String> entry : morsemap.entrySet()) {
            inversemap.put(entry.getValue(), entry.getKey());
        }
    }

    public String code(String s) {
        StringBuilder morseCode = new StringBuilder();
        s = s.toLowerCase();

        for (char c : s.toCharArray()) {
            if (c == ' ') {
                morseCode.append("/ ");
            } else if (morsemap.containsKey(c)) {
                morseCode.append(morsemap.get(c)).append(" ");
            }
        }

        return morseCode.toString().trim();
    }

    public String decode(String d) {
        StringBuilder text = new StringBuilder();
        String[] morseSymbols = d.split(" ");

        for (String symbol : morseSymbols) {
            if (symbol.equals("/")) {
                text.append(" ");
            } else if (inversemap.containsKey(symbol)) {
                text.append(inversemap.get(symbol));
            }
        }

        return text.toString();
    }

class Main {
    public boolean areSentencesSimilar(String sentence1, String sentence2) {
        String[] s1 = sentence1.split(" ");
        String[] s2 = sentence2.split(" ");
        int i=0;
        int j=0;
        while(i < s1.length && j < s2.length) {
            if(s1[i].equals(s2[j])) {
                i++;
                j++;
            } else {
                break;
            }
        }

        int k=s1.length-1;
        int l=s2.length-1;
        while(k >=i && l >=j) {
            if(s1[k].equals(s2[l])) {
                k--;
                l--;
            } else {
                break;
            }
        }
        if(l < j || k < i) {
            return true;
        }
        return false;
    }
}

