import javax.management.MXBean;

@MXBean
public class Endpoint implements EndpointMBean {

    private String _jmxType;
    private String _url;

    // Default constructor
    public Endpoint() {
        this._jmxType = "DefaultJMXType";
        this._url = "";
    }

    // Preferred constructor with explicit URL initialization
    public Endpoint(String url) {
        this._jmxType = "DefaultJMXType";
        this._url = url;
    }

    // Constructor with both JMX type and URL
    public Endpoint(String jmxType, String url) {
        this._jmxType = jmxType;
        this._url = url;
    }

    @Override
    public String getUrl() {
        return _url;
    }

    @Override
    public void setUrl(String url) {
        this._url = url;
    }

    @Override
    public String getJmxType() {
        return _jmxType;
    }

    @Override
    public void setJmxType(String jmxType) {
        this._jmxType = jmxType;
    }

    @Override
    public String toString() {
        return "Endpoint{" +
                "jmxType='" + _jmxType + '\'' +
                ", url='" + _url + '\'' +
                '}';
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        Endpoint endpoint = (Endpoint) o;

        if (!_jmxType.equals(endpoint._jmxType)) return false;
        return _url.equals(endpoint._url);
    }

    @Override
    public int hashCode() {
        int result = _jmxType.hashCode();
        result = 31 * result + _url.hashCode();
        return result;
    }
}

