import java.util.Objects;

import java.util.Scanner;

import java.util.HashMap;

import java.math.BigInteger;

public class Parser {

    public static void main(String[] args) {

        Scanner in = new Scanner(System.in);

        HashMap<Integer, Integer> measures = new HashMap<>();

        HashMap<IntPair, Integer> pairs = new HashMap<>();

        int t = Integer.parseInt(in.nextLine());

        long c = 0;

        for (int i = 0; i != t; i ++) {

            int first = Integer.parseInt(in.next());

            int second = Integer.parseInt(in.next());

            if (first > second) {

                int a = first;

                first = second;

                second = a;

            }

            if (first == second) {

                c += measures.getOrDefault(first, 0);

                measures.compute(first, (k, v) -> v == null ? 1 : v + 1);

            } else {

                IntPair pair = new IntPair(first, second);

                c += measures.getOrDefault(first, 0);

                c += measures.getOrDefault(second, 0);

                c -= pairs.getOrDefault(pair, 0);

                measures.compute(first, (k, v) -> v == null ? 1 : v + 1);

                measures.compute(second, (k, v) -> v == null ? 1 : v + 1);

                pairs.compute(pair, (k, v) -> v == null ? 1 : v + 1);

            }

        }

        System.out.println(c);

    }

}

class IntPair {

    private final int first;

    private final int second;

    public IntPair(int first, int second) {

        this.first = first;

        this.second = second;

    }

    public int getFirst() {

        return first;

    }

    public int getSecond() {

        return second;

    }

    @Override

    public boolean equals(Object o) {

        if (this == o) return true;

        if (o == null || getClass() != o.getClass()) return false;

        IntPair pair = (IntPair) o;

        return (first == pair.first &&

                second == pair.second);

    }

    @Override

    public int hashCode() {

        return Objects.hash(first, second);

    }

}

import org.apache.commons.lang.StringUtils;
import org.ovirt.engine.api.model.Group;
import org.ovirt.engine.api.model.Domain;
import org.ovirt.engine.core.common.businessentities.DbGroup;
import org.ovirt.engine.core.compat.Guid;

public class GroupMapper {

    public static Group map(DbGroup entity, Group template) {
        Group model = template != null ? template : new Group();

        model.setId(entity.getId().toString());
        model.setName(entity.getName());

        Domain domain = new Domain();
        domain.setId(entity.getDomainId().toString());
        model.setDomain(domain);

        model.setDomainEntryId(entity.getExternalId());

        return model;
    }

    public static Group map(DirectoryGroup entity, Group template) {
        Group model = template != null ? template : new Group();

        model.setName(entity.getName());
        model.setDomainEntryId(entity.getId());

        return model;
    }

    public static DbGroup map(Group model, DbGroup template) {
        DbGroup entity = template != null ? template : new DbGroup();

        if (StringUtils.isNotEmpty(model.getName())) {
            entity.setName(model.getName());
        }

        if (model.getId() != null) {
            entity.setId(new Guid(model.getId()));
        }

        if (model.getDomain() != null && model.getDomain().getId() != null) {
            entity.setDomainId(new Guid(model.getDomain().getId()));
        }

        if (StringUtils.isNotEmpty(model.getDomainEntryId())) {
            entity.setExternalId(model.getDomainEntryId());
        }

        return entity;
    }

    public static class DirectoryGroup {
        private String id;
        private String name;

        public DirectoryGroup(String id, String name) {
            this.id = id;
            this.name = name;
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }
    }
}

public int greatPartition(int[] nums, int k) {
        int mod = 10_000_000_07;

        PriorityQueue<Integer> q1 = new PriorityQueue<>();
        PriorityQueue<Integer> q2 = new PriorityQueue<>();

        for (int i : nums) {
            if (!q1.isEmpty() && !q2.isEmpty() && q1.peek() + q2.peek() < i) {
                q1.offer(i);
            } else if (!q1.isEmpty() && q1.peek() >= k) {
                q2.offer(i);
            } else if (!q2.isEmpty() && q2.peek() >= k) {
                q1.offer(i);
            } else if (q1.isEmpty() && q2.isEmpty()) {
                q1.offer(i);
            } else {
                q2.offer(i);
            }
        }

        int calc =  q1.size() + q2.size() + 1;
        int result = 1;

        for (int i = 2; i <= calc; i++) result = (result * i) % mod;
        for (int i = 2; i <= q1.size(); i++) result = (result * (q1.size() + 1 - i)) % mod;
        for (int i = 2; i <= q2.size(); i++) result = (result * (q2.size() + 1 - i)) % mod;

        return result;
    }
}

