import java.io.File;
import java.io.FileNotFoundException;
import java.util.Scanner;

/**
 * Reads arithmetic expressions from a text file, one per line, and
 * prints the evaluated result for each valid entry.
 */
public class HesapMakinesiScanner {

    private static final String KAYNAK_DOSYA = "islemler.txt";

    public static void main(String[] args) {
        File girdi = new File(KAYNAK_DOSYA);

        try (Scanner tarayici = new Scanner(girdi)) {
            System.out.println("Hesap Makinesi - Dosyadan Okuma");

            int satirNo = 0;
            while (tarayici.hasNextLine()) {
                satirNo++;
                String hamSatir = tarayici.nextLine();
                islemSatiriniIsle(hamSatir, satirNo);
            }
        } catch (FileNotFoundException hata) {
            System.out.println("Dosya bulunamadi: " + hata.getMessage());
        }
    }

    /** Bir satiri parcalayip aritmetik islemi cozumler ve sonucu basar. */
    private static void islemSatiriniIsle(String satir, int satirNo) {
        String[] token = satir.split(" ");

        if (token.length != 3) {
            System.out.println("Gecersiz islem! Lutfen dogru formatta islem girin (ornek: 10 + 5).");
            return;
        }

        try {
            int solTaraf = Integer.parseInt(token[0]);
            int sagTaraf = Integer.parseInt(token[2]);
            char operatorKarakteri = token[1].charAt(0);

            Integer sonuc = hesapla(solTaraf, sagTaraf, operatorKarakteri);
            if (sonuc != null) {
                System.out.println(solTaraf + " " + operatorKarakteri + " " + sagTaraf + " = " + sonuc);
            }
        } catch (NumberFormatException ayristirmaHatasi) {
            System.out.println("Sayilari parse ederken bir hata olustu: " + ayristirmaHatasi.getMessage());
        }
    }

    /** Verilen operatore gore iki tam sayi arasinda islem yapar. Basarisizsa null doner. */
    private static Integer hesapla(int a, int b, char op) {
        switch (op) {
            case '+':
                return a + b;
            case '-':
                return a - b;
            case '*':
                return a * b;
            case '/':
                if (b == 0) {
                    System.out.println("Hata: Sifira bolme yapilamaz!");
                    return null;
                }
                return a / b;
            default:
                System.out.println("Gecersiz islec! Lutfen +, -, * veya / kullanin.");
                return null;
        }
    }
}

public class Finder {
    int[][][] dp;
    int mod = 1000000007;
    public int findPaths(int m, int n, int N, int i, int j) {
        dp = new int[m][n][N+1];
        for(int a = 0; a < m; a++){
            for(int b = 0; b < n; b++){
                for(int k = 0; k <= N; k++){
                    dp[a][b][k] = -1;
                }
            }
        }
        return helper(m, n, N, i, j);
    }
    public int helper(int m, int n, int N, int i, int j){
        if(dp[i][j][N] > -1){
            return dp[i][j][N];
        }
        if(N <= 0){
            return 0;
        }
        long ret = 0;
        if(i > 0){
            ret += helper(m, n, N-1, i-1, j);
        }else{
            ret++;
        }
        ret %= mod;
        if(i+1 < m){
            ret += helper(m, n, N-1, i+1, j);
        }else{
            ret++;
        }
        ret %= mod;
        if(j > 0){
            ret += helper(m, n, N-1, i, j-1);
        }else{
            ret++;
        }
        ret %= mod;
        if(j+1 < n){
            ret += helper(m, n, N-1, i, j+1);
        }else{
            ret++;
        }
        ret %= mod;
        //System.out.println("i: " + i + " j: " + j + " N: " + N + " ret:" + ret);
        dp[i][j][N] = (int)ret;
        return (int)ret;
    }
}

import java.util.*;

public class Utils {

  public static ArrayList<Integer> pals = new ArrayList<>();

  public static Integer[][] dp = new Integer[500][40001];

    public static void main(String[] args) {

    Scanner sc = new Scanner(System.in);

      fill_pals();

     int t = sc.nextInt();

     while(t-->0){

       int sum = sc.nextInt();

    int ans =recurssion(0,sum,pals);

    System.out.println(ans);

     }

  }

  public static void fill_pals(){

     for(int i =1;i<=4*10000;i++){

          if(isPal(i)){

            pals.add(i);

          }

        }

  }

  public static int recurssion(int index , int remaining_sum, ArrayList<Integer> pals){

    if(remaining_sum==0)return 1;

    if(index==pals.size() || remaining_sum<0)return 0;

    if(dp[index][remaining_sum]!=null)return dp[index][remaining_sum];

    int op1 =0;

    int op2=0;

    op1=recurssion(index+1,remaining_sum,pals);

    op2=recurssion(index,remaining_sum-pals.get(index),pals);

    return dp[index][remaining_sum]=(op1+op2)%1000000007;

  }

  public static boolean isPal(int n){

    ArrayList<Integer> front = new ArrayList<>();

    while(n>0){

      front.add(n%10);

      n=n/10;

    }

    int i =0;

    int j = front.size()-1;

    while(i<=j){

      if(front.get(i)!=front.get(j)){

        return false;

      }

      i++;

      j--;

    }

    return true;

  }

}

