import java.awt.*;

public class CenterLayout implements LayoutManager {

    @Override
    public void addLayoutComponent(String name, Component comp) {
        // Not used as this layout only manages a single component.
    }

    @Override
    public void removeLayoutComponent(Component comp) {
        // Not used as this layout only manages a single component.
    }

    @Override
    public Dimension preferredLayoutSize(Container parent) {
        synchronized (parent.getTreeLock()) {
            Component comp = parent.getComponentCount() > 0 ? parent.getComponent(0) : null;
            Insets insets = parent.getInsets();
            int w = insets.left + insets.right;
            int h = insets.top + insets.bottom;
            if (comp != null) {
                Dimension d = comp.getPreferredSize();
                return new Dimension(w + d.width, h + d.height);
            } else {
                return new Dimension(w,h);
            }
        }
    }

    @Override
    public Dimension minimumLayoutSize(Container parent) {
        synchronized (parent.getTreeLock()) {
            Component comp = parent.getComponentCount() > 0 ? parent.getComponent(0) : null;
            Insets insets = parent.getInsets();
            int w = insets.left + insets.right;
            int h = insets.top + insets.bottom;

            if (comp != null) {
                Dimension d = comp.getMinimumSize();
                return new Dimension(w + d.width, h + d.height);
            } else {
                 return new Dimension(w,h);
            }
        }
    }

    @Override
    public void layoutContainer(Container parent) {
        synchronized (parent.getTreeLock()) {
            Insets insets = parent.getInsets();
            int top = insets.top;
            int left = insets.left;
            int width = parent.getWidth() - (insets.left + insets.right);
            int height = parent.getHeight() - (insets.top + insets.bottom);

            Component comp = parent.getComponentCount() > 0 ? parent.getComponent(0) : null;

            if (comp != null) {
                Dimension d = comp.getPreferredSize();
                int x = left + (width - d.width) / 2;
                int y = top + (height - d.height) / 2;

                comp.setBounds(x, y, d.width, d.height);
            }
        }
    }
}
